Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# ---------------------------------------------------------------------------
# Загрузочный экран. Показывается сразу после запуска, пока скрипт собирает окна, компилирует типы и читает
# библиотеки. Живёт в отдельном потоке со своим циклом сообщений (анимация не зависает, даже когда основной
# поток занят), закрывается, когда главное окно уже на экране (см. $form.Add_Shown) или перед первым окном настроек.
# Цвета продублированы вручную: палитра $steamUi создаётся позже.
# ---------------------------------------------------------------------------
$script:SplashState = [hashtable]::Synchronized(@{ Close = $false; Closed = $false; Text = ''; Progress = 0.0 })
$script:SplashPs = $null
$script:SplashRs = $null
$script:SplashRu = $false
# Композиция «Hero + логотип» в карточке (как в Steam). $false - вернуть прежнюю раскладку и поведение.
$script:LogoComposeEnabled = $true
try { $script:SplashRu = ([System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName -eq 'ru') } catch {}

function Set-SplashText ([string]$Text) {
    try { if ($null -ne $script:SplashState) { $script:SplashState['Text'] = $Text } } catch {}
}

# Прогресс запуска 0..1 для стартового экрана (экран библиотеки ключа Progress не имеет — у него бегущая полоска).
function Set-SplashProgress ([double]$Value) {
    try {
        if ($null -ne $script:SplashState -and $null -ne $script:SplashState['Progress']) {
            if ($Value -gt 1.0) { $Value = 1.0 }
            if ($Value -gt [double]$script:SplashState['Progress']) { $script:SplashState['Progress'] = $Value }
        }
    } catch {}
}

function Close-Splash {
    try {
        if ($null -eq $script:SplashState) { return }
        $script:SplashState['Close'] = $true
        $t0 = [Environment]::TickCount
        while (-not [bool]$script:SplashState['Closed'] -and (([Environment]::TickCount - $t0) -lt 800)) { Start-Sleep -Milliseconds 20 }
    } catch {}
    try { if ($null -ne $script:SplashPs) { $script:SplashPs.Dispose() } } catch {}
    try { if ($null -ne $script:SplashRs) { $script:SplashRs.Dispose() } } catch {}
    $script:SplashPs = $null
    $script:SplashRs = $null
}

try {
    $splashWorker = {
        param($st, $title, $initText)
        try {
            Add-Type -AssemblyName System.Windows.Forms
            Add-Type -AssemblyName System.Drawing
            $sc = 1.0
            try { $g0 = [System.Drawing.Graphics]::FromHwnd([IntPtr]::Zero); $sc = [double]($g0.DpiX / 96.0); $g0.Dispose() } catch { $sc = 1.0 }
            if ($sc -lt 1.0) { $sc = 1.0 }
            $f = New-Object System.Windows.Forms.Form
            $f.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::None
            $f.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen
            $f.ShowInTaskbar = $false
            $f.TopMost = $true
            $f.BackColor = [System.Drawing.Color]::FromArgb(23, 29, 37)
            $f.ClientSize = New-Object System.Drawing.Size([int](440 * $sc), [int](190 * $sc))
            try {
                $fl = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
                [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $fl).SetValue($f, $true, $null)
            } catch {}
            $fontTitle = New-Object System.Drawing.Font('Segoe UI Semibold', [single](22 * $sc / 1.333))
            $fontText = New-Object System.Drawing.Font('Segoe UI', [single](10 * $sc / 1.333))
            $brText = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(220, 223, 228))
            $brMuted = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(145, 154, 164))
            $brTrack = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(13, 20, 28))
            $brBar = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(26, 159, 255))
            $penBorder = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(58, 73, 90))
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            $pg = @{ Disp = 0.0 }
            $sfC = New-Object System.Drawing.StringFormat
            $sfC.Alignment = [System.Drawing.StringAlignment]::Center
            $sfC.LineAlignment = [System.Drawing.StringAlignment]::Center
            $f.Add_Paint({
                param($s0, $e)
                try {
                    $g = $e.Graphics
                    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
                    $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
                    $w = [int]$s0.ClientSize.Width; $h = [int]$s0.ClientSize.Height
                    $g.DrawRectangle($penBorder, 0, 0, ($w - 1), ($h - 1))
                    $g.DrawString([string]$title, $fontTitle, $brText, (New-Object System.Drawing.RectangleF(0, [single](34 * $sc), $w, [single](56 * $sc))), $sfC)
                    $txt = [string]$st['Text']
                    if ([string]::IsNullOrEmpty($txt)) { $txt = [string]$initText }
                    $g.DrawString($txt, $fontText, $brMuted, (New-Object System.Drawing.RectangleF(0, [single](96 * $sc), $w, [single](24 * $sc))), $sfC)
                    $bw = [int](300 * $sc); $bh = [int](4 * $sc)
                    $bx = [int](($w - $bw) / 2); $by = [int](138 * $sc)
                    $g.FillRectangle($brTrack, $bx, $by, $bw, $bh)
                    if ($null -ne $st['Progress']) {
                        # Определённый прогресс (стартовый экран): полоска заполняется слева направо.
                        $fw = [int]($bw * [Math]::Min(1.0, [Math]::Max(0.0, [double]$pg['Disp'])))
                        if ($fw -gt 0) { $g.FillRectangle($brBar, $bx, $by, $fw, $bh) }
                    } else {
                        # Неопределённый прогресс (экран библиотеки): светлый сегмент бежит по дорожке туда-обратно.
                        $seg = [int]($bw * 0.32)
                        $ph = ([double]($sw.ElapsedMilliseconds % 1600)) / 1600.0
                        $tri = if ($ph -lt 0.5) { $ph * 2.0 } else { (1.0 - $ph) * 2.0 }
                        $ease = $tri * $tri * (3.0 - 2.0 * $tri)
                        $sx = [int]($bx + ($bw - $seg) * $ease)
                        $g.FillRectangle($brBar, $sx, $by, $seg, $bh)
                    }
                } catch {}
            }.GetNewClosure())
            $tm = New-Object System.Windows.Forms.Timer
            $tm.Interval = 25
            $tm.Add_Tick({
                try {
                    if ([bool]$st['Close'] -or $sw.ElapsedMilliseconds -gt 120000) { $tm.Stop(); $f.Close(); return }
                    $pv = $st['Progress']
                    if ($null -ne $pv) {
                        # Плавно догоняем последнюю отметку; пока основной поток занят и отметок нет — чуть ползём вперёд,
                        # но не дальше +4% от неё (и не выше 97%), чтобы полоска не выглядела зависшей и не врала.
                        $tg = [double]$pv; $d = [double]$pg['Disp']
                        if ($d -lt $tg) {
                            $d = $d + [Math]::Max(($tg - $d) * 0.15, 0.002)
                            if ($d -gt $tg) { $d = $tg }
                        } elseif ($d -lt [Math]::Min($tg + 0.04, 0.97)) {
                            $d = $d + 0.0004
                        }
                        $pg['Disp'] = $d
                    }
                    $f.Invalidate()
                } catch {}
            }.GetNewClosure())
            $f.Add_FormClosed({
                try { $st['Closed'] = $true } catch {}
                try { [System.Windows.Forms.Application]::ExitThread() } catch {}
            }.GetNewClosure())
            $f.Add_Shown({ try { $tm.Start() } catch {} }.GetNewClosure())
            [System.Windows.Forms.Application]::Run($f)
        } catch {}
        try { $st['Closed'] = $true } catch {}
    }
    # Язык ОС (словарь ещё не загружен): надпись «Загрузка…» на шести встроенных языках.
    $splashLoadingMap = @{ ru = 'Загрузка…'; en = 'Loading…'; zh = '加载中…'; es = 'Cargando…'; pt = 'Carregando…'; de = 'Wird geladen…' }
    $splashOsLang = ''; try { $splashOsLang = [System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName } catch {}
    $splashInit = if ($splashLoadingMap.ContainsKey($splashOsLang)) { [string]$splashLoadingMap[$splashOsLang] } else { 'Loading…' }
    $script:SplashRs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
    $script:SplashRs.ApartmentState = [System.Threading.ApartmentState]::STA
    $script:SplashRs.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
    $script:SplashRs.Open()
    $script:SplashPs = [System.Management.Automation.PowerShell]::Create()
    $script:SplashPs.Runspace = $script:SplashRs
    [void]$script:SplashPs.AddScript($splashWorker.ToString())
    [void]$script:SplashPs.AddArgument($script:SplashState)
    [void]$script:SplashPs.AddArgument('Steam Commander')
    [void]$script:SplashPs.AddArgument($splashInit)
    [void]$script:SplashPs.BeginInvoke()
} catch {
    $script:SplashState = $null
}
Add-Type -AssemblyName System.Design

# ---------------------------------------------------------------------------
# Адаптация окон под маленькие экраны (например, 1366x768 или 1920x1080 при
# масштабе Windows 150% — логическое разрешение там всего 1280x720).
# Раскладку окон не трогаем (абсолютные координаты остаются прежними). Если
# окно с фиксированной раскладкой не помещается в рабочую область экрана
# (экран без панели задач), оно уменьшается до её размера, а содержимое
# становится прокручиваемым (AutoScroll). Изменяемые окна (Sizable) просто
# ограничиваются размером экрана — они сами перестраиваются через Anchor и
# свои обработчики Resize. На больших экранах ничего не меняется.
# ---------------------------------------------------------------------------
function Get-FormTargetWorkingArea {
    param($Owner = $null)
    try {
        if ($Owner -is [System.Windows.Forms.Control] -and $Owner.IsHandleCreated -and $Owner.Visible) {
            return [System.Windows.Forms.Screen]::FromControl($Owner).WorkingArea
        }
    } catch {}
    try {
        return [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).WorkingArea
    } catch {}
    return [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
}

function Set-FormFitToScreen {
    param(
        [System.Windows.Forms.Form]$Form,
        $Owner = $null,
        [int]$DesignWidth = 0,
        [int]$DesignHeight = 0
    )
    try {
        if ($null -eq $Form -or $Form.IsDisposed -or -not $Form.TopLevel) { return }
        $wa = Get-FormTargetWorkingArea -Owner $Owner
        $ncW = [int]($Form.Size.Width - $Form.ClientSize.Width)
        $ncH = [int]($Form.Size.Height - $Form.ClientSize.Height)
        $maxW = [int]($wa.Width - $ncW)
        $maxH = [int]($wa.Height - $ncH)

        # Проектный размер содержимого: либо передан явно, либо (если окно уже
        # переведено сюда в режим прокрутки) хранится в AutoScrollMinSize,
        # либо это текущий клиентский размер.
        if ($DesignWidth -gt 0 -and $DesignHeight -gt 0) {
            $designW = $DesignWidth
            $designH = $DesignHeight
        } elseif ($Form.AutoScroll -and $Form.AutoScrollMinSize.Width -gt 0 -and $Form.AutoScrollMinSize.Height -gt 0) {
            $designW = [int]$Form.AutoScrollMinSize.Width
            $designH = [int]$Form.AutoScrollMinSize.Height
        } else {
            $designW = [int]$Form.ClientSize.Width
            $designH = [int]$Form.ClientSize.Height
        }

        $sizable = ($Form.FormBorderStyle -eq [System.Windows.Forms.FormBorderStyle]::Sizable) -or
                   ($Form.FormBorderStyle -eq [System.Windows.Forms.FormBorderStyle]::SizableToolWindow)
        $needV = ($designH -gt $maxH)
        $needH = ($designW -gt $maxW)

        if (-not $needV -and -not $needH) {
            # Окно помещается целиком — возвращаем обычный режим, если ранее
            # включали прокрутку.
            if (-not $sizable -and $Form.AutoScroll -and $Form.AutoScrollMinSize.Width -gt 0) {
                try { $Form.AutoScrollPosition = New-Object System.Drawing.Point(0, 0) } catch {}
                $Form.AutoScrollMinSize = New-Object System.Drawing.Size(0, 0)
                $Form.AutoScroll = $false
                $Form.ClientSize = New-Object System.Drawing.Size($designW, $designH)
            }
            return
        }

        if ($sizable) {
            $limW = [Math]::Max(300, [Math]::Min($designW, $maxW))
            $limH = [Math]::Max(300, [Math]::Min($designH, $maxH))
            $Form.ClientSize = New-Object System.Drawing.Size($limW, $limH)
            return
        }

        # Резерв под ширину/высоту полосы прокрутки: когда не помещается только
        # одна сторона, окно чуть расширяется, чтобы вторая полоса не появлялась.
        $vsw = [int][System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth
        $hsh = [int][System.Windows.Forms.SystemInformation]::HorizontalScrollBarHeight
        $newW = $designW
        $newH = $designH
        if ($needV) {
            $newH = $maxH
            if (-not $needH) { $newW = [Math]::Min($designW + $vsw, $maxW) }
        }
        if ($needH) {
            $newW = $maxW
            if (-not $needV) { $newH = [Math]::Min($designH + $hsh, $maxH) }
        }
        $newW = [Math]::Max(300, $newW)
        $newH = [Math]::Max(300, $newH)

        $Form.AutoScroll = $true
        $Form.AutoScrollMinSize = New-Object System.Drawing.Size($designW, $designH)
        $Form.ClientSize = New-Object System.Drawing.Size($newW, $newH)
    } catch {}
}

function Move-FormIntoWorkingArea {
    param([System.Windows.Forms.Form]$Form)
    try {
        if ($null -eq $Form -or $Form.IsDisposed -or -not $Form.TopLevel) { return }
        $wa = [System.Windows.Forms.Screen]::FromControl($Form).WorkingArea
        $px = [int]$Form.Left
        $py = [int]$Form.Top
        if (($py + $Form.Height) -gt $wa.Bottom) { $py = $wa.Bottom - $Form.Height }
        if ($py -lt $wa.Top) { $py = $wa.Top }
        if (($px + $Form.Width) -gt $wa.Right) { $px = $wa.Right - $Form.Width }
        if ($px -lt $wa.Left) { $px = $wa.Left }
        if ($px -ne $Form.Left -or $py -ne $Form.Top) {
            $Form.Location = New-Object System.Drawing.Point($px, $py)
        }
    } catch {}
}

# Вызывается прямо перед показом окна (после того как вся раскладка построена).
function Initialize-FormForSmallScreen {
    param([System.Windows.Forms.Form]$Form, $Owner = $null)
    try {
        if ($null -eq $Form -or $Form.IsDisposed -or -not $Form.TopLevel) { return }
        $sizeBefore = $Form.ClientSize
        Set-FormFitToScreen -Form $Form -Owner $Owner
        $changed = ($Form.ClientSize.Width -ne $sizeBefore.Width) -or ($Form.ClientSize.Height -ne $sizeBefore.Height)
        if ($changed -or $Form.AutoScroll) {
            # После показа окно могло встать так, что часть его выходит за
            # рабочую область (например, CenterParent у края экрана).
            $Form.Add_Shown({
                param($sender, $e)
                Move-FormIntoWorkingArea -Form $sender
            })
        }
    } catch {}
}

# Хелпер: жёстко прячет нативную горизонтальную полосу прокрутки у control'а
# (даже если WinForms по каким-то причинам считает, что она нужна — например,
# из-за округления ширины плиток/паддингов при пересчёте сетки библиотеки).
# ShowScrollBar(hWnd, SB_HORZ, false) не трогает вертикальную полосу и не
# требует пересчёта AutoScrollMinSize — просто гарантированно убирает
# горизонтальную полосу с экрана.
if (-not ('Win32ScrollBarHelper' -as [type])) {
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public class Win32ScrollBarHelper
{
    private const int SB_HORZ = 0;
    private const int SB_VERT = 1;

    [DllImport("user32.dll")]
    private static extern bool ShowScrollBar(IntPtr hWnd, int wBar, bool bShow);

    public static void HideHorizontal(IntPtr hWnd)
    {
        if (hWnd == IntPtr.Zero) return;
        try { ShowScrollBar(hWnd, SB_HORZ, false); } catch {}
    }

    public static void HideVertical(IntPtr hWnd)
    {
        if (hWnd == IntPtr.Zero) return;
        try { ShowScrollBar(hWnd, SB_VERT, false); } catch {}
    }

    public static void HideBoth(IntPtr hWnd)
    {
        HideHorizontal(hWnd);
        HideVertical(hWnd);
    }
}
'@ -ErrorAction Stop
    } catch {}
}

Set-SplashProgress 0.06
# ComboBox выбора EXE: если в списке 0 или 1 элемент, выбирать не из чего —
# поэтому кнопка-стрелка скрывается (закрашивается цветом фона) и раскрытие
# списка блокируется. Как только в список добавляют второй элемент (в том числе
# вручную через "Обзор..."), стрелка появляется сама: следим за сообщениями
# CB_ADDSTRING / CB_INSERTSTRING / CB_DELETESTRING / CB_RESETCONTENT.
Add-Type -ReferencedAssemblies @('System.Drawing','System.Windows.Forms') -TypeDefinition @'
using System;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;

public class SmartExeComboBox : ComboBox
{
    private const int WM_PAINT = 0x000F;
    private const int WM_NCPAINT = 0x0085;
    private const int WM_KEYDOWN = 0x0100;
    private const int WM_SYSKEYDOWN = 0x0104;
    private const int WM_LBUTTONDOWN = 0x0201;
    private const int WM_LBUTTONDBLCLK = 0x0203;
    private const int WM_MOUSEWHEEL = 0x020A;
    private const int CB_ADDSTRING = 0x0143;
    private const int CB_DELETESTRING = 0x0144;
    private const int CB_INSERTSTRING = 0x014A;
    private const int CB_RESETCONTENT = 0x014B;
    private const int CB_SHOWDROPDOWN = 0x014F;
    private const int VK_F4 = 0x73;
    private const int VK_DOWN = 0x28;
    private const int VK_UP = 0x26;

    [DllImport("uxtheme.dll", ExactSpelling = true, CharSet = CharSet.Unicode)]
    private static extern int SetWindowTheme(IntPtr hWnd, string pszSubAppName, string pszSubIdList);

    // Цвет рамки (задаётся извне под тему Steam UI).
    public Color BorderColor = Color.FromArgb(55, 65, 75);

    private bool? _themed;

    // Убираем WS_BORDER / WS_EX_CLIENTEDGE — иначе WinForms рисует
    // обломанную светлую системную рамку на тёмном фоне.
    protected override CreateParams CreateParams
    {
        get
        {
            CreateParams cp = base.CreateParams;
            cp.Style &= ~0x00800000;   // WS_BORDER
            cp.ExStyle &= ~0x00000200; // WS_EX_CLIENTEDGE
            return cp;
        }
    }

    private void UpdateTheme()
    {
        if (!IsHandleCreated) return;
        // У DropDownStyle=DropDown (редактируемое поле, как "Ядро") есть
        // настоящий дочерний Edit-контрол — сам текст и его выделение рисует
        // он, а не наш DrawItem. Отключение темы (SetWindowTheme(hWnd,"",""))
        // меняет внутреннюю раскладку этого Edit-контрола: текст съезжает к
        // верхнему краю поля, а выделение текста перестаёт скрываться при
        // потере фокуса — именно то, что выглядит как "поле криво и будто
        // всегда в фокусе". У DropDownList/Simple отдельного Edit-контрола
        // нет (весь текст рисуем сами через DrawItem), поэтому тему безопасно
        // отключать только для них.
        if (DropDownStyle == ComboBoxStyle.DropDown) return;
        bool wantThemed = false;
        if (_themed == wantThemed) return;
        _themed = wantThemed;
        SetWindowTheme(Handle, "", "");
    }

    protected override void OnHandleCreated(EventArgs e)
    {
        base.OnHandleCreated(e);
        _themed = null;
        UpdateTheme();
    }

    // "Заблокировано" — состояние поля в карточке лицензионной игры: оно
    // должно выглядеть и вести себя как нередактируемое, но БЕЗ Enabled=false.
    // При реальном отключении (Enabled=false) Windows перестаёт слать нам
    // WM_PAINT/WM_NCPAINT через наш перехват и сама рисует системную (светлую)
    // рамку/фон поверх тёмной темы — это и есть белый "глюк" рамки. Поэтому
    // вместо Enabled просто блокируем ввод, а рисуем всё сами, как обычно.
    public bool Locked = false;

    // Центрированная подпись заблокированного поля. Область DrawItem у закрытого
    // комбобокса не включает зону стрелки справа (~21 px), поэтому текст, нарисованный
    // там, оказывается левее реального центра. Для Locked-полей подпись рисуем здесь,
    // по центру всей ширины, уже после закраски зоны стрелки.
    public bool CenterText = false;
    public Color CenterTextColor = Color.Empty;
    public float CenterFontSize = 0f;

    public bool ArrowHidden
    {
        get { return Items.Count <= 1 || Locked; }
    }

    private void PaintChrome()
    {
        if (!IsHandleCreated || Width <= 0 || Height <= 0) return;
        using (Graphics g = Graphics.FromHwnd(Handle))
        {
            // Перекрываем системные артефакты рамки и стрелки единым фоном.
            using (SolidBrush b = new SolidBrush(BackColor))
            {
                // тонкая внутренняя полоса по периметру
                g.FillRectangle(b, new Rectangle(0, 0, Width, 2));
                g.FillRectangle(b, new Rectangle(0, Height - 2, Width, 2));
                g.FillRectangle(b, new Rectangle(0, 0, 2, Height));
                g.FillRectangle(b, new Rectangle(Width - 2, 0, 2, Height));

                // Кнопка-стрелка справа: Windows всегда рисует её сама (светлым,
                // независимо от темы/BackColor) поверх поля — раньше мы
                // перекрывали это место фоном ТОЛЬКО когда стрелка спрятана
                // (ArrowHidden), поэтому при 2+ элементах в списке (обычный
                // случай — язык/профиль/регион и т.п.) там оставался нативный белый
                // квадрат кнопки. Теперь фон под кнопкой всегда наш, а сама
                // стрелка (если не спрятана) рисуется вручную тем же цветом,
                // что и текст поля — единый тёмный стиль во всех состояниях.
                int w = SystemInformation.VerticalScrollBarWidth + 4;
                Rectangle arrowRect = new Rectangle(Width - w - 1, 1, w, Height - 2);
                g.FillRectangle(b, arrowRect);

                if (!ArrowHidden)
                {
                    int cx = arrowRect.X + arrowRect.Width / 2;
                    int cy = arrowRect.Y + arrowRect.Height / 2;
                    int halfW = 4;
                    Point[] triangle = new Point[]
                    {
                        new Point(cx - halfW, cy - 2),
                        new Point(cx + halfW, cy - 2),
                        new Point(cx, cy + 3)
                    };
                    using (SolidBrush arrowBrush = new SolidBrush(ForeColor))
                    {
                        g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
                        g.FillPolygon(arrowBrush, triangle);
                    }
                }
            }
            if (Locked && CenterText && DropDownStyle != ComboBoxStyle.DropDown && Items.Count > 0)
            {
                try
                {
                    int idx = SelectedIndex >= 0 ? SelectedIndex : 0;
                    string txt = Convert.ToString(Items[idx]);
                    Color tc = CenterTextColor.IsEmpty ? ForeColor : CenterTextColor;
                    float fs = CenterFontSize > 0f ? CenterFontSize : Font.Size;
                    using (Font f = new Font(Font.FontFamily, fs, Font.Style))
                    using (SolidBrush tb = new SolidBrush(tc))
                    using (StringFormat sf = new StringFormat())
                    {
                        sf.Alignment = StringAlignment.Center;
                        sf.LineAlignment = StringAlignment.Center;
                        sf.Trimming = StringTrimming.EllipsisCharacter;
                        sf.FormatFlags = StringFormatFlags.NoWrap;
                        g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                        using (SolidBrush bb = new SolidBrush(BackColor))
                        {
                            g.FillRectangle(bb, new Rectangle(1, 1, Width - 2, Height - 2));
                        }
                        g.DrawString(txt, f, tb, new RectangleF(2, 0, Width - 4, Height), sf);
                    }
                }
                catch { }
            }
            // Рамку рисует внешняя Panel; здесь только подчищаем артефакты.
            if (BorderColor.ToArgb() != BackColor.ToArgb())
            {
                using (Pen p = new Pen(BorderColor))
                {
                    g.DrawRectangle(p, 0, 0, Width - 1, Height - 1);
                }
            }
        }
    }

    // После выбора в списке (а также если список закрыли Esc/кликом мимо)
    // фокус уходит с поля: иначе оно остаётся подсвеченным. Делается в общем
    // классе, поэтому действует на ВСЕ выпадающие списки программы без правок
    // в каждом месте создания. Отложено через BeginInvoke — сразу после
    // закрытия popup WinForms сам возвращает фокус комбобоксу и перебил бы
    // нашу правку. В карточке игры есть невидимый "EditorFocusSink" — фокус
    // отдаём ему (как и в остальных обработчиках карточки), в остальных
    // окнах просто снимаем ActiveControl. Стрелки клавиатуры при закрытом
    // списке не затрагиваются — навигация с клавиатуры продолжает работать.
    protected override void OnDropDownClosed(EventArgs e)
    {
        base.OnDropDownClosed(e);
        if (!IsHandleCreated) return;
        try
        {
            BeginInvoke((MethodInvoker)delegate
            {
                try
                {
                    Form f = FindForm();
                    if (f == null || f.IsDisposed) return;
                    // Если пользователь уже успел перейти в другое поле — не трогаем.
                    if (f.ActiveControl != null && !object.ReferenceEquals(f.ActiveControl, this)) return;
                    Control[] sinks = f.Controls.Find("EditorFocusSink", true);
                    if (sinks.Length > 0)
                    {
                        f.ActiveControl = sinks[0];
                        sinks[0].Focus();
                    }
                    else
                    {
                        f.ActiveControl = null;
                    }
                    Invalidate();
                }
                catch { }
            });
        }
        catch { }
    }

    protected override void WndProc(ref Message m)
    {
        if (ArrowHidden)
        {
            if (m.Msg == WM_LBUTTONDOWN || m.Msg == WM_LBUTTONDBLCLK) { return; }
            if (m.Msg == CB_SHOWDROPDOWN && m.WParam != IntPtr.Zero) { return; }
            if (m.Msg == WM_MOUSEWHEEL) { return; }
            if (m.Msg == WM_KEYDOWN || m.Msg == WM_SYSKEYDOWN)
            {
                int vk = m.WParam.ToInt32();
                if (vk == VK_F4 || vk == VK_DOWN || vk == VK_UP) { return; }
            }
        }

        base.WndProc(ref m);

        if (m.Msg == CB_ADDSTRING || m.Msg == CB_INSERTSTRING ||
            m.Msg == CB_DELETESTRING || m.Msg == CB_RESETCONTENT)
        {
            UpdateTheme();
            Invalidate();
        }
        else if (m.Msg == WM_PAINT || m.Msg == WM_NCPAINT)
        {
            PaintChrome();
        }
    }
}
