Set-SplashProgress 0.32
# ===================== СНЯТИЕ ФОКУСА ПРИ КЛИКЕ МИМО ПОЛЯ =====================
# Требование: фокус (рамка/выделение/курсор) должен оставаться в поле только
# пока пользователь реально в нём работает — как только он щёлкает мышью
# в любом другом месте программы (по фону окна, панели, подписи и т.п.), поле
# должно визуально терять фокус, даже если то, по чему щёлкнули, само по себе
# фокус принимать не может (и поэтому раньше просто не перехватывало клик).
#
# IMessageFilter — единая точка перехвата ДЛЯ ВСЕГО приложения (все диалоги,
# главное окно, модальные ShowDialog()), а не обработчик на каждый Panel/Label
# в отдельности: правкой одного класса эффект сразу получают все поля и все
# выпадающие списки во всей программе, без изменений в сотнях мест создания
# контролов.
Add-Type -ReferencedAssemblies @('System.Windows.Forms') -TypeDefinition @'
using System;
using System.Windows.Forms;

public class GlobalClickDefocusFilter : IMessageFilter
{
    private const int WM_LBUTTONDOWN = 0x0201;
    private static bool _registered;

    public static void Register()
    {
        if (_registered) return;
        _registered = true;
        Application.AddMessageFilter(new GlobalClickDefocusFilter());
    }

    public bool PreFilterMessage(ref Message m)
    {
        if (m.Msg != WM_LBUTTONDOWN) return false;
        try
        {
            Control target = Control.FromHandle(m.HWnd);
            // null — клик пришёлся на внутреннюю нативную часть составного
            // контрола (всплывающий список ComboBox, заголовок ListView и т.п,
            // у которых нет отдельного управляемого Control) — такие клики не
            // трогаем, иначе можно сломать выбор элемента в них же самих.
            if (target == null) return false;

            // "Поле" (текст, комбобокс, список, кнопка и т.п.) само умеет
            // принимать фокус (CanFocus == true) — раз по нему щёлкнули, значит
            // пользователь как раз начинает с ним работать, ничего не снимаем.
            // Всё остальное (сама форма, Panel/GroupBox/Label/PictureBox и т.п.
            // фон) фокус принимать не может — клик по нему как раз и означает
            // "мимо поля".
            bool isBackgroundClick = (target is Form) || !target.CanFocus;
            if (!isBackgroundClick) return false;

            Form form = target as Form ?? target.FindForm();
            if (form != null && form.ActiveControl != null)
            {
                form.ActiveControl = null;
            }
        }
        catch { }
        return false; // сообщение никогда не блокируем, только снимаем фокус
    }
}
