function T ([string]$Key, [object[]]$FormatArgs = @()) {
    # Порядок поиска: выбранный язык -> английский -> русский -> сам ключ
    # (так сразу видно, что строку забыли добавить). Английский раньше русского,
    # чтобы в неполных переводах сообщества недостающие строки были понятны большинству.
    $text = $null
    foreach ($l in @([string]$global:language, 'en', 'ru')) {
        if ($script:I18n.ContainsKey($l) -and $script:I18n[$l].ContainsKey($Key)) { $text = [string]$script:I18n[$l][$Key]; break }
    }
    if ($null -eq $text) { return $Key }
    if ($FormatArgs.Count -gt 0) {
        try { return ($text -f $FormatArgs) } catch {
            # Битые подстановки в пользовательском переводе не должны ронять интерфейс.
            try { return ([string]$script:langBuiltinI18n['ru'][$Key] -f $FormatArgs) } catch { return $text }
        }
    }
    return $text
}

# ===================== ВНЕШНИЕ ФАЙЛЫ ЛОКАЛИЗАЦИИ (СООБЩЕСТВО) =====================
# Каталог %AppData%\Steam Commander\lang содержит текстовые файлы <код>.lang.
# Встроенные языки (ru, en, zh, es, pt, de) выгружаются туда автоматически, поэтому
# любой перевод можно поправить обычным блокнотом; новый язык добавляется копией
# en.lang с другим именем и строками @code / @name / @steam в начале файла.
# Формат строки:  ключ = текст     (# — комментарий, \n — перевод строки, \\ — обратная
# косая черта, текст в "кавычках" сохраняет пробелы по краям, {0} {1}... — подстановки).
# Файл, который не правили руками, программа обновляет сама при выходе новых версий
# (признак — строка @hash); отредактированный файл не трогается: недостающие в нём
# ключи берутся из встроенного текста. Удалите файл — он будет создан заново.
# Ошибки в файлах (битые подстановки, неизвестные ключи) не ломают программу:
# такие строки пропускаются и перечисляются в окне при открытии «Настроек» и в _problems.log.
$script:langBuiltinI18n = @{}
foreach ($bc in @($script:I18n.Keys)) {
    $bt = @{}
    foreach ($bk in @($script:I18n[$bc].Keys)) { $bt[[string]$bk] = [string]$script:I18n[$bc][$bk] }
    $script:langBuiltinI18n[[string]$bc] = $bt
}
$script:langBuiltinList = @($script:languageList | ForEach-Object { [PSCustomObject]@{ Code = [string]$_.Code; Name = [string]$_.Name; Steam = [string]$_.Steam } })
$script:langSignature = $null
$script:langProblems = New-Object System.Collections.Generic.List[string]
$script:langProblemsReported = $true

function Get-LangDir { return (Join-Path $global:appDataDir 'lang') }

function ConvertTo-LangValue ([string]$Text) {
    return $Text.Replace('\', '\\').Replace("`r", '').Replace("`n", '\n')
}

function ConvertFrom-LangValue ([string]$Text) {
    $sb = New-Object System.Text.StringBuilder
    for ($i = 0; $i -lt $Text.Length; $i++) {
        $ch = [string]$Text[$i]
        if ($ch -eq '\' -and ($i + 1) -lt $Text.Length) {
            $next = [string]$Text[$i + 1]
            if ($next -eq '\') { [void]$sb.Append('\'); $i++; continue }
            if ($next -eq 'n') { [void]$sb.Append("`n"); $i++; continue }
        }
        [void]$sb.Append($ch)
    }
    return $sb.ToString()
}

function Get-LangTextHash ([string]$Text) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Text))
        return ([System.BitConverter]::ToString($bytes).Replace('-', '')).ToLowerInvariant()
    } finally { $sha.Dispose() }
}

# Каноническая форма таблицы (ключи по порядку, значения как есть) — для сравнения и хэша.
function Get-LangCanonical ($Table) {
    $keys = [string[]]@($Table.Keys)
    [Array]::Sort($keys, [System.StringComparer]::Ordinal)
    $sb = New-Object System.Text.StringBuilder
    foreach ($k in $keys) { [void]$sb.Append($k).Append('=').Append([string]$Table[$k]).Append("`n") }
    return $sb.ToString()
}

function Read-LangFile ([string]$Path) {
    $meta = @{}
    $entries = @{}
    $problems = New-Object System.Collections.Generic.List[string]
    $lines = [System.IO.File]::ReadAllLines($Path, [System.Text.Encoding]::UTF8)
    $n = 0
    foreach ($raw in $lines) {
        $n++
        $line = $raw.Trim()
        if ($line.Length -eq 0 -or $line.StartsWith('#') -or $line.StartsWith(';')) { continue }
        $eq = $line.IndexOf('=')
        if ($eq -lt 1) { [void]$problems.Add("line ${n}: '=' not found"); continue }
        $k = $line.Substring(0, $eq).Trim()
        $v = $line.Substring($eq + 1).Trim()
        if ($k.StartsWith('@')) { $meta[$k.Substring(1).ToLowerInvariant()] = $v; continue }
        if ($k -notmatch '^[A-Za-z0-9_]+$') { [void]$problems.Add("line ${n}: invalid key '$k'"); continue }
        if ($v.Length -ge 2 -and $v.StartsWith('"') -and $v.EndsWith('"')) { $v = $v.Substring(1, $v.Length - 2) }
        $entries[$k] = ConvertFrom-LangValue $v
    }
    return [PSCustomObject]@{ Meta = $meta; Entries = $entries; Problems = $problems }
}

# Подстановки {0}, {1}... в переводе должны быть допустимы для эталонной (русской) строки.
function Test-LangFormat ([string]$Text, [string]$Reference) {
    $max = -1
    foreach ($m in [System.Text.RegularExpressions.Regex]::Matches($Reference, '\{(\d+)')) {
        $idx = [int]$m.Groups[1].Value
        if ($idx -gt $max) { $max = $idx }
    }
    if ($max -lt 0) { return $true }
    try {
        $dummy = New-Object 'object[]' ($max + 1)
        for ($i = 0; $i -le $max; $i++) { $dummy[$i] = 'x' }
        [void][string]::Format($Text, $dummy)
        return $true
    } catch { return $false }
}

function Export-BuiltinLangFile ([string]$Code, [string]$Dir) {
    $path = Join-Path $Dir ($Code + '.lang')
    $table = $script:langBuiltinI18n[$Code]
    $hash = Get-LangTextHash (Get-LangCanonical $table)
    if ([System.IO.File]::Exists($path)) {
        $p = Read-LangFile $path
        $stored = [string]$p.Meta['hash']
        if ([string]::IsNullOrEmpty($stored)) { return }
        if ((Get-LangTextHash (Get-LangCanonical $p.Entries)) -ne $stored) { return }
        if ($stored -eq $hash) { return }
    }
    $info = $script:langBuiltinList | Where-Object { $_.Code -eq $Code } | Select-Object -First 1
    $out = New-Object System.Collections.Generic.List[string]
    [void]$out.Add('# Steam Commander language file. You can edit any text below; see _README.txt for the format.')
    [void]$out.Add('# Delete this file to restore the original built-in text.')
    [void]$out.Add('@code = ' + $Code)
    [void]$out.Add('@name = ' + [string]$info.Name)
    [void]$out.Add('@steam = ' + [string]$info.Steam)
    [void]$out.Add('@hash = ' + $hash)
    [void]$out.Add('')
    $keys = [string[]]@($table.Keys)
    [Array]::Sort($keys, [System.StringComparer]::Ordinal)
    foreach ($k in $keys) {
        $v = ConvertTo-LangValue ([string]$table[$k])
        if ($v -ne $v.Trim() -or ($v.Length -ge 2 -and $v.StartsWith('"') -and $v.EndsWith('"'))) { $v = '"' + $v + '"' }
        [void]$out.Add($k + ' = ' + $v)
    }
    [System.IO.File]::WriteAllText($path, (($out -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($true)))
}

function Write-LangReadme ([string]$Dir) {
    $text = @'
STEAM COMMANDER - LANGUAGE FILES / ЯЗЫКОВЫЕ ФАЙЛЫ

EDIT A TRANSLATION
  Open ru.lang / en.lang / ... in any text editor (UTF-8), change the text after "=",
  save, then open Settings in Steam Commander - the changes are picked up automatically.
  Delete a file to restore the original built-in text.

ADD A NEW LANGUAGE
  1. Copy en.lang to a new name, e.g. uk.lang.
  2. Change the header lines at the top:
       @code  = uk            (2-3 letters, lowercase; Windows UI language is auto-detected by it)
       @name  = Українська    (the name shown in the language list)
       @steam = ukrainian     (Steam API language for game art: english, russian, german, french,
                               spanish, latam, brazilian, schinese, tchinese, japanese, koreana,
                               polish, ukrainian, turkish, italian, ...)
  3. Delete the "@hash" line and translate the texts.
  4. Untranslated lines can simply be deleted - English text is used for them.
  5. Open Settings and pick your language in the list.

FORMAT
  key = text         one string per line. Do not change the keys (left side).
  # comment          lines starting with # or ; are ignored.
  \n                 new line inside a string.      \\   a backslash.
  "text "            quotes keep spaces at the start/end of a string.
  {0} {1} ...        placeholders filled in by the program - keep them (order may change).
Strings with broken placeholders or unknown keys are skipped and listed in _problems.log.

Русский: правьте текст после «=» в любом редакторе (UTF-8). Чтобы добавить язык, скопируйте
en.lang под новым именем (например, uk.lang), измените строки @code, @name, @steam, удалите
строку @hash и переведите тексты. Непереведённые строки можно удалить — будет использован
английский текст. Откройте «Настройки» — изменения подхватятся автоматически.
'@
    $path = Join-Path $Dir '_README.txt'
    $bytes = ($text -replace "`r?`n", "`r`n")
    try {
        if ([System.IO.File]::Exists($path) -and ([System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8) -eq $bytes)) { return }
        [System.IO.File]::WriteAllText($path, $bytes, (New-Object System.Text.UTF8Encoding($true)))
    } catch {}
}

# Собирает таблицы из встроенных данных + файлов каталога lang. Возвращает $true,
# если набор файлов изменился с прошлого вызова (и язык стоит применить заново).
function Initialize-Localization {
    $dir = Get-LangDir
    try { [void][System.IO.Directory]::CreateDirectory($dir) } catch { return $false }

    foreach ($c in @($script:langBuiltinList | ForEach-Object { $_.Code })) { try { Export-BuiltinLangFile ([string]$c) $dir } catch {} }
    Write-LangReadme $dir

    $files = @()
    try { $files = @(Get-ChildItem -LiteralPath $dir -Filter '*.lang' -File -ErrorAction Stop | Sort-Object Name) } catch {}
    $sig = (($files | ForEach-Object { $_.Name + '|' + $_.Length + '|' + $_.LastWriteTimeUtc.Ticks }) -join ';')
    if ($null -ne $script:langSignature -and $sig -eq $script:langSignature) { return $false }
    $script:langSignature = $sig

    $problems = New-Object System.Collections.Generic.List[string]
    $tables = @{}
    foreach ($bc in @($script:langBuiltinI18n.Keys)) {
        $copy = @{}
        foreach ($bk in @($script:langBuiltinI18n[$bc].Keys)) { $copy[[string]$bk] = [string]$script:langBuiltinI18n[$bc][$bk] }
        $tables[[string]$bc] = $copy
    }
    $builtinCodes = @($script:langBuiltinList | ForEach-Object { $_.Code })
    $community = New-Object System.Collections.Generic.List[object]
    $ref = $script:langBuiltinI18n['ru']

    foreach ($f in $files) {
        try {
            $p = Read-LangFile $f.FullName
            foreach ($pr in $p.Problems) { [void]$problems.Add($f.Name + ': ' + $pr) }
            $code = [string]$p.Meta['code']
            if ([string]::IsNullOrWhiteSpace($code)) { $code = [System.IO.Path]::GetFileNameWithoutExtension($f.Name) }
            $code = $code.Trim().ToLowerInvariant()
            if ($code -notmatch '^[a-z]{2,3}([_-][a-z0-9]{2,8})?$') {
                [void]$problems.Add($f.Name + ": invalid @code '" + $code + "'"); continue
            }
            if (-not $tables.ContainsKey($code)) {
                $tables[$code] = @{}
                $name = [string]$p.Meta['name']
                if ([string]::IsNullOrWhiteSpace($name)) { $name = $code }
                $steam = ([string]$p.Meta['steam']).Trim().ToLowerInvariant()
                if ($steam -notmatch '^[a-z]{3,20}$') { $steam = 'english' }
                [void]$community.Add([PSCustomObject]@{ Code = $code; Name = $name.Trim(); Steam = $steam })
            }
            $target = $tables[$code]
            foreach ($k in @($p.Entries.Keys)) {
                $v = [string]$p.Entries[$k]
                if (-not $ref.ContainsKey($k)) { [void]$problems.Add($f.Name + ": unknown key '" + $k + "'"); continue }
                if ($v.Length -eq 0 -and ([string]$ref[$k]).Length -gt 0) { continue }
                if (-not (Test-LangFormat $v ([string]$ref[$k]))) { [void]$problems.Add($f.Name + ": broken placeholders in '" + $k + "'"); continue }
                $target[$k] = $v
            }
        } catch {
            [void]$problems.Add($f.Name + ': ' + $_.Exception.Message)
        }
    }

    $list = New-Object System.Collections.ArrayList
    foreach ($b in $script:langBuiltinList) { [void]$list.Add($b) }
    foreach ($c in @($community | Sort-Object Name)) { [void]$list.Add($c) }
    $script:I18n = $tables
    $script:languageList = $list.ToArray()
    $script:langProblems = $problems
    $script:langProblemsReported = ($problems.Count -eq 0)

    $logPath = Join-Path $dir '_problems.log'
    try {
        if ($problems.Count -gt 0) { [System.IO.File]::WriteAllText($logPath, (($problems -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($true))) }
        elseif ([System.IO.File]::Exists($logPath)) { [System.IO.File]::Delete($logPath) }
    } catch {}

    if (-not $script:I18n.ContainsKey([string]$global:language)) {
        if ([string]$global:language -ne '') { $global:language = 'en' }
    }
    return $true
}

# Все постоянные настройки и служебные метаданные хранятся в профиле
# пользователя, а не рядом с EXE. Благодаря этому каталог программы может
# содержать только один Steam Commander.exe.
$global:appDataDir = Join-Path ([Environment]::GetFolderPath('ApplicationData')) "Steam Commander"
$global:coverSourcesDir = Join-Path $global:appDataDir "cover_sources"
# API-ключ SteamGridDB (бесплатный, получается на steamgriddb.com/profile/preferences/api)
# — используется как резервный источник обложек, когда у официального CDN
# Steam нет нужных картинок (совсем новые/непопулярные издания, только hero
# без капсулы и т.п.). Хранится в config.ini рядом с остальными настройками.
$global:steamGridDbApiKey = ""
# Состояние последней проверки ключа SteamGridDB. До успешной проверки
# SGDB-поиск считается недоступным.
$global:steamGridDbApiKeyValid = $false
# Если включено, игровые лаунчеры разрешены среди автоматически найденных EXE.
# По умолчанию выключено: лаунчеры отбрасываются из списка кандидатов.
$global:suggestGameLaunchers = $false
# Если включено, иконка игры берётся из её EXE (а не из Steam). Кнопка EXE на
# миниатюре иконки в карточке игры переключает иконку туда и обратно.
$global:useExeIcons = $false
# Положение и размер логотипа «по умолчанию» (галочка в слоте «Фон и логотип» карточки игры).
# Пока logoDefaultEnabled = $true, эти значения применяются ко всем карточкам, ромам и автоимпорту.
$global:logoDefaultEnabled = $false
$global:logoDefaultPosition = 'BottomLeft'
$global:logoDefaultWidthPct = 50.0
$global:logoDefaultHeightPct = 50.0
# Регион обложек Steam (API-имя: english, russian, …). Задаётся в «Настройках»
# и используется как язык ассетов по умолчанию (кнопки EN/РУ на карточке,
# загрузка официальных обложек). Пустое значение = брать из языка интерфейса.
$global:steamCoverRegion = ''

# Публичный ключ Steam Web API (steamcommunity.com/dev/apikey) — отдельный от
# ключа SteamGridDB. Используется только для скачивания полного списка
# приложений Steam (IStoreService/GetAppList) в локальную базу для поиска.
# Хранится в config.ini рядом с остальными настройками, база — рядом с ним
# же, в %AppData%\Steam Commander, там же, где все прочие метаданные программы.
$global:steamApiKey = ""
$global:steamApiKeyValid = $false
$global:steamAppsDbFile = Join-Path $global:appDataDir "steam_apps_db.json"

# ============================================================================
# ТЕМАТИЧЕСКОЕ ОКНО СООБЩЕНИЙ В СТИЛЕ STEAM COMMANDER
# Замена стандартного окна MessageBox во всей программе.
# Принимает те же аргументы в том же порядке — [владелец,] текст, заголовок, кнопки, значок —
# и возвращает DialogResult, поэтому вызовы переписываются механически:
#     Show-AppMessageBox($owner, $text, $title, $buttons, $icon)
# Поддерживаются кнопки OK и Да/Нет (OKCancel/YesNoCancel сводятся к ним), значки
# Error / Warning / Information / Question. Длинный текст получает прокрутку.
# Функция не зависит от остального интерфейса, поэтому работает и до запуска главного окна.
# ============================================================================
function Show-AppMessageBox {
    param($ArgList)
    $a = @($ArgList)
    $i = 0
    $owner = $null
    if ($a.Count -gt 0 -and -not ($a[0] -is [string])) { $owner = $a[0]; $i = 1 }
    $text  = if ($a.Count -gt $i)     { [string]$a[$i] }     else { '' }
    $title = if ($a.Count -gt $i + 1) { [string]$a[$i + 1] } else { '' }
    if ([string]::IsNullOrWhiteSpace($title)) { try { $title = [string]$global:appTitle } catch {} }
    $btnInt  = if ($a.Count -gt $i + 2) { [int]$a[$i + 2] } else { 0 }
    $iconInt = if ($a.Count -gt $i + 3) { [int]$a[$i + 3] } else { 0 }
    $isYesNo = ($btnInt -eq 4 -or $btnInt -eq 3)

    $ownerForm = $null
    if ($owner -is [System.Windows.Forms.Form] -and -not $owner.IsDisposed -and $owner.Visible) { $ownerForm = $owner }

    # Палитра берётся из $steamUi; запасные значения — те же цвета, на случай раннего вызова.
    $pal = @{
        Bg      = [System.Drawing.Color]::FromArgb(23, 29, 37)
        Panel   = [System.Drawing.Color]::FromArgb(27, 40, 56)
        Panel2  = [System.Drawing.Color]::FromArgb(20, 30, 42)
        Border  = [System.Drawing.Color]::FromArgb(58, 73, 90)
        Text    = [System.Drawing.Color]::FromArgb(220, 223, 228)
        Accent  = [System.Drawing.Color]::FromArgb(102, 192, 244)
        Accent2 = [System.Drawing.Color]::FromArgb(26, 159, 255)
    }
    try { if ($null -ne $steamUi) { foreach ($k in @('Bg', 'Panel', 'Panel2', 'Border', 'Text', 'Accent', 'Accent2')) { if ($null -ne $steamUi[$k]) { $pal[$k] = $steamUi[$k] } } } } catch {}

    # Значок: 16 = ошибка, 32 = вопрос, 48 = предупреждение, 64 = информация.
    $glyph = $null; $glyphColor = $pal.Accent
    switch ($iconInt) {
        16 { $glyph = [string][char]0x2715; $glyphColor = [System.Drawing.Color]::FromArgb(224, 90, 90) }
        32 { $glyph = '?';                  $glyphColor = $pal.Accent }
        48 { $glyph = '!';                  $glyphColor = [System.Drawing.Color]::FromArgb(240, 178, 60) }
        64 { $glyph = 'i';                  $glyphColor = $pal.Accent }
    }
    try {
        switch ($iconInt) {
            16 { [System.Media.SystemSounds]::Hand.Play() }
            32 { [System.Media.SystemSounds]::Question.Play() }
            48 { [System.Media.SystemSounds]::Exclamation.Play() }
            64 { [System.Media.SystemSounds]::Asterisk.Play() }
        }
    } catch {}

    $formW = 460; $padX = 24; $iconSize = 40; $iconGap = 16; $topPad = 26; $footerH = 64; $maxTextH = 280
    $textX = $padX + $(if ($null -ne $glyph) { $iconSize + $iconGap } else { 0 })
    $textW = $formW - $textX - $padX
    $font = New-Object System.Drawing.Font('Segoe UI', 10)

    $flags = [System.Windows.Forms.TextFormatFlags]::WordBreak -bor [System.Windows.Forms.TextFormatFlags]::NoPadding
    $measured = [System.Windows.Forms.TextRenderer]::MeasureText($text, $font, (New-Object System.Drawing.Size($textW, 0)), $flags)
    $textH = [Math]::Max(22, $measured.Height + 8)
    $needScroll = ($textH -gt $maxTextH)
    $panelH = [Math]::Min($textH, $maxTextH)
    $areaH = [Math]::Max($(if ($null -ne $glyph) { $iconSize } else { 0 }), $panelH)
    $panelW = $textW + $(if ($needScroll) { [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth } else { 0 })

    $f = New-Object System.Windows.Forms.Form
    $iconBmp = $null
    try {
        $f.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::None
        $f.Text = $title
        $f.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
        $f.MaximizeBox = $false; $f.MinimizeBox = $false
        $f.ShowInTaskbar = ($null -eq $ownerForm)
        $f.TopMost = ($null -eq $ownerForm)
        $f.StartPosition = if ($null -ne $ownerForm) { 'CenterParent' } else { 'CenterScreen' }
        $f.ClientSize = New-Object System.Drawing.Size($formW, ($topPad + $areaH + 24 + $footerH))
        $f.BackColor = $pal.Bg
        $f.ForeColor = $pal.Text
        $f.Font = New-Object System.Drawing.Font('Segoe UI', 9)
        try {
            if ($null -ne $ownerForm -and $null -ne $ownerForm.Icon) { $f.Icon = $ownerForm.Icon }
            elseif ($null -ne $form -and $null -ne $form.Icon) { $f.Icon = $form.Icon }
            else { $f.ShowIcon = $false }
        } catch { try { $f.ShowIcon = $false } catch {} }
        try { if ('Win11PopupDwm' -as [type]) { $f.Add_HandleCreated({ try { [Win11PopupDwm]::Apply($this.Handle) } catch {} }) } } catch {}

        if ($null -ne $glyph) {
            $iconBmp = New-Object System.Drawing.Bitmap($iconSize, $iconSize)
            $g = [System.Drawing.Graphics]::FromImage($iconBmp)
            try {
                $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
                $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
                $fill = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(44, $glyphColor))
                $pen = New-Object System.Drawing.Pen($glyphColor, 2.0)
                $gf = New-Object System.Drawing.Font($(if ($iconInt -eq 16) { 'Segoe UI Symbol' } else { 'Segoe UI Semibold' }), 17)
                $gb = New-Object System.Drawing.SolidBrush($glyphColor)
                $sf = New-Object System.Drawing.StringFormat
                $sf.Alignment = [System.Drawing.StringAlignment]::Center
                $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
                $g.FillEllipse($fill, 2, 2, ($iconSize - 5), ($iconSize - 5))
                $g.DrawEllipse($pen, 2, 2, ($iconSize - 5), ($iconSize - 5))
                $g.DrawString($glyph, $gf, $gb, (New-Object System.Drawing.RectangleF(0, 0, $iconSize, ($iconSize + 1))), $sf)
                $fill.Dispose(); $pen.Dispose(); $gf.Dispose(); $gb.Dispose(); $sf.Dispose()
            } finally { $g.Dispose() }
            $pic = New-Object System.Windows.Forms.PictureBox
            $pic.Image = $iconBmp
            $pic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Normal
            $pic.BackColor = $pal.Bg
            $pic.Size = New-Object System.Drawing.Size($iconSize, $iconSize)
            $pic.Location = New-Object System.Drawing.Point($padX, ($topPad + [int](($areaH - $iconSize) / 2)))
            $f.Controls.Add($pic)
        }

        $holder = New-Object System.Windows.Forms.Panel
        $holder.BackColor = $pal.Bg
        $holder.AutoScroll = $needScroll
        $holder.Size = New-Object System.Drawing.Size($panelW, $panelH)
        $holder.Location = New-Object System.Drawing.Point($textX, ($topPad + [int](($areaH - $panelH) / 2)))
        $lbl = New-Object System.Windows.Forms.Label
        $lbl.UseCompatibleTextRendering = $false
        $lbl.AutoSize = $false
        $lbl.Font = $font
        $lbl.ForeColor = $pal.Text
        $lbl.BackColor = $pal.Bg
        $lbl.Text = $text
        $lbl.Location = New-Object System.Drawing.Point(0, 0)
        $lbl.Size = New-Object System.Drawing.Size($textW, $textH)
        $holder.Controls.Add($lbl)
        $f.Controls.Add($holder)

        $footer = New-Object System.Windows.Forms.Panel
        $footer.Dock = [System.Windows.Forms.DockStyle]::Bottom
        $footer.Height = $footerH
        $footer.BackColor = $pal.Panel2
        $f.Controls.Add($footer)

        $mkBtn = {
            param([string]$caption, $result, [bool]$primary, [int]$x)
            $b = New-Object System.Windows.Forms.Button
            $b.Text = $caption
            $b.Size = New-Object System.Drawing.Size(110, 34)
            $b.Location = New-Object System.Drawing.Point($x, 15)
            $b.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
            $b.Font = New-Object System.Drawing.Font($(if ($primary) { 'Segoe UI Semibold' } else { 'Segoe UI' }), 9)
            $b.ForeColor = $pal.Text
            $b.Cursor = [System.Windows.Forms.Cursors]::Hand
            $b.DialogResult = $result
            if ($primary) {
                $b.FlatAppearance.BorderColor = $pal.Accent2
                $b.BackColor = [System.Drawing.Color]::FromArgb(25, 55, 75)
                $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(35, 78, 106)
            } else {
                $b.FlatAppearance.BorderColor = $pal.Border
                $b.BackColor = $pal.Panel
                $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(38, 76, 108)
            }
            return $b
        }
        $xRight = $formW - $padX - 110
        if ($isYesNo) {
            $bNo  = & $mkBtn (T 'confirm_no')  ([System.Windows.Forms.DialogResult]::No)  $false $xRight
            $bYes = & $mkBtn (T 'confirm_yes') ([System.Windows.Forms.DialogResult]::Yes) $true  ($xRight - 120)
            $footer.Controls.Add($bNo); $footer.Controls.Add($bYes)
            $f.AcceptButton = $bYes; $f.CancelButton = $bNo
            $f.ActiveControl = $bYes
        } else {
            $bOk = & $mkBtn 'OK' ([System.Windows.Forms.DialogResult]::OK) $true $xRight
            $footer.Controls.Add($bOk)
            $f.AcceptButton = $bOk; $f.CancelButton = $bOk
            $f.ActiveControl = $bOk
        }

        $res = if ($null -ne $ownerForm) { $f.ShowDialog($ownerForm) } else { $f.ShowDialog() }
        if ($res -eq [System.Windows.Forms.DialogResult]::Cancel -or $res -eq [System.Windows.Forms.DialogResult]::None) {
            $res = if ($isYesNo) { [System.Windows.Forms.DialogResult]::No } else { [System.Windows.Forms.DialogResult]::OK }
        }
        return $res
    } finally {
        try { $f.Dispose() } catch {}
        try { if ($null -ne $iconBmp) { $iconBmp.Dispose() } } catch {}
        try { $font.Dispose() } catch {}
    }
}

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    $osLang = ''; try { $osLang = [System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName } catch {}
    $adminMsg = switch ($osLang) { 'ru' { @('Запустите программу от имени АДМИНИСТРАТОРА!', 'Ошибка') } 'zh' { @('请以管理员身份运行本程序！', '错误') } 'es' { @('¡Ejecuta el programa como ADMINISTRADOR!', 'Error') } 'pt' { @('Execute o programa como ADMINISTRADOR!', 'Erro') } 'de' { @('Starte das Programm als ADMINISTRATOR!', 'Fehler') } default { @('Run the program as ADMINISTRATOR!', 'Error') } }
    Show-AppMessageBox($adminMsg[0], $adminMsg[1], [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
    exit
}

function Create-InitialDirs {
    # Постоянные данные программы находятся в %APPDATA%\Steam Commander.
    # Рядом с EXE ничего не создаём.
    if (-not (Test-Path $global:appDataDir)) {
        New-Item -ItemType Directory -Path $global:appDataDir -Force | Out-Null
    }
    $defaultBackupDir = Join-Path $global:appDataDir "backup"
    if (-not (Test-Path -LiteralPath $defaultBackupDir)) {
        New-Item -ItemType Directory -Path $defaultBackupDir -Force | Out-Null
    }
    if (-not (Test-Path $global:coverSourcesDir)) {
        New-Item -ItemType Directory -Path $global:coverSourcesDir -Force | Out-Null
    }
}
Create-InitialDirs
function Get-FolderSize ($path) {
    $size = 0
    try {
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            return [int64](Get-Item -LiteralPath $path -ErrorAction Stop).Length
        }
    } catch {}
    Get-ChildItem -LiteralPath $path -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $size += $_.Length }
    return $size
}

function Clean-GameName ($itemText) {
    return ($itemText -replace "\s*\(\d+(?:[.,]\d+)?\s*(?:ГБ|МБ|КБ|GB|MB|KB)\)", "").Trim()
}

# ЭТОЙ ФУНКЦИИ НЕ БЫЛО В ФАЙЛЕ ВООБЩЕ — отсюда были "сломаны" все три кнопки "..."
function Test-FileInsideRoot ($filePath, $rootPath) {
    if ([string]::IsNullOrWhiteSpace([string]$filePath) -or [string]::IsNullOrWhiteSpace([string]$rootPath)) { return $false }
    try {
        $fileFull = [System.IO.Path]::GetFullPath([string]$filePath).TrimEnd('\')
        $rootFull = [System.IO.Path]::GetFullPath([string]$rootPath).TrimEnd('\')
        $prefix = $rootFull + '\'
        return $fileFull.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
    } catch {
        return $false
    }
}

function Show-CenteredFolderDialog ($description, $initialPath) {
    # $form ещё не создана в момент ОПРЕДЕЛЕНИЯ этой функции, но к моменту её ВЫЗОВА
    # (из обработчиков кнопок) форма уже существует — PowerShell разрешает $form по имени
    # в момент выполнения, а не в момент объявления функции.
    $ownerHandle = [IntPtr]::Zero
    if ((Test-Path variable:form) -and ($form -ne $null)) { $ownerHandle = $form.Handle }

    try {
        # Современный диалог Проводника (IFileOpenDialog + FOS_PICKFOLDERS) —
        # тот же, что открывается через "Обзор" в самой Windows.
        $dialog = New-Object ModernDialogs.VistaFolderBrowserDialog
        $dialog.Description = $description
        # Режим выбора папки (FOS_PICKFOLDERS): папку можно выбрать одним кликом. В этом режиме Windows не показывает файлы — это ограничение системного диалога.
        $dialog.ShowFiles = $false
        $dialog.FileNameHint = (T 'dlg_pick_folder_name')
        $dialog.OkLabel = (T 'dlg_pick_folder_btn')
        if ((-not [string]::IsNullOrEmpty($initialPath)) -and (Test-Path $initialPath)) {
            $dialog.SelectedPath = $initialPath
        }
        if ($dialog.ShowDialog($ownerHandle)) {
            return $dialog.SelectedPath
        }
        return $null
    } catch {
        # Резервный вариант на случай, если современный COM-диалог недоступен
        # (сильно урезанная/нестандартная сборка Windows) — старый, но рабочий диалог.
        $fallback = New-Object System.Windows.Forms.FolderBrowserDialog
        $fallback.Description = $description
        $fallback.ShowNewFolderButton = $true
        if ((-not [string]::IsNullOrEmpty($initialPath)) -and (Test-Path $initialPath)) {
            $fallback.SelectedPath = $initialPath
        }
        $result = if ($form -ne $null) { $fallback.ShowDialog($form) } else { $fallback.ShowDialog() }
        if ($result -eq [System.Windows.Forms.DialogResult]::OK) {
            return $fallback.SelectedPath
        }
        return $null
    }
}

$global:installedSteamGames = @{}
# Сведения для значка строки в списке библиотеки: путь игры (нормализованный ключ) ->
# @{ Icon; Exe; LaunchOptions; Dir } из ярлыка Steam. Заполняется в Refresh-Panels.
$global:installedGameIcons = @{}

# БАГ-ФИКС: раньше "установлена ли игра" определялось только по совпадению
# НАЗВАНИЯ (нормализованное имя папки == нормализованный AppName ярлыка).
# Это ломалось в обе стороны: не подсвечивало реально установленные игры при
# расхождениях в написании названия, и — куда хуже — ОШИБОЧНО подсвечивало
# как "уже в Steam" любую папку, чьё название просто СОВПАДАЕТ с названием
# уже добавленной игры, даже если это совершенно другая папка на другом диске
# (например, тестовая копия с тем же именем).
#
# Теперь ключами словаря служат не названия, а нормализованные АБСОЛЮТНЫЕ ПУТИ
# (см. Get-NormalizedGamePathKey) — тот самый корень игры под $dirC/$dirD, на
# который в реальности указывает Exe/StartDir существующего ярлыка (см.
# Get-TopLevelFolderUnderRoot и заполнение словаря в Refresh-Panels). Совпадение
# признаётся только когда это буквально тот же самый путь на диске, а не просто
# похожее название.
function Get-NormalizedGameKey ($rawName) {
    if ([string]::IsNullOrEmpty($rawName)) { return "" }
    return [System.Text.RegularExpressions.Regex]::Replace($rawName.ToUpper(), '[^\p{L}\p{Nd}]', '')
}

# Ключ для сравнения РЕАЛЬНОГО расположения на диске (а не названия) — убираем
# кавычки, завершающий "\" и регистр. Используется там, где "уже в библиотеке"
# должно определяться по фактическому пути игры, а не по совпадению имени
# папки (см. $global:installedSteamGames выше и комментарий у Refresh-Panels).
function Get-NormalizedGamePathKey ($rawPath) {
    if ([string]::IsNullOrEmpty($rawPath)) { return "" }
    try { return $rawPath.Trim('"').TrimEnd('\').ToUpperInvariant() } catch { return "" }
}

# Тот же самый признак "в библиотеке", что рисует зелёную подпись-галочку у
# строки списка (см. Register-ListBoxDrawEvent) — используется колонкой
# сортировки "В библиотеке", чтобы сортировка совпадала с тем, что видно
# на экране. $rawPath — реальный путь папки на диске (обязателен: без пути
# сравнение по одному лишь имени возвращало бы ложные совпадения).
function Test-PanelItemInLibrary ([string]$rawName, [string]$rawPath = $null) {
    if ([string]::IsNullOrEmpty($rawPath)) { return $false }
    return [bool]$global:installedSteamGames.ContainsKey((Get-NormalizedGamePathKey $rawPath))
}

# ===================== НЕЧЁТКОЕ СРАВНЕНИЕ НАЗВАНИЙ ИГР =====================
# Слова, которые почти ничего не говорят о том, какая это ИМЕННО игра
# (обозначения изданий, ремастеров и т.п.) — исключаются при разбиении
# названия на "значимые" слова для нечёткого сравнения. Иначе почти любые
# две игры с "Complete Edition" в названии считались бы "похожими" друг
# на друга.
$global:steamStopWords = @('THE','A','AN','OF','AND','EDITION','EDITIONS','GOTY','COMPLETE','DEFINITIVE','REMASTERED','REMASTER','HD','ULTIMATE','DELUXE','GOLD','COLLECTORS','ENHANCED','DIRECTORS','CUT','REMAKE','REBIRTH','ANNIVERSARY','GAME','YEAR','SPECIAL','STANDARD','VERSION')

# Разбивает название на "значимые" слова (без пунктуации, торговых значков
# и служебных слов изданий) — используется для нечёткого сравнения
# результатов онлайн-поиска Steam.
function Get-NameTokens ($name) {
    if ([string]::IsNullOrEmpty($name)) { return @() }
    $clean = $name -replace '[™®©]', ''
    $words = [System.Text.RegularExpressions.Regex]::Split($clean.ToUpper(), '[^\p{L}\p{Nd}]+') | Where-Object { $_ -ne '' }
    return @($words | Where-Object { $global:steamStopWords -notcontains $_ })
}

# Доля общих значимых слов между двумя названиями (коэффициент Жаккара).
# 1.0 — идентичный набор слов, 0.0 — ничего общего.
function Get-TokenOverlapScore ($tokensA, $tokensB) {
    if ($tokensA.Count -eq 0 -or $tokensB.Count -eq 0) { return 0 }
    $setA = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($t in $tokensA) { [void]$setA.Add($t) }
    $setB = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($t in $tokensB) { [void]$setB.Add($t) }
    $common = 0
    foreach ($t in $setA) { if ($setB.Contains($t)) { $common++ } }
    $union = ([int]$setA.Count + [int]$setB.Count) - [int]$common
    if ($union -eq 0) { return 0 }
    return ($common / [double]$union)
}

# Проверяет, что нормализованный ключ короткого названия ($shortKey) совпадает
# с началом длинного названия РОВНО по границе слова. Нужна, чтобы «StarCraft»
# не считался началом «Star Crafter» (склеенные ключи STARCRAFT/STARCRAFTER
# начинаются одинаково, но слово «Crafter» — другое слово), тогда как
# «Resident Evil 4» по-прежнему считается началом «Resident Evil 4 Gold Edition»,
# а склеенное имя папки «ResidentEvil4» — началом «Resident Evil 4 Gold Edition».
function Test-NameWordBoundaryPrefix ([string]$shortKey, [string]$longName) {
    if ([string]::IsNullOrEmpty($shortKey) -or [string]::IsNullOrEmpty($longName)) { return $false }
    $clean = $longName -replace '[™®©]', ''
    $words = @([System.Text.RegularExpressions.Regex]::Split($clean.ToUpper(), '[^\p{L}\p{Nd}]+') | Where-Object { $_ -ne '' })
    $acc = ''
    foreach ($w in $words) {
        $acc += $w
        if ($acc -eq $shortKey) { return $true }
        if ($acc.Length -ge $shortKey.Length) { return $false }
    }
    return $false
}

# "Номера частей" в названии: отдельные цифры и римские числа (4, V, IV...). Нужны, чтобы
# нечёткий поиск не подсовывал соседнюю часть серии: "DiRT 4" ≠ "DiRT Rally 2.0", "GTA V" ≠ "GTA IV".
function Get-NameSequelMarkers ($tokens) {
    $list = New-Object System.Collections.Generic.List[string]
    foreach ($t in @($tokens)) {
        $s = [string]$t
        if ($s -match '^\d+$' -or $s -match '^(II|III|IV|V|VI|VII|VIII|IX|X|XI|XII|XIII|XIV|XV)$') { [void]$list.Add($s) }
    }
    return (($list | Sort-Object -Unique) -join ',')
}
function Test-NameSequelMarkersMatch ($tokensA, $tokensB) {
    return ((Get-NameSequelMarkers $tokensA) -eq (Get-NameSequelMarkers $tokensB))
}

# Похоже ли название кандидата на дополнение/саундтрек/демо, а не на саму игру. Если такое слово
# есть и в самом искомом названии, кандидата не отбраковываем.
function Test-SteamNameLooksLikeAddon ([string]$candidateName, [string]$targetName) {
    $pattern = '(?i)\b(season\s*pass|season\s*\d|dlc|soundtrack|original\s+score|artbook|art\s+book|expansion\s+pass|upgrade|bonus\s+(content|pack)|add-?on|demo|playtest|dedicated\s+server|mod\s+tools|sdk)\b'
    if ($candidateName -notmatch $pattern) { return $false }
    if ($targetName -match $pattern) { return $false }
    return $true
}

# Некоторые игры (особенно на Unreal Engine) держат .exe в глубоко вложенной
# подпапке (например "ИмяИгры\ИмяИгры\Binaries\Win64\Game.exe"), и StartDir
# ярлыка указывает именно на эту вложенную папку, а не на корневую папку игры
# в SSD/HDD-панели. Раньше игра "угадывалась" по фиксированному номеру
# сегмента пути — ломалось при любой другой глубине вложенности. Эта функция
# решает задачу иначе и однозначно: раз мы точно знаем корень библиотеки
# (SSD-папку $global:dirC или HDD-папку $global:dirD), достаточно найти, какой
# из ПОДПАПОК этого корня является префиксом пути из ярлыка (Exe/StartDir) —
# именно он и есть настоящая папка игры, независимо от того, насколько глубоко
# внутри неё лежит сам .exe.
function Get-TopLevelFolderUnderRoot ($fullPath, $rootPath) {
    if ([string]::IsNullOrEmpty($fullPath) -or [string]::IsNullOrEmpty($rootPath)) { return $null }
    try {
        $normRoot = $rootPath.Trim('"').TrimEnd('\') + '\'
        $normPath = $fullPath.Trim('"')
        if ($normPath.Length -le $normRoot.Length) { return $null }
        if ($normPath.Substring(0, $normRoot.Length).ToUpper() -ne $normRoot.ToUpper()) { return $null }
        $rest = $normPath.Substring($normRoot.Length)
        $firstSegment = $rest.Split('\')[0]
        if ([string]::IsNullOrEmpty($firstSegment)) { return $null }
        return $firstSegment
    } catch { return $null }
}

# ===================== ЗНАЧОК ДОБАВЛЕННОЙ ИГРЫ В СПИСКЕ =====================
# У игры, уже добавленной в Steam, вместо жёлтой папки показываем:
#   1) иконку, выбранную при добавлении (поле icon ярлыка, слот «5. Иконка»);
#   2) если её нет — значок exe-файла игры (Exe ярлыка);
#   3) для игр лаунчеров за SCLauncher.exe (в Exe стоит обёртка) — значок
#      основного exe из папки игры (или из --exe в параметрах запуска).
# Если ничего не нашлось, остаётся обычная папка.
if ($null -eq $script:installedGameIconCache) { $script:installedGameIconCache = @{} }

function Register-InstalledGameIconInfo ([string]$gamePath, [string]$iconVal, [string]$exeVal, [string]$launchOpts, [bool]$iconOnly = $false) {
    try {
        if ([string]::IsNullOrWhiteSpace($gamePath)) { return }
        $k = Get-NormalizedGamePathKey $gamePath
        if (-not $k) { return }
        $iconClean = ([string]$iconVal).Trim().Trim('"')
        $hasIcon = -not [string]::IsNullOrWhiteSpace($iconClean)
        # ROM: показываем только выбранную иконку (без подмены значком эмулятора/exe).
        if ($iconOnly -and -not $hasIcon) { return }
        if ($global:installedGameIcons.ContainsKey($k)) {
            $old = $global:installedGameIcons[$k]
            # Уже есть запись с выбранной иконкой — не затираем; иначе заменяем только записью с иконкой.
            if (-not [string]::IsNullOrWhiteSpace([string]$old.Icon) -or -not $hasIcon) { return }
        }
        $global:installedGameIcons[$k] = @{
            Icon = $iconClean
            Exe = ([string]$exeVal).Trim().Trim('"')
            LaunchOptions = [string]$launchOpts
            Dir = $gamePath
            IconOnly = $iconOnly
        }
    } catch {}
}

# Картинка-значок (.ico/.png/.jpg/...) -> Bitmap $size x $size. Файл читается в память и не блокируется.
function Get-ImageFileIconBitmap ([string]$filePath, [int]$size) {
    try {
        if ([string]::IsNullOrWhiteSpace($filePath) -or -not (Test-Path -LiteralPath $filePath -PathType Leaf)) { return $null }
        $ext = [System.IO.Path]::GetExtension($filePath).ToLowerInvariant()
        if ($ext -in @('.exe','.dll','.lnk')) { return (Get-IconBitmapFromFile $filePath $size) }
        $bytes = [System.IO.File]::ReadAllBytes($filePath)
        $ms = New-Object System.IO.MemoryStream(, $bytes)
        $src = $null
        try {
            if ($ext -eq '.ico') {
                $ico = New-Object System.Drawing.Icon($ms, $size, $size)
                try { $src = $ico.ToBitmap() } finally { $ico.Dispose() }
            } else {
                $img = [System.Drawing.Image]::FromStream($ms)
                try { $src = New-Object System.Drawing.Bitmap($img) } finally { $img.Dispose() }
            }
        } finally { $ms.Dispose() }
        if ($null -eq $src) { return $null }
        $bmp = New-Object System.Drawing.Bitmap($size, $size, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.Clear([System.Drawing.Color]::Transparent)
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
            # Вписываем с сохранением пропорций.
            $ratio = [Math]::Min($size / [double]$src.Width, $size / [double]$src.Height)
            $dw = [Math]::Max(1, [int][Math]::Round($src.Width * $ratio))
            $dh = [Math]::Max(1, [int][Math]::Round($src.Height * $ratio))
            $g.DrawImage($src, [int](($size - $dw) / 2), [int](($size - $dh) / 2), $dw, $dh)
        } finally { $g.Dispose(); $src.Dispose() }
        return $bmp
    } catch { return $null }
}

# exe игры из папки, если в ярлыке стоит обёртка SCLauncher.exe: сначала --exe из параметров,
# затем .exe в корне папки (без служебных), затем общий подбор кандидатов карточки.
function Find-InstalledGameExeForIcon ([hashtable]$info) {
    try {
        $lo = [string]$info.LaunchOptions
        if ($lo -match '--exe\s+"([^"]+)"') {
            $cand = $Matches[1]
            if (Test-Path -LiteralPath $cand -PathType Leaf) { return $cand }
        }
        $dir = [string]$info.Dir
        if ($lo -match '--dir\s+"([^"]+)"') { $d2 = $Matches[1].TrimEnd('\'); if (Test-Path -LiteralPath $d2 -PathType Container) { $dir = $d2 } }
        if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { return $null }
        $junk = '(?i)unins|crash|redist|setup|install|updater|patcher|launcher|eac|battleye|dxweb|vcredist'
        $top = @(Get-ChildItem -LiteralPath $dir -Filter '*.exe' -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch $junk } | Sort-Object Length -Descending)
        if ($top.Count -gt 0) { return $top[0].FullName }
        $cands = @(Get-EditorExecutableCandidates $dir)
        if ($cands.Count -gt 0) { return [string]$cands[0].FullName }
    } catch {}
    return $null
}

# Значок строки добавленной игры (16x16) или $null, если нужно оставить папку. Результат кэшируется до Refresh-Panels.
function Get-InstalledGameRowIcon ([string]$rowPath, [int]$size = 16) {
    try {
        $k = Get-NormalizedGamePathKey $rowPath
        if (-not $k -or -not $global:installedGameIcons.ContainsKey($k)) { return $null }
        $ck = $k + '|' + $size
        if ($script:installedGameIconCache.ContainsKey($ck)) { return $script:installedGameIconCache[$ck] }
        $info = $global:installedGameIcons[$k]
        $bmp = $null
        if (-not [string]::IsNullOrWhiteSpace([string]$info.Icon)) {
            $bmp = Get-ImageFileIconBitmap ([string]$info.Icon) $size
        }
        if ($null -eq $bmp -and -not [bool]$info.IconOnly) {
            $exe = [string]$info.Exe
            $isWrapper = $false
            try { if ($exe -and ([System.IO.Path]::GetFileName($exe) -ieq 'SCLauncher.exe')) { $isWrapper = $true } } catch {}
            if ($isWrapper -or [string]::IsNullOrWhiteSpace($exe)) { $exe = Find-InstalledGameExeForIcon $info }
            if (-not [string]::IsNullOrWhiteSpace($exe)) { $bmp = Get-IconBitmapFromFile $exe $size }
        }
        $script:installedGameIconCache[$ck] = $bmp   # может быть $null — повторно не ищем
        return $bmp
    } catch { return $null }
}

# Значок типа файла/папки для ROM-режима (список библиотеки и поле ROM в
# карточке): папка, архив, образ диска, файл-описатель (cue/m3u...) или обычный
# файл. Рисуется кодом, квадрат ~16x14 с левым верхним углом ($x,$y). $bgColor —
# цвет фона строки (им закрашивается отверстие у диска).
function Draw-RomTypeIcon ($g, [int]$x, [int]$y, [string]$name, [bool]$isDir, $bgColor) {
    $ext = ''
    try { $ext = [System.IO.Path]::GetExtension($name).TrimStart('.').ToLowerInvariant() } catch {}
    $prevSm = $g.SmoothingMode
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    if ($isDir) {
        $fBack = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(214,163,54))
        $fFront = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(245,200,80))
        $g.FillRectangle($fBack, $x, $y, 7, 4)
        $g.FillRectangle($fBack, $x, $y + 2, 16, 12)
        $g.FillRectangle($fFront, $x, $y + 5, 16, 9)
        $fBack.Dispose(); $fFront.Dispose()
    } else {
        # Тип файла определяем по расширению: архив / образ диска /
        # файл-описатель (cue, m3u...) / прочее.
        if ($ext -in @('7z','zip','rar','gz','tar','xz','bz2','zst')) {
            # Архив: оранжевая коробка с «молнией» посередине.
            $arBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(224,138,58))
            $arDark = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(120,64,20))
            $arLight = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(250,225,190))
            $g.FillRectangle($arBrush, $x + 1, $y, 14, 14)
            for ($zy = 0; $zy -lt 14; $zy += 2) {
                $zb = if ((($zy / 2) % 2) -eq 0) { $arDark } else { $arLight }
                $g.FillRectangle($zb, $x + 6, $y + $zy, 4, 2)
            }
            $arBrush.Dispose(); $arDark.Dispose(); $arLight.Dispose()
        } elseif ($ext -in @('iso','img','chd','cso','pbp','mdf','ecm','cdi','gdi','rvz','wbfs','nrg','dvd')) {
            # Образ диска: голубой диск с отверстием.
            $dcBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(84,170,232))
            $dcShine = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(190,228,250))
            $dcHole = New-Object System.Drawing.SolidBrush($bgColor)
            $g.FillEllipse($dcBrush, $x + 1, $y, 14, 14)
            $g.FillEllipse($dcShine, $x + 3, $y + 2, 5, 3)
            $g.FillEllipse($dcHole, $x + 6, $y + 5, 4, 4)
            $dcBrush.Dispose(); $dcShine.Dispose(); $dcHole.Dispose()
        } elseif ($ext -in @('cue','m3u','m3u8','toc','ccd','mds','sub','txt','nfo','sbi')) {
            # Файл-описатель: зелёная страница со строками текста.
            $dsBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(150,214,164))
            $dsLine = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(40,100,60))
            $g.FillRectangle($dsBrush, $x + 2, $y, 12, 14)
            foreach ($ly in @(3, 6, 9)) { $g.FillRectangle($dsLine, $x + 4, $y + $ly, 8, 1) }
            $dsBrush.Dispose(); $dsLine.Dispose()
        } else {
            $pgBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(225,230,236))
            $pgFold = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(150,160,172))
            $pts = [System.Drawing.Point[]]@(
                (New-Object System.Drawing.Point(($x + 2), $y)),
                (New-Object System.Drawing.Point(($x + 9), $y)),
                (New-Object System.Drawing.Point(($x + 13), ($y + 4))),
                (New-Object System.Drawing.Point(($x + 13), ($y + 14))),
                (New-Object System.Drawing.Point(($x + 2), ($y + 14))))
            $g.FillPolygon($pgBrush, $pts)
            $foldPts = [System.Drawing.Point[]]@(
                (New-Object System.Drawing.Point(($x + 9), $y)),
                (New-Object System.Drawing.Point(($x + 13), ($y + 4))),
                (New-Object System.Drawing.Point(($x + 9), ($y + 4))))
            $g.FillPolygon($pgFold, $foldPts)
            $pgBrush.Dispose(); $pgFold.Dispose()
        }
    }
    $g.SmoothingMode = $prevSm
}

function Register-ListBoxDrawEvent ($listBox) {
    $listBox.Add_DrawItem({
        param([object]$sender, [System.Windows.Forms.DrawItemEventArgs]$e)
        if ($e.Index -lt 0) { return }
        
        $itemText = $sender.Items[$e.Index].ToString()
        $cleanName = Clean-GameName $itemText
        $src = [string]$sender.Tag
        # Признак "в библиотеке" определяется по реальному пути папки (см.
        # Get-NormalizedGamePathKey), а не просто по совпадению названия —
        # иначе папка с тем же именем, что и уже добавленная игра, но лежащая
        # в другом месте, ошибочно получала бы зелёную галочку.
        $rootForRow = if ($src -eq 'C') { $global:dirC } else { $global:dirD }
        $rowPath = if ([string]::IsNullOrWhiteSpace($rootForRow)) { $null } else { Join-Path $rootForRow $cleanName }
        $isInstalled = if ($rowPath) { $global:installedSteamGames.ContainsKey((Get-NormalizedGamePathKey $rowPath)) } else { $false }
        $checkedSet = Get-CheckedSet $src
        $isChecked = $checkedSet.ContainsKey($cleanName)
        $isSelected = $e.State.HasFlag([System.Windows.Forms.DrawItemState]::Selected)
        
        if ($isSelected) {
            $rowBrush = New-Object System.Drawing.SolidBrush($steamUi.Selected)
            $e.Graphics.FillRectangle($rowBrush, $e.Bounds)
            $rowBrush.Dispose()
            $brush = New-Object System.Drawing.SolidBrush($steamUi.Text)
        } else {
            # Строки оформлены как в самом Steam: только едва заметное чередование
            # двух тёмных оттенков, одинаковое для всех строк вне зависимости от
            # статуса. Статус "в библиотеке" показывает исключительно зелёная
            # подпись-галочка в своей колонке — без изменения фона.
            $rowBg = if (($e.Index % 2) -eq 0) { $steamUi.Panel2 } else { $steamUi.Panel }
            $rowBrush = New-Object System.Drawing.SolidBrush($rowBg)
            $e.Graphics.FillRectangle($rowBrush, $e.Bounds)
            $rowBrush.Dispose()
            $brush = New-Object System.Drawing.SolidBrush($steamUi.Text)
        }

        # Галочка выбора для пакетных операций (перенос / добавление нескольких).
        # Отдельно от клика по самой строке — тот только выделяет строку, а не
        # открывает карточку (см. Invoke-GamePanelClick / Invoke-GamePanelDoubleClick).
        $cbRect = Get-RowCheckboxRect $e.Bounds
        if ($isChecked) {
            $cbBg = New-Object System.Drawing.SolidBrush($steamUi.Accent)
            $e.Graphics.FillRectangle($cbBg, $cbRect)
            $cbBg.Dispose()
            $checkPen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 1.6)
            $e.Graphics.DrawLine($checkPen, $cbRect.X + 3, $cbRect.Y + 7, $cbRect.X + 6, $cbRect.Y + 10)
            $e.Graphics.DrawLine($checkPen, $cbRect.X + 6, $cbRect.Y + 10, $cbRect.X + 11, $cbRect.Y + 3)
            $checkPen.Dispose()
        } else {
            $cbBorderColor = if ($isSelected) { [System.Drawing.Color]::White } else { $steamUi.Muted }
            $cbPen = New-Object System.Drawing.Pen($cbBorderColor, 1.2)
            $e.Graphics.DrawRectangle($cbPen, $cbRect)
            $cbPen.Dispose()
        }

        # ===== Колонки: Имя | Размер | Дата | В библиотеке =====
        # Границы берутся из $script:colWidths (их двигает пользователь мышкой в
        # заголовке — см. New-SortHeaderRow), поэтому каждое значение рисуется
        # строго в своей колонке и под своим заголовком. Текст в колонке обрезается
        # многоточием и никогда не залезает в соседнюю.
        $w = $script:colWidths[$src]
        if ($w -eq $null) { $w = @(238, 80, 85, 36) }
        $colX0 = $e.Bounds.X
        $colX1 = $colX0 + [int]$w[0]
        $colX2 = $colX1 + [int]$w[1]
        $colX3 = $colX2 + [int]$w[2]
        $sf = New-Object System.Drawing.StringFormat
        $sf.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter
        $sf.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap
        $mutedColor = if ($isSelected) { [System.Drawing.Color]::FromArgb(225,225,225) } else { $steamUi.Muted }

        # Имя (текст начинается правее галочки — на тех же 30 px, что и заголовок "Имя").
        # ROM-режим: слева от имени рисуем значок — папка (жёлтая) или файл (светлая
        # страница с загнутым уголком), иначе в общем списке их не отличить.
        $nameShift = 0
        if ($rowPath) {
            $nameShift = 24
            $icoX = $colX0 + 30
            $icoY = $e.Bounds.Y + [int](($e.Bounds.Height - 16) / 2)
            $rowBgColor = if ($isSelected) { $steamUi.Selected } else { if (($e.Index % 2) -eq 0) { $steamUi.Panel2 } else { $steamUi.Panel } }
            $isDirIcon = $true
            $extLow = ''
            try {
                if (Test-Path -LiteralPath $rowPath -PathType Leaf) {
                    $isDirIcon = $false
                    $extLow = [System.IO.Path]::GetExtension($rowPath).TrimStart('.').ToLowerInvariant()
                } elseif (Test-Path -LiteralPath $rowPath -PathType Container) {
                    $isDirIcon = $true
                } else {
                    $extLow = [System.IO.Path]::GetExtension([string]$itemText).TrimStart('.').ToLowerInvariant()
                    $isDirIcon = [string]::IsNullOrWhiteSpace($extLow)
                }
            } catch {}
            # .exe / .lnk / .bat / .cmd / .com — собственная иконка файла, не общая заглушка.
            $drewNative = $false
            if (-not $isDirIcon -and $extLow -in @('exe','lnk','bat','cmd','com')) {
                try {
                    $nativeIco = Get-PanelFileIconBitmap $rowPath 16
                    if ($null -ne $nativeIco) {
                        $e.Graphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                        $e.Graphics.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceOver
                        $e.Graphics.DrawImage($nativeIco, $icoX, $icoY, 16, 16)
                        $drewNative = $true
                    }
                } catch {}
            }
            # Игра уже добавлена в Steam: вместо папки — выбранная иконка, а если её нет — значок exe.
            if (-not $drewNative -and $isInstalled) {
                try {
                    $gameIco = Get-InstalledGameRowIcon $rowPath 16
                    if ($null -ne $gameIco) {
                        $e.Graphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                        $e.Graphics.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceOver
                        $e.Graphics.DrawImage($gameIco, $icoX, $icoY, 16, 16)
                        $drewNative = $true
                    }
                } catch {}
            }
            if (-not $drewNative) {
                Draw-RomTypeIcon $e.Graphics $icoX $icoY $(if ($isDirIcon) { $rowPath } else { [string]$itemText }) $isDirIcon $rowBgColor
            }
        }
        $nameRect = New-Object System.Drawing.RectangleF(($colX0 + 30 + $nameShift), ($e.Bounds.Y + 4), [Math]::Max(1, [int]$w[0] - 36 - $nameShift), 21)
        $e.Graphics.DrawString($itemText, $e.Font, $brush, $nameRect, $sf)
        $brush.Dispose()

        $smallFont = New-Object System.Drawing.Font("Segoe UI", 8)

        # Размер — посчитанный размер папки (Пробел / Alt+Shift+Enter / сортировка
        # "по размеру" кладут результат в общий $global:folderSizeCache).
        $cachedSizeBytes = if ($rowPath) { Get-FolderSizeCached $rowPath } else { -1 }
        if ($cachedSizeBytes -ge 0) {
            # Меньше гигабайта показываем в мегабайтах (целым числом), от гигабайта — в ГБ.
            $sizeMb = [Math]::Round($cachedSizeBytes / 1MB, 0)
            if ($cachedSizeBytes -lt 1GB -and $sizeMb -lt 1024) {
                $sizeText = $sizeMb.ToString([System.Globalization.CultureInfo]::InvariantCulture) + " " + (T 'unit_mb')
            } else {
                $sizeText = ([Math]::Round($cachedSizeBytes / 1GB, 2)).ToString([System.Globalization.CultureInfo]::InvariantCulture) + " " + (T 'unit_gb')
            }
            $sizeBrush = New-Object System.Drawing.SolidBrush($mutedColor)
            $sizeRect = New-Object System.Drawing.RectangleF(($colX1 + 8), ($e.Bounds.Y + 5), [Math]::Max(1, [int]$w[1] - 12), 20)
            $e.Graphics.DrawString($sizeText, $smallFont, $sizeBrush, $sizeRect, $sf)
            $sizeBrush.Dispose()
        }

        # Дата — дата изменения папки (та же, по которой работает сортировка "Дата").
        $dateMap = if ($src -eq 'C') { $script:panelDateMapC } else { $script:panelDateMapD }
        if ($dateMap -ne $null -and $dateMap.ContainsKey($cleanName)) {
            $dateText = ([datetime]$dateMap[$cleanName]).ToString('dd.MM.yyyy', [System.Globalization.CultureInfo]::InvariantCulture)
            $dateBrush = New-Object System.Drawing.SolidBrush($mutedColor)
            $dateRect = New-Object System.Drawing.RectangleF(($colX2 + 8), ($e.Bounds.Y + 5), [Math]::Max(1, [int]$w[2] - 12), 20)
            $e.Graphics.DrawString($dateText, $smallFont, $dateBrush, $dateRect, $sf)
            $dateBrush.Dispose()
        }
        $smallFont.Dispose()

        # В библиотеке — зелёная подпись-галочка; видна и на выделенной строке
        # (на синем фоне берём чуть более яркий зелёный, чтобы не сливалась).
        if ($isInstalled) {
            $badgeFont = New-Object System.Drawing.Font("Segoe UI Semibold", 8)
            $badgeColor = if ($isSelected) { [System.Drawing.Color]::FromArgb(128,214,150) } else { $steamUi.Green }
            $badgeBrush = New-Object System.Drawing.SolidBrush($badgeColor)
            $badgeRect = New-Object System.Drawing.RectangleF(($colX3 + 8), ($e.Bounds.Y + 5), [Math]::Max(1, [int]$w[3] - 10), 20)
            $e.Graphics.DrawString("✓", $badgeFont, $badgeBrush, $badgeRect, $sf)
            $badgeBrush.Dispose()
            $badgeFont.Dispose()
        }
        $sf.Dispose()
        $e.DrawFocusRectangle()
    })
}
function Get-SteamShortcutID ($exePath, $gameName) {
    $inputString = "`"$exePath`"$gameName"
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($inputString)

    # ВАЖНО: PowerShell парсит 8-значные HEX-литералы (0xffffffff, 0xedb88320,
    # 0x80000000) как ЗНАКОВЫЙ Int32 — например 0xffffffff превращается в -1,
    # а не в 4294967295. А оператор -shr на отрицательных (знаковых) числах
    # делает АРИФМЕТИЧЕСКИЙ сдвиг (протягивает единицы слева), а не логический
    # (заполнение нулями), который нужен для правильного CRC32. Из-за этого
    # расчёт "портился" знаковым битом, и на выходе иногда получалось
    # отрицательное число — которое затем не мог принять [uint32] при вызове
    # этой функции, и добавление ярлыка падало с ошибкой преобразования типа.
    # Фикс: работаем строго в типе [uint32] (для него -shr гарантированно
    # логический), а константы, которые как HEX стали бы отрицательными,
    # задаём десятичным числом — так они парсятся как положительные и не
    # "переинтерпретируются" в 32-битный знаковый вид.
    [uint32]$allOnes = 4294967295          # было бы 0xffffffff
    [uint32]$poly    = 3988292384          # было бы 0xedb88320
    [uint32]$topBit  = 2147483648          # было бы 0x80000000

    [uint32]$crc = $allOnes
    foreach ($b in $bytes) {
        $crc = $crc -bxor [uint32]$b
        for ($i = 0; $i -lt 8; $i++) {
            if (($crc -band 1) -ne 0) { $crc = ($crc -shr 1) -bxor $poly } else { $crc = $crc -shr 1 }
        }
    }
    [uint32]$hash = $crc -bxor $allOnes

    # Именно это 32-битное число Steam использует как ID для файлов обложек в config\grid\
    [uint32]$topPart = $hash -bor $topBit
    return [string]$topPart
}
# ===================== НАСТОЯЩИЙ ПАРСЕР БИНАРНОГО VDF =====================
# Раньше вставка новой записи в shortcuts.vdf делалась "на глаз": просто
# отрезались последние 1-2 байта 0x08 в конце файла, а поиск свободного
# индекса делался сканированием ВСЕХ байт файла на "похоже на цифры между
# нулями". Это работало только пока хвост файла случайно совпадал с
# предположением автора. Стоило структуре отличаться (другой набор полей
# у существующих ярлыков, файл уже был чуть повреждён предыдущим запуском
# и т.п.) — вставка попадала не в то место, файл ломался, и Steam либо не
# видел новый ярлык, либо падал при чтении битого shortcuts.vdf.
#
# Вместо этого здесь честно разбирается вложенность объектов VDF
# (тип 0x00 = вложенный объект, 0x01 = строка, 0x02 = int32, 0x08 = конец
# объекта) и новая запись вставляется РОВНО перед байтом 0x08, закрывающим
# объект "shortcuts" — независимо от того, что и как записано у уже
# существующих ярлыков.
function Read-VdfObjectBody ($bytes, $pos) {
    $children = New-Object System.Collections.Generic.List[object]
    while ($true) {
        if ($pos -ge $bytes.Length) { throw (T 'vdf_eof') }
        $type = $bytes[$pos]
        if ($type -eq 0x08) {
            return [PSCustomObject]@{ Children = $children; EndPos = $pos; NextPos = ($pos + 1) }
        }
        $pos++
        $keyStart = $pos
        while ($pos -lt $bytes.Length -and $bytes[$pos] -ne 0x00) { $pos++ }
        if ($pos -ge $bytes.Length) { throw (T 'vdf_eof_key') }
        $key = [System.Text.Encoding]::UTF8.GetString($bytes, $keyStart, $pos - $keyStart)
        $pos++
        switch ($type) {
            0x00 {
                $sub = Read-VdfObjectBody $bytes $pos
                $children.Add([PSCustomObject]@{ Key = $key; Type = 0x00; Body = $sub })
                $pos = $sub.NextPos
            }
            0x01 {
                $valStart = $pos
                while ($pos -lt $bytes.Length -and $bytes[$pos] -ne 0x00) { $pos++ }
                if ($pos -ge $bytes.Length) { throw (T 'vdf_eof_str') }
                $val = [System.Text.Encoding]::UTF8.GetString($bytes, $valStart, $pos - $valStart)
                $pos++
                $children.Add([PSCustomObject]@{ Key = $key; Type = 0x01; Value = $val })
            }
            0x02 {
                if ($pos + 4 -gt $bytes.Length) { throw (T 'vdf_eof_int') }
                $val = [BitConverter]::ToUInt32($bytes, $pos)
                $pos += 4
                $children.Add([PSCustomObject]@{ Key = $key; Type = 0x02; Value = $val })
            }
            default { throw (T 'vdf_bad_field' @($type.ToString('X2'), $pos)) }
        }
    }
}

# Находит объект "shortcuts" внутри разобранного корня файла.
function Get-ShortcutsNode ($bytes) {
    $root = Read-VdfObjectBody $bytes 0
    return ($root.Children | Where-Object { $_.Key -eq "shortcuts" } | Select-Object -First 1)
}

$global:exeDir = [System.AppDomain]::CurrentDomain.BaseDirectory
# Конфигурация пользователя — в %APPDATA%, а не рядом с EXE.
$global:configPath = Join-Path $global:appDataDir "config.ini"

# Папка для резервных копий shortcuts.vdf. Пусто = %AppData%\Steam Commander\backup
# (рядом с config.ini и прочими настройками программы). Пользователь может
# выбрать свою папку через кнопку «Обзор» в настройках.
$global:backupFolderPath = ""

function Get-BackupFolderPath {
    if (-not [string]::IsNullOrWhiteSpace([string]$global:backupFolderPath)) {
        return [string]$global:backupFolderPath
    }
    return (Join-Path $global:appDataDir "backup")
}

# Настройки Steam: путь установки и конкретный профиль userdata.
$global:steamInstallPath = ""
$global:steamUserId = ""

function Get-DefaultSteamInstallPath {
    try {
        $steamPath = (Get-ItemProperty -Path "HKCU:\Software\Valve\Steam" -Name "SteamPath" -ErrorAction SilentlyContinue).SteamPath
        if (-not [string]::IsNullOrWhiteSpace([string]$steamPath) -and (Test-Path -LiteralPath [string]$steamPath)) {
            return [System.IO.Path]::GetFullPath([string]$steamPath)
        }
    } catch {}
    try {
        $steamExe = (Get-ItemProperty -Path "HKCU:\Software\Valve\Steam" -Name "SteamExe" -ErrorAction SilentlyContinue).SteamExe
        if (-not [string]::IsNullOrWhiteSpace([string]$steamExe)) {
            $steamDir = [System.IO.Path]::GetDirectoryName([string]$steamExe)
            if (-not [string]::IsNullOrWhiteSpace($steamDir)) { return [System.IO.Path]::GetFullPath($steamDir) }
        }
    } catch {}
    return "C:\Program Files (x86)\Steam"
}

function Get-ConfiguredSteamInstallPath {
    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$global:steamInstallPath)) {
            return [System.IO.Path]::GetFullPath([string]$global:steamInstallPath)
        }
    } catch {}
    return Get-DefaultSteamInstallPath
}

function Get-ConfiguredSteamExePath {
    try {
        $root = Get-ConfiguredSteamInstallPath
        $candidate = Join-Path $root 'steam.exe'
        if (Test-Path -LiteralPath $candidate) { return [string]$candidate }
    } catch {}
    return 'steam.exe'
}

function Get-ConfiguredSteamUserDataPath {
    $root = Get-ConfiguredSteamInstallPath
    $userDataRoot = Join-Path $root 'userdata'
    try {
        $userId = [string]$global:steamUserId
        if (-not [string]::IsNullOrWhiteSpace($userId) -and $userId -match '^\d+$') {
            $profilePath = Join-Path $userDataRoot $userId
            if (Test-Path -LiteralPath $profilePath) { return [string]$profilePath }
        }
    } catch {}
    return [string]$userDataRoot
}

function Get-ConfiguredSteamProfileDirectories {
    try {
        $userDataRoot = Join-Path (Get-ConfiguredSteamInstallPath) 'userdata'
        if (-not (Test-Path -LiteralPath $userDataRoot)) { return @() }

        $userId = [string]$global:steamUserId
        if (-not [string]::IsNullOrWhiteSpace($userId) -and $userId -match '^\d+$') {
            $selected = Join-Path $userDataRoot $userId
            if (Test-Path -LiteralPath $selected) {
                return @([System.IO.DirectoryInfo]$selected)
            }
            return @()
        }

        return @(Get-ChildItem -LiteralPath $userDataRoot -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match '^\d+$' })
    } catch {
        return @()
    }
}

# Используется и при автозапуске (решение — открывать ли окно настроек сразу),
# и в самом окне настроек (чтобы показать красный значок рядом с полем).
function Test-ConfiguredSteamPathValid {
    try {
        $path = [string]$global:steamInstallPath
        if ([string]::IsNullOrWhiteSpace($path)) { return $false }
        if (-not (Test-Path -LiteralPath $path -PathType Container)) { return $false }
        $exeCandidate = Join-Path $path 'steam.exe'
        return (Test-Path -LiteralPath $exeCandidate -PathType Leaf)
    } catch { return $false }
}

function Test-ConfiguredSteamProfileValid {
    try {
        $userId = [string]$global:steamUserId
        if ([string]::IsNullOrWhiteSpace($userId) -or $userId -notmatch '^\d+$') { return $false }
        $userDataRoot = Join-Path (Get-ConfiguredSteamInstallPath) 'userdata'
        $profilePath = Join-Path $userDataRoot $userId
        if (-not (Test-Path -LiteralPath $profilePath -PathType Container)) { return $false }
        # Папка существует, но это ещё не значит, что это настоящий аккаунт
        # Steam: подложенная вручную папка с произвольным числом (например,
        # созданная вручную "345345") тоже пройдёт Test-Path. Настоящий профиль
        # обязан иметь запись в loginusers.vdf — см. Get-SteamUserProfiles.
        $matched = @(Get-SteamUserProfiles) | Where-Object { [string]::Equals([string]$_.Id, $userId, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1
        if ($null -eq $matched) { return $false }
        return [bool]$matched.IsKnownAccount
    } catch { return $false }
}

function Get-SteamUserProfiles {
    $result = New-Object System.Collections.ArrayList
    try {
        $steamRoot = Get-ConfiguredSteamInstallPath
        $userDataRoot = Join-Path $steamRoot 'userdata'
        if (-not (Test-Path -LiteralPath $userDataRoot)) { return @($result) }

        $loginUsersPath = Join-Path $steamRoot 'config\loginusers.vdf'
        $loginText = ""
        try {
            if (Test-Path -LiteralPath $loginUsersPath) {
                $loginText = Get-Content -LiteralPath $loginUsersPath -Raw -ErrorAction SilentlyContinue
            }
        } catch {}

        foreach ($dir in @(Get-ChildItem -LiteralPath $userDataRoot -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^\d+$' })) {
            $id = [string]$dir.Name
            $persona = ""
            $account = ""
            $mostRecent = $false
            # Совпадение с реальной записью в loginusers.vdf — это и есть признак
            # того, что папка действительно принадлежит аккаунту Steam, который
            # когда-либо логинился на этом компьютере. Подсунутая вручную папка
            # с произвольным числом (см. отчёт пользователя: папка "345345")
            # проходит все прежние проверки (существует, имя из цифр), но такой
            # записи в loginusers.vdf нет — это и отличает настоящий профиль от
            # подделки.
            $isKnownAccount = $false

            if (-not [string]::IsNullOrWhiteSpace($loginText)) {
                try {
                    # Папка userdata названа по 32-битному AccountID, а ключи в
                    # loginusers.vdf — это полные 64-битные SteamID64. Раньше
                    # регэксп сравнивал их напрямую, поэтому НИКОГДА не совпадал
                    # и PersonaName не находился. Переводим AccountID в SteamID64,
                    # прибавляя базовое смещение индивидуальных аккаунтов Steam.
                    $steamId64 = [uint64]$id + [uint64]76561197960265728
                    $escapedId = [regex]::Escape([string]$steamId64)
                    $startMatch = [regex]::Match($loginText, '"' + $escapedId + '"\s*\{')
                    if ($startMatch.Success) {
                        $isKnownAccount = $true
                        $tail = $loginText.Substring($startMatch.Index)
                        $block = $tail.Substring(0, [Math]::Min(5000, $tail.Length))
                        $pm = [regex]::Match($block, '"PersonaName"\s*"([^"]*)"')
                        if ($pm.Success) { $persona = [string]$pm.Groups[1].Value }
                        $am = [regex]::Match($block, '"AccountName"\s*"([^"]*)"')
                        if ($am.Success) { $account = [string]$am.Groups[1].Value }
                        if ($block -match '"MostRecent"\s*"1"') { $mostRecent = $true }
                    }
                } catch {}
            }

            $displayName = $id
            if (-not [string]::IsNullOrWhiteSpace($persona)) {
                $displayName = $id + "  (" + $persona + ")"
            } elseif (-not [string]::IsNullOrWhiteSpace($account)) {
                $displayName = $id + "  (" + $account + ")"
            } elseif (-not $isKnownAccount) {
                $displayName = $id + "  (" + (T 'set_profile_unknown_short') + ")"
            }

            [void]$result.Add([PSCustomObject]@{
                Id = $id
                Name = $persona
                AccountName = $account
                DisplayName = $displayName
                Directory = $dir
                MostRecent = $mostRecent
                IsKnownAccount = $isKnownAccount
            })
        }

        return @($result | Sort-Object @{Expression='MostRecent';Descending=$true}, @{Expression='DisplayName';Descending=$false})
    } catch {
        return @($result)
    }
}

function Load-Configuration {
    # Список эмуляторов для режима ROMs: Id (внутренний, для ссылок), Name
    # (отображаемое имя), ExePath (путь к exe эмулятора), Args (шаблон
    # аргументов запуска; {rom} — куда подставить путь к файлу рома, если
    # плейсхолдер не указан — путь просто дописывается в конец), Extensions
    # (через запятую, без точек, например "sfc,smc,fig"), Core (ядро RetroArch),
    # ExtractArchives (bool, по умолчанию $false: распаковывать архивы с ROM во
    # временную папку перед запуском; в старых профилях поля нет - читается как $false).
    $global:emulatorProfiles = @()
    # Id эмулятора из списка выше, который сейчас активен в режиме ROMs.
    $global:activeEmulatorId = ''
    if (Test-Path $global:configPath) {
        try {
            $lines = Get-Content $global:configPath -ErrorAction SilentlyContinue
            foreach ($line in $lines) {
                if ($line.StartsWith("dirC=")) { $global:dirC = $line.Substring(5).Trim() }
                if ($line.StartsWith("dirD=")) { $global:dirD = $line.Substring(5).Trim() }
                if ($line.StartsWith("steamInstallPath=")) { $global:steamInstallPath = $line.Substring(17).Trim() }
                if ($line.StartsWith("steamUserId=")) { $global:steamUserId = $line.Substring(12).Trim() }
                if ($line.StartsWith("emulatorProfiles=")) {
                    try {
                        $rawEmu = $line.Substring("emulatorProfiles=".Length).Trim()
                        if (-not [string]::IsNullOrWhiteSpace($rawEmu)) {
                            $parsedEmu = $rawEmu | ConvertFrom-Json -ErrorAction Stop
                            if ($parsedEmu -isnot [array]) { $parsedEmu = @($parsedEmu) }
                            $global:emulatorProfiles = @($parsedEmu | ForEach-Object {
                                @{ Id = [string]$_.Id; Name = [string]$_.Name; ExePath = [string]$_.ExePath; Args = [string]$_.Args; Extensions = [string]$_.Extensions; Core = [string]$_.Core; ExtractArchives = (([string]$_.ExtractArchives).Trim().ToLowerInvariant() -eq 'true') }
                            })
                        }
                    } catch {}
                }
                if ($line.StartsWith("activeEmulatorId=")) { $global:activeEmulatorId = $line.Substring("activeEmulatorId=".Length).Trim() }
                # БАГ-ФИКС: "steamGridDbApiKey=" — это РОВНО 18 символов, а здесь
                # стоял Substring(19) — при каждой загрузке config.ini у ключа
                # обрезался первый символ, ключ становился невалидным, и
                # SteamGridDB закономерно отвечал 401 Unauthorized даже с
                # правильно введённым и сохранённым ключом.
                if ($line.StartsWith("steamGridDbApiKey=")) { $global:steamGridDbApiKey = $line.Substring(18).Trim() }
                if ($line.StartsWith("suggestGameLaunchers=")) { $global:suggestGameLaunchers = ([string]$line.Substring(21).Trim()).ToLowerInvariant() -eq "true" }
                if ($line.StartsWith("useExeIcons=")) { $global:useExeIcons = ([string]$line.Substring(12).Trim()).ToLowerInvariant() -eq "true" }
                if ($line.StartsWith("logoDefaultEnabled=")) { $global:logoDefaultEnabled = ([string]$line.Substring("logoDefaultEnabled=".Length).Trim()).ToLowerInvariant() -eq "true" }
                if ($line.StartsWith("logoDefaultPosition=")) { $global:logoDefaultPosition = [string]$line.Substring("logoDefaultPosition=".Length).Trim() }
                if ($line.StartsWith("logoDefaultWidthPct=")) {
                    $ldw = 0.0
                    if ([double]::TryParse([string]$line.Substring("logoDefaultWidthPct=".Length).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$ldw)) { $global:logoDefaultWidthPct = $ldw }
                }
                if ($line.StartsWith("logoDefaultHeightPct=")) {
                    $ldh = 0.0
                    if ([double]::TryParse([string]$line.Substring("logoDefaultHeightPct=".Length).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$ldh)) { $global:logoDefaultHeightPct = $ldh }
                }
                if ($line.StartsWith("steamApiKey=")) { $global:steamApiKey = $line.Substring(12).Trim() }
                if ($line.StartsWith("backupFolderPath=")) { $global:backupFolderPath = $line.Substring(17).Trim() }
                if ($line.StartsWith("language=")) { $global:language = $line.Substring(9).Trim() }
                if ($line.StartsWith("steamCoverRegion=")) { $global:steamCoverRegion = $line.Substring(17).Trim() }
            }
        } catch {}
    }
}
try { [void](Initialize-Localization) } catch {}
Load-Configuration
# Язык не выбран (первый запуск) или в config.ini неизвестное значение — берём язык
# интерфейса Windows, если он есть в таблице, иначе английский.
if (-not $script:I18n.ContainsKey([string]$global:language)) {
    $uiLang = 'en'
    try { $uiLang = [System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName } catch {}
    $global:language = if ($script:I18n.ContainsKey($uiLang)) { $uiLang } else { 'en' }
}

# Результат проверки ключа SteamGridDB: не просто "да/нет", а причина, которую
# можно показать пользователю (см. подпись под полем ключа в «Настройках»).
#   Kind     — valid | invalid | forbidden | ratelimit | server | network | other | empty
#   Severity — ok | error | warn | none  (warn = ключ не признан плохим, сервис
#              просто не смог ответить; error = проблема с ключом или доступом)
# Текст сообщения НЕ запоминается готовой строкой: хранится ключ перевода и его
# аргументы, а Message вычисляется через T при каждом обращении. Поэтому после
# смены языка подпись под полем ключа переводится сразу, без перезапуска.
function New-SgdbKeyCheckResult($valid, [string]$kind, [string]$severity, [int]$status, [string]$msgKey, [object[]]$msgArgs = @()) {
    $res = [PSCustomObject]@{
        Valid        = [bool]$valid
        Kind         = $kind
        Severity     = $severity
        StatusCode   = $status
        MsgKey       = $msgKey
        MsgArgs      = @($msgArgs)
        NetworkError = ($kind -eq 'network' -or $kind -eq 'server' -or $kind -eq 'ratelimit')
    }
    Add-Member -InputObject $res -MemberType ScriptProperty -Name Message -Value { T ([string]$this.MsgKey) ([object[]]$this.MsgArgs) }
    return $res
}

# Сама сетевая проверка ключа SteamGridDB вынесена в самодостаточный
# scriptblock: он не обращается ни к функциям, ни к переменным программы и
# возвращает только простые данные — поэтому его можно выполнять и напрямую
# (проверка после ввода ключа в «Настройках»), и в фоновом runspace (проверка
# при запуске, чтобы не задерживать открытие программы на время сетевого
# таймаута). $maxAttempts > 1 — повторить запрос при сетевом сбое/5xx/429;
# 401/403 — окончательный ответ, повторять не нужно.
$script:SgdbKeyRawCheck = {
    param($apiKey, [int]$maxAttempts = 1)
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

    $r = @{ Ok = $false; StatusCode = 0; WebStatus = ''; RawMsg = '' }
    for ($attempt = 1; $attempt -le [Math]::Max(1, $maxAttempts); $attempt++) {
        $r = @{ Ok = $false; StatusCode = 0; WebStatus = ''; RawMsg = '' }
        try {
            $headers = @{ Authorization = "Bearer $(([string]$apiKey).Trim())" }
            $url = 'https://www.steamgriddb.com/api/v2/search/autocomplete/__steam_commander_key_check__'
            $resp = Invoke-RestMethod -Uri $url -Headers $headers -UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) SteamCommander' -TimeoutSec 15 -ErrorAction Stop
            # ВАЖНО: SteamGridDB на этот эндпоинт может вернуть HTTP 200 с телом
            # {"success": false, ...} даже для неверного/испорченного ключа — то есть
            # исключения не будет. Раньше тело ответа полностью отбрасывалось
            # (Out-Null), и ключ засчитывался валидным просто потому, что сервер не
            # ответил кодом ошибки. Поэтому дополнительно проверяем поле success.
            if ($resp -and ($resp.PSObject.Properties.Name -contains 'success') -and -not [bool]$resp.success) {
                $r.StatusCode = 401
                $r.WebStatus = 'ProtocolError'
                $r.RawMsg = 'success:false'
            } else {
                $r.Ok = $true
                break
            }
        } catch {
            $ex = $_.Exception
            try { $r.StatusCode = [int]$ex.Response.StatusCode.value__ } catch {}
            try { $r.WebStatus = [string]$ex.Status } catch {}
            try { $r.RawMsg = [string]$ex.Message } catch {}
        }
        if (-not ($r.StatusCode -eq 0 -or $r.StatusCode -ge 500 -or $r.StatusCode -eq 429)) { break }
        # Пауза перед повтором: мгновенный повтор при сбое/429 почти всегда падает так же.
        if ($attempt -lt $maxAttempts) { Start-Sleep -Milliseconds (1500 * $attempt) }
    }
    return $r
}

# Превращает "сырой" результат запроса в объект проверки (Valid/Kind/Severity/Message).
function ConvertTo-SgdbKeyCheckResult($raw) {
    if ($raw.Ok) { return (New-SgdbKeyCheckResult $true 'valid' 'ok' 200 'key_valid') }

    $statusCode = 0; try { $statusCode = [int]$raw.StatusCode } catch {}
    $webStatus = [string]$raw.WebStatus
    $rawMsg = [string]$raw.RawMsg

    if ($statusCode -eq 401) { return (New-SgdbKeyCheckResult $false 'invalid' 'error' 401 'sg_401') }
    if ($statusCode -eq 403) { return (New-SgdbKeyCheckResult $false 'forbidden' 'error' 403 'sg_403') }
    if ($statusCode -eq 429) { return (New-SgdbKeyCheckResult $false 'ratelimit' 'warn' 429 'sg_429') }
    if ($statusCode -ge 500) { return (New-SgdbKeyCheckResult $false 'server' 'warn' $statusCode 'sg_server' @($statusCode)) }
    if ($statusCode -gt 0)   { return (New-SgdbKeyCheckResult $false 'other' 'error' $statusCode 'sg_other' @($statusCode)) }

    # Ответа от сервера нет вовсе — уточняем причину по типу сетевой ошибки.
    $msgArgs = @()
    if ($webStatus -match 'NameResolutionFailure') {
        $msg = 'sg_dns'
    } elseif ($webStatus -eq 'Timeout') {
        $msg = 'sg_timeout'
    } elseif ($webStatus -match 'SecureChannelFailure|TrustFailure' -or $rawMsg -match 'SSL/TLS') {
        $msg = 'sg_tls'
    } elseif ($webStatus -match 'ConnectFailure|ConnectionClosed|SendFailure|ReceiveFailure') {
        $msg = 'sg_connect'
    } else {
        if ($rawMsg.Length -gt 100) { $rawMsg = $rawMsg.Substring(0, 100) + '…' }
        $msg = 'sg_noresp'; $msgArgs = @($rawMsg)
    }
    return (New-SgdbKeyCheckResult $false 'network' 'warn' 0 $msg $msgArgs)
}

# Синхронная проверка (для «Настроек»: пользователь ввёл ключ и ждёт ответа).
function Get-SgdbKeyCheckResult([string]$apiKey) {
    if ([string]::IsNullOrWhiteSpace($apiKey)) {
        return (New-SgdbKeyCheckResult $false 'empty' 'none' 0 'key_empty')
    }
    $raw = & $script:SgdbKeyRawCheck $apiKey 2
    return (ConvertTo-SgdbKeyCheckResult $raw)
}


# ------------------- Steam Web API ключ (для локальной базы игр) -------------------
# Отдельная от SteamGridDB проверка: свой ключ, свой статус, своя причина
# отказа — используется только для скачивания списка приложений Steam.
function Get-SteamApiKeyCheckResult([string]$apiKey) {
    if ([string]::IsNullOrWhiteSpace($apiKey)) {
        return (New-SgdbKeyCheckResult $false 'empty' 'none' 0 'key_empty')
    }
    $raw = & $script:SteamKeyRawCheck $apiKey
    return (ConvertTo-SteamKeyCheckResult $raw)
}

# Как и у SteamGridDB — самодостаточный scriptblock, пригодный для фонового runspace.
$script:SteamKeyRawCheck = {
    param($apiKey)
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

    $r = @{ Ok = $false; NoData = $false; StatusCode = 0; WebStatus = ''; RawMsg = '' }
    try {
        # Известный публичный SteamID64 (Gabe Newell) — используется ТОЛЬКО чтобы
        # проверить, принимает ли Steam ключ (запрос требует авторизации ключом).
        $url = "https://api.steampowered.com/ISteamUser/GetPlayerSummaries/v0002/?key=$(([string]$apiKey).Trim())&steamids=76561197960435530"
        $resp = Invoke-RestMethod -Uri $url -TimeoutSec 10 -ErrorAction Stop
        if ($resp -and $resp.response) { $r.Ok = $true } else { $r.NoData = $true }
    } catch {
        $ex = $_.Exception
        try { $r.StatusCode = [int]$ex.Response.StatusCode.value__ } catch {}
        try { $r.WebStatus = [string]$ex.Status } catch {}
        try { $r.RawMsg = [string]$ex.Message } catch {}
    }
    return $r
}

function ConvertTo-SteamKeyCheckResult($raw) {
    if ($raw.Ok) { return (New-SgdbKeyCheckResult $true 'valid' 'ok' 200 'key_valid') }
    if ($raw.NoData) { return (New-SgdbKeyCheckResult $false 'other' 'warn' 0 'key_invalid_default') }

    $statusCode = 0; try { $statusCode = [int]$raw.StatusCode } catch {}
    $webStatus = [string]$raw.WebStatus
    $rawMsg = [string]$raw.RawMsg

    if ($statusCode -eq 403) { return (New-SgdbKeyCheckResult $false 'forbidden' 'error' 403 'sw_key_403') }
    if ($statusCode -ge 500) { return (New-SgdbKeyCheckResult $false 'server' 'warn' $statusCode 'sw_key_server' @($statusCode)) }
    if ($statusCode -gt 0)   { return (New-SgdbKeyCheckResult $false 'other' 'error' $statusCode 'sw_key_other' @($statusCode)) }

    $msgArgs = @()
    if ($webStatus -match 'NameResolutionFailure') {
        $msg = 'sw_key_dns'
    } elseif ($webStatus -eq 'Timeout') {
        $msg = 'sw_key_timeout'
    } elseif ($webStatus -match 'SecureChannelFailure|TrustFailure' -or $rawMsg -match 'SSL/TLS') {
        $msg = 'sw_key_tls'
    } elseif ($webStatus -match 'ConnectFailure|ConnectionClosed|SendFailure|ReceiveFailure') {
        $msg = 'sw_key_connect'
    } else {
        if ($rawMsg.Length -gt 100) { $rawMsg = $rawMsg.Substring(0, 100) + '…' }
        $msg = 'sw_key_noresp'; $msgArgs = @($rawMsg)
    }
    return (New-SgdbKeyCheckResult $false 'network' 'warn' 0 $msg $msgArgs)
}

function Test-SteamApiKey([string]$apiKey) {
    $check = Get-SteamApiKeyCheckResult $apiKey
    $global:steamApiKeyValid = [bool]$check.Valid
    $global:steamApiKeyCheck = $check
    return $check
}

# ------------------- Проверка ключей при запуске — в фоне -------------------
# Раньше при запуске оба ключа (SteamGridDB и Steam Web API) проверялись
# синхронно, прямо в UI-потоке, и если сервис не отвечал, программа "висела"
# до 10 секунд (таймаут запроса) на каждый ключ, прежде чем показать окно.
# Теперь запросы уходят в фоновые runspace'ы, окно открывается сразу, а
# результат подхватывается в момент, когда он реально нужен: при открытии
# «Настроек» (там при необходимости ждём) и в карточке игры (там кнопка SGDB
# просто включится сама, как только проверка закончится).
$script:startupJobs = @{ Sgdb = $null; Steam = $null; Db = $null }
# Итог последнего обновления базы игр (@{Ok; Count} или @{Ok=$false; Error}).
$script:lastDbRefreshResult = $null

function Start-StartupBackgroundJob([string]$name, $scriptBlock, [object[]]$argList) {
    try {
        $ps = [System.Management.Automation.PowerShell]::Create()
        [void]$ps.AddScript($scriptBlock)
        foreach ($a in $argList) { [void]$ps.AddArgument($a) }
        $script:startupJobs[$name] = [PSCustomObject]@{ Ps = $ps; Async = $ps.BeginInvoke() }
        return $true
    } catch {
        $script:startupJobs[$name] = $null
        return $false
    }
}

function Get-StartupJobResult($job) {
    $res = $null
    try {
        $out = @($job.Ps.EndInvoke($job.Async))
        if ($out.Count -gt 0) { $res = $out[0].psobject.BaseObject }
    } catch {}
    try { $job.Ps.Dispose() } catch {}
    return $res
}

function Test-StartupKeyChecksPending {
    return (($null -ne $script:startupJobs['Sgdb']) -or ($null -ne $script:startupJobs['Steam']))
}

# Забирает результаты фоновых проверок ключей. Без -Wait ничего не ждёт и
# просто подбирает то, что уже готово; с -Wait дожидается (прокачивая
# сообщения окна), но не дольше ~25 секунд.
function Complete-StartupKeyChecks ([switch]$Wait) {
    foreach ($name in @('Sgdb', 'Steam')) {
        $job = $script:startupJobs[$name]
        if ($null -eq $job) { continue }
        if (-not $job.Async.IsCompleted) {
            if (-not $Wait) { continue }
            $deadline = (Get-Date).AddSeconds(25)
            while (-not $job.Async.IsCompleted -and (Get-Date) -lt $deadline) {
                [System.Windows.Forms.Application]::DoEvents()
                Start-Sleep -Milliseconds 30
            }
            if (-not $job.Async.IsCompleted) { try { $job.Ps.Stop() } catch {} }
        }
        $script:startupJobs[$name] = $null
        $raw = Get-StartupJobResult $job
        if ($null -eq $raw) { $raw = @{ Ok = $false; StatusCode = 0; WebStatus = 'Timeout'; RawMsg = '' } }
        if ($name -eq 'Sgdb') {
            $check = ConvertTo-SgdbKeyCheckResult $raw
            $global:steamGridDbApiKeyCheck = $check
            $global:steamGridDbApiKeyValid = [bool]$check.Valid
        } else {
            $check = ConvertTo-SteamKeyCheckResult $raw
            $global:steamApiKeyCheck = $check
            $global:steamApiKeyValid = [bool]$check.Valid
        }
    }

    # Фоновое обновление базы игр закончилось — освобождаем runspace.
    $dbJob = $script:startupJobs['Db']
    if ($null -ne $dbJob -and $dbJob.Async.IsCompleted) {
        $script:startupJobs['Db'] = $null
        $script:lastDbRefreshResult = Get-StartupJobResult $dbJob
    }
}

# При закрытии программы не даём фоновой загрузке базы держать процесс.
function Stop-StartupBackgroundJobs {
    foreach ($name in @('Sgdb', 'Steam', 'Db')) {
        $job = $script:startupJobs[$name]
        if ($null -eq $job) { continue }
        try { if (-not $job.Async.IsCompleted) { [void]$job.Ps.BeginStop($null, $null) } } catch {}
    }
}

function Start-StartupKeyChecks {
    $global:steamGridDbApiKeyValid = $false
    $global:steamGridDbApiKeyCheck = $null
    $global:steamApiKeyValid = $false
    $global:steamApiKeyCheck = $null

    $sgdbKey = [string]$global:steamGridDbApiKey
    if (-not [string]::IsNullOrWhiteSpace($sgdbKey)) {
        # Два захода: на сетевом сбое/таймауте вторая попытка идёт уже в фоне и
        # ничего не задерживает.
        if (-not (Start-StartupBackgroundJob 'Sgdb' $script:SgdbKeyRawCheck @($sgdbKey, 3))) {
            $check = Get-SgdbKeyCheckResult $sgdbKey
            $global:steamGridDbApiKeyCheck = $check
            $global:steamGridDbApiKeyValid = [bool]$check.Valid
        }
    }
    $steamKey = [string]$global:steamApiKey
    if (-not [string]::IsNullOrWhiteSpace($steamKey)) {
        if (-not (Start-StartupBackgroundJob 'Steam' $script:SteamKeyRawCheck @($steamKey))) {
            $check = Get-SteamApiKeyCheckResult $steamKey
            $global:steamApiKeyCheck = $check
            $global:steamApiKeyValid = [bool]$check.Valid
        }
    }
}
Start-StartupKeyChecks

# ------------------- Локальная база App ID <-> название -------------------
# Используется ТОЛЬКО для поиска игры по названию в карточке (см.
# Get-SteamStoreNameCandidates / Find-SteamAppInfo). Отдельного окна и кнопки
# в «Настройках» нет: если задан Steam Web API ключ, а базы ещё нет или она
# старше 7 дней, она тихо обновляется в фоне при запуске программы.
#
# Метод ISteamApps/GetAppList/v2 объявлен Valve устаревшим (не справляется с
# текущим объёмом каталога Steam) и у части пользователей отвечает 404.
# Официально рекомендованная замена — IStoreService/GetAppList/v1: требует
# ключ и отдаёт список порциями (постранично, через last_appid), поэтому тут
# цикл пагинации. Файл базы хранится рядом с config.ini, в %AppData%\Steam Commander.
$script:LocalSteamAppsDbRefreshDays = 7

# Самодостаточный scriptblock для фонового runspace: скачивает весь список,
# пишет JSON во временный файл и подменяет им рабочий (поиск никогда не
# увидит наполовину записанный файл).
$script:LocalSteamAppsDbRefresh = {
    param($apiKey, $dbPath, $progressPath)
    try {
        # Прогресс обновления передаём в окно настроек через небольшой
        # служебный файл: фоновый PowerShell-runspace имеет собственное
        # состояние и не может напрямую менять элементы WinForms.
        try {
            if (-not [string]::IsNullOrWhiteSpace([string]$progressPath)) {
                [System.IO.File]::WriteAllText([string]$progressPath, '0')
            }
        } catch {}
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
        $ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
        $baseUrl = 'https://api.steampowered.com/IStoreService/GetAppList/v1/'
        $ids = New-Object System.Collections.Generic.List[int]
        $names = New-Object System.Collections.Generic.List[string]
        $lastAppId = 0
        $haveMore = $true
        $page = 0
        # У Steam API нет общего количества страниц, поэтому процент строится
        # по ожидаемому размеру каталога. Берём размер уже существующей базы,
        # но не меньше 250 тыс. записей. Если каталог окажется больше оценки,
        # прогресс остановится на 95% и завершится 100% только после записи базы.
        $estimatedTotal = 250000
        try {
            if (Test-Path -LiteralPath $dbPath) {
                $head = [System.IO.File]::ReadAllText([string]$dbPath)
                $mCount = [regex]::Match($head, '"Count"\s*:\s*(\d+)')
                if ($mCount.Success) {
                    $oldCount = 0
                    if ([int]::TryParse($mCount.Groups[1].Value, [ref]$oldCount) -and $oldCount -gt $estimatedTotal) {
                        $estimatedTotal = $oldCount
                    }
                }
            }
        } catch {}
        $estimatedPages = [math]::Max(1, [int][math]::Ceiling($estimatedTotal / 50000.0))

        while ($haveMore) {
            $page++
            if ($page -gt 60) { throw 'too many pages' }
            $url = "$baseUrl`?key=$(([string]$apiKey).Trim())&max_results=50000&include_games=1&include_dlc=1&include_software=1&include_videos=0&include_hardware=0&last_appid=$lastAppId"
            $data = Invoke-RestMethod -Uri $url -UserAgent $ua -TimeoutSec 90 -ErrorAction Stop
            $resp = $data.response
            if (-not $resp -or -not $resp.apps) {
                if ($page -eq 1) { throw 'empty response' }
                break
            }
            foreach ($app in $resp.apps) {
                $ids.Add([int]$app.appid)
                $names.Add([string]$app.name)
            }

            # Показываем максимум 95% до фактического завершения скачивания.
            # Если страниц окажется больше ожидаемого числа, процент просто
            # остаётся на 95%, а не прыгает обратно.
            try {
                if (-not [string]::IsNullOrWhiteSpace([string]$progressPath)) {
                    $pct = [int][math]::Floor(($page / [double]$estimatedPages) * 95)
                    if ($pct -lt 1) { $pct = 1 }
                    if ($pct -gt 95) { $pct = 95 }
                    [System.IO.File]::WriteAllText([string]$progressPath, [string]$pct)
                }
            } catch {}

            $haveMore = [bool]$resp.have_more_results
            $lastAppId = $resp.last_appid
        }
        # Защита от "обновления" рабочей базы мусором.
        if ($ids.Count -lt 1000) { throw "suspiciously small list: $($ids.Count)" }

        $sb = New-Object System.Text.StringBuilder ($ids.Count * 40)
        [void]$sb.Append('{"UpdatedAt":"').Append((Get-Date).ToString('yyyy-MM-dd HH:mm:ss')).Append('","Count":').Append($ids.Count).Append(',"Apps":[')
        $first = $true
        for ($i = 0; $i -lt $ids.Count; $i++) {
            $n = $names[$i]
            if ([string]::IsNullOrWhiteSpace($n)) { continue }
            $n = $n.Replace('\', '\\').Replace('"', '\"')
            if ($n -match '[\x00-\x1f]') {
                $n = [regex]::Replace($n, '[\x00-\x1f]', { param($m) ('\u{0:x4}' -f [int][char]$m.Value) })
            }
            if ($first) { $first = $false } else { [void]$sb.Append(',') }
            [void]$sb.Append('{"appid":').Append($ids[$i]).Append(',"name":"').Append($n).Append('"}')
        }
        [void]$sb.Append(']}')

        $tmp = $dbPath + '.tmp'
        [System.IO.File]::WriteAllText($tmp, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
        $moved = $false
        for ($t = 1; $t -le 6 -and -not $moved; $t++) {
            try { Move-Item -LiteralPath $tmp -Destination $dbPath -Force -ErrorAction Stop; $moved = $true }
            catch { Start-Sleep -Milliseconds 500 }
        }
        if (-not $moved) { throw 'cannot replace database file' }

        # Сразу подгружаем свежую базу в индекс поиска (тип общий для всего процесса).
        try { [void][SteamAppsIndex]::EnsureLoaded($dbPath) } catch {}
        try {
            if (-not [string]::IsNullOrWhiteSpace([string]$progressPath)) {
                [System.IO.File]::WriteAllText([string]$progressPath, '100')
            }
        } catch {}
        return @{ Ok = $true; Count = $ids.Count }
    } catch {
        return @{ Ok = $false; Error = [string]$_.Exception.Message }
    } finally {
        # Файл прогресса удаляется после того, как результат уже сформирован.
        # При успехе UI успевает увидеть 100%; при ошибке старый процент не
        # останется после завершения операции.
        try {
            if (-not [string]::IsNullOrWhiteSpace([string]$progressPath)) {
                if (Test-Path -LiteralPath $progressPath) { Remove-Item -LiteralPath $progressPath -Force -ErrorAction SilentlyContinue }
            }
        } catch {}
    }
}

# Запускает фоновое обновление базы. Без -Force — только если базы нет или она
# старше $script:LocalSteamAppsDbRefreshDays дней. Если обновление уже идёт,
# второе не запускается (возвращается $true — можно просто дождаться первого).
function Start-LocalSteamAppsDbRefresh([string]$apiKey, [switch]$Force) {
    if ([string]::IsNullOrWhiteSpace($apiKey)) { return $false }

    $existing = $script:startupJobs['Db']
    if ($null -ne $existing) {
        if (-not $existing.Async.IsCompleted) { return $true }
        try { Complete-StartupKeyChecks } catch {}
    }

    $dbPath = [string]$global:steamAppsDbFile
    if (-not $Force) {
        try {
            if (Test-Path -LiteralPath $dbPath) {
                $age = (Get-Date) - (Get-Item -LiteralPath $dbPath).LastWriteTime
                if ($age.TotalDays -lt $script:LocalSteamAppsDbRefreshDays) { return $false }
            }
        } catch {}
    }
    $script:lastDbRefreshResult = $null
    $progressPath = $dbPath + '.progress'
    try {
        [System.IO.File]::WriteAllText($progressPath, '0')
    } catch {}
    return (Start-StartupBackgroundJob 'Db' $script:LocalSteamAppsDbRefresh @($apiKey, $dbPath, $progressPath))
}

# Автообновление при запуске программы.
function Start-LocalSteamAppsDbAutoUpdate {
    [void](Start-LocalSteamAppsDbRefresh ([string]$global:steamApiKey))
}


# Индекс локальной базы держится в памяти (один раз разобранный C#-кодом),
# а не перечитывается и не разбирается заново на КАЖДОМ поиске. Раньше
# Search-LocalSteamAppsDatabase на каждый вызов читал весь JSON-файл
# (десятки МБ) через ConvertFrom-Json и гонял по ~250 тыс. записей три
# отдельных Where-Object с -like — на каждую введённую в поле "Название"
# букву. Это и давало многосекундные "фризы" карточки игры.
# Теперь: файл разбирается один раз (в фоне при старте программы, см.
# BeginLoad ниже), а поиск — один проход по массивам в памяти (~десятки мс)
# с ранжированием: точное совпадение -> название начинается с запроса ->
# слово начинается с запроса -> все слова запроса -> подстрока. Записи
# вроде "... Soundtrack" / "... Demo" / "... Playtest" уходят вниз списка.
if (-not ('SteamAppsIndex' -as [type])) {
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;

public class SteamAppHit
{
    public int AppId;
    public string Name;
    // 0 - точное совпадение, 1 - название начинается с запроса,
    // 2 - какое-то слово начинается с запроса, 3 - все слова запроса есть,
    // 4 - запрос встречается внутри названия.
    public int Tier;
    public bool Junk;
}

public static class SteamAppsIndex
{
    private static readonly object Sync = new object();
    private static readonly object LoadLock = new object();
    private static readonly Dictionary<string, bool> JunkWords = BuildJunkWords();

    private static int[] _ids = new int[0];
    private static string[] _names = new string[0];
    private static string[] _norm = new string[0];
    private static bool[] _junk = new bool[0];
    private static string _path = "";
    private static DateTime _stamp = DateTime.MinValue;
    private static long _size = -1;
    private static string _updatedAt = "";
    private static Thread _loader = null;

    private static Dictionary<string, bool> BuildJunkWords()
    {
        Dictionary<string, bool> d = new Dictionary<string, bool>();
        string[] words = new string[] {
            "soundtrack", "ost", "demo", "playtest", "dlc", "artbook", "wallpaper", "wallpapers",
            "sdk", "dedicated", "trailer", "beta", "upgrade", "bonus"
        };
        foreach (string w in words) { d[w] = true; }
        return d;
    }

    public static int Count { get { return _ids.Length; } }
    public static string UpdatedAt { get { return _updatedAt; } }

    // Нижний регистр, только буквы/цифры, любые разделители -> один пробел.
    public static string Normalize(string s)
    {
        if (string.IsNullOrEmpty(s)) return "";
        StringBuilder sb = new StringBuilder(s.Length);
        bool pendingSpace = false;
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (char.IsLetterOrDigit(c))
            {
                if (pendingSpace && sb.Length > 0) sb.Append(' ');
                pendingSpace = false;
                sb.Append(char.ToLowerInvariant(c));
            }
            else
            {
                pendingSpace = true;
            }
        }
        return sb.ToString();
    }

    private static bool IsJunkName(string norm)
    {
        int start = 0;
        int len = norm.Length;
        while (start < len)
        {
            int end = norm.IndexOf(' ', start);
            if (end < 0) end = len;
            if (end > start)
            {
                if (JunkWords.ContainsKey(norm.Substring(start, end - start))) return true;
            }
            start = end + 1;
        }
        return false;
    }

    private static bool IsAllDigits(string t)
    {
        if (string.IsNullOrEmpty(t)) return false;
        for (int i = 0; i < t.Length; i++)
        {
            if (!char.IsDigit(t[i])) return false;
        }
        return true;
    }

    // Есть ли в нормализованном названии слово, начинающееся с token
    // (при whole == true — слово, равное token целиком).
    private static bool HasWord(string s, string token, bool whole)
    {
        int from = 0;
        while (from <= s.Length - token.Length)
        {
            int idx = s.IndexOf(token, from, StringComparison.Ordinal);
            if (idx < 0) return false;
            bool startOk = (idx == 0) || (s[idx - 1] == ' ');
            if (startOk)
            {
                if (!whole) return true;
                int end = idx + token.Length;
                if (end == s.Length || s[end] == ' ') return true;
            }
            from = idx + 1;
        }
        return false;
    }

    // Запускает разбор файла в фоне и сразу возвращает управление.
    public static void BeginLoad(string path)
    {
        lock (Sync)
        {
            if (_loader != null && _loader.IsAlive) return;
            Thread t = new Thread(delegate() { try { EnsureLoaded(path); } catch { } });
            t.IsBackground = true;
            _loader = t;
            t.Start();
        }
    }

    // Гарантирует, что в памяти актуальная версия файла (перечитывает только
    // если файл изменился). Если фоновая загрузка ещё идёт — дожидается её.
    public static bool EnsureLoaded(string path)
    {
        lock (LoadLock)
        {
            FileInfo fi = new FileInfo(path);
            if (!fi.Exists)
            {
                lock (Sync)
                {
                    _ids = new int[0]; _names = new string[0]; _norm = new string[0]; _junk = new bool[0];
                    _stamp = DateTime.MinValue; _size = -1; _updatedAt = ""; _path = path;
                }
                return false;
            }
            if (_stamp == fi.LastWriteTimeUtc && _size == fi.Length &&
                string.Equals(_path, path, StringComparison.OrdinalIgnoreCase))
            {
                return _ids.Length > 0;
            }
            Reload(path, fi);
            return _ids.Length > 0;
        }
    }

    private static void Reload(string path, FileInfo fi)
    {
        string text = File.ReadAllText(path, Encoding.UTF8);

        string updated = "";
        int appsPos = text.IndexOf("\"Apps\"", StringComparison.Ordinal);
        string head = text.Substring(0, appsPos > 0 ? appsPos : Math.Min(text.Length, 512));
        Match mu = Regex.Match(head, "\"UpdatedAt\"\\s*:\\s*\"([^\"]*)\"");
        if (mu.Success) updated = mu.Groups[1].Value;

        List<int> ids = new List<int>(300000);
        List<string> names = new List<string>(300000);
        List<string> norms = new List<string>(300000);
        List<bool> junk = new List<bool>(300000);

        Regex rx = new Regex(
            "\"appid\"\\s*:\\s*(\\d+)\\s*,\\s*\"name\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"",
            RegexOptions.CultureInvariant | RegexOptions.Compiled);

        Match m = rx.Match(text);
        while (m.Success)
        {
            int id;
            if (int.TryParse(m.Groups[1].Value, out id))
            {
                string name = m.Groups[2].Value;
                if (name.IndexOf('\\') >= 0)
                {
                    try { name = Regex.Unescape(name); } catch { }
                }
                string norm = Normalize(name);
                if (norm.Length > 0)
                {
                    ids.Add(id);
                    names.Add(name);
                    norms.Add(norm);
                    junk.Add(IsJunkName(norm));
                }
            }
            m = m.NextMatch();
        }

        lock (Sync)
        {
            _ids = ids.ToArray();
            _names = names.ToArray();
            _norm = norms.ToArray();
            _junk = junk.ToArray();
            _updatedAt = updated;
            _path = path;
            _stamp = fi.LastWriteTimeUtc;
            _size = fi.Length;
        }
    }

    // Поиск по частичному названию. Результат уже отсортирован по релевантности.
    public static SteamAppHit[] Search(string query, int limit)
    {
        string qs = Normalize(query);
        if (qs.Length == 0 || limit <= 0) return new SteamAppHit[0];
        string qc = qs.Replace(" ", "");
        string[] qt = qs.Split(' ');

        bool ignoreJunk = false;
        bool[] qWhole = new bool[qt.Length];
        for (int q = 0; q < qt.Length; q++)
        {
            if (JunkWords.ContainsKey(qt[q])) ignoreJunk = true;
            // Числовое слово запроса ("4" в "DiRT 4") должно совпасть с целым
            // словом, а не с кусочком вроде "C4", "24" или "2014".
            qWhole[q] = IsAllDigits(qt[q]);
        }

        int[] ids; string[] names; string[] norms; bool[] junk;
        lock (Sync) { ids = _ids; names = _names; norms = _norm; junk = _junk; }

        List<long> keys = new List<long>(2048);
        string spaceQs = " " + qs;
        int n = norms.Length;
        for (int i = 0; i < n; i++)
        {
            string s = norms[i];
            if (s.Length < qc.Length) continue;

            int tier;
            if (s.Length == qs.Length && string.Equals(s, qs, StringComparison.Ordinal)) tier = 0;
            else if (s.StartsWith(qs, StringComparison.Ordinal)) tier = 1;
            else if (s.IndexOf(spaceQs, StringComparison.Ordinal) >= 0) tier = 2;
            else
            {
                bool allTokens = qt.Length > 1;
                if (allTokens)
                {
                    for (int j = 0; j < qt.Length; j++)
                    {
                        if (!HasWord(s, qt[j], qWhole[j])) { allTokens = false; break; }
                    }
                }
                if (allTokens) tier = 3;
                else
                {
                    string c = (s.IndexOf(' ') >= 0) ? s.Replace(" ", "") : s;
                    if (c.StartsWith(qc, StringComparison.Ordinal)) tier = 1;
                    else if (qc.Length >= 3 && c.IndexOf(qc, StringComparison.Ordinal) >= 0) tier = 4;
                    else continue;
                }
            }

            int rankTier = tier + ((junk[i] && !ignoreJunk) ? 8 : 0);
            long key = ((long)rankTier << 40) + ((long)Math.Min(s.Length, 1023) << 30) + (long)i;
            keys.Add(key);
        }

        long[] arr = keys.ToArray();
        Array.Sort(arr);
        int take = Math.Min(limit, arr.Length);
        SteamAppHit[] result = new SteamAppHit[take];
        for (int k = 0; k < take; k++)
        {
            int idx = (int)(arr[k] & 0x3FFFFFFFL);
            int rt = (int)(arr[k] >> 40);
            SteamAppHit h = new SteamAppHit();
            h.AppId = ids[idx];
            h.Name = names[idx];
            h.Junk = rt >= 8;
            h.Tier = h.Junk ? rt - 8 : rt;
            result[k] = h;
        }
        return result;
    }

    // Точное совпадение названия (без учёта регистра и знаков препинания —
    // как Get-NormalizedGameKey). "Чистые" записи идут раньше soundtrack/demo.
    public static SteamAppHit[] FindExact(string query, int max)
    {
        string qs = Normalize(query);
        if (qs.Length == 0 || max <= 0) return new SteamAppHit[0];
        string qc = qs.Replace(" ", "");

        int[] ids; string[] names; string[] norms; bool[] junk;
        lock (Sync) { ids = _ids; names = _names; norms = _norm; junk = _junk; }

        List<SteamAppHit> clean = new List<SteamAppHit>();
        List<SteamAppHit> dirty = new List<SteamAppHit>();
        int n = norms.Length;
        for (int i = 0; i < n; i++)
        {
            string s = norms[i];
            if (s.Length < qc.Length) continue;
            bool eq;
            if (s.Length == qc.Length) eq = string.Equals(s, qc, StringComparison.Ordinal);
            else eq = (s.IndexOf(' ') >= 0) && string.Equals(s.Replace(" ", ""), qc, StringComparison.Ordinal);
            if (!eq) continue;

            SteamAppHit h = new SteamAppHit();
            h.AppId = ids[i];
            h.Name = names[i];
            h.Tier = 0;
            h.Junk = junk[i];
            if (h.Junk) dirty.Add(h); else clean.Add(h);
        }

        clean.AddRange(dirty);
        if (clean.Count > max) clean.RemoveRange(max, clean.Count - max);
        return clean.ToArray();
    }
}
'@
    } catch {}
}

function Search-LocalSteamAppsDatabase([string]$term, [int]$limit = 30) {
    if ([string]::IsNullOrWhiteSpace($term)) { return @() }
    $hits = $null
    try {
        if (-not [SteamAppsIndex]::EnsureLoaded([string]$global:steamAppsDbFile)) { return @() }
        $hits = [SteamAppsIndex]::Search($term, $limit)
    } catch { return @() }

    $out = New-Object System.Collections.Generic.List[object]
    foreach ($h in $hits) {
        $out.Add([pscustomobject]@{ appid = $h.AppId; name = $h.Name; Tier = $h.Tier; Junk = $h.Junk })
    }
    return $out.ToArray()
}

# ===================== ВСТРОЕННЫЙ СНИМОК БАЗЫ STEAM =====================
# Чтобы поиск по названию работал сразу, без Steam Web API ключа, в программу
# встроен снимок списка приложений Steam (gzip + base64, тот же JSON, что
# пишет обновление). При запуске он распаковывается в steam_apps_db.json,
# если рабочей базы нет или она старше снимка. База, которую пользователь
# уже обновил сам (свежее снимка), не трогается. Дальше обновлять базу можно
# только своим ключом — через кнопку в настройках / автообновление.
# Как пересобрать снимок: заменить $script:EmbeddedSteamSeedUpdatedAt и текст
# между метками SEED-BEGIN / SEED-END (JSON-файл -> gzip -> base64).
$script:EmbeddedSteamSeedUpdatedAt = '2026-10-02 20:14:52'

function Install-EmbeddedSteamAppsSeed {
    try {
        $dbPath = [string]$global:steamAppsDbFile
        $seedDate = [datetime]::ParseExact($script:EmbeddedSteamSeedUpdatedAt, 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture)

        if (Test-Path -LiteralPath $dbPath) {
            # Дата существующей базы берётся из заголовка файла ("UpdatedAt"),
            # а не из LastWriteTime: файл могли просто скопировать/перенести.
            $curUpdated = $null
            try {
                $fs = [System.IO.File]::OpenRead($dbPath)
                try {
                    $buf = New-Object byte[] 512
                    $n = $fs.Read($buf, 0, 512)
                    $head = [System.Text.Encoding]::UTF8.GetString($buf, 0, $n)
                } finally { $fs.Dispose() }
                $m = [regex]::Match($head, '"UpdatedAt"\s*:\s*"([^"]*)"')
                if ($m.Success) {
                    $parsed = [datetime]::MinValue
                    if ([datetime]::TryParseExact($m.Groups[1].Value, 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$parsed)) { $curUpdated = $parsed }
                }
            } catch {}
            if ($null -ne $curUpdated -and $curUpdated -ge $seedDate) { return }
        }

        $b64 = ($script:EmbeddedSteamSeedB64 -replace '\s', '')
        if ([string]::IsNullOrWhiteSpace($b64)) { return }
        $gz = [Convert]::FromBase64String($b64)
        $inMs = New-Object System.IO.MemoryStream (,$gz)
        $outMs = New-Object System.IO.MemoryStream
        try {
            $gs = New-Object System.IO.Compression.GZipStream ($inMs, [System.IO.Compression.CompressionMode]::Decompress)
            try { $gs.CopyTo($outMs) } finally { $gs.Dispose() }
            $bytes = $outMs.ToArray()
        } finally { $inMs.Dispose(); $outMs.Dispose() }
        # Защита от битого снимка: должен быть похож на нашу базу.
        if ($bytes.Length -lt 100000) { return }

        $dir = [System.IO.Path]::GetDirectoryName($dbPath)
        if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
        $tmp = $dbPath + '.seed.tmp'
        [System.IO.File]::WriteAllBytes($tmp, $bytes)
        $moved = $false
        for ($t = 1; $t -le 4 -and -not $moved; $t++) {
            try { Move-Item -LiteralPath $tmp -Destination $dbPath -Force -ErrorAction Stop; $moved = $true }
            catch { Start-Sleep -Milliseconds 300 }
        }
        if (-not $moved) { try { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } catch {} ; return }
        # Дата файла = дата снимка, чтобы автообновление (если есть ключ)
        # считало базу устаревшей по-настоящему, а не "свежей, только что записанной".
        try { (Get-Item -LiteralPath $dbPath).LastWriteTime = $seedDate } catch {}
    } catch {}
}

# SEED-BEGIN
$script:EmbeddedSteamSeedB64 = @'








































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































'@
# SEED-END

Install-EmbeddedSteamAppsSeed

# Разбираем файл базы заранее, в фоне, чтобы первый поиск в карточке не ждал.
try { [SteamAppsIndex]::BeginLoad([string]$global:steamAppsDbFile) } catch {}

# Если базы нет или она устарела — обновляем её тихо, в фоне.
Start-LocalSteamAppsDbAutoUpdate


if ([string]::IsNullOrWhiteSpace([string]$global:steamInstallPath)) {
    $global:steamInstallPath = Get-DefaultSteamInstallPath
}
if ([string]::IsNullOrWhiteSpace([string]$global:steamUserId)) {
    try {
        $allProfiles = @(Get-SteamUserProfiles)
        # Предпочитаем настоящие аккаунты Steam (с записью в loginusers.vdf);
        # если таких нет, откатываемся к первой попавшейся папке, как раньше.
        $firstProfile = @($allProfiles | Where-Object { $_.IsKnownAccount }) | Select-Object -First 1
        if ($firstProfile -eq $null) { $firstProfile = $allProfiles | Select-Object -First 1 }
        if ($firstProfile -ne $null) {
            $global:steamUserId = [string]$firstProfile.Id
        }
    } catch {}
}

$steamUi = [ordered]@{
    Bg = [System.Drawing.Color]::FromArgb(23,29,37)
    Panel = [System.Drawing.Color]::FromArgb(27,40,56)
    Panel2 = [System.Drawing.Color]::FromArgb(20,30,42)
    Input = [System.Drawing.Color]::FromArgb(13,20,28)
    Border = [System.Drawing.Color]::FromArgb(58,73,90)
    Text = [System.Drawing.Color]::FromArgb(220,223,228)
    Muted = [System.Drawing.Color]::FromArgb(145,154,164)
    Accent = [System.Drawing.Color]::FromArgb(102,192,244)
    Accent2 = [System.Drawing.Color]::FromArgb(26,159,255)
    Selected = [System.Drawing.Color]::FromArgb(38,76,108)
    Green = [System.Drawing.Color]::FromArgb(92,173,112)
}

# Небольшое тематическое окно подтверждения (Да/Нет) в стиле самого
# Commander — используется вместо стандартного Windows MessageBox везде,
# где нужно спросить пользователя "да/нет", чтобы окно не выбивалось из
# общего тёмного дизайна программы.
function Show-ThemedConfirm {
    param(
        $owner,
        [string]$titleText,
        [string]$messageText,
        [string]$yesText = '',
        [string]$noText = ''
    )
    if ([string]::IsNullOrEmpty($yesText)) { $yesText = (T 'confirm_yes') }
    if ([string]::IsNullOrEmpty($noText)) { $noText = (T 'confirm_no') }

    $confirm = New-Object System.Windows.Forms.Form
    $confirm.Text = $titleText
    $confirm.StartPosition = 'CenterParent'
    $confirm.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $confirm.MaximizeBox = $false
    $confirm.MinimizeBox = $false
    $confirm.ShowInTaskbar = $false
    $confirm.ClientSize = New-Object System.Drawing.Size(420, 160)
    $confirm.BackColor = $steamUi.Bg
    $confirm.ForeColor = $steamUi.Text
    $confirm.Font = New-Object System.Drawing.Font('Segoe UI', 9)

    $confirmMessage = New-Object System.Windows.Forms.Label
    $confirmMessage.Text = $messageText
    $confirmMessage.Location = New-Object System.Drawing.Point(20, 22)
    $confirmMessage.Size = New-Object System.Drawing.Size(380, 66)
    $confirmMessage.ForeColor = $steamUi.Text
    $confirmMessage.Font = New-Object System.Drawing.Font('Segoe UI', 10)
    $confirmMessage.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $confirm.Controls.Add($confirmMessage)

    $btnConfirmYes = New-Object System.Windows.Forms.Button
    $btnConfirmYes.Text = $yesText
    $btnConfirmYes.Location = New-Object System.Drawing.Point(175, 105)
    $btnConfirmYes.Size = New-Object System.Drawing.Size(110, 34)
    $btnConfirmYes.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnConfirmYes.FlatAppearance.BorderColor = $steamUi.Accent2
    $btnConfirmYes.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnConfirmYes.ForeColor = $steamUi.Text
    $btnConfirmYes.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
    $btnConfirmYes.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnConfirmYes.DialogResult = [System.Windows.Forms.DialogResult]::Yes
    $confirm.Controls.Add($btnConfirmYes)

    $btnConfirmNo = New-Object System.Windows.Forms.Button
    $btnConfirmNo.Text = $noText
    $btnConfirmNo.Location = New-Object System.Drawing.Point(290, 105)
    $btnConfirmNo.Size = New-Object System.Drawing.Size(110, 34)
    $btnConfirmNo.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnConfirmNo.FlatAppearance.BorderColor = $steamUi.Border
    $btnConfirmNo.BackColor = $steamUi.Panel
    $btnConfirmNo.ForeColor = $steamUi.Text
    $btnConfirmNo.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnConfirmNo.DialogResult = [System.Windows.Forms.DialogResult]::No
    $confirm.Controls.Add($btnConfirmNo)

    $confirm.AcceptButton = $btnConfirmYes
    $confirm.CancelButton = $btnConfirmNo

    try {
        return ($confirm.ShowDialog($owner) -eq [System.Windows.Forms.DialogResult]::Yes)
    } finally {
        try { $confirm.Dispose() } catch {}
    }
}

# Серый текст-подсказка внутри TextBox ("Поиск…"), пока поле пустое и не в
# фокусе — стандартного свойства Placeholder у WinForms TextBox нет, поэтому
# нативное сообщение EM_SETCUEBANNER (тот же приём P/Invoke, что и у
# ListBoxCaretNative дальше в этом файле).
try {
    if (-not ('TextBoxCueBanner' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class TextBoxCueBanner {
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, string lParam);
    private const int EM_SETCUEBANNER = 0x1501;
    public static void SetCue(IntPtr hWnd, string text) {
        SendMessage(hWnd, EM_SETCUEBANNER, IntPtr.Zero, text);
    }
}
'@
    }
} catch {}
function Set-TextBoxCue ($textBox, [string]$text) {
    try { [TextBoxCueBanner]::SetCue($textBox.Handle, $text) } catch {}
}

# ===================== ИКОНКА ПРИЛОЖЕНИЯ =====================
# ICO (16/20/24/32/40/48 px, несжатые BMP-кадры) встроен как Base64, чтобы
# значок был и при запуске из .ps1, и внутри собранного EXE. WinForms сам
# выбирает нужный кадр под текущий масштаб экрана.
$global:embeddedAppIconIco = ""
$global:appIcon = $null
function Get-AppIcon {
    if ($null -ne $global:appIcon) { return $global:appIcon }
    try {
        $iconBytes = [System.Convert]::FromBase64String($global:embeddedAppIconIco)
        $iconStream = New-Object System.IO.MemoryStream(,$iconBytes)
        $global:appIcon = New-Object System.Drawing.Icon($iconStream)
    } catch { $global:appIcon = $null }
    return $global:appIcon
}

Set-SplashProgress 0.58
$form = New-Object System.Windows.Forms.Form
$form.Text = "$($global:appTitle) $($global:appVersion)"
try { $appIconObj = Get-AppIcon; if ($null -ne $appIconObj) { $form.Icon = $appIconObj } } catch {}
# ClientSize, а не Size: нужно, чтобы 1080x700 было ИМЕННО внутренней рабочей
# областью окна, а не всем окном вместе с заголовком и рамкой — иначе высота
# заголовка (у FixedDialog она не резиновая, но всё равно отъедает несколько
# десятков пикселей) откусывала часть содержимого снизу (см. обрезанную
# нижнюю панель с прогресс-баром и кнопкой добавления).
$form.ClientSize = New-Object System.Drawing.Size(1080, 700)
$form.StartPosition = "CenterScreen"
$form.FormBorderStyle = "FixedSingle"
$form.MaximizeBox = $false
$form.BackColor = $steamUi.Bg
$form.ForeColor = $steamUi.Text
