# ---------------------------------------------------------------------------
# Выпадающий список ядер RetroArch — по центру, сразу под обеими панелями
# библиотеки. Виден только когда в режиме ROMs активный эмулятор — RetroArch
# (см. Test-IsRetroArchProfile): у него, в отличие от остальных эмуляторов,
# аргумент запуска зависит от загружаемого ядра (libretro core), а не
# фиксирован сам по себе. Показывает имена ядер ИМЕННО так, как их показывает
# сам RetroArch (Get-RetroArchCoreDisplayList читает display_name из
# .info-файлов), а не имена файлов *_libretro.dll. Выбор здесь сразу
# сохраняется как ядро по умолчанию активного профиля эмулятора ($profile.Core,
# то же поле, что редактируется в Настройках) — поэтому дальше, при обычном
# добавлении игры через карточку и при автопакетном добавлении (оно тоже
# в режиме ROMs ром добавляется тихо, без карточки, если всё определено уверенно — см. Add-RomToSteamQuietly и Invoke-SmartBatchAdd),
# аргумент запуска будет собран уже под это ядро (Get-RetroArchArgsTemplate),
# без необходимости открывать Настройки заново.
#
# Стилизован так же, как выбор языка/региона в Настройках: Panel-рамка +
# SmartExeComboBox с OwnerDrawFixed (иначе стрелка и список раскрытия
# оставались бы нативными светлыми независимо от BackColor/ForeColor — см.
# комментарий у самого класса SmartExeComboBox).
# ---------------------------------------------------------------------------
$pnlMainCore = New-Object System.Windows.Forms.Panel
$pnlMainCore.Location = New-Object System.Drawing.Point(390, 577)
$pnlMainCore.Size = New-Object System.Drawing.Size(300, 26)
$pnlMainCore.BackColor = $steamUi.Input
$pnlMainCore.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
$pnlMainCore.Visible = $false
$form.Controls.Add($pnlMainCore)

$cmbMainCore = New-Object SmartExeComboBox
$cmbMainCore.Dock = [System.Windows.Forms.DockStyle]::Fill
$cmbMainCore.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
$cmbMainCore.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
$cmbMainCore.ItemHeight = 20
$cmbMainCore.DropDownHeight = 200
$cmbMainCore.IntegralHeight = $false
$cmbMainCore.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
$cmbMainCore.BackColor = $steamUi.Input
$cmbMainCore.ForeColor = $steamUi.Text
$cmbMainCore.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
try { $cmbMainCore.BorderColor = $steamUi.Input } catch {}
$pnlMainCore.Controls.Add($cmbMainCore)
$cmbMainCore.Add_DrawItem({
    param($sender,$e)
    if ($e.Index -lt 0) { return }
    $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
    $bg = if ($isSelected) { $steamUi.Accent2 } else { $steamUi.Input }
    $fg = if ($isSelected) { [System.Drawing.Color]::White } else { $steamUi.Text }
    $bgBrush = New-Object System.Drawing.SolidBrush($bg)
    $textBrush = New-Object System.Drawing.SolidBrush($fg)
    try {
        $e.Graphics.FillRectangle($bgBrush, $e.Bounds)
        $text = [string]$sender.Items[$e.Index]
        $textSize = $e.Graphics.MeasureString($text, $sender.Font)
        $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
        $e.Graphics.DrawString($text, $sender.Font, $textBrush, [float]($e.Bounds.X + 8), [float]$textY)
    } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
}.GetNewClosure())

# Пункт-заглушка "Выберите ядро" всегда первый в списке (индекс 0) — вместо
# пустого поля, пока ядро ещё ни разу не выбрано для активного профиля.
# $script:mainCoreFileNames хранит имя файла ядра для КАЖДОГО пункта списка
# по тому же индексу (у заглушки — пустая строка).
$script:mainCorePlaceholderText = (T 'core_choose')
$script:mainCoreFileNames = @()
$script:mainCoreSuppress = $false

# Показывает/прячет и перезаполняет список ядер под текущий активный
# эмулятор режима ROMs. Вызывается из Update-RomEmulatorIndicator — то есть
# везде, где обновляется индикатор активного эмулятора (старт программы,
# переключение тумблера ROMs, быстрый пик эмулятора, Настройки).
function Update-MainCoreSelector {
    try {
        $active = Get-ActiveEmulatorProfile
        $isRA = ($active -ne $null) -and (Test-IsRetroArchProfile ([string]$active.Name) ([string]$active.ExePath))
        $showCore = [bool]$script:romsModeEnabled -and $isRA
        $pnlMainCore.Visible = $showCore
        if (-not $showCore) { return }

        $script:mainCoreSuppress = $true
        try {
            $prevFileCore = [string]$active.Core
            $cmbMainCore.Items.Clear()
            [void]$cmbMainCore.Items.Add($script:mainCorePlaceholderText)
            $script:mainCoreFileNames = @('')
            $selIdx = 0
            foreach ($c in @(Get-RetroArchCoreDisplayList ([string]$active.ExePath))) {
                [void]$cmbMainCore.Items.Add([string]$c.DisplayName)
                $script:mainCoreFileNames += [string]$c.FileCore
                if (-not [string]::IsNullOrWhiteSpace($prevFileCore) -and `
                    [string]::Equals([string]$c.FileCore, $prevFileCore, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $selIdx = $cmbMainCore.Items.Count - 1
                }
            }
            $cmbMainCore.SelectedIndex = $selIdx
        } finally { $script:mainCoreSuppress = $false }
    } catch {}
}

# Выбор ядра здесь сразу пишется в профиль активного эмулятора (то же поле
# Core, что и в Настройках -> Эмуляторы -> Изменить) и сохраняется в
# config.ini — той же схемой замены элемента в $global:emulatorProfiles, что
# используют кнопки "Изменить"/"Удалить" в Настройках. Выбор самой заглушки
# ("Выберите ядро", индекс 0) сбрасывает сохранённое ядро профиля обратно
# в пустое значение — то же состояние, что и до первого выбора.
$cmbMainCore.Add_SelectedIndexChanged({
    if ($script:mainCoreSuppress) { return }
    try {
        if ($cmbMainCore.SelectedIndex -lt 0 -or $cmbMainCore.SelectedIndex -ge $script:mainCoreFileNames.Count) { return }
        $active = Get-ActiveEmulatorProfile
        if ($active -eq $null) { return }
        $chosenFileCore = [string]$script:mainCoreFileNames[$cmbMainCore.SelectedIndex]
        if ([string]::Equals([string]$active.Core, $chosenFileCore, [System.StringComparison]::OrdinalIgnoreCase)) { return }
        $activeId = [string]$active.Id
        $global:emulatorProfiles = @($global:emulatorProfiles | ForEach-Object {
            if ([string]$_.Id -eq $activeId) {
                $updated = $_.Clone()
                $updated.Core = $chosenFileCore
                $updated
            } else { $_ }
        })
        try { Save-Configuration } catch {}
    } catch {}
})

# После выбора ядра (список закрылся) снимаем фокус с поля: иначе оно остаётся синим (выделенным).
$cmbMainCore.Add_DropDownClosed({
    try {
        $form.BeginInvoke([Action]{
            try { $cmbMainCore.SelectionLength = 0 } catch {}
            try { $form.ActiveControl = $null } catch {}
            try { $cmbMainCore.Invalidate() } catch {}
        }) | Out-Null
    } catch {}
})

# Подсказка по клавишам — одна на обе панели (её же возвращаем после переноса игр).
$global:mainHintText = (T 'hint_main')
# Значок уверенности (зелёный ✓ / красный !) слева от статусной строки —
# тот же, что на карточках игр. Показывается только когда Space считает
# отмеченные игры и выносит вердикт о возможности переноса между дисками.
$picStatusBadge = New-Object System.Windows.Forms.PictureBox
$picStatusBadge.Size = New-Object System.Drawing.Size(18, 18)
$picStatusBadge.Location = New-Object System.Drawing.Point(20, 609)
$picStatusBadge.BackColor = [System.Drawing.Color]::Transparent
$picStatusBadge.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
$picStatusBadge.Visible = $false
$form.Controls.Add($picStatusBadge)

$labelHeader = New-Object System.Windows.Forms.Label
$labelHeader.Text = $global:mainHintText
# Статусная строка живёт прямо над общим прогресс-баром ($progressBarFolder),
# а не в шапке окна — сюда же выводятся текстовые статусы пакетного
# добавления/переноса папок (см. Invoke-SmartBatchAdd, Start-GameCopy и т.д.),
# поэтому она соседствует именно с прогрессом, который эти статусы поясняют.
$labelHeader.Location = New-Object System.Drawing.Point(20, 607)
$labelHeader.Size = New-Object System.Drawing.Size(1040, 22)
$labelHeader.Font = New-Object System.Drawing.Font("Segoe UI Semibold", 10)
$labelHeader.ForeColor = $steamUi.Text
$form.Controls.Add($labelHeader)

# Пока $script:statusBadgeLocked = $true, TextChanged не прячет значок
# (мы сами ставим текст + badge). Любой другой код, который пишет в
# $labelHeader.Text, автоматически убирает значок и возвращает подпись
# на полную ширину.
$script:statusBadgeLocked = $false
$labelHeader.Add_TextChanged({
    if ($script:statusBadgeLocked) { return }
    try {
        if ($picStatusBadge.Visible) {
            $picStatusBadge.Visible = $false
            try { if ($null -ne $picStatusBadge.Image) { $picStatusBadge.Image.Dispose(); $picStatusBadge.Image = $null } } catch {}
        }
        if ($labelHeader.Left -ne 20) {
            $labelHeader.Location = New-Object System.Drawing.Point(20, 607)
            $labelHeader.Size = New-Object System.Drawing.Size(1040, 22)
        }
        $labelHeader.ForeColor = $steamUi.Text
    } catch {}
})

# confident: $true = зелёный, $false = красный, $null = без значка.
function Set-MainStatusWithBadge ([string]$text, $confident = $null) {
    $script:statusBadgeLocked = $true
    try {
        if ($null -eq $confident) {
            try { if ($null -ne $picStatusBadge.Image) { $picStatusBadge.Image.Dispose(); $picStatusBadge.Image = $null } } catch {}
            $picStatusBadge.Visible = $false
            $labelHeader.Location = New-Object System.Drawing.Point(20, 607)
            $labelHeader.Size = New-Object System.Drawing.Size(1040, 22)
            $labelHeader.ForeColor = $steamUi.Text
            $labelHeader.Text = $text
        } else {
            $bmp = Get-ConfidenceBadgeBitmap ([bool]$confident)
            try { if ($null -ne $picStatusBadge.Image) { $picStatusBadge.Image.Dispose() } } catch {}
            $picStatusBadge.Image = $bmp
            $picStatusBadge.Visible = ($null -ne $bmp)
            $labelHeader.Location = New-Object System.Drawing.Point(44, 607)
            $labelHeader.Size = New-Object System.Drawing.Size(1016, 22)
            $labelHeader.ForeColor = if ([bool]$confident) { $steamUi.Green } else { [System.Drawing.Color]::FromArgb(224, 82, 82) }
            $labelHeader.Text = $text
        }
    } finally {
        $script:statusBadgeLocked = $false
    }
}

