# ---------------------------------------------------------------------------
# Кэш иконок эмуляторов. Раньше иконка вытягивалась из exe через
# ExtractAssociatedIcon при каждом обновлении индикатора и при каждом открытии
# попапа (на HDD / при холодном кэше Windows это заметно медленно). Теперь иконка
# извлекается ОДИН раз — при добавлении/изменении эмулятора — и сохраняется PNG
# в %APPDATA%\Steam Commander\emu_icons\<Id>.png; дальше она читается с диска
# (и держится в памяти на время сеанса). Для эмуляторов, добавленных до этой
# версии, PNG создаётся лениво при первом обращении.
# ---------------------------------------------------------------------------
$global:emuIconDir = Join-Path $global:appDataDir 'emu_icons'
$script:emuIconMem = @{}

function Get-EmulatorIconPath ([string]$id) {
    $safe = ($id -replace '[^\w\-]', '_')
    if ([string]::IsNullOrWhiteSpace($safe)) { return $null }
    return (Join-Path $global:emuIconDir ($safe + '.png'))
}

function Remove-EmulatorIconCache ([string]$id) {
    try {
        if ($script:emuIconMem.ContainsKey($id)) {
            try { if ($null -ne $script:emuIconMem[$id]) { $script:emuIconMem[$id].Dispose() } } catch {}
            $script:emuIconMem.Remove($id)
        }
        $path = Get-EmulatorIconPath $id
        if ($path -and (Test-Path -LiteralPath $path)) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
    } catch {}
}

# Достаёт иконку из exe, пишет PNG на диск и кладёт в память. Возвращает Bitmap или $null.
function Save-EmulatorIconCache ($emu) {
    if ($null -eq $emu) { return $null }
    $id = [string]$emu.Id
    if ([string]::IsNullOrWhiteSpace($id)) { return $null }
    # Принудительное обновление: старое значение (в памяти и на диске) выбрасываем.
    try {
        if ($script:emuIconMem.ContainsKey($id)) {
            # старый Bitmap не освобождаем — он может ещё отображаться индикатором
            $script:emuIconMem.Remove($id)
        }
    } catch {}
    $bmp = $null
    try {
        $exe = [string]$emu.ExePath
        if (-not [string]::IsNullOrWhiteSpace($exe) -and (Test-Path -LiteralPath $exe)) {
            $ico = [System.Drawing.Icon]::ExtractAssociatedIcon($exe)
            if ($ico -ne $null) {
                try { $bmp = $ico.ToBitmap() } finally { $ico.Dispose() }
            }
        }
    } catch { $bmp = $null }
    $path = Get-EmulatorIconPath $id
    try {
        if ($path) {
            if (-not (Test-Path -LiteralPath $global:emuIconDir)) { New-Item -ItemType Directory -Path $global:emuIconDir -Force | Out-Null }
            if ($null -ne $bmp) { $bmp.Save($path, [System.Drawing.Imaging.ImageFormat]::Png) }
            elseif (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
        }
    } catch {}
    $script:emuIconMem[$id] = $bmp
    return $bmp
}

# Возвращает ОБЩИЙ Bitmap из кэша (не освобождать!). Порядок: память -> PNG на
# диске -> извлечение из exe (с записью PNG). Тем, кому нужна копия, которую
# можно освободить, — New-Object System.Drawing.Bitmap($общий).
function Get-EmulatorIconBitmap ($emu) {
    if ($null -eq $emu) { return $null }
    $id = [string]$emu.Id
    if ([string]::IsNullOrWhiteSpace($id)) { return $null }
    if ($script:emuIconMem.ContainsKey($id) -and $null -ne $script:emuIconMem[$id]) { return $script:emuIconMem[$id] }
    $path = Get-EmulatorIconPath $id
    try {
        if ($path -and (Test-Path -LiteralPath $path)) {
            # Через поток в памяти, чтобы не держать файл заблокированным.
            $bytes = [System.IO.File]::ReadAllBytes($path)
            $ms = New-Object System.IO.MemoryStream(, $bytes)
            try {
                $img = [System.Drawing.Image]::FromStream($ms)
                try { $bmp = New-Object System.Drawing.Bitmap($img) } finally { $img.Dispose() }
            } finally { $ms.Dispose() }
            $script:emuIconMem[$id] = $bmp
            return $bmp
        }
    } catch {}
    return (Save-EmulatorIconCache $emu)
}

# Обновляет иконку/название на индикаторе под текущий $global:activeEmulatorId
# и его видимость под текущий $script:romsModeEnabled. Вызывается при
# переключении тумблера ROMs, при выборе эмулятора (быстрый пик или
# Настройки) и один раз при старте программы.
function Update-RomEmulatorIndicator {
    try {
        $active = Get-ActiveEmulatorProfile
        if ($active -eq $null) {
            $picRomEmulatorIcon.Image = $null
            $lblRomEmulatorName.Text = (T 'rom_emu_none')
        } else {
            $lblRomEmulatorName.Text = [string]$active.Name
            $icoBmp = $null
            try { $icoBmp = Get-EmulatorIconBitmap $active } catch { $icoBmp = $null }
            $picRomEmulatorIcon.Image = $icoBmp
        }
        $pnlRomIndicator.Visible = [bool]$script:romsModeEnabled
    } catch {}
    try { Update-MainCoreSelector } catch {}
}

# Компиляция C#-типов попапа выбора эмулятора (фильтр колёсика и скругление
# окна Win11). Add-Type компилирует код при ПЕРВОМ вызове (секунды), поэтому раньше
# первое открытие попапа после запуска программы заметно тормозило, а второе
# было быстрым (типы уже есть). Теперь компиляция вынесена сюда и прогревается
# в фоне сразу после показа главного окна (см. $form.Add_Shown в конце файла);
# повторные вызовы мгновенны — работает защита "-not (type -as [type])".
function Initialize-RomPickerTypes {
    try {
        if (-not ('EmuPickerWheel' -as [type])) {
            $__wf = [System.Windows.Forms.Form].Assembly.Location
            $__dr = [System.Drawing.Bitmap].Assembly.Location
            Add-Type -ReferencedAssemblies @($__wf, $__dr) -TypeDefinition @'
using System;
using System.Windows.Forms;

public class EmuPickerWheel : IMessageFilter
{
    public static bool Active = false;
    public static Control Flow = null;
    public static Control Dots = null;
    public static int PageH = 1;
    public static int PageCount = 1;
    public static int Page = 0;

    public static void GoToPage(int page)
    {
        if (PageCount < 1) PageCount = 1;
        if (page < 0) page = 0;
        if (page >= PageCount) page = PageCount - 1;
        Page = page;
        Control f = Flow;
        Control d = Dots;
        int ph = PageH;
        int p = Page;
        Action apply = delegate {
            try {
                if (f != null && !f.IsDisposed) f.Top = -(p * ph);
                if (d != null && !d.IsDisposed) { d.Invalidate(); d.Update(); }
            } catch { }
        };
        try {
            if (f != null && f.IsHandleCreated && f.InvokeRequired)
                f.BeginInvoke(apply);
            else
                apply();
        } catch {
            try { apply(); } catch { }
        }
    }

    public bool PreFilterMessage(ref Message m)
    {
        if (!Active || m.Msg != 0x020A) return false;
        if (PageCount <= 1) return false;
        int delta = (short)((m.WParam.ToInt64() >> 16) & 0xFFFF);
        if (delta > 0) GoToPage(Page - 1);
        else if (delta < 0) GoToPage(Page + 1);
        return true;
    }
}
'@ -ErrorAction Stop
        }
    } catch {}
    try {
        if (-not ('Win11PopupDwm' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class Win11PopupDwm {
    [DllImport("dwmapi.dll")]
    public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int val, int size);
    public const int DWMWA_WINDOW_CORNER_PREFERENCE = 33;
    public const int DWMWCP_ROUND = 2;
    public const int DWMWA_BORDER_COLOR = 34;
    public static void Apply(IntPtr hwnd) {
        try {
            int round = DWMWCP_ROUND;
            DwmSetWindowAttribute(hwnd, DWMWA_WINDOW_CORNER_PREFERENCE, ref round, 4);
            int border = 0x005A493A;
            DwmSetWindowAttribute(hwnd, DWMWA_BORDER_COLOR, ref border, 4);
        } catch {}
    }
}
'@
        }
    } catch {}
}

# Всплывающая панель выбора эмулятора (в духе разворачивающейся папки
# Windows 11): крупные иконки + названия, а не текстовый ContextMenuStrip.
# Выбор сразу делает эмулятор активным и перечитывает панели в режиме ROMs.
function Show-RomEmulatorPickerPopup {
    if (@($global:emulatorProfiles).Count -eq 0) {
        Show-AppMessageBox($form, (T 'rom_emu_list_empty'), $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
        return
    }

    # Плитки эмуляторов в попапе отсортированы по алфавиту (по названию),
    # а не по порядку добавления в Настройках. ВАЖНО: элементы
    # $global:emulatorProfiles — это хеш-таблицы (@{ Id=...; Name=...; ... }),
    # а не объекты, поэтому "Sort-Object -Property Name" (имя свойства строкой)
    # молча не находит такое свойство и ничего не сортирует — нужно именно
    # блок скрипта { $_.Name }, который PowerShell вычисляет напрямую и уже
    # умеет читать ключи хеш-таблицы через точечную запись.
    $profiles = @($global:emulatorProfiles) | Sort-Object -Property { [string]$_.Name } -CaseSensitive:$false
    $tileW = 96
    $tileH = 88
    $tileMargin = 4
    $cols = if ($profiles.Count -ge 4) { 4 } elseif ($profiles.Count -ge 1) { $profiles.Count } else { 1 }
    $rows = [Math]::Ceiling($profiles.Count / [double]$cols)
    $cellW = $tileW + (2 * $tileMargin)
    $cellH = $tileH + (2 * $tileMargin)
    $flowPad = 6
    $gridW = ($cols * $cellW) + (2 * $flowPad)
    $gridH = ($rows * $cellH) + (2 * $flowPad)
    $hdrH = 28
    $dotsW = 16
    $borderExtra = 4
    $maxVisibleRows = 4
    $pageH = ($maxVisibleRows * $cellH) + (2 * $flowPad)
    $pageCount = [Math]::Max(1, [int][Math]::Ceiling($rows / [double]$maxVisibleRows))
    $needScroll = ($pageCount -gt 1)
    $visibleGridH = if ($needScroll) { $pageH } else { $gridH }
    $popupW = [Math]::Max(240, $gridW + $borderExtra + 8 + $(if ($needScroll) { $dotsW } else { 0 }))
    $popupH = $visibleGridH + $hdrH + $borderExtra + 8

    # C# фильтр колёсика: сам двигает Flow.Top и инвалидирует точки.
    # Никакого PowerShell из C#, никакого Timer — поэтому колесо реально работает.

    $popup = New-Object System.Windows.Forms.Form
    $popup.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::None
    $popup.StartPosition = [System.Windows.Forms.FormStartPosition]::Manual
    $popup.ShowInTaskbar = $false
    $popup.TopMost = $true
    $popup.KeyPreview = $true
    $popup.BackColor = $steamUi.Panel
    $popup.Size = New-Object System.Drawing.Size($popupW, $popupH)
    $popup.Padding = New-Object System.Windows.Forms.Padding(1)

    Initialize-RomPickerTypes

    $borderPanel = New-Object System.Windows.Forms.Panel
    $borderPanel.Dock = [System.Windows.Forms.DockStyle]::Fill
    $borderPanel.BackColor = $steamUi.Border
    $borderPanel.Padding = New-Object System.Windows.Forms.Padding(1)
    $popup.Controls.Add($borderPanel)

    $body = New-Object System.Windows.Forms.Panel
    $body.Dock = [System.Windows.Forms.DockStyle]::Fill
    $body.BackColor = $steamUi.Panel
    $borderPanel.Controls.Add($body)

    $hdr = New-Object System.Windows.Forms.Label
    $hdr.Text = (T 'rom_popup_hdr')
    $hdr.Location = New-Object System.Drawing.Point(0, 6)
    $hdr.Size = New-Object System.Drawing.Size(($popupW - 4), 20)
    $hdr.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    $hdr.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
    $hdr.ForeColor = $steamUi.Muted
    $body.Controls.Add($hdr)

    $contentW = $gridW + $(if ($needScroll) { $dotsW } else { 0 })
    $flowLeft = [Math]::Max(0, [int](($popupW - 4 - $contentW) / 2))

    $viewport = New-Object System.Windows.Forms.Panel
    $viewport.Location = New-Object System.Drawing.Point($flowLeft, $hdrH)
    $viewport.Size = New-Object System.Drawing.Size($gridW, $visibleGridH)
    $viewport.BackColor = $steamUi.Panel
    $viewport.AutoScroll = $false
    try {
        $viewport.GetType().GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'Instance, NonPublic').SetValue($viewport, $true, $null)
    } catch {}
    $body.Controls.Add($viewport)

    $flow = New-Object System.Windows.Forms.FlowLayoutPanel
    $flow.Location = New-Object System.Drawing.Point(0, 0)
    $flow.Size = New-Object System.Drawing.Size($gridW, $gridH)
    $flow.AutoScroll = $false
    $flow.WrapContents = $true
    $flow.FlowDirection = [System.Windows.Forms.FlowDirection]::LeftToRight
    $flow.BackColor = $steamUi.Panel
    $flow.Padding = New-Object System.Windows.Forms.Padding($flowPad)
    $viewport.Controls.Add($flow)

    $dotsPanel = $null
    if ($needScroll) {
        $dotsPanel = New-Object System.Windows.Forms.Panel
        $dotsPanel.Size = New-Object System.Drawing.Size($dotsW, $visibleGridH)
        $dotsPanel.Location = New-Object System.Drawing.Point(($flowLeft + $gridW), $hdrH)
        $dotsPanel.BackColor = $steamUi.Panel
        $body.Controls.Add($dotsPanel)
    }

    $script:__emuPickerClosed = $false
    $script:__emuPickerChosenId = $null
    $script:__emuPickerFocus = 0
    $tileImages = New-Object System.Collections.Generic.List[object]
    $tilePanels = New-Object System.Collections.Generic.List[object]

    $selectEmulator = {
        param($id)
        $script:__emuPickerChosenId = [string]$id
        $script:__emuPickerClosed = $true
        try { $popup.Close() } catch {}
    }

    $colorActive = $steamUi.Selected
    $colorNormal = $steamUi.Panel2
    $colorHover = [System.Drawing.Color]::FromArgb(35, 52, 72)
    $colorFocus = [System.Drawing.Color]::FromArgb(45, 90, 130)

    $applyTileColors = {
        for ($i = 0; $i -lt $tilePanels.Count; $i++) {
            $tp = $tilePanels[$i]
            $isActive = ([string]$tp.Tag -eq [string]$global:activeEmulatorId)
            $isFocus = ($i -eq [int]$script:__emuPickerFocus)
            if ($isFocus) { $tp.BackColor = $colorFocus }
            elseif ($isActive) { $tp.BackColor = $colorActive }
            else { $tp.BackColor = $colorNormal }
            foreach ($c in $tp.Controls) {
                if ($c -is [System.Windows.Forms.Label]) {
                    $c.ForeColor = if ($isActive -or $isFocus) { $steamUi.Accent } else { $steamUi.Text }
                }
            }
        }
    }

    $goToPage = {
        param([int]$page)
        try {
            if ('EmuPickerWheel' -as [type]) {
                [EmuPickerWheel]::GoToPage($page)
                return
            }
        } catch {}
        if ($page -lt 0) { $page = 0 }
        if ($page -ge $pageCount) { $page = $pageCount - 1 }
        $flow.Top = -($page * $pageH)
        if ($null -ne $dotsPanel) { $dotsPanel.Invalidate() }
    }

    $getPage = {
        try {
            if ('EmuPickerWheel' -as [type]) { return [int][EmuPickerWheel]::Page }
        } catch {}
        return 0
    }

    $ensureFocusVisible = {
        $fi = [int]$script:__emuPickerFocus
        if ($fi -lt 0 -or $fi -ge $tilePanels.Count) { return }
        if ($pageCount -le 1) { return }
        $row = [int][Math]::Floor($fi / $cols)
        $targetPage = [int][Math]::Floor($row / [double]$maxVisibleRows)
        & $goToPage $targetPage
    }

    $moveFocus = {
        param([int]$deltaCol, [int]$deltaRow)
        $count = $tilePanels.Count
        if ($count -le 0) { return }
        $idx = [int]$script:__emuPickerFocus
        $col = $idx % $cols
        $row = [int][Math]::Floor($idx / $cols)
        $col = [Math]::Max(0, [Math]::Min($cols - 1, $col + $deltaCol))
        $row = [Math]::Max(0, $row + $deltaRow)
        $newIdx = ($row * $cols) + $col
        if ($newIdx -ge $count) { $newIdx = $count - 1 }
        if ($newIdx -lt 0) { $newIdx = 0 }
        $script:__emuPickerFocus = $newIdx
        & $applyTileColors
        & $ensureFocusVisible
    }

    if ($needScroll -and $null -ne $dotsPanel) {
        $dotsPanel.Add_Paint({
            param($s, $e)
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $n = [Math]::Max(1, $pageCount)
            $active = 0
            try { if ('EmuPickerWheel' -as [type]) { $active = [int][EmuPickerWheel]::Page } } catch {}
            if ($active -lt 0) { $active = 0 }
            if ($active -ge $n) { $active = $n - 1 }
            $thin = 5; $thick = 8; $dotGap = 12
            $totalH = 0
            for ($di = 0; $di -lt $n; $di++) {
                $totalH += $(if ($di -eq $active) { $thick } else { $thin })
                if ($di -lt $n - 1) { $totalH += $dotGap }
            }
            $y = [int](($s.Height - $totalH) / 2)
            $cx = [int]($s.Width / 2)
            for ($di = 0; $di -lt $n; $di++) {
                $isA = ($di -eq $active)
                $sz = if ($isA) { $thick } else { $thin }
                $col = if ($isA) { $steamUi.Accent } else { [System.Drawing.Color]::FromArgb(90, 100, 112) }
                $brush = New-Object System.Drawing.SolidBrush $col
                try { $g.FillEllipse($brush, ($cx - [int]($sz / 2)), $y, $sz, $sz) } finally { $brush.Dispose() }
                $y += $sz + $dotGap
            }
        }.GetNewClosure())
        $dotsPanel.Add_MouseClick({
            param($s, $e)
            $n = [Math]::Max(1, $pageCount)
            if ($n -le 1) { return }
            $thin = 5; $thick = 8; $dotGap = 12
            $active = 0
            try { if ('EmuPickerWheel' -as [type]) { $active = [int][EmuPickerWheel]::Page } } catch {}
            $totalH = 0
            for ($di = 0; $di -lt $n; $di++) {
                $totalH += $(if ($di -eq $active) { $thick } else { $thin })
                if ($di -lt $n - 1) { $totalH += $dotGap }
            }
            $acc = [int](($s.Height - $totalH) / 2)
            for ($di = 0; $di -lt $n; $di++) {
                $sz = if ($di -eq $active) { $thick } else { $thin }
                if ($e.Y -ge ($acc - 4) -and $e.Y -le ($acc + $sz + 4)) {
                    & $goToPage $di
                    return
                }
                $acc += $sz + $dotGap
            }
        }.GetNewClosure())
    }

    foreach ($ep in $profiles) {
        $isActive = ([string]$ep.Id -eq [string]$global:activeEmulatorId)
        $tile = New-Object System.Windows.Forms.Panel
        $tile.Size = New-Object System.Drawing.Size($tileW, $tileH)
        $tile.Margin = New-Object System.Windows.Forms.Padding($tileMargin)
        $tile.Cursor = [System.Windows.Forms.Cursors]::Hand
        $tile.BackColor = if ($isActive) { $colorActive } else { $colorNormal }
        $tile.Tag = [string]$ep.Id

        $pic = New-Object System.Windows.Forms.PictureBox
        $pic.Size = New-Object System.Drawing.Size(40, 40)
        $pic.Location = New-Object System.Drawing.Point([int](($tileW - 40) / 2), 10)
        $pic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
        $pic.BackColor = [System.Drawing.Color]::Transparent
        $pic.Cursor = [System.Windows.Forms.Cursors]::Hand
        try {
            $cachedIcon = Get-EmulatorIconBitmap $ep
            if ($null -ne $cachedIcon) {
                # Копия: общий Bitmap из кэша освобождать нельзя, а плитки при закрытии освобождаются.
                $bmp = New-Object System.Drawing.Bitmap($cachedIcon)
                $pic.Image = $bmp
                [void]$tileImages.Add($bmp)
            }
        } catch {}
        $tile.Controls.Add($pic)

        $nameLbl = New-Object System.Windows.Forms.Label
        $nameLbl.Text = [string]$ep.Name
        $nameLbl.Location = New-Object System.Drawing.Point(4, 54)
        $nameLbl.Size = New-Object System.Drawing.Size(($tileW - 8), 30)
        $nameLbl.TextAlign = [System.Drawing.ContentAlignment]::TopCenter
        $nameLbl.Font = New-Object System.Drawing.Font('Segoe UI', 8)
        $nameLbl.ForeColor = if ($isActive) { $steamUi.Accent } else { $steamUi.Text }
        $nameLbl.Cursor = [System.Windows.Forms.Cursors]::Hand
        $tile.Controls.Add($nameLbl)

        $capId = [string]$ep.Id
        $onTileClick = { & $selectEmulator $capId }.GetNewClosure()
        $tile.Add_Click($onTileClick)
        $pic.Add_Click($onTileClick)
        $nameLbl.Add_Click($onTileClick)

        $tile.Add_MouseEnter({
            $fi = [int]$script:__emuPickerFocus
            $thisIdx = -1
            for ($hi = 0; $hi -lt $tilePanels.Count; $hi++) {
                if ([object]::ReferenceEquals($tilePanels[$hi], $tile)) { $thisIdx = $hi; break }
            }
            if ($thisIdx -ge 0 -and $thisIdx -ne $fi) { $tile.BackColor = $colorHover }
        }.GetNewClosure())
        $tile.Add_MouseLeave({ & $applyTileColors }.GetNewClosure())

        [void]$flow.Controls.Add($tile)
        [void]$tilePanels.Add($tile)
    }

    $startFocus = 0
    for ($i = 0; $i -lt $tilePanels.Count; $i++) {
        if ([string]$tilePanels[$i].Tag -eq [string]$global:activeEmulatorId) { $startFocus = $i; break }
    }
    $script:__emuPickerFocus = $startFocus
    & $applyTileColors

    try {
        $indTopLeft = $pnlRomIndicator.PointToScreen([System.Drawing.Point]::Empty)
        $indCenterX = $indTopLeft.X + [int]($pnlRomIndicator.Width / 2)
        $indTop = $indTopLeft.Y
        $indBottom = $indTopLeft.Y + $pnlRomIndicator.Height
        $screen = [System.Windows.Forms.Screen]::FromControl($form)
        $wa = $screen.WorkingArea
        $centerX = $indCenterX - [int]($popupW / 2)
        if ($centerX + $popupW -gt $wa.Right) { $centerX = $wa.Right - $popupW - 8 }
        if ($centerX -lt $wa.Left) { $centerX = $wa.Left + 8 }
        $posYAbove = $indTop - $popupH - 6
        $posYBelow = $indBottom + 6
        if ($posYAbove -ge $wa.Top) { $posY = $posYAbove }
        elseif ($posYBelow + $popupH -le $wa.Bottom) { $posY = $posYBelow }
        else { $posY = [Math]::Max($wa.Top + 8, [Math]::Min($posYAbove, $wa.Bottom - $popupH - 8)) }
        $popup.Location = New-Object System.Drawing.Point($centerX, $posY)
    } catch {
        $popup.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterParent
    }

    $script:__emuPickerWheelObj = $null

    $popup.Add_Shown({
        try { [Win11PopupDwm]::Apply($popup.Handle) } catch {}
        try { $popup.Activate() } catch {}
        try {
            if ('EmuPickerWheel' -as [type]) {
                [EmuPickerWheel]::Flow = $flow
                [EmuPickerWheel]::Dots = $dotsPanel
                [EmuPickerWheel]::PageH = [int]$pageH
                [EmuPickerWheel]::PageCount = [int]$pageCount
                [EmuPickerWheel]::Page = 0
                [EmuPickerWheel]::Active = $true
                [EmuPickerWheel]::GoToPage(0)
                $script:__emuPickerWheelObj = New-Object EmuPickerWheel
                [System.Windows.Forms.Application]::AddMessageFilter($script:__emuPickerWheelObj)
            } else {
                $flow.Top = 0
            }
        } catch {
            try { $flow.Top = 0 } catch {}
        }
    }.GetNewClosure())

    $cleanupWheel = {
        try {
            if ('EmuPickerWheel' -as [type]) {
                [EmuPickerWheel]::Active = $false
                [EmuPickerWheel]::Flow = $null
                [EmuPickerWheel]::Dots = $null
            }
        } catch {}
        try {
            if ($null -ne $script:__emuPickerWheelObj) {
                [System.Windows.Forms.Application]::RemoveMessageFilter($script:__emuPickerWheelObj)
            }
        } catch {}
        $script:__emuPickerWheelObj = $null
    }.GetNewClosure()

    $popup.Add_Deactivate({
        if (-not $script:__emuPickerClosed) {
            $script:__emuPickerClosed = $true
            try { $popup.Close() } catch {}
        }
    })

    $popup.Add_KeyDown({
        $k = $_.KeyCode
        if ($k -eq [System.Windows.Forms.Keys]::Escape) {
            $script:__emuPickerClosed = $true
            $popup.Close()
            $_.Handled = $true
            return
        }
        if ($k -eq [System.Windows.Forms.Keys]::Enter -or $k -eq [System.Windows.Forms.Keys]::Space) {
            $fi = [int]$script:__emuPickerFocus
            if ($fi -ge 0 -and $fi -lt $tilePanels.Count) {
                & $selectEmulator ([string]$tilePanels[$fi].Tag)
            }
            $_.Handled = $true
            return
        }
        if ($k -eq [System.Windows.Forms.Keys]::Left)  { & $moveFocus -1  0; $_.Handled = $true; return }
        if ($k -eq [System.Windows.Forms.Keys]::Right) { & $moveFocus  1  0; $_.Handled = $true; return }
        if ($k -eq [System.Windows.Forms.Keys]::Up)    { & $moveFocus  0 -1; $_.Handled = $true; return }
        if ($k -eq [System.Windows.Forms.Keys]::Down)  { & $moveFocus  0  1; $_.Handled = $true; return }
        if ($k -eq [System.Windows.Forms.Keys]::Home)  {
            $script:__emuPickerFocus = 0
            & $applyTileColors
            & $goToPage 0
            $_.Handled = $true
            return
        }
        if ($k -eq [System.Windows.Forms.Keys]::End) {
            $script:__emuPickerFocus = [Math]::Max(0, $tilePanels.Count - 1)
            & $applyTileColors
            & $goToPage ($pageCount - 1)
            $_.Handled = $true
            return
        }
        if ($k -eq [System.Windows.Forms.Keys]::PageUp) {
            $p = 0
            try { $p = [int][EmuPickerWheel]::Page } catch {}
            & $goToPage ($p - 1)
            $_.Handled = $true
            return
        }
        if ($k -eq [System.Windows.Forms.Keys]::PageDown) {
            $p = 0
            try { $p = [int][EmuPickerWheel]::Page } catch {}
            & $goToPage ($p + 1)
            $_.Handled = $true
            return
        }
    })

    $popup.Add_FormClosed({
        & $cleanupWheel
        foreach ($img in $tileImages) {
            try { if ($null -ne $img) { $img.Dispose() } } catch {}
        }
    }.GetNewClosure())

    try {
        [void]$popup.ShowDialog($form)
    } finally {
        & $cleanupWheel
    }

    if (-not [string]::IsNullOrWhiteSpace([string]$script:__emuPickerChosenId)) {
        if ([string]$global:activeEmulatorId -ne [string]$script:__emuPickerChosenId) {
            $global:activeEmulatorId = [string]$script:__emuPickerChosenId
            try { Save-Configuration } catch {}
            try { Update-RomEmulatorIndicator } catch {}
            if ($script:romsModeEnabled) {
                try { $global:checkedC.Clear(); $global:checkedD.Clear() } catch {}
                try { Refresh-Panels } catch {}
                try { Update-MainLibraryButtonState } catch {}
            }
        } else {
            try { Update-RomEmulatorIndicator } catch {}
        }
    }
}

$showRomEmulatorQuickPick = { Show-RomEmulatorPickerPopup }
$pnlRomIndicator.Add_Click($showRomEmulatorQuickPick)
$picRomEmulatorIcon.Add_Click($showRomEmulatorQuickPick)
$lblRomEmulatorName.Add_Click($showRomEmulatorQuickPick)

# Центральная кнопка добавления — компактная и строго центрирована
# относительно окна, а не растянута до шестерёнки.
$btnAddToSteam = New-Object System.Windows.Forms.Button
$btnAddToSteam.Tag = (T 'btn_add_batch')
$btnAddToSteam.Text = ''
$btnAddToSteam.Location = New-Object System.Drawing.Point(260, 0)
$btnAddToSteam.Size = New-Object System.Drawing.Size(520, 42)
$btnAddToSteam.FlatStyle = "Flat"
$btnAddToSteam.FlatAppearance.BorderColor = $steamUi.Accent2
$btnAddToSteam.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(35,78,106)
$btnAddToSteam.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
$btnAddToSteam.ForeColor = $steamUi.Text
$btnAddToSteam.Font = New-Object System.Drawing.Font("Segoe UI Semibold", 10.5)
$btnAddToSteam.Image = $null
$btnAddToSteam.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
# Появляется только когда отмечено 2+ игры галочками (см. Update-MainLibraryButtonState) —
# для одной игры добавление идёт через клик по ней -> кнопку внутри её карточки.
$btnAddToSteam.Visible = $false
$pnlBatchActions.Controls.Add($btnAddToSteam)

# Кнопка «Библиотека Steam» на том же месте, что и пакетное добавление.
# Видна, когда нет отмеченных игр (кнопка добавления скрыта).
$btnSteamLibrary = New-Object System.Windows.Forms.Button
$btnSteamLibrary.Tag = (T 'btn_steam_library')
$btnSteamLibrary.Location = New-Object System.Drawing.Point(260, 0)
$btnSteamLibrary.Size = New-Object System.Drawing.Size(520, 42)
$btnSteamLibrary.FlatStyle = "Flat"
$btnSteamLibrary.FlatAppearance.BorderColor = $steamUi.Accent2
$btnSteamLibrary.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(35,78,106)
$btnSteamLibrary.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
$btnSteamLibrary.ForeColor = $steamUi.Text
$btnSteamLibrary.Font = New-Object System.Drawing.Font("Segoe UI Semibold", 10.5)
$btnSteamLibrary.Image = $null
$btnSteamLibrary.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
$btnSteamLibrary.Cursor = [System.Windows.Forms.Cursors]::Hand
$btnSteamLibrary.Visible = $true
$pnlBatchActions.Controls.Add($btnSteamLibrary)

Set-SplashProgress 0.77
# Кнопка настроек в стиле Steam.
# Используется отдельный PNG самого Steam-стиля, чтобы форма шестерёнки
# совпадала с визуальным эталоном, а не зависела от Unicode-шрифта Windows.
$btnSettings = New-Object System.Windows.Forms.Button
$btnSettings.Text = ''
$btnSettings.Location = New-Object System.Drawing.Point(992, 0)
$btnSettings.Size = New-Object System.Drawing.Size(48, 42)
$btnSettings.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
$btnSettings.FlatAppearance.BorderSize = 0
$btnSettings.FlatAppearance.MouseOverBackColor = $steamUi.Panel
$btnSettings.FlatAppearance.MouseDownBackColor = $steamUi.Panel
$btnSettings.BackColor = [System.Drawing.Color]::Transparent
$btnSettings.ForeColor = $steamUi.Text
# Steam-style gear icon is embedded so the button does not disappear when
# the script is launched from a location where the optional assets folder is absent.
$settingsGearBase64 = ''
$settingsIcon = $null
try {
    $gearBytes = [System.Convert]::FromBase64String($settingsGearBase64)
    $gearStream = New-Object System.IO.MemoryStream(,$gearBytes)
    $settingsIcon = [System.Drawing.Image]::FromStream($gearStream)
    $btnSettings.BackgroundImage = $settingsIcon
    $btnSettings.BackgroundImageLayout = [System.Windows.Forms.ImageLayout]::Center
} catch {
    $settingsIcon = $null
}
$btnSettings.Cursor = [System.Windows.Forms.Cursors]::Hand
$btnSettings.TabStop = $false
$btnSettings.AccessibleName = (T 'settings_title')
$btnSettings.AccessibleDescription = (T 'settings_desc')
$pnlBatchActions.Controls.Add($btnSettings)

$pnlBatchActions.Add_Resize({
    try {
        $btnAddToSteam.Left = [int](($pnlBatchActions.ClientSize.Width - $btnAddToSteam.Width) / 2)
        $btnSteamLibrary.Left = [int](($pnlBatchActions.ClientSize.Width - $btnSteamLibrary.Width) / 2)
        $btnSettings.Left = $pnlBatchActions.ClientSize.Width - $btnSettings.Width
    } catch {}
})

function Save-Configuration {
    try {
        $configData = @(
            "dirC=$($global:dirC)",
            "dirD=$($global:dirD)",
            "steamInstallPath=$($global:steamInstallPath)",
            "steamUserId=$($global:steamUserId)",
            "steamGridDbApiKey=$($global:steamGridDbApiKey)",
            "suggestGameLaunchers=$($global:suggestGameLaunchers)",
            "useExeIcons=$($global:useExeIcons)",
            "steamApiKey=$($global:steamApiKey)",
            "backupFolderPath=$($global:backupFolderPath)",
            "language=$($global:language)",
            "steamCoverRegion=$($global:steamCoverRegion)",
            "logoDefaultEnabled=$([bool]$global:logoDefaultEnabled)",
            "logoDefaultPosition=$($global:logoDefaultPosition)",
            "logoDefaultWidthPct=$(([double]$global:logoDefaultWidthPct).ToString([System.Globalization.CultureInfo]::InvariantCulture))",
            "logoDefaultHeightPct=$(([double]$global:logoDefaultHeightPct).ToString([System.Globalization.CultureInfo]::InvariantCulture))"
        )
        try {
            if ($global:emulatorProfiles -and @($global:emulatorProfiles).Count -gt 0) {
                $profilesForJson = @($global:emulatorProfiles | ForEach-Object {
                    @{ Id = [string]$_.Id; Name = [string]$_.Name; ExePath = [string]$_.ExePath; Args = [string]$_.Args; Extensions = [string]$_.Extensions; Core = [string]$_.Core; ExtractArchives = [bool]$_.ExtractArchives }
                })
                $configData += "emulatorProfiles=$((ConvertTo-Json $profilesForJson -Compress -Depth 4))"
            }
            if (-not [string]::IsNullOrWhiteSpace([string]$global:activeEmulatorId)) {
                $configData += "activeEmulatorId=$($global:activeEmulatorId)"
            }
        } catch {}
        $configData | Out-File $global:configPath -Encoding UTF8 -Force -ErrorAction SilentlyContinue
    } catch {}
}

$form.Add_FormClosing({ if ($script:moveInProgress) { $_.Cancel = $true; $labelHeader.Text = (T 'mv2_busy'); return }; Stop-StartupBackgroundJobs; Save-Configuration; Remove-TemporaryCovers })

# Игры, убранные из списка клавишей Delete. Это ТОЛЬКО скрытие в интерфейсе:
# папки на диске не трогаются. Действует до кнопки «Обновить» или перезапуска.
# Ключ включает путь корневой папки, поэтому при смене папки записи не путаются.
$global:hiddenGames = @{}

# Игры, отмеченные галочкой в панели (для «Перенести»/«Добавить несколько»).
# Карточка игры открывается двойным кликом по строке или клавишей Enter —
# одиночный клик только выделяет строку. Галочки — отдельный, независимый
# механизм именно для пакетных операций (перенос между панелями, добавление
# сразу нескольких игр).
# Ключ — очищенное имя игры (Clean-GameName), отдельно для каждой панели.
$global:checkedC = @{}
$global:checkedD = @{}
function Get-CheckedSet ([string]$source) {
    if ($source -eq 'C') { return $global:checkedC } else { return $global:checkedD }
}
function Get-CheckedGames {
    $result = @()
    foreach ($name in @($global:checkedC.Keys)) { $result += [PSCustomObject]@{Name=$name; Source='C'; Path=(Join-Path $global:dirC $name)} }
    foreach ($name in @($global:checkedD.Keys)) { $result += [PSCustomObject]@{Name=$name; Source='D'; Path=(Join-Path $global:dirD $name)} }
    # $global:checkedC/D — обычные Hashtable: порядок .Keys в них не определён, поэтому
    # без сортировки карточки в пакетном добавлении шли в случайном порядке.
    # Сортируем так же, как панели по умолчанию (Sort-Object -Property Name).
    return @($result | Sort-Object -Property Name)
}
# Возвращает профиль эмулятора (Id/Name/ExePath/Args/Extensions), выбранный
# сейчас как активный для режима ROMs, либо $null, если ничего не выбрано
# или сохранённый Id больше не существует в списке (эмулятор удалили).
function Get-ActiveEmulatorProfile {
    if ([string]::IsNullOrWhiteSpace([string]$global:activeEmulatorId)) { return $null }
    foreach ($ep in @($global:emulatorProfiles)) {
        if ([string]$ep.Id -eq [string]$global:activeEmulatorId) { return $ep }
    }
    return $null
}

# Расширения ROM активного эмулятора. В режиме ROMs это жёсткий фильтр
# содержимого обеих панелей.
# С -IncludeArchives и включённой у профиля галочке «Распаковывать архивы» к
# расширениям добавляются форматы архивов (Get-RomArchiveExtensions), чтобы
# архивы считались допустимыми ROM, даже если их нет в списке расширений.
# Если расширения профиля не заданы — фильтра нет вовсе (как и раньше).
function Get-ActiveEmulatorRomExtensions {
    param([switch]$IncludeArchives)
    try {
        $ep = Get-ActiveEmulatorProfile
        if ($null -eq $ep -or [string]::IsNullOrWhiteSpace([string]$ep.Extensions)) { return @() }
        $list = @([string]$ep.Extensions -split '[,;\s]+' |
            ForEach-Object { $_.Trim().TrimStart('.').ToLowerInvariant() } |
            Where-Object { $_ -ne '' } | Select-Object -Unique)
        if ($IncludeArchives -and (Test-EmulatorExtractArchives $ep)) {
            $list = @(@($list) + @(Get-RomArchiveExtensions) | Select-Object -Unique)
        }
        return $list
    } catch { return @() }
}
# Форматы архивов (без точки), которые умеет распаковывать лончер: .zip — встроенным
# .NET, .7z — 7zr/7-Zip, остальные — установленным 7-Zip/WinRAR
# (см. Get-RomArchiveExtractor и Test-RomArchiveNeedsExtract).
function Get-RomArchiveExtensions { return @('zip','7z','rar','tar','gz','tgz','bz2','xz') }
# Включена ли у профиля эмулятора галочка «Распаковывать архивы». Профили без
# поля ExtractArchives (старый конфиг) считаются выключенными.
function Test-EmulatorExtractArchives($ep) {
    try { if ($null -eq $ep) { return $false }; return [bool]$ep.ExtractArchives } catch { return $false }
}
# Название игры по имени ROM-файла: имя без расширения. Для архивов вида
# game.tar.gz / game.tar.xz убирается и внутреннее .tar.
function Get-RomFileTitle([string]$nameOrPath) {
    $n = [System.IO.Path]::GetFileNameWithoutExtension($nameOrPath)
    $e = [System.IO.Path]::GetExtension($nameOrPath).ToLowerInvariant()
    if (@('.gz','.bz2','.xz') -contains $e -and $n.ToLowerInvariant().EndsWith('.tar')) { $n = $n.Substring(0, $n.Length - 4) }
    return $n
}
# Определяет, является ли эмулятор (по имени профиля и/или пути к exe)
# RetroArch — у него нет фиксированного набора расширений/аргументов: и то,
# и другое зависит от выбранного ядра (libretro core), поэтому только для
# него в диалогах показывается отдельное поле выбора ядра.
function Test-IsRetroArchProfile([string]$name, [string]$exePath) {
    try {
        if (-not [string]::IsNullOrWhiteSpace($exePath)) {
            $exeName = [System.IO.Path]::GetFileNameWithoutExtension($exePath)
            if ($exeName -match '(?i)retroarch') { return $true }
        }
    } catch {}
    if (-not [string]::IsNullOrWhiteSpace($name) -and $name -match '(?i)retroarch') { return $true }
    return $false
}

# Список ядер RetroArch (libretro core), доступных для указанного exe:
# сканирует папку "cores" рядом с retroarch.exe на файлы *_libretro.dll и
# возвращает их имена без суффикса _libretro и без расширения — то есть
# именно то, что нужно подставить в "-L cores\<имя>_libretro.dll".
function Get-RetroArchCoreNames([string]$exePath) {
    try {
        if ([string]::IsNullOrWhiteSpace($exePath)) { return @() }
        $dir = [System.IO.Path]::GetDirectoryName($exePath)
        if ([string]::IsNullOrWhiteSpace($dir)) { return @() }
        $coresDir = Join-Path $dir 'cores'
        if (-not (Test-Path -LiteralPath $coresDir)) { return @() }
        return @(Get-ChildItem -LiteralPath $coresDir -Filter '*_libretro.dll' -File -ErrorAction SilentlyContinue |
            ForEach-Object { $_.BaseName -replace '(?i)_libretro$', '' } |
            Where-Object { $_ -ne '' } |
            Sort-Object -Unique)
    } catch { return @() }
}

# Настоящее отображаемое имя ядра (то, что показывает сам RetroArch в своём
# меню "Load Core"), а не имя файла *_libretro.dll. Берётся из поля
# "display_name" .info-файла ядра — RetroArch хранит эти файлы рядом с exe,
# либо в папке "info", либо в "cores\info" (оба варианта встречаются в
# реальных установках). Если .info-файл не найден или в нём нет этого поля,
# возвращается само имя файла ядра как есть (то же, что показывалось раньше).
function Get-RetroArchCoreDisplayName([string]$exePath, [string]$fileCoreName) {
    if ([string]::IsNullOrWhiteSpace($fileCoreName)) { return $fileCoreName }
    try {
        if (-not [string]::IsNullOrWhiteSpace($exePath)) {
            $dir = [System.IO.Path]::GetDirectoryName($exePath)
            if (-not [string]::IsNullOrWhiteSpace($dir)) {
                $infoCandidates = @(
                    (Join-Path $dir ('info\{0}_libretro.info' -f $fileCoreName)),
                    (Join-Path $dir ('cores\info\{0}_libretro.info' -f $fileCoreName))
                )
                foreach ($infoPath in $infoCandidates) {
                    if (Test-Path -LiteralPath $infoPath -PathType Leaf) {
                        $content = Get-Content -LiteralPath $infoPath -Raw -ErrorAction SilentlyContinue
                        if (-not [string]::IsNullOrWhiteSpace($content) -and $content -match '(?im)^\s*display_name\s*=\s*"(?<dn>[^"]*)"') {
                            $dn = $Matches['dn'].Trim()
                            if (-not [string]::IsNullOrWhiteSpace($dn)) { return $dn }
                        }
                    }
                }
            }
        }
    } catch {}
    return $fileCoreName
}

# Список ядер RetroArch для указанного exe в виде пар "имя файла ядра" (то,
# что реально подставляется в аргумент запуска, см. Get-RetroArchArgsTemplate)
# / "отображаемое имя" (то, что покажет сам список — как в самом RetroArch),
# отсортированный по отображаемому имени.
function Get-RetroArchCoreDisplayList([string]$exePath) {
    $result = New-Object System.Collections.Generic.List[object]
    foreach ($fileCore in @(Get-RetroArchCoreNames $exePath)) {
        $result.Add([PSCustomObject]@{
            FileCore    = $fileCore
            DisplayName = (Get-RetroArchCoreDisplayName $exePath $fileCore)
        })
    }
    return @($result | Sort-Object -Property DisplayName -CaseSensitive:$false)
}

# Собирает аргумент запуска RetroArch для конкретного ядра: "-L
# cores\<core>_libretro.dll {rom}" — плейсхолдер {rom} заменяется дальше как
# обычно в Format-EmulatorLaunchArgs.
function Get-RetroArchArgsTemplate([string]$core) {
    if ([string]::IsNullOrWhiteSpace($core)) { return '-f {rom}' }
    return ('-L cores\{0}_libretro.dll {{rom}}' -f $core)
}

# Встраивает параметр загрузки ядра ("-L cores\<ядро>_libretro.dll") в уже
# имеющуюся строку аргументов эмулятора, НЕ заменяя её целиком — параметр
# ядра дополняет то, что указано в настройках эмулятора, а не подменяет
# собой всё поле:
#   - если в строке уже есть параметр "-L ..._libretro.dll" (от ранее
#     выбранного ядра) — обновляется только он, остальной текст (в т.ч.
#     {rom} и любые собственные флаги пользователя) остаётся нетронутым;
#   - если такого параметра ещё нет — новый параметр ядра дописывается в
#     начало строки, перед уже существующими аргументами;
#   - если строка аргументов пуста — используется прежнее поведение
#     (Get-RetroArchArgsTemplate), с {rom} в конце;
#   - если ядро не выбрано (пустая строка) — ранее вписанный параметр "-L"
#     просто убирается из строки, а остальные аргументы сохраняются.
function Merge-RetroArchCoreArgs([string]$existingArgs, [string]$core) {
    $existingArgs = [string]$existingArgs
    $corePattern = '(?i)-L\s+"?(?:[^"\\/]*[\\/])*[^"\\/]+?_libretro\.dll"?'
    $hasCoreArg = $existingArgs -match $corePattern

    if ([string]::IsNullOrWhiteSpace($core)) {
        if (-not $hasCoreArg) { return $existingArgs }
        $result = $existingArgs -replace $corePattern, ''
        return ($result -replace '\s{2,}', ' ').Trim()
    }

    if ([string]::IsNullOrWhiteSpace($existingArgs)) {
        return Get-RetroArchArgsTemplate $core
    }

    $newCoreArg = '-L cores\{0}_libretro.dll' -f $core
    if ($hasCoreArg) {
        return ($existingArgs -replace $corePattern, $newCoreArg)
    }
    return ($newCoreArg + ' ' + $existingArgs.Trim())
}

# Собирает строку параметров запуска эмулятора для конкретного файла рома:
# {rom} в шаблоне заменяется на путь к рому в кавычках, а если плейсхолдера
# нет — путь просто дописывается в конец (как и описано в подсказке поля
# "Параметры" эмулятора в Настройках).
function Format-EmulatorLaunchArgs([string]$argsTemplate, [string]$romPath) {
    $quotedRom = '"' + $romPath + '"'
    if ([string]::IsNullOrWhiteSpace($argsTemplate)) { return $quotedRom }
    if ($argsTemplate -like '*{rom}*') { return $argsTemplate.Replace('{rom}', $quotedRom) }
    return ($argsTemplate.TrimEnd() + ' ' + $quotedRom)
}

# ===================== Запуск ROM из архивов =====================
# RetroArch сам открывает только .zip/.7z (и только если ядро это умеет), а ядрам
# с needs_fullpath и мультифайловым образам (.bin+.cue, .gdi) нужен настоящий файл.
# Для таких архивов ярлык Steam указывает на SCLauncher.exe: он распаковывает архив
# во временную папку, запускает RetroArch и удаляет папку после выхода.
# Остальные ROM запускаются напрямую, как и раньше.

# Данные .info ядра: supported_extensions и needs_fullpath.
function Get-RetroArchCoreInfo([string]$exePath, [string]$fileCore) {
    $r = [PSCustomObject]@{ Found = $false; Extensions = @(); NeedsFullpath = $null }
    try {
        if ([string]::IsNullOrWhiteSpace($exePath) -or [string]::IsNullOrWhiteSpace($fileCore)) { return $r }
        $dir = [System.IO.Path]::GetDirectoryName($exePath)
        if ([string]::IsNullOrWhiteSpace($dir)) { return $r }
        $cands = @((Join-Path $dir ('info\{0}_libretro.info' -f $fileCore)), (Join-Path $dir ('cores\info\{0}_libretro.info' -f $fileCore)))
        foreach ($infoPath in $cands) {
            if (-not (Test-Path -LiteralPath $infoPath -PathType Leaf)) { continue }
            $content = Get-Content -LiteralPath $infoPath -Raw -ErrorAction SilentlyContinue
            if ([string]::IsNullOrWhiteSpace($content)) { continue }
            $r.Found = $true
            if ($content -match '(?im)^\s*supported_extensions\s*=\s*"(?<v>[^"]*)"') {
                $r.Extensions = @($Matches['v'].Split('|') | ForEach-Object { $_.Trim().ToLowerInvariant() } | Where-Object { $_ })
            }
            if ($content -match '(?im)^\s*needs_fullpath\s*=\s*"?(?<v>[A-Za-z]+)"?') {
                $r.NeedsFullpath = ($Matches['v'].ToLowerInvariant() -eq 'true')
            }
            break
        }
    } catch {}
    return $r
}

# Установленный 7-Zip (7z.exe): Program Files и реестр. Пустая строка, если не найден.
function Get-InstalledSevenZip {
    $c = New-Object System.Collections.Generic.List[string]
    foreach ($base in @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramW6432)) {
        if (-not [string]::IsNullOrWhiteSpace($base)) { $c.Add((Join-Path $base '7-Zip\7z.exe')) }
    }
    foreach ($key in @('HKLM:\SOFTWARE\7-Zip', 'HKCU:\SOFTWARE\7-Zip', 'HKLM:\SOFTWARE\WOW6432Node\7-Zip')) {
        try {
            $k = Get-ItemProperty -Path $key -ErrorAction Stop
            foreach ($n in @('Path64', 'Path')) {
                $v = [string]$k.$n
                if (-not [string]::IsNullOrWhiteSpace($v)) { $c.Add((Join-Path $v '7z.exe')) }
            }
        } catch {}
    }
    foreach ($p in $c) { if (Test-Path -LiteralPath $p -PathType Leaf) { return $p } }
    return ''
}

# 7z.exe: установленный 7-Zip, иначе свой 7zr.exe в %APPDATA%\Steam Commander\7z
# (при $allowDownload скачивается один раз с 7-zip.org). 7zr умеет только .7z.
function Get-SevenZipPath([bool]$allowDownload) {
    $inst = Get-InstalledSevenZip
    if ($inst) { return $inst }
    $dir = Join-Path $global:appDataDir '7z'
    $own = Join-Path $dir '7zr.exe'
    if ((Test-Path -LiteralPath $own -PathType Leaf) -and ((Get-Item -LiteralPath $own).Length -gt 100000)) { return $own }
    if (-not $allowDownload) { return '' }
    $tmp = ''
    try {
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $tmp = Join-Path $dir ('7zr.' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.tmp')
        $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
        if (-not (Test-Path -LiteralPath $curl -PathType Leaf)) { $curl = 'curl.exe' }
        $p = Start-Process -FilePath $curl -ArgumentList @('-L', '-f', '-s', '--max-time', '90', '-o', ('"' + $tmp + '"'), 'https://www.7-zip.org/a/7zr.exe') -WindowStyle Hidden -PassThru
        while (-not $p.HasExited) {
            [System.Windows.Forms.Application]::DoEvents()
            if ($global:editorLoadAbortRequested) { try { $p.Kill() } catch {}; return '' }
            Start-Sleep -Milliseconds 80
        }
        if ($p.ExitCode -ne 0) { return '' }
        if (-not (Test-Path -LiteralPath $tmp -PathType Leaf)) { return '' }
        if ((Get-Item -LiteralPath $tmp).Length -lt 100000) { return '' }
        $hdr = [System.IO.File]::ReadAllBytes($tmp)
        if ($hdr[0] -ne 0x4D -or $hdr[1] -ne 0x5A) { return '' }
        Move-Item -LiteralPath $tmp -Destination $own -Force -ErrorAction Stop
        $tmp = ''
        return $own
    } catch { return '' } finally {
        if ($tmp) { try { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } catch {} }
    }
}

# Чем распаковывать архив с расширением $ext: 'builtin' (.zip, встроенный .NET),
# путь к 7z.exe / WinRAR, либо '' если распаковщика нет.
function Get-RomArchiveExtractor([string]$ext, [bool]$allowDownload) {
    $ext = ([string]$ext).ToLowerInvariant()
    if ($ext -eq '.zip') { return 'builtin' }
    if ($ext -eq '.7z') { return (Get-SevenZipPath $allowDownload) }
    $sz = Get-InstalledSevenZip
    if ($sz) { return $sz }
    if ($ext -eq '.rar') {
        foreach ($base in @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramW6432)) {
            if ([string]::IsNullOrWhiteSpace($base)) { continue }
            foreach ($n in @('WinRAR\UnRAR.exe', 'WinRAR\WinRAR.exe')) {
                $p = Join-Path $base $n
                if (Test-Path -LiteralPath $p -PathType Leaf) { return $p }
            }
        }
    }
    return ''
}

# Список файлов внутри архива без распаковки: .zip через System.IO.Compression, остальное через 7z l.
function Get-RomArchiveEntries([string]$archive, [string]$szPath) {
    $r = [PSCustomObject]@{ Ok = $false; Files = @(); Error = '' }
    try {
        $ext = [System.IO.Path]::GetExtension($archive).ToLowerInvariant()
        $names = New-Object System.Collections.Generic.List[string]
        if ($ext -eq '.zip') {
            Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
            $za = [System.IO.Compression.ZipFile]::OpenRead($archive)
            try {
                foreach ($e in $za.Entries) { if (-not $e.FullName.EndsWith('/')) { $names.Add([string]$e.FullName) } }
            } finally { $za.Dispose() }
            $r.Files = @($names.ToArray()); $r.Ok = $true
            return $r
        }
        if ([string]::IsNullOrWhiteSpace($szPath) -or -not (Test-Path -LiteralPath $szPath -PathType Leaf)) { $r.Error = '7z'; return $r }
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $szPath
        $psi.Arguments = ('l -slt -ba "' + $archive + '"')
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $p = [System.Diagnostics.Process]::Start($psi)
        $errTask = $p.StandardError.ReadToEndAsync()
        $outTask = $p.StandardOutput.ReadToEndAsync()
        # Пока 7z/rar читает архив, окно живое (DoEvents), а отмена пакета или закрытие карточки
        # (см. $global:editorLoadAbortRequested) убивают процесс сразу, не дожидаясь таймаута.
        $listDeadline = (Get-Date).AddSeconds(60)
        $listAborted = $false
        while (-not $p.HasExited) {
            [System.Windows.Forms.Application]::DoEvents()
            if ($global:editorLoadAbortRequested) { try { $p.Kill() } catch {}; $listAborted = $true; break }
            Start-Sleep -Milliseconds 30
            if ((Get-Date) -gt $listDeadline) { try { $p.Kill() } catch {}; $listAborted = $true; break }
        }
        try { [void]$p.WaitForExit(2000) } catch {}
        if ($listAborted) { $r.Error = '7z, cancelled'; return $r }
        $out = [string]$outTask.Result
        if ($p.ExitCode -gt 1) { $r.Error = ('7z, code ' + $p.ExitCode); return $r }
        $cur = $null; $isDir = $false
        foreach ($line in ($out -split "\r?\n")) {
            if ($line -match '^Path = (.*)$') {
                if ($null -ne $cur -and -not $isDir) { $names.Add($cur) }
                $cur = [string]$Matches[1]; $isDir = $false
            } elseif ($line -match '^Folder = \+') { $isDir = $true }
            elseif ($line -match '^Attributes = D') { $isDir = $true }
        }
        if ($null -ne $cur -and -not $isDir) { $names.Add($cur) }
        $r.Files = @($names.ToArray()); $r.Ok = $true
    } catch { $r.Error = [string]$_.Exception.Message }
    return $r
}

# Решение: нужна ли распаковка (правила из PLAN_rom_archives.md).
# Ok=$false — запускать нельзя (Reason — текст для пользователя).
function Test-RomArchiveNeedsExtract([string]$romPath, [string]$exePath, [string]$core) {
    $res = [PSCustomObject]@{ Ok = $true; Needs = $false; Reason = ''; Extensions = @(); Extractor = '' }
    $ext = [System.IO.Path]::GetExtension($romPath).ToLowerInvariant()
    if (@('.zip', '.7z', '.rar', '.tar', '.gz', '.tgz', '.bz2', '.xz') -notcontains $ext) { return $res }   # 1. не архив
    $info = Get-RetroArchCoreInfo $exePath $core
    $res.Extensions = @($info.Extensions)
    $bare = $ext.TrimStart('.')
    $openable = ($ext -eq '.zip' -or $ext -eq '.7z')
    if ($openable -and (@($info.Extensions) -contains $bare)) { return $res }                                # 2. ядро открывает архив само
    $res.Needs = $true
    $res.Extractor = [string](Get-RomArchiveExtractor $ext $true)
    if ([string]::IsNullOrWhiteSpace($res.Extractor)) {
        $res.Ok = $false
        if ($ext -eq '.7z') { $res.Reason = (T 'rom_arc_dl_fail') } else { $res.Reason = (T 'rom_arc_no_extractor' @($ext)) }
        return $res
    }
    if (-not $openable) { return $res }                                                                      # 4. формат RetroArch не поддерживает
    $list = Get-RomArchiveEntries $romPath $res.Extractor
    if (-not $list.Ok) { $res.Ok = $false; $res.Reason = (T 'rom_arc_list_fail' @([string]$list.Error)); return $res }
    $files = @($list.Files)
    $knownInfo = ($info.Found -and (@($info.Extensions).Count -gt 0) -and ($null -ne $info.NeedsFullpath))
    if ($knownInfo) {
        if (($info.NeedsFullpath -eq $false) -and $files.Count -eq 1) {                                      # 3. читается из памяти, один файл
            $fe = [System.IO.Path]::GetExtension([string]$files[0]).TrimStart('.').ToLowerInvariant()
            if (@($info.Extensions) -contains $fe) { $res.Needs = $false }
        }
        return $res
    }
    $res.Needs = (($files.Count -gt 1) -or ($ext -ne '.zip'))                                                # 5. нет данных .info
    return $res
}

# Оценка файла внутри архива: чем меньше, тем лучше. Приоритет: оригинальный дамп, затем регион USA.
# Не оригинал (+1000): хаки, плохие/пере-дампы, переводы, трейнеры, пиратки ([b] [h] [o] [f] [t] [p] [T+..], (Hack) и т.п.).
# Бета/прото/демо/альтернативы (+500). Перевыпуски (+20), ревизии (+5). Регион: USA 0, World 10, Europe 20, Japan 30, прочие 40.
function Get-RomEntryScore([string]$name) {
    $n = [System.IO.Path]::GetFileName(([string]$name).Replace('/', '\'))
    $score = 0
    if ($n -match '(?i)\[(?:b|h|o|f|t|p)\d*[a-z]?\]|\[T[+\-][^\]]*\]|\[cr[^\]]*\]|\([^)]*\b(?:hack|bootleg|pirate|unlicensed|unl|translated|translation|aftermarket|homebrew|trainer|patched)\b[^)]*\)|[\s._\-](?:romhack|kaizo)(?:[\s._\-]|$)') { $score += 1000 }
    elseif ($n -match '(?i)\[a\d*\]|\([^)]*\b(?:beta|proto|prototype|demo|sample|kiosk|promo|alt|alternate|debug|test|preview|not for resale|review)\b[^)]*\)') { $score += 500 }
    if ($n -match '(?i)\([^)]*\b(?:virtual console|switch online|collection|classic mini|rerelease|re-release|steam)\b[^)]*\)') { $score += 20 }
    if ($n -match '(?i)\(rev\s*\w+\)|\(v(?!1\.0\))\d[\w.]*\)') { $score += 5 }
    $region = 25
    if ($n -match '(?i)\([^)]*\b(?:USA|US|North America)\b[^)]*\)') { $region = 0 }
    elseif ($n -match '(?i)\([^)]*\bWorld\b[^)]*\)') { $region = 10 }
    elseif ($n -match '(?i)\([^)]*\b(?:Europe|UK|England)\b[^)]*\)') { $region = 20 }
    elseif ($n -match '(?i)\([^)]*\bJapan\b[^)]*\)') { $region = 30 }
    elseif ($n -match '(?i)\((?:[^)]*\b)?(?:Australia|Asia|Brazil|Canada|China|France|Germany|Italy|Korea|Netherlands|Russia|Spain|Sweden|Taiwan|Hong Kong|Scandinavia|Denmark|Finland|Norway|Poland|Portugal|Greece)\b[^)]*\)') { $region = 40 }
    elseif ($n -cmatch '\(([JUEWKAFGSIDNC]{1,4})\)') {
        $code = [string]$Matches[1]
        if ($code.Contains('U')) { $region = 0 } elseif ($code.Contains('W')) { $region = 10 } elseif ($code.Contains('E')) { $region = 20 } elseif ($code.Contains('J')) { $region = 30 } else { $region = 40 }
    }
    $score += $region
    if ($n -match '\[!\]') { $score -= 5 }
    if ($n -match '(?i)\.m3u$') { $score -= 1 }
    return $score
}

# Файлы архива, которые можно запускать: по расширениям эмулятора (если заданы), иначе без мусора
# (картинки, txt, патчи, сохранения). Если есть .cue/.gdi/.m3u — части образа (.bin/.img/треки) скрываются.
# Результат отсортирован: лучший (оригинал, USA) первым.
function Get-RomArchiveRomEntries([string[]]$files, [string]$extsCsv) {
    $arcExts = @(Get-RomArchiveExtensions)
    $exts = @(([string]$extsCsv) -split '[,;\s]+' | ForEach-Object { $_.Trim().TrimStart('.').ToLowerInvariant() } | Where-Object { $_ -and ($arcExts -notcontains $_) })
    $junk = @('txt','nfo','png','jpg','jpeg','gif','bmp','xml','dat','db','ini','url','html','htm','pdf','diz','sav','srm','state','ips','ups','bps','ppf','xdelta','sfv','md5','sha1','log','cfg','lst','m3u8','mp3','ogg','mid')
    $kept = New-Object System.Collections.Generic.List[string]
    foreach ($f0 in @($files)) {
        $f = ([string]$f0).Replace('/', '\')
        $e = [System.IO.Path]::GetExtension($f).TrimStart('.').ToLowerInvariant()
        if ([string]::IsNullOrEmpty($e)) { continue }
        if ($exts.Count -gt 0) { if ($exts -notcontains $e) { continue } } elseif ($junk -contains $e) { continue }
        $kept.Add($f)
    }
    $hasDisc = $false
    foreach ($f in $kept) { if (@('cue','gdi','m3u') -contains ([System.IO.Path]::GetExtension($f).TrimStart('.').ToLowerInvariant())) { $hasDisc = $true; break } }
    $parts = @('bin','img','raw','wav','flac','ape','sub','mp3','ogg')
    $res = New-Object System.Collections.Generic.List[object]
    foreach ($f in $kept) {
        $e = [System.IO.Path]::GetExtension($f).TrimStart('.').ToLowerInvariant()
        if ($hasDisc -and ($parts -contains $e)) { continue }
        $res.Add([PSCustomObject]@{ Path = $f; Score = [int](Get-RomEntryScore $f) })
    }
    return @($res | Sort-Object @{Expression={ [int]$_.Score }}, @{Expression={ [string]$_.Path }})
}

# Заменяет в списке кандидатов ROM каждый архив с несколькими ROM внутри на отдельные пункты
# "архив > файл" (ArchiveEntry — путь внутри архива). Лучший по Get-RomEntryScore идёт первым и
# автоматически выбирается. .7z/.rar листаются только если 7-Zip уже есть (скачивание не запускаем).
function Expand-RomArchiveCandidates($candidates, [string]$extsCsv) {
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($c in @($candidates)) {
        $added = $false
        try {
            $ext = [System.IO.Path]::GetExtension([string]$c.FullName).ToLowerInvariant()
            if ((@('.zip', '.7z', '.rar') -contains $ext) -and (Test-Path -LiteralPath ([string]$c.FullName) -PathType Leaf)) {
                $sz = ''
                if ($ext -ne '.zip') {
                    $sz = Get-InstalledSevenZip
                    if (-not $sz -and $ext -eq '.7z') {
                        $own = Join-Path (Join-Path $global:appDataDir '7z') '7zr.exe'
                        if (Test-Path -LiteralPath $own -PathType Leaf) { $sz = $own }
                    }
                }
                if ($ext -eq '.zip' -or $sz) {
                    $list = Get-RomArchiveEntries ([string]$c.FullName) $sz
                    if ($list.Ok) {
                        $entries = @(Get-RomArchiveRomEntries @($list.Files) $extsCsv)
                        if ($entries.Count -gt 1) {
                            $best = [int]$entries[0].Score
                            $unique = ([int]$entries[1].Score -gt $best)
                            $leafCount = @{}
                            foreach ($e in $entries) { $lk = [System.IO.Path]::GetFileName([string]$e.Path).ToLowerInvariant(); $leafCount[$lk] = 1 + [int]$leafCount[$lk] }
                            # Архив остаётся ОДНИМ пунктом списка ROM; файлы внутри него отдаются отдельным
                            # полем справа (ArchiveEntries). ArchiveEntry - текущий выбор (лучший по умолчанию).
                            $items = New-Object System.Collections.Generic.List[object]
                            for ($i = 0; $i -lt $entries.Count; $i++) {
                                $e = $entries[$i]
                                $leaf = [System.IO.Path]::GetFileName([string]$e.Path)
                                $shown = if ([int]$leafCount[$leaf.ToLowerInvariant()] -gt 1) { [string]$e.Path } else { $leaf }
                                $items.Add([PSCustomObject]@{ Path = [string]$e.Path; Name = [string]$shown; IsKnown = ([int]$e.Score -lt 500) })
                            }
                            $good0 = ([int]$entries[0].Score -lt 500)
                            $prio = 0
                            if ($unique -and $good0) { $prio = -100 } elseif (-not $good0) { $prio = 200 }
                            $goodCnt = @($items | Where-Object { $_.IsKnown }).Count
                            $out.Add([PSCustomObject]@{
                                FullName = [string]$c.FullName
                                Name = [string]$c.Name
                                IsKnown = [bool]$good0
                                RomPriority = $prio
                                IsPreferredExtension = $true
                                ArchiveEntry = [string]$entries[0].Path
                                ArchiveEntries = @($items.ToArray())
                                EntryConfident = [bool](($unique -and $good0) -or $goodCnt -le 1)
                            })
                            $added = $true
                        }
                    }
                }
            }
        } catch {}
        if (-not $added) { $out.Add($c) }
    }
    return @($out.ToArray())
}

# Параметры ярлыка SCLauncher.exe для ROM из архива.
function Format-SCLauncherRomArgs([string]$Archive, [string]$Emu, [string]$Core, [string]$Exts, [string]$Sz, [string]$Extra, [string]$Entry = '') {
    $r = ('--rom-archive "' + $Archive + '" --emu "' + $Emu + '" --core "' + $Core + '"')
    if (-not [string]::IsNullOrWhiteSpace($Entry)) { $r += (' --entry "' + $Entry.Replace('"', '') + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Exts)) { $r += (' --exts "' + $Exts + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Sz)) { $r += (' --sz "' + $Sz + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Extra)) { $r += (' --extra "' + $Extra.Replace('"', '\"') + '"') }
    return $r
}

# Строка в кавычках для командной строки Windows: " -> \", обратные слэши перед кавычкой удваиваются.
function ConvertTo-SCLauncherQuoted([string]$s) {
    $e = [regex]::Replace([string]$s, '(\\*)"', '$1$1\"')
    $e = [regex]::Replace($e, '(\\+)$', '$1$1')
    return ('"' + $e + '"')
}
# Параметры ярлыка SCLauncher.exe для ROM из архива у ОБЫЧНОГО эмулятора (не RetroArch):
# --args - шаблон параметров запуска эмулятора, {rom} заменяется на распакованный файл.
function Format-SCLauncherEmuArgs([string]$Archive, [string]$Emu, [string]$Template, [string]$Exts, [string]$Sz, [string]$Entry = '', [string]$Lang = 'en') {
    $r = ('--rom-archive "' + $Archive + '" --emu "' + $Emu + '" --args ' + (ConvertTo-SCLauncherQuoted $Template))
    if (-not [string]::IsNullOrWhiteSpace($Entry)) { $r += (' --entry "' + $Entry.Replace('"', '') + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Exts)) { $r += (' --exts "' + $Exts + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Sz)) { $r += (' --sz "' + $Sz + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Lang)) { $r += (' --lang "' + $Lang + '"') }
    return $r
}
# Шаблон параметров эмулятора из строки параметров карточки: путь к архиву (в кавычках или без)
# заменяется на {rom}. Если пути в строке нет - вернётся строка как есть (путь допишется в конец).
function Get-EmulatorArgsTemplateFromLaunch([string]$launchOptions, [string]$romPath) {
    $t = [string]$launchOptions
    if ([string]::IsNullOrWhiteSpace($t) -or [string]::IsNullOrWhiteSpace($romPath)) { return $t.Trim() }
    $q = '"' + $romPath + '"'
    if ($t.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
        return ([regex]::Replace($t, [regex]::Escape($q), '{rom}', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)).Trim()
    }
    return ([regex]::Replace($t, [regex]::Escape($romPath), '{rom}', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)).Trim()
}
# План ярлыка для ROM из архива у обычного эмулятора с включённой галочкой «Распаковывать архивы».
# Wrapped=$false - ром не архив, запускается напрямую. Ok=$false - причина в Reason.
function Get-EmulatorArchiveWrapPlan([string]$romPath, [string]$exePath, [string]$launchOptions, [string]$extsCsv, [string]$entry = '') {
    $plan = [PSCustomObject]@{ Wrapped = $false; Ok = $true; Exe = ''; Args = ''; Reason = '' }
    $ext = [System.IO.Path]::GetExtension($romPath).ToLowerInvariant()
    if (@(Get-RomArchiveExtensions) -notcontains $ext.TrimStart('.')) { return $plan }
    $extractor = [string](Get-RomArchiveExtractor $ext $true)
    if ([string]::IsNullOrWhiteSpace($extractor)) {
        $plan.Ok = $false
        if ($ext -eq '.7z') { $plan.Reason = (T 'rom_arc_dl_fail') } else { $plan.Reason = (T 'rom_arc_no_extractor' @($ext)) }
        return $plan
    }
    $wrapExe = Ensure-SCLauncherExe
    if ([string]::IsNullOrWhiteSpace($wrapExe)) { $plan.Ok = $false; $plan.Reason = (T 'st_launcher_wrap_fail'); return $plan }
    $szArg = ''
    if ($extractor -ne 'builtin') { $szArg = $extractor }
    $tpl = Get-EmulatorArgsTemplateFromLaunch $launchOptions $romPath
    # Расширения архивов в списке профиля нужны сканеру; для выбора рома ВНУТРИ архива они не годятся.
    $arcExts = @(Get-RomArchiveExtensions)
    $extsCsv = (@(([string]$extsCsv) -split '[,;\s]+' | ForEach-Object { $_.Trim().TrimStart('.').ToLowerInvariant() } | Where-Object { $_ -and ($arcExts -notcontains $_) }) -join ',')
    $plan.Wrapped = $true
    $plan.Exe = [string]$wrapExe
    $plan.Args = Format-SCLauncherEmuArgs $romPath $exePath $tpl $extsCsv $szArg $entry ([string]$global:language)
    return $plan
}

# План ярлыка для ROM RetroArch: Wrapped=$false — ярлык прямо на retroarch.exe (как раньше).
# $entry — файл, выбранный внутри архива с несколькими ROM: тогда распаковка нужна всегда
# (распаковывается только он и файлы, на которые он ссылается).
function Get-RomArchiveWrapPlan([string]$romPath, [string]$exePath, [string]$launchOptions, [string]$entry = '') {
    $plan = [PSCustomObject]@{ Wrapped = $false; Ok = $true; Exe = ''; Args = ''; Reason = '' }
    $corePattern = '(?i)-L\s+"?(?:[^"\\/]*[\\/])*(?<c>[^"\\/]+?)_libretro\.dll"?'
    $m = [regex]::Match([string]$launchOptions, $corePattern)
    if (-not $m.Success) { return $plan }
    $core = [string]$m.Groups['c'].Value
    # Сюда попадаем только при включённой галочке «Распаковывать архивы» у профиля RetroArch (без неё
    # вызывающий код ярлык на архив не оборачивает вовсе). Распаковка нужна не всегда: решение принимает
    # Test-RomArchiveNeedsExtract по .info ядра (читает ли ядро архив само). Исключение - выбранный файл
    # внутри архива с несколькими ROM ($entry): его нужно распаковать в любом случае.
    if (-not [string]::IsNullOrWhiteSpace($entry)) {
        $ext = [System.IO.Path]::GetExtension($romPath).ToLowerInvariant()
        $extractor = [string](Get-RomArchiveExtractor $ext $true)
        if ([string]::IsNullOrWhiteSpace($extractor)) {
            $plan.Ok = $false
            if ($ext -eq '.7z') { $plan.Reason = (T 'rom_arc_dl_fail') } else { $plan.Reason = (T 'rom_arc_no_extractor' @($ext)) }
            return $plan
        }
        $info = Get-RomArchiveCoreInfoSafe $exePath $core
        $chk = [PSCustomObject]@{ Ok = $true; Needs = $true; Extractor = $extractor; Extensions = @($info.Extensions) }
    } else {
        $chk = Test-RomArchiveNeedsExtract $romPath $exePath $core
        if (-not $chk.Ok) { $plan.Ok = $false; $plan.Reason = [string]$chk.Reason; return $plan }
        if (-not $chk.Needs) { return $plan }
    }
    $wrapExe = Ensure-SCLauncherExe
    if ([string]::IsNullOrWhiteSpace($wrapExe)) { $plan.Ok = $false; $plan.Reason = (T 'st_launcher_wrap_fail'); return $plan }
    $rest = [regex]::Replace([string]$launchOptions, $corePattern, '')
    $rest = $rest.Replace(('"' + $romPath + '"'), '')
    $rest = ($rest -replace '\s{2,}', ' ').Trim()
    $szArg = ''
    if ([string]$chk.Extractor -ne 'builtin') { $szArg = [string]$chk.Extractor }
    $plan.Wrapped = $true
    $plan.Exe = [string]$wrapExe
    $plan.Args = Format-SCLauncherRomArgs $romPath $exePath $core ((@($chk.Extensions)) -join ',') $szArg $rest $entry
    return $plan
}
function Get-RomArchiveCoreInfoSafe([string]$exePath, [string]$core) {
    try { return (Get-RetroArchCoreInfo $exePath $core) } catch { return [PSCustomObject]@{ Found = $false; Extensions = @(); NeedsFullpath = $null } }
}
# Прямоугольник галочки внутри строки списка: квадрат 14x14, вертикально
# отцентрирован, с отступом 8px от левого края строки.
function Get-RowCheckboxRect ($itemBounds) {
    $size = 14
    $x = $itemBounds.X + 8
    $y = $itemBounds.Y + [int](($itemBounds.Height - $size) / 2)
    return New-Object System.Drawing.Rectangle($x, $y, $size, $size)
}

# Кликабельная зона галочки — ЗНАЧИТЕЛЬНО больше самого квадратика 14x14.
# Раньше хит-тест использовал тот же тесный прямоугольник, что и отрисовка:
# промах на пару пикселей выше/ниже центра строки уходил в клик "по игре" и
# открывал карточку. Теперь зона занимает всю высоту строки (сверху донизу,
# без зазоров между соседними строками) и расширена по ширине — от левого
# края строки до отступа с запасом вокруг видимого квадратика.
function Get-RowCheckboxHitRect ($itemBounds) {
    $x = $itemBounds.X
    $y = $itemBounds.Y
    $width = 28
    $height = $itemBounds.Height
    return New-Object System.Drawing.Rectangle($x, $y, $width, $height)
}

function Get-HiddenGameKey ([string]$source, [string]$folderName) {
    $root = if ($source -eq 'C') { [string]$global:dirC } else { [string]$global:dirD }
    return ($root + '|' + $folderName).ToLowerInvariant()
}

# ===================== ПОИСК / СОРТИРОВКА ПО ПАНЕЛЯМ =====================
# Полные (нефильтрованные) списки игр каждой панели — заполняются в
# Refresh-Panels из диска, а строка поиска и сортировка дальше работают уже
# только с этим массивом в памяти, без повторного обращения к диску.
$script:panelDataC = @()
$script:panelDataD = @()
# Имя папки -> дата изменения; заполняется в Apply-PanelView, читается при отрисовке колонки "Дата".
$script:panelDateMapC = @{}
$script:panelDateMapD = @{}
$script:panelSearchC = ''
$script:panelSearchD = ''
$script:panelSortC = 'NameAsc'
$script:panelSortD = 'NameAsc'

# Кэш посчитанных размеров папок (полный путь -> байты), на всю сессию.
# Заполняется и клавишей Space (Show-SelectedGameSize), и сортировкой "по
# размеру" (Ensure-FolderSizesCached) — они делят один и тот же кэш, поэтому
# повторный подсчёт одной и той же папки не происходит.
$global:folderSizeCache = @{}

function Get-FolderSizeCached ([string]$path) {
    $key = $path.ToLowerInvariant()
    if ($global:folderSizeCache.ContainsKey($key)) { return [int64]$global:folderSizeCache[$key] }
    return -1
}

# Досчитывает размер только тех папок из переданного набора, которых ещё нет
# в кэше — со статусом и прогресс-баром главного окна (тот же DoEvents-приём,
# что и везде в этом файле), чтобы сортировка "по размеру" не выглядела так,
# будто программа зависла на большой библиотеке.
function Ensure-FolderSizesCached ($items) {
    $missing = @($items | Where-Object { $global:folderSizeCache.ContainsKey($_.Path.ToLowerInvariant()) -eq $false })
    if ($missing.Count -eq 0) { return }
    $prevText = $labelHeader.Text
    $prevValue = $progressBarFolder.Value
    $i = 0
    try {
        foreach ($item in $missing) {
            $i++
            $labelHeader.Text = (T 'st_sizes_sort' @($item.Name, $i, $missing.Count))
            $progressBarFolder.Value = [Math]::Min(100, [int](($i / $missing.Count) * 100))
            [System.Windows.Forms.Application]::DoEvents()
            try { $global:folderSizeCache[$item.Path.ToLowerInvariant()] = Get-FolderSize $item.Path } catch {}
        }
    } finally {
        $progressBarFolder.Value = $prevValue
        $labelHeader.Text = $prevText
    }
}

# Применяет текущие поиск+сортировку панели ($script:panelSearchX /
# $script:panelSortX) к уже загруженному в память $script:panelDataX и
# перерисовывает соответствующий ListBox. Диск заново НЕ читается — это
# отдельная, дешёвая операция от Refresh-Panels, вызывается при каждом
# нажатии в строке поиска и при смене сортировки.
function Apply-PanelView ([string]$source, [string[]]$forceSelectedNames = $null) {
    $listBox   = if ($source -eq 'C') { $listBoxC } else { $listBoxD }
    $data      = if ($source -eq 'C') { $script:panelDataC } else { $script:panelDataD }
    $search    = if ($source -eq 'C') { $script:panelSearchC } else { $script:panelSearchD }
    $sortMode  = if ($source -eq 'C') { $script:panelSortC } else { $script:panelSortD }

    # По умолчанию сохраняем то, что уже выделено в списке (сценарий смены
    # поиска/сортировки на живом списке). Refresh-Panels, где список в момент
    # вызова уже очищен, передаёт имена явно через $forceSelectedNames.
    $selectedNames = if ($null -ne $forceSelectedNames) { @($forceSelectedNames) } else { @($listBox.SelectedItems | ForEach-Object { [string]$_ }) }

    $view = @($data)
    if (-not [string]::IsNullOrWhiteSpace($search)) {
        $needle = $search.Trim()
        $view = @($view | Where-Object { $_.Name.IndexOf($needle, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 })
    }

    switch ($sortMode) {
        'NameDesc'    { $view = @($view | Sort-Object -Property Name -Descending) }
        'DateDesc'    { $view = @($view | Sort-Object -Property LastWriteTime -Descending) }
        'DateAsc'     { $view = @($view | Sort-Object -Property LastWriteTime) }
        'SizeDesc'    { Ensure-FolderSizesCached $view; $view = @($view | Sort-Object -Property @{Expression={ Get-FolderSizeCached $_.Path }} -Descending) }
        'SizeAsc'     { Ensure-FolderSizesCached $view; $view = @($view | Sort-Object -Property @{Expression={ Get-FolderSizeCached $_.Path }}) }
        'LibraryDesc' { $view = @($view | Sort-Object -Property @{Expression={ Test-PanelItemInLibrary $_.Name $_.Path }; Descending=$true}, @{Expression='Name'}) }
        'LibraryAsc'  { $view = @($view | Sort-Object -Property @{Expression={ Test-PanelItemInLibrary $_.Name $_.Path }}, @{Expression='Name'}) }
        default       { $view = @($view | Sort-Object -Property Name) }
    }

    $hasDirFlag = $false
    foreach ($it in $view) {
        if ($it.PSObject.Properties['IsDirectory']) { $hasDirFlag = $true; break }
    }
    if ($hasDirFlag) {
        $viewDirs  = @($view | Where-Object { $_.PSObject.Properties['IsDirectory'] -and $_.IsDirectory })
        $viewFiles = @($view | Where-Object { -not ($_.PSObject.Properties['IsDirectory'] -and $_.IsDirectory) })
        $view = @($viewDirs) + @($viewFiles)
    }

    $dateMap = @{}
    foreach ($it in $data) { $dateMap[[string]$it.Name] = $it.LastWriteTime }
    if ($source -eq 'C') { $script:panelDateMapC = $dateMap } else { $script:panelDateMapD = $dateMap }

    $listBox.BeginUpdate()
    try {
        $listBox.Items.Clear()
        foreach ($it in $view) {
            $listBox.Items.Add($it.Name) | Out-Null
            if ($selectedNames -contains $it.Name) {
                $listBox.SetSelected($listBox.Items.Count - 1, $true)
            }
        }
    } finally { $listBox.EndUpdate() }

    # Папки на диске есть (иначе список пуст по другой причине — папка ещё не
    # выбрана, это уже решает Refresh-Panels, сюда мы не лезем): показываем
    # либо сам список, либо "ничего не найдено", смотря что дал текущий поиск.
    $emptyLabel = if ($source -eq 'C') { $lblEmptyC } else { $lblEmptyD }
    if ($data.Count -gt 0) {
        try {
            if ($view.Count -eq 0) {
                $emptyLabel.Text = (T 'nothing_found' @($search))
                $emptyLabel.Visible = $true
                $listBox.Visible = $false
            } else {
                $emptyLabel.Visible = $false
                $listBox.Visible = $true
            }
        } catch {}
    }
    try { Update-MainLibraryButtonState } catch {}
    try { Update-SortHeaderUI $source } catch {}
}

# Файлы shortcuts.vdf: только userdata\config и userdata\<id>\config (так же, как в Get-LibDataFingerprint).
# Раньше везде стоял Get-ChildItem -Recurse по всему userdata, а там тысячи файлов обложек (grid) —
# после пакетного добавления это давало долгое зависание окна.
function Get-ShortcutsVdfFiles ([string]$userDataPath) {
    $res = New-Object System.Collections.Generic.List[System.IO.FileInfo]
    try {
        if ([string]::IsNullOrWhiteSpace($userDataPath) -or -not [System.IO.Directory]::Exists($userDataPath)) { return $res.ToArray() }
        $cands = New-Object System.Collections.Generic.List[string]
        [void]$cands.Add([System.IO.Path]::Combine($userDataPath, 'config', 'shortcuts.vdf'))
        foreach ($sub in [System.IO.Directory]::EnumerateDirectories($userDataPath)) {
            [void]$cands.Add([System.IO.Path]::Combine($sub, 'config', 'shortcuts.vdf'))
        }
        foreach ($c in $cands) {
            $fi = New-Object System.IO.FileInfo($c)
            if ($fi.Exists) { [void]$res.Add($fi) }
        }
    } catch {}
    return $res.ToArray()
}

# Метка тома и свободное место без WMI (Get-CimInstance на каждом обновлении панелей занимал заметное время).
function Get-DriveInfoQuick ([string]$root) {
    try {
        $di = New-Object System.IO.DriveInfo($root)
        if ($di.IsReady) { return [PSCustomObject]@{ VolumeName = [string]$di.VolumeLabel; FreeSpace = [double]$di.TotalFreeSpace } }
    } catch {}
    return (Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$root'" -ErrorAction SilentlyContinue)
}

function Refresh-Panels {
    # 1. Запоминаем имя выделенной игры на левой и правой панели перед очисткой.
    # Поиск и сортировку (панель, текст, режим) НЕ сбрасываем — «Обновить»
    # перечитывает диск, но не должен сбрасывать то, что пользователь ввёл
    # в строку поиска или выбрал в сортировке.
    $selectedNameC = $null; $selectedNameD = $null
    if ($listBoxC.SelectedItem -ne $null) { $selectedNameC = Clean-GameName $listBoxC.SelectedItem.ToString() }
    if ($listBoxD.SelectedItem -ne $null) { $selectedNameD = Clean-GameName $listBoxD.SelectedItem.ToString() }

    $listBoxC.Items.Clear(); $listBoxD.Items.Clear()
    # ГАЛОЧКИ (checkedC/checkedD) больше НЕ чистятся здесь безусловно.
    # Раньше Refresh-Panels вызывался в т.ч. просто при закрытии карточки игры
    # (открытой одиночным кликом по строке, без всякого сохранения) — и это
    # обнуляло весь пакетный выбор пользователя. Теперь отметки переживают
    # перечитывание диска; актуальность (что папка не пропала) проверяется
    # ниже, после того как $script:panelDataC/D снова заполнены с диска —
    # см. фильтрацию в конце функции. Явная очистка отметок, когда она
    # действительно нужна (после переноса/добавления выбранных игр или по
    # нажатию кнопки "Обновить"), делается в местах вызова, а не тут.
    $script:panelDataC = @()
    $script:panelDataD = @()

    # 2. Обе панели равноправны: каждая содержит обычную выбранную пользователем
    # папку. Нет основной/дополнительной папки и нет зависимости порядка выбора.
    $hasD = (-not [string]::IsNullOrWhiteSpace($global:dirD)) -and (Test-Path -LiteralPath $global:dirD -PathType Container)
    $hasC = (-not [string]::IsNullOrWhiteSpace($global:dirC)) -and (Test-Path -LiteralPath $global:dirC -PathType Container)

    $btnSelectC.Visible = $true
    $btnSelectD.Visible = $true
    $lblC.Visible = $true
    $lblD.Visible = $true
    $lblPathC.Visible = $true
    $lblPathD.Visible = $true

    if ($hasC) {
        try {
            $rtC = [System.IO.Path]::GetPathRoot($global:dirC).Substring(0,2)
            $driveC = Get-DriveInfoQuick $rtC
            # Вместо общего названия "Папка" показываем имя тома, как это делает Steam/Total Commander.
            # Если у диска нет метки, оставляем букву диска.
            $driveNameC = if ($driveC -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$driveC.VolumeName)) {
                "$($driveC.VolumeName) ($rtC)"
            } else { $rtC }
            $lblC.Text = if ($driveC -ne $null) { (T 'panel_free' @($driveNameC, ([string][Math]::Round($driveC.FreeSpace / 1GB, 2)), (T 'unit_gb'))) } else { $driveNameC }
        } catch {
            try { $lblC.Text = [System.IO.Path]::GetPathRoot($global:dirC).Substring(0,2) } catch { $lblC.Text = (T 'panel_extra') }
        }
        $lblPathC.Text = $global:dirC
        $lblEmptyC.Visible = $false
        $listBoxC.Visible = $true
    } else {
        $lblC.Text = (T 'panel_extra')
        $lblPathC.Text = ''
        $lblEmptyC.Text = (T 'empty_extra')
        $listBoxC.Visible = $false
        $lblEmptyC.Visible = $true
    }

    if ($hasD) {
        try {
            $rtD = [System.IO.Path]::GetPathRoot($global:dirD).Substring(0,2)
            $driveD = Get-DriveInfoQuick $rtD
            # Вместо общего названия "Папка" показываем имя тома, как это делает Steam/Total Commander.
            # Если у диска нет метки, оставляем букву диска.
            $driveNameD = if ($driveD -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$driveD.VolumeName)) {
                "$($driveD.VolumeName) ($rtD)"
            } else { $rtD }
            $lblD.Text = if ($driveD -ne $null) { (T 'panel_free' @($driveNameD, ([string][Math]::Round($driveD.FreeSpace / 1GB, 2)), (T 'unit_gb'))) } else { $driveNameD }
        } catch {
            try { $lblD.Text = [System.IO.Path]::GetPathRoot($global:dirD).Substring(0,2) } catch { $lblD.Text = (T 'panel_main') }
        }
        $lblPathD.Text = $global:dirD
        $lblEmptyD.Visible = $false
        $listBoxD.Visible = $true
    } else {
        $lblD.Text = (T 'panel_main')
        $lblPathD.Text = ''
        $lblEmptyD.Text = (T 'empty_main')
        $listBoxD.Visible = $false
        $lblEmptyD.Visible = $true
    }

    $foldersReady = $hasC -and $hasD
    $global:foldersReady = $foldersReady
    try { Update-MainLibraryButtonState } catch {}
    
    $global:installedSteamGames.Clear()
    $global:installedGameIcons.Clear()
    $script:installedGameIconCache.Clear()
    
    $steamPathProperty = Get-ConfiguredSteamExePath
    # Множество ShortcutId (appid), реально присутствующих в shortcuts.vdf прямо
    # сейчас. Собираем его тут же, попутно с обычным сканированием библиотеки —
    # отдельного прохода по файлу не требуется. Используется ниже, чтобы почистить
    # cover_sources от JSON-файлов игр, которых больше нет в Steam (см.
    # Remove-OrphanedCoverSourcesMetadata).
    $liveShortcutIds = @{}
    $shortcutsScanOk = $false
    if (-not [string]::IsNullOrEmpty($steamPathProperty)) {
        $steamPath = Get-ConfiguredSteamInstallPath
        $userDataPath = Get-ConfiguredSteamUserDataPath
        
        # ИСТОЧНИК 1: нестимовские ярлыки (shortcuts.vdf) — например, добавленные
        # этой же программой.
        # ВАЖНО: раньше здесь ЕЩЁ запоминали AppName ярлыка как признак "игра
        # установлена" — но AppName это просто отображаемое название, никак не
        # привязанное к конкретной папке на диске. Из-за этого папка с тем же
        # названием, что и уже добавленная игра (но реально лежащая в другом
        # месте, например на другом диске), ошибочно получала зелёную галочку
        # "уже в библиотеке". Поэтому единственный источник теперь — Exe и
        # StartDir, сопоставленные с известными корнями $dirC/$dirD: находим,
        # какая именно подпапка SSD- или HDD-библиотеки является началом этого
        # пути (см. Get-TopLevelFolderUnderRoot), и запоминаем ПОЛНЫЙ путь к ней
        # (а не просто имя) — это работает даже если .exe лежит на 3-4 уровня
        # глубже (Binaries\Win64\...), и при этом не путает две разные папки с
        # одинаковым именем.
        if (Test-Path $userDataPath) {
            # Раз мы дошли до реального сканирования shortcuts.vdf (файл userdata
            # найден и доступен), результат можно считать достоверным — даже если
            # ни одного shortcuts.vdf не нашлось (пустая библиотека нестимовских игр).
            $shortcutsScanOk = $true
            Get-ShortcutsVdfFiles $userDataPath | ForEach-Object {
                try {
                    $bytes = [System.IO.File]::ReadAllBytes($_.FullName)
                    if ($bytes.Length -gt 0) {
                        $shortcutsNode = Get-ShortcutsNode $bytes
                        if ($shortcutsNode -ne $null) {
                            foreach ($entry in $shortcutsNode.Body.Children) {
                                if ($entry.Type -ne 0x00) { continue }

                                # ShortcutId — это appid записи, тот же ID, которым именуются
                                # файлы метаданных обложек в $global:coverSourcesDir (см.
                                # Get-CoverSourcesMetadataPath). Запоминаем как "живой".
                                $appidField = $entry.Body.Children | Where-Object { $_.Key -eq "appid" } | Select-Object -First 1
                                if ($appidField -ne $null -and -not [string]::IsNullOrEmpty([string]$appidField.Value)) {
                                    $liveShortcutIds[[string]$appidField.Value] = $true
                                }

                                $exeField = $entry.Body.Children | Where-Object { $_.Key -eq "Exe" } | Select-Object -First 1
                                $startDirField = $entry.Body.Children | Where-Object { $_.Key -eq "StartDir" } | Select-Object -First 1

                                # ROM-ярлыки: Exe указывает на эмулятор (RetroArch и т.п.), а путь к
                                # конкретному ROM-файлу зашит в кавычках в LaunchOptions. Регистрируем
                                # ТОЧНЫЙ путь этого файла (без папки-родителя), если он лежит внутри
                                # одного из корней — тогда строка ROM-файла получает галочку.
                                $loField = $entry.Body.Children | Where-Object { $_.Key -eq "LaunchOptions" } | Select-Object -First 1
                                $romIconField = $entry.Body.Children | Where-Object { $_.Key -eq "icon" } | Select-Object -First 1
                                $romIconVal = if ($romIconField -ne $null) { [string]$romIconField.Value } else { '' }
                                if ($loField -ne $null -and -not [string]::IsNullOrEmpty([string]$loField.Value)) {
                                    foreach ($qm in [regex]::Matches([string]$loField.Value, '"([^"]+)"')) {
                                        $romCand = ([string]$qm.Groups[1].Value).Replace('/', '\')
                                        foreach ($rootPath in @($global:dirC, $global:dirD)) {
                                            if ([string]::IsNullOrEmpty($rootPath)) { continue }
                                            $rootPrefix = $rootPath.Trim('"').TrimEnd('\') + '\'
                                            if ($romCand.StartsWith($rootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                                                $global:installedSteamGames[(Get-NormalizedGamePathKey $romCand)] = $true
                                                Register-InstalledGameIconInfo $romCand $romIconVal '' '' $true
                                                # Игры вроде Wii U (Cemu): ROM лежит внутри папки игры
                                                # (Game\code\Game.rpx) — отмечаем и саму папку игры в корне.
                                                $romTop = Get-TopLevelFolderUnderRoot $romCand $rootPath
                                                if (-not [string]::IsNullOrEmpty($romTop)) {
                                                    $global:installedSteamGames[(Get-NormalizedGamePathKey (Join-Path $rootPath $romTop))] = $true
                                                    Register-InstalledGameIconInfo (Join-Path $rootPath $romTop) $romIconVal '' '' $true
                                                }
                                            }
                                        }
                                    }
                                }
                                $iconFieldForMap = $entry.Body.Children | Where-Object { $_.Key -eq "icon" } | Select-Object -First 1
                                $iconValForMap = if ($iconFieldForMap -ne $null) { [string]$iconFieldForMap.Value } else { '' }
                                $exeValForMap = if ($exeField -ne $null) { [string]$exeField.Value } else { '' }
                                $loValForMap = if ($loField -ne $null) { [string]$loField.Value } else { '' }
                                foreach ($pathField in @($exeField, $startDirField)) {
                                    if ($pathField -eq $null -or [string]::IsNullOrEmpty($pathField.Value)) { continue }
                                    $cleanFieldValue = ([string]$pathField.Value).Trim('"')
                                    foreach ($rootPath in @($global:dirC, $global:dirD)) {
                                        $topFolder = Get-TopLevelFolderUnderRoot $cleanFieldValue $rootPath
                                        if (-not [string]::IsNullOrEmpty($topFolder)) {
                                            $topFolderPath = Join-Path $rootPath $topFolder
                                            $global:installedSteamGames[(Get-NormalizedGamePathKey $topFolderPath)] = $true
                                            Register-InstalledGameIconInfo $topFolderPath $iconValForMap $exeValForMap $loValForMap
                                        }
                                    }
                                }
                            }
                        }
                    }
                } catch {}
            }
        }
    }

    # Метаданные источников обложек (cover_sources\<ShortcutId>.json) переживают
    # удаление игры из Steam: сам Steam ничего не знает про эти файлы и не может
    # их подчистить. Раз сканирование shortcuts.vdf выше прошло успешно, у нас
    # есть достоверный список ShortcutId, которые реально есть в библиотеке
    # прямо сейчас — всё остальное в cover_sources оставлено удалённой игрой.
    if ($shortcutsScanOk) { Remove-OrphanedCoverSourcesMetadata $liveShortcutIds }

    if ($script:romsModeEnabled) {
        # ROM-режим: панели показывают И ПАПКИ, И ROM-файлы в корне выбранного
        # каталога. Папки не фильтруются и остаются навигационными контейнерами;
        # из файлов показываем только расширения, заданные активному эмулятору.
        # Если пользователь открывает карточку папки — она сканируется целиком;
        # если выбирает конкретный ROM-файл — карточка получает именно этот файл.
        if ($hasC) {
            Get-ChildItem -LiteralPath $global:dirC -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'C' $fName))) { return }
                $script:panelDataC += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $true }
            }
        }
        if ($hasD) {
            Get-ChildItem -LiteralPath $global:dirD -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                if (-not [string]::IsNullOrEmpty($_.LinkType)) { return }
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'D' $fName))) { return }
                $script:panelDataD += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $true }
            }
        }

        # Если у активного эмулятора расширения не заданы — фильтра нет:
        # показываем файлы всех расширений (а не ни одного, как было раньше).
        $romExts = @(Get-ActiveEmulatorRomExtensions -IncludeArchives)
        $romExtSet = $null
        if ($romExts.Count -gt 0) {
            $romExtSet = New-Object 'System.Collections.Generic.HashSet[string]' ([string[]]$romExts, [System.StringComparer]::OrdinalIgnoreCase)
        }
        if ($hasC) {
            Get-ChildItem -LiteralPath $global:dirC -File -ErrorAction SilentlyContinue | ForEach-Object {
                $ext = $_.Extension.TrimStart('.').ToLowerInvariant()
                if ($romExtSet -ne $null -and -not $romExtSet.Contains($ext)) { return }
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'C' $fName))) { return }
                $script:panelDataC += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $false }
            }
        }
        if ($hasD) {
            Get-ChildItem -LiteralPath $global:dirD -File -ErrorAction SilentlyContinue | ForEach-Object {
                $ext = $_.Extension.TrimStart('.').ToLowerInvariant()
                if ($romExtSet -ne $null -and -not $romExtSet.Contains($ext)) { return }
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'D' $fName))) { return }
                $script:panelDataD += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $false }
            }
        }
    } else {
        $gameFileExts = New-Object 'System.Collections.Generic.HashSet[string]' (
            [string[]]@('exe','bat','cmd','com','lnk'),
            [System.StringComparer]::OrdinalIgnoreCase
        )
        if ($hasC) {
            Get-ChildItem -LiteralPath $global:dirC -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'C' $fName))) { return }
                $script:panelDataC += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $true }
            }
            Get-ChildItem -LiteralPath $global:dirC -File -ErrorAction SilentlyContinue | ForEach-Object {
                $ext = $_.Extension.TrimStart('.').ToLowerInvariant()
                if (-not $gameFileExts.Contains($ext)) { return }
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'C' $fName))) { return }
                $script:panelDataC += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $false }
            }
        }
        if ($hasD) {
            Get-ChildItem -LiteralPath $global:dirD -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                if (-not [string]::IsNullOrEmpty($_.LinkType)) { return }
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'D' $fName))) { return }
                $script:panelDataD += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $true }
            }
            Get-ChildItem -LiteralPath $global:dirD -File -ErrorAction SilentlyContinue | ForEach-Object {
                if (-not [string]::IsNullOrEmpty($_.LinkType)) { return }
                $ext = $_.Extension.TrimStart('.').ToLowerInvariant()
                if (-not $gameFileExts.Contains($ext)) { return }
                $fName = $_.Name
                if ($global:hiddenGames.ContainsKey((Get-HiddenGameKey 'D' $fName))) { return }
                $script:panelDataD += [PSCustomObject]@{ Name = $fName; Path = $_.FullName; LastWriteTime = $_.LastWriteTime; IsDirectory = $false }
            }
        }
    }

    # Строим сами списки (с учётом текущего поиска/сортировки панели) и
    # восстанавливаем выделение по именам, запомненным в начале функции.
    Apply-PanelView 'C' (@($selectedNameC) | Where-Object { $_ -ne $null })
    Apply-PanelView 'D' (@($selectedNameD) | Where-Object { $_ -ne $null })

    # Отметки, переживающие перечитывание диска (см. комментарий выше),
    # подчищаем только от того, чего реально больше нет в списке (папку
    # удалили/переименовали/скрыли) — остальные галочки остаются как были.
    $namesC = @{}; foreach ($it in $script:panelDataC) { $namesC[$it.Name] = $true }
    $namesD = @{}; foreach ($it in $script:panelDataD) { $namesD[$it.Name] = $true }
    foreach ($k in @($global:checkedC.Keys)) { if (-not $namesC.ContainsKey($k)) { $global:checkedC.Remove($k) | Out-Null } }
    foreach ($k in @($global:checkedD.Keys)) { if (-not $namesD.ContainsKey($k)) { $global:checkedD.Remove($k) | Out-Null } }

    # Ярлыки/игры могли измениться: если снимок библиотеки устарел — готовим новый в фоне (если актуален — ничего не делает).
    try { Request-LibPreheat 2000 } catch {}
    try { Update-MainLibraryButtonState } catch {}
}

function Show-ExeSelectionDialog ($exeList, $rootPath, $gameName) {
    $dialog = New-Object System.Windows.Forms.Form; $dialog.Text = (T 'exe_dlg_title' @($gameName)); $dialog.Size = "640, 400"; $dialog.StartPosition = "CenterParent"; $dialog.FormBorderStyle = "FixedDialog"; $dialog.MaximizeBox = $false; $dialog.MinimizeBox = $false
    $lbl = New-Object System.Windows.Forms.Label; $lbl.Text = (T 'exe_dlg_hint'); $lbl.Location = "15, 15"; $lbl.Size = "590, 20"; $lbl.Font = New-Object System.Drawing.Font("Arial", 9.5, [System.Drawing.FontStyle]::Bold); $dialog.Controls.Add($lbl)

    # Значки реального exe (а не абстрактный список путей) помогают сразу
    # отличить настоящую игру от служебных утилит — у игр, как правило,
    # свой уникальный значок, а у редистрибутивов/лаунчеров движка — типовой.
    $imageList = New-Object System.Windows.Forms.ImageList
    $imageList.ImageSize = New-Object System.Drawing.Size(28, 28)
    $imageList.ColorDepth = [System.Windows.Forms.ColorDepth]::Depth32Bit

    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = "15, 45"; $lv.Size = "590, 245"
    $lv.View = [System.Windows.Forms.View]::Details
    $lv.FullRowSelect = $true; $lv.MultiSelect = $false; $lv.HideSelection = $false
    $lv.SmallImageList = $imageList
    $lv.Columns.Add((T 'exe_dlg_col'), 555) | Out-Null
    $lv.Font = New-Object System.Drawing.Font("Consolas", 9.5)

    for ($i = 0; $i -lt $exeList.Count; $i++) {
        $exe = $exeList[$i]
        $relativePath = $exe.FullName.Substring($rootPath.Length); if (-not $relativePath.StartsWith("")) { $relativePath = "" + $relativePath }
        $imgKey = "icon$i"
        try {
            $ico = [System.Drawing.Icon]::ExtractAssociatedIcon($exe.FullName)
            if ($ico -ne $null) { $imageList.Images.Add($imgKey, $ico) }
        } catch {}
        $lvItem = New-Object System.Windows.Forms.ListViewItem
        $lvItem.Text = [string]$relativePath
        if ($imageList.Images.ContainsKey($imgKey)) { $lvItem.ImageKey = $imgKey }
        $lv.Items.Add($lvItem) | Out-Null
    }
    if ($lv.Items.Count -gt 0) { $lv.Items[0].Selected = $true }
    $dialog.Controls.Add($lv)

    $btn = New-Object System.Windows.Forms.Button; $btn.Text = (T 'exe_dlg_ok'); $btn.Location = "250, 300"; $btn.Size = "140, 35"; $btn.DialogResult = "OK"; $dialog.Controls.Add($btn); $dialog.AcceptButton = $btn
    if ($dialog.ShowDialog() -eq "OK" -and $lv.SelectedIndices.Count -gt 0) { return $exeList[$lv.SelectedIndices[0]] }
    return $null
}

# ===================== ПОИСК/РЕДАКТИРОВАНИЕ СУЩЕСТВУЮЩЕГО ЯРЛЫКА =====================
# $exePath (необязательный) — точное совпадение по пути к exe. Нужен проверке
# дубликатов при добавлении: там $gamePath — это папка exe (например ...\bin), а не
# корень игры, и сравнение по имени последней папки давало ложные "игра уже есть".
function Find-SteamShortcutRecord ($gameName, $gamePath = $null, $exePath = $null, $matchLaunchOptions = $null) {
    $steamPath = Get-ConfiguredSteamInstallPath
    $userDataPath = Get-ConfiguredSteamUserDataPath
    if (-not (Test-Path $userDataPath)) { return $null }

    $pathMatch = $null
    foreach ($shortcutsFile in (Get-ShortcutsVdfFiles $userDataPath)) {
        try {
            $bytes = [System.IO.File]::ReadAllBytes($shortcutsFile.FullName)
            if ($bytes.Length -eq 0) { continue }
            $shortcutsNode = Get-ShortcutsNode $bytes
            if ($shortcutsNode -eq $null) { continue }

            foreach ($entry in $shortcutsNode.Body.Children) {
                if ($entry.Type -ne 0x00) { continue }

                $fields = @{}
                foreach ($field in $entry.Body.Children) {
                    if ($field.Type -eq 0x01 -or $field.Type -eq 0x02) { $fields[$field.Key] = $field }
                }

                $appName = if ($fields.ContainsKey("AppName")) { [string]$fields["AppName"].Value } else { "" }
                $exe = if ($fields.ContainsKey("Exe")) { [string]$fields["Exe"].Value } else { "" }
                $startDir = if ($fields.ContainsKey("StartDir")) { [string]$fields["StartDir"].Value } else { "" }
                $launchOptions = if ($fields.ContainsKey("LaunchOptions")) { [string]$fields["LaunchOptions"].Value } else { "" }
                $cleanExe = $exe.Trim('"')
                $cleanStart = $startDir.Trim('"')
                $entryId = if ($fields.ContainsKey("appid")) { [string]$fields["appid"].Value } else { "" }

                $record = [PSCustomObject]@{
                    FilePath=[string]$shortcutsFile.FullName
                    UserDataDir=[string]$shortcutsFile.Directory.Parent.FullName
                    Entry=$entry
                    ShortcutId=$entryId
                    AppName=$appName
                    Exe=$cleanExe
                    StartDir=$cleanStart
                    LaunchOptions=$launchOptions
                }

                # ВАЖНО: раньше здесь было ещё и совпадение по одному лишь имени
                # (AppName ярлыка == искомое имя игры, без всякой проверки пути) —
                # из-за этого две РАЗНЫЕ папки с одинаковым названием (например,
                # вручную созданная тестовая папка на другом диске с тем же именем,
                # что и уже добавленная игра) считались одной и той же игрой.
                # Теперь совпадение ищем строго по реальному расположению на диске:
                # точный путь к .exe (если он передан) или сама папка игры должна
                # быть тем же путём (или содержать тот же путь), что Exe/StartDir
                # уже существующего ярлыка. Имя тут ни при чём.
                # ROMs/эмуляторы: Exe у ярлыка — это путь к самому эмулятору
                # (Yuzu и т.п.), и он ОДИНАКОВЫЙ у всех игр, запускаемых через
                # этот эмулятор. Совпадения одного Exe тут недостаточно, чтобы
                # считать игры дубликатом — иначе вторая же добавленная ROM-игра
                # с тем же эмулятором ошибочно принимается за уже существующую
                # первую. Если вызывающий код передал $launchOptions (в них
                # зашит путь к конкретному файлу рома — см. Format-EmulatorLaunchArgs),
                # то при совпадении Exe дополнительно сверяем и LaunchOptions;
                # различаются — значит это разные игры на одном эмуляторе.
                if (-not [string]::IsNullOrEmpty($exePath) -and -not [string]::IsNullOrEmpty($cleanExe) -and
                    [string]::Equals($cleanExe, ([string]$exePath).Trim('"'), [System.StringComparison]::OrdinalIgnoreCase)) {
                    if ([string]::IsNullOrEmpty($matchLaunchOptions) -or
                        [string]::Equals($matchLaunchOptions.Trim(), $record.LaunchOptions.Trim(), [System.StringComparison]::OrdinalIgnoreCase)) {
                        return $record
                    }
                }

                # ROM-файл: путь к нему зашит в кавычках в LaunchOptions существующего ярлыка.
                if (-not [string]::IsNullOrEmpty($gamePath) -and -not [string]::IsNullOrEmpty($launchOptions)) {
                    $gpKey = Get-NormalizedGamePathKey $gamePath
                    foreach ($qm2 in [regex]::Matches($launchOptions, '"([^"]+)"')) {
                        $qKey = Get-NormalizedGamePathKey ([string]$qm2.Groups[1].Value).Replace('/', '\')
                        if ($qKey -eq $gpKey -or ($gpKey -and $qKey.StartsWith($gpKey + '\'))) { return $record }
                    }
                }

                if (-not [string]::IsNullOrEmpty($gamePath)) {
                    try {
                        $gamePrefix = $gamePath.TrimEnd('\') + '\'
                        $gameExact = $gamePath.TrimEnd('\')
                        if ($cleanExe -and ($cleanExe.StartsWith($gamePrefix,[System.StringComparison]::OrdinalIgnoreCase) -or [string]::Equals($cleanExe.TrimEnd('\'), $gameExact, [System.StringComparison]::OrdinalIgnoreCase))) { $pathMatch=$record }
                        elseif ($cleanStart -and ($cleanStart.TrimEnd('\').Equals($gameExact,[System.StringComparison]::OrdinalIgnoreCase) -or $cleanStart.StartsWith($gamePrefix,[System.StringComparison]::OrdinalIgnoreCase))) { $pathMatch=$record }
                    } catch {}
                }
            }
        } catch {}
    }
    return $pathMatch
}

# ------------------------------------------------------------------
# Повторный поиск УЖЕ ИЗВЕСТНОГО ярлыка строго по его ID (поле appid в shortcuts.vdf).
# Нужен при сохранении карточки в режиме редактирования: между открытием карточки и
# сохранением Steam закрывается (taskkill), и запись надо перечитать с диска. Раньше для
# этого использовался Find-SteamShortcutRecord по ИМЕНИ и ПАПКЕ игры. У ROM-ярлыков
# «папка игры» - это общая папка с ромами, поэтому поиск возвращал ПЕРВЫЙ ярлык с ромом
# из этой папки - не обязательно редактируемый. Правки (имя, эмулятор, параметры, обложки)
# записывались в чужой ярлык: он превращался в копию, а оригинал оставался нетронутым.
# Если несколько записей имеют один и тот же appid (одинаковые эмулятор и название),
# выбирается та, у которой совпадают Exe и LaunchOptions с исходным ярлыком.
# ------------------------------------------------------------------
function Find-SteamShortcutRecordById ($reference) {
    if ($null -eq $reference) { return $null }
    $wantId = [string]$reference.ShortcutId
    if ([string]::IsNullOrWhiteSpace($wantId)) { return $null }
    $wantExe = ([string]$reference.Exe).Trim('"')
    $wantLaunch = ([string]$reference.LaunchOptions).Trim()
    $wantName = [string]$reference.AppName

    $files = @()
    $refFile = [string]$reference.FilePath
    if (-not [string]::IsNullOrWhiteSpace($refFile) -and (Test-Path -LiteralPath $refFile)) {
        $files = @(Get-Item -LiteralPath $refFile)
    } else {
        $userDataPath = Get-ConfiguredSteamUserDataPath
        if (-not (Test-Path $userDataPath)) { return $null }
        $files = @(Get-ShortcutsVdfFiles $userDataPath)
    }

    $best = $null; $bestScore = -1
    foreach ($shortcutsFile in $files) {
        try {
            $bytes = [System.IO.File]::ReadAllBytes($shortcutsFile.FullName)
            if ($bytes.Length -eq 0) { continue }
            $shortcutsNode = Get-ShortcutsNode $bytes
            if ($shortcutsNode -eq $null) { continue }
            foreach ($entry in $shortcutsNode.Body.Children) {
                if ($entry.Type -ne 0x00) { continue }
                $fields = @{}
                foreach ($field in $entry.Body.Children) {
                    if ($field.Type -eq 0x01 -or $field.Type -eq 0x02) { $fields[$field.Key] = $field }
                }
                $entryId = if ($fields.ContainsKey("appid")) { [string]$fields["appid"].Value } else { "" }
                if ($entryId -ne $wantId) { continue }

                $appName = if ($fields.ContainsKey("AppName")) { [string]$fields["AppName"].Value } else { "" }
                $exe = if ($fields.ContainsKey("Exe")) { [string]$fields["Exe"].Value } else { "" }
                $startDir = if ($fields.ContainsKey("StartDir")) { [string]$fields["StartDir"].Value } else { "" }
                $launchOptions = if ($fields.ContainsKey("LaunchOptions")) { [string]$fields["LaunchOptions"].Value } else { "" }
                $cleanExe = $exe.Trim('"')

                $score = 0
                if ([string]::Equals($cleanExe, $wantExe, [System.StringComparison]::OrdinalIgnoreCase)) { $score += 2 }
                if ([string]::Equals($launchOptions.Trim(), $wantLaunch, [System.StringComparison]::OrdinalIgnoreCase)) { $score += 4 }
                if ([string]::Equals($appName, $wantName, [System.StringComparison]::OrdinalIgnoreCase)) { $score += 1 }
                if ($score -le $bestScore) { continue }
                $bestScore = $score
                $best = [PSCustomObject]@{
                    FilePath=[string]$shortcutsFile.FullName
                    UserDataDir=[string]$shortcutsFile.Directory.Parent.FullName
                    Entry=$entry
                    ShortcutId=$entryId
                    AppName=$appName
                    Exe=$cleanExe
                    StartDir=$startDir.Trim('"')
                    LaunchOptions=$launchOptions
                }
            }
        } catch {}
    }
    return $best
}

# ------------------------------------------------------------------
# Определение "это ROM-ярлык?" по самому ярлыку из shortcuts.vdf —
# используется при открытии карточки игры из окна "Библиотека Steam",
# чтобы показать правильную карточку (с выбором эмулятора) независимо
# от текущего состояния переключателя "Режим ROMs" на главном экране.
# ------------------------------------------------------------------

# Ищет профиль эмулятора, чей ExePath совпадает с Exe уже существующего
# ярлыка. Если совпадение есть — этот ярлык запускает ROM через эмулятор.
function Get-EmulatorProfileByExePath ([string]$exePath) {
    if ([string]::IsNullOrWhiteSpace($exePath)) { return $null }
    $clean = $exePath.Trim('"')
    foreach ($p in @($global:emulatorProfiles)) {
        try {
            if ([string]::Equals([string]$p.ExePath, $clean, [System.StringComparison]::OrdinalIgnoreCase)) { return $p }
        } catch {}
    }
    return $null
}

# $entry — элемент из Get-SteamLibraryEntries (или любой объект с полем Exe).
function Test-ShortcutIsRomEntry ($entry) {
    if ($null -eq $entry) { return $false }
    return (Get-EmulatorProfileByExePath ([string]$entry.Exe)) -ne $null
}

# В LaunchOptions ROM-ярлыка зашит (в кавычках) путь к конкретному файлу
# рома — см. Format-EmulatorLaunchArgs. Если в шаблоне аргументов эмулятора
# есть и другие пути в кавычках (например, путь к конфигу), "первая
# существующая кавычка" может зацепить не тот файл — поэтому сначала пробуем
# восстановить путь ТОЧНО, через сам шаблон найденного эмулятора (обратная
# операция к Format-EmulatorLaunchArgs: где стоял {rom} — там и был ром).
# Принимает $entry — элемент из Get-SteamLibraryEntries (нужны Exe, чтобы
# найти профиль эмулятора, и LaunchOptions).
function Get-RomPathFromLaunchOptions ($entry) {
    $launchOptions = [string]$entry.LaunchOptions
    if ([string]::IsNullOrWhiteSpace($launchOptions)) { return '' }

    $profile = Get-EmulatorProfileByExePath ([string]$entry.Exe)
    if ($profile -ne $null) {
        $template = [string]$profile.Args
        try {
            if ([string]::IsNullOrWhiteSpace($template)) {
                # Пустой шаблон: Format-EmulatorLaunchArgs вернула ТОЛЬКО
                # закавыченный путь к рому — это и есть все LaunchOptions целиком.
                $only = $launchOptions.Trim()
                if ($only.Length -ge 2 -and $only.StartsWith('"') -and $only.EndsWith('"')) {
                    $candidate = $only.Substring(1, $only.Length - 2)
                    if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
                }
            } elseif ($template -like '*{rom}*') {
                # {rom} в шаблоне заменяется на закавыченный путь ровно один
                # раз — делим шаблон по этому маркеру на неизменную часть до
                # и после, и вырезаем из LaunchOptions то, что оказалось между
                # ними (это и есть подставленный путь к рому).
                $parts = $template.Split(@('{rom}'), 2, [System.StringSplitOptions]::None)
                $pattern = '^' + [regex]::Escape($parts[0]) + '"(.+)"' + [regex]::Escape($parts[1]) + '$'
                $m = [regex]::Match($launchOptions, $pattern)
                if ($m.Success) {
                    $candidate = $m.Groups[1].Value
                    if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
                }
            } else {
                # {rom} в шаблоне нет — Format-EmulatorLaunchArgs дописывает
                # закавыченный путь к рому в самый конец строки.
                $m = [regex]::Match($launchOptions, '"([^"]+)"\s*$')
                if ($m.Success) {
                    $candidate = $m.Groups[1].Value
                    if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
                }
            }
        } catch {}
    }

    # Запасной вариант — эмулятор не опознан или разбор по шаблону не дал
    # результата (шаблон с тех пор поменяли и т.п.): берём первую кавычную
    # подстроку, которая реально существует на диске, как и раньше.
    foreach ($m in [regex]::Matches($launchOptions, '"([^"]+)"')) {
        $candidate = [string]$m.Groups[1].Value
        try { if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate } } catch {}
    }
    return ''
}

# Лёгкий индекс ярлыков (Exe/StartDir/LaunchOptions) по каждому shortcuts.vdf. Файл разбирается один раз и
# кэшируется по размеру и времени изменения: раньше проверка «уже в Steam» заново разбирала весь файл для
# КАЖДОЙ отмеченной игры (~1 с на игру), и окно висело до появления первой карточки.
$script:shortcutLightIndexCache = @{}
function Get-ShortcutLightIndex {
    $all = New-Object System.Collections.Generic.List[object]
    $userDataPath = Get-ConfiguredSteamUserDataPath
    if ([string]::IsNullOrWhiteSpace([string]$userDataPath) -or -not (Test-Path $userDataPath)) { return $all.ToArray() }
    foreach ($f in (Get-ShortcutsVdfFiles $userDataPath)) {
        $sig = [string]$f.Length + '|' + [string]$f.LastWriteTimeUtc.Ticks
        $cached = $script:shortcutLightIndexCache[[string]$f.FullName]
        if ($null -ne $cached -and [string]$cached.Sig -eq $sig) {
            $all.AddRange([object[]]$cached.Rows)
            continue
        }
        $rows = New-Object System.Collections.Generic.List[object]
        try {
            $bytes = [System.IO.File]::ReadAllBytes($f.FullName)
            if ($bytes.Length -gt 0) {
                $node = Get-ShortcutsNode $bytes
                if ($null -ne $node) {
                    foreach ($entry in $node.Body.Children) {
                        if ($entry.Type -ne 0x00) { continue }
                        $fields = @{}
                        foreach ($field in $entry.Body.Children) {
                            if ($field.Type -eq 0x01 -or $field.Type -eq 0x02) { $fields[$field.Key] = $field }
                        }
                        $exe = if ($fields.ContainsKey('Exe')) { ([string]$fields['Exe'].Value).Trim('"') } else { '' }
                        $startDir = if ($fields.ContainsKey('StartDir')) { ([string]$fields['StartDir'].Value).Trim('"') } else { '' }
                        $lo = if ($fields.ContainsKey('LaunchOptions')) { [string]$fields['LaunchOptions'].Value } else { '' }
                        $quoted = New-Object System.Collections.Generic.List[string]
                        if (-not [string]::IsNullOrEmpty($lo)) {
                            foreach ($qm in [regex]::Matches($lo, '"([^"]+)"')) {
                                [void]$quoted.Add((Get-NormalizedGamePathKey ([string]$qm.Groups[1].Value).Replace('/', '\')))
                            }
                        }
                        [void]$rows.Add([PSCustomObject]@{ Exe = $exe; StartDir = $startDir; Quoted = $quoted.ToArray() })
                    }
                }
            }
        } catch {}
        $script:shortcutLightIndexCache[[string]$f.FullName] = [PSCustomObject]@{ Sig = $sig; Rows = $rows.ToArray() }
        $all.AddRange([object[]]$rows.ToArray())
    }
    return $all.ToArray()
}

function Test-GameAlreadyInSteamLibrary ($gameName, $gamePath = $null) {
    # Только реальное расположение на диске (как в Find-SteamShortcutRecord), имя не учитывается.
    if ([string]::IsNullOrEmpty($gamePath)) { return $false }
    try {
        $gpKey = Get-NormalizedGamePathKey $gamePath
        $gamePrefix = ([string]$gamePath).TrimEnd('\') + '\'
        $gameExact = ([string]$gamePath).TrimEnd('\')
        foreach ($r in @(Get-ShortcutLightIndex)) {
            foreach ($qKey in @($r.Quoted)) {
                if ($qKey -eq $gpKey -or ($gpKey -and $qKey.StartsWith($gpKey + '\'))) { return $true }
            }
            $ex = [string]$r.Exe; $sd = [string]$r.StartDir
            if ($ex -and ($ex.StartsWith($gamePrefix, [System.StringComparison]::OrdinalIgnoreCase) -or [string]::Equals($ex.TrimEnd('\'), $gameExact, [System.StringComparison]::OrdinalIgnoreCase))) { return $true }
            if ($sd -and ($sd.TrimEnd('\').Equals($gameExact, [System.StringComparison]::OrdinalIgnoreCase) -or $sd.StartsWith($gamePrefix, [System.StringComparison]::OrdinalIgnoreCase))) { return $true }
        }
        return $false
    } catch {
        return [bool](Find-SteamShortcutRecord $gameName $gamePath)
    }
}

function Set-VdfStringField ($entry, $key, $value) {
    $field = $entry.Body.Children | Where-Object { $_.Key -eq $key } | Select-Object -First 1
    if ($field -ne $null) {
        if ($field.Type -ne 0x01) { throw (T 'vdf_bad_type_key' @($key)) }
        $field.Value = [string]$value
        return
    }
    $entry.Body.Children.Add([PSCustomObject]@{Key=$key;Type=0x01;Value=[string]$value})
}

function Write-VdfChildrenBytes ($children) {
    $out = New-Object System.Collections.Generic.List[byte]
    foreach ($child in $children) {
        if ($child.Type -eq 0x00) {
            $out.Add(0x00)
            $out.AddRange([byte[]][System.Text.Encoding]::UTF8.GetBytes([string]$child.Key))
            $out.Add(0x00)
            $out.AddRange([byte[]](Write-VdfChildrenBytes $child.Body.Children))
            $out.Add(0x08)
        } elseif ($child.Type -eq 0x01) {
            $out.Add(0x01)
            $out.AddRange([byte[]][System.Text.Encoding]::UTF8.GetBytes([string]$child.Key))
            $out.Add(0x00)
            $out.AddRange([byte[]][System.Text.Encoding]::UTF8.GetBytes([string]$child.Value))
            $out.Add(0x00)
        } elseif ($child.Type -eq 0x02) {
            $out.Add(0x02)
            $out.AddRange([byte[]][System.Text.Encoding]::UTF8.GetBytes([string]$child.Key))
            $out.Add(0x00)
            $out.AddRange([byte[]][BitConverter]::GetBytes([uint32]$child.Value))
        } else {
            throw (T 'vdf_bad_type' @(([int]$child.Type).ToString('X2')))
        }
    }
    # БАГ-ФИКС: "return $out" разворачивает List[byte] в отдельные элементы
    # потока вывода PowerShell. Для непустых узлов это случайно давало верный
    # массив байт, но для узла без единого дочернего элемента (например,
    # почти всегда пустой объект "tags") в конвейер попадало НОЛЬ элементов,
    # и вызывающий код получал $null вместо пустого массива байт. Дальше
    # "$out.AddRange($null)" падал с "Значение не может быть неопределенным",
    # редактирование карточки не сохранялось, и окно не закрывалось.
    # Унарная запятая заставляет PowerShell вернуть ровно один объект —
    # массив байт, даже если он пустой.
    return ,$out.ToArray()
}

function Write-VdfFileBytes ($rootChildren) {
    $out = New-Object System.Collections.Generic.List[byte]
    $out.AddRange([byte[]](Write-VdfChildrenBytes $rootChildren))
    $out.Add(0x08)
    return ,$out.ToArray()
}

function Update-ExistingSteamShortcut ($shortcutRecord, $newName, $newExePath, $newStartDir, $newLaunchOptions) {
    if ($shortcutRecord -eq $null) { $global:lastShortcutError=(T 'sc_not_found'); return $null }
    try {
        $filePath=[string]$shortcutRecord.FilePath
        if (-not (Test-Path $filePath)) { throw (T 'sc_file_missing' @($filePath)) }

        # Авто-бэкап перед изменением файла (см. Create-AutoShortcutBackup).
        Create-AutoShortcutBackup $filePath | Out-Null

        $bytes=[System.IO.File]::ReadAllBytes($filePath)
        $root=Read-VdfObjectBody $bytes 0
        $shortcutsNode=$root.Children | Where-Object { $_.Key -eq "shortcuts" } | Select-Object -First 1
        if ($shortcutsNode -eq $null) { throw (T 'sc_no_node') }

        # appid у ярлыков считается по Exe+названию, поэтому у двух ROM одного эмулятора
        # с одинаковым названием он может совпасть. Тогда берём ту запись, у которой
        # совпадают Exe и LaunchOptions с редактируемым ярлыком, а не первую попавшуюся.
        $targetEntry=$null; $targetScore=-1
        foreach($entry in $shortcutsNode.Body.Children){
            if($entry.Type -ne 0x00){continue}
            $appidField=$entry.Body.Children | Where-Object { $_.Key -eq "appid" } | Select-Object -First 1
            if($appidField -eq $null -or [string]$appidField.Value -ne [string]$shortcutRecord.ShortcutId){continue}
            $score=0
            $exeField=$entry.Body.Children | Where-Object { $_.Key -eq "Exe" } | Select-Object -First 1
            $loField=$entry.Body.Children | Where-Object { $_.Key -eq "LaunchOptions" } | Select-Object -First 1
            if($exeField -ne $null -and [string]::Equals(([string]$exeField.Value).Trim('"'),([string]$shortcutRecord.Exe).Trim('"'),[System.StringComparison]::OrdinalIgnoreCase)){$score+=2}
            if($loField -ne $null -and [string]::Equals(([string]$loField.Value).Trim(),([string]$shortcutRecord.LaunchOptions).Trim(),[System.StringComparison]::OrdinalIgnoreCase)){$score+=4}
            if($score -gt $targetScore){$targetScore=$score;$targetEntry=$entry}
        }
        if($targetEntry -eq $null){throw (T 'sc_target_gone')}

        Set-VdfStringField $targetEntry "AppName" $newName
        Set-VdfStringField $targetEntry "Exe" ('"' + [string]$newExePath + '"')
        Set-VdfStringField $targetEntry "StartDir" ('"' + [string]$newStartDir + '"')
        Set-VdfStringField $targetEntry "LaunchOptions" ([string]$newLaunchOptions)

        $iconField=$targetEntry.Body.Children | Where-Object { $_.Key -eq "icon" } | Select-Object -First 1
        $iconVal = ''
        try {
            $gridIcon = Join-Path (Join-Path ([string]$shortcutRecord.UserDataDir) 'config\grid') ([string]$shortcutRecord.ShortcutId + '_icon.png')
            $tempIcon = Get-TempIconPath
            if ($null -ne $tempIcon -and (Test-Path -LiteralPath $tempIcon)) {
                $iconExt = [System.IO.Path]::GetExtension($tempIcon)
                if ([string]::IsNullOrWhiteSpace($iconExt)) { $iconExt = '.png' }
                $gridIcon = Join-Path (Join-Path ([string]$shortcutRecord.UserDataDir) 'config\grid') ([string]$shortcutRecord.ShortcutId + '_icon' + $iconExt)
                $gridParent = Split-Path $gridIcon -Parent
                if (-not (Test-Path -LiteralPath $gridParent)) {
                    New-Item -ItemType Directory -Path $gridParent -Force | Out-Null
                }
                Copy-Item -LiteralPath $tempIcon -Destination $gridIcon -Force -ErrorAction SilentlyContinue
            }
            if (-not [string]::IsNullOrWhiteSpace($gridIcon) -and (Test-Path -LiteralPath $gridIcon)) { $iconVal = $gridIcon }
            elseif ($null -ne $tempIcon -and (Test-Path -LiteralPath $tempIcon)) { $iconVal = $tempIcon }
        } catch { $iconVal = '' }
        try {
            if ($iconField -ne $null -and $iconField.Type -eq 0x01) {
                $iconField.Value = [string]$iconVal
            } elseif (-not [string]::IsNullOrWhiteSpace($iconVal)) {
                Set-VdfStringField $targetEntry 'icon' $iconVal
            }
        } catch {}

        [System.IO.File]::WriteAllBytes($filePath,(Write-VdfFileBytes $root.Children))
        Save-Configuration
        return [string]$shortcutRecord.ShortcutId
    } catch {
        $global:lastShortcutError=$_.Exception.Message
        return $null
    }
}

function Copy-ExistingShortcutCoversToTemp ($shortcutRecord) {
    if ($shortcutRecord -eq $null) { return $false }
    $shortcutId=[string]$shortcutRecord.ShortcutId
    if ([string]::IsNullOrWhiteSpace($shortcutId)) { return $false }

    if(Test-Path $global:tempCovers){Remove-Item $global:tempCovers -Recurse -Force -ErrorAction SilentlyContinue}
    if(-not (Test-Path $global:tempCovers)){New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null}

    $userDataDir=[string]$shortcutRecord.UserDataDir
    if([string]::IsNullOrWhiteSpace($userDataDir) -or -not (Test-Path $userDataDir)){
        return $false
    }

    $gridDir=Join-Path $userDataDir "config\grid"
    if(-not (Test-Path $gridDir)){return $false}

    $copied=$false
    $pairs=@(
        @{Src=($shortcutId+"p.jpg");Dst="temp_p.jpg"},
        @{Src=($shortcutId+"_hero.jpg");Dst="temp_hero.jpg"},
        @{Src=($shortcutId+"_logo.png");Dst="temp_logo.png"},
        @{Src=($shortcutId+".jpg");Dst="temp_header.jpg"},
        @{Src=($shortcutId+"_icon.ico");Dst="temp_icon.ico"},
        @{Src=($shortcutId+"_icon.png");Dst="temp_icon.png"},
        @{Src=($shortcutId+"_icon.jpg");Dst="temp_icon.jpg"}
    )
    foreach($pair in $pairs){
        $srcFile=Join-Path $gridDir $pair.Src
        $dstFile=Join-Path $global:tempCovers $pair.Dst
        if(Test-Path $srcFile){
            try{Copy-Item $srcFile $dstFile -Force;$copied=$true}catch{}
        }
    }
    return $copied
}

# Лицензионная игра Steam: если обложки ранее были сохранены карточкой (или заданы вручную в Steam),
# они лежат в userdata\<account>\config\grid\<appid>*. Копируем их в temp, чтобы карточка при
# открытии показывала УСТАНОВЛЕННЫЕ сейчас обложки, а не официальные из Steam.
# Temp здесь НЕ очищается — поверх уже загруженных официальных ассетов заменяются только найденные.
# Возвращает hashtable с ключами p / header / hero / logo / icon для реально найденных файлов.
function Copy-LicensedGridCoversToTemp ([string]$appId, [bool]$includeIcon = $false) {
    $loaded = @{}
    if ([string]::IsNullOrWhiteSpace($appId) -or $appId -notmatch '^\d+$') { return $loaded }
    if (-not (Test-Path $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null }
    $profiles = @()
    try { $profiles = @(Get-ConfiguredSteamProfileDirectories) } catch {}
    if ($profiles.Count -eq 0) { return $loaded }

    # Из нескольких профилей берём самый свежий файл.
    $findNewest = {
        param([string[]]$names)
        $best = $null
        foreach ($pr in $profiles) {
            $gridDir = Join-Path ([string]$pr.FullName) 'config\grid'
            foreach ($n in $names) {
                $f = Join-Path $gridDir $n
                if (-not (Test-Path -LiteralPath $f -PathType Leaf)) { continue }
                $fi = $null
                try { $fi = Get-Item -LiteralPath $f -ErrorAction Stop } catch { continue }
                if ($fi.Length -lt 512) { continue }
                if ($null -eq $best -or $fi.LastWriteTime -gt $best.LastWriteTime) { $best = $fi }
            }
        }
        return $best
    }

    $pairs = @(
        @{ Key = 'p';      Src = ($appId + 'p.jpg');     Dst = 'temp_p.jpg' },
        @{ Key = 'header'; Src = ($appId + '.jpg');      Dst = 'temp_header.jpg' },
        @{ Key = 'hero';   Src = ($appId + '_hero.jpg'); Dst = 'temp_hero.jpg' },
        @{ Key = 'logo';   Src = ($appId + '_logo.png'); Dst = 'temp_logo.png' }
    )
    foreach ($pair in $pairs) {
        $best = & $findNewest @([string]$pair.Src)
        if ($null -eq $best) { continue }
        try {
            Copy-Item -LiteralPath $best.FullName -Destination (Join-Path $global:tempCovers $pair.Dst) -Force -ErrorAction Stop
            $loaded[$pair.Key] = $true
        } catch {}
    }

    if ($includeIcon) {
        $bestIcon = & $findNewest @(($appId + '_icon.png'), ($appId + '_icon.jpg'), ($appId + '_icon.ico'))
        if ($null -ne $bestIcon) {
            try {
                foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
                    Remove-Item -LiteralPath (Join-Path $global:tempCovers $n) -Force -ErrorAction SilentlyContinue
                }
                $ext = [System.IO.Path]::GetExtension($bestIcon.FullName).ToLowerInvariant()
                if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.png' }
                Copy-Item -LiteralPath $bestIcon.FullName -Destination (Join-Path $global:tempCovers ('temp_icon' + $ext)) -Force -ErrorAction Stop
                $loaded['icon'] = $true
            } catch {}
        }
    }
    return $loaded
}

function Save-ExistingShortcutCoversToGrid ($shortcutRecord) {
    if ($shortcutRecord -eq $null) { return $false }
    $shortcutId=[string]$shortcutRecord.ShortcutId
    if ([string]::IsNullOrWhiteSpace($shortcutId)) { return $false }

    $userDataDir=[string]$shortcutRecord.UserDataDir
    if([string]::IsNullOrWhiteSpace($userDataDir) -or -not (Test-Path $userDataDir)){return $false}

    $gridDir=Join-Path $userDataDir "config\grid"
    if(-not (Test-Path $gridDir)){New-Item -ItemType Directory -Path $gridDir -Force | Out-Null}

    $map=@(
        @{Temp="temp_p.jpg";Dest=($shortcutId+"p.jpg")},
        @{Temp="temp_hero.jpg";Dest=($shortcutId+"_hero.jpg")},
        @{Temp="temp_logo.png";Dest=($shortcutId+"_logo.png")},
        @{Temp="temp_header.jpg";Dest=($shortcutId+".jpg")}
    )
    $changed=$false
    foreach($item in $map){
        $src=Join-Path $global:tempCovers $item.Temp
        $dst=Join-Path $gridDir $item.Dest
        if(Test-Path $src){
            try{
                Copy-Item $src $dst -Force -ErrorAction Stop
                $changed=$true
            }catch{}
        }
    }
    try {
        $iconSrc = Get-TempIconPath
        if ($null -ne $iconSrc) {
            $iconExt = [System.IO.Path]::GetExtension($iconSrc)
            if ([string]::IsNullOrWhiteSpace($iconExt)) { $iconExt = '.png' }
            Copy-Item -LiteralPath $iconSrc -Destination (Join-Path $gridDir ($shortcutId + '_icon' + $iconExt)) -Force -ErrorAction Stop
            $changed = $true
        }
    } catch {}
    return $changed
}

function Add-ShortcutToSteam ($gameName, $exePath, $startDir, $launchOptions = "") {
    # БАГ-ФИКС: раньше здесь передавался $startDir. Из карточки игры это папка
    # выбранного exe (например "...\Baldurs Gate 3\bin"), и проверка по имени
    # последней папки принимала за дубликат ЛЮБОЙ ярлык, чей exe лежит в папке с
    # таким же общим именем (bin, Win64, Binaries...). Дубликат — это ярлык с тем
    # же названием или с тем же exe.
    $existingShortcut = Find-SteamShortcutRecord $gameName $null $exePath $launchOptions
    if ($existingShortcut -ne $null) {
        $global:lastShortcutError = (T 'sc_exists' @($gameName))
        return $null
    }
    $steamPath = Get-ConfiguredSteamInstallPath
    $userDataPath = Get-ConfiguredSteamUserDataPath
    if (-not (Test-Path $userDataPath)) { $global:lastShortcutError = (T 'sc_userdata_missing' @($userDataPath)); return $null }
    $success = $false; $resultId = $null
    
    $exePathNormalized = $exePath.ToUpper(); $startDirNormalized = $startDir.ToUpper()
    $global:lastShortcutError = $null

    # ID ярлыка (он же имя файлов обложек в config\grid) считается по Exe + названию. У ROM
    # это ломалось: второй диск той же игры (Disc 2) или другой ром с тем же названием на том
    # же эмуляторе получал ТОЧНО ТАКОЙ ЖЕ ID, как уже добавленный. Steam хранит игры и обложки
    # по этому ID, поэтому две записи с одним ID сливались: второй образ оставался без обложек
    # (а правка обложки у одного меняла и другой). Если такой ID уже занят в любом профиле,
    # подбираем свободный, подмешивая в хеш параметры запуска (путь к конкретному образу).
    # Считаем один раз для всех профилей, чтобы обложки лежали под одним и тем же ID.
    $sharedIdStr = [string](Get-SteamShortcutID $exePathNormalized $gameName)
    $usedIds = @{}
    foreach ($pd in @(Get-ConfiguredSteamProfileDirectories)) {
        try {
            $sf0 = Join-Path (Join-Path $pd.FullName "config") "shortcuts.vdf"
            if (-not (Test-Path -LiteralPath $sf0)) { continue }
            $b0 = [System.IO.File]::ReadAllBytes($sf0)
            if ($b0.Length -eq 0) { continue }
            $n0 = Get-ShortcutsNode $b0
            if ($null -eq $n0) { continue }
            foreach ($e0 in $n0.Body.Children) {
                if ($e0.Type -ne 0x00) { continue }
                foreach ($f0 in $e0.Body.Children) { if ($f0.Key -eq "appid") { $usedIds[[string]$f0.Value] = $true } }
            }
        } catch {}
    }
    if ($usedIds.ContainsKey($sharedIdStr)) {
        for ($salt = 1; $salt -le 100; $salt++) {
            $candId = [string](Get-SteamShortcutID $exePathNormalized ($gameName + "|" + [string]$launchOptions + "|" + $salt))
            if (-not $usedIds.ContainsKey($candId)) { $sharedIdStr = $candId; break }
        }
    }

    Get-ConfiguredSteamProfileDirectories | ForEach-Object {
        $configDir = Join-Path $_.FullName "config"
        if (-not (Test-Path $configDir)) { New-Item -ItemType Directory -Path $configDir -Force | Out-Null }
        $shortcutsFile = Join-Path $configDir "shortcuts.vdf"

        # РАНЬШЕ: если shortcuts.vdf ещё не существовал (у пользователя ни разу не было
        # нестимовского ярлыка на этом профиле), весь блок ниже просто пропускался —
        # игра молча НЕ добавлялась, а Steam, уже убитый через taskkill чуть выше,
        # не перезапускался, потому что код перезапуска сидит внутри "if ($newShortcutId)".
        # Именно это выглядело как "игра не добавляется, а Steam не запускается".
        # Теперь при отсутствии файла мы создаём валидный shortcuts.vdf с нуля.
        $fileExisted = Test-Path $shortcutsFile

        # Авто-бэкап перед изменением файла (см. Create-AutoShortcutBackup).
        # Если файла ещё не было, бэкапировать нечего — он будет создан заново.
        if ($fileExisted) { Create-AutoShortcutBackup $shortcutsFile | Out-Null }

        try {
            $bName = [System.Text.Encoding]::UTF8.GetBytes($gameName)
            $bExe = [System.Text.Encoding]::UTF8.GetBytes("`"$exePathNormalized`"")
            $bDir = [System.Text.Encoding]::UTF8.GetBytes("`"$startDirNormalized`"")
            $bLaunchOptions = [System.Text.Encoding]::UTF8.GetBytes([string]$launchOptions)

            # РАНЬШЕ ЭТОГО ПОЛЯ НЕ БЫЛО ВООБЩЕ. Без него Steam при чтении файла
            # сам придумывает id для ярлыка (неизвестным нам способом), из-за чего
            # обложки, посчитанные нашей формулой, не совпадали с тем, что ждёт Steam.
            # Теперь мы пишем id САМИ — Steam обязан использовать именно его.
            $shortcutIdValue = [uint32]$sharedIdStr
            $bAppId = [BitConverter]::GetBytes($shortcutIdValue)

            $bytes = $null; $insertPos = 0
            if ($fileExisted) {
                $bytes = [System.IO.File]::ReadAllBytes($shortcutsFile)
                $shortcutsNode = Get-ShortcutsNode $bytes
                if ($shortcutsNode -eq $null) { throw (T 'sc_node_corrupt') }

                $maxIndex = -1
                foreach ($c in $shortcutsNode.Body.Children) {
                    if ($c.Key -match '^\d+$') { $v = [int]$c.Key; if ($v -gt $maxIndex) { $maxIndex = $v } }
                }
                $nextIndexValue = $maxIndex + 1
                $insertPos = $shortcutsNode.Body.EndPos
            } else {
                $nextIndexValue = 0
            }
            $bIndex = [System.Text.Encoding]::UTF8.GetBytes($nextIndexValue.ToString())

            $fEntry = New-Object System.Collections.Generic.List[byte]
            $fEntry.Add(0x00); $fEntry.AddRange([byte[]]$bIndex); $fEntry.Add(0x00)

            # appid (должно идти одним из первых полей в записи)
            $fEntry.Add(0x02); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("appid"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]$bAppId)

            # AppName
            $fEntry.Add(0x01); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("AppName"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]$bName); $fEntry.Add(0x00)

            # Exe
            $fEntry.Add(0x01); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("Exe"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]$bExe); $fEntry.Add(0x00)

            # StartDir
            $fEntry.Add(0x01); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("StartDir"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]$bDir); $fEntry.Add(0x00)

            # LaunchOptions — параметры запуска из карточки.
            $fEntry.Add(0x01); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("LaunchOptions"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]$bLaunchOptions); $fEntry.Add(0x00)

            # icon — путь к client-иконке (ошибка копирования НЕ должна ломать добавление).
            $iconPathForVdf = ''
            try {
                $iconSrc = Get-TempIconPath
                if ($null -ne $iconSrc -and (Test-Path -LiteralPath $iconSrc)) {
                    $gridDirForIcon = Join-Path $_.FullName 'config\grid'
                    if (-not (Test-Path -LiteralPath $gridDirForIcon)) {
                        New-Item -ItemType Directory -Path $gridDirForIcon -Force | Out-Null
                    }
                    $iconExt = [System.IO.Path]::GetExtension($iconSrc)
                    if ([string]::IsNullOrWhiteSpace($iconExt)) { $iconExt = '.png' }
                    $candIcon = Join-Path $gridDirForIcon ([string]$shortcutIdValue + '_icon' + $iconExt)
                    Copy-Item -LiteralPath $iconSrc -Destination $candIcon -Force -ErrorAction SilentlyContinue
                    if (Test-Path -LiteralPath $candIcon) { $iconPathForVdf = $candIcon }
                }
            } catch { $iconPathForVdf = '' }
            $fEntry.Add(0x01); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("icon"))); $fEntry.Add(0x00)
            if (-not [string]::IsNullOrWhiteSpace($iconPathForVdf)) {
                $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes($iconPathForVdf)))
            }
            $fEntry.Add(0x00)

            # IsHidden
            $fEntry.Add(0x02); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("IsHidden"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]@(0,0,0,0))

            # AllowDesktopConfig
            $fEntry.Add(0x02); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("AllowDesktopConfig"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]@(1,0,0,0))

            # AllowOverlay
            $fEntry.Add(0x02); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("AllowOverlay"))); $fEntry.Add(0x00); $fEntry.AddRange([byte[]]@(1,0,0,0))

            # tags (пустой вложенный объект)
            $fEntry.Add(0x00); $fEntry.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("tags"))); $fEntry.Add(0x00); $fEntry.Add(0x08)
            $fEntry.Add(0x08)   # закрывает саму запись ярлыка

            $newBytes = New-Object System.Collections.Generic.List[byte]
            if ($fileExisted) {
                # Вставляем новую запись РОВНО перед байтом, закрывающим объект "shortcuts"
                # (позиция вычислена честным разбором дерева, а не догадкой по хвосту файла),
                # и переносим весь остальной файл как есть, без изменений.
                for ($i = 0; $i -lt $insertPos; $i++) { $newBytes.Add($bytes[$i]) }
                $newBytes.AddRange([byte[]]$fEntry.ToArray())
                for ($i = $insertPos; $i -lt $bytes.Length; $i++) { $newBytes.Add($bytes[$i]) }
            } else {
                # Файла не было — собираем минимальный валидный shortcuts.vdf с нуля.
                $newBytes.Add(0x00)
                $newBytes.AddRange([byte[]]([System.Text.Encoding]::UTF8.GetBytes("shortcuts")))
                $newBytes.Add(0x00)
                $newBytes.AddRange([byte[]]$fEntry.ToArray())
                $newBytes.Add(0x08)  # закрывает объект "shortcuts"
                $newBytes.Add(0x08)  # закрывает корень файла
            }

            [System.IO.File]::WriteAllBytes($shortcutsFile, $newBytes.ToArray())
            $success = $true; $resultId = [string]$shortcutIdValue
        } catch {
            $global:lastShortcutError = $_.Exception.Message
        }
    }
    
    Save-Configuration
    
    if ($success) { return $resultId } else { return $null }
}
function Start-GameCopy ($srcPath, $dstPath, $msgTitle, $gameName, $aggregateBaseBytes = 0, $aggregateTotalBytes = 0) {
    # ROM-режим: $srcPath — одиночный ФАЙЛ. Переносим его сами (копирование
    # блоками + удаление источника), не через robocopy: так окно не зависает,
    # прогресс виден, а имена с [ ] не воспринимаются как маски (-LiteralPath).
    if (Test-Path -LiteralPath $srcPath -PathType Leaf) {
        $srcInfo = Get-Item -LiteralPath $srcPath
        $fileLen = [int64]$srcInfo.Length
        $inS = $null; $outS = $null; $copyOk = $false
        try {
            $inS = New-Object System.IO.FileStream($srcPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read, 1048576)
            $outS = New-Object System.IO.FileStream($dstPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 1048576)
            $buf = New-Object byte[] 1048576
            $copied = [int64]0
            $lastTick = [DateTime]::Now; $lastBytes = [int64]0
            while (($n = $inS.Read($buf, 0, $buf.Length)) -gt 0) {
                $outS.Write($buf, 0, $n)
                $copied += $n
                $now = [DateTime]::Now
                $dt = ($now - $lastTick).TotalSeconds
                if ($dt -ge 0.25) {
                    $speedMB = [int][Math]::Round((($copied - $lastBytes) / 1MB) / $dt)
                    $lastTick = $now; $lastBytes = $copied
                    $total = if ($aggregateTotalBytes -gt 0) { [double]$aggregateTotalBytes } else { [double][Math]::Max(1, $fileLen) }
                    $pct = [int][Math]::Round((([int64]$aggregateBaseBytes + $copied) / $total) * 100)
                    $pct = [Math]::Min(100, [Math]::Max(0, $pct))
                    $progressBarFolder.Value = $pct
                    $labelHeader.Text = (T 'st_copy_progress' @($msgTitle, $gameName, ([string]$speedMB), $pct))
                    [System.Windows.Forms.Application]::DoEvents()
                }
            }
            $outS.Flush()
            $copyOk = $true
        } finally {
            if ($outS -ne $null) { $outS.Dispose() }
            if ($inS -ne $null) { $inS.Dispose() }
            # Оборванное копирование не оставляем как «готовый» файл.
            if (-not $copyOk) { try { Remove-Item -LiteralPath $dstPath -Force -ErrorAction SilentlyContinue } catch {} }
        }
        try {
            $dstInfo = Get-Item -LiteralPath $dstPath
            $dstInfo.CreationTime = $srcInfo.CreationTime
            $dstInfo.LastWriteTime = $srcInfo.LastWriteTime
        } catch {}
        Remove-Item -LiteralPath $srcPath -Force
        $labelHeader.Text = (T 'st_copy_done' @($msgTitle, $gameName))
        [System.Windows.Forms.Application]::DoEvents()
        return
    }

    $totalFiles = (Get-ChildItem -LiteralPath $srcPath -Recurse -File -ErrorAction SilentlyContinue).Count
    if ($totalFiles -eq 0) { $totalFiles = 1 }

    $totalSize = 0
    Get-ChildItem -LiteralPath $srcPath -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $totalSize += $_.Length }
    if ($totalSize -eq 0) { $totalSize = 1 }

    # /MT:32 на механическом HDD только вредит (случайные seek'и вместо последовательной записи)
    # и, на быстром SSD, копирует всё "залпом" быстрее, чем успевает сработать опрос прогресса —
    # отсюда и жалоба "бар почти сразу заполняется". /MT:6 — разумный баланс скорости и плавности.
    $rcArgs = "`"$srcPath`" `"$dstPath`" /E /MOVE /BYTES /NJH /NJS /NC /NFL /NDL /NP /R:1 /W:1 /MT:6"
    $pInfo = New-Object System.Diagnostics.ProcessStartInfo -Property @{
        FileName = "robocopy.exe"; Arguments = $rcArgs
        RedirectStandardOutput = $false; UseShellExecute = $false; CreateNoWindow = $true
    }
    $proc = New-Object System.Diagnostics.Process; $proc.StartInfo = $pInfo; $proc.Start() | Out-Null
    
    $lastSize = 0
    $lastCheckTime = [DateTime]::Now

    while (-not $proc.HasExited) {
        Start-Sleep -Milliseconds 250
        [System.Windows.Forms.Application]::DoEvents()
        
        if (Test-Path $dstPath) {
            $currentSize = 0
            Get-ChildItem -LiteralPath $dstPath -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $currentSize += $_.Length }
            
            $now = [DateTime]::Now
            $timeDiff = ([DateTime]$now - [DateTime]$lastCheckTime).TotalSeconds
            if ($timeDiff -gt 0) {
                $sizeDiff = [int64]$currentSize - [int64]$lastSize
                if ($sizeDiff -lt 0) { $sizeDiff = 0 }
                $speedMB = [int][Math]::Round(($sizeDiff / 1MB) / $timeDiff)
                
                $lastSize = $currentSize
                $lastCheckTime = $now
                
                # При переносе нескольких игр этот же бар показывает ОБЩИЙ
                # прогресс всей операции, а не начинает отсчёт заново для каждой
                # папки. За основу берём суммарный объём уже завершённых игр и
                # текущий объём текущей папки.
                $currentAggregateBytes = [int64]$aggregateBaseBytes + [int64]$currentSize
                if ($aggregateTotalBytes -gt 0) {
                    $aggregatePercent = [int][Math]::Round(($currentAggregateBytes / [double]$aggregateTotalBytes) * 100)
                } else {
                    $aggregatePercent = [int][Math]::Round(($currentSize / [double]$totalSize) * 100)
                }
                $aggregatePercent = [Math]::Min(100, [Math]::Max(0, $aggregatePercent))
                $progressBarFolder.Value = $aggregatePercent
                $labelHeader.Text = (T 'st_copy_progress' @($msgTitle, $gameName, ([string]$speedMB), $aggregatePercent))
            }
        }
    }
    $proc.WaitForExit(); $proc.Dispose()
    
    # Здесь НЕ сбрасываем бар и НЕ издаём звук: при пакетном переносе
    # следующая папка должна продолжить общий прогресс, а сигнал должен
    # прозвучать только один раз после завершения всей операции.
    if ($aggregateTotalBytes -le 0) {
        $progressBarFolder.Value = 100
    } else {
        $completedAggregate = [int64]$aggregateBaseBytes + [int64]$totalSize
        $aggregateDonePercent = [int][Math]::Round(($completedAggregate / [double]$aggregateTotalBytes) * 100)
        $progressBarFolder.Value = [Math]::Min(100, [Math]::Max(0, $aggregateDonePercent))
    }
    $labelHeader.Text = (T 'st_copy_done' @($msgTitle, $gameName))
    [System.Windows.Forms.Application]::DoEvents()
}

# Временные обложки никогда не создаются рядом с EXE.
# Они живут в системном TEMP и удаляются при закрытии программы.
$global:tempCovers = Join-Path ([System.IO.Path]::GetTempPath()) "SteamCommander"
if (-not (Test-Path $global:tempCovers)) {
    New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null
}

function Remove-TemporaryCovers {
    try {
        if (Test-Path $global:tempCovers) {
            Remove-Item -LiteralPath $global:tempCovers -Recurse -Force -ErrorAction SilentlyContinue
        }
    } catch {}
}

# Удаляет только четыре временных файла обложек текущей карточки (капсула,
# hero, header, logo). Нужна карточке игры: Add-кнопка решает, есть ли что
# копировать в grid, по НАЛИЧИЮ этих файлов в TEMP (Test-CoversValid), а не по
# тому, что показано в слотах. Без очистки при открытии карточки файлы от
# предыдущей игры (пропущенной, отменённой или оборвавшейся на ошибке)
# оставались лежать, и игра без App ID (например, фанатская, которой нет в
# Steam) получала чужие обложки, хотя в слотах было "NO COVER".
function Clear-TempCoverFiles {
    foreach ($f in @('temp_p.jpg','temp_hero.jpg','temp_header.jpg','temp_logo.png','temp_icon.png','temp_icon.ico','temp_icon.jpg')) {
        try { Remove-Item -LiteralPath (Join-Path $global:tempCovers $f) -Force -ErrorAction SilentlyContinue } catch {}
    }
}
# ===================== ТОЧНОЕ РАЗРЕШЕНИЕ ССЫЛОК НА ОБЛОЖКИ =====================
# БАГ-ФИКС: с 2025-2026 годов часть изданий на Steam раздаёт обложки НЕ по
# старому плоскому пути ".../apps/{appid}/library_600x900.jpg", а по пути с
# уникальным хеш-префиксом файла — например
# ".../apps/2623190/b52322f78cbdc.../library_600x900_2x.jpg". Угадать такой
# путь заранее невозможно, поэтому прямое скачивание по фиксированному
# шаблону (см. Download-CoversToTemp выше) закономерно получает 404 для
# таких игр — даже если обложка у них есть и прекрасно видна в самом Steam
# (именно так вело себя реальное App ID 1712100 "Carmageddon: Rogue Shift",
# выпущенное в 2026 году).
#
# Официальный (и не требующий API-ключа) способ узнать РЕАЛЬНЫЕ ссылки —
# IStoreBrowseService/GetItems с include_assets=true: он возвращает шаблон
# asset_url_format вида "steam/apps/{appid}/${FILENAME}?t=..." и конкретные
# имена файлов (уже с нужным хеш-префиксом, если он есть) для капсулы,
# hero-фона, header и логотипа.
# Язык Steam (для локализованных обложек) по языку интерфейса из «Настроек».
function Get-SteamAssetLanguage {
    # Явный регион из «Настроек» имеет приоритет над языком интерфейса.
    $region = [string]$global:steamCoverRegion
    if (-not [string]::IsNullOrWhiteSpace($region)) {
        $key = $region.Trim().ToLowerInvariant()
        foreach ($l in @($script:steamCoverLanguages)) {
            if ([string]$l.Steam -eq $key) { return $key }
        }
    }
    $code = [string]$global:language
    foreach ($l in @($script:languageList)) {
        if ([string]$l.Code -eq $code -and -not [string]::IsNullOrWhiteSpace([string]$l.Steam)) { return [string]$l.Steam }
    }
    return 'english'
}

function Get-AssetFilenameValue ($node, [string]$lang = 'english') {
    if ($node -eq $null) { return $null }
    if ($node -is [string]) {
        if ([string]::IsNullOrEmpty($node)) { return $null }
        return $node
    }

    $propNames = @($node.PSObject.Properties.Name)
    foreach ($sizeKey in @('image2x', 'image')) {
        if ($propNames -contains $sizeKey) {
            $sub = $node.$sizeKey
            if ($sub -is [string]) {
                if (-not [string]::IsNullOrEmpty($sub)) { return $sub }
            } elseif ($sub -ne $null) {
                $subNames = @($sub.PSObject.Properties.Name)
                # Сначала язык интерфейса, затем английский.
                if ($lang -ne 'english' -and $subNames -contains $lang -and -not [string]::IsNullOrEmpty([string]$sub.$lang)) {
                    return [string]$sub.$lang
                }
                if ($subNames -contains 'english' -and -not [string]::IsNullOrEmpty([string]$sub.english)) {
                    return [string]$sub.english
                }
                foreach ($n in $subNames) {
                    $val = $sub.$n
                    if ($val -is [string] -and -not [string]::IsNullOrEmpty($val)) { return [string]$val }
                }
            }
        }
    }
    if ($propNames -contains 'english' -and -not [string]::IsNullOrEmpty([string]$node.english)) {
        return [string]$node.english
    }
    foreach ($n in $propNames) {
        $val = $node.$n
        if ($val -is [string] -and -not [string]::IsNullOrEmpty($val)) { return [string]$val }
    }
    return $null
}

function Get-SteamAssetUrlsViaApi ($appId, [string]$lang = 'english') {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

    # Для языка, отличного от английского, просим витрину отдать ассеты на нём
    # (если у игры есть локализованные — придут они, иначе — стандартные).
    $ctx = @{ country_code = "US" }
    if ($lang -ne 'english') { $ctx.language = $lang }
    $inputObj = @{ ids = @(@{ appid = [int]$appId }); context = $ctx; data_request = @{ include_assets = $true } }
    $inputJson = ($inputObj | ConvertTo-Json -Depth 5 -Compress)
    $url = "https://api.steampowered.com/IStoreBrowseService/GetItems/v1/?input_json=" + [System.Uri]::EscapeDataString($inputJson)

    # Пилотная неблокирующая версия: сам запрос идёт в фоновом runspace (см.
    # Invoke-BackgroundJsonRequest), а UI-поток крутит спиннер, ожидая ответ.
    $data = Invoke-BackgroundJsonRequest {
        param($u)
        try {
            return (Invoke-RestMethod -Uri $u -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 12 -ErrorAction Stop)
        } catch {
            try {
                $rawLines = curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" $u
                $rawJson = ($rawLines -join "")
                if (-not [string]::IsNullOrWhiteSpace($rawJson)) { return ($rawJson | ConvertFrom-Json -ErrorAction Stop) }
            } catch {}
            return $null
        }
    } @($url) 15
    if ($data -eq $null -or $data.response -eq $null -or $data.response.store_items -eq $null -or $data.response.store_items.Count -eq 0) { return $null }

    $item = $data.response.store_items[0]
    $assets = $item.assets
    if ($assets -eq $null -or [string]::IsNullOrEmpty($assets.asset_url_format)) { return $null }

    $pathTemplate = [string]$assets.asset_url_format
    $assetPropNames = @($assets.PSObject.Properties.Name)

    $capsuleFile = if ($assetPropNames -contains 'library_capsule_2x') { Get-AssetFilenameValue $assets.library_capsule_2x $lang }
                   elseif ($assetPropNames -contains 'library_capsule') { Get-AssetFilenameValue $assets.library_capsule $lang }
                   else { $null }
    $heroFile = if ($assetPropNames -contains 'library_hero_2x') { Get-AssetFilenameValue $assets.library_hero_2x $lang }
                elseif ($assetPropNames -contains 'library_hero') { Get-AssetFilenameValue $assets.library_hero $lang }
                else { $null }
    $headerFile = if ($assetPropNames -contains 'header') { Get-AssetFilenameValue $assets.header $lang } else { $null }
    $logoFile = if ($assetPropNames -contains 'library_logo') { Get-AssetFilenameValue $assets.library_logo $lang }
                elseif ($assetPropNames -contains 'logo') { Get-AssetFilenameValue $assets.logo $lang }
                else { $null }

    # Steam может раздавать один и тот же asset через разные CDN-хосты.
    # Возвращаем список кандидатов, чтобы загрузчик мог попробовать второй,
    # если первый CDN временно недоступен.
    $cdnDomains = @(
        "https://shared.fastly.steamstatic.com/store_item_assets/",
        "https://shared.akamai.steamstatic.com/store_item_assets/"
    )
    $buildUrls = {
        param($filenameField)
        if ([string]::IsNullOrEmpty([string]$filenameField)) { return @() }
        return @($cdnDomains | ForEach-Object { $_ + $pathTemplate.Replace('${FILENAME}', [string]$filenameField) })
    }

    return [PSCustomObject]@{
        Capsule = & $buildUrls $capsuleFile
        Hero    = & $buildUrls $heroFile
        Header  = & $buildUrls $headerFile
        Logo    = & $buildUrls $logoFile
        Name    = [string]$item.name
    }
}

# ===================== РЕГИОНЫ (ЯЗЫКИ) ОБЛОЖЕК STEAM =====================
# Steam хранит библиотечные ассеты (капсула, hero, логотип, header) по языкам:
# в PICS это common.library_assets_full.<ассет>.image(2x).<язык>. Steam — API-имя
# языка, Short — подпись на кнопке в карточке, Name — название в списке выбора
# (на самом языке, чтобы не переводить его на каждый язык интерфейса).
$script:steamCoverLanguages = @(
    [PSCustomObject]@{ Steam='english';    Short='EN';    Name='English' },
    [PSCustomObject]@{ Steam='russian';    Short='РУ';    Name='Русский' },
    [PSCustomObject]@{ Steam='ukrainian';  Short='UK';    Name='Українська' },
    [PSCustomObject]@{ Steam='german';     Short='DE';    Name='Deutsch' },
    [PSCustomObject]@{ Steam='french';     Short='FR';    Name='Français' },
    [PSCustomObject]@{ Steam='spanish';    Short='ES';    Name='Español' },
    [PSCustomObject]@{ Steam='latam';      Short='LA';    Name='Español (Latinoamérica)' },
    [PSCustomObject]@{ Steam='brazilian';  Short='BR';    Name='Português (Brasil)' },
    [PSCustomObject]@{ Steam='portuguese'; Short='PT';    Name='Português' },
    [PSCustomObject]@{ Steam='italian';    Short='IT';    Name='Italiano' },
    [PSCustomObject]@{ Steam='polish';     Short='PL';    Name='Polski' },
    [PSCustomObject]@{ Steam='czech';      Short='CS';    Name='Čeština' },
    [PSCustomObject]@{ Steam='hungarian';  Short='HU';    Name='Magyar' },
    [PSCustomObject]@{ Steam='romanian';   Short='RO';    Name='Română' },
    [PSCustomObject]@{ Steam='bulgarian';  Short='BG';    Name='Български' },
    [PSCustomObject]@{ Steam='greek';      Short='EL';    Name='Ελληνικά' },
    [PSCustomObject]@{ Steam='turkish';    Short='TR';    Name='Türkçe' },
    [PSCustomObject]@{ Steam='dutch';      Short='NL';    Name='Nederlands' },
    [PSCustomObject]@{ Steam='swedish';    Short='SV';    Name='Svenska' },
    [PSCustomObject]@{ Steam='danish';     Short='DA';    Name='Dansk' },
    [PSCustomObject]@{ Steam='finnish';    Short='FI';    Name='Suomi' },
    [PSCustomObject]@{ Steam='norwegian';  Short='NO';    Name='Norsk' },
    [PSCustomObject]@{ Steam='schinese';   Short='ZH';    Name='简体中文' },
    [PSCustomObject]@{ Steam='tchinese';   Short='TW';    Name='繁體中文' },
    [PSCustomObject]@{ Steam='japanese';   Short='JA';    Name='日本語' },
    [PSCustomObject]@{ Steam='koreana';    Short='KO';    Name='한국어' },
    [PSCustomObject]@{ Steam='thai';       Short='TH';    Name='ไทย' },
    [PSCustomObject]@{ Steam='vietnamese'; Short='VI';    Name='Tiếng Việt' },
    [PSCustomObject]@{ Steam='arabic';     Short='AR';    Name='العربية' },
    [PSCustomObject]@{ Steam='indonesian'; Short='ID';    Name='Bahasa Indonesia' }
)

function Get-SteamLanguageInfo ([string]$steamLang) {
    $key = ([string]$steamLang).ToLowerInvariant()
    foreach ($l in $script:steamCoverLanguages) { if ([string]$l.Steam -eq $key) { return $l } }
    $short = if ($key.Length -ge 2) { $key.Substring(0,2).ToUpperInvariant() } else { $key.ToUpperInvariant() }
    return [PSCustomObject]@{ Steam=$key; Short=$short; Name=$key }
}

# Языки, на которых у игры реально есть библиотечные ассеты (объединение по
# капсуле/hero/логотипу/header). Порядок — как в таблице выше, неизвестные — в конце.
function Get-SteamPicsAvailableLanguages ($appId) {
    $common = Get-SteamPicsCommon $appId
    if ($common -eq $null -or $common.library_assets_full -eq $null) { return @() }
    # Язык считается доступным, только если у него есть СВОЙ файл, отличный от
    # english (или english отсутствует в этом слоте). Иначе Steam часто дублирует
    # один и тот же путь под всеми языками — кнопка РУ светилась бы при
    # полностью английских обложках.
    $found = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($nodeName in @('library_capsule','library_hero','library_logo','library_header')) {
        $node = $common.library_assets_full.$nodeName
        if ($node -eq $null) { continue }
        foreach ($key in @('image2x','image')) {
            $img = $node.$key
            if ($img -eq $null) { continue }
            $props = @($img.PSObject.Properties)
            $engVal = $null
            try {
                if (($props | Where-Object { [string]$_.Name -eq 'english' } | Select-Object -First 1) -ne $null) {
                    $ev = $img.english
                    if ($ev -is [string] -and -not [string]::IsNullOrEmpty($ev)) { $engVal = [string]$ev }
                }
            } catch {}
            foreach ($p in $props) {
                $val = $p.Value
                if (-not ($val -is [string]) -or [string]::IsNullOrEmpty([string]$val)) { continue }
                $langName = [string]$p.Name
                if ($langName -eq 'english') {
                    [void]$found.Add('english')
                    continue
                }
                # Свой путь (отличается от english) или english в этом слоте нет.
                if ([string]::IsNullOrEmpty($engVal) -or -not [string]::Equals([string]$val, $engVal, [System.StringComparison]::OrdinalIgnoreCase)) {
                    [void]$found.Add($langName)
                }
            }
        }
    }
    if ($found.Count -eq 0) {
        # Нет ни одного распознанного языка — считаем, что есть хотя бы english.
        [void]$found.Add('english')
    } elseif (-not $found.Contains('english')) {
        # У части игр english-ключ отсутствует, но файлы есть под другими именами;
        # english всё равно оставляем как безопасный fallback-кнопку.
        [void]$found.Add('english')
    }
    $ordered = @()
    foreach ($l in $script:steamCoverLanguages) { if ($found.Contains([string]$l.Steam)) { $ordered += [string]$l.Steam } }
    foreach ($n in @($found | Sort-Object)) { if ($ordered -notcontains [string]$n) { $ordered += [string]$n } }
    return @($ordered)
}

# Кэш узла common из PICS по App ID: и загрузка обложек, и кнопка выбора региона
# в карточке спрашивают одни и те же данные — второй запрос к сети не нужен.
$script:picsCommonCache = @{}
function Get-SteamPicsCommon ($appId) {
    $cacheKey = [string]$appId
    if ($script:picsCommonCache.ContainsKey($cacheKey)) { return $script:picsCommonCache[$cacheKey] }
    if (-not (Test-InternetConnectivity)) { return $null }

    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

    $url  = "https://api.steamcmd.net/v1/info/$appId"
    $data = $null

    # В карточке игры не блокируем UI-поток: тянем JSON отдельным curl.exe,
    # прокачивая очередь сообщений (тот же приём, что и для картинок).
    if ($global:uiPumpDuringDownload) {
        $tmpJson = Join-Path $env:TEMP ("steamorg_pics_{0}.json" -f $appId)
        Remove-Item $tmpJson -Force -ErrorAction SilentlyContinue
        $pumped = Invoke-UiPumpingDownload $url $tmpJson 20
        if ($pumped -eq $true) {
            try { $data = (Get-Content -LiteralPath $tmpJson -Raw) | ConvertFrom-Json -ErrorAction Stop } catch { $data = $null }
        }
        Remove-Item $tmpJson -Force -ErrorAction SilentlyContinue
    }

    if ($data -eq $null) {
        try {
            $data = Invoke-RestMethod -Uri $url -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 15 -ErrorAction Stop
        } catch {
            try {
                $raw = (curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" --connect-timeout 10 --max-time 20 $url) -join ""
                if (-not [string]::IsNullOrWhiteSpace($raw)) { $data = $raw | ConvertFrom-Json -ErrorAction Stop }
            } catch {}
        }
    }
    if ($data -eq $null -or $data.data -eq $null) { return $null }

    $appNode = $data.data.PSObject.Properties | Where-Object { $_.Name -eq [string]$appId } | Select-Object -First 1
    if ($appNode -eq $null) { return $null }
    $common = $appNode.Value.common
    if ($common -eq $null) { return $null }
    $script:picsCommonCache[$cacheKey] = $common
    return $common
}

# БАГ-ФИКС: логотип (library_logo) у современных игр не находится ни прямым
# путём .../store_item_assets/steam/apps/<appid>/logo.png (ассет лежит с
# хеш-префиксом в пути), ни через IStoreBrowseService/GetItems — в объекте
# assets этого API логотипа попросту нет (там только asset_url_format,
# main_capsule, small_capsule, header, library_capsule(_2x), library_hero(_2x)).
# Поэтому ветка "докачать логотип по API" оставалась пустой, и реально
# существующий логотип показывался в карточке как отсутствующий.
#
# Полный набор библиотечных ассетов вместе с хеш-префиксами лежит в PICS —
# в секции common.library_assets_full (это то же, что показывает SteamDB).
# Забираем оттуда и собираем прямые ссылки на CDN (по всем зеркалам).
function Get-SteamPicsAssetUrls ($appId, [string]$lang = 'english') {
    $common = Get-SteamPicsCommon $appId
    if ($common -eq $null) { return $null }

    # Из узла library_assets_full выбираем файл по приоритету языка:
    #   1) язык интерфейса программы (image2x, затем image),
    #   2) английский (image2x, затем image),
    #   3) первый непустой язык (у части игр английского варианта нет).
    # У игр без локализованных обложек язык интерфейса просто не находится и
    # берётся английский — как раньше.
    $pickFull = {
        param($node, $preferLang)
        if ($node -eq $null) { return $null }
        $langOrder = @([string]$preferLang)
        if ([string]$preferLang -ne 'english') { $langOrder += 'english' }
        foreach ($lg in $langOrder) {
            foreach ($key in @('image2x','image')) {
                $img = $node.$key
                if ($img -eq $null) { continue }
                $val = $img.$lg
                if ($val -is [string] -and -not [string]::IsNullOrEmpty($val)) { return [string]$val }
            }
        }
        foreach ($key in @('image2x','image')) {
            $img = $node.$key
            if ($img -eq $null) { continue }
            foreach ($p in @($img.PSObject.Properties)) {
                if ($p.Value -is [string] -and -not [string]::IsNullOrEmpty([string]$p.Value)) { return [string]$p.Value }
            }
        }
        return $null
    }

    $logoFile = $null; $capsuleFile = $null; $heroFile = $null; $headerFile = $null
    if ($common.library_assets_full -ne $null) {
        $logoFile    = & $pickFull $common.library_assets_full.library_logo $lang
        $capsuleFile = & $pickFull $common.library_assets_full.library_capsule $lang
        $heroFile    = & $pickFull $common.library_assets_full.library_hero $lang
        $headerFile  = & $pickFull $common.library_assets_full.library_header $lang
    }
    # Старый формат PICS (library_assets) — имена файлов без хеш-префикса.
    if ($common.library_assets -ne $null) {
        if ([string]::IsNullOrEmpty($logoFile)    -and -not [string]::IsNullOrEmpty([string]$common.library_assets.library_logo))    { $logoFile    = [string]$common.library_assets.library_logo }
        if ([string]::IsNullOrEmpty($capsuleFile) -and -not [string]::IsNullOrEmpty([string]$common.library_assets.library_capsule)) { $capsuleFile = [string]$common.library_assets.library_capsule }
        if ([string]::IsNullOrEmpty($heroFile)    -and -not [string]::IsNullOrEmpty([string]$common.library_assets.library_hero))    { $heroFile    = [string]$common.library_assets.library_hero }
    }

    # Язык, на котором ФАКТИЧЕСКИ получились ассеты: запрошенный — если он есть
    # хотя бы у одного из четырёх, иначе английский (так подписывается кнопка
    # региона в карточке).
    $effLang = 'english'
    if ($lang -ne 'english' -and $common.library_assets_full -ne $null) {
        foreach ($nodeName in @('library_capsule','library_hero','library_logo','library_header')) {
            $node = $common.library_assets_full.$nodeName
            if ($node -eq $null) { continue }
            foreach ($key in @('image2x','image')) {
                $img = $node.$key
                if ($img -eq $null) { continue }
                $v = $img.$lang
                if ($v -is [string] -and -not [string]::IsNullOrEmpty($v)) { $effLang = $lang; break }
            }
            if ($effLang -eq $lang) { break }
        }
    }

    $cdnDomains = @(
        "https://shared.fastly.steamstatic.com/store_item_assets/",
        "https://shared.akamai.steamstatic.com/store_item_assets/",
        "https://shared.cloudflare.steamstatic.com/store_item_assets/"
    )
    $buildUrls = {
        param($filenameField)
        if ([string]::IsNullOrEmpty([string]$filenameField)) { return @() }
        $rel = "steam/apps/$appId/" + ([string]$filenameField -replace '^/','')
        return @($cdnDomains | ForEach-Object { $_ + $rel })
    }

    $out = [PSCustomObject]@{
        Capsule  = & $buildUrls $capsuleFile
        Hero     = & $buildUrls $heroFile
        Header   = & $buildUrls $headerFile
        Logo     = & $buildUrls $logoFile
        Language = $effLang
    }
    if (@($out.Capsule).Count -eq 0 -and @($out.Hero).Count -eq 0 -and @($out.Header).Count -eq 0 -and @($out.Logo).Count -eq 0) { return $null }
    return $out
}

# Путь к скачанной иконке в temp (ico предпочтительнее png/jpg).
function Get-TempIconPath {
    # png после растра из ico — предпочтительнее для превью (без чёрного кадра).
    foreach ($name in @('temp_icon.png', 'temp_icon.jpg', 'temp_icon.ico')) {
        $p = Join-Path $global:tempCovers $name
        if (Test-Path -LiteralPath $p) {
            try {
                if ((Get-Item -LiteralPath $p).Length -gt 64) { return $p }
            } catch {}
        }
    }
    return $null
}

# БАГ-ФИКС: расширение временного файла иконки раньше угадывалось только по
# хвосту URL SteamGridDB (.ico / .jpg / иначе .png "по умолчанию"). CDN
# SteamGridDB не всегда честно отражает реальный формат в ссылке — иногда
# настоящий ICO-файл отдаётся под URL без ".ico" на конце. Из-за этого файл
# сохранялся с неверным расширением (например ICO-байты как .png), и дальше
# по коду он шёл НЕ через Icon.ToBitmap(), а через общий Image.FromStream,
# который на реальных ICO-байтах вместо ошибки часто рисует "сломанную"
# шумную картинку. Эта функция после скачивания смотрит на первые байты
# файла (настоящую сигнатуру формата) и переименовывает файл в правильное
# расширение, если оно не совпадает с угаданным.
function Repair-IconFileExtension ([string]$path) {
    try {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { return $path }
        $bytes = [System.IO.File]::ReadAllBytes($path)
        if ($bytes.Length -lt 4) { return $path }
        $isIco = ($bytes[0] -eq 0 -and $bytes[1] -eq 0 -and $bytes[2] -eq 1 -and $bytes[3] -eq 0)
        $isPng = ($bytes.Length -ge 8 -and $bytes[0] -eq 0x89 -and $bytes[1] -eq 0x50 -and $bytes[2] -eq 0x4E -and $bytes[3] -eq 0x47)
        $isJpg = ($bytes[0] -eq 0xFF -and $bytes[1] -eq 0xD8)
        $wantExt = $null
        if ($isIco) { $wantExt = '.ico' } elseif ($isJpg) { $wantExt = '.jpg' } elseif ($isPng) { $wantExt = '.png' }
        if ($null -eq $wantExt) { return $path }
        $curExt = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
        if ($curExt -eq $wantExt) { return $path }
        $newPath = [System.IO.Path]::ChangeExtension($path, $wantExt)
        try {
            Remove-Item -LiteralPath $newPath -Force -ErrorAction SilentlyContinue
            Move-Item -LiteralPath $path -Destination $newPath -Force
            return $newPath
        } catch { return $path }
    } catch { return $path }
}

# БАГ-ФИКС (настоящая причина "сломанных"/шумных иконок): System.Drawing.Icon
# в .NET имеет давний известный баг с современными ICO-файлами, где крупный
# размер (обычно 256x256) хранится не как обычный растр (DIB), а как вложенный
# PNG-чанк (формат из Windows Vista+). Для таких записей Icon(...).ToBitmap()
# иногда декодирует сырые PNG-байты так, будто это простой растр — отсюда и
# цветной "шум" вместо картинки. Эта функция сама разбирает заголовок ICO
# (ICONDIR/ICONDIRENTRY), находит запись с максимальным размером и, если она
# хранится как PNG, декодирует её НАПРЯМУЮ через Image.FromStream — это
# полностью обходит баг и даёт чёткую картинку. Возвращает $null, если ICO
# не в PNG-формате (тогда вызывающий код использует обычный System.Drawing.Icon
# как раньше — для классических DIB-иконок он работает нормально).
function ConvertFrom-IcoBytesToBitmap ([byte[]]$bytes) {
    if ($null -eq $bytes -or $bytes.Length -lt 6) { return $null }
    try {
        $type = [System.BitConverter]::ToUInt16($bytes, 2)
        $count = [System.BitConverter]::ToUInt16($bytes, 4)
        if ($type -ne 1 -or $count -lt 1) { return $null }
        $best = $null
        for ($i = 0; $i -lt $count; $i++) {
            $entryOffset = 6 + ($i * 16)
            if ($entryOffset + 16 -gt $bytes.Length) { break }
            $w = [int]$bytes[$entryOffset]; if ($w -eq 0) { $w = 256 }
            $h = [int]$bytes[$entryOffset + 1]; if ($h -eq 0) { $h = 256 }
            $bytesInRes = [System.BitConverter]::ToUInt32($bytes, $entryOffset + 8)
            $imageOffset = [System.BitConverter]::ToUInt32($bytes, $entryOffset + 12)
            $entry = [PSCustomObject]@{ Width = $w; Height = $h; Size = $bytesInRes; Offset = $imageOffset }
            if ($null -eq $best -or ($entry.Width * $entry.Height) -gt ($best.Width * $best.Height)) { $best = $entry }
        }
        if ($null -eq $best) { return $null }
        if (($best.Offset + $best.Size) -gt $bytes.Length -or $best.Size -lt 8) { return $null }
        $off = [int]$best.Offset
        $isPng = ($bytes[$off] -eq 0x89 -and $bytes[$off+1] -eq 0x50 -and $bytes[$off+2] -eq 0x4E -and $bytes[$off+3] -eq 0x47)
        if (-not $isPng) { return $null }
        $chunk = New-Object byte[] ([int]$best.Size)
        [System.Array]::Copy($bytes, $off, $chunk, 0, [int]$best.Size)
        $ms = New-Object System.IO.MemoryStream(,$chunk)
        try {
            $tmpImg = [System.Drawing.Image]::FromStream($ms)
            try { return (New-Object System.Drawing.Bitmap($tmpImg)) } finally { $tmpImg.Dispose() }
        } finally { $ms.Dispose() }
    } catch { return $null }
}

# Единая точка получения Bitmap из ICO-файла: сначала пробуем прямой разбор
# (обходит баг с PNG-чанками), при неудаче — обычный System.Drawing.Icon
# с явным запросом крупного размера (иначе конструктор без размера берёт
# маленькую системную иконку, и превью получается мыльным).
function Get-BitmapFromIcoFile ([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { return $null }
    try {
        $bytes = [System.IO.File]::ReadAllBytes($path)
        $direct = ConvertFrom-IcoBytesToBitmap $bytes
        if ($null -ne $direct) { return $direct }
    } catch {}
    $ico = $null
    try {
        try { $ico = New-Object System.Drawing.Icon($path, 256, 256) }
        catch { $ico = New-Object System.Drawing.Icon($path) }
        return $ico.ToBitmap()
    } catch { return $null }
    finally { try { if ($null -ne $ico) { $ico.Dispose() } } catch {} }
}


# Ищет именно ту маленькую иконку, которую уже закэшировал клиент Steam.
# Для лицензионных игр Steam использует appcache\librarycache. В новых
# версиях встречается вложенная папка <AppID> с JPG-файлом из 40 hex-символов,
# в старых/других установках — плоский <AppID>_icon.jpg.
# Важно: это локальный кэш самого клиента, а не Steam CDN и не SteamGridDB.
function Get-LocalSteamLibraryIconPath ([string]$appId) {
    if ([string]::IsNullOrWhiteSpace($appId) -or $appId -notmatch '^\d+$') { return $null }
    try {
        $steamRoot = Get-ConfiguredSteamInstallPath
        if ([string]::IsNullOrWhiteSpace($steamRoot) -or -not (Test-Path -LiteralPath $steamRoot -PathType Container)) { return $null }
        $cache = Join-Path $steamRoot 'appcache\librarycache'
        if (-not (Test-Path -LiteralPath $cache -PathType Container)) { return $null }
        $id = $appId.Trim()

        # Старый/плоский формат — самый однозначный.
        foreach ($name in @($id + '_icon.jpg', $id + '_icon.png', $id + '_icon.ico')) {
            $p = Join-Path $cache $name
            if (Test-Path -LiteralPath $p -PathType Leaf) {
                try { if ((Get-Item -LiteralPath $p).Length -ge 64) { return $p } } catch {}
            }
        }

        # Новый формат Steam: appcache\librarycache\<appid>\<40hex>.jpg.
        $appDir = Join-Path $cache $id
        if (Test-Path -LiteralPath $appDir -PathType Container) {
            try {
                $exact = Get-ChildItem -LiteralPath $appDir -File -ErrorAction SilentlyContinue |
                    Where-Object { $_.Name -match '^[0-9a-fA-F]{40}\.jpe?g$' -and $_.Length -ge 64 } |
                    Select-Object -First 1
                if ($null -ne $exact) { return [string]$exact.FullName }
            } catch {}

            # Резерв для промежуточных форматов Steam: ищем маленький квадратный
            # JPG/PNG/ICO, исключая header/capsule/hero/logo.
            $icons = New-Object System.Collections.Generic.List[object]
            try {
                Get-ChildItem -LiteralPath $appDir -File -ErrorAction SilentlyContinue | ForEach-Object {
                    if ($_.Length -lt 64) { return }
                    if ($_.Name -notmatch '\.(jpe?g|png|ico)$') { return }
                    if ($_.Name -match 'header|capsule|hero|logo|600x900|blur') { return }
                    try {
                        $img = [System.Drawing.Image]::FromFile($_.FullName)
                        try {
                            $ratio = if ($img.Height -gt 0) { $img.Width / [double]$img.Height } else { 99 }
                            if ($ratio -ge 0.75 -and $ratio -le 1.33) {
                                [void]$icons.Add([PSCustomObject]@{ Path=$_.FullName; Area=([int64]$img.Width * [int64]$img.Height); Size=[int64]$_.Length })
                            }
                        } finally { $img.Dispose() }
                    } catch {}
                }
            } catch {}
            if ($icons.Count -gt 0) {
                $best = $icons | Sort-Object Area, @{Expression='Size';Descending=$true} | Select-Object -First 1
                if ($null -ne $best) { return [string]$best.Path }
            }
        }
    } catch {}
    return $null
}

# Кэш результатов поиска иконки Steam на сеанс: без него каждый клик по кнопке
# "вернуть иконку Steam" заново обходил все CDN-хосты и PICS (до десятков секунд
# на UI-потоке), даже когда у игры в Steam иконки просто нет.
#   steamIconMissing  — PICS ответил, но ни icon, ни clienticon у игры нет (окончательно);
#   steamIconFailUntil — сеть/хосты не ответили, повторять не раньше этого времени.
$script:steamIconMissing = @{}
$script:steamIconFailUntil = @{}

# Качает первый рабочий URL с КОРОТКИМ таймаутом на каждый адрес и общим бюджетом
# времени (раньше Save-FirstWorkingUrl мог ждать 30+40 с на каждый из 8 адресов,
# если часть хостов Steam CDN не отвечала). При включённой прокачке UI (карточка)
# окно не замирает — файл тянет отдельный curl.exe.
function Save-SteamIconFirstUrl ($urls, [string]$destPath, [int]$minSize = 64, [int]$perUrlSeconds = 8, [int]$budgetSeconds = 20) {
    $deadline = (Get-Date).AddSeconds($budgetSeconds)
    foreach ($u in @($urls)) {
        if ((Get-Date) -gt $deadline) { break }
        if ($global:editorLoadAbortRequested) { break }
        if ([string]::IsNullOrWhiteSpace([string]$u)) { continue }
        if ($global:uiPumpDuringDownload) {
            $r = Invoke-UiPumpingDownload ([string]$u) $destPath $perUrlSeconds $minSize
            if ($r -eq $true) { return $true }
            if ($r -eq $false) { continue }
        }
        try {
            & curl.exe -L -s -S -f --connect-timeout 4 --max-time $perUrlSeconds -A "Mozilla/5.0" ([string]$u) -o $destPath 2>$null
            if ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $destPath) -and (Get-Item -LiteralPath $destPath).Length -ge $minSize) { return $true }
        } catch {}
        Remove-Item -LiteralPath $destPath -Force -ErrorAction SilentlyContinue
    }
    return $false
}

# Скачивает clienticon/icon в temp и всегда делает temp_icon.png для превью.
# $force — перезаписать даже если файл уже есть (иначе при открытии карточки
# остаётся старый чёрный png, сохранённый ранее в grid).
# $preferLocalCache — для лицензионной игры сначала взять иконку из локального
# кэша самого клиента Steam; к сети/CDN и SteamGridDB в этом случае не обращаемся.
function Download-SteamIconToTemp ([string]$appId, [bool]$force = $false, [bool]$preferLocalCache = $false) {
    if ([string]::IsNullOrWhiteSpace($appId) -or $appId -notmatch '^\d+$') { return $false }
    if (-not (Test-Path $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null }
    if ($force) {
        foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
            try { Remove-Item -LiteralPath (Join-Path $global:tempCovers $n) -Force -ErrorAction SilentlyContinue } catch {}
        }
    } elseif ($null -ne (Get-TempIconPath)) {
        return $true
    }
    try {
        # Для лицензионной игры источник №1 — уже загруженная Steam-клиентом
        # иконка. Это именно та картинка, которую сам клиент использует в
        # библиотеке. Если кэша ещё нет, продолжаем обычным Steam CDN-путём.
        if ($preferLocalCache) {
            $localIcon = Get-LocalSteamLibraryIconPath $appId
            if (-not [string]::IsNullOrWhiteSpace($localIcon) -and (Test-Path -LiteralPath $localIcon -PathType Leaf)) {
                $ext = [System.IO.Path]::GetExtension($localIcon).ToLowerInvariant()
                $dest = Join-Path $global:tempCovers ('temp_icon' + $(if ($ext -in @('.jpg','.jpeg')) { '.jpg' } elseif ($ext -eq '.ico') { '.ico' } else { '.png' }))
                try { Copy-Item -LiteralPath $localIcon -Destination $dest -Force -ErrorAction Stop; return $true } catch {}
            }
        }

        $id = ([string]$appId).Trim()
        # Уже выяснили, что у игры нет иконки в Steam, или недавно не достучались до сети —
        # не ходим по хостам повторно (раньше это и давало долгое зависание).
        if ($script:steamIconMissing.ContainsKey($id)) { return $false }
        if ($script:steamIconFailUntil.ContainsKey($id) -and (Get-Date) -lt $script:steamIconFailUntil[$id]) { return $false }

        $commonIcon = Get-SteamPicsCommon $appId
        if ($null -eq $commonIcon) {
            # PICS не ответил — это сбой сети, а не отсутствие иконки; пробуем снова не раньше чем через минуту.
            $script:steamIconFailUntil[$id] = (Get-Date).AddSeconds(60)
            return $false
        }
        $hasAppIcon = $false; $hasClientIcon = $false
        try { $hasAppIcon = -not [string]::IsNullOrWhiteSpace([string]$commonIcon.icon) } catch {}
        try { $hasClientIcon = -not [string]::IsNullOrWhiteSpace([string]$commonIcon.clienticon) } catch {}
        if (-not $hasAppIcon -and -not $hasClientIcon) {
            $script:steamIconMissing[$id] = $true
            return $false
        }
        $hosts = @(
            'https://cdn.cloudflare.steamstatic.com/steamcommunity/public/images/apps',
            'https://cdn.akamai.steamstatic.com/steamcommunity/public/images/apps',
            'https://media.steampowered.com/steamcommunity/public/images/apps',
            'https://steamcdn-a.akamaihd.net/steamcommunity/public/images/apps'
        )
        # Сначала настоящий Steam App Icon (common.icon).
        # БАГ-ФИКС: раньше Save-FirstWorkingUrl отбраковывал любой файл
        # меньше 512 байт (порог, рассчитанный на обложки), а маленькие
        # квадратные иконки нередко весят меньше — из-за этого валидная
        # иконка могла быть удалена ещё на этапе скачивания, хотя
        # Get-TempIconPath ниже проверяет её по гораздо меньшему порогу
        # (64 байта). Теперь для иконок используется тот же порог в 64 байта.
        if ($commonIcon -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$commonIcon.icon)) {
            $ih = ([string]$commonIcon.icon).Trim()
            $jpgUrls = @($hosts | ForEach-Object { "$_/$id/$ih.jpg" })
            Save-SteamIconFirstUrl $jpgUrls (Join-Path $global:tempCovers 'temp_icon.jpg') 64 | Out-Null
        }
        # Если App Icon отсутствует, используем clienticon как резерв.
        if ($null -eq (Get-TempIconPath) -and $commonIcon -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$commonIcon.clienticon)) {
            $ch = ([string]$commonIcon.clienticon).Trim()
            $icoUrls = @($hosts | ForEach-Object { "$_/$id/$ch.ico" })
            Save-SteamIconFirstUrl $icoUrls (Join-Path $global:tempCovers 'temp_icon.ico') 64 | Out-Null
        }
        try {
            $icoPath = Join-Path $global:tempCovers 'temp_icon.ico'
            $pngPath = Join-Path $global:tempCovers 'temp_icon.png'
            if (Test-Path -LiteralPath $icoPath) {
                $bmpIcon = Get-BitmapFromIcoFile $icoPath
                if ($null -ne $bmpIcon) {
                    try { $bmpIcon.Save($pngPath, [System.Drawing.Imaging.ImageFormat]::Png) } finally { $bmpIcon.Dispose() }
                }
            }
        } catch {}
        try {
            $jpgPath = Join-Path $global:tempCovers 'temp_icon.jpg'
            $pngPath = Join-Path $global:tempCovers 'temp_icon.png'
            if ((Test-Path -LiteralPath $jpgPath) -and -not (Test-Path -LiteralPath $pngPath)) {
                $img = [System.Drawing.Image]::FromFile($jpgPath)
                try { $img.Save($pngPath, [System.Drawing.Imaging.ImageFormat]::Png) } finally { $img.Dispose() }
            }
        } catch {}
    } catch {}
    $gotIcon = ($null -ne (Get-TempIconPath))
    if (-not $gotIcon) {
        # Хэши в PICS есть, но ни один хост не отдал файл — подождём минуту, а не зависаем на каждом клике.
        try { $script:steamIconFailUntil[([string]$appId).Trim()] = (Get-Date).AddSeconds(60) } catch {}
    }
    return $gotIcon
}

# ===================== ПОДСКАЗКА EXE ИЗ STEAM (PICS: config.launch) =====================
# У каждой игры в Steam есть запись о том, какой файл запускать (то же самое
# показывает SteamDB в разделе Configuration -> Launch Options -> Executable).
# Данные берём из того же PICS, но по обычному HTTP — через api.steamcmd.net
# (этот же сервис уже используется в Get-SteamPicsAssetUrls). Путь в записи
# указан ОТНОСИТЕЛЬНО папки установки игры, поэтому подсказка засчитывается
# только если такой файл реально существует в папке игры на диске. Это же
# служит подтверждением: если App ID определён неверно, нужного exe в папке
# просто не окажется, и программа вернётся к прежнему выбору.
$global:steamLaunchExeCache = @{}
$global:steamPrimaryExeCache = @{}
$global:steamLaunchHintDisabledUntil = [datetime]::MinValue

# Возвращает массив относительных путей exe для Windows (в порядке записей
# launch), либо пустой массив. Результат кэшируется на сеанс по App ID.
function Get-SteamLaunchExecutables ($appId) {
    $appIdStr = [string]$appId
    if ($appIdStr -notmatch '^\d+$') { return @() }
    if ($global:steamLaunchExeCache.ContainsKey($appIdStr)) { return @($global:steamLaunchExeCache[$appIdStr]) }
    # Если сервис недавно не ответил, не заставляем ждать заново на каждой игре.
    if ((Get-Date) -lt $global:steamLaunchHintDisabledUntil) { return @() }
    if (-not (Test-InternetConnectivity)) { return @() }

    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
    $url = "https://api.steamcmd.net/v1/info/$appIdStr"
    $data = Invoke-BackgroundJsonRequest {
        param($u)
        try {
            return (Invoke-RestMethod -Uri $u -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 8 -ErrorAction Stop)
        } catch {
            try {
                $rawLines = curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" --connect-timeout 5 --max-time 8 $u
                $rawJson = ($rawLines -join "")
                if (-not [string]::IsNullOrWhiteSpace($rawJson)) { return ($rawJson | ConvertFrom-Json -ErrorAction Stop) }
            } catch {}
            return $null
        }
    } @($url) 20

    if ($data -eq $null) {
        $global:steamLaunchHintDisabledUntil = (Get-Date).AddMinutes(10)
        return @()
    }

    $found = New-Object System.Collections.Generic.List[string]
    $optionExes = New-Object System.Collections.Generic.List[string]
    $primaryRel = $null
    try {
        $appNode = $null
        if ($data.data -ne $null) {
            $appNode = $data.data.PSObject.Properties | Where-Object { $_.Name -eq $appIdStr } | Select-Object -First 1
        }
        $launch = $null
        if ($appNode -ne $null -and $appNode.Value -ne $null -and $appNode.Value.config -ne $null) { $launch = $appNode.Value.config.launch }
        if ($launch -ne $null) {
            $launchItems = @()
            if ($launch -is [System.Array]) {
                $launchItems = @($launch)
            } else {
                $launchItems = @($launch.PSObject.Properties |
                    Sort-Object { $n = 0; if ([int]::TryParse($_.Name, [ref]$n)) { $n } else { [int]::MaxValue } } |
                    ForEach-Object { $_.Value })
            }
            foreach ($l in $launchItems) {
                if ($l -eq $null) { continue }
                $exe = [string]$l.executable
                if ([string]::IsNullOrWhiteSpace($exe)) { continue }
                # Основной запуск (default/none) и варианты выбора при запуске
                # (option1, option2...) — у некоторых игр прямой exe лежит именно
                # среди вариантов, а по умолчанию стоит лаунчер. VR, редакторы,
                # серверы и т.п. пропускаем.
                $launchType = [string]$l.type
                $isOption = $false
                if (-not [string]::IsNullOrEmpty($launchType) -and $launchType -ne 'default' -and $launchType -ne 'none') {
                    if ($launchType -match '^option\d*$') { $isOption = $true } else { continue }
                }
                $os = $null
                if ($l.config -ne $null) { $os = [string]$l.config.oslist }
                if (-not [string]::IsNullOrEmpty($os) -and $os -notmatch 'windows') { continue }
                $exe = ($exe -replace '/', '\').TrimStart('\')
                if ([System.IO.Path]::IsPathRooted($exe) -or $exe -match '(^|\\)\.\.(\\|$)') { continue }
                # Основной запуск по данным Steam (первая запись default/none),
                # в том числе лаунчер — нужен для лицензионных игр.
                if (-not $isOption -and $null -eq $primaryRel) { $primaryRel = $exe }
                if ($isOption) {
                    if (-not $optionExes.Contains($exe)) { $optionExes.Add($exe) }
                } else {
                    if (-not $found.Contains($exe)) { $found.Add($exe) }
                }
            }
        }
        # Варианты выбора идут после основных записей.
        foreach ($o in $optionExes) { if (-not $found.Contains($o)) { $found.Add($o) } }
    } catch {}

    $global:steamLaunchExeCache[$appIdStr] = $found.ToArray()
    $global:steamPrimaryExeCache[$appIdStr] = $primaryRel
    return @($found.ToArray())
}

# Ищет в папке игры файл, который Steam считает основным для этого App ID.
# Возвращает FileInfo или $null (если записи нет, сервис недоступен или такого
# файла в папке нет — тогда вызывающий код работает как раньше).
# Прямой запуск игры предпочтительнее лаунчера: сначала проверяются записи без
# слова "launcher" в пути, и только если ни одной из них нет в папке — лаунчеры.
# Сам лаунчер при этом остаётся в списке карточки для ручного выбора.
function Get-SteamHintedExecutable ($gamePath, $appId) {
    if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath)) { return $null }
    $rels = @(Get-SteamLaunchExecutables $appId)
    if ($rels.Count -eq 0) { return $null }

    $direct = @($rels | Where-Object { $_ -notmatch '(?i)launcher' })

    # БАГ-ФИКС: раньше при отсутствии прямого exe среди данных Steam функция
    # откатывалась на лаунчер из тех же данных ($launchers) и возвращала его
    # с ПОЛНОЙ уверенностью ("определён по данным Steam"), из-за чего вызывающий
    # код показывал зелёную галочку и даже автодобавлял игру в библиотеку без
    # диалога выбора. Проблема в том, что метаданные Steam для многих игр
    # (например, Baldur's Gate 3, App ID 1086940) вообще не объявляют прямой
    # exe как альтернативный вариант запуска — там прописан только сам
    # лаунчер (Launcher\LariLauncher.exe), хотя bin\bg3.exe прекрасно работает
    # и лежит в той же папке. В такой ситуации данные Steam не дают никакого
    # преимущества перед обычным локальным поиском exe (он и так найдёт
    # лаунчер как одного из кандидатов) — а вот ложная "уверенность" в выборе
    # именно лаунчера вместо прямого запуска игры была явной регрессией.
    # Поэтому теперь функция подтверждает выбор ТОЛЬКО если Steam указывает
    # прямой (не-лаунчер) exe; если такого нет — возвращаем null, и вызывающий
    # код переходит к обычному выбору (кэш/диалог), не выдавая лаунчер за
    # уверенно определённый файл запуска.
    foreach ($rel in @($direct)) {
        try {
            $full = Join-Path $gamePath $rel
            if (Test-Path -LiteralPath $full -PathType Leaf) { return (Get-Item -LiteralPath $full) }
        } catch {}
    }
    # Игра может лежать во вложенной папке (лишний уровень при копировании):
    # ищем файл с тем же хвостом пути, но только если совпадение ровно одно.
    foreach ($rel in @($direct)) {
        try {
            $leaf = [System.IO.Path]::GetFileName($rel)
            if ([string]::IsNullOrEmpty($leaf)) { continue }
            $suffix = '\' + $rel
            $nested = @(Get-ChildItem -LiteralPath $gamePath -Filter $leaf -File -Recurse -ErrorAction SilentlyContinue |
                Where-Object { $_.FullName.EndsWith($suffix, [System.StringComparison]::OrdinalIgnoreCase) })
            if ($nested.Count -eq 1) { return $nested[0] }
        } catch {}
    }
    return $null
}

# Для ЛИЦЕНЗИОННЫХ игр: возвращает файл, который Steam называет основным
# запуском (первая запись default/none), даже если это лаунчер — у такой игры
# exe не выбирается пользователем и в ярлык не сохраняется, поэтому правильным
# считается ровно тот файл, который указывает Steam. Возвращает FileInfo или
# $null (нет данных Steam или такого файла нет в папке игры).
function Get-SteamPrimaryExecutable ($gamePath, $appId) {
    if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath)) { return $null }
    [void](Get-SteamLaunchExecutables $appId)
    $rel = $null
    try { $rel = [string]$global:steamPrimaryExeCache[[string]$appId] } catch {}
    if ([string]::IsNullOrWhiteSpace($rel)) { return $null }
    try {
        $full = Join-Path $gamePath $rel
        if (Test-Path -LiteralPath $full -PathType Leaf) { return (Get-Item -LiteralPath $full) }
    } catch {}
    try {
        $leaf = [System.IO.Path]::GetFileName($rel)
        $suffix = '\' + $rel
        $nested = @(Get-ChildItem -LiteralPath $gamePath -Filter $leaf -File -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName.EndsWith($suffix, [System.StringComparison]::OrdinalIgnoreCase) })
        if ($nested.Count -eq 1) { return $nested[0] }
    } catch {}
    return $null
}

# ===================== ПАРАМЕТРЫ ЗАПУСКА ИЗ STEAM (PICS: config.launch) =====================
# То же самое, что показывает SteamDB в разделе Configuration -> Launch Options
# (Executable / Arguments / Description для каждого варианта запуска) — но не
# HTML-страница steamdb.info (нестабильная разметка, может стоять защита от
# ботов), а тот же самый api.steamcmd.net, что уже используется чуть выше в
# Get-SteamLaunchExecutables — тот же исходный PICS-источник, просто без
# фильтрации по типу/ОС/лаунчеру: здесь нужны ВСЕ записи как есть, чтобы
# показать их пользователю на выбор в выпадающем списке карточки игры.
# Кэш и сетевой запрос сделаны отдельно от Get-SteamLaunchExecutables (не
# переиспользуют её кэш) — так изменения здесь не рискуют задеть уже рабочую
# автоподсказку exe.
$global:steamLaunchOptionsCache = @{}

# Небольшой локальный справочник самых распространённых аргументов командной
# строки (движки на Source/Source 2 и общие флаги самого Steam) — сама витрина
# Steam текстового объяснения по каждому отдельному флагу не даёт (только
# "Description" на весь вариант запуска целиком, и то не всегда), поэтому
# подсказку рядом с полем строим сами по известным флагам.
