# Возвращает массив [PSCustomObject]@{ Index; Executable; Arguments; Type;
# Description; OS } — все варианты запуска, которые Steam знает для App ID,
# либо пустой массив (если запись отсутствует или сервис не ответил).
# Результат кэшируется на сеанс по App ID.
function Get-SteamDbLaunchOptions ($appId) {
    $appIdStr = [string]$appId
    if ($appIdStr -notmatch '^\d+$') { return @() }
    if ($global:steamLaunchOptionsCache.ContainsKey($appIdStr)) { return @($global:steamLaunchOptionsCache[$appIdStr]) }

    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
    $url = "https://api.steamcmd.net/v1/info/$appIdStr"
    $data = Invoke-BackgroundJsonRequest {
        param($u)
        try {
            return (Invoke-RestMethod -Uri $u -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 10 -ErrorAction Stop)
        } catch {
            try {
                $rawLines = curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" --connect-timeout 6 --max-time 10 $u
                $rawJson = ($rawLines -join "")
                if (-not [string]::IsNullOrWhiteSpace($rawJson)) { return ($rawJson | ConvertFrom-Json -ErrorAction Stop) }
            } catch {}
            return $null
        }
    } @($url) 20

    $result = New-Object System.Collections.Generic.List[object]
    if ($data -ne $null) {
        try {
            $appNode = $null
            if ($data.data -ne $null) {
                $appNode = $data.data.PSObject.Properties | Where-Object { $_.Name -eq $appIdStr } | Select-Object -First 1
            }
            $launch = $null
            if ($appNode -ne $null -and $appNode.Value -ne $null -and $appNode.Value.config -ne $null) { $launch = $appNode.Value.config.launch }
            if ($launch -ne $null) {
                $launchItems = @()
                if ($launch -is [System.Array]) {
                    $launchItems = @($launch)
                } else {
                    $launchItems = @($launch.PSObject.Properties |
                        Sort-Object { $n = 0; if ([int]::TryParse($_.Name, [ref]$n)) { $n } else { [int]::MaxValue } } |
                        ForEach-Object { $_.Value })
                }
                $idx = 0
                foreach ($l in $launchItems) {
                    if ($l -eq $null) { continue }
                    $exe = [string]$l.executable
                    if ([string]::IsNullOrWhiteSpace($exe)) { continue }
                    $osList = $null
                    if ($l.config -ne $null) { $osList = [string]$l.config.oslist }
                    $entry = [PSCustomObject]@{
                        Index       = $idx
                        Executable  = ($exe -replace '/', '\')
                        Arguments   = [string]$l.arguments
                        Type        = [string]$l.type
                        Description = [string]$l.description
                        OS          = if ([string]::IsNullOrWhiteSpace($osList)) { 'windows' } else { $osList }
                    }
                    $result.Add($entry)
                    $idx++
                }
            }
        } catch {}
    }

    $arr = $result.ToArray()
    $global:steamLaunchOptionsCache[$appIdStr] = $arr
    return @($arr)
}

# Короткая подсказка "что делает" выбранный вариант запуска — своё описание
# из Steam (если есть) плюс расшифровка узнаваемых флагов из Arguments.
function Format-LaunchOptionHint ($entry) {
    if ($entry -eq $null) { return '' }
    $parts = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace([string]$entry.Description)) { [void]$parts.Add([string]$entry.Description) }
    if (-not [string]::IsNullOrWhiteSpace([string]$entry.Arguments)) {
        $flagHints = New-Object System.Collections.Generic.List[string]
        $tokens = [System.Text.RegularExpressions.Regex]::Split([string]$entry.Arguments, '\s+') | Where-Object { $_ -match '^[+-]' }
        foreach ($tok in $tokens) {
            $hintTable = switch ([string]$global:language) { 'en' { $global:knownLaunchArgHintsEn } 'zh' { $global:knownLaunchArgHintsZh } 'es' { $global:knownLaunchArgHintsEs } 'pt' { $global:knownLaunchArgHintsPt } 'de' { $global:knownLaunchArgHintsDe } default { if ([string]$global:language -eq 'ru') { $global:knownLaunchArgHints } else { $global:knownLaunchArgHintsEn } } }
            if ($hintTable.Contains($tok)) { [void]$flagHints.Add("$tok — " + $hintTable[$tok]) }
        }
        if ($flagHints.Count -gt 0) { [void]$parts.Add(($flagHints -join '; ')) }
    }
    if ($parts.Count -eq 0) { return (T 'lo_no_hint') }
    return ($parts -join ' · ')
}

# ===================== БЫСТРАЯ ПРОВЕРКА ИНТЕРНЕТ-СОЕДИНЕНИЯ =====================
# Раньше при отсутствии интернета карточка игры реально зависала: каждый
# отдельный сетевой вызов (Invoke-RestMethod/Invoke-WebRequest/curl.exe) ждал
# СВОЙ полный таймаут (от 10 до 90 секунд), и таких вызовов на одну карточку
# выполняется больше десятка подряд (App ID, локализованное имя, доступные
# регионы обложек, сами обложки, SteamGridDB…). В сумме это выглядело как
# полное зависание программы на несколько минут.
#
# Эта проверка — короткое TCP-подключение НАПРЯМУЮ по IP (без обращения к DNS,
# который тоже может быть недоступен) к паре надёжных публичных хостов, с
# таймаутом $TimeoutMs на каждый. Результат кэшируется на несколько секунд,
# чтобы не гонять проверку перед каждым отдельным сетевым вызовом внутри одной
# и той же карточки.
$global:__connCheckResult = $null
$global:__connCheckTime = [datetime]::MinValue
function Test-InternetConnectivity ([int]$TimeoutMs = 1000, [switch]$Force) {
    $now = Get-Date
    if (-not $Force -and $null -ne $global:__connCheckResult -and (($now - $global:__connCheckTime).TotalSeconds -lt 5)) {
        return $global:__connCheckResult
    }
    $targets = @(
        @{ Ip = '1.1.1.1'; Port = 443 },   # Cloudflare DNS
        @{ Ip = '8.8.8.8'; Port = 443 },   # Google DNS
        @{ Ip = '23.204.4.100'; Port = 443 } # один из адресов Steam CDN
    )
    $ok = $false
    foreach ($t in $targets) {
        $client = $null
        try {
            $client = New-Object System.Net.Sockets.TcpClient
            $iar = $client.BeginConnect([string]$t.Ip, [int]$t.Port, $null, $null)
            if ($iar.AsyncWaitHandle.WaitOne($TimeoutMs) -and $client.Connected) {
                try { $client.EndConnect($iar) } catch {}
                $ok = $true
            }
        } catch { $ok = $false }
        finally { try { $client.Close() } catch {} }
        if ($ok) { break }
    }
    $global:__connCheckResult = $ok
    $global:__connCheckTime = $now
    return $ok
}

function Save-FirstWorkingUrl ($urls, $destPath, [int]$minSize = 512) {
    if ($urls -eq $null) { return $false }
    foreach ($candidateUrl in @($urls)) {
        if ([string]::IsNullOrEmpty([string]$candidateUrl)) { continue }
        if (Download-RemoteImage ([string]$candidateUrl) $destPath $minSize) { return $true }
    }
    return $false
}

# Пока в карточке игры крутится анимация загрузки, UI-поток не должен намертво
# блокироваться на скачивании: Invoke-WebRequest и "& curl.exe" держат поток до
# конца запроса, перерисовать спиннер в это время некому — он просто застывает.
# Поэтому на время работы карточки поднимается флаг $global:uiPumpDuringDownload:
# тогда файл качает отдельный процесс curl.exe, а мы ждём его, прокачивая очередь
# сообщений WinForms. Никаких обращений к контролам из фонового потока по-прежнему
# нет — всё происходит в UI-потоке, просто он не заблокирован.
$global:uiPumpDuringDownload = $false
# Флаг прерывания текущей карточки. Пока идёт сетевой поиск/загрузка,
# UI продолжает прокачиваться; при закрытии карточки или кнопках «Отмена»/«Пропустить»
# фоновые ожидания должны немедленно прекращаться.
$global:editorLoadAbortRequested = $false
# Идёт ли прямо сейчас загрузка Steam-обложек в карточке, и отложенное
# переключение источника (клик по SGDB во время этой загрузки).
$global:editorSteamLoadBusy = $false
$global:editorPendingSwitchAction = $null
# То же для загрузки SGDB-обложек: клик по переключателю источника во время
# неё тоже не блокируется, а прерывает загрузку и запускает новую.
$global:editorSgdbLoadBusy = $false

# Текущая загрузка/поиск в карточке отменены: либо карточка закрывается
# («Отмена»/«Пропустить»/крестик), либо пользователь уже выбрал другой источник
# (отложенное переключение ждёт, пока загрузчик освободит UI).
function Test-EditorLoadCancelled {
    if ($global:editorLoadAbortRequested) { return $true }
    if ($null -ne $global:editorPendingSwitchAction) { return $true }
    return $false
}

# Выполняет отложенное переключение источника (если оно было запрошено во время
# загрузки/поиска). Вызывается из finally загрузчиков и обработчиков карточки
# уже ПОСЛЕ того, как прерванная операция полностью освободила UI. Флаг
# прерывания сбрасываем, иначе новая загрузка сразу же сочтёт себя отменённой.
function Invoke-EditorPendingSwitch {
    $pending = $global:editorPendingSwitchAction
    if ($null -eq $pending) { return }
    $global:editorPendingSwitchAction = $null
    $global:editorLoadAbortRequested = $false
    try { & $pending } catch {}
}

# ===================== ФОНОВЫЕ (НЕБЛОКИРУЮЩИЕ) JSON-ЗАПРОСЫ =====================
# В отличие от Invoke-UiPumpingDownload (отдельный ПРОЦЕСС curl.exe — подходит
# для скачивания файлов), здесь сетевой вызов выполняется в отдельном
# PowerShell-runspace — это настоящий .NET-поток внутри того же процесса, а не
# внешний процесс. UI-поток при этом свободен и прокачивает очередь сообщений
# (спиннер продолжает крутиться), пока фоновый поток ждёт ответ сервера.
#
# ВАЖНО: это НЕ то же самое, что уже пробовали и откатили в Load-EditorSgdbPreviews
# (см. FIX 8) — там для JSON/autocomplete пытались использовать отдельный
# curl.exe-ПРОЦЕСС на каждый запрос, и именно это вызывало зависания на этапе
# "ищу…". Здесь никаких внешних процессов не создаётся вообще — только
# встроенный runspace, поэтому того риска нет.
#
# Ограничение: scriptblock выполняется в СВОЁМ пустом runspace — у него нет
# доступа к функциям и $global:-переменным основного скрипта. Ему можно
# передать только простые данные через $argumentList (строки, числа, hashtable
# заголовков) и использовать только встроенные команды (Invoke-RestMethod,
# ConvertFrom-Json, curl.exe и т.п.).
function Invoke-BackgroundJsonRequest ($scriptBlock, [object[]]$argumentList, [int]$maxSeconds = 20) {
    $ps = $null
    $async = $null
    try {
        $ps = [System.Management.Automation.PowerShell]::Create()
        [void]$ps.AddScript($scriptBlock)
        if ($argumentList) { foreach ($a in $argumentList) { [void]$ps.AddArgument($a) } }
        $async = $ps.BeginInvoke()
    } catch {
        # Не удалось поднять фоновый runspace (крайне редкий случай) —
        # выполняем как раньше, блокирующим способом, лишь бы не потерять результат.
        try { if ($ps) { $ps.Dispose() } } catch {}
        try { return (& $scriptBlock @argumentList) } catch { return $null }
    }

    $deadline = (Get-Date).AddSeconds([Math]::Max(1, $maxSeconds))
    try {
        while (-not $async.IsCompleted) {
            [System.Windows.Forms.Application]::DoEvents()
            if ($global:editorLoadAbortRequested) {
                try { $ps.Stop() } catch {}
                break
            }
            Start-Sleep -Milliseconds 30
            if ((Get-Date) -gt $deadline) { try { $ps.Stop() } catch {}; break }
        }
        $result = $null
        try { $result = $ps.EndInvoke($async) } catch { $result = $null }
        if ($result -eq $null) { return $null }
        $items = @($result)
        if ($items.Count -eq 0) { return $null }
        if ($items.Count -eq 1) { return $items[0] }
        return $items
    } finally {
        try { $ps.Dispose() } catch {}
    }
}

# ===================== ОБЩАЯ ОБЁРТКА ДЛЯ ЗАПРОСОВ К SteamGridDB =====================
# Нужна, чтобы в ОДНОМ месте отличать HTTP 401 (ключ невалиден/отозван — имеет
# смысл сбросить его и попробовать переполучить ещё раз) от обычного сетевого
# сбоя (таймаут, DNS, 5xx и т.п. — повторять с тем же ключом бессмысленно).
# Раньше эта развилка была вручную продублирована в паре мест (например,
# автодополнение поиска по названию), а в паре других мест (получение
# ассетов по Steam App ID и по SGDB Game ID) её не было вовсе — там любая
# ошибка, включая 401 из-за протухшего ключа, тихо проглатывалась пустым
# catch {}, и пользователь просто видел "обложки не найдены" без единого
# шанса, что ключ переполучится и следующий же запрос в этой карточке уже
# отработает.
#
# Возвращает [PSCustomObject]@{ Success; Data; WasUnauthorized; ErrorMessage }
#   Success         — $true, если запрос (возможно, уже после повторной
#                      попытки с новым ключом) вернул success:true и данные.
#   Data            — тело поля .data ответа SGDB, либо $null.
#   WasUnauthorized — $true, если сервер хоть раз ответил 401 — вызывающий
#                      код может опираться на этот флаг, а не парсить текст
#                      исключения самостоятельно.
#   ErrorMessage    — текст последней ошибки, если Success -eq $false.
function Invoke-SgdbApiRequest ($url, [hashtable]$headers, [int]$timeoutSec = 20, [switch]$NoKeyRetry) {
    $wasUnauthorized = $false
    $errMsg = $null
    $resp = $null
    $is401 = $false

    # Сетевой запрос выполняем в отдельном runspace. UI при этом продолжает
    # прокачиваться, поэтому крестик карточки и кнопки «Отмена/Пропустить»
    # остаются нажимаемыми даже при медленном или зависшем сервере.
    $requestBlock = {
        param($requestUrl, $requestHeaders, $requestTimeout)
        try {
            return (Invoke-RestMethod -Uri $requestUrl -Headers $requestHeaders -UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) SteamCommander' -TimeoutSec $requestTimeout -ErrorAction Stop)
        } catch {
            $st = 0; try { $st = [int]$_.Exception.Response.StatusCode.value__ } catch {}
            return [PSCustomObject]@{ __RequestError = [string]$_.Exception.Message; __Response = $_.Exception.Response; __Status = $st }
        }
    }
    # SteamGridDB стоит за Cloudflare и периодически отвечает 429/5xx, обрывает соединение
    # или не успевает за таймаут. Раньше любой такой сбой сразу превращался в «обложки не
    # загрузились» (и «ключ не проверен»), а через минуту тот же запрос проходил. Теперь
    # временные сбои (нет ответа, 429, 5xx) повторяются с нарастающей паузой; окончательные
    # ответы (401, 404 и т.п.) не повторяются.
    $maxAttempts = 3
    for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
        $errMsg = $null; $resp = $null; $is401 = $false; $httpStatus = 0
        try {
            $bg = Invoke-BackgroundJsonRequest $requestBlock @($url,$headers,$timeoutSec) ([Math]::Max(1,$timeoutSec + 2))
            if ($bg -and $bg.PSObject.Properties['__RequestError']) {
                $errMsg = [string]$bg.__RequestError
                try { $httpStatus = [int]$bg.__Status } catch {}
                $is401 = ($httpStatus -eq 401)
                $resp = $null
            } else {
                $resp = $bg
            }
        } catch {
            $errMsg = [string]$_.Exception.Message
        }
        if ($null -ne $resp -or $is401) { break }
        if ($global:editorLoadAbortRequested) { break }
        $transient = ($httpStatus -eq 0 -or $httpStatus -eq 429 -or $httpStatus -ge 500)
        if (-not $transient -or $attempt -ge $maxAttempts) { break }
        $pauseMs = if ($httpStatus -eq 429) { 2000 * $attempt } else { 700 * $attempt }
        $pauseUntil = (Get-Date).AddMilliseconds($pauseMs)
        while ((Get-Date) -lt $pauseUntil) {
            [System.Windows.Forms.Application]::DoEvents()
            if ($global:editorLoadAbortRequested) { break }
            Start-Sleep -Milliseconds 40
        }
    }

    if ($is401) {
        $wasUnauthorized = $true
        if (-not $NoKeyRetry -and -not $global:editorLoadAbortRequested) {
            # Ключ, скорее всего, отозван/истёк — сбрасываем и переполучаем,
            # затем даём ОДНУ повторную попытку с новым ключом.
            $global:steamGridDbApiKey = ""
            $global:steamGridDbApiKeyValid = $false
            $newKey = [string](Ensure-SteamGridDbApiKey)
            if (-not [string]::IsNullOrWhiteSpace($newKey)) {
                $headers = @{ Authorization = "Bearer $newKey" }
                try {
                    $bg2 = Invoke-BackgroundJsonRequest $requestBlock @($url,$headers,$timeoutSec) ([Math]::Max(1,$timeoutSec + 2))
                    if ($bg2 -and $bg2.PSObject.Properties['__RequestError']) {
                        $errMsg = [string]$bg2.__RequestError
                        $resp = $null
                    } else {
                        $resp = $bg2
                        $errMsg = $null
                    }
                } catch {
                    $errMsg = [string]$_.Exception.Message
                }
            }
        }
    }

    $ok = ($resp -ne $null -and $resp.success -eq $true -and $resp.data -ne $null)
    # Рабочий ответ API = ключ действительно принят, даже если проверка при запуске упала из-за сети.
    if ($resp -ne $null -and $resp.success -eq $true) { $global:steamGridDbApiKeyValid = $true }
    return [PSCustomObject]@{
        Success         = $ok
        Data            = if ($ok) { $resp.data } else { $null }
        WasUnauthorized = $wasUnauthorized
        ErrorMessage    = $errMsg
    }
}

function Invoke-UiPumpingDownload ($url, $targetPath, [int]$maxSeconds = 40, [int]$minSize = 512) {
    # $true  — файл скачан
    # $false — не скачался
    # $null  — не удалось даже запустить curl.exe; вызывающий код должен
    #          пойти обычным (блокирующим) путём.
    $proc = $null
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = 'curl.exe'
        $psi.Arguments = '-L -s -S -f --connect-timeout 10 --max-time {0} -A "Mozilla/5.0" -o "{1}" "{2}"' -f $maxSeconds, $targetPath, $url
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $proc = New-Object System.Diagnostics.Process
        $proc.StartInfo = $psi
        if (-not $proc.Start()) { return $null }
    } catch { return $null }

    $exitCode = 1
    try {
        $deadline = (Get-Date).AddSeconds([Math]::Max(5, $maxSeconds) + 10)
        while (-not $proc.HasExited) {
            [System.Windows.Forms.Application]::DoEvents()
            if ($global:editorLoadAbortRequested) {
                try { $proc.Kill() } catch {}
                break
            }
            Start-Sleep -Milliseconds 40
            if ((Get-Date) -gt $deadline) { try { $proc.Kill() } catch {}; break }
        }
        try { $proc.WaitForExit(2000) | Out-Null } catch {}
        try { $exitCode = [int]$proc.ExitCode } catch { $exitCode = 1 }
    } catch { $exitCode = 1 }
    finally { try { $proc.Dispose() } catch {} }

    if ($exitCode -eq 0 -and (Test-Path $targetPath) -and (Get-Item $targetPath -ErrorAction SilentlyContinue).Length -ge $minSize) { return $true }
    Remove-Item $targetPath -Force -ErrorAction SilentlyContinue
    return $false
}

function Download-RemoteImage ($url, $targetPath, [int]$minSize = 512) {
    if ([string]::IsNullOrWhiteSpace([string]$url)) { return $false }
    try {
        $parent = Split-Path -Parent $targetPath
        if (-not (Test-Path $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
    } catch {}

    # Карточка игры: качаем так, чтобы анимация загрузки продолжала крутиться.
    if ($global:uiPumpDuringDownload) {
        $pumped = Invoke-UiPumpingDownload $url $targetPath 40 $minSize
        if ($pumped -eq $true) { return $true }
        if ($pumped -eq $false) { return $false }
        # $null — curl.exe недоступен, идём обычным путём ниже.
    }

    try {
        Invoke-WebRequest -Uri $url -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 30 -UseBasicParsing -OutFile $targetPath -ErrorAction Stop
        if ((Test-Path $targetPath) -and (Get-Item $targetPath).Length -ge $minSize) { return $true }
    } catch {}
    Remove-Item $targetPath -Force -ErrorAction SilentlyContinue
    try {
        & curl.exe -L -s -S -f --connect-timeout 10 --max-time 40 -A "Mozilla/5.0" $url -o $targetPath 2>$null
        if ($LASTEXITCODE -eq 0 -and (Test-Path $targetPath) -and (Get-Item $targetPath).Length -ge $minSize) { return $true }
    } catch {}
    Remove-Item $targetPath -Force -ErrorAction SilentlyContinue
    return $false
}

function Get-SteamGridDbAssetsBySteamAppId ($steamAppId) {
    if ([string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey)) { return $null }
    $headers = @{ Authorization = "Bearer $($global:steamGridDbApiKey)" }
    $result = [ordered]@{ Grids = @(); Heroes = @(); Logos = @(); Icons = @() }
    foreach ($kind in @('grids','heroes','logos','icons')) {
        $url = "https://www.steamgriddb.com/api/v2/$kind/steam/$steamAppId"
        $r = Invoke-SgdbApiRequest $url $headers 30
        if ($r.Success) {
            $prop = $kind.Substring(0,1).ToUpper() + $kind.Substring(1)
            $result[$prop] = @($r.Data)
        }
    }
    $total = @($result.Grids).Count + @($result.Heroes).Count + @($result.Logos).Count + @($result.Icons).Count
    if ($total -eq 0) { return $null }
    return [PSCustomObject]$result
}

function Try-FillMissingLogoFromSteamGridDB ($steamAppId) {
    if (Test-Path (Join-Path $global:tempCovers 'temp_logo.png')) { return $true }
    if ([string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey)) { return $false }
    $assets = Get-SteamGridDbAssetsBySteamAppId $steamAppId
    if ($assets -eq $null -or @($assets.Logos).Count -eq 0) { return $false }
    foreach ($logo in @($assets.Logos)) {
        if (Download-RemoteImage ([string]$logo.url) (Join-Path $global:tempCovers 'temp_logo.png')) { return $true }
    }
    return $false
}

function Try-FillMissingIconFromSteamGridDB ($steamAppId) {
    if ($null -ne (Get-TempIconPath)) { return $true }
    if ([string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey)) { return $false }
    $assets = Get-SteamGridDbAssetsBySteamAppId $steamAppId
    if ($assets -eq $null -or @($assets.Icons).Count -eq 0) { return $false }
    foreach ($ic in @($assets.Icons | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})) {
        $url = [string]$ic.url
        if ([string]::IsNullOrWhiteSpace($url)) { continue }
        $ext = '.png'
        try {
            if ($url -match '\.ico(\?|$)') { $ext = '.ico' }
            elseif ($url -match '\.jpe?g(\?|$)') { $ext = '.jpg' }
        } catch {}
        $dest = Join-Path $global:tempCovers ("temp_icon" + $ext)
        if (Download-RemoteImage $url $dest) { Repair-IconFileExtension $dest | Out-Null; return $true }
    }
    return $false
}

function Download-CoversToTemp ($cleanAppID, [bool]$allowSgdbLogo = $true) {
    # Защита от зависания при отсутствии интернета: без этой проверки ниже
    # выполнилась бы длинная цепочка сетевых попыток (PICS, прямые ссылки CDN,
    # официальный API, SteamGridDB), каждая — со своим таймаутом.
    if (-not (Test-InternetConnectivity)) { return }
    # БАГ-ФИКС: без очистки temp-папки перед каждым скачиванием при пакетном
    # добавлении нескольких игр подряд файл, не найденный (404) для ТЕКУЩЕЙ
    # игры, мог остаться от ПРЕДЫДУЩЕЙ игры (curl.exe с -o не удаляет старый
    # файл, если новый запрос не удался) — и в грид попадала чужая картинка.
    if (Test-Path $global:tempCovers) { Remove-Item $global:tempCovers -Recurse -Force -ErrorAction SilentlyContinue }
    if (-not (Test-Path $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers | Out-Null }
    $hexApps = "68747470733a2f2f7368617265642e616b616d61692e737465616d7374617469632e636f6d2f73746f72655f6974656d5f6173736574732f737465616d2f617070732f"
    $bytesApps = New-Object byte[] ($hexApps.Length / 2)
    for ($i = 0; $i -lt $hexApps.Length; $i += 2) { $bytesApps[$i/2] = [Convert]::ToByte($hexApps.Substring($i, 2), 16) }
    $baseApps = [System.Text.Encoding]::ASCII.GetString($bytesApps)
    
    # БАГ-ФИКС: без флага -f curl.exe при ответе 404 от CDN (у некоторых
    # изданий/бандлов нет всех четырёх картинок) всё равно СОЗДАВАЛ файл
    # по пути -o (с телом ошибки или пустой) — Test-Path в местах применения
    # считал такой файл существующим, и в итоге в grid Steam попадала
    # битая/пустая "обложка" вместо того, чтобы честно пропустить
    # отсутствующий ассет. Теперь curl с -f не пишет файл при HTTP-ошибке,
    # а на всякий случай (некоторые сборки curl всё равно оставляют пустой
    # файл) дополнительно чистим файлы подозрительно малого размера.

    # ЛОКАЛИЗАЦИЯ: если в «Настройках» выбран не английский язык, СНАЧАЛА берём
    # обложки/логотип на этом языке из PICS (library_assets_full хранит файлы
    # по языкам). Прямые ссылки ниже всегда отдают стандартную (английскую)
    # версию, поэтому они используются только для того, чего ещё не хватает.
    # Если у игры нет локализованных ассетов — PICS сам отдаёт английские.
    $steamLang = Get-SteamAssetLanguage
    $pics = $null
    # Язык, на котором в итоге загрузились обложки (показывает кнопка региона в карточке).
    $script:lastCoversLanguage = 'english'
    if ($steamLang -ne 'english') {
        $pics = Get-SteamPicsAssetUrls $cleanAppID $steamLang
        if ($pics -ne $null) {
            Save-FirstWorkingUrl $pics.Capsule (Join-Path $global:tempCovers "temp_p.jpg")      | Out-Null
            Save-FirstWorkingUrl $pics.Hero    (Join-Path $global:tempCovers "temp_hero.jpg")   | Out-Null
            Save-FirstWorkingUrl $pics.Header  (Join-Path $global:tempCovers "temp_header.jpg") | Out-Null
            Save-FirstWorkingUrl $pics.Logo    (Join-Path $global:tempCovers "temp_logo.png")   | Out-Null
            foreach ($picsFile in @("temp_p.jpg", "temp_hero.jpg", "temp_header.jpg", "temp_logo.png")) {
                if (Test-Path (Join-Path $global:tempCovers $picsFile)) { $script:lastCoversLanguage = [string]$pics.Language; break }
            }
        }
    }

    if (Test-EditorLoadCancelled) { return }
    if (-not (Test-Path (Join-Path $global:tempCovers "temp_p.jpg")))      { Download-RemoteImage "${baseApps}${cleanAppID}/library_600x900.jpg" (Join-Path $global:tempCovers "temp_p.jpg") | Out-Null }
    if (-not (Test-Path (Join-Path $global:tempCovers "temp_hero.jpg")))   { Download-RemoteImage "${baseApps}${cleanAppID}/library_hero.jpg" (Join-Path $global:tempCovers "temp_hero.jpg") | Out-Null }
    if (-not (Test-Path (Join-Path $global:tempCovers "temp_logo.png")))   { Download-RemoteImage "${baseApps}${cleanAppID}/logo.png" (Join-Path $global:tempCovers "temp_logo.png") | Out-Null }
    if (-not (Test-Path (Join-Path $global:tempCovers "temp_header.jpg"))) { Download-RemoteImage "${baseApps}${cleanAppID}/header.jpg" (Join-Path $global:tempCovers "temp_header.jpg") | Out-Null }

    if (Test-EditorLoadCancelled) { return }
    # Иконка приложения (clienticon/.ico или icon/.jpg → temp_icon.png).
    try { Download-SteamIconToTemp $cleanAppID $false | Out-Null } catch {}

    foreach ($tempFile in @("temp_p.jpg", "temp_hero.jpg", "temp_logo.png", "temp_header.jpg")) {
        $tempFilePath = Join-Path $global:tempCovers $tempFile
        if ((Test-Path $tempFilePath) -and (Get-Item $tempFilePath).Length -lt 512) {
            Remove-Item $tempFilePath -Force -ErrorAction SilentlyContinue
        }
    }
    foreach ($tempFile in @("temp_icon.ico", "temp_icon.png", "temp_icon.jpg")) {
        $tempFilePath = Join-Path $global:tempCovers $tempFile
        if ((Test-Path $tempFilePath) -and (Get-Item $tempFilePath).Length -lt 64) {
            Remove-Item $tempFilePath -Force -ErrorAction SilentlyContinue
        }
    }

    # БАГ-ФИКС: прямое угадывание ссылки по фиксированному шаблону выше не
    # находит обложку для игр с CDN-путём на хеш-префиксе (см. комментарий
    # у Get-SteamAssetUrlsViaApi) — раньше это приводило к ложному "обложка
    # не найдена"/"только фон без обложки", хотя обложка у игры реально
    # есть.
    #
    # БАГ-ФИКС: раньше API-фолбэк запускался, только если ОБА — и капсула,
    # и header — не скачались напрямую. Из-за этого, если капсула успешно
    # скачивалась по старому пути, а вот логотип (у него своя, отдельная
    # хеш-часть в пути) — нет, логотип так и оставался недокачанным: до
    # него просто не доходило дело. Теперь каждая из четырёх картинок
    # проверяется НЕЗАВИСИМО, и если не хватает хотя бы одной — запрашиваем
    # точные ссылки через официальный API и докачиваем именно то, чего
    # не хватает (остальные, уже скачанные напрямую, не трогаем).
    $missingCapsule = -not (Test-Path (Join-Path $global:tempCovers "temp_p.jpg"))
    $missingHero    = -not (Test-Path (Join-Path $global:tempCovers "temp_hero.jpg"))
    $missingHeader  = -not (Test-Path (Join-Path $global:tempCovers "temp_header.jpg"))
    $missingLogo    = -not (Test-Path (Join-Path $global:tempCovers "temp_logo.png"))
    if ($missingCapsule -or $missingHero -or $missingHeader -or $missingLogo) {
        if (Test-EditorLoadCancelled) { return }
        $resolved = Get-SteamAssetUrlsViaApi $cleanAppID $steamLang
        if ($resolved -ne $null) {
            if ($missingCapsule) { Save-FirstWorkingUrl $resolved.Capsule (Join-Path $global:tempCovers "temp_p.jpg") | Out-Null }
            if ($missingHero)    { Save-FirstWorkingUrl $resolved.Hero    (Join-Path $global:tempCovers "temp_hero.jpg") | Out-Null }
            if ($missingHeader)  { Save-FirstWorkingUrl $resolved.Header  (Join-Path $global:tempCovers "temp_header.jpg") | Out-Null }
            if ($missingLogo)    { Save-FirstWorkingUrl $resolved.Logo    (Join-Path $global:tempCovers "temp_logo.png") | Out-Null }
            foreach ($tempFile in @("temp_p.jpg", "temp_hero.jpg", "temp_logo.png", "temp_header.jpg")) {
                $tempFilePath = Join-Path $global:tempCovers $tempFile
                if ((Test-Path $tempFilePath) -and (Get-Item $tempFilePath).Length -lt 512) {
                    Remove-Item $tempFilePath -Force -ErrorAction SilentlyContinue
                }
            }
        }
    }

    # БАГ-ФИКС: последний рубеж для ОФИЦИАЛЬНЫХ ресурсов Steam — PICS.
    # Сюда почти всегда попадает логотип (в GetItems его нет вовсе, а прямой
    # путь без хеш-префикса у новых игр отдаёт 404). Капсулу/hero/header тоже
    # пробуем добрать здесь, если предыдущие шаги их не нашли. Только после
    # этого имеет смысл уходить в SteamGridDB.
    $missingCapsule = -not (Test-Path (Join-Path $global:tempCovers "temp_p.jpg"))
    $missingHero    = -not (Test-Path (Join-Path $global:tempCovers "temp_hero.jpg"))
    $missingHeader  = -not (Test-Path (Join-Path $global:tempCovers "temp_header.jpg"))
    $missingLogo    = -not (Test-Path (Join-Path $global:tempCovers "temp_logo.png"))
    # Если PICS уже опрошен выше (для локализованных обложек) и вернул данные —
    # повторно не запрашиваем и те же ссылки не пробуем.
    if (($missingCapsule -or $missingHero -or $missingHeader -or $missingLogo) -and $pics -eq $null) {
        $pics = Get-SteamPicsAssetUrls $cleanAppID $steamLang
        if ($pics -ne $null) {
            if ($missingCapsule) { Save-FirstWorkingUrl $pics.Capsule (Join-Path $global:tempCovers "temp_p.jpg")      | Out-Null }
            if ($missingHero)    { Save-FirstWorkingUrl $pics.Hero    (Join-Path $global:tempCovers "temp_hero.jpg")   | Out-Null }
            if ($missingHeader)  { Save-FirstWorkingUrl $pics.Header  (Join-Path $global:tempCovers "temp_header.jpg") | Out-Null }
            if ($missingLogo)    { Save-FirstWorkingUrl $pics.Logo    (Join-Path $global:tempCovers "temp_logo.png")   | Out-Null }
            foreach ($tempFile in @("temp_p.jpg", "temp_hero.jpg", "temp_logo.png", "temp_header.jpg")) {
                $tempFilePath = Join-Path $global:tempCovers $tempFile
                if ((Test-Path $tempFilePath) -and (Get-Item $tempFilePath).Length -lt 512) {
                    Remove-Item $tempFilePath -Force -ErrorAction SilentlyContinue
                }
            }
        }
    }

    if ($allowSgdbLogo -and $null -eq (Get-TempIconPath)) {
        try { Try-FillMissingIconFromSteamGridDB $cleanAppID | Out-Null } catch {}
    }

    if ($allowSgdbLogo -and -not (Test-Path (Join-Path $global:tempCovers "temp_logo.png"))) {
        Try-FillMissingLogoFromSteamGridDB $cleanAppID | Out-Null
    }
}

# БАГ-ФИКС: раньше найденный App ID принимался "как есть", даже если у него
# реально скачивался ТОЛЬКО широкий фон (hero) — без вертикальной капсулы
# (library_600x900) и без header. Это верный признак, что App ID указывает
# не на ту игру: у чужой/похожей страницы нашёлся общий фон, но не сама
# обложка (именно так вели себя Planet of Lana II, Plants vs. Zombies:
# Replanted и Resonance: A Plague Tale Legacy). Считаем обложки "нормальными"
# только если скачалась хотя бы капсула ИЛИ header — то, что реально
# показывается в библиотеке Steam.
function Test-CoversValid {
    $hasCapsule = Test-Path (Join-Path $global:tempCovers "temp_p.jpg")
    $hasHeader  = Test-Path (Join-Path $global:tempCovers "temp_header.jpg")
    return ($hasCapsule -or $hasHeader)
}

# «Отпечаток» временных обложек и иконки карточки (имя|размер|время записи). Снимается сразу после
# загрузки карточки и перед сохранением: если отпечаток не изменился, обложки не трогали, и ради одних
# библиотек Steam закрывать не нужно. Любое сомнение трактуется как «изменилось».
function Get-EditorCoverFingerprint {
    $parts = New-Object System.Collections.ArrayList
    $files = New-Object System.Collections.ArrayList
    foreach ($n in @('temp_p.jpg', 'temp_header.jpg', 'temp_hero.jpg', 'temp_logo.png')) { [void]$files.Add((Join-Path $global:tempCovers $n)) }
    try { $ic = Get-TempIconPath; if ($null -ne $ic) { [void]$files.Add([string]$ic) } else { [void]$files.Add('') } } catch { [void]$files.Add('?') }
    foreach ($f in $files) {
        try {
            if ([string]::IsNullOrEmpty($f)) { [void]$parts.Add('-'); continue }
            if ($f -eq '?') { [void]$parts.Add('?' + [guid]::NewGuid().ToString('N')); continue }
            if ([System.IO.File]::Exists($f)) {
                $fi = New-Object System.IO.FileInfo($f)
                [void]$parts.Add(($fi.Name + '|' + $fi.Length + '|' + $fi.LastWriteTimeUtc.Ticks))
            } else { [void]$parts.Add(([System.IO.Path]::GetFileName($f) + '|-')) }
        } catch { [void]$parts.Add('?' + [guid]::NewGuid().ToString('N')) }
    }
    return ($parts -join ';')
}

# Добирает ТОЛЬКО отсутствующие типы обложек из SteamGridDB — Steam остаётся
# основным источником, SGDB лишь закрывает пробелы. Вынесено в отдельную
# функцию (раньше было локальным scriptblock-ом внутри старого окна пакетного
# добавления), т.к. теперь используется и тихим автодобавлением
# (Add-GameToSteamQuietly), и осталась бы полезной для карточки при желании.
function Fill-MissingCoversFromSgdb ($steamAppId) {
    if ([string]::IsNullOrWhiteSpace([string]$steamAppId)) { return }
    if ([string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey)) { return }
    try {
        $assets = Get-SteamGridDbAssetsBySteamAppId $steamAppId
        if ($assets -eq $null) { return }
        $targets = @(
            @{ File="temp_p.jpg";      Items=@($assets.Grids | Where-Object {
                $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                (($w -eq 600 -and $h -eq 900) -or ($w -eq 342 -and $h -eq 482) -or ($w -eq 660 -and $h -eq 930))
            } | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true}) },
            @{ File="temp_header.jpg"; Items=@($assets.Grids | Where-Object {
                $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                (($w -eq 920 -and $h -eq 430) -or ($w -eq 460 -and $h -eq 215))
            } | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true}) },
            @{ File="temp_hero.jpg"; Items=@($assets.Heroes | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true}) },
            @{ File="temp_logo.png"; Items=@($assets.Logos  | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true}) }
        )
        foreach ($target in $targets) {
            $path = Join-Path $global:tempCovers $target.File
            if (Test-Path $path) { continue }
            foreach ($asset in @($target.Items)) {
                if ($null -eq $asset -or [string]::IsNullOrWhiteSpace([string]$asset.url)) { continue }
                if (Download-RemoteImage ([string]$asset.url) $path) { break }
            }
        }
    } catch {}
}

# Тихая (без показа карточки) попытка добавить игру в Steam. Срабатывает
# ТОЛЬКО если программа уверена одновременно и в названии (Steam нашёл точное
# совпадение по имени папки), и в исполняемом файле (единственный кандидат
# или он уже закэширован по этому пути — см. $global:exeSelectionCache) —
# то есть ровно те же условия, при которых в обычной карточке у обоих полей
# горит зелёная галочка (см. Set-ConfidenceBadge / $exeConfidentInitial /
# $titleConfidentInitial внутри Show-GameEditorDialog). Если хоть одно из
# двух не подтверждено уверенно, .Handled=$false — вызывающий код обязан
# показать обычную карточку, чтобы пользователь проверил/поправил вручную.
function Add-GameToSteamQuietly ($game) {
    $result = [PSCustomObject]@{ Handled=$false; Success=$false; Reason='' }

    $steamInfo = $null
    try { $steamInfo = Find-SteamAppInfo $game.Name } catch { $steamInfo = $null }
    if ($steamInfo -eq $null -or [string]::IsNullOrWhiteSpace([string]$steamInfo.Id)) {
        $result.Reason = (T 'reason_title_unconfirmed')
        return $result
    }

    # Игра из лаунчера: exe, указанный лаунчером, всегда среди кандидатов; для игр, запускаемых
    # через SCLauncher.exe, отсутствие exe в папке не мешает добавлению (см. Resolve-LauncherExeChoice).
    $isLauncherGame = Test-IsLauncherEntry $game
    $isWrappedGame  = Test-LauncherEntryWrapped $game
    $exeCandidates = @(Get-EditorExecutableCandidates $game.Path)
    if ($isLauncherGame) {
        $mfExeQ = Get-LauncherManifestExe $game
        if ($null -ne $mfExeQ) {
            $mfFoundQ = $false
            foreach ($ce in $exeCandidates) {
                try { if ([string]::Equals([string]$ce.FullName, [string]$mfExeQ.FullName, [System.StringComparison]::OrdinalIgnoreCase)) { $mfFoundQ = $true; break } } catch {}
            }
            if (-not $mfFoundQ) { $exeCandidates = @($exeCandidates) + @($mfExeQ) }
        }
    }
    if (@($exeCandidates).Count -eq 0 -and -not $isWrappedGame) {
        $result.Reason = (T 'reason_exe_missing')
        return $result
    }

    $cacheKey = $game.Path.ToUpper()
    $cached = $null
    try { if ($global:exeSelectionCache.ContainsKey($cacheKey)) { $cached = [string]$global:exeSelectionCache[$cacheKey] } } catch {}
    $idx = -1
    if ($cached) {
        for ($i=0; $i -lt $exeCandidates.Count; $i++) {
            try {
                if ([string]::Equals([string]$exeCandidates[$i].FullName, $cached, [System.StringComparison]::OrdinalIgnoreCase)) { $idx=$i; break }
            } catch {}
        }
    }
    if ($idx -lt 0 -and $isLauncherGame) {
        $lcQ = Resolve-LauncherExeChoice $game $exeCandidates
        if ($lcQ.Index -ge 0) { $idx = $lcQ.Index }
    }
    # Та же уверенность, что и $exeConfidentInitial в карточке: уверенно,
    # если выбор взят из кэша (или из манифеста лаунчера) либо кандидат вообще
    # один — угадывание среди нескольких вариантов сюда не допускается.
    # Игры за SCLauncher.exe: выбор файла на запуск не влияет, поле всегда определено.
    $exeConfident = ($idx -ge 0) -or ($exeCandidates.Count -le 1) -or $isWrappedGame
    $chosenExe = $null
    if (-not $exeConfident) {
        # Несколько кандидатов и нет сохранённого выбора: спрашиваем у Steam,
        # какой файл он считает основным для этого App ID. Подсказка
        # принимается, только если этот файл реально есть в папке игры.
        $hintedExe = $null
        try { $hintedExe = Get-SteamHintedExecutable $game.Path ([string]$steamInfo.Id) } catch { $hintedExe = $null }
        if ($hintedExe -eq $null) {
            $result.Reason = (T 'reason_multi_exe')
            return $result
        }
        $chosenExe = $hintedExe
    } else {
        if ($idx -lt 0) { $idx = 0 }
        if ($exeCandidates.Count -gt 0) { $chosenExe = $exeCandidates[$idx] }
    }

    # Ярлык игры лаунчера с обёрткой: SCLauncher.exe + параметры. Если собрать его нельзя
    # (нет данных в манифесте) — отдаём игру в карточку, где причина будет показана.
    $wrapPlanQ = Get-LauncherWrapPlan $game
    if (-not $wrapPlanQ.Ok) {
        $result.Reason = [string]$wrapPlanQ.Reason
        return $result
    }

    # С этого момента решение принято: и название, и EXE определены
    # уверенно — дальше делаем всё без показа карточки.
    $result.Handled = $true

    $steamPathProperty = $null
    try {
        if ($null -ne $chosenExe) { $global:exeSelectionCache[$cacheKey] = $chosenExe.FullName }

        $appId = [string]$steamInfo.Id
        $displayName = [string]$steamInfo.Name
        try {
            $localizedQuiet = Get-SteamLocalizedAppName $appId ([string](Get-SteamAssetLanguage))
            if (-not [string]::IsNullOrWhiteSpace([string]$localizedQuiet)) { $displayName = [string]$localizedQuiet }
        } catch {}

        # Обе панели равноправны: автоматическое добавление тоже не переносит
        # игру между папками и не создаёт никаких ссылок. Steam получает реальный
        # путь к игре в той панели, где она находится сейчас.
        $finalExe = if ($null -ne $chosenExe) { [string]$chosenExe.FullName } else { '' }
        $finalStart = $game.Path
        $finalLaunchQ = ''
        if ($wrapPlanQ.Wrapped) { $finalExe = [string]$wrapPlanQ.Exe; $finalLaunchQ = [string]$wrapPlanQ.Args }

        # БАГ-ФИКС: раньше здесь (в отличие от карточки игры) флаг
        # $global:uiPumpDuringDownload оставался выключенным, поэтому
        # Invoke-WebRequest/curl.exe качали обложки и иконку БЛОКИРУЮЩЕ —
        # при недоступности/медленном ответе Steam CDN интерфейс мог
        # замереть на десятки секунд во время автодобавления игры.
        # Включаем тот же неблокирующий режим (curl.exe + DoEvents), что
        # используется при открытой карточке.
        $prevUiPump = $global:uiPumpDuringDownload
        $global:uiPumpDuringDownload = $true
        try {
            Download-CoversToTemp $appId $false | Out-Null
            Fill-MissingCoversFromSgdb $appId
        } finally {
            $global:uiPumpDuringDownload = $prevUiPump
        }

        # «Использовать иконки из EXE»: иконка игры — из выбранного EXE, а не из Steam.
        $autoExeIcon = $false
        try {
            if ([bool]$global:useExeIcons -and -not [bool]$script:romsModeEnabled -and $null -ne $chosenExe) { $autoExeIcon = [bool](Use-ExeIconInTemp ([string]$chosenExe.FullName)) }
        } catch { $autoExeIcon = $false }

        $newId = Add-ShortcutToSteam $displayName $finalExe $finalStart $finalLaunchQ
        if (-not $newId) {
            $result.Success = $false
            $result.Reason = if ($global:lastShortcutError) { [string]$global:lastShortcutError } else { (T 'reason_shortcut_fail') }
            return $result
        }
        # Запоминаем полную папку игры из панели (корень для поиска DLSS в библиотеке).
        try { Set-GameFolderForShortcut $finalExe $finalLaunchQ ([string]$game.Path) } catch {}

        if (Test-CoversValid) {
            Copy-TempCoversDirectlyToGrid $newId | Out-Null
            # Регион обложек (из «Настроек» / фактический fallback english) — чтобы
            # при позже открытой карточке кнопка региона совпадала с сохранённым.
            try {
                $coverLang = [string]$script:lastCoversLanguage
                if ([string]::IsNullOrWhiteSpace($coverLang)) { $coverLang = [string](Get-SteamAssetLanguage) }
                $quietSlots = [PSCustomObject]@{
                    Vertical   = [PSCustomObject]@{ Source = 'Steam' }
                    Horizontal = [PSCustomObject]@{ Source = 'Steam' }
                    Hero       = [PSCustomObject]@{ Source = 'Steam' }
                    Logo       = [PSCustomObject]@{ Source = 'Steam' }
                    Icon       = [PSCustomObject]@{ Source = $(if ($autoExeIcon) { 'Local' } else { 'Steam' }) }
                }
                Save-CoverSourcesMetadata ([string]$newId) $quietSlots $coverLang | Out-Null
            } catch {}
        } else {
            # Обложек нет, но положение логотипа «по умолчанию» всё равно записываем.
            try {
                $defLogoPos = Get-LogoDefaultPosition
                if ($null -ne $defLogoPos) { [void](Set-SteamLogoPositionForAllProfiles ([string]$newId) $defLogoPos) }
            } catch {}
        }
        $global:folderDisplayNameCache[$game.Path.ToUpper()] = $displayName
        $result.Success = $true
    } catch {
        $result.Success = $false
        $result.Reason = $_.Exception.Message
    }
    return $result
}
# ===================== ТИХОЕ ДОБАВЛЕНИЕ РОМА (без карточки) =====================
# Загрузка обложек рома из SteamGridDB без карточки: те же правила выбора, что у
# Load-EditorSgdbPreviews (лучший по score вариант каждого типа, файлы в
# $global:tempCovers), но без слотов и строки статуса. Возвращает число
# загруженных картинок. Между картинками проверяется отмена пакета.
function Get-RomSgdbCoversQuiet ([int]$sgdbGameId) {
    if ($sgdbGameId -le 0) { return 0 }
    if (-not (Test-InternetConnectivity)) { return 0 }
    $apiKey = [string](Ensure-SteamGridDbApiKey)
    if ([string]::IsNullOrWhiteSpace($apiKey)) { return 0 }
    $headers = @{ Authorization = "Bearer $apiKey" }

    $assets = $null
    try { $assets = Get-SgdbAssetsForGame $sgdbGameId $headers } catch { $assets = $null }
    if ($null -eq $assets) { return 0 }

    $vertical   = @($assets.GridsVertical)
    $horizontal = @($assets.GridsHorizontal)
    $heroes     = @($assets.Heroes)
    $logos      = @($assets.Logos)
    $icons = @()
    try { $icons = @($assets.Icons) } catch { $icons = @() }

    $iconUrl = if ($icons.Count -gt 0) { [string]$icons[0].url } else { $null }
    $iconFile = Join-Path $global:tempCovers 'temp_icon.png'
    if (-not [string]::IsNullOrWhiteSpace($iconUrl) -and $iconUrl -match '\.ico(\?|$)') { $iconFile = Join-Path $global:tempCovers 'temp_icon.ico' }
    elseif (-not [string]::IsNullOrWhiteSpace($iconUrl) -and $iconUrl -match '\.jpe?g(\?|$)') { $iconFile = Join-Path $global:tempCovers 'temp_icon.jpg' }

    $urls = @(
        [PSCustomObject]@{ Key='Vertical';   Url=$(if ($vertical.Count -gt 0)   { [string]$vertical[0].url }   else { $null }); File=(Join-Path $global:tempCovers 'temp_p.jpg') },
        [PSCustomObject]@{ Key='Horizontal'; Url=$(if ($horizontal.Count -gt 0) { [string]$horizontal[0].url } else { $null }); File=(Join-Path $global:tempCovers 'temp_header.jpg') },
        [PSCustomObject]@{ Key='Hero';       Url=$(if ($heroes.Count -gt 0)     { [string]$heroes[0].url }     else { $null }); File=(Join-Path $global:tempCovers 'temp_hero.jpg') },
        [PSCustomObject]@{ Key='Logo';       Url=$(if ($logos.Count -gt 0)      { [string]$logos[0].url }      else { $null }); File=(Join-Path $global:tempCovers 'temp_logo.png') },
        [PSCustomObject]@{ Key='Icon';       Url=$iconUrl; File=$iconFile }
    )

    $loaded = 0
    foreach ($u in $urls) {
        if ($script:batchCardCancelRequested) { break }
        if ([string]::IsNullOrWhiteSpace([string]$u.Url)) { continue }
        if (Download-RemoteImage ([string]$u.Url) ([string]$u.File)) {
            if ($u.Key -eq 'Icon') { try { [void](Repair-IconFileExtension ([string]$u.File)) } catch {} }
            $loaded++
        }
        [System.Windows.Forms.Application]::DoEvents()
    }
    return $loaded
}

# Тихое добавление рома: тот же контракт {Handled, Success, Reason}, что у
# Add-GameToSteamQuietly. Повторяет то, что делает карточка рома (Show-GameEditorDialog),
# но без окна: название и обложки из SteamGridDB, файл рома по правилу уверенности
# карточки, активный эмулятор, параметры запуска, обёртка для архивов.
# Handled = $false — что-то определено неуверенно, до любых изменений в Steam:
# ром нужно показать в обычной видимой карточке.
function Add-RomToSteamQuietly ($game) {
    $result = [PSCustomObject]@{ Handled=$false; Success=$false; Reason='' }

    $gamePath = [string]$game.Path
    if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath)) {
        $result.Reason = (T 'rom_file_gone')
        return $result
    }

    # Название: имя файла без расширения (как в начале Show-GameEditorDialog).
    $title = [string]$game.Name
    if (Test-Path -LiteralPath $gamePath -PathType Leaf) {
        try { $title = [string](Get-RomFileTitle $gamePath) } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($title)) { $title = [string]$game.Name }

    # Эмулятор: активный профиль, его exe и рабочая папка должны существовать.
    $emu = Get-ActiveEmulatorProfile
    if ($null -eq $emu) {
        $result.Reason = (T 'st_pick_emulator')
        return $result
    }
    $emuExe = [string]$emu.ExePath
    if ([string]::IsNullOrWhiteSpace($emuExe) -or -not (Test-Path -LiteralPath $emuExe)) {
        $result.Reason = (T 'st_emulator_gone')
        return $result
    }
    $startDir = ''
    try { $startDir = [System.IO.Path]::GetDirectoryName($emuExe) } catch {}
    if ([string]::IsNullOrWhiteSpace($startDir) -or -not (Test-Path -LiteralPath $startDir -PathType Container)) {
        $result.Reason = (T 'st_no_workdir')
        return $result
    }

    # Файл рома: кандидаты и правило уверенности те же, что в $populateRomCandidates карточки.
    $exts = [string]$emu.Extensions
    $extractOn = Test-EmulatorExtractArchives $emu
    $romCands = @(Get-EditorRomCandidates $gamePath $exts ([bool]$extractOn))
    if ($extractOn) { try { $romCands = @(Expand-RomArchiveCandidates $romCands $exts) } catch {} }
    if ($romCands.Count -eq 0) {
        $result.Reason = (T 'rom_badge_none')
        return $result
    }
    $bestIdx = 0
    for ($i = 0; $i -lt $romCands.Count; $i++) { if ([bool]$romCands[$i].IsKnown) { $bestIdx = $i; break } }
    $bestRom = $romCands[$bestIdx]
    $knownRoms = @($romCands | Where-Object { [bool]$_.IsKnown })
    $baseRoms = @($knownRoms | Where-Object { [int]$_.RomPriority -eq -100 })
    $romConfident = [bool]$bestRom.IsKnown -and (($knownRoms.Count -le 1) -or ($baseRoms.Count -eq 1 -and [int]$bestRom.RomPriority -eq -100))
    $pec = $bestRom.PSObject.Properties['EntryConfident']
    if ($null -ne $pec -and -not [bool]$pec.Value) { $romConfident = $false }
    if (-not $romConfident) {
        $result.Reason = (T 'rom_badge_unsure')
        return $result
    }
    $romFile = [string]$bestRom.FullName
    $romEntry = ''
    $pae = $bestRom.PSObject.Properties['ArchiveEntry']
    if ($null -ne $pae -and $null -ne $pae.Value) { $romEntry = [string]$pae.Value }

    if ($script:batchCardCancelRequested) { return $result }

    # Название в SteamGridDB: берём лучший вариант поиска, как карточка при открытии.
    $sgdbCands = @()
    try { $sgdbCands = @(Get-EditorSgdbCandidates $title '') } catch { $sgdbCands = @() }
    if ($sgdbCands.Count -eq 0 -or [string]::IsNullOrWhiteSpace([string]$sgdbCands[0].Name) -or [int]$sgdbCands[0].Id -le 0) {
        $result.Reason = (T 'badge_title_fail_auto')
        return $result
    }
    # Автоматически не берём другую часть серии: пусть пользователь выберет в карточке.
    if ((Get-TitleSeqKey $title) -ne (Get-TitleSeqKey ([string]$sgdbCands[0].Name))) {
        $result.Reason = (T 'badge_title_fail_auto')
        return $result
    }
    $sgdbId = [int]$sgdbCands[0].Id
    $displayName = [string]$sgdbCands[0].Name

    if ($script:batchCardCancelRequested) { return $result }

    # Параметры запуска: шаблон эмулятора (для RetroArch — с ядром профиля) с путём к рому.
    $launch = ''
    try {
        $argsTemplate = [string]$emu.Args
        if (Test-IsRetroArchProfile ([string]$emu.Name) $emuExe) {
            $argsTemplate = Merge-RetroArchCoreArgs $argsTemplate ([string]$emu.Core)
        }
        $launch = [string](Format-EmulatorLaunchArgs $argsTemplate $romFile)
    } catch { $launch = '' }

    # Архив, который эмулятор сам не откроет: ярлык = SCLauncher.exe с параметрами.
    # Неудача — не молчаливое добавление ярлыка на архив, а передача в карточку.
    $wrapExe = ''
    $wrapArgs = ''
    if ($extractOn) {
        $romWrap = $null
        try {
            if (Test-IsRetroArchProfile ([string]$emu.Name) $emuExe) {
                $romWrap = Get-RomArchiveWrapPlan $romFile $emuExe $launch $romEntry
            } else {
                $romWrap = Get-EmulatorArchiveWrapPlan $romFile $emuExe $launch $exts $romEntry
            }
        } catch {
            try { Write-LauncherLog ('rom wrap plan failed: ' + [string]$_.Exception.Message) } catch {}
            $romWrap = [PSCustomObject]@{ Wrapped = $false; Ok = $false; Exe = ''; Args = ''; Reason = (T 'st_launcher_wrap_fail') }
        }
        if ($null -ne $romWrap) {
            if (-not $romWrap.Ok) {
                $result.Reason = [string]$romWrap.Reason
                return $result
            }
            if ($romWrap.Wrapped) { $wrapExe = [string]$romWrap.Exe; $wrapArgs = [string]$romWrap.Args }
        }
    }

    if ($script:batchCardCancelRequested) { return $result }

    # Обложки: скачиваем во временную папку неблокирующим способом (curl.exe + DoEvents).
    # Если ни капсулы, ни заголовка нет — карточка, где обложки можно выбрать вручную.
    $prevUiPump = $global:uiPumpDuringDownload
    $global:uiPumpDuringDownload = $true
    try {
        Clear-TempCoverFiles
        [void](Get-RomSgdbCoversQuiet $sgdbId)
    } finally {
        $global:uiPumpDuringDownload = $prevUiPump
    }
    if ($script:batchCardCancelRequested) { return $result }
    if (-not (Test-CoversValid)) {
        $result.Reason = (T 'sl_sg_imgfail')
        return $result
    }

    # С этого момента решение принято: всё определено уверенно — пишем ярлык без карточки.
    $result.Handled = $true
    try {
        $finalExe = $emuExe
        $finalLaunch = $launch
        if ($wrapExe) { $finalExe = $wrapExe; $finalLaunch = $wrapArgs }

        $global:folderDisplayNameCache[$gamePath.ToUpper()] = $displayName
        $newId = Add-ShortcutToSteam $displayName $finalExe $startDir $finalLaunch
        if (-not $newId) {
            $result.Success = $false
            $result.Reason = if ($global:lastShortcutError) { [string]$global:lastShortcutError } else { (T 'reason_shortcut_fail') }
            return $result
        }

        # Положение логотипа по умолчанию подставит сама Copy-TempCoversDirectlyToGrid.
        Copy-TempCoversDirectlyToGrid $newId | Out-Null
        try {
            $quietSlots = [PSCustomObject]@{
                Vertical   = [PSCustomObject]@{ Source = 'SteamGridDB' }
                Horizontal = [PSCustomObject]@{ Source = 'SteamGridDB' }
                Hero       = [PSCustomObject]@{ Source = 'SteamGridDB' }
                Logo       = [PSCustomObject]@{ Source = 'SteamGridDB' }
                Icon       = [PSCustomObject]@{ Source = 'SteamGridDB' }
            }
            Save-CoverSourcesMetadata ([string]$newId) $quietSlots '' | Out-Null
        } catch {}
        $result.Success = $true
    } catch {
        $result.Success = $false
        $result.Reason = $_.Exception.Message
    }
    return $result
}

# Вынесено из btnAddToSteam, чтобы этой же логикой мог пользоваться btnApplyCoversNow
# (иначе им пришлось бы искать exe по-разному и получать разные ID)
#
# БАГ-ФИКС: раньше при выборе игры с несколькими exe диалог "Выбор запуска"
# показывался КАЖДЫЙ раз, когда для этой же игры вызывалась Get-GameExecutable —
# то есть один раз при "Добавить в Steam" и ещё раз при "Применить обложки".
# Теперь выбор пользователя (или автоматически найденный exe) кэшируется по
# пути папки игры, и повторный вызов для той же папки просто берёт его из кэша.
$global:exeSelectionCache = @{}
# Запоминает, под каким именно названием (папки или официальным из Steam)
# игра была добавлена ярлыком в текущем сеансе — чтобы кнопка "Применить
# обложки" считала App ID по ТОЙ ЖЕ строке, что реально попала в AppName
# ярлыка при "Добавить выбранные игры в Steam" (иначе ID не совпадёт).
$global:folderDisplayNameCache = @{}

function Test-IsGameLauncherExe ($exe) {
    if ($exe -eq $null) { return $false }
    try {
        # Учитываем имя файла и путь: лаунчеры часто находятся в отдельной
        # папке Launcher/Launchers, даже если само имя EXE не содержит слова.
        return ([string]$exe.FullName -match '(?i)(^|[\\/ _.-])launchers?([\\/ _.-]|$)') -or
               ([string]$exe.BaseName -match '(?i)launchers?')
    } catch { return $false }
}

function Get-GameExecutable ($gamePath, $gameName, [scriptblock]$selectorFn = $null) {
    $cacheKey = $gamePath.ToUpper()
    if ($global:exeSelectionCache.ContainsKey($cacheKey)) {
        $cachedPath = $global:exeSelectionCache[$cacheKey]
        if (Test-Path $cachedPath) {
            $cachedItem = Get-Item -Path $cachedPath
            if ([bool]$global:suggestGameLaunchers -or -not (Test-IsGameLauncherExe $cachedItem)) {
                return $cachedItem
            }
        }
        $global:exeSelectionCache.Remove($cacheKey)
    }

    # БАГ-ФИКС: раньше фильтр отсеивал .exe по ГОЛЫМ подстрокам вроде "crash"
    # или "launcher" — из-за чего под раздачу попадал, например, CrashBandicoot4.exe
    # (это часть НАЗВАНИЯ игры, а не "CrashReporter"), и настоящий exe даже не
    # доходил до диалога выбора. Теперь паттерны куда более точечные: они бьют
    # по конкретным известным служебным утилитам (реран-таймы, крash-репортеры,
    # анти-читы, апдейтеры), а не по случайным словам, которые могут встретиться
    # в имени самой игры. Проверяем полный путь — это ловит ещё и папки вида
    # "_CommonRedist", "Engine\Extras\Redist" независимо от имени самого файла.
    #
    # ДОПОЛНЕНИЕ: папка "\runtimes" целиком (там лежат подпроцессы CefSharp,
    # .NET-раннтаймы и т.п. — никогда не сам исполняемый файл игры), а также
    # конкретные служебные утилиты, которые часто кладут рядом с игрой в папку
    # "\Launcher" (проверщики драйверов/слоёв Vulkan, встроенный браузер
    # лаунчера) — раньше они не отсеивались и засоряли список выбора.
    $junkPattern = '(?i)clientsdkmdnshost|scenecefbrowser|\\cef\\|unins00|\buninstall(er)?\b|unitycrashhandler|crashpad|crashreportclient|crashreporter|crashsender|crashdump|crashupload|crashmonitor|eosbootstrapper|dxwebsetup|crashhandler|crs-handler|crs-uploader|unrealcefsubprocess|\bcefsubprocess\b|\bcefsharp\b|browsersubprocess|driverversionchecker|layerschecker|battleye|easyanticheat|\beac\b|vc_?redist|_?commonredist|\bdotnetfx\b|\bdxsetup\b|\bdirectx\b.*setup|\bprereqsetup\b|physxsetup|vcredist|vulkanrt|\bautorun\b|\bupdater\b|\bpatcher\b|installer\.exe$|_original|_crack|\\Support\\|\\runtimes\\|\\(config|settings|options|cfg)\.exe$'
    
    $allExes = @(Get-ChildItem -LiteralPath $gamePath -Filter "*.exe" -File -Recurse -ErrorAction SilentlyContinue)
    $clean = @($allExes | Where-Object { $_.FullName -notmatch $junkPattern })
    $launcherLikePattern = '(?i)launcher'

    # По умолчанию игровые лаунчеры не участвуют в автоматическом поиске EXE.
    # Если пользователь включил настройку — они остаются среди кандидатов, но
    # по-прежнему имеют более низкий приоритет, чем прямой EXE игры.
    if (-not [bool]$global:suggestGameLaunchers) {
        $clean = @($clean | Where-Object { -not (Test-IsGameLauncherExe $_) })
    }

    # Если фильтр служебных EXE ничего не оставил, возвращаем только исходные
    # EXE, но не нарушаем настройку лаунчеров: при выключенной настройке
    # лаунчеры всё равно не возвращаются.
    if ($clean.Count -eq 0 -and $allExes.Count -gt 0 -and [bool]$global:suggestGameLaunchers) {
        $clean = $allExes
    }

    # Приоритет — файлы прямо в КОРНЕ папки игры. Технический мусор (редистрибутивы,
    # установщики движка, крash-репортеры) почти всегда лежит во вложенных папках;
    # настоящий запускаемый файл игры в подавляющем большинстве случаев лежит в корне.
    $rootExes = $clean | Where-Object { $_.DirectoryName.TrimEnd('\') -eq $gamePath.TrimEnd('\') }
    $preOrdered = if ($rootExes.Count -gt 0) { $rootExes } else { $clean }
    # БАГ-ФИКС: см. аналогичное исправление в Get-EditorExecutableCandidates —
    # без этого первый (и, соответственно, выбранный по умолчанию в диалоге
    # выбора) exe определялся чисто алфавитным порядком, а не тем, похож ли
    # файл на лаунчер, из-за чего диалог мог по умолчанию выделять лаунчер
    # вместо прямого запуска игры.
    $candidates = @($preOrdered | Sort-Object `
        @{Expression={ if ($_.FullName -match $launcherLikePattern) { 1 } else { 0 } }}, `
        Name)

    $resultExe = $null
    if ($candidates.Count -eq 1) {
        $resultExe = $candidates
    } elseif ($candidates.Count -gt 1) {
        $exactMatch = $candidates | Where-Object { $gameName -match [System.Text.RegularExpressions.Regex]::Escape($_.BaseName) -or $_.BaseName -match [System.Text.RegularExpressions.Regex]::Escape($gameName) } | Select-Object -First 1
        if ($exactMatch -ne $null) {
            $resultExe = $exactMatch
        } elseif ($selectorFn -ne $null) {
            $resultExe = & $selectorFn $candidates $gamePath $gameName
        } else {
            $resultExe = Show-ExeSelectionDialog $candidates $gamePath $gameName
        }
    } elseif ($clean.Count -gt 0) {
        $resultExe = ($clean | Sort-Object Length -Descending | Select-Object -First 1)
    }

    if ($resultExe -ne $null) { $global:exeSelectionCache[$cacheKey] = $resultExe.FullName }
    return $resultExe
}

# БАГ-ФИКС: раньше функция возвращала ТОЛЬКО App ID. Из-за этого при добавлении
# ярлыка в Steam использовалось имя папки на диске, а не настоящее название
# игры из магазина Steam. Теперь возвращается объект с Id И Name сразу —
# оба поля берутся из ОДНОГО и того же найденного элемента поиска, так что
# они гарантированно относятся к одной и той же игре.
function Start-PumpedSleep ([int]$milliseconds) {
    # Обычный Start-Sleep держит поток мёртво — даже DoEvents() до/после него
    # не спасает от замирания спиннера ровно на время паузы. Здесь та же
    # пауза, но нарезанная на маленькие кусочки с прокачкой очереди сообщений
    # между ними — сеть это никак не трогает, поэтому риска нет.
    $deadline = (Get-Date).AddMilliseconds([Math]::Max(0, $milliseconds))
    while ((Get-Date) -lt $deadline) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 20
    }
}

# Возвращает официальное локализованное название Steam для App ID в языке,
# выбранном в программе. App ID остаётся единственным идентификатором игры;
# отображаемое название берётся отдельно из Steam Store API.
# Результаты кэшируются на время работы программы, чтобы повторное открытие
# карточки не создавало лишний HTTP-запрос.
$global:steamLocalizedNameCache = @{}

function Get-SteamLocalizedAppName ([string]$appId, [string]$languageCode = '') {
    if([string]::IsNullOrWhiteSpace($appId)) { return $null }
    if (-not (Test-InternetConnectivity)) { return $null }
    $idKey = ([string]$appId).Trim()

    # Разрешаем язык: UI-код (ru/en), Steam-имя (russian/english) или, если пусто, —
    # регион из «Настроек». Если локализации нет — english.
    $steamLanguage = 'english'
    try {
        if ([string]::IsNullOrWhiteSpace([string]$languageCode)) {
            $steamLanguage = [string](Get-SteamAssetLanguage)
        } else {
            $lang = @($script:languageList | Where-Object { $_.Code -eq [string]$languageCode }) | Select-Object -First 1
            if($null -ne $lang -and -not [string]::IsNullOrWhiteSpace([string]$lang.Steam)) {
                $steamLanguage = [string]$lang.Steam
            } else {
                $key = ([string]$languageCode).Trim().ToLowerInvariant()
                $known = $false
                foreach ($l in @($script:steamCoverLanguages)) {
                    if ([string]$l.Steam -eq $key) { $known = $true; break }
                }
                if (-not $known) {
                    foreach ($l in @($script:languageList)) {
                        if ([string]$l.Steam -eq $key) { $known = $true; break }
                    }
                }
                if ($known) { $steamLanguage = $key }
            }
        }
    } catch { $steamLanguage = 'english' }

    $tryLangs = @($steamLanguage)
    if ($steamLanguage -ne 'english') { $tryLangs += 'english' }

    foreach ($lang in $tryLangs) {
        $cacheKey = $idKey + '|' + $lang
        try {
            if ($global:steamLocalizedNameCache.ContainsKey($cacheKey)) {
                $cached = [string]$global:steamLocalizedNameCache[$cacheKey]
                # Непустой кэш — сразу отдаём. Пустой (прошлый сбой) не блокирует
                # повторный запрос: store API мог быть временно недоступен.
                if (-not [string]::IsNullOrWhiteSpace($cached)) { return $cached }
            }
        } catch {}

        $name = $null
        try {
            $url = "https://store.steampowered.com/api/appdetails/?appids=$([System.Uri]::EscapeDataString($idKey))&l=$([System.Uri]::EscapeDataString($lang))"
            $json = $null
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
            try {
                $json = Invoke-RestMethod -Uri $url -Method Get -TimeoutSec 10 -ErrorAction Stop
            } catch {
                try {
                    $raw = (& curl.exe -L --silent --show-error --max-time 10 --connect-timeout 10 --compressed --user-agent "SteamCommander/$($global:appVersion)" $url 2>$null) -join "`n"
                    if (-not [string]::IsNullOrWhiteSpace($raw)) { $json = $raw | ConvertFrom-Json }
                } catch {}
            }
            $entry = $null
            if ($null -ne $json) {
                try {
                    if ($json.PSObject.Properties.Name -contains $idKey) { $entry = $json.$idKey }
                    else { $entry = $json.$idKey }
                } catch {
                    try { $entry = $json.($idKey) } catch {}
                }
            }
            if ($null -ne $entry -and $entry.success -and $null -ne $entry.data -and -not [string]::IsNullOrWhiteSpace([string]$entry.data.name)) {
                $name = [string]$entry.data.name
            }
        } catch {}

        try { $global:steamLocalizedNameCache[$cacheKey] = if ($null -ne $name) { $name } else { '' } } catch {}
        if (-not [string]::IsNullOrWhiteSpace($name)) { return $name }
    }
    return $null
}

function Find-SteamAppInfo ($gameName) {
    $global:lastAppIdSearchError = $null
    $normTarget = Get-NormalizedGameKey $gameName

    # ===== 0) Локальная база приложений Steam (Настройки -> Steam Web API) =====
    # Полная база (весь каталог Steam, не ограниченный выдачей/популярностью
    # витрины) — если она скачана, точное совпадение по названию даёт
    # мгновенный ответ без обращения в интернет. Поиск идёт по индексу в
    # памяти (раньше — Where-Object с регулярным выражением по каждой из
    # ~250 тыс. записей).
    #
    # БАГ-ФИКС: одноимённых игр в Steam бывает несколько (например, два
    # "Keeper" — 2021 г. и Double Fine 2025 г.), а раньше молча брался первый
    # по App ID — то есть почти всегда самая старая. Если "чистых" точных
    # совпадений больше одного, локальная база выбрать не может — тогда
    # решает витрина Steam (она знает, какая из них популярнее), а локальный
    # вариант остаётся запасным на случай, если интернета нет.
    $localFirst = $null
    $localAmbiguous = $false
    try {
        if ([SteamAppsIndex]::EnsureLoaded([string]$global:steamAppsDbFile)) {
            $localExact = @([SteamAppsIndex]::FindExact([string]$gameName, 6))
            if ($localExact.Count -gt 0) {
                $localFirst = [PSCustomObject]@{ Id = [string]$localExact[0].AppId; Name = [string]$localExact[0].Name }
                $cleanExact = @($localExact | Where-Object { -not $_.Junk })
                $localAmbiguous = ($cleanExact.Count -gt 1)
            }
        }
    } catch {}

    if ($null -ne $localFirst -and -not $localAmbiguous) { return $localFirst }

    $onlineFound = Find-SteamAppInfoOnline $gameName
    if ($null -eq $localFirst) { return $onlineFound }

    if ($null -ne $onlineFound -and (Get-NormalizedGameKey ([string]$onlineFound.Name)) -eq $normTarget) {
        return $onlineFound
    }
    $global:lastAppIdSearchError = $null
    return $localFirst
}

# Поиск App ID через онлайн-поиск витрины Steam (без локальной базы).
function Find-SteamAppInfoOnline ($gameName) {
    $global:lastAppIdSearchError = $null
    if (-not (Test-InternetConnectivity)) {
        $global:lastAppIdSearchError = (T 'sl_no_internet')
        return $null
    }
    $normTarget = Get-NormalizedGameKey $gameName
    $targetTokens = Get-NameTokens $gameName

    # ===== 1) Онлайн-поиск витрины Steam (storesearch) =====
    $searchTerm = [System.Uri]::EscapeDataString($gameName)
    $url = "https://store.steampowered.com/api/storesearch/?term=$searchTerm&l=english&cc=us"

    # БАГ-ФИКС: раньше запрос шёл через "curl.exe | ConvertFrom-Json" внутри
    # общего try/catch — при любом сбое (сетевой сбой, временный бан/лимит
    # запросов от Steam, "проглоченный" вывод curl из-за построчного захвата
    # в PowerShell) функция молча возвращала null, и было не понять, это
    # "игры правда нет в Steam" или "запрос не удался". Крупные, абсолютно
    # реальные игры (DiRT 4, Diablo II Resurrected и т.п.) не должны были
    # не находиться в принципе — значит, дело было именно в запросе, а не
    # в сравнении названий.
    #
    # ВАЖНЫЙ НЮАНС: Invoke-RestMethod использует TLS-настройки самого .NET/
    # Windows PowerShell 5.1, а там TLS 1.2 для исходящих HTTPS-запросов
    # по умолчанию иногда НЕ включён (устаревшее системное значение) — тогда
    # Invoke-RestMethod тихо падает с ошибкой соединения, хотя curl.exe
    # (у него свой собственный стек TLS, не зависящий от настроек .NET)
    # прекрасно работает. Поэтому: сначала явно форсируем TLS 1.2/1.3,
    # а если Invoke-RestMethod всё равно не прошёл — откатываемся на curl.exe
    # как запасной вариант (соединяем многострочный вывод ДО ConvertFrom-Json,
    # чтобы PowerShell не разбил JSON на массив строк построчно).
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    } catch {}

    # БАГ-ФИКС (зависание первой карточки): раньше этот запрос шёл прямым
    # блокирующим Invoke-RestMethod прямо в UI-потоке. На первой карточке за
    # сеанс к этому добавлялись "холодный старт" командлета и первое TLS-
    # соединение, и интерфейс со спиннером замирал. Теперь запрос (вместе с
    # запасным curl.exe) выполняется в фоновом runspace через
    # Invoke-BackgroundJsonRequest, а UI-поток прокачивает очередь сообщений.
    $storeSearchRequest = {
        param($u)
        try {
            return (Invoke-RestMethod -Uri $u -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 10 -ErrorAction Stop)
        } catch {
            try {
                $rawLines = curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" --connect-timeout 8 --max-time 12 $u
                $rawJson = ($rawLines -join "")
                if (-not [string]::IsNullOrWhiteSpace($rawJson)) { return ($rawJson | ConvertFrom-Json -ErrorAction Stop) }
            } catch {}
            return $null
        }
    }

    $data = $null
    for ($attempt = 1; $attempt -le 2; $attempt++) {
        $data = Invoke-BackgroundJsonRequest $storeSearchRequest @($url) 25
        if ($data -ne $null) { break }
        $global:lastAppIdSearchError = "storesearch: нет ответа от сервера"
        if ($attempt -lt 2) { Start-PumpedSleep 900 }
    }
    if ($data -eq $null) { return $null }

    # БАГ-ФИКС: пустой результат ("total=0") от storesearch не всегда значит,
    # что игры правда нет в Steam — витрина иногда временно "тупит" на
    # конкретный запрос при частых подряд обращениях (пакетное добавление
    # многих игр). Прежде чем сдаваться, ждём и пробуем тот же запрос ещё раз.
    if ($data.total -lt 1 -or $data.items.Count -eq 0) {
        Start-PumpedSleep 1500
        $data2 = Invoke-BackgroundJsonRequest $storeSearchRequest @($url) 25
        if ($data2 -ne $null -and $data2.total -ge 1 -and $data2.items.Count -gt 0) { $data = $data2 }
    }
    if ($data.total -lt 1 -or $data.items.Count -eq 0) { $global:lastAppIdSearchError = "поиск не вернул результатов"; return $null }

    # БАГ-ФИКС: раньше при отсутствии точного совпадения слепо брался ПЕРВЫЙ
    # результат поиска — а это могла быть совершенно другая игра (поиск Steam
    # не идеален, особенно с апострофами/двоеточиями/приставками "Collection",
    # "Edition" и т.п.). Теперь сравниваем через ту же нормализацию, что и для
    # подсветки "уже установленных" игр (Get-NormalizedGameKey — убирает всю
    # пунктуацию, пробелы и регистр), и если ничего толком не похоже —
    # честно возвращаем "не найдено", а не подсовываем обложку не той игры.
    # ($normTarget и $targetTokens уже вычислены выше.)

    $exact = $data.items | Where-Object { (Get-NormalizedGameKey $_.name) -eq $normTarget } | Select-Object -First 1
    if ($exact -ne $null) { return [PSCustomObject]@{ Id = [string]$exact.id; Name = [string]$exact.name } }

    # Одно название — префикс другого (у нас "Resident Evil 4", в Steam —
    # "Resident Evil 4 Gold Edition" или наоборот). Из всех подходящих под
    # это условие берём тот, чья длина ближе всего к искомой — так меньше
    # риска зацепить непричастную игру с длинным похожим названием.
    #
    # БАГ-ФИКС: раньше здесь не было проверки НАСКОЛЬКО короче одно название
    # другого — из-за этого короткое реальное название вроде "Resonance"
    # (это префикс ЛЮБОЙ строки, начинающейся с этих букв) ложно "совпадало"
    # с папкой вроде "Resonance A Plague Tale Legacy" (склеенное/странное имя
    # папки на диске, не являющееся одной реальной игрой), и в Steam
    # добавлялось совершенно чужое, но похожее по первым буквам название.
    # Теперь совпадение по префиксу/суффиксу засчитывается, только если
    # короткое название покрывает не менее ~65% длины длинного — этого
    # достаточно для случаев вроде "+ Gold/Definitive/Complete Edition",
    # но отсекает совпадения по одному случайно похожему первому слову.
    $prefixMatch = $data.items | Where-Object {
        $nc = Get-NormalizedGameKey $_.name
        if ([string]::IsNullOrEmpty($nc)) { return $false }
        if (Test-SteamNameLooksLikeAddon ([string]$_.name) ([string]$gameName)) { return $false }
        if (-not ($nc.StartsWith($normTarget) -or $normTarget.StartsWith($nc))) { return $false }
        # Префикс должен заканчиваться на границе слова: «StarCraft» ≠ начало «Star Crafter».
        if ($nc.Length -ge $normTarget.Length) {
            if (-not (Test-NameWordBoundaryPrefix $normTarget ([string]$_.name))) { return $false }
        } else {
            if (-not (Test-NameWordBoundaryPrefix $nc ([string]$gameName))) { return $false }
        }
        $shorterLen = [Math]::Min($nc.Length, $normTarget.Length)
        $longerLen = [Math]::Max($nc.Length, $normTarget.Length)
        if ($longerLen -eq 0) { return $false }
        return (($shorterLen / [double]$longerLen) -ge 0.65)
    } | Sort-Object { [Math]::Abs(([int](Get-NormalizedGameKey $_.name).Length) - [int]$normTarget.Length) } | Select-Object -First 1
    if ($prefixMatch -ne $null) { return [PSCustomObject]@{ Id = [string]$prefixMatch.id; Name = [string]$prefixMatch.name } }

    # Последний резерв: нечёткий алгоритм "общие значимые слова"
    # (см. Get-NameTokens / Get-TokenOverlapScore) по результатам storesearch —
    # ловит случаи, где точного/префиксного совпадения нет, но по смыслу
    # слов результат явно тот же самый. Плюс та же проверка на полное
    # вхождение слов папки в название кандидата — для случаев вроде
    # подзаголовка, отсутствующего в имени папки на диске (например, папка
    # "Crash Bandicoot 4" против "Crash Bandicoot 4: It's About Time").
    $best = $null; $bestScore = 0.0
    $bestContainment = $null; $bestContainmentExtra = [int]::MaxValue
    # БАГ-ФИКС (слишком агрессивный поиск): раньше "содержит все слова папки" засчитывалось,
    # где бы эти слова ни стояли — папка "DiRT 4" сопоставлялась с DLC "DiRT Rally 2.0 Deluxe
    # 2.0 (Season3+4)" (там есть слова DiRT и 4). Теперь для нечётких вариантов:
    #  - номера частей (4, V, IV...) у папки и кандидата должны совпадать;
    #  - дополнения/DLC/саундтреки отбрасываются;
    #  - слова папки должны стоять В НАЧАЛЕ названия кандидата (подзаголовок допустим), и
    #    лишних слов не больше четырёх;
    #  - порог похожести по словам поднят с 0.6 до 0.75.
    foreach ($it in $data.items) {
        $itTokens = @(Get-NameTokens $it.name)
        if (-not (Test-NameSequelMarkersMatch $targetTokens $itTokens)) { continue }
        if (Test-SteamNameLooksLikeAddon ([string]$it.name) ([string]$gameName)) { continue }
        $score = Get-TokenOverlapScore $targetTokens $itTokens
        if ($score -gt $bestScore) { $bestScore = $score; $best = $it }
        if ($targetTokens.Count -ge 2 -and $itTokens.Count -gt $targetTokens.Count) {
            $leading = $true
            for ($ti = 0; $ti -lt $targetTokens.Count; $ti++) {
                if ([string]$itTokens[$ti] -ne [string]$targetTokens[$ti]) { $leading = $false; break }
            }
            $extra = $itTokens.Count - $targetTokens.Count
            if ($leading -and $extra -le 4 -and $extra -lt $bestContainmentExtra) { $bestContainmentExtra = $extra; $bestContainment = $it }
        }
    }
    if ($best -ne $null -and $bestScore -ge 0.75) {
        return [PSCustomObject]@{ Id = [string]$best.id; Name = [string]$best.name }
    }
    if ($bestContainment -ne $null) {
        return [PSCustomObject]@{ Id = [string]$bestContainment.id; Name = [string]$bestContainment.name }
    }

    # ===== 2) Запасной вариант — подсказки поиска витрины (search/suggest) =====
    # storesearch сортирует по общей популярности/продажам, а не по точному
    # совпадению текста — и для названия из одного распространённого слова
    # (например "Keeper": в Steam ещё есть "Graveyard Keeper", "Dungeon
    # Keeper", "Zoo Keeper" и т.п.) может просто не включить нужную игру в
    # свою (ограниченную) первую страницу результатов, даже если сама игра
    # прекрасно есть в Steam. Подсказки поиска (то же самое, что выпадающий
    # список при вводе текста в строке поиска на сайте Steam) сортируют в
    # первую очередь по релевантности самого текста запроса — для короткого/
    # частого названия это обычно куда точнее.
    try {
        $suggestUrl = "https://store.steampowered.com/search/suggest?term=$searchTerm&f=games&cc=us&l=english&realm=1"
        $suggestRequest = {
            param($u)
            try {
                return [string](Invoke-RestMethod -Uri $u -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 10 -ErrorAction Stop)
            } catch {
                try {
                    $rawLines = curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" --connect-timeout 8 --max-time 12 $u
                    return [string]($rawLines -join "`n")
                } catch {}
                return $null
            }
        }
        $suggestHtml = Invoke-BackgroundJsonRequest $suggestRequest @($suggestUrl) 20
        if (-not [string]::IsNullOrWhiteSpace([string]$suggestHtml)) {
            $suggestMatches = [System.Text.RegularExpressions.Regex]::Matches(
                [string]$suggestHtml,
                'data-ds-appid="(\d+)"[\s\S]*?class="match_name">([^<]+)<'
            )
            $suggestItems = New-Object System.Collections.Generic.List[object]
            foreach ($m in $suggestMatches) {
                $sName = [System.Net.WebUtility]::HtmlDecode($m.Groups[2].Value.Trim())
                $suggestItems.Add([PSCustomObject]@{ id = $m.Groups[1].Value; name = $sName })
            }
            if ($suggestItems.Count -gt 0) {
                $sExact = $suggestItems | Where-Object { (Get-NormalizedGameKey $_.name) -eq $normTarget } | Select-Object -First 1
                if ($sExact -ne $null) { return [PSCustomObject]@{ Id = [string]$sExact.id; Name = [string]$sExact.name } }

                $sBest = $null; $sBestScore = 0.0
                foreach ($it in $suggestItems) {
                    $sTokens = @(Get-NameTokens $it.name)
                    if (-not (Test-NameSequelMarkersMatch $targetTokens $sTokens)) { continue }
                    if (Test-SteamNameLooksLikeAddon ([string]$it.name) ([string]$gameName)) { continue }
                    $score = Get-TokenOverlapScore $targetTokens $sTokens
                    if ($score -gt $sBestScore) { $sBestScore = $score; $sBest = $it }
                }
                if ($sBest -ne $null -and $sBestScore -ge 0.75) {
                    return [PSCustomObject]@{ Id = [string]$sBest.id; Name = [string]$sBest.name }
                }
            }
        }
    } catch {}

    $global:lastAppIdSearchError = "ни одно название в результатах поиска не похоже на '$gameName'"
    return $null
}

# ===================== Steam — собственный поиск ВАРИАНТОВ названия =====================
# Раньше выпадающий список вариантов названия при источнике "Steam" (карточка
# добавления игры) заполнялся через Get-EditorSgdbCandidates — автодополнение
# SteamGridDB, для которого нужен личный API-ключ. Из-за этого поиск по Steam
# был самостоятельным только для ОДНОГО найденного App ID (Find-SteamAppInfo),
# а сам список вариантов для выбора — уже нет: без ключа SGDB он оставался
# пустым, даже когда сам Steam прекрасно находил нужную игру.
#
# Эта функция даёт источнику Steam полностью свой список вариантов, без
# какого-либо ключа и без SteamGridDB: берётся онлайн-поиск витрины Steam
# (storesearch), сохраняются ВСЕ подходящие элементы, а порядок, в котором
# их возвращает сама витрина Steam, — это и есть её собственная "логика
# совпадений": он просто переносится в скор для сортировки, а не
# переизобретается заново.
# Каждый вариант несёт СВОЙ настоящий Steam App ID, поэтому при выборе из
# списка повторный поиск App ID по названию уже не требуется.
function Get-SteamStoreNameCandidates ([string]$query, [int]$limit = 12) {
    $q = ([string]$query).Trim()
    if ($q.Length -lt 2) { return @() }
    $qKey = Get-NormalizedGameKey $q

    $results = New-Object System.Collections.Generic.List[object]
    $seenIds = New-Object 'System.Collections.Generic.HashSet[string]'

    # ===== 1) Онлайн-поиск витрины Steam (storesearch), без ключа =====
    # БАГ-ФИКС: раньше онлайн-поиск запускался ТОЛЬКО если локальная база
    # вернула меньше $limit вариантов. Для короткого/частого названия
    # (например "Keeper") локальная база сразу забивала все 12 мест старыми
    # играми с наименьшими App ID — и витрина Steam (которая как раз знает,
    # какая из одноимённых игр популярная/новая) вообще не опрашивалась.
    # Теперь онлайн-выдача запрашивается всегда, а результаты обоих
    # источников смешиваются (см. скоры ниже). Запрос идёт в фоновом
    # runspace (окно не замирает), ответы кэшируются на время сеанса —
    # повторный набор/стирание символов не создаёт лишних запросов.
    if ($null -eq $script:steamStoreSearchCache) { $script:steamStoreSearchCache = @{} }
    $cacheKey = $q.ToLowerInvariant()
    $onlineItems = @()
    if ($script:steamStoreSearchCache.ContainsKey($cacheKey)) {
        $onlineItems = @($script:steamStoreSearchCache[$cacheKey])
    } else {
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
        $searchTerm = [System.Uri]::EscapeDataString($q)
        $url = "https://store.steampowered.com/api/storesearch/?term=$searchTerm&l=english&cc=us"
        $storeSearchRequest = {
            param($u)
            try {
                return (Invoke-RestMethod -Uri $u -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -TimeoutSec 8 -ErrorAction Stop)
            } catch {
                try {
                    $rawLines = curl.exe -s -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" --connect-timeout 6 --max-time 8 $u
                    $rawJson = ($rawLines -join "")
                    if (-not [string]::IsNullOrWhiteSpace($rawJson)) { return ($rawJson | ConvertFrom-Json -ErrorAction Stop) }
                } catch {}
                return $null
            }
        }
        $data = $null
        try { $data = Invoke-BackgroundJsonRequest $storeSearchRequest @($url) 12 } catch { $data = $null }
        $rawItems = $null
        if ($data -ne $null) { $rawItems = $data.items }
        if ($null -ne $rawItems) {
            $onlineItems = @($rawItems)
            if ($onlineItems.Count -gt 0) {
                if ($script:steamStoreSearchCache.Count -ge 60) { $script:steamStoreSearchCache.Clear() }
                $script:steamStoreSearchCache[$cacheKey] = $onlineItems
            }
        }
    }

    # Порядок выдачи витрины = её собственный ранг релевантности/популярности.
    $onlineRank = 0
    foreach ($it in $onlineItems) {
        $id = [string]$it.id
        $nm = [string]$it.name
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($nm)) { continue }
        if (-not $seenIds.Add($id)) { continue }
        $onlineRank++
        if ((Get-NormalizedGameKey $nm) -eq $qKey) {
            $score = 2.0 - ($onlineRank * 0.001) + 0.0005
        } else {
            $score = 1.0 - ($onlineRank * 0.03) + 0.015
        }
        $results.Add([PSCustomObject]@{ Id = $id; Name = $nm; MatchScore = [double]$score })
    }

    # ===== 2) Локальная база приложений Steam (Настройки -> Steam Web API) =====
    # Мгновенный поиск по индексу в памяти. Полный каталог Steam, не
    # ограниченный выдачей витрины — находит и то, что витрина не показала.
    # Порядок уже отранжирован (точные -> начинаются с запроса -> ...,
    # soundtrack/demo/playtest — в самом конце).
    try {
        $localMatches = @(Search-LocalSteamAppsDatabase $q ($limit * 2))
        $localRank = 0
        foreach ($lm in $localMatches) {
            $lmId = [string]$lm.appid
            $lmName = [string]$lm.name
            if ([string]::IsNullOrWhiteSpace($lmId) -or [string]::IsNullOrWhiteSpace($lmName)) { continue }
            if (-not $seenIds.Add($lmId)) { continue }
            $localRank++
            if ((Get-NormalizedGameKey $lmName) -eq $qKey) {
                $lmScore = 2.0 - ($localRank * 0.001)
            } elseif ($lm.Junk) {
                $lmScore = 0.30 - ($localRank * 0.001)
            } else {
                $lmScore = [Math]::Max(0.35, 1.0 - ($localRank * 0.03))
            }
            $results.Add([PSCustomObject]@{ Id = $lmId; Name = $lmName; MatchScore = [double]$lmScore })
        }
    } catch {}

    if ($results.Count -eq 0) { return @() }
    return @($results | Sort-Object MatchScore -Descending | Select-Object -First $limit)
}

# Собирает соответствие "строка в выпадающем списке -> вариант". Раньше строкой
# списка было просто название, а ключом словаря — то же название, поэтому
# ДВЕ разные игры с одинаковым названием (как "Keeper" 2021 года и "Keeper"
# от Double Fine) схлопывались в одну: вторая молча терялась, и выбрать её в
# списке было невозможно. Теперь у одноимённых вариантов в списке дописывается
# App ID; при выборе название в поле берётся из самого варианта (.Name), так
# что суффикс в текст названия не попадает.
function New-EditorTitleCandidateMap ($candidates) {
    $map = @{}
    $names = New-Object System.Collections.Generic.List[string]
    $counts = @{}
    foreach ($c in @($candidates)) {
        if ($null -eq $c) { continue }
        $nm = [string]$c.Name
        if ([string]::IsNullOrWhiteSpace($nm)) { continue }
        $k = $nm.ToLowerInvariant()
        $counts[$k] = 1 + [int]$counts[$k]
    }
    foreach ($c in @($candidates)) {
        if ($null -eq $c) { continue }
        $nm = [string]$c.Name
        if ([string]::IsNullOrWhiteSpace($nm)) { continue }
        $label = $nm
        if ([int]$counts[$nm.ToLowerInvariant()] -gt 1 -and -not [string]::IsNullOrWhiteSpace([string]$c.Id)) {
            $label = "$nm  (#$([string]$c.Id))"
        }
        if (-not $map.ContainsKey($label)) {
            $map[$label] = $c
            [void]$names.Add($label)
        }
    }
    return [PSCustomObject]@{ Map = $map; Names = $names }
}

# ===================== SteamGridDB — РЕЗЕРВНЫЙ ИСТОЧНИК ОБЛОЖЕК =====================
# Официальный CDN Steam (store_item_assets) отдаёт обложки только для игр, у
# которых Valve сама сгенерировала полный набор картинок — для части изданий
# (переиздания, менее популярные игры, издания без "капсулы" 600x900) там
# реально лежит только широкий фон (hero), без вертикальной обложки. Test-CoversValid
# ловит эту ситуацию, но раньше выходом было только "ввести App ID вручную",
# что не помогает, если сам Steam обложку не хранит вообще. SteamGridDB — база
# обложек, собранная сообществом именно для таких случаев (в том числе для
# нестимовских игр); ниже — её поддержка с ручным выбором миниатюры.
#
# Нужен бесплатный личный API-ключ (steamgriddb.com -> Preferences -> API).
function Ensure-SteamGridDbApiKey {
    # Ввод и изменение ключа выполняются только в окне «Настройки».
    # Эта функция оставлена как единая точка чтения ключа для существующего кода.
    return [string]$global:steamGridDbApiKey
}

# Ищет игру в SteamGridDB, показывает миниатюры доступных вертикальных
# обложек и по выбору пользователя скачивает выбранную (плюс, по возможности,
# первые доступные hero/logo) напрямую в $global:tempCovers. Возвращает
# объект с полями Name/Id/SkipDownload=$true (готовые обложки уже лежат в
# temp, повторно скачивать их с CDN Steam не нужно) либо $null при отмене.
# Номер части в названии, приведённый к арабским цифрам: «II», «2», «Part 2» дают один и тот же ключ.
# Скобки «(USA)», «(2023)», «[v1.1]» не учитываются, годы (4 цифры) тоже. Нужен, чтобы
# «Dead to Rights II» не получал обложку/название первой части «Dead to Rights».
function Get-TitleSeqKey ([string]$title) {
    if ([string]::IsNullOrWhiteSpace($title)) { return '' }
    $romans = @{ 'ii'='2'; 'iii'='3'; 'iv'='4'; 'v'='5'; 'vi'='6'; 'vii'='7'; 'viii'='8'; 'ix'='9'; 'x'='10'; 'xi'='11'; 'xii'='12'; 'xiii'='13'; 'xiv'='14'; 'xv'='15' }
    $x = $title.ToLowerInvariant()
    $x = $x -replace '\([^)]*\)|\[[^\]]*\]', ' '
    $x = $x -replace '[^\p{L}\p{Nd}]+', ' '
    $list = New-Object System.Collections.Generic.List[string]
    foreach ($w in @($x.Trim() -split ' ' | Where-Object { $_ })) {
        if ($romans.ContainsKey($w)) { [void]$list.Add([string]$romans[$w]) }
        elseif ($w -match '^\d{1,3}$') { [void]$list.Add([string][int]$w) }
    }
    return (($list | Sort-Object -Unique) -join ',')
}

function Get-SgdbNameScore ($query, $candidate) {
    $q = ([string]$query).ToLowerInvariant().Trim()
    $c = ([string]$candidate.name).ToLowerInvariant().Trim()
    if ([string]::IsNullOrWhiteSpace($q) -or [string]::IsNullOrWhiteSpace($c)) { return 0 }

    function Normalize-SgdbTitle([string]$t) {
        $x = $t.ToLowerInvariant()
        $x = $x -replace '[^\p{L}\p{Nd}]+', ' '
        $x = $x -replace '\s+', ' '
        return $x.Trim()
    }

    $nq = Normalize-SgdbTitle $q
    $nc = Normalize-SgdbTitle $c
    if ($nq -eq $nc) { return 1000 }

    $qTokens = @($nq -split ' ' | Where-Object { $_ })
    $cTokens = @($nc -split ' ' | Where-Object { $_ })
    $common = 0
    foreach ($t in $qTokens) { if ($cTokens -contains $t) { $common++ } }
    $tokenScore = if ($qTokens.Count -gt 0 -and $cTokens.Count -gt 0) {
        (2.0 * $common / ($qTokens.Count + $cTokens.Count)) * 100
    } else { 0 }

    # Нормированная Levenshtein similarity — только для сортировки результатов.
    $a=$nq; $b=$nc; $la=$a.Length; $lb=$b.Length
    if ($la -eq 0 -or $lb -eq 0) { $lev=0 } else {
        $prev=New-Object int[] ($lb+1); $cur=New-Object int[] ($lb+1)
        for($j=0;$j -le $lb;$j++){ $prev[$j]=$j }
        for($i=1;$i -le $la;$i++){
            $cur[0]=$i
            for($j=1;$j -le $lb;$j++){
                $cost=if($a[$i-1] -eq $b[$j-1]){0}else{1}
                $cur[$j]=[Math]::Min([Math]::Min($cur[$j-1]+1,$prev[$j]+1),$prev[$j-1]+$cost)
            }
            $tmp=$prev;$prev=$cur;$cur=$tmp
        }
        $lev=(1.0-($prev[$lb]/[double][Math]::Max($la,$lb)))*100
    }

    $containsBonus = if ($nc.Contains($nq) -or $nq.Contains($nc)) { 18 } else { 0 }
    $typeBonus = if (@($candidate.types) -contains 'steam') { 8 } else { 0 }
    $verifiedBonus = if ($candidate.verified -eq $true) { 6 } else { 0 }
    # Разные номера части (или номер есть только с одной стороны) — это другая игра серии.
    # Без этого «Dead to Rights» (3 общих слова + бонус «содержит») обгонял
    # «Dead to Rights II: Hell to Pay» из-за длинного подзаголовка.
    $seqQ = Get-TitleSeqKey $q
    $seqC = Get-TitleSeqKey $c
    $seqAdj = 0
    if ($seqQ -ne $seqC) { $seqAdj = -60 } elseif ($seqQ) { $seqAdj = 12 }
    return [Math]::Round(($tokenScore*0.52)+($lev*0.30)+$containsBonus+$typeBonus+$verifiedBonus+$seqAdj,2)
}

function Get-SgdbAssetsForGame ($gameId, $headers) {
    # ВАЖНО: не полагаемся на серверный фильтр dimensions=...
    # У SteamGridDB для разных игр набор размеров может отличаться. Для части
    # игр фильтр возвращал пустой массив, хотя обычный /grids/game/{id}
    # прекрасно отдаёт вертикальные/горизонтальные варианты.
    # Поэтому получаем grids без жёсткого dimensions-фильтра и фильтруем
    # размеры локально. Это также позволяет поддержать альтернативные
    # стандартные размеры SGDB: 342x482 / 660x930 и 460x215.
    $result = [ordered]@{ GridsVertical=@(); GridsHorizontal=@(); Heroes=@(); Logos=@(); Icons=@() }

    $gridsReq = Invoke-SgdbApiRequest "https://www.steamgriddb.com/api/v2/grids/game/$gameId" $headers 20
    if ($gridsReq.Success) {
            $all=@($gridsReq.Data)
            $vertical=@($all | Where-Object {
                $w=0;$h=0
                try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                (($w -eq 600 -and $h -eq 900) -or
                 ($w -eq 342 -and $h -eq 482) -or
                 ($w -eq 660 -and $h -eq 930))
            })
            $horizontal=@($all | Where-Object {
                $w=0;$h=0
                try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                (($w -eq 920 -and $h -eq 430) -or
                 ($w -eq 460 -and $h -eq 215))
            })

            # Крайний fallback: если SGDB прислал нестандартный, но явно
            # подходящий по соотношению сторон static grid — тоже покажем его.
            if($vertical.Count -eq 0){
                $vertical=@($all | Where-Object {
                    $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                    $h -gt 0 -and ($w/$h) -ge 0.55 -and ($w/$h) -le 0.78
                })
            }
            if($horizontal.Count -eq 0){
                $horizontal=@($all | Where-Object {
                    $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                    $h -gt 0 -and ($w/$h) -ge 1.85 -and ($w/$h) -le 2.35
                })
            }

            $sortByScore = {
                $v=0.0
                try{$v=[double]$_.score}catch{}
                $v
            }
            $result.GridsVertical=@($vertical | Sort-Object $sortByScore -Descending)
            $result.GridsHorizontal=@($horizontal | Sort-Object $sortByScore -Descending)
    }

    foreach($req in @(
        @{ Name='Heroes'; Url="https://www.steamgriddb.com/api/v2/heroes/game/$gameId" },
        @{ Name='Logos'; Url="https://www.steamgriddb.com/api/v2/logos/game/$gameId" },
        @{ Name='Icons'; Url="https://www.steamgriddb.com/api/v2/icons/game/$gameId" }
    )) {
        $r = Invoke-SgdbApiRequest $req.Url $headers 20
        if ($r.Success) {
            $result[$req.Name]=@($r.Data | Sort-Object @{Expression={
                $v=0.0;try{$v=[double]$_.score}catch{};$v
            };Descending=$true})
        }
    }
    return [PSCustomObject]$result
}

# ===================== АНИМАЦИЯ ЗАГРУЗКИ МИНИАТЮР =====================
# Раньше "анимацией" был Label, которому таймер по кругу подставлял символы
# (⟳/⟲ в окнах SteamGridDB и ◌◔◑◕ в карточке игры). Это не вращалось, а
# мигало, зависело от наличия глифов в шрифте и в карточке игры вообще не
# работало (см. фикс в Start-EditorLoading).
#
# Теперь спиннер — отдельная панель, которая рисует себя сама через GDI+:
# по кругу бежит дуга поверх тусклого кольца, а если загрузка не удалась —
# рисуется крестик (или прочерк, если ссылки на миниатюру вообще не было).
# Панель кладётся ПОВЕРХ PictureBox миниатюры, поэтому анимация видна на
# каждой миниатюре отдельно, ровно пока грузится именно она.
#
# Всё состояние хранится в $spinner.Tag (обычный hashtable), а не в
# NoteProperty: Tag — настоящее свойство .NET, поэтому оно доступно и внутри
# обработчика Paint, куда PowerShell передаёт "голый" объект контрола.
function New-CoverSpinner {
    param($target, $accentColor = $null, [int]$maxDiameter = 44)

    if ($null -eq $accentColor) { $accentColor = [System.Drawing.Color]::FromArgb(102,192,244) }

    $sp = New-Object System.Windows.Forms.Panel
    $sp.Dock = 'Fill'
    try { if ($null -ne $target) { $sp.BackColor = $target.BackColor } } catch {}
    $sp.Tag = @{ State = 'loading'; Angle = 0; Accent = $accentColor; Max = $maxDiameter }

    # Двойная буферизация: без неё дуга заметно мерцает при перерисовке.
    try {
        $flags = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
        [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $flags).SetValue($sp, $true, $null)
    } catch {}

    $sp.Add_Paint({
        param($ctl, $e)
        try {
            $st = $ctl.Tag
            if ($null -eq $st) { return }
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias

            $w = $ctl.ClientSize.Width
            $h = $ctl.ClientSize.Height
            $side = [Math]::Min($w, $h)
            if ($side -lt 12) { return }
            $d = [Math]::Min([int]$st.Max, [int]($side * 0.55))
            if ($d -lt 10) { $d = [Math]::Max(10, [int]($side * 0.6)) }
            $x = [int](($w - $d) / 2)
            $y = [int](($h - $d) / 2)
            $rect = New-Object System.Drawing.Rectangle -ArgumentList $x, $y, $d, $d
            $thickness = [double][Math]::Max(2.0, $d / 9.0)
            $accent = [System.Drawing.Color]$st.Accent

            if ([string]$st.State -eq 'loading') {
                $trackColor = [System.Drawing.Color]::FromArgb(60, $accent.R, $accent.G, $accent.B)
                $trackPen = New-Object System.Drawing.Pen -ArgumentList $trackColor, $thickness
                $g.DrawEllipse($trackPen, $rect)
                $trackPen.Dispose()

                $arcPen = New-Object System.Drawing.Pen -ArgumentList $accent, $thickness
                $arcPen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
                $arcPen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
                $g.DrawArc($arcPen, $rect, [float]$st.Angle, [float]95)
                $arcPen.Dispose()
            }
            else {
                $failPen = New-Object System.Drawing.Pen -ArgumentList ([System.Drawing.Color]::FromArgb(145,154,164)), $thickness
                $g.DrawEllipse($failPen, $rect)
                $pad = [int]($d * 0.3)
                if ([string]$st.State -eq 'empty') {
                    $g.DrawLine($failPen, ($x + $pad), ($y + [int]($d / 2)), ($x + $d - $pad), ($y + [int]($d / 2)))
                } else {
                    $g.DrawLine($failPen, ($x + $pad), ($y + $pad), ($x + $d - $pad), ($y + $d - $pad))
                    $g.DrawLine($failPen, ($x + $d - $pad), ($y + $pad), ($x + $pad), ($y + $d - $pad))
                }
                $failPen.Dispose()
            }
        } catch {}
    })

    return $sp
}

# Один шаг анимации. Вызывается из уже существующих UI-таймеров — отдельных
# потоков по-прежнему нет, поэтому старое правило "никаких обращений к
# WinForms из фона" не нарушается.
function Step-CoverSpinner($spinner) {
    if ($null -eq $spinner) { return }
    try {
        $st = $spinner.Tag
        if ($null -eq $st -or [string]$st.State -ne 'loading') { return }
        if (-not $spinner.Visible) { return }
        $st.Angle = ([int]$st.Angle + 22) % 360
        $spinner.Invalidate()
    } catch {}
}

# Состояния: loading (крутится), done (прячем — миниатюра загрузилась),
# failed (крестик), empty (прочерк, ссылки не было вовсе).
function Set-CoverSpinnerState($spinner, [string]$state) {
    if ($null -eq $spinner) { return }
    try {
        $st = $spinner.Tag
        if ($null -eq $st) { $st = @{ State = $state; Angle = 0; Accent = [System.Drawing.Color]::FromArgb(102,192,244); Max = 44 }; $spinner.Tag = $st }
        $st.State = $state
        if ($state -eq 'done') {
            $spinner.Visible = $false
        } else {
            $spinner.Visible = $true
            $spinner.Invalidate()
        }
    } catch {}
}

# ===================== СВОИ ОБЛОЖКИ (хранилище) =====================
# Свои картинки, добавленные через плитку «Выбрать свою» в окне выбора обложек,
# копируются (уже в нужном формате слота) в %APPDATA%\Steam Commander\custom_covers\<ключ игры>\
# и показываются в этом окне при каждом следующем открытии для той же игры.
$script:customImageLastDir = ''

function Get-LocalSourceIconBitmap {
    try {
        $bmp = New-Object System.Drawing.Bitmap 20, 20
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $back = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(255, 214, 152, 48))
        $front = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(255, 245, 196, 92))
        try {
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $tab = [System.Drawing.Point[]]@(
                (New-Object System.Drawing.Point(1, 4)), (New-Object System.Drawing.Point(7, 4)),
                (New-Object System.Drawing.Point(9, 6)), (New-Object System.Drawing.Point(19, 6)),
                (New-Object System.Drawing.Point(19, 17)), (New-Object System.Drawing.Point(1, 17)))
            $g.FillPolygon($back, $tab)
            $g.FillRectangle($front, 1, 8, 18, 9)
        } finally { $g.Dispose(); $back.Dispose(); $front.Dispose() }
        return $bmp
    } catch { return $null }
}

function Get-GameCoverKey([string]$gamePath) {
    try {
        $norm = ([string]$gamePath).Trim().TrimEnd('\').ToUpperInvariant()
        $sha = [System.Security.Cryptography.SHA1]::Create()
        try {
            $hash = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($norm))
            return (-join ($hash[0..7] | ForEach-Object { $_.ToString('x2') }))
        } finally { $sha.Dispose() }
    } catch { return 'default' }
}

function Get-CustomCoverStoreDir([string]$gameKey) {
    return (Join-Path (Join-Path $global:appDataDir 'custom_covers') $gameKey)
}

function Get-CustomCoverFiles([string]$storeDir, [string]$slotId) {
    try {
        if ([string]::IsNullOrWhiteSpace($storeDir) -or -not (Test-Path -LiteralPath $storeDir -PathType Container)) { return @() }
        return @(Get-ChildItem -LiteralPath $storeDir -File -Filter ($slotId + '_*') -ErrorAction SilentlyContinue |
            Sort-Object LastWriteTime, Name | ForEach-Object { $_.FullName })
    } catch { return @() }
}

# Извлечение иконки из EXE/DLL (самый крупный доступный размер, до 256x256, с альфа-каналом).
if (-not ('ScExeIconExtractor' -as [type])) {
    try {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class ScExeIconExtractor {
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern uint PrivateExtractIcons(string lpszFile, int nIconIndex, int cxIcon, int cyIcon, IntPtr[] phicon, uint[] piconid, uint nIcons, uint flags);
    [DllImport("user32.dll")]
    public static extern bool DestroyIcon(IntPtr hIcon);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    static extern IntPtr LoadLibraryEx(string lpFileName, IntPtr hFile, uint dwFlags);
    [DllImport("kernel32.dll")]
    static extern bool FreeLibrary(IntPtr hModule);
    delegate bool EnumResNameProc(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, IntPtr lParam);
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool EnumResourceNames(IntPtr hModule, IntPtr lpszType, EnumResNameProc lpEnumFunc, IntPtr lParam);
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    static extern IntPtr FindResource(IntPtr hModule, IntPtr lpName, IntPtr lpType);
    [DllImport("kernel32.dll")]
    static extern IntPtr LoadResource(IntPtr hModule, IntPtr hResInfo);
    [DllImport("kernel32.dll")]
    static extern IntPtr LockResource(IntPtr hResData);
    [DllImport("kernel32.dll")]
    static extern uint SizeofResource(IntPtr hModule, IntPtr hResInfo);

    // Наибольший реальный размер (в пикселях) среди изображений первой группы иконок файла;
    // 0 — если определить не удалось. Нужен, чтобы не растягивать маленькую иконку до 256 px.
    public static int MaxNativeIconSize(string file) {
        IntPtr h = IntPtr.Zero;
        try {
            h = LoadLibraryEx(file, IntPtr.Zero, 0x2);
            if (h == IntPtr.Zero) return 0;
            IntPtr firstName = IntPtr.Zero;
            bool found = false;
            EnumResNameProc cb = delegate(IntPtr m, IntPtr t, IntPtr n, IntPtr l) { firstName = n; found = true; return false; };
            EnumResourceNames(h, (IntPtr)14, cb, IntPtr.Zero);
            GC.KeepAlive(cb);
            if (!found) return 0;
            IntPtr res = FindResource(h, firstName, (IntPtr)14);
            if (res == IntPtr.Zero) return 0;
            IntPtr data = LoadResource(h, res);
            if (data == IntPtr.Zero) return 0;
            IntPtr ptr = LockResource(data);
            uint size = SizeofResource(h, res);
            if (ptr == IntPtr.Zero || size < 6) return 0;
            int count = Marshal.ReadInt16(ptr, 4);
            int max = 0;
            for (int i = 0; i < count; i++) {
                int off = 6 + i * 14;
                if (off + 14 > size) break;
                int w = Marshal.ReadByte(ptr, off);
                int hh = Marshal.ReadByte(ptr, off + 1);
                if (w == 0) w = 256;
                if (hh == 0) hh = 256;
                int m2 = Math.Max(w, hh);
                if (m2 > max) max = m2;
            }
            return max;
        } catch { return 0; }
        finally { if (h != IntPtr.Zero) FreeLibrary(h); }
    }
}
'@
    } catch {}
}

function Write-ExeIconLog([string]$msg) {
    try {
        $f = Join-Path $global:appDataDir 'exe_icon_debug.log'
        Add-Content -LiteralPath $f -Value ('{0}  {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg) -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch {}
}

function Get-BitmapFromExeFile([string]$path) {
    try {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { return $null }
        $full = (Resolve-Path -LiteralPath $path).ProviderPath
        if ('ScExeIconExtractor' -as [type]) {
            $native = 0
            try { $native = [int][ScExeIconExtractor]::MaxNativeIconSize($full) } catch { $native = 0 }
            $sizes = @(256, 128, 64, 48, 32)
            if ($native -ge 16 -and $native -le 256) { $sizes = @($native) + @($sizes | Where-Object { $_ -lt $native }) }
            foreach ($sz in $sizes) {
                try {
                    $handles = New-Object 'System.IntPtr[]' 1
                    $ids = New-Object 'System.UInt32[]' 1
                    $n = [uint32][ScExeIconExtractor]::PrivateExtractIcons($full, 0, [int]$sz, [int]$sz, $handles, $ids, [uint32]1, [uint32]0)
                    if ($n -ge 1 -and $n -ne [uint32]::MaxValue -and $handles[0] -ne [IntPtr]::Zero) {
                        $bmp = $null
                        try {
                            $ico = [System.Drawing.Icon]::FromHandle($handles[0])
                            $bmp = $ico.ToBitmap()
                        } catch { $bmp = $null; Write-ExeIconLog ('ToBitmap failed: ' + $_.Exception.Message) }
                        finally { try { [void][ScExeIconExtractor]::DestroyIcon($handles[0]) } catch {} }
                        if ($null -ne $bmp -and $bmp.Width -ge 1) { return $bmp }
                    }
                } catch { Write-ExeIconLog ('PrivateExtractIcons {0}px failed: {1}' -f $sz, $_.Exception.Message) }
            }
        } else {
            Write-ExeIconLog 'ScExeIconExtractor type is not available (Add-Type failed)'
        }
        # Запасной путь: стандартная иконка файла (обычно 32x32).
        $ico2 = [System.Drawing.Icon]::ExtractAssociatedIcon($full)
        if ($null -ne $ico2) {
            try { return $ico2.ToBitmap() } finally { $ico2.Dispose() }
        }
    } catch { Write-ExeIconLog ('Get-BitmapFromExeFile: ' + $_.Exception.Message) }
    return $null
}

# Иконка EXE в лучшем доступном качестве, сохранённая в PNG-кэш (повторно не извлекается,
# пока файл не изменился). Возвращает путь к PNG или $null.
function Get-ExeIconCachePng([string]$exePath) {
    $bmp = $null
    try {
        if ([string]::IsNullOrWhiteSpace($exePath) -or -not (Test-Path -LiteralPath $exePath -PathType Leaf)) { return $null }
        if ([System.IO.Path]::GetExtension($exePath) -notmatch '(?i)^\.(exe|dll)$') { return $null }
        $fi = Get-Item -LiteralPath $exePath -ErrorAction Stop
        $dir = Join-Path $global:appDataDir 'exe_icons'
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $key = Get-GameCoverKey ('{0}|{1}|{2}|v2' -f $fi.FullName, $fi.LastWriteTimeUtc.Ticks, $fi.Length)
        $png = Join-Path $dir ($key + '.png')
        if ((Test-Path -LiteralPath $png -PathType Leaf) -and (Get-Item -LiteralPath $png).Length -gt 0) { return $png }
        $bmp = Get-BitmapFromExeFile $fi.FullName
        if ($null -eq $bmp -or $bmp.Width -lt 1 -or $bmp.Height -lt 1) { return $null }
        $bmp.Save($png, [System.Drawing.Imaging.ImageFormat]::Png)
        if (Test-Path -LiteralPath $png -PathType Leaf) { return $png }
        return $null
    } catch { Write-ExeIconLog ('Get-ExeIconCachePng: ' + $_.Exception.Message); return $null }
    finally { if ($null -ne $bmp) { try { $bmp.Dispose() } catch {} } }
}

# Совпадает ли текущая иконка в temp (temp_icon.*) по содержимому с указанным файлом.
function Test-TempIconMatchesFile([string]$filePath) {
    try {
        $cur = Get-TempIconPath
        if ($null -eq $cur -or [string]::IsNullOrWhiteSpace($filePath) -or -not (Test-Path -LiteralPath $filePath -PathType Leaf)) { return $false }
        if ((Get-Item -LiteralPath $cur).Length -ne (Get-Item -LiteralPath $filePath).Length) { return $false }
        $ha = (Get-FileHash -LiteralPath $cur -Algorithm SHA256).Hash
        $hb = (Get-FileHash -LiteralPath $filePath -Algorithm SHA256).Hash
        return ($ha -eq $hb)
    } catch { return $false }
}

# Сейчас в слоте иконки стоит именно иконка этого EXE?
function Test-EditorIconIsExe([string]$exePath) {
    try {
        if ([string]::IsNullOrWhiteSpace($exePath) -or -not (Test-Path -LiteralPath $exePath -PathType Leaf)) { return $false }
        $png = Get-ExeIconCachePng $exePath
        if ([string]::IsNullOrWhiteSpace($png)) { return $false }
        return (Test-TempIconMatchesFile $png)
    } catch { return $false }
}

# Запоминает иконку, стоявшую в слоте до замены иконкой из EXE (обычно — иконку Steam),
# чтобы кнопка EXE могла вернуть её обратно.
function Save-EditorIconBackup($slot) {
    try {
        $slot | Add-Member -NotePropertyName PrevIconPath -NotePropertyValue '' -Force
        $slot | Add-Member -NotePropertyName PrevIconSource -NotePropertyValue 'Steam' -Force
        $slot | Add-Member -NotePropertyName PrevIconSgdbUrl -NotePropertyValue $null -Force
        $cur = Get-TempIconPath
        if ($null -eq $cur) { return }
        $ext = [System.IO.Path]::GetExtension($cur)
        if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.png' }
        foreach ($e in @('.png','.jpg','.ico')) {
            try { Remove-Item -LiteralPath (Join-Path $global:tempCovers ('icon_toggle_backup' + $e)) -Force -ErrorAction SilentlyContinue } catch {}
        }
        $dst = Join-Path $global:tempCovers ('icon_toggle_backup' + $ext)
        Copy-Item -LiteralPath $cur -Destination $dst -Force -ErrorAction Stop
        $src = ''
        try { $src = [string]$slot.Source } catch {}
        if ([string]::IsNullOrWhiteSpace($src)) { $src = 'Steam' }
        $url = $null
        try { $url = $slot.SgdbSelectedUrl } catch {}
        $slot.PrevIconPath = $dst
        $slot.PrevIconSource = $src
        $slot.PrevIconSgdbUrl = $url
    } catch {}
}

# Возвращает в слот иконку, стоявшую до EXE. Если копии нет (например, temp-папку
# очистила перезагрузка обложек) — заново берёт иконку Steam по App ID.
function Restore-EditorIconFromBackup($slot, [string]$appId, [bool]$preferLocalCache = $false) {
    try {
        if (-not (Test-Path -LiteralPath $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null }
        $prevPath = ''; $prevSource = 'Steam'; $prevUrl = $null
        try { if ($null -ne $slot.PSObject.Properties['PrevIconPath']) { $prevPath = [string]$slot.PrevIconPath } } catch {}
        try { if ($null -ne $slot.PSObject.Properties['PrevIconSource']) { $prevSource = [string]$slot.PrevIconSource } } catch {}
        try { if ($null -ne $slot.PSObject.Properties['PrevIconSgdbUrl']) { $prevUrl = $slot.PrevIconSgdbUrl } } catch {}
        $ok = $false
        if (-not [string]::IsNullOrWhiteSpace($prevPath) -and (Test-Path -LiteralPath $prevPath -PathType Leaf)) {
            $ext = [System.IO.Path]::GetExtension($prevPath)
            if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.png' }
            foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
                try { Remove-Item -LiteralPath (Join-Path $global:tempCovers $n) -Force -ErrorAction SilentlyContinue } catch {}
            }
            $target = Join-Path $global:tempCovers ('temp_icon' + $ext)
            Copy-Item -LiteralPath $prevPath -Destination $target -Force
            $ok = [bool](Set-EditorPreviewFile $slot $target)
        }
        if (-not $ok -and $appId -match '^\d+$') {
            # Сеть на UI-потоке: включаем прокачку очереди сообщений (curl.exe в фоне), чтобы окно не "висело".
            $prevPump = $global:uiPumpDuringDownload
            $global:uiPumpDuringDownload = $true
            $prevCursor = [System.Windows.Forms.Cursor]::Current
            try {
                [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::WaitCursor
                [void](Download-SteamIconToTemp $appId $true $preferLocalCache)
            } finally {
                $global:uiPumpDuringDownload = $prevPump
                try { [System.Windows.Forms.Cursor]::Current = $prevCursor } catch {}
            }
            $ip = Get-TempIconPath
            if ($null -ne $ip -and (Set-EditorPreviewFile $slot $ip)) { $ok = $true; $prevSource = 'Steam'; $prevUrl = $null }
        }
        if ($ok) {
            Set-EditorSourceBadge $slot $prevSource
            try { $slot.SgdbSelectedUrl = $prevUrl } catch {}
        }
        return $ok
    } catch { Write-ExeIconLog ('Restore-EditorIconFromBackup: ' + $_.Exception.Message); return $false }
}

# Тихая замена иконки в temp (без карточки) — для автодобавления игры, когда в «Настройках»
# включено «Использовать иконки из EXE».
function Use-ExeIconInTemp([string]$exePath) {
    try {
        $png = Get-ExeIconCachePng $exePath
        if ([string]::IsNullOrWhiteSpace($png)) { return $false }
        if (-not (Test-Path -LiteralPath $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null }
        foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
            try { Remove-Item -LiteralPath (Join-Path $global:tempCovers $n) -Force -ErrorAction SilentlyContinue } catch {}
        }
        Copy-Item -LiteralPath $png -Destination (Join-Path $global:tempCovers 'temp_icon.png') -Force
        return $true
    } catch { Write-ExeIconLog ('Use-ExeIconInTemp: ' + $_.Exception.Message); return $false }
}

# Карточка: если включено «Использовать иконки из EXE» и EXE игры известен — ставим в слот
# иконку из EXE (иконка Steam при этом сохраняется для возврата кнопкой EXE).
function Invoke-EditorAutoExeIcon($slots) {
    try {
        if (-not [bool]$global:useExeIcons) { return }
        if ($null -eq $slots -or $null -eq $slots.Icon) { return }
        # ROM-ы: галочка «Использовать иконки из EXE» игнорируется — иконка всегда из SteamGridDB.
        $romFlag = $slots.Icon.PSObject.Properties['IsRomCard']
        if ($null -ne $romFlag -and [bool]$romFlag.Value) { return }
        $gp = $slots.Icon.PSObject.Properties['ExePathGetter']
        if ($null -eq $gp -or $null -eq $gp.Value) { return }
        $exe = [string](& $gp.Value)
        if ([string]::IsNullOrWhiteSpace($exe) -or -not (Test-Path -LiteralPath $exe -PathType Leaf)) { return }
        if (Test-EditorIconIsExe $exe) { return }
        if (Set-EditorIconFromExe $slots.Icon $exe) { try { $slots.Icon.PendingMissing = $false } catch {} }
    } catch {}
}

# Мгновенно ставит в слот иконки картинку из EXE (лучшее качество) — как обычный выбор иконки.
function Set-EditorIconFromExe($slot, [string]$exePath) {
    try {
        $png = Get-ExeIconCachePng $exePath
        if ([string]::IsNullOrWhiteSpace($png)) { return $false }
        if (-not (Test-Path -LiteralPath $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers -Force | Out-Null }
        # Прежнюю иконку (Steam и т.п.) сохраняем, чтобы кнопка EXE вернула её обратно.
        try { if (-not (Test-TempIconMatchesFile $png)) { Save-EditorIconBackup $slot } } catch {}
        foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
            try { Remove-Item -LiteralPath (Join-Path $global:tempCovers $n) -Force -ErrorAction SilentlyContinue } catch {}
        }
        $target = Join-Path $global:tempCovers 'temp_icon.png'
        Copy-Item -LiteralPath $png -Destination $target -Force
        if (Set-EditorPreviewFile $slot $target) {
            Set-EditorSourceBadge $slot 'Local'
            try { $slot.SgdbSelectedUrl = $null } catch {}
            try { $slot | Add-Member -NotePropertyName ExeIconPng -NotePropertyValue ([string]$png) -Force } catch {}
            return $true
        }
        return $false
    } catch { Write-ExeIconLog ('Set-EditorIconFromExe: ' + $_.Exception.Message); return $false }
}

function Convert-CustomImageForSlot([string]$srcPath, [string]$title, [string]$targetPath) {
    $bmp = $null
    try {
        $isIco = $false
        try {
            $head = New-Object byte[] 4
            $fs = [System.IO.File]::OpenRead($srcPath)
            try { [void]$fs.Read($head, 0, 4) } finally { $fs.Dispose() }
            $isIco = ($head[0] -eq 0 -and $head[1] -eq 0 -and $head[2] -eq 1 -and $head[3] -eq 0)
        } catch {}
        if ([System.IO.Path]::GetExtension($srcPath) -match '(?i)^\.(exe|dll)$') {
            # Иконку из программы можно взять только для слота «5. Иконка».
            if ($title -notmatch '^\s*5\.') { return $false }
            $bmp = Get-BitmapFromExeFile $srcPath
        } elseif ($isIco -or [System.IO.Path]::GetExtension($srcPath).ToLowerInvariant() -eq '.ico') {
            $bmp = Get-BitmapFromIcoFile $srcPath
        } else {
            $bytes = [System.IO.File]::ReadAllBytes($srcPath)
            $ms = New-Object System.IO.MemoryStream(,$bytes)
            try {
                $img = [System.Drawing.Image]::FromStream($ms)
                try { $bmp = New-Object System.Drawing.Bitmap($img) } finally { $img.Dispose() }
            } finally { $ms.Dispose() }
        }
        if ($null -eq $bmp -or $bmp.Width -lt 1 -or $bmp.Height -lt 1) { return $false }
        if ($title -match '^\s*[123]\.') {
            # JPEG без альфа-канала: прозрачные области заливаем чёрным.
            $flat = New-Object System.Drawing.Bitmap($bmp.Width, $bmp.Height, [System.Drawing.Imaging.PixelFormat]::Format24bppRgb)
            $g = [System.Drawing.Graphics]::FromImage($flat)
            try {
                $g.Clear([System.Drawing.Color]::Black)
                $g.DrawImage($bmp, 0, 0, $bmp.Width, $bmp.Height)
            } finally { $g.Dispose() }
            try {
                $codec = [System.Drawing.Imaging.ImageCodecInfo]::GetImageEncoders() | Where-Object { $_.MimeType -eq 'image/jpeg' } | Select-Object -First 1
                $ep = New-Object System.Drawing.Imaging.EncoderParameters(1)
                $ep.Param[0] = New-Object System.Drawing.Imaging.EncoderParameter([System.Drawing.Imaging.Encoder]::Quality, [long]95)
                $flat.Save($targetPath, $codec, $ep)
            } finally { $flat.Dispose() }
        } else {
            $bmp.Save($targetPath, [System.Drawing.Imaging.ImageFormat]::Png)
        }
        return (Test-Path -LiteralPath $targetPath)
    } catch { return $false }
    finally { if ($null -ne $bmp) { try { $bmp.Dispose() } catch {} } }
}

# Конвертирует выбранный пользователем файл в формат слота и кладёт в хранилище игры.
# Возвращает путь к сохранённому файлу или $null.
function Add-CustomCoverFile([string]$storeDir, [string]$slotId, [string]$srcPath, [string]$title) {
    try {
        if ([string]::IsNullOrWhiteSpace($storeDir) -or -not (Test-Path -LiteralPath $srcPath -PathType Leaf)) { return $null }
        if (-not (Test-Path -LiteralPath $storeDir)) { New-Item -ItemType Directory -Path $storeDir -Force | Out-Null }
        $ext = if ($title -match '^\s*[123]\.') { '.jpg' } else { '.png' }
        $name = '{0}_{1}_{2}{3}' -f $slotId, (Get-Date -Format 'yyyyMMddHHmmssfff'), ([guid]::NewGuid().ToString('N').Substring(0, 4)), $ext
        $target = Join-Path $storeDir $name
        if (-not (Convert-CustomImageForSlot $srcPath $title $target)) { return $null }
        # Не копим бесконечно: на слот храним не больше 24 своих файлов.
        $all = @(Get-CustomCoverFiles $storeDir $slotId)
        if ($all.Count -gt 24) {
            foreach ($old in ($all | Select-Object -First ($all.Count - 24))) { try { Remove-Item -LiteralPath $old -Force -ErrorAction SilentlyContinue } catch {} }
        }
        return $target
    } catch { return $null }
}

function Show-SgdbAssetChooser ($title, [array]$items, [int]$thumbWidth, [int]$thumbHeight, $owner, $customStore = $null) {
    $items=@($items)
    if($items.Count -eq 0 -and $null -eq $customStore){return $null}
    # Уже скачанная миниатюра выбранного варианта передаётся вызывающему коду
    # через эти переменные, чтобы не качать то же самое повторно.
    $script:sgdbChooserPickedBytes=$null
    $script:sgdbChooserPickedIsFull=$false

    $dlg=New-Object System.Windows.Forms.Form
    $dlg.Text="SteamGridDB — $title"
    try { $sgdbIco = Get-SteamGridDbFormIcon; if ($null -ne $sgdbIco) { $dlg.Icon = $sgdbIco } } catch {}
    # ВАЖНО про тёмный отступ снизу: раньше здесь стоял жёстко заданный
    # $dlg.Size=1040x720, который не совпадал с реальной высотой контента
    # (особенно при масштабировании экрана — Windows пересчитывает Size формы
    # и расположение дочерних элементов не всегда синхронно, из-за чего под
    # кнопкой «Отмена» оставалась пустая полоса фона). Теперь точный размер
    # окна выставляется в конце функции — по фактическим границам добавленных
    # элементов (после $btnClose), поэтому низ окна всегда совпадает с низом
    # кнопки «Отмена», а не с произвольным числом.
    $dlg.MinimumSize=New-Object System.Drawing.Size(820,560)
    $dlg.StartPosition="CenterParent"
    $dlg.FormBorderStyle="Sizable"
    $dlg.AutoScaleMode=[System.Windows.Forms.AutoScaleMode]::Font
    $dlg.BackColor=[System.Drawing.Color]::FromArgb(23,29,37)
    $dlg.ForeColor=[System.Drawing.Color]::FromArgb(220,223,228)
    $dlg.Font=New-Object System.Drawing.Font("Segoe UI",9)

    $lbl=New-Object System.Windows.Forms.Label
    $lbl.Text=$(if($items.Count -eq 0){(T 'custom_empty_hint')}else{(T 'sgdb_chooser_hint')})
    $lbl.Location=New-Object System.Drawing.Point(15,12)
    $lbl.Size=New-Object System.Drawing.Size(1050,25)
    $lbl.Font=New-Object System.Drawing.Font("Segoe UI",9,[System.Drawing.FontStyle]::Bold)
    $lbl.ForeColor=[System.Drawing.Color]::FromArgb(220,223,228)
    $dlg.Controls.Add($lbl)

    # Область миниатюр. Обычный Panel + ручной перенос строк: это надёжнее
    # FlowLayoutPanel при AutoScroll и не создаёт горизонтальный диапазон.
    $flow=New-Object System.Windows.Forms.Panel
    $flow.Location=New-Object System.Drawing.Point(12,45)
    $flow.Size=New-Object System.Drawing.Size(1060,580)
    $flow.Anchor='Top,Bottom,Left,Right'
    $flow.AutoScroll=$true
    $flow.BackColor=[System.Drawing.Color]::FromArgb(23,29,37)
    $flow.HorizontalScroll.Enabled=$false
    $flow.HorizontalScroll.Visible=$false
    $dlg.Controls.Add($flow)

    # ВАЖНО: никаких Process.Exited/BeginInvoke и никаких фоновых обращений к WinForms.
    # Process.Exited у PowerShell может выполняться вне UI-потока и приводить к тихому
    # падению WinForms. Вместо этого UI Timer периодически проверяет завершившиеся curl.
    $dialogState=@{Result=$null;Clients=New-Object System.Collections.ArrayList;SpinIndex=0;Closed=$false}
    $maxItems=[Math]::Min(40,$items.Count)
    $allCards=New-Object System.Collections.ArrayList
    $pickCard=$null

    # Рассчитываем число колонок и размеры сетки один раз, по фактической
    # ширине области. Для вертикальных (170 px) получается 5 колонок; для
    # широких Horizontal/Hero/Logo/Icon (270 px) — 3 колонки. Остальные
    # карточки автоматически переходят на следующую строку.
    $cardWidth=$thumbWidth+14
    $cardHeight=$thumbHeight+42
    $availableWidth=[Math]::Max(1,$flow.ClientSize.Width-12)
    $cellWidth=[Math]::Max(1,$cardWidth+10)
    $columns=[Math]::Max(1,[int][Math]::Floor(($availableWidth+10)/$cellWidth))
    # Ширина сетки уже посчитанного числа колонок почти никогда не занимает
    # всю доступную ширину области ровно — раньше сетка всегда прижималась
    # к левому краю (x=10), а весь остаток уходил одним куском вправо.
    # Центрируем сетку по горизонтали, чтобы отступы слева и справа от
    # миниатюр были одинаковыми.
    $gridWidth=($columns*$cellWidth)-10
    $gridOffsetX=10+[Math]::Max(0,[int][Math]::Floor(($availableWidth-$gridWidth)/2))

    for($j=0;$j -lt $maxItems;$j++){
        $item=$items[$j]
        $url='';$thumbUrl=''
        try {
            if($null -ne $item.PSObject.Properties['url']) {$url=[string]$item.PSObject.Properties['url'].Value}
            if($null -ne $item.PSObject.Properties['thumb']) {$thumbUrl=[string]$item.PSObject.Properties['thumb'].Value}
            if([string]::IsNullOrWhiteSpace($url) -and $null -ne $item.PSObject.Properties['grid_url']) {$url=[string]$item.PSObject.Properties['grid_url'].Value}
            if([string]::IsNullOrWhiteSpace($thumbUrl) -and $null -ne $item.PSObject.Properties['grid_url_thumbnail']) {$thumbUrl=[string]$item.PSObject.Properties['grid_url_thumbnail'].Value}
        } catch {}
        if([string]::IsNullOrWhiteSpace($thumbUrl)){$thumbUrl=$url}
        if([string]::IsNullOrWhiteSpace($url)){$url=$thumbUrl}

        $card=New-Object System.Windows.Forms.Panel
        $card.Size=New-Object System.Drawing.Size($cardWidth,$cardHeight)

        $col=$j % $columns
        $row=[int][Math]::Floor($j/$columns)
        $x=$gridOffsetX+($col*$cellWidth)
        $y=10+($row*($cardHeight+13))
        $card.Location=New-Object System.Drawing.Point([int]$x,[int]$y)
        $card.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
        $card.BackColor=[System.Drawing.Color]::FromArgb(13,20,28)
        $flow.Controls.Add($card)
        [void]$allCards.Add($card)

        $pb=New-Object System.Windows.Forms.PictureBox
        $pb.Location=New-Object System.Drawing.Point(5,5)
        $pb.Size=New-Object System.Drawing.Size($thumbWidth,$thumbHeight)
        $pb.SizeMode=[System.Windows.Forms.PictureBoxSizeMode]::Zoom
        $pb.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
        $pb.BackColor=[System.Drawing.Color]::FromArgb(13,20,28)
        $pb.Cursor=[System.Windows.Forms.Cursors]::Hand
        $pb.Tag=$url
        $pb | Add-Member -NotePropertyName ThumbIsFull -NotePropertyValue ([bool]($thumbUrl -eq $url)) -Force
        $card.Controls.Add($pb)

        # Анимация загрузки поверх конкретно этой миниатюры.
        $spinner=New-CoverSpinner $pb ([System.Drawing.Color]::FromArgb(102,192,244)) 46
        $pb.Controls.Add($spinner)

        $num=New-Object System.Windows.Forms.Label
        $num.Text="#" + ($j+1)
        $num.Location=New-Object System.Drawing.Point(5,($thumbHeight+10))
        $num.Size=New-Object System.Drawing.Size($thumbWidth,22)
        $num.TextAlign='MiddleCenter'
        $num.ForeColor=[System.Drawing.Color]::FromArgb(145,154,164)
        $card.Controls.Add($num)

        $pb.Add_Click({
            try {
                $picked=[string]$this.Tag
                if(-not [string]::IsNullOrWhiteSpace($picked)){
                    try {
                        if($null -ne $this.PSObject.Properties['ThumbBytes'] -and $null -ne $this.ThumbBytes){
                            $script:sgdbChooserPickedBytes=$this.ThumbBytes
                            $script:sgdbChooserPickedIsFull=[bool]$this.ThumbIsFull
                        }
                    } catch {}
                    $dialogState.Result=$picked
                    $dlg.DialogResult=[System.Windows.Forms.DialogResult]::OK
                    $dlg.Close()
                }
            } catch {}
        })

        if(-not [string]::IsNullOrWhiteSpace($thumbUrl)){
            try {
                $tmp=[System.IO.Path]::Combine($global:tempCovers,('sgdb_chooser_{0}.tmp' -f [guid]::NewGuid().ToString('N')))
                $psi=New-Object System.Diagnostics.ProcessStartInfo
                $psi.FileName='curl.exe'
                $psi.Arguments='-L --silent --show-error --fail --max-time 20 -A "{2}/{3}" -o "{0}" "{1}"' -f $tmp,$thumbUrl,$global:appTitle,$global:appVersion
                $psi.UseShellExecute=$false
                $psi.CreateNoWindow=$true
                $proc=New-Object System.Diagnostics.Process
                $proc.StartInfo=$psi
                $proc | Add-Member -NotePropertyName TargetPictureBox -NotePropertyValue $pb -Force
                $proc | Add-Member -NotePropertyName TargetSpinner -NotePropertyValue $spinner -Force
                $proc | Add-Member -NotePropertyName TempFile -NotePropertyValue $tmp -Force
                $proc | Add-Member -NotePropertyName TargetUrl -NotePropertyValue $url -Force
                $proc | Add-Member -NotePropertyName DoneHandled -NotePropertyValue $false -Force
                [void]$dialogState.Clients.Add($proc)
                [void]$proc.Start()
            } catch {
                Set-CoverSpinnerState $spinner 'failed'
            }
        } else {
            Set-CoverSpinnerState $spinner 'empty'
        }
    }

    # Задаём минимальную высоту содержимого (по уже посчитанному числу
    # колонок $columns), чтобы при большом количестве вариантов появлялась
    # именно вертикальная полоса прокрутки, а горизонтальная была полностью
    # исключена.
    # Раскладка всех плиток по сетке (удаление/добавление своих плиток вызывает её заново).
    $relayout={
        for($k=0;$k -lt $allCards.Count;$k++){
            $cc=$allCards[$k]
            $col2=$k % $columns
            $row2=[int][Math]::Floor($k/$columns)
            $cc.Location=New-Object System.Drawing.Point([int]($gridOffsetX+($col2*$cellWidth)),[int](10+($row2*($cardHeight+13))))
        }
        $rows2=[int][Math]::Ceiling($allCards.Count/[double]$columns)
        $h2=10+($rows2*$cardHeight)+([Math]::Max(0,$rows2-1)*13)+10
        $flow.AutoScrollMinSize=New-Object System.Drawing.Size(1,[int]$h2)
    }

    if($null -ne $customStore){
        # Плитка уже сохранённой своей картинки: грузится с диска, выбирается как любая другая,
        # правый клик — убрать из списка.
        # Удаление своей плитки: файл, плитка и перераскладка.
        $removeCustomCard={
            param($t)
            try {
                try{Remove-Item -LiteralPath ([string]$t.Path) -Force -ErrorAction SilentlyContinue}catch{}
                $allCards.Remove($t.Card)
                $flow.Controls.Remove($t.Card)
                foreach($ctl in @($t.Card.Controls)){ try{ if($ctl.Image){$ctl.Image.Dispose()} }catch{} }
                $t.Card.Dispose()
                & $relayout
            } catch {}
        }

        # Плитка картинки с диска: выбирается как любая другая. Для добавленных вручную
        # ($removable) в правом верхнем углу красный крестик (и пункт в контекстном меню) — убрать из списка.
        $addCustomCard={
            param([string]$path,[bool]$removable=$true,[string]$labelKey='custom_label')
            $card=New-Object System.Windows.Forms.Panel
            $card.Size=New-Object System.Drawing.Size($cardWidth,$cardHeight)
            $card.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
            $card.BackColor=[System.Drawing.Color]::FromArgb(13,20,28)

            $pb=New-Object System.Windows.Forms.PictureBox
            $pb.Location=New-Object System.Drawing.Point(5,5)
            $pb.Size=New-Object System.Drawing.Size($thumbWidth,$thumbHeight)
            $pb.SizeMode=[System.Windows.Forms.PictureBoxSizeMode]::Zoom
            $pb.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
            $pb.BackColor=[System.Drawing.Color]::FromArgb(13,20,28)
            $pb.Cursor=[System.Windows.Forms.Cursors]::Hand
            $pb.Tag=$path
            try {
                $bytes=[System.IO.File]::ReadAllBytes($path)
                $ms=New-Object System.IO.MemoryStream(,$bytes)
                $pb.Image=[System.Drawing.Image]::FromStream($ms)
                $pb | Add-Member -NotePropertyName ImageStream -NotePropertyValue $ms -Force
            } catch {}
            $card.Controls.Add($pb)

            $num=New-Object System.Windows.Forms.Label
            $num.Text=(T $labelKey)
            $num.Location=New-Object System.Drawing.Point(5,($thumbHeight+10))
            $num.Size=New-Object System.Drawing.Size($thumbWidth,22)
            $num.TextAlign='MiddleCenter'
            $num.ForeColor=[System.Drawing.Color]::FromArgb(102,192,244)
            $card.Controls.Add($num)

            $pb.Add_Click({
                try {
                    $picked=[string]$this.Tag
                    if(-not [string]::IsNullOrWhiteSpace($picked) -and (Test-Path -LiteralPath $picked)){
                        $dialogState.Result=$picked
                        $dlg.DialogResult=[System.Windows.Forms.DialogResult]::OK
                        $dlg.Close()
                    }
                } catch {}
            })

            if($removable){
                $tag=[PSCustomObject]@{Card=$card;Path=$path}

                $menu=New-Object System.Windows.Forms.ContextMenuStrip
                $mi=New-Object System.Windows.Forms.ToolStripMenuItem((T 'custom_remove'))
                $mi.Tag=$tag
                $mi.Add_Click({ try { & $removeCustomCard $this.Tag } catch {} })
                [void]$menu.Items.Add($mi)
                $pb.ContextMenuStrip=$menu

                # Красный крестик в правом верхнем углу миниатюры.
                $xb=New-Object System.Windows.Forms.PictureBox
                $xb.Size=New-Object System.Drawing.Size(22,22)
                $xb.Location=New-Object System.Drawing.Point([int](5+$thumbWidth-22-2),[int](5+2))
                $xb.BackColor=[System.Drawing.Color]::FromArgb(24,24,28)
                $xb.Cursor=[System.Windows.Forms.Cursors]::Hand
                $xb.Tag=$tag
                $xb.Add_MouseEnter({ $this.BackColor=[System.Drawing.Color]::FromArgb(200,40,40); $this.Invalidate() })
                $xb.Add_MouseLeave({ $this.BackColor=[System.Drawing.Color]::FromArgb(24,24,28); $this.Invalidate() })
                $xb.Add_Paint({
                    param($s,$e)
                    try {
                        $g=$e.Graphics
                        $g.SmoothingMode=[System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
                        $hot=($s.BackColor.R -gt 100)
                        $clr=if($hot){[System.Drawing.Color]::White}else{[System.Drawing.Color]::FromArgb(235,64,64)}
                        $pen=New-Object System.Drawing.Pen($clr,2.4)
                        $pen.StartCap=[System.Drawing.Drawing2D.LineCap]::Round
                        $pen.EndCap=[System.Drawing.Drawing2D.LineCap]::Round
                        $g.DrawLine($pen,6,6,[int]($s.Width-7),[int]($s.Height-7))
                        $g.DrawLine($pen,[int]($s.Width-7),6,6,[int]($s.Height-7))
                        $pen.Dispose()
                    } catch {}
                })
                $xb.Add_Click({ try { & $removeCustomCard $this.Tag } catch {} })
                $card.Controls.Add($xb)
                $xb.BringToFront()
            }

            $flow.Controls.Add($card)
            $at=$allCards.Count
            if($null -ne $pickCard){ $at=$allCards.IndexOf($pickCard); if($at -lt 0){$at=$allCards.Count} }
            $allCards.Insert($at,$card)
            return $card
        }

        # Иконки EXE игры в лучшем качестве — автоматически, первыми среди своих плиток
        # (без крестика: это не добавленный вручную файл). Одинаковые иконки не дублируются.
        try {
            $seenHashes=@{}
            foreach($autoExe in @($customStore.AutoExes)){
                try {
                    if([string]::IsNullOrWhiteSpace([string]$autoExe)){continue}
                    $autoPng=Get-ExeIconCachePng ([string]$autoExe)
                    if([string]::IsNullOrWhiteSpace($autoPng)){continue}
                    $hh=(Get-FileHash -LiteralPath $autoPng -Algorithm SHA1).Hash
                    if($seenHashes.ContainsKey($hh)){continue}
                    $seenHashes[$hh]=$true
                    [void](& $addCustomCard ([string]$autoPng) $false 'custom_label_exe')
                } catch {}
            }
        } catch {}

        foreach($cf in @(Get-CustomCoverFiles ([string]$customStore.Dir) ([string]$customStore.Slot))){
            [void](& $addCustomCard ([string]$cf))
        }

        # Последняя плитка «Выбрать свою» — открывает проводник.
        $pickCard=New-Object System.Windows.Forms.Panel
        $pickCard.Size=New-Object System.Drawing.Size($cardWidth,$cardHeight)
        $pickCard.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
        $pickCard.BackColor=[System.Drawing.Color]::FromArgb(13,20,28)
        $pickBox=New-Object System.Windows.Forms.PictureBox
        $pickBox.Location=New-Object System.Drawing.Point(5,5)
        $pickBox.Size=New-Object System.Drawing.Size($thumbWidth,$thumbHeight)
        $pickBox.BackColor=[System.Drawing.Color]::FromArgb(13,20,28)
        $pickBox.Cursor=[System.Windows.Forms.Cursors]::Hand
        $pickBox.Add_MouseEnter({ $this.Tag='hot'; $this.Invalidate() })
        $pickBox.Add_MouseLeave({ $this.Tag=$null; $this.Invalidate() })
        $pickBox.Add_Paint({
            param($s,$e)
            try {
                $g=$e.Graphics
                $g.SmoothingMode=[System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
                $clr=if($s.Tag -eq 'hot'){[System.Drawing.Color]::FromArgb(102,192,244)}else{[System.Drawing.Color]::FromArgb(110,122,136)}
                $pen=New-Object System.Drawing.Pen($clr,2)
                $pen.DashStyle=[System.Drawing.Drawing2D.DashStyle]::Dash
                $g.DrawRectangle($pen,6,6,[int]($s.Width-13),[int]($s.Height-13))
                $cx=[int]($s.Width/2); $cy=[int]($s.Height/2)-14
                $pen2=New-Object System.Drawing.Pen($clr,3)
                $g.DrawLine($pen2,($cx-14),$cy,($cx+14),$cy)
                $g.DrawLine($pen2,$cx,($cy-14),$cx,($cy+14))
                $font=New-Object System.Drawing.Font('Segoe UI Semibold',10)
                $brush=New-Object System.Drawing.SolidBrush($clr)
                $sf=New-Object System.Drawing.StringFormat
                $sf.Alignment=[System.Drawing.StringAlignment]::Center
                $g.DrawString((T 'custom_tile'),$font,$brush,(New-Object System.Drawing.RectangleF(8,[single]($cy+24),[single]($s.Width-16),40)),$sf)
                $pen.Dispose();$pen2.Dispose();$font.Dispose();$brush.Dispose();$sf.Dispose()
            } catch {}
        })
        $pickBox.Add_Click({
            try {
                $ofd=New-Object System.Windows.Forms.OpenFileDialog
                try {
                    $ofd.Title=(T 'custom_dlg_title' @([string]$title))
                    $ofd.Filter=$(if([string]$title -match '^\s*5\.'){(T 'custom_filter_icon')}else{(T 'custom_filter')})
                    $ofd.CheckFileExists=$true
                    $ofd.Multiselect=$true
                    $startDir=[string]$script:customImageLastDir
                    if(-not [string]::IsNullOrWhiteSpace($startDir) -and (Test-Path -LiteralPath $startDir -PathType Container)){ $ofd.InitialDirectory=$startDir }
                    if($ofd.ShowDialog($dlg) -eq [System.Windows.Forms.DialogResult]::OK){
                        try { $script:customImageLastDir=[System.IO.Path]::GetDirectoryName($ofd.FileName) } catch {}
                        $lastCard=$null
                        foreach($fn2 in @($ofd.FileNames)){
                            $stored=Add-CustomCoverFile ([string]$customStore.Dir) ([string]$customStore.Slot) ([string]$fn2) ([string]$title)
                            if($null -ne $stored){
                                $lastCard=& $addCustomCard ([string]$stored)
                            } else {
                                try {
                                    Show-AppMessageBox((T 'custom_bad' @([System.IO.Path]::GetFileName([string]$fn2))),$global:appTitle,[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                                } catch {}
                            }
                        }
                        & $relayout
                        if($null -ne $lastCard){ try{ $flow.ScrollControlIntoView($lastCard) }catch{} }
                    }
                } finally { $ofd.Dispose() }
            } catch {}
        })
        $pickCard.Controls.Add($pickBox)
        $flow.Controls.Add($pickCard)
        [void]$allCards.Add($pickCard)
    }

    & $relayout
    $flow.HorizontalScroll.Enabled=$false
    $flow.HorizontalScroll.Visible=$false

    $timer=New-Object System.Windows.Forms.Timer
    # 70 мс вместо 120: дуга крутится плавно, а не рывками. Тик по-прежнему
    # заодно опрашивает завершившиеся curl-процессы.
    $timer.Interval=70
    $timer.Add_Tick({
        try {
            foreach($client in @($dialogState.Clients)){
                if($null -eq $client){continue}
                try {
                    if(-not $client.DoneHandled -and $client.HasExited){
                        $client.DoneHandled=$true
                        $target=$client.TargetPictureBox
                        $sp=$client.TargetSpinner
                        $file=[string]$client.TempFile
                        $ok=$false
                        try {
                            if($client.ExitCode -eq 0 -and (Test-Path -LiteralPath $file)){
                                $fi=Get-Item -LiteralPath $file -ErrorAction SilentlyContinue
                                if($fi -and $fi.Length -ge 128){
                                    $bytes=[System.IO.File]::ReadAllBytes($file)
                                    $ms=New-Object System.IO.MemoryStream(,$bytes)
                                    $img=[System.Drawing.Image]::FromStream($ms)
                                    if($target.Image){try{$target.Image.Dispose()}catch{}}
                                    $target.Image=$img
                                    $target | Add-Member -NotePropertyName ImageStream -NotePropertyValue $ms -Force
                                    $target | Add-Member -NotePropertyName ThumbBytes -NotePropertyValue $bytes -Force
                                    if($sp){Set-CoverSpinnerState $sp 'done'}
                                    $ok=$true
                                }
                            }
                        } catch { $ok=$false }
                        if(-not $ok -and $sp){Set-CoverSpinnerState $sp 'failed'}
                        try{Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue}catch{}
                        try{$client.Dispose()}catch{}
                    } elseif(-not $client.DoneHandled){
                        # Миниатюра ещё грузится — крутим её спиннер.
                        Step-CoverSpinner $client.TargetSpinner
                    }
                } catch {}
            }
        } catch {}
    })
    $dlg.Add_FormClosed({
        try { $titleSearchTimer.Stop(); $titleSearchTimer.Dispose() } catch {}
    })

    $dlg.Add_Shown({$timer.Start()})
    $dlg.Add_FormClosed({
        $dialogState.Closed=$true
        try{$timer.Stop();$timer.Dispose()}catch{}
        foreach($client in @($dialogState.Clients)){
            try{if($client -is [System.Diagnostics.Process]){if(-not $client.HasExited){$client.Kill()};$client.WaitForExit(500)}}catch{}
            try{Remove-Item -LiteralPath ([string]$client.TempFile) -Force -ErrorAction SilentlyContinue}catch{}
            try{$client.Dispose()}catch{}
        }
    })

    $btnClose=New-Object System.Windows.Forms.Button
    $btnClose.Text=(T 'set_cancel')
    $btnClose.Location=New-Object System.Drawing.Point(935,635)
    $btnClose.Size=New-Object System.Drawing.Size(120,32)
    $btnClose.Anchor='Bottom,Right'
    $btnClose.Add_Click({$dlg.DialogResult=[System.Windows.Forms.DialogResult]::Cancel;$dlg.Close()})
    $dlg.Controls.Add($btnClose)
    $dlg.CancelButton=$btnClose

    # Точный размер окна — по факту нижнего края кнопки «Отмена» (плюс
    # небольшой отступ), а не по произвольно подобранным числам. Это и убирает
    # пустую тёмную полосу снизу, и не зависит от масштабирования экрана,
    # потому что ClientSize и Location/Size дочерних элементов масштабируются
    # WinForms согласованно.
    # Ширина ~1084 подходит для всех категорий: и для узких вертикальных
    # обложек (5 колонок по 170px), и для широких 270px-миниатюр —
    # горизонтальных/hero/логотипа/иконки (3 колонки).
    $dlg.ClientSize=New-Object System.Drawing.Size(1084, ($btnClose.Bottom+15))

    try { Initialize-FormForSmallScreen -Form $dlg -Owner $owner } catch {}
    $dlg.ShowDialog($owner)|Out-Null
    return $dialogState.Result
}

# ===================== ПОЛОЖЕНИЕ ЛОГОТИПА В STEAM (этап 4: запись и чтение) =====================
# Steam хранит положение/размер логотипа в userdata\<account>\config\librarycache\<appid>.json:
#   [["achievements",{...}],["customimage",{"version":1,"data":{"nVersion":1,"logoPosition":{"pinnedPosition":"BottomLeft","nWidthPct":50,"nHeightPct":50}}}]]
# Файл может содержать и другие поля, поэтому запись всегда идёт слиянием: читаем, меняем только
# нужные ключи, пишем обратно. Если положение не трогали - в json ничего не пишем (поведение Steam).

function Get-LogoDefaultPosition {
    # Положение/размер логотипа «по умолчанию» (галочка в слоте «Фон и логотип»).
    # $null - галочка не включена, тогда у каждой игры своё положение, как раньше.
    try {
        if (-not [bool]$global:logoDefaultEnabled) { return $null }
        $pos = [string]$global:logoDefaultPosition
        if ($script:EditorLogoPositions -notcontains $pos) { $pos = 'BottomLeft' }
        $w = [math]::Max(1.0, [math]::Min(100.0, [double]$global:logoDefaultWidthPct))
        $h = [math]::Max(1.0, [math]::Min(100.0, [double]$global:logoDefaultHeightPct))
        return [PSCustomObject]@{ Position = $pos; WidthPct = $w; HeightPct = $h }
    } catch { return $null }
}

function Sync-LogoDefaultFromState($state) {
    # Вызывается при сохранении карточки. Галочка включена - текущие положение и размер логотипа становятся
    # значением по умолчанию (config.ini); галочку сняли - значение по умолчанию отключается
    # (числа в config.ini остаются, но не применяются).
    try {
        if ($null -eq $state) { return }
        if ([bool]$state.LogoUseDefault) {
            $pos = [string]$state.LogoPosition
            if ($script:EditorLogoPositions -notcontains $pos) { $pos = 'BottomLeft' }
            $w = [double]$state.LogoWidthPct
            $h = [double]$state.LogoHeightPct
            if ([bool]$global:logoDefaultEnabled -and [string]$global:logoDefaultPosition -eq $pos -and [double]$global:logoDefaultWidthPct -eq $w -and [double]$global:logoDefaultHeightPct -eq $h) { return }
            $global:logoDefaultEnabled = $true
            $global:logoDefaultPosition = $pos
            $global:logoDefaultWidthPct = $w
            $global:logoDefaultHeightPct = $h
        } else {
            if (-not [bool]$global:logoDefaultEnabled) { return }
            $global:logoDefaultEnabled = $false
        }
        Save-Configuration
    } catch {}
}

function Get-WrappedTipText([string]$text, [int]$width = 52) {
    # ToolTip сам длинную строку не переносит: разбиваем по словам, текст без пробелов (китайский) - кусками.
    $lines = New-Object System.Collections.Generic.List[string]
    $cur = ''
    foreach ($word in ($text -split ' ')) {
        while ($word.Length -gt $width) {
            if ($cur.Length -gt 0) { $lines.Add($cur); $cur = '' }
            $cut = [math]::Max(8, [int]($width / 2))
            $lines.Add($word.Substring(0, $cut)); $word = $word.Substring($cut)
        }
        if ($cur.Length -gt 0 -and ($cur.Length + 1 + $word.Length) -gt $width) { $lines.Add($cur); $cur = $word }
        elseif ($cur.Length -gt 0) { $cur = $cur + ' ' + $word }
        else { $cur = $word }
    }
    if ($cur.Length -gt 0) { $lines.Add($cur) }
    return ($lines.ToArray() -join "`n")
}

function Get-EditorLogoSignature($state) {
    # Строка-отпечаток положения/размера логотипа: по ней понимаем, трогали ли положение.
    try {
        $ci = [System.Globalization.CultureInfo]::InvariantCulture
        $w = [math]::Round([double]$state.LogoWidthPct, 1)
        $h = [math]::Round([double]$state.LogoHeightPct, 1)
        # Галочка «по умолчанию» входит в отпечаток: её переключение тоже считается изменением карточки.
        $dflag = ''
        try { if ([bool]$state.LogoUseDefault) { $dflag = '|D' } } catch {}
        return ([string]$state.LogoPosition + '|' + $w.ToString($ci) + '|' + $h.ToString($ci) + $dflag)
    } catch { return ('?' + [guid]::NewGuid().ToString('N')) }
}

function Get-EditorLogoPositionToSave($state, [bool]$ForceIfFromCache = $false) {
    # Что писать в json: $null, если положение не менялось (тогда ничего не пишем).
    # $ForceIfFromCache - перенос уже сохранённого положения на новый id (ярлык переименовали).
    try {
        $touched = ((Get-EditorLogoSignature $state) -ne [string]$state.LogoSig0)
        $carry = ($ForceIfFromCache -and [bool]$state.LogoFromCache)
        # Галочка «по умолчанию»: сохраняем значения как общие и всегда пишем положение в Steam для этой игры.
        Sync-LogoDefaultFromState $state
        $forceDefault = $false
        try { $forceDefault = [bool]$state.LogoUseDefault } catch {}
        if (-not $touched -and -not $carry -and -not $forceDefault) { return $null }
        $pos = [string]$state.LogoPosition
        if ($script:EditorLogoPositions -notcontains $pos) { $pos = 'BottomLeft' }
        return [PSCustomObject]@{ Position = $pos; WidthPct = [double]$state.LogoWidthPct; HeightPct = [double]$state.LogoHeightPct }
    } catch { return $null }
}

function Merge-SteamLibraryCacheJson([string]$Path, [System.Collections.IDictionary]$Set = $null, [System.Collections.IDictionary]$SetIfMissing = $null) {
    # Слияние в librarycache\<id>.json: остальные поля сохраняются. $Set перезаписывает ключи,
    # $SetIfMissing добавляет только отсутствующие. Нечитаемый файл сначала копируется в .bak.
    try {
        $obj = $null
        $existed = [System.IO.File]::Exists($Path)
        if ($existed) {
            $raw = ''
            try { $raw = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) } catch {}
            # Реальный формат Steam - массив пар [ключ, {version,data}]. Старые поля appid/Count туда не добавляем.
            if ($raw.TrimStart().StartsWith('[')) { return $true }
            if (-not [string]::IsNullOrWhiteSpace($raw)) {
                $parsed = $null
                try { $parsed = $raw | ConvertFrom-Json -ErrorAction Stop } catch { $parsed = $null }
                if ($parsed -is [System.Management.Automation.PSCustomObject]) { $obj = $parsed }
                else { try { [System.IO.File]::Copy($Path, ($Path + '.bak'), $true) } catch {} }
            }
        }
        if ($null -eq $obj) { $obj = [PSCustomObject]@{} }
        if ($null -ne $SetIfMissing) {
            foreach ($k in @($SetIfMissing.Keys)) {
                if ($null -eq $obj.PSObject.Properties[[string]$k]) { $obj | Add-Member -NotePropertyName ([string]$k) -NotePropertyValue $SetIfMissing[$k] }
            }
        }
        if ($null -ne $Set) {
            foreach ($k in @($Set.Keys)) { $obj | Add-Member -NotePropertyName ([string]$k) -NotePropertyValue $Set[$k] -Force }
        }
        $json = ConvertTo-Json -InputObject $obj -Depth 10 -Compress
        $tmp = $Path + '.tmp'
        try {
            [System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding($false)))
            if ($existed) { [System.IO.File]::Copy($tmp, $Path, $true) } else { [System.IO.File]::Move($tmp, $Path) }
        } finally {
            if ([System.IO.File]::Exists($tmp)) { try { [System.IO.File]::Delete($tmp) } catch {} }
        }
        return $true
    } catch { return $false }
}

function Set-SteamCacheEntryJson([string]$Path, [string]$Key, [System.Collections.IDictionary]$DataPatch) {
    # Реальный формат librarycache\<id>.json:
    #   [["achievements",{"version":2,"data":{...}}],["customimage",{"version":1,"data":{"nVersion":1,"logoPosition":{...}}}]]
    # Меняем только data записи $Key (ключи из $DataPatch), остальные записи и поля сохраняются.
    # Старый формат-объект (его раньше писал сам скрипт) заменяется массивом. Нечитаемый файл -> .bak.
    try {
        $pairs = New-Object System.Collections.ArrayList
        $existed = [System.IO.File]::Exists($Path)
        if ($existed) {
            $raw = ''
            try { $raw = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) } catch {}
            if (-not [string]::IsNullOrWhiteSpace($raw)) {
                $parsed = $null; $okParse = $true
                try { $parsed = @($raw | ConvertFrom-Json -ErrorAction Stop) } catch { $okParse = $false }
                if (-not $okParse) { try { [System.IO.File]::Copy($Path, ($Path + '.bak'), $true) } catch {} }
                else {
                    foreach ($el in $parsed) {
                        if ($el -is [System.Array] -and $el.Count -ge 2 -and $el[0] -is [string]) { [void]$pairs.Add([object[]]@([string]$el[0], $el[1])) }
                        # PSCustomObject = старый формат скрипта: пропускаем
                    }
                }
            }
        }
        # Нового файла у Steam без записи achievements не бывает: добавляем такую же, как пишет сам Steam
        # для не-Steam игры, иначе при запуске Steam пересоздаёт файл и теряет нашу запись.
        $hasAch = $false
        for ($k = 0; $k -lt $pairs.Count; $k++) { if ([string]$pairs[$k][0] -eq 'achievements') { $hasAch = $true; break } }
        if (-not $hasAch -and $Key -ne 'achievements') {
            $achData = [PSCustomObject]@{ vecHighlight = [object[]]@(); vecUnachieved = [object[]]@(); vecAchievedHidden = [object[]]@(); nTotal = 0; nAchieved = 0 }
            $achWrap = [PSCustomObject]@{ version = 2; data = $achData }
            $pairs.Insert(0, [object[]]@('achievements', $achWrap))
        }
        $idx = -1
        for ($k = 0; $k -lt $pairs.Count; $k++) { if ([string]$pairs[$k][0] -eq $Key) { $idx = $k; break } }
        $wrapper = $null
        if ($idx -ge 0) { $wrapper = $pairs[$idx][1] }
        if ($wrapper -isnot [System.Management.Automation.PSCustomObject]) {
            $wrapper = [PSCustomObject]@{ version = 1; data = [PSCustomObject]@{ nVersion = 1 } }
        }
        $data = $null
        try { $data = $wrapper.data } catch {}
        if ($data -isnot [System.Management.Automation.PSCustomObject]) { $data = [PSCustomObject]@{ nVersion = 1 } }
        foreach ($pk in @($DataPatch.Keys)) { $data | Add-Member -NotePropertyName ([string]$pk) -NotePropertyValue $DataPatch[$pk] -Force }
        $wrapper | Add-Member -NotePropertyName 'data' -NotePropertyValue $data -Force
        if ($null -eq $wrapper.PSObject.Properties['version']) { $wrapper | Add-Member -NotePropertyName 'version' -NotePropertyValue 1 }
        $entry = [object[]]@($Key, $wrapper)
        if ($idx -ge 0) { $pairs[$idx] = $entry } else { [void]$pairs.Add($entry) }

        $json = ConvertTo-Json -InputObject ([object[]]$pairs.ToArray()) -Depth 12 -Compress
        $tmp = $Path + '.tmp'
        try {
            [System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding($false)))
            if ($existed) { [System.IO.File]::Copy($tmp, $Path, $true) } else { [System.IO.File]::Move($tmp, $Path) }
        } finally {
            if ([System.IO.File]::Exists($tmp)) { try { [System.IO.File]::Delete($tmp) } catch {} }
        }
        return $true
    } catch { return $false }
}

function Set-SteamLogoPositionInDir([string]$cacheDir, [string]$appId, $pos) {
    # Steam хранит положение логотипа не-Steam игры в <профиль>\config\grid\<appId>.json:
    #   {"nVersion":1,"logoPosition":{"pinnedPosition":...,"nWidthPct":...,"nHeightPct":...}}
    # (librarycache\<id>.json - лишь производный кэш Steam, его Steam пересоздаёт). $cacheDir - папка
    # config\librarycache профиля; рядом лежит config\grid.
    if ($null -eq $pos -or [string]::IsNullOrWhiteSpace($appId)) { return $false }
    try {
        $gridDir = Join-Path (Split-Path -Path $cacheDir -Parent) 'grid'
        if (-not (Test-Path -LiteralPath $gridDir)) { New-Item -ItemType Directory -Path $gridDir -Force | Out-Null }
        $lp = [ordered]@{
            pinnedPosition = [string]$pos.Position
            nWidthPct      = [math]::Round([double]$pos.WidthPct, 2)
            nHeightPct     = [math]::Round([double]$pos.HeightPct, 2)
        }
        $f = Join-Path $gridDir ($appId + '.json')
        return [bool](Merge-SteamLibraryCacheJson $f ([ordered]@{ logoPosition = [PSCustomObject]$lp }) ([ordered]@{ nVersion = 1 }))
    } catch { return $false }
}

function Set-SteamLogoPositionForAllProfiles([string]$appId, $pos) {
    # Запись положения логотипа во все профили Steam. Возвращает число успешно записанных профилей.
    if ($null -eq $pos) { return 0 }
    $ok = 0
    foreach ($pr in @(Get-ConfiguredSteamProfileDirectories)) {
        try { if (Set-SteamLogoPositionInDir (Join-Path ([string]$pr.FullName) 'config\librarycache') $appId $pos) { $ok++ } } catch {}
    }
    return $ok
}

function Get-SteamLogoPositionFromCache([string]$appId) {
    # Читает сохранённое положение логотипа: config\grid\<id>.json (основной источник Steam), затем
    # config\librarycache\<id>.json (запасной). Из нескольких профилей берётся самый свежий файл.
    # Нет данных / неизвестное значение - $null (карточка останется по умолчанию).
    if ($appId -notmatch '^\d+$') { return $null }
    $best = $null; $bestTime = [datetime]::MinValue
    foreach ($pr in @(Get-ConfiguredSteamProfileDirectories)) {
        foreach ($rel in @('config\grid\', 'config\librarycache\')) {
            try {
                $f = Join-Path ([string]$pr.FullName) ($rel + $appId + '.json')
                if (-not [System.IO.File]::Exists($f)) { continue }
                $raw = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8)
                if ([string]::IsNullOrWhiteSpace($raw)) { continue }
                $lp = $null
                $items = @($raw | ConvertFrom-Json -ErrorAction Stop)
                foreach ($el in $items) {
                    if ($el -is [System.Array] -and $el.Count -ge 2 -and [string]$el[0] -eq 'customimage') {
                        try { $lp = $el[1].data.logoPosition } catch {}
                    } elseif ($el -is [System.Management.Automation.PSCustomObject]) {
                        try { $lp = $el.logoPosition } catch {}
                    }
                }
                if ($null -eq $lp) { continue }
                $pp = [string]$lp.pinnedPosition
                if ($script:EditorLogoPositions -notcontains $pp) { continue }
                $w = 50.0; $h = 50.0
                try { if ($null -ne $lp.nWidthPct) { $w = [double]$lp.nWidthPct } } catch {}
                try { if ($null -ne $lp.nHeightPct) { $h = [double]$lp.nHeightPct } } catch {}
                $w = [math]::Max(1.0, [math]::Min(100.0, $w)); $h = [math]::Max(1.0, [math]::Min(100.0, $h))
                $wt = [System.IO.File]::GetLastWriteTime($f)
                if ($null -eq $best -or $wt -gt $bestTime) {
                    $best = [PSCustomObject]@{ Position = $pp; WidthPct = $w; HeightPct = $h }
                    $bestTime = $wt
                }
            } catch {}
        }
    }
    return $best
}

function Set-EditorLogoStateFromCache($hs, $pos) {
    # Подставляет сохранённое положение в карточку (состояние, ползунок, превью).
    if ($null -eq $hs -or $null -eq $pos) { return }
    $st = $hs.EditorState
    $st.LogoPosition = [string]$pos.Position
    $st.LogoWidthPct = [double]$pos.WidthPct
    $st.LogoHeightPct = [double]$pos.HeightPct
    $st.LogoFromCache = $true
    try {
        $v = [int][math]::Round([double]$pos.WidthPct)
        $v = [math]::Max($script:EditorLogoScaleMin, [math]::Min($script:EditorLogoScaleMax, $v))
        if ($hs.Slider.Value -ne $v) { $hs.Slider.Value = $v }
    } catch {}
    try { Update-EditorComposeView $hs } catch {}
    try { $hs.Picture.Invalidate() } catch {}
}

# ===================== ПРЯМОЕ ПРИМЕНЕНИЕ СВЕЖЕСКАЧАННЫХ ОБЛОЖЕК =====================
# Используется автоматическим потоком "Добавить выбранные игры в Steam":
# копирует обложки НАПРЯМУЮ из temp-папки в config\grid.
function Copy-TempCoversDirectlyToGrid ($shortcutId, $logoPosition = $null) {
    # Положение логотипа не передано (автоимпорт, ромы и т.п.) - берём «по умолчанию», если галочка включена.
    if ($null -eq $logoPosition) { try { $logoPosition = Get-LogoDefaultPosition } catch {} }
    $steamPathProperty = Get-ConfiguredSteamExePath
    $steamPath = Get-ConfiguredSteamInstallPath
    $userDataPath = Get-ConfiguredSteamUserDataPath
    if (-not (Test-Path $userDataPath)) { return $false }

    Get-ConfiguredSteamProfileDirectories | ForEach-Object {
        $cacheDir = Join-Path $_.FullName "config\librarycache"
        if (-not (Test-Path $cacheDir)) { New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null }
        # Раньше json перезаписывался целиком ({"appid":..,"Count":1}) и затирал всё остальное, в том числе
        # logoPosition. Теперь недостающие appid/Count только добавляются, остальные поля остаются.
        $sidNum = [int64]0
        $sidFields = [ordered]@{}
        if ([int64]::TryParse([string]$shortcutId, [ref]$sidNum)) { $sidFields['appid'] = $sidNum; $sidFields['Count'] = 1 }
        [void](Merge-SteamLibraryCacheJson (Join-Path $cacheDir ($shortcutId + ".json")) $null $sidFields)
        # Положение логотипа: $logoPosition = $null, если его не трогали - тогда ничего не пишем.
        if ($null -ne $logoPosition) { [void](Set-SteamLogoPositionInDir $cacheDir ([string]$shortcutId) $logoPosition) }

        $gridDir = Join-Path $_.FullName "config\grid"
        if (-not (Test-Path $gridDir)) { New-Item -ItemType Directory -Path $gridDir | Out-Null }

        if (Test-Path (Join-Path $global:tempCovers "temp_p.jpg")) { Copy-Item (Join-Path $global:tempCovers "temp_p.jpg") (Join-Path $gridDir ($shortcutId + "p.jpg")) -Force }
        if (Test-Path (Join-Path $global:tempCovers "temp_hero.jpg")) { Copy-Item (Join-Path $global:tempCovers "temp_hero.jpg") (Join-Path $gridDir ($shortcutId + "_hero.jpg")) -Force }
        if (Test-Path (Join-Path $global:tempCovers "temp_logo.png")) { Copy-Item (Join-Path $global:tempCovers "temp_logo.png") (Join-Path $gridDir ($shortcutId + "_logo.png")) -Force }
        if (Test-Path (Join-Path $global:tempCovers "temp_header.jpg")) { Copy-Item (Join-Path $global:tempCovers "temp_header.jpg") (Join-Path $gridDir ($shortcutId + ".jpg")) -Force }
        $iconTemp = Get-TempIconPath
        if ($null -ne $iconTemp) {
            $iconExt = [System.IO.Path]::GetExtension($iconTemp)
            if ([string]::IsNullOrWhiteSpace($iconExt)) { $iconExt = '.png' }
            Copy-Item -LiteralPath $iconTemp -Destination (Join-Path $gridDir ($shortcutId + '_icon' + $iconExt)) -Force
            # Дублируем как _icon.png для превью при повторном открытии, если исходник не png.
            if ($iconExt -ne '.png') {
                try { Copy-Item -LiteralPath $iconTemp -Destination (Join-Path $gridDir ($shortcutId + '_icon.png')) -Force -ErrorAction SilentlyContinue } catch {}
            }
        }
    }

    if (Test-Path $global:tempCovers) { Remove-Item $global:tempCovers -Recurse -Force -ErrorAction SilentlyContinue }
    if (-not (Test-Path $global:tempCovers)) { New-Item -ItemType Directory -Path $global:tempCovers | Out-Null }
    return $true
}


# ===================== НОВАЯ КАРТОЧКА ИГРЫ =====================
function Get-EditorExecutableCandidates ($gamePath) {
    if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path $gamePath)) { return @() }
    try {
        if (Test-Path -LiteralPath $gamePath -PathType Leaf) {
            $fi = Get-Item -LiteralPath $gamePath -ErrorAction Stop
            if ($fi.Extension -match '(?i)\.(exe|bat|cmd|com)$') { return @($fi) }
            return @()
        }
    } catch {}
    $junkPattern = '(?i)clientsdkmdnshost|scenecefbrowser|\\cef\\|unins00|\buninstall(er)?\b|unitycrashhandler|crashpad|crashreportclient|crashreporter|crashsender|crashdump|crashupload|crashmonitor|eosbootstrapper|dxwebsetup|crashhandler|crs-handler|crs-uploader|unrealcefsubprocess|\bcefsubprocess\b|\bcefsharp\b|browsersubprocess|driverversionchecker|layerschecker|battleye|easyanticheat|\beac\b|vc_?redist|_?commonredist|\bdotnetfx\b|\bdxsetup\b|\bdirectx\b.*setup|\bprereqsetup\b|physxsetup|vcredist|vulkanrt|\bautorun\b|\bupdater\b|\bpatcher\b|installer\.exe$|_original|_crack|\\Support\\|\\runtimes\\|\\(config|settings|options|cfg)\.exe$'
    $all = @(Get-ChildItem -LiteralPath $gamePath -Filter '*.exe' -File -Recurse -ErrorAction SilentlyContinue)
    $clean = @($all | Where-Object { $_.FullName -notmatch $junkPattern })
    if (-not [bool]$global:suggestGameLaunchers) {
        $clean = @($clean | Where-Object { -not (Test-IsGameLauncherExe $_) })
    }
    if ($clean.Count -eq 0 -and $all.Count -gt 0 -and [bool]$global:suggestGameLaunchers) { $clean = $all }
    $root = @($clean | Where-Object { $_.DirectoryName.TrimEnd('\') -eq $gamePath.TrimEnd('\') })
    $ordered = if ($root.Count -gt 0) { $root } else { $clean }
    # БАГ-ФИКС: раньше сортировка учитывала только "лежит ли exe в корне папки
    # игры", а среди файлов одного уровня вложенности порядок был чисто
    # алфавитным. Из-за этого, например, для Baldur's Gate 3 (ни bin\bg3.exe,
    # ни Launcher\LariLauncher.exe не лежат в корне) файлы просто сортировались
    # по имени, и совпадение, что "b" < "L", было единственной причиной, почему
    # прямой exe вообще оказывался первым — при другом имени лаунчера или игры
    # первым мог оказаться именно лаунчер. Добавлен явный признак "похоже на
    # лаунчер" (по имени файла/папки), который ставится ниже прямых exe вне
    # зависимости от алфавита — это и есть то самое "прямой запуск
    # предпочтительнее лаунчера", которое должно было работать всегда.
    $launcherLikePattern = '(?i)launcher'
    return @($ordered | Sort-Object `
        @{Expression={ if ($_.DirectoryName.TrimEnd('\') -eq $gamePath.TrimEnd('\')) { 0 } else { 1 } }}, `
        @{Expression={ if ($_.FullName -match $launcherLikePattern) { 1 } else { 0 } }}, `
        Name)
}

# Кандидаты в файл рома для карточки добавления/редактирования в режиме
# ROMs. $gamePath может быть как папкой с файлами игры (обычный случай при
# добавлении из библиотеки), так и уже готовым путём к конкретному файлу
# (например, при редактировании существующего ярлыка) — во втором случае
# сам этот файл всегда остаётся в списке кандидатов, а поиск соседних файлов
# идёт по папке, в которой он лежит.
#
# $preferredExtensions — список расширений активного эмулятора без точек,
# через запятую (формат поля "Расширения" в настройках эмулятора, например
# "sfc,smc,fig"). Если он пуст, используется широкий список общеизвестных
# расширений образов/картриджей.
#
# Патчи, DLC, бонусные материалы, версии v1/v2/... и файлы-описатели
# образов (.cue/.dvd и подобные) отбрасываются полностью — они не попадают
# даже в список "неопределённых" файлов. Остальные файлы остаются в списке.
# Совпадение с расширением, указанным у выбранного эмулятора, повышает
# уверенность и даёт приоритет автоматическому выбору. v0 считается базовой
# версией и получает дополнительный приоритет среди подходящих ROM.
function Get-EditorRomCandidates ($gamePath, [string]$preferredExtensions = '', [bool]$includeArchives = $false) {
    if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath)) { return @() }

    $isFile = Test-Path -LiteralPath $gamePath -PathType Leaf
    $rootDir = if ($isFile) { [System.IO.Path]::GetDirectoryName($gamePath) } else { $gamePath }
    if ([string]::IsNullOrWhiteSpace($rootDir) -or -not (Test-Path -LiteralPath $rootDir)) { return @() }

    # Если из панели выбран конкретный ROM-файл, карточка работает только с
    # этим файлом. Соседние ROM из той же папки в выпадающий список не добавляем.
    # Если из панели выбрана папка, наоборот, сканируем её содержимое как раньше.
    if ($isFile) {
        $direct = Get-Item -LiteralPath $gamePath -ErrorAction SilentlyContinue
        if ($direct -eq $null -or $direct.PSIsContainer) { return @() }
        $all = @($direct)
    } else {
        $all = @(Get-ChildItem -LiteralPath $rootDir -File -Recurse -ErrorAction SilentlyContinue)
    }

    # Расширения, указанные у выбранного эмулятора, являются ЖЁСТКИМ фильтром
    # только для содержимого выпадающего списка: если у эмулятора указано
    # "nsp", в список попадают только *.nsp. При этом сами файлы не отбрасываем
    # по названию: DLC/patch/update/v1 и т.п. остаются видимыми для ручного
    # выбора, но никогда не становятся автоматическим кандидатом, если рядом
    # есть нормальный ROM.
    $preferredExts = @()
    if (-not [string]::IsNullOrWhiteSpace($preferredExtensions)) {
        $preferredExts = @($preferredExtensions -split '[,;\s]+' |
            ForEach-Object { $_.Trim().TrimStart('.').ToLowerInvariant() } |
            Where-Object { $_ -ne '' } |
            Select-Object -Unique)
    }

    # Если фильтр эмулятора не задан, сохраняем прежний широкий набор известных
    # расширений. При заданном фильтре никакие другие расширения в список не
    # попадают.
    $knownExt = if ($preferredExts.Count -gt 0) {
        $preferredExts
    } else {
        @('iso','bin','img','chd','cso','pbp','gdi','rvz','wbfs','wux','nsp','xci','cia','vpk',
          'nes','fds','unf','sfc','smc','fig','gb','gbc','gba','nds','3ds','n64','z64','v64',
          'sms','gg','md','32x','pce','ngp','ngc','ws','wsc','vb','lnx','a26','a52','a78',
          'j64','col','int','vec','d64','t64','adf','ipf','dsk','rom','zip','7z',
          'cue','m3u','ccd','mds','toc','sub','cdi','sgx','exe')
    }
    # Галочка «Распаковывать архивы» у эмулятора: архивы допустимы, даже если их
    # расширения нет в списке эмулятора (и в широком списке по умолчанию).
    if ($includeArchives) { $knownExt = @(@($knownExt) + @(Get-RomArchiveExtensions) | Select-Object -Unique) }
    $knownExtSet = New-Object 'System.Collections.Generic.HashSet[string]' ([string[]]$knownExt, [System.StringComparer]::OrdinalIgnoreCase)
    $archiveExtSet = New-Object 'System.Collections.Generic.HashSet[string]' ([string[]]@(Get-RomArchiveExtensions), [System.StringComparer]::OrdinalIgnoreCase)

    # Никаких дополнительных исключений по расширению здесь нет: содержимое
    # списка определяется ТОЛЬКО настройкой расширений выбранного эмулятора.
    # Поэтому, например, DLC/patch в формате .nsp остаются в ComboBox, но
    # исключаются из автоматического кандидата по имени ниже.

    # Эти признаки исключают файл только из АВТОВЫБОРА.
    $junkNamePattern = '(?i)(?:^|[\s._\-\[\]()])(?:patch(?:es)?|update|upd|dlc|bonus(?:es)?|extra(?:s)?|addon|add-on|expansion|season[\s._\-]+pass|fighters[\s._\-]+pass|artbook|ost|soundtrack|manual|scan(?:s)?|crack|trainer|keygen|repack|hotfix|(?:bug)?fix|proto(?:type)?|sample|demo|beta)(?:$|[\s._\-\[\]()])'

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($f in $all) {
        $ext = $f.Extension.TrimStart('.').ToLowerInvariant()

        # При настроенном эмуляторе в ComboBox разрешены ТОЛЬКО его расширения.
        if (-not $knownExtSet.Contains($ext)) { continue }

        $isAutoCandidate = $true
        if ($f.Name -match $junkNamePattern) { $isAutoCandidate = $false }

        # v1/v2/... — патч/обновление. v0 — базовая версия и имеет максимальный
        # приоритет среди обычных ROM. Версии оставляем в списке, но v1+ никогда
        # не выбираются автоматически.
        $versionNumber = -1
        $versionMatch = [regex]::Match([string]$f.BaseName, '(?i)(?:^|[\s._\-\[\]()])v(?<n>\d+)(?:$|[\s._\-\[\]()])')
        if ($versionMatch.Success) {
            [int]::TryParse($versionMatch.Groups['n'].Value, [ref]$versionNumber) | Out-Null
        }
        if ($versionNumber -ge 1) { $isAutoCandidate = $false }

        # Дисковые образы: .m3u (мультидиск) и .cue — то, что реально запускает
        # ядро; .bin/.img лежат рядом как данные и не должны выбираться первыми.
        $extBoost = 0
        if ($ext -eq 'm3u') { $extBoost = -20 }
        elseif ($ext -in @('cue','ccd','mds','toc','gdi')) { $extBoost = -10 }
        elseif ($ext -in @('bin','img') -and @($all | Where-Object { $_.DirectoryName -eq $f.DirectoryName -and $_.Extension -match '(?i)^\.(cue|m3u|ccd|mds|toc)$' }).Count -gt 0) { $extBoost = 5 }

        # Чем меньше приоритет — тем раньше автоматический выбор.
        # v0 = базовая версия, затем обычный ROM, затем DLC/patch/update и v1+.
        $romPriority = 100
        if ($isAutoCandidate) {
            $romPriority = 0
            if ($versionNumber -eq 0) { $romPriority = -100 }
            $romPriority += $extBoost
        } elseif ($versionNumber -ge 1) {
            $romPriority = 300 + $versionNumber
        } else {
            $romPriority = 200
        }

        $result.Add([PSCustomObject]@{
            FullName = $f.FullName
            Name = $f.Name
            # IsKnown теперь означает "можно использовать для автоматического
            # выбора", а не просто "расширение известно".
            IsKnown = [bool]$isAutoCandidate
            RomPriority = $romPriority
            IsPreferredExtension = [bool](($preferredExts.Count -gt 0 -and $preferredExts -contains $ext) -or ($includeArchives -and $archiveExtSet.Contains($ext)))
        })
    }

    # Сначала нормальные кандидаты (v0 первым), затем файлы, которые оставлены
    # в списке только для ручного выбора (DLC/patch/v1+).
    return @($result | Sort-Object @{Expression={ [int]$_.RomPriority }}, Name)
}


# ===================== ИСТОЧНИК МИНИАТЮР =====================
# Ресурсы интерфейса встроены непосредственно в EXE/скрипт как Base64.
# Отдельная папка assets рядом с программой больше не требуется.
$global:embeddedSteamGridSourcePng = ""
$global:embeddedNoCoverSteamJpg = ""
$global:embeddedNoCoverSteamGridJpg = ""

# Встроенные значки лаунчеров (PNG 32x32, Base64): программа не ищет их в системе и не зависит от
# того, куда установлен лаунчер. Порядок вкладок библиотеки: Steam, Epic, GOG, Ubisoft, EA, Battle.net, Xbox.
$global:embeddedLauncherIconsB64 = @{
    'steam' = ''
    'epic' = ''
    'gog' = ''
    'ubisoft' = ''
    'ea' = ''
    'battlenet' = ''
    'xbox' = ''
}

# Возвращает значок лаунчера как Bitmap size x size (с прозрачным полем $pad px), либо $null.
function Get-EmbeddedLauncherIconBitmap([string]$id, [int]$size = 20, [int]$pad = 0) {
    try {
        $b64 = $global:embeddedLauncherIconsB64[[string]$id]
        if ([string]::IsNullOrWhiteSpace([string]$b64)) { return $null }
        $ms = New-Object System.IO.MemoryStream(,[System.Convert]::FromBase64String([string]$b64))
        try {
            $img = [System.Drawing.Image]::FromStream($ms)
            try {
                $bmp = New-Object System.Drawing.Bitmap($size, $size, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
                $g = [System.Drawing.Graphics]::FromImage($bmp)
                try {
                    $g.Clear([System.Drawing.Color]::Transparent)
                    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                    $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
                    $inner = $size - (2 * $pad)
                    $g.DrawImage($img, $pad, $pad, $inner, $inner)
                } finally { $g.Dispose() }
                return $bmp
            } finally { $img.Dispose() }
        } finally { $ms.Dispose() }
    } catch { return $null }
}


# ===================== ЕДИНЫЕ ЗНАЧКИ БИБЛИОТЕКИ =====================
# Все значки в библиотеке (вкладки лаунчеров, бейджи на плитках, всплывающая карточка,
# значки на кнопке «Библиотека/Импорт») строятся ОДНИМ способом и имеют ОДИН размер:
#   1) берётся самый крупный доступный исходник (встроенный PNG 64 px / иконка exe до 256 px);
#   2) обрезаются прозрачные поля — у разных значков они разные, из-за этого одни казались меньше;
#   3) видимая часть вписывается в квадрат ($global:LibIconSize - 2 px) и ставится по центру;
#   4) уменьшение идёт ступенями (в 2 раза за шаг) с HighQualityBicubic — без «лесенки» и ореолов.
# Готовый Bitmap точно $global:LibIconSize x $global:LibIconSize рисуется 1:1, без растяжения.
# Bitmap'ы общие (кэш на весь сеанс) — их нельзя освобождать (Dispose).
$global:LibIconSize = 22
if ($null -eq $script:libIconCache) { $script:libIconCache = @{} }

function ConvertTo-LibUniformIcon ($Src, [int]$Size = 0) {
    if ($Size -le 0) { $Size = [int]$global:LibIconSize }
    $fill = [Math]::Max(1, $Size - 2)
    $work = $null; $cur = $null; $out = $null; $ia = $null
    $temps = New-Object System.Collections.Generic.List[object]
    try {
        if ($null -eq $Src) { return $null }
        $sw = [int]$Src.Width; $sh = [int]$Src.Height
        if ($sw -lt 1 -or $sh -lt 1) { return $null }

        # Рабочая копия в ARGB (исходник может быть Icon-bitmap, индексированным PNG и т.п.).
        $work = New-Object System.Drawing.Bitmap($sw, $sh, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $g0 = [System.Drawing.Graphics]::FromImage($work)
        try {
            $g0.Clear([System.Drawing.Color]::Transparent)
            $g0.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceCopy
            $g0.DrawImage($Src, 0, 0, $sw, $sh)
        } finally { $g0.Dispose() }

        # Границы непрозрачной части (альфа > 24).
        $rect = New-Object System.Drawing.Rectangle(0, 0, $sw, $sh)
        $bd = $work.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $stride = [int]$bd.Stride
        $bytes = New-Object byte[] ($stride * $sh)
        try { [System.Runtime.InteropServices.Marshal]::Copy($bd.Scan0, $bytes, 0, $bytes.Length) } finally { $work.UnlockBits($bd) }
        $step = [Math]::Max(1, [int][Math]::Floor([Math]::Max($sw, $sh) / 96))
        $minX = $sw; $minY = $sh; $maxX = -1; $maxY = -1
        for ($y = 0; $y -lt $sh; $y += $step) {
            $row = $y * $stride
            for ($x = 0; $x -lt $sw; $x += $step) {
                if ($bytes[$row + ($x * 4) + 3] -gt 24) {
                    if ($x -lt $minX) { $minX = $x }
                    if ($x -gt $maxX) { $maxX = $x }
                    if ($y -lt $minY) { $minY = $y }
                    if ($y -gt $maxY) { $maxY = $y }
                }
            }
        }
        if ($maxX -lt 0) {
            $minX = 0; $minY = 0; $maxX = $sw - 1; $maxY = $sh - 1
        } else {
            $minX = [Math]::Max(0, $minX - ($step - 1)); $minY = [Math]::Max(0, $minY - ($step - 1))
            $maxX = [Math]::Min($sw - 1, $maxX + ($step - 1)); $maxY = [Math]::Min($sh - 1, $maxY + ($step - 1))
        }
        $bw = $maxX - $minX + 1
        $bh = $maxY - $minY + 1

        $scale = $fill / [double][Math]::Max($bw, $bh)
        $dw = [Math]::Max(1, [int][Math]::Round($bw * $scale))
        $dh = [Math]::Max(1, [int][Math]::Round($bh * $scale))

        $ia = New-Object System.Drawing.Imaging.ImageAttributes
        $ia.SetWrapMode([System.Drawing.Drawing2D.WrapMode]::TileFlipXY)

        # Ступенчатое уменьшение: пока исходник больше цели более чем вдвое — делим пополам.
        $cur = $work; $curX = $minX; $curY = $minY; $curW = $bw; $curH = $bh
        while ($curW -ge (2 * $dw) -and $curH -ge (2 * $dh)) {
            $nw = [Math]::Max($dw, [int][Math]::Floor($curW / 2))
            $nh = [Math]::Max($dh, [int][Math]::Floor($curH / 2))
            $tmp = New-Object System.Drawing.Bitmap($nw, $nh, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
            $gt = [System.Drawing.Graphics]::FromImage($tmp)
            try {
                $gt.Clear([System.Drawing.Color]::Transparent)
                $gt.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceCopy
                $gt.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                $gt.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                $gt.DrawImage($cur, (New-Object System.Drawing.Rectangle(0, 0, $nw, $nh)), $curX, $curY, $curW, $curH, [System.Drawing.GraphicsUnit]::Pixel, $ia)
            } finally { $gt.Dispose() }
            [void]$temps.Add($tmp)
            $cur = $tmp; $curX = 0; $curY = 0; $curW = $nw; $curH = $nh
        }

        $out = New-Object System.Drawing.Bitmap($Size, $Size, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $go = [System.Drawing.Graphics]::FromImage($out)
        try {
            $go.Clear([System.Drawing.Color]::Transparent)
            $go.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceOver
            $go.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $go.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $go.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
            $dx = [int][Math]::Floor(($Size - $dw) / 2.0)
            $dy = [int][Math]::Floor(($Size - $dh) / 2.0)
            $go.DrawImage($cur, (New-Object System.Drawing.Rectangle($dx, $dy, $dw, $dh)), $curX, $curY, $curW, $curH, [System.Drawing.GraphicsUnit]::Pixel, $ia)
        } finally { $go.Dispose() }
        return $out
    } catch {
        if ($null -ne $out) { try { $out.Dispose() } catch {} }
        return $null
    } finally {
        foreach ($t in $temps) { try { $t.Dispose() } catch {} }
        if ($null -ne $work) { try { $work.Dispose() } catch {} }
        if ($null -ne $ia) { try { $ia.Dispose() } catch {} }
    }
}

# Кэшированный Bitmap ещё жив (его не освободили)?
function Test-LibIconBitmapAlive ($Bmp) {
    if ($null -eq $Bmp) { return $false }
    try { [void]$Bmp.Width; return $true } catch { return $false }
}

# Значок из встроенных ресурсов ('steam', 'epic', 'gog', ...) в едином размере/качестве.
function Get-LibUniformIcon ([string]$Id, [int]$Size = 0) {
    if ($Size -le 0) { $Size = [int]$global:LibIconSize }
    $key = 'emb|' + $Id + '|' + $Size
    if ($script:libIconCache.ContainsKey($key)) {
        $cached = $script:libIconCache[$key]
        if (Test-LibIconBitmapAlive $cached) { return $cached }
        [void]$script:libIconCache.Remove($key)
    }
    $bmp = $null
    try {
        $b64 = $global:embeddedLauncherIconsB64[[string]$Id]
        if (-not [string]::IsNullOrWhiteSpace([string]$b64)) {
            $ms = New-Object System.IO.MemoryStream(,[System.Convert]::FromBase64String([string]$b64))
            try {
                $img = [System.Drawing.Image]::FromStream($ms)
                try { $bmp = ConvertTo-LibUniformIcon $img $Size } finally { $img.Dispose() }
            } finally { $ms.Dispose() }
        }
    } catch { $bmp = $null }
    if ($null -ne $bmp) { $script:libIconCache[$key] = $bmp }
    return $bmp
}

# Значок эмулятора для ROM-плиток: исходник берём в максимальном качестве из exe (до 256 px),
# а не 32-пиксельный из кэша, и приводим к тому же размеру/полям, что и значки лаунчеров.
function Get-LibEmulatorBadgeBitmap ($Emu, [int]$Size = 0) {
    if ($null -eq $Emu) { return $null }
    if ($Size -le 0) { $Size = [int]$global:LibIconSize }
    $id = ''; $exe = ''
    try { $id = [string]$Emu.Id; $exe = [string]$Emu.ExePath } catch {}
    if ([string]::IsNullOrWhiteSpace($id)) { return $null }
    $key = 'emu|' + $id + '|' + $exe + '|' + $Size
    if ($script:libIconCache.ContainsKey($key)) {
        $cached = $script:libIconCache[$key]
        if (Test-LibIconBitmapAlive $cached) { return $cached }
        [void]$script:libIconCache.Remove($key)
    }
    $src = $null; $own = $false; $bmp = $null
    try {
        if (-not [string]::IsNullOrWhiteSpace($exe) -and (Test-Path -LiteralPath $exe -PathType Leaf)) {
            try { $src = Get-BitmapFromExeFile $exe; if ($null -ne $src) { $own = $true } } catch { $src = $null }
        }
        if ($null -eq $src) { $src = Get-EmulatorIconBitmap $Emu; $own = $false }
        if ($null -ne $src) { $bmp = ConvertTo-LibUniformIcon $src $Size }
    } catch { $bmp = $null }
    finally { if ($own -and $null -ne $src) { try { $src.Dispose() } catch {} } }
    if ($null -ne $bmp) { $script:libIconCache[$key] = $bmp }
    return $bmp
}


function Get-EmbeddedAssetBytes([string]$name) {
    try {
        $b64 = switch ($name) {
            'steamgrid_source.png'  { $global:embeddedSteamGridSourcePng }
            'no_cover_steam.jpg'   { $global:embeddedNoCoverSteamJpg }
            'no_cover_steamgrid.jpg' { $global:embeddedNoCoverSteamGridJpg }
            default { $null }
        }
        if ([string]::IsNullOrWhiteSpace([string]$b64)) { return $null }
        return [System.Convert]::FromBase64String($b64)
    } catch { return $null }
}

function Get-EditorMissingPlaceholderBitmap([string]$source) {
    try {
        $name = if ($source -eq 'Steam') { 'no_cover_steam.jpg' } else { 'no_cover_steamgrid.jpg' }
        $bytes = Get-EmbeddedAssetBytes $name
        if ($null -eq $bytes) { return $null }
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        try {
            $img = [System.Drawing.Image]::FromStream($ms)
            try { return New-Object System.Drawing.Bitmap($img) } finally { $img.Dispose() }
        } finally { $ms.Dispose() }
    } catch { return $null }
}

function Get-SteamSourceIconBitmap ([int]$size = 20, [int]$pad = 1) {
    # Сначала встроенный значок Steam (не зависит от расположения steam.exe).
    try { $embSteam = Get-EmbeddedLauncherIconBitmap 'steam' $size $pad; if ($null -ne $embSteam) { return $embSteam } } catch {}
    # Иконка именно Steam-клиента. Ищем steam.exe не только в стандартной
    # папке, но и по настройке/реестру — Steam у пользователя может быть
    # установлен на другом диске.
    $candidates = New-Object System.Collections.Generic.List[string]
    try {
        $configured = [string](Get-ConfiguredSteamExePath)
        if (-not [string]::IsNullOrWhiteSpace($configured)) { [void]$candidates.Add($configured) }
    } catch {}
    try {
        $reg = (Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
        if (-not [string]::IsNullOrWhiteSpace([string]$reg)) { [void]$candidates.Add([string]$reg) }
    } catch {}
    foreach ($p in @(
        'C:\Program Files (x86)\Steam\steam.exe',
        'C:\Program Files\Steam\steam.exe'
    )) { [void]$candidates.Add($p) }

    foreach ($steamExe in $candidates) {
        try {
            if (-not (Test-Path -LiteralPath $steamExe -PathType Leaf)) { continue }
            $ico = [System.Drawing.Icon]::ExtractAssociatedIcon((Resolve-Path -LiteralPath $steamExe).Path)
            if ($null -eq $ico) { continue }
            try {
                # Отдельная Bitmap с прозрачным полем. Не возвращаем сам Icon,
                # чтобы кнопка гарантированно могла отрисовать его после выхода
                # из функции.
                $src = $ico.ToBitmap()
                try {
                    $bmp = New-Object System.Drawing.Bitmap 20,20
                    $g = [System.Drawing.Graphics]::FromImage($bmp)
                    try {
                        $g.Clear([System.Drawing.Color]::Transparent)
                        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
                        $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                        $g.DrawImage($src, 1, 1, 18, 18)
                    } finally { $g.Dispose() }
                    return $bmp
                } catch {}
                finally { }
            } finally { $ico.Dispose() }
        } catch {}
    }

    # Резервный Steam-знак, если steam.exe недоступен.
    try {
        $bmp = New-Object System.Drawing.Bitmap 20,20
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.Clear([System.Drawing.Color]::Transparent)
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 1.7)
            $brush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(45,118,180))
            $g.FillEllipse($brush, 1, 1, 18, 18)
            $g.DrawEllipse($pen, 1, 1, 18, 18)
            $g.DrawEllipse($pen, 10, 4, 5, 5)
            $g.DrawLine($pen, 10, 9, 7, 13)
            $g.DrawLine($pen, 7, 13, 4, 11)
            $pen.Dispose(); $brush.Dispose()
        } finally { $g.Dispose() }
        return $bmp
    } catch { return $null }
}

# Единый значок Steam для плиток библиотеки (вкладка Steam + «уже в Steam» на
# вкладках лаунчеров + всплывающая карточка). Один bitmap 22×22, без повторного
# ресайза — иначе качество и «вес» значка отличаются между вкладками.
function Get-LibSteamBadgeBitmap {
    if (Test-LibIconBitmapAlive $script:libSteamBadgeBmp) { return $script:libSteamBadgeBmp }
    try {
        $b = Get-LibUniformIcon 'steam'
        if ($null -eq $b) {
            # Встроенного значка нет — берём значок steam.exe/запасной знак и приводим к тому же виду.
            $fb = $null
            try { $fb = Get-SteamSourceIconBitmap 64 0 } catch { $fb = $null }
            if ($null -ne $fb) { try { $b = ConvertTo-LibUniformIcon $fb } finally { try { $fb.Dispose() } catch {} } }
        }
        $script:libSteamBadgeBmp = $b
    } catch {
        $script:libSteamBadgeBmp = $null
    }
    return $script:libSteamBadgeBmp
}

# Значки ВСЕХ поддерживаемых лаунчеров для кнопки «Библиотека/Импорт» — в порядке вкладок
# библиотеки (после Steam): Epic, GOG, Ubisoft, EA, Battle.net, Xbox. Берутся из встроенных
# ресурсов (см. $global:embeddedLauncherIconsB64), поиска по системе нет.
function Get-LibraryButtonLauncherIcons {
    $result = New-Object System.Collections.Generic.List[object]
    $fallback = @{
        'epic'      = @('E',  52,  52,  58)
        'gog'       = @('G',  134, 50,  212)
        'ubisoft'   = @('U',  0,   112, 255)
        'ea'        = @('EA', 230, 60,  60)
        'battlenet' = @('B',  0,   174, 255)
        'xbox'      = @('X',  16,  124, 16)
    }
    foreach ($id in @('epic', 'gog', 'ubisoft', 'ea', 'battlenet', 'xbox')) {
        $bmp = $null
        try { $bmp = Get-LibUniformIcon $id } catch {}
        if ($null -eq $bmp) {
            try {
                $f = $fallback[$id]
                $gl = New-LauncherGlyphBitmap $f[0] ([System.Drawing.Color]::FromArgb([int]$f[1], [int]$f[2], [int]$f[3])) 64
                try { $bmp = ConvertTo-LibUniformIcon $gl } finally { $gl.Dispose() }
            } catch { $bmp = $null }
        }
        if ($null -ne $bmp) { [void]$result.Add($bmp) }
    }
    return $result.ToArray()
}

# Повторно назначаем иконки ПОСЛЕ полной инициализации формы. Для каждой кнопки
# создаём отдельную Bitmap: один и тот же Image в WinForms-кнопках иногда ведёт
# к неожиданной перерисовке/замене при обновлении текста.
function Set-SteamButtonIcons {
    try {
        if ($null -eq $script:steamAddButtonIcon) {
            $script:steamAddButtonIcon = Get-SteamSourceIconBitmap
        }
        if ($null -eq $script:steamLibraryButtonIcon) {
            $script:steamLibraryButtonIcon = Get-SteamSourceIconBitmap
        }
        if ($null -eq $script:libraryButtonLauncherIcons) {
            $script:libraryButtonLauncherIcons = @(Get-LibraryButtonLauncherIcons)
        }
        if ($null -ne $btnAddToSteam) { $btnAddToSteam.Invalidate() }
        if ($null -ne $btnSteamLibrary) { $btnSteamLibrary.Invalidate() }
    } catch {}
}

# WinForms ImageBeforeText центрирует Image и Text не как единый блок.
# Поэтому содержимое этих двух кнопок рисуем вручную как единый блок:
# иконка Steam + (для добавления) плюсик + текст, строго по центру кнопки.
$drawSteamButtonContent = {
    param($sender, $e)
    try {
        $btn = $sender
        $g = $e.Graphics
        $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
        $icon = if ($btn -eq $btnAddToSteam) { $script:steamAddButtonIcon } else { $script:steamLibraryButtonIcon }
        $text = [string]$btn.Tag
        if ([string]::IsNullOrWhiteSpace($text)) { return }

        $font = $btn.Font
        # Плюс как у кнопки "Добавить игру" в Steam: скруглённый квадрат, плюс в нём вырезан.
        $plus = ($btn -eq $btnAddToSteam -and -not $script:batchInProgress)
        $mainText = $text

        $plusBox = 14
        $plusSize = if ($plus) { [System.Drawing.SizeF]::new($plusBox, $plusBox) } else { [System.Drawing.SizeF]::new(0,0) }
        $textSize = $g.MeasureString($mainText, $font)
        $gap1 = if ($icon) { 7 } else { 0 }
        $gap2 = if ($plus) { 8 } else { 0 }
        $iconW = if ($icon) { 20 } else { 0 }
        # Кнопка «Библиотека/Импорт»: после текста — значки всех поддерживаемых лаунчеров
        # (в порядке вкладок библиотеки), каждый $global:LibIconSize x $global:LibIconSize (как на вкладках) с зазором 6 px.
        $tailIcons = @()
        if ($btn -eq $btnSteamLibrary) { $tailIcons = @($script:libraryButtonLauncherIcons | Where-Object { $null -ne $_ }) }
        $tailSize = [int]$global:LibIconSize   # тот же размер, что и у значков на вкладках/плитках
        $tailGap  = 6
        $tailLead = -1  # поправка к зазору между текстом и значками (DrawString/MeasureString и сами значки уже дают ≈ 12 px; по скриншоту при 4 было ≈ 17 px)
        $suffixLead = 8 # добавка к пробелу в начале « / DLSS Swap» (пробел ≈ 4 px; вместе ≈ 12 px — как перед значками)
        $tailW = if ($tailIcons.Count -gt 0) { $tailLead + ($tailIcons.Count * $tailSize) + (($tailIcons.Count - 1) * $tailGap) } else { 0 }
        # Кнопка «Библиотека/Импорт»: после значков лаунчеров — « / DLSS Swap» (пробел, /, пробел, DLSS Swap).
        $suffixText = ''
        $suffixW = 0.0
        if ($btn -eq $btnSteamLibrary) {
            $suffixText = ' / DLSS Swap'
            $suffixW = [double]$g.MeasureString($suffixText, $font, 10000, [System.Drawing.StringFormat]::GenericTypographic).Width
        }
        $totalW = $iconW + $gap1 + $plusSize.Width + $gap2 + $textSize.Width + $tailW + $suffixW + $(if ($suffixText.Length -gt 0 -and $tailIcons.Count -gt 0) { $suffixLead } else { 0 })
        $x = ($btn.ClientSize.Width - $totalW) / 2.0
        $yIcon = ($btn.ClientSize.Height - 20) / 2.0
        $yText = ($btn.ClientSize.Height - $textSize.Height) / 2.0
        $brush = New-Object System.Drawing.SolidBrush($btn.ForeColor)
        try {
            if ($icon) { $g.DrawImage($icon, [float]$x, [float]$yIcon, 20.0, 20.0); $x += $iconW + $gap1 }
            if ($plus) {
                $yPlus = [float](($btn.ClientSize.Height - $plusBox) / 2.0)
                $px = [float]$x
                $r = 3.0; $d = $r * 2; $s = [float]$plusBox
                $path = New-Object System.Drawing.Drawing2D.GraphicsPath([System.Drawing.Drawing2D.FillMode]::Alternate)
                try {
                    # скруглённый квадрат
                    $path.AddArc($px, $yPlus, $d, $d, 180, 90)
                    $path.AddArc($px + $s - $d, $yPlus, $d, $d, 270, 90)
                    $path.AddArc($px + $s - $d, $yPlus + $s - $d, $d, $d, 0, 90)
                    $path.AddArc($px, $yPlus + $s - $d, $d, $d, 90, 90)
                    $path.CloseFigure()
                    # плюс 8x8 px, толщина 2 px — при Alternate-заливке получается "дыркой"
                    $c = $s / 2.0
                    # Плюс — ОДИН 12-угольник: две пересекающиеся перекладины при Alternate-заливке
                    # дали бы закрашенную точку в центре (чётное/нечётное число вхождений).
                    $cx = $px + $c; $cy = $yPlus + $c
                    $plusPts = [System.Drawing.PointF[]]@(
                        [System.Drawing.PointF]::new($cx - 1, $cy - 4), [System.Drawing.PointF]::new($cx + 1, $cy - 4),
                        [System.Drawing.PointF]::new($cx + 1, $cy - 1), [System.Drawing.PointF]::new($cx + 4, $cy - 1),
                        [System.Drawing.PointF]::new($cx + 4, $cy + 1), [System.Drawing.PointF]::new($cx + 1, $cy + 1),
                        [System.Drawing.PointF]::new($cx + 1, $cy + 4), [System.Drawing.PointF]::new($cx - 1, $cy + 4),
                        [System.Drawing.PointF]::new($cx - 1, $cy + 1), [System.Drawing.PointF]::new($cx - 4, $cy + 1),
                        [System.Drawing.PointF]::new($cx - 4, $cy - 1), [System.Drawing.PointF]::new($cx - 1, $cy - 1)
                    )
                    $path.StartFigure()
                    $path.AddPolygon($plusPts)
                    $oldSmooth = $g.SmoothingMode
                    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
                    $g.FillPath($brush, $path)
                    $g.SmoothingMode = $oldSmooth
                } finally { $path.Dispose() }
                $x += $plusSize.Width + $gap2
            }
            $g.DrawString($mainText, $font, $brush, [float]$x, [float]$yText)
            if ($tailIcons.Count -gt 0) {
                $x += $textSize.Width + $tailLead
                $yTail = ($btn.ClientSize.Height - $tailSize) / 2.0
                $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                foreach ($ti in $tailIcons) {
                    $g.DrawImage($ti, [float]$x, [float]$yTail, [float]$tailSize, [float]$tailSize)
                    $x += $tailSize + $tailGap
                }
                $x -= $tailGap   # после последнего значка зазор задаёт пробел в начале суффикса + $suffixLead
                if ($suffixText.Length -gt 0) { $x += $suffixLead }
            } else {
                $x += $textSize.Width
            }
            if ($suffixText.Length -gt 0) {
                $g.DrawString($suffixText, $font, $brush, [float]$x, [float]$yText, [System.Drawing.StringFormat]::GenericTypographic)
            }
        } finally { $brush.Dispose() }
    } catch {}
}
$btnAddToSteam.Add_Paint($drawSteamButtonContent)
$btnSteamLibrary.Add_Paint($drawSteamButtonContent)

function Get-SteamGridDbSourceIconBitmap {
    try {
        $bytes = Get-EmbeddedAssetBytes 'steamgrid_source.png'
        if ($null -eq $bytes) { return $null }
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        try {
            $img = [System.Drawing.Image]::FromStream($ms)
            try {
                # Приводим SGDB-иконку к 22x22: вытянутый значок занимает всю ширину холста (22 px),
                # чтобы не выглядеть мельче остальных.
                $bmp = New-Object System.Drawing.Bitmap 22,22
                $g = [System.Drawing.Graphics]::FromImage($bmp)
                try {
                    $g.Clear([System.Drawing.Color]::Transparent)
                    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
                    $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                    $srcW = [int]$img.Width
                    $srcH = [int]$img.Height
                    $scale = [Math]::Min(22.0 / [Math]::Max(1,$srcW), 22.0 / [Math]::Max(1,$srcH))
                    $dstW = [int][Math]::Round($srcW * $scale)
                    $dstH = [int][Math]::Round($srcH * $scale)
                    $dstX = [int][Math]::Round((22 - $dstW) / 2.0)
                    $dstY = [int][Math]::Round((22 - $dstH) / 2.0)
                    $g.DrawImage($img, $dstX, $dstY, $dstW, $dstH)
                } finally { $g.Dispose() }
                return $bmp
            } finally { $img.Dispose() }
        } finally { $ms.Dispose() }
    } catch { return $null }
}

# Иконка SGDB для заголовков окон (маленький значок в левом углу заголовка).
# Собирается один раз из встроенного steamgrid_source.png (та же картинка, что
# помечает источник обложек) и кэшируется на весь сеанс.
$global:sgdbFormIcon = $null
function Get-SteamGridDbFormIcon {
    if ($null -ne $global:sgdbFormIcon) { return $global:sgdbFormIcon }
    try {
        $bytes = Get-EmbeddedAssetBytes 'steamgrid_source.png'
        if ($null -eq $bytes) { return $null }
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        try {
            $img = [System.Drawing.Image]::FromStream($ms)
            try {
                # 32x32 с прозрачным полем: Windows сама уменьшит до размера
                # заголовка (16 px при 100% масштабе, больше при 125-200%).
                $bmp = New-Object System.Drawing.Bitmap 32,32
                $g = [System.Drawing.Graphics]::FromImage($bmp)
                try {
                    $g.Clear([System.Drawing.Color]::Transparent)
                    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
                    $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                    $scale = [Math]::Min(30.0 / [Math]::Max(1,[int]$img.Width), 30.0 / [Math]::Max(1,[int]$img.Height))
                    $dstW = [int][Math]::Round($img.Width * $scale)
                    $dstH = [int][Math]::Round($img.Height * $scale)
                    $g.DrawImage($img, [int][Math]::Round((32 - $dstW) / 2.0), [int][Math]::Round((32 - $dstH) / 2.0), $dstW, $dstH)
                } finally { $g.Dispose() }
                try { $global:sgdbFormIcon = [System.Drawing.Icon]::FromHandle($bmp.GetHicon()) } finally { $bmp.Dispose() }
            } finally { $img.Dispose() }
        } finally { $ms.Dispose() }
    } catch { $global:sgdbFormIcon = $null }
    return $global:sgdbFormIcon
}

# Значки для кнопок переключения источника поиска (Steam / SGDB) в карточке игры.
# Берём те же 22x22 картинки, что помечают источник обложек, обрезаем прозрачное
# поле и приводим к 16x16. Возвращаем пару: обычный значок и приглушённый (для
# неактивного источника и заблокированной кнопки SGDB).
function New-SourceButtonIconPair ($sourceBmp) {
    if ($null -eq $sourceBmp) { return $null }
    try {
        # Квадрат 20x20 — крупный значок на кнопке 28 px.
        # WinForms при ImageBeforeText рисует Image на 1–2 px ниже текста
        # (особенно заметно, когда Image почти во всю высоту кнопки). Поэтому
        # глиф внутри холста сдвигаем вверх на $shiftUp: снизу остаётся
        # прозрачный запас, сверху глиф ближе к середине кнопки рядом с текстом.
        $sz = 20
        $targetVis = 17
        $shiftUp = 2

        $srcW = [int]$sourceBmp.Width; $srcH = [int]$sourceBmp.Height
        $minX = $srcW; $minY = $srcH; $maxX = -1; $maxY = -1
        for ($yy = 0; $yy -lt $srcH; $yy++) {
            for ($xx = 0; $xx -lt $srcW; $xx++) {
                if ($sourceBmp.GetPixel($xx, $yy).A -gt 24) {
                    if ($xx -lt $minX) { $minX = $xx }; if ($xx -gt $maxX) { $maxX = $xx }
                    if ($yy -lt $minY) { $minY = $yy }; if ($yy -gt $maxY) { $maxY = $yy }
                }
            }
        }
        if ($maxX -lt 0) { $minX = 0; $minY = 0; $maxX = $srcW - 1; $maxY = $srcH - 1 }

        # Масштаб по непрозрачной рамке — одинаковый размер у Steam и SGDB.
        $visW = [double]($maxX - $minX + 1)
        $visH = [double]($maxY - $minY + 1)
        $k = $targetVis / [Math]::Max($visW, $visH)
        $dw = [int][Math]::Round($visW * $k)
        $dh = [int][Math]::Round($visH * $k)
        $dx = [int][Math]::Round(($sz - $dw) / 2.0)
        $dy = [int][Math]::Round(($sz - $dh) / 2.0) - $shiftUp
        if ($dy -lt 0) { $dy = 0 }

        $bright = New-Object System.Drawing.Bitmap $sz,$sz
        $g = [System.Drawing.Graphics]::FromImage($bright)
        try {
            $g.Clear([System.Drawing.Color]::Transparent)
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $ia0 = New-Object System.Drawing.Imaging.ImageAttributes
            $ia0.SetWrapMode([System.Drawing.Drawing2D.WrapMode]::TileFlipXY)
            $dest = New-Object System.Drawing.Rectangle $dx,$dy,$dw,$dh
            $g.DrawImage($sourceBmp, $dest, $minX, $minY, [int]$visW, [int]$visH, [System.Drawing.GraphicsUnit]::Pixel, $ia0)
            $ia0.Dispose()
        } finally { $g.Dispose() }

        $dim = New-Object System.Drawing.Bitmap $sz,$sz
        $g2 = [System.Drawing.Graphics]::FromImage($dim)
        try {
            $g2.Clear([System.Drawing.Color]::Transparent)
            $cm = New-Object System.Drawing.Imaging.ColorMatrix
            $cm.Matrix33 = 0.5
            $ia = New-Object System.Drawing.Imaging.ImageAttributes
            $ia.SetColorMatrix($cm)
            $dest2 = New-Object System.Drawing.Rectangle 0,0,$sz,$sz
            $g2.DrawImage($bright, $dest2, 0, 0, $sz, $sz, [System.Drawing.GraphicsUnit]::Pixel, $ia)
            $ia.Dispose()
        } finally { $g2.Dispose() }
        return [PSCustomObject]@{ Bright = $bright; Dim = $dim }
    } catch { return $null }
}


# ===================== МЕТАДАННЫЕ ОБ ИСТОЧНИКЕ ОБЛОЖЕК =====================
# Один JSON-файл на shortcutId в $global:coverSourcesDir, например "12345678.json":
# {"p":"Steam","header":"SteamGridDB","hero":"Steam","logo":"SteamGridDB"}
# Без этих файлов при повторном открытии карточки уже сохранённой игры узнать,
# откуда взялась каждая конкретная миниатюра, неоткуда — сам Steam это не хранит.

function Get-CoverSourcesMetadataPath([string]$shortcutId) {
    if ([string]::IsNullOrWhiteSpace($shortcutId)) { return $null }
    return (Join-Path $global:coverSourcesDir ($shortcutId + ".json"))
}

function Get-CoverSourcesMetadata([string]$shortcutId) {
    try {
        $path = Get-CoverSourcesMetadataPath $shortcutId
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path $path)) { return $null }
        $raw = Get-Content -LiteralPath $path -Raw -ErrorAction Stop
        if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
        return ($raw | ConvertFrom-Json -ErrorAction Stop)
    } catch { return $null }
}

# $slots — та же коллекция слотов карточки (Vertical/Horizontal/Hero/Logo),
# что используется в редакторе. Пишем текущий .Source каждого слота на диск,
# чтобы при следующем открытии карточки значки источников не терялись.
function Save-CoverSourcesMetadata([string]$shortcutId, $slots, [string]$coverLang = '') {
    try {
        if ([string]::IsNullOrWhiteSpace($shortcutId) -or $null -eq $slots) { return $false }
        if (-not (Test-Path $global:coverSourcesDir)) { New-Item -ItemType Directory -Path $global:coverSourcesDir -Force | Out-Null }
        $path = Get-CoverSourcesMetadataPath $shortcutId
        if ([string]::IsNullOrWhiteSpace($path)) { return $false }

        $resolve = { param($slot) $s = try { [string]$slot.Source } catch { $null }; if ([string]::IsNullOrWhiteSpace($s)) { 'Steam' } else { $s } }
        $data = [ordered]@{
            p      = (& $resolve $slots.Vertical)
            header = (& $resolve $slots.Horizontal)
            hero   = (& $resolve $slots.Hero)
            logo   = (& $resolve $slots.Logo)
        }
        try {
            if ($null -ne $slots.Icon) { $data['icon'] = (& $resolve $slots.Icon) }
        } catch {}
        # Регион (язык) Steam-обложек — чтобы при повторном открытии карточки кнопка
        # региона показывала тот, на котором обложки были сохранены.
        if (-not [string]::IsNullOrWhiteSpace($coverLang)) { $data['lang'] = $coverLang }
        ($data | ConvertTo-Json -Compress) | Out-File -LiteralPath $path -Encoding utf8 -Force
        return $true
    } catch { return $false }
}

# Удаляет устаревший файл метаданных, если у ярлыка при сохранении сменился
# shortcutId (например, из-за изменения имени или пути к EXE — оба участвуют
# в CRC-32, формирующем этот ID). Иначе рядом накапливался бы мусор от ID,
# которого в Steam уже не существует.
function Remove-CoverSourcesMetadata([string]$shortcutId) {
    try {
        $path = Get-CoverSourcesMetadataPath $shortcutId
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path $path)) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
    } catch {}
}

# Удаляет из $global:coverSourcesDir все файлы метаданных, чей ShortcutId
# (имя файла без .json) отсутствует в $liveShortcutIds — то есть игра, которой
# принадлежали эти обложки, была удалена из библиотеки Steam (shortcuts.vdf).
# $liveShortcutIds — хэш-таблица вида @{ "12345678" = $true; ... }, собранная
# при свежем чтении shortcuts.vdf в Refresh-Panels.
function Remove-OrphanedCoverSourcesMetadata($liveShortcutIds) {
    try {
        if (-not (Test-Path $global:coverSourcesDir)) { return }
        Get-ChildItem -Path $global:coverSourcesDir -Filter "*.json" -File -ErrorAction SilentlyContinue | ForEach-Object {
            $id = [System.IO.Path]::GetFileNameWithoutExtension($_.Name)
            if ([string]::IsNullOrWhiteSpace($id)) { return }
            # JSON лицензионных игр Steam тоже лежат здесь (имя файла = обычный App ID, он меньше 2^31),
            # а в shortcuts.vdf их нет — их не трогаем. У ярлыков appid всегда >= 2^31.
            if ($id -match '^\d+$') { $idNum = 0L; if ([int64]::TryParse($id, [ref]$idNum) -and $idNum -lt 2147483648L) { return } }
            if ($liveShortcutIds -eq $null -or -not $liveShortcutIds.ContainsKey($id)) {
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {}
}

function Set-EditorSourceBadge($slot, [string]$source) {
    try {
        if ($null -eq $slot -or $null -eq $slot.SourceBadge) { return }
        $slot.Source = [string]$source

        if ([string]::IsNullOrWhiteSpace($source)) {
            $slot.SourceBadge.Visible = $false
            try { $slot.SourceBadge.Image.Dispose() } catch {}
            $slot.SourceBadge.Image = $null
            $slot.SourceBadge.Tag = $null
            return
        }

        $bmp = if ($source -eq 'Steam') { Get-SteamSourceIconBitmap } elseif ($source -eq 'Local') { Get-LocalSourceIconBitmap } else { Get-SteamGridDbSourceIconBitmap }
        if ($null -eq $bmp) {
            $slot.SourceBadge.Visible = $false
            return
        }

        try { if ($null -ne $slot.SourceBadge.Image) { $slot.SourceBadge.Image.Dispose() } } catch {}
        $slot.SourceBadge.Image = $bmp
        $slot.SourceBadge.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
        $slot.SourceBadge.Visible = $true
        $slot.SourceBadge.BringToFront()
        try {
            if ($null -eq $slot.SourceBadge.Tag -or $slot.SourceBadge.Tag -isnot [System.Windows.Forms.ToolTip]) {
                $tt = New-Object System.Windows.Forms.ToolTip
                $slot.SourceBadge.Tag = $tt
            }
            $tipText = if ($source -eq 'Steam') { (T 'src_tip_steam') } elseif ($source -eq 'Local') { (T 'src_tip_local') } else { (T 'src_tip_sgdb') }
            # В композиции у фона и логотипа свои значки: в подсказке указываем, к чему относится источник.
            $pfxProp = $slot.PSObject.Properties['BadgeTipPrefix']
            if ($null -ne $pfxProp -and -not [string]::IsNullOrWhiteSpace([string]$pfxProp.Value)) { $tipText = [string]$pfxProp.Value + ': ' + $tipText }
            $slot.SourceBadge.Tag.SetToolTip($slot.SourceBadge, $tipText)
        } catch {}
    } catch {}
}

function Set-EditorMissingStateCore($slot, [bool]$missing) {
    if ($null -eq $slot) { return }
    try { $slot.PendingMissing = $missing } catch {}
    try {
        if (-not $missing) {
            # Миниатюра есть — убираем заглушку и спиннер.
            Set-EditorSlotLoading $slot $false
            $slot.Missing.Visible = $false
            $slot.Picture.Visible = $true
            return
        }

        # Источник известен из текущей операции загрузки.
        $expected = ''
        try { $expected = [string]$slot.ExpectedSource } catch {}
        if ([string]::IsNullOrWhiteSpace($expected)) {
            try { $expected = [string]$slot.Source } catch {}
        }
        if ([string]::IsNullOrWhiteSpace($expected)) { $expected = 'Steam' }

        # При отсутствии обложки используем красивую заглушку именно этого источника,
        # а не старый красный крест.
        try {
            $placeholder = Get-EditorMissingPlaceholderBitmap $expected
            if ($null -ne $placeholder) {
                if ($null -ne $slot.Missing.Image) { $slot.Missing.Image.Dispose() }
                $slot.Missing.Image = $placeholder
            }
        } catch {}

        # Пока загрузка идёт — только анимация. Значок источника и заглушка
        # появляются после завершения попытки загрузки.
        if ($slot.IsLoading) {
            $slot.Missing.Visible = $false
            $slot.Picture.Visible = $true
            try { if ($null -ne $slot.Loading) { $slot.Loading.BringToFront() } } catch {}
            return
        }

        try { Set-EditorSourceBadge $slot $expected } catch {}
        $slot.Missing.Visible = $true
        $slot.Picture.Visible = $false
    } catch {}
}

# ===================== КОМПОЗИЦИЯ «HERO + ЛОГОТИП» (этапы 2-3: отрисовка и управление) =====================
# Картинка Hero рисуется по центру с сохранением пропорций, логотип - поверх. Положение/размер
# логотипа лежат в $editorState (LogoPosition / LogoWidthPct / LogoHeightPct), по умолчанию
# BottomLeft и 50/50 - как у Steam. Слот Logo скрыт, но по-прежнему хранит саму картинку логотипа.
# Отступ логотипа от края фона (доля ширины фона); сверить со Steam на этапе 7.
$script:EditorLogoPadFraction = 0.03

function Get-EditorComposeBackRect($heroImage, $clientSize) {
    # Прямоугольник фона внутри PictureBox: вписан по центру, пропорции сохранены.
    # Нет hero - рабочая заглушка с пропорциями hero Steam (3840x1240).
    $ar = 3840.0 / 1240.0
    try { if ($null -ne $heroImage -and $heroImage.Height -gt 0) { $ar = [double]$heroImage.Width / [double]$heroImage.Height } } catch {}
    $cw = [double]$clientSize.Width; $ch = [double]$clientSize.Height
    if ($cw -le 0 -or $ch -le 0) { return [System.Drawing.RectangleF]::Empty }
    $w = $cw; $h = $w / $ar
    if ($h -gt $ch) { $h = $ch; $w = $h * $ar }
    return [System.Drawing.RectangleF]::new([single](($cw - $w) / 2.0), [single](($ch - $h) / 2.0), [single]$w, [single]$h)
}

function Get-EditorLogoRect($logoImage, $backRect, $state) {
    # Реальные границы логотипа (в координатах PictureBox). Пустой прямоугольник - логотипа нет.
    # Эту же функцию использует проверка попадания клика на этапе 3.
    if ($null -eq $logoImage -or $logoImage.Width -le 0 -or $logoImage.Height -le 0 -or $backRect.Width -le 0) { return [System.Drawing.RectangleF]::Empty }
    $wp = 50.0; $hp = 50.0; $pos = 'BottomLeft'
    try { $wp = [double]$state.LogoWidthPct; $hp = [double]$state.LogoHeightPct; $pos = [string]$state.LogoPosition } catch {}
    $wp = [math]::Max(1.0, [math]::Min(100.0, $wp)); $hp = [math]::Max(1.0, [math]::Min(100.0, $hp))
    $bw = [double]$backRect.Width * $wp / 100.0; $bh = [double]$backRect.Height * $hp / 100.0
    $sc = [math]::Min($bw / [double]$logoImage.Width, $bh / [double]$logoImage.Height)
    $lw = [double]$logoImage.Width * $sc; $lh = [double]$logoImage.Height * $sc
    $pad = [double]$backRect.Width * $script:EditorLogoPadFraction
    $x = [double]$backRect.X + $pad
    if ($pos -match 'Center') { $x = [double]$backRect.X + ([double]$backRect.Width - $lw) / 2.0 }
    $y = [double]$backRect.Y + $pad
    if ($pos -like 'Bottom*') { $y = [double]$backRect.Y + [double]$backRect.Height - $pad - $lh }
    elseif ($pos -eq 'CenterCenter') { $y = [double]$backRect.Y + ([double]$backRect.Height - $lh) / 2.0 }
    return [System.Drawing.RectangleF]::new([single]$x, [single]$y, [single]$lw, [single]$lh)
}

# Положения логотипа, которые поддерживает Steam (в порядке перебора при «прилипании»).
$script:EditorLogoPositions = @('UpperLeft','UpperCenter','CenterCenter','BottomLeft','BottomCenter')
# Порог в пикселях, после которого нажатие на логотипе считается перетаскиванием, а не кликом.
$script:EditorLogoDragThreshold = 4
$script:EditorLogoScaleMin = 10
$script:EditorLogoScaleMax = 100
$script:EditorLogoScaleStep = 5

function Invoke-EditorControlClick($ctl) {
    # Вызывает уже подключённые обработчики Click элемента (выбор hero / логотипа), не дублируя их код.
    try {
        if ($null -eq $ctl) { return }
        $m = [System.Windows.Forms.Control].GetMethod('OnClick', [System.Reflection.BindingFlags]'NonPublic,Instance')
        if ($null -ne $m) { [void]$m.Invoke($ctl, @([System.EventArgs]::Empty)) }
    } catch {}
}

function Test-EditorComposeHidden($hs) {
    # Скрытая карточка (автодобавление ромов открывает её с Opacity = 0): композицию не рисуем и не обновляем,
    # это впустую тратит время очереди. Когда карточку показывают, композиция обновляется заново.
    try { $f = $hs.Picture.FindForm(); return ($null -ne $f -and [double]$f.Opacity -eq 0) } catch { return $false }
}

function Test-EditorComposeBusy($hs) {
    # Пока грузится фон или логотип, управление композицией заблокировано.
    try { if ($hs.IsLoading) { return $true } } catch {}
    try { if ($hs.ComposeLogo.IsLoading) { return $true } } catch {}
    return $false
}

function Get-EditorComposeGeometry($hs) {
    # Текущие прямоугольники композиции в координатах PictureBox: фон и логотип (пустой, если логотипа нет или он скрыт).
    $pb = $hs.Picture
    $hidden = $false
    try { $hidden = [bool]$hs.EditorState.LogoHidden } catch {}
    $logoImg = $null
    if (-not $hidden) { try { $logoImg = $hs.ComposeLogo.Picture.Image } catch {} }
    $back = Get-EditorComposeBackRect $pb.Image $pb.ClientSize
    $lr = [System.Drawing.RectangleF]::Empty
    if ($null -ne $logoImg -and $back.Width -gt 0) { $lr = Get-EditorLogoRect $logoImg $back $hs.EditorState }
    return [PSCustomObject]@{ Back = $back; Logo = $lr; LogoImage = $logoImg }
}

function Get-EditorLogoSnapPosition($logoImage, $back, $state, $dragRect) {
    # Ближайшая из пяти позиций Steam: сравниваются центры логотипа в каждой позиции и перетаскиваемого логотипа.
    $cx = [double]$dragRect.X + [double]$dragRect.Width / 2.0
    $cy = [double]$dragRect.Y + [double]$dragRect.Height / 2.0
    $best = [string]$state.LogoPosition
    $bestDist = [double]::MaxValue
    foreach ($pos in $script:EditorLogoPositions) {
        $tmp = [PSCustomObject]@{ LogoWidthPct = $state.LogoWidthPct; LogoHeightPct = $state.LogoHeightPct; LogoPosition = $pos }
        $r = Get-EditorLogoRect $logoImage $back $tmp
        if ($r.Width -le 0) { continue }
        $dx = ([double]$r.X + [double]$r.Width / 2.0) - $cx
        $dy = ([double]$r.Y + [double]$r.Height / 2.0) - $cy
        $d = $dx * $dx + $dy * $dy
        if ($d -lt $bestDist) { $bestDist = $d; $best = $pos }
    }
    return $best
}

function Set-EditorLogoScale($hs, [int]$percent) {
    # Масштаб логотипа: ширина и высота рамки в процентах от фона меняются вместе.
    $v = [math]::Max($script:EditorLogoScaleMin, [math]::Min($script:EditorLogoScaleMax, $percent))
    $st = $hs.EditorState
    $st.LogoWidthPct = $v
    $st.LogoHeightPct = $v
    try { if ($hs.Slider.Value -ne $v) { $hs.Slider.Value = $v } } catch {}
    Update-EditorComposeScaleLabel $hs
    $hs.Picture.Invalidate()
}

function New-EditorComposeHeaderButton([string]$text, $tag) {
    $btn = New-Object System.Windows.Forms.Button
    $font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $w = 90
    try { $w = [System.Windows.Forms.TextRenderer]::MeasureText($text, $font).Width + 20 } catch {}
    $btn.Font = $font
    $btn.Size = New-Object System.Drawing.Size($w, 24)
    $btn.FlatStyle = 'Flat'
    $btn.FlatAppearance.BorderColor = $steamUi.Border
    $btn.FlatAppearance.MouseOverBackColor = $steamUi.Selected
    $btn.BackColor = $steamUi.Panel
    $btn.ForeColor = $steamUi.Text
    $btn.Padding = New-Object System.Windows.Forms.Padding(0)
    $btn.Text = $text
    $btn.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btn.TabStop = $false
    $btn.Tag = $tag
    return $btn
}

function Set-EditorComposeTip($hs, [string]$kind) {
    # Подсказка над превью зависит от того, что под курсором (логотип / фон / идёт загрузка).
    # Текст переустанавливается только при смене области, иначе ToolTip мерцает.
    try {
        $ui = $hs.ComposeUi
        if ($null -eq $ui -or [string]$ui.TipKind -eq $kind) { return }
        $ui.TipKind = $kind
        $key = 'logo_tip_preview_bg'
        if ($kind -eq 'logo') { $key = 'logo_tip_preview_logo' } elseif ($kind -eq 'busy') { $key = 'logo_tip_busy' }
        $text = T $key
        $hs.EyeTip.SetToolTip($hs.Picture, $text)
        $hs.EyeTip.SetToolTip($hs.Missing, $text)
    } catch {}
}

function Update-EditorComposeScaleLabel($hs) {
    # Подпись у ползунка: «Размер логотипа: N%». Приглушена, пока ползунок недоступен.
    try {
        $v = 50
        try { $v = [int][math]::Round([double]$hs.EditorState.LogoWidthPct) } catch {}
        $hs.ScaleLabel.Text = (T 'logo_scale_label' @($v))
        if ($hs.Slider.Enabled) { $hs.ScaleLabel.ForeColor = $steamUi.Text } else { $hs.ScaleLabel.ForeColor = $steamUi.Muted }
    } catch {}
}

function New-EditorScaledBitmap($img, [int]$w, [int]$h) {
    # Копия картинки нужного размера в формате PArgb: такую картинку GDI+ рисует без пересчёта пикселей.
    $bmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format32bppPArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $ia = New-Object System.Drawing.Imaging.ImageAttributes
    try {
        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
        $ia.SetWrapMode([System.Drawing.Drawing2D.WrapMode]::TileFlipXY)
        $g.DrawImage($img, (New-Object System.Drawing.Rectangle(0, 0, $w, $h)), 0, 0, [int]$img.Width, [int]$img.Height, [System.Drawing.GraphicsUnit]::Pixel, $ia)
    } finally { $ia.Dispose(); $g.Dispose() }
    return $bmp
}

function Get-EditorComposeBitmap($ui, [string]$slot, $img, [int]$w, [int]$h) {
    # Кэш для Paint: тяжёлое бикубическое масштабирование делается один раз на (картинка, размер),
    # а при перетаскивании рисуется готовый битмап 1:1. Большие исходники (логотипы SGDB бывают 2-3 тыс. px)
    # один раз уменьшаются до промежуточной копии <= 1024 px, с неё же пересчитывается масштаб колесом/ползунком.
    if ($null -eq $img -or $w -le 0 -or $h -le 0) { return $null }
    $c = $ui.Cache[$slot]
    if ($null -eq $c) { $c = @{ Src = $null; W = 0; H = 0; Bmp = $null; Proxy = $null }; $ui.Cache[$slot] = $c }
    if ([object]::ReferenceEquals($c.Src, $img) -and $c.W -eq $w -and $c.H -eq $h -and $null -ne $c.Bmp) { return $c.Bmp }
    if (-not [object]::ReferenceEquals($c.Src, $img)) {
        if ($null -ne $c.Proxy) { try { $c.Proxy.Dispose() } catch {}; $c.Proxy = $null }
        $c.Src = $img
        $long = [math]::Max([int]$img.Width, [int]$img.Height)
        if ($long -gt 1024) {
            $k = 1024.0 / $long
            $c.Proxy = New-EditorScaledBitmap $img ([math]::Max(1, [int][math]::Round($img.Width * $k))) ([math]::Max(1, [int][math]::Round($img.Height * $k)))
        }
    }
    $from = $img
    if ($null -ne $c.Proxy) { $from = $c.Proxy }
    if ($null -ne $c.Bmp) { try { $c.Bmp.Dispose() } catch {} }
    $c.Bmp = New-EditorScaledBitmap $from $w $h
    $c.W = $w; $c.H = $h
    return $c.Bmp
}

function Update-EditorComposeView($slot) {
    # Вызывается после смены картинки/состояния hero или logo (и начала/конца загрузки): переключает заглушку,
    # глаз, кнопки и ползунок и перерисовывает превью.
    try {
        if ($null -eq $slot) { return }
        $hero = $null
        if ($null -ne $slot.PSObject.Properties['ComposeLogo']) { $hero = $slot }
        elseif ($null -ne $slot.PSObject.Properties['ComposeHero']) { $hero = $slot.ComposeHero }
        if ($null -eq $hero) { return }
        if (Test-EditorComposeHidden $hero) { return }
        $logo = $hero.ComposeLogo
        $hasHero = ($null -ne $hero.Picture.Image)
        $hasLogo = ($null -ne $logo -and $null -ne $logo.Picture.Image)
        if ($hasHero -or $hasLogo) {
            # Есть что показывать: обычную заглушку «нет обложки» убираем, композиция рисуется сама.
            $hero.Missing.Visible = $false
            $hero.Picture.Visible = $true
        }
        elseif (-not $hero.IsLoading -and $null -ne $hero.Missing.Image) {
            # Нет ни фона, ни логотипа: обычная заглушка источника.
            $hero.Missing.Visible = $true
            $hero.Picture.Visible = $false
        }
        $busy = Test-EditorComposeBusy $hero
        if ($busy) { Set-EditorComposeTip $hero 'busy' } elseif ([string]$hero.ComposeUi.TipKind -eq 'busy') { Set-EditorComposeTip $hero 'bg' }
        $hidden = $false
        try { $hidden = [bool]$hero.EditorState.LogoHidden } catch {}
        $eye = $null
        try { $eye = $hero.EyeButton } catch {}
        if ($null -ne $eye) {
            $eye.Visible = $hasLogo
            $eye.Enabled = -not $busy
            $eye.Text = [string][char]$(if ($hidden) { 0xED1A } else { 0xE7B3 })
            try { $hero.EyeTip.SetToolTip($eye, (T $(if ($hidden) { 'logo_eye_show' } else { 'logo_eye_hide' }))) } catch {}
            if ($hasLogo) { $eye.BringToFront() }
        }
        try { $hero.BtnBackground.Enabled = -not $busy } catch {}
        try { $hero.BtnLogo.Enabled = -not $busy } catch {}
        try {
            $sl = $hero.Slider
            if ($null -ne $sl) {
                $v = 50
                try { $v = [int][math]::Round([double]$hero.EditorState.LogoWidthPct) } catch {}
                $v = [math]::Max($script:EditorLogoScaleMin, [math]::Min($script:EditorLogoScaleMax, $v))
                if ($sl.Value -ne $v) { $sl.Value = $v }
                $sl.Enabled = ($hasLogo -and -not $hidden -and -not $busy)
            }
        } catch {}
        Update-EditorComposeScaleLabel $hero
        if ($busy) { try { $hero.Picture.Cursor = [System.Windows.Forms.Cursors]::Default } catch {} }
        else { try { $hero.Picture.Cursor = [System.Windows.Forms.Cursors]::Hand } catch {} }
        $hero.Picture.Invalidate()
    } catch {}
}

function Initialize-EditorCompose($heroSlot, $logoSlot) {
    # Подключает к слоту Hero отрисовку композиции и управление: клики, перетаскивание, масштаб, «глаз»,
    # кнопки смены фона/логотипа в заголовке и ползунок масштаба под превью.
    if ($null -eq $heroSlot -or $null -eq $logoSlot) { return }
    $heroSlot | Add-Member -NotePropertyName ComposeLogo -NotePropertyValue $logoSlot -Force
    $logoSlot | Add-Member -NotePropertyName ComposeHero -NotePropertyValue $heroSlot -Force
    $heroSlot | Add-Member -NotePropertyName ComposeUi -NotePropertyValue ([hashtable]@{
        Down = $false; HitLogo = $false; Dragging = $false; TipKind = ''; Cache = @{}
        StartX = 0; StartY = 0; GrabX = 0.0; GrabY = 0.0
        DragRect = [System.Drawing.RectangleF]::Empty
    }) -Force
    $heroSlot.Picture.Tag = $heroSlot
    # У фона и логотипа источники независимы (например, hero из Steam, логотип из SteamGridDB), поэтому показываем два значка:
    # значок скрытого слота Logo переносим на панель Hero, левее значка фона. Вся прежняя логика значков работает как раньше.
    try {
        $heroSlot | Add-Member -NotePropertyName BadgeTipPrefix -NotePropertyValue (T 'logo_src_bg') -Force
        $logoSlot | Add-Member -NotePropertyName BadgeTipPrefix -NotePropertyValue (T 'logo_src_logo') -Force
        $logoBadge = $logoSlot.SourceBadge
        $logoSlot.Panel.Controls.Remove($logoBadge)
        $heroSlot.Panel.Controls.Add($logoBadge)
        $logoBadge.Location = New-Object System.Drawing.Point(([int]$heroSlot.Panel.Width - 58), 7)
        $logoBadge.BringToFront()
    } catch {}
    # Двойная буферизация убирает мерцание при перетаскивании (свойство DoubleBuffered у PictureBox закрытое).
    try { [System.Windows.Forms.Control].GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'NonPublic,Instance').SetValue($heroSlot.Picture, $true, $null) } catch {}
    $heroSlot.Picture.Add_Disposed({
        try {
            $hs = $this.Tag
            foreach ($ck in @($hs.ComposeUi.Cache.Keys)) {
                $c = $hs.ComposeUi.Cache[$ck]
                try { if ($null -ne $c.Bmp) { $c.Bmp.Dispose() } } catch {}
                try { if ($null -ne $c.Proxy) { $c.Proxy.Dispose() } } catch {}
            }
        } catch {}
    })

    # Превью немного ниже по высоте: под ним остаётся свободная полоса для ползунка масштаба.
    $picH = 180
    # Нижняя строка (подпись, «глаз», ползунок) - в одну линию по центру свободной полосы между низом превью и нижним краем слота.
    $scaleLblW = 170
    # Под превью две строки: ползунок масштаба (28 px) и ниже галочка «по умолчанию» (22 px).
    $rowY = [int](35 + $picH + 4)
    $heroSlot.Picture.Size = New-Object System.Drawing.Size([int]$heroSlot.Picture.Width, $picH)
    $heroSlot.Missing.Size = New-Object System.Drawing.Size([int]$heroSlot.Missing.Width, $picH)

    $heroSlot.Picture.Add_Paint({
        param($sender, $e)
        try {
            $hs = $sender.Tag
            if ($null -eq $hs) { return }
            if (Test-EditorComposeHidden $hs) { return }
            $g = $e.Graphics
            $bgBrush = New-Object System.Drawing.SolidBrush($sender.BackColor)
            try { $g.FillRectangle($bgBrush, $sender.ClientRectangle) } finally { $bgBrush.Dispose() }
            $heroImg = $sender.Image
            $logoImg = $null
            $hidden = $false
            try { $hidden = [bool]$hs.EditorState.LogoHidden } catch {}
            if (-not $hidden) { $logoImg = $hs.ComposeLogo.Picture.Image }
            if ($null -eq $heroImg -and $null -eq $logoImg) { return }
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $back = Get-EditorComposeBackRect $heroImg $sender.ClientSize
            if ($back.Width -le 0) { return }
            $ui = $hs.ComposeUi
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::Default
            if ($null -ne $heroImg) {
                $bx = [int][math]::Round($back.X); $by = [int][math]::Round($back.Y); $bw = [int][math]::Round($back.Width); $bh = [int][math]::Round($back.Height)
                $hb = Get-EditorComposeBitmap $ui 'Hero' $heroImg $bw $bh
                if ($null -ne $hb) { $g.DrawImage($hb, $bx, $by, $bw, $bh) }
            }
            else {
                $stubBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255, 18, 22, 29))
                try { $g.FillRectangle($stubBrush, $back) } finally { $stubBrush.Dispose() }
            }
            if ($null -ne $logoImg) {
                $lr = Get-EditorLogoRect $logoImg $back $hs.EditorState
                # Во время перетаскивания логотип рисуется там, где его держит курсор.
                if ($null -ne $ui -and $ui.Dragging -and $ui.DragRect.Width -gt 0) { $lr = $ui.DragRect }
                if ($lr.Width -gt 0) {
                    $lw = [math]::Max(1, [int][math]::Round($lr.Width)); $lh = [math]::Max(1, [int][math]::Round($lr.Height))
                    $lb = Get-EditorComposeBitmap $ui 'Logo' $logoImg $lw $lh
                    if ($null -ne $lb) { $g.DrawImage($lb, [int][math]::Round($lr.X), [int][math]::Round($lr.Y), $lw, $lh) }
                }
            }
        } catch {}
    })

    # --- Управление мышью: нажатие, перетаскивание с порогом, отпускание (клик), колесо ---
    $heroSlot.Picture.Add_MouseDown({
        param($sender, $e)
        try {
            $hs = $sender.Tag
            if ($null -eq $hs -or $e.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
            if (Test-EditorComposeBusy $hs) { return }
            $ui = $hs.ComposeUi
            $geo = Get-EditorComposeGeometry $hs
            $ui.Down = $true
            $ui.Dragging = $false
            $ui.StartX = [int]$e.X
            $ui.StartY = [int]$e.Y
            $ui.HitLogo = ($geo.Logo.Width -gt 0 -and $geo.Logo.Contains([single]$e.X, [single]$e.Y))
            $ui.GrabX = [double]$e.X - [double]$geo.Logo.X
            $ui.GrabY = [double]$e.Y - [double]$geo.Logo.Y
        } catch {}
    })

    $heroSlot.Picture.Add_MouseMove({
        param($sender, $e)
        try {
            $hs = $sender.Tag
            if ($null -eq $hs) { return }
            $ui = $hs.ComposeUi
            if (Test-EditorComposeBusy $hs) {
                $sender.Cursor = [System.Windows.Forms.Cursors]::Default
                Set-EditorComposeTip $hs 'busy'
                $ui.Down = $false; $ui.Dragging = $false; $ui.DragRect = [System.Drawing.RectangleF]::Empty
                return
            }
            if ($ui.Down) {
                if (-not $ui.Dragging -and $ui.HitLogo) {
                    $thr = [int]$script:EditorLogoDragThreshold
                    if ([math]::Abs([int]$e.X - [int]$ui.StartX) -ge $thr -or [math]::Abs([int]$e.Y - [int]$ui.StartY) -ge $thr) { $ui.Dragging = $true }
                }
                if ($ui.Dragging) {
                    $geo = Get-EditorComposeGeometry $hs
                    if ($geo.Logo.Width -gt 0) {
                        $lw = [double]$geo.Logo.Width; $lh = [double]$geo.Logo.Height
                        $x = [double]$e.X - [double]$ui.GrabX
                        $y = [double]$e.Y - [double]$ui.GrabY
                        $x = [math]::Max([double]$geo.Back.X, [math]::Min([double]$geo.Back.X + [double]$geo.Back.Width - $lw, $x))
                        $y = [math]::Max([double]$geo.Back.Y, [math]::Min([double]$geo.Back.Y + [double]$geo.Back.Height - $lh, $y))
                        $prev = $ui.DragRect
                        if ($prev.Width -le 0) { $prev = $geo.Logo }
                        $ui.DragRect = [System.Drawing.RectangleF]::new([single]$x, [single]$y, [single]$lw, [single]$lh)
                        $sender.Cursor = [System.Windows.Forms.Cursors]::SizeAll
                        # Перерисовываем только объединение старого и нового положения логотипа, а не всё превью.
                        $dirty = [System.Drawing.RectangleF]::Union($prev, $ui.DragRect)
                        $sender.Invalidate([System.Drawing.Rectangle]::Ceiling([System.Drawing.RectangleF]::Inflate($dirty, 3, 3)))
                    }
                }
                return
            }
            $geo = Get-EditorComposeGeometry $hs
            if ($geo.Logo.Width -gt 0 -and $geo.Logo.Contains([single]$e.X, [single]$e.Y)) { $sender.Cursor = [System.Windows.Forms.Cursors]::SizeAll; Set-EditorComposeTip $hs 'logo' }
            else { $sender.Cursor = [System.Windows.Forms.Cursors]::Hand; Set-EditorComposeTip $hs 'bg' }
        } catch {}
    })

    $heroSlot.Picture.Add_MouseUp({
        param($sender, $e)
        try {
            $hs = $sender.Tag
            if ($null -eq $hs) { return }
            $ui = $hs.ComposeUi
            if (-not $ui.Down) { return }
            $wasDrag = [bool]$ui.Dragging
            $hit = [bool]$ui.HitLogo
            $dragRect = $ui.DragRect
            $ui.Down = $false; $ui.Dragging = $false; $ui.HitLogo = $false
            $ui.DragRect = [System.Drawing.RectangleF]::Empty
            if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Left) { $sender.Invalidate(); return }
            if ($wasDrag) {
                # Отпустили после перетаскивания: логотип прилипает к ближайшей из пяти позиций Steam.
                $geo = Get-EditorComposeGeometry $hs
                if ($null -ne $geo.LogoImage -and $geo.Back.Width -gt 0 -and $dragRect.Width -gt 0) {
                    $hs.EditorState.LogoPosition = (Get-EditorLogoSnapPosition $geo.LogoImage $geo.Back $hs.EditorState $dragRect)
                }
                $sender.Invalidate()
                return
            }
            $sender.Invalidate()
            if (Test-EditorComposeBusy $hs) { return }
            if (-not $sender.ClientRectangle.Contains([int]$e.X, [int]$e.Y)) { return }
            # Обычный клик: по логотипу - выбор логотипа, по фону - выбор hero (существующие обработчики слотов).
            if ($hit) { Invoke-EditorControlClick $hs.ComposeLogo.Picture }
            else { Invoke-EditorControlClick $hs.Missing }
        } catch {}
    })

    $heroSlot.Picture.Add_MouseWheel({
        param($sender, $e)
        try {
            $hs = $sender.Tag
            if ($null -eq $hs) { return }
            if (Test-EditorComposeBusy $hs) { return }
            $geo = Get-EditorComposeGeometry $hs
            if ($geo.Logo.Width -le 0 -or -not $geo.Logo.Contains([single]$e.X, [single]$e.Y)) { return }
            $cur = 50.0
            try { $cur = [double]$hs.EditorState.LogoWidthPct } catch {}
            $step = [int]$script:EditorLogoScaleStep
            if ($e.Delta -lt 0) { $step = -$step }
            Set-EditorLogoScale $hs ([int][math]::Round($cur) + $step)
            if ($e -is [System.Windows.Forms.HandledMouseEventArgs]) { $e.Handled = $true }
        } catch {}
    })

    # --- «Глаз» (показать/скрыть логотип на превью): стоит в полосе под превью, сразу перед началом шкалы масштаба ---
    $eye = New-Object System.Windows.Forms.Button
    $eye.Size = New-Object System.Drawing.Size(26, 24)
    $eye.Location = New-Object System.Drawing.Point((10 + $scaleLblW + 4), ($rowY + 2))
    $eye.FlatStyle = 'Flat'
    $eye.FlatAppearance.BorderColor = $steamUi.Border
    $eye.BackColor = $steamUi.Panel
    $eye.ForeColor = $steamUi.Text
    $eye.Font = New-Object System.Drawing.Font('Segoe MDL2 Assets', 10)
    $eye.Padding = New-Object System.Windows.Forms.Padding(0)
    $eye.Text = [string][char]0xE7B3
    $eye.Cursor = [System.Windows.Forms.Cursors]::Hand
    $eye.TabStop = $false
    $eye.Visible = $false
    $eye.Tag = $heroSlot
    $eye.Add_Click({
        try {
            $hs = $this.Tag
            if (Test-EditorComposeBusy $hs) { return }
            $st = $hs.EditorState
            $st.LogoHidden = -not [bool]$st.LogoHidden
            Update-EditorComposeView $hs
        } catch {}
    })
    $heroSlot.Panel.Controls.Add($eye)
    $eye.BringToFront()
    $heroSlot | Add-Member -NotePropertyName EyeButton -NotePropertyValue $eye -Force
    $heroSlot | Add-Member -NotePropertyName EyeTip -NotePropertyValue (New-Object System.Windows.Forms.ToolTip) -Force

    # --- Кнопки «Сменить логотип» / «Сменить фон» в заголовке слота (левее «глаза») ---
    $btnLogo = New-EditorComposeHeaderButton (T 'logo_btn_logo') $heroSlot
    $btnLogo.Add_Click({
        try {
            $hs = $this.Tag
            if (Test-EditorComposeBusy $hs) { return }
            Invoke-EditorControlClick $hs.ComposeLogo.Picture
        } catch {}
    })
    $btnBg = New-EditorComposeHeaderButton (T 'logo_btn_bg') $heroSlot
    $btnBg.Add_Click({
        try {
            $hs = $this.Tag
            if (Test-EditorComposeBusy $hs) { return }
            Invoke-EditorControlClick $hs.Missing
        } catch {}
    })
    # Порядок слева направо: [Сменить логотип] (значок логотипа) [Сменить фон] (значок фона) [правый край].
    # Значок стоит сразу после своей кнопки.
    $badgeLogoCtl = $logoSlot.SourceBadge
    $badgeHeroCtl = $heroSlot.SourceBadge
    $badgeHeroCtl.Location = New-Object System.Drawing.Point(([int]$heroSlot.Panel.Width - 10 - [int]$badgeHeroCtl.Width), 8)
    $btnBg.Location = New-Object System.Drawing.Point(([int]$badgeHeroCtl.Left - 4 - [int]$btnBg.Width), 7)
    $badgeLogoCtl.Location = New-Object System.Drawing.Point(([int]$btnBg.Left - 6 - [int]$badgeLogoCtl.Width), 8)
    $btnLogo.Location = New-Object System.Drawing.Point(([int]$badgeLogoCtl.Left - 4 - [int]$btnLogo.Width), 7)
    $heroSlot.Panel.Controls.Add($btnLogo)
    $heroSlot.Panel.Controls.Add($btnBg)
    $btnLogo.BringToFront(); $btnBg.BringToFront()
    try { $badgeHeroCtl.BringToFront(); $badgeLogoCtl.BringToFront() } catch {}
    $heroSlot | Add-Member -NotePropertyName BtnLogo -NotePropertyValue $btnLogo -Force
    $heroSlot | Add-Member -NotePropertyName BtnBackground -NotePropertyValue $btnBg -Force
    # Подпись слота не должна заезжать под кнопки.
    try { $heroSlot.Caption.AutoEllipsis = $true; $heroSlot.Caption.Width = [math]::Max(60, [int]$btnLogo.Left - 10 - 8) } catch {}
    # Подсказки на кнопках заголовка (тот же ToolTip, что у «глаза», задержки как у главного окна).
    try {
        $heroTip = $heroSlot.EyeTip
        $heroTip.AutoPopDelay = 8000; $heroTip.InitialDelay = 400; $heroTip.ReshowDelay = 200
        $heroTip.SetToolTip($btnBg, (T 'logo_tip_btn_bg'))
        $heroTip.SetToolTip($btnLogo, (T 'logo_tip_btn_logo'))
    } catch {}

    # --- Ползунок масштаба в свободной полосе под превью ---
    $tb = New-Object System.Windows.Forms.TrackBar
    $tb.AutoSize = $false
    $tb.Minimum = [int]$script:EditorLogoScaleMin
    $tb.Maximum = [int]$script:EditorLogoScaleMax
    $tb.SmallChange = [int]$script:EditorLogoScaleStep
    $tb.LargeChange = 10
    $tb.TickStyle = [System.Windows.Forms.TickStyle]::None
    $scaleLblW = 170
    $lblScale = New-Object System.Windows.Forms.Label
    $lblScale.AutoSize = $false
    $lblScale.AutoEllipsis = $true
    $lblScale.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $lblScale.ForeColor = $steamUi.Muted
    $lblScale.BackColor = [System.Drawing.Color]::Transparent
    $lblScale.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $lblScale.Location = New-Object System.Drawing.Point(10, ($rowY + 2))
    $lblScale.Size = New-Object System.Drawing.Size($scaleLblW, 24)
    $heroSlot.Panel.Controls.Add($lblScale)
    $heroSlot | Add-Member -NotePropertyName ScaleLabel -NotePropertyValue $lblScale -Force
    # Линия TrackBar рисуется выше середины его высоты, поэтому ползунок опущен на 4 px, чтобы линия шла по центру кнопки и подписи.
    $tb.Location = New-Object System.Drawing.Point((10 + $scaleLblW + 4 + 26 + 4), ($rowY + 4))
    $tb.Size = New-Object System.Drawing.Size(([int]$heroSlot.Panel.Width - 10 - (10 + $scaleLblW + 4 + 26 + 4)), 28)
    $tb.BackColor = $heroSlot.Panel.BackColor
    $tb.Value = 50
    $tb.TabStop = $false
    $tb.Enabled = $false
    $tb.Tag = $heroSlot
    $tb.Add_Scroll({
        try {
            $hs = $this.Tag
            if (Test-EditorComposeBusy $hs) { return }
            $v = [int]$this.Value
            $st = $hs.EditorState
            $st.LogoWidthPct = $v
            $st.LogoHeightPct = $v
            Update-EditorComposeScaleLabel $hs
            $hs.Picture.Invalidate()
        } catch {}
    })
    $heroSlot.Panel.Controls.Add($tb)
    $heroSlot | Add-Member -NotePropertyName Slider -NotePropertyValue $tb -Force

    # --- Галочка «по умолчанию» под шкалой масштаба: положение и размер логотипа для всех карточек, ромов и автоимпорта ---
    # Рисуется так же, как галочки в остальных окнах программы (квадрат 14x14, Accent с белой птичкой).
    $chkDef = New-Object System.Windows.Forms.CheckBox
    $chkDef.Text = (T 'logo_chk_default')
    $chkDef.AutoSize = $false
    $chkDef.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $chkDef.UseVisualStyleBackColor = $false
    $chkDef.BackColor = $heroSlot.Panel.BackColor
    $chkDef.ForeColor = $steamUi.Text
    $chkDef.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $chkDef.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $chkDef.FlatAppearance.BorderSize = 0
    $chkDef.Cursor = [System.Windows.Forms.Cursors]::Hand
    $chkDef.TabStop = $false
    $chkDef.Location = New-Object System.Drawing.Point(10, ($rowY + 30))
    $chkDef.Size = New-Object System.Drawing.Size(([int]$heroSlot.Panel.Width - 20), 22)
    $chkDef.Tag = $heroSlot
    $chkDef.Add_MouseEnter({ param($s, $e) $s.Invalidate() })
    $chkDef.Add_MouseLeave({ param($s, $e) $s.Invalidate() })
    $chkDef.Add_Paint({
        param($s, $pe)
        $g = $pe.Graphics
        $bgBrush = New-Object System.Drawing.SolidBrush($s.BackColor)
        $g.FillRectangle($bgBrush, $s.ClientRectangle)
        $bgBrush.Dispose()
        $boxRect = New-Object System.Drawing.Rectangle(0, [int](($s.ClientSize.Height - 14) / 2), 14, 14)
        if ($s.Checked) {
            $fillBrush = New-Object System.Drawing.SolidBrush($steamUi.Accent)
            $g.FillRectangle($fillBrush, $boxRect)
            $fillBrush.Dispose()
            $markPen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 1.6)
            $g.DrawLine($markPen, $boxRect.X + 3, $boxRect.Y + 7, $boxRect.X + 6, $boxRect.Y + 10)
            $g.DrawLine($markPen, $boxRect.X + 6, $boxRect.Y + 10, $boxRect.X + 11, $boxRect.Y + 3)
            $markPen.Dispose()
        } else {
            $hover = $false
            try { $hover = $s.ClientRectangle.Contains($s.PointToClient([System.Windows.Forms.Cursor]::Position)) } catch {}
            $borderColor = if ($hover) { [System.Drawing.Color]::White } else { $steamUi.Muted }
            $borderPen = New-Object System.Drawing.Pen($borderColor, 1.2)
            $g.DrawRectangle($borderPen, $boxRect)
            $borderPen.Dispose()
        }
        $textRect = New-Object System.Drawing.Rectangle(22, 0, [Math]::Max(10, $s.ClientSize.Width - 22), $s.ClientSize.Height)
        $flags = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis
        [System.Windows.Forms.TextRenderer]::DrawText($g, [string]$s.Text, $s.Font, $textRect, $s.ForeColor, $flags)
    }.GetNewClosure())
    $chkDef.Add_CheckedChanged({
        try {
            $hs = $this.Tag
            $hs.EditorState.LogoUseDefault = [bool]$this.Checked
        } catch {}
    })
    $heroSlot.Panel.Controls.Add($chkDef)
    $heroSlot | Add-Member -NotePropertyName ChkDefault -NotePropertyValue $chkDef -Force
    try { $heroSlot.EyeTip.SetToolTip($chkDef, (Get-WrappedTipText ([string](T 'logo_tip_default')))) } catch {}
    try {
        $heroSlot.EyeTip.SetToolTip($tb, (T 'logo_tip_slider'))
        $heroSlot.EyeTip.SetToolTip($lblScale, (T 'logo_tip_slider'))
    } catch {}
    Set-EditorComposeTip $heroSlot 'bg'
    try { Update-EditorComposeView $heroSlot } catch {}
}

function Set-EditorMissingState($slot, [bool]$missing) {
    Set-EditorMissingStateCore $slot $missing
    if ($script:LogoComposeEnabled) { try { Update-EditorComposeView $slot } catch {} }
}

function Set-EditorPreviewFile($slot, $filePath) {
    $r = Set-EditorPreviewFileCore $slot $filePath
    if ($script:LogoComposeEnabled) { try { Update-EditorComposeView $slot } catch {} }
    return $r
}

function Set-EditorPreviewFileCore($slot, $filePath) {
    try {
        if ($slot.Stream -ne $null) { $slot.Stream.Dispose(); $slot.Stream = $null }
        if ($slot.Picture.Image -ne $null) { $slot.Picture.Image.Dispose(); $slot.Picture.Image = $null }
    } catch {}
    $minBytes = 64
    if ([string]::IsNullOrWhiteSpace($filePath) -or -not (Test-Path $filePath) -or (Get-Item $filePath -ErrorAction SilentlyContinue).Length -lt $minBytes) {
        Set-EditorMissingState $slot $true
        return $false
    }
    try {
        $ext = ''
        try { $ext = [System.IO.Path]::GetExtension($filePath).ToLowerInvariant() } catch {}
        # Определяем реальный формат по сигнатуре байтов, а не только по
        # расширению файла: некоторые ссылки SteamGridDB отдают ICO под именем
        # без ".ico", и Image.FromStream на настоящих ICO-байтах вместо ошибки
        # часто рисует "сломанную"/шумную картинку вместо явного отказа.
        $isIcoContent = $false
        try {
            $head = New-Object byte[] 4
            $fs = [System.IO.File]::OpenRead($filePath)
            try { [void]$fs.Read($head, 0, 4) } finally { $fs.Dispose() }
            $isIcoContent = ($head[0] -eq 0 -and $head[1] -eq 0 -and $head[2] -eq 1 -and $head[3] -eq 0)
        } catch {}
        # ICO: Image.FromStream часто даёт чёрный/шумный кадр. Берём через
        # Icon.ToBitmap, явно запрашивая крупный размер — иначе конструктор
        # Icon без размера берёт маленькую системную иконку (обычно 32x32)
        # даже если в файле есть 256x256, и превью получается мыльным.
        if ($ext -eq '.ico' -or $isIcoContent) {
            $bmp = $null
            try {
                $bmp = Get-BitmapFromIcoFile $filePath
                if ($null -eq $bmp) { throw 'icon decode failed' }
                $slot.Stream = $null
                $slot.Picture.Image = $bmp
                $bmp = $null
                Set-EditorMissingState $slot $false
                return $true
            } finally {
                try { if ($null -ne $bmp) { $bmp.Dispose() } } catch {}
            }
        }
        $bytes = [System.IO.File]::ReadAllBytes($filePath)
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        $img = [System.Drawing.Image]::FromStream($ms)
        $slot.Stream = $ms
        $slot.Picture.Image = New-Object System.Drawing.Bitmap($img)
        $img.Dispose()
        Set-EditorMissingState $slot $false
        return $true
    } catch {
        Set-EditorMissingState $slot $true
        return $false
    }
}

function New-EditorCoverSlot($parent, [string]$title, [int]$x, [int]$y, [int]$w, [int]$h) {
    $group = New-Object System.Windows.Forms.Panel
    $group.Location = New-Object System.Drawing.Point($x, $y)
    $group.Size = New-Object System.Drawing.Size($w, $h)
    $group.BackColor = $steamUi.Panel2
    $group.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $parent.Controls.Add($group)

    $caption = New-Object System.Windows.Forms.Label
    $caption.Text = $title
    $caption.Location = New-Object System.Drawing.Point(10, 8)
    $caption.Size = New-Object System.Drawing.Size(([int]$w - 52), 22)
    $caption.Font = New-Object System.Drawing.Font("Segoe UI Semibold", 9)
    $caption.ForeColor = $steamUi.Text
    $group.Controls.Add($caption)

    $pb = New-Object System.Windows.Forms.PictureBox
    $pb.Location = New-Object System.Drawing.Point(10, 35)
    $pb.Size = New-Object System.Drawing.Size(([int]$w - 20), ([int]$h - 45))
    $pb.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $pb.BackColor = $steamUi.Input
    $group.Controls.Add($pb)

    $missing = New-Object System.Windows.Forms.PictureBox
    $missing.Location = New-Object System.Drawing.Point(10, 35)
    $missing.Size = New-Object System.Drawing.Size(([int]$w - 20), ([int]$h - 45))
    $missing.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $missing.BackColor = $steamUi.Input
    $missing.Visible = $false
    $missing.Cursor = [System.Windows.Forms.Cursors]::Hand
    $group.Controls.Add($missing)
    $missing.BringToFront()
    # БАГ-ФИКС: раньше крестик был виден сразу при открытии карточки игры —
    # ещё до того, как хоть что-то начали грузить. Из-за этого пользователь
    # видел последовательность "красный крест → анимация → миниатюра".
    # Теперь слот стартует пустым, а крест показывается ТОЛЬКО когда загрузка
    # закончилась и обложки в источнике действительно нет.
    $missing.Visible = $false

    # Маленький значок источника располагается В СТРОКЕ ЗАГОЛОВКА,
    # справа от названия миниатюры, а не поверх самой картинки.
    $sourceBadge = New-Object System.Windows.Forms.PictureBox
    $sourceBadge.Size = New-Object System.Drawing.Size(22,22)
    $sourceBadge.Location = New-Object System.Drawing.Point(([int]$w - 32), 7)
    $sourceBadge.BackColor = [System.Drawing.Color]::Transparent
    $sourceBadge.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $sourceBadge.Visible = $false
    $sourceBadge.Cursor = [System.Windows.Forms.Cursors]::Default
    $group.Controls.Add($sourceBadge)
    $sourceBadge.BringToFront()

    $pb.Cursor = [System.Windows.Forms.Cursors]::Hand
    return [PSCustomObject]@{
        Panel=$group
        Caption=$caption
        Picture=$pb
        Missing=$missing
        Stream=$null
        Loading=$null
        SourceBadge=$sourceBadge
        Source=$null
        ExpectedSource=$null
        # IsLoading — идёт ли прямо сейчас загрузка ИМЕННО этой миниатюры.
        # PendingMissing — "обложки нет", отложенный до конца загрузки вердикт.
        IsLoading=$false
        PendingMissing=$false
        SgdbItems=@()
        SgdbSelectedUrl=$null
    }
}



function Set-EditorSlotLoading($slot, [bool]$loading) {
    try {
        if ($null -eq $slot) { return }
        $slot.IsLoading = $loading
        if ($loading) {
            # Крест на время загрузки всегда прячем.
            try { $slot.Missing.Visible = $false; $slot.Picture.Visible = $true } catch {}
            if ($null -eq $slot.Loading) {
                $spin = New-CoverSpinner $slot.Picture $steamUi.Accent 56
                $spin.Dock = 'None'
                $spin.Location = $slot.Picture.Location
                $spin.Size = $slot.Picture.Size
                $spin.BackColor = $steamUi.Input
                $slot.Panel.Controls.Add($spin)
                $slot.Loading = $spin
            }
            Set-CoverSpinnerState $slot.Loading 'loading'
            $slot.Loading.BringToFront()
            # Кнопка EXE выступала за край миниатюры и торчала из-под спиннера
            # уголком — на время загрузки прячем её целиком.
            try { if ($null -ne $slot.PSObject.Properties['ExeButton'] -and $null -ne $slot.ExeButton) { $slot.ExeButton.Visible = $false } } catch {}
        } elseif ($null -ne $slot.Loading) {
            Set-CoverSpinnerState $slot.Loading 'done'
            try { if ($null -ne $slot.PSObject.Properties['ExeButton'] -and $null -ne $slot.ExeButton) { $slot.ExeButton.Visible = $true; $slot.ExeButton.BringToFront() } } catch {}
        }
        # Идёт загрузка - управление композицией блокируется, закончилась - разблокируется.
        if ($script:LogoComposeEnabled) { try { Update-EditorComposeView $slot } catch {} }
    } catch {}
}

function Start-EditorLoading($slots, $form) {
    # Пока карточка грузит обложки — качаем так, чтобы UI не замирал
    # и анимация реально крутилась (см. Invoke-UiPumpingDownload).
    $global:uiPumpDuringDownload = $true
    foreach($slot in $slots.Values) {
        Set-EditorSourceBadge $slot $null
        Set-EditorSlotLoading $slot $true
    }
    try {
        if ($null -ne $form) {
            if ($null -eq $form.Tag -or $null -eq $form.Tag.EditorLoadTimer) {
                $timer = New-Object System.Windows.Forms.Timer
                $timer.Interval = 70
                $timer.Tag = [PSCustomObject]@{Frame=0;Slots=$slots}
                $timer.Add_Tick({
                    try {
                        # БАГ-ФИКС: раньше здесь было $_.Sender — у PowerShell в
                        # обработчике события отправитель лежит в $this, а $_ —
                        # это EventArgs. Обращение к .Sender падало, исключение
                        # глушил catch, и анимация в карточке игры не работала
                        # вообще: символ так и висел неподвижно.
                        $t = $this
                        foreach($slot in $t.Tag.Slots.Values) {
                            if ($null -ne $slot.Loading) { Step-CoverSpinner $slot.Loading }
                        }
                    } catch {}
                })
                $form.Tag = [PSCustomObject]@{EditorLoadTimer=$timer;EditorSlots=$slots}
            }
            $form.Tag.EditorLoadTimer.Start()
        }
    } catch {}
}

function Stop-EditorLoading($slots, $form) {
    $global:uiPumpDuringDownload = $false
    foreach($slot in $slots.Values) {
        Set-EditorSlotLoading $slot $false
        # Загрузка закончилась — теперь показываем source-specific заглушку,
        # если обложки в источнике действительно не оказалось.
        Set-EditorMissingState $slot ([bool]$slot.PendingMissing)
    }
    # «Использовать иконки из EXE»: по умолчанию в любом источнике (Steam, SteamGridDB, нет сети
    # или App ID) иконка слота — из EXE игры. Прежняя иконка источника запоминается для кнопки EXE.
    try { if (-not (Test-EditorLoadCancelled)) { Invoke-EditorAutoExeIcon $slots } } catch {}
    try {
        if ($null -ne $form -and $null -ne $form.Tag -and $null -ne $form.Tag.EditorLoadTimer) {
            $form.Tag.EditorLoadTimer.Stop()
        }
    } catch {}
}


# ===================== ЯЗЫКИ ОБЛОЖЕК В КАРТОЧКЕ =====================
# Вместо одного переключателя показываем все реально найденные языки Steam
# отдельными компактными значками. Активный язык — синий, остальные найденные —
# приглушённые, в том же стиле, что и переключатель Steam / SteamGridDB.
# Сам контейнер сохраняет совместимость со старым кодом: .Tag.Lang содержит
# текущий выбранный язык и используется при сохранении метаданных обложек.
function Set-EditorCoverLangButton($panel, [string]$steamLang) {
    try {
        if ($null -eq $panel) { return }
        if ([string]::IsNullOrWhiteSpace($steamLang)) { $steamLang = 'english' }
        $info = Get-SteamLanguageInfo $steamLang
        if ($null -eq $panel.Tag) { $panel.Tag = [PSCustomObject]@{} }
        $panel.Tag.Lang = [string]$info.Steam
        foreach($child in @($panel.Controls)) {
            try {
                $isMore = $false
                try { $isMore = [bool]$child.Tag.IsMore } catch { $isMore = $false }
                if ($isMore) {
                    $overflow = @()
                    try { $overflow = @($child.Tag.Overflow) } catch {}
                    $active = ($overflow -contains [string]$info.Steam)
                } else {
                    $lang = [string]$child.Tag.Lang
                    $active = ($lang -eq [string]$info.Steam)
                }
                if($active){
                    $child.BackColor = $steamUi.Accent2
                    $child.ForeColor = [System.Drawing.Color]::White
                    $child.FlatAppearance.BorderColor = $steamUi.Accent2
                } else {
                    $child.BackColor = $steamUi.Panel
                    $child.ForeColor = $steamUi.Muted
                    $child.FlatAppearance.BorderColor = $steamUi.Border
                }
            } catch {}
        }
    } catch {}
}

function Set-EditorCoverLanguageButtons($panel, [object[]]$codes, [string]$activeLang) {
    try {
        if ($null -eq $panel) { return }
        $panel.Controls.Clear()
        $panel.Tag.Codes = @($codes)
        if([string]::IsNullOrWhiteSpace($activeLang)){ $activeLang = Get-SteamAssetLanguage }
        $panel.Tag.Lang = [string]$activeLang
        foreach($c in @($codes)) {
            $inf = Get-SteamLanguageInfo ([string]$c)
            $b = New-Object System.Windows.Forms.Button
            $b.Size = New-Object System.Drawing.Size(40,24)
            $b.Margin = New-Object System.Windows.Forms.Padding(2,2,2,2)
            $b.Padding = New-Object System.Windows.Forms.Padding(0)
            $b.Text = [string]$inf.Short
            $b.FlatStyle = 'Flat'
            $b.Font = New-Object System.Drawing.Font('Segoe UI Semibold',8.5)
            $b.Cursor = [System.Windows.Forms.Cursors]::Hand
            $b.TabStop = $false
            $b.Tag = [PSCustomObject]@{ Lang=[string]$inf.Steam; Tip=(New-Object System.Windows.Forms.ToolTip) }
            $b.Tag.Tip.SetToolTip($b, (T 'covlang_tip' @([string]$inf.Name)))
            if([string]$inf.Steam -eq [string]$activeLang){
                $b.BackColor=$steamUi.Accent2; $b.ForeColor=[System.Drawing.Color]::White; $b.FlatAppearance.BorderColor=$steamUi.Accent2
            } else {
                $b.BackColor=$steamUi.Panel; $b.ForeColor=$steamUi.Muted; $b.FlatAppearance.BorderColor=$steamUi.Border
            }
            [void]$panel.Controls.Add($b)
        }
        $panel.Visible = (@($codes).Count -gt 0)
    } catch {}
}

function Get-EditorCoverLanguagePanel($control) {
    try {
        if($null -eq $control){ return $null }
        return @($control.Controls.Find('EditorCoverLangButton', $true))[0]
    } catch { return $null }
}

# Перезагружает Steam-обложки карточки на выбранном языке. Заменяются только
# те миниатюры, что сейчас из Steam (или пустые): выбранное вручную из SteamGridDB
# не трогаем. Файл заменяется, только если новый скачался, — иначе остаётся
# текущая картинка. Возвращает, сколько миниатюр обновлено.
function Reload-EditorSteamCoversForLanguage($appId, $slots, $statusLabel, [string]$lang) {
    $langName = [string](Get-SteamLanguageInfo $lang).Name
    $form = $null
    try { $form = $statusLabel.FindForm() } catch {}

    $defs = @(
        @{ Name='Vertical';   File='temp_p.jpg';      Prop='Capsule'; Legacy='library_600x900.jpg' },
        @{ Name='Horizontal'; File='temp_header.jpg'; Prop='Header';  Legacy='header.jpg' },
        @{ Name='Hero';       File='temp_hero.jpg';   Prop='Hero';    Legacy='library_hero.jpg' },
        @{ Name='Logo';       File='temp_logo.png';   Prop='Logo';    Legacy='logo.png' }
    )
    $targets = [ordered]@{}
    $targetDefs = @()
    foreach ($d in $defs) {
        $slot = $slots[[string]$d.Name]
        if ($null -eq $slot) { continue }
        $src = ''
        try { $src = [string]$slot.Source } catch {}
        if ([string]::IsNullOrWhiteSpace($src) -or $src -eq 'Steam') { $targets[[string]$d.Name] = $slot; $targetDefs += $d }
    }
    if ($targetDefs.Count -eq 0) { $statusLabel.Text = (T 'covlang_all_sgdb'); return 0 }

    $statusLabel.Text = (T 'covlang_loading' @($langName))
    Start-EditorLoading $targets $form
    [System.Windows.Forms.Application]::DoEvents()
    $replaced = 0
    try {
        $pics = Get-SteamPicsAssetUrls $appId $lang
        foreach ($d in $targetDefs) {
            $slot = $slots[[string]$d.Name]
            $urls = @()
            if ($pics -ne $null) { $urls = @($pics.([string]$d.Prop)) }
            if ($urls.Count -eq 0 -and $lang -eq 'english') {
                # Английский — стандартная версия: если PICS недоступен, берём прямые ссылки.
                $urls = @(
                    "https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/$appId/$($d.Legacy)",
                    "https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/$appId/$($d.Legacy)"
                )
            }
            $dest = Join-Path $global:tempCovers ([string]$d.File)
            $tmp = $dest + '.new'
            Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
            $got = $false
            if ($urls.Count -gt 0) { $got = [bool](Save-FirstWorkingUrl $urls $tmp) }
            if ($got -and (Test-Path -LiteralPath $tmp)) {
                Move-Item -LiteralPath $tmp -Destination $dest -Force
                if (Set-EditorPreviewFile $slot $dest) { $replaced++ }
            }
            Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        }
    } catch {
    } finally {
        Stop-EditorLoading $targets $form
        foreach ($d in $targetDefs) {
            $slot = $slots[[string]$d.Name]
            try { if (-not [bool]$slot.PendingMissing) { Set-EditorSourceBadge $slot 'Steam' } } catch {}
        }
    }
    if ($replaced -gt 0) { $statusLabel.Text = (T 'covlang_done' @($langName, $replaced)) }
    else { $statusLabel.Text = (T 'covlang_fail' @($langName)) }
    return [int]$replaced
}

function Load-EditorSteamPreviews($appId, $slots, $statusLabel, [bool]$preferLocalIcon = $false) {
    foreach($s in $slots.Values){ try { $s.ExpectedSource = 'Steam' } catch {} }
    $form = $null
    try { $form = $statusLabel.FindForm() } catch {}
    if ([string]::IsNullOrWhiteSpace([string]$appId) -or [string]$appId -notmatch '^\d+$') {
        foreach($s in $slots.Values){ Set-EditorPreviewFile $s $null | Out-Null }
        Stop-EditorLoading $slots $form
        $statusLabel.Text = (T 'sl_no_appid')
        return
    }
    # Нет интернета — сразу заглушки, без единого сетевого вызова (см.
    # Test-InternetConnectivity), иначе карточка "зависает" на суммарном
    # таймауте всех последовательных запросов ниже. ВАЖНО: спиннер к этому
    # моменту уже может крутиться (Add_Shown карточки включает его ДО вызова
    # этой функции) — Set-EditorPreviewFile сам заглушку не покажет, пока
    # слот числится "загружающимся" (см. Set-EditorMissingState), поэтому
    # обязательно снимаем состояние загрузки через Stop-EditorLoading, а не
    # просто выходим из функции.
    if (-not (Test-InternetConnectivity)) {
        foreach($s in $slots.Values){ Set-EditorPreviewFile $s $null | Out-Null }
        Stop-EditorLoading $slots $form
        $statusLabel.Text = (T 'sl_no_internet')
        return
    }
    $statusLabel.Text = (T 'sl_steam_fetch' @($appId))
    $global:editorSteamLoadBusy = $true
    Start-EditorLoading $slots $form
    [System.Windows.Forms.Application]::DoEvents()
    try {
        # В редакторе Steam — единственный первичный источник. SGDB подключается
        # только отдельной кнопкой; при отсутствии ресурсов показываем
        # встроенную заглушку Steam.
        Download-CoversToTemp $appId $false
        # Пользователь переключил источник (или закрыл карточку), пока грузились
        # Steam-обложки. Результат Steam уже не нужен — не трогаем слоты и значки
        # источника, переключение выполнится в finally, когда загрузчик освободит UI.
        if (Test-EditorLoadCancelled) { return }
        if ($preferLocalIcon) {
            # Перезаписываем только иконку: остальные четыре ассета остаются
            # официальными Steam-ресурсами.
            Download-SteamIconToTemp $appId $true $true | Out-Null
            if (Test-EditorLoadCancelled) { return }
        }
        $ok = 0
        if (Set-EditorPreviewFile $slots.Vertical (Join-Path $global:tempCovers 'temp_p.jpg')) { Set-EditorSourceBadge $slots.Vertical 'Steam'; $ok++ }
        if (Set-EditorPreviewFile $slots.Horizontal (Join-Path $global:tempCovers 'temp_header.jpg')) { Set-EditorSourceBadge $slots.Horizontal 'Steam'; $ok++ }
        if (Set-EditorPreviewFile $slots.Hero (Join-Path $global:tempCovers 'temp_hero.jpg')) { Set-EditorSourceBadge $slots.Hero 'Steam'; $ok++ }
        if (Set-EditorPreviewFile $slots.Logo (Join-Path $global:tempCovers 'temp_logo.png')) { Set-EditorSourceBadge $slots.Logo 'Steam'; $ok++ }
        if ($null -ne $slots.Icon) {
            $iconPrev = Get-TempIconPath
            if ($null -ne $iconPrev -and (Set-EditorPreviewFile $slots.Icon $iconPrev)) { Set-EditorSourceBadge $slots.Icon 'Steam'; $ok++ }
        }
        $statusLabel.Text = (T 'sl_steam_found' @($ok))
        # Список языков заполняется самой карточкой после завершения загрузки.
        # Здесь только запоминаем найденные коды в панели, чтобы не создавать
        # кнопки без обработчиков во время первичной загрузки.
        try {
            $langPanel = Get-EditorCoverLanguagePanel $form
            if($null -ne $langPanel){
                $avail = @(Get-SteamPicsAvailableLanguages $appId)
                # Только реально доступные регионы. Регион из «Настроек» НЕ
                # подмешиваем в список, если у игры для него нет ассетов —
                # иначе светится РУ при английских обложках.
                if ($avail.Count -eq 0) { $avail = @('english') }
                $prefer = [string](Get-SteamAssetLanguage)
                if ($avail -contains $prefer) { $activeLang = $prefer }
                elseif ($avail -contains 'english') { $activeLang = 'english' }
                else { $activeLang = [string]$avail[0] }
                $langPanel.Tag.Codes = @($avail)
                $langPanel.Tag.Lang = [string]$activeLang
            }
        } catch {}
    } catch {
        if (-not (Test-EditorLoadCancelled)) {
            foreach($s in $slots.Values){ Set-EditorPreviewFile $s $null | Out-Null }
            $statusLabel.Text = (T 'sl_steam_fail' @([string]$_.Exception.Message))
        }
    } finally {
        $global:editorSteamLoadBusy = $false
        Stop-EditorLoading $slots $form
        # Выполняем отложенное переключение источника (если оно было запрошено
        # во время загрузки).
        Invoke-EditorPendingSwitch
    }
}

function Load-EditorSgdbPreviews($gameName, $steamAppId, $slots, $statusLabel, $onComplete = $null, [int]$sgdbGameId = 0) {
    foreach($s in $slots.Values){ try { $s.ExpectedSource = 'SteamGridDB' } catch {} }
    # FIX 8 — возвращаем проверенную логику из 2.6.4.
    # Ключевой момент: API SteamGridDB вызывается через Invoke-RestMethod,
    # как в старом рабочем picker'е. curl используется только для картинок.
    # Никаких отдельных curl-процессов для autocomplete/API, которые в v3
    # могли зависнуть на этапе "ищу…".
    $completed = $false
    $form = $null
    try { $form = $statusLabel.FindForm() } catch {}
    $global:editorSgdbLoadBusy = $true
    try {
        # Нет интернета — сразу заглушки, без обращения к SteamGridDB API.
        # ВАЖНО: спиннер к этому моменту уже может крутиться (Add_Shown
        # карточки включает его ДО вызова этой функции) — Stop-EditorLoading
        # обязателен, иначе заглушка так и не появится (см. Set-EditorMissingState).
        if (-not (Test-InternetConnectivity)) {
            foreach($s in $slots.Values){ Set-EditorPreviewFile $s $null | Out-Null }
            Stop-EditorLoading $slots $form
            $statusLabel.Text = (T 'sl_no_internet')
            return $false
        }
        $apiKey = [string](Ensure-SteamGridDbApiKey)
        if ([string]::IsNullOrWhiteSpace($apiKey)) {
            foreach($s in $slots.Values){ Set-EditorPreviewFile $s $null | Out-Null }
            Stop-EditorLoading $slots $form
            $statusLabel.Text = (T 'sl_sg_nokey')
            return $false
        }

        $name = [string]$gameName
        $appId = [string]$steamAppId
        if ([string]::IsNullOrWhiteSpace($name) -and [string]::IsNullOrWhiteSpace($appId) -and $sgdbGameId -le 0) {
            Stop-EditorLoading $slots $form
            $statusLabel.Text = (T 'sl_sg_need_name')
            return $false
        }

        $headers = @{ Authorization = "Bearer $apiKey" }
        $candidate = $null
        $assets = $null
        Start-EditorLoading $slots $form
        [System.Windows.Forms.Application]::DoEvents()
        # Во время DoEvents пользователь мог уже выбрать другой источник —
        # дальше не идём, переключение выполнится в finally.
        if (Test-EditorLoadCancelled) { return $false }

        # ------------------------------------------------------------
        # 0. Если передан конкретный SGDB Game ID (пользователь выбрал
        # определённый вариант из выпадающего списка названия) — берём
        # обложки ИМЕННО для него, без повторного нечёткого поиска по имени.
        # Без этой ветки повторный поиск по имени для похожих вариантов
        # (разные издания/моды с похожими названиями) почти всегда
        # возвращал один и тот же самый популярный результат — из-за этого
        # выбор другого варианта в списке визуально ничего не менял.
        # ------------------------------------------------------------
        if ($sgdbGameId -gt 0) {
            $statusLabel.Text = (T 'sl_sg_variants' @($name))
            [System.Windows.Forms.Application]::DoEvents()

            $assets = Get-SgdbAssetsForGame $sgdbGameId $headers
            if (Test-EditorLoadCancelled) { return $false }
            if ($assets -eq $null) {
                $statusLabel.Text = (T 'sl_sg_nocovers' @($name))
                return $false
            }
            $candidate = [PSCustomObject]@{ Id=$sgdbGameId; Name=$name }
        }
        # ------------------------------------------------------------
        # 1. Если App ID указан — НЕ ищем по названию.
        # Используем тот же прямой Steam App ID путь, который уже есть
        # в старом проекте.
        # ------------------------------------------------------------
        elseif ($appId -match '^\d+$') {
            $statusLabel.Text = (T 'sl_sg_by_id' @($appId))
            [System.Windows.Forms.Application]::DoEvents()

            $direct = Get-SteamGridDbAssetsBySteamAppId $appId
            if (Test-EditorLoadCancelled) { return $false }
            if ($direct -ne $null) {
                $assets = [PSCustomObject]@{
                    GridsVertical   = @($direct.Grids | Where-Object {
                        $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                        (($w -eq 600 -and $h -eq 900) -or ($w -eq 342 -and $h -eq 482) -or ($w -eq 660 -and $h -eq 930))
                    } | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                    GridsHorizontal = @($direct.Grids | Where-Object {
                        $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                        (($w -eq 920 -and $h -eq 430) -or ($w -eq 460 -and $h -eq 215))
                    } | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                    Heroes = @($direct.Heroes | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                    Logos  = @($direct.Logos  | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                    Icons  = @($direct.Icons  | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                }

                # Fallback по соотношению сторон — как в старой версии.
                if (@($assets.GridsVertical).Count -eq 0) {
                    $assets.GridsVertical = @($direct.Grids | Where-Object {
                        $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                        $h -gt 0 -and ($w/$h) -ge 0.55 -and ($w/$h) -le 0.78
                    } | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                }
                if (@($assets.GridsHorizontal).Count -eq 0) {
                    $assets.GridsHorizontal = @($direct.Grids | Where-Object {
                        $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                        $h -gt 0 -and ($w/$h) -ge 1.85 -and ($w/$h) -le 2.35
                    } | Sort-Object @{Expression={try{[double]$_.score}catch{0}};Descending=$true})
                }
            }
            if ($assets -eq $null) {
                $statusLabel.Text = (T 'sl_sg_id_none' @($appId))
                return $false
            }
            $candidate = [PSCustomObject]@{ Id=$appId; Name=$name }
        }
        else {
            # ------------------------------------------------------------
            # 2. App ID пуст — повторяем старый поиск по названию:
            # полный запрос + один fallback по первым значимым словам.
            # ------------------------------------------------------------
            $statusLabel.Text = (T 'sl_sg_searching' @($name))
            [System.Windows.Forms.Application]::DoEvents()

            # Та же обработка 401 (переполучить ключ и повторить один раз),
            # что была в рабочем 2.6.4 — теперь через общую обёртку
            # Invoke-SgdbApiRequest, а не продублированной вручную веткой.
            $searchReq = $null
            $searchQueries = @($name)

            $fallbackTokens = @([regex]::Matches($name,'[\p{L}\p{Nd}]+') | ForEach-Object { [string]$_.Value })
            if ($fallbackTokens.Count -gt 1) {
                $fallbackQuery = (($fallbackTokens | Select-Object -First ([Math]::Min(3,[int]$fallbackTokens.Count))) -join ' ')
                if (-not [string]::IsNullOrWhiteSpace($fallbackQuery) -and $fallbackQuery -ne $name) {
                    $searchQueries += $fallbackQuery
                }
            }

            foreach($searchQuery in $searchQueries) {
                if ($searchReq -ne $null -and $searchReq.Success) { break }

                $searchUrl = "https://www.steamgriddb.com/api/v2/search/autocomplete/" + [System.Uri]::EscapeDataString([string]$searchQuery)
                $searchReq = Invoke-SgdbApiRequest $searchUrl $headers 12
                [System.Windows.Forms.Application]::DoEvents()
                if (Test-EditorLoadCancelled) { return $false }
            }

            if ($searchReq -eq $null -or -not $searchReq.Success) {
                $statusLabel.Text = if($searchReq -ne $null -and $searchReq.ErrorMessage) { (T 'sl_sg_error' @([string]$searchReq.ErrorMessage)) } else { (T 'sl_sg_notfound') }
                return $false
            }

            $candidates = @($searchReq.Data | ForEach-Object {
                if ($null -eq $_) { return }
                $id=0
                try{$id=[int]$_.id}catch{}
                if($id -le 0){return}
                [PSCustomObject]@{
                    Id=$id
                    Name=[string]$_.name
                    Verified=$_.verified
                    Types=@($_.types)
                    MatchScore=Get-SgdbNameScore $name $_
                }
            } | Sort-Object MatchScore -Descending | Select-Object -First 12)

            if ($candidates.Count -eq 0) {
                $statusLabel.Text = (T 'sl_sg_nogames')
                return $false
            }

            # При наличии Steam-типа предпочитаем его — старое поведение.
            $steamMatches = @($candidates | Where-Object { @($_.Types) -contains 'steam' })
            if ($steamMatches.Count -gt 0) {
                $others = @($candidates | Where-Object { $_ -notin $steamMatches })
                $candidates = @($steamMatches + $others)
            }

            $candidate = $candidates[0]
            $statusLabel.Text = (T 'sl_sg_found_fetch' @([string]$candidate.Name))
            [System.Windows.Forms.Application]::DoEvents()

            $assets = Get-SgdbAssetsForGame $candidate.Id $headers
            if (Test-EditorLoadCancelled) { return $false }
            if ($assets -eq $null) {
                $statusLabel.Text = (T 'sl_sg_nocovers' @([string]$candidate.Name))
                return $false
            }
        }

        # ------------------------------------------------------------
        if (Test-EditorLoadCancelled) { return $false }
        # 3. Берём самый популярный вариант каждого типа.
        # Это ровно тот же принцип, который использовал старый picker:
        # сначала лучший score, а пользователь потом может заменить вариант
        # уже отдельным chooser'ом при необходимости.
        # ------------------------------------------------------------
        $vertical = @($assets.GridsVertical)
        $horizontal = @($assets.GridsHorizontal)
        $heroes = @($assets.Heroes)
        $logos = @($assets.Logos)
        $icons = @()
        try { $icons = @($assets.Icons) } catch { $icons = @() }

        # Сохраняем ВСЕ варианты, чтобы клик по миниатюре открывал
        # старый проверенный chooser, а не только первый выбранный результат.
        try { $slots.Vertical.SgdbItems = @($vertical) } catch {}
        try { $slots.Horizontal.SgdbItems = @($horizontal) } catch {}
        try { $slots.Hero.SgdbItems = @($heroes) } catch {}
        try { $slots.Logo.SgdbItems = @($logos) } catch {}
        try { if ($null -ne $slots.Icon) { $slots.Icon.SgdbItems = @($icons) } } catch {}

        $v = if($vertical.Count -gt 0){[string]$vertical[0].url}else{$null}
        $h = if($horizontal.Count -gt 0){[string]$horizontal[0].url}else{$null}
        $hero = if($heroes.Count -gt 0){[string]$heroes[0].url}else{$null}
        $logo = if($logos.Count -gt 0){[string]$logos[0].url}else{$null}
        $iconUrl = if($icons.Count -gt 0){[string]$icons[0].url}else{$null}

        $urls = @(
            [PSCustomObject]@{Key='Vertical';Url=$v;File=(Join-Path $global:tempCovers 'temp_p.jpg');Slot=$slots.Vertical},
            [PSCustomObject]@{Key='Horizontal';Url=$h;File=(Join-Path $global:tempCovers 'temp_header.jpg');Slot=$slots.Horizontal},
            [PSCustomObject]@{Key='Hero';Url=$hero;File=(Join-Path $global:tempCovers 'temp_hero.jpg');Slot=$slots.Hero},
            [PSCustomObject]@{Key='Logo';Url=$logo;File=(Join-Path $global:tempCovers 'temp_logo.png');Slot=$slots.Logo}
        )
        if ($null -ne $slots.Icon) {
            $iconFile = Join-Path $global:tempCovers 'temp_icon.png'
            try {
                if (-not [string]::IsNullOrWhiteSpace($iconUrl) -and $iconUrl -match '\.ico(\?|$)') {
                    $iconFile = Join-Path $global:tempCovers 'temp_icon.ico'
                } elseif (-not [string]::IsNullOrWhiteSpace($iconUrl) -and $iconUrl -match '\.jpe?g(\?|$)') {
                    $iconFile = Join-Path $global:tempCovers 'temp_icon.jpg'
                }
            } catch {}
            $urls += [PSCustomObject]@{Key='Icon';Url=$iconUrl;File=$iconFile;Slot=$slots.Icon}
        }

        # Сначала очищаем старые SGDB-временные картинки, чтобы старый результат
        # никогда не оставался на экране при новом поиске.
        foreach($u in $urls) {
            Remove-Item -LiteralPath $u.File -Force -ErrorAction SilentlyContinue
            # Иконка: удаляем ВСЕ варианты temp_icon.*. Иначе старая иконка Steam/EXE в
            # temp_icon.png перекрывает новую SGDB-иконку в .ico/.jpg (Get-TempIconPath
            # предпочитает png), и «возврат» с иконки EXE ставил бы не ту иконку.
            if ($u.Key -eq 'Icon') {
                foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
                    try { Remove-Item -LiteralPath (Join-Path $global:tempCovers $n) -Force -ErrorAction SilentlyContinue } catch {}
                }
            }
            Set-EditorPreviewFile $u.Slot $null | Out-Null
        }

        $loaded = 0
        foreach($u in $urls) {
            if (Test-EditorLoadCancelled) { return $false }
            if ([string]::IsNullOrWhiteSpace([string]$u.Url)) {
                [System.Windows.Forms.Application]::DoEvents()
                continue
            }

            $statusLabel.Text = (T 'sl_sg_loading' @(((T ('slot_' + ([string]$u.Key).ToLower())) -replace '^\d+\.\s*', '')))
            [System.Windows.Forms.Application]::DoEvents()

            # Используем старый проверенный Download-RemoteImage:
            # Invoke-WebRequest -> fallback curl, с таймаутом.
            if (Download-RemoteImage ([string]$u.Url) ([string]$u.File)) {
                # Источник переключили во время скачивания — старый результат
                # не должен попасть в слот.
                if (Test-EditorLoadCancelled) { return $false }
                $actualFile = if ($u.Key -eq 'Icon') { Repair-IconFileExtension ([string]$u.File) } else { [string]$u.File }
                if (Set-EditorPreviewFile $u.Slot $actualFile) {
                    Set-EditorSourceBadge $u.Slot 'SteamGridDB'
                    $loaded++
                }
            }
            [System.Windows.Forms.Application]::DoEvents()
        }
        if (Test-EditorLoadCancelled) { return $false }

        if ($loaded -gt 0) {
            $display = if($candidate -and $candidate.Name){[string]$candidate.Name}else{$name}
            $statusLabel.Text = (T 'sl_sg_done' @($loaded, $display))
        }
        else {
            $statusLabel.Text = (T 'sl_sg_imgfail')
        }

        $completed = $true
        return ($loaded -gt 0)
    }
    catch {
        if (-not (Test-EditorLoadCancelled)) {
            $statusLabel.Text = (T 'sl_sg_error' @([string]$_.Exception.Message))
        }
        return $false
    }
    finally {
        $global:editorSgdbLoadBusy = $false
        try { Stop-EditorLoading $slots $form } catch {}
        if ($onComplete) {
            try { & $onComplete } catch {}
        }
        # Отложенное переключение источника (клик по Steam во время загрузки SGDB).
        Invoke-EditorPendingSwitch
    }
}


# ===================== РУЧНЫЕ РЕЗЕРВНЫЕ КОПИИ shortcuts.vdf =====================
# Автоматические копии больше не создаются при изменении shortcuts.vdf.
# Пользователь создаёт копию явно из окна "Настройки". Копии лежат рядом
# с программой, чтобы их было легко найти и перенести вместе с Commander.
function Get-SteamShortcutsFiles {
    $files = New-Object System.Collections.ArrayList
    try {
        $userDataPath = Get-ConfiguredSteamUserDataPath
        if (-not (Test-Path $userDataPath)) { return @() }

        foreach ($f in (Get-ShortcutsVdfFiles $userDataPath)) {
            try {
                if ($f.Length -gt 0) { $files.Add($f) }
            } catch {}
        }
    } catch {}
    return @($files)
}

function Get-ManualShortcutBackupFiles {
    try {
        $dir = Get-BackupFolderPath
        if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { return @() }
        if (-not [string]::IsNullOrWhiteSpace([string]$global:steamUserId) -and [string]$global:steamUserId -match '^\d+$') {
            $filters = @(
                ("shortcuts_{0}_*.vdf.bak" -f [string]$global:steamUserId),
                ("auto_shortcuts_{0}_*.vdf.bak" -f [string]$global:steamUserId)
            )
        } else {
            $filters = @("shortcuts_*.vdf.bak", "auto_shortcuts_*.vdf.bak")
        }
        $files = foreach ($filter in $filters) {
            Get-ChildItem -LiteralPath $dir -Filter $filter -File -ErrorAction SilentlyContinue
        }
        return @($files | Sort-Object LastWriteTime -Descending)
    } catch {
        return @()
    }
}

function Resolve-ManualBackupTarget {
    param([System.IO.FileInfo]$BackupFile)
    try {
        if ($BackupFile -eq $null) { return $null }
        $name = [string]$BackupFile.Name
        $m = [System.Text.RegularExpressions.Regex]::Match(
            $name,
            '^(?:auto_)?shortcuts_(.+)_(\d{4}-\d{2}-\d{2}_\d{2}-\d{2})(?:_\d+)?\.vdf\.bak$'
        )
        if (-not $m.Success) { return $null }
        $accountId = [string]$m.Groups[1].Value

        # Восстановление всегда идёт в профиль, выбранный в настройках.
        $userDataPath = Get-ConfiguredSteamUserDataPath
        if (-not (Test-Path $userDataPath)) {
            try { [System.IO.Directory]::CreateDirectory([string]$userDataPath) | Out-Null } catch {}
        }
        if (-not [string]::IsNullOrWhiteSpace([string]$global:steamUserId) -and [string]$global:steamUserId -match '^\d+$') {
            return (Join-Path (Join-Path $userDataPath "config") "shortcuts.vdf")
        }

        $sourceFiles = @(Get-SteamShortcutsFiles)
        if ($sourceFiles.Count -eq 1) { return [string]$sourceFiles[0].FullName }
        return $null
    } catch {
        return $null
    }
}

function Create-ManualShortcutBackup {
    try {
        $sourceFiles = @(Get-SteamShortcutsFiles)
        if ($sourceFiles.Count -eq 0) {
            return @()
        }

        $backupDir = Get-BackupFolderPath
        [System.IO.Directory]::CreateDirectory([string]$backupDir) | Out-Null
        $stamp = (Get-Date).ToString("yyyy-MM-dd_HH-mm")
        $created = @()

        foreach ($source in $sourceFiles) {
            $accountId = [string]$global:steamUserId
            if ([string]::IsNullOrWhiteSpace($accountId) -or $accountId -notmatch '^\d+$') {
                try { $accountId = [System.IO.Path]::GetFileName($source.Directory.Parent.FullName) } catch {}
            }
            if ([string]::IsNullOrWhiteSpace($accountId) -or $accountId -notmatch '^\d+$') {
                $accountId = "steam"
            }

            # Имя содержит только дату и время до минут. Если несколько копий
            # создаются в одну минуту, добавляем индекс _2, _3, ... вместо секунд,
            # чтобы старые копии никогда не перезаписывались.
            $baseName = "shortcuts_{0}_{1}" -f $accountId, $stamp
            $target = Join-Path $backupDir ($baseName + ".vdf.bak")
            $duplicateIndex = 2
            while (Test-Path -LiteralPath $target) {
                $target = Join-Path $backupDir ("{0}_{1}.vdf.bak" -f $baseName, $duplicateIndex)
                $duplicateIndex++
            }
            try {
                [System.IO.File]::Copy([string]$source.FullName, [string]$target, $false)
                $created += [string]$target
            } catch {}
        }

        if ($created.Count -gt 0) {
            try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
        }
        return @($created)
    } catch {
        Show-AppMessageBox(
            $form,
            ((T 'bk_create_fail') + "`r`n" + [string]$_.Exception.Message),
            (T 'bk_title'),
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
        return @()
    }
}

function Get-AutoShortcutBackupAccountId([string]$SourceFile) {
    $accountId = [string]$global:steamUserId
    if (-not [string]::IsNullOrWhiteSpace($accountId) -and $accountId -match '^\d+$') { return $accountId }
    try {
        # $SourceFile = ...\userdata\<accountId>\config\shortcuts.vdf
        $accountId = [System.IO.Path]::GetFileName((Split-Path (Split-Path $SourceFile -Parent) -Parent))
    } catch { $accountId = '' }
    if ([string]::IsNullOrWhiteSpace($accountId) -or $accountId -notmatch '^\d+$') { $accountId = 'steam' }
    return $accountId
}

# Автоматическая резервная копия shortcuts.vdf, создаваемая перед КАЖДЫМ его
# изменением программой (в дополнение к бэкапам, создаваемым вручную кнопкой
# "Создать бэкап"). Копии кладутся в ту же папку, что и ручные бэкапы и
# используют схему имён "auto_shortcuts_<accountId>_...", поэтому они
# автоматически подхватываются Get-ManualShortcutBackupFiles и показываются
# в общем списке окна резервных копий, доступные для восстановления так же,
# как и ручные. Префикс "auto_" в имени отличает их от ручных копий.
# Хранится не более $global:autoBackupMaxCount авто-копий НА ПРОФИЛЬ — при
# превышении лимита самые старые авто-копии этого профиля удаляются.
$global:autoBackupMaxCount = 5

function Create-AutoShortcutBackup {
    param([string]$SourceFile)
    try {
        if ([string]::IsNullOrWhiteSpace($SourceFile) -or -not (Test-Path -LiteralPath $SourceFile)) { return $null }

        $backupDir = Get-BackupFolderPath
        [System.IO.Directory]::CreateDirectory([string]$backupDir) | Out-Null

        $accountId = Get-AutoShortcutBackupAccountId $SourceFile
        $stamp = (Get-Date).ToString("yyyy-MM-dd_HH-mm")

        # Формат имени "auto_shortcuts_<accountId>_<дата>" отличается от ручных
        # бэкапов только префиксом "auto_", поэтому фильтр списка
        # (Get-ManualShortcutBackupFiles) и регэксп восстановления
        # (Resolve-ManualBackupTarget) распознают и те, и другие.
        $baseName = "auto_shortcuts_{0}_{1}" -f $accountId, $stamp
        $target = Join-Path $backupDir ($baseName + ".vdf.bak")
        $duplicateIndex = 2
        while (Test-Path -LiteralPath $target) {
            $target = Join-Path $backupDir ("{0}_{1}.vdf.bak" -f $baseName, $duplicateIndex)
            $duplicateIndex++
        }

        [System.IO.File]::Copy([string]$SourceFile, [string]$target, $false)

        # Ротация по кругу: оставляем только $global:autoBackupMaxCount самых
        # свежих авто-копий для этого профиля, остальные удаляем.
        try {
            $autoFilter = "auto_shortcuts_{0}_*.vdf.bak" -f $accountId
            $existingAuto = @(Get-ChildItem -LiteralPath $backupDir -Filter $autoFilter -File -ErrorAction SilentlyContinue |
                Sort-Object LastWriteTime -Descending)
            if ($existingAuto.Count -gt $global:autoBackupMaxCount) {
                $existingAuto | Select-Object -Skip $global:autoBackupMaxCount | ForEach-Object {
                    try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue } catch {}
                }
            }
        } catch {}

        return $target
    } catch {
        return $null
    }
}

function Test-SteamGridDbApiKey([string]$apiKey) {
    # Возвращает результат Get-SgdbKeyCheckResult (Valid, NetworkError, Message
    # и дополнительно Kind/Severity/StatusCode) и обновляет глобальное состояние.
    $check = Get-SgdbKeyCheckResult $apiKey
    $global:steamGridDbApiKeyValid = [bool]$check.Valid
    $global:steamGridDbApiKeyCheck = $check
    return $check
}

function Set-ApiKeyValidationBadge($pictureBox, [string]$state, [string]$tip) {
    try {
        if ($null -eq $pictureBox) { return }
        if ($state -eq 'hidden') {
            $pictureBox.Visible = $false
            return
        }
        # Тот же значок, который уже используется в карточках:
        # зелёная галочка = true, красный ! = false.
        $bmp = Get-ConfidenceBadgeBitmap ($state -eq 'valid')
        try { if ($null -ne $pictureBox.Image) { $pictureBox.Image.Dispose() } } catch {}
        $pictureBox.Image = $bmp
        $pictureBox.Visible = ($null -ne $bmp)
        try {
            if ($null -eq $pictureBox.Tag -or $pictureBox.Tag -isnot [System.Windows.Forms.ToolTip]) {
                $tt = New-Object System.Windows.Forms.ToolTip
                $pictureBox.Tag = $tt
            }
            $pictureBox.Tag.SetToolTip($pictureBox, $tip)
        } catch {}
    } catch {}
}

# Ставит текст в LinkLabel и делает кликабельными адреса вида «домен/путь»
# (steamgriddb.com/profile/preferences/api и т.п.), где бы они ни стояли в тексте —
# поэтому одинаково работает для всех языков интерфейса. Ссылка открывается в
# браузере по умолчанию (см. обработчик LinkClicked у самого поля).
function Set-HintLinkText($label, [string]$text) {
    try {
        $label.Text = $text
        # Сбрасываем ссылку по умолчанию (весь текст) и ставим только найденные адреса.
        $label.Links.Clear()
        $urlPattern = '(?i)\b(?:[a-z0-9-]+\.)+[a-z]{2,}/[a-z0-9\-._~/%?=&#]*[a-z0-9\-_~/%=&#]'
        foreach ($m in [regex]::Matches($text, $urlPattern)) {
            [void]$label.Links.Add($m.Index, $m.Length, ('https://' + $m.Value))
        }
    } catch {}
}

function New-EmulatorProfileId {
    return [guid]::NewGuid().ToString('N').Substring(0, 8)
}

# Справочник платформ эмуляции и их типичных расширений ромов — используется
# только для подсказок в поле «Расширения» диалога эмулятора (Show-EmulatorEditDialog).
# Расширения — без точек, через запятую, в порядке, в каком они попадут в поле
# при выборе платформы из выпадающего списка.
function Get-EmulatorPlatformPresets {
    return @(
        [PSCustomObject]@{ Name = 'NES / Famicom';             Ext = 'nes,fds,unf,unif' }
        [PSCustomObject]@{ Name = 'SNES / Super Famicom';      Ext = 'sfc,smc,fig,swc' }
        [PSCustomObject]@{ Name = 'Nintendo 64';                Ext = 'n64,z64,v64' }
        [PSCustomObject]@{ Name = 'GameCube';                   Ext = 'iso,gcm,rvz,ciso' }
        [PSCustomObject]@{ Name = 'Wii';                        Ext = 'iso,wbfs,rvz,wia' }
        [PSCustomObject]@{ Name = 'Wii U';                      Ext = 'wud,wux,rpx' }
        [PSCustomObject]@{ Name = 'Nintendo Switch';            Ext = 'nsp,xci' }
        [PSCustomObject]@{ Name = 'Game Boy / Color';           Ext = 'gb,gbc' }
        [PSCustomObject]@{ Name = 'Game Boy Advance';           Ext = 'gba' }
        [PSCustomObject]@{ Name = 'Nintendo DS';                Ext = 'nds,dsi' }
        [PSCustomObject]@{ Name = 'Nintendo 3DS';               Ext = '3ds,cia,cxi' }
        [PSCustomObject]@{ Name = 'Virtual Boy';                Ext = 'vb' }
        [PSCustomObject]@{ Name = 'PlayStation (PS1)';          Ext = 'bin,cue,img,chd,pbp,ecm' }
        [PSCustomObject]@{ Name = 'PlayStation 2';              Ext = 'iso,bin,mdf,chd' }
        [PSCustomObject]@{ Name = 'PlayStation Portable';       Ext = 'iso,cso,pbp' }
        [PSCustomObject]@{ Name = 'PlayStation Vita';           Ext = 'vpk' }
        [PSCustomObject]@{ Name = 'Sega Genesis / Mega Drive';  Ext = 'md,gen,smd,bin' }
        [PSCustomObject]@{ Name = 'Sega Master System';         Ext = 'sms' }
        [PSCustomObject]@{ Name = 'Sega Game Gear';             Ext = 'gg' }
        [PSCustomObject]@{ Name = 'Sega 32X';                   Ext = '32x' }
        [PSCustomObject]@{ Name = 'Sega Saturn';                Ext = 'cue,bin,iso,chd,mds' }
        [PSCustomObject]@{ Name = 'Sega Dreamcast';             Ext = 'gdi,cdi,chd' }
        [PSCustomObject]@{ Name = 'Atari 2600';                 Ext = 'a26,bin' }
        [PSCustomObject]@{ Name = 'Atari 7800';                 Ext = 'a78' }
        [PSCustomObject]@{ Name = 'Atari Lynx';                 Ext = 'lnx' }
        [PSCustomObject]@{ Name = 'Atari Jaguar';               Ext = 'j64,jag' }
        [PSCustomObject]@{ Name = 'Neo Geo';                    Ext = 'neo,zip' }
        [PSCustomObject]@{ Name = 'Neo Geo Pocket';             Ext = 'ngp,ngc' }
        [PSCustomObject]@{ Name = 'PC Engine / TurboGrafx-16';  Ext = 'pce' }
        [PSCustomObject]@{ Name = 'WonderSwan';                 Ext = 'ws,wsc' }
        [PSCustomObject]@{ Name = 'Commodore 64';               Ext = 'd64,t64,prg,crt' }
        [PSCustomObject]@{ Name = 'Amiga';                      Ext = 'adf,lha,ipf' }
        [PSCustomObject]@{ Name = 'MSX';                        Ext = 'rom,dsk,cas' }
        [PSCustomObject]@{ Name = 'ColecoVision';               Ext = 'col' }
        [PSCustomObject]@{ Name = '3DO';                        Ext = 'iso,cue' }
        [PSCustomObject]@{ Name = 'Xbox';                       Ext = 'iso,xbe' }
        [PSCustomObject]@{ Name = 'Xbox 360';                   Ext = 'iso,xex,god' }
        [PSCustomObject]@{ Name = (T 'plat_arcade');                 Ext = 'zip,7z' }
    ) | Sort-Object Name
}

# Справочник известных эмуляторов — используется только для подсказок в поле
# «Название» диалога эмулятора (Show-EmulatorEditDialog): при выборе одного из
# них автоматически подставляются его платформы (через справочник выше —
# Get-EmulatorPlatformPresets, отсюда и ссылки по названию платформы в Platforms,
# а не дублирование списков расширений) и типовые аргументы запуска в
# полноэкранном режиме.
#   Platforms — массив названий платформ ИЗ Get-EmulatorPlatformPresets (Name),
#               в порядке, в каком их расширения попадут в поле «Расширения»;
#               пустой массив — эмулятор либо мультиплатформенный настолько,
#               что общий список расширений бессмысленен (RetroArch — зависит
#               от выбранного ядра), либо расширения ромов для его платформы
#               не укладываются в формат «через запятую, без точек» (RPCS3,
#               shadPS4 — игры хранятся папками/пакетами, а не одним файлом).
#   Args — аргумент(ы) командной строки для запуска в полноэкранном режиме,
#          {rom} — куда подставится путь к рому (как и в поле «Аргументы»
#          диалога). Пустая строка — у эмулятора нет официально
#          задокументированного ключа командной строки для полноэкранного
#          режима (переключается только внутри самого эмулятора/горячей
#          клавишей) — тогда при выборе эмулятора поле «Аргументы» не
#          трогается, чтобы не затирать то, что уже вписано вручную.
function Get-KnownEmulatorPresets {
    return @(
        [PSCustomObject]@{ Name = 'Fceux';              Platforms = @('NES / Famicom');                                                              Args = '' }
        [PSCustomObject]@{ Name = 'snes9x';              Platforms = @('SNES / Super Famicom');                                                       Args = '' }
        [PSCustomObject]@{ Name = 'Dolphin';             Platforms = @('GameCube', 'Wii');                                                            Args = '-b -e {rom}' }
        [PSCustomObject]@{ Name = 'Cemu';                Platforms = @('Wii U');                                                                      Args = '-f -g {rom}' }
        [PSCustomObject]@{ Name = 'Yuzu';                Platforms = @('Nintendo Switch');                                                            Args = '-f -g {rom}' }
        [PSCustomObject]@{ Name = 'Yuzu Early Access';   Platforms = @('Nintendo Switch');                                                            Args = '-f -g {rom}' }
        [PSCustomObject]@{ Name = 'Sudachi';             Platforms = @('Nintendo Switch');                                                            Args = '-f -g {rom}' }
        [PSCustomObject]@{ Name = 'Citron';              Platforms = @('Nintendo Switch');                                                            Args = '-f -g {rom}' }
        [PSCustomObject]@{ Name = 'Eden';                Platforms = @('Nintendo Switch');                                                            Args = '-f -g {rom}' }
        [PSCustomObject]@{ Name = 'Ryujinx';             Platforms = @('Nintendo Switch');                                                            Args = '' }
        [PSCustomObject]@{ Name = 'Ryubing';             Platforms = @('Nintendo Switch');                                                            Args = '' }
        [PSCustomObject]@{ Name = 'ePSXe';               Platforms = @('PlayStation (PS1)');                                                          Args = '' }
        [PSCustomObject]@{ Name = 'PCSX2';               Platforms = @('PlayStation 2');                                                               Args = '-fullscreen -batch -- {rom}' }
        [PSCustomObject]@{ Name = 'RPCS3';               Platforms = @();                                                                              Args = '' }
        [PSCustomObject]@{ Name = 'shadPS4';             Platforms = @();                                                                              Args = '' }
        [PSCustomObject]@{ Name = 'Redream';             Platforms = @('Sega Dreamcast');                                                             Args = '' }
        [PSCustomObject]@{ Name = 'Flycast';             Platforms = @('Sega Dreamcast');                                                             Args = '' }
        [PSCustomObject]@{ Name = 'Fusion';              Platforms = @('Sega Genesis / Mega Drive', 'Sega Master System', 'Sega Game Gear');           Args = '' }
        [PSCustomObject]@{ Name = 'Xenia';               Platforms = @('Xbox 360');                                                                    Args = '' }
        [PSCustomObject]@{ Name = 'RetroArch';           Platforms = @();                                                                              Args = '-f {rom}' }
    ) | Sort-Object Name
}

# Окно «Поддержать автора»: ссылки на донат-платформы, адреса USDT с кнопкой
# «Копировать» и ссылка на исходный код. Ссылки и адреса — в $global:supportLinks /
# $global:supportUsdt / $global:appRepoUrl (начало скрипта).
function Add-SupportCopyRow ($dlg, [int]$y, [string]$network, [string]$address) {
    $lblNet = New-Object System.Windows.Forms.Label
    $lblNet.Text = $network
    $lblNet.Location = New-Object System.Drawing.Point(20, ($y + 3))
    $lblNet.Size = New-Object System.Drawing.Size(60, 22)
    $lblNet.ForeColor = $steamUi.Muted
    $lblNet.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $dlg.Controls.Add($lblNet)

    $txtAddr = New-Object System.Windows.Forms.TextBox
    $txtAddr.Text = $address
    $txtAddr.ReadOnly = $true
    $txtAddr.Location = New-Object System.Drawing.Point(84, $y)
    $txtAddr.Size = New-Object System.Drawing.Size(316, 26)
    $txtAddr.BackColor = $steamUi.Input
    $txtAddr.ForeColor = $steamUi.Text
    $txtAddr.BorderStyle = 'FixedSingle'
    $txtAddr.Font = New-Object System.Drawing.Font('Consolas', 9)
    $txtAddr.Add_Enter({ param($s, $e) try { $s.SelectAll() } catch {} })
    $dlg.Controls.Add($txtAddr)

    $copyText = (T 'support_copy')
    $doneText = (T 'support_copied')
    $btnCopy = New-Object System.Windows.Forms.Button
    $btnCopy.Text = $copyText
    $btnCopy.Location = New-Object System.Drawing.Point(408, ($y - 1))
    $btnCopy.Size = New-Object System.Drawing.Size(92, 28)
    $btnCopy.FlatStyle = 'Flat'
    $btnCopy.FlatAppearance.BorderColor = $steamUi.Border
    $btnCopy.BackColor = $steamUi.Panel2
    $btnCopy.ForeColor = $steamUi.Text
    $btnCopy.Cursor = [System.Windows.Forms.Cursors]::Hand
    $resetTimer = New-Object System.Windows.Forms.Timer
    $resetTimer.Interval = 1500
    $resetTimer.Add_Tick({
        $resetTimer.Stop()
        try { $btnCopy.Text = $copyText } catch {}
    }.GetNewClosure())
    $btnCopy.Add_Click({
        try {
            [System.Windows.Forms.Clipboard]::SetText($address)
            $btnCopy.Text = $doneText
            $resetTimer.Stop(); $resetTimer.Start()
        } catch {}
    }.GetNewClosure())
    $btnCopy.Add_Disposed({ try { $resetTimer.Stop(); $resetTimer.Dispose() } catch {} }.GetNewClosure())
    $dlg.Controls.Add($btnCopy)
}

function Show-SupportDialog ($owner) {
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = (T 'support_title')
    $dlg.ClientSize = New-Object System.Drawing.Size(520, 392)
    $dlg.StartPosition = 'CenterParent'
    $dlg.FormBorderStyle = 'FixedDialog'
    $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false; $dlg.ShowInTaskbar = $false
    $dlg.BackColor = $steamUi.Bg
    $dlg.ForeColor = $steamUi.Text
    $dlg.Font = New-Object System.Drawing.Font('Segoe UI', 9)

    $lblTitle = New-Object System.Windows.Forms.Label
    $lblTitle.Text = (T 'support_title')
    $lblTitle.Location = New-Object System.Drawing.Point(20, 16)
    $lblTitle.Size = New-Object System.Drawing.Size(480, 30)
    $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 14)
    $lblTitle.ForeColor = $steamUi.Text
    $dlg.Controls.Add($lblTitle)

    $lblText = New-Object System.Windows.Forms.Label
    $lblText.Text = (T 'support_text')
    $lblText.Location = New-Object System.Drawing.Point(20, 52)
    $lblText.Size = New-Object System.Drawing.Size(480, 36)
    $lblText.ForeColor = $steamUi.Muted
    $dlg.Controls.Add($lblText)

    $links = @($global:supportLinks)
    $btnW = 152; $btnGap = 12
    for ($i = 0; $i -lt $links.Count; $i++) {
        $btnLink = New-Object System.Windows.Forms.Button
        $btnLink.Text = [string]$links[$i].Name
        $btnLink.Tag = [string]$links[$i].Url
        $btnLink.Location = New-Object System.Drawing.Point((20 + $i * ($btnW + $btnGap)), 96)
        $btnLink.Size = New-Object System.Drawing.Size($btnW, 34)
        $btnLink.FlatStyle = 'Flat'
        $btnLink.FlatAppearance.BorderColor = $steamUi.Accent2
        $btnLink.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
        $btnLink.ForeColor = $steamUi.Text
        $btnLink.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
        $btnLink.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnLink.Add_Click({ param($s, $e) try { Start-Process ([string]$s.Tag) } catch {} })
        $dlg.Controls.Add($btnLink)
    }

    $lblUsdt = New-Object System.Windows.Forms.Label
    $lblUsdt.Text = (T 'support_usdt')
    $lblUsdt.Location = New-Object System.Drawing.Point(20, 154)
    $lblUsdt.Size = New-Object System.Drawing.Size(480, 25)
    $lblUsdt.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $lblUsdt.ForeColor = $steamUi.Accent
    $dlg.Controls.Add($lblUsdt)

    $rowY = 190
    foreach ($w in @($global:supportUsdt)) {
        Add-SupportCopyRow $dlg $rowY ([string]$w.Network) ([string]$w.Address)
        $rowY += 38
    }

    $lblNetHint = New-Object System.Windows.Forms.Label
    $lblNetHint.Text = (T 'support_net_hint')
    $lblNetHint.Location = New-Object System.Drawing.Point(20, ($rowY + 2))
    $lblNetHint.Size = New-Object System.Drawing.Size(480, 34)
    $lblNetHint.ForeColor = $steamUi.Muted
    $lblNetHint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $dlg.Controls.Add($lblNetHint)

    $lnkGit = New-Object System.Windows.Forms.LinkLabel
    $lnkGit.Text = (T 'support_github')
    $lnkGit.Location = New-Object System.Drawing.Point(20, 350)
    $lnkGit.Size = New-Object System.Drawing.Size(340, 26)
    $lnkGit.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $lnkGit.LinkColor = $steamUi.Accent
    $lnkGit.ActiveLinkColor = $steamUi.Accent2
    $lnkGit.VisitedLinkColor = $steamUi.Accent
    $lnkGit.LinkBehavior = [System.Windows.Forms.LinkBehavior]::HoverUnderline
    $lnkGit.Links.Clear()
    [void]$lnkGit.Links.Add(0, $lnkGit.Text.Length, [string]$global:appRepoUrl)
    $lnkGit.Add_LinkClicked({ param($s, $e) try { Start-Process ([string]$e.Link.LinkData) } catch {} })
    $dlg.Controls.Add($lnkGit)

    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Text = (T 'support_close')
    $btnClose.Location = New-Object System.Drawing.Point(400, 346)
    $btnClose.Size = New-Object System.Drawing.Size(100, 34)
    $btnClose.FlatStyle = 'Flat'
    $btnClose.FlatAppearance.BorderColor = $steamUi.Border
    $btnClose.BackColor = $steamUi.Panel
    $btnClose.ForeColor = $steamUi.Text
    $btnClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlg.Controls.Add($btnClose)
    $dlg.CancelButton = $btnClose
    $dlg.AcceptButton = $btnClose

    [void]$dlg.ShowDialog($owner)
    try { $dlg.Dispose() } catch {}
}

# Диалог добавления/редактирования одного эмулятора. $existing - существующий
# профиль (хэштаблица Id/Name/ExePath/Args/Extensions) при редактировании,
# либо $null при добавлении нового. Возвращает обновлённую хэштаблицу или
# $null, если пользователь нажал «Отмена».
function Show-EmulatorEditDialog ($owner, $existing = $null) {
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = if ($existing -eq $null) { (T 'emu_dlg_new') } else { (T 'emu_dlg_edit') }
    $dlg.ClientSize = New-Object System.Drawing.Size(480, 276)
    $dlg.StartPosition = 'CenterParent'
    $dlg.FormBorderStyle = 'FixedDialog'
    $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
    $dlg.BackColor = $steamUi.Bg
    $dlg.ForeColor = $steamUi.Text
    $dlg.Font = New-Object System.Drawing.Font('Segoe UI', 9)

    $lblName = New-Object System.Windows.Forms.Label
    $lblName.Text = (T 'emu_lbl_name')
    $lblName.Location = New-Object System.Drawing.Point(16, 16)
    $lblName.Size = New-Object System.Drawing.Size(100, 24)
    $lblName.ForeColor = $steamUi.Muted
    $dlg.Controls.Add($lblName)

    $txtName = New-Object System.Windows.Forms.TextBox
    $txtName.Location = New-Object System.Drawing.Point(120, 14)
    $txtName.Size = New-Object System.Drawing.Size(340, 24)
    $txtName.BackColor = $steamUi.Input
    $txtName.ForeColor = $steamUi.Text
    $txtName.BorderStyle = 'FixedSingle'
    if ($existing -ne $null) { $txtName.Text = [string]$existing.Name }
    $dlg.Controls.Add($txtName)

    $lblExe = New-Object System.Windows.Forms.Label
    $lblExe.Text = (T 'emu_lbl_exe')
    $lblExe.Location = New-Object System.Drawing.Point(16, 50)
    $lblExe.Size = New-Object System.Drawing.Size(100, 24)
    $lblExe.ForeColor = $steamUi.Muted
    $dlg.Controls.Add($lblExe)

    $txtExe = New-Object System.Windows.Forms.TextBox
    $txtExe.Location = New-Object System.Drawing.Point(120, 48)
    $txtExe.Size = New-Object System.Drawing.Size(258, 24)
    $txtExe.BackColor = $steamUi.Input
    $txtExe.ForeColor = $steamUi.Text
    $txtExe.BorderStyle = 'FixedSingle'
    if ($existing -ne $null) { $txtExe.Text = [string]$existing.ExePath }
    $dlg.Controls.Add($txtExe)

    $btnBrowseExeEmu = New-Object System.Windows.Forms.Button
    $btnBrowseExeEmu.Location = New-Object System.Drawing.Point(384, $txtExe.Top)
    $btnBrowseExeEmu.Size = New-Object System.Drawing.Size(76, $txtExe.Height)
    Set-BrowseIconButton $btnBrowseExeEmu
    # Кнопка папки - вровень с полем пути эмулятора: те же верх и высота (фактическая высота TextBox
    # задаётся шрифтом, а не Size, поэтому берём её у самого поля; Set-BrowseIconButton трогает только ширину).
    $btnBrowseExeEmu.Top = $txtExe.Top
    $btnBrowseExeEmu.Height = $txtExe.Height
    $btnBrowseExeEmu.FlatStyle = 'Flat'
    $btnBrowseExeEmu.BackColor = $steamUi.Panel2
    $btnBrowseExeEmu.ForeColor = $steamUi.Text
    $btnBrowseExeEmu.Add_Click({
        $ofdEmu = New-Object System.Windows.Forms.OpenFileDialog
        $ofdEmu.Title = (T 'emu_ofd_title')
        $ofdEmu.Filter = (T 'emu_ofd_filter')
        if ($ofdEmu.ShowDialog($dlg) -eq [System.Windows.Forms.DialogResult]::OK) {
            $txtExe.Text = $ofdEmu.FileName
            if ([string]::IsNullOrWhiteSpace($txtName.Text)) {
                $txtName.Text = [System.IO.Path]::GetFileNameWithoutExtension($ofdEmu.FileName)
            }
        }
    })
    $dlg.Controls.Add($btnBrowseExeEmu)

    $lblExt = New-Object System.Windows.Forms.Label
    $lblExt.Text = (T 'emu_lbl_ext')
    $lblExt.Location = New-Object System.Drawing.Point(16, 84)
    $lblExt.Size = New-Object System.Drawing.Size(100, 24)
    $lblExt.ForeColor = $steamUi.Muted
    $dlg.Controls.Add($lblExt)

    $txtExt = New-Object System.Windows.Forms.TextBox
    $txtExt.Location = New-Object System.Drawing.Point(120, 82)
    $txtExt.Size = New-Object System.Drawing.Size(340, 24)
    $txtExt.BackColor = $steamUi.Input
    $txtExt.ForeColor = $steamUi.Text
    $txtExt.BorderStyle = 'FixedSingle'
    if ($existing -ne $null) { $txtExt.Text = [string]$existing.Extensions }
    $dlg.Controls.Add($txtExt)

    $lblExtHint = New-Object System.Windows.Forms.Label
    $lblExtHint.Text = (T 'emu_ext_hint')
    $lblExtHint.Location = New-Object System.Drawing.Point(120, 106)
    $lblExtHint.Size = New-Object System.Drawing.Size(340, 18)
    $lblExtHint.ForeColor = $steamUi.Muted
    $lblExtHint.Font = New-Object System.Drawing.Font('Segoe UI', 7.5)
    $dlg.Controls.Add($lblExtHint)

    # Чекбокс «Распаковывать архивы» под полем расширений. Состояние читается из
    # профиля (старые профили без поля -> $false), записывается в результат
    # диалога в конце функции. Подсказка — стандартный ToolTip.
    $chkExtract = New-Object System.Windows.Forms.CheckBox
    $chkExtract.Text = (T 'emu_chk_extract')
    $chkExtract.Location = New-Object System.Drawing.Point(120, 126)
    $chkExtract.Size = New-Object System.Drawing.Size(340, 22)
    $chkExtract.AutoSize = $false
    $chkExtract.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $chkExtract.UseVisualStyleBackColor = $false
    $chkExtract.BackColor = $steamUi.Bg
    $chkExtract.ForeColor = $steamUi.Text
    $chkExtract.Checked = if ($existing -ne $null) { [bool]$existing.ExtractArchives } else { $false }
    # Галочка рисуется так же, как в панелях игр (см. DrawItem списков и «выбрать всё»): квадрат 14x14,
    # заливка Accent с белой «птичкой» при включении, иначе рамка Muted (белая при наведении/фокусе).
    # Сам CheckBox остаётся настоящим (Checked, клавиатура, Tab, ToolTip), заменена только отрисовка.
    $chkExtract.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $chkExtract.FlatAppearance.BorderSize = 0
    $chkExtract.Cursor = [System.Windows.Forms.Cursors]::Hand
    $chkExtract.Tag = $false
    $chkExtract.Add_MouseEnter({ param($s, $e) $s.Tag = $true; $s.Invalidate() })
    $chkExtract.Add_MouseLeave({ param($s, $e) $s.Tag = $false; $s.Invalidate() })
    $chkExtract.Add_GotFocus({ param($s, $e) $s.Invalidate() })
    $chkExtract.Add_LostFocus({ param($s, $e) $s.Invalidate() })
    $chkExtract.Add_Paint({
        param($s, $pe)
        $g = $pe.Graphics
        $bgBrush = New-Object System.Drawing.SolidBrush($s.BackColor)
        $g.FillRectangle($bgBrush, $s.ClientRectangle)
        $bgBrush.Dispose()
        $boxRect = New-Object System.Drawing.Rectangle(0, [int](($s.ClientSize.Height - 14) / 2), 14, 14)
        if ($s.Checked) {
            $fillBrush = New-Object System.Drawing.SolidBrush($steamUi.Accent)
            $g.FillRectangle($fillBrush, $boxRect)
            $fillBrush.Dispose()
            $markPen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 1.6)
            $g.DrawLine($markPen, $boxRect.X + 3, $boxRect.Y + 7, $boxRect.X + 6, $boxRect.Y + 10)
            $g.DrawLine($markPen, $boxRect.X + 6, $boxRect.Y + 10, $boxRect.X + 11, $boxRect.Y + 3)
            $markPen.Dispose()
        } else {
            $borderColor = if ([bool]$s.Tag -or $s.Focused) { [System.Drawing.Color]::White } else { $steamUi.Muted }
            $borderPen = New-Object System.Drawing.Pen($borderColor, 1.2)
            $g.DrawRectangle($borderPen, $boxRect)
            $borderPen.Dispose()
        }
        $textRect = New-Object System.Drawing.Rectangle(22, 0, [Math]::Max(10, $s.ClientSize.Width - 22), $s.ClientSize.Height)
        $flags = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis
        [System.Windows.Forms.TextRenderer]::DrawText($g, [string]$s.Text, $s.Font, $textRect, $s.ForeColor, $flags)
    }.GetNewClosure())
    $dlg.Controls.Add($chkExtract)
    $emuExtractTip = New-Object System.Windows.Forms.ToolTip
    $emuExtractTip.AutoPopDelay = 12000
    # ToolTip не переносит длинную строку сам: разбиваем по словам (~60 символов), а текст без пробелов
    # (китайский) - кусками по 26 символов, иначе подсказка растянулась бы на весь экран.
    $tipLines = New-Object System.Collections.Generic.List[string]
    $tipCur = ''
    foreach ($tipWord in ([string](T 'emu_chk_extract_tip') -split ' ')) {
        while ($tipWord.Length -gt 30) {
            if ($tipCur.Length -gt 0) { $tipLines.Add($tipCur); $tipCur = '' }
            $tipLines.Add($tipWord.Substring(0, 26)); $tipWord = $tipWord.Substring(26)
        }
        if ($tipCur.Length -gt 0 -and ($tipCur.Length + 1 + $tipWord.Length) -gt 60) { $tipLines.Add($tipCur); $tipCur = $tipWord }
        elseif ($tipCur.Length -gt 0) { $tipCur = $tipCur + ' ' + $tipWord }
        else { $tipCur = $tipWord }
    }
    if ($tipCur.Length -gt 0) { $tipLines.Add($tipCur) }
    $emuExtractTip.SetToolTip($chkExtract, ($tipLines.ToArray() -join "`n"))

    # Поле «Аргументы» создаётся здесь, ДО определения $commitNameResult ниже
    # (см. $refreshNameResults/$commitNameResult): они закрыты через
    # .GetNewClosure() и захватывают текущие значения переменных на момент
    # вызова. Если бы $txtArgs создавался позже (как было раньше), внутри
    # этих замыканий он был бы $null, и присвоение $txtArgs.Text = ... кидало
    # бы исключение, которое тихо гасилось в catch {} — из-за этого не
    # выполнялись ни закрытие списка подсказок, ни запись аргументов. Именно
    # это и вызывало баг «у эмуляторов с аргументами список не закрывается,
    # аргументы не прописываются» (у эмуляторов без аргументов эта строка
    # просто не выполнялась, поэтому ошибки не было).
    $lblArgs = New-Object System.Windows.Forms.Label
    $lblArgs.Text = (T 'emu_lbl_args')
    $lblArgs.Location = New-Object System.Drawing.Point(16, 158)
    $lblArgs.Size = New-Object System.Drawing.Size(100, 24)
    $lblArgs.ForeColor = $steamUi.Muted
    $dlg.Controls.Add($lblArgs)

    $txtArgs = New-Object System.Windows.Forms.TextBox
    $txtArgs.Location = New-Object System.Drawing.Point(120, 156)
    $txtArgs.Size = New-Object System.Drawing.Size(340, 24)
    $txtArgs.BackColor = $steamUi.Input
    $txtArgs.ForeColor = $steamUi.Text
    $txtArgs.BorderStyle = 'FixedSingle'
    if ($existing -ne $null) { $txtArgs.Text = [string]$existing.Args }
    $dlg.Controls.Add($txtArgs)

    $lblArgsHint = New-Object System.Windows.Forms.Label
    $lblArgsHint.Text = (T 'emu_args_hint')
    $lblArgsHint.Location = New-Object System.Drawing.Point(120, 180)
    $lblArgsHint.Size = New-Object System.Drawing.Size(340, 32)
    $lblArgsHint.ForeColor = $steamUi.Muted
    $lblArgsHint.Font = New-Object System.Drawing.Font('Segoe UI', 7.5)
    $dlg.Controls.Add($lblArgsHint)

    # Подсказки платформ эмуляции для поля «Расширения» — тот же приём, что и
    # выпадающий список параметров запуска в карточке игры (launchOptResults):
    # обычный ListBox, скрытый по умолчанию, разворачивается поверх остальных
    # контролов диалога (BringToFront) на время выбора. Само поле остаётся
    # обычным текстовым полем — можно как выбрать платформу из списка, так и
    # просто вписать расширения вручную.
    $extResults = New-Object System.Windows.Forms.ListBox
    $extResults.Location = New-Object System.Drawing.Point(120, 104)
    $extResults.Size = New-Object System.Drawing.Size(340, 24)
    $extResults.BackColor = $steamUi.Input
    $extResults.ForeColor = $steamUi.Text
    $extResults.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $extResults.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $extResults.IntegralHeight = $false
    $extResults.Visible = $false
    $extResults.TabStop = $false
    $dlg.Controls.Add($extResults)

    $emuPlatformPresets = Get-EmulatorPlatformPresets
    # Флаг подавления повторного открытия: после выбора варианта фокус
    # программно возвращается в $txtExt, что иначе снова открыло бы список
    # (тот же приём, что и LaunchOptSuppressReopen/SuppressLaunchOptionOnce
    # у параметров запуска в карточке игры).
    $extState = [PSCustomObject]@{ SuppressReopen = $false; AddedArchiveExts = @() }

    # Заполняет список подходящими платформами: без текста в поле — показывает
    # все платформы, с текстом — фильтрует по названию платформы ИЛИ по
    # вхождению в любое из её расширений (чтобы работал ввод как названия
    # платформы, так и самого расширения).
    $refreshExtResults = {
        $query = ([string]$txtExt.Text).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($query)) {
            $filteredPresets = @($emuPlatformPresets)
        } else {
            $filteredPresets = @($emuPlatformPresets | Where-Object {
                $_.Name.ToLowerInvariant().Contains($query) -or
                (@($_.Ext -split ',') -like "*$query*").Count -gt 0
            })
        }
        $extResults.Tag = $filteredPresets
        $extResults.BeginUpdate()
        $extResults.Items.Clear()
        foreach ($p in $filteredPresets) {
            [void]$extResults.Items.Add("$($p.Name)  —  $($p.Ext -replace ',', ', ')")
        }
        $extResults.EndUpdate()
        $extResults.SelectedIndex = -1
        $extResults.Height = [Math]::Min(160, [Math]::Max(24, (@($filteredPresets).Count * 18) + 4))
        return (@($filteredPresets).Count -gt 0)
    }.GetNewClosure()

    $closeExtResults = {
        $extResults.Visible = $false
        $extResults.SelectedIndex = -1
    }.GetNewClosure()

    $openExtResults = {
        if ($extState.SuppressReopen) { $extState.SuppressReopen = $false; return }
        $hasItems = & $refreshExtResults
        if (-not $hasItems) { & $closeExtResults; return }
        $extResults.Visible = $true
        $extResults.BringToFront()
    }.GetNewClosure()

    $commitExtResult = {
        try {
            if ($extResults.SelectedIndex -lt 0) { return }
            $presets = $extResults.Tag
            if ($presets -eq $null -or $extResults.SelectedIndex -ge @($presets).Count) { return }
            $picked = @($presets)[$extResults.SelectedIndex]
            # SuppressReopen ставим ДО присвоения Text: сама установка Text ниже
            # синхронно вызывает TextChanged, а он иначе снова дёрнул бы
            # $openExtResults ещё до explicit-закрытия списка несколькими
            # строками ниже.
            $extState.SuppressReopen = $true
            $txtExt.Text = [string]$picked.Ext
            $txtExt.SelectionStart = $txtExt.Text.Length
            $txtExt.SelectionLength = 0
            & $closeExtResults
            $txtExt.Focus()
        } catch {}
    }.GetNewClosure()

    $txtExt.Add_Click({ & $openExtResults }.GetNewClosure())
    $txtExt.Add_TextChanged({
        if ($extState.SuppressReopen) { $extState.SuppressReopen = $false; return }
        & $openExtResults
    }.GetNewClosure())

    # Галочка «Распаковывать архивы» дописывает расширения архивов в поле «Расширения»,
    # а при снятии убирает только те, что дописала сама (то, что пользователь вписал
    # вручную, не трогаем). Пустое поле означает «без фильтра» (подходят любые файлы,
    # в том числе архивы), поэтому в пустое поле ничего не дописываем: иначе фильтр
    # внезапно ограничился бы одними архивами.
    $chkExtract.Add_CheckedChanged({
        try {
            $cur = @(([string]$txtExt.Text -split '[,;\s]+') | ForEach-Object { $_.Trim().TrimStart('.').ToLowerInvariant() } | Where-Object { $_ -ne '' } | Select-Object -Unique)
            if ($chkExtract.Checked) {
                if ($cur.Count -eq 0) { return }
                $added = @()
                foreach ($a in @(Get-RomArchiveExtensions)) {
                    if ($cur -notcontains $a) { $cur += $a; $added += $a }
                }
                $extState.AddedArchiveExts = @($added)
            } else {
                $drop = @($extState.AddedArchiveExts)
                $cur = @($cur | Where-Object { $drop -notcontains $_ })
                $extState.AddedArchiveExts = @()
            }
            $newText = ($cur -join ',')
            if ($newText -ne [string]$txtExt.Text) {
                $extState.SuppressReopen = $true
                $txtExt.Text = $newText
                $extState.SuppressReopen = $false
                & $closeExtResults
            }
        } catch {}
    }.GetNewClosure())
    $txtExt.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Down -and $extResults.Visible -and $extResults.Items.Count -gt 0) {
            $_.SuppressKeyPress = $true
            $extResults.SelectedIndex = 0
            $extResults.Focus()
        } elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) {
            & $closeExtResults
        }
    }.GetNewClosure())
    $extResults.Add_MouseClick({ & $commitExtResult }.GetNewClosure())
    $extResults.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $_.SuppressKeyPress = $true; & $commitExtResult }
        elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) { $_.SuppressKeyPress = $true; & $closeExtResults; $txtExt.Focus() }
    }.GetNewClosure())

    # Тот же выпадающий список, что и у «Расширений» выше, но для поля
    # «Название»: справочник известных эмуляторов (Get-KnownEmulatorPresets).
    # При выборе эмулятора из списка автоматически подставляются его платформа
    # (или несколько платформ для мультиплатформенных эмуляторов — расширения
    # всех платформ объединяются через запятую) в поле «Расширения» и типовые
    # аргументы запуска в полноэкранном режиме в поле «Аргументы» — но только
    # если для этого эмулятора они известны, иначе поле «Аргументы» не
    # трогается (чтобы не затирать то, что уже вписано вручную).
    $nameResults = New-Object System.Windows.Forms.ListBox
    $nameResults.Location = New-Object System.Drawing.Point(120, 36)
    $nameResults.Size = New-Object System.Drawing.Size(340, 24)
    $nameResults.BackColor = $steamUi.Input
    $nameResults.ForeColor = $steamUi.Text
    $nameResults.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $nameResults.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $nameResults.IntegralHeight = $false
    $nameResults.Visible = $false
    $nameResults.TabStop = $false
    $dlg.Controls.Add($nameResults)

    $knownEmulatorPresets = Get-KnownEmulatorPresets
    $nameState = [PSCustomObject]@{ SuppressReopen = $false }

    # Возвращает объединённые (без повторов) расширения всех платформ пресета —
    # ищет каждое название платформы в справочнике Get-EmulatorPlatformPresets.
    $getPresetExtensions = {
        param($preset)
        $seen = New-Object System.Collections.Generic.List[string]
        foreach ($platformName in @($preset.Platforms)) {
            $platform = $emuPlatformPresets | Where-Object { $_.Name -eq $platformName } | Select-Object -First 1
            if ($platform -eq $null) { continue }
            foreach ($e in @($platform.Ext -split ',')) {
                if (-not $seen.Contains($e)) { [void]$seen.Add($e) }
            }
        }
        return ($seen -join ',')
    }.GetNewClosure()

    $refreshNameResults = {
        $query = ([string]$txtName.Text).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($query)) {
            $filteredEmus = @($knownEmulatorPresets)
        } else {
            $filteredEmus = @($knownEmulatorPresets | Where-Object { $_.Name.ToLowerInvariant().Contains($query) })
        }
        $nameResults.Tag = $filteredEmus
        $nameResults.BeginUpdate()
        $nameResults.Items.Clear()
        foreach ($p in $filteredEmus) {
            $platformsText = if (@($p.Platforms).Count -gt 0) { ($p.Platforms -join ', ') } else { '' }
            [void]$nameResults.Items.Add($(if ($platformsText -ne '') { "$($p.Name)  —  $platformsText" } else { [string]$p.Name }))
        }
        $nameResults.EndUpdate()
        $nameResults.SelectedIndex = -1
        $nameResults.Height = [Math]::Min(160, [Math]::Max(24, (@($filteredEmus).Count * 18) + 4))
        return (@($filteredEmus).Count -gt 0)
    }.GetNewClosure()

    $closeNameResults = {
        $nameResults.Visible = $false
        $nameResults.SelectedIndex = -1
    }.GetNewClosure()

    $openNameResults = {
        if ($nameState.SuppressReopen) { $nameState.SuppressReopen = $false; return }
        & $closeExtResults
        $hasItems = & $refreshNameResults
        if (-not $hasItems) { & $closeNameResults; return }
        $nameResults.Visible = $true
        $nameResults.BringToFront()
    }.GetNewClosure()

    $commitNameResult = {
        try {
            if ($nameResults.SelectedIndex -lt 0) { return }
            $presets = $nameResults.Tag
            if ($presets -eq $null -or $nameResults.SelectedIndex -ge @($presets).Count) { return }
            $picked = @($presets)[$nameResults.SelectedIndex]
            $nameState.SuppressReopen = $true
            $txtName.Text = [string]$picked.Name
            $txtName.SelectionStart = $txtName.Text.Length
            $txtName.SelectionLength = 0
            $pickedExt = & $getPresetExtensions $picked
            if (-not [string]::IsNullOrWhiteSpace($pickedExt)) {
                $extState.SuppressReopen = $true
                $txtExt.Text = $pickedExt
            }
            if (-not [string]::IsNullOrWhiteSpace([string]$picked.Args)) {
                $txtArgs.Text = [string]$picked.Args
            }
            & $closeNameResults
            $txtName.Focus()
        } catch {}
    }.GetNewClosure()

    $txtName.Add_Click({ & $openNameResults }.GetNewClosure())
    $txtName.Add_TextChanged({
        if ($nameState.SuppressReopen) { $nameState.SuppressReopen = $false; return }
        & $openNameResults
    }.GetNewClosure())
    $txtName.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Down -and $nameResults.Visible -and $nameResults.Items.Count -gt 0) {
            $_.SuppressKeyPress = $true
            $nameResults.SelectedIndex = 0
            $nameResults.Focus()
        } elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) {
            & $closeNameResults
        }
    }.GetNewClosure())
    $nameResults.Add_MouseClick({ & $commitNameResult }.GetNewClosure())
    $nameResults.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $_.SuppressKeyPress = $true; & $commitNameResult }
        elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) { $_.SuppressKeyPress = $true; & $closeNameResults; $txtName.Focus() }
    }.GetNewClosure())
    # Открытие списка расширений должно закрывать список эмуляторов, если он
    # ещё был виден (и наоборот — см. $openNameResults выше).
    $txtExt.Add_Click({ & $closeNameResults }.GetNewClosure())

    $btnOkEmu = New-Object System.Windows.Forms.Button
    $btnOkEmu.Text = (T 'set_save')
    $btnOkEmu.Location = New-Object System.Drawing.Point(268, 226)
    $btnOkEmu.Size = New-Object System.Drawing.Size(96, 30)
    $btnOkEmu.FlatStyle = 'Flat'
    $btnOkEmu.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnOkEmu.ForeColor = $steamUi.Text
    $btnOkEmu.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $dlg.Controls.Add($btnOkEmu)

    $btnCancelEmu = New-Object System.Windows.Forms.Button
    $btnCancelEmu.Text = (T 'set_cancel')
    $btnCancelEmu.Location = New-Object System.Drawing.Point(370, 226)
    $btnCancelEmu.Size = New-Object System.Drawing.Size(90, 30)
    $btnCancelEmu.FlatStyle = 'Flat'
    $btnCancelEmu.BackColor = $steamUi.Panel2
    $btnCancelEmu.ForeColor = $steamUi.Text
    $btnCancelEmu.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlg.Controls.Add($btnCancelEmu)

    $dlg.AcceptButton = $btnOkEmu
    $dlg.CancelButton = $btnCancelEmu

    foreach ($otherCtrl in @($txtName, $txtExe, $btnBrowseExeEmu, $chkExtract, $txtArgs, $btnOkEmu, $btnCancelEmu)) {
        $otherCtrl.Add_Enter({ & $closeExtResults }.GetNewClosure())
    }
    foreach ($otherCtrl in @($txtExe, $btnBrowseExeEmu, $txtExt, $chkExtract, $txtArgs, $btnOkEmu, $btnCancelEmu)) {
        $otherCtrl.Add_Enter({ & $closeNameResults }.GetNewClosure())
    }

    # Кнопка «Сохранить» недоступна, пока не выбран существующий exe эмулятора
    # — раньше при пустом/несуществующем пути диалог просто закрывался (OK
    # уже отработал DialogResult), а сообщение об ошибке «Указанный файл
    # эмулятора не найден» всплывало уже ПОСЛЕ закрытия окна, что выглядело
    # как «окно закрывается с ошибкой». Теперь вместо постфактум-проверки
    # кнопка блокируется заранее и сохранить с пустым/неверным путём просто
    # нельзя.
    $updateOkEmuState = {
        $btnOkEmu.Enabled = (-not [string]::IsNullOrWhiteSpace($txtExe.Text)) -and (Test-Path -LiteralPath $txtExe.Text)
    }.GetNewClosure()
    $txtExe.Add_TextChanged({ & $updateOkEmuState }.GetNewClosure())
    & $updateOkEmuState

    # Клик мышкой в любом месте окна (кроме самих текстовых полей и списков
    # подсказок) снимает фокус с активного поля — тот же приём, что и
    # Install-PathFocusDismissHandlers у главного окна, только здесь общий,
    # для всех четырёх полей сразу, а не для конкретных двух меток. Заодно
    # закрываются оба выпадающих списка подсказок, если были открыты.
    $removeEmuFocus = {
        try {
            & $closeExtResults
            & $closeNameResults
            $dlg.ActiveControl = $null
        } catch {}
    }.GetNewClosure()

    function Add-EmuFocusDismissHandler([System.Windows.Forms.Control]$control, $dismissAction) {
        if ($null -eq $control) { return }
        # Кнопки (Обзор/Сохранить/Отмена) сюда НЕ включаем: если в их
        # собственном MouseDown сбросить ActiveControl, WinForms теряет
        # внутреннее состояние «нажата», и Click/DialogResult у кнопки
        # перестаёт срабатывать — кнопка визуально нажимается, но диалог не
        # закрывается (баг с неработающей кнопкой «Отмена»). Клик по кнопке
        # и так снимает фокус с текстовых полей естественным образом, когда
        # сама кнопка получает фокус.
        if ($control -ne $txtName -and $control -ne $txtExe -and $control -ne $txtExt -and `
            $control -ne $txtArgs -and $control -ne $nameResults -and $control -ne $extResults -and `
            $control -isnot [System.Windows.Forms.ButtonBase]) {
            # ВАЖНО: $dismissAction передан параметром именно для того, чтобы
            # .GetNewClosure() здесь захватывал настоящую локальную переменную
            # этой функции. Если вместо параметра читать $removeEmuFocus из
            # объемлющей функции напрямую (динамический скоуп), GetNewClosure
            # его не подхватывает — при реальном клике мышью значение
            # оказывается $null, и "& $null" валит приложение необработанным
            # исключением (см. баг с кнопкой «Отмена»).
            $control.Add_MouseDown({ & $dismissAction }.GetNewClosure())
        }
        foreach ($child in @($control.Controls)) {
            Add-EmuFocusDismissHandler $child $dismissAction
        }
    }
    foreach ($control in @($dlg.Controls)) {
        Add-EmuFocusDismissHandler $control $removeEmuFocus
    }
    $dlg.Add_MouseDown({ & $removeEmuFocus }.GetNewClosure())

    $res = $dlg.ShowDialog($owner)
    if ($res -ne [System.Windows.Forms.DialogResult]::OK) { return $null }

    if ([string]::IsNullOrWhiteSpace($txtName.Text)) {
        Show-AppMessageBox($owner, (T 'emu_need_name'), $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
        return $null
    }

    $cleanExt = (@($txtExt.Text -split ',') | ForEach-Object { $_.Trim().TrimStart('.').ToLowerInvariant() } | Where-Object { $_ -ne '' }) -join ','

    return @{
        Id         = if ($existing -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$existing.Id)) { [string]$existing.Id } else { New-EmulatorProfileId }
        Name       = $txtName.Text.Trim()
        ExePath    = $txtExe.Text.Trim()
        Args       = $txtArgs.Text.Trim()
        Extensions = $cleanExt
        Core       = if ($existing -ne $null) { [string]$existing.Core } else { '' }
        ExtractArchives = [bool]$chkExtract.Checked
    }
}

# Встраивает управление списком эмуляторов (список + Добавить/Изменить/
# Удалить/Сделать активным) прямо в переданную панель $container внутри окна
# настроек — раньше это был отдельный всплывающий диалог по кнопке, но сама
# кнопка была криво расположена (перекрывала заголовок секции «Steam» и
# выглядела как «полоска»); вместо доработки её позиции список теперь сразу
# виден в правой колонке настроек, без дополнительного клика.
# $owner — окно настроек, используется как владелец для диалога добавления/
# изменения одного эмулятора (Show-EmulatorEditDialog) и для MessageBox.
# Каждое действие сразу сохраняется в config.ini — отдельных кнопок
# «Сохранить/Отмена» для всего списка нет, это управление списком, а не форма.
# Компаратор для сортировки ListView по клику на заголовок колонки — классическая
# .NET-схема (IComparer + запоминание текущей колонки/направления), т.к. у самого
# ListView нет встроенной сортировки текстовых строк по клику на Details-заголовок.
if (-not ('ListViewColumnSorter' -as [type])) {
    Add-Type -ReferencedAssemblies @('System.Windows.Forms') -TypeDefinition @'
using System;
using System.Collections;
using System.Windows.Forms;

public class ListViewColumnSorter : IComparer
{
    private int ColumnToSort;
    private SortOrder OrderOfSort;
    private CaseInsensitiveComparer ObjectCompare;

    public ListViewColumnSorter()
    {
        ColumnToSort = 0;
        OrderOfSort = SortOrder.None;
        ObjectCompare = new CaseInsensitiveComparer();
    }

    public int Compare(object x, object y)
    {
        ListViewItem listviewX = (ListViewItem)x;
        ListViewItem listviewY = (ListViewItem)y;

        string textX = listviewX.SubItems.Count > ColumnToSort ? listviewX.SubItems[ColumnToSort].Text : "";
        string textY = listviewY.SubItems.Count > ColumnToSort ? listviewY.SubItems[ColumnToSort].Text : "";

        int compareResult = ObjectCompare.Compare(textX, textY);

        if (OrderOfSort == SortOrder.Ascending) return compareResult;
        if (OrderOfSort == SortOrder.Descending) return -compareResult;
        return 0;
    }

    public int SortColumn
    {
        get { return ColumnToSort; }
        set { ColumnToSort = value; }
    }

    public SortOrder Order
    {
        get { return OrderOfSort; }
        set { OrderOfSort = value; }
    }
}
'@ -ErrorAction Stop
}

# ===================== БИБЛИОТЕКИ АПСКЕЙЛЕРОВ (DLSS / FSR / XeSS) В НАСТРОЙКАХ =====================
# Блок под списком эмуляторов: те же девять DLL и та же сетка 3×3, что и в карточке игры
# (DLSS / DLSS RR / DLSS FG / FSR DX12 / FSR VK / XeSS / XeSS FG / XeSS DX11 / XeLL).
# Каждая плитка — одна библиотека:
#   • заголовок + статус («↑ v310.9.1» — есть новее, «✓ актуально», «↓ 43%» — идёт загрузка);
#   • список СКАЧАННЫХ версий — выбор в нём и есть «выбранная по умолчанию» версия (её будет
#     подставлять карточка игры);
#   • кнопка ↓ — всплывающий список версий, которых ещё нет на диске (самая новая помечена ★);
#   • кнопка ✕ — удалить выбранную версию с диска (с подтверждением).
# В строке заголовка: «Проверить» (обновить список версий) и «Обновить все» (скачать последние версии
# всех библиотек одной очередью). Список версий берётся из открытого манифеста DLSS Swapper и кэшируется
# на диске; при открытии настроек обновляется в фоне, если кэшу больше 12 часов.
# Файлы: %AppData%\Steam Commander\upscalers\files\<Ключ>\<версия>_<md5>\<dll> + meta.json,
# выбор версий — upscalers\selection.json, кэш манифеста — upscalers\manifest_slim.json.
$script:upscalerManifestUrl = 'https://raw.githubusercontent.com/beeradmoore/dlss-swapper-manifest-builder/refs/heads/main/manifest.json'

function Get-UpscalerDefs {
    # Порядок и файлы — как в сетке карточки игры ($dlssFieldDefs). Manifest/Pat — ключи в манифесте.
    return @(
        @{ Key = 'SR';     Title = 'DLSS';      Tip = (T 'card_dlss_sr'); File = 'nvngx_dlss.dll';          Manifest = @('dlss');          Pat = '^dlss$' },
        @{ Key = 'RR';     Title = 'DLSS RR';   Tip = (T 'card_dlss_rr'); File = 'nvngx_dlssd.dll';         Manifest = @('dlss_d');        Pat = '^dlss_d$' },
        @{ Key = 'FG';     Title = 'DLSS FG';   Tip = (T 'card_dlss_fg'); File = 'nvngx_dlssg.dll';         Manifest = @('dlss_g');        Pat = '^dlss_g$' },
        @{ Key = 'FSR12';  Title = 'FSR DX12';  Tip = 'FSR 3.1 DirectX 12'; File = 'amd_fidelityfx_dx12.dll'; Manifest = @('fsr_31_dx12'); Pat = 'fsr.*dx12' },
        @{ Key = 'FSRVK';  Title = 'FSR VK';    Tip = 'FSR 3.1 Vulkan';     File = 'amd_fidelityfx_vk.dll';   Manifest = @('fsr_31_vk');   Pat = 'fsr.*vk' },
        @{ Key = 'XESS';   Title = 'XeSS';      Tip = 'XeSS';               File = 'libxess.dll';             Manifest = @('xess');        Pat = '^xess$' },
        @{ Key = 'XESSFG'; Title = 'XeSS FG';   Tip = 'XeSS Frame Generation'; File = 'libxess_fg.dll';      Manifest = @('xess_fg');     Pat = 'xess.*fg' },
        @{ Key = 'XESS11'; Title = 'XeSS DX11'; Tip = 'XeSS (DirectX 11)';  File = 'libxess_dx11.dll';       Manifest = @('xess_dx11');   Pat = 'xess.*dx11' },
        @{ Key = 'XELL';   Title = 'XeLL';      Tip = 'XeLL (Xe Low Latency)'; File = 'libxell.dll';          Manifest = @('xell');        Pat = 'xell' }
    )
}

function Get-UpscalerStoreRoot {
    $p = Join-Path $global:appDataDir 'upscalers'
    try { if (-not [System.IO.Directory]::Exists($p)) { [void][System.IO.Directory]::CreateDirectory($p) } } catch {}
    return $p
}

function Format-UpscalerVersion ([string]$Ver) {
    if ([string]::IsNullOrWhiteSpace($Ver)) { return '?' }
    $parts = @($Ver.Split('.'))
    $n = $parts.Count
    # 310.7.129.0 -> v310.7.129 (как в полосе DLSS на плитках библиотеки)
    while ($n -gt 2 -and [string]$parts[$n - 1] -eq '0') { $n-- }
    return 'v' + ((@($parts[0..($n - 1)])) -join '.')
}

function ConvertTo-UpscalerVersionObj ([string]$Ver) {
    try { return [version]$Ver } catch { return [version]'0.0' }
}

function Format-UpscalerSize ([long]$Bytes) {
    if ($Bytes -le 0) { return '' }
    return ('{0:0.#} {1}' -f ($Bytes / 1MB), (T 'upl_mb'))
}

function New-UpscalerEntryId ($Entry) {
    $m = [string]$Entry.md5
    if ($m.Length -gt 8) { $m = $m.Substring(0, 8) }
    $id = ([string]$Entry.ver) + '_' + $m
    return ($id -replace '[^0-9A-Za-z._-]', '_')
}

function Get-UpscalerRemote {
    # Кэш манифеста: хэш-таблица «ключ манифеста -> массив версий» или $null, если кэша нет.
    $f = Join-Path (Get-UpscalerStoreRoot) 'manifest_slim.json'
    if (-not [System.IO.File]::Exists($f)) { return $null }
    try {
        $o = ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8))
        $res = @{}
        foreach ($p in $o.PSObject.Properties) { $res[[string]$p.Name] = @($p.Value) }
        return $res
    } catch { return $null }
}

function Get-UpscalerRemoteEntries ($Remote, $Def) {
    # Версии библиотеки в манифесте, новые — первыми.
    if ($null -eq $Remote) { return @() }
    $list = $null
    foreach ($mk in @($Def.Manifest)) { if ($Remote.ContainsKey($mk)) { $list = @($Remote[$mk]); break } }
    if ($null -eq $list) {
        foreach ($rk in @($Remote.Keys)) { if ([string]$rk -match [string]$Def.Pat) { $list = @($Remote[$rk]); break } }
    }
    if ($null -eq $list) { return @() }
    return @($list | Sort-Object -Property @{ Expression = { ConvertTo-UpscalerVersionObj ([string]$_.ver) }; Descending = $true })
}

function Get-UpscalerLocalVersions ([string]$Key, [string]$Dll) {
    $dir = Join-Path (Join-Path (Get-UpscalerStoreRoot) 'files') $Key
    $out = New-Object System.Collections.ArrayList
    if ([System.IO.Directory]::Exists($dir)) {
        foreach ($d in [System.IO.Directory]::GetDirectories($dir)) {
            $dllPath = Join-Path $d $Dll
            $metaPath = Join-Path $d 'meta.json'
            if (-not ([System.IO.File]::Exists($dllPath) -and [System.IO.File]::Exists($metaPath))) { continue }
            try { $m = ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($metaPath, [System.Text.Encoding]::UTF8)) } catch { continue }
            $label = [string]$m.label
            $disp = Format-UpscalerVersion ([string]$m.ver)
            if (-not [string]::IsNullOrWhiteSpace($label)) { $disp += ' ' + $label }
            $size = [long]0
            try { $size = (New-Object System.IO.FileInfo($dllPath)).Length } catch {}
            [void]$out.Add([PSCustomObject]@{
                Id = [string][System.IO.Path]::GetFileName($d); Ver = [string]$m.ver; Label = $label
                Display = $disp; Dir = $d; Path = $dllPath; Size = $size
                Num = (ConvertTo-UpscalerVersionObj ([string]$m.ver))
            })
        }
    }
    return @($out | Sort-Object -Property Num -Descending)
}

function Get-UpscalerSelection {
    $f = Join-Path (Get-UpscalerStoreRoot) 'selection.json'
    $res = @{}
    try {
        if ([System.IO.File]::Exists($f)) {
            $o = ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8))
            foreach ($p in $o.PSObject.Properties) { $res[[string]$p.Name] = [string]$p.Value }
        }
    } catch {}
    return $res
}

function Set-UpscalerSelection ([string]$Key, [string]$Id) {
    try {
        $sel = Get-UpscalerSelection
        if ([string]::IsNullOrEmpty($Id)) { [void]$sel.Remove($Key) } else { $sel[$Key] = $Id }
        $f = Join-Path (Get-UpscalerStoreRoot) 'selection.json'
        [System.IO.File]::WriteAllText($f, (ConvertTo-Json -InputObject $sel), (New-Object System.Text.UTF8Encoding($false)))
    } catch {}
}

function Remove-UpscalerLocalVersion ([string]$Key, [string]$Id) {
    if ([string]::IsNullOrWhiteSpace($Id) -or $Id -match '[\\/:]' -or $Id -eq '..') { return $false }
    $dir = Join-Path (Join-Path (Join-Path (Get-UpscalerStoreRoot) 'files') $Key) $Id
    try {
        if ([System.IO.Directory]::Exists($dir)) { [System.IO.Directory]::Delete($dir, $true) }
        return $true
    } catch { return $false }
}

# Версия DLL в том же виде, что и в карточке игры: 310.7.129.0 -> v310.7.129.
function Get-DllVersionLabel ([string]$Path) {
    try {
        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($Path)
        $parts = @([int]$vi.FileMajorPart, [int]$vi.FileMinorPart, [int]$vi.FileBuildPart, [int]$vi.FilePrivatePart)
        if ($parts[0] -gt 0) {
            $n = 4
            while ($n -gt 2 -and $parts[$n - 1] -eq 0) { $n-- }
            return 'v' + ((@($parts[0..($n - 1)])) -join '.')
        }
    } catch {}
    return ''
}

# Замена библиотек апскейлеров в папке игры. Targets — массив @{ Dst = файл в игре; Src = откуда взять }.
# Порядок безопасный:
#   1) для каждого файла рядом кладём <dll>.sc_new (новая версия) и <dll>.sc_prev (копия текущей) —
#      если на этом шаге что-то не так (нет места, нет доступа), игра ещё не тронута;
#   2) перед первой заменой делаем бэкап оригинала <dll>.sc_orig (только если его ещё нет, поэтому он
#      всегда хранит исходную версию игры, а не промежуточную), затем копируем новую версию поверх;
#   3) если замена любого файла не удалась (например, игра запущена и держит DLL), уже заменённые
#      возвращаются из .sc_prev — игра остаётся в прежнем состоянии;
#   4) временные .sc_new/.sc_prev удаляются; .sc_orig остаётся — из него «Восстановить» возвращает оригинал.
function Set-GameUpscalerFiles ([object[]]$Targets) {
    $prepared = New-Object System.Collections.ArrayList
    $touched = New-Object System.Collections.ArrayList
    $err = ''
    try {
        foreach ($t in @($Targets)) {
            $dst = [string]$t.Dst; $src = [string]$t.Src
            if (-not [System.IO.File]::Exists($src)) { throw (T 'dll_err_no_src' @($src)) }
            if (-not [System.IO.File]::Exists($dst)) { throw (T 'dll_err_no_dst' @($dst)) }
            $item = [PSCustomObject]@{ Dst = $dst; New = ($dst + '.sc_new'); Prev = ($dst + '.sc_prev'); Orig = ($dst + '.sc_orig') }
            [void]$prepared.Add($item)
            [System.IO.File]::Copy($src, $item.New, $true)
            [System.IO.File]::Copy($dst, $item.Prev, $true)
            # Оригинал (<dll>.sc_orig) сохраняем уже на этапе подготовки — до того, как хоть один файл игры тронут.
            # Если бэкап уже есть, он не перезаписывается: в нём всегда исходная версия игры.
            if (-not [System.IO.File]::Exists($item.Orig)) { [System.IO.File]::Copy($item.Prev, $item.Orig, $false) }
        }
        foreach ($it in $prepared) {
            [void]$touched.Add($it)
            try { [System.IO.File]::SetAttributes($it.Dst, [System.IO.FileAttributes]::Normal) } catch {}
            [System.IO.File]::Copy($it.New, $it.Dst, $true)
        }
    } catch {
        $err = [string]$_.Exception.Message
        foreach ($it in $touched) { try { [System.IO.File]::Copy($it.Prev, $it.Dst, $true) } catch {} }
    }
    foreach ($it in $prepared) {
        try { if ([System.IO.File]::Exists($it.New)) { [System.IO.File]::Delete($it.New) } } catch {}
        try { if ([System.IO.File]::Exists($it.Prev)) { [System.IO.File]::Delete($it.Prev) } } catch {}
    }
    return [PSCustomObject]@{ Ok = ([string]::IsNullOrEmpty($err)); Error = $err; Count = $(if ([string]::IsNullOrEmpty($err)) { $prepared.Count } else { 0 }) }
}

# Фоновый работник (отдельный runspace, только .NET — без функций скрипта). Два режима:
#   manifest — скачать манифест, оставить из него нужные поля (без dev-сборок), записать кэш;
#   download — по очереди скачать zip каждой версии, проверить md5, достать из архива DLL
#              и записать meta.json (сначала в папку «.part», затем переименовать — недокачанных версий не бывает).
$script:upscalerWorker = {
    param($mode, $jobs, $state, $root, $url)
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
    $md5Of = {
        param($path)
        $fs = [System.IO.File]::OpenRead($path)
        try {
            $h = [System.Security.Cryptography.MD5]::Create()
            return ([System.BitConverter]::ToString($h.ComputeHash($fs)) -replace '-', '')
        } finally { $fs.Dispose() }
    }
    if ($mode -eq 'manifest') {
        try {
            Add-Type -AssemblyName System.Web.Extensions
            $req = [System.Net.HttpWebRequest]::Create($url)
            $req.UserAgent = 'SteamCommander'
            $req.Timeout = 30000
            $req.ReadWriteTimeout = 60000
            $resp = $req.GetResponse()
            $sr = New-Object System.IO.StreamReader($resp.GetResponseStream(), [System.Text.Encoding]::UTF8)
            try { $txt = $sr.ReadToEnd() } finally { $sr.Dispose(); $resp.Close() }
            $ser = New-Object System.Web.Script.Serialization.JavaScriptSerializer
            $ser.MaxJsonLength = [int]::MaxValue
            $ser.RecursionLimit = 100
            $obj = $ser.DeserializeObject($txt)
            $slim = @{}
            foreach ($k in @($obj.Keys)) {
                $list = New-Object System.Collections.ArrayList
                foreach ($it in @($obj[$k])) {
                    if ($it -isnot [System.Collections.IDictionary]) { continue }
                    if ($it['is_dev_file']) { continue }
                    if ([string]::IsNullOrEmpty([string]$it['download_url'])) { continue }
                    [void]$list.Add(@{
                        ver = [string]$it['version']; label = [string]$it['additional_label']
                        url = [string]$it['download_url']; md5 = [string]$it['md5_hash']; zmd5 = [string]$it['zip_md5_hash']
                        size = [long]$it['file_size']; zsize = [long]$it['zip_file_size']
                    })
                }
                $slim[[string]$k] = $list
            }
            if ($slim.Count -eq 0) { throw 'empty manifest' }
            if (-not [System.IO.Directory]::Exists($root)) { [void][System.IO.Directory]::CreateDirectory($root) }
            $tmp = [System.IO.Path]::Combine($root, 'manifest_slim.json.tmp')
            $dst = [System.IO.Path]::Combine($root, 'manifest_slim.json')
            # JSON пишем вручную: JavaScriptSerializer.Serialize падал на объектах, обёрнутых в PSObject
            $jEsc = {
                param($v)
                $sb2 = New-Object System.Text.StringBuilder
                [void]$sb2.Append('"')
                foreach ($ch in ([string]$v).ToCharArray()) {
                    $c = [int]$ch
                    if ($ch -eq '"') { [void]$sb2.Append('\"') }
                    elseif ($ch -eq '\') { [void]$sb2.Append('\\') }
                    elseif ($c -lt 32) { [void]$sb2.Append(('\u{0:x4}' -f $c)) }
                    else { [void]$sb2.Append($ch) }
                }
                [void]$sb2.Append('"')
                return $sb2.ToString()
            }
            $jb = New-Object System.Text.StringBuilder
            [void]$jb.Append('{')
            $firstKey = $true
            foreach ($k in @($slim.Keys)) {
                if (-not $firstKey) { [void]$jb.Append(',') }
                $firstKey = $false
                [void]$jb.Append((& $jEsc $k)).Append(':[')
                $firstItem = $true
                foreach ($e in $slim[$k]) {
                    if (-not $firstItem) { [void]$jb.Append(',') }
                    $firstItem = $false
                    [void]$jb.Append('{"ver":').Append((& $jEsc $e['ver']))
                    [void]$jb.Append(',"label":').Append((& $jEsc $e['label']))
                    [void]$jb.Append(',"url":').Append((& $jEsc $e['url']))
                    [void]$jb.Append(',"md5":').Append((& $jEsc $e['md5']))
                    [void]$jb.Append(',"zmd5":').Append((& $jEsc $e['zmd5']))
                    [void]$jb.Append(',"size":').Append(([long]$e['size']).ToString([System.Globalization.CultureInfo]::InvariantCulture))
                    [void]$jb.Append(',"zsize":').Append(([long]$e['zsize']).ToString([System.Globalization.CultureInfo]::InvariantCulture))
                    [void]$jb.Append('}')
                }
                [void]$jb.Append(']')
            }
            [void]$jb.Append('}')
            [System.IO.File]::WriteAllText($tmp, $jb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
            [System.IO.File]::Copy($tmp, $dst, $true)
            [System.IO.File]::Delete($tmp)
            $state['Ok'] = $true
        } catch { $state['Error'] = $_.Exception.Message }
        $state['Done'] = $true
        return
    }

    # ----- download -----
    try { Add-Type -AssemblyName System.IO.Compression.FileSystem } catch {}
    $idx = 0
    foreach ($j in @($jobs)) {
        if ($state['Cancel']) { break }
        $state['Index'] = $idx
        $idx++
        $state['Pct'][$j.Key] = 0
        $tmpZip = [System.IO.Path]::Combine([System.IO.Path]::GetTempPath(), ('sc_upscaler_' + [guid]::NewGuid().ToString('N') + '.zip'))
        $stage = ([string]$j.FinalDir) + '.part'
        try {
            $req = [System.Net.HttpWebRequest]::Create([string]$j.Url)
            $req.UserAgent = 'SteamCommander'
            $req.Timeout = 30000
            $req.ReadWriteTimeout = 60000
            $resp = $req.GetResponse()
            try {
                $len = [long]$resp.ContentLength
                $in = $resp.GetResponseStream()
                $out = [System.IO.File]::Create($tmpZip)
                try {
                    $buf = New-Object byte[] 81920
                    $read = [long]0
                    while (($n = $in.Read($buf, 0, $buf.Length)) -gt 0) {
                        if ($state['Cancel']) { throw 'cancelled' }
                        $out.Write($buf, 0, $n)
                        $read += $n
                        if ($len -gt 0) { $state['Pct'][$j.Key] = [int][Math]::Min(99, [Math]::Floor(100.0 * $read / $len)) }
                    }
                } finally { $out.Dispose(); $in.Dispose() }
            } finally { $resp.Close() }

            if (-not [string]::IsNullOrEmpty([string]$j.Zmd5)) {
                $zh = & $md5Of $tmpZip
                if (-not [string]::Equals($zh, [string]$j.Zmd5, [System.StringComparison]::OrdinalIgnoreCase)) { throw 'zip checksum mismatch' }
            }
            if ([System.IO.Directory]::Exists($stage)) { [System.IO.Directory]::Delete($stage, $true) }
            [void][System.IO.Directory]::CreateDirectory($stage)
            $zip = [System.IO.Compression.ZipFile]::OpenRead($tmpZip)
            try {
                $entry = $null
                foreach ($en in $zip.Entries) {
                    if ([string]::Equals($en.Name, [string]$j.Dll, [System.StringComparison]::OrdinalIgnoreCase)) { $entry = $en; break }
                }
                if ($null -eq $entry) { throw ('no ' + [string]$j.Dll + ' in archive') }
                [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, [System.IO.Path]::Combine($stage, [string]$j.Dll), $true)
            } finally { $zip.Dispose() }
            if (-not [string]::IsNullOrEmpty([string]$j.Md5)) {
                $dh = & $md5Of ([System.IO.Path]::Combine($stage, [string]$j.Dll))
                if (-not [string]::Equals($dh, [string]$j.Md5, [System.StringComparison]::OrdinalIgnoreCase)) { throw 'dll checksum mismatch' }
            }
            $meta = ConvertTo-Json -InputObject ([ordered]@{ ver = [string]$j.Ver; label = [string]$j.Label; md5 = [string]$j.Md5; file = [string]$j.Dll })
            [System.IO.File]::WriteAllText([System.IO.Path]::Combine($stage, 'meta.json'), $meta, (New-Object System.Text.UTF8Encoding($false)))
            if ([System.IO.Directory]::Exists([string]$j.FinalDir)) { [System.IO.Directory]::Delete([string]$j.FinalDir, $true) }
            [System.IO.Directory]::Move($stage, [string]$j.FinalDir)
            $state['Pct'][$j.Key] = 100
            [void]$state['Finished'].Add(@{ Key = [string]$j.Key; Id = [string]$j.Id })
        } catch {
            [void]$state['Errors'].Add(([string]$j.Title + ': ' + $_.Exception.Message))
            try { if ([System.IO.Directory]::Exists($stage)) { [System.IO.Directory]::Delete($stage, $true) } } catch {}
        } finally {
            try { if ([System.IO.File]::Exists($tmpZip)) { [System.IO.File]::Delete($tmpZip) } } catch {}
        }
    }
    $state['Done'] = $true
}

function Start-UpscalerWorker ([string]$Mode, $Jobs) {
    $state = [hashtable]::Synchronized(@{
        Cancel = $false; Done = $false; Ok = $false; Error = ''; Index = 0
        Pct = [hashtable]::Synchronized(@{})
        Errors = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
        Finished = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    })
    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = [System.Threading.ApartmentState]::MTA
    $rs.Open()
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($script:upscalerWorker.ToString())
    [void]$ps.AddArgument($Mode)
    [void]$ps.AddArgument($Jobs)
    [void]$ps.AddArgument($state)
    [void]$ps.AddArgument((Get-UpscalerStoreRoot))
    [void]$ps.AddArgument($script:upscalerManifestUrl)
    $handle = $ps.BeginInvoke()
    return [PSCustomObject]@{ Ps = $ps; Rs = $rs; Handle = $handle; State = $state }
}

function Add-UpscalerLibraryControls ($owner, $container) {
    $W = [int]$container.ClientSize.Width
    $tileH = 51; $gapY = 4
    # Плитки занимают всю ширину блока: левый край — по левой границе списка эмуляторов, правый — по правой.
    $tileW = [int][Math]::Floor(($W - 2 * 10) / 3)
    $gapX = [int][Math]::Floor(($W - 3 * $tileW) / 2); if ($gapX -lt 4) { $gapX = 4 }
    $gridTop = 32
    $symFont = New-Object System.Drawing.Font('Segoe UI Symbol', 9)
    $glyphDown = [string][char]0x2193
    $glyphUp = [string][char]0x2191
    $glyphOk = [string][char]0x2713
    $glyphDel = [string][char]0x2715

    $ctx = @{
        Tiles = [ordered]@{}; Remote = $null; Run = $null; Busy = $false; Mode = ''; Jobs = $null
        Status = $null; Bar = $null; BarBg = $null; BtnCheck = $null; BtnAll = $null; BtnLatest = $null; Timer = $null
    }
    $defs = @(Get-UpscalerDefs)
    $defByKey = @{}
    foreach ($d in $defs) { $defByKey[[string]$d.Key] = $d }
    $tip = New-Object System.Windows.Forms.ToolTip

    # --- Заголовок раздела и кнопка «папка» (как кнопка папки языков) ---
    $secTitle = New-Object System.Windows.Forms.Label
    $secTitle.Text = (T 'upl_section')
    $secTitle.Location = New-Object System.Drawing.Point(0, 0)
    $secTitle.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $secTitle.Size = New-Object System.Drawing.Size(([int]$secTitle.PreferredWidth + 4), 26)
    $secTitle.ForeColor = $steamUi.Accent
    $container.Controls.Add($secTitle)

    $btnFolder = New-Object System.Windows.Forms.Button
    $btnFolder.Location = New-Object System.Drawing.Point(([int]$secTitle.Width + 6), 0)
    $btnFolder.Size = New-Object System.Drawing.Size(28, 26)
    $btnFolder.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnFolder.FlatAppearance.BorderColor = $steamUi.Border
    $btnFolder.FlatAppearance.BorderSize = 1
    $btnFolder.BackColor = $steamUi.Panel
    $btnFolder.ForeColor = $steamUi.Text
    $btnFolder.Font = New-Object System.Drawing.Font('Segoe UI Emoji', 9)
    $btnFolder.Text = ([string][char]0xD83D + [string][char]0xDCC1)
    $btnFolder.Padding = New-Object System.Windows.Forms.Padding(0)
    $btnFolder.TabStop = $false
    $btnFolder.Cursor = [System.Windows.Forms.Cursors]::Hand
    $tip.SetToolTip($btnFolder, (T 'upl_tip_folder'))
    $btnFolder.Add_Click({
        try { Start-Process -FilePath 'explorer.exe' -ArgumentList ('"' + (Get-UpscalerStoreRoot) + '"') } catch {}
    })
    $container.Controls.Add($btnFolder)


    # --- Невидимая точка фокуса: после действий в этом блоке фокус уходит на неё, а не на
    #     первое поле окна (иначе WinForms передаёт его полю пути Steam, а в списке остаётся рамка выбора) ---
    $focusSink = New-Object System.Windows.Forms.Button
    $focusSink.Text = ''
    $focusSink.Location = New-Object System.Drawing.Point(0, 0)
    $focusSink.Size = New-Object System.Drawing.Size(1, 1)
    $focusSink.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $focusSink.FlatAppearance.BorderSize = 0
    $focusSink.BackColor = $container.BackColor
    $focusSink.ForeColor = $container.BackColor
    $focusSink.TabStop = $false
    $container.Controls.Add($focusSink)
    $ctx.ClearFocus = {
        try {
            $owner.ActiveControl = $focusSink
            [void]$focusSink.Focus()
        } catch {}
    }.GetNewClosure()

    # --- Обновление одной плитки по данным диска и кэша манифеста ---
    $ctx.RefreshTile = {
        param([string]$key)
        $def = $defByKey[$key]
        $t = $ctx.Tiles[$key]
        $local = @(Get-UpscalerLocalVersions $key ([string]$def.File))
        $t.Local = $local
        $entries = @(Get-UpscalerRemoteEntries $ctx.Remote $def)
        $latest = $null
        if ($entries.Count -gt 0) { $latest = $entries[0] }

        # Полный список: все версии из манифеста + скачанные, которых в манифесте нет.
        $localById = @{}
        foreach ($lv in $local) { $localById[[string]$lv.Id] = $lv }
        $raw = New-Object System.Collections.ArrayList
        $seen = @{}
        $ord = 0
        foreach ($en in $entries) {
            $eid = New-UpscalerEntryId $en
            if ($seen.ContainsKey($eid)) { continue }
            $seen[$eid] = $true
            $lv = $null
            if ($localById.ContainsKey($eid)) { $lv = $localById[$eid] }
            $txt = Format-UpscalerVersion ([string]$en.ver)
            if (-not [string]::IsNullOrWhiteSpace([string]$en.label)) { $txt += ' ' + [string]$en.label }
            [void]$raw.Add([PSCustomObject]@{
                Id = $eid; Text = $txt; Downloaded = ($null -ne $lv); Entry = $en; Local = $lv
                Num = (ConvertTo-UpscalerVersionObj ([string]$en.ver)); Ord = $ord
            })
            $ord++
        }
        foreach ($lv in $local) {
            if ($seen.ContainsKey([string]$lv.Id)) { continue }
            [void]$raw.Add([PSCustomObject]@{
                Id = [string]$lv.Id; Text = [string]$lv.Display; Downloaded = $true; Entry = $null; Local = $lv
                Num = $lv.Num; Ord = $ord
            })
            $ord++
        }
        $items = @($raw | Sort-Object -Property @{ Expression = { $_.Num }; Descending = $true }, @{ Expression = { $_.Ord }; Descending = $false })
        $t.Items = $items

        # Версия по умолчанию — выбранная пользователем из скачанных (иначе самая новая скачанная).
        $sel = Get-UpscalerSelection
        $defId = ''
        if ($local.Count -gt 0) {
            $defId = [string]$local[0].Id
            if ($sel.ContainsKey($key) -and $localById.ContainsKey([string]$sel[$key])) { $defId = [string]$sel[$key] }
        }
        $marks = New-Object System.Collections.ArrayList
        foreach ($it in $items) {
            [void]$marks.Add([bool]$it.Downloaded)
        }
        $t.Marks = @($marks)

        # Что показано в списке: прежний выбор, иначе версия по умолчанию, иначе первая в списке.
        $showId = [string]$t.Sel
        $showIdx = -1
        for ($i = 0; $i -lt $items.Count; $i++) { if ([string]$items[$i].Id -eq $showId) { $showIdx = $i; break } }
        if ($showIdx -lt 0 -and $defId -ne '') {
            for ($i = 0; $i -lt $items.Count; $i++) { if ([string]$items[$i].Id -eq $defId) { $showIdx = $i; break } }
        }
        if ($showIdx -lt 0 -and $items.Count -gt 0) { $showIdx = 0 }

        $cmb = $t.Combo
        $cmb.Items.Clear()
        if ($items.Count -eq 0) {
            [void]$cmb.Items.Add((T 'upl_none'))
            $cmb.SelectedIndex = 0
            $cmb.Tag = 'missing'
            $cmb.Locked = $true
            $t.Sel = ''
        } else {
            foreach ($it in $items) { [void]$cmb.Items.Add([string]$it.Text) }
            $cmb.SelectedIndex = $showIdx
            $cmb.Tag = $null
            $cmb.Locked = $false
            $t.Sel = [string]$items[$showIdx].Id
        }
        try { $cmb.Invalidate() } catch {}
        & $ctx.UpdateButtons $key

        # Статус справа от названия.
        $stText = ''; $stColor = $steamUi.Muted
        if ($null -ne $latest) {
            # «Актуально» — только если версией по умолчанию выбрана самая последняя версия.
            $best = $null
            if ($defId -ne '' -and $localById.ContainsKey($defId)) { $best = $localById[$defId] }
            $latestNum = ConvertTo-UpscalerVersionObj ([string]$latest.ver)
            if ($null -eq $best) {
                $stText = $glyphDown + ' ' + (Format-UpscalerVersion ([string]$latest.ver)); $stColor = $steamUi.Accent
            } elseif ($best.Num -lt $latestNum) {
                $stText = $glyphUp + ' ' + (Format-UpscalerVersion ([string]$latest.ver)); $stColor = $steamUi.Accent
            } else {
                $stText = $glyphOk + ' ' + (T 'upl_uptodate'); $stColor = $steamUi.Green
            }
        }
        $t.Status.Text = $stText
        $t.Status.ForeColor = $stColor

        # Строка-пояснение под списком — про выбранную в списке версию.
        $info = ''
        if ($items.Count -gt 0) {
            $cur = $items[$showIdx]
            if ($cur.Downloaded) {
                $info = (Format-UpscalerSize ([long]$cur.Local.Size)) + '  ·  ' + (T 'upl_have' @($local.Count))
            } elseif ($null -ne $cur.Entry -and [long]$cur.Entry.zsize -gt 0) {
                $info = (T 'upl_available' @((Format-UpscalerSize ([long]$cur.Entry.zsize))))
            }
        }
        $t.Info.Text = $info
    }.GetNewClosure()

    # ↓ горит только на версии, которой ещё нет на диске; ✕ — только на скачанной.
    $ctx.UpdateButtons = {
        param([string]$key)
        $t = $ctx.Tiles[$key]
        $items = @($t.Items)
        $i = $t.Combo.SelectedIndex
        $it = $null
        if ($i -ge 0 -and $i -lt $items.Count) { $it = $items[$i] }
        $canDl = ((-not $ctx.Busy) -and ($null -ne $it) -and (-not $it.Downloaded) -and ($null -ne $it.Entry))
        $canDel = ((-not $ctx.Busy) -and ($null -ne $it) -and $it.Downloaded)
        $t.BtnDl.Enabled = $canDl
        $t.BtnDel.Enabled = $canDel
        if ($canDl) {
            $t.BtnDl.ForeColor = $steamUi.Accent
            $t.BtnDl.FlatAppearance.BorderColor = $steamUi.Accent
        } else {
            $t.BtnDl.ForeColor = $steamUi.Muted
            $t.BtnDl.FlatAppearance.BorderColor = $steamUi.Border
        }
    }.GetNewClosure()

    $ctx.RefreshAll = {
        foreach ($k in @($ctx.Tiles.Keys)) { & $ctx.RefreshTile ([string]$k) }
    }.GetNewClosure()

    $ctx.SetBusy = {
        param([bool]$busy)
        $ctx.Busy = $busy
        $ctx.BtnAll.Enabled = (-not $busy)
        $ctx.BtnLatest.Enabled = (-not $busy)
        foreach ($k in @($ctx.Tiles.Keys)) {
            & $ctx.UpdateButtons ([string]$k)
        }
    }.GetNewClosure()

    $ctx.StartRun = {
        param([string]$mode, $jobs)
        if ($ctx.Busy) { return }
        & $ctx.ClearFocus
        try {
            $run = Start-UpscalerWorker $mode $jobs
        } catch {
            $ctx.Status.Text = (T 'upl_check_fail' @($_.Exception.Message))
            return
        }
        $ctx.Run = $run
        $ctx.Mode = $mode
        $ctx.Jobs = $jobs
        & $ctx.SetBusy $true
        if ($mode -eq 'manifest') { $ctx.Status.Text = (T 'upl_checking') }
        $ctx.Timer.Start()
    }.GetNewClosure()

    # Очередь «скачать последние версии» для перечисленных ключей (или для всех, если ключи не заданы).
    $ctx.BuildJob = {
        param($def, $entry)
        $id = New-UpscalerEntryId $entry
        return @{
            Key = [string]$def.Key; Title = [string]$def.Title; Dll = [string]$def.File
            Ver = [string]$entry.ver; Label = [string]$entry.label; Url = [string]$entry.url
            Md5 = [string]$entry.md5; Zmd5 = [string]$entry.zmd5; Id = $id
            FinalDir = (Join-Path (Join-Path (Join-Path (Get-UpscalerStoreRoot) 'files') ([string]$def.Key)) $id)
        }
    }.GetNewClosure()

    # --- Опрос фонового работника (200 мс) ---
    $ctx.Timer = New-Object System.Windows.Forms.Timer
    $ctx.Timer.Interval = 200
    $ctx.Timer.Add_Tick({
        $run = $ctx.Run
        if ($null -eq $run) { $ctx.Timer.Stop(); return }
        $st = $run.State
        if ($ctx.Mode -eq 'download') {
            $tot = @($ctx.Jobs).Count
            $sum = 0
            foreach ($j in @($ctx.Jobs)) {
                $p = 0
                if ($st['Pct'].ContainsKey([string]$j.Key)) { $p = [int]$st['Pct'][[string]$j.Key] }
                $sum += $p
                $tl = $ctx.Tiles[[string]$j.Key]
                if ($null -ne $tl -and -not $st['Done']) {
                    $tl.Status.Text = $glyphDown + ' ' + $p + '%'
                    $tl.Status.ForeColor = $steamUi.Accent
                }
            }
            if ($tot -gt 0) {
                $ctx.Bar.Width = [int][Math]::Floor($ctx.BarBg.Width * ($sum / [double]$tot) / 100.0)
                $ci = [Math]::Min($tot - 1, [int]$st['Index'])
                $cj = @($ctx.Jobs)[$ci]
                $cp = 0
                if ($st['Pct'].ContainsKey([string]$cj.Key)) { $cp = [int]$st['Pct'][[string]$cj.Key] }
                $ctx.Status.Text = (T 'upl_downloading' @(($ci + 1), $tot, [string]$cj.Title, $cp))
            }
        }
        if (-not [bool]$st['Done']) { return }

        $ctx.Timer.Stop()
        try { [void]$run.Ps.EndInvoke($run.Handle) } catch {}
        try { $run.Ps.Dispose() } catch {}
        try { $run.Rs.Dispose() } catch {}
        $mode = $ctx.Mode
        $ctx.Run = $null
        if ($mode -eq 'manifest') {
            if ([bool]$st['Ok']) {
                $ctx.Remote = Get-UpscalerRemote
                $ctx.Status.Text = (T 'upl_checked') + '  ' + (Get-Date).ToString('HH:mm')
            } else {
                $ctx.Status.Text = (T 'upl_check_fail' @([string]$st['Error']))
            }
        } else {
            $okCount = @($st['Finished']).Count
            foreach ($fin in @($st['Finished'])) { Set-UpscalerSelection ([string]$fin['Key']) ([string]$fin['Id']) }
            $errs = @($st['Errors'])
            if ($errs.Count -gt 0) {
                $ctx.Status.Text = (T 'upl_done_err' @($okCount, $errs.Count, [string]$errs[0]))
            } else {
                $ctx.Status.Text = (T 'upl_done' @($okCount))
            }
            $ctx.Bar.Width = 0
        }
        & $ctx.SetBusy $false
        & $ctx.RefreshAll
    }.GetNewClosure())

    # --- Плитки 3×3 ---
    $idx = 0
    foreach ($def in $defs) {
        $key = [string]$def.Key
        $col = $idx % 3
        $row = [int][Math]::Floor($idx / 3)
        $tx = $col * ($tileW + $gapX)
        $ty = $gridTop + $row * ($tileH + $gapY)

        $tile = New-Object System.Windows.Forms.Panel
        $tile.Location = New-Object System.Drawing.Point($tx, $ty)
        $tile.Size = New-Object System.Drawing.Size($tileW, $tileH)
        $tile.BackColor = $container.BackColor
        $container.Controls.Add($tile)

        $lblName = New-Object System.Windows.Forms.Label
        $lblName.Text = [string]$def.Title
        $lblName.Location = New-Object System.Drawing.Point(0, 4)
        $lblName.Size = New-Object System.Drawing.Size(([Math]::Min(70, ($tileW - 96))), 18)
        $lblName.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
        $lblName.ForeColor = $steamUi.Text
        $lblName.BackColor = $container.BackColor
        $lblName.AutoEllipsis = $true
        $tile.Controls.Add($lblName)
        $tip.SetToolTip($lblName, ([string]$def.Tip + ' (' + [string]$def.File + ')'))

        $lblStatus = New-Object System.Windows.Forms.Label
        $lblStatus.Location = New-Object System.Drawing.Point(($tileW - 96), 4)
        $lblStatus.Size = New-Object System.Drawing.Size(96, 18)
        $lblStatus.Font = New-Object System.Drawing.Font('Segoe UI', 8)
        $lblStatus.ForeColor = $steamUi.Muted
        $lblStatus.BackColor = $container.BackColor
        $lblStatus.TextAlign = [System.Drawing.ContentAlignment]::MiddleRight
        $lblStatus.AutoEllipsis = $true
        $tile.Controls.Add($lblStatus)

        $pnlCombo = New-Object System.Windows.Forms.Panel
        $pnlCombo.Location = New-Object System.Drawing.Point(0, 25)
        $pnlCombo.Size = New-Object System.Drawing.Size(($tileW - 56), 24)
        $pnlCombo.BackColor = $steamUi.Input
        $pnlCombo.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
        $tile.Controls.Add($pnlCombo)
        $tip.SetToolTip($pnlCombo, (T 'upl_tip_sel'))

        $cmb = New-Object SmartExeComboBox
        $cmb.Dock = [System.Windows.Forms.DockStyle]::Fill
        $cmb.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
        $cmb.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
        $cmb.ItemHeight = 18
        $cmb.IntegralHeight = $false
        $cmb.MaxDropDownItems = 10
        $cmb.DropDownWidth = 150
        $cmb.BackColor = $steamUi.Input
        $cmb.ForeColor = $steamUi.Text
        $cmb.Font = New-Object System.Drawing.Font('Segoe UI', 9)
        $cmb.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        try { $cmb.BorderColor = $steamUi.Input } catch {}
        [void]$cmb.Items.Add([string][char]0x2014)
        $cmb.SelectedIndex = 0
        $cmb.Locked = $true
        $cmb.Add_DrawItem({
            param($sender, $e)
            if ($e.Index -lt 0) { return }
            $isSel = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
            $isLocked = $false
            try { $isLocked = [bool]$sender.Locked } catch {}
            if ($isLocked) {
                $bg = $steamUi.Input; $fg = $steamUi.Text
                try { if ([string]$sender.Tag -eq 'missing') { $fg = $steamUi.Muted } } catch {}
            } else {
                # Белый текст — версия скачана, серый — ещё нет, зелёный — выбранная в списке версия.
                # Под курсором подсвечивается только фон.
                $bg = if ($isSel) { $steamUi.Border } else { $steamUi.Input }
                $fg = $steamUi.Muted
                try {
                    $mk = @($ctx.Tiles[$key].Marks)
                    if ($e.Index -lt $mk.Count -and [bool]$mk[$e.Index]) { $fg = $steamUi.Text }
                } catch {}
                # Зелёная — только зафиксированная версия ($t.Sel). SelectedIndex при наведении в открытом списке
                # прыгает за курсором, поэтому по нему красить нельзя; закрытое поле показывает именно выбранную.
                try {
                    $isEdit = (($e.State -band [System.Windows.Forms.DrawItemState]::ComboBoxEdit) -ne 0)
                    if ($isEdit) { $fg = $steamUi.Green }
                    else {
                        $tt = $ctx.Tiles[$key]
                        $its = @($tt.Items)
                        if ($e.Index -lt $its.Count -and [string]$its[$e.Index].Id -eq [string]$tt.Sel -and [string]$tt.Sel -ne '') { $fg = $steamUi.Green }
                    }
                } catch {}
            }
            $bgBrush = New-Object System.Drawing.SolidBrush($bg)
            $textBrush = New-Object System.Drawing.SolidBrush($fg)
            try {
                $e.Graphics.FillRectangle($bgBrush, $e.Bounds)
                $text = [string]$sender.Items[$e.Index]
                $textSize = $e.Graphics.MeasureString($text, $sender.Font)
                $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
                $textRect = New-Object System.Drawing.RectangleF([float]($e.Bounds.X + 6), [float]$textY, [float][Math]::Max(10, ($e.Bounds.Width - 8)), [float]$textSize.Height)
                $sf = New-Object System.Drawing.StringFormat
                try {
                    $sf.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter
                    $sf.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap
                    $e.Graphics.DrawString($text, $sender.Font, $textBrush, $textRect, $sf)
                } finally { $sf.Dispose() }
            } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
        }.GetNewClosure())
        $pnlCombo.Controls.Add($cmb)

        $btnDl = New-Object System.Windows.Forms.Button
        $btnDl.Text = $glyphDown
        $btnDl.Font = $symFont
        $btnDl.Location = New-Object System.Drawing.Point(($tileW - 52), 25)
        $btnDl.Size = New-Object System.Drawing.Size(24, 24)
        $btnDl.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $btnDl.FlatAppearance.BorderColor = $steamUi.Border
        $btnDl.FlatAppearance.MouseOverBackColor = $steamUi.Accent2
        $btnDl.BackColor = $steamUi.Panel2
        $btnDl.ForeColor = $steamUi.Accent
        $btnDl.Padding = New-Object System.Windows.Forms.Padding(0)
        $btnDl.TabStop = $false
        $btnDl.Cursor = [System.Windows.Forms.Cursors]::Hand
        $tip.SetToolTip($btnDl, (T 'upl_tip_dl'))
        $tile.Controls.Add($btnDl)

        $btnDel = New-Object System.Windows.Forms.Button
        $btnDel.Text = $glyphDel
        $btnDel.Font = $symFont
        $btnDel.Location = New-Object System.Drawing.Point(($tileW - 24), 25)
        $btnDel.Size = New-Object System.Drawing.Size(24, 24)
        $btnDel.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $btnDel.FlatAppearance.BorderColor = $steamUi.Border
        $btnDel.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(150, 56, 56)
        $btnDel.BackColor = $steamUi.Panel2
        $btnDel.ForeColor = $steamUi.Muted
        $btnDel.Padding = New-Object System.Windows.Forms.Padding(0)
        $btnDel.TabStop = $false
        $btnDel.Cursor = [System.Windows.Forms.Cursors]::Hand
        $tip.SetToolTip($btnDel, (T 'upl_tip_del'))
        $tile.Controls.Add($btnDel)

        $lblInfo = New-Object System.Windows.Forms.Label
        $lblInfo.Location = New-Object System.Drawing.Point(0, 51)
        $lblInfo.Size = New-Object System.Drawing.Size($tileW, 14)
        $lblInfo.Font = New-Object System.Drawing.Font('Segoe UI', 7.5)
        $lblInfo.Visible = $false   # размер и число версий убраны с плитки (экономия места)
        $lblInfo.ForeColor = $steamUi.Muted
        $lblInfo.BackColor = $container.BackColor
        $lblInfo.AutoEllipsis = $true
        $tile.Controls.Add($lblInfo)

        $ctx.Tiles[$key] = @{ Tile = $tile; Status = $lblStatus; Combo = $cmb; BtnDl = $btnDl; BtnDel = $btnDel; Info = $lblInfo; Local = @(); Items = @(); Marks = @(); Sel = '' }

        # Выбор в списке: скачанная версия становится версией по умолчанию,
        # нескачанную можно загрузить кнопкой ↓.
        $cmb.Add_SelectionChangeCommitted({
            try {
                $t = $ctx.Tiles[$key]
                $its = @($t.Items)
                $i = $t.Combo.SelectedIndex
                if ($i -ge 0 -and $i -lt $its.Count) {
                    $it = $its[$i]
                    $t.Sel = [string]$it.Id
                    if ($it.Downloaded) { Set-UpscalerSelection $key ([string]$it.Id) }
                    & $ctx.RefreshTile $key
                }
            } catch {}
            & $ctx.ClearFocus
        }.GetNewClosure())
        $cmb.Add_DropDownClosed({ & $ctx.ClearFocus }.GetNewClosure())

        # ↓ — скачать выбранную в списке версию (кнопка активна, только если её нет на диске).
        $btnDl.Add_Click({
            & $ctx.ClearFocus
            try {
                if ($ctx.Busy) { return }
                $df = $defByKey[$key]
                $t = $ctx.Tiles[$key]
                $its = @($t.Items)
                $i = $t.Combo.SelectedIndex
                if ($i -lt 0 -or $i -ge $its.Count) { return }
                $it = $its[$i]
                if ($it.Downloaded -or $null -eq $it.Entry) { return }
                $job = & $ctx.BuildJob $df $it.Entry
                $jobList = New-Object System.Collections.ArrayList
                [void]$jobList.Add($job)
                & $ctx.StartRun 'download' $jobList
            } catch {
                $ctx.Status.Text = [string]$_.Exception.Message
            }
        }.GetNewClosure())

        # ✕ — удалить выбранную версию с диска (активна, только если она скачана).
        $btnDel.Add_Click({
            & $ctx.ClearFocus
            try {
                if ($ctx.Busy) { return }
                $df = $defByKey[$key]
                $t = $ctx.Tiles[$key]
                $its = @($t.Items)
                $i = $t.Combo.SelectedIndex
                if ($i -lt 0 -or $i -ge $its.Count) { return }
                $cur = $its[$i]
                if (-not $cur.Downloaded) { return }
                $ok = Show-ThemedConfirm $owner $global:appTitle (T 'upl_confirm_del' @([string]$df.Title, [string]$cur.Text))
                if (-not $ok) { return }
                [void](Remove-UpscalerLocalVersion $key ([string]$cur.Id))
                $sel = Get-UpscalerSelection
                if ($sel.ContainsKey($key) -and [string]$sel[$key] -eq [string]$cur.Id) { Set-UpscalerSelection $key '' }
                & $ctx.RefreshTile $key
            } catch {
                $ctx.Status.Text = [string]$_.Exception.Message
            }
        }.GetNewClosure())

        $idx++
    }

    # --- Прогресс и статус (под сеткой) ---
    $statusTop = $gridTop + 3 * $tileH + 2 * $gapY + 6
    $rowY = $statusTop + 13
    $barBg = New-Object System.Windows.Forms.Panel
    $barBg.Location = New-Object System.Drawing.Point(0, $statusTop)
    $barBg.Size = New-Object System.Drawing.Size($W, 5)
    # Фон полосы прогресса совпадает с фоном окна: тёмной дорожки под плитками нет, виден только сам прогресс при скачивании.
    $barBg.BackColor = $container.BackColor
    $container.Controls.Add($barBg)
    $bar = New-Object System.Windows.Forms.Panel
    $bar.Location = New-Object System.Drawing.Point(0, 0)
    $bar.Size = New-Object System.Drawing.Size(0, 5)
    $bar.BackColor = $steamUi.Accent
    $barBg.Controls.Add($bar)
    $ctx.BarBg = $barBg
    $ctx.Bar = $bar

    $status = New-Object System.Windows.Forms.Label
    # Статус — в одной строке с кнопками, правее них.
    $status.Location = New-Object System.Drawing.Point((140 + 6 + 112 + 6 + 34 + 10), $rowY)
    $status.Size = New-Object System.Drawing.Size(($W - (140 + 6 + 112 + 6 + 34 + 10)), 28)
    $status.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $status.ForeColor = $steamUi.Muted
    $status.Font = New-Object System.Drawing.Font('Segoe UI', 8)
    $status.AutoEllipsis = $true
    $container.Controls.Add($status)
    $ctx.Status = $status

    # --- Кнопки «Выбрать последние» и «Обновить все» — внизу слева, под плитками ---
    $btnAll = New-Object System.Windows.Forms.Button
    $btnAll.Text = (T 'upl_update_all')
    $btnAll.Size = New-Object System.Drawing.Size(112, 28)
    $btnAll.Location = New-Object System.Drawing.Point((140 + 6), $rowY)
    $btnAll.FlatStyle = 'Flat'
    $btnAll.FlatAppearance.BorderColor = $steamUi.Border
    $btnAll.BackColor = $steamUi.Panel
    $btnAll.ForeColor = $steamUi.Text
    $btnAll.TabStop = $false
    $btnAll.Cursor = [System.Windows.Forms.Cursors]::Hand
    $container.Controls.Add($btnAll)
    $ctx.BtnAll = $btnAll

    $tip.SetToolTip($btnAll, (T 'upl_tip_all'))

    # Кнопка папки — сразу правее «Обновить все», той же высоты, что и остальные кнопки.
    $btnFolder.Size = New-Object System.Drawing.Size(34, 28)
    $btnFolder.Location = New-Object System.Drawing.Point((140 + 6 + 112 + 6), $rowY)

    $btnLatest = New-Object System.Windows.Forms.Button
    $btnLatest.Text = (T 'upl_select_latest')
    $btnLatest.Size = New-Object System.Drawing.Size(140, 28)
    $btnLatest.Location = New-Object System.Drawing.Point(0, $rowY)
    $btnLatest.FlatStyle = 'Flat'
    $btnLatest.FlatAppearance.BorderColor = $steamUi.Border
    $btnLatest.BackColor = $steamUi.Panel
    $btnLatest.ForeColor = $steamUi.Text
    $btnLatest.TabStop = $false
    $btnLatest.Cursor = [System.Windows.Forms.Cursors]::Hand
    $container.Controls.Add($btnLatest)
    $ctx.BtnLatest = $btnLatest
    $tip.SetToolTip($btnLatest, (T 'upl_tip_latest'))

    # «Выбрать последние»: в каждой библиотеке версией по умолчанию становится самая новая из скачанных.
    $btnLatest.Add_Click({
        & $ctx.ClearFocus
        try {
            if ($ctx.Busy) { return }
            $changed = 0
            $sel = Get-UpscalerSelection
            foreach ($df in $defs) {
                $k = [string]$df.Key
                $t = $ctx.Tiles[$k]
                $loc = @($t.Local)
                if ($loc.Count -eq 0) { continue }
                $newest = $null
                foreach ($it in @($t.Items)) { if ($it.Downloaded) { $newest = $it; break } }
                if ($null -eq $newest) { continue }
                $curId = [string]$loc[0].Id
                if ($sel.ContainsKey($k)) {
                    foreach ($lv2 in $loc) { if ([string]$lv2.Id -eq [string]$sel[$k]) { $curId = [string]$lv2.Id; break } }
                }
                if ($curId -ne [string]$newest.Id) {
                    Set-UpscalerSelection $k ([string]$newest.Id)
                    $changed++
                }
                $t.Sel = ''
            }
            & $ctx.RefreshAll
            if ($changed -gt 0) { $ctx.Status.Text = (T 'upl_latest_done' @($changed)) }
            else { $ctx.Status.Text = (T 'upl_latest_same') }
        } catch { $ctx.Status.Text = [string]$_.Exception.Message }
    }.GetNewClosure())

    $btnAll.Add_Click({
        & $ctx.ClearFocus
        try {
            if ($ctx.Busy) { return }
            if ($null -eq $ctx.Remote) { & $ctx.StartRun 'manifest' @(); return }
            $jobs = New-Object System.Collections.ArrayList
            foreach ($df in $defs) {
                $entries = @(Get-UpscalerRemoteEntries $ctx.Remote $df)
                if ($entries.Count -eq 0) { continue }
                $latest = $entries[0]
                $loc = @($ctx.Tiles[[string]$df.Key].Local)
                $latestNum = ConvertTo-UpscalerVersionObj ([string]$latest.ver)
                # Скачиваем, если на диске нет версии не ниже последней.
                if ($loc.Count -gt 0 -and $loc[0].Num -ge $latestNum) { continue }
                [void]$jobs.Add((& $ctx.BuildJob $df $latest))
            }
            if ($jobs.Count -eq 0) { $ctx.Status.Text = (T 'upl_all_actual'); return }
            & $ctx.StartRun 'download' $jobs
        } catch { $ctx.Status.Text = [string]$_.Exception.Message }
    }.GetNewClosure())

    # --- Первое заполнение: сначала сразу показываем кэш манифеста, затем при каждом открытии
    #     настроек в фоне проверяем список версий заново ---
    $ctx.Remote = Get-UpscalerRemote
    & $ctx.RefreshAll
    & $ctx.StartRun 'manifest' @()

    $container.Add_Disposed({
        try {
            $ctx.Timer.Stop()
            if ($null -ne $ctx.Run) {
                $ctx.Run.State['Cancel'] = $true
                try { $ctx.Run.Ps.Dispose() } catch {}
                try { $ctx.Run.Rs.Dispose() } catch {}
            }
            $ctx.Timer.Dispose()
        } catch {}
    }.GetNewClosure())
}

function Add-EmulatorsManagerControls ($owner, $container) {
    # Список эмуляторов оформлен в стиле остального приложения (тёмный фон,
    # без сетки, свой заголовок), а не стандартной белой таблицей Windows —
    # для этого ListView рисуется вручную (OwnerDraw), иначе и заголовок, и
    # линии сетки, и фон всегда остаются нативными белыми независимо от
    # BackColor/ForeColor. Список только для просмотра/редактирования профилей
    # эмуляторов (Добавить/Изменить/Удалить) — выбор активного эмулятора здесь
    # не отображается и не производится, это делается только на главном экране
    # при включённом режиме ROM.
    # Кнопки ниже (Добавить/Изменить/Удалить) — того же размера (90×30), что
    # и остальные вспомогательные кнопки окна настроек (например, «Обзор» у
    # пути к Steam, «Обновить» у ключа Steam Web API, а теперь и «Обзор»/
    # «Создать бэкап»/«Восстановить» слева), выровнены по правому краю таблицы
    # и стоят на фиксированном отступе (10px) от низа этой панели. Сама панель
    # (см. $pnlRomsManager выше) подобрана по высоте так, чтобы нижний край
    # ИМЕННО ТАБЛИЦЫ эмуляторов (а не панели целиком) совпадал по Y с нижним
    # краем таблицы бэкапов слева — поэтому ряд кнопок оказывается под этой
    # таблицей, уже за пределами уровня таблицы бэкапов.
    $btnEmuWidth = 90
    $btnEmuHeight = 28
    $btnEmuGap = 8
    $btnRowTop = $container.ClientSize.Height - 10 - $btnEmuHeight
    # 13px — тот же отступ, что и между таблицей бэкапов и рядом кнопок под
    # ней слева («Обзор…»/«Создать бэкап»), чтобы расстояние от таблицы до
    # кнопок было одинаковым по обе стороны.
    $listBottomGap = 13

    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = New-Object System.Drawing.Point(0, 0)
    $lv.Size = New-Object System.Drawing.Size($container.ClientSize.Width, ($btnRowTop - $listBottomGap))
    # Список снова растягивается на всю высоту колонки (кроме строки кнопок).
    $lv.Anchor = [System.Windows.Forms.AnchorStyles]::Top -bor [System.Windows.Forms.AnchorStyles]::Left -bor `
                 [System.Windows.Forms.AnchorStyles]::Right -bor [System.Windows.Forms.AnchorStyles]::Bottom
    $lv.View = [System.Windows.Forms.View]::Details
    $lv.FullRowSelect = $true
    $lv.GridLines = $false
    $lv.MultiSelect = $false
    $lv.HideSelection = $false
    $lv.HeaderStyle = [System.Windows.Forms.ColumnHeaderStyle]::Clickable
    $lv.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $lv.BackColor = $steamUi.Input
    $lv.ForeColor = $steamUi.Text
    $lv.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $colName = 120; $colFile = 150; $colExt = 90
    $colArgs = [System.Math]::Max(100, ($container.ClientSize.Width - $colName - $colFile - $colExt))
    [void]$lv.Columns.Add((T 'emu_col_name'), $colName)
    [void]$lv.Columns.Add((T 'col_file'), $colFile)
    [void]$lv.Columns.Add((T 'emu_col_ext'), $colExt)
    [void]$lv.Columns.Add((T 'emu_col_args'), $colArgs)
    $container.Controls.Add($lv)

    # Горизонтальной прокрутки быть не должно: последняя колонка занимает ровно остаток
    # ширины (с учётом вертикальной полосы, если она есть), а нативная горизонтальная полоса прячется.
    $fitEmuColumns = {
        try {
            if ($lv.Columns.Count -lt 2) { return }
            $used = 0
            for ($ci = 0; $ci -lt ($lv.Columns.Count - 1); $ci++) { $used += [int]$lv.Columns[$ci].Width }
            $avail = [int]$lv.ClientSize.Width - $used
            if ($avail -lt 60) { $avail = 60 }
            $last = $lv.Columns[$lv.Columns.Count - 1]
            if ([int]$last.Width -ne $avail) { $last.Width = $avail }
        } catch {}
        try { [Win32ScrollBarHelper]::HideHorizontal($lv.Handle) } catch {}
    }.GetNewClosure()
    $lv.Add_Resize({ & $fitEmuColumns }.GetNewClosure())
    $lv.Add_HandleCreated({ & $fitEmuColumns }.GetNewClosure())
    $lv.Add_ColumnWidthChanged({ & $fitEmuColumns }.GetNewClosure())

    # Сортировка по клику на заголовок колонки (Название/Файл/Расширения/Аргументы):
    # повторный клик по той же колонке переключает направление (по возрастанию /
    # по убыванию), клик по другой колонке начинает сортировку заново по ней.
    $lvSorter = New-Object ListViewColumnSorter
    # По умолчанию список отсортирован по названию (первая колонка), по возрастанию.
    $lvSorter.SortColumn = 0
    $lvSorter.Order = [System.Windows.Forms.SortOrder]::Ascending
    $lv.ListViewItemSorter = $lvSorter

    # Полностью своя отрисовка: нативный светлый заголовок и белый фон строк
    # иначе не убрать никакими цветовыми свойствами ListView.
    $lv.OwnerDraw = $true
    $drawColumnHeaderHandler = {
        param($s, $e)
        $e.Graphics.FillRectangle((New-Object System.Drawing.SolidBrush($steamUi.Panel2)), $e.Bounds)
        $borderPen = New-Object System.Drawing.Pen($steamUi.Border)
        $e.Graphics.DrawLine($borderPen, $e.Bounds.Left, $e.Bounds.Bottom - 1, $e.Bounds.Right, $e.Bounds.Bottom - 1)
        $borderPen.Dispose()
        if (-not [string]::IsNullOrEmpty($e.Header.Text)) {
            $headerText = $e.Header.Text
            if ($lvSorter -ne $null -and $lvSorter.SortColumn -eq $e.Header.Index -and $lvSorter.Order -ne [System.Windows.Forms.SortOrder]::None) {
                $arrow = if ($lvSorter.Order -eq [System.Windows.Forms.SortOrder]::Ascending) { ' ^' } else { ' v' }
                $headerText = $headerText + $arrow
            }
            $sf = New-Object System.Drawing.StringFormat
            $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
            $textRect = New-Object System.Drawing.RectangleF(($e.Bounds.X + 6), $e.Bounds.Y, ($e.Bounds.Width - 8), $e.Bounds.Height)
            $e.Graphics.DrawString($headerText, $lv.Font, (New-Object System.Drawing.SolidBrush($steamUi.Muted)), $textRect, $sf)
        }
        $e.DrawDefault = $false
    }.GetNewClosure()
    $lv.Add_DrawColumnHeader($drawColumnHeaderHandler)
    $lv.Add_DrawItem({
        param($s, $e)
        $e.DrawDefault = $false
    })
    $lv.Add_DrawSubItem({
        param($s, $e)
        $bg = if ($e.Item.Selected) { $steamUi.Selected } else { $steamUi.Input }
        $e.Graphics.FillRectangle((New-Object System.Drawing.SolidBrush($bg)), $e.Bounds)
        # Список в «Настройках» больше не показывает и не выбирает активный
        # эмулятор (это делается только на главном экране при включённом
        # режиме ROM) — весь текст строки одного цвета, без акцентной подсветки.
        $fg = $steamUi.Text
        $sf = New-Object System.Drawing.StringFormat
        $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
        $sf.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter
        $sf.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap
        $textRect = New-Object System.Drawing.RectangleF(($e.Bounds.X + 6), $e.Bounds.Y, ($e.Bounds.Width - 8), $e.Bounds.Height)
        $e.Graphics.DrawString($e.SubItem.Text, $e.Item.Font, (New-Object System.Drawing.SolidBrush($fg)), $textRect, $sf)
    })

    $reloadList = {
        $lv.Items.Clear()
        foreach ($ep in @($global:emulatorProfiles)) {
            # ВАЖНО: New-Object ...ListViewItem(@(a,b,c,d)) — известная ловушка
            # PowerShell: массив из 4 строк разворачивается в 4 отдельных
            # аргумента конструктора, а у ListViewItem нет перегрузки с 4
            # параметрами (есть только ListViewItem(string[] items) — ОДИН
            # аргумент-массив). Из-за этого New-Object не находил перегрузку и
            # падал с "Не удаётся найти перегрузку... количество аргументов: 4"
            # каждый раз, когда в списке был хотя бы один эмулятор (при 0
            # эмуляторах foreach не выполнялся, поэтому баг не проявлялся сразу
            # при первом запуске). Собираем элемент так же, как везде в файле —
            # без конструктора с массивом.
            $item = New-Object System.Windows.Forms.ListViewItem([string]$ep.Name)
            [void]$item.SubItems.Add([string]$ep.ExePath)
            [void]$item.SubItems.Add([string]$ep.Extensions)
            [void]$item.SubItems.Add([string]$ep.Args)
            $item.Tag = $ep.Id
            [void]$lv.Items.Add($item)
        }
        # Сортировка (по умолчанию — по названию) должна сохраняться и после
        # перезагрузки списка: добавление/изменение/удаление эмулятора не
        # должно сбрасывать текущий выбранный столбец/направление сортировки.
        if ($lvSorter -ne $null) { $lv.Sort() }
        & $fitEmuColumns
    }.GetNewClosure()
    # ВАЖНО: без .GetNewClosure() здесь $reloadList — обычный скриптблок, который
    # прекрасно видит $lv, пока вызывается напрямую (как строкой ниже). Но кнопки
    # Добавить/Изменить/Удалить сами обёрнуты в .GetNewClosure() (чтобы видеть
    # $owner), и вызов "& $reloadList" ИЗ ТАКОГО изолированного замыкания уже не
    # находит $lv — отсюда и была ошибка "Невозможно вызвать метод для выражения
    # со значением NULL" на $lv.Items.Clear(). Замыкание на $reloadList делает его
    # самодостаточным и рабочим независимо от того, откуда его вызвали.
    & $reloadList
    & $fitEmuColumns

    # Список в «Настройках» больше не выбирает активный эмулятор — выбор строки
    # здесь используется только кнопками «Изменить»/«Удалить» ниже. Активный
    # эмулятор выбирается исключительно на главном экране при включённом
    # режиме ROM.

    $columnClickHandler = {
        param($s, $e)
        try {
            if ($lvSorter -eq $null) { return }
            if ($lvSorter.SortColumn -eq $e.Column) {
                # Повторный клик по той же колонке — меняем направление сортировки.
                if ($lvSorter.Order -eq [System.Windows.Forms.SortOrder]::Ascending) {
                    $lvSorter.Order = [System.Windows.Forms.SortOrder]::Descending
                } else {
                    $lvSorter.Order = [System.Windows.Forms.SortOrder]::Ascending
                }
            } else {
                $lvSorter.SortColumn = $e.Column
                $lvSorter.Order = [System.Windows.Forms.SortOrder]::Ascending
            }
            $lv.Sort()
            $lv.Invalidate()
        } catch {
            Show-AppMessageBox($owner, ((T 'emu_err_sort') + "`r`n$($_.Exception.Message)"), $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    }.GetNewClosure()
    $lv.Add_ColumnClick($columnClickHandler)

    $btnAnchorBottomRight = [System.Windows.Forms.AnchorStyles]::Bottom -bor [System.Windows.Forms.AnchorStyles]::Right

    $btnAddEmu = New-Object System.Windows.Forms.Button
    $btnAddEmu.Text = (T 'emu_btn_add')
    $btnAddEmu.Location = New-Object System.Drawing.Point(($container.ClientSize.Width - 3 * $btnEmuWidth - 2 * $btnEmuGap), $btnRowTop)
    $btnAddEmu.Size = New-Object System.Drawing.Size($btnEmuWidth, $btnEmuHeight)
    $btnAddEmu.Anchor = $btnAnchorBottomRight
    $btnAddEmu.FlatStyle = 'Flat'
    $btnAddEmu.FlatAppearance.BorderColor = $steamUi.Border
    $btnAddEmu.BackColor = $steamUi.Panel
    $btnAddEmu.ForeColor = $steamUi.Text
    $btnAddEmu.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnAddEmu.Add_Click({
        try {
            $newProfile = Show-EmulatorEditDialog $owner $null
            if ($newProfile -ne $null) {
                $global:emulatorProfiles = @($global:emulatorProfiles) + $newProfile
                if ([string]::IsNullOrWhiteSpace([string]$global:activeEmulatorId)) { $global:activeEmulatorId = [string]$newProfile.Id }
                try { [void](Save-EmulatorIconCache $newProfile) } catch {}
                Save-Configuration
                & $reloadList
                try { Update-RomEmulatorIndicator } catch {}
            }
        } catch {
            # ВРЕМЕННАЯ ДИАГНОСТИКА: раньше исключение здесь вылетало необработанным
            # (крах всего приложения, окно JIT-отладки без номера строки). Показываем
            # текст и место ошибки, чтобы найти точную причину, не гадая вслепую.
            Show-AppMessageBox($owner, ((T 'emu_err_add') + "`r`n$($_.Exception.Message)`r`n`r`n$($_.InvocationInfo.PositionMessage)"), $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    }.GetNewClosure())
    $container.Controls.Add($btnAddEmu)

    $btnEditEmu = New-Object System.Windows.Forms.Button
    $btnEditEmu.Text = (T 'emu_btn_edit')
    $btnEditEmu.Location = New-Object System.Drawing.Point(($container.ClientSize.Width - 2 * $btnEmuWidth - $btnEmuGap), $btnRowTop)
    $btnEditEmu.Size = New-Object System.Drawing.Size($btnEmuWidth, $btnEmuHeight)
    $btnEditEmu.Anchor = $btnAnchorBottomRight
    $btnEditEmu.FlatStyle = 'Flat'
    $btnEditEmu.FlatAppearance.BorderColor = $steamUi.Border
    $btnEditEmu.BackColor = $steamUi.Panel
    $btnEditEmu.ForeColor = $steamUi.Text
    $btnEditEmu.Cursor = [System.Windows.Forms.Cursors]::Hand
    $editSelectedEmulator = {
        try {
            if ($lv.SelectedItems.Count -eq 0) { return }
            $selId = [string]$lv.SelectedItems[0].Tag
            $existingProfile = $null
            foreach ($ep in @($global:emulatorProfiles)) { if ([string]$ep.Id -eq $selId) { $existingProfile = $ep; break } }
            if ($existingProfile -eq $null) { return }
            $updatedProfile = Show-EmulatorEditDialog $owner $existingProfile
            if ($updatedProfile -ne $null) {
                $global:emulatorProfiles = @($global:emulatorProfiles | ForEach-Object { if ([string]$_.Id -eq $selId) { $updatedProfile } else { $_ } })
                try { [void](Save-EmulatorIconCache $updatedProfile) } catch {}
                Save-Configuration
                & $reloadList
                try { Update-RomEmulatorIndicator } catch {}
            }
        } catch {
            # См. комментарий в btnAddEmu.Add_Click — та же временная диагностика.
            Show-AppMessageBox($owner, ((T 'emu_err_edit') + "`r`n$($_.Exception.Message)`r`n`r`n$($_.InvocationInfo.PositionMessage)"), $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    }.GetNewClosure()
    $btnEditEmu.Add_Click($editSelectedEmulator)
    $container.Controls.Add($btnEditEmu)

    $btnRemoveEmu = New-Object System.Windows.Forms.Button
    $btnRemoveEmu.Text = (T 'emu_btn_remove')
    $btnRemoveEmu.Location = New-Object System.Drawing.Point(($container.ClientSize.Width - $btnEmuWidth), $btnRowTop)
    $btnRemoveEmu.Size = New-Object System.Drawing.Size($btnEmuWidth, $btnEmuHeight)
    $btnRemoveEmu.Anchor = $btnAnchorBottomRight
    $btnRemoveEmu.FlatStyle = 'Flat'
    $btnRemoveEmu.FlatAppearance.BorderColor = $steamUi.Border
    $btnRemoveEmu.BackColor = $steamUi.Panel
    $btnRemoveEmu.ForeColor = $steamUi.Text
    $btnRemoveEmu.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnRemoveEmu.Add_Click({
        if ($lv.SelectedItems.Count -eq 0) { return }
        $selId = [string]$lv.SelectedItems[0].Tag
        $confirmed = Show-ThemedConfirm $owner $global:appTitle (T 'emu_confirm_remove')
        if (-not $confirmed) { return }
        $global:emulatorProfiles = @($global:emulatorProfiles | Where-Object { [string]$_.Id -ne $selId })
        if ([string]$global:activeEmulatorId -eq $selId) { $global:activeEmulatorId = '' }
        try { Remove-EmulatorIconCache $selId } catch {}
        Save-Configuration
        & $reloadList
        try { Update-RomEmulatorIndicator } catch {}
    }.GetNewClosure())
    $container.Controls.Add($btnRemoveEmu)

    # У ListView нет прямого способа "вызвать обработчик клика кнопки" —
    # двойной клик по строке дублирует логику «Изменить» напрямую.
    $lv.Add_MouseDoubleClick($editSelectedEmulator)
}

function Show-ProgramSettingsDialog {
    # Подхватываем правки файлов локализации, сделанные за время работы программы.
    $langReloaded = $false
    try { $langReloaded = [bool](Initialize-Localization) } catch {}
    if ($langReloaded) { try { Apply-Localization } catch {} }
    if (-not $script:langProblemsReported -and $script:langProblems.Count -gt 0) {
        $script:langProblemsReported = $true
        try {
            $shownProblems = @($script:langProblems | Select-Object -First 15)
            $problemText = (T 'lang_problems') + "`r`n`r`n" + ($shownProblems -join "`r`n")
            if ($script:langProblems.Count -gt 15) { $problemText += "`r`n…" }
            Show-AppMessageBox($problemText, (T 'settings_title'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
        } catch {}
    }
    $originalSteamInstallPath = [string]$global:steamInstallPath
    $originalSteamUserId = [string]$global:steamUserId
    $originalSuggestGameLaunchers = [bool]$global:suggestGameLaunchers
    $originalUseExeIcons = [bool]$global:useExeIcons
    # ВАЖНО: обработчики событий (Add_Click/Add_FormClosed) выполняются в дочерней
    # области видимости, и простое присваивание `$settingsAccepted = $true` внутри
    # обработчика создавало бы ЛОКАЛЬНУЮ копию переменной — родительская осталась
    # бы $false. Из-за этого после «Сохранить» FormClosed считал, что диалог
    # отменён, и откатывал флаги валидности ключей (и путь/профиль Steam) к
    # состоянию на момент открытия. Хэштаблица изменяется по ссылке, поэтому
    # значение видно во всех обработчиках.
    $settingsState = @{ Accepted = $false; ButtonClose = $false; ExitRequested = $false }

    # Проверка ключей при запуске идёт в фоне — здесь результат уже нужен.
    try { Complete-StartupKeyChecks -Wait } catch {}

    # БАГ-ФИКС: результат проверки ключей (Valid/Check) менялся "живьём" при
    # каждом изменении текста в полях (см. Add_TextChanged/таймеры ниже), даже
    # если диалог потом закрывали без сохранения. Сам текст ключа откатывался
    # по кнопке "Отмена" корректно, а вот флаг валидности — нет, поэтому при
    # повторном открытии значок статуса не соответствовал сохранённому ключу.
    # Запоминаем исходное состояние ПОСЛЕ ожидания фоновой проверки (иначе тут
    # был бы захвачен ещё не готовый, устаревший результат) и восстанавливаем
    # его при отмене.
    $originalSgdbKeyValid = [bool]$global:steamGridDbApiKeyValid
    $originalSgdbKeyCheck = $global:steamGridDbApiKeyCheck
    $originalSteamKeyValid = [bool]$global:steamApiKeyValid
    $originalSteamKeyCheck = $global:steamApiKeyCheck

    # Окно настроек должно открываться ВМЕСТО главного окна, а не поверх
    # него: прячем главное окно на время показа диалога и возвращаем его
    # после закрытия (см. $dlg.ShowDialog() ниже). При самом первом запуске
    # (когда настройки открываются автоматически ещё до $form.ShowDialog())
    # главное окно ещё не видно — тогда прятать/показывать его не нужно.
    $mainFormWasVisible = ($form -ne $null) -and $form.Visible
    # Бесшовный переход (как у библиотеки): главное окно не прячем, а настройки открываем поверх него —
    # окно настроек строится невидимым (Opacity = 0), затем в Add_Shown появляется ровно по центру главного,
    # а главное становится прозрачным (но остаётся владельцем и единственной кнопкой на панели задач).
    # Закрытие настроек возвращает главное окно в $dlg.Add_FormClosing, пока настройки ещё на экране.
    # Если главное окно свёрнуто — работаем по-старому: прячем и потом показываем.
    $settingsSeamless = $false
    try { $settingsSeamless = $mainFormWasVisible -and ($form.WindowState -eq [System.Windows.Forms.FormWindowState]::Normal) } catch {}
    if ($settingsSeamless) {
        try { $form.UseWaitCursor = $true; [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::WaitCursor } catch {}
    } elseif ($mainFormWasVisible) { try { $form.Hide() } catch {} }

    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = (T 'settings_title')
    $dlg.StartPosition = 'CenterScreen'
    $dlg.FormBorderStyle = 'FixedSingle'
    $dlg.MaximizeBox = $false
    $dlg.MinimizeBox = $false
    try { if ($null -ne $form -and $null -ne $form.Icon) { $dlg.Icon = $form.Icon } } catch {}
    if ($settingsSeamless) {
        # Одна кнопка программы на панели задач; пустой кадр не показываем — окно появляется после построения.
        $dlg.ShowInTaskbar = $false
        $dlg.Opacity = 0
        try {
            $dbFlags = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
            [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $dbFlags).SetValue($dlg, $true, $null)
        } catch {}
    }
    # Окно настроек — две колонки одинаковой ширины: слева обычные настройки
    # (без изменений, все координаты внутри неё как были — 0..560), справа —
    # панель управления эмуляторами для режима ROMs (тот же список, что раньше
    # открывался отдельным диалогом по кнопке; кнопка была криво расположена
    # прямо поверх заголовка «Steam» и выглядела как «полоска» — вместо
    # починки позиции список сразу встроен в окно настроек, как просил пользователь).
    # Окно настроек — ровно по размеру главного (клиентская область 1080x700), чтобы открываться поверх него
    # без скачка размера. Левая колонка: содержимое x=20..520; зазор 40; правая: x=560..1060; справа поле 20.
    # Высота фиксированная: подсказки к ключам занимают место по мере необходимости, а список бэкапов
    # забирает/отдаёт остаток (см. $applySettingsLayout).
    $script:settingsLeftColumnWidth = 520
    $script:settingsColumnGap = 40
    $script:settingsRightColumnWidth = 520
    $script:settingsDialogWidth = $script:settingsLeftColumnWidth + $script:settingsColumnGap + $script:settingsRightColumnWidth
    $script:settingsDialogHeight = 700
    $dlg.ClientSize = New-Object System.Drawing.Size($script:settingsDialogWidth, $script:settingsDialogHeight)
    $dlg.BackColor = $steamUi.Bg
    $dlg.ForeColor = $steamUi.Text
    $dlg.Font = New-Object System.Drawing.Font('Segoe UI', 9)

    $title = New-Object System.Windows.Forms.Label
    $title.Text = (T 'settings_title')
    $title.Location = New-Object System.Drawing.Point(20, 16)
    $title.Size = New-Object System.Drawing.Size(300, 30)
    $title.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 16)
    $title.ForeColor = $steamUi.Text
    $dlg.Controls.Add($title)

    # Выбор языка интерфейса — справа от заголовка. Применяется по кнопке «Сохранить» (окно при этом не закрывается, а переводится на месте).
    # Обёрнут в Panel с рамкой (как $pnlExe/$pnlRom у карточки игры) — у самого
    # ComboBox системная рамка снята, а тип SmartExeComboBox (с отключением темы
    # через SetWindowTheme) убирает нативную светлую отрисовку стрелки и списка;
    # иначе они оставались бы белыми независимо от BackColor/ForeColor — тот же
    # приём, что и в диалоге выбора эмулятора/ROM.
    $pnlLanguage = New-Object System.Windows.Forms.Panel
    $pnlLanguage.Location = New-Object System.Drawing.Point(336, 20)
    $pnlLanguage.Size = New-Object System.Drawing.Size(150, 28)
    $pnlLanguage.BackColor = $steamUi.Input
    $pnlLanguage.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($pnlLanguage)

    $cmbLanguage = New-Object SmartExeComboBox
    $cmbLanguage.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbLanguage.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbLanguage.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbLanguage.ItemHeight = 20
    $cmbLanguage.DropDownHeight = 200
    $cmbLanguage.IntegralHeight = $false
    $cmbLanguage.BackColor = $steamUi.Input
    $cmbLanguage.ForeColor = $steamUi.Text
    $cmbLanguage.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    try { $cmbLanguage.BorderColor = $steamUi.Input } catch {}
    foreach ($langItem in $script:languageList) { [void]$cmbLanguage.Items.Add([string]$langItem.Name) }
    for ($li = 0; $li -lt $script:languageList.Count; $li++) {
        if ($script:languageList[$li].Code -eq [string]$global:language) { $cmbLanguage.SelectedIndex = $li }
    }
    $pnlLanguage.Controls.Add($cmbLanguage)
    $cmbLanguage.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
        $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            # Текст рисуем через TextRenderer (как в TextBox): тот же отступ слева (12 px), что у полей ввода,
            # и точное вертикальное центрирование.
            $ctFlags = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
            $ctRect = New-Object System.Drawing.Rectangle(($e.Bounds.X + 12), $e.Bounds.Y, [Math]::Max(10, $e.Bounds.Width - 12 - 4), $e.Bounds.Height)
            [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $text, $sender.Font, $ctRect, $fg, $ctFlags)
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })
    $langToolTip = New-Object System.Windows.Forms.ToolTip
    $langToolTip.SetToolTip($cmbLanguage, 'Язык / Language / 语言 / Idioma / Sprache')

    # Кнопка «папка языков»: файлы <код>.lang можно править и добавлять свои.
    $btnLangFolder = New-Object System.Windows.Forms.Button
    $btnLangFolder.Location = New-Object System.Drawing.Point(492, 20)
    $btnLangFolder.Size = New-Object System.Drawing.Size(28, 28)
    $btnLangFolder.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnLangFolder.FlatAppearance.BorderColor = $steamUi.Border
    $btnLangFolder.FlatAppearance.BorderSize = 1
    $btnLangFolder.BackColor = $steamUi.Panel
    $btnLangFolder.ForeColor = $steamUi.Text
    $btnLangFolder.Font = New-Object System.Drawing.Font('Segoe UI Emoji', 9)
    $btnLangFolder.Text = ([string][char]0xD83D + [string][char]0xDCC1)
    $btnLangFolder.Padding = New-Object System.Windows.Forms.Padding(0)
    $btnLangFolder.TabStop = $false
    $btnLangFolder.Cursor = [System.Windows.Forms.Cursors]::Hand
    $langToolTip.SetToolTip($btnLangFolder, (T 'set_lang_folder_tip'))
    $btnLangFolder.Add_Click({
        try {
            $langDirPath = Get-LangDir
            if (-not [System.IO.Directory]::Exists($langDirPath)) { [void][System.IO.Directory]::CreateDirectory($langDirPath) }
            Start-Process -FilePath 'explorer.exe' -ArgumentList ('"' + $langDirPath + '"')
        } catch {
            Show-AppMessageBox((T 'lang_folder_fail' @([string]$_.Exception.Message)), (T 'settings_title'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    })
    $dlg.Controls.Add($btnLangFolder)

    # Смена языка интерфейса сразу переключает регион обложек на соответствующий
    # язык Steam (ru→russian, en→english, zh→schinese, …). Регион всё ещё можно
    # выбрать вручную отдельно — до следующего переключения языка.
    $syncRegionFromUiLanguage = {
        try {
            $li = $cmbLanguage.SelectedIndex
            if ($li -lt 0 -or $li -ge $script:languageList.Count) { return }
            $steamCode = [string]$script:languageList[$li].Steam
            if ([string]::IsNullOrWhiteSpace($steamCode)) { return }
            $regList = @($cmbSteamRegion.Tag)
            for ($ri = 0; $ri -lt $regList.Count; $ri++) {
                if ([string]::Equals([string]$regList[$ri].Steam, $steamCode, [System.StringComparison]::OrdinalIgnoreCase)) {
                    if ($cmbSteamRegion.SelectedIndex -ne $ri) { $cmbSteamRegion.SelectedIndex = $ri }
                    return
                }
            }
        } catch {}
    }
    $cmbLanguage.Add_SelectionChangeCommitted({ & $syncRegionFromUiLanguage })

    $steamSection = New-Object System.Windows.Forms.Label
    $steamSection.Text = 'Steam'
    $steamSection.Location = New-Object System.Drawing.Point(20, 58)
    $steamSection.Size = New-Object System.Drawing.Size(500, 25)
    $steamSection.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $steamSection.ForeColor = $steamUi.Accent
    $dlg.Controls.Add($steamSection)

    # Правая колонка: та же ширина, что и левая (по просьбе — «половинка
    # такого же размера»), с управлением эмуляторами для режима ROMs.
    # Разделительная вертикальная линия между колонками.
    $romsColumnX = $script:settingsLeftColumnWidth + $script:settingsColumnGap
    # Отступ слева внутри правой колонки — такой же (20px), как у левой
    # колонки от края диалога (там же 20px до полей/списка бэкапов), чтобы
    # список эмуляторов не упирался в разделитель и в правый край окна.
    $romsContentX = $romsColumnX
    $romsContentWidth = $script:settingsRightColumnWidth - 20

    # Заголовок правой колонки поднят до уровня выбора языка в левой половине
    # (та же Y=20, что и у $cmbLanguage), а не до уровня заголовка «Steam».
    $romsSection = New-Object System.Windows.Forms.Label
    $romsSection.Text = (T 'emu_section')
    $romsSection.Location = New-Object System.Drawing.Point($romsContentX, 20)
    $romsSection.Size = New-Object System.Drawing.Size($romsContentWidth, 25)
    $romsSection.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $romsSection.ForeColor = $steamUi.Accent
    $dlg.Controls.Add($romsSection)

    # Пояснение под заголовком «Эмуляторы» убрано (место нужно, чтобы уложиться в размер главного окна).

    # Окно настроек меняет высоту (≈730–800 px: зависит от того, введены ли ключи API), поэтому:
    #  • блок «Библиотеки апскейлеров» — фиксированной высоты, прижат к низу (Bottom|Left) и его нижний
    #    край совпадает с прежним нижним краем панели эмуляторов (ClientSize.Height - 71): ряд кнопок
    #    «Добавить / Изменить / Удалить» остаётся на уровне «Обзор… / Создать бэкап» слева;
    #  • область эмуляторов (Top|Left|Bottom) занимает всё место над ним и растягивается вместе с окном.
    # Верх панели эмуляторов — Y=92, на одном уровне со строкой «Папка Steam» слева.
    # Высота окна фиксирована (700): блок апскейлеров 243 px (плитки 3x51 + зазоры + строка статуса)
    # нижним краем вровень с рядом кнопок бэкапов слева; панель эмуляторов — от y=52 до него.
    $upscalerHeight = 243
    $romsBlockGap = 8
    $upscalerTop = $script:settingsDialogHeight - 71 - $upscalerHeight
    $romsPanelHeight = $upscalerTop - $romsBlockGap - 52
    $pnlRomsManager = New-Object System.Windows.Forms.Panel
    $pnlRomsManager.Location = New-Object System.Drawing.Point($romsContentX, 52)
    $pnlRomsManager.Size = New-Object System.Drawing.Size($romsContentWidth, $romsPanelHeight)
    $pnlRomsManager.Anchor = [System.Windows.Forms.AnchorStyles]::Top -bor [System.Windows.Forms.AnchorStyles]::Left -bor [System.Windows.Forms.AnchorStyles]::Bottom
    $dlg.Controls.Add($pnlRomsManager)
    Add-EmulatorsManagerControls $dlg $pnlRomsManager

    $pnlUpscalers = New-Object System.Windows.Forms.Panel
    $pnlUpscalers.Location = New-Object System.Drawing.Point($romsContentX, $upscalerTop)
    $pnlUpscalers.Size = New-Object System.Drawing.Size($romsContentWidth, $upscalerHeight)
    $pnlUpscalers.Anchor = [System.Windows.Forms.AnchorStyles]::Bottom -bor [System.Windows.Forms.AnchorStyles]::Left
    $dlg.Controls.Add($pnlUpscalers)
    try { Add-UpscalerLibraryControls $dlg $pnlUpscalers } catch { try { Write-LauncherLog ('Add-UpscalerLibraryControls: ' + $_.Exception.Message) } catch {} }

    $steamPathLabel = New-Object System.Windows.Forms.Label
    $steamPathLabel.Text = (T 'set_steam_folder')
    $steamPathLabel.Location = New-Object System.Drawing.Point(20, 92)
    $steamPathLabel.Size = New-Object System.Drawing.Size(80, 28)
    $steamPathLabel.ForeColor = $steamUi.Muted
    $steamPathLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $dlg.Controls.Add($steamPathLabel)

    # Значок ошибки — красный !, если папка Steam не найдена (или в ней нет
    # steam.exe). Тот же значок, что используется для ключей API, стоит
    # непосредственно перед полем ввода и обновляется вживую при правке пути.
    $steamPathValidationBadge = New-ConfidenceBadge $dlg 100 97

    # Текст в однострочных полях: отступ слева как у выпадающих списков (≈12 px) и по центру по вертикали.
    # У TextBox с AutoSize = $false текст прижат к верху, поэтому высоту ставим по шрифту и центрируем в панели.
    $centerFieldText = {
        param($tb, $pnl)
        $tb.AutoSize = $false
        $tb.Height = [int]$tb.PreferredHeight
        $tb.Width = [int]($pnl.ClientSize.Width - 12 - 8)
        $tb.Left = 12
        $tb.Top = [int][Math]::Floor(($pnl.ClientSize.Height - $tb.Height) / 2)
    }

    $steamPathPanel = New-Object System.Windows.Forms.Panel
    $steamPathPanel.Location = New-Object System.Drawing.Point(120, 92)
    $steamPathPanel.Size = New-Object System.Drawing.Size(300, 28)
    $steamPathPanel.BackColor = $steamUi.Input
    $steamPathPanel.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($steamPathPanel)

    $txtSteamPath = New-Object System.Windows.Forms.TextBox
    $txtSteamPath.AutoSize = $false
    $txtSteamPath.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    $txtSteamPath.BackColor = $steamUi.Input
    $txtSteamPath.ForeColor = $steamUi.Text
    $txtSteamPath.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    $txtSteamPath.Text = [string](Get-ConfiguredSteamInstallPath)
    $txtSteamPath.Location = New-Object System.Drawing.Point(6, 4)
    $txtSteamPath.Size = New-Object System.Drawing.Size(288, 21)
    $steamPathPanel.Controls.Add($txtSteamPath)
    & $centerFieldText $txtSteamPath $steamPathPanel

    $btnBrowseSteamPath = New-Object System.Windows.Forms.Button
    $btnBrowseSteamPath.Location = New-Object System.Drawing.Point(430, 92)
    $btnBrowseSteamPath.Size = New-Object System.Drawing.Size(90, 28)
    Set-BrowseIconButton $btnBrowseSteamPath
    $btnBrowseSteamPath.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnBrowseSteamPath.FlatAppearance.BorderColor = $steamUi.Border
    $btnBrowseSteamPath.BackColor = $steamUi.Panel
    $btnBrowseSteamPath.ForeColor = $steamUi.Text
    $btnBrowseSteamPath.Cursor = [System.Windows.Forms.Cursors]::Hand
    $dlg.Controls.Add($btnBrowseSteamPath)

    $steamProfileLabel = New-Object System.Windows.Forms.Label
    $steamProfileLabel.Text = (T 'set_profile')
