    # не выбран или выбранный userdata-профиль не найден на диске.
    $steamProfileValidationBadge = New-ConfidenceBadge $dlg 100 137

    $pnlSteamProfile = New-Object System.Windows.Forms.Panel
    $pnlSteamProfile.Location = New-Object System.Drawing.Point(120, 132)
    $pnlSteamProfile.Size = New-Object System.Drawing.Size(300, 28)
    $pnlSteamProfile.BackColor = $steamUi.Input
    $pnlSteamProfile.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($pnlSteamProfile)

    $cmbSteamProfile = New-Object SmartExeComboBox
    $cmbSteamProfile.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbSteamProfile.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbSteamProfile.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbSteamProfile.ItemHeight = 20
    $cmbSteamProfile.DropDownHeight = 128
    $cmbSteamProfile.IntegralHeight = $false
    $cmbSteamProfile.BackColor = $steamUi.Input
    $cmbSteamProfile.ForeColor = $steamUi.Text
    $cmbSteamProfile.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    try { $cmbSteamProfile.BorderColor = $steamUi.Input } catch {}
    $pnlSteamProfile.Controls.Add($cmbSteamProfile)
    # Профиль "блокируется" через .Locked (а не .Enabled), когда профилей Steam
    # не найдено — .Enabled=$false отключает наш перехват WM_PAINT/WM_NCPAINT,
    # и Windows рисует поверх тёмной темы системную светлую рамку/фон (тот же
    # "белый глюк", что уже описан у Locked в самом классе SmartExeComboBox для
    # заблокированного EXE лицензионной игры).
    $cmbSteamProfile.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $isDisabled = $sender.Locked
        if ($isDisabled) {
            $bg = $steamUi.Panel
            $fg = $steamUi.Muted
        } else {
            $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
            $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            # Текст рисуем через TextRenderer (как в TextBox): тот же отступ слева (12 px), что у полей ввода,
            # и точное вертикальное центрирование.
            $ctFlags = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
            $ctRect = New-Object System.Drawing.Rectangle(($e.Bounds.X + 12), $e.Bounds.Y, [Math]::Max(10, $e.Bounds.Width - 12 - 4), $e.Bounds.Height)
            [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $text, $sender.Font, $ctRect, $fg, $ctFlags)
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })

    # Регион обложек Steam (вместо бывшей подписи «Выбран профиль: …»).
    $steamRegionLabel = New-Object System.Windows.Forms.Label
    $steamRegionLabel.Text = (T 'set_region')
    $steamRegionLabel.Location = New-Object System.Drawing.Point(20, 166)
    $steamRegionLabel.Size = New-Object System.Drawing.Size(92, 28)
    $steamRegionLabel.ForeColor = $steamUi.Muted
    $steamRegionLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $dlg.Controls.Add($steamRegionLabel)

    $pnlSteamRegion = New-Object System.Windows.Forms.Panel
    $pnlSteamRegion.Location = New-Object System.Drawing.Point(120, 166)
    $pnlSteamRegion.Size = New-Object System.Drawing.Size(300, 28)
    $pnlSteamRegion.BackColor = $steamUi.Input
    $pnlSteamRegion.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($pnlSteamRegion)

    # Как и $cmbLanguage/$cmbSteamProfile выше: обычный ComboBox всегда рисует
    # стрелку и раскрытый список нативным светлым цветом Windows независимо от
    # BackColor/ForeColor — поэтому SmartExeComboBox (снимает тему через
    # SetWindowTheme) + OwnerDrawFixed с собственным DrawItem, а не просто
    # System.Windows.Forms.ComboBox, как было раньше.
    $cmbSteamRegion = New-Object SmartExeComboBox
    $cmbSteamRegion.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbSteamRegion.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbSteamRegion.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbSteamRegion.ItemHeight = 20
    $cmbSteamRegion.BackColor = $steamUi.Input
    $cmbSteamRegion.ForeColor = $steamUi.Text
    $cmbSteamRegion.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    try { $cmbSteamRegion.BorderColor = $steamUi.Input } catch {}
    $cmbSteamRegion.IntegralHeight = $false
    $cmbSteamRegion.MaxDropDownItems = 16
    foreach ($rl in @($script:steamCoverLanguages)) {
        [void]$cmbSteamRegion.Items.Add([string]$rl.Name)
    }
    $cmbSteamRegion.Tag = @($script:steamCoverLanguages)
    $regionSel = 0
    $wantRegion = [string]$global:steamCoverRegion
    if ([string]::IsNullOrWhiteSpace($wantRegion)) { $wantRegion = [string](Get-SteamAssetLanguage) }
    for ($ri = 0; $ri -lt $script:steamCoverLanguages.Count; $ri++) {
        if ([string]$script:steamCoverLanguages[$ri].Steam -eq $wantRegion) { $regionSel = $ri; break }
    }
    if ($cmbSteamRegion.Items.Count -gt 0) { $cmbSteamRegion.SelectedIndex = $regionSel }
    $pnlSteamRegion.Controls.Add($cmbSteamRegion)
    $cmbSteamRegion.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
        $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            # Текст рисуем через TextRenderer (как в TextBox): тот же отступ слева (12 px), что у полей ввода,
            # и точное вертикальное центрирование.
            $ctFlags = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
            $ctRect = New-Object System.Drawing.Rectangle(($e.Bounds.X + 12), $e.Bounds.Y, [Math]::Max(10, $e.Bounds.Width - 12 - 4), $e.Bounds.Height)
            [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $text, $sender.Font, $ctRect, $fg, $ctFlags)
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })

    # Скрытая строка статуса для ошибок сохранения (путь Steam и т.п.) —
