    $chkUseExeIconsLabel = New-Object System.Windows.Forms.Label
    $chkUseExeIconsLabel.Text = (T 'set_use_exe_icons')
    $chkUseExeIconsLabel.Location = New-Object System.Drawing.Point(346, 202)
    $chkUseExeIconsLabel.Size = New-Object System.Drawing.Size(174, 32)
    $chkUseExeIconsLabel.ForeColor = $steamUi.Muted
    $chkUseExeIconsLabel.BackColor = $steamUi.Bg
    $chkUseExeIconsLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $chkUseExeIconsLabel.Cursor = [System.Windows.Forms.Cursors]::Hand

    $toggleUseExeIcons = {
        $chkUseExeIcons.Tag = -not [bool]$chkUseExeIcons.Tag
        $chkUseExeIcons.Invalidate()
    }
    $chkUseExeIcons.Add_Click($toggleUseExeIcons)
    $chkUseExeIconsLabel.Add_Click($toggleUseExeIcons)

    $dlg.Controls.Add($chkUseExeIcons)
    $dlg.Controls.Add($chkUseExeIconsLabel)

    $section = New-Object System.Windows.Forms.Label
    $section.Text = (T 'api_keys_section')
    $section.Location = New-Object System.Drawing.Point(20, 244)
    $section.Size = New-Object System.Drawing.Size(500, 25)
    $section.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $section.ForeColor = $steamUi.Accent
    $dlg.Controls.Add($section)

    $keyLabel = New-Object System.Windows.Forms.Label
    $keyLabel.Text = 'SteamGridDB'
    $keyLabel.Location = New-Object System.Drawing.Point(20, 278)
    $keyLabel.Size = New-Object System.Drawing.Size(78, 28)
    $keyLabel.ForeColor = $steamUi.Muted
    $keyLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $dlg.Controls.Add($keyLabel)

    # Значок состояния API-ключа — точно такой же, как в карточке игры:
    # зелёная галочка для валидного ключа, красный ! для невалидного.
    # Он находится непосредственно перед полем ввода.
    $apiKeyValidationBadge = New-ConfidenceBadge $dlg 100 283

    $keyPanel = New-Object System.Windows.Forms.Panel
    $keyPanel.Location = New-Object System.Drawing.Point(120, 278)
    $keyPanel.Size = New-Object System.Drawing.Size(300, 28)
    $keyPanel.BackColor = $steamUi.Input
    $keyPanel.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($keyPanel)

    $txtKey = New-Object System.Windows.Forms.TextBox
    $txtKey.AutoSize = $false
    $txtKey.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    $txtKey.BackColor = $steamUi.Input
    $txtKey.ForeColor = $steamUi.Text
    $txtKey.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    $txtKey.Text = [string]$global:steamGridDbApiKey
    $txtKey.Location = New-Object System.Drawing.Point(6, 4)
    $txtKey.Size = New-Object System.Drawing.Size(288, 21)
    $keyPanel.Controls.Add($txtKey)
    & $centerFieldText $txtKey $keyPanel

    # При открытии настроек НЕ выполняем повторную проверку API. Используем
    # результат проверки, уже полученный при запуске программы. Поэтому
    # зелёная галочка/красный ! сразу видны рядом с ключом. Текстом статус не
    # дублируется: причина отказа лежит в подсказке-tooltip значка.
    if (-not [string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey)) {
        if ([bool]$global:steamGridDbApiKeyValid) {
            Set-ApiKeyValidationBadge $apiKeyValidationBadge 'valid' (T 'key_valid')
        } else {
            $startupCheck = $global:steamGridDbApiKeyCheck
            $startupMsg = if ($startupCheck -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$startupCheck.Message)) { [string]$startupCheck.Message } else { (T 'key_invalid_default') }
            if ($startupCheck -ne $null -and $startupCheck.Kind -eq 'invalid') { $startupMsg += (T 'key_new_key') }
            Set-ApiKeyValidationBadge $apiKeyValidationBadge 'invalid' $startupMsg
        }
    } else {
        Set-ApiKeyValidationBadge $apiKeyValidationBadge 'hidden' ''
    }

    # Проверяем ключ после окончания ввода, а не на каждый символ.
    # Это исключает десятки лишних HTTP-запросов во время вставки/набора ключа.
    $apiKeyValidationTimer = New-Object System.Windows.Forms.Timer
    $apiKeyValidationTimer.Interval = 650

    $apiKeyValidationTimer.Add_Tick({
        $apiKeyValidationTimer.Stop()
        $key = [string]$txtKey.Text.Trim()
        if ([string]::IsNullOrWhiteSpace($key)) {
            $global:steamGridDbApiKeyValid = $false
            Set-ApiKeyValidationBadge $apiKeyValidationBadge 'hidden' ''
            return
        }

        $global:steamGridDbApiKeyValid = $false
        $check = Test-SteamGridDbApiKey $key
        if ($check.Valid) {
            Set-ApiKeyValidationBadge $apiKeyValidationBadge 'valid' $check.Message
        } else {
            # Красный ! и при неверном ключе, и при сетевом сбое; чем именно
            # это вызвано, объясняет tooltip значка.
            $failTip = [string]$check.Message
            if ($check.Kind -eq 'invalid') { $failTip += (T 'key_new_key') }
            Set-ApiKeyValidationBadge $apiKeyValidationBadge 'invalid' $failTip
        }
    })

    $txtKey.Add_TextChanged({
        $apiKeyValidationTimer.Stop()
        # После любого изменения ключ снова считается непроверенным, поэтому
        # кнопка SGDB в карточке игры должна стать неактивной до новой успешной проверки.
        $global:steamGridDbApiKeyValid = $false
        Set-ApiKeyValidationBadge $apiKeyValidationBadge 'hidden' ''
        # Пустое поле — показываем подсказку по ключу, иначе только значок.
        & $applySettingsLayout
        if (-not [string]::IsNullOrWhiteSpace([string]$txtKey.Text.Trim())) {
            $apiKeyValidationTimer.Start()
        }
    })

    $dlg.Add_FormClosed({
        try { $apiKeyValidationTimer.Stop(); $apiKeyValidationTimer.Dispose() } catch {}
    })

    # Подсказка под самым полем ключа (что это за ключ и где его взять).
    # Видна только пока поле пустое; когда ключ введён — состояние показывает
    # значок рядом с полем (см. $applySettingsLayout ниже).
    $hint = New-Object System.Windows.Forms.LinkLabel
    $hint.Location = New-Object System.Drawing.Point(120, 310)
    $hint.Size = New-Object System.Drawing.Size(400, 30)
    $hint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $hint.ForeColor = $steamUi.Muted
    $hint.LinkColor = $steamUi.Accent
    $hint.ActiveLinkColor = $steamUi.Accent2
    $hint.VisitedLinkColor = $steamUi.Accent
    $hint.LinkBehavior = [System.Windows.Forms.LinkBehavior]::HoverUnderline
    $hint.Add_LinkClicked({
        param($sender, $e)
        try { Start-Process ([string]$e.Link.LinkData) } catch {}
    })
    Set-HintLinkText $hint (T 'key_hint_default')
    $dlg.Controls.Add($hint)

    $hintColorError = [System.Drawing.Color]::FromArgb(232, 110, 110)
    $hintColorWarn = [System.Drawing.Color]::FromArgb(226, 180, 90)

    # --- Steam Web API (отдельный ключ, только для локальной базы игр) ---
    $swSection = New-Object System.Windows.Forms.Label
    $swSection.Text = (T 'sw_section')
    $swSection.Location = New-Object System.Drawing.Point(20, 370)
    $swSection.Size = New-Object System.Drawing.Size(500, 25)
    $swSection.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $swSection.ForeColor = $steamUi.Accent
    # Отдельный заголовок Steam Web API убран: ключи идут под общим «API-ключи» (подробности — во всплывающей подсказке метки).

    $swKeyLabel = New-Object System.Windows.Forms.Label
    $swKeyLabel.Text = 'Steam'
    $swKeyLabel.Location = New-Object System.Drawing.Point(20, 404)
    $swKeyLabel.Size = New-Object System.Drawing.Size(78, 28)
    $swKeyLabel.ForeColor = $steamUi.Muted
    $swKeyLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $dlg.Controls.Add($swKeyLabel)
    try { $langToolTip.SetToolTip($swKeyLabel, (T 'sw_section')) } catch {}

    $swKeyValidationBadge = New-ConfidenceBadge $dlg 100 349

    $swKeyPanel = New-Object System.Windows.Forms.Panel
    $swKeyPanel.Location = New-Object System.Drawing.Point(120, 404)
    $swKeyPanel.Size = New-Object System.Drawing.Size(300, 28)
    $swKeyPanel.BackColor = $steamUi.Input
    $swKeyPanel.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($swKeyPanel)

    $txtSteamKey = New-Object System.Windows.Forms.TextBox
    $txtSteamKey.AutoSize = $false
    $txtSteamKey.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    $txtSteamKey.BackColor = $steamUi.Input
    $txtSteamKey.ForeColor = $steamUi.Text
    $txtSteamKey.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    $txtSteamKey.Text = [string]$global:steamApiKey
    $txtSteamKey.Location = New-Object System.Drawing.Point(6, 4)
    $txtSteamKey.Size = New-Object System.Drawing.Size(288, 21)
    $swKeyPanel.Controls.Add($txtSteamKey)
    & $centerFieldText $txtSteamKey $swKeyPanel

    if (-not [string]::IsNullOrWhiteSpace([string]$global:steamApiKey)) {
        if ([bool]$global:steamApiKeyValid) {
            Set-ApiKeyValidationBadge $swKeyValidationBadge 'valid' (T 'key_valid')
        } else {
            $swStartupCheck = $global:steamApiKeyCheck
            $swStartupMsg = if ($swStartupCheck -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$swStartupCheck.Message)) { [string]$swStartupCheck.Message } else { (T 'key_invalid_default') }
            if ($swStartupCheck -ne $null -and ($swStartupCheck.Kind -eq 'invalid' -or $swStartupCheck.Kind -eq 'forbidden')) { $swStartupMsg += (T 'sw_key_new_key') }
            Set-ApiKeyValidationBadge $swKeyValidationBadge 'invalid' $swStartupMsg
        }
    } else {
        Set-ApiKeyValidationBadge $swKeyValidationBadge 'hidden' ''
    }

    $swKeyValidationTimer = New-Object System.Windows.Forms.Timer
    $swKeyValidationTimer.Interval = 650
    $swKeyValidationTimer.Add_Tick({
        $swKeyValidationTimer.Stop()
        $swKey = [string]$txtSteamKey.Text.Trim()
        if ([string]::IsNullOrWhiteSpace($swKey)) {
            $global:steamApiKeyValid = $false
            Set-ApiKeyValidationBadge $swKeyValidationBadge 'hidden' ''
            return
        }
        $global:steamApiKeyValid = $false
        $swCheck = Test-SteamApiKey $swKey
        if ($swCheck.Valid) {
            Set-ApiKeyValidationBadge $swKeyValidationBadge 'valid' $swCheck.Message
        } else {
            $swFailTip = [string]$swCheck.Message
            if ($swCheck.Kind -eq 'invalid' -or $swCheck.Kind -eq 'forbidden') { $swFailTip += (T 'sw_key_new_key') }
            Set-ApiKeyValidationBadge $swKeyValidationBadge 'invalid' $swFailTip
        }
    })

    $txtSteamKey.Add_TextChanged({
        $swKeyValidationTimer.Stop()
        $global:steamApiKeyValid = $false
        Set-ApiKeyValidationBadge $swKeyValidationBadge 'hidden' ''
        # Вернуть обычную подсказку по ключу (там мог остаться ответ на «Обновить»
        # без ключа) и пересобрать раскладку: пустое поле — подсказка, иначе —
        # строка состояния локальной базы.
        Set-HintLinkText $swHint $swHintDefaultText
        $swHint.ForeColor = $steamUi.Muted
        & $applySettingsLayout
        if (-not [string]::IsNullOrWhiteSpace([string]$txtSteamKey.Text.Trim())) {
            $swKeyValidationTimer.Start()
        }
    })

    $dlg.Add_FormClosed({
        try { $swKeyValidationTimer.Stop(); $swKeyValidationTimer.Dispose() } catch {}
    })

    # Пока поле ключа пустое, под ним стоит подсказка по ключу; когда ключ введён,
    # на её месте показывается строка состояния локальной базы ($dbStatusLabel).
    $swHint = New-Object System.Windows.Forms.LinkLabel
    $swHint.Location = New-Object System.Drawing.Point(120, 436)
    $swHint.Size = New-Object System.Drawing.Size(400, 52)
    $swHint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $swHint.ForeColor = $steamUi.Muted
    $swHint.LinkColor = $steamUi.Accent
    $swHint.ActiveLinkColor = $steamUi.Accent2
    $swHint.VisitedLinkColor = $steamUi.Accent
    $swHint.LinkBehavior = [System.Windows.Forms.LinkBehavior]::HoverUnderline
    $swHint.Add_LinkClicked({
        param($sender, $e)
        try { Start-Process ([string]$e.Link.LinkData) } catch {}
    })
    Set-HintLinkText $swHint (T 'sw_key_hint')
    $dlg.Controls.Add($swHint)

    $swHintDefaultText = [string]$swHint.Text

    # Ручное обновление локальной базы игр (сама она обновляется раз в неделю).
    # Маленькая кнопка со значком «обновить» — тот же стиль и размер (28x28), что у кнопки-папки,
    # по одной вертикали с кнопкой выбора папки Steam. Значок рисуется векторно в Add_Paint ниже.
    # Подпись остаётся во всплывающей подсказке.
    $btnUpdateDb = New-Object System.Windows.Forms.Button
    $btnUpdateDb.Text = ''
    $btnUpdateDb.Padding = New-Object System.Windows.Forms.Padding(0)
    $btnUpdateDb.Location = New-Object System.Drawing.Point(430, 344)
    $btnUpdateDb.Size = New-Object System.Drawing.Size(28, 28)
    $btnUpdateDb.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnUpdateDb.FlatAppearance.BorderColor = $steamUi.Border
    $btnUpdateDb.BackColor = $steamUi.Panel
    $btnUpdateDb.ForeColor = $steamUi.Text
    $btnUpdateDb.Cursor = [System.Windows.Forms.Cursors]::Hand
    $dlg.Controls.Add($btnUpdateDb)

    # Значок «обновить» рисуем векторно, а не шрифтом: шрифтовые глифы (эмодзи/Segoe Icons) на размере
    # ~14 px получаются мутными, а штатный текст кнопки ещё и смещён от центра из-за метрик шрифта.
    # Здесь — две дуги со стрелками по кругу (как у 🔄), сглаженные, строго по центру кнопки.
    $btnUpdateDb.Add_Paint({
        param($sender, $e)
        try {
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $col = if ($sender.Enabled) { $sender.ForeColor } else { $steamUi.Muted }

            $cx = [single]($sender.ClientSize.Width / 2.0)
            $cy = [single]($sender.ClientSize.Height / 2.0)
            $r = [single]5.6          # радиус окружности значка
            $headSweep = 38.0         # угловая длина наконечника стрелки (градусы)
            $headHalfW = 2.5          # половина ширины основания наконечника (px)
            $arcSweep = 108.0         # длина самой дуги (градусы)

            $pen = New-Object System.Drawing.Pen($col, [single]1.6)
            $brush = New-Object System.Drawing.SolidBrush($col)
            try {
                $rect = New-Object System.Drawing.RectangleF(($cx - $r), ($cy - $r), (2 * $r), (2 * $r))
                foreach ($startAngle in @(192.0, 12.0)) {
                    $g.DrawArc($pen, $rect, [single]$startAngle, [single]$arcSweep)
                    # Наконечник: основание — в конце дуги, остриё — на окружности чуть дальше по ходу часовой стрелки.
                    $endA = ($startAngle + $arcSweep) * [Math]::PI / 180.0
                    $tipA = ($startAngle + $arcSweep + $headSweep) * [Math]::PI / 180.0
                    $bx = $cx + $r * [Math]::Cos($endA); $by = $cy + $r * [Math]::Sin($endA)
                    $nx = [Math]::Cos($endA);            $ny = [Math]::Sin($endA)   # нормаль (радиально наружу)
                    $tip = New-Object System.Drawing.PointF([single]($cx + $r * [Math]::Cos($tipA)), [single]($cy + $r * [Math]::Sin($tipA)))
                    $p1 = New-Object System.Drawing.PointF([single]($bx + $nx * $headHalfW), [single]($by + $ny * $headHalfW))
                    $p2 = New-Object System.Drawing.PointF([single]($bx - $nx * $headHalfW), [single]($by - $ny * $headHalfW))
                    $g.FillPolygon($brush, [System.Drawing.PointF[]]@($p1, $tip, $p2))
                }
            } finally { $pen.Dispose(); $brush.Dispose() }
        } catch {}
    }.GetNewClosure())

    $dbStatusLabel = New-Object System.Windows.Forms.Label
    # Стоит вплотную под полем Steam Web API-ключа (там же, где подсказка $swHint;
    # что из двух видно, решает $applySettingsLayout). Текст прижат к верху,
    # чтобы не «проваливаться» вниз от поля.
    $dbStatusLabel.Location = New-Object System.Drawing.Point(120, 436)
    $dbStatusLabel.Size = New-Object System.Drawing.Size(400, 18)
    $dbStatusLabel.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $dbStatusLabel.ForeColor = $steamUi.Muted
    $dbStatusLabel.AutoEllipsis = $true
    $dbStatusLabel.TextAlign = [System.Drawing.ContentAlignment]::TopLeft
    $dlg.Controls.Add($dbStatusLabel)
    $dbStatusTip = New-Object System.Windows.Forms.ToolTip
    $dbStatusTip.SetToolTip($btnUpdateDb, (T 'sw_db_update_btn'))

    # Текущее состояние базы (без ожидания: если индекс ещё грузится, поле пустое).
    $dbCount = 0; $dbUpdated = ''
    try { $dbCount = [int][SteamAppsIndex]::Count; $dbUpdated = [string][SteamAppsIndex]::UpdatedAt } catch {}
    if ($dbCount -gt 0) {
        $dbStatusLabel.Text = (T 'sw_db_status_known' @($dbCount, $dbUpdated))
    } elseif (-not (Test-Path -LiteralPath ([string]$global:steamAppsDbFile))) {
        $dbStatusLabel.Text = (T 'sw_db_status_none')
    }
    # Обновление уже идёт (автообновление при запуске) — показываем это и ждём.
    $dbPollTimer = New-Object System.Windows.Forms.Timer
    $dbPollTimer.Interval = 500
    $dbPollTimer.Add_Tick({
        try { Complete-StartupKeyChecks } catch {}

        # Пока фоновое обновление идёт, читаем процент из служебного файла.
        # Текст остаётся в одной строке: «Обновляю… 42%».
        if ($null -ne $script:startupJobs['Db']) {
            try {
                $progressPath = ([string]$global:steamAppsDbFile) + '.progress'
                if (Test-Path -LiteralPath $progressPath) {
                    $rawPct = [string]([System.IO.File]::ReadAllText($progressPath)).Trim()
                    $pct = 0
                    if ([int]::TryParse($rawPct, [ref]$pct)) {
                        if ($pct -lt 0) { $pct = 0 }
                        if ($pct -gt 100) { $pct = 100 }
                        $dbStatusLabel.Text = (T 'sw_db_state_updating') + ' ' + $pct + '%'
                    }
                }
            } catch {}
            return
        }

        $dbPollTimer.Stop()
        $btnUpdateDb.Enabled = $true
        $dbRes = $script:lastDbRefreshResult
        if ($null -ne $dbRes -and $dbRes['Ok']) {
            $dbStatusLabel.ForeColor = $steamUi.Green
            $dbStatusLabel.Text = (T 'sw_db_update_done_msg' @($dbRes['Count']))
            $dbStatusTip.SetToolTip($dbStatusLabel, '')
        } else {
            $dbErr = ''
            if ($null -ne $dbRes) { $dbErr = [string]$dbRes['Error'] }
            $dbStatusLabel.ForeColor = $hintColorError
            $dbStatusLabel.Text = if ($dbErr -match '403') { (T 'sw_key_403') } else { (T 'sw_db_state_fail') }
            $dbStatusTip.SetToolTip($dbStatusLabel, $dbErr)
        }
    })
    if ($null -ne $script:startupJobs['Db']) {
        $btnUpdateDb.Enabled = $false
        $dbStatusLabel.Text = (T 'sw_db_state_updating') + ' 0%'
        $dbPollTimer.Start()
    }

    $btnUpdateDb.Add_Click({
        $dbKey = [string]$txtSteamKey.Text.Trim()
        if ([string]::IsNullOrWhiteSpace($dbKey)) {
            # Поле ключа пустое → строка состояния базы скрыта, поэтому ответ
            # показываем на месте подсказки (вернётся к обычной при вводе ключа).
            $swHint.ForeColor = $hintColorWarn
            Set-HintLinkText $swHint (T 'sw_db_state_nokey')
            return
        }
        $btnUpdateDb.Enabled = $false
        $dbStatusLabel.ForeColor = $steamUi.Muted
        $dbStatusLabel.Text = (T 'sw_db_state_updating')
        $dbStatusTip.SetToolTip($dbStatusLabel, '')
        [void](Start-LocalSteamAppsDbRefresh $dbKey -Force)
        $dbPollTimer.Start()
    })
    $dlg.Add_FormClosed({
        try { $dbPollTimer.Stop(); $dbPollTimer.Dispose() } catch {}
    })

    $backupSection = New-Object System.Windows.Forms.Label
    $backupSection.Text = (T 'set_backup_section')
    $backupSection.Location = New-Object System.Drawing.Point(20, 506)
    $backupSection.Size = New-Object System.Drawing.Size(500, 25)
    $backupSection.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10.5)
    $backupSection.ForeColor = $steamUi.Accent
    $dlg.Controls.Add($backupSection)

    # Текущий путь к папке бэкапов (по умолчанию %AppData%\Steam Commander\backup).
    $lblBackupPath = New-Object System.Windows.Forms.Label
    $lblBackupPath.Text = (T 'set_backup_current' @((Get-BackupFolderPath)))
    $lblBackupPath.Location = New-Object System.Drawing.Point(20, 532)
    $lblBackupPath.Size = New-Object System.Drawing.Size(500, 22)
    $lblBackupPath.ForeColor = $steamUi.Muted
    $lblBackupPath.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $lblBackupPath.AutoEllipsis = $true
    $dlg.Controls.Add($lblBackupPath)

    # Кнопка выбора собственной папки для сохранения резервных копий —
    # вторая в ряду, справа от «Создать бэкап». Ряд теперь под таблицей
    # бэкапов (см. $applySettingsLayout), ширина увеличена с 90 до 120px,
    # чтобы уместился текст «Создать бэкап»/«Восстановить», а зазор между
    # кнопками сокращён до 8px — как в ряду «Добавить/Изменить/Удалить».
    $btnBackupRowWidth = 120
    $btnBackupRowGap = 8

    $btnBrowseBackupFolder = New-Object System.Windows.Forms.Button
    $btnBrowseBackupFolder.Location = New-Object System.Drawing.Point(($btnBackupRowWidth + $btnBackupRowGap + 20), 558)
    $btnBrowseBackupFolder.Size = New-Object System.Drawing.Size($btnBackupRowWidth, 28)
    Set-BrowseIconButton $btnBrowseBackupFolder 28 $false
    $btnBrowseBackupFolder.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnBrowseBackupFolder.FlatAppearance.BorderColor = $steamUi.Border
    $btnBrowseBackupFolder.BackColor = $steamUi.Panel
    $btnBrowseBackupFolder.ForeColor = $steamUi.Text
    $btnBrowseBackupFolder.Cursor = [System.Windows.Forms.Cursors]::Hand
    $dlg.Controls.Add($btnBrowseBackupFolder)

    $backupFolderTip = New-Object System.Windows.Forms.ToolTip
    $backupFolderTip.SetToolTip($btnBrowseBackupFolder, (T 'set_backup_current' @((Get-BackupFolderPath))))

    $btnCreateBackup = New-Object System.Windows.Forms.Button
    $btnCreateBackup.Text = (T 'set_create_backup')
    $btnCreateBackup.Location = New-Object System.Drawing.Point(20, 558)
    $btnCreateBackup.Size = New-Object System.Drawing.Size($btnBackupRowWidth, 28)
    $btnCreateBackup.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCreateBackup.FlatAppearance.BorderColor = $steamUi.Border
    $btnCreateBackup.BackColor = $steamUi.Panel
    $btnCreateBackup.ForeColor = $steamUi.Text
    $btnCreateBackup.Cursor = [System.Windows.Forms.Cursors]::Hand
    $dlg.Controls.Add($btnCreateBackup)

    $btnRestoreBackup = New-Object System.Windows.Forms.Button
    $btnRestoreBackup.Text = (T 'set_restore')
    $btnRestoreBackup.Location = New-Object System.Drawing.Point((520 - $btnBackupRowWidth), 558)
    $btnRestoreBackup.Size = New-Object System.Drawing.Size($btnBackupRowWidth, 28)
    $btnRestoreBackup.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnRestoreBackup.FlatAppearance.BorderColor = $steamUi.Border
    $btnRestoreBackup.BackColor = $steamUi.Panel
    $btnRestoreBackup.ForeColor = $steamUi.Text
    $btnRestoreBackup.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnRestoreBackup.Visible = $false
    $dlg.Controls.Add($btnRestoreBackup)

    $lvBackups = New-Object System.Windows.Forms.ListView
    $lvBackups.Location = New-Object System.Drawing.Point(20, 601)
    $lvBackups.Size = New-Object System.Drawing.Size(500, 96)
    $lvBackups.View = [System.Windows.Forms.View]::Details
    $lvBackups.FullRowSelect = $true
    $lvBackups.GridLines = $false
    $lvBackups.HideSelection = $false
    $lvBackups.HeaderStyle = [System.Windows.Forms.ColumnHeaderStyle]::Clickable
    $lvBackups.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $lvBackups.BackColor = $steamUi.Input
    $lvBackups.ForeColor = $steamUi.Text
    $lvBackups.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    [void]$lvBackups.Columns.Add((T 'col_file'), 255)
    [void]$lvBackups.Columns.Add((T 'col_date'), 125)
    [void]$lvBackups.Columns.Add((T 'col_size'), 90)
    $dlg.Controls.Add($lvBackups)

    # Тот же приём, что и у списка эмуляторов (Add-EmulatorsManagerControls) —
    # заголовок колонок и фон строк ListView иначе всегда остаются нативно
    # светлыми независимо от BackColor/ForeColor.
    $lvBackups.OwnerDraw = $true
    $lvBackups.Add_DrawColumnHeader({
        param($s, $e)
        $e.Graphics.FillRectangle((New-Object System.Drawing.SolidBrush($steamUi.Panel2)), $e.Bounds)
        $borderPen = New-Object System.Drawing.Pen($steamUi.Border)
        $e.Graphics.DrawLine($borderPen, $e.Bounds.Left, $e.Bounds.Bottom - 1, $e.Bounds.Right, $e.Bounds.Bottom - 1)
        $borderPen.Dispose()
        if (-not [string]::IsNullOrEmpty($e.Header.Text)) {
            $sf = New-Object System.Drawing.StringFormat
            $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
            $textRect = New-Object System.Drawing.RectangleF(($e.Bounds.X + 6), $e.Bounds.Y, ($e.Bounds.Width - 8), $e.Bounds.Height)
            $e.Graphics.DrawString($e.Header.Text, $lvBackups.Font, (New-Object System.Drawing.SolidBrush($steamUi.Muted)), $textRect, $sf)
        }
        $e.DrawDefault = $false
    }.GetNewClosure())
    $lvBackups.Add_DrawItem({
        param($s, $e)
        $e.DrawDefault = $false
    })
    $lvBackups.Add_DrawSubItem({
        param($s, $e)
        $bg = if ($e.Item.Selected) { $steamUi.Selected } else { $steamUi.Input }
        $e.Graphics.FillRectangle((New-Object System.Drawing.SolidBrush($bg)), $e.Bounds)
        # Цвет текста берём из ForeColor самого элемента (а не жёстко $steamUi.Text),
        # чтобы сохранить приглушённый цвет у строки-заглушки «Нет резервных копий»
        # (см. $refreshBackupList) — ListViewItem.ForeColor по умолчанию и так равен
        # ForeColor списка, если не переопределён явно.
        $fg = $e.Item.ForeColor
        $sf = New-Object System.Drawing.StringFormat
        $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
        $sf.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter
        $sf.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap
        $textRect = New-Object System.Drawing.RectangleF(($e.Bounds.X + 6), $e.Bounds.Y, ($e.Bounds.Width - 8), $e.Bounds.Height)
        $e.Graphics.DrawString($e.SubItem.Text, $e.Item.Font, (New-Object System.Drawing.SolidBrush($fg)), $textRect, $sf)
    }.GetNewClosure())

    # Ширина колонок (275+125+90) не дотягивает до правого края списка —
    # оставшаяся полоса заголовка ничья ни одной колонке, поэтому она вне
    # DrawColumnHeader и всегда остаётся нативно-белой, что бы мы ни рисовали.
    # Растягиваем последнюю колонку («Размер») до фактической ширины списка:
    # ClientSize сам уменьшается, если появляется вертикальная полоса
    # прокрутки (много бэкапов), так что зазор не возникает и в этом случае.
    $resizeBackupsLastColumn = {
        try {
            if ($lvBackups.Columns.Count -lt 3) { return }
            $minWidth = 70
            $avail = $lvBackups.ClientSize.Width - $lvBackups.Columns[0].Width - $lvBackups.Columns[1].Width
            if ($avail -lt $minWidth) { $avail = $minWidth }
            if ($lvBackups.Columns[2].Width -ne $avail) { $lvBackups.Columns[2].Width = $avail }
        } catch {}
    }.GetNewClosure()

    # Строка статуса для сообщений о создании/восстановлении резервных
    # копий («Готово к восстановлению», «Создано копий: N» и т.п.).
    $backupHint = New-Object System.Windows.Forms.Label
    $backupHint.Text = ''
    $backupHint.Location = New-Object System.Drawing.Point(20, 715)
    $backupHint.Size = New-Object System.Drawing.Size(500, 18)
    $backupHint.ForeColor = $steamUi.Muted
    $backupHint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
    $dlg.Controls.Add($backupHint)

    $appVersionLabel = New-Object System.Windows.Forms.Label
    $appVersionLabel.Text = "$($global:appTitle) • v$($global:appVersion)"
    $appVersionLabel.Location = New-Object System.Drawing.Point(20, 734)
    $appVersionLabel.Size = New-Object System.Drawing.Size(300, 34)
    $appVersionLabel.ForeColor = $steamUi.Muted
    $appVersionLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $appVersionLabel.Width = [System.Windows.Forms.TextRenderer]::MeasureText($appVersionLabel.Text, $dlg.Font).Width + 4
    $dlg.Controls.Add($appVersionLabel)

    # Ссылка на исходный код и кнопка «Поддержать» — справа от версии, в той же нижней строке.
    $lnkGithub = New-Object System.Windows.Forms.LinkLabel
    $lnkGithub.Text = '• GitHub'
    $lnkGithub.Location = New-Object System.Drawing.Point(($appVersionLabel.Right + 2), 734)
    $lnkGithub.Size = New-Object System.Drawing.Size(([System.Windows.Forms.TextRenderer]::MeasureText($lnkGithub.Text, $dlg.Font).Width + 6), 34)
    $lnkGithub.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $lnkGithub.ForeColor = $steamUi.Muted
    $lnkGithub.LinkColor = $steamUi.Accent
    $lnkGithub.ActiveLinkColor = $steamUi.Accent2
    $lnkGithub.VisitedLinkColor = $steamUi.Accent
    $lnkGithub.LinkBehavior = [System.Windows.Forms.LinkBehavior]::HoverUnderline
    $lnkGithub.Links.Clear()
    [void]$lnkGithub.Links.Add(2, 6, [string]$global:appRepoUrl)
    $lnkGithub.Add_LinkClicked({ param($s, $e) try { Start-Process ([string]$e.Link.LinkData) } catch {} })
    $dlg.Controls.Add($lnkGithub)

    $btnSupport = New-Object System.Windows.Forms.Button
    $btnSupport.Text = ([string][char]0x2665 + ' ' + (T 'support_btn'))
    $btnSupport.Location = New-Object System.Drawing.Point(($lnkGithub.Right + 12), 736)
    $btnSupport.Size = New-Object System.Drawing.Size(([System.Windows.Forms.TextRenderer]::MeasureText($btnSupport.Text, $dlg.Font).Width + 32), 28)
    $btnSupport.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnSupport.FlatAppearance.BorderColor = $steamUi.Accent2
    $btnSupport.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnSupport.ForeColor = $steamUi.Text
    $btnSupport.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnSupport.Add_Click({ param($s, $e) try { Show-SupportDialog ($s.FindForm()) } catch {} })
    $dlg.Controls.Add($btnSupport)

    # «Отмена»/«Сохранить» перенесены в правую колонку (вровень по правому
    # краю со списком/кнопками эмуляторов, romsContentX+romsContentWidth) —
    # в место, освободившееся под панелью эмуляторов после того, как её
    # подняли вровень с кнопками бэкапов. По вертикали (.Top) их положение
    # по-прежнему считает $applySettingsLayout ниже — меняется только X.
    $btnCancelSaveRight = $romsContentX + $romsContentWidth

    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = (T 'set_cancel')
    $btnCancel.Location = New-Object System.Drawing.Point(($btnCancelSaveRight - 2 * 100 - 8), 734)
    $btnCancel.Size = New-Object System.Drawing.Size(100, 28)
    $btnCancel.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnCancel.FlatAppearance.BorderColor = $steamUi.Border
    $btnCancel.BackColor = $steamUi.Panel
    $btnCancel.ForeColor = $steamUi.Text
    # Закрытие кнопкой «Отмена»/Esc — только окно настроек; крестик (Alt+F4) закрывает программу целиком
    # (см. $dlg.Add_FormClosing). Поэтому DialogResult у кнопки не задаём, а закрываем окно сами с признаком.
    $btnCancel.Add_Click({
        $settingsState.ButtonClose = $true
        $dlg.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        $dlg.Close()
    })
    $dlg.Controls.Add($btnCancel)

    $btnSave = New-Object System.Windows.Forms.Button
    $btnSave.Text = (T 'set_save')
    $btnSave.Location = New-Object System.Drawing.Point(($btnCancelSaveRight - 100), 734)
    $btnSave.Size = New-Object System.Drawing.Size(100, 28)
    $btnSave.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnSave.FlatAppearance.BorderColor = $steamUi.Accent2
    $btnSave.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnSave.ForeColor = $steamUi.Text
    $btnSave.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
    $dlg.Controls.Add($btnSave)

    # Раскладка нижней части окна зависит от того, заполнены ли поля ключей:
    #  - SteamGridDB: пустое поле → подсказка по ключу, заполнено → ничего
    #    (состояние показывает значок), блок Steam Web API поднимается выше;
    #  - Steam Web API: пустое поле → подсказка по ключу, заполнено → строка
    #    «Локальная база: …» вплотную под полем;
    #  - всё, что ниже, сдвигается вслед за ними, а высота окна подгоняется.
    # Координаты — исходные («базовые») плюс сдвиг $dy.
    $applySettingsLayout = {
        $sgEmpty = [string]::IsNullOrWhiteSpace([string]$txtKey.Text)
        $swEmpty = [string]::IsNullOrWhiteSpace([string]$txtSteamKey.Text)

        # Высота подсказок — по реальному тексту (на любом языке), а не «с запасом».
        $measureHint = {
            param($lbl)
            try {
                $sz = New-Object System.Drawing.Size(([int]$lbl.Width), 0)
                $h = [System.Windows.Forms.TextRenderer]::MeasureText([string]$lbl.Text, $lbl.Font, $sz, [System.Windows.Forms.TextFormatFlags]::WordBreak).Height
                return [int]([Math]::Max(16, $h + 2))
            } catch { return [int]$lbl.Height }
        }
        $hint.Height = (& $measureHint $hint)
        $swHint.Height = (& $measureHint $swHint)

        $hint.Visible = $sgEmpty

        # Ряд SteamGridDB — на постоянном месте; ряд Steam сдвигается вслед за подсказкой под ним.
        $sgTop = 278
        $swTop = if ($sgEmpty) { $sgTop + 30 + $hint.Height + 4 } else { $sgTop + 34 }
        $keyLabel.Top = $sgTop
        $keyPanel.Top = $sgTop
        $hint.Top = $sgTop + 30

        $swKeyLabel.Top = $swTop
        $swKeyPanel.Top = $swTop
        $swKeyValidationBadge.Top = $swTop + 5
        $btnUpdateDb.Top = $swTop

        $swHint.Top = $swTop + 30
        $dbStatusLabel.Top = $swTop + 30
        $swHint.Visible = $swEmpty
        $dbStatusLabel.Visible = (-not $swEmpty)
        $slotHeight = if ($swEmpty) { $swHint.Height } else { $dbStatusLabel.Height }

        $bTop = $swTop + 30 + $slotHeight + 14

        # Высота окна фиксирована (= главному окну). Всё, что внизу, привязано к низу окна,
        # а список бэкапов занимает оставшееся между заголовком раздела и рядом кнопок место.
        $footerTop = $script:settingsDialogHeight - 16 - 34
        $btnRowTop = $footerTop - 19 - 32
        $backupSection.Top = $bTop
        $lblBackupPath.Top = $bTop + 26
        $lvBackups.Top = $bTop + 52
        $lvBackups.Height = [int][Math]::Max(60, ($btnRowTop - 13) - ($bTop + 52))
        $btnBrowseBackupFolder.Top = $btnRowTop
        $btnCreateBackup.Top = $btnRowTop
        $btnRestoreBackup.Top = $btnRowTop
        $backupHint.Top = $footerTop - 19
        $appVersionLabel.Top = $footerTop
        $lnkGithub.Top = $footerTop
        $btnSupport.Top = $footerTop + 3
        $btnCancel.Top = $footerTop + 3
        $btnSave.Top = $footerTop + 3
    }
    & $applySettingsLayout

    # Красные значки рядом с полями пути Steam и профиля: обновляются вживую
    # при любой правке — ручном вводе пути, выборе через «Обзор», смене
    # профиля в списке или пересборке самого списка профилей.
    $refreshSteamValidationBadges = {
        try {
            $pathText = [string]$txtSteamPath.Text.Trim()
            $pathOk = $false
            if (-not [string]::IsNullOrWhiteSpace($pathText)) {
                try {
                    $exeCandidate = Join-Path $pathText 'steam.exe'
                    $pathOk = (Test-Path -LiteralPath $pathText -PathType Container) -and (Test-Path -LiteralPath $exeCandidate -PathType Leaf)
                } catch { $pathOk = $false }
            }
            if ($pathOk) {
                Set-ApiKeyValidationBadge $steamPathValidationBadge 'hidden' ''
            } else {
                Set-ApiKeyValidationBadge $steamPathValidationBadge 'invalid' (T 'set_steam_folder_invalid')
            }

            $profileOk = [bool]($cmbSteamProfile.Enabled -and $cmbSteamProfile.Items.Count -gt 0 -and $cmbSteamProfile.SelectedIndex -ge 0)
            $profileUnknown = $false
            if ($profileOk) {
                try {
                    $selectedProfiles = @($cmbSteamProfile.Tag)
                    $selIdx = $cmbSteamProfile.SelectedIndex
                    if ($selIdx -ge 0 -and $selIdx -lt $selectedProfiles.Count) {
                        # Папка существует и выглядит как userdata-профиль, но её
                        # AccountID не найден ни в одной записи loginusers.vdf —
                        # значит, это не настоящий, когда-либо залогиненный на
                        # этом ПК аккаунт Steam, а подложенная вручную папка.
                        $profileUnknown = -not [bool]$selectedProfiles[$selIdx].IsKnownAccount
                    }
                } catch {}
            }
            if ($profileOk -and -not $profileUnknown) {
                Set-ApiKeyValidationBadge $steamProfileValidationBadge 'hidden' ''
            } elseif ($profileOk -and $profileUnknown) {
                Set-ApiKeyValidationBadge $steamProfileValidationBadge 'invalid' (T 'set_profile_unknown')
            } else {
                Set-ApiKeyValidationBadge $steamProfileValidationBadge 'invalid' (T 'set_profile_invalid')
            }
        } catch {}
    }

    $refreshSteamProfiles = {
        try {
            $oldId = [string]$global:steamUserId
            $profiles = @(Get-SteamUserProfiles)

            $cmbSteamProfile.Items.Clear()
            $cmbSteamProfile.Tag = $profiles

            if ($profiles.Count -eq 0) {
                $cmbSteamProfile.Items.Add((T 'set_no_profiles')) | Out-Null
                $cmbSteamProfile.SelectedIndex = 0
                $cmbSteamProfile.Enabled = $false
                return
            }

            $cmbSteamProfile.Enabled = $true
            foreach ($profile in $profiles) {
                [void]$cmbSteamProfile.Items.Add([string]$profile.DisplayName)
            }

            $selectedIndex = -1
            for ($i = 0; $i -lt $profiles.Count; $i++) {
                if ([string]::Equals([string]$profiles[$i].Id, $oldId, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $selectedIndex = $i
                    break
                }
            }
            if ($selectedIndex -lt 0) { $selectedIndex = 0 }
            $cmbSteamProfile.SelectedIndex = $selectedIndex
        } catch {
            $cmbSteamProfile.Items.Clear()
            $cmbSteamProfile.Items.Add((T 'set_profiles_fail')) | Out-Null
            $cmbSteamProfile.SelectedIndex = 0
            $cmbSteamProfile.Enabled = $false
        } finally {
            & $refreshSteamValidationBadges
        }
    }

    $txtSteamPath.Add_TextChanged({
        & $refreshSteamValidationBadges
    })

    $btnBrowseSteamPath.Add_Click({
        try {
            $res = Show-CenteredFolderDialog (T 'pick_steam_folder') $txtSteamPath.Text
            if ($res -ne $null) {
                $txtSteamPath.Text = [string]$res
                $global:steamInstallPath = [string]$res
                $global:steamUserId = ''
                & $refreshSteamProfiles
            }
        } catch {}
    })

    $cmbSteamProfile.Add_SelectionChangeCommitted({
        # Профиль уже виден в ComboBox — отдельная подпись не нужна.
        & $refreshSteamValidationBadges
    })

    & $refreshSteamProfiles

    $refreshBackupList = {
        try {
            $lvBackups.Items.Clear()
            $btnRestoreBackup.Visible = $false
            $btnRestoreBackup.Tag = $null
            foreach ($backup in @(Get-ManualShortcutBackupFiles)) {
                $item = $lvBackups.Items.Add([string]$backup.Name)
                [void]$item.SubItems.Add($backup.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'))
                $sizeText = if ($backup.Length -ge 1MB) {
                    ('{0:N1} ' -f ($backup.Length / 1MB)) + (T 'unit_mb')
                } elseif ($backup.Length -ge 1KB) {
                    ('{0:N0} ' -f ($backup.Length / 1KB)) + (T 'unit_kb')
                } else {
                    ('{0} ' -f $backup.Length) + (T 'unit_b')
                }
                [void]$item.SubItems.Add($sizeText)
                $item.Tag = $backup
            }
            if ($lvBackups.Items.Count -eq 0) {
                $empty = New-Object System.Windows.Forms.ListViewItem
                $empty.Text = (T 'no_backups')
                $empty.ForeColor = $steamUi.Muted
                [void]$empty.SubItems.Add('')
                [void]$empty.SubItems.Add('')
                [void]$lvBackups.Items.Add($empty)
            }
            & $resizeBackupsLastColumn
        } catch {
            try { $btnRestoreBackup.Visible = $false } catch {}
        }
    }

    # Небольшое тематическое окно подтверждения в стиле самого Commander.
    # Используется вместо стандартного Windows MessageBox при восстановлении.
    $showThemedRestoreConfirm = {
        param(
            [string]$windowTitle,
            [string]$messageText
        )

        $confirm = New-Object System.Windows.Forms.Form
        $confirm.Text = $windowTitle
        $confirm.StartPosition = 'CenterParent'
        $confirm.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
        $confirm.MaximizeBox = $false
        $confirm.MinimizeBox = $false
        $confirm.ShowInTaskbar = $false
        $confirm.ClientSize = New-Object System.Drawing.Size(500, 190)
        $confirm.BackColor = $steamUi.Bg
        $confirm.ForeColor = $steamUi.Text
        $confirm.Font = New-Object System.Drawing.Font('Segoe UI', 9)

        $confirmTitle = New-Object System.Windows.Forms.Label
        $confirmTitle.Text = $windowTitle
        $confirmTitle.Location = New-Object System.Drawing.Point(20, 16)
        $confirmTitle.Size = New-Object System.Drawing.Size(460, 28)
        $confirmTitle.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 12)
        $confirmTitle.ForeColor = $steamUi.Text
        $confirm.Controls.Add($confirmTitle)

        $confirmMessage = New-Object System.Windows.Forms.Label
        $confirmMessage.Text = $messageText
        $confirmMessage.Location = New-Object System.Drawing.Point(20, 52)
        $confirmMessage.Size = New-Object System.Drawing.Size(460, 62)
        $confirmMessage.ForeColor = $steamUi.Muted
        $confirmMessage.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
        $confirm.Controls.Add($confirmMessage)

        $btnConfirmYes = New-Object System.Windows.Forms.Button
        $btnConfirmYes.Text = (T 'set_restore')
        $btnConfirmYes.Location = New-Object System.Drawing.Point(235, 132)
        $btnConfirmYes.Size = New-Object System.Drawing.Size(120, 34)
        $btnConfirmYes.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $btnConfirmYes.FlatAppearance.BorderColor = $steamUi.Accent2
        $btnConfirmYes.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
        $btnConfirmYes.ForeColor = $steamUi.Text
        $btnConfirmYes.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
        $btnConfirmYes.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnConfirmYes.DialogResult = [System.Windows.Forms.DialogResult]::Yes
        $confirm.Controls.Add($btnConfirmYes)

        $btnConfirmNo = New-Object System.Windows.Forms.Button
        $btnConfirmNo.Text = (T 'set_cancel')
        $btnConfirmNo.Location = New-Object System.Drawing.Point(365, 132)
        $btnConfirmNo.Size = New-Object System.Drawing.Size(115, 34)
        $btnConfirmNo.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $btnConfirmNo.FlatAppearance.BorderColor = $steamUi.Border
        $btnConfirmNo.BackColor = $steamUi.Panel
        $btnConfirmNo.ForeColor = $steamUi.Text
        $btnConfirmNo.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnConfirmNo.DialogResult = [System.Windows.Forms.DialogResult]::No
        $confirm.Controls.Add($btnConfirmNo)

        $confirm.AcceptButton = $btnConfirmYes
        $confirm.CancelButton = $btnConfirmNo

        try {
            return ($confirm.ShowDialog($dlg) -eq [System.Windows.Forms.DialogResult]::Yes)
        } finally {
            try { $confirm.Dispose() } catch {}
        }
    }

    # Полностью закрывает Steam перед заменой shortcuts.vdf.
    # Путь возвращается в вызывающий код, где Steam запускается уже ПОСЛЕ
    # копирования восстановленного файла.
    $restartSteamAfterRestore = {
        try {
            $steamExe = $null

            # 0) Если Steam уже запущен, сначала запоминаем реальный путь
            # из самого процесса. Это надёжнее реестра для нестандартной установки.
            try {
                $runningForPath = @(Get-Process -Name 'steam' -ErrorAction SilentlyContinue | Select-Object -First 1)
                if ($runningForPath.Count -gt 0) {
                    try {
                        $procPath = [string]$runningForPath[0].Path
                        if ([string]::IsNullOrWhiteSpace($procPath)) {
                            $procPath = [string]$runningForPath[0].MainModule.FileName
                        }
                        if (-not [string]::IsNullOrWhiteSpace($procPath) -and (Test-Path -LiteralPath $procPath)) {
                            $steamExe = $procPath
                        }
                    } catch {
                        try {
                            $procPath = [string]$runningForPath[0].MainModule.FileName
                            if (-not [string]::IsNullOrWhiteSpace($procPath) -and (Test-Path -LiteralPath $procPath)) {
                                $steamExe = $procPath
                            }
                        } catch {}
                    }
                }
            } catch {}

            # 1) Путь из настроек программы (приоритетный).
            try {
                $configuredExe = Get-ConfiguredSteamExePath
                if (-not [string]::IsNullOrWhiteSpace([string]$configuredExe) -and (Test-Path -LiteralPath [string]$configuredExe)) {
                    $steamExe = [string]$configuredExe
                }
            } catch {}

            # 2) Резервный способ — путь Steam из реестра.
            if ([string]::IsNullOrWhiteSpace([string]$steamExe)) {
                try {
                    $steamExeReg = (Get-ItemProperty -Path "HKCU:\Software\Valve\Steam" -Name "SteamExe" -ErrorAction SilentlyContinue).SteamExe
                    if (-not [string]::IsNullOrWhiteSpace([string]$steamExeReg) -and (Test-Path -LiteralPath [string]$steamExeReg)) {
                        $steamExe = [string]$steamExeReg
                    }
                } catch {}
            }

            # Если Steam ещё работает — сначала просим его закрыться.
            $running = @(Get-Process -Name 'steam' -ErrorAction SilentlyContinue)
            if ($running.Count -gt 0) {
                foreach ($proc in $running) {
                    try {
                        if ($proc.MainWindowHandle -ne 0) {
                            [void]$proc.CloseMainWindow()
                        }
                    } catch {}
                }

                # Ждём завершения всех steam.exe, а не только главного окна.
                $deadline = (Get-Date).AddSeconds(12)
                while ((@(Get-Process -Name 'steam' -ErrorAction SilentlyContinue)).Count -gt 0 -and (Get-Date) -lt $deadline) {
                    Start-Sleep -Milliseconds 250
                }

                # Остались процессы — принудительно закрываем их.
                $leftovers = @(Get-Process -Name 'steam' -ErrorAction SilentlyContinue)
                foreach ($proc in $leftovers) {
                    try { Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } catch {}
                }

                # Дожидаемся реального освобождения shortcuts.vdf.
                $deadline = (Get-Date).AddSeconds(6)
                while ((@(Get-Process -Name 'steam' -ErrorAction SilentlyContinue)).Count -gt 0 -and (Get-Date) -lt $deadline) {
                    Start-Sleep -Milliseconds 250
                }

                Start-Sleep -Milliseconds 500
            }

            if ([string]::IsNullOrWhiteSpace([string]$steamExe)) {
                $steamExe = 'steam.exe'
            }

            return [string]$steamExe
        } catch {
            return $null
        }
    }

    # Надёжный запуск Steam: обычный Start-Process + резервный запуск через
    # explorer.exe, затем проверяем, что процесс действительно появился.
    $startSteamAfterRestore = {
        param([string]$steamExe)

        try {
            if ([string]::IsNullOrWhiteSpace($steamExe)) { return $false }

            $launchPath = [string]$steamExe
            $workingDir = $null
            try { $workingDir = [System.IO.Path]::GetDirectoryName($launchPath) } catch {}

            if (Test-Path -LiteralPath $launchPath) {
                try {
                    if ([string]::IsNullOrWhiteSpace($workingDir)) {
                        Start-Process -FilePath $launchPath -ErrorAction Stop | Out-Null
                    } else {
                        Start-Process -FilePath $launchPath -WorkingDirectory $workingDir -ErrorAction Stop | Out-Null
                    }
                } catch {}

                # Steam иногда стартует не мгновенно — даём ему до 8 секунд.
                $deadline = (Get-Date).AddSeconds(8)
                while ((Get-Date) -lt $deadline) {
                    if (@(Get-Process -Name 'steam' -ErrorAction SilentlyContinue).Count -gt 0) {
                        return $true
                    }
                    Start-Sleep -Milliseconds 250
                }

                # Резерв: передаём запуск Windows Shell.
                try {
                    Start-Process -FilePath 'explorer.exe' -ArgumentList ('"' + $launchPath + '"') -ErrorAction Stop | Out-Null
                } catch {}
            } else {
                # Путь не найден — полагаемся на зарегистрированный steam.exe.
                try {
                    Start-Process -FilePath 'steam.exe' -ErrorAction Stop | Out-Null
                } catch {}
            }

            $deadline = (Get-Date).AddSeconds(8)
            while ((Get-Date) -lt $deadline) {
                if (@(Get-Process -Name 'steam' -ErrorAction SilentlyContinue).Count -gt 0) {
                    return $true
                }
                Start-Sleep -Milliseconds 250
            }

            return $false
        } catch {
            return $false
        }
    }

    $lvBackups.Add_SelectedIndexChanged({
        try {
            $btnRestoreBackup.Visible = $false
            $btnRestoreBackup.Tag = $null
            if ($lvBackups.SelectedItems.Count -eq 0) { return }
            $selectedItem = $lvBackups.SelectedItems[0]
            $backup = $selectedItem.Tag
            if ($backup -eq $null -or -not ($backup -is [System.IO.FileInfo])) { return }
            $target = Resolve-ManualBackupTarget $backup
            if ($target -eq $null) {
                $backupHint.Text = (T 'bk_no_source')
                return
            }
            $btnRestoreBackup.Tag = [PSCustomObject]@{ Backup = $backup; Target = [string]$target }
            $btnRestoreBackup.Visible = $true
            $backupHint.Text = (T 'bk_ready')
        } catch {
            $btnRestoreBackup.Visible = $false
            $btnRestoreBackup.Tag = $null
        }
    })

    $btnBrowseBackupFolder.Add_Click({
        try {
            $res = Show-CenteredFolderDialog (T 'pick_backup_folder') (Get-BackupFolderPath)
            if ($res -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$res)) {
                $global:backupFolderPath = [string]$res
                $pathText = (T 'set_backup_current' @((Get-BackupFolderPath)))
                try { $lblBackupPath.Text = $pathText } catch {}
                try { $backupFolderTip.SetToolTip($btnBrowseBackupFolder, $pathText) } catch {}
                & $refreshBackupList
            }
        } catch {}
    })

    $btnCreateBackup.Add_Click({
        $btnCreateBackup.Enabled = $false
        try {
            $created = @(Create-ManualShortcutBackup)
            & $refreshBackupList
            if ($created.Count -gt 0) {
                $backupHint.Text = (T 'bk_created' @($created.Count))
            } else {
                $backupHint.Text = (T 'bk_vdf_missing')
            }
        } finally {
            $btnCreateBackup.Enabled = $true
        }
    })

    $btnRestoreBackup.Add_Click({
        try {
            $payload = $btnRestoreBackup.Tag
            if ($payload -eq $null) { return }
            $backup = $payload.Backup
            $target = $payload.Target
            if ($backup -eq $null -or [string]::IsNullOrWhiteSpace([string]$target)) { return }

            $confirmed = & $showThemedRestoreConfirm (T 'confirm_title') (
                (T 'confirm_q' @([string]$backup.Name)) + "`r`n`r`n" + (T 'confirm_note')
            )
            if (-not $confirmed) { return }

            $btnRestoreBackup.Enabled = $false
            $btnCreateBackup.Enabled = $false
            $backupHint.Text = (T 'bk_closing')
            [System.Windows.Forms.Application]::DoEvents()

            $steamExe = & $restartSteamAfterRestore
            if ([string]::IsNullOrWhiteSpace([string]$steamExe)) {
                $backupHint.Text = (T 'bk_no_steam_path')
                return
            }

            $targetDir = [System.IO.Path]::GetDirectoryName([string]$target)
            if (-not [string]::IsNullOrWhiteSpace($targetDir)) {
                [System.IO.Directory]::CreateDirectory([string]$targetDir) | Out-Null
            }

            $backupHint.Text = (T 'bk_restoring')
            [System.Windows.Forms.Application]::DoEvents()

            Copy-Item -LiteralPath $backup.FullName -Destination ([string]$target) -Force -ErrorAction Stop

            $backupHint.Text = (T 'bk_starting')
            [System.Windows.Forms.Application]::DoEvents()

            $steamStarted = & $startSteamAfterRestore ([string]$steamExe)
            if ($steamStarted) {
                $backupHint.Text = (T 'bk_restored_ok' @([string]$backup.Name))
            } else {
                $backupHint.Text = (T 'bk_restored_nosteam')
            }
            try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
            & $refreshBackupList
            try { Refresh-Panels } catch {}
        } catch {
            $backupHint.Text = (T 'bk_restore_err' @([string]$_.Exception.Message))
        } finally {
            $btnRestoreBackup.Enabled = $true
            $btnCreateBackup.Enabled = $true
        }
    })

    & $refreshBackupList

    $btnSave.Add_Click({
        try {
            $chosenSteamPath = [string]$txtSteamPath.Text.Trim()
            if ([string]::IsNullOrWhiteSpace($chosenSteamPath)) {
                Show-AppMessageBox((T 'set_path_empty'), (T 'settings_title'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                return
            }

            $fullSteamPath = [System.IO.Path]::GetFullPath($chosenSteamPath)
            if (-not (Test-Path -LiteralPath $fullSteamPath -PathType Container)) {
                Show-AppMessageBox((T 'set_path_missing'), (T 'settings_title'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                return
            }

            $steamExeCandidate = Join-Path $fullSteamPath 'steam.exe'
            if (-not (Test-Path -LiteralPath $steamExeCandidate -PathType Leaf)) {
                Show-AppMessageBox((T 'set_exe_missing'), (T 'settings_title'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                return
            }

            $profiles = @($cmbSteamProfile.Tag)
            $idx = $cmbSteamProfile.SelectedIndex
            $chosenUserId = ''
            if ($cmbSteamProfile.Enabled -and $idx -ge 0 -and $idx -lt $profiles.Count) {
                $chosenUserId = [string]$profiles[$idx].Id
            }

            $global:steamInstallPath = $fullSteamPath
            $global:steamUserId = $chosenUserId
            $global:steamGridDbApiKey = $txtKey.Text.Trim()
            $launchersSettingChanged = ([bool]$global:suggestGameLaunchers -ne [bool]$chkSuggestLaunchers.Tag)
            $global:suggestGameLaunchers = [bool]$chkSuggestLaunchers.Tag
            $global:useExeIcons = [bool]$chkUseExeIcons.Tag
            if ($launchersSettingChanged) { $global:exeSelectionCache.Clear() }
            $global:steamApiKey = $txtSteamKey.Text.Trim()
            $settingsState.Accepted = $true

            # Если ключ изменили и сразу нажали «Сохранить», не дождавшись отложенной
            # проверки (таймер 650 мс), — проверяем его сейчас, чтобы сохранённое
            # состояние соответствовало сохранённому ключу.
            try {
                if ($apiKeyValidationTimer.Enabled) {
                    $apiKeyValidationTimer.Stop()
                    if (-not [string]::IsNullOrWhiteSpace($global:steamGridDbApiKey)) { [void](Test-SteamGridDbApiKey $global:steamGridDbApiKey) }
                }
            } catch {}
            try {
                if ($swKeyValidationTimer.Enabled) {
                    $swKeyValidationTimer.Stop()
                    if (-not [string]::IsNullOrWhiteSpace($global:steamApiKey)) { [void](Test-SteamApiKey $global:steamApiKey) }
                }
            } catch {}

            # Язык: применяем по «Сохранить» — и к главному окну, и к самому окну настроек (оно остаётся открытым).
            $langChangedOnSave = $false
            $langIdx = $cmbLanguage.SelectedIndex
            if ($langIdx -ge 0 -and $langIdx -lt $script:languageList.Count) {
                $newLang = [string]$script:languageList[$langIdx].Code
                if ($newLang -ne [string]$global:language) {
                    $langChangedOnSave = $true
                    & $applyLiveLanguage
                }
            }

            # Регион обложек Steam.
            $regIdx = $cmbSteamRegion.SelectedIndex
            $regList = @($cmbSteamRegion.Tag)
            if ($regIdx -ge 0 -and $regIdx -lt $regList.Count) {
                $global:steamCoverRegion = [string]$regList[$regIdx].Steam
            }

            Save-Configuration
            try { Refresh-Panels } catch {}
            $settingsState.ButtonClose = $true
            $dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK
            $dlg.Close()
        } catch {
            Show-AppMessageBox((T 'set_save_err' @([string]$_.Exception.Message)), (T 'settings_title'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    })

    # Клик мышкой в любом месте окна настроек снимает выделение/фокус с таблицы
    # резервных копий. Исключения: сама таблица (клик по строке — обычный выбор;
    # клик по её пустой области, наоборот, тоже снимает выделение) и кнопка
    # «Восстановить» — ей выделенная строка нужна для самого восстановления.
    # Выделение сбрасываем через SelectedItems.Clear(): сработает
    # SelectedIndexChanged, который сам прячет «Восстановить».
    $clearBackupSelection = {
        try {
            if ($lvBackups.SelectedItems.Count -eq 0) { return }
            $lvBackups.SelectedItems.Clear()
            if ($backupHint.Text -eq (T 'bk_ready') -or $backupHint.Text -eq (T 'bk_no_source')) {
                $backupHint.Text = ''
            }
        } catch {}
    }.GetNewClosure()

    # $dismissAction передаётся параметром, чтобы GetNewClosure() захватил
    # именно локальную переменную функции (см. Add-EmuFocusDismissHandler).
    function Add-BackupDefocusHandler([System.Windows.Forms.Control]$control, $dismissAction) {
        if ($null -eq $control) { return }
        if ($control -ne $lvBackups -and $control -ne $btnRestoreBackup) {
            $control.Add_MouseDown({ & $dismissAction }.GetNewClosure())
        }
        foreach ($child in @($control.Controls)) {
            Add-BackupDefocusHandler $child $dismissAction
        }
    }
    foreach ($control in @($dlg.Controls)) {
        Add-BackupDefocusHandler $control $clearBackupSelection
    }
    $dlg.Add_MouseDown({ & $clearBackupSelection }.GetNewClosure())
    $lvBackups.Add_MouseDown({
        param($s, $e)
        try { if ($null -eq $s.GetItemAt($e.X, $e.Y)) { & $clearBackupSelection } } catch {}
    }.GetNewClosure())

    $dlg.AcceptButton = $btnSave
    $dlg.CancelButton = $btnCancel
    # При открытии настроек ничего не выделяем и не ставим курсор в поле ключа.
    $dlg.Add_Shown({
        if ($settingsSeamless) {
            # Ставим окно по центру главного (внутри рабочей области), затем одним кадром меняем их местами.
            try {
                $mb = $form.Bounds
                if ($dlg.Width -eq $mb.Width -and $dlg.Height -eq $mb.Height) {
                    # Размеры совпадают — окно встаёт ровно поверх главного.
                    $dlg.Location = $mb.Location
                    throw 'placed'
                }
                $wa = [System.Windows.Forms.Screen]::FromControl($form).WorkingArea
                $nx = [int]($mb.Left + ($mb.Width - $dlg.Width) / 2)
                $ny = [int]($mb.Top + ($mb.Height - $dlg.Height) / 2)
                if (($nx + $dlg.Width) -gt $wa.Right) { $nx = $wa.Right - $dlg.Width }
                if (($ny + $dlg.Height) -gt $wa.Bottom) { $ny = $wa.Bottom - $dlg.Height }
                if ($nx -lt $wa.Left) { $nx = $wa.Left }
                if ($ny -lt $wa.Top) { $ny = $wa.Top }
                $dlg.Location = New-Object System.Drawing.Point($nx, $ny)
            } catch {}
            $dlg.Opacity = 1
            try { $form.Opacity = 0; $form.UseWaitCursor = $false } catch {}
        }
        try {
            $txtKey.SelectionLength = 0
            $txtKey.SelectionStart = 0
            $dlg.ActiveControl = $null
            $dlg.Select()
        } catch {}
        try {
            $dlg.BeginInvoke([Action]{
                try {
                    $txtKey.SelectionLength = 0
                    $txtKey.SelectionStart = 0
                    $dlg.ActiveControl = $null
                } catch {}
            }) | Out-Null
        } catch {}
        # Известная особенность OwnerDraw-заголовка ListView: пока хэндл окна
        # не создан (до показа диалога), заголовок может остаться нативно-
        # светлым, несмотря на DrawColumnHeader — список эмуляторов эту
        # перерисовку получал «бесплатно» через Sort() при первой загрузке,
        # а список бэкапов (без сортировки по клику) — нет. Пересчёт ширины
        # последней колонки (см. $resizeBackupsLastColumn) заодно принудительно
        # перерисовывает заголовок уже в нашем тёмном стиле.
        try {
            $dlg.BeginInvoke([Action]{
                try { & $resizeBackupsLastColumn } catch {}
            }) | Out-Null
        } catch {}
    })

    $dlg.Add_FormClosing({
        if ($settingsSeamless) {
            # Настройки — тот же экран программы, что и главное окно: крестик/Alt+F4 закрывает программу целиком
            # (как в библиотеке). Кнопки «Сохранить»/«Отмена» и Esc ставят ButtonClose и лишь возвращают главное окно.
            if (-not $settingsState.ButtonClose -and $_.CloseReason -eq [System.Windows.Forms.CloseReason]::UserClosing) {
                $settingsState.ExitRequested = $true
                try { [System.Windows.Forms.Application]::Exit() } catch {}
                return
            }
            # Главное окно возвращается, пока настройки ещё на экране: на месте закрывшегося окна сразу «проявляется» оно.
            try { $form.Opacity = 1; $form.UseWaitCursor = $false } catch {}
        }
    })

    $dlg.Add_FormClosed({
        try {
            if (-not $settingsState.Accepted) {
                $global:steamInstallPath = $originalSteamInstallPath
                $global:steamUserId = $originalSteamUserId
                $global:suggestGameLaunchers = $originalSuggestGameLaunchers
                $global:useExeIcons = $originalUseExeIcons
                $global:steamGridDbApiKeyValid = $originalSgdbKeyValid
                $global:steamGridDbApiKeyCheck = $originalSgdbKeyCheck
                $global:steamApiKeyValid = $originalSteamKeyValid
                $global:steamApiKeyCheck = $originalSteamKeyCheck
            }
        } catch {}
    })

    # ВАЖНО: при простом открытии настроек повторную проверку сохранённого
    # ключа не запускаем. Ключ уже был проверен при старте программы.
    # Повторная проверка выполняется только после изменения значения в поле.

    # Смена языка по кнопке «Сохранить»: окно настроек не закрывается, подписи и подсказки переводятся на месте.
    # Все строки окна строятся через T при создании, поэтому поступаем так: до переключения запоминаем текст каждого
    # ключа на старом языке, после — на новом, и заменяем у контролов совпавшие тексты (поля ввода не трогаем).
    # Строки с подстановками (путь, число записей и т.п.) обновляются явно ниже.
    $applyLiveLanguage = {
        try {
            $li = $cmbLanguage.SelectedIndex
            if ($li -lt 0 -or $li -ge $script:languageList.Count) { return }
            $newLang = [string]$script:languageList[$li].Code
            $oldLang = [string]$global:language
            if ([string]::IsNullOrWhiteSpace($newLang) -or $newLang -eq $oldLang) { return }

            $keys = New-Object System.Collections.Generic.HashSet[string]
            foreach ($lc in @($oldLang, $newLang, 'en', 'ru')) {
                if ($script:I18n.ContainsKey($lc)) { foreach ($k in @($script:I18n[$lc].Keys)) { [void]$keys.Add([string]$k) } }
            }
            $oldTexts = @{}
            foreach ($k in $keys) { $oldTexts[$k] = [string](T $k) }

            $global:language = $newLang
            try { Apply-Localization } catch {}

            # Старый текст -> новый. Если один старый текст у разных ключей даёт разные новые — не трогаем (неоднозначно).
            $textMap = @{}
            foreach ($k in $keys) {
                $o = [string]$oldTexts[$k]
                if ([string]::IsNullOrWhiteSpace($o)) { continue }
                $n = [string](T $k)
                if ($textMap.ContainsKey($o)) { if ([string]$textMap[$o] -ne $n) { $textMap[$o] = $null } } else { $textMap[$o] = $n }
            }
            $mapText = { param([string]$s); if ($textMap.ContainsKey($s) -and $null -ne $textMap[$s]) { return [string]$textMap[$s] }; return $null }

            $dlg.SuspendLayout()
            $walkControls = {
                param($parentCtl)
                foreach ($c in $parentCtl.Controls) {
                    try {
                        if ($c -ne $cmbLanguage -and $c -ne $pnlLanguage -and -not ($c -is [System.Windows.Forms.TextBox]) -and -not ($c -is [System.Windows.Forms.ComboBox])) {
                            $curText = [string]$c.Text
                            if ($curText.Length -gt 0) {
                                $nt = & $mapText $curText
                                if ($null -ne $nt -and $nt -ne $curText) {
                                    if ($c -is [System.Windows.Forms.LinkLabel]) { Set-HintLinkText $c $nt } else { $c.Text = $nt }
                                }
                            }
                        }
                    } catch {}
                    try { if ($c.Controls.Count -gt 0) { & $walkControls $c } } catch {}
                }
            }
            & $walkControls $dlg

            try { $dlg.Text = (T 'settings_title') } catch {}
            try { $langToolTip.SetToolTip($btnLangFolder, (T 'set_lang_folder_tip')) } catch {}
            try { $langToolTip.SetToolTip($swKeyLabel, (T 'sw_section')) } catch {}
            try { $dbStatusTip.SetToolTip($btnUpdateDb, (T 'sw_db_update_btn')) } catch {}
            try { $backupFolderTip.SetToolTip($btnBrowseBackupFolder, (T 'set_backup_current' @((Get-BackupFolderPath)))) } catch {}
            try { $lblBackupPath.Text = (T 'set_backup_current' @((Get-BackupFolderPath))) } catch {}
            try {
                if ($lvBackups.Columns.Count -ge 3) {
                    $lvBackups.Columns[0].Text = (T 'col_file')
                    $lvBackups.Columns[1].Text = (T 'col_date')
                    $lvBackups.Columns[2].Text = (T 'col_size')
                }
            } catch {}
            try {
                $btnSupport.Text = ([string][char]0x2665 + ' ' + (T 'support_btn'))
                $btnSupport.Width = [System.Windows.Forms.TextRenderer]::MeasureText($btnSupport.Text, $dlg.Font).Width + 32
            } catch {}
            try {
                # Строка состояния базы Steam: пересобираем только если там было «известно/нет данных» на старом языке.
                $dbCnt = 0; $dbUpd = ''
                try { $dbCnt = [int][SteamAppsIndex]::Count; $dbUpd = [string][SteamAppsIndex]::UpdatedAt } catch {}
                $oldKnown = ''
                try { $oldKnown = ([string]$oldTexts['sw_db_status_known'] -f @($dbCnt, $dbUpd)) } catch {}
                if ($dbCnt -gt 0 -and $dbStatusLabel.Text -eq $oldKnown) { $dbStatusLabel.Text = (T 'sw_db_status_known' @($dbCnt, $dbUpd)) }
                elseif ($dbStatusLabel.Text -eq [string]$oldTexts['sw_db_status_none']) { $dbStatusLabel.Text = (T 'sw_db_status_none') }
            } catch {}
            try { & $refreshBackupList } catch {}
            $dlg.ResumeLayout($true)
            try { & $applySettingsLayout } catch {}
            try { $dlg.Invalidate($true) } catch {}
        } catch {
            try { $dlg.ResumeLayout($true) } catch {}
        }
    }
    try { Initialize-FormForSmallScreen -Form $dlg -Owner $(if ($settingsSeamless) { $form } else { $null }) } catch {}
    try {
        if ($settingsSeamless) { $dlg.ShowDialog($form) | Out-Null } else { $dlg.ShowDialog() | Out-Null }
    } finally {
        if ($settingsSeamless) {
            # Страховка: если окно не дошло до Add_Shown (ошибка при показе) — главное окно не должно остаться невидимым.
            if (-not $settingsState.ExitRequested) {
                try { $form.Opacity = 1; $form.UseWaitCursor = $false; $form.Activate() } catch {}
            }
        } elseif ($mainFormWasVisible) {
            try {
                $form.Show()
                if ($form.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal }
                $form.Activate()
            } catch {}
        }
    }

    return [string]$global:steamGridDbApiKey
}


function Get-EditorSgdbCandidates([string]$query, [string]$steamAppId = "") {
    # Автодополнение названия берём напрямую из SteamGridDB — это та же
    # рабочая логика, которая использовалась в старом picker-е.
    try {
        $q = ([string]$query).Trim()
        if ($q.Length -lt 2) { return @() }

        $apiKey = [string](Ensure-SteamGridDbApiKey)
        if ([string]::IsNullOrWhiteSpace($apiKey)) { return @() }
        $headers = @{ Authorization = "Bearer $apiKey" }

        $searchQueries = @($q)
        $tokens = @([regex]::Matches($q,'[\p{L}\p{Nd}]+') | ForEach-Object { [string]$_.Value })
        if ($tokens.Count -gt 1) {
            $fallback = (($tokens | Select-Object -First ([Math]::Min(3,[int]$tokens.Count))) -join ' ')
            if ($fallback -and $fallback -ne $q) { $searchQueries += $fallback }
        }

        # Та же обработка 401, что и в Load-EditorSgdbPreviews — через общую
        # обёртку Invoke-SgdbApiRequest вместо продублированной вручную ветки.
        $req = $null
        foreach($searchQuery in $searchQueries) {
            $url = 'https://www.steamgriddb.com/api/v2/search/autocomplete/' + [System.Uri]::EscapeDataString($searchQuery)
            $req = Invoke-SgdbApiRequest $url $headers 12
            if ($req.Success) { break }
        }

        if ($req -eq $null -or -not $req.Success) { return @() }

        $candidates = @($req.Data | ForEach-Object {
            if ($null -eq $_) { return }
            $id = 0
            try { $id = [int]$_.id } catch { $id = 0 }
            $nm = [string]$_.name
            if ($id -le 0 -or [string]::IsNullOrWhiteSpace($nm)) { return }
            $types = @()
            try { $types = @($_.types) } catch {}
            $score = 0.0
            try { $score = [double](Get-SgdbNameScore $q $_) } catch {}
            [PSCustomObject]@{ Id=$id; Name=$nm; Verified=$_.verified; Types=$types; MatchScore=$score }
        } | Sort-Object MatchScore -Descending | Select-Object -First 12)

        # SteamGridDB id — это НЕ Steam App ID. Используем App ID только
        # для предпочтения steam-совместимых кандидатов, но не записываем его
        # в поле App ID при выборе названия.
        if ($steamAppId -match '^\d+$') {
            $steamMatch = @($candidates | Where-Object { @($_.Types) -contains 'steam' })
            if ($steamMatch.Count -gt 0) {
                $candidates = @($steamMatch + @($candidates | Where-Object { $_ -notin $steamMatch }))
            }
        }
        return @($candidates)
    } catch {
        $global:lastSgdbEditorError = [string]$_.Exception.Message
        return @()
    }
}

# Кэши для альтернатив в режиме Steam: ответ SGDB по Steam App ID (чтобы не слать 4 запроса
# при каждом клике по каждому слоту) и найденный по названию SGDB Game ID.
$script:editorSteamSgdbAssetsCache = @{}
$script:editorSgdbNameIdCache = @{}

function Get-EditorSteamSgdbAssetsCached([string]$steamAppId) {
    $key = [string]$steamAppId
    if ($script:editorSteamSgdbAssetsCache.ContainsKey($key)) {
        $c = $script:editorSteamSgdbAssetsCache[$key]
        # Успех храним до конца сессии, «пусто/ошибка» — 2 минуты (мог быть сбой сети).
        if ($null -ne $c.Assets -or ((Get-Date) - $c.At).TotalSeconds -lt 120) { return $c.Assets }
    }
    $a = Get-SteamGridDbAssetsBySteamAppId $key
    $script:editorSteamSgdbAssetsCache[$key] = [PSCustomObject]@{ Assets = $a; At = (Get-Date) }
    return $a
}

function Prepare-EditorSteamSgdbAlternatives($slot, [string]$title, [string]$steamAppId, [string]$gameName = '', $statusLabel = $null) {
    # В источнике Steam миниатюра остаётся официальной Steam, но по клику
    # пользователь может открыть SGDB только для ЭТОГО типа обложки.
    # Источник поиска карточки при этом не переключается.
    # Сначала варианты берём по Steam App ID. Если для него в SGDB ничего нет
    # (игра на SGDB не привязана к Steam ID), ищем игру в SGDB по названию —
    # так же, как это делает режим SteamGridDB.
    try {
        if ($null -eq $slot) { return $false }

        # Если для этого слота варианты уже были загружены ранее — повторный
        # сетевой запрос не нужен.
        try {
            if (@($slot.SgdbItems).Count -gt 0) { return $true }
        } catch {}

        $apiKey = [string](Ensure-SteamGridDbApiKey)
        if ([string]::IsNullOrWhiteSpace($apiKey)) {
            if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_nokey') }
            return $false
        }

        if ($null -eq $statusLabel) {
            $slotForm = $null
            try { $slotForm = $slot.Panel.FindForm() } catch {}
            try {
                if ($null -ne $slotForm) {
                    $statusLabel = @($slotForm.Controls | Where-Object { $_ -is [System.Windows.Forms.Label] -and $_.Location.X -eq 20 -and $_.Location.Y -ge 100 -and $_.Size.Width -ge 400 }) | Select-Object -Last 1
                }
            } catch {}
        }
        if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_alts' @($title)) }
        [System.Windows.Forms.Application]::DoEvents()

        $id = ([string]$steamAppId).Trim()
        $items = @()

        # 1) По Steam App ID.
        if ($id -match '^\d+$') {
            $assets = Get-EditorSteamSgdbAssetsCached $id
            if ($null -ne $assets) {
                switch -Regex ($title) {
                    '^\s*1\.' {
                        $items = @($assets.Grids | Where-Object {
                            $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                            (($w -eq 600 -and $h -eq 900) -or
                             ($w -eq 342 -and $h -eq 482) -or
                             ($w -eq 660 -and $h -eq 930))
                        })
                        if ($items.Count -eq 0) {
                            $items = @($assets.Grids | Where-Object {
                                $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                                $h -gt 0 -and ($w/$h) -ge 0.55 -and ($w/$h) -le 0.78
                            })
                        }
                    }
                    '^\s*2\.' {
                        $items = @($assets.Grids | Where-Object {
                            $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                            (($w -eq 920 -and $h -eq 430) -or ($w -eq 460 -and $h -eq 215))
                        })
                        if ($items.Count -eq 0) {
                            $items = @($assets.Grids | Where-Object {
                                $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                                $h -gt 0 -and ($w/$h) -ge 1.85 -and ($w/$h) -le 2.35
                            })
                        }
                    }
                    '^\s*3\.' { $items = @($assets.Heroes) }
                    '^\s*4\.' { $items = @($assets.Logos) }
                    '^\s*5\.' { $items = @($assets.Icons) }
                }
            }
        }

        if ($items.Count -gt 0) {
            $items = @($items | Sort-Object @{Expression={ $v=0.0; try{$v=[double]$_.score}catch{}; $v }; Descending=$true})
            $slot.SgdbItems = $items
            if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_steam_loaded_alt') }
            return $true
        }

        # 2) Запасной путь: ищем игру в SGDB по названию и берём варианты по SGDB Game ID.
        $nm = ([string]$gameName).Trim()
        if ($nm.Length -ge 2) {
            $nameKey = $nm.ToLowerInvariant()
            $sgdbId = ''
            if ($script:editorSgdbNameIdCache.ContainsKey($nameKey)) {
                $sgdbId = [string]$script:editorSgdbNameIdCache[$nameKey]
            } else {
                if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_searching' @($nm)) }
                [System.Windows.Forms.Application]::DoEvents()
                $cands = @(Get-EditorSgdbCandidates $nm '')
                if ($cands.Count -gt 0) {
                    $sgdbId = [string]$cands[0].Id
                    $script:editorSgdbNameIdCache[$nameKey] = $sgdbId
                }
            }
            if ($sgdbId -match '^\d+$') {
                return [bool](Prepare-EditorSgdbGameAlternatives $slot $title $sgdbId $statusLabel)
            }
            if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_nogames') }
            return $false
        }

        if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_noalts') }
        return $false
    } catch {
        try { if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_error' @([string]$_.Exception.Message)) } } catch {}
        return $false
    }
}

# Варианты обложек из SteamGridDB по SGDB Game ID — для карточек, где источник SteamGridDB (ROM-игры),
# когда карточка открыта на редактирование: текущие обложки взяты из Steam, а список вариантов не загружался.
# Грузится ТОЛЬКО нужный тип (один запрос, а не четыре подряд), сетка 1/2 кэшируется между слотами.
$script:editorSgdbAltsBusy = $false
$script:editorSgdbGridsCache = @{}

function Prepare-EditorSgdbGameAlternatives($slot, [string]$title, [string]$sgdbGameId, $statusLabel = $null) {
    if ($script:editorSgdbAltsBusy) { return $false }
    $form = $null
    try {
        if ($null -eq $slot) { return $false }
        try { if (@($slot.SgdbItems).Count -gt 0) { return $true } } catch {}

        $id = ([string]$sgdbGameId).Trim()
        if ($id -notmatch '^\d+$') {
            if ($null -ne $statusLabel) { $statusLabel.Text = (T 'st_noid_hint_sgdb') }
            return $false
        }
        $apiKey = [string](Ensure-SteamGridDbApiKey)
        if ([string]::IsNullOrWhiteSpace($apiKey)) {
            if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_nokey') }
            return $false
        }

        $script:editorSgdbAltsBusy = $true
        try { $form = $slot.Panel.FindForm() } catch {}
        try { if ($null -ne $form) { $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor } } catch {}
        if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_alts' @($title)) }
        [System.Windows.Forms.Application]::DoEvents()

        $headers = @{ Authorization = "Bearer $apiKey" }
        $items = @()
        $failMsg = ''
        if ($title -match '^\s*[12]\.') {
            $all = $null
            if ($script:editorSgdbGridsCache.ContainsKey($id)) { $all = $script:editorSgdbGridsCache[$id] }
            else {
                $req = Invoke-SgdbApiRequest "https://www.steamgriddb.com/api/v2/grids/game/$id" $headers 20
                if ($req.Success) { $all = @($req.Data); $script:editorSgdbGridsCache[$id] = $all }
                else { try { $failMsg = [string]$req.ErrorMessage } catch {} }
            }
            if ($null -ne $all) {
                if ($title -match '^\s*1\.') {
                    $items = @($all | Where-Object {
                        $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                        (($w -eq 600 -and $h -eq 900) -or ($w -eq 342 -and $h -eq 482) -or ($w -eq 660 -and $h -eq 930))
                    })
                    if ($items.Count -eq 0) {
                        $items = @($all | Where-Object {
                            $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                            $h -gt 0 -and ($w/$h) -ge 0.55 -and ($w/$h) -le 0.78
                        })
                    }
                } else {
                    $items = @($all | Where-Object {
                        $w=0;$h=0;try{$w=[int]$_.width;$h=[int]$_.height}catch{}
                        (($w -eq 920 -and $h -eq 430) -or ($w -eq 460 -and $h -eq 215))
                    })
                    if ($items.Count -eq 0) {
                        $items = @($all | Where-Object {
                            $w=0;$h=0;try{$w=[double]$_.width;$h=[double]$_.height}catch{}
                            $h -gt 0 -and ($w/$h) -ge 1.85 -and ($w/$h) -le 2.35
                        })
                    }
                }
            }
        } else {
            $kind = if ($title -match '^\s*3\.') { 'heroes' } elseif ($title -match '^\s*4\.') { 'logos' } else { 'icons' }
            $req = Invoke-SgdbApiRequest "https://www.steamgriddb.com/api/v2/$kind/game/$id" $headers 20
            if ($req.Success) { $items = @($req.Data) }
            else { try { $failMsg = [string]$req.ErrorMessage } catch {} }
        }

        if ($items.Count -eq 0) {
            if ($null -ne $statusLabel) {
                $statusLabel.Text = if ($failMsg) { (T 'sl_sg_error' @($failMsg)) } else { (T 'sl_sg_noalts') }
            }
            return $false
        }
        $items = @($items | Sort-Object @{Expression={ $v=0.0; try{$v=[double]$_.score}catch{}; $v }; Descending=$true})
        $slot.SgdbItems = $items
        if ($null -ne $statusLabel) { $statusLabel.Text = '' }
        return $true
    } catch {
        try { if ($null -ne $statusLabel) { $statusLabel.Text = (T 'sl_sg_error' @([string]$_.Exception.Message)) } } catch {}
        return $false
    } finally {
        $script:editorSgdbAltsBusy = $false
        try { if ($null -ne $form) { $form.Cursor = [System.Windows.Forms.Cursors]::Default } } catch {}
    }
}

function Show-EditorAlternativeCover($slot, [string]$title) {
    try {
        $items = @($slot.SgdbItems)

        $chooserWidth = 170
        $chooserHeight = 230
        if ($title -match '^\s*[2345]\.') {
            # БАГ-ФИКС: слот иконки в карточке теперь того же размера, что и
            # остальные (270x170, как Логотип) — раньше здесь был отдельный
            # квадратный вариант 120x120, из-за которого превью в диалоге
            # выбора не совпадало по пропорциям с тем, как иконка реально
            # выглядит в карточке после выбора.
            $chooserWidth = 270
            $chooserHeight = 130
        }

        try {
            $slotFormForSuppress = $slot.Panel.FindForm()
            if($null -ne $slotFormForSuppress -and $null -ne $slotFormForSuppress.Tag){
                $es = $slotFormForSuppress.Tag
                if($es.LastSuggestionField -eq 'title'){ $es.SuppressTitleSuggestionOnce=$true }
                elseif($es.LastSuggestionField -eq 'launch'){ $es.SuppressLaunchOptionOnce=$true }
            }
        } catch {}
        # Хранилище своих картинок ЭТОЙ карточки: плитка «Добавить свою» в окне выбора.
        # Ключ — путь + исходное имя + App ID (см. CoverKey в состоянии карточки), поэтому
        # загруженные картинки не попадают в другие карточки, даже если у них общая папка
        # (например, ROM-игры из одной папки или игры одного лаунчера).
        $customStore = $null
        try {
            $slotId = [regex]::Match([string]$title, '^\s*(\d)').Groups[1].Value
            if (-not [string]::IsNullOrWhiteSpace($slotId)) {
                $keySrc = ''
                $esx = $null
                try { $esx = $slot.EditorState } catch {}
                if ($null -eq $esx) { try { $esx = $slot.Panel.FindForm().Tag } catch {} }
                try { $keySrc = [string]$esx.CoverKey } catch {}
                if ([string]::IsNullOrWhiteSpace($keySrc)) {
                    try { $keySrc = ('{0}|{1}' -f [string]$esx.GamePath, [string]$esx.OriginalTitle) } catch {}
                }
                if ([string]::IsNullOrWhiteSpace($keySrc) -or $keySrc -eq '|') { $keySrc = 'card|' + [guid]::NewGuid().ToString('N') }
                $customStore = @{ Dir = (Get-CustomCoverStoreDir (Get-GameCoverKey $keySrc)); Slot = $slotId; AutoExes = @() }
                # Для иконки автоматически предлагаем иконку(и) EXE этой игры.
                if ($slotId -eq '5') {
                    $exeList = @()
                    try {
                        $resolver = $null
                        try { $resolver = $esx.ExePathResolver } catch {}
                        if ($null -ne $resolver) { $exeList = @(& $resolver | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) }
                    } catch {}
                    # Запасной путь: сама карточка не дала EXE — ищем в папке игры.
                    if ($exeList.Count -eq 0) {
                        try {
                            $isRomCard = $false
                            try { $isRomCard = [bool]$esx.IsRom } catch {}
                            $gp = ''
                            try { $gp = [string]$esx.GamePath } catch {}
                            if (-not $isRomCard -and -not [string]::IsNullOrWhiteSpace($gp)) {
                                $exeList = @(Get-EditorExecutableCandidates $gp | Select-Object -First 6 | ForEach-Object { [string]$_.FullName })
                            }
                        } catch {}
                    }
                    $customStore.AutoExes = @($exeList)
                }
            }
        } catch { $customStore = $null }
        $chosen = Show-SgdbAssetChooser $title $items $chooserWidth $chooserHeight $slot.Panel.FindForm() $customStore
        if ([string]::IsNullOrWhiteSpace([string]$chosen)) {
            return
        }

        $fileName = switch -Regex ($title) {
            '^\s*1\.' { 'temp_p.jpg'; break }
            '^\s*2\.' { 'temp_header.jpg'; break }
            '^\s*3\.' { 'temp_hero.jpg'; break }
            '^\s*4\.' { 'temp_logo.png'; break }
            '^\s*5\.' {
                $ext = '.png'
                try {
                    if ([string]$chosen -match '\.ico(\?|$)') { $ext = '.ico' }
                    elseif ([string]$chosen -match '\.jpe?g(\?|$)') { $ext = '.jpg' }
                } catch {}
                ('temp_icon' + $ext)
                break
            }
            default { return }
        }
        $target = Join-Path $global:tempCovers $fileName
        # При выборе иконки сбрасываем остальные расширения, чтобы Get-TempIconPath
        # не вернул старый чёрный/чужой файл.
        if ($title -match '^\s*5\.') {
            foreach ($n in @('temp_icon.ico','temp_icon.png','temp_icon.jpg')) {
                $p = Join-Path $global:tempCovers $n
                if ($p -ne $target) {
                    try { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue } catch {}
                }
            }
        }

        # Своя картинка из хранилища (плитка «Выбрать свою»): это локальный файл уже в формате слота —
        # просто копируем во временный файл и показываем, без скачивания.
        if (-not ([string]$chosen -match '^(?i)https?://') -and (Test-Path -LiteralPath ([string]$chosen) -PathType Leaf)) {
            $script:sgdbChooserPickedBytes = $null
            $script:sgdbChooserPickedIsFull = $false
            try {
                Copy-Item -LiteralPath ([string]$chosen) -Destination $target -Force
                if (Set-EditorPreviewFile $slot $target) {
                    Set-EditorSourceBadge $slot 'Local'
                    $slot.SgdbSelectedUrl = $null
                }
            } catch {}
            return
        }

        # Используем тот же рабочий загрузчик, что и в старой версии.
        # Замена обложки — это тоже загрузка миниатюры, поэтому на время
        # скачивания показываем на слоте анимацию, а не пустой квадрат/крест.
        $slotForm = $null
        try { $slotForm = $slot.Panel.FindForm() } catch {}
        $pickedBytes = $script:sgdbChooserPickedBytes
        $pickedIsFull = [bool]$script:sgdbChooserPickedIsFull
        $script:sgdbChooserPickedBytes = $null
        $script:sgdbChooserPickedIsFull = $false
        $haveThumb = ($null -ne $pickedBytes -and $pickedBytes.Length -ge 512)
        $downloadedOk = $false
        if ($haveThumb -and $pickedIsFull) {
            # Миниатюра в окне выбора — это и есть полное изображение: второй раз не качаем.
            try { [System.IO.File]::WriteAllBytes($target, [byte[]]$pickedBytes); $downloadedOk = $true } catch { $downloadedOk = $false }
        }
        $interimShown = $false
        if (-not $downloadedOk) {
            if ($haveThumb) {
                # Сразу показываем уже загруженную миниатюру, а полное изображение
                # докачиваем в фоне и подменяем — без пустого слота и спиннера.
                try {
                    $previewPath = Join-Path $global:tempCovers 'sgdb_pick_preview.tmp'
                    [System.IO.File]::WriteAllBytes($previewPath, [byte[]]$pickedBytes)
                    $interimShown = [bool](Set-EditorPreviewFile $slot $previewPath)
                    try { Remove-Item -LiteralPath $previewPath -Force -ErrorAction SilentlyContinue } catch {}
                } catch { $interimShown = $false }
            }
            if ($interimShown) { $slot.IsLoading = $true } else { Set-EditorSlotLoading $slot $true }
            try { if ($null -ne $slotForm -and $null -ne $slotForm.Tag -and $null -ne $slotForm.Tag.EditorLoadTimer) { $slotForm.Tag.EditorLoadTimer.Start() } } catch {}
        }
        $global:uiPumpDuringDownload = $true
        try { if ($null -ne $slotForm) { $slotForm.Cursor = [System.Windows.Forms.Cursors]::WaitCursor } } catch {}
        try {
            if (-not $downloadedOk) { $downloadedOk = [bool](Download-RemoteImage ([string]$chosen) $target) }
            if (-not $downloadedOk -and $interimShown) {
                # Полное изображение не скачалось — возвращаем слот в состояние, соответствующее файлу на диске.
                try { [void](Set-EditorPreviewFile $slot $target) } catch {}
            }
            if ($downloadedOk) {
                if ($title -match '^\s*5\.') { $target = Repair-IconFileExtension $target }
                if ($title -match '^\s*5\.' -and $target -match '\.ico$') {
                    try {
                        $pngPath = Join-Path $global:tempCovers 'temp_icon.png'
                        $bmpIcon = Get-BitmapFromIcoFile $target
                        if ($null -ne $bmpIcon) {
                            try { $bmpIcon.Save($pngPath, [System.Drawing.Imaging.ImageFormat]::Png) } finally { $bmpIcon.Dispose() }
                            if (Test-Path -LiteralPath $pngPath) { $target = $pngPath }
                        }
                    } catch {}
                }
                if (Set-EditorPreviewFile $slot $target) {
                    Set-EditorSourceBadge $slot 'SteamGridDB'
                    $slot.SgdbSelectedUrl = [string]$chosen
                }
            }
        } finally {
            $global:uiPumpDuringDownload = $false
            Set-EditorSlotLoading $slot $false
            Set-EditorMissingState $slot ([bool]$slot.PendingMissing)
            # Таймер анимации останавливаем только если больше ничего не грузится.
            try {
                if ($null -ne $slotForm -and $null -ne $slotForm.Tag -and $null -ne $slotForm.Tag.EditorLoadTimer) {
                    $stillLoading = $false
                    foreach($other in $slotForm.Tag.EditorSlots.Values) { if ($other.IsLoading) { $stillLoading = $true } }
                    if (-not $stillLoading) { $slotForm.Tag.EditorLoadTimer.Stop() }
                }
            } catch {}
            try { if ($null -ne $slotForm) { $slotForm.Cursor = [System.Windows.Forms.Cursors]::Default } } catch {}
        }
    } catch {
        try {
            Show-AppMessageBox(
                (T 'sg_pick_fail' @([string]$_.Exception.Message)),
                'SteamGridDB',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Warning
            ) | Out-Null
        } catch {}
    }
}

# ===================== ЗНАЧКИ УВЕРЕННОСТИ (Название / EXE) =====================
# Маленький кружок рядом с полем: зелёная галочка — программа сама уверенно
# определила значение, красный восклицательный знак — не смогла и нужна
# ручная проверка. Рисуется кодом (без файлов assets), чтобы не плодить
# лишние ресурсы под два простых состояния.
function Get-ConfidenceBadgeBitmap([bool]$confident) {
    try {
        $size = 18
        $bmp = New-Object System.Drawing.Bitmap $size, $size
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.Clear([System.Drawing.Color]::Transparent)
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias

            $fill = if ($confident) { [System.Drawing.Color]::FromArgb(255, 67, 181, 129) } else { [System.Drawing.Color]::FromArgb(255, 224, 82, 82) }
            $border = if ($confident) { [System.Drawing.Color]::FromArgb(255, 45, 140, 101) } else { [System.Drawing.Color]::FromArgb(255, 176, 50, 50) }
            $brush = New-Object System.Drawing.SolidBrush($fill)
            $pen = New-Object System.Drawing.Pen($border, 1.4)
            $g.FillEllipse($brush, 1, 1, $size - 2, $size - 2)
            $g.DrawEllipse($pen, 1, 1, $size - 2, $size - 2)

            $glyphPen = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 2.1)
            $glyphPen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
            $glyphPen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
            if ($confident) {
                $pts = @(
                    (New-Object System.Drawing.PointF(4.5, 9.3)),
                    (New-Object System.Drawing.PointF(7.6, 12.6)),
                    (New-Object System.Drawing.PointF(13.5, 5.6))
                )
                $g.DrawLines($glyphPen, $pts)
            } else {
                $g.DrawLine($glyphPen, 9, 4.3, 9, 10.6)
                $dotBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
                $g.FillEllipse($dotBrush, 7.9, 12.3, 2.2, 2.2)
                $dotBrush.Dispose()
            }
            $glyphPen.Dispose(); $pen.Dispose(); $brush.Dispose()
        } finally { $g.Dispose() }
        return $bmp
    } catch { return $null }
}

function New-ConfidenceBadge($parent, [int]$x, [int]$y) {
    $pb = New-Object System.Windows.Forms.PictureBox
    $pb.Size = New-Object System.Drawing.Size(18, 18)
    $pb.Location = New-Object System.Drawing.Point($x, $y)
    $pb.BackColor = [System.Drawing.Color]::Transparent
    $pb.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $pb.Cursor = [System.Windows.Forms.Cursors]::Default
    $pb.Visible = $false
    $parent.Controls.Add($pb)
    $pb.BringToFront()
    return $pb
}

function Set-ConfidenceBadge($pictureBox, [bool]$confident, [string]$confidentTip, [string]$unsureTip) {
    try {
        if ($null -eq $pictureBox) { return }
        try { $pictureBox.AccessibleDescription = $(if ($confident) { 'ok' } else { 'unsure' }) } catch {}
        $bmp = Get-ConfidenceBadgeBitmap $confident
        try { if ($null -ne $pictureBox.Image) { $pictureBox.Image.Dispose() } } catch {}
        $pictureBox.Image = $bmp
        $pictureBox.Visible = ($null -ne $bmp)
        try {
            if ($null -eq $pictureBox.Tag -or $pictureBox.Tag -isnot [System.Windows.Forms.ToolTip]) {
                $tt = New-Object System.Windows.Forms.ToolTip
                $pictureBox.Tag = $tt
            }
            $tip = if ($confident) { $confidentTip } else { $unsureTip }
            $pictureBox.Tag.SetToolTip($pictureBox, $tip)
        } catch {}
    } catch {}
}

# Определяет Steam App ID для уже добавленной игры, не путая пользовательское
# имя ярлыка с именем папки. Для существующих shortcut'ов сначала используем
# имя папки игры (обычно это оригинальное/английское имя), затем AppName как
# запасной вариант. Найденное официальное имя Steam НЕ подменяет название,
# которое пользователь видит и редактирует в карточке.
function Find-ExistingGameSteamAppInfo($displayName, $gamePath, $existingShortcut) {
    $queries = New-Object System.Collections.Generic.List[string]

    try {
        if(-not [string]::IsNullOrWhiteSpace([string]$gamePath)) {
            $folderName = [System.IO.Path]::GetFileName($gamePath.TrimEnd('\'))
            if(-not [string]::IsNullOrWhiteSpace($folderName)) {
                [void]$queries.Add($folderName)
            }
        }
    } catch {}

    try {
        if($null -ne $existingShortcut -and -not [string]::IsNullOrWhiteSpace([string]$existingShortcut.AppName)) {
            $shortcutName = [string]$existingShortcut.AppName
            if(-not $queries.Contains($shortcutName)) { [void]$queries.Add($shortcutName) }
        }
    } catch {}

    try {
        if(-not [string]::IsNullOrWhiteSpace([string]$displayName) -and -not $queries.Contains([string]$displayName)) {
            [void]$queries.Add([string]$displayName)
        }
    } catch {}

    foreach($query in $queries) {
        try {
            $result = Find-SteamAppInfo ([string]$query)
            if($null -ne $result -and -not [string]::IsNullOrWhiteSpace([string]$result.Id)) {
                return $result
            }
        } catch {}
    }
    return $null
}


# ===================== БИБЛИОТЕКА STEAM (лицензии + non-steam) =====================
function Get-SteamLibraryFolders {
    $roots = New-Object System.Collections.Generic.List[string]
    try {
        $steamRoot = Get-ConfiguredSteamInstallPath
        if ([string]::IsNullOrWhiteSpace($steamRoot)) { return @() }
        $defaultApps = Join-Path $steamRoot 'steamapps'
        if (Test-Path -LiteralPath $defaultApps) { [void]$roots.Add([string]$defaultApps) }
        $vdfPath = Join-Path $defaultApps 'libraryfolders.vdf'
        if (Test-Path -LiteralPath $vdfPath) {
            $raw = Get-Content -LiteralPath $vdfPath -Raw -ErrorAction SilentlyContinue
            if ($raw) {
                foreach ($m in [regex]::Matches($raw, '"path"\s*"([^"]+)"')) {
                    $p = [string]$m.Groups[1].Value
                    $p = $p -replace '\\\\', '\'
                    $apps = Join-Path $p 'steamapps'
                    if ((Test-Path -LiteralPath $apps) -and -not ($roots -contains $apps)) {
                        [void]$roots.Add($apps)
                    }
                }
            }
        }
    } catch {}
    return @($roots)
}

function Get-SteamLibraryEntries {
    $list = New-Object System.Collections.Generic.List[object]
    $seenAppIds = @{}

    # 1) Установленные лицензионные игры (appmanifest_*.acf)
    foreach ($appsRoot in @(Get-SteamLibraryFolders)) {
        try {
            Get-ChildItem -LiteralPath $appsRoot -Filter 'appmanifest_*.acf' -File -ErrorAction SilentlyContinue | ForEach-Object {
                try {
                    $raw = Get-Content -LiteralPath $_.FullName -Raw -ErrorAction SilentlyContinue
                    if ([string]::IsNullOrWhiteSpace($raw)) { return }
                    $appId = ''
                    $name = ''
                    $installDir = ''
                    if ($raw -match '"appid"\s*"(\d+)"') { $appId = [string]$Matches[1] }
                    if ($raw -match '"name"\s*"([^"]*)"') { $name = [string]$Matches[1] }
                    if ($raw -match '"installdir"\s*"([^"]*)"') { $installDir = [string]$Matches[1] }
                    if ([string]::IsNullOrWhiteSpace($appId) -or $appId -eq '0') { return }
                    if ($seenAppIds.ContainsKey($appId)) { return }
                    $seenAppIds[$appId] = $true
                    if ([string]::IsNullOrWhiteSpace($name)) { $name = "App $appId" }
                    # Служебные приложения Steam (не игры) — скрываем. SteamVR (250820) намеренно остаётся.
                    $toolAppIds = @('228980','1070560','1391110','1628350','1493710','2180100','241100','1826330','1161040')
                    if ($toolAppIds -contains $appId) { return }
                    if ($name -match '^(Steamworks Common Redistributables|Proton(\s|$)|Steam Linux Runtime|Steam Controller Configs|Steam Deck Compatibility|Steam Client Bootstrapper)') { return }
                    $fullPath = ''
                    if (-not [string]::IsNullOrWhiteSpace($installDir)) {
                        $fullPath = Join-Path (Join-Path $appsRoot 'common') $installDir
                    }
                    [void]$list.Add([PSCustomObject]@{
                        Name = $name
                        AppId = $appId
                        Kind = 'steam'
                        Path = $fullPath
                        Exe = ''
                        StartDir = $fullPath
                        LaunchOptions = ''
                        ShortcutRecord = $null
                    })
                } catch {}
            }
        } catch {}
    }

    # 2) Non-Steam ярлыки из shortcuts.vdf
    try {
        $userDataPath = Get-ConfiguredSteamUserDataPath
        if (Test-Path $userDataPath) {
            Get-ShortcutsVdfFiles $userDataPath | ForEach-Object {
                try {
                    $bytes = [System.IO.File]::ReadAllBytes($_.FullName)
                    if ($bytes.Length -eq 0) { return }
                    $shortcutsNode = Get-ShortcutsNode $bytes
                    if ($null -eq $shortcutsNode) { return }
                    foreach ($entry in $shortcutsNode.Body.Children) {
                        if ($entry.Type -ne 0x00) { continue }
                        $fields = @{}
                        foreach ($field in $entry.Body.Children) {
                            if ($field.Type -eq 0x01 -or $field.Type -eq 0x02) { $fields[$field.Key] = $field }
                        }
                        $appName = if ($fields.ContainsKey('AppName')) { [string]$fields['AppName'].Value } else { '' }
                        $exe = if ($fields.ContainsKey('Exe')) { [string]$fields['Exe'].Value } else { '' }
                        $startDir = if ($fields.ContainsKey('StartDir')) { [string]$fields['StartDir'].Value } else { '' }
                        $launchOptions = if ($fields.ContainsKey('LaunchOptions')) { [string]$fields['LaunchOptions'].Value } else { '' }
                        $entryId = if ($fields.ContainsKey('appid')) { [string]$fields['appid'].Value } else { '' }
                        $cleanExe = $exe.Trim('"')
                        $cleanStart = $startDir.Trim('"')
                        if ([string]::IsNullOrWhiteSpace($appName)) { continue }
                        $record = [PSCustomObject]@{
                            FilePath = [string]$_.FullName
                            UserDataDir = [string]$_.Directory.Parent.FullName
                            Entry = $entry
                            ShortcutId = $entryId
                            AppName = $appName
                            Exe = $cleanExe
                            StartDir = $cleanStart
                            LaunchOptions = $launchOptions
                        }
                        [void]$list.Add([PSCustomObject]@{
                            Name = $appName
                            AppId = $entryId
                            Kind = 'shortcut'
                            Path = $cleanStart
                            Exe = $cleanExe
                            StartDir = $cleanStart
                            LaunchOptions = $launchOptions
                            ShortcutRecord = $record
                        })
                    }
                } catch {}
            }
        }
    } catch {}

    return @($list | Sort-Object @{Expression='Name';Ascending=$true})
}

# Размер картинки по ЗАГОЛОВКУ файла (без полного декодирования). Результат кэшируется по пути+размеру+времени файла.
$script:coverSizeCache = @{}
function Get-ImageSizeFast ([string]$Path) {
    try {
        $fi = New-Object System.IO.FileInfo($Path)
        if (-not $fi.Exists) { return $null }
        $key = $fi.FullName + '|' + $fi.Length + '|' + $fi.LastWriteTimeUtc.Ticks
        if ($script:coverSizeCache.ContainsKey($key)) { return $script:coverSizeCache[$key] }
        $res = $null
        $fs = New-Object System.IO.FileStream($fi.FullName, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try {
            $img = [System.Drawing.Image]::FromStream($fs, $false, $false)
            try { $res = @([int]$img.Width, [int]$img.Height) } finally { $img.Dispose() }
        } finally { $fs.Dispose() }
        $script:coverSizeCache[$key] = $res
        return $res
    } catch { return $null }
}

function Test-LibraryCoverCandidateFile ([string]$path) {
    # Отсекает иконки/логотипы: слишком маленькие или почти квадратные мелкие файлы.
    if ([string]::IsNullOrWhiteSpace($path)) { return $false }
    try {
        $fi = New-Object System.IO.FileInfo($path)
        if (-not $fi.Exists) { return $false }
        if ($fi.Length -lt 2048) { return $false }
        $n = $fi.Name.ToLowerInvariant()
        if ($n -match '(^|[^a-z])(logo|icon|clienticon|clienttga|tga|blur)([^a-z]|$)') { return $false }
        $sz = Get-ImageSizeFast $fi.FullName
        if ($null -eq $sz) { return $false }
        $w = [int]$sz[0]
        $h = [int]$sz[1]
        if ($w -lt 120 -or $h -lt 120) { return $false }
        $ratio = if ($h -gt 0) { $w / [double]$h } else { 1 }
        # Иконки/логотипы обычно квадрат ~1:1. Обложка библиотеки — портрет ~2:3 или широкий header ~2:1.
        if ($ratio -gt 0.85 -and $ratio -lt 1.15) { return $false }
        return $true
    } catch { return $false }
}

function Get-LibraryCoverPathCore ([string]$appId) {
    if ([string]::IsNullOrWhiteSpace($appId) -or $appId -notmatch '^\d+$') { return $null }
    try {
        $ranked = New-Object System.Collections.Generic.List[object]

        $addFile = {
            param([string]$p, [int]$prio)
            if ([string]::IsNullOrWhiteSpace($p)) { return }
            try {
                $fi = New-Object System.IO.FileInfo($p)
                if (-not $fi.Exists) { return }
                if ($fi.Length -lt 2048) { return }
                $n = $fi.Name.ToLowerInvariant()
                if ($n -match 'logo|icon|clienticon|clienttga|blur|\.tga$') { return }
                if (-not (Test-LibraryCoverCandidateFile $fi.FullName)) { return }
                # Уточняем приоритет по пропорциям: портрет выше широкого header.
                $extra = 15
                $sz = Get-ImageSizeFast $fi.FullName
                if ($null -ne $sz) {
                    $w = [int]$sz[0]; $h = [int]$sz[1]
                    if ($h -gt ($w * 1.15)) { $extra = 0 }
                    elseif ($w -gt ($h * 1.15)) { $extra = 8 }
                    else { $extra = 20 }
                }
                [void]$ranked.Add([PSCustomObject]@{ Path = $fi.FullName; Prio = ($prio + $extra); Size = [int64]$fi.Length })
            } catch {}
        }

        $scanAppDir = {
            param([string]$dir, [int]$basePrio)
            if ([string]::IsNullOrWhiteSpace($dir) -or -not [System.IO.Directory]::Exists($dir)) { return }
            try {
                foreach ($fp in [System.IO.Directory]::EnumerateFiles($dir)) {
                    $n = [System.IO.Path]::GetFileName($fp).ToLowerInvariant()
                    if ($n -notmatch '\.(jpe?g|png)$') { continue }
                    if ($n -match 'logo|icon|clienticon|blur') { continue }
                    # library_hero — широкий баннер, для портретной плитки не используем.
                    if ($n -match 'library_hero|hero_blur') { continue }
                    $prio = $basePrio + 40
                    if ($n -match '600x900|library_600') { $prio = $basePrio }
                    elseif ($n -match 'library_capsule') { $prio = $basePrio + 3 }
                    elseif ($n -match 'header') { $prio = $basePrio + 18 }
                    elseif ($n -match 'capsule') { $prio = $basePrio + 22 }
                    & $addFile $fp $prio
                }
            } catch {}
        }

        foreach ($root in @(Get-CoverProfileRoots)) {
            $grid = [System.IO.Path]::Combine($root, 'config\grid')
            foreach ($name in @(
                ($appId + 'p.jpg'), ($appId + 'p.png'),
                ($appId + '_library_600x900.jpg'), ($appId + '_library_600x900.png'),
                ($appId + '.jpg'), ($appId + '.png')
            )) {
                & $addFile ([System.IO.Path]::Combine($grid, $name)) 0
            }

            $libCache = [System.IO.Path]::Combine($root, 'librarycache')
            foreach ($rel in @(
                ($appId + '\library_600x900.jpg'),
                ($appId + '\library_600x900_2x.jpg'),
                ($appId + '\library_capsule.jpg'),
                ($appId + '\library_capsule_2x.jpg'),
                ($appId + '\header.jpg'),
                ($appId + '_library_600x900.jpg'),
                ($appId + '_library_capsule.jpg')
            )) {
                & $addFile ([System.IO.Path]::Combine($libCache, $rel)) 10
            }
            & $scanAppDir ([System.IO.Path]::Combine($libCache, $appId)) 20
            # Раньше здесь листалась ВСЯ папка librarycache и фильтровалась в PowerShell — для каждой игры.
            # Теперь фильтр по префиксу делает сама файловая система.
            try {
                if ([System.IO.Directory]::Exists($libCache)) {
                    foreach ($fp in [System.IO.Directory]::EnumerateFiles($libCache, ($appId + '*'))) {
                        $n = [System.IO.Path]::GetFileName($fp)
                        if ($n -notmatch '\.(jpe?g|png)$') { continue }
                        if ($n -match 'logo|icon') { continue }
                        & $addFile $fp 28
                    }
                }
            } catch {}
        }

        try {
            $steamRoot = Get-ConfiguredSteamInstallPath
            if (-not [string]::IsNullOrWhiteSpace($steamRoot)) {
                $appc = [System.IO.Path]::Combine($steamRoot, 'appcache\librarycache')
                foreach ($name in @(
                    ($appId + '_library_600x900.jpg'),
                    ($appId + '_library_600x900_2x.jpg'),
                    ($appId + '_library_capsule.jpg'),
                    ($appId + '_library_capsule_2x.jpg')
                )) {
                    & $addFile ([System.IO.Path]::Combine($appc, $name)) 30
                }
                & $scanAppDir ([System.IO.Path]::Combine($appc, $appId)) 35
            }
        } catch {}

        if ($ranked.Count -eq 0) { return $null }
        $best = $ranked | Sort-Object Prio, @{Expression='Size';Descending=$true} | Select-Object -First 1
        if ($null -ne $best) { return [string]$best.Path }
    } catch {}
    return $null
}

# ---- Кэш "appId -> выбранный файл обложки" (память + файл cover_index.txt) ----
# Запись действительна, пока не изменились: даты папок config\grid, librarycache (+ подпапка игры)
# и appcache\librarycache (+ подпапка игры), а выбранный файл — по размеру и дате.
# Любое добавление/удаление файла в этих папках меняет дату папки — игра пересчитывается полностью.
$script:coverPathMemo = @{}
$script:coverPathMemoLoaded = $false
$script:coverPathMemoDirty = $false
$script:coverProfileRootsKey = $null
$script:coverProfileRoots = @()

function Get-CoverProfileRoots {
    $key = [string]$global:steamInstallPath + '|' + [string]$global:steamUserId
    if ($null -ne $script:coverProfileRootsKey -and $script:coverProfileRootsKey -eq $key) { return $script:coverProfileRoots }
    $roots = New-Object System.Collections.Generic.List[string]
    try { foreach ($p in @(Get-ConfiguredSteamProfileDirectories)) { [void]$roots.Add([string]$p.FullName) } } catch {}
    $script:coverProfileRoots = $roots.ToArray()
    $script:coverProfileRootsKey = $key
    return $script:coverProfileRoots
}

function Initialize-CoverPathMemo {
    if ($script:coverPathMemoLoaded) { return }
    $script:coverPathMemoLoaded = $true
    try {
        $f = Join-Path $global:appDataDir 'cover_index.txt'
        if ([System.IO.File]::Exists($f)) {
            foreach ($line in [System.IO.File]::ReadAllLines($f, [System.Text.Encoding]::UTF8)) {
                $p = $line.Split("`t")
                if ($p.Count -lt 5) { continue }
                $script:coverPathMemo[[string]$p[0]] = [PSCustomObject]@{ Stamp = [string]$p[1]; Len = [int64]$p[2]; Ticks = [int64]$p[3]; Path = [string]$p[4] }
            }
        }
    } catch {}
}

function Save-CoverPathMemo {
    if (-not $script:coverPathMemoDirty) { return }
    try {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($k in @($script:coverPathMemo.Keys)) {
            $m = $script:coverPathMemo[$k]
            [void]$lines.Add(([string]$k + "`t" + $m.Stamp + "`t" + $m.Len + "`t" + $m.Ticks + "`t" + $m.Path))
        }
        [System.IO.File]::WriteAllLines((Join-Path $global:appDataDir 'cover_index.txt'), $lines.ToArray(), (New-Object System.Text.UTF8Encoding($false)))
        $script:coverPathMemoDirty = $false
    } catch {}
}

function Get-CoverDirStamp ([string]$appId) {
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($root in @(Get-CoverProfileRoots)) {
        $lc = [System.IO.Path]::Combine($root, 'librarycache')
        [void]$parts.Add($root)
        [void]$parts.Add([string][System.IO.Directory]::GetLastWriteTimeUtc([System.IO.Path]::Combine($root, 'config\grid')).Ticks)
        [void]$parts.Add([string][System.IO.Directory]::GetLastWriteTimeUtc($lc).Ticks)
        [void]$parts.Add([string][System.IO.Directory]::GetLastWriteTimeUtc([System.IO.Path]::Combine($lc, $appId)).Ticks)
    }
    $steamRoot = Get-ConfiguredSteamInstallPath
    if (-not [string]::IsNullOrWhiteSpace($steamRoot)) {
        $appc = [System.IO.Path]::Combine($steamRoot, 'appcache\librarycache')
        [void]$parts.Add([string][System.IO.Directory]::GetLastWriteTimeUtc($appc).Ticks)
        [void]$parts.Add([string][System.IO.Directory]::GetLastWriteTimeUtc([System.IO.Path]::Combine($appc, $appId)).Ticks)
    }
    return ($parts -join ',')
}

function Get-LibraryCoverPath ([string]$appId) {
    if ([string]::IsNullOrWhiteSpace($appId) -or $appId -notmatch '^\d+$') { return $null }
    Initialize-CoverPathMemo
    $stamp = ''
    try { $stamp = Get-CoverDirStamp $appId } catch { $stamp = '' }
    if ($stamp) {
        $m = $script:coverPathMemo[$appId]
        if ($null -ne $m -and $m.Stamp -eq $stamp) {
            if ([string]::IsNullOrEmpty($m.Path)) { Add-TmA 'pathMemoHit_n' 1; return $null }
            try {
                $fi = New-Object System.IO.FileInfo($m.Path)
                if ($fi.Exists -and $fi.Length -eq $m.Len -and $fi.LastWriteTimeUtc.Ticks -eq $m.Ticks) { Add-TmA 'pathMemoHit_n' 1; return [string]$m.Path }
            } catch {}
        }
    }
    Add-TmA 'pathMemoMiss_n' 1
    $res = Get-LibraryCoverPathCore $appId
    if ($stamp) {
        $len = [int64]0; $ticks = [int64]0
        if ($res) { try { $fi2 = New-Object System.IO.FileInfo([string]$res); $len = [int64]$fi2.Length; $ticks = [int64]$fi2.LastWriteTimeUtc.Ticks } catch {} }
        $script:coverPathMemo[$appId] = [PSCustomObject]@{ Stamp = $stamp; Len = $len; Ticks = $ticks; Path = [string]$res }
        $script:coverPathMemoDirty = $true
    }
    return $res
}



function Get-LibraryHeaderPath ([string]$appId, [string]$userDataDir = '') {
    # Горизонтальная обложка (header), НЕ hero/фон.
    # Те же локальные пути, что у карточки игры. Без сети.
    if ([string]::IsNullOrWhiteSpace($appId)) { return $null }
    $id = $appId.Trim()
    try {
        # Два списка: сначала настоящий header, потом hero только как запасной.
        $headers = New-Object System.Collections.Generic.List[string]
        $heroes  = New-Object System.Collections.Generic.List[string]

        $addPath = {
            param([string]$p, [string]$kind)
            if ([string]::IsNullOrWhiteSpace($p)) { return }
            try {
                if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { return }
                $fi = Get-Item -LiteralPath $p -ErrorAction Stop
                if ($fi.Length -lt 2048) { return }
                if ($kind -eq 'hero') { [void]$heroes.Add($fi.FullName) }
                else { [void]$headers.Add($fi.FullName) }
            } catch {}
        }

        $scanGrid = {
            param([string]$gridDir)
            if ([string]::IsNullOrWhiteSpace($gridDir) -or -not (Test-Path -LiteralPath $gridDir -PathType Container)) { return }
            # {id}.jpg в grid — горизонтальная (как temp_header в редакторе).
            foreach ($n in @(($id + '.jpg'), ($id + '.png'), ($id + '_header.jpg'))) {
                & $addPath (Join-Path $gridDir $n) 'header'
            }
            # hero в grid — только fallback.
            foreach ($n in @(($id + '_hero.jpg'), ($id + '_library_hero.jpg'))) {
                & $addPath (Join-Path $gridDir $n) 'hero'
            }
        }

        $scanLibCache = {
            param([string]$libCache)
            if ([string]::IsNullOrWhiteSpace($libCache) -or -not (Test-Path -LiteralPath $libCache -PathType Container)) { return }
            foreach ($rel in @(
                (Join-Path $id 'header.jpg'),
                (Join-Path $id 'library_header.jpg'),
                (Join-Path $id 'library_header_2x.jpg'),
                ($id + '_header.jpg'),
                ($id + '_library_header.jpg')
            )) {
                & $addPath (Join-Path $libCache $rel) 'header'
            }
            foreach ($rel in @(
                (Join-Path $id 'library_hero.jpg'),
                (Join-Path $id 'library_hero_2x.jpg'),
                ($id + '_library_hero.jpg')
            )) {
                & $addPath (Join-Path $libCache $rel) 'hero'
            }
            $appDir = Join-Path $libCache $id
            try {
                if (Test-Path -LiteralPath $appDir -PathType Container) {
                    Get-ChildItem -LiteralPath $appDir -File -ErrorAction SilentlyContinue | ForEach-Object {
                        if ($_.Length -lt 2048) { return }
                        if ($_.Name -notmatch '\.(jpe?g|png)$') { return }
                        if ($_.Name -match 'logo|icon|capsule|600x900|portrait') { return }
                        $n = $_.Name.ToLowerInvariant()
                        if ($n -match 'header') { & $addPath $_.FullName 'header' }
                        elseif ($n -match 'hero') { & $addPath $_.FullName 'hero' }
                    }
                }
            } catch {}
        }

        if (-not [string]::IsNullOrWhiteSpace($userDataDir)) {
            & $scanGrid (Join-Path $userDataDir 'config\grid')
            & $scanLibCache (Join-Path $userDataDir 'librarycache')
        }
        try {
            foreach ($profile in @(Get-ConfiguredSteamProfileDirectories)) {
                $root = [string]$profile.FullName
                if (-not [string]::IsNullOrWhiteSpace($userDataDir) -and ($root -eq $userDataDir)) { continue }
                & $scanGrid (Join-Path $root 'config\grid')
                & $scanLibCache (Join-Path $root 'librarycache')
            }
        } catch {}
        try {
            $steamRoot = Get-ConfiguredSteamInstallPath
            if (-not [string]::IsNullOrWhiteSpace($steamRoot)) {
                $appc = Join-Path $steamRoot 'appcache\librarycache'
                & $scanLibCache $appc
                $appDir = Join-Path $appc $id
                try {
                    if (Test-Path -LiteralPath $appDir -PathType Container) {
                        Get-ChildItem -LiteralPath $appDir -Recurse -File -ErrorAction SilentlyContinue |
                            Where-Object {
                                $_.Length -gt 2048 -and
                                $_.Name -match '\.(jpe?g|png)$' -and
                                $_.Name -match 'header|hero' -and
                                $_.Name -notmatch 'logo|icon|600x900'
                            } |
                            Select-Object -First 30 |
                            ForEach-Object {
                                $n = $_.Name.ToLowerInvariant()
                                if ($n -match 'header') { & $addPath $_.FullName 'header' }
                                elseif ($n -match 'hero') { & $addPath $_.FullName 'hero' }
                            }
                    }
                } catch {}
            }
        } catch {}

        $pickWide = {
            param($list)
            foreach ($p in $list) {
                try {
                    $bmp = New-Object System.Drawing.Bitmap($p)
                    try {
                        if ($bmp.Width -ge [int]($bmp.Height * 1.15)) { return $p }
                    } finally { $bmp.Dispose() }
                } catch {
                    # Не прочитали размеры — для явного header всё равно отдаём.
                    $n = [System.IO.Path]::GetFileName($p).ToLowerInvariant()
                    if ($n -match 'header' -or $n -match ('^' + [regex]::Escape($id.ToLowerInvariant()) + '\.(jpe?g|png)$')) { return $p }
                }
            }
            return $null
        }

        $best = & $pickWide $headers
        if ($best) { return $best }
        # Hero только если header нигде нет.
        $best = & $pickWide $heroes
        if ($best) { return $best }
        return $null
    } catch { return $null }
}


# ===================== ЛАУНЧЕРЫ: ОБНАРУЖЕНИЕ И СПИСОК ИХ ИГР =====================
# Окно "Библиотека/Импорт" показывает вкладки по обнаруженным в системе
# лаунчерам (Epic Games, GOG, Ubisoft Connect, EA app, Battle.net). Здесь — только чтение
# данных самих лаунчеров (манифесты / реестр), без сети и без записи чего-либо.
# Каждая игра — объект, совместимый по полям с элементами Get-SteamLibraryEntries
# (Name/Path/StartDir/Exe...), плюс Kind='launcher', Key и AlreadyInSteam.

function Get-RegValueSafe ([string]$Path, [string]$Name) {
    try {
        $v = (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction Stop).$Name
        if ($null -eq $v) { return '' }
        return [string]$v
    } catch { return '' }
}

function Get-RegSubKeysSafe ([string]$Path) {
    try { return @(Get-ChildItem -LiteralPath $Path -ErrorAction Stop) } catch { return @() }
}

# Ищет запись об установленной программе по DisplayName (regex) в разделах Uninstall.
function Find-UninstallEntryByName ([string]$Pattern) {
    foreach ($root in @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'
    )) {
        foreach ($k in @(Get-RegSubKeysSafe $root)) {
            try {
                $dn = [string]$k.GetValue('DisplayName')
                if ($dn -match $Pattern) {
                    return [PSCustomObject]@{
                        DisplayName     = $dn
                        InstallLocation = [string]$k.GetValue('InstallLocation')
                        DisplayIcon     = [string]$k.GetValue('DisplayIcon')
                    }
                }
            } catch {}
        }
    }
    return $null
}

# Иконка exe-файла лаунчера в виде квадратной Bitmap (для значка на вкладке).
function Get-IconBitmapFromFile ($FilePath, $Size = 20) {
    try {
        $Size = [int]$Size
        $p = ([string]$FilePath).Trim().Trim('"')
        $p = ($p -replace ',\s*-?\d+$', '')
        if ([string]::IsNullOrWhiteSpace($p) -or -not (Test-Path -LiteralPath $p -PathType Leaf)) { return $null }
        $ico = [System.Drawing.Icon]::ExtractAssociatedIcon($p)
        if ($null -eq $ico) { return $null }
        $bmp = New-Object System.Drawing.Bitmap($Size, $Size, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.Clear([System.Drawing.Color]::Transparent)
            $g.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceOver
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
            $src = $ico.ToBitmap()
            try { $g.DrawImage($src, 0, 0, $Size, $Size) } finally { $src.Dispose() }
        } finally { $g.Dispose(); $ico.Dispose() }
        return $bmp
    } catch { return $null }
}

# Кэш собственных иконок файлов (.exe/.lnk) для панелей библиотеки.
if ($null -eq $script:panelFileIconCache) { $script:panelFileIconCache = @{} }

function Get-PanelFileIconBitmap ([string]$filePath, [int]$size = 16) {
    try {
        if ([string]::IsNullOrWhiteSpace($filePath)) { return $null }
        $key = $filePath.ToLowerInvariant() + '|' + $size
        if ($script:panelFileIconCache.ContainsKey($key)) {
            return $script:panelFileIconCache[$key]
        }
        $bmp = Get-IconBitmapFromFile $filePath $size
        $script:panelFileIconCache[$key] = $bmp  # может быть $null — не дёргаем повторно
        return $bmp
    } catch { return $null }
}

# Запасной значок: цветной кружок с буквой (если exe лаунчера не найден/без иконки).

# ===================== ЗНАЧОК «Non-Steam» =====================
# Шрифт интерфейса Steam — Motiva Sans. Берём его, если он установлен в системе или лежит
# в папке Steam (clientui / resource / steamui). Иначе — ближайший по виду Segoe UI Semibold.
$script:steamUiFontFamily = $null
$script:steamUiPrivateFonts = $null
$script:nonSteamBadgeCache = @{}

function Get-SteamUiFontFamily {
    if ($null -ne $script:steamUiFontFamily) { return $script:steamUiFontFamily }
    $fam = $null
    try {
        foreach ($ff in [System.Drawing.FontFamily]::Families) {
            if ($ff.Name -like 'Motiva Sans*') { $fam = $ff; break }
        }
    } catch {}
    if ($null -eq $fam) {
        try {
            $root = Get-ConfiguredSteamInstallPath
            if (-not [string]::IsNullOrWhiteSpace($root)) {
                $pfc = New-Object System.Drawing.Text.PrivateFontCollection
                $loaded = $false
                foreach ($sub in @('clientui', 'resource', 'steamui', 'public')) {
                    $d = Join-Path $root $sub
                    if (-not (Test-Path -LiteralPath $d -PathType Container)) { continue }
                    $files = @(Get-ChildItem -LiteralPath $d -Recurse -File -Include 'Motiva*.ttf', 'Motiva*.otf' -ErrorAction SilentlyContinue | Select-Object -First 4)
                    foreach ($f in $files) { try { $pfc.AddFontFile($f.FullName); $loaded = $true } catch {} }
                    if ($loaded) { break }
                }
                if ($loaded -and $pfc.Families.Count -gt 0) {
                    $script:steamUiPrivateFonts = $pfc   # коллекция должна жить, пока используется шрифт
                    $fam = $pfc.Families[0]
                }
            }
        } catch {}
    }
    if ($null -eq $fam) {
        foreach ($nm in @('Segoe UI Semibold', 'Segoe UI', 'Arial')) {
            try { $fam = New-Object System.Drawing.FontFamily($nm); break } catch {}
        }
    }
    $script:steamUiFontFamily = $fam
    return $fam
}

function Get-SteamUiFont ([single]$px) {
    $fam = Get-SteamUiFontFamily
    try { return (New-Object System.Drawing.Font($fam, $px, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)) } catch {}
    try { return (New-Object System.Drawing.Font($fam, $px, [System.Drawing.FontStyle]::Regular, [System.Drawing.GraphicsUnit]::Pixel)) } catch {}
    return (New-Object System.Drawing.Font('Segoe UI', $px, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel))
}

function Get-RoundedRectPath ([single]$x, [single]$y, [single]$w, [single]$h, [single]$r) {
    $path = New-Object System.Drawing.Drawing2D.GraphicsPath
    $d = [Math]::Max(0.1, $r * 2)
    $path.AddArc($x, $y, $d, $d, 180, 90)
    $path.AddArc($x + $w - $d, $y, $d, $d, 270, 90)
    $path.AddArc($x + $w - $d, $y + $h - $d, $d, $d, 0, 90)
    $path.AddArc($x, $y + $h - $d, $d, $d, 90, 90)
    $path.CloseFigure()
    return $path
}

# Бейдж «Non-Steam»: плоская капсула высотой 16 px — тёмно-синяя заливка Steam, тонкая голубая рамка,
# светлый текст шрифтом Steam (см. Get-SteamUiFontFamily).
function Get-NonSteamBadgeBitmap ([int]$h = 16, [string]$kind = 'shortcut') {
    $cacheKey = [string]$h + '|' + $kind
    if ($script:nonSteamBadgeCache.ContainsKey($cacheKey)) { return $script:nonSteamBadgeCache[$cacheKey] }
    $text = 'Non-Steam'
    if ($kind -eq 'rom') { $text = 'ROM' }
    else { try { $text = [string](T 'lib_kind_shortcut') } catch {} }
    $font = Get-SteamUiFont ([single]($h * 0.625))
    $sf = [System.Drawing.StringFormat]::GenericTypographic
    $tmp = New-Object System.Drawing.Bitmap(1, 1)
    $tg = [System.Drawing.Graphics]::FromImage($tmp)
    $tw = 0
    try {
        $tg.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAlias
        $tw = [int][Math]::Ceiling($tg.MeasureString($text, $font, 1000, $sf).Width)
    } finally { $tg.Dispose(); $tmp.Dispose() }
    $padX = 7
    $w = $tw + $padX * 2
    $bmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAlias
        $g.Clear([System.Drawing.Color]::Transparent)
        $fillBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(27, 40, 56))
        $fillPath = Get-RoundedRectPath 0 0 $w $h ($h / 2.0)
        $borderPath = Get-RoundedRectPath 0.5 0.5 ($w - 1) ($h - 1) (($h - 1) / 2.0)
        $borderPen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(61, 126, 166), 1)
        $textBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(199, 213, 224))
        try {
            $g.FillPath($fillBrush, $fillPath)
            $g.DrawPath($borderPen, $borderPath)
            $ty = [single](($h - $font.GetHeight($g)) / 2.0)
            $g.DrawString($text, $font, $textBrush, [single]$padX, $ty, $sf)
        } finally { $fillBrush.Dispose(); $fillPath.Dispose(); $borderPath.Dispose(); $borderPen.Dispose(); $textBrush.Dispose() }
    } finally { $g.Dispose(); $font.Dispose() }
    $script:nonSteamBadgeCache[$cacheKey] = $bmp
    return $bmp
}

# Готовый контрол с бейджем «Non-Steam» (обрезан по скруглённой форме, поэтому поверх обложки без тёмных углов).
function New-NonSteamBadgeControl ([int]$h = 16, [string]$kind = 'shortcut') {
    $bmp = Get-NonSteamBadgeBitmap $h $kind
    $pb = New-Object System.Windows.Forms.PictureBox
    $pb.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Normal
    $pb.Size = New-Object System.Drawing.Size([int]$bmp.Width, [int]$bmp.Height)
    $pb.Image = $bmp
    $pb.BackColor = [System.Drawing.Color]::FromArgb(27, 40, 56)
    $pb.Cursor = [System.Windows.Forms.Cursors]::Hand
    try {
        $rp = Get-RoundedRectPath 0 0 $bmp.Width $bmp.Height ($bmp.Height / 2.0)
        try { $pb.Region = New-Object System.Drawing.Region($rp) } finally { $rp.Dispose() }
    } catch {}
    return $pb
}

function Add-LauncherBadgeToPictureBox ($Pic, $IconBmp, [int]$BadgeSize = 22, [int]$Margin = 6) {
    try {
        if ($null -eq $Pic -or $null -eq $IconBmp) { return }
        $pw = [Math]::Max(1, [int]$Pic.Width)
        $ph = [Math]::Max(1, [int]$Pic.Height)
        $baseImg = $Pic.Image
        $canvas = New-Object System.Drawing.Bitmap($pw, $ph, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $g = [System.Drawing.Graphics]::FromImage($canvas)
        try {
            $g.Clear([System.Drawing.Color]::Transparent)
            $g.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceOver
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
            if ($null -ne $baseImg) { $g.DrawImage($baseImg, 0, 0, $pw, $ph) }
            else { $g.Clear([System.Drawing.Color]::FromArgb(20, 24, 28)) }
            $bx = [Math]::Max(0, $pw - $BadgeSize - $Margin)
            $by = $Margin
            $g.DrawImage($IconBmp, $bx, $by, $BadgeSize, $BadgeSize)
        } finally { $g.Dispose() }
        try {
            $Pic.Image = $null
            if ($null -ne $baseImg) { $baseImg.Dispose() }
        } catch {}
        $Pic.Image = $canvas
        $Pic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Normal
    } catch {}
}

function Get-ShortcutLauncherId ($Entry) {
    try {
        if ($null -eq $Entry) { return '' }
        if ([string]$Entry.Kind -ne 'shortcut') { return '' }
        $exe = ([string]$Entry.Exe).Trim().Trim('"')
        $lo  = [string]$Entry.LaunchOptions
        $isWrap = $false
        try {
            if ($exe -and ([System.IO.Path]::GetFileName($exe) -ieq 'SCLauncher.exe')) { $isWrap = $true }
        } catch {}
        if ($isWrap -or ($lo -match '--uri\s+"')) {
            if ($lo -match 'com\.epicgames\.launcher') { return 'epic' }
            if ($lo -match 'gog:') { return 'gog' }
            if ($lo -match 'uplay:') { return 'ubisoft' }
        }
        if ($null -eq $script:libLauncherMap -or $script:libLauncherMap.Count -eq 0) { return '' }
        # Ключи — только пути самого ярлыка (папка игры, рабочая папка, exe). Родительские папки
        # сюда НЕ добавляем: для обычной non-Steam игры это корень общей библиотеки (D:\Games), и под
        # него попадала любая игра лаунчера из той же папки — отсюда ложные значки EGS/GOG/Ubisoft.
        $keys = New-Object System.Collections.Generic.List[string]
        foreach ($p in @([string]$Entry.Path, [string]$Entry.StartDir, $exe)) {
            if ([string]::IsNullOrWhiteSpace($p)) { continue }
            try {
                $nk = Get-NormalizedGamePathKey $p
                if ($nk -and -not $keys.Contains($nk)) { [void]$keys.Add($nk) }
            } catch {}
        }
        if ($keys.Count -eq 0) { return '' }
        $sep = [string][System.IO.Path]::DirectorySeparatorChar
        $entryNameKey = ([string]$Entry.Name).Trim().ToUpperInvariant()
        foreach ($lid in @($script:libLauncherMap.Keys)) {
            $src = $script:libLauncherMap[$lid]
            if ($null -eq $src) { continue }
            foreach ($g in @($src.Games)) {
                $gk = ''
                try { $gk = Get-NormalizedGamePathKey ([string]$g.Path) } catch { $gk = '' }
                if (-not $gk) { continue }
                foreach ($k in $keys) {
                    # Тот же путь или ярлык лежит внутри папки игры лаунчера.
                    if ($k -eq $gk) { return [string]$lid }
                    if ($k.StartsWith($gk + $sep, [System.StringComparison]::OrdinalIgnoreCase)) { return [string]$lid }
                    # Путь ярлыка выше папки игры лаунчера (игра во вложенной папке) — только при совпадении названия.
                    if ($entryNameKey -and $gk.StartsWith($k + $sep, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $gn = ''
                        try { $gn = ([string]$g.Name).Trim().ToUpperInvariant() } catch { $gn = '' }
                        if ($gn -and $gn -eq $entryNameKey) { return [string]$lid }
                    }
                }
            }
        }
    } catch {}
    return ''
}

function New-LauncherGlyphBitmap ($Letter, $Color, $Size = 20) {
    $Letter = [string]$Letter
    $Size = [int]$Size
    $bmp = New-Object System.Drawing.Bitmap($Size, $Size, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.Clear([System.Drawing.Color]::Transparent)
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
        $br = New-Object System.Drawing.SolidBrush($Color)
        try { $g.FillEllipse($br, 0, 0, ($Size - 1), ($Size - 1)) } finally { $br.Dispose() }
        $fs = if ($Letter.Length -gt 1) { $Size * 0.40 } else { $Size * 0.58 }
        $font = New-Object System.Drawing.Font('Segoe UI', [single]$fs, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
        $sf = New-Object System.Drawing.StringFormat
        $sf.Alignment = [System.Drawing.StringAlignment]::Center
        $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
        $wb = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
        try {
            $g.DrawString($Letter, $font, $wb, (New-Object System.Drawing.RectangleF(0, 0, $Size, $Size)), $sf)
        } finally { $wb.Dispose(); $sf.Dispose(); $font.Dispose() }
    } finally { $g.Dispose() }
    return $bmp
}

# Игра лаунчера. $SteamShortcuts — Non-Steam ярлыки (Kind='shortcut') из библиотеки Steam:
# по ним и по $global:installedSteamGames определяем, что игра уже добавлена в Steam
# (совпадение строго по расположению на диске, не по имени — как и в остальной программе).
function New-LauncherGameEntry ([string]$LauncherId, [string]$LauncherName, [string]$GameId, [string]$Name, [string]$Dir, [string]$Exe, $SteamShortcuts, [string]$CatalogId = '', [string]$CatalogNamespace = '') {
    $dirClean = ([string]$Dir).Trim().Trim('"').Replace('/', '\').TrimEnd('\')
    $inSteam = $false
    try {
        $dk = Get-NormalizedGamePathKey $dirClean
        if ($dk -and $global:installedSteamGames.ContainsKey($dk)) { $inSteam = $true }
        if (-not $inSteam -and $dk) {
            $prefix = $dk + '\'
            foreach ($sc in @($SteamShortcuts)) {
                foreach ($p in @([string]$sc.Exe, [string]$sc.StartDir)) {
                    $pk = Get-NormalizedGamePathKey $p
                    if ($pk -and ($pk -eq $dk -or $pk.StartsWith($prefix))) { $inSteam = $true; break }
                }
                if ($inSteam) { break }
            }
        }
    } catch {}
    $gid = [string]$GameId
    if ([string]::IsNullOrWhiteSpace($gid)) { $gid = $Name + '@' + $dirClean }
    return [PSCustomObject]@{
        Name           = [string]$Name
        AppId          = ''
        Kind           = 'launcher'
        Launcher       = [string]$LauncherId
        LauncherName   = [string]$LauncherName
        GameId         = $gid
        CatalogId      = [string]$CatalogId
        CatalogNamespace = [string]$CatalogNamespace
        Key            = ($LauncherId + '|' + $gid)
        Path           = $dirClean
        Exe            = [string]$Exe
        StartDir       = $dirClean
        LaunchOptions  = ''
        ShortcutRecord = $null
        AlreadyInSteam = [bool]$inSteam
    }
}

function New-LauncherSourceObject ($Id, $Name, $Letter, $ColorRgb, $ExeCandidates, $Games) {
    # Без типизированных параметров: привязка [System.Drawing.Color]/[string[]] здесь падала
    # с "Типы аргумента не совпадают". Цвет передаётся тройкой R,G,B.
    $Color = [System.Drawing.Color]::FromArgb([int]$ColorRgb[0], [int]$ColorRgb[1], [int]$ColorRgb[2])
    $exe = ''
    foreach ($c in @($ExeCandidates)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$c) -and (Test-Path -LiteralPath $c -PathType Leaf)) { $exe = $c; break }
    }
    # Встроенный значок лаунчера; значок из exe и кружок с буквой — только запасные варианты.
    # Все варианты приводятся к единому размеру/качеству ($global:LibIconSize) через ConvertTo-LibUniformIcon.
    $icon = $null
    try { $icon = Get-LibUniformIcon ([string]$Id) } catch {}
    if ($null -eq $icon -and $exe) {
        $exeBmp = $null
        try { $exeBmp = Get-BitmapFromExeFile $exe } catch { $exeBmp = $null }
        if ($null -ne $exeBmp) { try { $icon = ConvertTo-LibUniformIcon $exeBmp } finally { try { $exeBmp.Dispose() } catch {} } }
    }
    if ($null -eq $icon) {
        $gl = New-LauncherGlyphBitmap $Letter $Color 64
        try { $icon = ConvertTo-LibUniformIcon $gl } finally { try { $gl.Dispose() } catch {} }
    }
    return [PSCustomObject]@{
        Id       = [string]$Id
        Name     = [string]$Name
        ExePath  = $exe
        Detected = [bool]$exe
        Icon     = $icon
        Color    = $Color
        Games    = @($Games | Sort-Object -Property Name)
    }
}

function Get-EpicLauncherSource ($SteamShortcuts) {
    $exes = New-Object System.Collections.Generic.List[string]
    foreach ($base in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        foreach ($sub in @('Win32', 'Win64')) {
            [void]$exes.Add((Join-Path $base ('Epic Games\Launcher\Portal\Binaries\' + $sub + '\EpicGamesLauncher.exe')))
        }
    }
    try {
        $u = Find-UninstallEntryByName '^Epic Games Launcher'
        if ($null -ne $u -and -not [string]::IsNullOrWhiteSpace($u.InstallLocation)) {
            foreach ($sub in @('Win32', 'Win64')) {
                [void]$exes.Add((Join-Path $u.InstallLocation ('Launcher\Portal\Binaries\' + $sub + '\EpicGamesLauncher.exe')))
            }
        }
    } catch {}

    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $manifestDir = Join-Path ([string]$env:ProgramData) 'Epic\EpicGamesLauncher\Data\Manifests'
    if (Test-Path -LiteralPath $manifestDir -PathType Container) {
        foreach ($f in @(Get-ChildItem -LiteralPath $manifestDir -Filter '*.item' -File -ErrorAction SilentlyContinue)) {
            try {
                $m = (Get-Content -LiteralPath $f.FullName -Raw -ErrorAction Stop) | ConvertFrom-Json
                $name = [string]$m.DisplayName
                $dir = [string]$m.InstallLocation
                if ([string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($dir)) { continue }
                if ($m.bIsIncompleteInstall) { continue }
                if (-not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
                # DLC, дополнения и движок (Unreal Engine и т.п.) — не игры.
                $cats = @($m.AppCategories | ForEach-Object { ([string]$_).ToLowerInvariant() })
                if (($cats -contains 'addons') -or ($cats -contains 'digitalextras') -or
                    (($cats -contains 'applications') -and -not ($cats -contains 'games'))) { continue }
                $exe = ''
                if (-not [string]::IsNullOrWhiteSpace([string]$m.LaunchExecutable)) {
                    $exeTry = Join-Path $dir ([string]$m.LaunchExecutable)
                    if (Test-Path -LiteralPath $exeTry -PathType Leaf) { $exe = $exeTry }
                }
                $gid = [string]$m.AppName
                $dupKey = (Get-NormalizedGamePathKey $dir)
                if ($seen.ContainsKey($dupKey)) { continue }
                $seen[$dupKey] = $true
                [void]$games.Add((New-LauncherGameEntry 'epic' 'Epic Games' $gid $name $dir $exe $SteamShortcuts ([string]$m.CatalogItemId) ([string]$m.CatalogNamespace)))
            } catch { Write-LauncherLog ('Epic manifest ' + $f.Name + ': ' + $_.Exception.Message) }
        }
    }
    return (New-LauncherSourceObject 'epic' 'Epic Games' 'E' @(52, 52, 58) @($exes.ToArray()) @($games.ToArray()))
}

# ---------- Обёртка SCLauncher.exe: запуск игры через лаунчер с фокусом и статусом в Steam ----------
# Ярлык Steam с ссылкой лаунчера (com.epicgames.launcher://...) запускает игру мимо Steam:
# процесс игры не виден, окно открывается позади. Поэтому в ярлык вместо игры пишется
# маленький exe в %APPDATA%\Steam Commander\launcher: он открывает ссылку, ждёт процесс
# из папки игры, выводит его окно вперёд и живёт, пока игра запущена.
$script:scLauncherVersion = '33'
$script:scLauncherSource = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Management;
using Microsoft.Win32;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Windows.Forms;

namespace SCLauncherNS
{
    // Скрытое окно: получает WM_CLOSE, когда Steam просит остановить "игру".
    class StopWindow : NativeWindow
    {
        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0010)
            {
                Program.StopRequested = true;
                return;
            }
            base.WndProc(ref m);
        }
    }

    public static class Program
    {
        public static volatile bool StopRequested = false;

        [StructLayout(LayoutKind.Sequential)]
        struct RECT { public int Left, Top, Right, Bottom; }
        delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

        [DllImport("kernel32.dll", SetLastError = true)]
        static extern IntPtr OpenProcess(uint access, bool inherit, int pid);
        [DllImport("kernel32.dll", SetLastError = true)]
        static extern bool CloseHandle(IntPtr h);
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        static extern bool QueryFullProcessImageName(IntPtr h, int flags, StringBuilder sb, ref int size);
        [DllImport("kernel32.dll")]
        static extern uint GetCurrentThreadId();
        [DllImport("user32.dll")]
        static extern bool EnumWindows(EnumWindowsProc cb, IntPtr lp);
        [DllImport("user32.dll")]
        static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
        [DllImport("user32.dll")]
        static extern bool IsWindowVisible(IntPtr h);
        [DllImport("user32.dll")]
        static extern bool IsIconic(IntPtr h);
        [DllImport("user32.dll")]
        static extern bool GetWindowRect(IntPtr h, out RECT r);
        [DllImport("user32.dll")]
        static extern int GetWindowLong(IntPtr h, int idx);
        [DllImport("user32.dll")]
        static extern bool ShowWindow(IntPtr h, int cmd);
        [DllImport("user32.dll")]
        static extern bool SetForegroundWindow(IntPtr h);
        [DllImport("user32.dll")]
        static extern bool BringWindowToTop(IntPtr h);
        [DllImport("user32.dll")]
        static extern IntPtr GetForegroundWindow();
        [DllImport("user32.dll")]
        static extern bool AttachThreadInput(uint a, uint b, bool attach);
        [DllImport("user32.dll")]
        static extern bool PostMessage(IntPtr h, uint msg, IntPtr w, IntPtr l);
        [DllImport("user32.dll")]
        static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);

        static string logPath = "";
        static int selfPid = 0;

        static readonly object logLock = new object();

        static void Log(string s)
        {
            try { lock (logLock) File.AppendAllText(logPath, DateTime.Now.ToString("yyyy-MM-ddTHH:mm:ss.fff") + " [" + selfPid + "] " + s + "\r\n"); } catch { }
        }

        static string GetImagePath(int pid)
        {
            IntPtr h = OpenProcess(0x1000, false, pid);
            if (h == IntPtr.Zero) return "";
            try
            {
                StringBuilder sb = new StringBuilder(1024);
                int size = sb.Capacity;
                if (QueryFullProcessImageName(h, 0, sb, ref size)) return sb.ToString(0, size);
            }
            finally { CloseHandle(h); }
            return "";
        }

        static List<int> FindGamePids(string dir, int self)
        {
            List<int> list = new List<int>();
            Process[] all = Process.GetProcesses();
            foreach (Process p in all)
            {
                try
                {
                    int id = p.Id;
                    if (id == self || id == 0 || id == 4) continue;
                    string path = GetImagePath(id);
                    if (path.Length > 0 && path.StartsWith(dir, StringComparison.OrdinalIgnoreCase))
                    {
                        // EA: служебные процессы из папки игры (EACoreServer и т.п.) не считаются игрой.
                        if (eaMode && IsEaHelperPath(path)) continue;
                        list.Add(id);
                    }
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return list;
        }

        // Режим EA: включается для игр, запускаемых через EA app (и передаётся сторожу флагом --eamode).
        static bool eaMode = false;

        // Служебные процессы EA в папке игры: они переживают игру (завершают сессию с EA app) и не должны
        // удерживать игру «запущенной» для Steam.
        static bool IsEaHelperPath(string path)
        {
            string n = Path.GetFileName(path).ToLowerInvariant();
            return n.StartsWith("eacoreserver") || n.StartsWith("eaanticheat") || n.StartsWith("eabackgroundservice") || n.StartsWith("ealocalhostsvc");
        }

        static List<int> FindEaHelperPids(string dir)
        {
            List<int> list = new List<int>();
            Process[] all = Process.GetProcesses();
            foreach (Process p in all)
            {
                try
                {
                    int id = p.Id;
                    if (id == 0 || id == 4) continue;
                    string path = GetImagePath(id);
                    if (path.Length > 0 && path.StartsWith(dir, StringComparison.OrdinalIgnoreCase) && IsEaHelperPath(path)) list.Add(id);
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return list;
        }

        // Дескрипторы процессов: HasExited дёшево, без перечисления всех процессов системы.
        static List<Process> TrackPids(List<int> ids, List<Process> old)
        {
            if (old != null) foreach (Process q in old) { try { q.Dispose(); } catch { } }
            List<Process> r = new List<Process>();
            foreach (int id in ids) { try { r.Add(Process.GetProcessById(id)); } catch { } }
            return r;
        }

        static bool AllExited(List<Process> l)
        {
            if (l == null || l.Count == 0) return false;
            foreach (Process q in l) { try { if (!q.HasExited) return false; } catch { return false; } }
            return true;
        }

        static IntPtr FindBestWindow(List<int> pids)
        {
            IntPtr best = IntPtr.Zero;
            long bestArea = 0;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!pids.Contains((int)pid)) return true;
                if (!IsWindowVisible(h)) return true;
                if ((GetWindowLong(h, -20) & 0x80) != 0) return true;
                RECT r;
                if (!GetWindowRect(h, out r)) return true;
                long area = (long)(r.Right - r.Left) * (long)(r.Bottom - r.Top);
                if (area >= 40000 && area > bestArea) { bestArea = area; best = h; }
                return true;
            }, IntPtr.Zero);
            return best;
        }

        static void Focus(IntPtr h, bool useAlt)
        {
            if (IsIconic(h)) ShowWindow(h, 9);
            IntPtr fg = GetForegroundWindow();
            uint dummy;
            uint fgThread = (fg == IntPtr.Zero) ? 0 : GetWindowThreadProcessId(fg, out dummy);
            uint cur = GetCurrentThreadId();
            bool attached = false;
            if (fgThread != 0 && fgThread != cur) attached = AttachThreadInput(cur, fgThread, true);
            if (useAlt)
            {
                keybd_event(0x12, 0, 0, UIntPtr.Zero);
                keybd_event(0x12, 0, 2, UIntPtr.Zero);
            }
            BringWindowToTop(h);
            SetForegroundWindow(h);
            if (attached) AttachThreadInput(cur, fgThread, false);
        }

        // Процесс, созданный через WMI, не является потомком SCLauncher.exe (и Steam),
        // поэтому Steam не считает его частью запущенной игры.
        static bool WmiCreate(string cmd)
        {
            return WmiCreate(cmd, null);
        }

        static bool WmiCreate(string cmd, string cwd)
        {
            try
            {
                ManagementClass mc = new ManagementClass("Win32_Process");
                object[] a = new object[] { cmd, cwd, null, 0 };
                object r = mc.InvokeMethod("Create", a);
                uint rc = Convert.ToUInt32(r);
                Log("wmi create rc=" + rc + " pid=" + a[3]);
                mc.Dispose();
                return rc == 0;
            }
            catch (Exception ex)
            {
                Log("wmi failed: " + ex.Message);
                return false;
            }
        }

        // Открывает ссылку лаунчера так, чтобы сам лаунчер (и запущенная им игра) не попал
        // в дерево процессов Steam: иначе Steam считает игру запущенной, пока открыт лаунчер.
        static void LaunchUriDetached(string uri)
        {
            // Ubisoft Connect: клиент (и игра), запущенные через WMI, работают без пользовательского
            // окружения и теряют доступ к библиотеке игр ("контент недоступен", игра закрывается через 2-5 с).
            // Поэтому ссылку отдаём оболочке: explorer.exe передаёт её уже работающему Explorer,
            // клиент становится его потомком (вне дерева Steam) и получает нормальное окружение.
            if (uri.StartsWith("uplay:", StringComparison.OrdinalIgnoreCase))
            {
                try
                {
                    string winDir = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
                    ProcessStartInfo upsi = new ProcessStartInfo(Path.Combine(winDir, "explorer.exe"), "\"" + uri + "\"");
                    upsi.UseShellExecute = false;
                    Process.Start(upsi);
                    Log("uri opened via explorer (ubisoft)");
                    return;
                }
                catch (Exception ex) { Log("ubisoft explorer start failed: " + ex.Message); }
            }
            string sys = Environment.GetFolderPath(Environment.SpecialFolder.System);
            string rundll = Path.Combine(sys, "rundll32.exe");
            if (WmiCreate("\"" + rundll + "\" url.dll,FileProtocolHandler \"" + uri + "\""))
            {
                Log("uri opened via wmi");
                return;
            }
            try
            {
                string win = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
                ProcessStartInfo psi = new ProcessStartInfo(Path.Combine(win, "explorer.exe"), "\"" + uri + "\"");
                psi.UseShellExecute = false;
                Process.Start(psi);
                Log("uri opened via explorer");
                return;
            }
            catch (Exception ex) { Log("explorer start failed: " + ex.Message); }
            ProcessStartInfo p2 = new ProcessStartInfo(uri);
            p2.UseShellExecute = true;
            Process.Start(p2);
            Log("uri opened via shell");
        }

        // Запуск игры GOG через клиент Galaxy. Ссылки запуска у Galaxy нет, только командная строка;
        // если клиент уже открыт, команда уходит в работающий экземпляр. Как и ссылка Epic,
        // создаётся через WMI, чтобы клиент не попал в дерево процессов Steam.
        static bool LaunchGalaxyDetached(string gameId, string dir, string client, bool quiet)
        {
            string gdir = dir.TrimEnd('\\');
            string cargs = "/command=runGame /gameId=" + gameId + " /path=\"" + gdir + "\"";
            // /launchViaAutoStart: клиент стартует тихо (в трей). Ключ не документирован и действует,
            // только если Galaxy ещё не запущена, поэтому добавляем его лишь когда запускаем клиент сами.
            if (quiet) cargs = "/launchViaAutoStart " + cargs;
            Log("galaxy args: " + cargs);
            string cwd = null;
            try { cwd = Path.GetDirectoryName(client); } catch { }
            if (WmiCreate("\"" + client + "\" " + cargs, cwd)) { Log("galaxy command started via wmi"); return true; }
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(client, cargs);
                psi.UseShellExecute = false;
                if (cwd != null && cwd.Length > 0) psi.WorkingDirectory = cwd;
                Process.Start(psi);
                Log("galaxy command started directly");
                return true;
            }
            catch (Exception ex) { Log("galaxy start failed: " + ex.Message); }
            return false;
        }

        // Battle.net: --exec="launch <код>" принимает НЕ тот uid, что лежит в деинсталляторе
        // (--uid=pro, fen, viper ...), а внутренний код продукта, причём с учётом регистра
        // (Pro, Fen, VIPR ...). С неверным кодом клиент просто открывает страницу игры и ничего не делает.
        static string BnetExecCode(string uid)
        {
            string u = uid.ToLowerInvariant();
            switch (u)
            {
                case "wow": return "WoW";
                case "pro": case "overwatch": return "Pro";
                case "fen": case "diablo4": return "Fen";
                case "d3": case "diablo3": return "D3";
                case "s2": case "starcraft2": return "S2";
                case "s1": case "starcraft": return "S1";
                case "hero": return "Hero";
                case "hs_beta": case "hs": case "wtcg": return "WTCG";
                case "w3": return "W3";
                case "odin": return "ODIN";
                case "viper": case "vipr": return "VIPR";
                case "zeus": return "ZEUS";
                case "lazr": return "LAZR";
                case "fore": return "FORE";
                case "auks": return "AUKS";
                case "anbs": return "ANBS";
                case "osi": return "OSI";
                case "wlby": return "WLBY";
                case "rtro": return "RTRO";
            }
            return uid;
        }

        // Версии WoW (classic, era, PTR...) через exec не запускаются: клиенту нужны --game/--productcode/--gamepath.
        static bool BnetIsWowVariant(string uid)
        {
            string u = uid.ToLowerInvariant();
            return u.StartsWith("wow_") || u == "wowt" || u == "wowb" || u == "wowclassic" || u == "wow_classic";
        }

        static string BnetBuildArgs(string productId, string gameDir)
        {
            if (BnetIsWowVariant(productId) && gameDir != null && gameDir.Length > 0)
                return "--game=" + productId + " --gamepath=\"" + gameDir + "\" --productcode=" + productId;
            return "--exec=\"launch " + BnetExecCode(productId) + "\"";
        }

        static bool LaunchBattleNetDetached(string productId, string client, string gameDir)
        {
            if (productId == null || productId.Length == 0 || client == null || client.Length == 0 || !File.Exists(client))
            { Log("bnet: bad args"); return false; }
            string cargs = BnetBuildArgs(productId, gameDir);
            Log("bnet args: " + cargs + " client=" + client);
            string cwd = null;
            try { cwd = Path.GetDirectoryName(client); } catch { }
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo();
                psi.FileName = client;
                psi.Arguments = cargs;
                psi.UseShellExecute = true;
                if (cwd != null && cwd.Length > 0) psi.WorkingDirectory = cwd;
                Process.Start(psi);
                Log("bnet command started via shell");
                return true;
            }
            catch (Exception ex) { Log("bnet shell start failed: " + ex.Message); }
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(client, cargs);
                psi.UseShellExecute = false;
                if (cwd != null && cwd.Length > 0) psi.WorkingDirectory = cwd;
                Process.Start(psi);
                Log("bnet command started directly");
                return true;
            }
            catch (Exception ex) { Log("bnet start failed: " + ex.Message); }
            return false;
        }

        // Имя exe игры (ищется рекурсивно внутри папки игры: у StarCraft он лежит в x86_64\\).
        static string BnetGameExeName(string uid)
        {
            switch (uid.ToLowerInvariant())
            {
                case "hs_beta": case "hs": case "wtcg": return "Hearthstone.exe";
                case "s1": return "StarCraft.exe";
                case "s2": return "SC2_x64.exe";
                case "d3": return "Diablo III64.exe";
                case "pro": return "Overwatch.exe";
                case "fen": return "Diablo IV.exe";
                case "w3": return "Warcraft III.exe";
                case "wow": return "Wow.exe";
                case "hero": return "HeroesOfTheStorm_x64.exe";
            }
            return null;
        }

        static string FindBnetGameExe(string uid, string dir, string exePath)
        {
            string name = BnetGameExeName(uid);
            if (name != null)
            {
                try
                {
                    string[] found = Directory.GetFiles(dir, name, SearchOption.AllDirectories);
                    string best = null;
                    foreach (string f in found)
                    {
                        if (f.IndexOf("\\Support", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                        // Предпочитаем 64-бит (x86_64): клиент запускает именно его; иначе - самый короткий путь.
                        bool f64 = f.IndexOf("x86_64", StringComparison.OrdinalIgnoreCase) >= 0;
                        bool b64 = best != null && best.IndexOf("x86_64", StringComparison.OrdinalIgnoreCase) >= 0;
                        if (best == null || (f64 && !b64) || (f64 == b64 && f.Length < best.Length)) best = f;
                    }
                    if (best != null) return best;
                }
                catch (Exception ex) { Log("bnet exe search failed: " + ex.Message); }
            }
            try { if (exePath != null && exePath.Length > 0 && File.Exists(exePath)) return exePath; } catch { }
            return null;
        }

        // Battle.net 2021+ нередко игнорирует --exec="launch ..." и открывает только страницу игры с кнопкой
        // "Играть". Кнопка сама запускает exe игры с аргументами "-launch -uid <uid>" - делаем то же самое.
        static bool LaunchBnetGameExeDirect(string uid, string dir, string exePath)
        {
            string exe = FindBnetGameExe(uid, dir, exePath);
            if (exe == null) { Log("bnet: no game exe for direct start (uid=" + uid + ")"); return false; }
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo();
                psi.FileName = exe;
                psi.Arguments = "-launch -uid " + uid;
                psi.UseShellExecute = true;
                string wd = Path.GetDirectoryName(exe);
                if (wd != null && wd.Length > 0) psi.WorkingDirectory = wd;
                Process.Start(psi);
                Log("bnet: game exe started directly: " + exe + " " + psi.Arguments);
                return true;
            }
            catch (Exception ex) { Log("bnet direct start failed: " + ex.Message); }
            return false;
        }

        // Холодный старт клиента: через Explorer, чтобы клиент не попал в дерево процессов Steam
        // (иначе Steam считает игру запущенной, пока клиент не закроется).
        static bool LaunchBnetClientDetached(string client)
        {
            try
            {
                string winDir = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
                ProcessStartInfo psi = new ProcessStartInfo(Path.Combine(winDir, "explorer.exe"), "\"" + client + "\"");
                psi.UseShellExecute = false;
                Process.Start(psi);
                Log("bnet: client started via explorer");
                return true;
            }
            catch (Exception ex) { Log("bnet explorer start failed: " + ex.Message); }
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(client);
                psi.UseShellExecute = true;
                Process.Start(psi);
                Log("bnet: client started directly");
                return true;
            }
            catch (Exception ex) { Log("bnet client start failed: " + ex.Message); }
            return false;
        }

        static void PostCloseToWindows(List<int> pids)
        {
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (pids.Contains((int)pid)) PostMessage(h, 0x0010, IntPtr.Zero, IntPtr.Zero);
                return true;
            }, IntPtr.Zero);
        }

        // Закрывает игру: сначала вежливо (WM_CLOSE), через 6 секунд принудительно.
        static void CloseGame(string dir, int self)
        {
            List<int> pids = FindGamePids(dir, self);
            if (pids.Count == 0) return;
            Log("closing game, pids=" + pids.Count);
            PostCloseToWindows(pids);
            DateTime t0 = DateTime.UtcNow;
            while ((DateTime.UtcNow - t0).TotalSeconds < 6)
            {
                Thread.Sleep(300);
                pids = FindGamePids(dir, self);
                if (pids.Count == 0) { Log("game closed gracefully"); return; }
            }
            foreach (int id in pids)
            {
                try
                {
                    Process p = Process.GetProcessById(id);
                    p.Kill();
                    p.Dispose();
                }
                catch (Exception ex) { Log("kill " + id + ": " + ex.Message); }
            }
            Log("game killed");
        }

        // Процессы клиента Ubisoft Connect (старое имя клиента - upc.exe).
        static List<int> FindUbiPids()
        {
            List<int> all = new List<int>();
            string[] tails = new string[] { "\\UbisoftConnect.exe", "\\upc.exe", "\\UplayWebCore.exe", "\\UbisoftGameLauncher.exe", "\\UbisoftGameLauncher64.exe" };
            Process[] procs = Process.GetProcesses();
            foreach (Process p in procs)
            {
                try
                {
                    int id = p.Id;
                    if (id == 0 || id == 4) continue;
                    string path = GetImagePath(id);
                    if (path.Length == 0) continue;
                    foreach (string t in tails)
                    {
                        if (path.EndsWith(t, StringComparison.OrdinalIgnoreCase)) { all.Add(id); break; }
                    }
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return all;
        }

        // Тихий запуск Ubisoft Connect: у клиента нет ключа запуска в трей, поэтому его окна прячутся
        // (hide=true: окно и кнопка на панели задач исчезают, клиент остаётся в трее) или сворачиваются
        // без активации (hide=false). Спрятанное или свёрнутое окно не считается открытым, поэтому
        // клиент после игры можно закрыть. Вызывается только для клиента, запущенного самой обёрткой.
        static void QuietUbiWindows(bool hide)
        {
            List<int> ubi = FindUbiPids();
            if (ubi.Count == 0) return;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!ubi.Contains((int)pid)) return true;
                if (!IsWindowVisible(h)) return true;
                if (!hide && IsIconic(h)) return true;
                if ((GetWindowLong(h, -20) & 0x80) != 0) return true;
                RECT r;
                if (!GetWindowRect(h, out r)) return true;
                long area = (long)(r.Right - r.Left) * (long)(r.Bottom - r.Top);
                if (area < 40000 && !IsIconic(h)) return true;
                ShowWindow(h, hide ? 0 : 7);
                Log(hide ? "ubisoft: client window hidden" : "ubisoft: client window minimized");
                return true;
            }, IntPtr.Zero);
        }

        // Папки установки всех игр Ubisoft из реестра.
        static List<string> ReadUbiInstallDirs()
        {
            List<string> dirs = new List<string>();
            try
            {
                using (RegistryKey hklm = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64))
                using (RegistryKey root = hklm.OpenSubKey("SOFTWARE\\WOW6432Node\\Ubisoft\\Launcher\\Installs"))
                {
                    if (root != null)
                    {
                        foreach (string name in root.GetSubKeyNames())
                        {
                            try
                            {
                                using (RegistryKey k = root.OpenSubKey(name))
                                {
                                    if (k == null) continue;
                                    object p = k.GetValue("InstallDir");
                                    if (p == null) continue;
                                    string v = p.ToString().Replace("/", "\\").TrimEnd('\\');
                                    if (v.Length > 3) dirs.Add(v + "\\");
                                }
                            }
                            catch { }
                        }
                    }
                }
            }
            catch (Exception ex) { Log("ubisoft registry read failed: " + ex.Message); }
            return dirs;
        }

        // Запущена ли сейчас другая игра Ubisoft (любой процесс из папки другой установленной игры).
        static string FindOtherUbiGame(string ownDir)
        {
            List<string> dirs = new List<string>();
            foreach (string d in ReadUbiInstallDirs())
            {
                if (!string.Equals(d, ownDir, StringComparison.OrdinalIgnoreCase)) dirs.Add(d);
            }
            if (dirs.Count == 0) return "";
            Process[] all = Process.GetProcesses();
            string found = "";
            foreach (Process p in all)
            {
                try
                {
                    if (found.Length == 0)
                    {
                        int id = p.Id;
                        if (id != 0 && id != 4)
                        {
                            string path = GetImagePath(id);
                            if (path.Length > 0)
                            {
                                foreach (string d in dirs)
                                {
                                    if (path.StartsWith(d, StringComparison.OrdinalIgnoreCase)) { found = path; break; }
                                }
                            }
                        }
                    }
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return found;
        }

        // Закрывает Ubisoft Connect, который был запущен вместе с игрой: сначала ждёт (облачные
        // сохранения), потом закрывает вежливо (WM_CLOSE), а если клиент остался в трее - принудительно.
        // Ничего не делает, если открыто окно клиента или запущена другая игра Ubisoft.
        static void CloseUbiIfIdle(string dir, int self)
        {
            for (int i = 0; i < 15; i++)
            {
                Thread.Sleep(1000);
                if (FindGamePids(dir, self).Count > 0) { Log("ubisoft: game started again, leaving client open"); return; }
                // После выхода из игры клиент сам показывает своё окно поверх всего - сразу прячем его.
                QuietUbiWindows(true);
            }
            List<int> ubi = FindUbiPids();
            if (ubi.Count == 0) { Log("ubisoft: client already closed"); return; }
            // Сюда попадаем только если клиент запущен нами вместе с игрой (иначе сторож не закрывает клиент),
            // поэтому состояние его окна не учитываем: оно открывается само при выходе из игры.
            string other = FindOtherUbiGame(dir);
            if (other.Length > 0) { Log("ubisoft: another Ubisoft game is running (" + other + "), leaving client open"); return; }
            Log("ubisoft: closing client, pids=" + ubi.Count);
            PostCloseToWindows(ubi);
            DateTime t0 = DateTime.UtcNow;
            while ((DateTime.UtcNow - t0).TotalSeconds < 10)
            {
                Thread.Sleep(500);
                if (FindUbiPids().Count == 0) { Log("ubisoft: client closed gracefully"); return; }
            }
            foreach (int id in FindUbiPids())
            {
                try
                {
                    Process p = Process.GetProcessById(id);
                    p.Kill();
                    p.Dispose();
                }
                catch (Exception ex) { Log("ubisoft kill " + id + ": " + ex.Message); }
            }
            Log("ubisoft: client killed");
        }

        // Процессы клиента EA app (бывш. EA Desktop) и старого Origin. Службы (EABackgroundService,
        // EALocalHostSvc, OriginWebHelperService) не трогаем: они работают отдельно от окна клиента.
        static List<int> FindEaPids()
        {
            List<int> all = new List<int>();
            string[] tails = new string[] { "\\EADesktop.exe", "\\EACefSubprocess.exe", "\\Origin.exe" };
            Process[] procs = Process.GetProcesses();
            foreach (Process p in procs)
            {
                try
                {
                    int id = p.Id;
                    if (id == 0 || id == 4) continue;
                    string path = GetImagePath(id);
                    if (path.Length == 0) continue;
                    string low = path.ToLowerInvariant();
                    // Службы окон не имеют, закрывать их не нужно (и нельзя без прав администратора).
                    if (low.EndsWith("\\eabackgroundservice.exe") || low.EndsWith("\\ealocalhostsvc.exe")) continue;
                    bool match = low.IndexOf("\\electronic arts\\ea desktop\\") >= 0;
                    if (!match)
                    {
                        foreach (string t in tails)
                        {
                            if (path.EndsWith(t, StringComparison.OrdinalIgnoreCase)) { match = true; break; }
                        }
                    }
                    if (match) all.Add(id);
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return all;
        }

        // Прячет видимые окна клиента EA app: после выхода из игры клиент сам показывает своё окно
        // поверх всего. Спрятанное окно остаётся в трее и не считается открытым.
        static void QuietEaWindows()
        {
            QuietEaWindows(FindEaPids());
        }

        static HashSet<long> eaLogged = new HashSet<long>();

        static void QuietEaWindows(List<int> ea)
        {
            if (ea == null || ea.Count == 0) return;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!ea.Contains((int)pid)) return true;
                if (!IsWindowVisible(h)) return true;
                if ((GetWindowLong(h, -20) & 0x80) != 0) return true;
                RECT r;
                if (!GetWindowRect(h, out r)) return true;
                long area = (long)(r.Right - r.Left) * (long)(r.Bottom - r.Top);
                if (area < 40000 && !IsIconic(h)) return true;
                ShowWindow(h, 0);
                bool firstTime;
                lock (eaLogged) { firstTime = eaLogged.Count < 30 && eaLogged.Add((long)h); }
                if (firstTime)
                    Log("ea: client window hidden, pid=" + pid + " area=" + area + " " + GetImagePath((int)pid));
                return true;
            }, IntPtr.Zero);
        }

        // Есть ли у игры видимое окно (обычное, достаточного размера или свёрнутое).
        static bool GameHasWindow(List<int> pids)
        {
            if (pids == null || pids.Count == 0) return false;
            bool found = false;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!pids.Contains((int)pid)) return true;
                if (!IsWindowVisible(h)) return true;
                if ((GetWindowLong(h, -20) & 0x80) != 0) return true;
                if (IsIconic(h)) { found = true; return false; }
                RECT r;
                if (!GetWindowRect(h, out r)) return true;
                long area = (long)(r.Right - r.Left) * (long)(r.Bottom - r.Top);
                if (area >= 40000) { found = true; return false; }
                return true;
            }, IntPtr.Zero);
            return found;
        }

        // Папки установки всех игр EA из реестра (HKLM\SOFTWARE\[WOW6432Node\]EA Games\*\Install Dir).
        static List<string> ReadEaInstallDirs()
        {
            List<string> dirs = new List<string>();
            string[] roots = new string[] { "SOFTWARE\\WOW6432Node\\EA Games", "SOFTWARE\\EA Games" };
            try
            {
                using (RegistryKey hklm = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64))
                {
                    foreach (string rp in roots)
                    {
                        using (RegistryKey root = hklm.OpenSubKey(rp))
                        {
                            if (root == null) continue;
                            foreach (string name in root.GetSubKeyNames())
                            {
                                try
                                {
                                    using (RegistryKey k = root.OpenSubKey(name))
                                    {
                                        if (k == null) continue;
                                        object p = k.GetValue("Install Dir");
                                        if (p == null) continue;
                                        string v = p.ToString().Replace("/", "\\").TrimEnd('\\');
                                        if (v.Length > 3) dirs.Add(v + "\\");
                                    }
                                }
                                catch { }
                            }
                        }
                    }
                }
            }
            catch (Exception ex) { Log("ea registry read failed: " + ex.Message); }
            return dirs;
        }

        // Запущена ли сейчас другая игра EA (любой процесс из папки другой установленной игры).
        static string FindOtherEaGame(string ownDir)
        {
            List<string> dirs = new List<string>();
            foreach (string d in ReadEaInstallDirs())
            {
                if (!string.Equals(d, ownDir, StringComparison.OrdinalIgnoreCase)) dirs.Add(d);
            }
            if (dirs.Count == 0) return "";
            Process[] all = Process.GetProcesses();
            string found = "";
            foreach (Process p in all)
            {
                try
                {
                    if (found.Length == 0)
                    {
                        int id = p.Id;
                        if (id != 0 && id != 4)
                        {
                            string path = GetImagePath(id);
                            if (path.Length > 0)
                            {
                                foreach (string d in dirs)
                                {
                                    if (path.StartsWith(d, StringComparison.OrdinalIgnoreCase)) { found = path; break; }
                                }
                            }
                        }
                    }
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return found;
        }

        // Ждёт ms миллисекунд и всё это время каждые 250 мс прячет окно EA app
        // (список процессов обновляется раз в секунду, чтобы не грузить систему).
        static void SleepHidingEa(int ms)
        {
            List<int> ea = FindEaPids();
            int steps = ms / 250;
            for (int i = 0; i < steps; i++)
            {
                Thread.Sleep(250);
                if ((i % 4) == 3) ea = FindEaPids();
                QuietEaWindows(ea);
            }
        }

        // Пока жива обёртка: как только игра завершилась, сразу прячет окно EA app,
        // которое клиент открывает сам. Пока игра работает или ещё не запускалась - окно не трогает
        // (при холодном старте клиенту может понадобиться вход в аккаунт).
        // Ставится, когда обёртка завершилась (игра закончилась или её останавливают): с этого момента
        // окно EA app прячется безусловно.
        static volatile bool eaForceHide = false;

        static void WatchEaWhileWrapperAlive(Process wp, string dir, int self)
        {
            // Окно прячется: (1) как только у игры пропало её окно (не дожидаясь, пока завершатся
            // вспомогательные процессы), (2) когда исчезли все процессы игры, (3) когда завершилась
            // сама обёртка (eaForceHide). Во время игры раз в 250 мс проверяется только наличие её
            // окна, список процессов читается раз в 2 с (раз в секунду - при скрытии).
            List<int> gids = new List<int>();
            List<int> ea = new List<int>();
            bool gameSeen = false;
            bool windowSeen = false;
            bool hiding = false;
            DateTime goneAt = DateTime.MinValue;
            IntPtr lastFg = IntPtr.Zero;
            int tick = 0;
            while (true)
            {
                Thread.Sleep(250);
                tick++;
                if ((tick % (hiding ? 4 : 8)) == 0)
                {
                    gids = FindGamePids(dir, self);
                    if (gids.Count > 0 && !gameSeen) { gameSeen = true; Log("ea: watch: game found, pids=" + gids.Count); }
                    if (hiding) ea = FindEaPids();
                }
                bool force = eaForceHide;
                if (!gameSeen && !force) continue;
                bool hasWin = gameSeen && GameHasWindow(gids);
                if (hasWin && !windowSeen) { windowSeen = true; Log("ea: watch: game window seen"); }
                bool shouldHide = force || (windowSeen && !hasWin) || (gameSeen && gids.Count == 0);
                if (shouldHide)
                {
                    if (!hiding)
                    {
                        hiding = true;
                        goneAt = DateTime.UtcNow;
                        gids = FindGamePids(dir, self);
                        ea = FindEaPids();
                        Log("ea: watch: hiding EA window (" + (force ? "wrapper ended" : (hasWin ? "game processes gone" : "game window gone")) + "), remaining game processes=" + gids.Count + ", ea pids=" + ea.Count);
                        int shown = 0;
                        foreach (int gid in gids) { if (shown++ < 5) Log("ea: watch: still running: " + GetImagePath(gid)); }
                    }
                    QuietEaWindows(ea);
                    if ((DateTime.UtcNow - goneAt).TotalSeconds < 30)
                    {
                        IntPtr fg = GetForegroundWindow();
                        if (fg != lastFg)
                        {
                            lastFg = fg;
                            uint fp;
                            GetWindowThreadProcessId(fg, out fp);
                            Log("ea: watch: foreground pid=" + fp + " " + GetImagePath((int)fp));
                        }
                    }
                }
                else if (hiding && hasWin)
                {
                    hiding = false;
                    Log("ea: watch: game window is back, stop hiding");
                }
            }
        }

        // Закрывает EA app, который был запущен вместе с игрой: сначала ждёт (облачные сохранения)
        // и всё это время прячет окно, которое клиент открывает сам при выходе из игры; потом закрывает
        // вежливо (WM_CLOSE), а если клиент остался в трее (крестик EA app сворачивает его в трей) -
        // принудительно. Ничего не делает, если запущена другая игра EA.
        static void CloseEaIfIdle(string dir, int self)
        {
            for (int i = 0; i < 15; i++)
            {
                SleepHidingEa(1000);
                if (FindGamePids(dir, self).Count > 0) { eaForceHide = false; Log("ea: game started again, leaving client open"); return; }
            }
            // Служебные процессы игры (EACoreServer) после выхода ещё завершают сессию с EA app: клиент
            // не закрываем, пока они не завершатся (но не дольше 60 с), окно при этом остаётся спрятанным.
            for (int i = 0; i < 60; i++)
            {
                if (FindEaHelperPids(dir).Count == 0) break;
                if (i == 0) Log("ea: waiting for the game's EA helper processes to exit");
                SleepHidingEa(1000);
                if (FindGamePids(dir, self).Count > 0) { eaForceHide = false; Log("ea: game started again, leaving client open"); return; }
            }
            List<int> ea = FindEaPids();
            if (ea.Count == 0) { Log("ea: client already closed"); return; }
            string other = FindOtherEaGame(dir);
            if (other.Length > 0) { Log("ea: another EA game is running (" + other + "), leaving client open"); return; }
            Log("ea: closing client, pids=" + ea.Count);
            PostCloseToWindows(ea);
            DateTime t0 = DateTime.UtcNow;
            while ((DateTime.UtcNow - t0).TotalSeconds < 6)
            {
                Thread.Sleep(500);
                if (FindEaPids().Count == 0) { Log("ea: client closed gracefully"); return; }
            }
            foreach (int id in FindEaPids())
            {
                try
                {
                    Process p = Process.GetProcessById(id);
                    p.Kill();
                    p.Dispose();
                }
                catch (Exception ex) { Log("ea kill " + id + ": " + ex.Message); }
            }
            Log("ea: client killed");
        }

        static void QuietBnetWindows(bool forceHide)
        {
            List<int> bn = FindPidsByName("Battle.net.exe");
            bn.AddRange(FindPidsByName("Battle.net Launcher.exe"));
            if (bn.Count == 0) return;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!bn.Contains((int)pid)) return true;
                if (!IsWindowVisible(h)) return true;
                int area = 0;
                try
                {
                    RECT r;
                    if (GetWindowRect(h, out r)) area = Math.Abs((r.Right - r.Left) * (r.Bottom - r.Top));
                }
                catch { }
                if (area < 40000 && !forceHide) return true;
                ShowWindow(h, forceHide ? 0 : 7);
                Log(forceHide ? "bnet: window hidden" : "bnet: window minimized");
                return true;
            }, IntPtr.Zero);
        }

        static void CloseBnetIfIdle(string dir, int self)
        {
            for (int i = 0; i < 15; i++)
            {
                Thread.Sleep(1000);
                if (FindGamePids(dir, self).Count > 0) { Log("bnet: game started again, leaving client open"); return; }
                QuietBnetWindows(true);
            }
            List<int> bn = FindPidsByName("Battle.net.exe");
            bn.AddRange(FindPidsByName("Battle.net Launcher.exe"));
            if (bn.Count == 0) { Log("bnet: client already closed"); return; }
            Log("bnet: closing client, pids=" + bn.Count);
            PostCloseToWindows(bn);
            DateTime t0 = DateTime.UtcNow;
            while ((DateTime.UtcNow - t0).TotalSeconds < 10)
            {
                Thread.Sleep(500);
                if (FindPidsByName("Battle.net.exe").Count == 0 && FindPidsByName("Battle.net Launcher.exe").Count == 0)
                { Log("bnet: client closed gracefully"); return; }
            }
            foreach (int id in FindPidsByName("Battle.net.exe"))
            {
                try { Process p = Process.GetProcessById(id); p.Kill(); p.Dispose(); }
                catch (Exception ex) { Log("bnet kill " + id + ": " + ex.Message); }
            }
            foreach (int id in FindPidsByName("Battle.net Launcher.exe"))
            {
                try { Process p = Process.GetProcessById(id); p.Kill(); p.Dispose(); }
                catch (Exception ex) { Log("bnet kill " + id + ": " + ex.Message); }
            }
            Log("bnet: client killed");
        }

        static void StartStopListener()
        {
            try
            {
                Thread t = new Thread(delegate ()
                {
                    try
                    {
                        StopWindow w = new StopWindow();
                        CreateParams cp = new CreateParams();
                        cp.Caption = "Steam Commander Launcher";
                        w.CreateHandle(cp);
                        Application.Run();
                    }
                    catch (Exception ex) { Log("stop listener: " + ex.Message); }
                });
                t.SetApartmentState(ApartmentState.STA);
                t.IsBackground = true;
                t.Start();
            }
            catch (Exception ex) { Log("stop listener start: " + ex.Message); }
        }

        static List<int> FindPidsByName(string exeName)
        {
            List<int> list = new List<int>();
            string tail = "\\" + exeName;
            Process[] all = Process.GetProcesses();
            foreach (Process p in all)
            {
                try
                {
                    int id = p.Id;
                    if (id == 0 || id == 4) continue;
                    string path = GetImagePath(id);
                    if (path.EndsWith(tail, StringComparison.OrdinalIgnoreCase)) list.Add(id);
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return list;
        }

        // Диагностика: пишет в лог дочерние процессы лаунчера не из его собственной папки.
        static void LogForeignChildren(int parentPid)
        {
            try
            {
                ManagementObjectSearcher ms = new ManagementObjectSearcher("SELECT ProcessId FROM Win32_Process WHERE ParentProcessId=" + parentPid);
                int n = 0;
                foreach (ManagementBaseObject o in ms.Get())
                {
                    int cid = Convert.ToInt32(o["ProcessId"]);
                    string img = GetImagePath(cid);
                    if (img.Length == 0) continue;
                    if (img.IndexOf("\\epic games\\launcher\\", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                    Log("egs: child outside launcher folder: " + img);
                    if (++n >= 10) break;
                }
            }
            catch (Exception ex) { Log("children log failed: " + ex.Message); }
        }

        // Папки установки всех игр Epic из манифестов лаунчера.
        static List<string> ReadEpicInstallDirs()
        {
            List<string> dirs = new List<string>();
            try
            {
                string md = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Epic\\EpicGamesLauncher\\Data\\Manifests");
                foreach (string f in Directory.GetFiles(md, "*.item"))
                {
                    try
                    {
                        string txt = File.ReadAllText(f);
                        Match m = Regex.Match(txt, @"""InstallLocation""\s*:\s*""((?:[^""\\]|\\.)*)""");
                        if (!m.Success) continue;
                        string v = m.Groups[1].Value.Replace("\\\\", "\\").Replace("/", "\\").TrimEnd('\\');
                        if (v.Length > 3) dirs.Add(v + "\\");
                    }
                    catch { }
                }
            }
            catch (Exception ex) { Log("manifests read failed: " + ex.Message); }
            return dirs;
        }

        // Запущена ли сейчас другая игра Epic (любой процесс из папки другой установленной игры).
        // Возвращает путь найденного процесса или пустую строку.
        static string FindOtherEpicGame(string ownDir)
        {
            List<string> dirs = new List<string>();
            foreach (string d in ReadEpicInstallDirs())
            {
                if (!string.Equals(d, ownDir, StringComparison.OrdinalIgnoreCase)) dirs.Add(d);
            }
            if (dirs.Count == 0) return "";
            Process[] all = Process.GetProcesses();
            string found = "";
            foreach (Process p in all)
            {
                try
                {
                    if (found.Length == 0)
                    {
                        int id = p.Id;
                        if (id != 0 && id != 4)
                        {
                            string path = GetImagePath(id);
                            if (path.Length > 0)
                            {
                                foreach (string d in dirs)
                                {
                                    if (path.StartsWith(d, StringComparison.OrdinalIgnoreCase)) { found = path; break; }
                                }
                            }
                        }
                    }
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return found;
        }

        // Закрывает Epic Games Launcher, который был запущен вместе с игрой: сначала ждёт
        // (облачные сохранения), потом закрывает вежливо, и только если он не закрылся — принудительно.
        // Ничего не делает, если открыто окно лаунчера или через него запущена другая игра.
        static void CloseEgsIfIdle(string dir, int self)
        {
            for (int i = 0; i < 12; i++)
            {
                Thread.Sleep(1000);
                if (FindGamePids(dir, self).Count > 0) { Log("egs: game started again, leaving launcher open"); return; }
            }
            List<int> egs = FindPidsByName("EpicGamesLauncher.exe");
            if (egs.Count == 0) { Log("egs: launcher already closed"); return; }
            IntPtr w = FindBestWindow(egs);
            if (w != IntPtr.Zero && !IsIconic(w)) { Log("egs: launcher window is open, leaving it"); return; }
            foreach (int cid in egs) LogForeignChildren(cid);
            string other = FindOtherEpicGame(dir);
            if (other.Length > 0) { Log("egs: another Epic game is running (" + other + "), leaving launcher open"); return; }
            List<int> all = new List<int>(egs);
            all.AddRange(FindPidsByName("EpicWebHelper.exe"));
            Log("egs: closing launcher, pids=" + all.Count);
            PostCloseToWindows(all);
            DateTime t0 = DateTime.UtcNow;
            while ((DateTime.UtcNow - t0).TotalSeconds < 10)
            {
                Thread.Sleep(500);
                if (FindPidsByName("EpicGamesLauncher.exe").Count == 0) { Log("egs: launcher closed gracefully"); return; }
            }
            List<int> left = FindPidsByName("EpicGamesLauncher.exe");
            left.AddRange(FindPidsByName("EpicWebHelper.exe"));
            foreach (int id in left)
            {
                try
                {
                    Process p = Process.GetProcessById(id);
                    p.Kill();
                    p.Dispose();
                }
                catch (Exception ex) { Log("egs kill " + id + ": " + ex.Message); }
            }
            Log("egs: launcher killed");
        }

        // Папки установки всех игр GOG из реестра (записи DLC пропускаем).
        static List<string> ReadGogInstallDirs()
        {
            List<string> dirs = new List<string>();
            try
            {
                using (RegistryKey hklm = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64))
                using (RegistryKey root = hklm.OpenSubKey("SOFTWARE\\WOW6432Node\\GOG.com\\Games"))
                {
                    if (root != null)
                    {
                        foreach (string name in root.GetSubKeyNames())
                        {
                            try
                            {
                                using (RegistryKey k = root.OpenSubKey(name))
                                {
                                    if (k == null) continue;
                                    object dep = k.GetValue("dependsOn");
                                    if (dep != null && dep.ToString().Length > 0) continue;
                                    object p = k.GetValue("path");
                                    if (p == null) continue;
                                    string v = p.ToString().Replace("/", "\\").TrimEnd('\\');
                                    if (v.Length > 3) dirs.Add(v + "\\");
                                }
                            }
                            catch { }
                        }
                    }
                }
            }
            catch (Exception ex) { Log("gog registry read failed: " + ex.Message); }
            return dirs;
        }

        // Запущена ли сейчас другая игра GOG (любой процесс из папки другой установленной игры).
        // Возвращает путь найденного процесса или пустую строку.
        static string FindOtherGogGame(string ownDir)
        {
            List<string> dirs = new List<string>();
            foreach (string d in ReadGogInstallDirs())
            {
                if (!string.Equals(d, ownDir, StringComparison.OrdinalIgnoreCase)) dirs.Add(d);
            }
            if (dirs.Count == 0) return "";
            Process[] all = Process.GetProcesses();
            string found = "";
            foreach (Process p in all)
            {
                try
                {
                    if (found.Length == 0)
                    {
                        int id = p.Id;
                        if (id != 0 && id != 4)
                        {
                            string path = GetImagePath(id);
                            if (path.Length > 0)
                            {
                                foreach (string d in dirs)
                                {
                                    if (path.StartsWith(d, StringComparison.OrdinalIgnoreCase)) { found = path; break; }
                                }
                            }
                        }
                    }
                }
                catch { }
                finally { try { p.Dispose(); } catch { } }
            }
            return found;
        }

        // Сворачивает видимые окна Galaxy без активации (если клиент, запущенный нами, всё же открыл окно
        // поверх игры). Свёрнутое окно не считается открытым, поэтому потом клиент можно закрыть.
        static void MinimizeGalaxyWindows()
        {
            List<int> gx = FindPidsByName("GalaxyClient.exe");
            if (gx.Count == 0) return;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!gx.Contains((int)pid)) return true;
                if (!IsWindowVisible(h) || IsIconic(h)) return true;
                if ((GetWindowLong(h, -20) & 0x80) != 0) return true;
                RECT r;
                if (!GetWindowRect(h, out r)) return true;
                long area = (long)(r.Right - r.Left) * (long)(r.Bottom - r.Top);
                if (area < 40000) return true;
                ShowWindow(h, 7);
                Log("gog: Galaxy window minimized");
                return true;
            }, IntPtr.Zero);
        }

        // Прячет видимые окна Galaxy сразу после её запуска нами: клиент остаётся в трее, кнопка на
        // панели задач исчезает. Спрятанное окно не считается открытым, поэтому потом клиент можно закрыть.
        static void HideGalaxyWindows()
        {
            List<int> gx = FindPidsByName("GalaxyClient.exe");
            if (gx.Count == 0) return;
            EnumWindows(delegate (IntPtr h, IntPtr lp)
            {
                uint pid;
                GetWindowThreadProcessId(h, out pid);
                if (!gx.Contains((int)pid)) return true;
                if (!IsWindowVisible(h)) return true;
                if ((GetWindowLong(h, -20) & 0x80) != 0) return true;
                RECT r;
                if (!GetWindowRect(h, out r)) return true;
                long area = (long)(r.Right - r.Left) * (long)(r.Bottom - r.Top);
                if (area < 40000 && !IsIconic(h)) return true;
                ShowWindow(h, 0);
                Log("gog: Galaxy window hidden");
                return true;
            }, IntPtr.Zero);
        }

        // Закрывает GOG Galaxy, который был запущен вместе с игрой: сначала ждёт (облачные
        // сохранения), потом закрывает только вежливо (WM_CLOSE), без принудительного завершения.
        // Ничего не делает, если открыто окно клиента или через него запущена другая игра GOG.
        static void CloseGalaxyIfIdle(string dir, int self)
        {
            for (int i = 0; i < 12; i++)
            {
                Thread.Sleep(1000);
                if (FindGamePids(dir, self).Count > 0) { Log("gog: game started again, leaving Galaxy open"); return; }
            }
            List<int> gx = FindPidsByName("GalaxyClient.exe");
            if (gx.Count == 0) { Log("gog: Galaxy already closed"); return; }
            IntPtr w = FindBestWindow(gx);
            if (w != IntPtr.Zero && !IsIconic(w)) { Log("gog: Galaxy window is open, leaving it"); return; }
            string other = FindOtherGogGame(dir);
            if (other.Length > 0) { Log("gog: another GOG game is running (" + other + "), leaving Galaxy open"); return; }
            Log("gog: closing Galaxy, pids=" + gx.Count);
            PostCloseToWindows(gx);
            DateTime t0 = DateTime.UtcNow;
            while ((DateTime.UtcNow - t0).TotalSeconds < 10)
            {
                Thread.Sleep(500);
                if (FindPidsByName("GalaxyClient.exe").Count == 0) { Log("gog: Galaxy closed gracefully"); return; }
            }
            Log("gog: Galaxy did not close gracefully, leaving it running");
        }

        // Сторож: отдельный процесс (вне дерева Steam). Если Steam убил SCLauncher.exe жёстко
        // (кнопка "Остановить"), а игра ещё работает — закрывает игру. Если лаунчер запущен
        // вместе с игрой (closeEgs / closeGog), после выхода из игры закрывает и его.
        static void StartWatchdog(string dir, bool closeEgs, bool closeGog, bool closeUbi, bool closeEa, bool closeBnet)
        {
            try
            {
                string self = System.Reflection.Assembly.GetExecutingAssembly().Location;
                string cmd = "\"" + self + "\" --watch " + selfPid + " --dir \"" + dir.TrimEnd('\\') + "\"";
                if (closeEgs) cmd += " --egs 1";
                if (closeGog) cmd += " --gog 1";
                if (closeUbi) cmd += " --ubi 1";
                if (closeEa) cmd += " --ea 1";
                if (closeBnet) cmd += " --bnet 1";
                if (eaMode) cmd += " --eamode 1";
                WmiCreate(cmd);
            }
            catch (Exception ex) { Log("watchdog start: " + ex.Message); }
        }

        static int RunWatchdog(int wrapperPid, string dir, int self, bool closeEgs, bool closeGog, bool closeUbi, bool closeEa, bool closeBnet)
        {
            Process wp = null;
            try { wp = Process.GetProcessById(wrapperPid); }
            catch { return 0; }
            Log("watchdog: watching wrapper " + wrapperPid + (closeEgs ? " (will close EGS)" : "") + (closeGog ? " (will close Galaxy)" : "") + (closeUbi ? " (will close Ubisoft)" : "") + (closeEa ? " (will close EA app)" : "") + (closeBnet ? " (will close Battle.net)" : ""));
            if (closeEa)
            {
                // Наблюдатель работает в отдельном потоке до конца жизни сторожа: окно EA app должно
                // прятаться и пока сторож закрывает игру (это занимает до ~6 с), а не только после.
                Thread th = new Thread(delegate ()
                {
                    try { WatchEaWhileWrapperAlive(wp, dir, self); }
                    catch (Exception ex) { Log("ea: watcher failed: " + ex.Message); }
                });
                th.IsBackground = true;
                th.Start();
            }
            wp.WaitForExit();
            if (closeEa) { eaForceHide = true; Log("ea: wrapper ended, hiding EA window"); }
            Thread.Sleep(1500);
            if (FindGamePids(dir, self).Count > 0)
            {
                Log("watchdog: wrapper ended while game is running -> closing game");
                CloseGame(dir, self);
            }
            else Log("watchdog: game already gone");
            if (closeEgs) CloseEgsIfIdle(dir, self);
            if (closeGog) CloseGalaxyIfIdle(dir, self);
            if (closeUbi) CloseUbiIfIdle(dir, self);
            if (closeEa) CloseEaIfIdle(dir, self);
            if (closeBnet) CloseBnetIfIdle(dir, self);
            return 0;
        }


        // ---------- ROM из архива: распаковка во временную папку и запуск RetroArch ----------
        static string RomRoot()
        {
            return Path.Combine(Path.Combine(Path.GetTempPath(), "SteamCommander"), "roms");
        }

        // Маркер владельца папки: PID + время старта процесса (защита от повторного использования PID).
        static string RomMarkerText()
        {
            long st = 0;
            try { st = Process.GetCurrentProcess().StartTime.ToFileTimeUtc(); } catch { }
            return selfPid + "|" + st;
        }

        static bool RomMarkerAlive(string markerPath)
        {
            try
            {
                string[] p = File.ReadAllText(markerPath).Trim().Split('|');
                int pid; long st;
                if (p.Length < 2 || !int.TryParse(p[0], out pid) || !long.TryParse(p[1], out st)) return false;
                Process pr = Process.GetProcessById(pid);
                try { return pr.StartTime.ToFileTimeUtc() == st; }
                finally { pr.Dispose(); }
            }
            catch { return false; }
        }

        static void TryDeleteDir(string d)
        {
            for (int i = 0; i < 6; i++)
            {
                try
                {
                    if (!Directory.Exists(d)) return;
                    foreach (string f in Directory.GetFiles(d, "*", SearchOption.AllDirectories))
                    {
                        try { File.SetAttributes(f, FileAttributes.Normal); } catch { }
                    }
                    Directory.Delete(d, true);
                    return;
                }
                catch { Thread.Sleep(500); }
            }
            Log("roms: could not delete " + d);
        }

        // Удаляет папки распаковки, чей процесс уже не жив (убили SCLauncher/выключили ПК).
        static void CleanupOrphanRoms()
        {
            try
            {
                string root = RomRoot();
                if (!Directory.Exists(root)) return;
                foreach (string d in Directory.GetDirectories(root))
                {
                    try
                    {
                        string m = Path.Combine(d, ".sc_pid");
                        bool alive;
                        if (File.Exists(m)) alive = RomMarkerAlive(m);
                        else alive = (DateTime.UtcNow - Directory.GetCreationTimeUtc(d)).TotalHours < 1;
                        if (!alive) { Log("roms: cleanup orphan " + d); TryDeleteDir(d); }
                    }
                    catch { }
                }
            }
            catch (Exception ex) { Log("roms: cleanup failed: " + ex.Message); }
        }

        static string FindSevenZip(string baseDir)
        {
            List<string> c = new List<string>();
            string[] bases = new string[] {
                Environment.GetEnvironmentVariable("ProgramFiles"),
                Environment.GetEnvironmentVariable("ProgramFiles(x86)"),
                Environment.GetEnvironmentVariable("ProgramW6432") };
            foreach (string b in bases) { if (!string.IsNullOrEmpty(b)) c.Add(Path.Combine(b, "7-Zip\\7z.exe")); }
            try { c.Add(Path.Combine(Path.Combine(Path.GetFullPath(Path.Combine(baseDir, "..")), "7z"), "7zr.exe")); } catch { }
            foreach (string p in c) { if (File.Exists(p)) return p; }
            return "";
        }

        static bool ExtractZipBuiltin(string archive, string dest)
        {
            string destFull = Path.GetFullPath(dest).TrimEnd('\\') + "\\";
            using (ZipArchive za = ZipFile.OpenRead(archive))
            {
                foreach (ZipArchiveEntry e in za.Entries)
                {
                    if (StopRequested) return false;
                    string name = e.FullName.Replace('/', '\\');
                    if (name.Length == 0 || name.EndsWith("\\")) continue;
                    string target = Path.GetFullPath(Path.Combine(dest, name));
                    if (!target.StartsWith(destFull, StringComparison.OrdinalIgnoreCase)) continue;
                    Directory.CreateDirectory(Path.GetDirectoryName(target));
                    e.ExtractToFile(target, true);
                }
            }
            return true;
        }

        static bool ExtractExternal(string tool, string archive, string dest)
        {
            string n = Path.GetFileName(tool).ToLowerInvariant();
            ProcessStartInfo psi = new ProcessStartInfo();
            psi.FileName = tool;
            psi.UseShellExecute = false;
            psi.CreateNoWindow = true;
            if (n.StartsWith("winrar") || n.StartsWith("unrar") || n == "rar.exe")
            {
                psi.Arguments = "x -y -ibck -o+ \"" + archive + "\"";
                psi.WorkingDirectory = dest;
            }
            else
            {
                psi.Arguments = "x -y -bd -o\"" + dest.TrimEnd('\\') + "\" \"" + archive + "\"";
            }
            Process p = Process.Start(psi);
            while (!p.WaitForExit(300))
            {
                if (StopRequested) { try { p.Kill(); } catch { } return false; }
            }
            Log("rom: extractor exit code " + p.ExitCode);
            return p.ExitCode <= 1;
        }

        // Главный файл образа: .cue -> .gdi -> .m3u -> .iso (если ядро их поддерживает),
        // затем первый файл с расширением из supported_extensions, затем самый большой.
        static string FindRomMain(string dir, string[] exts)
        {
            List<string> files = new List<string>();
            foreach (string f in Directory.GetFiles(dir, "*", SearchOption.AllDirectories))
            {
                if (string.Equals(Path.GetFileName(f), ".sc_pid", StringComparison.OrdinalIgnoreCase)) continue;
                files.Add(f);
            }
            if (files.Count == 0) return "";
            files.Sort(delegate (string a, string b)
            {
                int da = a.Split('\\').Length;
                int db = b.Split('\\').Length;
                if (da != db) return da.CompareTo(db);
                return string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
            });
            string[] pri = new string[] { ".cue", ".gdi", ".m3u", ".iso" };
            bool haveExts = (exts != null && exts.Length > 0);
            foreach (string p in pri)
            {
                if (haveExts && Array.IndexOf(exts, p.Substring(1)) < 0) continue;
                foreach (string f in files) { if (f.EndsWith(p, StringComparison.OrdinalIgnoreCase)) return f; }
            }
            if (haveExts)
            {
                foreach (string f in files)
                {
                    string e = Path.GetExtension(f).TrimStart('.').ToLowerInvariant();
                    if (Array.IndexOf(exts, e) >= 0) return f;
                }
            }
            foreach (string p in pri)
            {
                foreach (string f in files) { if (f.EndsWith(p, StringComparison.OrdinalIgnoreCase)) return f; }
            }
            string best = files[0];
            long bestLen = -1;
            foreach (string f in files)
            {
                long len = 0;
                try { len = new FileInfo(f).Length; } catch { }
                if (len > bestLen) { bestLen = len; best = f; }
            }
            return best;
        }

        // Сторож вне дерева Steam: если SCLauncher убит жёстко, закрывает RetroArch и удаляет папку.
        static void StartRomWatchdog(int emuPid, string emu, string romDir)
        {
            try
            {
                string self = System.Reflection.Assembly.GetExecutingAssembly().Location;
                string cmd = "\"" + self + "\" --romwatch " + selfPid + " --emupid " + emuPid + " --emu \"" + emu + "\" --romdir \"" + romDir + "\"";
                WmiCreate(cmd);
            }
            catch (Exception ex) { Log("rom watchdog start: " + ex.Message); }
        }

        static int RunRomWatchdog(int wrapperPid, int emuPid, string emu, string romDir)
        {
            try
            {
                Process wp = Process.GetProcessById(wrapperPid);
                wp.WaitForExit();
            }
            catch { }
            Thread.Sleep(1500);
            try
            {
                if (emuPid > 0)
                {
                    string img = GetImagePath(emuPid);
                    if (img.Length > 0 && string.Equals(img, emu, StringComparison.OrdinalIgnoreCase))
                    {
                        Process ep = Process.GetProcessById(emuPid);
                        Log("romwatch: wrapper ended while RetroArch runs -> closing it");
                        try { ep.CloseMainWindow(); } catch { }
                        if (!ep.WaitForExit(4000)) { try { ep.Kill(); ep.WaitForExit(3000); } catch { } }
                    }
                }
            }
            catch { }
            if (romDir.Length > 0) TryDeleteDir(romDir);
            return 0;
        }


        static List<string> ParseDiscRefs(string file)
        {
            List<string> r = new List<string>();
            string ext = Path.GetExtension(file).ToLowerInvariant();
            foreach (string line in File.ReadAllLines(file))
            {
                string t = line.Trim();
                if (t.Length == 0) continue;
                if (ext == ".cue")
                {
                    Match m = Regex.Match(t, "^FILE\\s+\"([^\"]+)\"", RegexOptions.IgnoreCase);
                    if (m.Success) r.Add(m.Groups[1].Value);
                }
                else if (ext == ".m3u")
                {
                    if (!t.StartsWith("#")) r.Add(t);
                }
                else if (ext == ".gdi")
                {
                    Match m = Regex.Match(t, "^\\d+\\s+\\d+\\s+\\d+\\s+\\d+\\s+(\"[^\"]+\"|\\S+)\\s+\\d+");
                    if (m.Success) r.Add(m.Groups[1].Value.Trim('"'));
                }
            }
            return r;
        }

        static void ExtractZipNames(string archive, string dest, List<string> names)
        {
            string destFull = Path.GetFullPath(dest).TrimEnd('\\') + "\\";
            using (ZipArchive za = ZipFile.OpenRead(archive))
            {
                Dictionary<string, ZipArchiveEntry> byPath = new Dictionary<string, ZipArchiveEntry>();
                Dictionary<string, List<ZipArchiveEntry>> byLeaf = new Dictionary<string, List<ZipArchiveEntry>>();
                foreach (ZipArchiveEntry e in za.Entries)
                {
                    string n = e.FullName.Replace('/', '\\');
                    if (n.Length == 0 || n.EndsWith("\\")) continue;
                    byPath[n.ToLowerInvariant()] = e;
                    string leaf = Path.GetFileName(n).ToLowerInvariant();
                    if (!byLeaf.ContainsKey(leaf)) byLeaf[leaf] = new List<ZipArchiveEntry>();
                    byLeaf[leaf].Add(e);
                }
                foreach (string name in names)
                {
                    if (StopRequested) return;
                    string key = name.Replace('/', '\\').TrimStart('\\');
                    ZipArchiveEntry ze;
                    if (!byPath.TryGetValue(key.ToLowerInvariant(), out ze))
                    {
                        List<ZipArchiveEntry> l;
                        if (byLeaf.TryGetValue(Path.GetFileName(key).ToLowerInvariant(), out l) && l.Count == 1) ze = l[0];
                        else { Log("rom: not found in archive: " + name); continue; }
                    }
                    string rel = ze.FullName.Replace('/', '\\');
                    string target = Path.GetFullPath(Path.Combine(dest, rel));
                    if (!target.StartsWith(destFull, StringComparison.OrdinalIgnoreCase)) continue;
                    Directory.CreateDirectory(Path.GetDirectoryName(target));
                    ze.ExtractToFile(target, true);
                }
            }
        }

        static bool ExtractExternalNames(string tool, string archive, string dest, List<string> names)
        {
            string n = Path.GetFileName(tool).ToLowerInvariant();
            ProcessStartInfo psi = new ProcessStartInfo();
            psi.FileName = tool;
            psi.UseShellExecute = false;
            psi.CreateNoWindow = true;
            StringBuilder sb = new StringBuilder();
            foreach (string name in names) sb.Append(" \"").Append(name.Replace('/', '\\').TrimStart('\\')).Append("\"");
            if (n.StartsWith("winrar") || n.StartsWith("unrar") || n == "rar.exe")
            {
                psi.Arguments = "x -y -ibck -o+ \"" + archive + "\"" + sb.ToString();
                psi.WorkingDirectory = dest;
            }
            else
            {
                psi.Arguments = "x -y -bd -o\"" + dest.TrimEnd('\\') + "\" \"" + archive + "\"" + sb.ToString();
            }
            Process p = Process.Start(psi);
            while (!p.WaitForExit(300))
            {
                if (StopRequested) { try { p.Kill(); } catch { } return false; }
            }
            Log("rom: extractor exit code " + p.ExitCode);
            return p.ExitCode <= 1;
        }

        static bool ExtractNames(string tool, string archive, string dest, List<string> names)
        {
            if (names.Count == 0) return true;
            if (string.Equals(Path.GetExtension(archive), ".zip", StringComparison.OrdinalIgnoreCase)) { ExtractZipNames(archive, dest, names); return true; }
            return ExtractExternalNames(tool, archive, dest, names);
        }

        // Распаковывает выбранный файл и, для .cue/.gdi/.m3u, все файлы, на которые он ссылается.
        static bool ExtractEntryTree(string tool, string archive, string dest, string entry, int depth)
        {
            List<string> one = new List<string>();
            one.Add(entry);
            if (!ExtractNames(tool, archive, dest, one)) return false;
            string e = Path.GetExtension(entry).ToLowerInvariant();
            string full = Path.Combine(dest, entry);
            if (depth >= 3 || !(e == ".cue" || e == ".gdi" || e == ".m3u") || !File.Exists(full)) return true;
            string baseDir = Path.GetDirectoryName(entry);
            if (baseDir == null) baseDir = "";
            List<string> names = new List<string>();
            foreach (string r in ParseDiscRefs(full))
            {
                string rr = r.Replace('/', '\\');
                names.Add(baseDir.Length > 0 ? baseDir + "\\" + rr : rr);
            }
            if (names.Count > 0 && !ExtractNames(tool, archive, dest, names)) return false;
            foreach (string rel in names)
            {
                string re = Path.GetExtension(rel).ToLowerInvariant();
                if ((re == ".cue" || re == ".gdi" || re == ".m3u") && File.Exists(Path.Combine(dest, rel)))
                    ExtractEntryTree(tool, archive, dest, rel, depth + 1);
            }
            return true;
        }

        // ---- Общая подготовка ROM из архива (RetroArch и обычные эмуляторы) ----
        // Коды ошибок: 0 - успех (или запрошена остановка), 2 - нет файла архива/эмулятора,
        // 3 - нет распаковщика, 4 - эмулятор не запустился, 5 - архив повреждён, 6 - нет места.
        static long FreeSpace(string path)
        {
            try { return new DriveInfo(Path.GetPathRoot(Path.GetFullPath(path))).AvailableFreeSpace; }
            catch { return -1; }
        }

        static bool IsDiskFull(Exception ex)
        {
            if (!(ex is IOException)) return false;
            int code = System.Runtime.InteropServices.Marshal.GetHRForException(ex) & 0xFFFF;
            return code == 112 || code == 39;
        }

        // Размер файлов .zip после распаковки (всех или только выбранного) - для проверки свободного места.
        static long ZipUnpackedSize(string archive, string entry)
        {
            long sum = 0;
            string key = entry.Length > 0 ? entry.Replace('/', '\\').TrimStart('\\').ToLowerInvariant() : null;
            using (ZipArchive za = ZipFile.OpenRead(archive))
            {
                foreach (ZipArchiveEntry e in za.Entries)
                {
                    if (key != null && e.FullName.Replace('/', '\\').ToLowerInvariant() != key) continue;
                    sum += e.Length;
                }
            }
            return sum;
        }

        // Распаковывает архив в готовую папку dir и возвращает путь к главному файлу ROM.
        // Пустая строка: при err == 0 - запрошена остановка, иначе - ошибка (err/detail).
        static string PrepareRomFromArchive(string archive, string sz, string[] extList, string entry, string baseDir, string dir, out int err, out string detail)
        {
            err = 0; detail = "";
            try
            {
                string ext = Path.GetExtension(archive).ToLowerInvariant();
                string tool = "";
                if (ext != ".zip")
                {
                    tool = (sz.Length > 0 && File.Exists(sz)) ? sz : FindSevenZip(baseDir);
                    if (tool.Length == 0) { Log("rom: no extractor for " + ext); err = 3; detail = "7-Zip"; return ""; }
                }
                else
                {
                    long need = ZipUnpackedSize(archive, entry);
                    long free = FreeSpace(dir);
                    if (free >= 0 && need > 0 && free < need + 50L * 1024 * 1024)
                    {
                        Log("rom: not enough disk space, need " + need + " free " + free);
                        err = 6; detail = ((need / 1048576) + 1) + "|" + (free / 1048576);
                        return "";
                    }
                }
                string main;
                bool ok;
                if (entry.Length > 0)
                {
                    string en = entry.Replace('/', '\\').TrimStart('\\');
                    Log("rom: entry " + en);
                    ok = ExtractEntryTree(tool, archive, dir, en, 0);
                    if (StopRequested) return "";
                    if (ok)
                    {
                        main = Path.GetFullPath(Path.Combine(dir, en));
                        if (!main.StartsWith(Path.GetFullPath(dir), StringComparison.OrdinalIgnoreCase) || !File.Exists(main)) { Log("rom: entry not extracted"); err = 5; return ""; }
                        return main;
                    }
                }
                else
                {
                    if (ext == ".zip") ok = ExtractZipBuiltin(archive, dir);
                    else ok = ExtractExternal(tool, archive, dir);
                    if (StopRequested) return "";
                    if (ok)
                    {
                        main = FindRomMain(dir, extList);
                        if (main.Length == 0) { Log("rom: no files after extraction"); err = 5; return ""; }
                        return main;
                    }
                }
                Log("rom: extraction failed");
                long fr = FreeSpace(dir);
                if (fr >= 0 && fr < 100L * 1024 * 1024) { err = 6; detail = "?|" + (fr / 1048576); }
                else err = 5;
                return "";
            }
            catch (InvalidDataException ex) { Log("rom: corrupted archive: " + ex.Message); err = 5; detail = ex.Message; return ""; }
            catch (IOException ex)
            {
                Log("rom: io error: " + ex.Message);
                if (IsDiskFull(ex)) { err = 6; long f2 = FreeSpace(dir); detail = "?|" + (f2 >= 0 ? (f2 / 1048576).ToString() : "?"); }
                else { err = 5; detail = ex.Message; }
                return "";
            }
            catch (Exception ex) { Log("rom: extract error: " + ex.Message); err = 5; detail = ex.Message; return ""; }
        }

        static string BuildEmuArgs(string template, string rom)
        {
            string q = "\"" + rom + "\"";
            if (string.IsNullOrEmpty(template) || template.Trim().Length == 0) return q;
            if (template.IndexOf("{rom}", StringComparison.OrdinalIgnoreCase) >= 0)
                return Regex.Replace(template, Regex.Escape("{rom}"), q.Replace("$", "$$"), RegexOptions.IgnoreCase);
            return template.TrimEnd() + " " + q;
        }

        // Эмулятор мог передать запуск другому процессу того же exe и завершиться сам - ждём и его.
        static bool EmuFamilyAlive(string emu, int exceptPid)
        {
            try
            {
                foreach (Process p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(emu)))
                {
                    try
                    {
                        if (p.Id == exceptPid) continue;
                        string img = GetImagePath(p.Id);
                        if (img.Length > 0 && string.Equals(img, emu, StringComparison.OrdinalIgnoreCase)) return true;
                    }
                    catch { }
                    finally { p.Dispose(); }
                }
            }
            catch { }
            return false;
        }

        [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "MessageBoxW")]
        static extern int RomMessageBox(IntPtr hWnd, string text, string caption, uint type);

