                        "7-Zip is required to extract this archive, but it was not found.",
                        "\u89e3\u538b\u6b64\u538b\u7f29\u5305\u9700\u8981 7-Zip\uff0c\u4f46\u672a\u627e\u5230\u3002",
                        "Se necesita 7-Zip para extraer este archivo, pero no se encontr\u00f3.",
                        "O 7-Zip \u00e9 necess\u00e1rio para extrair este arquivo, mas n\u00e3o foi encontrado.",
                        "Zum Entpacken dieses Archivs wird 7-Zip ben\u00f6tigt, es wurde aber nicht gefunden." };
                    return t[li];
                case 4:
                    t = new string[] {
                        "\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u044d\u043c\u0443\u043b\u044f\u0442\u043e\u0440.",
                        "Could not start the emulator.",
                        "\u65e0\u6cd5\u542f\u52a8\u6a21\u62df\u5668\u3002",
                        "No se pudo iniciar el emulador.",
                        "N\u00e3o foi poss\u00edvel iniciar o emulador.",
                        "Der Emulator konnte nicht gestartet werden." };
                    return t[li];
                case 2:
                    t = new string[] {
                        "\u0424\u0430\u0439\u043b \u0430\u0440\u0445\u0438\u0432\u0430 \u0438\u043b\u0438 \u044d\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d.",
                        "The archive or emulator file was not found.",
                        "\u672a\u627e\u5230\u538b\u7f29\u5305\u6216\u6a21\u62df\u5668\u6587\u4ef6\u3002",
                        "No se encontr\u00f3 el archivo comprimido o el emulador.",
                        "O arquivo compactado ou o emulador n\u00e3o foi encontrado.",
                        "Das Archiv oder der Emulator wurde nicht gefunden." };
                    return t[li];
                default:
                    t = new string[] {
                        "\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0440\u0430\u0441\u043f\u0430\u043a\u043e\u0432\u0430\u0442\u044c \u0430\u0440\u0445\u0438\u0432: \u043e\u043d \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0451\u043d \u0438\u043b\u0438 \u0438\u043c\u0435\u0435\u0442 \u043d\u0435\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u0439 \u0444\u043e\u0440\u043c\u0430\u0442.",
                        "Could not extract the archive: it is corrupted or its format is not supported.",
                        "\u65e0\u6cd5\u89e3\u538b\u538b\u7f29\u5305\uff1a\u6587\u4ef6\u5df2\u635f\u574f\u6216\u683c\u5f0f\u4e0d\u53d7\u652f\u6301\u3002",
                        "No se pudo extraer el archivo: est\u00e1 da\u00f1ado o su formato no es compatible.",
                        "N\u00e3o foi poss\u00edvel extrair o arquivo: ele est\u00e1 corrompido ou o formato n\u00e3o \u00e9 compat\u00edvel.",
                        "Das Archiv konnte nicht entpackt werden: Es ist besch\u00e4digt oder das Format wird nicht unterst\u00fctzt." };
                    return t[li];
            }
        }

        // Сообщение об ошибке запуска ROM из архива (только для обычных эмуляторов; RetroArch, как и раньше, пишет в лог).
        static void ShowRomError(string lang, int err, string detail)
        {
            try
            {
                if (StopRequested) return;
                string text = RomMsg(lang, err, detail);
                if (err == 5 && detail.Length > 0 && detail.Length < 300) text += "\r\n\r\n" + detail;
                // MB_ICONERROR | MB_SETFOREGROUND | MB_TOPMOST: у обёртки нет окна, иначе сообщение осталось бы позади.
                RomMessageBox(IntPtr.Zero, text, "Steam Commander", 0x10 | 0x10000 | 0x40000);
            }
            catch { }
        }

        // generic == false: RetroArch (-L core + extra + файл); generic == true: любой эмулятор, параметры из шаблона emuArgs ({rom}).
        static int RunRomArchive(string archive, string emu, string core, string exts, string sz, string extra, string baseDir, string entry, bool generic, string emuArgs, string lang)
        {
            Log("rom: archive=" + archive + " emu=" + emu + (generic ? " (generic)" : " core=" + core));
            if (!File.Exists(archive) || !File.Exists(emu) || (!generic && core.Length == 0))
            {
                Log("rom: bad args or file missing");
                if (generic) ShowRomError(lang, 2, "");
                return 2;
            }
            StartStopListener();
            CleanupOrphanRoms();
            string[] extList = exts.Length > 0 ? exts.ToLowerInvariant().Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries) : new string[0];
            // Папка с уникальным именем: если такая вдруг уже есть, берём другое имя.
            string dir = "";
            for (int tries = 0; tries < 10; tries++)
            {
                dir = Path.Combine(RomRoot(), Guid.NewGuid().ToString("N").Substring(0, 12));
                if (!Directory.Exists(dir)) break;
            }
            try
            {
                Directory.CreateDirectory(dir);
                File.WriteAllText(Path.Combine(dir, ".sc_pid"), RomMarkerText());
                int perr; string pdetail;
                string main = PrepareRomFromArchive(archive, sz, extList, entry, baseDir, dir, out perr, out pdetail);
                if (main.Length == 0)
                {
                    if (perr != 0 && generic) ShowRomError(lang, perr, pdetail);
                    return perr == 0 ? 0 : 3;
                }
                Log("rom: main file " + main);

                ProcessStartInfo psi = new ProcessStartInfo();
                psi.FileName = emu;
                psi.WorkingDirectory = Path.GetDirectoryName(emu);
                psi.UseShellExecute = false;
                if (generic) psi.Arguments = BuildEmuArgs(emuArgs, main);
                else psi.Arguments = "-L \"cores\\" + core + "_libretro.dll\" " + (extra.Length > 0 ? extra + " " : "") + "\"" + main + "\"";
                Log("rom: start " + psi.Arguments);
                // Дочерний процесс наследует пониженный приоритет: на время запуска возвращаем обычный.
                Process self = Process.GetCurrentProcess();
                try { self.PriorityClass = ProcessPriorityClass.Normal; } catch { }
                Process rp = null;
                try { rp = Process.Start(psi); }
                catch (Exception sx) { Log("rom: start failed: " + sx.Message); }
                try { self.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                if (rp == null)
                {
                    Log("rom: emulator did not start");
                    if (generic) ShowRomError(lang, 4, "");
                    return 4;
                }
                int rpId = rp.Id;
                try { rp.PriorityClass = ProcessPriorityClass.Normal; } catch { }
                StartRomWatchdog(rpId, emu, dir);
                while (!rp.WaitForExit(300))
                {
                    if (StopRequested)
                    {
                        Log("rom: stop requested");
                        try { rp.CloseMainWindow(); } catch { }
                        if (!rp.WaitForExit(4000)) { try { rp.Kill(); rp.WaitForExit(3000); } catch { } }
                        break;
                    }
                }
                if (generic && !StopRequested)
                {
                    DateTime until = DateTime.UtcNow.AddSeconds(3);
                    while (!StopRequested)
                    {
                        if (EmuFamilyAlive(emu, rpId)) { until = DateTime.UtcNow.AddSeconds(3); Thread.Sleep(500); }
                        else if (DateTime.UtcNow > until) break;
                        else Thread.Sleep(300);
                    }
                }
                Log("rom: emulator finished");
                return 0;
            }
            catch (Exception ex) { Log("rom: " + ex.Message); if (generic) ShowRomError(lang, 5, ex.Message); return 4; }
            finally { TryDeleteDir(dir); }
        }

        public static int Main(string[] args)
        {
            try
            {
                selfPid = Process.GetCurrentProcess().Id;
                // Пониженный приоритет: обёртка и сторож не должны отнимать процессор у игры.
                try { Process.GetCurrentProcess().PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                string baseDir = AppDomain.CurrentDomain.BaseDirectory;
                logPath = Path.Combine(baseDir, "SCLauncher.log");
                try
                {
                    FileInfo fi = new FileInfo(logPath);
                    if (fi.Exists && fi.Length > 200000) fi.Delete();
                }
                catch { }

                string uri = "";
                string dir = "";
                int timeout = 120;
                int watchPid = 0;
                bool closeEgs = false;
                bool closeGog = false;
                bool closeUbi = false;
                bool closeEa = false;
                bool closeBnet = false;
                bool timeoutSet = false;
                string client = "";
                string exePath = "";
                string romArchive = "", romEmu = "", romCore = "", romExts = "", romSz = "", romExtra = "", romDirArg = "", romEntry = "", romArgs = "", romLang = "en";
                bool romGeneric = false;
                int romWatchPid = 0, romEmuPid = 0;
                bool cleanupRoms = false;
                for (int i = 0; i < args.Length - 1; i++)
                {
                    string a = args[i].ToLowerInvariant();
                    if (a == "--uri") uri = args[i + 1];
                    else if (a == "--dir") dir = args[i + 1];
                    else if (a == "--timeout") { int t; if (int.TryParse(args[i + 1], out t) && t > 0) { timeout = t; timeoutSet = true; } }
                    else if (a == "--watch") { int w; if (int.TryParse(args[i + 1], out w) && w > 0) watchPid = w; }
                    else if (a == "--egs") closeEgs = (args[i + 1] == "1");
                    else if (a == "--gog") closeGog = (args[i + 1] == "1");
                    else if (a == "--ubi") closeUbi = (args[i + 1] == "1");
                    else if (a == "--ea") closeEa = (args[i + 1] == "1");
                    else if (a == "--bnet") closeBnet = (args[i + 1] == "1");
                    else if (a == "--eamode") eaMode = (args[i + 1] == "1");
                    else if (a == "--client") client = args[i + 1];
                    else if (a == "--exe") exePath = args[i + 1];
                    else if (a == "--rom-archive") romArchive = args[i + 1];
                    else if (a == "--emu") romEmu = args[i + 1];
                    else if (a == "--core") romCore = args[i + 1];
                    else if (a == "--exts") romExts = args[i + 1];
                    else if (a == "--sz") romSz = args[i + 1];
                    else if (a == "--extra") romExtra = args[i + 1];
                    else if (a == "--entry") romEntry = args[i + 1];
                    else if (a == "--args") { romArgs = args[i + 1]; romGeneric = true; }
                    else if (a == "--lang") romLang = args[i + 1];
                    else if (a == "--romdir") romDirArg = args[i + 1];
                    else if (a == "--romwatch") { int rw; if (int.TryParse(args[i + 1], out rw) && rw > 0) romWatchPid = rw; }
                    else if (a == "--emupid") { int re; if (int.TryParse(args[i + 1], out re) && re > 0) romEmuPid = re; }
                    else if (a == "--cleanup-roms") cleanupRoms = (args[i + 1] == "1");
                }
                if (cleanupRoms) { CleanupOrphanRoms(); return 0; }
                if (romWatchPid > 0) return RunRomWatchdog(romWatchPid, romEmuPid, romEmu, romDirArg);
                if (romArchive.Length > 0) return RunRomArchive(romArchive, romEmu, romCore, romExts, romSz, romExtra, baseDir, romEntry, romGeneric, romArgs, romLang);
                if (dir.Length == 0) { Log("bad args"); return 2; }
                dir = dir.Replace('/', '\\').TrimEnd('\\') + "\\";
                int self = selfPid;

                if (watchPid > 0) return RunWatchdog(watchPid, dir, self, closeEgs, closeGog, closeUbi, closeEa, closeBnet);
                if (uri.Length == 0) { Log("bad args"); return 2; }
                Log("start dir=" + dir + " uri=" + uri);

                // gog:<id> - игра GOG запускается через клиент Galaxy (путь к нему в --client).
                bool isGog = uri.StartsWith("gog:", StringComparison.OrdinalIgnoreCase);
                string gogId = "";
                if (isGog)
                {
                    gogId = uri.Substring(4).Trim();
                    if (!Regex.IsMatch(gogId, @"^\d+$") || client.Length == 0 || !File.Exists(client)) { Log("bad gog args"); return 2; }
                    if (!timeoutSet) timeout = 180;
                }

                // uplay://launch/<id>/<mode> - игра Ubisoft запускается через Ubisoft Connect.
                // Клиент стартует долго (вход в аккаунт, проверка обновлений), поэтому ждём дольше.
                bool isUbi = uri.StartsWith("uplay:", StringComparison.OrdinalIgnoreCase);
                if (isUbi)
                {
                    if (!Regex.IsMatch(uri, @"^uplay://launch/\d+/\d+$", RegexOptions.IgnoreCase)) { Log("bad uplay args"); return 2; }
                    if (!timeoutSet) timeout = 180;
                }

                bool isEa = uri.StartsWith("origin2://", StringComparison.OrdinalIgnoreCase)
                    || uri.StartsWith("origin://", StringComparison.OrdinalIgnoreCase);
                if (isEa)
                {
                    eaMode = true;
                    if (uri.IndexOf("offerIds=", StringComparison.OrdinalIgnoreCase) < 0
                        && uri.IndexOf("launchgame", StringComparison.OrdinalIgnoreCase) < 0)
                    { Log("bad ea/origin args"); return 2; }
                    if (!timeoutSet) timeout = 180;
                }

                bool isBnet = uri.StartsWith("bnet:", StringComparison.OrdinalIgnoreCase);
                string bnetId = "";
                if (isBnet)
                {
                    bnetId = uri.Substring(5).Trim();
                    if (!Regex.IsMatch(bnetId, @"^[A-Za-z0-9_]+$") || client.Length == 0 || !File.Exists(client))
                    { Log("bad bnet args"); return 2; }
                    if (!timeoutSet) timeout = 180;
                }

                StartStopListener();

                List<int> pids = FindGamePids(dir, self);
                // Лаунчер закрываем после игры только если он не был запущен до нас.
                bool egsStartedByUs = false;
                if (pids.Count == 0 && uri.StartsWith("com.epicgames.launcher:", StringComparison.OrdinalIgnoreCase))
                    egsStartedByUs = (FindPidsByName("EpicGamesLauncher.exe").Count == 0);
                bool gogStartedByUs = false;
                if (pids.Count == 0 && isGog)
                    gogStartedByUs = (FindPidsByName("GalaxyClient.exe").Count == 0);
                // Ubisoft Connect закрываем после игры только если он не был запущен до нас.
                bool ubiStartedByUs = false;
                if (pids.Count == 0 && isUbi)
                    ubiStartedByUs = (FindPidsByName("UbisoftConnect.exe").Count == 0 && FindPidsByName("upc.exe").Count == 0);
                bool eaStartedByUs = false;
                if (pids.Count == 0 && isEa)
                    eaStartedByUs = (FindPidsByName("EADesktop.exe").Count == 0 && FindPidsByName("Origin.exe").Count == 0);
                bool bnetStartedByUs = false;
                if (pids.Count == 0 && isBnet)
                    bnetStartedByUs = (FindPidsByName("Battle.net.exe").Count == 0 && FindPidsByName("Battle.net Launcher.exe").Count == 0);
                StartWatchdog(dir, egsStartedByUs, gogStartedByUs, ubiStartedByUs, eaStartedByUs, bnetStartedByUs);
                if (pids.Count == 0)
                {
                    // Ubisoft Connect: при холодном старте клиента первая ссылка uplay:// иногда теряется
                    // (клиент ещё входит в аккаунт и грузит список игр) - тогда ниже она отправляется повторно.
                    bool ubiCold = isUbi && FindPidsByName("UbisoftConnect.exe").Count == 0 && FindPidsByName("upc.exe").Count == 0;
                    bool ubiRetried = false;
                    int bnetResends = 0;
                    bool bnetDirectTried = false;
                    int bnetDirectCount = 0;
                    DateTime bnetSeen = DateTime.MinValue;
                    DateTime bnetNextDirect = DateTime.MinValue;
                    bool bnetClientWasRunning = isBnet && (FindPidsByName("Battle.net.exe").Count > 0 || FindPidsByName("Battle.net Launcher.exe").Count > 0);
                    if (isUbi) Log("ubisoft: client " + (ubiCold ? "not running (cold start)" : "already running"));
                    try
                    {
                        if (isGog)
                        {
                            if (!LaunchGalaxyDetached(gogId, dir, client, gogStartedByUs)) { Log("galaxy launch failed"); return 3; }
                        }
                        else if (isBnet)
                        {
                            // Клиент уже работает - игру запустим напрямую ниже (без показа страницы игры).
                            if (bnetClientWasRunning) Log("bnet: client already running, direct start");
                            else if (!LaunchBnetClientDetached(client)) { Log("bnet launch failed"); return 3; }
                        }
                        else LaunchUriDetached(uri);
                    }
                    catch (Exception ex) { Log("uri start failed: " + ex.Message); return 3; }
                    DateTime t0 = DateTime.UtcNow;
                    while ((DateTime.UtcNow - t0).TotalSeconds < timeout)
                    {
                        Thread.Sleep((isGog || isBnet) ? 250 : 500);
                        if (StopRequested) { Log("stop requested before game start"); return 0; }
                        // Только первые секунды после запуска клиента нами: дальше окно, открытое из трея, не трогаем.
                        if (gogStartedByUs && (DateTime.UtcNow - t0).TotalSeconds < 15) HideGalaxyWindows();
                        // Ubisoft: прячем окно клиента, запущенного нами; после 45 с только сворачиваем,
                        // чтобы при запросе входа в аккаунт окно можно было открыть с панели задач.
                        if (ubiStartedByUs) QuietUbiWindows((DateTime.UtcNow - t0).TotalSeconds < 45);
                        // Battle.net: окно клиента, запущенного нами, прячем (как у GOG/Ubisoft).
                        if (bnetStartedByUs && (DateTime.UtcNow - t0).TotalSeconds < 40) QuietBnetWindows(true);
                        pids = FindGamePids(dir, self);
                        if (pids.Count > 0)
                        {
                            // Battle.net: при холодном старте игра может запуститься и сразу закрыться (клиент ещё не готов).
                            // Считаем запуск удавшимся, только если процесс прожил 6 с; иначе повторяем (до 3 раз).
                            if (!(isBnet && bnetDirectTried && bnetDirectCount < 3)) break;
                            if (bnetSeen == DateTime.MinValue) bnetSeen = DateTime.UtcNow;
                            if ((DateTime.UtcNow - bnetSeen).TotalSeconds >= 6) break;
                        }
                        else if (isBnet && bnetSeen != DateTime.MinValue)
                        {
                            bnetSeen = DateTime.MinValue;
                            bnetDirectTried = false;
                            bnetNextDirect = DateTime.UtcNow.AddSeconds(8);
                            Log("bnet: game exited right after start, will retry");
                        }
                        // Battle.net: клиент часто открывает только страницу игры и ничего не запускает.
                        // Сразу (клиент уже работал) или через 10 с после холодного старта запускаем exe игры напрямую,
                        // а если и это не помогло - повторяем команду --exec через 45 с.
                        if (isBnet && !bnetDirectTried && bnetDirectCount < 3 && DateTime.UtcNow >= bnetNextDirect && (DateTime.UtcNow - t0).TotalSeconds >= (bnetClientWasRunning ? 1 : 10)
                            && (FindPidsByName("Battle.net.exe").Count > 0 || FindPidsByName("Battle.net Launcher.exe").Count > 0))
                        {
                            bnetDirectTried = true;
                            bnetDirectCount++;
                            Log("bnet: game not started by client, trying direct exe start (attempt " + bnetDirectCount + ")");
                            LaunchBnetGameExeDirect(bnetId, dir, exePath);
                        }
                        if (isBnet && bnetResends < 1 && (DateTime.UtcNow - t0).TotalSeconds >= 45)
                        {
                            bnetResends++;
                            Log("bnet: game still not started, resending command");
                            try { LaunchBattleNetDetached(bnetId, client, dir); } catch (Exception ex) { Log("bnet retry failed: " + ex.Message); }
                        }
                        // Ubisoft: игра не появилась - один раз повторяем ссылку (не чаще, чтобы не плодить окна).
                        if (isUbi && !ubiRetried && (DateTime.UtcNow - t0).TotalSeconds >= (ubiCold ? 45 : 30))
                        {
                            ubiRetried = true;
                            Log("ubisoft: game not started yet, resending uri");
                            try { LaunchUriDetached(uri); } catch (Exception ex) { Log("ubisoft retry failed: " + ex.Message); }
                        }
                    }
                    if (pids.Count == 0) { Log("game process not found"); return 1; }
                }
                Log("game running, pids=" + pids.Count);
                foreach (int gpid in pids) Log("game pid " + gpid + ": " + GetImagePath(gpid));
                if (gogStartedByUs) MinimizeGalaxyWindows();
                if (bnetStartedByUs) QuietBnetWindows(false);

                if (isUbi)
                {
                    // Игры Ubisoft запускаются тихо: окно игры не трогаем (принудительный фокус в момент
                    // инициализации ронял игру). Только ждём и фиксируем, как завершился процесс игры.
                    List<Process> watch = new List<Process>();
                    foreach (int gp in pids) { try { watch.Add(Process.GetProcessById(gp)); } catch { } }
                    DateTime tw = DateTime.UtcNow;
                    int quietTick = 0;
                    while ((DateTime.UtcNow - tw).TotalSeconds < 30)
                    {
                        Thread.Sleep(250);
                        if (StopRequested) { Log("stop requested -> closing game"); CloseGame(dir, self); return 0; }
                        if (ubiStartedByUs && (++quietTick % 4) == 0 && (DateTime.UtcNow - tw).TotalSeconds < 20) QuietUbiWindows(false);
                        bool allGone = true;
                        foreach (Process wpr in watch) { try { if (!wpr.HasExited) allGone = false; } catch { } }
                        if (allGone) break;
                    }
                    foreach (Process wpr in watch)
                    {
                        try
                        {
                            if (wpr.HasExited) Log("game pid " + wpr.Id + " exited after " + (int)(DateTime.UtcNow - tw).TotalMilliseconds + " ms, code=0x" + wpr.ExitCode.ToString("X"));
                            else Log("game pid " + wpr.Id + " still alive after 30 s");
                        }
                        catch (Exception ex) { Log("exit info failed: " + ex.Message); }
                        finally { try { wpr.Dispose(); } catch { } }
                    }
                }

                int attempts = 0;
                int stable = 0;
                for (int n = 0; n < 60 && stable < 3 && !isUbi; n++)
                {
                    Thread.Sleep(500);
                    if (StopRequested) { Log("stop requested -> closing game"); CloseGame(dir, self); return 0; }
                    if (gogStartedByUs && n < 10) MinimizeGalaxyWindows();
                    if (bnetStartedByUs && n < 20) QuietBnetWindows(true);
                    pids = FindGamePids(dir, self);
                    if (pids.Count == 0) break;
                    IntPtr w = FindBestWindow(pids);
                    if (w == IntPtr.Zero) continue;
                    if (GetForegroundWindow() == w) { stable++; continue; }
                    if (attempts >= 8) break;
                    attempts++;
                    stable = 0;
                    Focus(w, attempts >= 3);
                    Log("focus attempt " + attempts);
                }

                int missing = 0;
                int tick = 0;
                // EA: «игра запущена» = есть процессы самой игры (служебные, вроде EACoreServer, не считаются,
                // см. eaMode). Чтобы Steam узнал о выходе сразу, для EA держим дескрипторы процессов игры и,
                // как только все завершились, проверяем список без ожидания 3 с (раз в 0,5 с).
                List<Process> trk = (isEa || isBnet) ? TrackPids(pids, null) : null;
                int needMiss = isEa ? 4 : 3;
                while (true)
                {
                    Thread.Sleep(500);
                    if (StopRequested) { Log("stop requested -> closing game"); CloseGame(dir, self); return 0; }
                    tick++;
                    bool fast = (isEa || isBnet) && (missing > 0 || AllExited(trk));
                    // Список процессов просматриваем раз в 3 секунды (флаг остановки — каждые 0,5 с).
                    if (!fast && (tick % 6) != 0) continue;
                    pids = FindGamePids(dir, self);
                    if (isEa || isBnet) trk = TrackPids(pids, trk);
                    if (pids.Count == 0)
                    {
                        missing++;
                        if (missing >= needMiss) break;
                    }
                    else missing = 0;
                }
                Log("game exited");
                if (egsStartedByUs) CloseEgsIfIdle(dir, self);
                if (gogStartedByUs) CloseGalaxyIfIdle(dir, self);
                if (ubiStartedByUs) CloseUbiIfIdle(dir, self);
                if (eaStartedByUs) CloseEaIfIdle(dir, self);
                // Клиент Battle.net закрывает сторож (отдельный процесс вне дерева Steam), чтобы Steam
                // сразу увидел выход из игры и не ждал 15-25 с.
                return 0;
            }
            catch (Exception ex)
            {
                Log("fatal: " + ex.Message);
                return 4;
            }
        }
    }
}
'@

# Путь к GalaxyClient.exe (реестр, затем стандартные папки). Пустая строка, если Galaxy не найдена.
# Результат кэшируется: функция вызывается при каждой проверке игры лаунчера.
function Get-GogGalaxyClientExe {
    if ($null -ne $script:gogGalaxyClientExeCache) { return [string]$script:gogGalaxyClientExeCache }
    $found = ''
    try {
        $cands = New-Object System.Collections.Generic.List[string]
        $clientDir = Get-RegValueSafe 'HKLM:\SOFTWARE\WOW6432Node\GOG.com\GalaxyClient\paths' 'client'
        if (-not [string]::IsNullOrWhiteSpace($clientDir)) { [void]$cands.Add((Join-Path $clientDir 'GalaxyClient.exe')) }
        foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
            if ([string]::IsNullOrWhiteSpace($base)) { continue }
            [void]$cands.Add((Join-Path $base 'GOG Galaxy\GalaxyClient.exe'))
        }
        foreach ($c in $cands) {
            if (-not [string]::IsNullOrWhiteSpace([string]$c) -and (Test-Path -LiteralPath $c -PathType Leaf)) { $found = [string]$c; break }
        }
    } catch {}
    $script:gogGalaxyClientExeCache = $found
    return $found
}

# Метка запуска игры GOG для обёртки: gog:<gameId>. Пусто, если ID игры не числовой.
function Get-GogLaunchUri ($Entry) {
    try {
        $gid = ([string]$Entry.GameId).Trim()
        if ($gid -notmatch '^\d+$') { return '' }
        return ('gog:' + $gid)
    } catch { return '' }
}

# Ссылка запуска игры Ubisoft Connect: uplay://launch/<installId>/0. installId - имя подраздела
# HKLM\SOFTWARE\WOW6432Node\Ubisoft\Launcher\Installs (он же GameId записи). Пусто, если ID не числовой.

$script:bnetClientExeCache = $null
function Get-BattleNetClientExe {
    if ($null -ne $script:bnetClientExeCache) { return [string]$script:bnetClientExeCache }
    $found = ''
    try {
        $cands = New-Object System.Collections.Generic.List[string]
        foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
            if ([string]::IsNullOrWhiteSpace($base)) { continue }
            [void]$cands.Add((Join-Path $base 'Battle.net\Battle.net.exe'))
            [void]$cands.Add((Join-Path $base 'Battle.net\Battle.net Launcher.exe'))
        }
        try {
            $bu = Find-UninstallEntryByName '^Battle\.net$'
            if ($null -ne $bu -and -not [string]::IsNullOrWhiteSpace($bu.InstallLocation)) {
                $il = $bu.InstallLocation.Trim().Trim('"')
                [void]$cands.Add((Join-Path $il 'Battle.net.exe'))
                [void]$cands.Add((Join-Path $il 'Battle.net Launcher.exe'))
            }
        } catch {}
        foreach ($c in $cands) {
            if (-not [string]::IsNullOrWhiteSpace([string]$c) -and (Test-Path -LiteralPath $c -PathType Leaf)) { $found = [string]$c; break }
        }
    } catch {}
    $script:bnetClientExeCache = $found
    return $found
}

function Get-BattleNetLaunchUri ($Entry) {
    try {
        if (-not (Test-IsLauncherEntry $Entry)) { return '' }
        if ([string]$Entry.Launcher -ne 'battlenet') { return '' }
        $uid = ([string]$Entry.GameId).Trim()
        if ($uid -notmatch '^[A-Za-z0-9_]+$') { return '' }
        return ('bnet:' + $uid)
    } catch { return '' }
}

function Get-UbisoftLaunchUri ($Entry) {
    try {
        $gid = ([string]$Entry.GameId).Trim()
        if ($gid -notmatch '^\d+$') { return '' }
        return ('uplay://launch/' + $gid + '/0')
    } catch { return '' }
}

function Get-EaOfferIdsFromInstallDir ([string]$Dir) {
    try {
        $dir = ([string]$Dir).Trim().Trim('"').TrimEnd('\')
        if ([string]::IsNullOrWhiteSpace($dir)) { return '' }
        $xmlPath = Join-Path $dir '__Installer\installerdata.xml'
        if (-not (Test-Path -LiteralPath $xmlPath -PathType Leaf)) { return '' }
        $raw = ''
        try {
            $fs = New-Object System.IO.FileStream($xmlPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            try {
                $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::UTF8, $true)
                try { $raw = $sr.ReadToEnd() } finally { $sr.Dispose() }
            } finally { $fs.Dispose() }
        } catch {
            $raw = [string](Get-Content -LiteralPath $xmlPath -Raw -ErrorAction Stop)
        }
        if ([string]::IsNullOrWhiteSpace($raw)) { return '' }
        $ids = New-Object System.Collections.Generic.List[string]
        $seen = @{}
        foreach ($m in [regex]::Matches($raw, '(?is)<contentID>\s*([^<]+?)\s*</contentID>')) {
            $id = ([string]$m.Groups[1].Value).Trim()
            if ([string]::IsNullOrWhiteSpace($id)) { continue }
            if ($seen.ContainsKey($id)) { continue }
            $seen[$id] = $true
            [void]$ids.Add($id)
        }
        if ($ids.Count -eq 0) { return '' }
        return [string]::Join(',', $ids.ToArray())
    } catch { return '' }
}

function Get-EaLaunchUri ($Entry) {
    try {
        if (-not (Test-IsLauncherEntry $Entry)) { return '' }
        if ([string]$Entry.Launcher -ne 'ea') { return '' }
        $ids = ([string]$Entry.CatalogId).Trim()
        if ([string]::IsNullOrWhiteSpace($ids)) {
            $ids = Get-EaOfferIdsFromInstallDir ([string]$Entry.Path)
        }
        if ([string]::IsNullOrWhiteSpace($ids)) {
            $gid = ([string]$Entry.GameId).Trim()
            if ($gid -match '^[0-9]+$') { $ids = $gid }
        }
        if ([string]::IsNullOrWhiteSpace($ids)) { return '' }
        return ('origin2://game/launch/?offerIds=' + $ids)
    } catch { return '' }
}

function Get-EpicLaunchUri ($Entry) {
    try {
        $ns = [string]$Entry.CatalogNamespace
        $cid = [string]$Entry.CatalogId
        $app = [string]$Entry.GameId
        if ([string]::IsNullOrWhiteSpace($ns) -or [string]::IsNullOrWhiteSpace($cid) -or [string]::IsNullOrWhiteSpace($app)) { return '' }
        if ($app -notmatch '^[A-Za-z0-9_\-\.]+$') { return '' }
        return ('com.epicgames.launcher://apps/' + [uri]::EscapeDataString($ns) + '%3A' + [uri]::EscapeDataString($cid) + '%3A' + [uri]::EscapeDataString($app) + '?action=launch&silent=true')
    } catch { return '' }
}

# Путь к SCLauncher.exe; при отсутствии (или устаревшей версии) компилирует его.
# Возвращает пустую строку, если создать не удалось.
function Ensure-SCLauncherExe {
    $tmp = ''
    try {
        $dir = Join-Path $global:appDataDir 'launcher'
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $exe = Join-Path $dir 'SCLauncher.exe'
        $verFile = Join-Path $dir 'SCLauncher.ver'
        $curVer = ''
        if (Test-Path -LiteralPath $verFile -PathType Leaf) {
            try { $curVer = ([string](Get-Content -LiteralPath $verFile -Raw)).Trim() } catch {}
        }
        $haveExe = Test-Path -LiteralPath $exe -PathType Leaf
        if ($haveExe -and $curVer -eq $script:scLauncherVersion) { return $exe }

        $tag = [guid]::NewGuid().ToString('N').Substring(0, 8)
        $tmp = Join-Path $dir ('SCLauncher.' + $tag + '.tmp.exe')
        $src = $script:scLauncherSource.Replace('SCLauncherNS', ('SCLauncherNS_' + $tag))
        try {
            Add-Type -TypeDefinition $src -Language CSharp -ReferencedAssemblies @('System.Windows.Forms.dll', 'System.Management.dll', 'System.IO.Compression.dll', 'System.IO.Compression.FileSystem.dll') -OutputAssembly $tmp -OutputType WindowsApplication -ErrorAction Stop
        } catch {
            $detail = [string]$_.Exception.Message
            try {
                if ($_.Exception.InnerException) { $detail += (' | inner: ' + $_.Exception.InnerException.Message) }
            } catch {}
            try {
                $errors = $_.Exception.ErrorRecords
                if ($errors) { foreach ($er in @($errors)) { $detail += (' | ' + [string]$er) } }
            } catch {}
            Write-LauncherLog ('Ensure-SCLauncherExe compile: ' + $detail)
            throw
        }
        if (-not (Test-Path -LiteralPath $tmp -PathType Leaf)) { throw 'компилятор не создал файл' }
        try {
            Move-Item -LiteralPath $tmp -Destination $exe -Force -ErrorAction Stop
            $tmp = ''
            Set-Content -LiteralPath $verFile -Value $script:scLauncherVersion -Encoding ASCII
        } catch {
            # Старый exe может быть занят запущенной игрой — тогда пользуемся им.
            if (-not $haveExe) { throw }
            Write-LauncherLog ('SCLauncher.exe не обновлён (файл занят): ' + $_.Exception.Message)
        }
        return $exe
    } catch {
        try { Write-LauncherLog ('Ensure-SCLauncherExe: ' + $_.Exception.Message) } catch {}
        # Уже собранный SCLauncher.exe лучше, чем полный отказ добавления.
        if ($haveExe) {
            Write-LauncherLog ('Ensure-SCLauncherExe: using existing SCLauncher.exe after compile/update failure')
            return $exe
        }
        return ''
    } finally {
        if ($tmp) { try { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } catch {} }
    }
}

# Параметры запуска для ярлыка с обёрткой (имя игры и папка — в кавычках, без \ на конце).
function Format-SCLauncherArgs ([string]$Uri, [string]$GameDir, [string]$Client = '', [string]$Exe = '') {
    $d = ([string]$GameDir).Trim().Trim('"').TrimEnd('\')
    $r = ('--uri "' + $Uri + '" --dir "' + $d + '"')
    # GOG: путь к GalaxyClient.exe (ссылки запуска у Galaxy нет, обёртка запускает клиент командой).
    if (-not [string]::IsNullOrWhiteSpace($Client)) { $r += (' --client "' + ([string]$Client).Trim().Trim('"') + '"') }
    if (-not [string]::IsNullOrWhiteSpace($Exe)) { $r += (' --exe "' + ([string]$Exe).Trim().Trim('"') + '"') }
    return $r
}

# ---------- Единая логика поля EXE для игр из лаунчеров ----------
# Одни и те же правила для карточки, пакетной классификации и тихого добавления:
#  1. Явный выбор пользователя (кэш выбора / уже сохранённый ярлык) приоритетнее всего.
#  2. Игра, которая запускается через SCLauncher.exe (Epic Games, GOG, Ubisoft Connect): выбор EXE на запуск
#     не влияет (он задаёт только рабочую папку ярлыка), поэтому поле всегда считается
#     определённым, а отсутствие exe в папке не блокирует добавление.
#  3. Если лаунчер сам указал exe (манифест: Epic LaunchExecutable, GOG, Xbox), он
#     предвыбирается как определённый, даже если в папке несколько кандидатов.
#  4. Иначе действуют обычные правила: единственный кандидат, подсказка Steam, иначе — проверка вручную.
function Test-IsLauncherEntry ($Entry) {
    return ($null -ne $Entry -and [string]$Entry.Kind -eq 'launcher')
}

# Запускается ли игра лаунчера через обёртку SCLauncher.exe (Epic: ссылка com.epicgames.launcher://..., GOG: клиент Galaxy,
# Ubisoft: ссылка uplay://launch/...).
function Test-LauncherEntryWrapped ($Entry) {
    if (-not (Test-IsLauncherEntry $Entry)) { return $false }
    switch ([string]$Entry.Launcher) {
        'epic' { return $true }
        # GOG: через Galaxy только если клиент найден и ID игры числовой; иначе прямой exe, как раньше.
        'gog'  { return ((-not [string]::IsNullOrWhiteSpace((Get-GogLaunchUri $Entry))) -and (-not [string]::IsNullOrWhiteSpace((Get-GogGalaxyClientExe)))) }
        # Ubisoft: через Ubisoft Connect (ссылка uplay://), если ID установки числовой; иначе прямой exe, как раньше.
        'ubisoft' { return (-not [string]::IsNullOrWhiteSpace((Get-UbisoftLaunchUri $Entry))) }
        'ea' { return (-not [string]::IsNullOrWhiteSpace((Get-EaLaunchUri $Entry))) }
        'battlenet' { return ((-not [string]::IsNullOrWhiteSpace((Get-BattleNetLaunchUri $Entry))) -and (-not [string]::IsNullOrWhiteSpace((Get-BattleNetClientExe)))) }
        default { return $false }
    }
}

function Get-LauncherLaunchUri ($Entry) {
    if (-not (Test-IsLauncherEntry $Entry)) { return '' }
    switch ([string]$Entry.Launcher) {
        'epic'  { return (Get-EpicLaunchUri $Entry) }
        'gog'   { return (Get-GogLaunchUri $Entry) }
        'ubisoft' { return (Get-UbisoftLaunchUri $Entry) }
        'ea'    { return (Get-EaLaunchUri $Entry) }
        'battlenet' { return (Get-BattleNetLaunchUri $Entry) }
        default { return '' }
    }
}

# План ярлыка для игры лаунчера: SCLauncher.exe + параметры. Ok=$false — причина в Reason
# (ссылку запуска собрать нельзя или SCLauncher.exe не создан). Для игр без обёртки Wrapped=$false.
function Get-LauncherWrapPlan ($Entry) {
    $plan = [PSCustomObject]@{ Wrapped = $false; Ok = $true; Exe = ''; Args = ''; Reason = '' }
    if (-not (Test-LauncherEntryWrapped $Entry)) { return $plan }
    $plan.Wrapped = $true
    $uri = Get-LauncherLaunchUri $Entry
    if ([string]::IsNullOrWhiteSpace($uri)) { $plan.Ok = $false; $plan.Reason = (T 'st_launcher_uri_fail'); return $plan }
    $wrapExe = Ensure-SCLauncherExe
    if ([string]::IsNullOrWhiteSpace($wrapExe)) { $plan.Ok = $false; $plan.Reason = (T 'st_launcher_wrap_fail'); return $plan }
    $wrapDir = [string]$Entry.Path
    if ([string]::IsNullOrWhiteSpace($wrapDir)) { $wrapDir = [string]$Entry.StartDir }
    $plan.Exe = [string]$wrapExe
    if ([string]$Entry.Launcher -eq 'gog') {
        $gx = Get-GogGalaxyClientExe
        if ([string]::IsNullOrWhiteSpace($gx)) { $plan.Ok = $false; $plan.Reason = (T 'st_launcher_uri_fail'); return $plan }
        $plan.Args = Format-SCLauncherArgs $uri $wrapDir $gx
    } elseif ([string]$Entry.Launcher -eq 'battlenet') {
        $bx = Get-BattleNetClientExe
        if ([string]::IsNullOrWhiteSpace($bx)) { $plan.Ok = $false; $plan.Reason = (T 'st_launcher_uri_fail'); return $plan }
        $bexe = ''
        try { $bfi = Get-LauncherManifestExe $Entry; if ($null -ne $bfi) { $bexe = [string]$bfi.FullName } } catch {}
        $plan.Args = Format-SCLauncherArgs $uri $wrapDir $bx $bexe
    } else {
        $plan.Args = Format-SCLauncherArgs $uri $wrapDir
    }
    return $plan
}

# EXE, который лаунчер указал сам (Entry.Exe). Возвращает FileInfo или $null, если exe не задан,
# не существует или лежит вне папки игры.
function Get-LauncherManifestExe ($Entry) {
    if (-not (Test-IsLauncherEntry $Entry)) { return $null }
    $p = ([string]$Entry.Exe).Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    try {
        if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { return $null }
        $f = Get-Item -LiteralPath $p -ErrorAction Stop
        $dir = ([string]$Entry.Path).Trim().TrimEnd('\')
        if ($dir -and -not ([string]$f.FullName).StartsWith($dir + '\', [System.StringComparison]::OrdinalIgnoreCase)) { return $null }
        return $f
    } catch { return $null }
}

# Выбор EXE среди кандидатов (без учёта кэша/ярлыка — их проверяет вызывающий код).
# Index — позиция в $Candidates или -1; Source: 'manifest' | 'single' | 'none'.
function Resolve-LauncherExeChoice ($Entry, $Candidates) {
    $res = [PSCustomObject]@{ Index = -1; File = $null; Source = 'none'; Confident = $false }
    $list = @($Candidates)
    $mf = Get-LauncherManifestExe $Entry
    if ($null -ne $mf) {
        $res.File = $mf; $res.Source = 'manifest'; $res.Confident = $true
        for ($i = 0; $i -lt $list.Count; $i++) {
            try { if ([string]::Equals([string]$list[$i].FullName, [string]$mf.FullName, [System.StringComparison]::OrdinalIgnoreCase)) { $res.Index = $i; break } } catch {}
        }
        return $res
    }
    if ($list.Count -eq 1) { $res.Index = 0; $res.Source = 'single'; $res.Confident = $true }
    return $res
}

# ---------- GOG: только игры, которыми управляет Galaxy ----------
# Ключи в HKLM\...\GOG.com\Games пишет и офлайн-установщик (setup_*.exe), поэтому реестр
# показывает и игры, поставленные без лаунчера. Настоящий список Galaxy лежит в SQLite-базе
# %ProgramData%\GOG.com\Galaxy\storage\galaxy-2.0.db. Для определения
# реально установленных GOG-игр используем InstalledProducts, а путь берём из
# InstalledBaseProducts. Одной InstalledBaseProducts недостаточно: там могут
# оставаться старые записи.
function Initialize-GogGalaxyIndex {
    # Read GOG Galaxy's actual InstalledBaseProducts table through Windows' built-in
    # SQLite engine (winsqlite3.dll). Do NOT infer Galaxy ownership from the GOG
    # registry: offline installers write the same registry keys.
    try {
        if (-not ('SCWinSQLite' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;

public static class SCWinSQLite {
    const int SQLITE_OK = 0;
    const int SQLITE_ROW = 100;
    const int SQLITE_DONE = 101;
    const int SQLITE_OPEN_READONLY = 0x00000001;
    const int SQLITE_OPEN_URI = 0x00000040;

    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern int sqlite3_open_v2(byte[] filename, out IntPtr db, int flags, IntPtr zvfs);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern int sqlite3_close(IntPtr db);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern int sqlite3_prepare_v2(IntPtr db, byte[] sql, int nByte, out IntPtr stmt, IntPtr pzTail);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern int sqlite3_step(IntPtr stmt);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern int sqlite3_finalize(IntPtr stmt);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern IntPtr sqlite3_errmsg(IntPtr db);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern IntPtr sqlite3_column_text(IntPtr stmt, int iCol);
    [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)]
    static extern int sqlite3_column_bytes(IntPtr stmt, int iCol);

    static byte[] U8(string s) {
        if (s == null) return new byte[] { 0 };
        byte[] b = Encoding.UTF8.GetBytes(s);
        byte[] z = new byte[b.Length + 1];
        Buffer.BlockCopy(b, 0, z, 0, b.Length);
        return z;
    }

    static string ColText(IntPtr stmt, int col) {
        IntPtr p = sqlite3_column_text(stmt, col);
        int n = sqlite3_column_bytes(stmt, col);
        if (p == IntPtr.Zero || n <= 0) return "";
        byte[] b = new byte[n];
        Marshal.Copy(p, b, 0, n);
        return Encoding.UTF8.GetString(b);
    }

    public static string[] ReadInstalledProducts(string dbPath) {
        IntPtr db = IntPtr.Zero, stmt = IntPtr.Zero;
        var rows = new System.Collections.Generic.List<string>();
        try {
            int rc = sqlite3_open_v2(U8(dbPath), out db, SQLITE_OPEN_READONLY, IntPtr.Zero);
            if (rc != SQLITE_OK || db == IntPtr.Zero) return rows.ToArray();

            // InstalledProducts/InstalledBaseProducts alone are NOT enough:
            // Galaxy can keep imported/offline installations there. Require the
            // product to also be present in Galaxy's current library via
            // ProductsToReleaseKeys -> LibraryReleases. This excludes offline/
            // pirated installations that are not actually in the user's Galaxy library.
            string sql = "SELECT DISTINCT ibp.productId, ibp.installationPath, " +
                         "wc.userId, wcr.filename " +
                         "FROM InstalledBaseProducts ibp " +
                         "INNER JOIN InstalledProducts ip ON ip.productId = ibp.productId " +
                         "INNER JOIN ProductsToReleaseKeys prk ON prk.gogId = ibp.productId " +
                         "INNER JOIN LibraryReleases lr ON lr.releaseKey = prk.releaseKey " +
                         "LEFT JOIN WebCache wc ON wc.releaseKey = prk.releaseKey " +
                         "LEFT JOIN WebCacheResources wcr ON wcr.webCacheId = wc.id " +
                         "AND wcr.webCacheResourceTypeId = 3";
            rc = sqlite3_prepare_v2(db, U8(sql), -1, out stmt, IntPtr.Zero);
            if (rc != SQLITE_OK || stmt == IntPtr.Zero) return rows.ToArray();

            while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
                string id = ColText(stmt, 0).Trim();
                string path = ColText(stmt, 1).Trim();
                string userId = ColText(stmt, 2).Trim();
                string filename = ColText(stmt, 3).Trim();
                if (!String.IsNullOrWhiteSpace(id) && !String.IsNullOrWhiteSpace(path))
                    rows.Add(id + "\t" + path + "\t" + userId + "\t" + filename);
            }
            return rows.ToArray();
        } catch { return rows.ToArray(); }
        finally {
            if (stmt != IntPtr.Zero) { try { sqlite3_finalize(stmt); } catch {} }
            if (db != IntPtr.Zero) { try { sqlite3_close(db); } catch {} }
        }
    }
}
'@ -Language CSharp
        }

        $db = Join-Path ([string]$env:ProgramData) 'GOG.com\Galaxy\storage\galaxy-2.0.db'
        if (-not (Test-Path -LiteralPath $db -PathType Leaf)) {
            Write-LauncherLog 'gog: Galaxy DB not found'
            return $false
        }

        $global:GogGalaxyInstalledIndex = @{}
        foreach ($row in @([SCWinSQLite]::ReadInstalledProducts($db))) {
            $parts = $row -split "`t", 4
            if ($parts.Count -lt 2) { continue }
            $id = [string]$parts[0]
            $path = ([string]$parts[1]).Trim().TrimEnd('\','/')
            $userId = if ($parts.Count -ge 3) { [string]$parts[2] } else { '' }
            $filename = if ($parts.Count -ge 4) { [string]$parts[3] } else { '' }
            if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($path)) { continue }
            if (-not $global:GogGalaxyInstalledIndex.ContainsKey($id)) { $global:GogGalaxyInstalledIndex[$id] = @{} }
            $key = (Get-NormalizedGamePathKey $path)
            $global:GogGalaxyInstalledIndex[$id][$key] = [PSCustomObject]@{ Path=$path; UserId=$userId; CoverFile=$filename }
        }
        Write-LauncherLog ('gog: InstalledProducts + InstalledBaseProducts + LibraryReleases loaded: ' + $global:GogGalaxyInstalledIndex.Count)
        return ($global:GogGalaxyInstalledIndex.Count -gt 0)
    } catch {
        Write-LauncherLog ('gog: Galaxy DB index error: ' + $_.Exception.Message)
        return $false
    }
}

function Test-GogPathInGalaxy ([string]$Dir, [string]$GameId) {
    try {
        $id = ([string]$GameId).Trim()
        $path = ([string]$Dir).Trim().TrimEnd('\','/')
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($path)) { return $false }
        if ($null -eq $global:GogGalaxyInstalledIndex) { return $null }
        if (-not $global:GogGalaxyInstalledIndex.ContainsKey($id)) { return $null }
        $key = (Get-NormalizedGamePathKey $path)
        if (-not $global:GogGalaxyInstalledIndex[$id].ContainsKey($key)) { return $null }
        return $global:GogGalaxyInstalledIndex[$id][$key]
    } catch { return $null }
}

# Returns the exact vertical cover file that GOG Galaxy associates with the game.
# Galaxy stores the filename in WebCacheResources and the actual file under:
# %ProgramData%\GOG.com\Galaxy\webcache\<userId>\gog\<productId>\
function Get-GogLocalCoverFile ([string]$Dir, [string]$GameId) {
    try {
        $info = Test-GogPathInGalaxy $Dir $GameId
        if ($null -eq $info) { return '' }
        $userId = [string]$info.UserId
        $fn = [string]$info.CoverFile
        if ([string]::IsNullOrWhiteSpace($userId) -or [string]::IsNullOrWhiteSpace($fn)) { return '' }
        if ($fn -notmatch '_glx_vertical_cover\.webp$') { return '' }
        $root = Join-Path ([string]$env:ProgramData) 'GOG.com\Galaxy\webcache'
        $p = Join-Path (Join-Path (Join-Path $root $userId) 'gog') ([string]$GameId)
        $file = Join-Path $p $fn
        if (Test-Path -LiteralPath $file -PathType Leaf) { return $file }
    } catch {}
    return ''
}

# Decode GOG Galaxy's WebP through Windows Imaging Component and save JPEG for GDI+.
function Convert-GogWebpToJpg ([string]$Source, [string]$Target) {
    try {
        if ([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source -PathType Leaf)) { return $false }
        Add-Type -AssemblyName PresentationCore,WindowsBase -ErrorAction Stop
        $uri = New-Object System.Uri($Source)
        $decoder = [System.Windows.Media.Imaging.BitmapDecoder]::Create($uri, [System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat, [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
        if ($null -eq $decoder -or $decoder.Frames.Count -eq 0) { return $false }
        $encoder = New-Object System.Windows.Media.Imaging.JpegBitmapEncoder
        $encoder.QualityLevel = 95
        $encoder.Frames.Add($decoder.Frames[0])
        $fs = [System.IO.File]::Open($Target, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try { $encoder.Save($fs) } finally { $fs.Dispose() }
        return (Test-LauncherCoverFile $Target $true)
    } catch {
        Write-LauncherLog ('gog local webp decode failed: ' + $_.Exception.Message)
        try { Remove-Item -LiteralPath $Target -Force -ErrorAction SilentlyContinue } catch {}
        return $false
    }
}

function Get-GogLauncherSource ($SteamShortcuts) {
    $exes = New-Object System.Collections.Generic.List[string]
    $clientDir = Get-RegValueSafe 'HKLM:\SOFTWARE\WOW6432Node\GOG.com\GalaxyClient\paths' 'client'
    if (-not [string]::IsNullOrWhiteSpace($clientDir)) { [void]$exes.Add((Join-Path $clientDir 'GalaxyClient.exe')) }
    foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        [void]$exes.Add((Join-Path $base 'GOG Galaxy\GalaxyClient.exe'))
    }

    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $galaxyDbReady = Initialize-GogGalaxyIndex
    $galaxyInstalled = $false
    foreach ($c in $exes) { if (-not [string]::IsNullOrWhiteSpace([string]$c) -and (Test-Path -LiteralPath $c -PathType Leaf)) { $galaxyInstalled = $true; break } }
    foreach ($k in @(Get-RegSubKeysSafe 'HKLM:\SOFTWARE\WOW6432Node\GOG.com\Games')) {
        try {
            # DLC в реестре GOG — отдельные записи с непустым dependsOn.
            if (-not [string]::IsNullOrWhiteSpace([string]$k.GetValue('dependsOn'))) { continue }
            $dir = [string]$k.GetValue('path')
            if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
            $name = [string]$k.GetValue('gameName')
            if ([string]::IsNullOrWhiteSpace($name)) { $name = Split-Path -Leaf ($dir.TrimEnd('\', '/')) }
            $gid = [string]$k.GetValue('gameID')
            if ([string]::IsNullOrWhiteSpace($gid)) { $gid = [string]$k.PSChildName }
            # Только игры Galaxy. Если база доступна, одновременно требуем путь и
            # product ID в одной области базы — старые записи/пиратские установки
            # из одного лишь реестра не проходят.
            $galaxyInfo = $null
            if ($galaxyDbReady) {
                $galaxyInfo = Test-GogPathInGalaxy $dir $gid
                if ($null -eq $galaxyInfo) { Write-LauncherLog ('gog skip (not in Galaxy DB/current product): ' + $dir); continue }
            } elseif (-not $galaxyInstalled) { continue }
            $exe = [string]$k.GetValue('exe')
            if (-not [string]::IsNullOrWhiteSpace($exe) -and -not (Test-Path -LiteralPath $exe -PathType Leaf)) { $exe = '' }
            $dupKey = (Get-NormalizedGamePathKey $dir)
            if ($seen.ContainsKey($dupKey)) { continue }
            $seen[$dupKey] = $true
            $entry = New-LauncherGameEntry 'gog' 'GOG' $gid $name $dir $exe $SteamShortcuts
            try {
                if ($null -ne $galaxyInfo) {
                    $entry | Add-Member -NotePropertyName GogWebCacheUserId -NotePropertyValue ([string]$galaxyInfo.UserId) -Force
                    $entry | Add-Member -NotePropertyName GogWebCacheCoverFile -NotePropertyValue ([string]$galaxyInfo.CoverFile) -Force
                }
            } catch {}
            [void]$games.Add($entry)
        } catch {}
    }
    return (New-LauncherSourceObject 'gog' 'GOG' 'G' @(134, 50, 212) @($exes.ToArray()) @($games.ToArray()))
}

function Get-UbisoftLauncherSource ($SteamShortcuts) {
    $exes = New-Object System.Collections.Generic.List[string]
    $ubiDir = Get-RegValueSafe 'HKLM:\SOFTWARE\WOW6432Node\Ubisoft\Launcher' 'InstallDir'
    if (-not [string]::IsNullOrWhiteSpace($ubiDir)) {
        $ubiDir = $ubiDir.Replace('/', '\')
        foreach ($n in @('UbisoftConnect.exe', 'upc.exe', 'UbisoftGameLauncher.exe')) { [void]$exes.Add((Join-Path $ubiDir $n)) }
    }
    foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        [void]$exes.Add((Join-Path $base 'Ubisoft\Ubisoft Game Launcher\UbisoftConnect.exe'))
        [void]$exes.Add((Join-Path $base 'Ubisoft\Ubisoft Game Launcher\upc.exe'))
    }

    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($k in @(Get-RegSubKeysSafe 'HKLM:\SOFTWARE\WOW6432Node\Ubisoft\Launcher\Installs')) {
        try {
            $dir = ([string]$k.GetValue('InstallDir')).Replace('/', '\').TrimEnd('\')
            if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
            # В реестре Ubisoft нет названия игры — берём имя папки установки.
            $name = Split-Path -Leaf $dir
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $gid = [string]$k.PSChildName
            # Если в configurations есть человекочитаемое имя — берём его вместо имени папки.
            try {
                $idx = Initialize-UbisoftConfigIndex
                if ($gid -and $idx.ById.ContainsKey($gid) -and -not [string]::IsNullOrWhiteSpace([string]$idx.ById[$gid].Name)) {
                    $name = [string]$idx.ById[$gid].Name
                } else {
                    $nk = Normalize-UbiNameKey $name
                    if ($nk -and $idx.ByName.ContainsKey($nk) -and -not [string]::IsNullOrWhiteSpace([string]$idx.ByName[$nk].Name)) {
                        $name = [string]$idx.ByName[$nk].Name
                    }
                }
            } catch {}
            $dupKey = (Get-NormalizedGamePathKey $dir)
            if ($seen.ContainsKey($dupKey)) { continue }
            $seen[$dupKey] = $true
            [void]$games.Add((New-LauncherGameEntry 'ubisoft' 'Ubisoft' $gid $name $dir '' $SteamShortcuts))
        } catch {}
    }
    return (New-LauncherSourceObject 'ubisoft' 'Ubisoft' 'U' @(0, 112, 255) @($exes.ToArray()) @($games.ToArray()))
}

function Get-EaLauncherSource ($SteamShortcuts) {
    $exes = New-Object System.Collections.Generic.List[string]
    foreach ($base in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        [void]$exes.Add((Join-Path $base 'Electronic Arts\EA Desktop\EA Desktop\EADesktop.exe'))
        [void]$exes.Add((Join-Path $base 'Origin\Origin.exe'))
    }

    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($root in @('HKLM:\SOFTWARE\WOW6432Node\EA Games', 'HKLM:\SOFTWARE\EA Games')) {
        foreach ($k in @(Get-RegSubKeysSafe $root)) {
            try {
                $dir = ([string]$k.GetValue('Install Dir')).Replace('/', '\').TrimEnd('\')
                if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
                $name = [string]$k.GetValue('DisplayName')
                if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$k.PSChildName }
                $dupKey = (Get-NormalizedGamePathKey $dir)
                if ($seen.ContainsKey($dupKey)) { continue }
                $seen[$dupKey] = $true
                $offerIds = Get-EaOfferIdsFromInstallDir $dir
                [void]$games.Add((New-LauncherGameEntry 'ea' 'EA app' ([string]$k.PSChildName) $name $dir '' $SteamShortcuts $offerIds))
            } catch {}
        }
    }
    # EA app (бывш. EA Desktop) не пишет игры в HKLM\SOFTWARE\EA Games. Зато каждая её игра
    # есть в «Установка и удаление программ»: там InstallLocation и деинсталлятор
    # Common Files\EAInstaller\<игра>\Cleanup.exe — по нему отличаем игры EA app
    # от чужих записей (Steam и др. тоже пишут туда свои игры).
    $eaViaUninstall = 0
    foreach ($ur in @('HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall')) {
        foreach ($k in @(Get-RegSubKeysSafe $ur)) {
            try {
                if ([string]$k.GetValue('UninstallString') -notmatch 'EAInstaller') { continue }
                $dir = ([string]$k.GetValue('InstallLocation')).Replace('/', '\').TrimEnd('\')
                if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
                $name = ([string]$k.GetValue('DisplayName')) -replace '[\u2122\u00AE\u00A9]', ''
                $name = $name.Trim()
                if ([string]::IsNullOrWhiteSpace($name)) { $name = Split-Path -Leaf $dir }
                $dupKey = (Get-NormalizedGamePathKey $dir)
                if ($seen.ContainsKey($dupKey)) { continue }
                $seen[$dupKey] = $true
                $offerIds = Get-EaOfferIdsFromInstallDir $dir
                [void]$games.Add((New-LauncherGameEntry 'ea' 'EA app' ([string]$k.PSChildName) $name $dir '' $SteamShortcuts $offerIds))
                $eaViaUninstall++
            } catch {}
        }
    }
    Write-LauncherLog ('EA games via Uninstall keys: ' + $eaViaUninstall)
    return (New-LauncherSourceObject 'ea' 'EA app' 'EA' @(230, 60, 60) @($exes.ToArray()) @($games.ToArray()))
}

# ---------- Battle.net ----------
# Игры Blizzard пишут себя в «Установка и удаление программ»: UninstallString ведёт на
# ...\Battle.net\Agent\Blizzard Uninstaller.exe --uid=<код продукта> --displayname="...",
# InstallLocation — папка игры. По этому признаку отличаем их от чужих записей.
# Сам Battle.net (запись DisplayName = "Battle.net") в список игр не попадает.
# Exe игры Blizzard по коду продукта (тот же список, что в SCLauncher). Ищется рекурсивно в папке игры,
# 64-битный (x86_64) предпочтительнее. Пусто, если код неизвестен или файл не найден.
function Get-BattleNetGameExe ([string]$Uid, [string]$Dir) {
    try {
        $name = ''
        switch (([string]$Uid).ToLowerInvariant()) {
            { $_ -in @('hs_beta', 'hs', 'wtcg') } { $name = 'Hearthstone.exe' }
            's1'   { $name = 'StarCraft.exe' }
            's2'   { $name = 'SC2_x64.exe' }
            'd3'   { $name = 'Diablo III64.exe' }
            'pro'  { $name = 'Overwatch.exe' }
            'fen'  { $name = 'Diablo IV.exe' }
            'w3'   { $name = 'Warcraft III.exe' }
            'wow'  { $name = 'Wow.exe' }
            'hero' { $name = 'HeroesOfTheStorm_x64.exe' }
        }
        if ([string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($Dir)) { return '' }
        $found = @(Get-ChildItem -LiteralPath $Dir -Filter $name -File -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName -notmatch '\\Support\\' })
        if ($found.Count -eq 0) { return '' }
        $best = $found | Sort-Object @{Expression={ if ($_.FullName -match 'x86_64') { 0 } else { 1 } }}, @{Expression={ $_.FullName.Length }} | Select-Object -First 1
        return [string]$best.FullName
    } catch { return '' }
}

function Get-BattleNetLauncherSource ($SteamShortcuts) {
    $exes = New-Object System.Collections.Generic.List[string]
    foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        [void]$exes.Add((Join-Path $base 'Battle.net\Battle.net Launcher.exe'))
        [void]$exes.Add((Join-Path $base 'Battle.net\Battle.net.exe'))
    }
    try {
        $bu = Find-UninstallEntryByName '^Battle\.net$'
        if ($null -ne $bu) {
            if (-not [string]::IsNullOrWhiteSpace($bu.InstallLocation)) {
                [void]$exes.Add((Join-Path $bu.InstallLocation.Trim().Trim('"') 'Battle.net Launcher.exe'))
            }
            $di = ([string]$bu.DisplayIcon).Trim().Trim('"') -replace ',\s*-?\d+$', ''
            if ($di) { [void]$exes.Add($di) }
        }
    } catch {}

    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($ur in @('HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall')) {
        foreach ($k in @(Get-RegSubKeysSafe $ur)) {
            try {
                $us = [string]$k.GetValue('UninstallString')
                if ($us -notmatch 'Blizzard Uninstaller') { continue }
                $dir = ([string]$k.GetValue('InstallLocation')).Trim().Trim('"').Replace('/', '\').TrimEnd('\')
                if ([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
                $name = (([string]$k.GetValue('DisplayName')) -replace '[\u2122\u00AE\u00A9]', '').Trim()
                if ([string]::IsNullOrWhiteSpace($name)) { $name = Split-Path -Leaf $dir }
                if ($name -match '^(?i)Battle\.net$') { continue }
                $uid = ''
                $mu = [regex]::Match($us, '--uid=([^\s"]+)')
                if ($mu.Success) { $uid = $mu.Groups[1].Value }
                if ([string]::IsNullOrWhiteSpace($uid)) { $uid = [string]$k.PSChildName }
                $dupKey = (Get-NormalizedGamePathKey $dir)
                if ($seen.ContainsKey($dupKey)) { continue }
                $seen[$dupKey] = $true
                $gexe = Get-BattleNetGameExe $uid $dir
                [void]$games.Add((New-LauncherGameEntry 'battlenet' 'Battle.net' $uid $name $dir $gexe $SteamShortcuts))
            } catch {}
        }
    }
    Write-LauncherLog ('Battle.net games via Uninstall keys: ' + $games.Count)
    return (New-LauncherSourceObject 'battlenet' 'Battle.net' 'B' @(0, 174, 255) @($exes.ToArray()) @($games.ToArray()))
}

# ---------- Xbox (приложение Xbox для ПК / Game Pass / Microsoft Store) ----------
# Игры ставятся в <диск>:\XboxGames\<Игра>\Content. Библиотечные папки помечены файлом
# <диск>:\.GamingRoot: заголовок "RGBX", 4 байта версии и путь папки в UTF-16.
# Сведения об игре — в Content\MicrosoftGame.Config (название, exe, логотипы).
function Get-XboxGamesRoots {
    $roots = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    try {
        foreach ($d in [System.IO.DriveInfo]::GetDrives()) {
            try {
                if (-not $d.IsReady) { continue }
                if ($d.DriveType -ne [System.IO.DriveType]::Fixed -and $d.DriveType -ne [System.IO.DriveType]::Removable) { continue }
                $rootDir = [string]$d.RootDirectory.FullName
                $rel = ''
                $gr = Join-Path $rootDir '.GamingRoot'
                if ([System.IO.File]::Exists($gr)) {
                    try {
                        $b = [System.IO.File]::ReadAllBytes($gr)
                        if ($b.Length -gt 10) {
                            $rel = ([System.Text.Encoding]::Unicode.GetString($b, 8, $b.Length - 8)).Trim([char]0).Trim()
                        }
                    } catch {}
                    Write-LauncherLog ('xbox .GamingRoot on ' + $rootDir + ' -> [' + $rel + ']')
                }
                $cands = New-Object System.Collections.Generic.List[string]
                if ($rel) { [void]$cands.Add((Join-Path $rootDir ($rel.TrimStart([char[]]@('\', '/'))))) }
                [void]$cands.Add((Join-Path $rootDir 'XboxGames'))
                foreach ($c in $cands) {
                    $k = ([string]$c).TrimEnd('\').ToLowerInvariant()
                    if ($seen.ContainsKey($k)) { continue }
                    if (Test-Path -LiteralPath $c -PathType Container) {
                        $seen[$k] = $true
                        [void]$roots.Add([string]$c)
                    }
                }
            } catch {}
        }
    } catch { Write-LauncherLog ('xbox roots error: ' + $_.Exception.Message) }
    return @($roots.ToArray())
}

# Читает MicrosoftGame.Config из папки Content. $null — если файла нет или он не разбирается.
function Get-XboxGameConfig ([string]$ContentDir) {
    try {
        $cfg = Join-Path $ContentDir 'MicrosoftGame.Config'
        if (-not [System.IO.File]::Exists($cfg)) { return $null }
        $doc = New-Object System.Xml.XmlDocument
        $doc.Load($cfg)
        $g = $doc.DocumentElement
        if ($null -eq $g) { return $null }
        $sv  = $g.SelectSingleNode('ShellVisuals')
        $idn = $g.SelectSingleNode('Identity')
        $sid = $g.SelectSingleNode('StoreId')
        $exeName = ''
        $exeNames = New-Object System.Collections.Generic.List[string]
        $exeNodes = @($g.SelectNodes('ExecutableList/Executable'))
        foreach ($en in $exeNodes) {
            $nm = [string]$en.GetAttribute('Name')
            if ([string]::IsNullOrWhiteSpace($nm)) { continue }
            # Список всех exe из манифеста: PC/Desktop — в начале, остальные — следом.
            if ([string]$en.GetAttribute('TargetDeviceFamily') -match '(?i)PC|Desktop') { $exeNames.Insert(0, $nm) } else { [void]$exeNames.Add($nm) }
            if ([string]::IsNullOrWhiteSpace($exeName)) { $exeName = $nm }
            if ([string]$en.GetAttribute('TargetDeviceFamily') -match '(?i)PC|Desktop') { $exeName = $nm }
        }
        $attr = {
            param($node, [string]$a)
            if ($null -eq $node) { return '' }
            return [string]$node.GetAttribute($a)
        }
        return [PSCustomObject]@{
            DisplayName = (& $attr $sv 'DefaultDisplayName')
            PackageName = (& $attr $idn 'Name')
            StoreId     = $(if ($null -ne $sid) { [string]$sid.InnerText } else { '' })
            ExeName     = $exeName
            ExeNames    = @($exeNames.ToArray())
            Logo480     = (& $attr $sv 'Square480x480Logo')
            Logo150     = (& $attr $sv 'Square150x150Logo')
            StoreLogo   = (& $attr $sv 'StoreLogo')
        }
    } catch {
        Write-LauncherLog ('xbox config error (' + $ContentDir + '): ' + $_.Exception.Message)
        return $null
    }
}

# Пакеты, зарегистрированные в Windows для текущего пользователя (Магазин / приложение Xbox / Game Pass).
# Ключ раздела — полное имя пакета, значение PackageRootFolder — папка, где он установлен.
# Игра, скопированная в папку вручную (без установки через Магазин), в реестре не значится.
function Get-XboxRegisteredPackageRoots {
    $roots = @{}
    try {
        $base = 'HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\Repository\Packages'
        foreach ($k in @(Get-RegSubKeysSafe $base)) {
            try {
                $r = ([string]$k.GetValue('PackageRootFolder')).Trim().Trim('"').Replace('/', '\').TrimEnd('\')
                $full = [string]$k.PSChildName
                if ($r) { $roots[(Get-NormalizedGamePathKey $r)] = $full }
                # Запасной признак — имя пакета (часть до первого "_"): путь в реестре бывает не тем, что на диске.
                $nm = ($full -split '_')[0].ToLowerInvariant()
                if ($nm) { $roots['name|' + $nm] = $full }
                if ($r -and $r -notmatch '(?i)\\(WindowsApps|SystemApps|ImmersiveControlPanel)(\\|$)') { Write-LauncherLog ('  xbox pkg outside system dirs: ' + $full + ' -> ' + $r) }
            } catch {}
        }
    } catch { Write-LauncherLog ('xbox registry packages error: ' + $_.Exception.Message) }
    Write-LauncherLog ('xbox registered packages: ' + $roots.Count)
    return $roots
}

# Игра считается установленной, если корень одного из пакетов совпадает с её папкой Content
# (или папкой игры) либо лежит внутри неё.
function Test-XboxPackageRegistered ([string]$ContentDir, [string]$GameDir, $Roots, [string]$PackageName = '') {
    if ($PackageName) {
        $nk = 'name|' + $PackageName.ToLowerInvariant()
        if ($Roots.ContainsKey($nk)) { return $Roots[$nk] }
    }
    foreach ($d in @($ContentDir, $GameDir)) {
        $dk = Get-NormalizedGamePathKey $d
        if (-not $dk) { continue }
        if ($Roots.ContainsKey($dk)) { return $Roots[$dk] }
        $pre = $dk + '\'
        foreach ($rk in @($Roots.Keys)) {
            if (([string]$rk).StartsWith($pre)) { return $Roots[$rk] }
        }
    }
    return $null
}

function Get-XboxLauncherSource ($SteamShortcuts) {
    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $regRoots = Get-XboxRegisteredPackageRoots
    foreach ($root in @(Get-XboxGamesRoots)) {
        $gameDirs = @()
        try { $gameDirs = @(Get-ChildItem -LiteralPath $root -Directory -ErrorAction Stop) } catch { Write-LauncherLog ('xbox list ' + $root + ': ' + $_.Exception.Message) }
        foreach ($gd in $gameDirs) {
            try {
                $content = Join-Path $gd.FullName 'Content'
                if (-not (Test-Path -LiteralPath $content -PathType Container)) { $content = $gd.FullName }
                $cfg = Get-XboxGameConfig $content
                if ($null -eq $cfg) { continue }
                # Только игры, установленные через Магазин/приложение Xbox. Если реестр пакетов
                # прочитать не удалось (список пуст), фильтр не применяем, чтобы не потерять всё.
                if ($regRoots.Count -gt 0) {
                    $pkgFull = Test-XboxPackageRegistered $content ([string]$gd.FullName) $regRoots ([string]$cfg.PackageName)
                    if ($null -eq $pkgFull) { Write-LauncherLog ('xbox skip (not registered as installed package): ' + $content + ' [identity=' + [string]$cfg.PackageName + ']'); continue }
                }
                $dupKey = (Get-NormalizedGamePathKey $content)
                if ($seen.ContainsKey($dupKey)) { continue }
                $seen[$dupKey] = $true
                $name = ([string]$cfg.DisplayName -replace '[\u2122\u00AE\u00A9]', '').Trim()
                # Название бывает ссылкой на ресурс (ms-resource:...) — тогда берём имя папки игры.
                if ([string]::IsNullOrWhiteSpace($name) -or $name -match '^(?i)ms-resource:') { $name = [string]$gd.Name }
                # Настоящий exe игры приоритетнее gamelaunchhelper.exe: напрямую запускать
                # helper нельзя — он лишь передаёт запуск приложению Xbox/Gaming Services.
                # 1) exe из манифеста (кроме helper), 2) самый крупный exe в корне папки
                # (без служебных), 3) helper — только если больше ничего нет.
                $exe = ''
                $helper = Join-Path $content 'gamelaunchhelper.exe'
                foreach ($en in @($cfg.ExeNames)) {
                    if ([string]::IsNullOrWhiteSpace([string]$en) -or [string]$en -match '(?i)^gamelaunchhelper\.exe$') { continue }
                    $cand = Join-Path $content ([string]$en)
                    if ([System.IO.File]::Exists($cand)) { $exe = $cand; break }
                }
                if ([string]::IsNullOrWhiteSpace($exe)) {
                    try {
                        $big = @(Get-ChildItem -LiteralPath $content -Filter '*.exe' -File -ErrorAction Stop |
                            Where-Object { $_.Name -notmatch '(?i)^gamelaunchhelper\.exe$|crash|redist|setup|unins|vcredist|dxsetup|easyanticheat|eac|cef|webview' } |
                            Sort-Object Length -Descending)
                        if ($big.Count -gt 0) { $exe = [string]$big[0].FullName }
                    } catch {}
                }
                if ([string]::IsNullOrWhiteSpace($exe) -and [System.IO.File]::Exists($helper)) { $exe = $helper }
                $gid = [string]$cfg.PackageName
                if ([string]::IsNullOrWhiteSpace($gid)) { $gid = [string]$gd.Name }
                [void]$games.Add((New-LauncherGameEntry 'xbox' 'Xbox' $gid $name $content $exe $SteamShortcuts ([string]$cfg.StoreId)))
            } catch { Write-LauncherLog ('xbox game ' + [string]$gd.Name + ': ' + $_.Exception.Message) }
        }
    }
    Write-LauncherLog ('Xbox games found: ' + $games.Count)
    # Собственного exe у приложения Xbox нет (лежит в WindowsApps), поэтому значок — буква X;
    # вкладка появляется только если найдена хотя бы одна игра.
    return (New-LauncherSourceObject 'xbox' 'Xbox' 'X' @(16, 124, 16) @() @($games.ToArray()))
}

# Официальный постер игры из каталога Microsoft Store (вертикальный 2:3) по StoreId из MicrosoftGame.Config.
function Get-XboxCoverUrls ($Entry) {
    $out = New-Object System.Collections.Generic.List[string]
    try {
        $sid = ([string]$Entry.CatalogId).Trim()
        if ($sid -notmatch '^[0-9A-Za-z]{12}$') {
            Write-LauncherLog ('xbox cover [' + [string]$Entry.Name + ']: no StoreId in MicrosoftGame.Config')
            return @()
        }
        $blk = { param($u) try { Invoke-RestMethod -Uri $u -TimeoutSec 10 -UserAgent 'Mozilla/5.0' -ErrorAction Stop } catch { $null } }
        $r = Invoke-BackgroundJsonRequest $blk @('https://displaycatalog.mp.microsoft.com/v7.0/products?bigIds=' + $sid + '&market=US&languages=en-US') 14
        if ($null -eq $r) { Write-LauncherLog ('xbox cover [' + [string]$Entry.Name + ']: catalog request failed'); return @() }
        $imgs = @()
        try { $imgs = @($r.Products[0].LocalizedProperties[0].Images) } catch {}
        $posters = @($imgs | Where-Object { [string]$_.ImagePurpose -eq 'Poster' -and [string]$_.Uri } |
            Sort-Object @{ Expression = { $h = 0; try { $h = [int]$_.Height } catch {}; -$h } })
        foreach ($im in $posters) {
            $u = [string]$im.Uri
            if ($u.StartsWith('//')) { $u = 'https:' + $u }
            [void]$out.Add($u)
        }
        Write-LauncherLog ('xbox cover [' + [string]$Entry.Name + ']: store posters=' + $out.Count)
    } catch { Write-LauncherLog ('xbox cover urls: ' + $_.Exception.Message) }
    return @($out.ToArray())
}

# Запасная обложка Xbox-игры: у неё есть только квадратные логотипы (вертикальной капсулы
# в пакете нет), поэтому логотип ставится по центру на тёмно-зелёный вертикальный фон 600x900.
# Используется, только если SteamGridDB ничего подходящего не нашла.
function Get-XboxLocalCover ($Entry, [string]$TargetPath) {
    try {
        $content = [string]$Entry.Path
        $cfg = Get-XboxGameConfig $content
        if ($null -eq $cfg) { return $false }
        $logoFile = ''
        foreach ($rel in @([string]$cfg.Logo480, [string]$cfg.Logo150, [string]$cfg.StoreLogo)) {
            if ([string]::IsNullOrWhiteSpace($rel)) { continue }
            $p = Join-Path $content ($rel -replace '/', '\')
            if (-not [System.IO.File]::Exists($p)) {
                # Манифест ссылается на "Logo.png", а на диске лежит "Logo.scale-200.png".
                $dir = Split-Path -Parent $p
                if (Test-Path -LiteralPath $dir -PathType Container) {
                    $stem = [System.IO.Path]::GetFileNameWithoutExtension($p)
                    $ext = [System.IO.Path]::GetExtension($p)
                    $m = Get-ChildItem -LiteralPath $dir -Filter ($stem + '*' + $ext) -File -ErrorAction SilentlyContinue |
                        Sort-Object Length -Descending | Select-Object -First 1
                    if ($null -ne $m) { $p = $m.FullName }
                }
            }
            if ([System.IO.File]::Exists($p)) { $logoFile = $p; break }
        }
        if (-not $logoFile) { Write-LauncherLog ('xbox cover [' + [string]$Entry.Name + ']: no logo file in package'); return $false }
        $bytes = [System.IO.File]::ReadAllBytes($logoFile)
        $ms = New-Object System.IO.MemoryStream(, $bytes)
        $src = $null; $bmp = $null; $g = $null; $br = $null
        try {
            $src = [System.Drawing.Image]::FromStream($ms)
            if ($src.Width -lt 80 -or $src.Height -lt 80) { return $false }
            $W = 600; $H = 900
            $bmp = New-Object System.Drawing.Bitmap($W, $H)
            $g = [System.Drawing.Graphics]::FromImage($bmp)
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $rect = New-Object System.Drawing.Rectangle(0, 0, $W, $H)
            $br = New-Object System.Drawing.Drawing2D.LinearGradientBrush($rect, [System.Drawing.Color]::FromArgb(24, 92, 24), [System.Drawing.Color]::FromArgb(8, 18, 8), [single]90)
            $g.FillRectangle($br, $rect)
            $side = 440.0
            $scale = [Math]::Min($side / [double]$src.Width, $side / [double]$src.Height)
            $dw = [single]($src.Width * $scale); $dh = [single]($src.Height * $scale)
            $g.DrawImage($src, [single](($W - $dw) / 2), [single](($H - $dh) / 2), $dw, $dh)
            $bmp.Save($TargetPath, [System.Drawing.Imaging.ImageFormat]::Jpeg)
        } finally {
            if ($null -ne $br) { $br.Dispose() }
            if ($null -ne $g) { $g.Dispose() }
            if ($null -ne $bmp) { $bmp.Dispose() }
            if ($null -ne $src) { $src.Dispose() }
            $ms.Dispose()
        }
        if (Test-LauncherCoverFile $TargetPath $false) {
            Write-LauncherLog ('xbox cover [' + [string]$Entry.Name + ']: placeholder from ' + $logoFile)
            return $true
        }
        return $false
    } catch {
        Write-LauncherLog ('xbox local cover error: ' + $_.Exception.Message)
        return $false
    }
}

# Диагностика обнаружения лаунчеров (запись в файл отключена)
# ---- ЗАМЕРЫ ВРЕМЕНИ ОТКРЫТИЯ БИБЛИОТЕКИ (временный код) ----
$script:scTmSw = [System.Diagnostics.Stopwatch]::StartNew()
$script:scTmLast = 0
function Write-Tm ([string]$Label, [switch]$Reset) {
    try {
        $now = [int]$script:scTmSw.ElapsedMilliseconds
        if ($Reset) { $script:scTmLast = $now }
        $delta = $now - $script:scTmLast
        $script:scTmLast = $now
        # Запись замеров в файл в папке temp отключена.
    } catch {}
}

$script:tmA = @{}
function Get-TmNow { return [double]$script:scTmSw.Elapsed.TotalMilliseconds }
function Add-TmA ([string]$k, [double]$v) {
    try { if (-not $script:tmA.ContainsKey($k)) { $script:tmA[$k] = 0.0 }; $script:tmA[$k] += $v } catch {}
}

function Write-LauncherLog ([string]$Text) {
    try {
        # Запись журнала лаунчеров в файл в папке temp отключена.
    } catch {}
}

# Функции-сканеры лаунчеров: один список и для обычного сканирования, и для прогрева (см. Step-LibPreheat).
$script:LauncherSourceFnNames = @('Get-EpicLauncherSource', 'Get-GogLauncherSource', 'Get-UbisoftLauncherSource', 'Get-EaLauncherSource', 'Get-BattleNetLauncherSource', 'Get-XboxLauncherSource')

# Все обнаруженные лаунчеры (лаунчер найден по exe или по наличию его игр).
function Get-InstalledLauncherSources ($SteamShortcuts = @()) {
    $out = New-Object System.Collections.Generic.List[object]
    $script:libFoundSources = New-Object System.Collections.ArrayList
    foreach ($fn in @($script:LauncherSourceFnNames)) {
        try {
            $src = & $fn $SteamShortcuts
            Write-Tm ('   ' + $fn)
            if ($null -eq $src) { Write-LauncherLog ($fn + ': returned null'); continue }
            Write-LauncherLog ($fn + ': detected=' + $src.Detected + ' exe=' + $src.ExePath + ' games=' + @($src.Games).Count)
            if ([bool]$src.Detected -or @($src.Games).Count -gt 0) {
                [void]$out.Add($src)
                try { [void]$script:libFoundSources.Add($src) } catch { Write-LauncherLog ('libFoundSources.Add: ' + $_.Exception.Message) }
            }
        } catch {
            Write-LauncherLog ($fn + ': ERROR ' + $_.Exception.Message + ' @ line ' + $_.InvocationInfo.ScriptLineNumber)
        }
    }
    Write-LauncherLog ('scan finished, sources: ' + $script:libFoundSources.Count)
    # Результат — в $script:libFoundSources. Возврат @($out) падал с "Типы аргумента не совпадают".
}

# ===================== ПРОГРЕВ ДАННЫХ БИБЛИОТЕКИ =====================
# Записи Steam (Get-SteamLibraryEntries) и список лаунчеров с их играми (Get-InstalledLauncherSources)
# читаются заранее, пока человек смотрит на главное окно, а при открытии библиотеки берутся готовыми.
# Работа идёт в потоке интерфейса, но кусками по таймеру: один тик = один шаг (записи Steam или один
# лаунчер), между тиками окно живёт. Снимок хранится вместе с «отпечатком» данных Steam
# (appmanifest_*.acf + shortcuts.vdf): если отпечаток изменился — снимок считается устаревшим и
# библиотека читает всё заново, как раньше. Лаунчеры отпечатка не имеют, поэтому снимок ещё и
# ограничен по возрасту. Явное «Обновить» (кнопка / F5) сбрасывает снимок целиком.
# Значки лаунчеров в снимке — общие кэшированные Bitmap ($script:libIconCache); окно библиотеки
# при закрытии их не освобождает, поэтому повторное использование безопасно.
$script:libPreheat = $null            # готовый снимок: Fp, At, Entries, Sources
$script:libPreheatJob = $null         # идущее сейчас прогревание (шаги по таймеру)
$script:libPreheatTimer = $null
$script:libPreheatEnabled = $false    # включается, когда главное окно показано
$script:libPreheatBlocked = $false    # $true, пока открыта библиотека
$script:LibPreheatMaxAgeSec = 600

# Поверхностная копия объекта: окно библиотеки меняет записи (AlreadyInSteam = $true и т.п.),
# а снимок должен оставаться чистым.
function Copy-LibObject ($Obj) {
    try { return $Obj.PSObject.Copy() } catch { return $Obj }
}

function Copy-LibObjectList ($List) {
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($o in @($List)) { if ($null -ne $o) { [void]$out.Add((Copy-LibObject $o)) } }
    return $out.ToArray()
}

function Copy-LibLauncherSource ($Src) {
    $c = Copy-LibObject $Src
    try { $c.Games = @(Copy-LibObjectList $Src.Games) } catch {}
    return $c
}

# Отпечаток данных, от которых зависят записи Steam и признак «уже в Steam» у игр лаунчеров.
function Get-LibDataFingerprint {
    $sb = New-Object System.Text.StringBuilder
    try {
        foreach ($appsRoot in @(Get-SteamLibraryFolders)) {
            $cnt = 0; $maxT = [long]0; $sumLen = [long]0
            try {
                $di = New-Object System.IO.DirectoryInfo([string]$appsRoot)
                foreach ($fi in $di.EnumerateFiles('appmanifest_*.acf')) {
                    $cnt++
                    $tk = [long]$fi.LastWriteTimeUtc.Ticks
                    if ($tk -gt $maxT) { $maxT = $tk }
                    $sumLen += [long]$fi.Length
                }
            } catch {}
            [void]$sb.Append('A|' + [string]$appsRoot + '|' + [string]$cnt + '|' + [string]$maxT + '|' + [string]$sumLen + ';')
        }
    } catch {}
    try {
        $ud = [string](Get-ConfiguredSteamUserDataPath)
        [void]$sb.Append('U|' + $ud + ';')
        $cands = New-Object System.Collections.Generic.List[string]
        [void]$cands.Add([System.IO.Path]::Combine($ud, 'config', 'shortcuts.vdf'))
        if ([System.IO.Directory]::Exists($ud)) {
            foreach ($sub in [System.IO.Directory]::EnumerateDirectories($ud)) {
                [void]$cands.Add([System.IO.Path]::Combine($sub, 'config', 'shortcuts.vdf'))
            }
        }
        foreach ($p in $cands) {
            $f = New-Object System.IO.FileInfo($p)
            if ($f.Exists) { [void]$sb.Append('S|' + $p + '|' + [string]$f.Length + '|' + [string]$f.LastWriteTimeUtc.Ticks + ';') }
        }
    } catch {}
    try { [void]$sb.Append('G|' + [string]@($global:installedSteamGames.Keys).Count) } catch {}
    return $sb.ToString()
}

function Set-LibPreheatSnapshot ([string]$Fp, $Entries, $Sources) {
    $ents = @(Copy-LibObjectList $Entries)
    $srcs = New-Object System.Collections.ArrayList
    foreach ($s in @($Sources)) { if ($null -ne $s) { [void]$srcs.Add((Copy-LibLauncherSource $s)) } }
    $script:libPreheat = [PSCustomObject]@{ Fp = [string]$Fp; At = [DateTime]::UtcNow; Entries = $ents; Sources = $srcs }
}

# Снимок, если он есть, не старше MaxAge и отпечаток не изменился; иначе $null.
function Get-LibPreheatSnapshot {
    $s = $script:libPreheat
    if ($null -eq $s) { return $null }
    if (([DateTime]::UtcNow - [DateTime]$s.At).TotalSeconds -gt [double]$script:LibPreheatMaxAgeSec) { return $null }
    $fp = ''
    try { $fp = Get-LibDataFingerprint } catch { return $null }
    if ([string]$s.Fp -cne $fp) { return $null }
    return $s
}

function Stop-LibPreheatJob {
    $script:libPreheatJob = $null
    try { if ($null -ne $script:libPreheatTimer) { $script:libPreheatTimer.Stop() } } catch {}
}

function Reset-LibPreheat {
    $script:libPreheat = $null
    Stop-LibPreheatJob
}

# Запросить прогрев: ничего не делает, если он не включён, открыта библиотека, прогрев уже идёт
# или снимок ещё актуален. Иначе запускает цепочку шагов через DelayMs.
function Request-LibPreheat ([int]$DelayMs = 1500) {
    try {
        if (-not $script:libPreheatEnabled -or $script:libPreheatBlocked) { return }
        if ($null -ne $script:libPreheatJob) { return }
        if ($null -ne (Get-LibPreheatSnapshot)) { return }
        $script:libPreheatJob = @{ Stage = 0; Fp = ''; Entries = @(); Shortcuts = $null; Sources = (New-Object System.Collections.ArrayList) }
        if ($null -eq $script:libPreheatTimer) {
            $tm = New-Object System.Windows.Forms.Timer
            $tm.Add_Tick({
                try { Step-LibPreheat } catch { try { Stop-LibPreheatJob } catch {} }
            })
            $script:libPreheatTimer = $tm
        }
        $script:libPreheatTimer.Interval = [Math]::Max(10, $DelayMs)
        $script:libPreheatTimer.Start()
    } catch {}
}

# Один шаг прогрева. Стадия 0 — записи Steam, стадии 1..N — по одному лаунчеру, дальше — сохранение снимка.
function Step-LibPreheat {
    $tm = $script:libPreheatTimer
    try { $tm.Stop() } catch {}
    $job = $script:libPreheatJob
    if ($null -eq $job -or $script:libPreheatBlocked -or -not $script:libPreheatEnabled) { $script:libPreheatJob = $null; return }
    # Идёт пакетное добавление игр (ярлыки пишутся) — не вмешиваемся, пробуем позже.
    if ($script:batchInProgress) { $tm.Interval = 1500; $tm.Start(); return }
    $fns = @($script:LauncherSourceFnNames)
    $st = [int]$job.Stage
    if ($st -eq 0) {
        # Отпечаток снимается ДО чтения: если данные изменятся по ходу прогрева, снимок окажется устаревшим.
        $job.Fp = Get-LibDataFingerprint
        $job.Entries = @(Get-SteamLibraryEntries)
        $sc = New-Object System.Collections.ArrayList
        foreach ($se in $job.Entries) { if ([string]$se.Kind -eq 'shortcut') { [void]$sc.Add($se) } }
        $job.Shortcuts = $sc
    } elseif ($st -le $fns.Count) {
        $fn = [string]$fns[$st - 1]
        try {
            $src = & $fn $job.Shortcuts.ToArray()
            if ($null -eq $src) {
                Write-LauncherLog ($fn + ': returned null')
            } else {
                Write-LauncherLog ($fn + ': detected=' + $src.Detected + ' exe=' + $src.ExePath + ' games=' + @($src.Games).Count)
                if ([bool]$src.Detected -or @($src.Games).Count -gt 0) { [void]$job.Sources.Add($src) }
            }
        } catch {
            Write-LauncherLog ($fn + ': ERROR ' + $_.Exception.Message)
        }
    } else {
        Set-LibPreheatSnapshot ([string]$job.Fp) $job.Entries $job.Sources
        Write-LauncherLog ('preheat finished, sources: ' + $job.Sources.Count)
        $script:libPreheatJob = $null
        return
    }
    $job.Stage = $st + 1
    $tm.Interval = 40
    $tm.Start()
}

# ===================== ОБЛОЖКИ ИГР ЛАУНЧЕРОВ =====================
# Обложка ищется в SteamGridDB по названию игры (тот же ключ API, что в «Настройках»),
# скачивается один раз в %APPDATA%\Steam Commander\launcher_covers и дальше берётся с диска.

function Get-LauncherCoverCachePath ($Name) {
    $dir = Join-Path $global:appDataDir 'launcher_covers'
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $sha = [System.Security.Cryptography.SHA1]::Create()
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes(([string]$Name).ToLowerInvariant().Trim())
        $hash = ([System.BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLowerInvariant()
    } finally { $sha.Dispose() }
    return (Join-Path $dir ($hash + '.v5.img'))
}

# Файл -> Bitmap строго под размер плитки (обрезка по центру, без растяжения).
function New-LauncherCoverBitmap ($Path, $W, $H) {
    try {
        $W = [int]$W; $H = [int]$H
        $bytes = [System.IO.File]::ReadAllBytes([string]$Path)
        $ms = New-Object System.IO.MemoryStream(, $bytes)
        $src = $null
        try {
            $src = [System.Drawing.Image]::FromStream($ms)
            $bmp = New-Object System.Drawing.Bitmap($W, $H)
            $g = [System.Drawing.Graphics]::FromImage($bmp)
            try {
                $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                $scale = [Math]::Max($W / [double]$src.Width, $H / [double]$src.Height)
                $dw = [single]($src.Width * $scale)
                $dh = [single]($src.Height * $scale)
                $g.DrawImage($src, [single](($W - $dw) / 2), [single](($H - $dh) / 2), $dw, $dh)
            } finally { $g.Dispose() }
            return $bmp
        } finally {
            if ($null -ne $src) { $src.Dispose() }
            $ms.Dispose()
        }
    } catch { return $null }
}

# ---------- Проверка скачанной картинки ----------
# Обложка должна декодироваться GDI+ (WebP он не читает) и быть ВЕРТИКАЛЬНОЙ (как в Steam/лаунчерах):
# горизонтальный баннер в плитке 150x225 выглядел бы обрезком, поэтому его отбрасываем.
function Test-LauncherCoverFile ([string]$Path, [bool]$RequireVertical = $true) {
    try {
        $b = [System.IO.File]::ReadAllBytes($Path)
        $m = New-Object System.IO.MemoryStream(, $b)
        try {
            $im = [System.Drawing.Image]::FromStream($m)
            try {
                if ($im.Width -lt 80 -or $im.Height -lt 80) { return $false }
                if ($RequireVertical -and ([double]$im.Height / [double]$im.Width) -lt 1.2) { return $false }
                return $true
            } finally { $im.Dispose() }
        } finally { $m.Dispose() }
    } catch { return $false }
}

# Перебирает ссылки, первую подошедшую кладёт в $TargetPath.
function Save-FirstValidCover ($Urls, [string]$TargetPath, [int]$MaxTries = 4, [bool]$RequireVertical = $true) {
    $tries = 0
    foreach ($u in @($Urls)) {
        if ([string]::IsNullOrWhiteSpace([string]$u)) { continue }
        if ($tries -ge $MaxTries) { break }
        $tries++
        $tmp = $TargetPath + '.tmp'
        if (-not (Download-RemoteImage ([string]$u) $tmp 2048)) { Write-LauncherLog ('  download failed: ' + [string]$u); continue }
        if (Test-LauncherCoverFile $tmp $RequireVertical) {
            Move-Item -LiteralPath $tmp -Destination $TargetPath -Force
            Write-LauncherLog ('  accepted: ' + [string]$u + $(if ($RequireVertical) { '' } else { ' (any orientation)' }))
            return $true
        }
        # Для нативных обложек лаунчера (часто горизонтальных) — второй шанс без требования вертикали
        if ($RequireVertical -and (Test-LauncherCoverFile $tmp $false)) {
            Move-Item -LiteralPath $tmp -Destination $TargetPath -Force
            Write-LauncherLog ('  accepted (landscape ok): ' + [string]$u)
            return $true
        }
        Write-LauncherLog ('  rejected (not vertical / unreadable): ' + [string]$u)
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    }
    return $false
}

# ---------- Epic: локальный каталог лаунчера ----------
# %ProgramData%\Epic\EpicGamesLauncher\Data\Catalog\catcache.bin — base64(JSON) со всеми
# играми, которые лаунчер когда-либо показывал; у каждой есть keyImages со ссылками на CDN.
$script:epicCatalogMap = $null
function Get-EpicCatalogMap {
    if ($null -ne $script:epicCatalogMap) { return $script:epicCatalogMap }
    $map = @{ ById = @{}; ByTitle = @{} }
    try {
        $f = Join-Path ([string]$env:ProgramData) 'Epic\EpicGamesLauncher\Data\Catalog\catcache.bin'
        if (Test-Path -LiteralPath $f -PathType Leaf) {
            $json = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(([System.IO.File]::ReadAllText($f)).Trim()))
            Add-Type -AssemblyName System.Web.Extensions
            $ser = New-Object System.Web.Script.Serialization.JavaScriptSerializer
            $ser.MaxJsonLength = [int]::MaxValue
            $ser.RecursionLimit = 200
            $items = $ser.DeserializeObject($json)
            # Порядок предпочтения: вертикальные типы, затем всё остальное (отсеется проверкой пропорций).
            $pref = @('DieselGameBoxTall', 'OfferImageTall', 'DieselStoreFrontTall', 'Thumbnail', 'DieselGameBox')
            foreach ($it in @($items)) {
                try {
                    $imgs = @($it['keyImages'])
                    if ($imgs.Count -eq 0) { continue }
                    $urls = New-Object System.Collections.Generic.List[string]
                    foreach ($t in $pref) {
                        foreach ($im in $imgs) {
                            if ([string]$im['type'] -eq $t -and -not [string]::IsNullOrWhiteSpace([string]$im['url'])) { [void]$urls.Add([string]$im['url']) }
                        }
                    }
                    if ($urls.Count -eq 0) { continue }
                    $arr = $urls.ToArray()
                    if ($it['id']) { $map.ById[[string]$it['id']] = $arr }
                    if ($it['title']) { $map.ByTitle[([string]$it['title']).ToLowerInvariant().Trim()] = $arr }
                } catch {}
            }
        }
        Write-LauncherLog ('epic catalog: ' + $map.ById.Count + ' items')
    } catch { Write-LauncherLog ('epic catalog error: ' + $_.Exception.Message) }
    $script:epicCatalogMap = $map
    return $map
}

function Get-EpicCoverUrls ($Entry) {
    $map = Get-EpicCatalogMap
    $cid = [string]$Entry.CatalogId
    if ($cid -and $map.ById.ContainsKey($cid)) { Write-LauncherLog ('epic [' + [string]$Entry.Name + '] catalog match by id'); return @($map.ById[$cid]) }
    $t = ([string]$Entry.Name).ToLowerInvariant().Trim()
    if ($t -and $map.ByTitle.ContainsKey($t)) { Write-LauncherLog ('epic [' + [string]$Entry.Name + '] catalog match by title'); return @($map.ByTitle[$t]) }
    Write-LauncherLog ('epic [' + [string]$Entry.Name + '] NOT in catalog (catalogId=' + $cid + ', items=' + $map.ById.Count + ')')
    return @()
}

# ---------- GOG: точная обложка из Galaxy webcache + API fallback ----------
function Get-GogCoverUrls ($Entry) {
    $out = New-Object System.Collections.Generic.List[string]
    try {
        $id = [string]$Entry.GameId
        if ($id -notmatch '^\d+$') { return @() }
        $blk = { param($u) try { Invoke-RestMethod -Uri $u -TimeoutSec 10 -UserAgent 'Mozilla/5.0' -ErrorAction Stop } catch { $null } }
        $r = Invoke-BackgroundJsonRequest $blk @('https://api.gog.com/v2/games/' + $id + '?locale=en-US') 14
        if ($null -eq $r) { return @() }
        $box = ''
        try { $box = [string]$r._links.boxArtImage.href } catch {}
        if ($box) {
            # Вертикальная обложка Galaxy строится от того же хэша; JPG — потому что GDI+ не читает WebP.
            $base = [regex]::Replace($box, '\.(png|jpe?g|webp)(\?.*)?$', '')
            [void]$out.Add($base + '_glx_vertical_cover.jpg')
            [void]$out.Add($box)
        }
    } catch { Write-LauncherLog ('gog cover urls: ' + $_.Exception.Message) }
    return @($out.ToArray())
}

# ---------- Ubisoft Connect: configurations + cache/assets + CDN ----------
# Источники обложек (по приоритету):
#  1) CDN assets: ubistatic3-a.akamaihd.net/orbit/uplay_launcher_3_0/assets/<thumb>
#  2) CDN boxart: ubiservices.cdn.ubi.com/<spaceId>/spaceCardAsset/boxArt_mobile.jpg
# thumb / spaceId / name — из файла configurations лаунчера.
$script:ubisoftConfigCache = $null

function Get-UbisoftConfigurationsFilePaths {
    $out = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    $add = {
        param($p)
        if ([string]::IsNullOrWhiteSpace($p)) { return }
        $full = [string]$p
        $key = $full.ToLowerInvariant()
        if ($seen.ContainsKey($key)) { return }
        if (Test-Path -LiteralPath $full -PathType Leaf) {
            $seen[$key] = $true
            [void]$out.Add($full)
        }
    }
    foreach ($root in @(
        (Join-Path ([string]$env:LOCALAPPDATA) 'Ubisoft Game Launcher'),
        (Join-Path ([string]$env:LOCALAPPDATA) 'Ubisoft\Ubisoft Game Launcher')
    )) {
        foreach ($rel in @(
            'cache\configuration\configurations',
            'caches\configuration\configurations',
            'cache\configurations'
        )) { & $add (Join-Path $root $rel) }
    }
    $installDir = Get-RegValueSafe 'HKLM:\SOFTWARE\WOW6432Node\Ubisoft\Launcher' 'InstallDir'
    if (-not [string]::IsNullOrWhiteSpace($installDir)) {
        $installDir = $installDir.Replace('/', '\').TrimEnd('\')
        foreach ($rel in @(
            'cache\configuration\configurations',
            'caches\configuration\configurations'
        )) { & $add (Join-Path $installDir $rel) }
    }
    foreach ($base in @(${env:ProgramFiles(x86)}, $env:ProgramFiles)) {
        if ([string]::IsNullOrWhiteSpace($base)) { continue }
        & $add (Join-Path $base 'Ubisoft\Ubisoft Game Launcher\cache\configuration\configurations')
        & $add (Join-Path $base 'Ubisoft Game Launcher\cache\configuration\configurations')
    }
    return @($out.ToArray())
}

function Normalize-UbiNameKey ([string]$s) {
    if ([string]::IsNullOrWhiteSpace($s)) { return '' }
    $s = $s.ToLowerInvariant().Trim()
    $s = [regex]::Replace($s, '[^a-z0-9]+', '')
    return $s
}

function Initialize-UbisoftConfigIndex {
    if ($null -ne $script:ubisoftConfigCache) { return $script:ubisoftConfigCache }
    $byId = @{}
    $byName = @{}
    try {
        foreach ($cfgPath in @(Get-UbisoftConfigurationsFilePaths)) {
            try {
                $bytes = [System.IO.File]::ReadAllBytes($cfgPath)
                $start = 0
                while ($start -lt $bytes.Length -and $bytes[$start] -lt 32) { $start++ }
                $text = [System.Text.Encoding]::UTF8.GetString($bytes, $start, $bytes.Length - $start)
                if ([string]::IsNullOrWhiteSpace($text)) { continue }

                $rxThumbAll = [regex]'(?i)(?:thumb_image|thumbImage)\s*:\s*["'']?([^\s"''#\r\n]+)'
                $rxSpaceAll = [regex]'(?i)(?:space_id|spaceId)\s*:\s*["'']?([0-9a-fA-F\-]{8,})'
                $rxNameNear = [regex]'(?i)(?:name|display_name|displayName|shortcut_name|shortcutName)\s*:\s*["'']([^"''\r\n]+)["'']'
                $rxIdNear   = [regex]'(?i)(?:install_id|installId|uplay_id|uplayId|product_id|productId|game_id|gameId|app_id|appId|\bid)\s*:\s*["'']?(\d{2,})'
                $rxNameAll  = [regex]'(?im)(?:name|display_name|displayName|shortcut_name|shortcutName)\s*:\s*["'']([^"''\r\n]+)["'']'

                $thumbMatches = @($rxThumbAll.Matches($text))
                Write-LauncherLog ('ubisoft config: ' + $cfgPath + ' thumb_image hits=' + $thumbMatches.Count)

                foreach ($tm in $thumbMatches) {
                    try {
                        $thumb = [string]$tm.Groups[1].Value.Trim().TrimEnd(',',';')
                        if ([string]::IsNullOrWhiteSpace($thumb)) { continue }
                        if ($thumb -notmatch '\.(jpg|jpeg|png|webp)$') { continue }

                        $pos = [int]$tm.Index
                        $w0 = [Math]::Max(0, $pos - 1500)
                        $w1 = [Math]::Min($text.Length, $pos + 800)
                        $window = $text.Substring($w0, $w1 - $w0)

                        $gname = ''
                        foreach ($nm in $rxNameNear.Matches($window)) {
                            $cand = [string]$nm.Groups[1].Value.Trim()
                            if ($cand.Length -lt 2) { continue }
                            if ($cand -match '^(default|true|false|null|\d+)$') { continue }
                            # Берём имя, которое стоит до thumb (ближе к нему)
                            if (([int]$nm.Index + $w0) -le $pos) { $gname = $cand }
                        }

                        $ids = New-Object System.Collections.Generic.List[string]
                        foreach ($im in $rxIdNear.Matches($window)) {
                            $idv = [string]$im.Groups[1].Value
                            if ($idv -and -not $ids.Contains($idv)) { [void]$ids.Add($idv) }
                        }

                        $spaceId = ''
                        $sm = $rxSpaceAll.Match($window)
                        if ($sm.Success) { $spaceId = [string]$sm.Groups[1].Value.Trim().TrimEnd(',',';') }

                        $info = @{
                            Thumb      = $thumb
                            SpaceId    = $spaceId
                            Name       = $gname
                            InstallIds = @($ids.ToArray())
                        }

                        foreach ($idv in $ids) {
                            if (-not $byId.ContainsKey($idv)) {
                                $byId[$idv] = $info
                            } else {
                                if ([string]::IsNullOrWhiteSpace([string]$byId[$idv].Thumb)) { $byId[$idv].Thumb = $thumb }
                                if ([string]::IsNullOrWhiteSpace([string]$byId[$idv].SpaceId) -and $spaceId) { $byId[$idv].SpaceId = $spaceId }
                                if ([string]::IsNullOrWhiteSpace([string]$byId[$idv].Name) -and $gname) { $byId[$idv].Name = $gname }
                            }
                        }
                        $nk = Normalize-UbiNameKey $gname
                        if ($nk) {
                            if (-not $byName.ContainsKey($nk)) {
                                $byName[$nk] = $info
                            } else {
                                if ([string]::IsNullOrWhiteSpace([string]$byName[$nk].Thumb)) { $byName[$nk].Thumb = $thumb }
                                if ([string]::IsNullOrWhiteSpace([string]$byName[$nk].SpaceId) -and $spaceId) { $byName[$nk].SpaceId = $spaceId }
                            }
                        }
                    } catch {}
                }

                # name -> ближайший thumb после имени
                foreach ($nm in $rxNameAll.Matches($text)) {
                    try {
                        $gname = [string]$nm.Groups[1].Value.Trim()
                        $nk = Normalize-UbiNameKey $gname
                        if (-not $nk) { continue }
                        if ($byName.ContainsKey($nk) -and -not [string]::IsNullOrWhiteSpace([string]$byName[$nk].Thumb)) { continue }
                        $pos = [int]$nm.Index
                        $w1 = [Math]::Min($text.Length, $pos + 2000)
                        $window = $text.Substring($pos, $w1 - $pos)
                        $tm = $rxThumbAll.Match($window)
                        if (-not $tm.Success) { continue }
                        $thumb = [string]$tm.Groups[1].Value.Trim().TrimEnd(',',';')
                        if ($thumb -notmatch '\.(jpg|jpeg|png|webp)$') { continue }
                        $spaceId = ''
                        $sm = $rxSpaceAll.Match($window)
                        if ($sm.Success) { $spaceId = [string]$sm.Groups[1].Value.Trim() }
                        $ids = New-Object System.Collections.Generic.List[string]
                        foreach ($im in $rxIdNear.Matches($window)) {
                            $idv = [string]$im.Groups[1].Value
                            if ($idv -and -not $ids.Contains($idv)) { [void]$ids.Add($idv) }
                        }
                        $info = @{ Thumb = $thumb; SpaceId = $spaceId; Name = $gname; InstallIds = @($ids.ToArray()) }
                        $byName[$nk] = $info
                        foreach ($idv in $ids) {
                            if (-not $byId.ContainsKey($idv)) { $byId[$idv] = $info }
                        }
                    } catch {}
                }

                Write-LauncherLog ('ubisoft config parsed: byId=' + $byId.Count + ' byName=' + $byName.Count)
            } catch {
                Write-LauncherLog ('ubisoft config read error: ' + $_.Exception.Message)
            }
        }
    } catch {
        Write-LauncherLog ('ubisoft config index error: ' + $_.Exception.Message)
    }
    $script:ubisoftConfigCache = @{ ById = $byId; ByName = $byName }
    return $script:ubisoftConfigCache
}

function Get-UbisoftCoverInfo ($Entry) {
    $idx = Initialize-UbisoftConfigIndex
    $byId = $idx.ById
    $byName = $idx.ByName

    $id = [string]$Entry.GameId
    if ($id -and $byId.ContainsKey($id)) {
        Write-LauncherLog ('ubisoft cover info: matched by id=' + $id + ' thumb=' + [string]$byId[$id].Thumb + ' space=' + [string]$byId[$id].SpaceId)
        return $byId[$id]
    }

    $nk = Normalize-UbiNameKey ([string]$Entry.Name)
    if ($nk -and $byName.ContainsKey($nk)) {
        Write-LauncherLog ('ubisoft cover info: matched by name=' + [string]$Entry.Name + ' thumb=' + [string]$byName[$nk].Thumb + ' space=' + [string]$byName[$nk].SpaceId)
        return $byName[$nk]
    }

    if ($nk -and $nk.Length -ge 5) {
        foreach ($k in @($byName.Keys)) {
            if ($k.Contains($nk) -or $nk.Contains($k)) {
                Write-LauncherLog ('ubisoft cover info: partial name ' + [string]$Entry.Name + ' ~ ' + $k + ' thumb=' + [string]$byName[$k].Thumb)
                return $byName[$k]
            }
        }
    }

    Write-LauncherLog ('ubisoft cover info: NO match for id=' + $id + ' name=' + [string]$Entry.Name + ' (byId=' + $byId.Count + ' byName=' + $byName.Count + ')')
    return $null
}

function Get-UbisoftCoverUrls ($Entry) {
    $out = New-Object System.Collections.Generic.List[string]
    try {
        $info = Get-UbisoftCoverInfo $Entry
        $thumb = if ($null -ne $info) { [string]$info.Thumb } else { '' }
        $spaceId = if ($null -ne $info) { [string]$info.SpaceId } else { '' }

        if (-not [string]::IsNullOrWhiteSpace($thumb)) {
            $thumbUrl = $thumb.Replace('\', '/').TrimStart('/')
            [void]$out.Add('https://ubistatic3-a.akamaihd.net/orbit/uplay_launcher_3_0/assets/' + $thumbUrl)
            [void]$out.Add('https://static3.cdn.ubi.com/orbit/uplay_launcher_3_0/assets/' + $thumbUrl)
            if ($thumbUrl.Contains('/')) {
                [void]$out.Add('https://ubistatic3-a.akamaihd.net/orbit/uplay_launcher_3_0/assets/' + [System.IO.Path]::GetFileName($thumbUrl))
            }
        }
        if (-not [string]::IsNullOrWhiteSpace($spaceId)) {
            [void]$out.Add('https://ubiservices.cdn.ubi.com/' + $spaceId + '/spaceCardAsset/boxArt_mobile.jpg?imwidth=600')
            [void]$out.Add('https://ubiservices.cdn.ubi.com/' + $spaceId + '/spaceCardAsset/boxArt_mobile.jpg?imwidth=320')
            [void]$out.Add('https://ubiservices.cdn.ubi.com/' + $spaceId + '/spaceCardAsset/boxArt.jpg?imwidth=600')
        }
        if ($out.Count -gt 0) {
            Write-LauncherLog ('ubisoft cover urls for [' + [string]$Entry.Name + ']: ' + $out.Count + ' candidates')
        }
    } catch {
        Write-LauncherLog ('ubisoft cover urls: ' + $_.Exception.Message)
    }
    return @($out.ToArray())
}

# ---------- SteamGridDB: вертикальная сетка (600x900 как в Steam) ----------
function Get-LauncherCoverFromSgdb ($Name, $TargetPath) {
    try {
        $apiKey = [string]$global:steamGridDbApiKey
        if ([string]::IsNullOrWhiteSpace($apiKey)) { return 'nokey' }
        $headers = @{ Authorization = ('Bearer ' + $apiKey) }
        $cands = @(Get-EditorSgdbCandidates ([string]$Name) '')
        if ($cands.Count -eq 0) { return 'error' }
        $best = $cands[0]
        # Слабое совпадение названия хуже, чем отсутствие обложки: чужую не ставим.
        if ([double]$best.MatchScore -lt 60) { return 'none' }
        $req = Invoke-SgdbApiRequest ('https://www.steamgriddb.com/api/v2/grids/game/' + [int]$best.Id) $headers 20
        if (-not $req.Success) { return 'error' }
        $all = @($req.Data | Where-Object {
            $mime = ''; try { $mime = [string]$_.mime } catch {}
            $u = [string]$_.url
            ($mime -notmatch 'webp|apng|gif') -and ($u -notmatch '\.(webp|apng|gif)(\?|$)')
        })
        $vert = @($all | Where-Object {
            $w = 0.0; $h = 0.0; try { $w = [double]$_.width; $h = [double]$_.height } catch {}
            $h -gt 0 -and ($w / $h) -ge 0.55 -and ($w / $h) -le 0.78
        })
        if ($vert.Count -eq 0) { return 'none' }
        # Сначала стандартный Steam-размер 600x900, потом по рейтингу.
        $vert = @($vert | Sort-Object @{Expression = { if ([int]$_.width -eq 600 -and [int]$_.height -eq 900) { 0 } else { 1 } }}, @{Expression = { $v = 0.0; try { $v = [double]$_.score } catch {}; -$v }})
        $urls = New-Object System.Collections.Generic.List[string]
        foreach ($gr in ($vert | Select-Object -First 3)) {
            [void]$urls.Add([string]$gr.thumb); [void]$urls.Add([string]$gr.url)
        }
        if (Save-FirstValidCover $urls.ToArray() ([string]$TargetPath) 6) { return 'ok' }
        return 'none'
    } catch {
        Write-LauncherLog ('sgdb cover error (' + [string]$Name + '): ' + $_.Exception.Message)
        return 'error'
    }
}

# ---------- EA app: обложка из Steam ----------
# У EA app нет доступного снаружи каталога обложек, а SteamGridDB по названию нередко
# отдаёт чужие версии (например, коробку Nintendo DS). Поэтому для игр EA сначала
# ищем ту же игру в Steam и берём её официальную вертикальную капсулу.
# Совпадение — только по «значимым» словам названия (без Edition/GOTY/™ и т.п.),
# чтобы «Plants vs. Zombies» не подхватила «Plants vs. Zombies: Garden Warfare».
function Get-EaCoverUrls ($Entry) {
    try {
        $name = [string]$Entry.Name
        if ([string]::IsNullOrWhiteSpace($name)) { return @() }
        # Find-SteamAppInfo возвращает ОДИН вариант и для «Plants vs. Zombies» отдаёт
        # Demo (id=3592) вместо самой игры, поэтому берём список кандидатов и сами
        # выбираем первого, у кого набор значимых слов совпадает полностью, а название
        # не похоже на демо/саундтрек/бету и т.п.
        $myTokens = Get-NameTokens $name
        $junkRx = '(?i)\b(demo|soundtrack|ost|beta|playtest|dedicated server|sdk|artbook)\b'
        $tried = 0
        foreach ($c in @(Get-SteamStoreNameCandidates $name 12)) {
            $cn = [string]$c.Name
            if ([string]::IsNullOrWhiteSpace($cn) -or [string]::IsNullOrWhiteSpace([string]$c.Id)) { continue }
            if ($cn -match $junkRx) { continue }
            if ((Get-TokenOverlapScore $myTokens (Get-NameTokens $cn)) -lt 1.0) { continue }
            $tried++
            $assets = Get-SteamAssetUrlsViaApi ([string]$c.Id)
            if ($null -eq $assets -or @($assets.Capsule).Count -eq 0) {
                Write-LauncherLog ('ea cover [' + $name + ']: no Steam capsule for ' + $cn + ' (id=' + [string]$c.Id + ')')
                if ($tried -ge 3) { break }
                continue
            }
            Write-LauncherLog ('ea cover [' + $name + ']: Steam id=' + [string]$c.Id + ' (' + $cn + ')')
            return @($assets.Capsule)
        }
        Write-LauncherLog ('ea cover [' + $name + ']: no suitable Steam match')
        return @()
    } catch {
        Write-LauncherLog ('ea cover urls error: ' + $_.Exception.Message)
        return @()
    }
}

# ---------- Battle.net: обложка из кэша клиента ----------
# %LOCALAPPDATA%\Battle.net\Cache — хранилище по содержимому: файл лежит в Cache\aa\bb\<md5>,
# где имя = MD5 самого файла. JSON-фрагменты продуктов (fragment_id вида starcraft_remastered)
# содержат products[].id / uid и карту files: { ключ: { hash = md5 картинки; name = путь } }.
# По uid из реестра (--uid=s1) находим фрагмент, берём его картинки и выбираем вертикальную.
# Формат внутренний и может смениться: при любой неудаче возвращаем $false (дальше SteamGridDB).
$script:bnetCoverIndex = $null

function Get-BattleNetCacheDir { return (Join-Path ([string]$env:LOCALAPPDATA) 'Battle.net\Cache') }

# Чтение файла даже если он открыт клиентом. $Max > 0 — только первые байты.
function Read-BnetFileBytes ([string]$Path, [int]$Max = 0) {
    $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
    try {
        $len = [int]$fs.Length
        if ($Max -gt 0 -and $len -gt $Max) { $len = $Max }
        $b = New-Object byte[] $len
        $o = 0
        while ($o -lt $len) {
            $r = $fs.Read($b, $o, $len - $o)
            if ($r -le 0) { break }
            $o += $r
        }
        return , $b
    } finally { $fs.Dispose() }
}

# Все узлы вида { hash: <md5>, name: *.png|jpg } внутри карты files (структура вложенности не важна).
function Add-BnetImageNodes ($Node, $Out, [string]$Key = '', [int]$Depth = 0) {
    if ($Depth -gt 12 -or $null -eq $Node) { return }
    if ($Node -is [System.Collections.IDictionary]) {
        if ($Node.ContainsKey('hash') -and $Node.ContainsKey('name')) {
            $hh = ([string]$Node['hash']).ToLowerInvariant()
            $nn = [string]$Node['name']
            if ($hh -match '^[0-9a-f]{32}$' -and $nn -match '(?i)\.(png|jpe?g)$') {
                [void]$Out.Add([PSCustomObject]@{ Key = $Key; Hash = $hh; Name = $nn })
            }
            return
        }
        foreach ($k in @($Node.Keys)) { Add-BnetImageNodes $Node[$k] $Out ([string]$k) ($Depth + 1) }
    } elseif ($Node -is [System.Collections.IEnumerable] -and $Node -isnot [string]) {
        foreach ($it in $Node) { Add-BnetImageNodes $it $Out $Key ($Depth + 1) }
    }
}

# Значения uid на любой глубине продукта (например, base.types.retail.uid).
function Add-BnetUids ($Node, $Out, [int]$Depth = 0) {
    if ($Depth -gt 12 -or $null -eq $Node) { return }
    if ($Node -is [System.Collections.IDictionary]) {
        foreach ($k in @($Node.Keys)) {
            $v = $Node[$k]
            if ([string]$k -eq 'uid' -and $v -is [string] -and $v) { [void]$Out.Add(([string]$v).ToLowerInvariant()) }
            elseif ($v -is [System.Collections.IDictionary] -or ($v -is [System.Collections.IEnumerable] -and $v -isnot [string])) { Add-BnetUids $v $Out ($Depth + 1) }
        }
    } elseif ($Node -is [System.Collections.IEnumerable] -and $Node -isnot [string]) {
        foreach ($it in $Node) { Add-BnetUids $it $Out ($Depth + 1) }
    }
}

# Индекс: uid продукта (нижний регистр) -> список картинок его фрагментов. Строится один раз за запуск.
function Get-BattleNetCoverIndex {
    if ($null -ne $script:bnetCoverIndex) { return $script:bnetCoverIndex }
    $idx = @{}
    try {
        $cache = Get-BattleNetCacheDir
        if (Test-Path -LiteralPath $cache -PathType Container) {
            Add-Type -AssemblyName System.Web.Extensions
            $ser = New-Object System.Web.Script.Serialization.JavaScriptSerializer
            $ser.MaxJsonLength = [int]::MaxValue
            $ser.RecursionLimit = 200
            $utf8 = New-Object System.Text.UTF8Encoding($false)
            $frag = 0
            foreach ($f in @(Get-ChildItem -LiteralPath $cache -Recurse -File -ErrorAction SilentlyContinue)) {
                try {
                    if ($f.Length -lt 50 -or $f.Length -gt 3MB) { continue }
                    $first = Read-BnetFileBytes $f.FullName 1
                    if ($first.Length -lt 1 -or $first[0] -ne 0x7B) { continue }
                    $text = $utf8.GetString((Read-BnetFileBytes $f.FullName))
                    if ($text.IndexOf('"products"') -lt 0 -or $text.IndexOf('"files"') -lt 0) { continue }
                    $obj = $ser.DeserializeObject($text)
                    if ($obj -isnot [System.Collections.IDictionary]) { continue }
                    if (-not $obj.ContainsKey('products') -or -not $obj.ContainsKey('files')) { continue }
                    $imgs = New-Object System.Collections.Generic.List[object]
                    Add-BnetImageNodes $obj['files'] $imgs
                    if ($imgs.Count -eq 0) { continue }
                    $ids = New-Object System.Collections.Generic.List[string]
                    foreach ($pr in @($obj['products'])) {
                        if ($pr -isnot [System.Collections.IDictionary]) { continue }
                        if ($pr.ContainsKey('id') -and $pr['id'] -is [string] -and $pr['id']) { [void]$ids.Add(([string]$pr['id']).ToLowerInvariant()) }
                        Add-BnetUids $pr $ids
                    }
                    foreach ($id in @($ids | Select-Object -Unique)) {
                        if (-not $idx.ContainsKey($id)) { $idx[$id] = New-Object System.Collections.Generic.List[object] }
                        foreach ($im in $imgs) { [void]$idx[$id].Add($im) }
                    }
                    $frag++
                } catch {}
            }
            Write-LauncherLog ('battlenet cover index: fragments=' + $frag + ' products=' + $idx.Count)
        } else {
            Write-LauncherLog ('battlenet cover index: cache dir not found: ' + $cache)
        }
    } catch { Write-LauncherLog ('battlenet cover index error: ' + $_.Exception.Message) }
    $script:bnetCoverIndex = $idx
    return $idx
}

# Копирует в $TargetPath лучшую вертикальную картинку игры из кэша клиента. $true — получилось.
function Get-BattleNetLocalCover ($Entry, [string]$TargetPath) {
    try {
        $nm = [string]$Entry.Name
        $uid = ([string]$Entry.GameId).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($uid)) { return $false }
        $idx = Get-BattleNetCoverIndex
        if (-not $idx.ContainsKey($uid)) {
            Write-LauncherLog ('battlenet cover [' + $nm + ']: uid ' + $uid + ' not in client cache index')
            return $false
        }
        $cache = Get-BattleNetCacheDir
        $best = $null
        $seen = @{}
        foreach ($im in @($idx[$uid])) {
            if ($seen.ContainsKey($im.Hash)) { continue }
            $seen[$im.Hash] = $true
            $pth = Join-Path $cache ($im.Hash.Substring(0, 2) + '\' + $im.Hash.Substring(2, 2) + '\' + $im.Hash)
            if (-not (Test-Path -LiteralPath $pth -PathType Leaf)) {
                Write-LauncherLog ('  bnet image ' + $im.Key + ': not in cache (' + $im.Name + ')')
                continue
            }
            $iw = 0; $ih = 0
            try {
                $ms = New-Object System.IO.MemoryStream(, (Read-BnetFileBytes $pth))
                try {
                    $img = [System.Drawing.Image]::FromStream($ms)
                    try { $iw = $img.Width; $ih = $img.Height } finally { $img.Dispose() }
                } finally { $ms.Dispose() }
            } catch { continue }
            Write-LauncherLog ('  bnet image ' + $im.Key + ' ' + $iw + 'x' + $ih + ' ' + $im.Name)
            if ($iw -lt 200 -or $ih -le 0) { continue }
            $ratio = $ih / [double]$iw
            if ($ratio -lt 1.25 -or $ratio -gt 1.45) { continue }
            # Фоны/размытия/затемнённые арты клиент тоже хранит вертикальными — это не обложка.
            if (([string]$im.Key + ' ' + [string]$im.Name) -match '(?i)BACKGROUND|BACKDROP|BLUR|WALLPAPER|GRADIENT|OVERLAY|BANNER|LOGO|ICON|SCREENSHOT|(^|[^a-z])BG([^a-z]|$)') {
                Write-LauncherLog ('  bnet image ' + $im.Key + ': skipped (background-like)')
                continue
            }
            $score = [double]($iw * $ih)
            if ($im.Key -match '(?i)TILE|BOX|COVER|POSTER|PORTRAIT|VERTICAL|CARD') { $score += 100000000 }
            if ($null -eq $best -or $score -gt $best.Score) { $best = [PSCustomObject]@{ Path = $pth; Score = $score; Key = $im.Key } }
        }
        if ($null -eq $best) {
            Write-LauncherLog ('battlenet cover [' + $nm + ']: no vertical image among ' + $seen.Count + ' cached candidates')
            return $false
        }
        Copy-Item -LiteralPath $best.Path -Destination $TargetPath -Force
        if (Test-LauncherCoverFile $TargetPath $true) {
            Write-LauncherLog ('battlenet cover [' + $nm + ']: ' + $best.Key + ' <- ' + $best.Path)
            return $true
        }
        Remove-Item -LiteralPath $TargetPath -Force -ErrorAction SilentlyContinue
        return $false
    } catch {
        Write-LauncherLog ('battlenet local cover error: ' + $_.Exception.Message)
        return $false
    }
}

# Результат: 'ok' (файл сохранён) | 'none' (обложки нет нигде) | 'nokey' | 'error' (сеть и т.п.)
# Порядок: родной источник лаунчера (Epic/GOG/Ubisoft/Battle.net; для EA — капсула Steam) -> SteamGridDB по названию.
function Get-LauncherGameCover ($Entry, $TargetPath) {
    try {
        # GOG Galaxy's own cached vertical cover is the first and most authoritative source.
        if ([string]$Entry.Launcher -eq 'gog') {
            $local = Get-GogLocalCoverFile ([string]$Entry.Path) ([string]$Entry.GameId)
            if ($local) {
                if (Convert-GogWebpToJpg $local ([string]$TargetPath)) {
                    Write-LauncherLog ('cover [' + [string]$Entry.Name + '] from GOG Galaxy webcache: ' + $local)
                    return 'ok'
                }
            }
        }
    } catch { Write-LauncherLog ('gog local cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }

    try {
        # Ubisoft Connect: обложка (thumb_image из configurations) с CDN лаунчера, не SGDB.
        if ([string]$Entry.Launcher -eq 'ubisoft') {
            $ubiUrls = @(Get-UbisoftCoverUrls $Entry)
            # thumb_image — обложка игры (у Rayman Origins вертикальная); ориентацию не
            # требуем, плитка всё равно кадрирует по центру (New-LauncherCoverBitmap).
            if ($ubiUrls.Count -gt 0 -and (Save-FirstValidCover $ubiUrls ([string]$TargetPath) 6 $false)) {
                Write-LauncherLog ('cover [' + [string]$Entry.Name + '] from Ubisoft CDN')
                return 'ok'
            }
            Write-LauncherLog ('cover [' + [string]$Entry.Name + '] Ubisoft native not found, fallback SGDB')
        }
    } catch { Write-LauncherLog ('ubisoft local cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }

    try {
        # EA app: сначала официальная вертикальная капсула той же игры из Steam, затем SGDB.
        if ([string]$Entry.Launcher -eq 'ea') {
            $eaUrls = @(Get-EaCoverUrls $Entry)
            if ($eaUrls.Count -gt 0 -and (Save-FirstValidCover $eaUrls ([string]$TargetPath) 4)) {
                Write-LauncherLog ('cover [' + [string]$Entry.Name + '] from Steam capsule (EA)')
                return 'ok'
            }
        }
    } catch { Write-LauncherLog ('ea cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }

    try {
        # Battle.net: вертикальная картинка из кэша клиента (см. Get-BattleNetLocalCover), затем SGDB.
        if ([string]$Entry.Launcher -eq 'battlenet') {
            if (Get-BattleNetLocalCover $Entry ([string]$TargetPath)) {
                Write-LauncherLog ('cover [' + [string]$Entry.Name + '] from Battle.net client cache')
                return 'ok'
            }
            Write-LauncherLog ('cover [' + [string]$Entry.Name + '] Battle.net native not found, fallback SGDB')
        }
    } catch { Write-LauncherLog ('battlenet cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }

    try {
        # Xbox: постер из каталога Магазина, затем SGDB, затем заглушка из логотипа.
        if ([string]$Entry.Launcher -eq 'xbox') {
            $xbUrls = @(Get-XboxCoverUrls $Entry)
            if ($xbUrls.Count -gt 0 -and (Save-FirstValidCover $xbUrls ([string]$TargetPath) 3)) {
                Write-LauncherLog ('cover [' + [string]$Entry.Name + '] from Microsoft Store poster')
                return 'ok'
            }
        }
    } catch { Write-LauncherLog ('xbox store cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }

    try {
        $urls = @()
        switch ([string]$Entry.Launcher) {
            'epic' { $urls = @(Get-EpicCoverUrls $Entry) }
            'gog'  { $urls = @(Get-GogCoverUrls $Entry) }
        }
        if ($urls.Count -gt 0 -and (Save-FirstValidCover $urls ([string]$TargetPath) 4)) {
            Write-LauncherLog ('cover [' + [string]$Entry.Name + '] from ' + [string]$Entry.Launcher)
            return 'ok'
        }
    } catch { Write-LauncherLog ('native cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }
    $sgdbRes = Get-LauncherCoverFromSgdb ([string]$Entry.Name) $TargetPath
    # Xbox: если SteamGridDB не нашла подходящую вертикальную обложку (или нет ключа) —
    # собираем запасную из логотипа игры. Сетевую ошибку не кэшируем как "обложка готова".
    try {
        if ([string]$Entry.Launcher -eq 'xbox' -and ($sgdbRes -eq 'none' -or $sgdbRes -eq 'nokey')) {
            if (Get-XboxLocalCover $Entry ([string]$TargetPath)) { return 'ok' }
        }
    } catch { Write-LauncherLog ('xbox cover error (' + [string]$Entry.Name + '): ' + $_.Exception.Message) }
    return $sgdbRes
}

# ===================== ПАПКИ ИГР ДЛЯ ЯРЛЫКОВ (корень поиска DLSS) =====================
# В ярлыке Steam хранится только папка exe (StartDir), а не вся папка игры, поэтому DLL DLSS,
# лежащая выше или рядом, не находилась. При добавлении игры из панели теперь запоминается
# ПОЛНАЯ папка игры (%AppData%\Steam Commander\game_folders.json, ключ — exe + параметры запуска).
# Для ярлыков, добавленных раньше, корень определяется по папкам игр, найденным в панелях
# ($global:installedSteamGames): берётся самая верхняя такая папка, внутри которой лежит exe.
$script:gameFolderMap = $null

function Get-GameFolderMapPath { return (Join-Path ([string]$global:appDataDir) 'game_folders.json') }

function Get-GameFolderKey ([string]$Exe, [string]$LaunchOptions) {
    return ((Get-NormalizedGamePathKey ([string]$Exe)) + '|' + ([string]$LaunchOptions).Trim().ToUpperInvariant())
}

function Get-GameFolderMap {
    if ($null -ne $script:gameFolderMap) { return $script:gameFolderMap }
    $map = @{}
    try {
        $f = Get-GameFolderMapPath
        if (Test-Path -LiteralPath $f -PathType Leaf) {
            $obj = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
            if ($null -ne $obj) { foreach ($pr in $obj.PSObject.Properties) { $map[[string]$pr.Name] = [string]$pr.Value } }
        }
    } catch {}
    $script:gameFolderMap = $map
    return $map
}

function Set-GameFolderForShortcut ([string]$Exe, [string]$LaunchOptions, [string]$Folder) {
    try {
        if ([string]::IsNullOrWhiteSpace($Exe) -or [string]::IsNullOrWhiteSpace($Folder)) { return }
        $map = Get-GameFolderMap
        $map[(Get-GameFolderKey $Exe $LaunchOptions)] = ([string]$Folder).Trim().Trim('"').TrimEnd('\')
        $dir = [string]$global:appDataDir
        try { [void][System.IO.Directory]::CreateDirectory($dir) } catch {}
        $ordered = [ordered]@{}
        foreach ($k in @($map.Keys | Sort-Object)) { $ordered[[string]$k] = [string]$map[$k] }
        $json = $ordered | ConvertTo-Json
        [System.IO.File]::WriteAllText((Get-GameFolderMapPath), $json, (New-Object System.Text.UTF8Encoding($false)))
    } catch {
        try { Write-LauncherLog ('Set-GameFolderForShortcut: ' + $_.Exception.Message) } catch {}
    }
}

# Перенос записи при изменении ярлыка (перемещение игры на другой диск/папку, правка exe/параметров в карточке).
# $NewFolder пустой — берётся ранее запомненная папка (для правки exe в карточке).
function Move-GameFolderMapEntry ([string]$OldExe, [string]$OldLaunch, [string]$NewExe, [string]$NewLaunch, [string]$NewFolder = '') {
    try {
        $map = Get-GameFolderMap
        $ok = Get-GameFolderKey $OldExe $OldLaunch
        $nk = Get-GameFolderKey $NewExe $NewLaunch
        $folder = [string]$NewFolder
        if ([string]::IsNullOrWhiteSpace($folder) -and $map.ContainsKey($ok)) { $folder = [string]$map[$ok] }
        if ([string]::IsNullOrWhiteSpace($folder)) { return }
        if ($ok -ne $nk) { [void]$map.Remove($ok) }
        Set-GameFolderForShortcut $NewExe $NewLaunch $folder
    } catch {}
}

# ===================== АВТООПРЕДЕЛЕНИЕ КОРНЯ ПАПКИ ИГРЫ ПО ПУТИ К EXE =====================
# Не зависит ни от панелей, ни от game_folders.json, ни от того, на какой диск/в какую папку
# игра перенесена: корень вычисляется заново из текущего пути exe в ярлыке.
#  1) steamapps\common\<Игра>\...                      -> <Игра>
#  2) папка-«контейнер» (Games, Program Files, Epic Games, GOG Games, XboxGames ...) -> первая папка под ней
#  3) иначе поднимаемся из служебных папок (bin, x64, Win64, Binaries, Shipping ...);
#     для Unreal дополнительно: <Корень>\Engine + <Корень>\<Проект>\Content -> корень выше проекта.
# Диск/«Загрузки»/«Рабочий стол»/сам контейнер корнем не считаются ('' = не удалось определить).
$script:gameRootCache = @{}
$script:gameRootInnerDirs = @('bin','bin32','bin64','binaries','win64','win32','x64','x86','x86_64','x64_dx11','x64_dx12','shipping','release','retail','windowsnoeditor')
$script:gameRootContainerDirs = @('games','program files','program files (x86)','xboxgames','epic games','gog games','origin games','ea games','downloads','desktop','documents')

# Ярлык-обёртка SCLauncher.exe (игры Epic/GOG/Ubisoft/Battle.net): в Exe стоит сам SCLauncher.exe
# (лежит в папке программы, а не в папке игры), а игра описана в параметрах запуска:
#   --dir "<папка игры>"  [--exe "<exe игры>"]  (формат — Format-SCLauncherArgs).
# Возвращает IsWrapper, Dir (папка игры из --dir) и Exe (из --exe), пустые строки если не заданы.
function Get-ShortcutWrapperInfo ([string]$Exe, [string]$LaunchOptions) {
    $r = [PSCustomObject]@{ IsWrapper = $false; Dir = ''; Exe = '' }
    try {
        $e = ([string]$Exe).Trim().Trim('"')
        $lo = [string]$LaunchOptions
        $isW = $false
        if ($e -and ([System.IO.Path]::GetFileName($e) -ieq 'SCLauncher.exe')) { $isW = $true }
        elseif ($lo -match '--uri\s+"' -and $lo -match '--dir\s+"') { $isW = $true }
        if (-not $isW) { return $r }
        $r.IsWrapper = $true
        if ($lo -match '--dir\s+"([^"]+)"') { $r.Dir = $Matches[1].Trim().TrimEnd('\') }
        if ($lo -match '--exe\s+"([^"]+)"') { $r.Exe = $Matches[1].Trim() }
    } catch {}
    return $r
}

function Get-GameRootFromExePath ([string]$Exe, [string]$StartDir = '') {
    try {
        $p = ([string]$Exe).Trim().Trim('"')
        if ([string]::IsNullOrWhiteSpace($p) -or -not [System.IO.Path]::IsPathRooted($p)) { $p = ([string]$StartDir).Trim().Trim('"') }
        if ([string]::IsNullOrWhiteSpace($p) -or -not [System.IO.Path]::IsPathRooted($p)) { return '' }
        # Сама обёртка SCLauncher.exe лежит в папке программы — путь к ней корнем игры быть не может.
        if ([System.IO.Path]::GetFileName($p) -ieq 'SCLauncher.exe') { return '' }
        $ck = $p.ToUpperInvariant()
        if ($script:gameRootCache.ContainsKey($ck)) { return [string]$script:gameRootCache[$ck] }

        $dir = $p.TrimEnd('\')
        if ($dir -match '\.(exe|bat|cmd|com|lnk|jar|ps1)$') { $dir = [System.IO.Path]::GetDirectoryName($dir) }
        $pathRoot = [System.IO.Path]::GetPathRoot($dir)
        if ([string]::IsNullOrEmpty($pathRoot) -or $dir.Length -le $pathRoot.TrimEnd('\').Length) { $script:gameRootCache[$ck] = ''; return '' }
        $segs = @($dir.Substring($pathRoot.Length).Trim('\').Split('\') | Where-Object { $_ -ne '' })
        $n = $segs.Count
        $idx = -1

        # 1) ...\steamapps\common\<Игра>
        for ($i = 0; $i -lt ($n - 2); $i++) {
            if ($segs[$i] -ieq 'steamapps' -and $segs[$i + 1] -ieq 'common') { $idx = $i + 2 }
        }
        # 2) ...\<Контейнер>\<Игра> (берём самый глубокий контейнер)
        if ($idx -lt 0) {
            for ($i = 0; $i -lt ($n - 1); $i++) {
                if ($script:gameRootContainerDirs -contains $segs[$i].ToLowerInvariant()) { $idx = $i + 1 }
            }
        }
        # 3) подъём из служебных папок
        if ($idx -lt 0) {
            $idx = $n - 1
            while ($idx -ge 0 -and ($script:gameRootInnerDirs -contains $segs[$idx].ToLowerInvariant())) { $idx-- }
            if ($idx -ge 1) {
                # Unreal: <Корень>\Engine и <Корень>\<Проект>\Content
                $cur = $pathRoot + ($segs[0..$idx] -join '\')
                $par = $pathRoot + ($segs[0..($idx - 1)] -join '\')
                if ([System.IO.Directory]::Exists([System.IO.Path]::Combine($cur, 'Content')) -and [System.IO.Directory]::Exists([System.IO.Path]::Combine($par, 'Engine'))) { $idx-- }
            }
        }

        $root = ''
        if ($idx -ge 0) {
            $root = $pathRoot + ($segs[0..$idx] -join '\')
            $last = $segs[$idx].ToLowerInvariant()
            if ($script:gameRootContainerDirs -contains $last) { $root = '' }
            # C:\Users\<имя> (корень профиля) игрой не бывает.
            if ($idx -ge 1 -and $segs[$idx - 1] -ieq 'users') { $root = '' }
        }
        $script:gameRootCache[$ck] = $root
        return $root
    } catch { return '' }
}

# Полная папка игры для ярлыка (запомненная при добавлении; иначе — по папкам игр из панелей); '' если неизвестна.
function Get-GameFolderForEntry ($Entry) {
    try {
        if ($null -eq $Entry -or [string]$Entry.Kind -ne 'shortcut') { return '' }
        $exe = ([string]$Entry.Exe).Trim().Trim('"')
        $mapKey = Get-GameFolderKey $exe ([string]$Entry.LaunchOptions)
        # Обёртка SCLauncher.exe: exe в ярлыке — не игра, поэтому корень берём из параметров запуска.
        $wrap = Get-ShortcutWrapperInfo $exe ([string]$Entry.LaunchOptions)
        if ($wrap.IsWrapper) {
            $exe = ''
            # 1) --dir — папка игры, записанная программой/лаунчером (при переносе игры обновляется вместе с ярлыком).
            $wd = [string]$wrap.Dir
            if (-not [string]::IsNullOrWhiteSpace($wd) -and [System.IO.Directory]::Exists($wd)) {
                $wRoot = ''
                try { $wRoot = [System.IO.Path]::GetPathRoot($wd) } catch {}
                if (-not ($wRoot -and ($wRoot.TrimEnd('\') -eq $wd.TrimEnd('\')))) { return $wd }
            }
            # 2) --exe — exe игры: корень по его пути (на случай, если --dir устарел или не задан).
            if (-not [string]::IsNullOrWhiteSpace([string]$wrap.Exe)) {
                $wr = [string](Get-GameRootFromExePath ([string]$wrap.Exe) '')
                if ($wr -and [System.IO.Directory]::Exists($wr)) { return $wr }
            }
            # 3) дальше — StartDir, запомненная папка и панели (exe обёртки в проверках не участвует).
        }
        $map = Get-GameFolderMap
        $k = $mapKey
        if ($map.ContainsKey($k)) {
            $saved = [string]$map[$k]
            # Запомненная папка — только подсказка: принимаем её, если она существует и exe всё ещё внутри
            # (при ручном переносе игры вне программы запись устаревает и просто игнорируется).
            if (-not [string]::IsNullOrWhiteSpace($saved) -and [System.IO.Directory]::Exists($saved) -and
                ([string]::IsNullOrWhiteSpace($exe) -or (Test-FileInsideRoot $exe $saved))) { return $saved }
        }
        if ($null -eq $global:installedSteamGames -or $global:installedSteamGames.Count -eq 0) {
            return [string](Get-GameRootFromExePath $exe ([string]$Entry.StartDir))
        }
        $start = ''
        foreach ($cand in @($exe, ([string]$Entry.StartDir).Trim().Trim('"'))) {
            if ([string]::IsNullOrWhiteSpace($cand)) { continue }
            $cur = $cand
            $best = ''
            for ($i = 0; $i -lt 12 -and $cur; $i++) {
                if ($global:installedSteamGames.ContainsKey((Get-NormalizedGamePathKey $cur))) { $best = $cur }
                $parent = $null
                try { $parent = [System.IO.Path]::GetDirectoryName($cur) } catch { $parent = $null }
                if ([string]::IsNullOrEmpty($parent) -or $parent -eq $cur) { break }
                $cur = $parent
            }
            if ($best) { return $best }
        }
        # Панели ничего не знают об этой игре (перенесена/удалена из панели) — определяем корень по пути exe.
        return [string](Get-GameRootFromExePath $exe ([string]$Entry.StartDir))
    } catch {}
    return ''
}

# ===================== ВЕРСИЯ DLSS НА ПЛИТКАХ БИБЛИОТЕКИ =====================
# Внизу каждой плитки на вкладке Steam рисуется полоса «DLSS ........ v310.7.129».
# Версия берётся из nvngx_dlss.dll в папке игры (поиск в фоновом потоке, глубина до 12 папок);
# если файла нет или версия не читается — «N/A». Хвостовые нули версии не показываются
# (310.7.129.0 -> v310.7.129, 310.7.0.0 -> v310.7).
$script:libDlssState = $null
$script:libDlssPs = $null
$script:libDlssRs = $null
$script:libDlssLastCount = -1

# Плитки с полосой DLSS рисуются НАТИВНО (C#), а не обработчиком Paint на PowerShell: при перетаскивании
# ползунка прокрутки плитки перерисовываются десятки раз в секунду, и скриптовый Paint не успевал —
# обложки на время «обрезались» справа. В контрол передаётся только готовый текст версии (DlssText).
$script:libDlssNativeOk = $false
function Initialize-LibDlssNative {
    if ($script:libDlssNativeOk) { return }
    try {
        if (-not ('SCDlssPicture' -as [type])) {
            Add-Type -ReferencedAssemblies @('System.Drawing','System.Windows.Forms') -TypeDefinition @'
using System;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Windows.Forms;

public static class SCDlssBar
{
    static Font fL = new Font("Segoe UI Semibold", 9f);
    static Font fR = new Font("Segoe UI", 9f);
    static SolidBrush br = new SolidBrush(Color.FromArgb(185, 0, 0, 0));
    static TextFormatFlags tf = TextFormatFlags.NoPadding | TextFormatFlags.SingleLine;

    public static void Draw(Graphics g, int w, int h, string ver)
    {
        if (ver == null) return;
        int bh = 24;
        g.FillRectangle(br, 0, h - bh, w, bh);
        int ty = h - bh + (bh - fL.Height) / 2;
        TextRenderer.DrawText(g, "DLSS", fL, new Point(8, ty), Color.White, tf);
        int vw = TextRenderer.MeasureText(ver, fR, new Size(1000, 40), tf).Width;
        TextRenderer.DrawText(g, ver, fR, new Point(w - vw - 8, ty), Color.FromArgb(225, 228, 232), tf);
    }

    // Галочка выбора: скруглённый квадрат 24x24 в точке (8, 8), те же цвета и штрихи, что у плиток лаунчеров.
    // state: 0 — не рисовать, 1 — не выбрано, 2 — выбрано.
    public static void DrawCheck(Graphics g, int state)
    {
        if (state <= 0) return;
        var oldMode = g.SmoothingMode;
        g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
        try
        {
            int d = 12;
            using (var path = new System.Drawing.Drawing2D.GraphicsPath())
            {
                path.AddArc(8, 8, d, d, 180, 90);
                path.AddArc(32 - d, 8, d, d, 270, 90);
                path.AddArc(32 - d, 32 - d, d, d, 0, 90);
                path.AddArc(8, 32 - d, d, d, 90, 90);
                path.CloseFigure();
                Color fill = state == 2 ? Color.FromArgb(30, 144, 230) : Color.FromArgb(245, 247, 250);
                Color edge = state == 2 ? fill : Color.FromArgb(150, 158, 168);
                using (var fb = new SolidBrush(fill))
                using (var ep = new Pen(edge, 1.2f))
                {
                    g.FillPath(fb, path);
                    g.DrawPath(ep, path);
                }
            }
            if (state == 2)
            {
                using (var cp = new Pen(Color.White, 2.4f))
                {
                    cp.StartCap = System.Drawing.Drawing2D.LineCap.Round;
                    cp.EndCap = System.Drawing.Drawing2D.LineCap.Round;
                    cp.LineJoin = System.Drawing.Drawing2D.LineJoin.Round;
                    g.DrawLines(cp, new PointF[] { new PointF(13, 20), new PointF(18, 25), new PointF(27, 14) });
                }
            }
        }
        finally { g.SmoothingMode = oldMode; }
    }
}

// WS_EX_COMPOSITED (0x02000000): все дочерние окна рисуются через общий буфер. Без этого на панели с сотнями
// дочерних окон при прокрутке (особенно при перетаскивании ползунка) часть плиток не успевает перерисоваться.
public class SCCompositedPanel : Panel
{
    // Плавная прокрутка колёсиком: каждое «деление» колеса сдвигает целевую позицию, а текущая плавно
    // (по экспоненте, по реальному времени) к ней догоняет. Вся анимация — здесь, в C#, без PowerShell на кадр.
    public bool SmoothWheel = true;
    public int WheelPixels = 120;      // пикселей на одно деление колеса
    public double TauMs = 85.0;        // «инерция»: меньше — резче, больше — мягче
    double cur, target;
    int lastSet;
    bool animating;
    long lastTicks;
    Timer tm;
    Stopwatch sw = new Stopwatch();

    protected override CreateParams CreateParams
    {
        get
        {
            CreateParams cp = base.CreateParams;
            cp.ExStyle |= 0x02000000;
            return cp;
        }
    }

    [DllImport("user32.dll")]
    static extern bool RedrawWindow(IntPtr hWnd, IntPtr lprcUpdate, IntPtr hrgnUpdate, uint flags);

    int MaxScroll()
    {
        return Math.Max(0, DisplayRectangle.Height - ClientSize.Height);
    }

    void StopAnim()
    {
        animating = false;
        if (tm != null) tm.Stop();
    }

    protected override void WndProc(ref Message m)
    {
        if (m.Msg == 0x020A && SmoothWheel && (Control.ModifierKeys & Keys.Control) == 0)   // WM_MOUSEWHEEL
        {
            int delta = (short)((m.WParam.ToInt64() >> 16) & 0xFFFF);
            if (delta != 0 && MaxScroll() > 0)
            {
                int pos = -DisplayRectangle.Y;
                if (!animating || Math.Abs(pos - lastSet) > 1) { cur = pos; target = pos; lastSet = pos; }
                target -= (delta / 120.0) * WheelPixels;
                if (target < 0) target = 0;
                if (target > MaxScroll()) target = MaxScroll();
                if (!animating)
                {
                    animating = true;
                    if (tm == null) { tm = new Timer(); tm.Interval = 8; tm.Tick += OnAnimTick; }
                    sw.Restart();
                    lastTicks = 0;
                    tm.Start();
                }
                return;
            }
        }
        else if (m.Msg == 0x0115 || m.Msg == 0x0114)   // WM_VSCROLL / WM_HSCROLL: полосу тянут руками — анимацию прекращаем
        {
            StopAnim();
        }
        base.WndProc(ref m);
    }

    void OnAnimTick(object sender, EventArgs e)
    {
        if (!animating || IsDisposed) { StopAnim(); return; }
        int actual = -DisplayRectangle.Y;
        if (Math.Abs(actual - lastSet) > 1) { StopAnim(); return; }   // позицию сменил кто-то другой (пересборка сетки и т. п.)
        long now = sw.ElapsedMilliseconds;
        double dt = Math.Max(1, now - lastTicks);
        lastTicks = now;
        double k = 1.0 - Math.Exp(-dt / TauMs);
        cur += (target - cur) * k;
        if (Math.Abs(target - cur) < 0.6) cur = target;
        int y = (int)Math.Round(cur);
        if (y != actual)
        {
            AutoScrollPosition = new Point(-DisplayRectangle.X, y);
            lastSet = -DisplayRectangle.Y;
            // Рисуем кадр сразу (RDW_UPDATENOW | RDW_ALLCHILDREN), а не ждём низкоприоритетного WM_PAINT:
            // иначе несколько тиков подряд сдвигают позицию, а перерисовка происходит раз в несколько кадров.
            if (IsHandleCreated) RedrawWindow(Handle, IntPtr.Zero, IntPtr.Zero, 0x0100 | 0x0080);
        }
        if (cur == target) StopAnim();
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing && tm != null) { tm.Stop(); tm.Dispose(); tm = null; }
        base.Dispose(disposing);
    }
}

public class SCDlssPicture : PictureBox
{
    public string DlssText;
    public int CheckState;   // 0 — без галочки, 1 — не выбрано, 2 — выбрано (см. SCDlssBar.DrawCheck)
    int cacheChk;
    // Готовый кадр плитки (обложка + полоса DLSS) в формате 32bppPArgb: при прокрутке перерисовка плитки —
    // один быстрый BitBlt вместо конвертации формата обложки, масштабирования и рисования текста на каждый кадр.
    Bitmap cache;
    Image cacheSrc;
    string cacheTxt;

    public SCDlssPicture()
    {
        SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint, true);
    }

    void Rebuild(Image src, int w, int h)
    {
        if (cache != null) { cache.Dispose(); cache = null; }
        Bitmap bmp = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.Clear(BackColor);
            try { if (src != null) g.DrawImage(src, 0, 0, src.Width, src.Height); } catch { }
            SCDlssBar.Draw(g, w, h, DlssText);
            SCDlssBar.DrawCheck(g, CheckState);
        }
        // GDI-текст не пишет альфа-канал, а плитка всегда непрозрачная — выставляем alpha = 255 вручную.
        Rectangle r = new Rectangle(0, 0, w, h);
        BitmapData d = bmp.LockBits(r, ImageLockMode.ReadWrite, PixelFormat.Format32bppPArgb);
        try
        {
            int bytes = Math.Abs(d.Stride) * d.Height;
            byte[] buf = new byte[bytes];
            Marshal.Copy(d.Scan0, buf, 0, bytes);
            for (int i = 3; i < bytes; i += 4) buf[i] = 255;
            Marshal.Copy(buf, 0, d.Scan0, bytes);
        }
        finally { bmp.UnlockBits(d); }
        cache = bmp;
        cacheSrc = src;
        cacheTxt = DlssText;
        cacheChk = CheckState;
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        int w = ClientSize.Width, h = ClientSize.Height;
        if (w <= 0 || h <= 0) return;
        Image src = Image;
        if (cache == null || !object.ReferenceEquals(src, cacheSrc) || cacheTxt != DlssText || cacheChk != CheckState || cache.Width != w || cache.Height != h)
            Rebuild(src, w, h);
        e.Graphics.DrawImageUnscaled(cache, 0, 0);
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing && cache != null) { cache.Dispose(); cache = null; }
        base.Dispose(disposing);
    }
}

public class SCDlssLabel : Label
{
    public string DlssText;
    public int CheckState;
    public SCDlssLabel()
    {
        SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint, true);
    }
    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e);
        SCDlssBar.Draw(e.Graphics, ClientSize.Width, ClientSize.Height, DlssText);
        SCDlssBar.DrawCheck(e.Graphics, CheckState);
    }
}
'@ -ErrorAction Stop
        }
        $script:libDlssNativeOk = $true
    } catch {
        try { Write-LauncherLog ('Initialize-LibDlssNative: ' + $_.Exception.Message) } catch {}
    }
}

# Корень игры для записи считается один раз за скан (кэш сбрасывается в Start-LibDlssScan): Paint плиток
# вызывает эту функцию очень часто, и без кэша каждый вызов ходил бы на диск (Directory.Exists и т. п.).
$script:libDlssDirCache = @{}

function Get-LibDlssEntryDir ($Entry) {
    $ck = ''
    try {
        $ck = (Get-GameFolderKey ([string]$Entry.Exe) ([string]$Entry.LaunchOptions)) + '|' + ([string]$Entry.StartDir).ToUpperInvariant() + '|' + ([string]$Entry.Path).ToUpperInvariant()
        if ($script:libDlssDirCache.ContainsKey($ck)) { return [string]$script:libDlssDirCache[$ck] }
    } catch { $ck = '' }
    $res = Get-LibDlssEntryDirUncached $Entry
    if ($ck) { $script:libDlssDirCache[$ck] = $res }
    return $res
}

function Get-LibDlssEntryDirUncached ($Entry) {
    try {
        $p = ''
        # Ярлык: сначала полная папка игры (запомнена при добавлении / найдена по панелям).
        try { $p = [string](Get-GameFolderForEntry $Entry) } catch { $p = '' }
        if ([string]::IsNullOrWhiteSpace($p)) { try { $p = [string]$Entry.Path } catch {} }
        if ([string]::IsNullOrWhiteSpace($p)) {
            try {
                $ex = ([string]$Entry.Exe).Trim().Trim('"')
                if ($ex) { $p = [System.IO.Path]::GetDirectoryName($ex) }
            } catch {}
        }
        $p = ([string]$p).Trim().Trim('"').TrimEnd('\')
        if ([string]::IsNullOrWhiteSpace($p)) { return '' }
        # Корень диска не обходим (ярлык со StartDir = C:\ превратился бы в обход всего диска).
        $root = ''
        try { $root = [System.IO.Path]::GetPathRoot($p) } catch {}
        if ($root -and ($root.TrimEnd('\') -eq $p)) { return '' }
        return $p
    } catch { return '' }
}

function Stop-LibDlssScan {
    try { if ($null -ne $script:libDlssState) { $script:libDlssState['Cancel'] = $true } } catch {}
    try { if ($null -ne $script:libDlssPs) { $script:libDlssPs.Dispose() } } catch {}
    try { if ($null -ne $script:libDlssRs) { $script:libDlssRs.Dispose() } } catch {}
    $script:libDlssPs = $null
    $script:libDlssRs = $null
}

function Start-LibDlssScan ($Entries) {
    Stop-LibDlssScan
    $script:gameRootCache = @{}
    $script:libDlssDirCache = @{}
    $script:libDlssLastCount = -1
    # Libs: папка игры -> есть ли в ней хоть одна библиотека апскейлера (DLSS / FSR / XeSS / XeLL). Нужно кнопке «Обновить апскейлеры».
    $state = [hashtable]::Synchronized(@{ Results = [hashtable]::Synchronized(@{}); Libs = [hashtable]::Synchronized(@{}); Orig = [hashtable]::Synchronized(@{}); Done = $false; Cancel = $false })
    $libNames = @()
    try { $libNames = @(Get-UpscalerDefs | ForEach-Object { [string]$_.File }) } catch { $libNames = @() }
    if ($libNames.Count -eq 0) { $libNames = @('nvngx_dlss.dll') }
    $dirs = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($en in @($Entries)) {
        $d = Get-LibDlssEntryDir $en
        if ([string]::IsNullOrEmpty($d)) { continue }
        $k = Get-NormalizedGamePathKey $d
        if ($seen.ContainsKey($k)) { continue }
        $seen[$k] = $true
        [void]$dirs.Add($d)
    }
    $worker = {
        param($dirs, $state, $libNames)
        try {
            foreach ($d in $dirs) {
                if ($state['Cancel']) { break }
                $ver = ''
                $anyLib = $false
                try {
                    if ([System.IO.Directory]::Exists($d)) {
                        $found = ''
                        $queue = New-Object System.Collections.Generic.Queue[object]
                        $queue.Enqueue(@($d, 0))
                        while ($queue.Count -gt 0 -and -not $found) {
                            if ($state['Cancel']) { break }
                            $it = $queue.Dequeue()
                            $dir = [string]$it[0]
                            $depth = [int]$it[1]
                            try {
                                $cand = [System.IO.Path]::Combine($dir, 'nvngx_dlss.dll')
                                if ([System.IO.File]::Exists($cand)) { $found = $cand; $anyLib = $true; break }
                            } catch {}
                            if (-not $anyLib) {
                                foreach ($ln in $libNames) {
                                    try { if ([System.IO.File]::Exists([System.IO.Path]::Combine($dir, [string]$ln))) { $anyLib = $true; break } } catch {}
                                }
                            }
                            if ($depth -lt 12) {
                                try {
                                    foreach ($sd in [System.IO.Directory]::EnumerateDirectories($dir)) {
                                        $skip = $false
                                        try { if (([System.IO.File]::GetAttributes($sd) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $skip = $true } } catch { $skip = $true }
                                        if (-not $skip) { $queue.Enqueue(@([string]$sd, ($depth + 1))) }
                                    }
                                } catch {}
                            }
                        }
                        if ($found) {
                            $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($found)
                            $parts = @([int]$vi.FileMajorPart, [int]$vi.FileMinorPart, [int]$vi.FileBuildPart, [int]$vi.FilePrivatePart)
                            if ($parts[0] -gt 0) {
                                $n = 4
                                while ($n -gt 2 -and $parts[$n - 1] -eq 0) { $n-- }
                                $ver = 'v' + ((@($parts[0..($n - 1)])) -join '.')
                            }
                        }
                    }
                } catch {}
                $state['Libs'][$d.TrimEnd('\').ToUpperInvariant()] = $anyLib
                $state['Results'][$d.TrimEnd('\').ToUpperInvariant()] = $ver
            }
            # Второй проход: есть ли в папке игры бэкапы оригиналов (<dll>.sc_orig) — нужно кнопке «Вернуть бэкапы».
            # Идёт после версий, поэтому полосы DLSS на плитках не задерживает.
            foreach ($d in $dirs) {
                if ($state['Cancel']) { break }
                $hasOrig = $false
                try {
                    if ([System.IO.Directory]::Exists($d)) {
                        $queue = New-Object System.Collections.Generic.Queue[object]
                        $queue.Enqueue(@($d, 0))
                        $visited = 0
                        while ($queue.Count -gt 0 -and -not $hasOrig -and $visited -lt 30000) {
                            if ($state['Cancel']) { break }
                            $it = $queue.Dequeue()
                            $dir = [string]$it[0]
                            $depth = [int]$it[1]
                            $visited++
                            foreach ($ln in $libNames) {
                                try { if ([System.IO.File]::Exists([System.IO.Path]::Combine($dir, ([string]$ln + '.sc_orig')))) { $hasOrig = $true; break } } catch {}
                            }
                            if ($hasOrig) { break }
                            if ($depth -lt 12) {
                                try {
                                    foreach ($sd in [System.IO.Directory]::EnumerateDirectories($dir)) {
                                        $skip = $false
                                        try { if (([System.IO.File]::GetAttributes($sd) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $skip = $true } } catch { $skip = $true }
                                        if (-not $skip) { $queue.Enqueue(@([string]$sd, ($depth + 1))) }
                                    }
                                } catch {}
                            }
                        }
                    }
                } catch {}
                $state['Orig'][$d.TrimEnd('\').ToUpperInvariant()] = $hasOrig
            }
        } catch {}
        $state['Done'] = $true
    }
    try {
        $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $rs.Open()
        $ps = [System.Management.Automation.PowerShell]::Create()
        $ps.Runspace = $rs
        [void]$ps.AddScript($worker.ToString())
        [void]$ps.AddArgument($dirs.ToArray())
        [void]$ps.AddArgument($state)
        [void]$ps.AddArgument($libNames)
        [void]$ps.BeginInvoke()
        $script:libDlssState = $state
        $script:libDlssPs = $ps
        $script:libDlssRs = $rs
    } catch {
        $state['Done'] = $true
        $script:libDlssState = $state
    }
}

# ----- Обновление апскейлеров в играх из библиотеки -----
# Самые новые СКАЧАННЫЕ версии по каждой библиотеке: ключ поля -> { Key, Title, File, Path, Ver (System.Version) }.
function Get-UpscalerLatestLocalMap {
    $map = [ordered]@{}
    foreach ($def in @(Get-UpscalerDefs)) {
        try {
            $lv = @(Get-UpscalerLocalVersions ([string]$def.Key) ([string]$def.File))
            if ($lv.Count -eq 0) { continue }
            $map[[string]$def.Key] = [PSCustomObject]@{
                Key = [string]$def.Key; Title = [string]$def.Title; File = [string]$def.File
                Path = [string]$lv[0].Path; Ver = (ConvertTo-UpscalerFullVersion $lv[0].Num)
            }
        } catch {}
    }
    return $map
}

# System.Version всегда из 4 частей (без -1), иначе 3.1.2 окажется «меньше» 3.1.2.0.
function ConvertTo-UpscalerFullVersion ($V) {
    try {
        return (New-Object System.Version([int]$V.Major, [int]$V.Minor, [Math]::Max(0, [int]$V.Build), [Math]::Max(0, [int]$V.Revision)))
    } catch { return (New-Object System.Version(0, 0, 0, 0)) }
}

function Get-DllFullVersion ([string]$Path) {
    try {
        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($Path)
        return (New-Object System.Version([int]$vi.FileMajorPart, [int]$vi.FileMinorPart, [int]$vi.FileBuildPart, [int]$vi.FilePrivatePart))
    } catch { return (New-Object System.Version(0, 0, 0, 0)) }
}

# Обход папки игры (глубина до 12, ссылки-junction пропускаем): все копии DLL апскейлеров.
function Find-GameUpscalerFiles ([string]$Root, [string[]]$Names) {
    $res = @{}
    foreach ($nm in $Names) { $res[$nm] = New-Object System.Collections.ArrayList }
    $queue = New-Object System.Collections.Generic.Queue[object]
    $queue.Enqueue(@($Root, 0))
    $visited = 0
    while ($queue.Count -gt 0 -and $visited -lt 30000) {
        $it = $queue.Dequeue()
        $dir = [string]$it[0]
        $depth = [int]$it[1]
        $visited++
        foreach ($nm in $Names) {
            try {
                $cand = [System.IO.Path]::Combine($dir, $nm)
                if ([System.IO.File]::Exists($cand)) { [void]$res[$nm].Add($cand) }
            } catch {}
        }
        if ($depth -lt 12) {
            try {
                foreach ($sd in [System.IO.Directory]::EnumerateDirectories($dir)) {
                    $skip = $false
                    try { if (([System.IO.File]::GetAttributes($sd) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $skip = $true } } catch { $skip = $true }
                    if (-not $skip) { $queue.Enqueue(@([string]$sd, ($depth + 1))) }
                }
            } catch {}
        }
    }
    return $res
}

# Обновляет апскейлеры одной игры до последних скачанных версий. Status: updated / same / none / error.
# Файл заменяется только если версия в игре НИЖЕ скачанной (такая же или новее — не трогаем).
function Update-GameUpscalers ($Entry, $Latest) {
    $dir = ''
    try { $dir = [string](Get-LibDlssEntryDir $Entry) } catch {}
    return (Update-GameUpscalersInDir $dir $Latest)
}

# Ядро обновления по папке игры: без обращений к UI и функциям окна, поэтому его можно выполнять в фоновом runspace
# (см. Invoke-UpscalerUpdateBackground) — окно не зависает, прогресс-бар и «Отменить» работают.
function Update-GameUpscalersInDir ([string]$dir, $Latest) {
    if ([string]::IsNullOrWhiteSpace($dir) -or -not [System.IO.Directory]::Exists($dir)) {
        return [PSCustomObject]@{ Status = 'none'; Replaced = 0; Titles = @(); Error = '' }
    }
    $names = @($Latest.Values | ForEach-Object { [string]$_.File })
    $found = Find-GameUpscalerFiles $dir $names
    $targets = New-Object System.Collections.ArrayList
    $titles = New-Object System.Collections.Generic.List[string]
    $foundAny = $false
    foreach ($def in @($Latest.Values)) {
        foreach ($p in @($found[[string]$def.File])) {
            $foundAny = $true
            $cur = Get-DllFullVersion ([string]$p)
            if ($cur -ge $def.Ver) { continue }
            [void]$targets.Add(@{ Dst = [string]$p; Src = [string]$def.Path })
            if (-not $titles.Contains([string]$def.Title)) { [void]$titles.Add([string]$def.Title) }
        }
    }
    if (-not $foundAny) { return [PSCustomObject]@{ Status = 'none'; Replaced = 0; Titles = @(); Error = '' } }
    if ($targets.Count -eq 0) { return [PSCustomObject]@{ Status = 'same'; Replaced = 0; Titles = @(); Error = '' } }
    $r = Set-GameUpscalerFiles @($targets)
    if ([bool]$r.Ok) {
        return [PSCustomObject]@{ Status = 'updated'; Replaced = [int]$r.Count; Titles = @($titles); Error = '' }
    }
    return [PSCustomObject]@{ Status = 'error'; Replaced = 0; Titles = @(); Error = [string]$r.Error }
}

# Обновление одной игры в фоновом runspace. Пока оно идёт, UI-поток крутит сообщения окна (DoEvents),
# поэтому прогресс-бар, надпись и кнопка «Отменить» остаются живыми даже на больших папках игр.
# Если фоновый запуск не удался — тихо работаем в текущем потоке, как раньше.
$script:upscalerBgSrc = @{}
function Get-UpscalerBgSource ([string[]]$Funcs) {
    $ck = ($Funcs -join '|')
    if ($script:upscalerBgSrc.ContainsKey($ck)) { return [string]$script:upscalerBgSrc[$ck] }
    $sb = New-Object System.Text.StringBuilder
    foreach ($fn in $Funcs) {
        $cmd = Get-Command -Name $fn -CommandType Function -ErrorAction Stop
        $txt = ''
        try { $txt = [string]$cmd.ScriptBlock.Ast.Extent.Text } catch { $txt = '' }
        if ($txt -notmatch '^\s*function\s') { throw ('нет текста функции ' + $fn) }
        [void]$sb.AppendLine($txt)
    }
    $script:upscalerBgSrc[$ck] = $sb.ToString()
    return [string]$script:upscalerBgSrc[$ck]
}

function Invoke-UpscalerUpdateBackground ([string]$Dir, $Latest) {
    return (Invoke-UpscalerBackground @('Find-GameUpscalerFiles', 'Get-DllFullVersion', 'Set-GameUpscalerFiles', 'Update-GameUpscalersInDir') 'Update-GameUpscalersInDir' $Dir $Latest)
}

function Invoke-UpscalerRestoreBackground ([string]$Dir, $TitleOf) {
    return (Invoke-UpscalerBackground @('Find-GameUpscalerFiles', 'Test-SameFileContent', 'Restore-GameUpscalersInDir') 'Restore-GameUpscalersInDir' $Dir $TitleOf)
}

function Invoke-UpscalerBackground ([string[]]$Funcs, [string]$Entry, [string]$Dir, $Arg2) {
    $ps = $null; $rs = $null
    try {
        $src = Get-UpscalerBgSource $Funcs
        $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $rs.Open()
        $ps = [System.Management.Automation.PowerShell]::Create()
        $ps.Runspace = $rs
        [void]$ps.AddScript($src + "`r`n" + $Entry + ' $args[0] $args[1]')
        [void]$ps.AddArgument($Dir)
        [void]$ps.AddArgument($Arg2)
        $ar = $ps.BeginInvoke()
        while (-not $ar.IsCompleted) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 25
        }
        $out = @($ps.EndInvoke($ar))
        if ($ps.HadErrors -and $out.Count -eq 0) { throw 'background update failed' }
        foreach ($o in $out) { if ($null -ne $o -and $null -ne $o.PSObject.Properties['Status']) { return $o } }
        throw 'empty background result'
    } finally {
        try { if ($null -ne $ps) { $ps.Dispose() } } catch {}
        try { if ($null -ne $rs) { $rs.Dispose() } } catch {}
    }
}

# Побайтовое сравнение двух файлов (сначала длина, потом MD5) — чтобы не перезаписывать то, что уже совпадает.
function Test-SameFileContent ([string]$A, [string]$B) {
    try {
        if ((New-Object System.IO.FileInfo($A)).Length -ne (New-Object System.IO.FileInfo($B)).Length) { return $false }
        $md5 = [System.Security.Cryptography.MD5]::Create()
        try {
            $hs = New-Object System.Collections.ArrayList
            foreach ($p in @($A, $B)) {
                $fs = [System.IO.File]::OpenRead($p)
                try { [void]$hs.Add([System.BitConverter]::ToString($md5.ComputeHash($fs))) } finally { $fs.Dispose() }
            }
            return ([string]$hs[0] -eq [string]$hs[1])
        } finally { $md5.Dispose() }
    } catch { return $false }
}

# Возвращает в игре оригинальные DLL апскейлеров из бэкапов <dll>.sc_orig. Status: restored / same / none / error.
# Бэкап .sc_orig остаётся на месте — после возврата игру можно снова обновить, оригинал не потеряется.
# Порядок безопасный: сначала копия текущего файла (<dll>.sc_prev), затем замена; если любая замена не удалась
# (например, игра запущена), уже возвращённые файлы откатываются из .sc_prev.
function Restore-GameUpscalers ($Entry) {
    $dir = ''
    try { $dir = [string](Get-LibDlssEntryDir $Entry) } catch {}
    $titleOf = @{}
    foreach ($def in @(Get-UpscalerDefs)) { $titleOf[[string]$def.File] = [string]$def.Title }
    return (Restore-GameUpscalersInDir $dir $titleOf)
}

# Ядро возврата по папке игры (без UI и функций окна — выполняется в фоновом runspace, см. Invoke-UpscalerBackground).
function Restore-GameUpscalersInDir ([string]$dir, $titleOf) {
    $none = [PSCustomObject]@{ Status = 'none'; Replaced = 0; Titles = @(); Error = '' }
    if ([string]::IsNullOrWhiteSpace($dir) -or -not [System.IO.Directory]::Exists($dir)) { return $none }
    $names = @($titleOf.Keys)
    $found = Find-GameUpscalerFiles $dir $names
    $targets = New-Object System.Collections.ArrayList
    $titles = New-Object System.Collections.Generic.List[string]
    $haveBackup = $false
    foreach ($nm in $names) {
        foreach ($p in @($found[[string]$nm])) {
            $orig = [string]$p + '.sc_orig'
            if (-not [System.IO.File]::Exists($orig)) { continue }
            $haveBackup = $true
            if (Test-SameFileContent ([string]$p) $orig) { continue }
            [void]$targets.Add([PSCustomObject]@{ Dst = [string]$p; Src = $orig; Prev = ([string]$p + '.sc_prev') })
            if (-not $titles.Contains([string]$titleOf[[string]$nm])) { [void]$titles.Add([string]$titleOf[[string]$nm]) }
        }
    }
    if (-not $haveBackup) { return $none }
    if ($targets.Count -eq 0) { return [PSCustomObject]@{ Status = 'same'; Replaced = 0; Titles = @(); Error = '' } }
    $touched = New-Object System.Collections.ArrayList
    $err = ''
    try {
        foreach ($t in $targets) { [System.IO.File]::Copy($t.Dst, $t.Prev, $true) }
        foreach ($t in $targets) {
            [void]$touched.Add($t)
            try { [System.IO.File]::SetAttributes($t.Dst, [System.IO.FileAttributes]::Normal) } catch {}
            [System.IO.File]::Copy($t.Src, $t.Dst, $true)
        }
    } catch {
        $err = [string]$_.Exception.Message
        foreach ($t in $touched) { try { [System.IO.File]::Copy($t.Prev, $t.Dst, $true) } catch {} }
    }
    foreach ($t in $targets) { try { if ([System.IO.File]::Exists($t.Prev)) { [System.IO.File]::Delete($t.Prev) } } catch {} }
    if ([string]::IsNullOrEmpty($err)) {
        return [PSCustomObject]@{ Status = 'restored'; Replaced = [int]$targets.Count; Titles = @($titles); Error = '' }
    }
    return [PSCustomObject]@{ Status = 'error'; Replaced = 0; Titles = @(); Error = $err }
}

function Show-SteamLibraryBrowser {
    # Сбрасываем флаг на каждое новое открытие библиотеки: он отличает закрытие
    # кнопкой "Назад" (просто вернуться к главному окну) от закрытия крестиком/
    # Alt+F4 (это "верх" всего окна программы — такое закрытие должно завершать
    # программу целиком, а не только прятать библиотеку). См. $dlg.Add_FormClosing
    # ниже и $btnLibBack.Add_Click.
    Write-Tm 'вход в Show-SteamLibraryBrowser'
    $script:libClosingViaBack = $false
    $script:libBottomReserve = 0
    try { Initialize-LibDlssNative } catch {}
    Write-Tm 'Initialize-LibDlssNative (Add-Type и т.п.)'
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = (T 'lib_browser_title')
    $dlg.Size = New-Object System.Drawing.Size(980, 720)
    $dlg.MinimumSize = New-Object System.Drawing.Size(1040, 480)
    $dlg.StartPosition = 'CenterParent'
    # Бесшовный переход: библиотека открывается ровно поверх главного окна (те же границы), а на панели
    # задач остаётся одна кнопка программы. Размер задаём ДО создания контролов — раскладка считается от него.
    try {
        if ($null -ne $form -and $form.Visible -and $form.WindowState -eq [System.Windows.Forms.FormWindowState]::Normal) {
            $dlg.StartPosition = 'Manual'
            $dlg.Bounds = $form.Bounds
        }
    } catch {}
    $dlg.ShowInTaskbar = $false
    $dlg.MinimizeBox = $false
    $dlg.MaximizeBox = $true
    $dlg.BackColor = $steamUi.Bg
    $dlg.ForeColor = $steamUi.Text
    $dlg.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    # В окне библиотеки используем именно значок Steam, а не значок самого приложения.
    # Если steam.exe недоступен, оставляем штатную иконку программы как безопасный fallback.
    try {
        $librarySteamIcon = $null
        $steamIconCandidates = New-Object System.Collections.Generic.List[string]
        try {
            $configuredSteamExe = [string](Get-ConfiguredSteamExePath)
            if (-not [string]::IsNullOrWhiteSpace($configuredSteamExe)) { [void]$steamIconCandidates.Add($configuredSteamExe) }
        } catch {}
        try {
            $regSteamExe = (Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
            if (-not [string]::IsNullOrWhiteSpace([string]$regSteamExe)) { [void]$steamIconCandidates.Add([string]$regSteamExe) }
        } catch {}
        foreach ($steamIconPath in @('C:\Program Files (x86)\Steam\steam.exe','C:\Program Files\Steam\steam.exe')) { [void]$steamIconCandidates.Add($steamIconPath) }
        foreach ($steamIconPath in $steamIconCandidates) {
            try {
                if (-not (Test-Path -LiteralPath $steamIconPath -PathType Leaf)) { continue }
                $librarySteamIcon = [System.Drawing.Icon]::ExtractAssociatedIcon((Resolve-Path -LiteralPath $steamIconPath).Path)
                if ($null -ne $librarySteamIcon) { break }
            } catch {}
        }
        if ($null -ne $librarySteamIcon) { $dlg.Icon = $librarySteamIcon } else { $dlg.Icon = $form.Icon }
    } catch { try { $dlg.Icon = $form.Icon } catch {} }
    # Не показываем пустой кадр: окно появляется только после первой раскладки сетки.
    $dlg.Opacity = 0
    try {
        $flags = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
        [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $flags).SetValue($dlg, $true, $null)
    } catch {}

    # Кнопка "Назад" в стиле Steam: тонкая рисованная стрелка вместо иконки,
    # закрывает окно библиотеки и возвращает главное окно программы (см.
    # обработчик $btnSteamLibrary.Add_Click, который прячет $form на время
    # показа библиотеки и снова показывает его после закрытия этого диалога).
    $btnLibBack = New-Object System.Windows.Forms.Button
    $btnLibBack.Location = New-Object System.Drawing.Point(12, 10)
    $btnLibBack.Size = New-Object System.Drawing.Size(34, 34)
    $btnLibBack.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btnLibBack.FlatAppearance.BorderSize = 0
    $btnLibBack.FlatAppearance.MouseOverBackColor = $steamUi.Bg
    $btnLibBack.FlatAppearance.MouseDownBackColor = $steamUi.Bg
    $btnLibBack.BackColor = $steamUi.Bg
    $btnLibBack.Text = ''
    $btnLibBack.UseVisualStyleBackColor = $false
    $btnLibBack.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnLibBack.TabStop = $false
    $btnLibBack.AccessibleName = (T 'lib_back')
    $libBackTip = New-Object System.Windows.Forms.ToolTip
    $libBackTip.SetToolTip($btnLibBack, (T 'lib_back'))
    $script:libBackHover = $false
    $script:libBackDown = $false
    $btnLibBack.Add_MouseEnter({ $script:libBackHover = $true; $btnLibBack.Invalidate() })
    $btnLibBack.Add_MouseLeave({ $script:libBackHover = $false; $script:libBackDown = $false; $btnLibBack.Invalidate() })
    $btnLibBack.Add_MouseDown({ $script:libBackDown = $true; $btnLibBack.Invalidate() })
    $btnLibBack.Add_MouseUp({ $script:libBackDown = $false; $btnLibBack.Invalidate() })
    $btnLibBack.Add_Paint({
        param($sender, $e)
        $g = $e.Graphics
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $w = [float]$sender.ClientSize.Width
        $h = [float]$sender.ClientSize.Height
        $cx = $w / 2.0
        $cy = $h / 2.0
        # Круглая подложка в стиле Steam (при наведении / нажатии).
        if ($script:libBackDown -or $script:libBackHover) {
            $bgCol = if ($script:libBackDown) {
                [System.Drawing.Color]::FromArgb(38, 76, 108)
            } else {
                [System.Drawing.Color]::FromArgb(42, 56, 72)
            }
            $pad = 1.5
            $brush = New-Object System.Drawing.SolidBrush($bgCol)
            try { $g.FillEllipse($brush, $pad, $pad, $w - $pad * 2, $h - $pad * 2) } finally { $brush.Dispose() }
            if ($script:libBackHover -and -not $script:libBackDown) {
                $ringCol = [System.Drawing.Color]::FromArgb(70, 102, 192, 244)
                $ringPen = New-Object System.Drawing.Pen($ringCol, 1.2)
                try { $g.DrawEllipse($ringPen, $pad, $pad, $w - $pad * 2, $h - $pad * 2) } finally { $ringPen.Dispose() }
            }
        }
        # Стрелка «‹»: чуть толще, скруглённые концы, лёгкий сдвиг влево для оптического центра.
        $arrowCol = if ($script:libBackDown) {
            [System.Drawing.Color]::White
        } elseif ($script:libBackHover) {
            $steamUi.Accent
        } else {
            $steamUi.Muted
        }
        $ox = $cx - 1.0
        $arm = 6.0
        $pen = New-Object System.Drawing.Pen($arrowCol, 2.4)
        try {
            $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
            $pen.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
            $pen.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
            $pts = @(
                (New-Object System.Drawing.PointF(($ox + $arm * 0.55), ($cy - $arm))),
                (New-Object System.Drawing.PointF(($ox - $arm * 0.55), $cy)),
                (New-Object System.Drawing.PointF(($ox + $arm * 0.55), ($cy + $arm)))
            )
            $g.DrawLines($pen, $pts)
        } finally { $pen.Dispose() }
    })
    $btnLibBack.Add_Click({ $script:libClosingViaBack = $true; try { $dlg.Close() } catch {} })
    $dlg.Controls.Add($btnLibBack)

    # Поле поиска той же высоты и на том же уровне, что и кнопки (30 px, y = 12): у однострочного TextBox
    # высоту задать нельзя, поэтому он стоит без рамки внутри панели-рамки нужного размера.
    $pnlSearch = New-Object System.Windows.Forms.Panel
    $pnlSearch.Location = New-Object System.Drawing.Point(92, 12)   # 12..46 «Назад», 54..84 «Обновить», дальше поиск
    $pnlSearch.Size = New-Object System.Drawing.Size(190, 30)
    $pnlSearch.BackColor = $steamUi.Input
