    $lblCount.Text = (T 'lib_loading')
    $dlg.Controls.Add($lblCount)

    # --- Панель импорта (видна только на вкладках лаунчеров, на вкладке Steam скрыта) ---
    $script:libActiveTab = 'steam'
    $script:libTabs = New-Object System.Collections.ArrayList
    $script:libLauncherMap = @{}
    $script:libSelected = @{}
    # Выбор игр на вкладке Steam (для кнопки «Обновить апскейлеры»): ключ «тип|AppId|название».
    $script:libSteamSelected = @{}
    $script:libUpdRunning = $false
    $script:libUpdCancel = $false
    $script:libRestoreRunning = $false
    $script:libRestoreCancel = $false
