    $btnImport.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnImport.ForeColor = $steamUi.Text
    $btnImport.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
    $btnImport.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    $btnImport.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnImport.TabStop = $false
    $btnImport.Text = (T 'lib_import')
    $btnImport.Enabled = $false
    $btnImport.Visible = $false
    $btnImport.Location = New-Object System.Drawing.Point(($libToolCw - 12 - 240), 12)
