    $dlg.Controls.Add($btnImport)

    # Кнопка «Обновить апскейлеры» — тот же вид и место, что у «Импорт», но на вкладке Steam.
    $btnUpdUp = New-Object System.Windows.Forms.Button
    $btnUpdUp.Size = New-Object System.Drawing.Size(150, 30)
    $btnUpdUp.FlatStyle = 'Flat'
    $btnUpdUp.FlatAppearance.BorderColor = $steamUi.Accent2
    $btnUpdUp.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(35,78,106)
    $btnUpdUp.UseVisualStyleBackColor = $false
    $btnUpdUp.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnUpdUp.ForeColor = $steamUi.Text
    $btnUpdUp.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
    $btnUpdUp.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    $btnUpdUp.Cursor = [System.Windows.Forms.Cursors]::Hand
