    # ===== Фильтр игр на вкладке Steam =====
    # Кнопка стоит в свободном месте верхней панели (между счётчиком и «Обновить апскейлеры»).
    # Меню с галочками: что показывать — Steam, Non-Steam, ROM, каждый лаунчер отдельно, игры с библиотеками
    # апскейлеров / без них. Снятая галочка прячет категорию. Хранится «выключенное» ($script:libFilterOff),
    # поэтому пустой набор = показано всё. Набор живёт, пока запущена программа.
    if ($null -eq $script:libFilterOff) { $script:libFilterOff = @{} }
    if ($null -eq $script:libFilterOnlyLibs) { $script:libFilterOnlyLibs = $false }
    $script:libFilterCatCache = @{}
    $script:libFilterLibsState = $null

    $btnFilter = New-Object System.Windows.Forms.Button
    $btnFilter.Size = New-Object System.Drawing.Size(88, 30)
    $btnFilter.Location = New-Object System.Drawing.Point(290, 12)   # сразу за полем поиска (92..282) с зазором 8
    $btnFilter.Anchor = 'Top,Left'
    $btnFilter.FlatStyle = 'Flat'
    $btnFilter.FlatAppearance.BorderColor = $steamUi.Border
    $btnFilter.FlatAppearance.BorderSize = 1
    $btnFilter.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(35,78,106)
    $btnFilter.UseVisualStyleBackColor = $false
    $btnFilter.BackColor = $steamUi.Panel2
    $btnFilter.ForeColor = $steamUi.Text
    $btnFilter.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
    $btnFilter.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    $btnFilter.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnFilter.TabStop = $false
    $btnFilter.Visible = $false
    $dlg.Controls.Add($btnFilter)

    # Категория записи вкладки Steam: steam / nonsteam / rom / launcher:<id>. Результат кэшируем (путь к лаунчеру
    # ищется перебором игр); кэш сбрасывается при пересборке плиток.
    $getEntryFilterCat = {
        param($en)
        try {
            if ($null -eq $en) { return '' }
            $kind = [string]$en.Kind
            if ($kind -eq 'steam') { return 'steam' }
            if ($kind -ne 'shortcut') { return '' }
            $ck = [string]$en.AppId + '|' + [string]$en.Name + '|' + [string]$en.Exe
            if ($script:libFilterCatCache.ContainsKey($ck)) { return [string]$script:libFilterCatCache[$ck] }
            $cat = 'nonsteam'
            $isRom = $false
            try { $isRom = [bool](Test-ShortcutIsRomEntry $en) } catch { $isRom = $false }
            if ($isRom) { $cat = 'rom' }
            else {
                $lid = ''
                try { $lid = [string](Get-ShortcutLauncherId $en) } catch { $lid = '' }
                if (-not [string]::IsNullOrWhiteSpace($lid)) { $cat = 'launcher:' + $lid }
            }
            $script:libFilterCatCache[$ck] = $cat
            return $cat
        } catch { return '' }
    }

    # Проходит ли запись фильтр. Действует только на вкладке Steam; записи без категории не прячем.
    $passesLibFilter = {
        param($en)
        try {
            if ([string]$script:libActiveTab -ne 'steam') { return $true }
            $off = $script:libFilterOff
            $onlyLibs = [bool]$script:libFilterOnlyLibs
            if (($null -eq $off -or $off.Count -eq 0) -and -not $onlyLibs) { return $true }
            $cat = [string](& $getEntryFilterCat $en)
            if ($cat -and $null -ne $off -and $off.ContainsKey($cat)) { return $false }
            # «Только с библиотеками апскейлеров» — по результату фонового поиска; касается и ROM-ярлыков.
            if ($onlyLibs) {
                if (-not [bool](& $getEntryHasLibs $en)) { return $false }
            }
            return $true
        } catch { return $true }
    }

    $updateFilterBtn = {
        try {
            $active = (($script:libFilterOff.Count -gt 0) -or [bool]$script:libFilterOnlyLibs)
            $btnFilter.Text = (T 'lib_filter_btn') + $(if ($active) { ' ' + [string][char]0x25CF } else { ' ' + [string][char]0x25BE })
            if ($active) {
                $btnFilter.FlatAppearance.BorderColor = $steamUi.Accent2
                $btnFilter.BackColor = [System.Drawing.Color]::FromArgb(25,55,75)
            } else {
                $btnFilter.FlatAppearance.BorderColor = $steamUi.Border
                $btnFilter.BackColor = $steamUi.Panel2
            }
        } catch {}
    }
    & $updateFilterBtn

    # Применить фильтр: быстрая перестановка готовых плиток, иначе полная пересборка.
    $applyLibFilter = {
        try {
            $fastOk = $false
            try { $fastOk = [bool](& $applyTileFilter $txtSearch.Text) } catch { $fastOk = $false }
            if (-not $fastOk) { try { & $buildTiles $txtSearch.Text } catch {} }
            try { & $updateSelectionUi } catch {}
            & $updateFilterBtn
        } catch {}
    }

    # Помощники меню фильтра живут на уровне окна (не внутри обработчика кнопки): обработчики пунктов
    # выполняются позже и должны находить их так же, как остальные блоки окна.
            # Галочку рисует SCFilterRenderer (стиль как в списках игр главных панелей). Состояние: категория включена, пока её нет в $script:libFilterOff
            # (для «Только с библиотеками» — пока $script:libFilterOnlyLibs = $true).
            $isItemOn = {
                param([string]$key)
                if ($key -eq 'onlylibs') { return [bool]$script:libFilterOnlyLibs }
                return (-not $script:libFilterOff.ContainsKey($key))
            }
            $paintItem = {
                param($mi)
                $on = [bool](& $isItemOn ([string]$mi.Tag))
                $mi.Checked = $on
                $mi.Text = [string]$mi.AccessibleName
                $mi.ForeColor = $steamUi.Text
            }
    $btnFilter.Add_Click({
        try {
            if ($script:libUpdRunning -or $script:libRestoreRunning -or $script:libImportRunning) { return }
            if ($null -eq $script:libFilterOff) { $script:libFilterOff = @{} }
            if (-not ('SCFilterRenderer' -as [type])) {
                Add-Type -ReferencedAssemblies @('System.Drawing','System.Windows.Forms') -TypeDefinition @'
using System.Drawing;
using System.Windows.Forms;
public class SCFilterColors : ProfessionalColorTable
{
    private static readonly Color Bg = Color.FromArgb(22, 28, 36);
    private static readonly Color Hover = Color.FromArgb(35, 78, 106);
    private static readonly Color Line = Color.FromArgb(55, 65, 75);
    public override Color ToolStripDropDownBackground { get { return Bg; } }
    public override Color ImageMarginGradientBegin { get { return Bg; } }
