    # Кнопка «Обновить» (значок кругового обновления) в верхней панели: между «Назад» и полем поиска.
    # Стоит на месте и не двигается. F5 делает то же (см. $refreshLibraryAll).
    $script:libRefreshHover = $false
    $btnLibRefresh = New-Object System.Windows.Forms.Button
    $btnLibRefresh.Size = New-Object System.Drawing.Size(30, 30)
    $btnLibRefresh.Location = New-Object System.Drawing.Point(54, 12)
    $btnLibRefresh.Anchor = 'Top,Left'
    $btnLibRefresh.FlatStyle = 'Flat'
    $btnLibRefresh.FlatAppearance.BorderColor = $steamUi.Border
    $btnLibRefresh.FlatAppearance.BorderSize = 1
    $btnLibRefresh.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(35,78,106)
    $btnLibRefresh.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(25,55,75)
    $btnLibRefresh.UseVisualStyleBackColor = $false
    $btnLibRefresh.BackColor = $steamUi.Panel2
    $btnLibRefresh.Text = ''
    $btnLibRefresh.AccessibleName = (T 'btn_refresh')
    $btnLibRefresh.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnLibRefresh.TabStop = $false
    $btnLibRefresh.Add_MouseEnter({ $script:libRefreshHover = $true; $btnLibRefresh.Invalidate() })
    $btnLibRefresh.Add_MouseLeave({ $script:libRefreshHover = $false; $btnLibRefresh.Invalidate() })
    $btnLibRefresh.Add_Paint({
        param($sender, $e)
        $pen = $null; $br = $null
        try {
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $col = if (-not $sender.Enabled) { $steamUi.Muted } elseif ($script:libRefreshHover) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(214, 222, 234) }
            $pen = New-Object System.Drawing.Pen($col, 2.0)
            $pen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
            $br = New-Object System.Drawing.SolidBrush($col)
            $cx = [double]$sender.ClientSize.Width / 2.0
            $cy = [double]$sender.ClientSize.Height / 2.0
            $r = 7.0; $start = -40.0; $sweep = 290.0
            $g.DrawArc($pen, [single]($cx - $r), [single]($cy - $r), [single]($r * 2), [single]($r * 2), [single]$start, [single]$sweep)
            # наконечник на конце дуги, по касательной (по часовой стрелке)
            $th = ($start + $sweep) * [Math]::PI / 180.0
            $ex = $cx + $r * [Math]::Cos($th); $ey = $cy + $r * [Math]::Sin($th)
            $tx = -[Math]::Sin($th); $ty = [Math]::Cos($th)
            $nx = [Math]::Cos($th);  $ny = [Math]::Sin($th)
            $head = [System.Drawing.PointF[]]@(
                (New-Object System.Drawing.PointF(($ex + $tx * 4.2), ($ey + $ty * 4.2))),
                (New-Object System.Drawing.PointF(($ex + $nx * 3.6), ($ey + $ny * 3.6))),
                (New-Object System.Drawing.PointF(($ex - $nx * 3.6), ($ey - $ny * 3.6))))
            $g.FillPolygon($br, $head)
        } catch {} finally {
            if ($null -ne $pen) { $pen.Dispose() }
            if ($null -ne $br) { $br.Dispose() }
        }
    })
    $dlg.Controls.Add($btnLibRefresh)
    $btnLibRefresh.BringToFront()

    $tabBar.Add_Paint({
        param($sender, $e)
        $fontName = $null; $fontCnt = $null; $penLine = $null
        try {
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $fontName = New-Object System.Drawing.Font('Segoe UI Semibold', 10)
            $fontCnt = New-Object System.Drawing.Font('Segoe UI', 9)
            $tf = [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
            $huge = New-Object System.Drawing.Size(1000, 40)
            $w = [int]$sender.ClientSize.Width
            $h = [int]$sender.ClientSize.Height
            $penLine = New-Object System.Drawing.Pen($steamUi.Border)
            $g.DrawLine($penLine, 0, ($h - 1), $w, ($h - 1))
            $libTabIcoPx = [int]$global:LibIconSize   # один размер значка для всех вкладок
            $rects = New-Object System.Collections.ArrayList
            $x = 4
            foreach ($tab in @($script:libTabs)) {
                $id = [string]$tab.Id
                $active = ($id -eq [string]$script:libActiveTab)
                $hover = ($id -eq [string]$script:libTabHover)
                $nameTxt = [string]$tab.Name
                $cntTxt = [string]$tab.Count
                $nameW = [System.Windows.Forms.TextRenderer]::MeasureText($nameTxt, $fontName, $huge, $tf).Width
                $cntW = [System.Windows.Forms.TextRenderer]::MeasureText($cntTxt, $fontCnt, $huge, $tf).Width
                $rw = 14 + $libTabIcoPx + 8 + $nameW + 6 + $cntW + 14
                if ($hover -and -not $active) {
                    $hb = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(14, 255, 255, 255))
                    try { $g.FillRectangle($hb, $x, 0, $rw, ($h - 1)) } finally { $hb.Dispose() }
                }
                if ($null -ne $tab.Icon) {
                    try { $g.DrawImage($tab.Icon, [int]($x + 14), [int](($h - $libTabIcoPx) / 2), $libTabIcoPx, $libTabIcoPx) } catch {}
                }
                $nameCol = if ($active) { [System.Drawing.Color]::White } elseif ($hover) { $steamUi.Text } else { $steamUi.Muted }
                $tx = $x + 14 + $libTabIcoPx + 8
                $ty1 = [int](($h - $fontName.Height) / 2)
                [System.Windows.Forms.TextRenderer]::DrawText($g, $nameTxt, $fontName, (New-Object System.Drawing.Point($tx, $ty1)), $nameCol, $tf)
                $ty2 = [int](($h - $fontCnt.Height) / 2) + 1
                [System.Windows.Forms.TextRenderer]::DrawText($g, $cntTxt, $fontCnt, (New-Object System.Drawing.Point(($tx + $nameW + 6), $ty2)), $steamUi.Muted, $tf)
                if ($active) {
                    $ub = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(30, 144, 230))
                    try { $g.FillRectangle($ub, $x, ($h - 3), $rw, 3) } finally { $ub.Dispose() }
                }
                [void]$rects.Add([PSCustomObject]@{ Id = $id; X = [int]$x; W = [int]$rw })
                $x += $rw + 4
            }
            $script:libTabRects = @($rects)
        } catch {
        } finally {
            if ($null -ne $fontName) { $fontName.Dispose() }
            if ($null -ne $fontCnt) { $fontCnt.Dispose() }
            if ($null -ne $penLine) { $penLine.Dispose() }
        }
    })
    $tabBar.Add_MouseMove({
        param($sender, $e)
        try {
            $hit = ''
            foreach ($r in @($script:libTabRects)) {
                if ($e.X -ge $r.X -and $e.X -lt ($r.X + $r.W)) { $hit = [string]$r.Id; break }
            }
            $sender.Cursor = if ($hit) { [System.Windows.Forms.Cursors]::Hand } else { [System.Windows.Forms.Cursors]::Default }
            if ($hit -ne [string]$script:libTabHover) { $script:libTabHover = $hit; $sender.Invalidate() }
        } catch {}
    })
    $tabBar.Add_MouseLeave({
        try { if ([string]$script:libTabHover -ne '') { $script:libTabHover = ''; $tabBar.Invalidate() } } catch {}
    })
    $tabBar.Add_MouseClick({
        param($sender, $e)
        try {
            foreach ($r in @($script:libTabRects)) {
                if ($e.X -ge $r.X -and $e.X -lt ($r.X + $r.W)) { & $switchTab ([string]$r.Id); break }
            }
        } catch {}
    })


    if ($script:libDlssNativeOk) { $scroll = New-Object SCCompositedPanel } else { $scroll = New-Object System.Windows.Forms.Panel }
    $scroll.Location = New-Object System.Drawing.Point(12, 96)
    $scroll.Size = New-Object System.Drawing.Size(([Math]::Max(100, $dlg.ClientSize.Width - 24)), ([Math]::Max(100, $dlg.ClientSize.Height - 108 - [int]$script:libBottomReserve)))
    $scroll.AutoScroll = $true
    $scroll.BackColor = $steamUi.Panel
    $scroll.Anchor = 'Top,Bottom,Left,Right'
    try {
        $scroll.HorizontalScroll.Enabled = $false
        $scroll.HorizontalScroll.Visible = $false
    } catch {}
    try {
        $flags = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
        [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $flags).SetValue($scroll, $true, $null)
    } catch {}
    $dlg.Controls.Add($scroll)

    $flow = New-Object System.Windows.Forms.FlowLayoutPanel
    $flow.Location = New-Object System.Drawing.Point(0, 0)
    $flow.FlowDirection = [System.Windows.Forms.FlowDirection]::LeftToRight
    $flow.WrapContents = $true
    $flow.AutoSize = $false
    $flow.BackColor = $steamUi.Panel
    $flow.Padding = New-Object System.Windows.Forms.Padding(0, 8, 0, 8)
    $flow.Margin = New-Object System.Windows.Forms.Padding(0)
    try {
        $flags = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
        [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $flags).SetValue($flow, $true, $null)
    } catch {}
    $scroll.Controls.Add($flow)

    # Плитка 140x220, margin 6 с каждой стороны → внешняя ширина 152.
    $script:libTileInnerW = 150
    $script:libTileInnerH = 225
    $script:libTileMargin = 6

    # Применить ширину сетки под текущий ClientSize (без горизонтального скролла).
    # Раскладка сетки: ширина всегда = ClientSize скролла (после учёта
    # вертикальной полосы). Высоту считаем сами — AutoSize по ширине не
    # используем, чтобы PreferredSize не раздувал горизонтальный скролл.
    $applyLibraryFlowWidth = {
        param([int]$avail)
        $avail = [Math]::Max(120, $avail)
        $tileOuter = [int]$script:libTileInnerW + (2 * [int]$script:libTileMargin)
        if ($tileOuter -lt 1) { $tileOuter = 1 }
        $cols = [Math]::Max(1, [int][Math]::Floor($avail / [double]$tileOuter))
        $contentW = $cols * $tileOuter
        $padLeft = [Math]::Max(0, [int](($avail - $contentW) / 2))
        $count = [int]$flow.Controls.Count
        if ([int]$script:libTileCountOverride -gt $count) { $count = [int]$script:libTileCountOverride }
        $rows = if ($count -le 0) { 0 } else { [int][Math]::Ceiling($count / [double]$cols) }
        $tileH = [int]$script:libTileInnerH + (2 * [int]$script:libTileMargin)
        # padding top+bottom = 8+8
        $contentH = if ($rows -le 0) { 16 } else { 16 + ($rows * $tileH) }

        $flow.SuspendLayout()
        try {
            $flow.AutoSize = $false
            $flow.Padding = New-Object System.Windows.Forms.Padding($padLeft, 8, 0, 8)
            $flow.Width = $avail
            $flow.Height = $contentH
        } finally {
            $flow.ResumeLayout($true)
        }
        return $contentH
    }

    $forceNoHScroll = {
        try {
            $scroll.HorizontalScroll.Maximum = 0
            $scroll.HorizontalScroll.Value = 0
            $scroll.HorizontalScroll.Visible = $false
            $scroll.HorizontalScroll.Enabled = $false
            # AutoScrollMinSize: ширина не больше клиента — иначе полоса снизу.
            $ms = $scroll.AutoScrollMinSize
            $cw = [Math]::Max(1, [int]$scroll.ClientSize.Width)
            if ($ms.Width -gt $cw) {
                $scroll.AutoScrollMinSize = New-Object System.Drawing.Size($cw, $ms.Height)
            }
            # Жёсткая подстраховка поверх всей логики выше: даже если из-за
            # округления ширины плиток/паддингов WinForms всё же решит, что
            # горизонтальная полоса нужна, прячем её напрямую через WinAPI.
            if ($scroll.IsHandleCreated) {
                [Win32ScrollBarHelper]::HideHorizontal($scroll.Handle)
            }
        } catch {}
    }

    $resetLibraryScroll = {
        param([int]$preferY = -1, [int]$contentH = -1)
        try {
            if ($contentH -lt 0) {
                $contentH = [Math]::Max(0, [int]$flow.Height)
            }
            $cw = [Math]::Max(1, [int]$scroll.ClientSize.Width)
            $scroll.AutoScrollMinSize = New-Object System.Drawing.Size(0, 0)
            # Ширина MinSize = 0 (не требуем гориз. прокрутки); высота = контент.
            $scroll.AutoScrollMinSize = New-Object System.Drawing.Size(0, $contentH)
            & $forceNoHScroll
            $viewH = [Math]::Max(1, [int]$scroll.ClientSize.Height)
            $maxY = [Math]::Max(0, $contentH - $viewH)
            if ($preferY -lt 0) {
                try { $preferY = -[int]$scroll.AutoScrollPosition.Y } catch { $preferY = 0 }
            }
            if ($preferY -lt 0) { $preferY = 0 }
            if ($preferY -gt $maxY) { $preferY = $maxY }
            $scroll.AutoScrollPosition = New-Object System.Drawing.Point(0, $preferY)
            & $forceNoHScroll
            # Программная установка AutoScrollPosition у WinForms Panel не
            # всегда стирает предыдущий кадр под новой раскладкой — остаются
            # "призраки" старых плиток на экране. Принудительно перерисовываем.
            try { $scroll.Invalidate($true) } catch {}
            if (-not $script:libReflowing) { try { $scroll.Update() } catch {} }
        } catch {}
    }

    $syncLibraryFlowWidth = {
        try {
            $savedY = 0
            try { $savedY = -[int]$scroll.AutoScrollPosition.Y } catch { $savedY = 0 }

            $sbw = [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth
            $rawW = [Math]::Max(120, [int]$scroll.ClientSize.Width)
            $viewH = [Math]::Max(1, [int]$scroll.ClientSize.Height)
            $tileOuter = [int]$script:libTileInnerW + (2 * [int]$script:libTileMargin)
            if ($tileOuter -lt 1) { $tileOuter = 1 }
            $count = [int]$flow.Controls.Count
            if ([int]$script:libTileCountOverride -gt $count) { $count = [int]$script:libTileCountOverride }

            # Если контент выше окна, вертикальная полоса появится и отъест ширину.
            # До её появления ClientSize ещё «полный» — заранее вычитаем sbw,
            # иначе flow шире клиента и при первом показе виден горизонтальный скролл.
            $vAlready = $false
            try { $vAlready = [bool]$scroll.VerticalScroll.Visible } catch {}
            $colsGuess = [Math]::Max(1, [int][Math]::Floor($rawW / [double]$tileOuter))
            $rowsGuess = if ($count -le 0) { 0 } else { [int][Math]::Ceiling($count / [double]$colsGuess) }
            $tileH = [int]$script:libTileInnerH + (2 * [int]$script:libTileMargin)
            $hGuess = if ($rowsGuess -le 0) { 16 } else { 16 + ($rowsGuess * $tileH) }
            $needV = ($hGuess -gt $viewH)
            if ($needV -and -not $vAlready) {
                $avail = [Math]::Max(120, $rawW - $sbw)
            } else {
                $avail = $rawW
            }

            $contentH = [int](& $applyLibraryFlowWidth $avail)
            & $resetLibraryScroll $savedY $contentH

            # После Apply ClientSize мог измениться — подогнать ещё раз.
            $rawW2 = [Math]::Max(120, [int]$scroll.ClientSize.Width)
            if ($rawW2 -ne $avail) {
                $contentH = [int](& $applyLibraryFlowWidth $rawW2)
                & $resetLibraryScroll $savedY $contentH
            }

            $finalW = [Math]::Max(1, [int]$scroll.ClientSize.Width)
            if ($flow.Width -ne $finalW) { $flow.Width = $finalW }
            & $forceNoHScroll
            # AutoScroll-панель WinForms не всегда стирает старый кадр при
            # программном изменении Padding/AutoScrollPosition (пересчёт
            # padLeft при смене числа колонок) — остаются "призраки" старых
            # плиток. Принудительно перерисовываем весь видимый регион.
            try { $scroll.Invalidate($true) } catch {}
            if (-not $script:libReflowing) { try { $scroll.Update() } catch {} }
        } catch {}
    }

    # Предсказание "нужна ли вертикальная полоса ещё до появления" (в
    # syncLibraryFlowWidth) — это догадка по эвристике и может разойтись с
    # реальностью именно в момент перехода между "не нужна" и "нужна" (когда
    # число результатов растёт и добавляется новая строка плиток). Вместо
    # того чтобы гадать точнее, здесь просто СМОТРИМ на факт: если после
    # раскладки горизонтальная полоса всё равно видна — значит сетка шире
    # реального клиента (обычно из-за только что появившейся вертикальной
    # полосы, отъевшей ширину), пересчитываем ширину ещё раз с поправкой и
    # повторяем, пока полоса не исчезнет (или не кончатся попытки).
    $stabilizeLibraryGridWidth = {
        for ($i = 0; $i -lt 4; $i++) {
            $hasHScroll = $false
            try {
                $hasHScroll = ([int]$scroll.HorizontalScroll.Maximum -gt 0) -or [bool]$scroll.HorizontalScroll.Visible
            } catch { $hasHScroll = $false }
            if (-not $hasHScroll) { break }
            try {
                $sbw = [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth
                $avail = [Math]::Max(120, [int]$scroll.ClientSize.Width - $sbw)
                $contentH = [int](& $applyLibraryFlowWidth $avail)
                & $resetLibraryScroll -1 $contentH
                if ($flow.Width -ne $avail) { $flow.Width = $avail }
                & $forceNoHScroll
            } catch { break }
        }
        try { $scroll.Invalidate($true) } catch {}
        if (-not $script:libReflowing) { try { $scroll.Update() } catch {} }
    }
    & $syncLibraryFlowWidth
    & $stabilizeLibraryGridWidth
    # Resize приходит пачкой (разворот на весь экран, перетаскивание края), причём и от формы, и от
    # самого $scroll. Раньше каждое событие синхронно пересчитывало сетку и принудительно перерисовывало
    # все плитки (Update) — в PowerShell это занимает секунды, и сетка «ездила» влево-вправо. Теперь
    # события лишь перезапускают короткий таймер, а пересчёт идёт один раз и без промежуточных перерисовок.
    $script:libReflowing = $false
    $libReflowTimer = New-Object System.Windows.Forms.Timer
    $libReflowTimer.Interval = 60
    $libReflowTimer.Add_Tick({
        try { $libReflowTimer.Stop() } catch {}
        try {
            if ($dlg.IsDisposed) { return }
            $script:libReflowing = $true
            try {
                $scroll.Width = [Math]::Max(100, $dlg.ClientSize.Width - 24)
                $scroll.Height = [Math]::Max(100, $dlg.ClientSize.Height - 108 - [int]$script:libBottomReserve)
                # Панель вкладок всегда на всю ширину окна (иначе при 7 вкладках у последней обрезается счётчик).
                try { $tabBar.Width = [Math]::Max(940, [int]$dlg.ClientSize.Width - 24); $tabBar.Invalidate() } catch {}
                & $syncLibraryFlowWidth
                & $stabilizeLibraryGridWidth
            } finally { $script:libReflowing = $false }
            # Один финальный кадр уже с итоговой раскладкой.
            try { $scroll.Invalidate($true); $scroll.Update() } catch {}
        } catch {}
    })
    $requestLibraryReflow = { try { $libReflowTimer.Stop(); $libReflowTimer.Start() } catch {} }
    $scroll.Add_Resize({ & $requestLibraryReflow })
    $dlg.Add_Resize({ & $requestLibraryReflow })
    # Maximize/Restore меняет ClientSize не только через Resize — ловим
    # смену WindowState отдельно и пересобираем скролл после окончания
    # системной анимации раскладки.
    $script:libLastWindowState = $dlg.WindowState
    $dlg.Add_SizeChanged({
        try {
            $ws = $dlg.WindowState
            if ($ws -eq $script:libLastWindowState) { return }
            $script:libLastWindowState = $ws
            if ($ws -eq [System.Windows.Forms.FormWindowState]::Minimized) { return }
            # После maximize/restore даём WinForms досчитать ClientSize,
            # затем жёстко сбрасываем фантомный AutoScroll.
            $dlg.BeginInvoke([Action]{ try { & $requestLibraryReflow } catch {} }) | Out-Null
        } catch {}
    })

    # --- Нижний блок: статус и прогресс-бар ---
    # Расположен так же, как в главном окне: строка статуса (Segoe UI Semibold 10),
    # под ней ProgressBar (Continuous, 14 px) с процентом справа (Segoe UI 8,
    # приглушённый), ниже — переключатель автоимпорта слева и большая кнопка по центру.
    # Блок виден только пока идёт обновление/возврат/импорт (см. $showLibProgress); сетка игр подгоняется через $script:libBottomReserve.
    $script:libBottomBlockH = 40
    $pnlLibProgress = New-Object System.Windows.Forms.Panel
    $pnlLibProgress.Size = New-Object System.Drawing.Size(([Math]::Max(100, $dlg.ClientSize.Width - 24)), $script:libBottomBlockH)
    $pnlLibProgress.Location = New-Object System.Drawing.Point(12, ($dlg.ClientSize.Height - 10 - $script:libBottomBlockH))
    $pnlLibProgress.Anchor = 'Bottom,Left,Right'
    $pnlLibProgress.BackColor = $steamUi.Bg
    # Виден на всех вкладках: на вкладках лаунчеров — «Импорт», на вкладке Steam — «Обновить апскейлеры» (см. $updateSelectionUi).
    $pnlLibProgress.Visible = $false

    $lblLibStatus = New-Object System.Windows.Forms.Label
    $lblLibStatus.Location = New-Object System.Drawing.Point(0, 0)
    $lblLibStatus.Size = New-Object System.Drawing.Size($pnlLibProgress.Width, 22)
    $lblLibStatus.Anchor = 'Top,Left,Right'
    $lblLibStatus.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 10)
    $lblLibStatus.ForeColor = $steamUi.Text
    $lblLibStatus.AutoEllipsis = $true
    $lblLibStatus.Text = ''
    $pnlLibProgress.Controls.Add($lblLibStatus)

    $libProgressBar = New-Object System.Windows.Forms.ProgressBar
    $libProgressBar.Location = New-Object System.Drawing.Point(0, 26)
    $libProgressBar.Size = New-Object System.Drawing.Size(($pnlLibProgress.Width - 40), 14)
    $libProgressBar.Anchor = 'Top,Left,Right'
    $libProgressBar.Style = [System.Windows.Forms.ProgressBarStyle]::Continuous
    # Скрыт, пока импорт не запущен (см. $showLibProgress).
    $libProgressBar.Visible = $false
    $pnlLibProgress.Controls.Add($libProgressBar)

    $lblLibPercent = New-Object System.Windows.Forms.Label
    $lblLibPercent.Location = New-Object System.Drawing.Point(($pnlLibProgress.Width - 36), 23)
    $lblLibPercent.Size = New-Object System.Drawing.Size(36, 20)
    $lblLibPercent.Anchor = 'Top,Right'
    $lblLibPercent.Font = New-Object System.Drawing.Font('Segoe UI', 8)
    $lblLibPercent.ForeColor = $steamUi.Muted
    $lblLibPercent.TextAlign = [System.Drawing.ContentAlignment]::MiddleRight
    $lblLibPercent.Text = ''
    $pnlLibProgress.Controls.Add($lblLibPercent)

    # Кнопки и переключатель автоимпорта живут в верхней строке окна; внизу — только статус и прогресс-бар.
    $dlg.Controls.Add($pnlLibProgress)

    # Блок целиком показывает/прячет $updateSelectionUi по вкладке; сам бар виден только во время импорта
    # (true — показать бар, false — спрятать и сбросить статус и процент).
    $showLibProgress = {
        param([bool]$show)
        try {
            # Нижний блок занимает место только пока идёт работа; в остальное время сетка игр тянется до низа окна.
            $wantReserve = if ($show) { 48 } else { 0 }
            if ([int]$script:libBottomReserve -ne $wantReserve) {
                $script:libBottomReserve = $wantReserve
                $pnlLibProgress.Visible = $show
                $scroll.Height = [Math]::Max(100, $dlg.ClientSize.Height - 108 - [int]$script:libBottomReserve)
                & $syncLibraryFlowWidth
                & $stabilizeLibraryGridWidth
            }
            if ($show) {
                $libProgressBar.Visible = $true
            } else {
                $lblLibStatus.Text = ''
                $lblLibPercent.Text = ''
                $libProgressBar.Value = 0
                $libProgressBar.Visible = $false
            }
        } catch {}
    }

    $script:libBrowserEntries = @()
    $script:libCoverQueue = New-Object System.Collections.Queue
    $script:libLocalCoverQueue = New-Object System.Collections.Queue
    $script:libLocalCoverT0 = 0.0
    $script:libTilePending = $null
    $script:libTileCountOverride = 0
    $script:libProgressiveOnce = $false
    $script:libLastTile = $null
    $script:libFillT0 = 0.0
    # Кэш "appId -> путь к файлу" на время сессии диалога: без него каждая
    # пересборка сетки (в т.ч. при стирании символов в поиске) заново ставит
    # в очередь скачивание уже скачанной обложки, забивая параллельные слоты
    # ($libCoverMaxParallel) повторными запросами и задерживая появление
    # свежих плиток.
    $script:libCoverMemCache = @{}
    $tileImages = New-Object System.Collections.Generic.List[System.Drawing.Image]
    # Значок источника поверх Image плитки (Steam / лаунчер / ROM-эмулятор).
    # После фоновой подгрузки обложки Image заменяется — значок нужно наложить снова.
    $overlayLibTileSourceBadge = {
        param($pic)
        try {
            if ($null -eq $pic -or $pic.IsDisposed) { return }
            $entry = $pic.Tag
            if ($null -eq $entry) { return }
            $kind = [string]$entry.Kind
            if ($kind -eq 'steam') {
                $steamIco = $null
                try { $steamIco = Get-LibSteamBadgeBitmap } catch { $steamIco = $null }
                if ($null -ne $steamIco) { Add-LauncherBadgeToPictureBox $pic $steamIco 22 6 }
                return
            }
            if ($kind -ne 'shortcut') { return }
            $srcLid = ''
            try { $srcLid = Get-ShortcutLauncherId $entry } catch { $srcLid = '' }
            $tileIsRom = $false
            try { $tileIsRom = [bool](Test-ShortcutIsRomEntry $entry) } catch { $tileIsRom = $false }
            if ($tileIsRom) { $srcLid = '' }
            if (-not [string]::IsNullOrWhiteSpace($srcLid)) {
                if ($null -ne $script:libLauncherMap -and $script:libLauncherMap.ContainsKey($srcLid)) {
                    $srcIcon = $script:libLauncherMap[$srcLid].Icon
                    if ($null -ne $srcIcon) { Add-LauncherBadgeToPictureBox $pic $srcIcon 22 6 }
                }
            } elseif ($tileIsRom) {
                $romEmuIcon = $null
                try { $romEmuIcon = Get-LibEmulatorBadgeBitmap (Get-EmulatorProfileByExePath ([string]$entry.Exe)) } catch { $romEmuIcon = $null }
                if ($null -ne $romEmuIcon) { Add-LauncherBadgeToPictureBox $pic $romEmuIcon 22 6 }
            }
        } catch {}
    }

    $libCoverCacheDir = Join-Path $env:TEMP 'SteamCommanderLibCovers'
    try { if (-not (Test-Path -LiteralPath $libCoverCacheDir)) { New-Item -ItemType Directory -Path $libCoverCacheDir -Force | Out-Null } } catch {}

    # Кэш готовых плиток на диске: ключ = исходный файл (путь+размер+время) + размер плитки.
    # Исходник изменился или другой размер плитки — ключ другой, старый файл просто не используется.
    $libTileCacheDir = Join-Path $global:appDataDir 'tile_cache'
    try { if (-not [System.IO.Directory]::Exists($libTileCacheDir)) { [void][System.IO.Directory]::CreateDirectory($libTileCacheDir) } } catch {}

    # $prescaled = $true: $bytes — уже готовая плитка из кэша (без ресайза и проверок).
    # $saveTo: куда сохранить готовую плитку (PNG) после ресайза. Результат — в $script:libApplyOk.
    $applyCoverBytesToPic = {
        param($pic, $bytes, $prescaled, $saveTo)
        $script:libApplyOk = $false
        if ($null -eq $pic -or $pic.IsDisposed) { return }
        if ($null -eq $bytes -or $bytes.Length -lt 2048) { return }
        try {
            $ms = New-Object System.IO.MemoryStream(,$bytes)
            $img = [System.Drawing.Image]::FromStream($ms)
            $w = [int]$img.Width
            $h = [int]$img.Height
            # Размер цели: явный размер плитки (Dock/Layout ещё может дать 0).
            $tw = [int]$script:libTileInnerW
            $th = [int]$script:libTileInnerH
            if ($pic.Width -gt 32) { $tw = $pic.Width }
            if ($pic.Height -gt 32) { $th = $pic.Height }
            $tw = [Math]::Max(32, $tw)
            $th = [Math]::Max(32, $th)
            $isPre = ([bool]$prescaled -and $w -eq $tw -and $h -eq $th)
            if (-not $isPre) {
                # Не ставим в плитку логотипы/иконки (квадрат и мелкий размер).
                if ($w -lt 120 -or $h -lt 120) { $img.Dispose(); $ms.Dispose(); return }
                $ratio = if ($h -gt 0) { $w / [double]$h } else { 1 }
                if ($ratio -gt 0.85 -and $ratio -lt 1.15) {
                    $img.Dispose(); $ms.Dispose(); return
                }
            }
            if ($isPre) {
                $bmp = New-Object System.Drawing.Bitmap($img)
            } else {
                $bmp = New-Object System.Drawing.Bitmap($tw, $th)
                $g = [System.Drawing.Graphics]::FromImage($bmp)
                try {
                    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                    $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                    $g.Clear([System.Drawing.Color]::FromArgb(20, 24, 28))
                    # Cover/crop как в Steam: заполняем всю плитку, лишнее обрезаем.
                    $scale = [Math]::Max($tw / [double]$w, $th / [double]$h)
                    $dw = [int]($w * $scale)
                    $dh = [int]($h * $scale)
                    $dx = [int](($tw - $dw) / 2)
                    $dy = [int](($th - $dh) / 2)
                    $g.DrawImage($img, $dx, $dy, $dw, $dh)
                } finally { $g.Dispose() }
                # Сохраняем готовую плитку (ещё без значка источника) в кэш.
                if (-not [string]::IsNullOrEmpty([string]$saveTo)) {
                    try { $bmp.Save([string]$saveTo, [System.Drawing.Imaging.ImageFormat]::Png) } catch { try { [System.IO.File]::Delete([string]$saveTo) } catch {} }
                }
            }
            $img.Dispose(); $ms.Dispose()
            $old = $pic.Image
            $pic.Image = $bmp
            $script:libApplyOk = $true
            [void]$tileImages.Add($bmp)
            if ($null -ne $old) { try { $old.Dispose() } catch {} }
            # Обложка подгрузилась — убираем текстовую заглушку на плитке.
            try {
                $parent = $pic.Parent
                if ($null -ne $parent) {
                    foreach ($c in @($parent.Controls)) {
                        if ($c -is [System.Windows.Forms.Label]) {
                            try { $parent.Controls.Remove($c); $c.Dispose() } catch {}
                        }
                    }
                }
            } catch {}
            try { & $overlayLibTileSourceBadge $pic } catch {}
        } catch {}
    }

    $applyCoverFileToPic = {
        param($pic, $filePath)
        if ($null -eq $pic -or $pic.IsDisposed) { return }
        if ([string]::IsNullOrWhiteSpace([string]$filePath)) { return }
        try {
            $fi = New-Object System.IO.FileInfo([string]$filePath)
            if (-not $fi.Exists) { return }
            $tw = [int]$script:libTileInnerW
            $th = [int]$script:libTileInnerH
            if ($pic.Width -gt 32) { $tw = $pic.Width }
            if ($pic.Height -gt 32) { $th = $pic.Height }
            $tw = [Math]::Max(32, $tw)
            $th = [Math]::Max(32, $th)
            $cfile = ''
            try {
                $keySrc = $fi.FullName.ToLowerInvariant() + '|' + $fi.Length + '|' + $fi.LastWriteTimeUtc.Ticks + '|' + $tw + 'x' + $th + '|v1'
                $sha = [System.Security.Cryptography.SHA1]::Create()
                try { $hex = ([System.BitConverter]::ToString($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($keySrc))) -replace '-', '').ToLowerInvariant() } finally { $sha.Dispose() }
                $cfile = [System.IO.Path]::Combine($libTileCacheDir, ($hex + '.png'))
            } catch { $cfile = '' }
            if ($cfile -and [System.IO.File]::Exists($cfile)) {
                $cb = $null
                try { $cb = [System.IO.File]::ReadAllBytes($cfile) } catch { $cb = $null }
                if ($null -ne $cb) {
                    & $applyCoverBytesToPic $pic $cb $true ''
                    if ($script:libApplyOk) { Add-TmA 'tileCacheHit_n' 1; return }
                }
            }
            Add-TmA 'tileCacheMiss_n' 1
            $bytes = [System.IO.File]::ReadAllBytes($fi.FullName)
            & $applyCoverBytesToPic $pic $bytes $false $cfile
        } catch {}
    }

    # Настоящий фон: WebClient.DownloadDataAsync — UI-поток не ждёт сеть.
    $script:libCoverInflight = 0
    $script:libCoverMaxParallel = 8
    $script:libCoverClients = New-Object System.Collections.ArrayList

    $startNextLibCoverDownloads = {
        if ($dlg.IsDisposed -or $dlg.Disposing) { return }
        if ($null -eq $script:libCoverQueue) { return }
        try {
            [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls12
            [System.Net.ServicePointManager]::DefaultConnectionLimit = 16
        } catch {}
        while ([int]$script:libCoverInflight -lt [int]$script:libCoverMaxParallel -and $script:libCoverQueue.Count -gt 0) {
            $job = $script:libCoverQueue.Dequeue()
            if ($null -eq $job -or $null -eq $job.Pic -or $job.Pic.IsDisposed) { continue }
            $appId = [string]$job.AppId

            # Оба имени кэша: старое (до правки) и новое.
            $tmpCandidates = @(
                (Join-Path $libCoverCacheDir ($appId + '_libcover.jpg')),
                (Join-Path $libCoverCacheDir ($appId + '_600x900.jpg'))
            )
            $tmp = $tmpCandidates[0]
            $usedCache = $false
            foreach ($cpath in $tmpCandidates) {
                try {
                    if ((Test-Path -LiteralPath $cpath) -and ((Get-Item -LiteralPath $cpath).Length -gt 2048)) {
                        if (Test-LibraryCoverCandidateFile $cpath) {
                            & $applyCoverFileToPic $job.Pic $cpath
                            $usedCache = $true
                            break
                        }
                        # Битый/логотип в кэше — удаляем и качаем нормальную обложку.
                        Remove-Item -LiteralPath $cpath -Force -ErrorAction SilentlyContinue
                    } elseif (Test-Path -LiteralPath $cpath) {
                        Remove-Item -LiteralPath $cpath -Force -ErrorAction SilentlyContinue
                    }
                } catch {}
            }
            if ($usedCache) { continue }

            $local = Get-LibraryCoverPath $appId
            if ($local) {
                try {
                    Copy-Item -LiteralPath $local -Destination $tmp -Force -ErrorAction SilentlyContinue
                    if ((Test-Path -LiteralPath $tmp) -and ((Get-Item -LiteralPath $tmp).Length -gt 512)) {
                        & $applyCoverFileToPic $job.Pic $tmp
                        continue
                    }
                } catch {}
            }

            # Без синхронного PICS на UI (он подвисал и срывал очередь).
            # Сначала классическая вертикальная, затем то, что реально отдаёт CDN
            # у игр вроде Robinson (нет library_600x900, но есть header/capsule).
            $urls = New-Object System.Collections.Generic.List[string]
            foreach ($host in @(
                'https://cdn.cloudflare.steamstatic.com/steam/apps',
                'https://steamcdn-a.akamaihd.net/steam/apps',
                'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps',
                'https://shared.fastly.steamstatic.com/store_item_assets/steam/apps'
            )) {
                foreach ($file in @(
                    'library_600x900.jpg',
                    'library_600x900_2x.jpg',
                    'library_capsule_2x.jpg',
                    'library_capsule.jpg',
                    'header.jpg',
                    'capsule_616x353.jpg'
                )) {
                    [void]$urls.Add("$host/$appId/$file")
                }
            }

            $wc = New-Object System.Net.WebClient
            try { $wc.Headers['User-Agent'] = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) SteamCommander' } catch {}
            [void]$script:libCoverClients.Add($wc)
            $script:libCoverInflight++

            $state = [PSCustomObject]@{
                Pic = $job.Pic
                AppId = $appId
                Tmp = $tmp
                Client = $wc
                Urls = @($urls)
                UrlIndex = 0
            }
            $wc.add_DownloadDataCompleted({
                param($sender, $e)
                $st = $e.UserState
                $retrying = $false
                try {
                    if (-not $e.Cancelled -and $null -eq $e.Error -and $null -ne $e.Result -and $e.Result.Length -gt 2048) {
                        # Отбраковка логотипов/иконок до записи в кэш.
                        $accept = $false
                        try {
                            $msCheck = New-Object System.IO.MemoryStream(,$e.Result)
                            $imgCheck = [System.Drawing.Image]::FromStream($msCheck)
                            try {
                                $cw = [int]$imgCheck.Width; $ch = [int]$imgCheck.Height
                                if ($cw -ge 120 -and $ch -ge 120) {
                                    $cr = if ($ch -gt 0) { $cw / [double]$ch } else { 1 }
                                    if (-not ($cr -gt 0.85 -and $cr -lt 1.15)) {
                                        $accept = $true
                                    }
                                }
                            } finally { $imgCheck.Dispose(); $msCheck.Dispose() }
                        } catch { $accept = $false }
                        if ($accept) {
                            try { [System.IO.File]::WriteAllBytes([string]$st.Tmp, $e.Result) } catch {}
                            try { $script:libCoverMemCache[[string]$st.AppId] = [string]$st.Tmp } catch {}
                            $picRef = $st.Pic
                            $tmpRef = [string]$st.Tmp
                            if ($null -ne $dlg -and -not $dlg.IsDisposed) {
                                try {
                                    [void]$dlg.BeginInvoke([Action]{
                                        try { & $applyCoverFileToPic $picRef $tmpRef } catch {}
                                    }.GetNewClosure())
                                } catch {
                                    try { & $applyCoverFileToPic $picRef $tmpRef } catch {}
                                }
                            }
                        } elseif ($null -ne $st -and $null -ne $st.Urls) {
                            # Похоже на логотип — пробуем следующий URL.
                            $next = [int]$st.UrlIndex + 1
                            if ($next -lt @($st.Urls).Count) {
                                $st.UrlIndex = $next
                                try {
                                    $sender.DownloadDataAsync([Uri]([string]$st.Urls[$next]), $st)
                                    $retrying = $true
                                } catch { $retrying = $false }
                            }
                        }
                    } elseif (-not $e.Cancelled -and $null -ne $st -and $null -ne $st.Urls) {
                        $next = [int]$st.UrlIndex + 1
                        if ($next -lt @($st.Urls).Count) {
                            $st.UrlIndex = $next
                            try {
                                $sender.DownloadDataAsync([Uri]([string]$st.Urls[$next]), $st)
                                $retrying = $true
                            } catch { $retrying = $false }
                        }
                    }
                } finally {
                    if (-not $retrying) {
                        $script:libCoverInflight = [Math]::Max(0, [int]$script:libCoverInflight - 1)
                        try { $sender.Dispose() } catch {}
                        try { [void]$script:libCoverClients.Remove($sender) } catch {}
                        try {
                            if (-not $dlg.IsDisposed -and $script:libCoverQueue.Count -gt 0) {
                                $libCoverTimer.Start()
                            }
                        } catch {}
                    }
                }
            }.GetNewClosure())

            try {
                $wc.DownloadDataAsync([Uri]([string]$state.Urls[0]), $state)
            } catch {
                $script:libCoverInflight = [Math]::Max(0, [int]$script:libCoverInflight - 1)
                try { $wc.Dispose() } catch {}
            }
        }
    }

    $libCoverTimer = New-Object System.Windows.Forms.Timer
    $libCoverTimer.Interval = 30
    $libCoverTimer.Add_Tick({
        try { $libCoverTimer.Stop() } catch {}
        try { & $startNextLibCoverDownloads } catch {}
    })


    # Досоздание плиток порциями (первое открытие библиотеки): за тик не дольше ~25 мс, новые плитки
    # добавляются во flow одним AddRange. Размер сетки уже посчитан под все плитки ($script:libTileCountOverride).
    $libTileFillTimer = New-Object System.Windows.Forms.Timer
    $libTileFillTimer.Interval = 10
    $libTileFillTimer.Add_Tick({
        try { $libTileFillTimer.Stop() } catch {}
        try {
            if ($dlg.IsDisposed -or $dlg.Disposing) { return }
            $pend = $script:libTilePending
            if ($null -eq $pend) { return }
            if ([string]$script:libActiveTab -ne [string]$pend.Tab) { $script:libTilePending = $null; $script:libTileCountOverride = 0; return }
            $fsw = [System.Diagnostics.Stopwatch]::StartNew()
            $batch = New-Object System.Collections.Generic.List[System.Windows.Forms.Control]
            $ents = $pend.Entries
            while ($pend.Next -lt $ents.Count -and $fsw.ElapsedMilliseconds -lt 25) {
                $fentry = $ents[$pend.Next]
                $pend.Next = $pend.Next + 1
                $ftm = (-not ($pend.Q -and -not ([string]$fentry.Name).ToLowerInvariant().Contains([string]$pend.Q))) -and (& $passesLibFilter $fentry)
                $script:libLastTile = $null
                $null = & $makeTile $fentry
                $ft = $script:libLastTile
                if ($null -ne $ft -and $ftm) { [void]$batch.Add($ft) }
            }
            if ($batch.Count -gt 0) {
                $flow.SuspendLayout()
                try { $flow.Controls.AddRange($batch.ToArray()) } finally { $flow.ResumeLayout($true) }
            }
            if ($script:libLocalCoverQueue.Count -gt 0 -and -not $libLocalCoverTimer.Enabled) {
                try { $libLocalCoverTimer.Start() } catch {}
            }
            if ($pend.Next -lt $ents.Count) {
                try { $libTileFillTimer.Start() } catch {}
            } else {
                $script:libTilePending = $null
                $script:libTileCountOverride = 0
                $script:libTileAllKey = ([string]$pend.Tab + '|' + [string]$pend.Total)
                try { & $syncLibraryFlowWidth } catch {}
                try { & $updateSelectionUi } catch {}
                try { Write-Tm ('ПЛИТКИ ДОСОЗДАНЫ: ' + [int]((Get-TmNow) - $script:libFillT0) + ' мс с запуска таймера') } catch {}
            }
        } catch {
            try { $script:libTilePending = $null; $script:libTileCountOverride = 0 } catch {}
        }
    })

    # Порционная подгрузка локальных обложек: за один тик — не дольше ~30 мс, между тиками окно живёт (прокрутка, клики).
    # Для каждой игры: найти файл обложки -> применить (с дисковым кэшем плиток) -> если нет, память сеанса -> если нет, сетевая очередь.
    $libLocalCoverTimer = New-Object System.Windows.Forms.Timer
    $libLocalCoverTimer.Interval = 10
    $libLocalCoverTimer.Add_Tick({
        try { $libLocalCoverTimer.Stop() } catch {}
        try {
            if ($dlg.IsDisposed -or $dlg.Disposing) { return }
            $lsw = [System.Diagnostics.Stopwatch]::StartNew()
            while ($script:libLocalCoverQueue.Count -gt 0 -and $lsw.ElapsedMilliseconds -lt 30) {
                $job = $script:libLocalCoverQueue.Dequeue()
                if ($null -eq $job -or $null -eq $job.Pic -or $job.Pic.IsDisposed) { continue }
                $lpic = $job.Pic
                $lentry = $job.Entry
                $lid = [string]$lentry.AppId
                $applied = $false
                $__lp0 = Get-TmNow
                $lpath = $null
                try { $lpath = Get-LibraryCoverPath $lid } catch { $lpath = $null }
                Add-TmA 'lazy_path_ms' ((Get-TmNow) - $__lp0)
                if ($lpath) {
                    $__la0 = Get-TmNow
                    $script:libApplyOk = $false
                    try { & $applyCoverFileToPic $lpic $lpath } catch {}
                    $applied = [bool]$script:libApplyOk
                    Add-TmA 'lazy_apply_ms' ((Get-TmNow) - $__la0)
                }
                if (-not $applied -and $script:libCoverMemCache.ContainsKey($lid)) {
                    $cachedPath = [string]$script:libCoverMemCache[$lid]
                    if ($cachedPath -and (Test-Path -LiteralPath $cachedPath)) {
                        $script:libApplyOk = $false
                        try { & $applyCoverFileToPic $lpic $cachedPath } catch {}
                        $applied = [bool]$script:libApplyOk
                    }
                }
                if (-not $applied) {
                    if ([string]$lentry.Kind -eq 'steam' -and ($lid -match '^\d+$') -and ([long]$lid -gt 0)) {
                        $script:libCoverQueue.Enqueue([PSCustomObject]@{ Pic = $lpic; AppId = $lid })
                    }
                    # Обложки нет — значок источника на пустую плитку (как раньше делал buildTiles).
                    if ([string]$lentry.Kind -eq 'steam') { try { & $overlayLibTileSourceBadge $lpic } catch {} }
                }
            }
            if ($script:libLocalCoverQueue.Count -gt 0) {
                try { $libLocalCoverTimer.Start() } catch {}
            } else {
                try { Save-CoverPathMemo } catch {}
                if ($null -eq $script:libTilePending) { try {
                    Write-Tm ('ЛЕНИВЫЕ ОБЛОЖКИ ГОТОВЫ: ' + [int]((Get-TmNow) - $script:libLocalCoverT0) + ' мс с запуска таймера')
                    foreach ($__k in @($script:tmA.Keys | Sort-Object)) { Write-Tm ('     ' + $__k + ' = ' + [int]$script:tmA[$__k]) }
                } catch {} }
                if ($script:libCoverQueue.Count -gt 0) { try { $libCoverTimer.Start() } catch {} }
            }
        } catch {}
    })

    # После закрытия карточки игры (обложки, иконка, название и т.д. могли измениться)
    # сразу перечитываем ярлыки Steam и пересобираем плитки — без перезапуска программы.
    # Позицию прокрутки сохраняем, чтобы список не прыгал в начало.
    $refreshLibAfterEdit = {
        param($entry)
        try {
            if ($dlg.IsDisposed) { return }
            $savedY = 0
            try { $savedY = -[int]$scroll.AutoScrollPosition.Y } catch { $savedY = 0 }
            if ($savedY -lt 0) { $savedY = 0 }
            # Кэш скачанных обложек этой игры сбрасываем — локальная (выбранная в карточке) важнее.
            if ($null -ne $entry) { try { $script:libCoverMemCache.Remove([string]$entry.AppId) } catch {} }
            try { & $hideLibHoverCardNow } catch {}
            & $refreshSteamTabEntries
            try { & $resetLibraryScroll $savedY } catch {}
        } catch {}
    }

    $openEntry = {
        param($entry)
        if ($null -eq $entry) { return }
        try {
            if ($entry.Kind -eq 'steam') {
                # Лицензионные игры Steam никогда не бывают ROM-ярлыками.
                Show-GameEditorDialog $entry.Name 'Steam' $entry.Path $false $null $entry $dlg -IsRomEntry:$false
                if ($script:editorSavedChanges) { try { & $refreshLibAfterEdit $entry } catch {} }
            } else {
                # Определяем по самому ярлыку (Exe совпадает с exe одного из
                # настроенных эмуляторов), а не по текущему состоянию
                # переключателя "Режим ROMs" на главном экране — иначе уже
                # добавленная ROM-игра открывалась бы как обычная, если в
                # момент клика в библиотеке режим ROMs выключен (и наоборот).
                $isRom = Test-ShortcutIsRomEntry $entry
                $path = ''
                if ($isRom) {
                    # В карточке ROM-режима это поле — папка с файлом рома
                    # (в ней сканируются кандидаты), а не папка эмулятора,
                    # которая лежит в StartDir/Path этого ярлыка.
                    $romFile = Get-RomPathFromLaunchOptions $entry
                    if (-not [string]::IsNullOrWhiteSpace($romFile)) {
                        try { $path = [System.IO.Path]::GetDirectoryName($romFile) } catch {}
                    }
                }
                if ([string]::IsNullOrWhiteSpace($path)) {
                    $path = [string]$entry.Path
                    if ([string]::IsNullOrWhiteSpace($path) -and -not [string]::IsNullOrWhiteSpace([string]$entry.Exe)) {
                        try { $path = [System.IO.Path]::GetDirectoryName([string]$entry.Exe) } catch {}
                    }
                }
                Show-GameEditorDialog $entry.Name 'Steam' $path $false $null $entry $dlg -IsRomEntry:$isRom
                if ($script:editorSavedChanges) { try { & $refreshLibAfterEdit $entry } catch {} }
            }
        } catch {
            Show-AppMessageBox(
                $dlg,
                (T 'lib_open_fail' @([string]$_.Exception.Message)),
                $global:appTitle,
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }

    # --- Всплывающая карточка как в Steam (header + бейдж + название) ---
    # Компактная миниатюра как в Steam (~230x150).
    $libHoverCard = New-Object System.Windows.Forms.Panel
    $libHoverCard.Size = New-Object System.Drawing.Size(230, 150)
    $libHoverCard.BackColor = [System.Drawing.Color]::FromArgb(28, 34, 42)
    $libHoverCard.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $libHoverCard.Visible = $false
    $libHoverCard.Padding = New-Object System.Windows.Forms.Padding(0)
    $dlg.Controls.Add($libHoverCard)
    $libHoverCard.BringToFront()

    $libHoverPic = New-Object System.Windows.Forms.PictureBox
    $libHoverPic.Location = New-Object System.Drawing.Point(0, 0)
    $libHoverPic.Size = New-Object System.Drawing.Size(228, 108)
    $libHoverPic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $libHoverPic.BackColor = [System.Drawing.Color]::FromArgb(16, 20, 26)
    $libHoverCard.Controls.Add($libHoverPic)

    $libHoverBadge = New-Object System.Windows.Forms.Label
    $libHoverBadge.Location = New-Object System.Drawing.Point(8, 116)
    $libHoverBadge.AutoSize = $true
    $libHoverBadge.ForeColor = [System.Drawing.Color]::White
    $libHoverBadge.Font = New-Object System.Drawing.Font('Segoe UI', 7, [System.Drawing.FontStyle]::Bold)
    $libHoverBadge.Padding = New-Object System.Windows.Forms.Padding(3, 1, 3, 1)
    $libHoverCard.Controls.Add($libHoverBadge)

    $libHoverLauncherIcon = New-Object System.Windows.Forms.PictureBox
    $libHoverLauncherIcon.Size = New-Object System.Drawing.Size([int]$global:LibIconSize, [int]$global:LibIconSize)
    $libHoverLauncherIcon.Location = New-Object System.Drawing.Point(8, 117)
    $libHoverLauncherIcon.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $libHoverLauncherIcon.BackColor = [System.Drawing.Color]::Transparent
    $libHoverLauncherIcon.Visible = $false
    $libHoverCard.Controls.Add($libHoverLauncherIcon)

    $libHoverName = New-Object System.Windows.Forms.Label
    $libHoverName.Location = New-Object System.Drawing.Point(8, 114)
    $libHoverName.Size = New-Object System.Drawing.Size(212, 28)
    $libHoverName.ForeColor = $steamUi.Text
    $libHoverName.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 8.5)
    $libHoverName.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $libHoverCard.Controls.Add($libHoverName)

    # Бейдж «Non-Steam» — на месте значка лаунчера (виден, когда игра добавлена из папки, а не из лаунчера).
    $libHoverNsBadge = New-NonSteamBadgeControl 16
    $libHoverNsBadge.Location = New-Object System.Drawing.Point(8, 119)
    $libHoverNsBadge.Visible = $false
    $libHoverCard.Controls.Add($libHoverNsBadge)
    $libHoverNsBadge.BringToFront()
    # Бейдж «ROM» — для ярлыков, запускающих ROM через эмулятор (тот же стиль, что «Non-Steam»).
    $libHoverRomBadge = New-NonSteamBadgeControl 16 'rom'
    $libHoverRomBadge.Location = New-Object System.Drawing.Point(8, 119)
    $libHoverRomBadge.Visible = $false
    $libHoverCard.Controls.Add($libHoverRomBadge)
    $libHoverRomBadge.BringToFront()

    $script:libHoverImages = New-Object System.Collections.Generic.List[System.Drawing.Image]
    $script:libHoverPendingTile = $null
    $script:libHoverPendingEntry = $null
    # Как в Steam: миниатюра не сразу, а с небольшой задержкой (~0.9 с).
    $script:libHoverShowTimer = New-Object System.Windows.Forms.Timer
    $script:libHoverShowTimer.Interval = 500
    $script:libHoverShowTimer.Add_Tick({
        try { $script:libHoverShowTimer.Stop() } catch {}
        try {
            $t = $script:libHoverPendingTile
            $en = $script:libHoverPendingEntry
            if ($null -eq $t -or $t.IsDisposed -or $null -eq $en) { return }
            # Курсор всё ещё над плиткой?
            $mp = $t.PointToClient([System.Windows.Forms.Control]::MousePosition)
            if (-not $t.ClientRectangle.Contains($mp)) { return }
            & $showLibHoverCardNow $t $en
        } catch {}
    })
    $script:libHoverHideTimer = New-Object System.Windows.Forms.Timer
    $script:libHoverHideTimer.Interval = 180
    $script:libHoverHideTimer.Add_Tick({
        try { $script:libHoverHideTimer.Stop() } catch {}
        try {
            $mp = $libHoverCard.PointToClient([System.Windows.Forms.Control]::MousePosition)
            if ($libHoverCard.ClientRectangle.Contains($mp)) { return }
        } catch {}
        $libHoverCard.Visible = $false
        try {
            if ($null -ne $libHoverPic.Image) {
                $old = $libHoverPic.Image
                $libHoverPic.Image = $null
                $old.Dispose()
            }
        } catch {}
    })

    $findLibraryHeaderPath = {
        param($entry)
        if ($null -eq $entry) { return $null }
        try {
            $id = [string]$entry.AppId
            $ud = ''
            if ($null -ne $entry.ShortcutRecord) {
                if (-not [string]::IsNullOrWhiteSpace([string]$entry.ShortcutRecord.ShortcutId)) {
                    $id = [string]$entry.ShortcutRecord.ShortcutId
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$entry.ShortcutRecord.UserDataDir)) {
                    $ud = [string]$entry.ShortcutRecord.UserDataDir
                }
            }
            return (Get-LibraryHeaderPath $id $ud)
        } catch { return $null }
    }

    $showLibHoverCard = {
        param($tile, $entry)
        try { $script:libHoverHideTimer.Stop() } catch {}
        if ($null -eq $entry -or $null -eq $tile -or $tile.IsDisposed) { return }
        # Уже показана карточка для этой же плитки — не перезапускаем задержку.
        if ($libHoverCard.Visible -and [object]::ReferenceEquals($script:libHoverPendingTile, $tile)) { return }
        $script:libHoverPendingTile = $tile
        $script:libHoverPendingEntry = $entry
        try { $script:libHoverShowTimer.Stop(); $script:libHoverShowTimer.Start() } catch {}
    }

    $showLibHoverCardNow = {
        param($tile, $entry)
        try { $script:libHoverHideTimer.Stop() } catch {}
        if ($null -eq $entry -or $null -eq $tile -or $tile.IsDisposed) { return }
        $libHoverName.Text = [string]$entry.Name
        $isSteam = ([string]$entry.Kind -eq 'steam')
        $srcLid = ''
        if (-not $isSteam) {
            try { $srcLid = Get-ShortcutLauncherId $entry } catch { $srcLid = '' }
        }
        $isRomHover = $false
        if (-not $isSteam) { try { $isRomHover = [bool](Test-ShortcutIsRomEntry $entry) } catch { $isRomHover = $false } }
        if ($isRomHover) { $srcLid = '' }
        $srcIcon = $null
        if (-not [string]::IsNullOrWhiteSpace($srcLid) -and $null -ne $script:libLauncherMap -and $script:libLauncherMap.ContainsKey($srcLid)) {
            try { $srcIcon = $script:libLauncherMap[$srcLid].Icon } catch { $srcIcon = $null }
        }
        if ($null -ne $srcIcon) {
            $libHoverBadge.Visible = $false
            $libHoverLauncherIcon.BackColor = [System.Drawing.Color]::Transparent
            $libHoverLauncherIcon.Image = $srcIcon
            $libHoverLauncherIcon.Visible = $true
            $libHoverNsBadge.Visible = $false
            $libHoverRomBadge.Visible = $false
            try {
                $libHoverLauncherIcon.Location = New-Object System.Drawing.Point(8, 117)
                $bx = $libHoverLauncherIcon.Right + 6
                $libHoverName.Location = New-Object System.Drawing.Point($bx, 114)
                $libHoverName.Size = New-Object System.Drawing.Size([Math]::Max(40, 220 - $bx), 28)
            } catch {}
        } else {
            $libHoverLauncherIcon.Visible = $false
            $libHoverLauncherIcon.Image = $null
            $showRom = ($isRomHover -and (-not $isSteam))
            $showNs = ((-not $isSteam) -and (-not $isRomHover) -and [string]::IsNullOrWhiteSpace($srcLid))
            $libHoverNsBadge.Visible = $showNs
            $libHoverRomBadge.Visible = $showRom
            if ($isSteam) {
                # Значок Steam (как у лаунчеров), не текстовый бейдж «Steam».
                $libHoverBadge.Visible = $false
                $steamHoverIco = $null
                try { $steamHoverIco = Get-LibSteamBadgeBitmap } catch { $steamHoverIco = $null }
                if ($null -ne $steamHoverIco) {
                    $libHoverLauncherIcon.BackColor = [System.Drawing.Color]::Transparent
                    $libHoverLauncherIcon.Image = $steamHoverIco
                    $libHoverLauncherIcon.Visible = $true
                    try {
                        $libHoverLauncherIcon.Location = New-Object System.Drawing.Point(8, 117)
                        $bx = $libHoverLauncherIcon.Right + 6
                        $libHoverName.Location = New-Object System.Drawing.Point($bx, 114)
                        $libHoverName.Size = New-Object System.Drawing.Size([Math]::Max(40, 220 - $bx), 28)
                    } catch {}
                } else {
                    $libHoverLauncherIcon.Visible = $false
                    try {
                        $libHoverName.Location = New-Object System.Drawing.Point(8, 114)
                        $libHoverName.Size = New-Object System.Drawing.Size(212, 28)
                    } catch {}
                }
            } elseif ($showNs -or $showRom) {
                $libHoverBadge.Visible = $false
                try {
                    $hoverKindBadge = if ($showRom) { $libHoverRomBadge } else { $libHoverNsBadge }
                    $hoverKindBadge.Location = New-Object System.Drawing.Point(8, 119)
                    $bx = $hoverKindBadge.Right + 6
                    if ($showRom) {
                        # Значок эмулятора — отдельно, справа от «ROM» (размер как у значка лаунчера).
                        $romHoverIcon = $null
                        try { $romHoverIcon = Get-LibEmulatorBadgeBitmap (Get-EmulatorProfileByExePath ([string]$entry.Exe)) } catch { $romHoverIcon = $null }
                        if ($null -ne $romHoverIcon) {
                            $libHoverLauncherIcon.BackColor = [System.Drawing.Color]::Transparent
                            $libHoverLauncherIcon.Image = $romHoverIcon
                            $libHoverLauncherIcon.Location = New-Object System.Drawing.Point(($libHoverRomBadge.Right + 4), 117)
                            $libHoverLauncherIcon.Visible = $true
                            $bx = $libHoverLauncherIcon.Right + 6
                        }
                    }
                    $libHoverName.Location = New-Object System.Drawing.Point($bx, 114)
                    $libHoverName.Size = New-Object System.Drawing.Size([Math]::Max(40, 220 - $bx), 28)
                } catch {}
            } else {
                # Лаунчер определён, но его значок недоступен — только название.
                $libHoverBadge.Visible = $false
                try {
                    $libHoverName.Location = New-Object System.Drawing.Point(8, 114)
                    $libHoverName.Size = New-Object System.Drawing.Size(212, 28)
                } catch {}
            }
        }

        # Картинка: горизонтальная обложка или портрет.
        try {
            if ($null -ne $libHoverPic.Image) {
                $old = $libHoverPic.Image
                $libHoverPic.Image = $null
                try { $old.Dispose() } catch {}
            }
        } catch {}
        $hdr = $null
        try { $hdr = & $findLibraryHeaderPath $entry } catch { $hdr = $null }
        $applyHoverImageFile = {
            param([string]$filePath)
            if ([string]::IsNullOrWhiteSpace($filePath) -or -not (Test-Path -LiteralPath $filePath)) { return $false }
            try {
                $src = New-Object System.Drawing.Bitmap($filePath)
                try {
                    $tw = [Math]::Max(32, $libHoverPic.Width)
                    $th = [Math]::Max(32, $libHoverPic.Height)
                    $bmp = New-Object System.Drawing.Bitmap($tw, $th)
                    $g = [System.Drawing.Graphics]::FromImage($bmp)
                    try {
                        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                        $g.Clear([System.Drawing.Color]::FromArgb(16, 20, 26))
                        $sw = [int]$src.Width; $sh = [int]$src.Height
                        # Cover-fill в горизонтальный кадр.
                        $scale = [Math]::Max($tw / [double]$sw, $th / [double]$sh)
                        $dw = [int]($sw * $scale)
                        $dh = [int]($sh * $scale)
                        $dx = [int](($tw - $dw) / 2)
                        $dy = [int](($th - $dh) / 2)
                        $g.DrawImage($src, $dx, $dy, $dw, $dh)
                    } finally { $g.Dispose() }
                    try {
                        if ($null -ne $libHoverPic.Image) {
                            $prev = $libHoverPic.Image
                            $libHoverPic.Image = $null
                            $prev.Dispose()
                        }
                    } catch {}
                    $libHoverPic.Image = $bmp
                    $libHoverPic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Normal
                    [void]$script:libHoverImages.Add($bmp)
                    return $true
                } finally { $src.Dispose() }
            } catch { return $false }
        }
        if ($hdr) { try { [void](& $applyHoverImageFile $hdr) } catch {} }
        # На горизонтальной миниатюре всплывающей карточки значка Steam нет: он показывается только под ней
        # (в строке с названием, см. $libHoverLauncherIcon).
        try { if ($libHoverNsBadge.Visible) { $libHoverNsBadge.BringToFront() } } catch {}
        try { if ($libHoverRomBadge.Visible) { $libHoverRomBadge.BringToFront() } } catch {}

        # Всегда справа от плитки; влево — только если справа не помещается.
        try {
            $gap = 10
            $screenRight = $tile.PointToScreen((New-Object System.Drawing.Point(($tile.Width + $gap), 0)))
            $clientRight = $dlg.PointToClient($screenRight)
            $x = [int]$clientRight.X
            $y = [int]$clientRight.Y
            $cardW = [int]$libHoverCard.Width
            $cardH = [int]$libHoverCard.Height
            $maxX = [int]$dlg.ClientSize.Width - $cardW - 8
            $maxY = [int]$dlg.ClientSize.Height - $cardH - 8
            if ($x -gt $maxX) {
                # Справа не влезает — ставим слева от плитки.
                $screenLeft = $tile.PointToScreen((New-Object System.Drawing.Point((-$cardW - $gap), 0)))
                $x = [int]$dlg.PointToClient($screenLeft).X
            }
            if ($x -lt 8) { $x = 8 }
            if ($x -gt $maxX) { $x = [Math]::Max(8, $maxX) }
            if ($y -gt $maxY) { $y = [Math]::Max(8, $maxY) }
            if ($y -lt 8) { $y = 8 }
            $libHoverCard.Location = New-Object System.Drawing.Point($x, $y)
        } catch {
            $libHoverCard.Location = New-Object System.Drawing.Point(20, 60)
        }
        $libHoverCard.Visible = $true
        $libHoverCard.BringToFront()
    }

    $hideLibHoverCardNow = {
        try { $script:libHoverShowTimer.Stop() } catch {}
        try { $script:libHoverHideTimer.Stop() } catch {}
        $script:libHoverPendingTile = $null
        $script:libHoverPendingEntry = $null
        $libHoverCard.Visible = $false
        try {
            if ($null -ne $libHoverPic.Image) {
                $oldImg = $libHoverPic.Image
                $libHoverPic.Image = $null
                $oldImg.Dispose()
            }
        } catch {}
    }
    # Сразу скрываем при уходе с обложки (как в Steam).
    $hideLibHoverCardSoon = { & $hideLibHoverCardNow }

    $libHoverCard.Add_MouseEnter({ try { $script:libHoverHideTimer.Stop() } catch {} })
    $libHoverCard.Add_MouseLeave({ & $hideLibHoverCardSoon })

    # Полоса «DLSS / версия» внизу плитки (рисуется поверх обложки в Paint, поэтому не пропадает
    # при подмене картинки и сразу обновляется, когда фоновый поиск находит версию).
    $paintDlssBar = {
        param($s, $e)
        try {
            $en = $s.Tag
            $st = $script:libDlssState
            # Галочка выбора рисуется тем же способом, что и на плитках лаунчеров.
            if ($null -ne $en -and [string]$s.AccessibleDescription -eq 'selcheck') {
                try {
                    $chkSel = $script:libSteamSelected.ContainsKey([string](& $getSteamEntryKey $en))
                    $cg = $e.Graphics
                    $cg.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
                    $cpath = New-Object System.Drawing.Drawing2D.GraphicsPath
                    try {
                        $cd = 12
                        [void]$cpath.AddArc(8, 8, $cd, $cd, 180, 90)
                        [void]$cpath.AddArc((32 - $cd), 8, $cd, $cd, 270, 90)
                        [void]$cpath.AddArc((32 - $cd), (32 - $cd), $cd, $cd, 0, 90)
                        [void]$cpath.AddArc(8, (32 - $cd), $cd, $cd, 90, 90)
                        $cpath.CloseFigure()
                        if ($chkSel) { $cf = [System.Drawing.Color]::FromArgb(30, 144, 230); $ce = $cf }
                        else { $cf = [System.Drawing.Color]::FromArgb(245, 247, 250); $ce = [System.Drawing.Color]::FromArgb(150, 158, 168) }
                        $cfb = New-Object System.Drawing.SolidBrush($cf)
                        $cep = New-Object System.Drawing.Pen($ce, 1.2)
                        try { $cg.FillPath($cfb, $cpath); $cg.DrawPath($cep, $cpath) } finally { $cfb.Dispose(); $cep.Dispose() }
                    } finally { $cpath.Dispose() }
                    if ($chkSel) {
                        $ckp = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 2.4)
                        try {
                            $ckp.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
                            $ckp.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
                            $ckp.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
                            $cg.DrawLines($ckp, @((New-Object System.Drawing.PointF(13, 20)), (New-Object System.Drawing.PointF(18, 25)), (New-Object System.Drawing.PointF(27, 14))))
                        } finally { $ckp.Dispose() }
                    }
                } catch {}
            }
            if ($null -eq $en -or $null -eq $st) { return }
            $d = Get-LibDlssEntryDir $en
            $ver = ''
            $has = $false
            if ([string]::IsNullOrEmpty($d)) { $has = $true }
            else {
                $k = Get-NormalizedGamePathKey $d
                if ($st['Results'].ContainsKey($k)) { $has = $true; $ver = [string]$st['Results'][$k] }
                elseif ([bool]$st['Done']) { $has = $true }
            }
            if (-not $has) { return }
            if ([string]::IsNullOrEmpty($ver)) { $ver = 'N/A' }
            $g = $e.Graphics
            $w = [int]$s.ClientSize.Width
            $h = [int]$s.ClientSize.Height
            $bh = 24
            if ($null -eq $script:libDlssBarBrush) {
                $script:libDlssBarBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(185, 0, 0, 0))
                $script:libDlssFontL = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
                $script:libDlssFontR = New-Object System.Drawing.Font('Segoe UI', 9)
            }
            $br = $script:libDlssBarBrush; $fL = $script:libDlssFontL; $fR = $script:libDlssFontR
            $g.FillRectangle($br, 0, ($h - $bh), $w, $bh)
            $tf = [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
            $huge = New-Object System.Drawing.Size(1000, 40)
            $ty = [int]($h - $bh + (($bh - $fL.Height) / 2))
            [System.Windows.Forms.TextRenderer]::DrawText($g, 'DLSS', $fL, (New-Object System.Drawing.Point(8, $ty)), [System.Drawing.Color]::White, $tf)
            $vw = [System.Windows.Forms.TextRenderer]::MeasureText($ver, $fR, $huge, $tf).Width
            [System.Windows.Forms.TextRenderer]::DrawText($g, $ver, $fR, (New-Object System.Drawing.Point(([int]($w - $vw - 8)), $ty)), [System.Drawing.Color]::FromArgb(225, 228, 232), $tf)
        } catch {
        }
    }
    # Текст полосы для нативного контрола плитки: версия / «N/A»; пока результата ещё нет — не трогаем.
    $setDlssText = {
        param($c)
        try {
            if (-not $script:libDlssNativeOk) { return }
            $en = $c.Tag
            $st = $script:libDlssState
            if ($null -eq $en -or $null -eq $st) { return }
            $d = Get-LibDlssEntryDir $en
            $ver = ''
            $has = $false
            if ([string]::IsNullOrEmpty($d)) { $has = $true }
            else {
                $k = Get-NormalizedGamePathKey $d
                if ($st['Results'].ContainsKey($k)) { $has = $true; $ver = [string]$st['Results'][$k] }
                elseif ([bool]$st['Done']) { $has = $true }
            }
            if (-not $has) { return }
            if ([string]::IsNullOrEmpty($ver)) { $ver = 'N/A' }
            if ([string]$c.DlssText -ne $ver) { $c.DlssText = $ver; $c.Invalidate() }
        } catch {}
    }
    # Пока фоновый поиск идёт, раз в 0,7 с обновляем плитки, если появились новые результаты.
    $libDlssTimer = New-Object System.Windows.Forms.Timer
    $libDlssTimer.Interval = 700
    $libDlssTimer.Add_Tick({
        try {
            $st = $script:libDlssState
            if ($null -eq $st) { $libDlssTimer.Stop(); return }
            # Пока кнопка мыши зажата (тянут ползунок прокрутки) UI-поток не занимаем — обновим на следующем тике.
            if ([System.Windows.Forms.Control]::MouseButtons -ne [System.Windows.Forms.MouseButtons]::None) { return }
            $cnt = [int]$st['Results'].Count
            $done = [bool]$st['Done']
            if ($cnt -ne [int]$script:libDlssLastCount -or $done) {
                $script:libDlssLastCount = $cnt
                # Пришли новые результаты поиска — пересчитываем доступность «Обновить апскейлеры».
                if ([string]$script:libActiveTab -eq 'steam' -and -not $script:libUpdRunning -and -not $script:libRestoreRunning -and -not $script:libImportRunning) {
                    try { & $updateSelectionUi } catch {}
                }
                foreach ($t in @($flow.Controls)) {
                    foreach ($c in @($t.Controls)) {
                        if ($script:libDlssNativeOk -and (@('SCDlssPicture','SCDlssLabel') -contains $c.GetType().Name)) { & $setDlssText $c }
                        else { try { $c.Invalidate() } catch {} }
                    }
                }
            }
            # Фильтр по библиотекам зависит от результатов поиска: когда поиск закончился, применяем его ещё раз (один раз на поиск).
            if ($done -and [string]$script:libActiveTab -eq 'steam' -and $null -ne $script:libFilterOff -and [bool]$script:libFilterOnlyLibs -and -not [object]::ReferenceEquals($script:libFilterLibsState, $st)) {
                $script:libFilterLibsState = $st
                try { & $applyLibFilter } catch {}
            }
            if ($done) { $libDlssTimer.Stop() }
        } catch {}
    })

    # Создаёт одну плитку для записи $entry (кладёт в $script:libTileAll, сама плитка — в $script:libLastTile).
    # Вынесено из buildTiles, чтобы одну и ту же сборку можно было вызывать и сразу, и порциями по таймеру.
    $makeTile = {
        param($entry)
        $script:libLastTile = $null
                if ([string]$script:libActiveTab -ne 'steam') {
                    # Вкладка лаунчера: плитка рисуется вручную (см. $paintLauncherTile).
                    $ltile = New-Object System.Windows.Forms.Panel
                    $ltile.Size = New-Object System.Drawing.Size([int]$script:libTileInnerW, [int]$script:libTileInnerH)
                    $ltile.Margin = New-Object System.Windows.Forms.Padding([int]$script:libTileMargin)
                    $ltile.BackColor = [System.Drawing.Color]::FromArgb(20, 24, 28)
                    $ltile.Tag = $entry
                    $ltile.Cursor = [System.Windows.Forms.Cursors]::Default
                    try {
                        $dbFlags = [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
                        [System.Windows.Forms.Control].GetProperty('DoubleBuffered', $dbFlags).SetValue($ltile, $true, $null)
                    } catch {}
                    $ltile.Add_Paint($paintLauncherTile)
                    $ltile.Add_MouseClick($launcherTileClick)
                    $ltile.Add_MouseMove($launcherTileMove)
                    [void]$script:libTileAll.Add($ltile)
                    $script:libLastTile = $ltile
                    return
                }
                $__tt0 = Get-TmNow
                $tile = New-Object System.Windows.Forms.Panel
                $tile.Size = New-Object System.Drawing.Size([int]$script:libTileInnerW, [int]$script:libTileInnerH)
                $m = [int]$script:libTileMargin
                $tile.Margin = New-Object System.Windows.Forms.Padding($m)
                $tile.BackColor = [System.Drawing.Color]::FromArgb(20, 24, 28)
                $tile.Cursor = [System.Windows.Forms.Cursors]::Hand
                $tile.Tag = $entry

                # Только обложка — как сетка Steam. Название и бейдж во всплывающей карточке.
                if ($script:libDlssNativeOk) { $pic = New-Object SCDlssPicture } else { $pic = New-Object System.Windows.Forms.PictureBox }
                $pic.Location = New-Object System.Drawing.Point(0, 0)
                $pic.Size = New-Object System.Drawing.Size([int]$script:libTileInnerW, [int]$script:libTileInnerH)
                $pic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Normal
                $pic.BackColor = [System.Drawing.Color]::FromArgb(20, 24, 28)
                $pic.Cursor = [System.Windows.Forms.Cursors]::Hand
                $pic.Tag = $entry
                if ($script:libDlssNativeOk) { & $setDlssText $pic } else { $pic.Add_Paint($paintDlssBar) }

                $skipCover = $false
                $nm = ([string]$entry.Name).ToLowerInvariant()
                if ($nm -match 'redistributable|steamworks common|directx|vcredist|visual c\+\+') { $skipCover = $true }
                if ([string]$entry.AppId -in @('228980','228990')) { $skipCover = $true }

                # Обложки подгружаются ПОСЛЕ показа окна, небольшими порциями по таймеру (см. $libLocalCoverTimer):
                # плитка сразу получает текстовую заглушку, обложка заменит её, когда до неё дойдёт очередь.
                $hasCover = $false
                $deferCover = $false
                if (-not $skipCover) {
                    [void]$script:libLocalCoverQueue.Enqueue([PSCustomObject]@{ Pic = $pic; Entry = $entry })
                    $deferCover = $true
                }

                $click = {
                    param($s, $e)
                    if ($script:libUpdRunning -or $script:libRestoreRunning) { return }
                    # Клик по галочке (квадрат 24x24 в точке 8,8) выбирает игру, а не открывает карточку.
                    try {
                        if ([string]$s.AccessibleDescription -eq 'selcheck') {
                            $cpt = $s.PointToClient([System.Windows.Forms.Control]::MousePosition)
                            if ($cpt.X -ge 8 -and $cpt.X -le 32 -and $cpt.Y -ge 8 -and $cpt.Y -le 32) {
                                & $toggleSteamSelection $s
                                return
                            }
                        }
                    } catch {}
                    $en = $s.Tag
                    if ($null -eq $en -and $s.Parent -ne $null) { $en = $s.Parent.Tag }
                    if ($null -ne $en) { & $openEntry $en }
                }
                $tile.Add_Click($click)
                $pic.Add_Click($click)
                $tile.Add_MouseEnter({
                    param($s, $e)
                    try {
                        $en = $s.Tag
                        if ($null -eq $en) { return }
                        & $showLibHoverCard $s $en
                    } catch {}
                })
                $tile.Add_MouseLeave({ & $hideLibHoverCardSoon })
                $pic.Add_MouseEnter({
                    param($s, $e)
                    try {
                        $t = $s.Parent
                        $en = $s.Tag
                        if ($null -eq $t -or $null -eq $en) { return }
                        & $showLibHoverCard $t $en
                    } catch {}
                })
                $pic.Add_MouseLeave({ & $hideLibHoverCardSoon })

                # Нет обложки — текстовая заглушка с названием игры.
                if (-not $hasCover) {
                    if ($script:libDlssNativeOk) { $ph = New-Object SCDlssLabel } else { $ph = New-Object System.Windows.Forms.Label }
                    $ph.Dock = [System.Windows.Forms.DockStyle]::Fill
                    $ph.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
                    $ph.ForeColor = [System.Drawing.Color]::FromArgb(180, 190, 200)
                    $ph.BackColor = [System.Drawing.Color]::FromArgb(28, 34, 42)
                    $ph.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
                    $ph.Text = [string]$entry.Name
                    $ph.Cursor = [System.Windows.Forms.Cursors]::Hand
                    $ph.Tag = $entry
                    if ($script:libDlssNativeOk) { & $setDlssText $ph } else { $ph.Add_Paint($paintDlssBar) }
                    $ph.Padding = New-Object System.Windows.Forms.Padding(8)
                    $ph.Add_Click($click)
                    $ph.Add_MouseEnter({
                        param($s, $e)
                        try {
                            $t = $s.Parent
                            $en = $s.Tag
                            if ($null -eq $t -or $null -eq $en) { return }
                            & $showLibHoverCard $t $en
                        } catch {}
                    })
                    $ph.Add_MouseLeave({ & $hideLibHoverCardSoon })
                    $tile.Controls.Add($ph)
                }

                $tile.Controls.Add($pic)
                if (-not $hasCover) { $ph.BringToFront() }
                $__b0 = Get-TmNow
                if ([string]$entry.Kind -eq 'steam') {
                    # Только значок Steam в углу (без фона), как у лаунчеров.
                    # Если обложка уже применена, значок на ней уже нарисован (см. $applyCoverBytesToPic) — второй раз не рисуем.
                    if (-not $hasCover -and -not $deferCover) { try { & $overlayLibTileSourceBadge $pic } catch {} }
                } elseif ([string]$entry.Kind -eq 'shortcut') {
                    # Источник игры — значок в правом верхнем углу: либо лаунчер (EGS, GOG, ...),
                    # либо «Non-Steam», если игра добавлена из папки с игрой, а не из лаунчера.
                    # Одновременно два значка не ставим.
                    $srcLid = ''
                    try { $srcLid = Get-ShortcutLauncherId $entry } catch { $srcLid = '' }
                    $tileIsRom = $false
                    try { $tileIsRom = [bool](Test-ShortcutIsRomEntry $entry) } catch { $tileIsRom = $false }
                    if ($tileIsRom) { $srcLid = '' }
                    if (-not [string]::IsNullOrWhiteSpace($srcLid)) {
                        try {
                            if ($null -ne $script:libLauncherMap -and $script:libLauncherMap.ContainsKey($srcLid)) {
                                $srcIcon = $script:libLauncherMap[$srcLid].Icon
                                if ($null -ne $srcIcon) { Add-LauncherBadgeToPictureBox $pic $srcIcon 22 6 }
                            }
                        } catch {}
                    } else {
                        try {
                            $nsb = if ($tileIsRom) { New-NonSteamBadgeControl 16 'rom' } else { New-NonSteamBadgeControl 16 }
                            $nsb.Location = New-Object System.Drawing.Point(([int]$script:libTileInnerW - [int]$nsb.Width - 6), 6)
                            if ($tileIsRom) {
                                # Значок эмулятора — отдельно, в углу (как значки лаунчеров, 22 px); «ROM» стоит слева от него.
                                $romEmuIcon = $null
                                try { $romEmuIcon = Get-LibEmulatorBadgeBitmap (Get-EmulatorProfileByExePath ([string]$entry.Exe)) } catch { $romEmuIcon = $null }
                                if ($null -ne $romEmuIcon) {
                                    Add-LauncherBadgeToPictureBox $pic $romEmuIcon 22 6
                                    $nsb.Location = New-Object System.Drawing.Point(([int]$script:libTileInnerW - 6 - 22 - 4 - [int]$nsb.Width), 9)
                                }
                            }
                            $nsb.Tag = $entry
                            $nsb.Add_Click($click)
                            $nsb.Add_MouseEnter({
                                param($s, $e)
                                try {
                                    $t = $s.Parent
                                    $en = $s.Tag
                                    if ($null -eq $t -or $null -eq $en) { return }
                                    & $showLibHoverCard $t $en
                                } catch {}
                            })
                            $nsb.Add_MouseLeave({ & $hideLibHoverCardSoon })
                            $tile.Controls.Add($nsb)
                            $nsb.BringToFront()
                        } catch {}
                    }
                }
                Add-TmA 'badge_ms' ((Get-TmNow) - $__b0)
                $__s0 = Get-TmNow
                # Галочка выбора (как на плитках лаунчеров) и рамка выбранной плитки — для кнопки
                # «Обновить апскейлеры». Только у игр с известной папкой (иначе обновлять нечего).
                if (& $isSteamEntrySelectable $entry) {
                    try {
                        $tw = [int]$script:libTileInnerW; $th = [int]$script:libTileInnerH
                        $isSel = $script:libSteamSelected.ContainsKey([string](& $getSteamEntryKey $entry))
                        $frm = New-Object System.Windows.Forms.Panel
                        $frm.Name = 'SelFrame'
                        $frm.Location = New-Object System.Drawing.Point(0, 0)
                        $frm.Size = New-Object System.Drawing.Size($tw, $th)
                        $frm.BackColor = [System.Drawing.Color]::FromArgb(102, 192, 244)
                        $frm.Tag = $entry
                        $frm.Cursor = [System.Windows.Forms.Cursors]::Hand
                        $frmRgn = New-Object System.Drawing.Region((New-Object System.Drawing.Rectangle(0, 0, $tw, $th)))
                        $frmRgn.Exclude((New-Object System.Drawing.Rectangle(3, 3, ($tw - 6), ($th - 6))))
                        $frm.Region = $frmRgn
                        $frm.Visible = $isSel
                        $frm.Add_Click($click)
                        $tile.Controls.Add($frm)
                        $frm.BringToFront()

                        # Галочка рисуется прямо на обложке (со сглаживанием, как на плитках лаунчеров).
                        $pic.AccessibleDescription = 'selcheck'
                        if (-not $hasCover) { $ph.AccessibleDescription = 'selcheck' }
                        & $setSteamTileCheck $tile $isSel
                    } catch {}
                }
                Add-TmA 'selFrame_ms' ((Get-TmNow) - $__s0)
                [void]$script:libTileAll.Add($tile)
                $script:libLastTile = $tile
                Add-TmA 'tileTotal_ms' ((Get-TmNow) - $__tt0); Add-TmA 'tiles_n' 1
    }

    $buildTiles = {
        param($filter)
        try { $libCoverTimer.Stop() } catch {}
        try { $libLocalCoverTimer.Stop() } catch {}
        try { $libTileFillTimer.Stop() } catch {}
        $script:libTilePending = $null
        $script:libTileCountOverride = 0
        try { while ($script:libCoverQueue.Count -gt 0) { [void]$script:libCoverQueue.Dequeue() } } catch {}
        try { $script:libLocalCoverQueue.Clear() } catch {}
        $script:coverProfileRootsKey = $null
        $script:libFilterCatCache = @{}
        # Полностью скрываем панель на время пересборки: программные Invalidate()
        # на AutoScroll-панели не всегда стирают предыдущий кадр (остаются
        # "хвосты" старых плиток при смене отступа/числа колонок). Скрытие и
        # повторный показ контрола форсируют полную чистую перерисовку без
        # этого артефакта — в отличие от одного Invalidate().
        $script:tmA = @{}
        $script:tmBT0 = Get-TmNow
        $flow.Visible = $false
        $flow.SuspendLayout()
        try {
            foreach ($c in @($flow.Controls)) {
                try { $c.Dispose() } catch {}
            }
            $flow.Controls.Clear()
            # Плитки, скрытые фильтром, живут только в кэше — освобождаем и их.
            try { foreach ($c in @($script:libTileAll)) { try { $c.Dispose() } catch {} } } catch {}
            $script:libTileAll = New-Object System.Collections.Generic.List[object]
            $script:libTileAllKey = $null
            $q = ([string]$filter).Trim().ToLowerInvariant()
            $shown = 0
            $allCount = 0
            $entriesAll = @(& $getActiveEntries)
            $allCount = $entriesAll.Count
            $shown = 0
            foreach ($en0 in $entriesAll) {
                if ((-not ($q -and -not ([string]$en0.Name).ToLowerInvariant().Contains($q))) -and (& $passesLibFilter $en0)) { $shown++ }
            }
            # Первое открытие библиотеки: синхронно строим только то, что помещается на экран,
            # остальные плитки досоздаются по таймеру уже после показа окна ($libTileFillTimer).
            $progressive = [bool]$script:libProgressiveOnce
            $script:libProgressiveOnce = $false
            $syncLimit = $allCount
            if ($progressive) {
                $tOw = [int]$script:libTileInnerW + (2 * [int]$script:libTileMargin)
                $tOh = [int]$script:libTileInnerH + (2 * [int]$script:libTileMargin)
                $vw = [Math]::Max(200, [int]$scroll.ClientSize.Width)
                $vh = [Math]::Max(200, [int]$scroll.ClientSize.Height)
                $syncLimit = ([int][Math]::Floor($vw / [double]$tOw)) * ([int][Math]::Ceiling($vh / [double]$tOh) + 1)
                $syncLimit = [Math]::Max(18, [Math]::Min(150, $syncLimit))
            }
            $made = 0
            foreach ($entry in $entriesAll) {
                if ($made -ge $syncLimit) { break }
                # Строим плитки для ВСЕХ игр (кэш), а в сетку добавляем только подходящие под поиск:
                # дальше набор текста в поиске только переставляет готовые плитки (см. $applyTileFilter).
                $tileMatches = (-not ($q -and -not ([string]$entry.Name).ToLowerInvariant().Contains($q))) -and (& $passesLibFilter $entry)
                $script:libLastTile = $null
                $null = & $makeTile $entry
                $madeTile = $script:libLastTile
                if ($null -ne $madeTile -and $tileMatches) { [void]$flow.Controls.Add($madeTile) }
                $made++
            }
            if ($made -lt $allCount) {
                $script:libTilePending = [PSCustomObject]@{ Entries = $entriesAll; Next = $made; Q = $q; Tab = [string]$script:libActiveTab; Total = $allCount }
                # Высоту сетки и полосу прокрутки считаем сразу под ВСЕ плитки — они появятся позже, но прокрутка не будет «прыгать».
                $script:libTileCountOverride = [int]$shown
            }
            try {
                Write-Tm ('buildTiles: синхронная часть плиток завершена (' + $made + ' из ' + $allCount + '), всего ' + [int]((Get-TmNow) - $script:tmBT0) + ' мс')
                foreach ($__k in @($script:tmA.Keys | Sort-Object)) { Write-Tm ('     ' + $__k + ' = ' + [int]$script:tmA[$__k]) }
            } catch {}
            if ($null -eq $script:libTilePending) { $script:libTileAllKey = ([string]$script:libActiveTab + '|' + [string]$allCount) }
            $lblCount.Text = (T 'lib_count' @($shown))
            $script:libShownCount = [int]$shown
            try { & $updateSelectionUi } catch {}
            if ($shown -eq 0) {
                if ([string]$script:libActiveTab -eq 'steam') {
                    $lblCount.Text = (T 'lib_empty')
                } else {
                    $emptyLbl = New-Object System.Windows.Forms.Label
                    $emptyLbl.Size = New-Object System.Drawing.Size(520, 40)
                    $emptyLbl.Margin = New-Object System.Windows.Forms.Padding(12)
                    $emptyLbl.ForeColor = $steamUi.Muted
                    $emptyLbl.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
                    $emptyLbl.Text = (T 'lib_empty_launcher')
                    [void]$flow.Controls.Add($emptyLbl)
                }
            }
        } finally {
            $flow.ResumeLayout($true)
            Write-Tm '   buildTiles finally: flow.ResumeLayout'
            try { & $syncLibraryFlowWidth } catch {}
            try { & $resetLibraryScroll 0 } catch {}
            Write-Tm '   buildTiles finally: syncWidth + resetScroll'
            $flow.Visible = $true
            Write-Tm '   buildTiles finally: flow.Visible = true'
            try { & $stabilizeLibraryGridWidth } catch {}
            Write-Tm '   buildTiles finally: stabilizeGridWidth'
            # Страховка от гонки: ScrollableControl пересчитывает видимость
            # полос на СЛЕДУЮЩЕМ проходе Layout (после того как этот код уже
            # отработал), и горизонтальная полоса может появиться заново.
            # Догоняем её отложенным вызовом уже после обработки текущей
            # очереди сообщений/layout-событий.
            try {
                if (-not $dlg.IsDisposed) {
                    [void]$dlg.BeginInvoke([Action]{
                        try { & $stabilizeLibraryGridWidth } catch {}
                    })
                }
            } catch {}
            # Недостающие плитки — порциями по таймеру, после показа окна.
            if ($null -ne $script:libTilePending) {
                $script:libFillT0 = Get-TmNow
                try { $libTileFillTimer.Start() } catch {}
            }
            # Локальные обложки — порциями по таймеру, уже после показа сетки.
            if ($script:libLocalCoverQueue.Count -gt 0) {
                $script:libLocalCoverT0 = Get-TmNow
                try { $libLocalCoverTimer.Start() } catch {}
            }
            # Обложки с CDN — после отрисовки сетки, пачками в фоне.
            if ($script:libCoverQueue.Count -gt 0) {
                try { $libCoverTimer.Start() } catch {}
            }
        }
    }

    # ===== Вкладки лаунчеров: данные, плитки, выбор, импорт =====
    $script:libTilePalette = @(
        [System.Drawing.Color]::FromArgb(44, 74, 110),
        [System.Drawing.Color]::FromArgb(48, 88, 72),
        [System.Drawing.Color]::FromArgb(82, 64, 112),
        [System.Drawing.Color]::FromArgb(108, 78, 42),
        [System.Drawing.Color]::FromArgb(100, 54, 68),
        [System.Drawing.Color]::FromArgb(42, 82, 96),
        [System.Drawing.Color]::FromArgb(74, 82, 46),
        [System.Drawing.Color]::FromArgb(88, 58, 94)
    )

    # Игры активной вкладки: Steam — общий список библиотеки, иначе — игры лаунчера.
    $getActiveEntries = {
        if ([string]$script:libActiveTab -eq 'steam') {
            @($script:libBrowserEntries)
        } else {
            $L = $script:libLauncherMap[[string]$script:libActiveTab]
            if ($null -ne $L) { @($L.Games) }
        }
    }

    # Игры активной вкладки лаунчера с учётом строки поиска.
    $getVisibleLauncherEntries = {
        $q = ([string]$txtSearch.Text).Trim().ToLowerInvariant()
        $res = @()
        $L = $script:libLauncherMap[[string]$script:libActiveTab]
        if ($null -ne $L) {
            foreach ($en in @($L.Games)) {
                if ($q -and -not ([string]$en.Name).ToLowerInvariant().Contains($q)) { continue }
                $res += $en
            }
        }
        $res
    }

    # Выбор хранится общим для всех вкладок-лаунчеров ($script:libSelected, ключ
    # «лаунчер|id игры») и не сбрасывается при переходе между вкладками. Этот блок
    # собирает все выбранные игры по ВСЕМ лаунчерам — для счётчика и для импорта.
    $getAllSelectedGames = {
        $res = New-Object System.Collections.Generic.List[object]
        foreach ($lid in @($script:libLauncherMap.Keys)) {
            $src = $script:libLauncherMap[$lid]
            if ($null -eq $src) { continue }
            foreach ($g in @($src.Games)) {
                if ([bool]$g.AlreadyInSteam) { continue }
                if ($script:libSelected.ContainsKey([string]$g.Key)) { [void]$res.Add($g) }
            }
        }
        $res.ToArray()
    }

    # ----- Выбор игр на вкладке Steam (галочки, «Выбрать все» / «Снять все», «Обновить апскейлеры») -----
    $getSteamEntryKey = {
        param($en)
        return ([string]$en.Kind + '|' + [string]$en.AppId + '|' + [string]$en.Name)
    }

    # Игра подходит для обновления апскейлеров: у неё есть папка, и это не служебный пакет Steam.
    $isSteamEntrySelectable = {
        param($en)
        try {
            if ($null -eq $en) { return $false }
            $nmL = ([string]$en.Name).ToLowerInvariant()
            if ($nmL -match 'redistributable|steamworks common|directx|vcredist|visual c\+\+') { return $false }
            if ([string]$en.AppId -in @('228980', '228990')) { return $false }
            $d = Get-LibDlssEntryDir $en
            return (-not [string]::IsNullOrWhiteSpace([string]$d))
        } catch { return $false }
    }

    # Игры вкладки Steam с учётом строки поиска.
    $getVisibleSteamEntries = {
        $q = ([string]$txtSearch.Text).Trim().ToLowerInvariant()
        $res = New-Object System.Collections.Generic.List[object]
        foreach ($en in @($script:libBrowserEntries)) {
            if ($q -and -not ([string]$en.Name).ToLowerInvariant().Contains($q)) { continue }
            if (-not (& $passesLibFilter $en)) { continue }
            if (-not (& $isSteamEntrySelectable $en)) { continue }
            [void]$res.Add($en)
        }
        $res.ToArray()
    }

    # Все отмеченные игры вкладки Steam (независимо от строки поиска).
    $getSelectedSteamEntries = {
        $res = New-Object System.Collections.Generic.List[object]
        foreach ($en in @($script:libBrowserEntries)) {
            if (-not $script:libSteamSelected.ContainsKey([string](& $getSteamEntryKey $en))) { continue }
            if (-not (& $isSteamEntrySelectable $en)) { continue }
            [void]$res.Add($en)
        }
        $res.ToArray()
    }

    # Есть ли в папке игры хоть одна библиотека апскейлера (результат фонового поиска; true запоминаем на сессию окна).
    $script:libHasLibsCache = @{}
    $getEntryHasLibs = {
        param($en)
        try {
            $d = Get-LibDlssEntryDir $en
            if ([string]::IsNullOrEmpty($d)) { return $false }
            $k = Get-NormalizedGamePathKey $d
            if ($script:libHasLibsCache.ContainsKey($k)) { return $true }
            $st = $script:libDlssState
            if ($null -ne $st -and $st.ContainsKey('Libs')) {
                $lb = $st['Libs']
                if ($lb.ContainsKey($k) -and [bool]$lb[$k]) { $script:libHasLibsCache[$k] = $true; return $true }
            }
        } catch {}
        return $false
    }

    # Отмеченные игры, которым есть что обновлять: с библиотеками апскейлеров, не ROM-ярлыки.
    $getUpdatableSteamEntries = {
        $res = New-Object System.Collections.Generic.List[object]
        foreach ($en in @(& $getSelectedSteamEntries)) {
            try { if (Test-ShortcutIsRomEntry $en) { continue } } catch {}
            if (-not (& $getEntryHasLibs $en)) { continue }
            [void]$res.Add($en)
        }
        $res.ToArray()
    }

    # Есть ли в папке игры бэкапы оригиналов (.sc_orig); true запоминаем на сессию окна.
    $script:libHasOrigCache = @{}
    $getEntryHasOrig = {
        param($en)
        try {
            $d = Get-LibDlssEntryDir $en
            if ([string]::IsNullOrEmpty($d)) { return $false }
            $k = Get-NormalizedGamePathKey $d
            if ($script:libHasOrigCache.ContainsKey($k)) { return $true }
            $st = $script:libDlssState
            if ($null -ne $st -and $st.ContainsKey('Orig')) {
                $ob = $st['Orig']
                if ($ob.ContainsKey($k) -and [bool]$ob[$k]) { $script:libHasOrigCache[$k] = $true; return $true }
            }
        } catch {}
        return $false
    }

    # Отмеченные игры, в которых есть что возвращать: есть бэкапы .sc_orig, не ROM-ярлыки.
    $getRestorableSteamEntries = {
        $res = New-Object System.Collections.Generic.List[object]
        foreach ($en in @(& $getSelectedSteamEntries)) {
            try { if (Test-ShortcutIsRomEntry $en) { continue } } catch {}
            if (-not (& $getEntryHasOrig $en)) { continue }
            [void]$res.Add($en)
        }
        $res.ToArray()
    }

    # Приводит галочки и рамки плиток Steam в соответствие с выбором.
    $syncSteamTileSelection = {
        foreach ($t in @($flow.Controls)) {
            try {
                $en = $t.Tag
                if ($null -eq $en) { continue }
                $frm = $t.Controls['SelFrame']
                if ($null -eq $frm) { continue }
                $sel = $script:libSteamSelected.ContainsKey([string](& $getSteamEntryKey $en))
                if ([bool]$frm.Visible -ne $sel) { $frm.Visible = $sel }
                & $setSteamTileCheck $t $sel
            } catch {}
        }
    }

    # Состояние галочки на обложке плитки (нативные контролы) или перерисовка (запасной вариант без C#).
    $setSteamTileCheck = {
        param($tile, [bool]$sel)
        foreach ($c in @($tile.Controls)) {
            try {
                if ([string]$c.AccessibleDescription -ne 'selcheck') { continue }
                if ($script:libDlssNativeOk) {
                    $ns = if ($sel) { 2 } else { 1 }
                    if ([int]$c.CheckState -ne $ns) { $c.CheckState = $ns; $c.Invalidate() }
                } else { $c.Invalidate() }
            } catch {}
        }
    }

    # Клик по галочке на плитке: переключает выбор игры, рамку плитки и счётчики.
    $toggleSteamSelection = {
        param($c)
        try {
            if ($script:libUpdRunning -or $script:libImportRunning -or $script:libRestoreRunning) { return }
            $en = $c.Tag
            if ($null -eq $en) { return }
            $k = [string](& $getSteamEntryKey $en)
            if ($script:libSteamSelected.ContainsKey($k)) { $script:libSteamSelected.Remove($k) } else { $script:libSteamSelected[$k] = $true }
            $sel = $script:libSteamSelected.ContainsKey($k)
            $t = $c.Parent
            try {
                $frm = $t.Controls['SelFrame']
                if ($null -ne $frm) { $frm.Visible = $sel }
            } catch {}
            & $setSteamTileCheck $t $sel
            & $updateSelectionUi
        } catch {}
    }

    # Панель внизу и кнопки выбора: на вкладке Steam — «Обновить апскейлеры», на вкладках
    # лаунчеров — автоимпорт и «Импорт». Счётчик выбранных и подписи кнопок.
    $updateSelectionUi = {
        try {
            $isL = ([string]$script:libActiveTab -ne 'steam')
            foreach ($c in @($btnSelectAll, $btnDeselectAll)) { $c.Visible = $true }
            foreach ($c in @($lblAutoImport, $toggleAuto, $btnImport)) { $c.Visible = $isL }
            foreach ($c in @($btnUpdUp, $btnRestoreUp, $btnFilter)) { $c.Visible = (-not $isL) }
            # Кнопка «Фильтр» стоит сразу за поиском (только на вкладке Steam): остальные кнопки и счётчик
            # сдвигаются правее на её ширину + зазор; на вкладках лаунчеров возвращаются на прежние места.
            $fdx = if ($btnFilter.Visible) { [int]($btnFilter.Width + 8) } else { 0 }
            $btnSelectAll.Left = 290 + $fdx
            $btnDeselectAll.Left = 398 + $fdx
            $lblCount.Left = 506 + $fdx
            $lblSelected.Visible = $false
            $lblCount.Width = if ($isL) { 100 } else { 96 }
            if (-not $isL) {
                $cntS = @(& $getSelectedSteamEntries).Count
                $lblSelected.Text = (T 'lib_selected' @($cntS))
                # Один текст «Выбрано: N из M» вместо двух отдельных подписей (пока идёт загрузка/пусто — не трогаем).
                if ([int]$script:libShownCount -gt 0 -and [string]$lblCount.Text -ne (T 'lib_loading')) { $lblCount.Text = (T 'lib_selected_of' @($cntS, [int]$script:libShownCount)) }
                if ([int]$script:libShownCount -gt 0 -and [string]$lblCount.Text -ne (T 'lib_loading')) {
                    # Текст вида «20 / 25» короткий: счётчик сужаем.
                    $lblCount.Width = 76
                }
                $btnSelectAll.Text = (T 'lib_select_all')
                $btnDeselectAll.Text = (T 'lib_deselect_all')
                if ($script:libUpdRunning -or $script:libRestoreRunning) { return }
                $btnUpdUp.Text = (T 'lib_upd_btn')
                $btnRestoreUp.Text = (T 'lib_restore_btn')
                # «Обновить апскейлеры» горит, только если среди отмеченных есть игра с библиотеками (ROM и игры без библиотек не считаются).
                $cntU = @(& $getUpdatableSteamEntries).Count
                $btnUpdUp.Enabled = ($cntU -gt 0)
                $cntR = @(& $getRestorableSteamEntries).Count
                $btnRestoreUp.Enabled = ($cntR -gt 0)
                foreach ($pair in @(@($btnUpdUp, $cntU), @($btnRestoreUp, $cntR))) {
                    $b = $pair[0]
                    if ([int]$pair[1] -gt 0) {
                        $b.FlatAppearance.BorderColor = $steamUi.Accent2
                        $b.ForeColor = $steamUi.Text
                    } else {
                        $b.FlatAppearance.BorderColor = $steamUi.Border
                        $b.ForeColor = $steamUi.Muted
                    }
                }
                $btnSelectAll.Enabled = (@($script:libBrowserEntries).Count -gt 0)
                $btnDeselectAll.Enabled = ($cntS -gt 0)
                return
            }
            # Счётчик и кнопка «Импорт» — по выбору во всех лаунчерах, а не только
            # на активной вкладке.
            $cnt = @(& $getAllSelectedGames).Count
            $lblSelected.Text = (T 'lib_selected' @($cnt))
            $btnImport.Text = if ($cnt -gt 0) { (T 'lib_import_n' @($cnt)) } else { (T 'lib_import') }
            $btnImport.Enabled = ($cnt -gt 0)
            if ($cnt -gt 0) {
                $btnImport.FlatAppearance.BorderColor = $steamUi.Accent2
                $btnImport.ForeColor = $steamUi.Text
            } else {
                $btnImport.FlatAppearance.BorderColor = $steamUi.Border
                $btnImport.ForeColor = $steamUi.Muted
            }
            $selectable = @(@(& $getVisibleLauncherEntries) | Where-Object { -not [bool]$_.AlreadyInSteam })
            $btnSelectAll.Text = (T 'lib_select_all')
            $btnSelectAll.Enabled = ($selectable.Count -gt 0)
            $btnDeselectAll.Text = (T 'lib_deselect_all')
            $btnDeselectAll.Enabled = ($cnt -gt 0)
        } catch {}
    }

    # Плитка игры лаунчера рисуется вручную: цветная заглушка (обложки — на одном
    # из следующих шагов), название внизу, галочка выбора в углу. Уже добавленные
    # в Steam игры — пунктирная плитка с подписью, без галочки и не кликаются.
    # Клик по галочке выбирает игру, клик по остальной плитке открывает карточку.
    $paintLauncherTile = {
        param($sender, $e)
        try {
            $en = $sender.Tag
            if ($null -eq $en) { return }
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
            $w = [int]$sender.ClientSize.Width
            $h = [int]$sender.ClientSize.Height
            $inSteam = [bool]$en.AlreadyInSteam
            $sel = (-not $inSteam) -and $script:libSelected.ContainsKey([string]$en.Key)
            $name = [string]$en.Name

            if ($inSteam) {
                $bgCol = [System.Drawing.Color]::FromArgb(28, 34, 42)
            } else {
                $hs = 7
                foreach ($ch in $name.ToCharArray()) { $hs = (($hs * 31) + [int]$ch) % 100003 }
                $bgCol = $script:libTilePalette[$hs % $script:libTilePalette.Count]
            }
            $bg = New-Object System.Drawing.SolidBrush($bgCol)
            try { $g.FillRectangle($bg, 0, 0, $w, $h) } finally { $bg.Dispose() }

            # Обложка из кэша (если уже подгружена): рисуем на всю плитку.
            $hasCover = $false
            if ($script:libCoverImgs.ContainsKey($name)) {
                try {
                    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                    $g.DrawImage($script:libCoverImgs[$name], 0, 0, $w, $h)
                    $hasCover = $true
                } catch {}
                if ($hasCover -and $inSteam) {
                    $dim = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(165, 12, 16, 22))
                    try { $g.FillRectangle($dim, 0, 0, $w, $h) } finally { $dim.Dispose() }
                }
            }

            $sf = New-Object System.Drawing.StringFormat
            try {
                if (-not $inSteam -and -not $hasCover -and $name.Length -gt 0) {
                    # Крупная бледная буква вместо обложки + затемнение под названием.
                    $lf = New-Object System.Drawing.Font('Segoe UI', 64, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
                    $lb = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(38, 255, 255, 255))
                    $sfc = New-Object System.Drawing.StringFormat
                    try {
                        $sfc.Alignment = [System.Drawing.StringAlignment]::Center
                        $sfc.LineAlignment = [System.Drawing.StringAlignment]::Center
                        $g.DrawString($name.Substring(0, 1).ToUpperInvariant(), $lf, $lb, (New-Object System.Drawing.RectangleF(0, 10, $w, ($h - 60))), $sfc)
                    } finally { $sfc.Dispose(); $lb.Dispose(); $lf.Dispose() }
                    $gr = New-Object System.Drawing.Drawing2D.LinearGradientBrush((New-Object System.Drawing.Rectangle(0, ($h - 72), $w, 72)), [System.Drawing.Color]::FromArgb(0, 0, 0, 0), [System.Drawing.Color]::FromArgb(175, 0, 0, 0), 90.0)
                    try { $g.FillRectangle($gr, 0, ($h - 72), $w, 72) } finally { $gr.Dispose() }
                }

                $sf.Alignment = [System.Drawing.StringAlignment]::Near
                $sf.LineAlignment = [System.Drawing.StringAlignment]::Far
                $sf.Trimming = [System.Drawing.StringTrimming]::EllipsisWord
                $nameFont = New-Object System.Drawing.Font('Segoe UI Semibold', 10)
                $nameBrush = New-Object System.Drawing.SolidBrush($(if ($inSteam) { $steamUi.Muted } else { [System.Drawing.Color]::White }))
                try {
                    if ($inSteam) {
                        if (-not $hasCover) { $g.DrawString($name, $nameFont, $nameBrush, (New-Object System.Drawing.RectangleF(10, ($h - 88), ($w - 20), 58)), $sf) }
                        $lblFont = New-Object System.Drawing.Font('Segoe UI', 8.5)
                        $lblBrush = New-Object System.Drawing.SolidBrush($steamUi.Muted)
                        try { $g.DrawString((T 'lib_already_in_steam'), $lblFont, $lblBrush, (New-Object System.Drawing.RectangleF(10, ($h - 28), ($w - 20), 20)), $sf) }
                        finally { $lblBrush.Dispose(); $lblFont.Dispose() }
                    } elseif (-not $hasCover) {
                        $g.DrawString($name, $nameFont, $nameBrush, (New-Object System.Drawing.RectangleF(10, ($h - 68), ($w - 20), 58)), $sf)
                    }
                } finally { $nameBrush.Dispose(); $nameFont.Dispose() }
            } finally { $sf.Dispose() }

            # Рамка: выбранная — акцентная, уже в Steam — пунктирная.
            if ($sel) {
                $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(102, 192, 244), 3)
                try { $g.DrawRectangle($pen, 1, 1, ($w - 3), ($h - 3)) } finally { $pen.Dispose() }
            } elseif ($inSteam) {
                $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(74, 86, 100), 1.5)
                $pen.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash
                try { $g.DrawRectangle($pen, 1, 1, ($w - 3), ($h - 3)) } finally { $pen.Dispose() }
            }

            # Галочка выбора (скруглённый квадрат 24x24 в левом верхнем углу).
            $path = New-Object System.Drawing.Drawing2D.GraphicsPath
            try {
                $d = 12
                [void]$path.AddArc(8, 8, $d, $d, 180, 90)
                [void]$path.AddArc((32 - $d), 8, $d, $d, 270, 90)
                [void]$path.AddArc((32 - $d), (32 - $d), $d, $d, 0, 90)
                [void]$path.AddArc(8, (32 - $d), $d, $d, 90, 90)
                $path.CloseFigure()
                if ($sel) {
                    $fillCol = [System.Drawing.Color]::FromArgb(30, 144, 230); $edgeCol = $fillCol
                } elseif ($inSteam) {
                    $fillCol = [System.Drawing.Color]::FromArgb(40, 255, 255, 255); $edgeCol = [System.Drawing.Color]::FromArgb(60, 255, 255, 255)
                } else {
                    $fillCol = [System.Drawing.Color]::FromArgb(245, 247, 250); $edgeCol = [System.Drawing.Color]::FromArgb(150, 158, 168)
                }
                $fb = New-Object System.Drawing.SolidBrush($fillCol)
                $ep = New-Object System.Drawing.Pen($edgeCol, 1.2)
                try { $g.FillPath($fb, $path); $g.DrawPath($ep, $path) } finally { $fb.Dispose(); $ep.Dispose() }
            } finally { $path.Dispose() }
            if ($sel) {
                $cp = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 2.4)
                try {
                    $cp.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
                    $cp.EndCap = [System.Drawing.Drawing2D.LineCap]::Round
                    $cp.LineJoin = [System.Drawing.Drawing2D.LineJoin]::Round
                    $pts = @(
                        (New-Object System.Drawing.PointF(13, 20)),
                        (New-Object System.Drawing.PointF(18, 25)),
                        (New-Object System.Drawing.PointF(27, 14))
                    )
                    $g.DrawLines($cp, $pts)
                } finally { $cp.Dispose() }
            }
        } catch {}

            if ($inSteam) {
                try {
                    $badge = Get-LibSteamBadgeBitmap
                    if ($null -ne $badge) {
                        $bw = 22; $bh = 22
                        $bx = [Math]::Max(0, $w - $bw - 6)
                        $by = 6
                        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                        $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
                        $g.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceOver
                        $g.DrawImage($badge, $bx, $by, $bw, $bh)
                    }
                } catch {}
            }
    }

    # Попадание в галочку выбора (рисуется в квадрате 8..32 px; берём небольшой запас по краям).
    $isOverTileCheck = {
        param($pt)
        return ([int]$pt.X -ge 4 -and [int]$pt.X -le 36 -and [int]$pt.Y -ge 4 -and [int]$pt.Y -le 36)
    }

    # Указатель-рука над всей плиткой импортируемой игры: галочка — выбор,
    # остальная плитка — открытие стандартной карточки добавления.
    $launcherTileMove = {
        param($s, $e)
        try {
            $en = $s.Tag
            $hand = ($null -ne $en) -and (-not [bool]$en.AlreadyInSteam)
            $s.Cursor = if ($hand) { [System.Windows.Forms.Cursors]::Hand } else { [System.Windows.Forms.Cursors]::Default }
        } catch {}
    }

    # Открывает стандартную карточку добавления игры (ту же, что открывается из
    # главного окна) для игры лаунчера. Параметры добавления не меняем: карточка
    # сама определяет exe, название и обложки по папке игры.
    $openLauncherEntryCard = {
        param($en)
        if ($null -eq $en -or [bool]$en.AlreadyInSteam) { return }
        try {
            Show-GameEditorDialog $en.Name 'Steam' $en.Path $false $null $null $dlg -IsRomEntry:$false -LauncherEntry $en
        } catch {
            Show-AppMessageBox(
                $dlg,
                (T 'lib_open_fail' @([string]$_.Exception.Message)),
                $global:appTitle,
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
            return
        }
        # Карточку закрыли: если игру в ней добавили в Steam — помечаем плитку
        # как «уже в Steam» и снимаем с неё выбор.
        try {
            if ($script:editorSavedChanges) { try { & $refreshSteamTabEntries } catch {} }
            $added = $null
            try { $added = Find-SteamShortcutRecord ([string]$en.Name) ([string]$en.Path) } catch {}
            if ($null -eq $added) {
                try {
                    $gp = Get-NormalizedGamePathKey ([string]$en.Path)
                    if ($gp) {
                        foreach ($se in @($script:libBrowserEntries)) {
                            if ([string]$se.Kind -ne 'shortcut') { continue }
                            $sd = Get-NormalizedGamePathKey ([string]$se.StartDir)
                            if ($sd -and ($sd -eq $gp -or $sd.StartsWith($gp + '') -or $gp.StartsWith($sd + ''))) {
                                $added = $se; break
                            }
                            $lo = [string]$se.LaunchOptions
                            if ($lo -and $lo.IndexOf($gp, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                                $added = $se; break
                            }
                        }
                    }
                } catch {}
            }
            if ($null -ne $added) {
                $en.AlreadyInSteam = $true
                if ($script:libSelected.ContainsKey([string]$en.Key)) { $script:libSelected.Remove([string]$en.Key) }
                try {
                    $pk = Get-NormalizedGamePathKey ([string]$en.Path)
                    if ($pk) { $global:installedSteamGames[$pk] = $true }
                } catch {}
                foreach ($t in @($flow.Controls)) { try { $t.Invalidate() } catch {} }
                & $updateSelectionUi
            }
        } catch {}
    }

    $launcherTileClick = {
        param($s, $e)
        try {
            if ($script:libImportRunning) { return }
            $en = $s.Tag
            if ($null -eq $en -or [bool]$en.AlreadyInSteam) { return }
            if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
            # Клик по галочке — выбор игры для импорта.
            if (& $isOverTileCheck $e.Location) {
                $k = [string]$en.Key
                if ($script:libSelected.ContainsKey($k)) { $script:libSelected.Remove($k) } else { $script:libSelected[$k] = $true }
                $s.Invalidate()
                & $updateSelectionUi
                return
            }
            # Клик по остальной плитке — стандартная карточка добавления игры.
            & $openLauncherEntryCard $en
        } catch {}
    }

    # ===== Обложки плиток лаунчеров: очередь подгрузки (по одной за тик) =====
    $script:libCoverImgs = @{}
    $script:libCoverFail = @{}
    $script:libCoverBusy = $false
    $coverTimer = New-Object System.Windows.Forms.Timer
    $coverTimer.Interval = 300
    $coverTimer.Add_Tick({
        if ($script:libCoverBusy) { return }
        $script:libCoverBusy = $true
        try {
            if ([string]$script:libActiveTab -eq 'steam') { $coverTimer.Stop(); return }
            $L = $script:libLauncherMap[[string]$script:libActiveTab]
            if ($null -eq $L) { $coverTimer.Stop(); return }
            $repaint = $false
            $todo = $null
            foreach ($en in @($L.Games)) {
                $nm = [string]$en.Name
                if ($script:libCoverImgs.ContainsKey($nm) -or $script:libCoverFail.ContainsKey($nm)) { continue }
                $cp = Get-LauncherCoverCachePath $nm
                if (Test-Path -LiteralPath $cp -PathType Leaf) {
                    $bmp = New-LauncherCoverBitmap $cp $script:libTileInnerW $script:libTileInnerH
                    if ($null -ne $bmp) { $script:libCoverImgs[$nm] = $bmp; $repaint = $true }
                    else { $script:libCoverFail[$nm] = 1; try { Remove-Item -LiteralPath $cp -Force } catch {} }
                    continue
                }
                $mk = $cp + '.miss2'
                if (Test-Path -LiteralPath $mk -PathType Leaf) {
                    if ((Get-Item -LiteralPath $mk).LastWriteTime -gt (Get-Date).AddDays(-7)) { $script:libCoverFail[$nm] = 1; continue }
                }
                if ($null -eq $todo) { $todo = $en }
            }
            if ($repaint) { foreach ($t in @($flow.Controls)) { try { $t.Invalidate() } catch {} } }
            if ($null -eq $todo) { $coverTimer.Stop(); return }
            $nm = [string]$todo.Name
            $cp = Get-LauncherCoverCachePath $nm
            # Качаем с прокачкой UI (curl.exe + DoEvents), иначе Invoke-WebRequest
            # на 20+ секунд вешает всё окно библиотеки.
            $prevPump = $global:uiPumpDuringDownload
            $global:uiPumpDuringDownload = $true
            try {
                $res = Get-LauncherGameCover $todo $cp
            } finally {
                $global:uiPumpDuringDownload = $prevPump
            }
            Write-LauncherLog ('cover [' + $nm + ']: ' + $res)
            if ($res -eq 'ok') {
                $bmp = New-LauncherCoverBitmap $cp $script:libTileInnerW $script:libTileInnerH
                if ($null -ne $bmp) { $script:libCoverImgs[$nm] = $bmp } else { $script:libCoverFail[$nm] = 1 }
                foreach ($t in @($flow.Controls)) { try { $t.Invalidate() } catch {} }
            } elseif ($res -eq 'none') {
                $script:libCoverFail[$nm] = 1
                try { Set-Content -LiteralPath ($cp + '.miss2') -Value (Get-Date).ToString('s') -Encoding UTF8 } catch {}
            } else {
                $script:libCoverFail[$nm] = 1
            }
        } catch {
            Write-LauncherLog ('cover tick error: ' + $_.Exception.Message + ' @ line ' + $_.InvocationInfo.ScriptLineNumber)
        } finally { $script:libCoverBusy = $false }
    })

    $switchTab = {
        param([string]$id)
        if ([string]::IsNullOrWhiteSpace($id) -or $id -eq [string]$script:libActiveTab) { return }
        $script:libActiveTab = $id
        try { if (-not $script:libImportRunning) { & $showLibProgress $false } } catch {}
        try { & $hideLibHoverCardNow } catch {}
        try { $tabBar.Invalidate() } catch {}
        try { & $buildTiles ([string]$txtSearch.Text) } catch {}
        & $updateSelectionUi
        try { $coverTimer.Start() } catch {}
    }

    # "Выбрать все" — отмечает все видимые (с учётом поиска) игры текущей вкладки,
    # которых ещё нет в Steam. Уже отмеченное не трогает и никогда не снимает.
    $btnSelectAll.Add_Click({
        try {
            if ([string]$script:libActiveTab -eq 'steam') {
                foreach ($en in @(& $getVisibleSteamEntries)) {
                    $script:libSteamSelected[[string](& $getSteamEntryKey $en)] = $true
                }
                & $syncSteamTileSelection
                & $updateSelectionUi
                return
            }
            $selectable = @(@(& $getVisibleLauncherEntries) | Where-Object { -not [bool]$_.AlreadyInSteam })
            if ($selectable.Count -eq 0) { return }
            foreach ($en in $selectable) {
                $script:libSelected[[string]$en.Key] = $true
            }
            foreach ($t in @($flow.Controls)) { try { $t.Invalidate() } catch {} }
            & $updateSelectionUi
        } catch {}
    })

    # "Снять все" — снимает выбор со всех игр (на всех вкладках-лаунчерах).
    $btnDeselectAll.Add_Click({
        try {
            if ([string]$script:libActiveTab -eq 'steam') {
                $script:libSteamSelected.Clear()
                & $syncSteamTileSelection
                & $updateSelectionUi
                return
            }
            $script:libSelected.Clear()
            foreach ($t in @($flow.Controls)) { try { $t.Invalidate() } catch {} }
            & $updateSelectionUi
        } catch {}
    })

    # Импорт выбранных игр со ВСЕХ вкладок-лаунчеров. Работает через тот же
    # Invoke-SmartBatchAdd, что и пакетное добавление в главном окне:
    #  - автоимпорт включён: игры с уверенно определёнными названием и exe добавляются без
    #    карточки, остальные открываются карточками по очереди;
    #  - автоимпорт выключен: каждая выбранная игра открывается в карточке.
    # Во время импорта кнопка превращается в «Отменить» (отмена безопасна: текущая игра
    # дорабатывается до конца), остальные элементы окна блокируются.
    # Перечитывает ярлыки Steam и обновляет вкладку Steam сразу после импорта.
    $refreshSteamTabEntries = {
        try {
            $script:libBrowserEntries = @(Get-SteamLibraryEntries)
            try { Start-LibDlssScan $script:libBrowserEntries; $libDlssTimer.Start() } catch {}
        } catch {
            try { Write-LauncherLog ('refreshSteamTabEntries: ' + $_.Exception.Message) } catch {}
            return
        }
        try {
            $steamCount = @($script:libBrowserEntries).Count
            for ($ti = 0; $ti -lt $script:libTabs.Count; $ti++) {
                $tab = $script:libTabs[$ti]
                if ([string]$tab.Id -ne 'steam') { continue }
                $ico = $null
                try { $ico = $tab.Icon } catch {}
                $script:libTabs[$ti] = [PSCustomObject]@{ Id = 'steam'; Name = (T 'lib_kind_steam'); Count = $steamCount; Icon = $ico }
                break
            }
        } catch {}
        try { $tabBar.Invalidate() } catch {}
        if ([string]$script:libActiveTab -eq 'steam') {
            try { & $buildTiles ([string]$txtSearch.Text) } catch {}
            try { & $updateSelectionUi } catch {}
        }
    }

    # Полное обновление библиотеки (кнопка «Обновить» и F5): сбрасываем прогретый снимок, заново читаем
    # ярлыки Steam и все лаунчеры, пересобираем вкладки и плитки. Активная вкладка и текст поиска сохраняются.
    $script:libRefreshing = $false
    $refreshLibraryAll = {
        if ($script:libRefreshing -or $script:libImportRunning -or $script:libUpdRunning -or $script:libRestoreRunning) { return }
        $script:libRefreshing = $true
        $btnLibRefresh.Enabled = $false
        $prevCursor = $dlg.Cursor
        try {
            $dlg.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
            $lblCount.Text = (T 'lib_loading')
            [System.Windows.Forms.Application]::DoEvents()
            try { Reset-LibPreheat } catch {}
            $fpBefore = ''
            try { $fpBefore = Get-LibDataFingerprint } catch {}
            $prevTab = [string]$script:libActiveTab
            $steamIco = $null
            foreach ($ot in @($script:libTabs)) { if ([string]$ot.Id -eq 'steam') { try { $steamIco = $ot.Icon } catch {}; break } }
            $script:libBrowserEntries = @(Get-SteamLibraryEntries)
            try { Start-LibDlssScan $script:libBrowserEntries; $libDlssTimer.Start() } catch {}
            $steamShortcuts = New-Object System.Collections.ArrayList
            foreach ($se in $script:libBrowserEntries) {
                if ([string]$se.Kind -eq 'shortcut') { [void]$steamShortcuts.Add($se) }
            }
            [void](Get-InstalledLauncherSources $steamShortcuts.ToArray())
            $foundSources = $script:libFoundSources
            if ($fpBefore) { try { Set-LibPreheatSnapshot $fpBefore $script:libBrowserEntries $foundSources } catch {} }
            $script:libTabs.Clear()
            $script:libLauncherMap = @{}
            [void]$script:libTabs.Add([PSCustomObject]@{ Id = 'steam'; Name = (T 'lib_kind_steam'); Count = @($script:libBrowserEntries).Count; Icon = $steamIco })
            foreach ($lsrc in @($foundSources)) {
                $lid = [string]$lsrc.Id
                $gcount = 0
                foreach ($gm in @($lsrc.Games)) { $gcount++ }
                $script:libLauncherMap.Item($lid) = $lsrc
                [void]$script:libTabs.Add((New-Object PSObject -Property ([ordered]@{ Id = $lid; Name = [string]$lsrc.Name; Count = $gcount; Icon = $lsrc.Icon })))
            }
            $script:libActiveTab = 'steam'
            foreach ($nt in @($script:libTabs)) { if ([string]$nt.Id -eq $prevTab) { $script:libActiveTab = $prevTab; break } }
            try { $tabBar.Invalidate() } catch {}
            & $buildTiles ([string]$txtSearch.Text)
            try { & $updateSelectionUi } catch {}
            try { & $syncLibraryFlowWidth } catch {}
            try { $coverTimer.Start() } catch {}
        } catch {
            try { Write-LauncherLog ('refreshLibraryAll: ' + $_.Exception.Message) } catch {}
        } finally {
            try { $dlg.Cursor = $prevCursor } catch {}
            $script:libRefreshing = $false
            try { $btnLibRefresh.Invalidate(); $dlg.Invalidate($true) } catch {}
            try { $btnLibRefresh.Enabled = (-not $script:libImportRunning) } catch {}
        }
    }
    $btnLibRefresh.Add_Click({ & $refreshLibraryAll })
    try { $libToolTip.SetToolTip($btnLibRefresh, ((T 'btn_refresh') + ' (F5)')) } catch {}
    $dlg.KeyPreview = $true
    $dlg.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::F5) {
            $_.Handled = $true
            $_.SuppressKeyPress = $true
            & $refreshLibraryAll
        }
    })

    $script:libImportRunning = $false
    $setLibImportLock = {
        param([bool]$locked)
        foreach ($c in @($txtSearch, $btnSelectAll, $btnDeselectAll, $toggleAuto, $lblAutoImport, $btnLibBack, $tabBar, $btnRestoreUp, $btnFilter, $btnLibRefresh)) {
            try { $c.Enabled = (-not $locked) } catch {}
        }
    }
    # «Обновить апскейлеры»: во всех отмеченных играх заменяет найденные DLSS / FSR / XeSS / XeLL
    # на последние СКАЧАННЫЕ версии (из «Библиотек апскейлеров»). Что нашлось в игре — то и меняем;
    # если в игре версия такая же или новее, файл не трогаем. Замена — тем же безопасным способом,
    # что и в карточке игры (бэкап .sc_orig, откат при ошибке). Во время работы кнопка превращается
    # в «Отменить» (текущая игра дорабатывается до конца).
    $btnUpdUp.Add_Click({
        if ($script:libUpdRunning) {
            $script:libUpdCancel = $true
            try { $lblLibStatus.Text = (T 'hd_cancelling') } catch {}
            return
        }
        try {
            $games = @(& $getUpdatableSteamEntries)
            if ($games.Count -eq 0) { return }
            $latest = Get-UpscalerLatestLocalMap
            if ($latest.Count -eq 0) {
                Show-AppMessageBox($dlg, (T 'lib_upd_none_dl'), $global:appTitle,
                    [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
                return
            }
            $answer = Show-AppMessageBox($dlg, ((T 'lib_upd_confirm' @($games.Count)) + "`n`n" + (T 'lib_upd_confirm2')), $global:appTitle,
                [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
            if ($answer -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        } catch { return }

        $script:libUpdRunning = $true
        $script:libUpdCancel = $false
        $updated = 0; $replaced = 0; $same = 0; $none = 0
        $okLines = New-Object System.Collections.Generic.List[string]
        $failLines = New-Object System.Collections.Generic.List[string]
        $wasCancelled = $false
        try {
            & $setLibImportLock $true
            $btnUpdUp.Text = (T 'lib_import_cancel')
            $btnUpdUp.Enabled = $true
            $libProgressBar.Minimum = 0
            $libProgressBar.Maximum = [Math]::Max(1, $games.Count)
            $libProgressBar.Value = 0
            & $showLibProgress $true
            $lblLibPercent.Text = '0%'
            $idx = 0
            foreach ($gm in $games) {
                if ($script:libUpdCancel) { $wasCancelled = $true; break }
                $idx++
                $lblLibStatus.Text = ((T 'lib_upd_progress' @($idx, $games.Count)) + ' — ' + [string]$gm.Name)
                try { $lblLibPercent.Text = ([string][int](100.0 * ($idx - 1) / [Math]::Max(1, $games.Count)) + '%') } catch {}
                [System.Windows.Forms.Application]::DoEvents()
                $r = $null
                try {
                    $gmDir = [string](Get-LibDlssEntryDir $gm)
                    try { $r = Invoke-UpscalerUpdateBackground $gmDir $latest }
                    catch { $r = Update-GameUpscalersInDir $gmDir $latest }
                } catch { $r = [PSCustomObject]@{ Status = 'error'; Replaced = 0; Titles = @(); Error = [string]$_.Exception.Message } }
                switch ([string]$r.Status) {
                    'updated' { try { $script:libHasOrigCache[(Get-NormalizedGamePathKey (Get-LibDlssEntryDir $gm))] = $true } catch {}; $updated++; $replaced += [int]$r.Replaced; [void]$okLines.Add([string]$gm.Name + ': ' + ((@($r.Titles)) -join ', ')) }
                    'same'    { $same++ }
                    'error'   { [void]$failLines.Add([string]$gm.Name + ': ' + [string]$r.Error) }
                    default   { $none++ }
                }
                try {
                    $libProgressBar.Value = [Math]::Min($libProgressBar.Maximum, $idx)
                    $lblLibPercent.Text = ([string][int](100.0 * $idx / [Math]::Max(1, $games.Count)) + '%')
                } catch {}
                [System.Windows.Forms.Application]::DoEvents()
            }
        } finally {
            $script:libUpdRunning = $false
            $script:libUpdCancel = $false
            try { & $setLibImportLock $false } catch {}
            try { & $showLibProgress $false } catch {}
            try { & $updateSelectionUi } catch {}
        }
        # Версии в плитках (полоса DLSS) перечитываем заново.
        try { Start-LibDlssScan $script:libBrowserEntries; $libDlssTimer.Start() } catch {}

        $lines = New-Object System.Collections.Generic.List[string]
        [void]$lines.Add((T 'lib_upd_res_updated' @($updated, $replaced)))
        [void]$lines.Add((T 'lib_upd_res_same' @($same)))
        [void]$lines.Add((T 'lib_upd_res_none' @($none)))
        if ($failLines.Count -gt 0) { [void]$lines.Add((T 'lib_upd_res_fail' @($failLines.Count))) }
        if ($wasCancelled) { [void]$lines.Add((T 'lib_upd_cancelled')) }
        $msg = ($lines -join "`n")
        if ($okLines.Count -gt 0) {
            $msg += ("`n`n" + ((@($okLines | Select-Object -First 6)) -join "`n"))
            if ($okLines.Count -gt 6) { $msg += "`n…" }
        }
        if ($failLines.Count -gt 0) {
            $msg += ("`n`n" + ((@($failLines | Select-Object -First 4)) -join "`n"))
            if ($failLines.Count -gt 4) { $msg += "`n…" }
        }
        $icon = if ($failLines.Count -gt 0) { [System.Windows.Forms.MessageBoxIcon]::Warning } else { [System.Windows.Forms.MessageBoxIcon]::Information }
        try {
            Show-AppMessageBox($dlg, $msg, $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, $icon) | Out-Null
        } catch {}
    })

    # «Вернуть бэкапы»: в отмеченных играх возвращает оригинальные DLL апскейлеров из <dll>.sc_orig
    # (их создаёт «Обновить апскейлеры» перед первой заменой). Бэкапы остаются на месте.
    # Во время работы кнопка превращается в «Отменить» (текущая игра дорабатывается до конца).
    $btnRestoreUp.Add_Click({
        if ($script:libRestoreRunning) {
            $script:libRestoreCancel = $true
            try { $lblLibStatus.Text = (T 'hd_cancelling') } catch {}
            return
        }
        try {
            $games = @(& $getRestorableSteamEntries)
            if ($games.Count -eq 0) { return }
            $answer = Show-AppMessageBox($dlg, ((T 'lib_restore_confirm' @($games.Count)) + "`n`n" + (T 'lib_restore_confirm2')), $global:appTitle,
                [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
            if ($answer -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        } catch { return }

        $script:libRestoreRunning = $true
        $script:libRestoreCancel = $false
        $restored = 0; $replaced = 0; $same = 0; $none = 0
        $okLines = New-Object System.Collections.Generic.List[string]
        $failLines = New-Object System.Collections.Generic.List[string]
        $wasCancelled = $false
        try {
            & $setLibImportLock $true
            $btnUpdUp.Enabled = $false
            $btnRestoreUp.Text = (T 'lib_import_cancel')
            $btnRestoreUp.Enabled = $true
            $libProgressBar.Minimum = 0
            $libProgressBar.Maximum = [Math]::Max(1, $games.Count)
            $libProgressBar.Value = 0
            & $showLibProgress $true
            $lblLibPercent.Text = '0%'
            $idx = 0
            foreach ($gm in $games) {
                if ($script:libRestoreCancel) { $wasCancelled = $true; break }
                $idx++
                $lblLibStatus.Text = ((T 'lib_restore_progress' @($idx, $games.Count)) + ' — ' + [string]$gm.Name)
                try { $lblLibPercent.Text = ([string][int](100.0 * ($idx - 1) / [Math]::Max(1, $games.Count)) + '%') } catch {}
                [System.Windows.Forms.Application]::DoEvents()
                $r = $null
                try {
                    $gmDir = [string](Get-LibDlssEntryDir $gm)
                    $titleOf = @{}
                    foreach ($def in @(Get-UpscalerDefs)) { $titleOf[[string]$def.File] = [string]$def.Title }
                    try { $r = Invoke-UpscalerRestoreBackground $gmDir $titleOf }
                    catch { $r = Restore-GameUpscalersInDir $gmDir $titleOf }
                } catch { $r = [PSCustomObject]@{ Status = 'error'; Replaced = 0; Titles = @(); Error = [string]$_.Exception.Message } }
                switch ([string]$r.Status) {
                    'restored' { $restored++; $replaced += [int]$r.Replaced; [void]$okLines.Add([string]$gm.Name + ': ' + ((@($r.Titles)) -join ', ')) }
                    'same'     { $same++ }
                    'error'    { [void]$failLines.Add([string]$gm.Name + ': ' + [string]$r.Error) }
                    default    { $none++ }
                }
                try {
                    $libProgressBar.Value = [Math]::Min($libProgressBar.Maximum, $idx)
                    $lblLibPercent.Text = ([string][int](100.0 * $idx / [Math]::Max(1, $games.Count)) + '%')
                } catch {}
                [System.Windows.Forms.Application]::DoEvents()
            }
        } finally {
            $script:libRestoreRunning = $false
            $script:libRestoreCancel = $false
            try { & $setLibImportLock $false } catch {}
            try { & $showLibProgress $false } catch {}
            try { & $updateSelectionUi } catch {}
        }
        # Версии в плитках (полоса DLSS) перечитываем заново.
        try { Start-LibDlssScan $script:libBrowserEntries; $libDlssTimer.Start() } catch {}

        $lines = New-Object System.Collections.Generic.List[string]
        [void]$lines.Add((T 'lib_restore_res_restored' @($restored, $replaced)))
        [void]$lines.Add((T 'lib_restore_res_same' @($same)))
        [void]$lines.Add((T 'lib_restore_res_none' @($none)))
        if ($failLines.Count -gt 0) { [void]$lines.Add((T 'lib_restore_res_fail' @($failLines.Count))) }
        if ($wasCancelled) { [void]$lines.Add((T 'lib_upd_cancelled')) }
        $msg = ($lines -join "`n")
        if ($okLines.Count -gt 0) {
            $msg += ("`n`n" + ((@($okLines | Select-Object -First 6)) -join "`n"))
            if ($okLines.Count -gt 6) { $msg += "`n…" }
        }
        if ($failLines.Count -gt 0) {
            $msg += ("`n`n" + ((@($failLines | Select-Object -First 4)) -join "`n"))
            if ($failLines.Count -gt 4) { $msg += "`n…" }
        }
        $icon = if ($failLines.Count -gt 0) { [System.Windows.Forms.MessageBoxIcon]::Warning } else { [System.Windows.Forms.MessageBoxIcon]::Information }
        try {
            Show-AppMessageBox($dlg, $msg, $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::OK, $icon) | Out-Null
        } catch {}
    })

    $btnImport.Add_Click({
        if ($script:libImportRunning) {
            $script:batchCardCancelRequested = $true
            try { $lblLibStatus.Text = (T 'hd_cancelling') } catch {}
            return
        }
        try {
            # Игры из всех лаунчеров одним пакетом; каждая запись знает свой
            # лаунчер (Entry.Launcher), поэтому смешанный список обрабатывается
            # теми же правилами, что и по отдельности.
            $gameArr = @(& $getAllSelectedGames)
            if ($gameArr.Count -eq 0) { return }

            $script:libImportRunning = $true
            & $setLibImportLock $true
            $btnImport.Text = (T 'lib_import_cancel')
            $btnImport.Enabled = $true
            $lblLibStatus.Text = ''
            $lblLibPercent.Text = ''
            $libProgressBar.Value = 0
            & $showLibProgress $true
            $stRef = $lblLibStatus; $pbRef = $libProgressBar; $pcRef = $lblLibPercent
            $statusHook = { param($t) try { $stRef.Text = [string]$t; [System.Windows.Forms.Application]::DoEvents() } catch {} }.GetNewClosure()
            $progressHook = {
                param($v)
                try {
                    $n = [Math]::Max(0, [Math]::Min(100, [int]$v))
                    $pbRef.Value = $n
                    $pcRef.Text = if ($n -gt 0 -and $n -lt 100) { "$n%" } else { '' }
                    [System.Windows.Forms.Application]::DoEvents()
                } catch {}
            }.GetNewClosure()
            $res = $null
            try {
                $res = Invoke-SmartBatchAdd $gameArr ([bool]$toggleAuto.Checked) $dlg $statusHook $progressHook
            } catch {
                try { $lblLibStatus.Text = (T 'hd_autofill_err' @([string]$_.Exception.Message)) } catch {}
            } finally {
                $script:libImportRunning = $false
                & $setLibImportLock $false
            }

            # Сразу перечитываем библиотеку Steam (shortcuts.vdf), чтобы новые
            # ярлыки были на вкладке Steam без перезапуска программы.
            try { & $refreshSteamTabEntries } catch {}

            # Игры, реально попавшие в Steam, помечаем на плитках и снимаем с них выбор.
            foreach ($g in $gameArr) {
                $added = $null
                try { $added = Find-SteamShortcutRecord ([string]$g.Name) ([string]$g.Path) } catch {}
                # Обёртка SCLauncher: путь игры в --dir LaunchOptions, а не в Exe.
                if ($null -eq $added) {
                    try {
                        $gp = Get-NormalizedGamePathKey ([string]$g.Path)
                        if ($gp) {
                            foreach ($se in @($script:libBrowserEntries)) {
                                if ([string]$se.Kind -ne 'shortcut') { continue }
                                $sd = Get-NormalizedGamePathKey ([string]$se.StartDir)
                                if ($sd -and ($sd -eq $gp -or $sd.StartsWith($gp + '') -or $gp.StartsWith($sd + ''))) {
                                    $added = $se; break
                                }
                                $lo = [string]$se.LaunchOptions
                                if ($lo -and $lo.IndexOf($gp, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                                    $added = $se; break
                                }
                            }
                        }
                    } catch {}
                }
                if ($null -ne $added) {
                    $g.AlreadyInSteam = $true
                    if ($script:libSelected.ContainsKey([string]$g.Key)) { $script:libSelected.Remove([string]$g.Key) }
                    try {
                        $pk = Get-NormalizedGamePathKey ([string]$g.Path)
                        if ($pk) { $global:installedSteamGames[$pk] = $true }
                    } catch {}
                }
            }
            foreach ($t in @($flow.Controls)) { try { $t.Invalidate() } catch {} }
            & $updateSelectionUi
            try { & $showLibProgress $false } catch {}
        } catch {
            $script:libImportRunning = $false
            try { & $setLibImportLock $false } catch {}
            try { & $updateSelectionUi } catch {}
            try { & $showLibProgress $false } catch {}
        }
    })

    # Быстрый поиск: готовые плитки из кэша ($script:libTileAll) переставляются в сетку без
    # пересоздания контролов и без перечитывания обложек. Возвращает $false, если кэш не подходит
    # (другая вкладка, список игр изменился, ничего не найдено) — тогда нужна полная пересборка.
    $applyTileFilter = {
        param($filter)
        try {
            $all = $script:libTileAll
            if ($null -eq $all -or $all.Count -eq 0) { return $false }
            $curKey = ([string]$script:libActiveTab + '|' + [string]@(& $getActiveEntries).Count)
            if ([string]$script:libTileAllKey -ne $curKey) { return $false }
            $q = ([string]$filter).Trim().ToLowerInvariant()
            $vis = New-Object System.Collections.Generic.List[System.Windows.Forms.Control]
            foreach ($t in $all) {
                $en = $t.Tag
                if ($null -eq $en) { continue }
                if ($q -and -not ([string]$en.Name).ToLowerInvariant().Contains($q)) { continue }
                if (-not (& $passesLibFilter $en)) { continue }
                [void]$vis.Add($t)
            }
            try { & $hideLibHoverCardNow } catch {}
            $flow.Visible = $false
            $flow.SuspendLayout()
            try {
                # Служебные контролы без Tag (напр. надпись «пусто») в кэше не живут — удаляем.
                foreach ($c in @($flow.Controls)) {
                    if ($null -eq $c.Tag) { try { $c.Dispose() } catch {} }
                }
                $flow.Controls.Clear()
                $script:libShownCount = [int]$vis.Count
                if ($vis.Count -gt 0) {
                    $flow.Controls.AddRange($vis.ToArray())
                    $lblCount.Text = (T 'lib_count' @($vis.Count))
                } elseif ([string]$script:libActiveTab -eq 'steam') {
                    # Ничего не найдено: кэш плиток не трогаем, просто показываем пустую сетку.
                    $lblCount.Text = (T 'lib_empty')
                } else {
                    $lblCount.Text = (T 'lib_count' @(0))
                    $emptyLbl = New-Object System.Windows.Forms.Label
                    $emptyLbl.Size = New-Object System.Drawing.Size(520, 40)
                    $emptyLbl.Margin = New-Object System.Windows.Forms.Padding(12)
                    $emptyLbl.ForeColor = $steamUi.Muted
                    $emptyLbl.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
                    $emptyLbl.Text = (T 'lib_empty_launcher')
                    [void]$flow.Controls.Add($emptyLbl)
                }
            } finally {
                $flow.ResumeLayout($true)
                try { & $syncLibraryFlowWidth } catch {}
                try { & $resetLibraryScroll 0 } catch {}
                $flow.Visible = $true
                try { & $stabilizeLibraryGridWidth } catch {}
                try {
                    if (-not $dlg.IsDisposed) {
                        [void]$dlg.BeginInvoke([Action]{
                            try { & $stabilizeLibraryGridWidth } catch {}
                        })
                    }
                } catch {}
            }
            return $true
        } catch { return $false }
    }

    $searchTimer = New-Object System.Windows.Forms.Timer
    $searchTimer.Interval = 150
    $searchTimer.Add_Tick({
        try { $searchTimer.Stop() } catch {}
        $fastOk = $false
        try { $fastOk = [bool](& $applyTileFilter $txtSearch.Text) } catch { $fastOk = $false }
        if (-not $fastOk) {
            try { & $buildTiles $txtSearch.Text } catch {}
        }
        try { & $updateSelectionUi } catch {}
    })
    $txtSearch.Add_TextChanged({
        try { $searchTimer.Stop(); $searchTimer.Start() } catch {}
    })

    $dlg.Add_Shown({
        try {
            $dlg.SuspendLayout()
            $scroll.SuspendLayout()
            $flow.SuspendLayout()
            $lblCount.Text = (T 'lib_loading')
            $script:libShownCount = 0
            Write-Tm 'Add_Shown: старт (окно показано)'
            # Прогретый снимок (см. Get-LibPreheatSnapshot): записи Steam и лаунчеры уже прочитаны, пока было открыто главное окно.
            $libSnap = $null
            try { $libSnap = Get-LibPreheatSnapshot } catch { $libSnap = $null }
            $libFpBefore = ''
            if ($null -ne $libSnap) {
                $script:libBrowserEntries = @(Copy-LibObjectList $libSnap.Entries)
                Write-Tm ('Get-SteamLibraryEntries ИЗ ПРОГРЕВА, записей: ' + @($script:libBrowserEntries).Count)
            } else {
                try { $libFpBefore = Get-LibDataFingerprint } catch { $libFpBefore = '' }
                $script:libBrowserEntries = @(Get-SteamLibraryEntries)
                Write-Tm ('Get-SteamLibraryEntries, записей: ' + @($script:libBrowserEntries).Count)
            }
            try { Start-LibDlssScan $script:libBrowserEntries; $libDlssTimer.Start() } catch {}
            Write-Tm 'Start-LibDlssScan (запуск фонового)'
            # Вкладки: Steam всегда первая, дальше — обнаруженные в системе лаунчеры.
            $script:libTabs.Clear()
            $script:libLauncherMap = @{}
            $script:libActiveTab = 'steam'
            $steamTabIcon = $null
            try { $steamTabIcon = Get-LibSteamBadgeBitmap } catch {}
            if ($null -eq $steamTabIcon) {
                try {
                    $gl = New-LauncherGlyphBitmap 'S' ([System.Drawing.Color]::FromArgb(30, 144, 230)) 64
                    try { $steamTabIcon = ConvertTo-LibUniformIcon $gl } finally { $gl.Dispose() }
                } catch {}
            }
            [void]$script:libTabs.Add([PSCustomObject]@{ Id = 'steam'; Name = (T 'lib_kind_steam'); Count = @($script:libBrowserEntries).Count; Icon = $steamTabIcon })
            Write-Tm 'иконка вкладки Steam'
            $libStep = 'start'
            try {
                # Non-Steam ярлыки — простым циклом (без Where-Object), для проверки "уже в Steam".
                $libStep = 'shortcuts'
                $steamShortcuts = New-Object System.Collections.ArrayList
                foreach ($se in $script:libBrowserEntries) {
                    if ([string]$se.Kind -eq 'shortcut') { [void]$steamShortcuts.Add($se) }
                }
                Write-LauncherLog ('step shortcuts ok: ' + $steamShortcuts.Count)
                $libStep = 'scan'
                if ($null -ne $libSnap) {
                    $script:libFoundSources = New-Object System.Collections.ArrayList
                    foreach ($cs in @($libSnap.Sources)) { [void]$script:libFoundSources.Add((Copy-LibLauncherSource $cs)) }
                    Write-LauncherLog ('step scan from preheat: ' + $script:libFoundSources.Count + ' sources')
                    Write-Tm 'Get-InstalledLauncherSources ИЗ ПРОГРЕВА'
                } else {
                    [void](Get-InstalledLauncherSources $steamShortcuts.ToArray())
                    Write-Tm 'Get-InstalledLauncherSources (ВСЕ лаунчеры)'
                    # Свежий результат сохраняем: повторное открытие библиотеки тоже будет быстрым.
                    if ($libFpBefore) { try { Set-LibPreheatSnapshot $libFpBefore $script:libBrowserEntries $script:libFoundSources } catch {} }
                }
                $foundSources = $script:libFoundSources
                Write-LauncherLog ('step scan ok: ' + @($foundSources).Count + ' sources')
                foreach ($lsrc in @($foundSources)) {
                    $libStep = 'tab ' + [string]$lsrc.Id
                    $lid = [string]$lsrc.Id
                    $gcount = 0
                    foreach ($gm in @($lsrc.Games)) { $gcount++ }
                    $script:libLauncherMap.Item($lid) = $lsrc
                    Write-LauncherLog ('step map ok: ' + $lid)
                    $tabObj = New-Object PSObject -Property ([ordered]@{ Id = $lid; Name = [string]$lsrc.Name; Count = $gcount; Icon = $lsrc.Icon })
                    [void]$script:libTabs.Add($tabObj)
                    Write-LauncherLog ('step tab ok: ' + $lid + ' games=' + $gcount)
                }
            } catch {
                Write-LauncherLog ('tabs build error at step [' + $libStep + '] line ' + $_.InvocationInfo.ScriptLineNumber + ': ' + $_.Exception.Message)
                try { Write-LauncherLog ($_.ScriptStackTrace) } catch {}
            }
            try { $tabBar.Invalidate() } catch {}
            Write-Tm 'вкладки собраны'
            $script:libProgressiveOnce = $true
            & $buildTiles ''
            $script:libProgressiveOnce = $false
            Write-Tm 'buildTiles'
            try { & $updateSelectionUi } catch {}
            try { & $syncLibraryFlowWidth } catch {}
            try { $coverTimer.Start() } catch {}
            try { & $resetLibraryScroll 0 } catch {}
            Write-Tm 'updateSelectionUi / syncFlowWidth / resetScroll'
            # Уже созданный SCLauncher.exe обновляем при смене версии: ярлыки Steam
            # указывают на этот же файл, поэтому новая логика подхватится без повторного добавления игр.
            try {
                if (Test-Path -LiteralPath (Join-Path (Join-Path $global:appDataDir 'launcher') 'SCLauncher.exe') -PathType Leaf) { [void](Ensure-SCLauncherExe) }
            } catch {}
            Write-Tm 'Ensure-SCLauncherExe'
            # Папки распаковки ROM от убитых/прерванных запусков чистит сам SCLauncher.exe.
            try {
                if (-not $script:romCleanupDone) {
                    $script:romCleanupDone = $true
                    $sclRom = Join-Path (Join-Path $global:appDataDir 'launcher') 'SCLauncher.exe'
                    if (Test-Path -LiteralPath $sclRom -PathType Leaf) { Start-Process -FilePath $sclRom -ArgumentList '--cleanup-roms 1' -WindowStyle Hidden }
                }
            } catch {}
            $flow.ResumeLayout($true)
            $scroll.ResumeLayout($true)
            $dlg.ResumeLayout($true)
            Write-Tm 'ResumeLayout x3 (раскладка плиток)'
            # Один финальный кадр — уже с сеткой, без промежуточных «пустых» отрисовок.
            $dlg.Opacity = 1
            # Библиотека перекрыла главное окно: делаем его невидимым, но НЕ прячем — Hide() владельца спрятал бы
            # и саму библиотеку, а кнопка программы на панели задач должна остаться. Возвращается в FormClosing.
            try { $form.Opacity = 0; $form.UseWaitCursor = $false } catch {}
            # После первого показа ClientSize/полосы стабилизируются — ещё один
            # проход убирает горизонтальный скролл, который иначе виден до
            # первого Resize (maximize/restore).
            try {
                $dlg.BeginInvoke([Action]{
                    try { & $syncLibraryFlowWidth } catch {}
                    try { & $forceNoHScroll } catch {}
                    Write-Tm '=== ГОТОВО ==='
                }) | Out-Null
            } catch {}
        } catch {
            try { $flow.ResumeLayout($true); $scroll.ResumeLayout($true); $dlg.ResumeLayout($true) } catch {}
            $dlg.Opacity = 1
            $lblCount.Text = (T 'lib_open_fail' @([string]$_.Exception.Message))
        }
    })

    # Окно библиотеки сейчас и есть "лицо" программы (главное окно на это
    # время спрятано, см. $btnSteamLibrary.Add_Click) — поэтому закрытие её
    # крестиком/Alt+F4 воспринимается как закрытие всей программы целиком,
    # а не просто как возврат в главное окно. Кнопка "Назад" — другое дело:
    # она сама выставляет $script:libClosingViaBack = $true перед закрытием.
    $dlg.Add_FormClosing({
        # Идёт обновление апскейлеров (файлы игр заменяются): не закрываем, просим отмену.
        if ($script:libUpdRunning) {
            $_.Cancel = $true
            $script:libUpdCancel = $true
            return
        }
        # Идёт импорт (Steam закрыт, ярлыки пишутся): окно не закрываем, а просим отмену.
        if ($script:libImportRunning) {
            $_.Cancel = $true
            $script:batchCardCancelRequested = $true
            return
        }
        if (-not $script:libClosingViaBack) {
            try { [System.Windows.Forms.Application]::Exit() } catch {}
        }
        # Возвращаем главное окно, пока библиотека ещё на экране: на месте закрывшейся она сразу «превращается» в него.
        try { $form.Opacity = 1; $form.UseWaitCursor = $false } catch {}
    })

    $dlg.Add_FormClosed({
        try { $script:libHoverShowTimer.Stop(); $script:libHoverShowTimer.Dispose() } catch {}
        try { $script:libHoverHideTimer.Stop(); $script:libHoverHideTimer.Dispose() } catch {}
        try {
            if ($null -ne $libHoverPic.Image) { $libHoverPic.Image.Dispose(); $libHoverPic.Image = $null }
        } catch {}
        try {
            foreach ($im in @($script:libHoverImages)) { try { $im.Dispose() } catch {} }
            $script:libHoverImages.Clear()
        } catch {}
        try { $libCoverTimer.Stop(); $libCoverTimer.Dispose() } catch {}
        try { $libLocalCoverTimer.Stop(); $libLocalCoverTimer.Dispose() } catch {}
        try { $libTileFillTimer.Stop(); $libTileFillTimer.Dispose() } catch {}
        $script:libTilePending = $null
        $script:libTileCountOverride = 0
        try { $script:libLocalCoverQueue.Clear() } catch {}
        try { Save-CoverPathMemo } catch {}
        try { while ($script:libCoverQueue.Count -gt 0) { [void]$script:libCoverQueue.Dequeue() } } catch {}
        try {
            foreach ($c in @($script:libCoverClients)) {
                try { $c.CancelAsync() } catch {}
                try { $c.Dispose() } catch {}
            }
            $script:libCoverClients.Clear()
        } catch {}
        $script:libCoverInflight = 0
        try { $searchTimer.Stop(); $searchTimer.Dispose() } catch {}
        try { $libDlssTimer.Stop(); $libDlssTimer.Dispose() } catch {}
        try { $libReflowTimer.Stop(); $libReflowTimer.Dispose() } catch {}
        try { if ($null -ne $script:libDlssBarBrush) { $script:libDlssBarBrush.Dispose() } } catch {}
        try { if ($null -ne $script:libDlssFontL) { $script:libDlssFontL.Dispose() } } catch {}
        try { if ($null -ne $script:libDlssFontR) { $script:libDlssFontR.Dispose() } } catch {}
        $script:libDlssBarBrush = $null; $script:libDlssFontL = $null; $script:libDlssFontR = $null
        try { Stop-LibDlssScan } catch {}
        foreach ($img in $tileImages) { try { $img.Dispose() } catch {} }
        # Значки вкладок — общие кэшированные Bitmap (см. Get-LibUniformIcon); освобождать их нельзя.
        try { $libToolTip.Dispose() } catch {}
        try { $coverTimer.Stop(); $coverTimer.Dispose() } catch {}
        try { foreach ($cb in @($script:libCoverImgs.Values)) { try { $cb.Dispose() } catch {} }; $script:libCoverImgs.Clear() } catch {}
    })

    try { Initialize-FormForSmallScreen -Form $dlg -Owner $form } catch {}
    Write-Tm 'окно построено, перед ShowDialog (создание всех контролов)'
    $dlg.ShowDialog($form) | Out-Null
}

function Show-GameEditorDialog($gameName, $source, $gamePath, [bool]$batchMode = $false, $batchHost = $null, $libraryEntry = $null, $ownerWin = $null, [bool]$IsRomEntry = $false, $LauncherEntry = $null) {
    # Окно-владелец карточки: если её открыли из библиотеки — это окно
    # библиотеки (карточка должна блокировать именно его и после закрытия
    # возвращать на передний план именно его, а не прятать/поднимать главное
    # окно программы, которое всё это время скрыто). Если карточку открыли
    # не из библиотеки — владелец по умолчанию главное окно, как раньше.
    if ($null -eq $ownerWin) { $ownerWin = $form }
    # Каждая новая карточка начинает с чистого состояния отмены.
    # Предыдущая карточка могла быть закрыта во время сетевой загрузки.
    $global:editorLoadAbortRequested = $false
    if($batchMode){ if (-not $script:smartBatchActive) { $script:batchCardCancelRequested = $false }; $script:batchCardSkipRequested = $false }
    $editMode = $false
    $existingShortcut = $null
    $licensedMode = $false
    $licensedAppId = ''
    if ($IsRomEntry -and -not [string]::IsNullOrWhiteSpace([string]$gamePath) -and (Test-Path -LiteralPath $gamePath -PathType Leaf)) {
        try { $gameName = Get-RomFileTitle ([string]$gamePath) } catch {}
    }
    # Исходное имя папки/файла, по которому программа ищет игру. Именно оно
    # всегда стоит в заголовке окна карточки — найденное поиском название
    # (SteamGridDB/Steam) в заголовок не попадает, оно только в поле «Название».
    $originalCardName = [string]$gameName
    # Steam перезапускается после закрытия карточки только если он правда был
    # убит (taskkill) в этой сессии карточки — то есть при реальном сохранении
    # изменений. Раньше перезапуск срабатывал всегда при editMode, даже если
    # пользователь просто открыл и закрыл/отменил карточку: Steam ни разу не
    # закрывался, но всё равно поднимался на передний план, из-за чего главное
    # окно программы (и всё, что было под ним) уходило в фон без причины.
    $script:steamWasKilledThisSession = $false
    # Флаг «карточка реально что-то сохранила» — от него зависит, нужно ли после закрытия
    # перечитывать диск/Steam (при закрытии без изменений это давало подвисание на секунды).
    $script:editorSavedChanges = $false
    if ($null -ne $libraryEntry -and [string]$libraryEntry.Kind -eq 'steam') {
        $licensedMode = $true
        $editMode = $true
        $licensedAppId = [string]$libraryEntry.AppId
        if (-not [string]::IsNullOrWhiteSpace([string]$libraryEntry.Name)) {
            $gameName = [string]$libraryEntry.Name
        }
        if (-not [string]::IsNullOrWhiteSpace([string]$libraryEntry.Path)) {
            $gamePath = [string]$libraryEntry.Path
        }
    } elseif ($null -ne $libraryEntry -and [string]$libraryEntry.Kind -eq 'shortcut' -and $null -ne $libraryEntry.ShortcutRecord) {
        # Ярлык уже найден заранее в окне "Библиотека Steam" (Get-SteamLibraryEntries) —
        # используем готовую запись напрямую, не ищем повторно по имени/пути ниже.
        # Это принципиально для ROM-ярлыков: у них Exe — путь к эмулятору, он
        # ОДИНАКОВЫЙ у всех игр на этом эмуляторе, и $gamePath здесь — папка с
        # ромом, а не папка эмулятора, так что обычный поиск по пути (см. ниже)
        # такой ярлык всё равно не нашёл бы.
        $existingShortcut = $libraryEntry.ShortcutRecord
        $editMode = $true
        if (-not [string]::IsNullOrWhiteSpace([string]$existingShortcut.AppName)) { $gameName = [string]$existingShortcut.AppName }
    }
    if(-not $batchMode -and -not $licensedMode -and $null -eq $existingShortcut){
        try { $existingShortcut = Find-SteamShortcutRecord $gameName $gamePath } catch { $existingShortcut = $null }
        if($existingShortcut -ne $null){
            $editMode = $true
            # AppName в shortcuts.vdf — это пользовательское отображаемое имя
            # ярлыка. Не используем его как единственный источник для поиска
            # Steam App ID и не подменяем им $gameName: пользователь мог назвать
            # игру на русском/своим именем, а папка осталась оригинальной.
            if(-not [string]::IsNullOrWhiteSpace([string]$existingShortcut.AppName)){ $gameName=[string]$existingShortcut.AppName }
        }
    }
    # Все элементы верхней строки выровнены по общей вертикали: Y=14, высота=28 px.
    # Подписи центрируются относительно этой строки отдельной координатой Y=17.
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = (T 'card_title' @($originalCardName))
    # В режиме ROMs между строкой "Эмулятор" и строкой "Параметры" добавляется
    # ещё одна строка — "ROM". Все контролы ниже неё (сами "Параметры",
    # статус-строка и слоты обложек) сдвигаются вниз на высоту этой строки,
    # а диалог соответственно увеличивается по высоте. В обычном режиме
    # (не ROMs) смещение нулевое — раскладка полностью прежняя.
    $romRowOffset = if ($IsRomEntry) { 37 } else { 0 }
    $dlg.Size = New-Object System.Drawing.Size(900, (735 + $romRowOffset))
    if($batchHost -ne $null){
        # Встраивание карточки как дочернего контрола в панель отдельного окна
        # пакета сейчас никем не используется (и авто-пакет, и обычный пакет
        # открывают карточку отдельным диалогом — см. ветку else ниже), но
        # параметр $batchHost оставлен на случай, если такой режим встраивания
        # понадобится снова.
        $dlg.TopLevel = $false
        $dlg.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::None
        $dlg.StartPosition = 'Manual'
        $dlg.Location = New-Object System.Drawing.Point(0, 0)
    } else {
        $dlg.StartPosition = "CenterParent"
        $dlg.FormBorderStyle = "FixedDialog"
    }
    $dlg.MaximizeBox = $false
    $dlg.BackColor = $steamUi.Bg
    $dlg.ForeColor = $steamUi.Text
    $dlg.Font = New-Object System.Drawing.Font("Segoe UI", 9)

    # Во время первичного открытия карточки ни одно поле ввода не должно получать
    # фокус автоматически. WinForms обычно передаёт фокус первому доступному
    # TextBox, из-за чего при установке/обновлении текста он может визуально
    # выделиться целиком (особенно пока загрузка обложек прокачивает UI через
    # Application.DoEvents()). Невидимая точка фокуса — маленькая кнопка вне
    # рабочей области — принимает фокус на время начальной загрузки. После этого
    # пользователь сам кликает/переходит в нужное поле.
    $editorFocusSink = New-Object System.Windows.Forms.Button
    $editorFocusSink.Name = 'EditorFocusSink'
    $editorFocusSink.Text = ''
    $editorFocusSink.Location = New-Object System.Drawing.Point(0,0)
    $editorFocusSink.Size = New-Object System.Drawing.Size(1,1)
    $editorFocusSink.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $editorFocusSink.FlatAppearance.BorderSize = 0
    $editorFocusSink.BackColor = $steamUi.Bg
    $editorFocusSink.ForeColor = $steamUi.Bg
    $editorFocusSink.TabStop = $false
    $editorFocusSink.Cursor = [System.Windows.Forms.Cursors]::Default
    $dlg.Controls.Add($editorFocusSink)

    $titleLbl = New-Object System.Windows.Forms.Label; $titleLbl.Text=(T 'card_name'); $titleLbl.Location='20,14'; $titleLbl.Size='90,28'; $titleLbl.ForeColor=$steamUi.Muted; $titleLbl.TextAlign=[System.Drawing.ContentAlignment]::MiddleLeft; $dlg.Controls.Add($titleLbl)
    # Значок уверенности в названии: зелёная галочка — Steam/SGDB подтвердили
    # это название, красный "!" — совпадение не найдено, нужна ручная проверка.
    $titleConfidenceBadge = New-ConfidenceBadge $dlg 91 19
    # Название — отдельное поле ввода. Список результатов больше НЕ является частью
    # ComboBox: это принципиально важно, потому что WinForms ComboBox может менять
    # Text/SelectedIndex при Clear/Add Items. Теперь поиск вообще не имеет права
    # менять введённый текст — он только обновляет отдельный нативный ComboBox-popup под полем.
    #
    # Однострочный TextBox в WinForms игнорирует заданную высоту и сам сжимается
    # до "предпочтительной" высоты под текущий шрифт, поэтому рамка рисовалась не
    # по тем 28px, что мы просили, и текст внутри казался прижатым кверху
    # относительно соседних кнопок/подписей. Чтобы получить ровно 28px высоты с
    # текстом строго по центру, рамку и фон теперь рисует Panel, а сам TextBox
    # лежит внутри неё без своей рамки и центрируется по вертикали вручную.
    $pnlTitle = New-Object System.Windows.Forms.Panel
    $pnlTitle.Location='115,14'; $pnlTitle.Size='420,28'
    $pnlTitle.BackColor=$steamUi.Input; $pnlTitle.BorderStyle='FixedSingle'
    $dlg.Controls.Add($pnlTitle)

    $txtTitle = New-Object System.Windows.Forms.TextBox
    $txtTitle.Text=$gameName; $txtTitle.AutoSize=$false; $txtTitle.BorderStyle='None'
    $txtTitle.BackColor=$steamUi.Input; $txtTitle.ForeColor=$steamUi.Text
    $txtTitle.Font=New-Object System.Drawing.Font('Segoe UI',9)
    $pnlTitle.Controls.Add($txtTitle)
    $txtTitle.Width = $pnlTitle.ClientSize.Width - 10
    $txtTitle.Location = New-Object System.Drawing.Point(5, [int](($pnlTitle.ClientSize.Height - $txtTitle.PreferredHeight) / 2))

    # Результаты — отдельный ComboBox только для ВЫБОРА результата.
    # Он лежит под TextBox и используется только как нативный выпадающий popup.
    # Поэтому список можно раскрывать настоящей стрелкой/Popup WinForms, но его
    # Items никогда не связаны с текстом, который пользователь редактирует.
    $titleResults = New-Object System.Windows.Forms.ListBox
    $titleResults.Location=New-Object System.Drawing.Point(115,43)
    $titleResults.Size=New-Object System.Drawing.Size(420,180)
    $titleResults.BackColor=$steamUi.Input; $titleResults.ForeColor=$steamUi.Text
    $titleResults.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
    $titleResults.Font=New-Object System.Drawing.Font('Segoe UI',9)
    $titleResults.SelectionMode=[System.Windows.Forms.SelectionMode]::One
    $titleResults.IntegralHeight=$false
    $titleResults.Visible=$false
    $titleResults.TabStop=$false
    $dlg.Controls.Add($titleResults)

    # Высота списка зависит от фактического количества результатов.
    # Если результатов немного — не оставляем большой пустой тёмный блок.
    # При большом количестве сохраняем ограничение 180 px и стандартную
    # прокрутку ListBox.
    $resizeEditorTitleResults = {
        try {
            $count = [int]$titleResults.Items.Count
            if($count -le 0){
                $titleResults.Height = 20
                return
            }
            # Берём фактическую высоту последней строки ListBox, а не Font.Height.
            # Font.Height немного больше реальной строки элемента, из-за чего
            # при небольшом количестве результатов снизу появлялись лишние строки.
            try {
                $lastRect = $titleResults.GetItemRectangle($count - 1)
                $newHeight = [int]$lastRect.Bottom + 2
            } catch {
                $rowHeight = [Math]::Max(14, [int]$titleResults.ItemHeight)
                $newHeight = ($count * $rowHeight) + 2
            }
            $newHeight = [Math]::Min(180, [Math]::Max(20, $newHeight))
            $titleResults.Height = [int]$newHeight
        } catch {}
    }

    $titleResults.BringToFront()
    $pnlTitle.BringToFront()

    # Переключатель источника поиска. По умолчанию — Steam.
    # Steam использует Steam App ID, SGDB — SteamGridDB Game ID.
    # Одна кнопка-переключатель: показывает текущий источник (Steam / SGDB),
    # по клику источник меняется на другой. Размер и положение — как у «Обзор...»
    # на строке ниже (90x28), чтобы кнопки в одном столбце выглядели единым рядом.
    $searchSourceBtn = New-Object System.Windows.Forms.Button
    $searchSourceBtn.Text='Steam'
    $searchSourceBtn.Location = New-Object System.Drawing.Point(540,14)
    $searchSourceBtn.Size = New-Object System.Drawing.Size(90,28)
    $searchSourceBtn.FlatStyle='Flat'; $searchSourceBtn.FlatAppearance.BorderColor=$steamUi.Accent2
    $searchSourceBtn.Font=New-Object System.Drawing.Font('Segoe UI Semibold',8.5)
    $searchSourceBtn.Cursor=[System.Windows.Forms.Cursors]::Hand
    $dlg.Controls.Add($searchSourceBtn)
    $searchSourceTip = New-Object System.Windows.Forms.ToolTip

    # Для ROM-карточек переключатель источника не показываем:
    # ROM всегда работает только через SteamGridDB.
    if ($IsRomEntry) {
        $searchSourceBtn.Visible = $false
    }

    # Значки на кнопках источников: значок слева от текста, вместе центрируются.
    # Пары значков (яркий/приглушённый) для обоих источников хранятся в Tag кнопки;
    # какой из них показать — решает $updateSgdbButtonState по текущему источнику.
    $srcIconPairs = @{ Steam = $null; SteamGridDB = $null }
    foreach ($srcBtnDef in @(
        @{ Key = 'Steam';       Bmp = (Get-SteamSourceIconBitmap 22 0) },
        @{ Key = 'SteamGridDB'; Bmp = (Get-SteamGridDbSourceIconBitmap) }
    )) {
        try {
            $srcIconPairs[$srcBtnDef.Key] = New-SourceButtonIconPair $srcBtnDef.Bmp
            if ($null -ne $srcBtnDef.Bmp) { $srcBtnDef.Bmp.Dispose() }
        } catch {}
    }
    $searchSourceBtn.Tag = $srcIconPairs
    $searchSourceBtn.ImageAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $searchSourceBtn.TextAlign = [System.Drawing.ContentAlignment]::MiddleRight
    $searchSourceBtn.TextImageRelation = [System.Windows.Forms.TextImageRelation]::ImageBeforeText
    # Небольшой верхний «воздух» у Image: WinForms иначе сажает крупный значок ниже текста.
    $searchSourceBtn.Padding = New-Object System.Windows.Forms.Padding(4, 0, 4, 2)

    # SGDB доступен только после успешной проверки API-ключа. Пустой, изменённый,
    # невалидный или не проверенный ключ оставляет переключатель серым и неактивным.
    # Проверка ключа SGDB при запуске идёт в фоне. Если она ещё не закончилась,
    # кнопка пока серая, а этот таймер включит её, как только результат будет готов.
    $sgdbPendingTimer = New-Object System.Windows.Forms.Timer
    $sgdbPendingTimer.Interval = 400
    $sgdbPendingTimer.Add_Tick({
        try { $sgdbPendingTimer.Stop() } catch {}
        try { & $updateSgdbButtonState } catch {}
    })
    $dlg.Add_FormClosed({
        try { $sgdbPendingTimer.Stop(); $sgdbPendingTimer.Dispose() } catch {}
    })
    $updateSgdbButtonState = {
        try { Complete-StartupKeyChecks } catch {}
        # Сетевой сбой/429/5xx при проверке ключа на старте НЕ означает, что ключ плохой:
        # раньше из-за этого кнопка SGDB была серой до перезапуска программы. Блокируем её
        # только когда сервер реально отверг ключ (401/403/«invalid»).
        $sgdbCheckNow = $global:steamGridDbApiKeyCheck
        $sgdbTransient = ($null -ne $sgdbCheckNow -and [bool]$sgdbCheckNow.NetworkError)
        $isValid = (([bool]$global:steamGridDbApiKeyValid -or $sgdbTransient) -and -not [string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey))
        $isSgdb = ($editorState -ne $null -and $editorState.SearchSource -eq 'SteamGridDB')
        # Кнопка всегда показывает ТЕКУЩИЙ источник. Из Steam в SGDB можно перейти
        # только с валидным API-ключом (иначе кнопка серая и неактивная), а из SGDB
        # обратно в Steam — всегда.
        $canSwitch = ($isValid -or $isSgdb)
        $searchSourceBtn.Text = $(if($isSgdb){ 'SGDB' } else { 'Steam' })
        $searchSourceBtn.Enabled = $canSwitch
        $pairs = $searchSourceBtn.Tag
        $pair = $null
        try { $pair = $pairs[$(if($isSgdb){ 'SteamGridDB' } else { 'Steam' })] } catch {}
        if($canSwitch){
            $searchSourceBtn.BackColor=$steamUi.Accent2
            $searchSourceBtn.ForeColor=[System.Drawing.Color]::White
            $searchSourceBtn.FlatAppearance.BorderColor=$steamUi.Accent2
            $searchSourceBtn.Cursor=[System.Windows.Forms.Cursors]::Hand
            if ($pair -ne $null) { $searchSourceBtn.Image = $pair.Bright }
        } else {
            $searchSourceBtn.BackColor=[System.Drawing.Color]::FromArgb(45,45,45)
            $searchSourceBtn.ForeColor=[System.Drawing.Color]::FromArgb(105,105,105)
            $searchSourceBtn.FlatAppearance.BorderColor=[System.Drawing.Color]::FromArgb(65,65,65)
            $searchSourceBtn.Cursor=[System.Windows.Forms.Cursors]::Default
            if ($pair -ne $null) { $searchSourceBtn.Image = $pair.Dim }
        }
        try { $searchSourceTip.SetToolTip($searchSourceBtn, (T $(if($isSgdb){ 'src_tip_sgdb' } else { 'src_tip_steam' }))) } catch {}
        if (Test-StartupKeyChecksPending) { try { $sgdbPendingTimer.Start() } catch {} }
    }
    & $updateSgdbButtonState

    # Состояние источника хранится в объекте, а не в локальной переменной: PowerShell
    # создаёт отдельную область видимости для обработчиков событий и из-за обычного
    # присваивания $editorState.SearchSource переключение фактически возвращалось к Steam.
    # Ключ хранилища своих картинок: стабильный между открытиями карточки.
    # Лицензионная игра — по App ID; ROM — по папке и имени (в папке их много); остальное — по пути игры.
    $coverKeyValue = if ($licensedMode -and -not [string]::IsNullOrWhiteSpace($licensedAppId)) { 'steam:' + $licensedAppId }
        elseif ($IsRomEntry) { 'rom:' + [string]$gamePath + '|' + [string]$originalCardName }
        elseif (-not [string]::IsNullOrWhiteSpace([string]$gamePath)) { 'path:' + [string]$gamePath }
        else { 'name:' + [string]$originalCardName }
    $editorState = [PSCustomObject]@{ CoverKey = $coverKeyValue; IsRom = [bool]$IsRomEntry; GamePath = [string]$gamePath; SearchSource = $(if($IsRomEntry){'SteamGridDB'}else{'Steam'}); SwitchSerial = 0; OpDepth = 0; OriginalTitle = [string]$gameName; Baseline = $null; AutoTitle = ''; LastSuggestionField = ''; SuppressTitleSuggestionOnce = $false; SuppressLaunchOptionOnce = $false; LogoPosition = 'BottomLeft'; LogoWidthPct = 50; LogoHeightPct = 50; LogoHidden = $false; LogoSig0 = 'BottomLeft|50|50'; LogoFromCache = $false; LogoUseDefault = $false }
    try { $dlg.Tag = $editorState } catch {}

    # Название и EXE используют один и тот же стиль ComboBox:
    # одинаковая высота строки, фон, рамка и выделение.
    $titleCandidates=@(); $titleCandidateMap=@{}

    $idLbl = New-Object System.Windows.Forms.Label; $idLbl.Text='App ID'; $idLbl.Location='702,14'; $idLbl.Size='55,28'; $idLbl.ForeColor=$steamUi.Muted; $idLbl.TextAlign=[System.Drawing.ContentAlignment]::MiddleLeft; $dlg.Controls.Add($idLbl)
    # Та же проблема и то же решение, что и у поля "Название" выше: однострочный
    # TextBox сам сжимает свою высоту под шрифт, поэтому рамку и фон рисует
    # Panel, а сам TextBox центрируется внутри неё вручную по вертикали.
    $pnlId = New-Object System.Windows.Forms.Panel
    $pnlId.Location='757,14'; $pnlId.Size='103,28'
    $pnlId.BackColor=$steamUi.Input; $pnlId.BorderStyle='FixedSingle'
    $dlg.Controls.Add($pnlId)

    $txtId = New-Object System.Windows.Forms.TextBox
    $txtId.AutoSize=$false
    # App ID: значение выравниваем по центру и горизонтально, и (за счёт
    # оборачивающей Panel) вертикально.
    $txtId.Multiline = $false
    $txtId.TextAlign = [System.Windows.Forms.HorizontalAlignment]::Center
    $txtId.BackColor=$steamUi.Input; $txtId.ForeColor=$steamUi.Text; $txtId.BorderStyle='None'
    $pnlId.Controls.Add($txtId)
    $txtId.Width = $pnlId.ClientSize.Width - 10
    $txtId.Location = New-Object System.Drawing.Point(5, [int](($pnlId.ClientSize.Height - $txtId.PreferredHeight) / 2))

    $exeLbl = New-Object System.Windows.Forms.Label; $exeLbl.Text=(T 'card_launch'); $exeLbl.Location='20,50'; $exeLbl.Size='90,28'; $exeLbl.ForeColor=$steamUi.Muted; $exeLbl.TextAlign=[System.Drawing.ContentAlignment]::MiddleLeft; $dlg.Controls.Add($exeLbl)
    # Значок уверенности в выбранном EXE: зелёная галочка — файл определён
    # однозначно (совпал с уже сохранённым/кэшированным, единственный
    # кандидат, либо выбран пользователем вручную), красный "!" — программа
    # просто взяла первый файл из нескольких кандидатов наугад.
    $exeConfidenceBadge = New-ConfidenceBadge $dlg 91 55

    # Единый EXE-пикер для карточки и пакетного добавления.
    # В закрытом состоянии показывается только выбранный EXE.
    # Полный список раскрывается только по стрелке ComboBox.
    # Рамку рисует Panel (как у App ID / Название) — у самого ComboBox системная рамка снята.
    $pnlExe = New-Object System.Windows.Forms.Panel
    $pnlExe.Location = New-Object System.Drawing.Point(115, 50)
    $pnlExe.Size = New-Object System.Drawing.Size(420, 28)
    $pnlExe.BackColor = $steamUi.Input
    $pnlExe.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $dlg.Controls.Add($pnlExe)

    $cmbExe = New-Object SmartExeComboBox
    $cmbExe.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbExe.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbExe.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbExe.ItemHeight = 20
    $cmbExe.DropDownHeight = 128
    $cmbExe.IntegralHeight = $false
    $cmbExe.BackColor = $steamUi.Input
    $cmbExe.ForeColor = $steamUi.Text
    $cmbExe.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    $cmbExe.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    try { $cmbExe.BorderColor = $steamUi.Input } catch {}
    $pnlExe.Controls.Add($cmbExe)

    # Флаг отличает программное назначение выбора (первичное автоопределение,
    # где сама уверенность ещё вычисляется отдельно) от реального клика
    # пользователя по выпадающему списку — тот всегда означает осознанный
    # и потому "уверенный" выбор.
    $exeProgrammaticSelect = $false
    # БАГ-ФИКС: раньше подсказка exe из данных Steam применялась только ОДИН
    # РАЗ, в момент открытия карточки — с тем App ID, который автоматика
    # успела определить к этому моменту. Если автоматический поиск названия
    # не срабатывал (например, "Crash Bandicoot 4" на диске против
    # официального "Crash Bandicoot™ 4: It's About Time" в Steam — см. ниже
    # исправление самого поиска), а пользователь потом сам находил и
    # подтверждал игру вручную, exe так и оставался неопределённым (красный
    # "!"), хотя после подтверждения App ID подсказка от Steam уже могла
    # сработать. Флаг ExeConfirmed на $editorState (а не отдельная переменная —
    # присваивание простой переменной внутри вложенного обработчика события
    # не отражается на внешней области видимости) отслеживает, подтверждён ли
    # выбор exe (кэшем, сохранённым ярлыком, вручную пользователем или
    # подсказкой Steam), и используется, чтобы разрешить повторную попытку
    # подсказки при каждом новом подтверждении App ID, не перетирая уже
    # сделанный осознанный выбор.
    $editorState | Add-Member -NotePropertyName ExeConfirmed -NotePropertyValue $false -Force
    $cmbExe.Add_SelectedIndexChanged({
        if(-not $exeProgrammaticSelect){
            $editorState.ExeConfirmed = $true
            Set-ConfidenceBadge $exeConfidenceBadge $true (T 'badge_exe_manual') ''
        }
    })


    $cmbExe.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $isDisabled = $sender.Locked
        if ($isDisabled) {
            $bg = $steamUi.Panel
            $fg = $steamUi.Muted
        } else {
            $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
            $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $entry=$null
            try { $entry=$sender.Tag[$e.Index] } catch {}
            $text = if($entry -ne $null){ [string]$entry.Text } else { [string]$sender.Items[$e.Index] }
            $textX=$e.Bounds.X+8
            if($entry -ne $null -and $entry.Image -ne $null){
                $img=$entry.Image
                $iconSize=18
                $iy=$e.Bounds.Y+[Math]::Max(0,[int](($e.Bounds.Height-$iconSize)/2))
                $e.Graphics.DrawImage($img, $e.Bounds.X+4, $iy, $iconSize, $iconSize)
                $textX=$e.Bounds.X+30
            }
            # Иконку уже центрировали по Bounds.Height, а текст рядом рисовался с
            # жёстко зашитым отступом +2 от верха — то есть не по центру, а почти
            # у верхнего края строки. Меряем реальную высоту текста и центрируем
            # его так же, как иконку.
            $textSize = $e.Graphics.MeasureString($text, $sender.Font)
            $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
            $e.Graphics.DrawString($text,$sender.Font,$textBrush,[float]$textX,[float]$textY)
        } finally {
            $bgBrush.Dispose(); $textBrush.Dispose()
        }
    })

    $btnBrowseExe = New-Object System.Windows.Forms.Button
    $btnBrowseExe.Location = New-Object System.Drawing.Point(540,49)
    $btnBrowseExe.Size = New-Object System.Drawing.Size(90,28)
    Set-BrowseIconButton $btnBrowseExe
    $btnBrowseExe.FlatStyle='Flat'; $btnBrowseExe.FlatAppearance.BorderColor=$steamUi.Border
    $btnBrowseExe.BackColor=$steamUi.Panel; $btnBrowseExe.ForeColor=$steamUi.Text
    $btnBrowseExe.Cursor=[System.Windows.Forms.Cursors]::Hand
    $dlg.Controls.Add($btnBrowseExe)

    # --- Режим ROMs: вместо EXE-пикера показываем выбор эмулятора --------
    # Поле "Запуск" превращается в поле "Эмулятор" с выпадающим списком уже
    # настроенных эмуляторов (Настройки -> Эмуляторы...). По умолчанию
    # выбирается активный эмулятор режима ROMs (индикатор в главном окне),
    # а поле "Параметры" сразу заполняется шаблоном аргументов этого
    # эмулятора с подставленным путём к файлу рома — пользователь может
    # после этого свободно отредактировать текст вручную.
    $pnlEmulator = New-Object System.Windows.Forms.Panel
    $pnlEmulator.Location = New-Object System.Drawing.Point(115, 50)
    $pnlEmulator.Size = New-Object System.Drawing.Size(420, 28)
    $pnlEmulator.BackColor = $steamUi.Input
    $pnlEmulator.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $pnlEmulator.Visible = $false
    $dlg.Controls.Add($pnlEmulator)

    $cmbEmulator = New-Object SmartExeComboBox
    $cmbEmulator.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbEmulator.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbEmulator.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbEmulator.ItemHeight = 20
    $cmbEmulator.DropDownHeight = 128
    $cmbEmulator.IntegralHeight = $false
    $cmbEmulator.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $cmbEmulator.BackColor = $steamUi.Input
    $cmbEmulator.ForeColor = $steamUi.Text
    $cmbEmulator.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    try { $cmbEmulator.BorderColor = $steamUi.Input } catch {}
    $pnlEmulator.Controls.Add($cmbEmulator)
    $cmbEmulator.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
        $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            $textSize = $e.Graphics.MeasureString($text, $sender.Font)
            $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
            $e.Graphics.DrawString($text,$sender.Font,$textBrush,[float]($e.Bounds.X+8),[float]$textY)
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })

    # Эмуляторы в выпадающем списке — по алфавиту (по названию, без учёта
    # регистра). Все обращения ниже идут по индексу в $emuProfiles, поэтому
    # достаточно отсортировать сам список до заполнения комбобокса.
    [System.Collections.Generic.List[object]]$emuProfiles = @(@($global:emulatorProfiles) | Sort-Object -Property { [string]$_.Name } -CaseSensitive:$false)
    foreach ($ep in $emuProfiles) { [void]$cmbEmulator.Items.Add([string]$ep.Name) }

    # Поле "Ядро" — появляется в этой же строке, правее эмулятора, только
    # когда выбранный эмулятор — RetroArch (у него, в отличие от остальных,
    # аргумент запуска зависит от того, какое ядро (libretro core) грузить,
    # а не фиксирован для всего эмулятора). Место справа свободно именно в
    # режиме ROMs: там прячутся $btnBrowseExe и путь к EXE.
    $lblCoreGame = New-Object System.Windows.Forms.Label
    $lblCoreGame.Text = (T 'emu_lbl_core')
    $lblCoreGame.Location = New-Object System.Drawing.Point(610, 50)
    $lblCoreGame.Size = New-Object System.Drawing.Size(45, 28)
    $lblCoreGame.ForeColor = $steamUi.Muted
    $lblCoreGame.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $lblCoreGame.Visible = $false
    $dlg.Controls.Add($lblCoreGame)

    $pnlCoreGame = New-Object System.Windows.Forms.Panel
    $pnlCoreGame.Location = New-Object System.Drawing.Point(658, 50)
    $pnlCoreGame.Size = New-Object System.Drawing.Size(202, 28)
    $pnlCoreGame.BackColor = $steamUi.Input
    $pnlCoreGame.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $pnlCoreGame.Visible = $false
    $dlg.Controls.Add($pnlCoreGame)

    $cmbCoreGame = New-Object SmartExeComboBox
    $cmbCoreGame.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbCoreGame.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbCoreGame.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbCoreGame.ItemHeight = 20
    $cmbCoreGame.DropDownHeight = 200
    $cmbCoreGame.IntegralHeight = $false
    $cmbCoreGame.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $cmbCoreGame.BackColor = $steamUi.Input
    $cmbCoreGame.ForeColor = $steamUi.Text
    $cmbCoreGame.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    try { $cmbCoreGame.BorderColor = $steamUi.Input } catch {}
    $pnlCoreGame.Controls.Add($cmbCoreGame)
    # Как и у главной панели ($cmbMainCore) и у выбора эмулятора ($cmbEmulator):
    # DropDownList (без редактируемого Edit-контрола) + Dock=Fill, тема
    # отключается в SmartExeComboBox — поэтому нет белой рамки при наведении.
    # Показываются отображаемые имена ядер (display_name из .info RetroArch),
    # а имя файла ядра хранится в $coreGameState.Files по тому же индексу.
    $cmbCoreGame.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
        $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            $textSize = $e.Graphics.MeasureString($text, $sender.Font)
            $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
            $e.Graphics.DrawString($text,$sender.Font,$textBrush,[float]($e.Bounds.X+8),[float]$textY)
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })

    # Состояние списка ядер: Files[i] — имя файла ядра (без _libretro.dll) для
    # пункта i; пункт 0 — заглушка "Выберите ядро" (пустое ядро).
    $coreGamePlaceholder = (T 'core_choose')
    $coreGameState = [PSCustomObject]@{ Suppress = $false; Files = @(''); ExePath = '' }

    # Имя файла ядра для выбранного пункта ('' — ядро не выбрано).
    $getCoreGameFile = {
        $idx = $cmbCoreGame.SelectedIndex
        if ($idx -lt 0 -or $idx -ge @($coreGameState.Files).Count) { return '' }
        return [string]$coreGameState.Files[$idx]
    }

    # Выбирает пункт по имени файла ядра без пересборки "Параметров". Если ядра
    # нет в списке (например, в параметрах ярлыка указано отсутствующее в
    # папке cores) — добавляет его отдельным пунктом, чтобы не потерять.
    $setCoreGameFile = {
        param([string]$fileCore)
        $coreGameState.Suppress = $true
        try {
            $idx = 0
            if (-not [string]::IsNullOrWhiteSpace($fileCore)) {
                $idx = -1
                for ($i = 1; $i -lt @($coreGameState.Files).Count; $i++) {
                    if ([string]::Equals([string]$coreGameState.Files[$i], $fileCore, [System.StringComparison]::OrdinalIgnoreCase)) { $idx = $i; break }
                }
                if ($idx -lt 0) {
                    $shown = $fileCore
                    try { $shown = [string](Get-RetroArchCoreDisplayName ([string]$coreGameState.ExePath) $fileCore) } catch {}
                    [void]$cmbCoreGame.Items.Add($shown)
                    $coreGameState.Files = @($coreGameState.Files) + @($fileCore)
                    $idx = $cmbCoreGame.Items.Count - 1
                }
            }
            $cmbCoreGame.SelectedIndex = $idx
        } finally { $coreGameState.Suppress = $false }
    }

    # Подставляет в "Параметры" шаблон аргументов выбранного эмулятора с
    # путём к текущему файлу рома ($gamePath — в режиме ROMs это путь к
    # самому файлу, а не к папке игры). Для RetroArch параметр ядра
    # "-L cores\<ядро>_libretro.dll" (где <ядро> — то, что выбрано/введено в
    # $cmbCoreGame) ДОПОЛНЯЕТ аргументы из настроек эмулятора ($profile.Args),
    # а не заменяет их целиком — см. Merge-RetroArchCoreArgs.
    $applyEmulatorArgsTemplate = {
        param($profile, $romPath = $null)
        if ($profile -eq $null) { return }
        if ([string]::IsNullOrWhiteSpace([string]$romPath)) { $romPath = $gamePath }
        $argsTemplate = [string]$profile.Args
        try {
            if (Test-IsRetroArchProfile ([string]$profile.Name) ([string]$profile.ExePath)) {
                $coreSel = [string](& $getCoreGameFile)
                $argsTemplate = Merge-RetroArchCoreArgs $argsTemplate $coreSel
            }
        } catch {}
        try { $txtLaunchOptions.Text = Format-EmulatorLaunchArgs $argsTemplate $romPath } catch {}
    }

    # Показывает/прячет поле "Ядро" по текущему выбранному эмулятору и
    # заполняет список ядер, найденных в папке cores рядом с его exe.
    # $setDefaultFromProfile=$true — сбросить выбор на сохранённое ядро
    # профиля (используется при смене эмулятора пользователем); $false —
    # сохранить то, что уже введено (используется при простом обновлении
    # видимости, чтобы не затирать ручной ввод).
    $updateGameCoreVisibility = {
        param($setDefaultFromProfile = $false)
        $isRA = $false
        $profile = $null
        if ($cmbEmulator.SelectedIndex -ge 0 -and $cmbEmulator.SelectedIndex -lt $emuProfiles.Count) {
            $profile = $emuProfiles[$cmbEmulator.SelectedIndex]
            $isRA = Test-IsRetroArchProfile ([string]$profile.Name) ([string]$profile.ExePath)
        }
        $showCore = $isRA -and $IsRomEntry
        $lblCoreGame.Visible = $showCore
        $pnlCoreGame.Visible = $showCore
        if ($isRA) {
            $prevFile = [string](& $getCoreGameFile)
            $coreGameState.Suppress = $true
            try {
                $cmbCoreGame.Items.Clear()
                [void]$cmbCoreGame.Items.Add($coreGamePlaceholder)
                $files = @('')
                $coreGameState.ExePath = [string]$profile.ExePath
                foreach ($c in @(Get-RetroArchCoreDisplayList ([string]$profile.ExePath))) {
                    [void]$cmbCoreGame.Items.Add([string]$c.DisplayName)
                    $files += [string]$c.FileCore
                }
                $coreGameState.Files = $files
                # Выпадающий список шире самого поля, если имена ядер длинные.
                $maxW = $pnlCoreGame.ClientSize.Width
                foreach ($t in $cmbCoreGame.Items) {
                    $w = [System.Windows.Forms.TextRenderer]::MeasureText([string]$t, $cmbCoreGame.Font).Width + 28
                    if ($w -gt $maxW) { $maxW = $w }
                }
                $cmbCoreGame.DropDownWidth = [Math]::Min($maxW, 360)
            } finally {
                $coreGameState.Suppress = $false
            }
            $targetFile = if ($setDefaultFromProfile) { [string]$profile.Core } else { $prevFile }
            & $setCoreGameFile $targetFile
        }
    }

    $emuProgrammaticSelect = $false
    $cmbEmulator.Add_SelectedIndexChanged({
        if ($emuProgrammaticSelect) { return }
        if ($cmbEmulator.SelectedIndex -lt 0 -or $cmbEmulator.SelectedIndex -ge $emuProfiles.Count) { return }
        & $updateGameCoreVisibility $true
        $romPathForArgs = try { & $getSelectedRomPath } catch { $gamePath }
        & $applyEmulatorArgsTemplate $emuProfiles[$cmbEmulator.SelectedIndex] $romPathForArgs
    })

    # Выбор (или ручной ввод) ядра сразу пересобирает "Параметры" — так же,
    # как смена ROM или самого эмулятора.
    $rebuildArgsForCoreGame = {
        if ($coreGameState.Suppress) { return }
        if ($cmbEmulator.SelectedIndex -lt 0 -or $cmbEmulator.SelectedIndex -ge $emuProfiles.Count) { return }
        $romPathForArgs = try { & $getSelectedRomPath } catch { $gamePath }
        & $applyEmulatorArgsTemplate $emuProfiles[$cmbEmulator.SelectedIndex] $romPathForArgs
    }
    $cmbCoreGame.Add_SelectedIndexChanged({ & $rebuildArgsForCoreGame })
    $cmbCoreGame.Add_Leave({ & $rebuildArgsForCoreGame })

    if ($IsRomEntry) {
        $exeLbl.Text = (T 'card_emulator')
        $pnlExe.Visible = $false
        $btnBrowseExe.Visible = $false
        try { $exeConfidenceBadge.Visible = $false } catch {}
        $pnlEmulator.Visible = $true
    }

    # --- Режим ROMs: поле "ROM" -------------------------------------------
    # Отдельная строка сразу под "Эмулятором" — выбор конкретного файла рома
    # из папки игры. Список заполняется автоматически (Get-EditorRomCandidates
    # ниже), патчи/DLC/.cue/.dvd/и подобные файлы в него не попадают вовсе;
    # неопознанные файлы остаются доступны для ручного выбора. Есть и кнопка
    # "Обзор..." — на случай, если нужный файл лежит вне папки игры или
    # автоматика ошиблась.
    $romLbl = New-Object System.Windows.Forms.Label
    $romLbl.Text = 'ROM'
    $romLbl.Location = New-Object System.Drawing.Point(20, 87)
    $romLbl.Size = New-Object System.Drawing.Size(90, 28)
    $romLbl.ForeColor = $steamUi.Muted
    $romLbl.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $romLbl.Visible = $IsRomEntry
    $dlg.Controls.Add($romLbl)
    $romConfidenceBadge = New-ConfidenceBadge $dlg 91 92

    $pnlRom = New-Object System.Windows.Forms.Panel
    $pnlRom.Location = New-Object System.Drawing.Point(115, 87)
    $pnlRom.Size = New-Object System.Drawing.Size(420, 28)
    $pnlRom.BackColor = $steamUi.Input
    $pnlRom.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $pnlRom.Visible = $IsRomEntry
    $dlg.Controls.Add($pnlRom)

    $cmbRom = New-Object SmartExeComboBox
    $cmbRom.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbRom.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbRom.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbRom.ItemHeight = 20
    $cmbRom.DropDownHeight = 128
    $cmbRom.IntegralHeight = $false
    $cmbRom.BackColor = $steamUi.Input
    $cmbRom.ForeColor = $steamUi.Text
    $cmbRom.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    $cmbRom.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    try { $cmbRom.BorderColor = $steamUi.Input } catch {}
    $pnlRom.Controls.Add($cmbRom)

    $cmbRom.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
        $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            $textSize = $e.Graphics.MeasureString($text, $sender.Font)
            $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
            $e.Graphics.DrawString($text,$sender.Font,$textBrush,[float]($e.Bounds.X+32),[float]$textY)
            Draw-RomTypeIcon $e.Graphics ($e.Bounds.X + 8) ($e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - 14) / 2))) $text $false $bg
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })

    $btnBrowseRom = New-Object System.Windows.Forms.Button
    $btnBrowseRom.Location = New-Object System.Drawing.Point(540, 86)
    $btnBrowseRom.Size = New-Object System.Drawing.Size(90, 28)
    Set-BrowseIconButton $btnBrowseRom
    $btnBrowseRom.FlatStyle = 'Flat'; $btnBrowseRom.FlatAppearance.BorderColor = $steamUi.Border
    $btnBrowseRom.BackColor = $steamUi.Panel; $btnBrowseRom.ForeColor = $steamUi.Text
    $btnBrowseRom.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnBrowseRom.Visible = $IsRomEntry
    $dlg.Controls.Add($btnBrowseRom)

    # Поле "Файл" (в архиве) - в той же колонке справа, что и "Ядро" строкой выше. Показывается только
    # когда выбранный в "ROM" архив содержит несколько ROM; сам архив в списке "ROM" - одним пунктом.
    $lblRomEntry = New-Object System.Windows.Forms.Label
    $lblRomEntry.Text = (T 'rom_lbl_entry')
    $lblRomEntry.Location = New-Object System.Drawing.Point(610, 87)
    $lblRomEntry.Size = New-Object System.Drawing.Size(48, 28)
    $lblRomEntry.ForeColor = $steamUi.Muted
    $lblRomEntry.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $lblRomEntry.Visible = $false
    $dlg.Controls.Add($lblRomEntry)

    $pnlRomEntry = New-Object System.Windows.Forms.Panel
    $pnlRomEntry.Location = New-Object System.Drawing.Point(658, 87)
    $pnlRomEntry.Size = New-Object System.Drawing.Size(202, 28)
    $pnlRomEntry.BackColor = $steamUi.Input
    $pnlRomEntry.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    $pnlRomEntry.Visible = $false
    $dlg.Controls.Add($pnlRomEntry)

    $cmbRomEntry = New-Object SmartExeComboBox
    $cmbRomEntry.Dock = [System.Windows.Forms.DockStyle]::Fill
    $cmbRomEntry.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $cmbRomEntry.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $cmbRomEntry.ItemHeight = 20
    $cmbRomEntry.DropDownHeight = 200
    $cmbRomEntry.IntegralHeight = $false
    $cmbRomEntry.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $cmbRomEntry.BackColor = $steamUi.Input
    $cmbRomEntry.ForeColor = $steamUi.Text
    $cmbRomEntry.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    try { $cmbRomEntry.BorderColor = $steamUi.Input } catch {}
    $pnlRomEntry.Controls.Add($cmbRomEntry)

    $cmbRomEntry.Add_DrawItem({
        param($sender,$e)
        if($e.Index -lt 0){ return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $bg = if($isSelected){ $steamUi.Accent2 } else { $steamUi.Input }
        $fg = if($isSelected){ [System.Drawing.Color]::White } else { $steamUi.Text }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush,$e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            $textSize = $e.Graphics.MeasureString($text, $sender.Font)
            $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
            $e.Graphics.DrawString($text,$sender.Font,$textBrush,[float]($e.Bounds.X+8),[float]$textY)
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    })

    # Как у остальных списков карточки: после выбора фокус уходит на невидимый $editorFocusSink
    # (иначе остаётся серая подсветка); повторно через BeginInvoke - после закрытия popup WinForms
    # сам возвращает фокус комбобоксу.
    $cmbRomEntry.Add_DropDownClosed({
        try {
            $dlg.ActiveControl = $editorFocusSink
            $editorFocusSink.Focus() | Out-Null
            $dlg.BeginInvoke([Action]{
                try { $dlg.ActiveControl = $editorFocusSink; $editorFocusSink.Focus() | Out-Null } catch {}
            }) | Out-Null
        } catch {}
    }.GetNewClosure())

    # Paths[i] - путь файла внутри архива для пункта i.
    $romEntryState = [PSCustomObject]@{ Suppress = $false; Paths = @() }

    # Показ/скрытие поля. Поле "ROM" всегда одной длины с остальными; кнопка-папка (28 px) в колонку справа не заходит.
    $setRomEntryVisible = {
        param([bool]$show)
        $lblRomEntry.Visible = ($show -and $IsRomEntry)
        $pnlRomEntry.Visible = ($show -and $IsRomEntry)
    }

    # Список кандидатов (объекты FullName/Name/IsKnown из Get-EditorRomCandidates),
    # индекс в $cmbRom.Items соответствует индексу в этом списке — тот же приём,
    # что и у $exeCandidates/$cmbExe. Заполняется чуть ниже, после того как
    # становится известен эмулятор по умолчанию (его расширения используются
    # для уверенного автовыбора).
    [System.Collections.Generic.List[object]]$romCandidates = @()
    # Присваивание простой переменной внутри вложенного обработчика события
    # (или скрипт-блока, вызываемого через &) не отражается на внешней
    # области видимости — та же особенность, что и у ExeConfirmed/
    # LaunchOptSuppressReopen выше, поэтому флаг тоже хранится на $editorState.
    $editorState | Add-Member -NotePropertyName RomProgrammaticSelect -NotePropertyValue $false -Force

    # Возвращает полный путь к файлу рома, выбранному сейчас в "ROM" —
    # именно он подставляется в шаблон аргументов эмулятора вместо "сырого"
    # $gamePath (папки игры).
    $getSelectedRomPath = {
        try {
            if ($cmbRom.SelectedIndex -ge 0 -and $cmbRom.SelectedIndex -lt $romCandidates.Count) {
                return [string]$romCandidates[$cmbRom.SelectedIndex].FullName
            }
        } catch {}
        return $gamePath
    }

    # Файл, выбранный внутри архива с несколькими ROM ('' — запускается сам файл/архив целиком).
    $getSelectedRomEntry = {
        try {
            if ($cmbRom.SelectedIndex -ge 0 -and $cmbRom.SelectedIndex -lt $romCandidates.Count) {
                $pr = $romCandidates[$cmbRom.SelectedIndex].PSObject.Properties['ArchiveEntry']
                if ($null -ne $pr) { return [string]$pr.Value }
            }
        } catch {}
        return ''
    }

    # Заполняет поле "Файл" файлами внутри архива, выбранного в "ROM" (у обычных ROM и архивов с одним
    # ROM поле скрыто). Выбранный пункт = ArchiveEntry кандидата, его читает $getSelectedRomEntry.
    $updateRomEntryList = {
        $cand = $null
        try { if ($cmbRom.SelectedIndex -ge 0 -and $cmbRom.SelectedIndex -lt $romCandidates.Count) { $cand = $romCandidates[$cmbRom.SelectedIndex] } } catch {}
        $entries = @()
        if ($null -ne $cand) {
            $pe = $cand.PSObject.Properties['ArchiveEntries']
            if ($null -ne $pe -and $null -ne $pe.Value) { $entries = @($pe.Value) }
        }
        $romEntryState.Suppress = $true
        try {
            $cmbRomEntry.Items.Clear()
            $paths = @()
            $selIdx = -1
            if ($entries.Count -gt 0) {
                $curEntry = ''
                $pc = $cand.PSObject.Properties['ArchiveEntry']
                if ($null -ne $pc) { $curEntry = [string]$pc.Value }
                $maxW = $pnlRomEntry.ClientSize.Width
                for ($i = 0; $i -lt $entries.Count; $i++) {
                    [void]$cmbRomEntry.Items.Add([string]$entries[$i].Name)
                    $paths += [string]$entries[$i].Path
                    $w = [System.Windows.Forms.TextRenderer]::MeasureText([string]$entries[$i].Name, $cmbRomEntry.Font).Width + 28
                    if ($w -gt $maxW) { $maxW = $w }
                    if ($selIdx -lt 0 -and [string]::Equals([string]$entries[$i].Path, $curEntry, [System.StringComparison]::OrdinalIgnoreCase)) { $selIdx = $i }
                }
                if ($selIdx -lt 0) { $selIdx = 0 }
                $cmbRomEntry.DropDownWidth = [Math]::Min($maxW, 520)
            }
            $romEntryState.Paths = $paths
            if ($selIdx -ge 0) { $cmbRomEntry.SelectedIndex = $selIdx }
        } finally { $romEntryState.Suppress = $false }
        & $setRomEntryVisible ($entries.Count -gt 0)
    }

    $cmbRomEntry.Add_SelectedIndexChanged({
        if ($romEntryState.Suppress) { return }
        $idx = $cmbRomEntry.SelectedIndex
        if ($cmbRom.SelectedIndex -lt 0 -or $cmbRom.SelectedIndex -ge $romCandidates.Count) { return }
        if ($idx -lt 0 -or $idx -ge @($romEntryState.Paths).Count) { return }
        $cand = $romCandidates[$cmbRom.SelectedIndex]
        if ($null -eq $cand.PSObject.Properties['ArchiveEntry']) { return }
        $cand.ArchiveEntry = [string]$romEntryState.Paths[$idx]
        Set-ConfidenceBadge $romConfidenceBadge $true (T 'rom_badge_manual') ''
    })

    # Заполняет $cmbRom списком кандидатов и выбирает лучший: сначала ROM,
    # совпадающий с расширением выбранного эмулятора, затем другие известные
    # типы. Патчи/DLC и служебные файлы до этого этапа уже исключены.
    $populateRomCandidates = {
        param($preferredExtensions = '', $extractArchives = $false)
        $romCandidates.Clear()
        $baseRomCandidates = @(Get-EditorRomCandidates $gamePath ([string]$preferredExtensions) ([bool]$extractArchives))
        # Архивы с несколькими ROM внутри раскрываются в отдельные пункты (лучший: оригинал, USA).
        # Только при включённой галочке «Распаковывать архивы»: без неё архивы не трогаем.
        if ([bool]$extractArchives) { try { $baseRomCandidates = @(Expand-RomArchiveCandidates $baseRomCandidates ([string]$preferredExtensions)) } catch {} }
        foreach ($c in $baseRomCandidates) { $romCandidates.Add($c) }
        $editorState.RomProgrammaticSelect = $true
        try {
            $cmbRom.Items.Clear()
            foreach ($c in $romCandidates) { [void]$cmbRom.Items.Add([string]$c.Name) }
            if ($romCandidates.Count -gt 0) {
                $bestIdx = 0
                for ($i = 0; $i -lt $romCandidates.Count; $i++) { if ([bool]$romCandidates[$i].IsKnown) { $bestIdx = $i; break } }
                $cmbRom.SelectedIndex = $bestIdx
                $knownRomCandidates = @($romCandidates | Where-Object { [bool]$_.IsKnown })
                $baseVersionCandidates = @($knownRomCandidates | Where-Object { [int]$_.RomPriority -eq -100 })
                $confident = [bool]$romCandidates[$bestIdx].IsKnown -and (($knownRomCandidates.Count -le 1) -or ($baseVersionCandidates.Count -eq 1 -and [int]$romCandidates[$bestIdx].RomPriority -eq -100))
                $pec = $romCandidates[$bestIdx].PSObject.Properties['EntryConfident']
                if ($null -ne $pec -and -not [bool]$pec.Value) { $confident = $false }
                Set-ConfidenceBadge $romConfidenceBadge $confident (T 'rom_badge_ok') (T 'rom_badge_unsure')
            } else {
                Set-ConfidenceBadge $romConfidenceBadge $false (T 'rom_badge_ok') (T 'rom_badge_none')
            }
        } finally { $editorState.RomProgrammaticSelect = $false }
        & $updateRomEntryList
    }

    $cmbRom.Add_SelectedIndexChanged({
        & $updateRomEntryList
        if ($editorState.RomProgrammaticSelect) { return }
        Set-ConfidenceBadge $romConfidenceBadge $true (T 'rom_badge_manual') ''
        if ($cmbEmulator.SelectedIndex -ge 0 -and $cmbEmulator.SelectedIndex -lt $emuProfiles.Count) {
            & $applyEmulatorArgsTemplate $emuProfiles[$cmbEmulator.SelectedIndex] (& $getSelectedRomPath)
        }
    })

    $btnBrowseRom.Add_Click({
        $ofdRom = New-Object System.Windows.Forms.OpenFileDialog
        $ofdRom.Title = (T 'rom_ofd_title')
        $browseExts = ''
        $browseArchives = $false
        try {
            if ($cmbEmulator.SelectedIndex -ge 0 -and $cmbEmulator.SelectedIndex -lt $emuProfiles.Count) {
                $browseExts = [string]$emuProfiles[$cmbEmulator.SelectedIndex].Extensions
                $browseArchives = Test-EmulatorExtractArchives $emuProfiles[$cmbEmulator.SelectedIndex]
            }
        } catch {}
        if (-not [string]::IsNullOrWhiteSpace($browseExts)) {
            $extParts = @($browseExts -split '[,;\s]+' | ForEach-Object { $_.Trim().TrimStart('.') } | Where-Object { $_ -ne '' } | Select-Object -Unique)
            if ($browseArchives) { $extParts = @(@($extParts) + @(Get-RomArchiveExtensions) | Select-Object -Unique) }
            $patterns = @($extParts | ForEach-Object { '*.' + $_ })
            $ofdRom.Filter = (T 'rom_ofd_filter' @(($patterns -join ', '), ($patterns -join ';')))
        } else {
            $ofdRom.Filter = (T 'rom_ofd_all')
        }
        $ofdRom.CheckFileExists = $true
        $ofdRom.Multiselect = $false
        try { if (Test-Path -LiteralPath $gamePath) { $ofdRom.InitialDirectory = if (Test-Path -LiteralPath $gamePath -PathType Leaf) { [System.IO.Path]::GetDirectoryName($gamePath) } else { $gamePath } } } catch {}
        if ($ofdRom.ShowDialog($dlg) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $chosenRom = Get-Item -LiteralPath $ofdRom.FileName -ErrorAction SilentlyContinue
        if ($chosenRom -eq $null) { return }
        $existingIdx = -1
        for ($i = 0; $i -lt $romCandidates.Count; $i++) {
            if ([string]::Equals([string]$romCandidates[$i].FullName, $chosenRom.FullName, [System.StringComparison]::OrdinalIgnoreCase)) { $existingIdx = $i; break }
        }
        if ($existingIdx -lt 0) {
            $newBrowseCands = @([PSCustomObject]@{ FullName = $chosenRom.FullName; Name = $chosenRom.Name; IsKnown = $true; RomPriority = 0 })
            if ($browseArchives) { try { $newBrowseCands = @(Expand-RomArchiveCandidates $newBrowseCands $browseExts) } catch {} }
            $existingIdx = $romCandidates.Count
            foreach ($nc in $newBrowseCands) {
                $romCandidates.Add($nc)
                [void]$cmbRom.Items.Add([string]$nc.Name)
            }
        }
        $cmbRom.SelectedIndex = $existingIdx
    })
    # --- конец блока ROMs (продолжение выбора по умолчанию — ниже, после
    # определения $status и $editMode/$existingShortcut) -------------------

    $launchOptionsLbl = New-Object System.Windows.Forms.Label
    $launchOptionsLbl.Text=(T 'card_params'); $launchOptionsLbl.Location=New-Object System.Drawing.Point(20,(87+$romRowOffset)); $launchOptionsLbl.Size='90,28'
    $launchOptionsLbl.ForeColor=$steamUi.Muted; $launchOptionsLbl.TextAlign=[System.Drawing.ContentAlignment]::MiddleLeft
    $dlg.Controls.Add($launchOptionsLbl)
    $launchOptionsLblTip = New-Object System.Windows.Forms.ToolTip
    $launchOptionsLblTip.SetToolTip($launchOptionsLbl, (T 'card_params_tip'))
    # Значок уверенности для параметров запуска — тот же приём, что и у
    # "Название"/"Запуск": зелёная галочка, когда выбранный вариант параметров
    # относится к уже выбранному EXE, красный "!" — когда относится к другому
    # файлу. До выбора варианта из списка остаётся скрытым.
    $launchOptConfidenceBadge = New-ConfidenceBadge $dlg 91 (92+$romRowOffset)

    # Поле параметров укорочено (было 740 шириной на всю строку), чтобы
    # справа поместилась короткая подсказка о том, что делает выбранный
    # вариант запуска. Отдельной кнопки-стрелки нет: список открывается тем
    # же способом, что и у поля "Название" — по клику/фокусу в самом поле,
    # без переключения на что-то отдельное.
    $pnlLaunchOptions = New-Object System.Windows.Forms.Panel
    $pnlLaunchOptions.Location=New-Object System.Drawing.Point(115,(87+$romRowOffset)); $pnlLaunchOptions.Size='420,28'
    $pnlLaunchOptions.BackColor=$steamUi.Input; $pnlLaunchOptions.BorderStyle='FixedSingle'
    $dlg.Controls.Add($pnlLaunchOptions)

    $txtLaunchOptions = New-Object System.Windows.Forms.TextBox
    $txtLaunchOptions.AutoSize=$false; $txtLaunchOptions.BorderStyle='None'
    $txtLaunchOptions.BackColor=$steamUi.Input; $txtLaunchOptions.ForeColor=$steamUi.Text
    $txtLaunchOptions.Font=New-Object System.Drawing.Font('Consolas',8.8)
    $pnlLaunchOptions.Controls.Add($txtLaunchOptions)
    $txtLaunchOptions.Width=$pnlLaunchOptions.ClientSize.Width-10
    $txtLaunchOptions.Location=New-Object System.Drawing.Point(5,[int](($pnlLaunchOptions.ClientSize.Height-$txtLaunchOptions.PreferredHeight)/2))

    # Подсказка "что делает" появляется здесь только ПОСЛЕ выбора варианта
    # из списка — до этого остаётся пустой.
    $lblLaunchOptionsHint = New-Object System.Windows.Forms.Label
    $lblLaunchOptionsHint.Location = New-Object System.Drawing.Point(115,(117+$romRowOffset))
    $lblLaunchOptionsHint.Size = New-Object System.Drawing.Size(745,18)
    $lblLaunchOptionsHint.ForeColor = $steamUi.Muted
    $lblLaunchOptionsHint.Font = New-Object System.Drawing.Font('Segoe UI',8)
    $lblLaunchOptionsHint.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $lblLaunchOptionsHint.AutoEllipsis = $true
    $lblLaunchOptionsHint.Text = ''
    $dlg.Controls.Add($lblLaunchOptionsHint)
    $launchOptionsHintTip = New-Object System.Windows.Forms.ToolTip

    # Выпадающий список вариантов — тот же приём, что и titleResults для
    # автодополнения названия: обычный ListBox, скрытый по умолчанию,
    # разворачивается поверх остальных контролов формы (BringToFront) на
    # время выбора. Реальные объекты вариантов (со Arguments/Description)
    # лежат в .Tag — сам список показывает только читаемые строки. Поле при
    # этом остаётся обычным текстовым полем — можно как выбрать вариант из
    # списка, так и просто напечатать свои параметры вручную.
    $launchOptResults = New-Object System.Windows.Forms.ListBox
    $launchOptResults.Location = New-Object System.Drawing.Point(115,(116+$romRowOffset))
    $launchOptResults.Size = New-Object System.Drawing.Size(420,24)
    $launchOptResults.BackColor=$steamUi.Input; $launchOptResults.ForeColor=$steamUi.Text
    $launchOptResults.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
    $launchOptResults.Font=New-Object System.Drawing.Font('Consolas',8.6)
    $launchOptResults.IntegralHeight=$false
    $launchOptResults.Visible=$false
    $launchOptResults.TabStop=$false
    $dlg.Controls.Add($launchOptResults)

    # Сдерживающий флаг на $editorState: без него Focus() на поле параметров
    # ниже сразу же заново открывал список, потому что вызывал тот же
    # обработчик GotFocus, что и обычный клик по полю — список просто не
    # успевал сворачиваться. Как и с ExeConfirmed выше, обычная переменная
    # тут не подойдёт: присваивание простой переменной внутри вложенного
    # обработчика события не отражается на внешней области видимости.
    $editorState | Add-Member -NotePropertyName LaunchOptSuppressReopen -NotePropertyValue $false -Force
    # Запись о том, к какому exe относится СЕЙЧАС выбранный вариант параметров
    # (если он вообще был выбран из списка, а не введён вручную). Хранится
    # отдельно от самой проверки, чтобы её можно было повторно прогнать при
    # смене EXE в "Запуск" — не только сразу после выбора параметров.
    $editorState | Add-Member -NotePropertyName LaunchOptExpectedEntry -NotePropertyValue $null -Force

    # Сверяет exe выбранного варианта параметров (если он есть) с реально
    # выбранным сейчас в "Запуск" и обновляет значок/подсказку у "Параметры".
    # Вызывается и сразу после выбора варианта, и при каждой последующей смене
    # EXE — иначе значок оставался бы в устаревшем состоянии.
    $updateLaunchOptExeMatch = {
        try {
            $picked = $editorState.LaunchOptExpectedEntry
            if ($picked -eq $null) { return }
            $expectedExeName = [string]$picked.Executable
            if (-not [string]::IsNullOrWhiteSpace($expectedExeName)) { $expectedExeName = [System.IO.Path]::GetFileName($expectedExeName) }
            $currentExeName = $null
            if ($cmbExe.SelectedIndex -ge 0 -and $cmbExe.SelectedIndex -lt $exeCandidates.Count) {
                try { $currentExeName = [System.IO.Path]::GetFileName([string]$exeCandidates[$cmbExe.SelectedIndex].FullName) } catch {}
            }
            $hintText = Format-LaunchOptionHint $picked
            $exeMismatch = (-not [string]::IsNullOrWhiteSpace($expectedExeName)) -and (-not [string]::IsNullOrWhiteSpace($currentExeName)) -and (-not [string]::Equals($expectedExeName, $currentExeName, [System.StringComparison]::OrdinalIgnoreCase))
            if ($exeMismatch) {
                $mismatchText = (T 'badge_opt_mismatch' @($expectedExeName, $currentExeName))
                Set-ConfidenceBadge $launchOptConfidenceBadge $false (T 'badge_opt_ok') $mismatchText
                $lblLaunchOptionsHint.Text = $mismatchText
                $launchOptionsHintTip.SetToolTip($lblLaunchOptionsHint, $mismatchText + ' ' + $hintText)
            } else {
                Set-ConfidenceBadge $launchOptConfidenceBadge $true (T 'badge_opt_ok') ''
                $lblLaunchOptionsHint.Text = $hintText
                $launchOptionsHintTip.SetToolTip($lblLaunchOptionsHint, $hintText)
            }
        } catch {}
    }
    # Ту же проверку нужно повторить, если после выбора параметров пользователь
    # сменил EXE в "Запуск" — иначе значок и подсказка остаются от прошлого EXE.
    $cmbExe.Add_SelectedIndexChanged({ & $updateLaunchOptExeMatch })

    $commitLaunchOptionResult = {
        try {
            if ($launchOptResults.SelectedIndex -lt 0) { return }
            $entries = $launchOptResults.Tag
            if ($entries -eq $null -or $launchOptResults.SelectedIndex -ge @($entries).Count) { return }
            $picked = @($entries)[$launchOptResults.SelectedIndex]
            $txtLaunchOptions.Text = [string]$picked.Arguments
            $txtLaunchOptions.SelectionStart = $txtLaunchOptions.Text.Length
            $txtLaunchOptions.SelectionLength = 0

            # Выбранный вариант параметров привязан к своему exe (Executable из
            # данных Steam). Если он не совпадает с уже выбранным в "Запуск"
            # файлом, отдельный значок уверенности у "Параметры" загорается
            # красным, а справа вместо расшифровки флагов появляется
            # предупреждение с названием правильного файла.
            $editorState.LaunchOptExpectedEntry = $picked
            & $updateLaunchOptExeMatch

            $launchOptResults.Visible = $false
            $launchOptResults.SelectedIndex = -1
            $editorState.LaunchOptSuppressReopen = $true
            $txtLaunchOptions.Focus()
        } catch {}
    }
    $launchOptResults.Add_MouseClick({ & $commitLaunchOptionResult })
    $launchOptResults.Add_KeyDown({
        if($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter){ $_.SuppressKeyPress=$true; & $commitLaunchOptionResult }
        elseif($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape){ $_.SuppressKeyPress=$true; $launchOptResults.Visible=$false; $launchOptResults.SelectedIndex=-1; $editorState.LaunchOptSuppressReopen=$true; $txtLaunchOptions.Focus() }
    })

    # Открывает список по клику/фокусу в самом поле параметров — как и в
    # поле "Название". Пункты без аргументов (Arguments пустая строка)
    # выбросили: выбрать такой пункт означало ничего не вписать в поле, то
    # есть по сути пустое действие, только засорявшее список.
    $openLaunchOptionsDropDown = {
        try {
            if ($editorState.LaunchOptSuppressReopen) {
                $editorState.LaunchOptSuppressReopen = $false
                return
            }
            $appIdForLookup = $txtId.Text.Trim()
            if ($appIdForLookup -notmatch '^\d+$') { return }
            if (-not $global:steamLaunchOptionsCache.ContainsKey($appIdForLookup)) {
                $status.Text = (T 'st_lo_search')
                [System.Windows.Forms.Application]::DoEvents()
            }
            $entries = @(Get-SteamDbLaunchOptions $appIdForLookup) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Arguments) }
            if (@($entries).Count -eq 0) {
                $launchOptResults.Visible = $false
                $status.Text = (T 'st_lo_none')
                return
            }
            $status.Text = (T 'st_lo_found' @(@($entries).Count))
            $launchOptResults.Tag = $entries
            $launchOptResults.BeginUpdate()
            $launchOptResults.Items.Clear()
            foreach ($e in $entries) {
                [void]$launchOptResults.Items.Add( [string]$e.Arguments )
            }
            $launchOptResults.EndUpdate()
            $launchOptResults.SelectedIndex = -1
            $launchOptResults.Height = [Math]::Min(140, [Math]::Max(24, (@($entries).Count * 20) + 4))
            $launchOptResults.Visible = $true
            $launchOptResults.BringToFront()
        } catch {}
    }
    $txtLaunchOptions.Add_Click({
        if($editorState.SuppressLaunchOptionOnce){ $editorState.SuppressLaunchOptionOnce=$false; return }
        $editorState.LastSuggestionField='launch'
        & $openLaunchOptionsDropDown
    })
    # GotFocus намеренно не открывает список. Возврат фокуса после окна выбора
    # обложки не должен считаться кликом по полю и повторно раскрывать список.
    # Список открывается только явным кликом по самому полю.
    $txtLaunchOptions.Add_KeyDown({
        if($_.KeyCode -eq [System.Windows.Forms.Keys]::Down -and $launchOptResults.Visible -and $launchOptResults.Items.Count -gt 0){
            $_.SuppressKeyPress=$true
            $launchOptResults.SelectedIndex=0
            $launchOptResults.Focus()
        } elseif($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape){
            $launchOptResults.Visible=$false; $launchOptResults.SelectedIndex=-1
        }
    })

    # Это поле напрямую записывается в shortcuts.vdf -> LaunchOptions.
    # Выпадающий список launchOptResults при открытии временно перекрывает
    # эту строку сверху (тот же приём, что и titleResults выше: BringToFront
    # поверх остальных контролов, пока список раскрыт) — это нормально, он
    # закрывается сразу после выбора варианта или по Esc.
    #
    # Строка статуса перенесена под миниатюры (была сразу над ними, на месте
    # этой самой Y=115): визуально это отдельная строка "снизу", а не часть
    # шапки с полями ввода. 606 — это низ второго ряда миниатюр (Логотип/
    # Иконка: 428+170=598) плюс небольшой отступ в 8px; до кнопок снизу
    # ($bottomButtonY, см. ниже) естественно остаётся ещё запас по высоте
    # диалога, так что ничего не перекрывается.
    $status = New-Object System.Windows.Forms.Label; $status.Text=''; $status.Location=(New-Object System.Drawing.Point(20,(606+$romRowOffset))); $status.Size='850,20'; $status.ForeColor=$steamUi.Accent; $dlg.Controls.Add($status)

    $slots = [ordered]@{}
    $slots.Vertical = New-EditorCoverSlot $dlg (T 'slot_vertical') 20 (138+$romRowOffset) 270 280
    if ($script:LogoComposeEnabled) {
        # Этап 1: Горизонтальная под Вертикальной, Hero растянут на место бывших «Горизонтальной» и «Hero».
        # Панель Logo скрыта, но остаётся в $slots: на ней держатся загрузка, значок источника, альтернативы и сохранение.
        $slots.Horizontal = New-EditorCoverSlot $dlg (T 'slot_horizontal') 20 (428+$romRowOffset) 270 170
        $slots.Hero = New-EditorCoverSlot $dlg (T 'slot_herologo') 305 (138+$romRowOffset) 555 280
        $slots.Logo = New-EditorCoverSlot $dlg (T 'slot_logo') 20 (428+$romRowOffset) 270 170
        $slots.Logo.Panel.Visible = $false
    } else {
    $slots.Horizontal = New-EditorCoverSlot $dlg (T 'slot_horizontal') 305 (138+$romRowOffset) 270 280
    $slots.Hero = New-EditorCoverSlot $dlg (T 'slot_hero') 590 (138+$romRowOffset) 270 280
    $slots.Logo = New-EditorCoverSlot $dlg (T 'slot_logo') 20 (428+$romRowOffset) 270 170
    }
    # Иконка приложения (clienticon) — справа от логотипа, в свободной зоне.
    # Размер такой же, как у остальных слотов (270x170, как у Логотипа) —
    # раньше слот был уже (120px), из-за чего фон-заглушка "NO COVER" не
    # помещалась целиком и выглядела обрезанной по сравнению с другими слотами.
    # Окно иконки сужено до 234 px (сама миниатюра 125×125 не уменьшается — она по центру, как и раньше):
    # освободившееся место отдано сетке библиотек апскейлеров справа (см. $dlssGridLeft).
    $slots.Icon = New-EditorCoverSlot $dlg $(if ($script:LogoComposeEnabled) { (T 'slot_icon') -replace '^5\.','4.' } else { (T 'slot_icon') }) 305 (428+$romRowOffset) 234 170
    # Для всех типов обложек фон карточки должен совпадать
    # с тёмным фоном области изображения внутри.
    $slots.Vertical.Panel.BackColor = $steamUi.Input
    $slots.Horizontal.Panel.BackColor = $steamUi.Input
    $slots.Hero.Panel.BackColor = $steamUi.Input
    $slots.Logo.Panel.BackColor = $steamUi.Input
    $slots.Icon.Panel.BackColor = $steamUi.Input
    # Состояние карточки доступно слоту напрямую (не только через Form.Tag): по нему окно выбора
    # определяет ключ хранилища своих картинок и EXE игры.
    foreach ($slotKey in @($slots.Keys)) {
        try { $slots[$slotKey] | Add-Member -NotePropertyName EditorState -NotePropertyValue $editorState -Force } catch {}
    }
    if ($script:LogoComposeEnabled) { try { Initialize-EditorCompose $slots.Hero $slots.Logo } catch {} }

    # Клик по миниатюре открывает альтернативы ИМЕННО этого типа.
    # Если текущий источник Steam, варианты подгружаются напрямую из SGDB по
    # тому же Steam App ID — источник поиска карточки при этом НЕ переключается.
    $onSlotVerticalClick = {
        if($editorState.SearchSource -eq 'Steam' -and @($slots.Vertical.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSteamSgdbAlternatives $slots.Vertical (T 'slot_vertical') $txtId.Text.Trim() $txtTitle.Text.Trim() $status)
        }
        elseif($editorState.SearchSource -eq 'SteamGridDB' -and @($slots.Vertical.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSgdbGameAlternatives $slots.Vertical (T 'slot_vertical') $txtId.Text.Trim() $status)
        }
        Show-EditorAlternativeCover $slots.Vertical (T 'slot_vertical')
    }
    $slots.Vertical.Picture.Add_Click($onSlotVerticalClick)
    # Если обложки в источнике нет, поверх Picture лежит заглушка Missing —
    # клик по ней тоже должен открывать альтернативы (в т.ч. из SGDB).
    $slots.Vertical.Missing.Add_Click($onSlotVerticalClick)
    $onSlotHorizontalClick = {
        if($editorState.SearchSource -eq 'Steam' -and @($slots.Horizontal.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSteamSgdbAlternatives $slots.Horizontal (T 'slot_horizontal') $txtId.Text.Trim() $txtTitle.Text.Trim() $status)
        }
        elseif($editorState.SearchSource -eq 'SteamGridDB' -and @($slots.Horizontal.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSgdbGameAlternatives $slots.Horizontal (T 'slot_horizontal') $txtId.Text.Trim() $status)
        }
        Show-EditorAlternativeCover $slots.Horizontal (T 'slot_horizontal')
    }
    $slots.Horizontal.Picture.Add_Click($onSlotHorizontalClick)
    # Если обложки в источнике нет, поверх Picture лежит заглушка Missing —
    # клик по ней тоже должен открывать альтернативы (в т.ч. из SGDB).
    $slots.Horizontal.Missing.Add_Click($onSlotHorizontalClick)
    $onSlotHeroClick = {
        if($editorState.SearchSource -eq 'Steam' -and @($slots.Hero.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSteamSgdbAlternatives $slots.Hero (T 'slot_hero') $txtId.Text.Trim() $txtTitle.Text.Trim() $status)
        }
        elseif($editorState.SearchSource -eq 'SteamGridDB' -and @($slots.Hero.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSgdbGameAlternatives $slots.Hero (T 'slot_hero') $txtId.Text.Trim() $status)
        }
        Show-EditorAlternativeCover $slots.Hero (T 'slot_hero')
    }
    # В композиции клик по превью разбирает MouseUp (логотип или фон), см. Initialize-EditorCompose.
    if (-not $script:LogoComposeEnabled -or $null -eq $slots.Hero.PSObject.Properties['ComposeLogo']) { $slots.Hero.Picture.Add_Click($onSlotHeroClick) }
    # Если обложки в источнике нет, поверх Picture лежит заглушка Missing —
    # клик по ней тоже должен открывать альтернативы (в т.ч. из SGDB).
    $slots.Hero.Missing.Add_Click($onSlotHeroClick)
    $onSlotLogoClick = {
        if($editorState.SearchSource -eq 'Steam' -and @($slots.Logo.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSteamSgdbAlternatives $slots.Logo (T 'slot_logo') $txtId.Text.Trim() $txtTitle.Text.Trim() $status)
        }
        elseif($editorState.SearchSource -eq 'SteamGridDB' -and @($slots.Logo.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSgdbGameAlternatives $slots.Logo (T 'slot_logo') $txtId.Text.Trim() $status)
        }
        Show-EditorAlternativeCover $slots.Logo (T 'slot_logo')
    }
    $slots.Logo.Picture.Add_Click($onSlotLogoClick)
    # Если обложки в источнике нет, поверх Picture лежит заглушка Missing —
    # клик по ней тоже должен открывать альтернативы (в т.ч. из SGDB).
    $slots.Logo.Missing.Add_Click($onSlotLogoClick)
    $onSlotIconClick = {
        if($editorState.SearchSource -eq 'Steam' -and @($slots.Icon.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSteamSgdbAlternatives $slots.Icon (T 'slot_icon') $txtId.Text.Trim() $txtTitle.Text.Trim() $status)
        }
        elseif($editorState.SearchSource -eq 'SteamGridDB' -and @($slots.Icon.SgdbItems).Count -eq 0){
            [void](Prepare-EditorSgdbGameAlternatives $slots.Icon (T 'slot_icon') $txtId.Text.Trim() $status)
        }
        Show-EditorAlternativeCover $slots.Icon (T 'slot_icon')
    }
    $slots.Icon.Picture.Add_Click($onSlotIconClick)
    # Если обложки в источнике нет, поверх Picture лежит заглушка Missing —
    # клик по ней тоже должен открывать альтернативы (в т.ч. из SGDB).
    $slots.Icon.Missing.Add_Click($onSlotIconClick)

    # EXE игры для иконки: выбранный в списке или единственный найденный. Доступен слоту
    # иконки, чтобы загрузчик обложек мог сам поставить иконку из EXE (см. Invoke-EditorAutoExeIcon).
    $getEditorExePath = {
        $gp = ''
        try {
            $gix = [int]$cmbExe.SelectedIndex
            if ($gix -ge 0 -and $gix -lt @($exeCandidates).Count) { $gp = [string]@($exeCandidates)[$gix].FullName }
            elseif (@($exeCandidates).Count -eq 1) { $gp = [string]@($exeCandidates)[0].FullName }
        } catch {}
        return $gp
    }
    $getAutoExePath = {
        if ($licensedMode -or $IsRomEntry) { return '' }
        return [string](& $getEditorExePath)
    }
    try { $slots.Icon | Add-Member -NotePropertyName ExePathGetter -NotePropertyValue $getAutoExePath -Force } catch {}
    try { $slots.Icon | Add-Member -NotePropertyName IsRomCard -NotePropertyValue ([bool]$IsRomEntry) -Force } catch {}

    # В режиме ROM кнопка «EXE» не создаётся: у ROM нет exe, из которого можно взять иконку.
    $btnIconExe = $null
    if (-not $IsRomEntry) {
    # Красивая кнопка «EXE» в строке заголовка слота иконки: переключает иконку игры между
    # иконкой Steam (прежней) и иконкой файла EXE — туда и обратно.
    $btnIconExe = New-Object System.Windows.Forms.PictureBox
    $btnIconExe.Size = New-Object System.Drawing.Size(46, 20)
    # Миниатюра слота занимает x: 10..W-10, y: 35..H-10 — кнопка должна лежать
    # строго внутри неё (раньше выступала на 2 px и торчала из-под спиннера).
    $btnIconExe.Location = New-Object System.Drawing.Point(([int]$slots.Icon.Panel.Width - 46 - 8), ([int]$slots.Icon.Panel.Height - 20 - 16))
    try { $slots.Icon | Add-Member -NotePropertyName ExeButton -NotePropertyValue $btnIconExe -Force } catch {}
    $btnIconExe.BackColor = $steamUi.Input
    $btnIconExe.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnIconExe.Tag = 'normal'
    $btnIconExe.Add_MouseEnter({ $this.Tag = 'hot'; $this.Invalidate() })
    $btnIconExe.Add_MouseLeave({ $this.Tag = 'normal'; $this.Invalidate() })
    $btnIconExe.Add_MouseDown({ $this.Tag = 'down'; $this.Invalidate() })
    $btnIconExe.Add_MouseUp({ $this.Tag = 'hot'; $this.Invalidate() })
    $btnIconExe.Add_Paint({
        param($s,$e)
        try {
            $g = $e.Graphics
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
            $st = [string]$s.Tag
            if ($st -eq 'down') { $c1 = [System.Drawing.Color]::FromArgb(44,112,168); $c2 = [System.Drawing.Color]::FromArgb(30,84,132) }
            elseif ($st -eq 'hot') { $c1 = [System.Drawing.Color]::FromArgb(122,206,255); $c2 = [System.Drawing.Color]::FromArgb(58,138,206) }
            else { $c1 = [System.Drawing.Color]::FromArgb(92,178,236); $c2 = [System.Drawing.Color]::FromArgb(40,108,170) }
            $rect = New-Object System.Drawing.Rectangle(0, 0, ($s.Width - 1), ($s.Height - 1))
            $r = 5
            $path = New-Object System.Drawing.Drawing2D.GraphicsPath
            $path.AddArc($rect.X, $rect.Y, $r*2, $r*2, 180, 90)
            $path.AddArc(($rect.Right - $r*2), $rect.Y, $r*2, $r*2, 270, 90)
            $path.AddArc(($rect.Right - $r*2), ($rect.Bottom - $r*2), $r*2, $r*2, 0, 90)
            $path.AddArc($rect.X, ($rect.Bottom - $r*2), $r*2, $r*2, 90, 90)
            $path.CloseFigure()
            $br = New-Object System.Drawing.Drawing2D.LinearGradientBrush($rect, $c1, $c2, [System.Drawing.Drawing2D.LinearGradientMode]::Vertical)
            $g.FillPath($br, $path)
            $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(110,255,255,255), 1)
            $g.DrawPath($pen, $path)
            # Маленький значок «окно программы» слева от текста.
            $wp = New-Object System.Drawing.Pen([System.Drawing.Color]::White, 1.2)
            $g.DrawRectangle($wp, 6, 5, 8, 8)
            $g.DrawLine($wp, 6, 8, 14, 8)
            $font = New-Object System.Drawing.Font('Segoe UI Semibold', 7.5)
            $tb = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
            $sf = New-Object System.Drawing.StringFormat
            $sf.Alignment = [System.Drawing.StringAlignment]::Near
            $sf.LineAlignment = [System.Drawing.StringAlignment]::Center
            $g.DrawString('EXE', $font, $tb, (New-Object System.Drawing.RectangleF(17, 0, 28, [single]($s.Height - 1))), $sf)
            $br.Dispose(); $pen.Dispose(); $wp.Dispose(); $font.Dispose(); $tb.Dispose(); $sf.Dispose(); $path.Dispose()
        } catch {}
    })
    $btnIconExeTip = New-Object System.Windows.Forms.ToolTip
    $btnIconExeTip.SetToolTip($btnIconExe, (T 'icon_exe_tip'))
    $btnIconExe | Add-Member -NotePropertyName TipRef -NotePropertyValue $btnIconExeTip -Force
    # Подсказка кнопки зависит от того, что сейчас в слоте: иконка EXE → «вернуть прежнюю»,
    # иначе → «взять из EXE».
    $updateIconExeTip = {
        try {
            $tp = [string](& $getEditorExePath)
            $tipKey = if (-not [string]::IsNullOrWhiteSpace($tp) -and (Test-EditorIconIsExe $tp)) { 'icon_exe_back_tip' } else { 'icon_exe_tip' }
            $btnIconExeTip.SetToolTip($btnIconExe, (T $tipKey))
        } catch {}
    }
    $btnIconExe.Add_MouseEnter({ & $updateIconExeTip })
    $btnIconExe.Add_Click({
        try {
            $exePath = [string](& $getEditorExePath)
            # Иконка уже из этого EXE — возвращаем ту, что была до него (Steam), и наоборот.
            if (-not [string]::IsNullOrWhiteSpace($exePath) -and (Test-Path -LiteralPath $exePath -PathType Leaf) -and (Test-EditorIconIsExe $exePath)) {
                if (-not (Restore-EditorIconFromBackup $slots.Icon ([string]$txtId.Text.Trim()) ([bool]$licensedMode))) {
                    try {
                        $rid = [string]$txtId.Text.Trim()
                        if ($rid -notmatch '^\d+$') { $status.Text = (T 'sl_no_appid') }
                        else { $status.Text = (T 'icon_steam_none') }
                    } catch {}
                }
                & $updateIconExeTip
                return
            }
            if ([string]::IsNullOrWhiteSpace($exePath) -or -not (Test-Path -LiteralPath $exePath -PathType Leaf)) {
                # EXE в карточке не выбран однозначно — просим указать файл.
                $ofd = New-Object System.Windows.Forms.OpenFileDialog
                try {
                    $ofd.Title = (T 'icon_exe_pick')
                    $ofd.Filter = (T 'icon_exe_filter')
                    $ofd.CheckFileExists = $true
                    $startDir = ''
                    try { $gp = [string]$editorState.GamePath; if (Test-Path -LiteralPath $gp -PathType Container) { $startDir = $gp } elseif (Test-Path -LiteralPath $gp -PathType Leaf) { $startDir = [System.IO.Path]::GetDirectoryName($gp) } } catch {}
                    if (-not [string]::IsNullOrWhiteSpace($startDir)) { $ofd.InitialDirectory = $startDir }
                    if ($ofd.ShowDialog($dlg) -eq [System.Windows.Forms.DialogResult]::OK) { $exePath = [string]$ofd.FileName } else { return }
                } finally { $ofd.Dispose() }
            }
            if (-not (Set-EditorIconFromExe $slots.Icon $exePath)) {
                try {
                    Show-AppMessageBox((T 'icon_exe_fail' @([System.IO.Path]::GetFileName($exePath))),$global:appTitle,[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                } catch {}
            }
            & $updateIconExeTip
        } catch { try { Write-ExeIconLog ('EXE button: ' + $_.Exception.Message) } catch {} }
    })
    $slots.Icon.Panel.Controls.Add($btnIconExe)
    $btnIconExe.BringToFront()
    }
    $cmbExe.Add_SelectedIndexChanged({
        try {
            if (-not [bool]$global:useExeIcons) { return }
            if ($IsRomEntry) { return }
            if ($slots.Icon.IsLoading) { return }
            $prevPng = ''
            try { if ($null -ne $slots.Icon.PSObject.Properties['ExeIconPng']) { $prevPng = [string]$slots.Icon.ExeIconPng } } catch {}
            if ([string]::IsNullOrWhiteSpace($prevPng) -or -not (Test-TempIconMatchesFile $prevPng)) { return }
            $newExe = [string](& $getAutoExePath)
            if ([string]::IsNullOrWhiteSpace($newExe) -or -not (Test-Path -LiteralPath $newExe -PathType Leaf)) { return }
            if (Test-EditorIconIsExe $newExe) { return }
            [void](Set-EditorIconFromExe $slots.Icon $newExe)
        } catch {}
    })
    # Если загрузка уже идёт к моменту создания кнопки — сразу прячем.
    try { if ($null -ne $btnIconExe -and $slots.Icon.IsLoading) { $btnIconExe.Visible = $false } } catch {}

    # Подсказка card_info убрана: перекрывала кнопки регионов.

    # Нижняя строка карточки. В пакетном режиме три кнопки стоят строго у нижнего
    # края окна и равномерно делят всю ширину карточки на три одинаковые части:
    # отменить пакет / пропустить текущую игру / добавить текущую игру.
    # В обычном режиме кнопки отмены нет: карточка закрывается крестиком окна,
    # а единственная нижняя кнопка занимает всю ширину.
    $bottomButtonY = $dlg.ClientSize.Height - 65
    $bottomButtonHeight = 50
    $bottomButtonGap = 10
    $bottomButtonWidth = [int](($dlg.ClientSize.Width - 40 - $bottomButtonGap*2) / 3)

    $btnAdd = New-Object System.Windows.Forms.Button
    $btnAdd.Text=if($editMode){(T 'card_save')}else{(T 'card_add')}
    # Лицензионные Steam-игры: EXE и App ID только для просмотра.
    if ($licensedMode) {
        try {
            # Тот же фон, что у неактивной кнопки Steam/SGDB ($steamUi.Panel).
            $disabledFill = $steamUi.Panel
            $txtTitle.ReadOnly = $true
            $txtTitle.TabStop = $false
            $txtTitle.BackColor = $disabledFill
            $txtTitle.ForeColor = $steamUi.Muted
            try {
                $pnlTitle.BackColor = $disabledFill
                $pnlTitle.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
            } catch {}
            $txtId.ReadOnly = $true
            $txtId.TabStop = $false
            $txtId.BackColor = $disabledFill
            $txtId.ForeColor = $steamUi.Muted
            $txtId.Text = $licensedAppId
            try {
                $pnlId.BackColor = $disabledFill
                $pnlId.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
            } catch {}
            # НЕ Enabled=false: у отключённого ComboBox Windows игнорирует наш
            # перехват WM_PAINT/WM_NCPAINT и рисует системную светлую рамку/фон
            # поверх тёмной темы (белый "глюк" рамки). Вместо этого только
            # блокируем ввод (Locked) — поле остаётся полностью самостоятельно
            # прорисованным, как во всех остальных состояниях.
            try { $cmbExe.Locked = $true } catch {}
            $cmbExe.TabStop = $false
            $cmbExe.BackColor = $disabledFill
            $cmbExe.ForeColor = $steamUi.Muted
            try { $cmbExe.BorderColor = $disabledFill } catch {}
            try { $cmbExe.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat } catch {}
            try {
                $pnlExe.BackColor = $disabledFill
            } catch {}
            try { $cmbExe.Invalidate(); $cmbExe.Refresh() } catch {}
            # Скрываем «Обзор...» у EXE
            try {
                $btnBrowseExe.Enabled = $false
                $btnBrowseExe.Visible = $false
            } catch {}
            foreach ($c in @($dlg.Controls)) {
                try {
                    if ($c -is [System.Windows.Forms.Button] -and (@($script:I18n.Values | ForEach-Object { [string]$_['browse'] }) -contains [string]$c.Text)) {
                        if ($c.Location.Y -ge 45 -and $c.Location.Y -le 60) { $c.Enabled = $false; $c.Visible = $false }
                    }
                } catch {}
            }
        } catch {}
    }

    if($batchMode){
        $btnAdd.Location=New-Object System.Drawing.Point((20 + ($bottomButtonWidth + $bottomButtonGap)*2),$bottomButtonY)
        $btnAdd.Size=New-Object System.Drawing.Size($bottomButtonWidth,$bottomButtonHeight)
    } else {
        $btnAdd.Location=New-Object System.Drawing.Point(20,$bottomButtonY)
        $btnAdd.Size=New-Object System.Drawing.Size(($dlg.ClientSize.Width - 40),$bottomButtonHeight)
    }
    $btnAdd.FlatStyle='Flat'; $btnAdd.FlatAppearance.BorderColor=$steamUi.Accent2; $btnAdd.BackColor=[System.Drawing.Color]::FromArgb(25,55,75); $btnAdd.ForeColor=$steamUi.Text; $btnAdd.Font=New-Object System.Drawing.Font('Segoe UI Semibold',10)
    $dlg.Controls.Add($btnAdd)

    $btnCancel = $null
    if($batchMode){
        $btnCancel = New-Object System.Windows.Forms.Button
        $btnCancel.Text=(T 'card_cancel')
        $btnCancel.Location=New-Object System.Drawing.Point(20,$bottomButtonY)
        $btnCancel.Size=New-Object System.Drawing.Size($bottomButtonWidth,$bottomButtonHeight)
        $btnCancel.FlatStyle='Flat'; $btnCancel.FlatAppearance.BorderColor=$steamUi.Border; $btnCancel.BackColor=$steamUi.Panel; $btnCancel.ForeColor=$steamUi.Text
        $dlg.Controls.Add($btnCancel)
    }

    $btnSkip = $null
    if($batchMode){
        $btnSkip = New-Object System.Windows.Forms.Button
        $btnSkip.Text=(T 'card_skip')
        $btnSkip.Location=New-Object System.Drawing.Point((20 + $bottomButtonWidth + $bottomButtonGap),$bottomButtonY)
        $btnSkip.Size=New-Object System.Drawing.Size($bottomButtonWidth,$bottomButtonHeight)
        $btnSkip.FlatStyle='Flat'
        $btnSkip.FlatAppearance.BorderColor=$steamUi.Border
        $btnSkip.BackColor=$steamUi.Panel
        $btnSkip.ForeColor=$steamUi.Text
        $btnSkip.Font=New-Object System.Drawing.Font('Segoe UI Semibold',10)
        $dlg.Controls.Add($btnSkip)
    }

    # ===== Языки обложек Steam: одна строка на уровне поля «Параметры», правый край = 860 =====
    # Зона: справа от поля параметров (x ~545..860, y 87..115). Значок 32×24, зазор 2 px.
    # Правый край последнего значка совпадает с правым краем остальных элементов карточки (860).
    # Если языков больше 9, на странице 8 значков, а 9-й — кнопка «›» («далее»): она листает
    # страницы по кругу. Если активный язык сейчас на другой странице, «›» подсвечивается
    # (см. Set-EditorCoverLangButton). В режиме ROM значков языка нет вообще.
    $coverLangCols = 9
    $coverLangRows = 1
    $coverLangCap = $coverLangCols * $coverLangRows
    $coverLangCellW = 34      # значок 32 + зазор слева 2 (справа отступа нет)
    $coverLangCellH = 28
    $coverLangRight = 860     # общий правый край элементов карточки
    $coverLangTop = 87 + $romRowOffset   # строка «Параметры»
    # Правая колонка DLSS (под слотами) использует эти значения — не менять.
    $coverLangWidth = 216
    $coverLangLeft = $coverLangRight - $coverLangWidth
    $coverLangPanelW = $coverLangCols * $coverLangCellW + 2
    $coverLangPanelLeft = $coverLangRight - $coverLangPanelW
    $coverLangState = [PSCustomObject]@{ Page = 0; Codes = @() }

    $btnCoverLang = New-Object System.Windows.Forms.FlowLayoutPanel
    $btnCoverLang.Name = 'EditorCoverLangButton'
    $btnCoverLang.Size = New-Object System.Drawing.Size($coverLangPanelW, $coverLangCellH)
    $btnCoverLang.Location = New-Object System.Drawing.Point($coverLangPanelLeft, $coverLangTop)
    $btnCoverLang.Anchor = [System.Windows.Forms.AnchorStyles]::Top
    $btnCoverLang.FlowDirection = [System.Windows.Forms.FlowDirection]::LeftToRight
    $btnCoverLang.WrapContents = $true
    $btnCoverLang.AutoScroll = $false
    $btnCoverLang.Padding = New-Object System.Windows.Forms.Padding(0)
    $btnCoverLang.Margin = New-Object System.Windows.Forms.Padding(0)
    $btnCoverLang.BackColor = $steamUi.Bg
    $btnCoverLang.Cursor = [System.Windows.Forms.Cursors]::Default
    $btnCoverLang.TabStop = $false
    $btnCoverLang.Tag = [PSCustomObject]@{ Lang=[string](Get-SteamAssetLanguage); Codes=@() }
    if ($IsRomEntry) { $btnCoverLang.Visible = $false }
    $dlg.Controls.Add($btnCoverLang)

    $alignCoverLangPanelRight = {
        try {
            $cnt = @($btnCoverLang.Controls).Count
            if ($cnt -le 0) { $btnCoverLang.Height = 0 }
            else {
                # Ширина по числу значков, правый край панели (= последнего значка) всегда 860.
                $usedCols = [Math]::Min($cnt, $coverLangCols)
                $panelW = $usedCols * $coverLangCellW + 2
                $btnCoverLang.Width = $panelW
                $btnCoverLang.Left = $coverLangRight - $panelW
                $btnCoverLang.Top = $coverLangTop
                $rowsUsed = [Math]::Min($coverLangRows, [int][Math]::Ceiling($cnt / [double]$coverLangCols))
                $btnCoverLang.Height = $rowsUsed * $coverLangCellH
            }
        } catch {}
    }

    # Рисует текущую страницу языков из $coverLangState (набор кодов + номер страницы).
    $buildCoverLangPage = {
        $all = @($coverLangState.Codes)
        $active = [string]$btnCoverLang.Tag.Lang
        $paged = ($all.Count -gt $coverLangCap)
        $perPage = $coverLangCap
        if ($paged) { $perPage = $coverLangCap - 1 }
        $pageCount = 1
        if ($paged) { $pageCount = [int][Math]::Ceiling($all.Count / [double]$perPage) }
        $page = [int]$coverLangState.Page
        if ($page -lt 0 -or $page -ge $pageCount) { $page = 0 }
        $coverLangState.Page = $page
        $list = @($all | Select-Object -Skip ($page * $perPage) -First $perPage)

        Set-EditorCoverLanguageButtons $btnCoverLang $list $active
        # Set-EditorCoverLanguageButtons записывает в Tag.Codes только показанные значки,
        # а остальной код читает оттуда ПОЛНЫЙ список языков — возвращаем его.
        $btnCoverLang.Tag.Codes = @($all)

        if ($paged) {
            $others = @($all | Where-Object { $list -notcontains $_ })
            $next = New-Object System.Windows.Forms.Button
            $next.Size = New-Object System.Drawing.Size(40, 24)
            $next.Padding = New-Object System.Windows.Forms.Padding(0)
            $next.Text = [string][char]0x203A
            $next.FlatStyle = 'Flat'
            $next.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 12)
            $next.Cursor = [System.Windows.Forms.Cursors]::Hand
            $next.TabStop = $false
            $next.BackColor = $steamUi.Panel
            $next.ForeColor = $steamUi.Muted
            $next.FlatAppearance.BorderColor = $steamUi.Border
            $nextTip = New-Object System.Windows.Forms.ToolTip
            $nextTip.SetToolTip($next, (T 'covlang_next' @(($page + 1), $pageCount)))
            $next.Tag = [PSCustomObject]@{ IsMore = $true; Overflow = @($others); Lang = ''; Tip = $nextTip }
            $next.Add_Click({
                try {
                    $pc = [int][Math]::Ceiling(@($coverLangState.Codes).Count / [double]($coverLangCap - 1))
                    if ($pc -lt 1) { $pc = 1 }
                    $coverLangState.Page = ([int]$coverLangState.Page + 1) % $pc
                    & $buildCoverLangPage
                } catch {}
            })
            [void]$btnCoverLang.Controls.Add($next)
            try { Set-EditorCoverLangButton $btnCoverLang $active } catch {}
        }

        # Значок 32×24, отступы слева/сверху/снизу по 2 px, справа 0: ячейка 34×28,
        # правый край последнего значка вплотную к правому краю панели.
        $ctrls = @($btnCoverLang.Controls)
        foreach ($cc in $ctrls) {
            $cc.Size = New-Object System.Drawing.Size(32, 24)
            $cc.Margin = New-Object System.Windows.Forms.Padding(2, 2, 0, 2)
        }
        foreach ($child in $ctrls) {
            try {
                $isMore = $false
                try { $isMore = [bool]$child.Tag.IsMore } catch {}
                if (-not $isMore) { & $wireCoverLanguageButton $child }
            } catch {}
        }
        & $alignCoverLangPanelRight
    }

    $renderCoverLanguages = {
        param([object[]]$codes, [string]$activeLang)
        if ($IsRomEntry) { $btnCoverLang.Visible = $false; return }
        $all = @($codes)
        $paged = ($all.Count -gt $coverLangCap)
        $perPage = $coverLangCap
        if ($paged) { $perPage = $coverLangCap - 1 }
        # Тот же набор языков — остаёмся на текущей странице; новый набор — открываем
        # страницу с активным языком.
        $sameSet = ((@($coverLangState.Codes) -join '|') -eq ($all -join '|'))
        if (-not $sameSet) {
            $page = 0
            if ($paged -and -not [string]::IsNullOrWhiteSpace([string]$activeLang)) {
                for ($ai = 0; $ai -lt $all.Count; $ai++) {
                    if ([string]$all[$ai] -eq [string]$activeLang) { $page = [int][Math]::Floor($ai / $perPage); break }
                }
            }
            $coverLangState.Page = $page
        }
        $coverLangState.Codes = $all
        if (-not [string]::IsNullOrWhiteSpace([string]$activeLang)) { $btnCoverLang.Tag.Lang = [string]$activeLang }
        & $buildCoverLangPage
    }

    # ===== Апскейлеры в карточке: сетка 3×3 справа от слотов Логотип/Иконка (x 590..860, y 428..) =====
    # Девять DLL: DLSS (SR / RR / FG), FSR 3.1 (DX12 / Vulkan), XeSS (основная / FG / DX11), XeLL.
    # Первое поле (DLSS, nvngx_dlss.dll) — главное: именно по нему показывается версия DLSS
    # на плитке. Поля скрыты, пока в папке игры не найдена соответствующая DLL; найденные
    # укладываются в сетку слева направо, сверху вниз без пропусков. Левый край сетки совпадает
    # с левым краем слота «Hero», правый — с правым краем всех остальных элементов (860).
    # Поиск идёт в фоне после показа карточки (см. $startDlssScan ниже), чтобы окно не подвисало.
    $dlssControls = [ordered]@{}
    # Title — короткая подпись над полем (в сетке 86 px полные названия не помещаются),
    # Tip — полное название во всплывающей подсказке, File — имя DLL, по которой ищем версию.
    $dlssFieldDefs = @(
        @{ Key = 'SR';     Title = 'DLSS';      Tip = (T 'card_dlss_sr');            File = 'nvngx_dlss.dll';           Name = 'EditorDlssSrCombo' },
        @{ Key = 'RR';     Title = 'DLSS RR';   Tip = (T 'card_dlss_rr');            File = 'nvngx_dlssd.dll';          Name = 'EditorDlssRrCombo' },
        @{ Key = 'FG';     Title = 'DLSS FG';   Tip = (T 'card_dlss_fg');            File = 'nvngx_dlssg.dll';          Name = 'EditorDlssFgCombo' },
        @{ Key = 'FSR12';  Title = 'FSR DX12';  Tip = 'FSR 3.1 DirectX 12';          File = 'amd_fidelityfx_dx12.dll';  Name = 'EditorFsrDx12Combo' },
        @{ Key = 'FSRVK';  Title = 'FSR VK';    Tip = 'FSR 3.1 Vulkan';              File = 'amd_fidelityfx_vk.dll';    Name = 'EditorFsrVkCombo' },
        @{ Key = 'XESS';   Title = 'XeSS';      Tip = 'XeSS';                        File = 'libxess.dll';              Name = 'EditorXessCombo' },
        @{ Key = 'XESSFG'; Title = 'XeSS FG';   Tip = 'XeSS Frame Generation';       File = 'libxess_fg.dll';           Name = 'EditorXessFgCombo' },
        @{ Key = 'XESS11'; Title = 'XeSS DX11'; Tip = 'XeSS (DirectX 11)';           File = 'libxess_dx11.dll';         Name = 'EditorXessDx11Combo' },
        @{ Key = 'XELL';   Title = 'XeLL';      Tip = 'XeLL (Xe Low Latency)';       File = 'libxell.dll';              Name = 'EditorXellCombo' }
    )
    $dlssGridLeft = 551          # слот «Иконка» заканчивается на 539 (305 + 234), зазор 12
    $dlssColW     = 99           # внутри поля помещается полная версия вида «v310.7.129»
    $dlssColGap   = 6            # 3 × 99 + 2 × 6 = 309 → правый край 860
    $dlssGridCols = 3
    $dlssRowH     = 48           # поле 16 (подпись) + 24 (список) + 8 зазор; под сеткой остаётся место для двух кнопок
    $dlssTip = New-Object System.Windows.Forms.ToolTip
    # Разметка элементов выпадающих списков: имя комбо -> массив 'dl' (скачана) / 'nodl' (не скачана) / 'cur' (версия из папки игры).
    $dlssMarks = @{}
    $dlssCommitted = @{} # имя комбо -> индекс выбранной (зафиксированной) версии — для зелёного цвета в списке
    $dlssBaseTip = @{}
    $dlssOrig = @{}      # ключ поля -> индекс исходной версии (для «Восстановить»: бэкап .sc_orig, иначе версия из папки игры)
    $dlssCurIdx = @{}    # ключ поля -> индекс версии, которая лежит в игре прямо сейчас
    $dlssSrcs = @{}      # имя комбо -> массив файлов-источников по элементам списка ('' — взять неоткуда)
    $dlssTargets = @{}   # ключ поля -> все найденные в игре копии DLL
    $dlssTitles = @{}    # ключ поля -> короткое название (DLSS, FSR DX12, ...)
    $dlssDrawItem = {
        param($sender, $e)
        if ($e.Index -lt 0) { return }
        $isSelected = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        $isLocked = $false
        try { $isLocked = [bool]$sender.Locked } catch {}
        if ($isLocked) {
            $bg = $steamUi.Input; $fg = $steamUi.Text
            # Поле без найденной DLL («Не найдено») рисуем приглушённым цветом.
            try { if ([string]$sender.Tag -eq 'missing') { $fg = $steamUi.Muted } } catch {}
        }
        else {
            # Как в настройках: белый текст — версия скачана (или лежит в папке игры), серый — ещё нет,
            # зелёный — выбранная в списке версия. Под курсором подсвечивается только фон.
            $bg = if ($isSelected) { $steamUi.Border } else { $steamUi.Input }
            $fg = $steamUi.Text
            try {
                $mk = @($dlssMarks[[string]$sender.Name])
                if ($e.Index -lt $mk.Count -and [string]$mk[$e.Index] -eq 'nodl') { $fg = $steamUi.Muted }
            } catch {}
            # Зелёная — только зафиксированная версия ($dlssCommitted); SelectedIndex при наведении в открытом списке
            # прыгает за курсором. Закрытое поле показывает именно выбранную.
            try {
                if (($e.State -band [System.Windows.Forms.DrawItemState]::ComboBoxEdit) -ne 0) { $fg = $steamUi.Green }
                elseif ($dlssCommitted.ContainsKey([string]$sender.Name) -and [int]$dlssCommitted[[string]$sender.Name] -eq [int]$e.Index) { $fg = $steamUi.Green }
            } catch {}
        }
        $bgBrush = New-Object System.Drawing.SolidBrush($bg)
        $textBrush = New-Object System.Drawing.SolidBrush($fg)
        try {
            $e.Graphics.FillRectangle($bgBrush, $e.Bounds)
            $text = [string]$sender.Items[$e.Index]
            $drawFont = $sender.Font
            $ownFont = $false
            $textSize = $e.Graphics.MeasureString($text, $drawFont)
            # Подпись «Отсутствует» (любой язык, в т.ч. пользовательский перевод) не должна обрезаться
            # многоточием: если не помещается, уменьшаем шрифт (не мельче 7 pt).
            $sz = [float]$sender.Font.Size
            if ($isLocked -and [string]$sender.Tag -eq 'missing') {
                $maxW = [float][Math]::Max(10, ($sender.Width - 10))
                while ($textSize.Width -gt $maxW -and $sz -gt 7) {
                    $sz = $sz - 0.5
                    if ($ownFont) { $drawFont.Dispose() }
                    $drawFont = New-Object System.Drawing.Font($sender.Font.FontFamily, $sz, $sender.Font.Style)
                    $ownFont = $true
                    $textSize = $e.Graphics.MeasureString($text, $drawFont)
                }
            }
            if ($isLocked) {
                # Заблокированное поле: подпись по центру всей ширины рисует сам SmartExeComboBox
                # (PaintChrome) — здесь только передаём цвет и размер шрифта.
                $sender.CenterTextColor = $fg
                $sender.CenterFontSize = $sz
                $sender.CenterText = $true
            }
            else {
                $sender.CenterText = $false
                $textY = $e.Bounds.Y + [Math]::Max(0, [int](($e.Bounds.Height - $textSize.Height) / 2))
                $textRect = New-Object System.Drawing.RectangleF([float]($e.Bounds.X + 6), [float]$textY, [float][Math]::Max(10, ($e.Bounds.Width - 8)), [float]$textSize.Height)
                $sf = New-Object System.Drawing.StringFormat
                try {
                    $sf.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter
                    $sf.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap
                    $e.Graphics.DrawString($text, $drawFont, $textBrush, $textRect, $sf)
                } finally { $sf.Dispose() }
            }
            if ($ownFont) { $drawFont.Dispose() }
        } finally { $bgBrush.Dispose(); $textBrush.Dispose() }
    }
    $dlssTop = 428 + $romRowOffset
    $dlssIdx = 0
    foreach ($def in $dlssFieldDefs) {
        $dlssX = $dlssGridLeft + ($dlssIdx % $dlssGridCols) * ($dlssColW + $dlssColGap)
        $dlssY = $dlssTop + [int][Math]::Floor($dlssIdx / $dlssGridCols) * $dlssRowH
        $lbl = New-Object System.Windows.Forms.Label
        $lbl.Text = [string]$def.Title
        $lbl.Location = New-Object System.Drawing.Point($dlssX, $dlssY)
        $lbl.Size = New-Object System.Drawing.Size($dlssColW, 16)
        $lbl.Font = New-Object System.Drawing.Font('Segoe UI Semibold', 9)
        $lbl.ForeColor = $steamUi.Text
        $lbl.BackColor = $steamUi.Bg
        $lbl.AutoEllipsis = $true
        $lbl.Visible = (-not $IsRomEntry)
        $dlg.Controls.Add($lbl)
        $dlssTip.SetToolTip($lbl, ([string]$def.Tip + ' (' + [string]$def.File + ')'))

        $pnl = New-Object System.Windows.Forms.Panel
        $pnl.Location = New-Object System.Drawing.Point($dlssX, ($dlssY + 16))
        $pnl.Size = New-Object System.Drawing.Size($dlssColW, 24)
        $pnl.BackColor = $steamUi.Input
        $pnl.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
        $pnl.Visible = (-not $IsRomEntry)
        $dlg.Controls.Add($pnl)

        $cmb = New-Object SmartExeComboBox
        $cmb.Name = [string]$def.Name
        $cmb.Dock = [System.Windows.Forms.DockStyle]::Fill
        $cmb.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
        $cmb.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
        $cmb.ItemHeight = 18
        $cmb.IntegralHeight = $false
        $cmb.MaxDropDownItems = 12
        $cmb.DropDownWidth = 170
        $cmb.BackColor = $steamUi.Input
        $cmb.ForeColor = $steamUi.Text
        $cmb.Font = New-Object System.Drawing.Font('Segoe UI', 9)
        $cmb.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        try { $cmb.BorderColor = $steamUi.Input } catch {}
        [void]$cmb.Items.Add([string][char]0x2014)
        $cmb.SelectedIndex = 0
        $cmb.Locked = $true
        $cmb.Add_DrawItem($dlssDrawItem)
        $cmb.Add_SelectionChangeCommitted({
            param($snd, $ea)
            try { $dlssCommitted[[string]$snd.Name] = [int]$snd.SelectedIndex } catch {}
        }.GetNewClosure())
        # После выбора версии снимаем фокус с поля (иначе остаётся серая подсветка
        # выбранного значения). Фокус отдаём невидимому $editorFocusSink; повторно
        # через BeginInvoke - после закрытия popup WinForms сам возвращает фокус комбобоксу.
        $cmb.Add_DropDownClosed({
            try {
                $dlg.ActiveControl = $editorFocusSink
                $editorFocusSink.Focus() | Out-Null
                $dlg.BeginInvoke([Action]{
                    try { $dlg.ActiveControl = $editorFocusSink; $editorFocusSink.Focus() | Out-Null } catch {}
                }) | Out-Null
            } catch {}
        }.GetNewClosure())
        $pnl.Controls.Add($cmb)

        $dlssControls[[string]$def.Key] = [PSCustomObject]@{ Label = $lbl; Panel = $pnl; Combo = $cmb }
        $dlssBaseTip[[string]$def.Key] = ([string]$def.Tip + ' (' + [string]$def.File + ')')
        $dlssTitles[[string]$def.Key] = [string]$def.Title
        $dlssTip.SetToolTip($pnl, $dlssBaseTip[[string]$def.Key])
        $dlssIdx++
    }

    # ----- Кнопки под сеткой: «Выбрать последние» и «Восстановить» -----
    # Работают только с выбором в выпадающих списках (замена файлов в папке игры — отдельный шаг).
    $dllBtnGap = 6
    $dllBtnW = [int][Math]::Floor((3 * $dlssColW + 2 * $dlssColGap - $dllBtnGap) / 2)
    $dllBtnY = $dlssTop + 2 * $dlssRowH + 40 + 6
    $newDllButton = {
        param([string]$text, [int]$x)
        $b = New-Object System.Windows.Forms.Button
        $b.Text = $text
        $b.Location = New-Object System.Drawing.Point($x, $dllBtnY)
        $b.Size = New-Object System.Drawing.Size($dllBtnW, 26)
        $b.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $b.FlatAppearance.BorderColor = $steamUi.Border
        $b.FlatAppearance.MouseOverBackColor = $steamUi.Selected
        $b.BackColor = $steamUi.Panel
        $b.ForeColor = $steamUi.Text
        $b.Font = New-Object System.Drawing.Font('Segoe UI', 9)
        $b.Padding = New-Object System.Windows.Forms.Padding(0)
        $b.TabStop = $false
        $b.Cursor = [System.Windows.Forms.Cursors]::Hand
        $b.Enabled = $false
        $b.Visible = (-not $IsRomEntry)
        $dlg.Controls.Add($b)
        return $b
    }
    $btnDllLatest = & $newDllButton (T 'upl_select_latest') $dlssGridLeft
    $btnDllRestore = & $newDllButton (T 'card_dll_btn_restore') ($dlssGridLeft + $dllBtnW + $dllBtnGap)
    $dlssTip.SetToolTip($btnDllLatest, (T 'card_dll_tip_latest'))
    $dlssTip.SetToolTip($btnDllRestore, (T 'card_dll_tip_restore'))

    # «Выбрать последние»: в каждом найденном поле выбирается самая новая из скачанных версий.
    $btnDllLatest.Add_Click({
        try {
            $changed = 0
            foreach ($k in @($dlssControls.Keys)) {
                $c = $dlssControls[$k].Combo
                if ([bool]$c.Locked) { continue }
                $mk = @($dlssMarks[[string]$c.Name])
                $idx = -1
                for ($i = 0; $i -lt $mk.Count; $i++) { if ([string]$mk[$i] -eq 'dl') { $idx = $i; break } }
                if ($idx -ge 0 -and $c.SelectedIndex -ne $idx) { $c.SelectedIndex = $idx; $dlssCommitted[[string]$c.Name] = $idx; $changed++ }
            }
            if ($changed -gt 0) { $status.Text = (T 'upl_latest_done' @($changed)) } else { $status.Text = (T 'upl_latest_same') }
        } catch {}
    }.GetNewClosure())

    # «Восстановить»: в каждом поле возвращается исходная версия — та, что лежит в папке игры.
    $btnDllRestore.Add_Click({
        try {
            $changed = 0
            foreach ($k in @($dlssControls.Keys)) {
                $c = $dlssControls[$k].Combo
                if ([bool]$c.Locked) { continue }
                if (-not $dlssOrig.ContainsKey([string]$k)) { continue }
                $idx = [int]$dlssOrig[[string]$k]
                if ($idx -ge 0 -and $idx -lt $c.Items.Count -and $c.SelectedIndex -ne $idx) { $c.SelectedIndex = $idx; $dlssCommitted[[string]$c.Name] = $idx; $changed++ }
            }
            if ($changed -gt 0) { $status.Text = (T 'card_dll_restored' @($changed)) } else { $status.Text = (T 'card_dll_restore_same') }
        } catch {}
    }.GetNewClosure())

    # ----- Поиск DLL DLSS в папке игры -----
    # Корень поиска: для записи из библиотеки — тот же, что для версии на плитке
    # (Get-LibDlssEntryDir), иначе папка игры из панели ($gamePath). ROM-ы DLSS не имеют.
    $dlssRoot = ''
    try {
        if (-not $IsRomEntry) {
            if ($null -ne $libraryEntry) { $dlssRoot = [string](Get-LibDlssEntryDir $libraryEntry) }
            if ([string]::IsNullOrWhiteSpace($dlssRoot)) {
                $gp = ([string]$gamePath).Trim().Trim('"').TrimEnd('\')
                if ($gp -and [System.IO.Directory]::Exists($gp)) {
                    $gr = ''
                    try { $gr = [System.IO.Path]::GetPathRoot($gp) } catch {}
                    # Корень диска не обходим.
                    if (-not ($gr -and ($gr.TrimEnd('\') -eq $gp))) { $dlssRoot = $gp }
                }
            }
        }
    } catch { $dlssRoot = '' }

    $dlssScan = [PSCustomObject]@{ State = $null; Ps = $null; Rs = $null; Timer = $null }

    # Ставит поле в состояние «Не найдено» (приглушённый текст).
    $setDlssMissing = {
        param($c)
        $c.Combo.Items.Clear()
        [void]$c.Combo.Items.Add((T 'card_dll_not_found'))
        $c.Combo.SelectedIndex = 0
        $c.Combo.Tag = 'missing'
        try { $c.Combo.Invalidate() } catch {}
    }

    # Фоновый обход папки игры (глубина до 12, ссылки-junction пропускаем): собираем ВСЕ копии
    # трёх DLL с их версиями — копий в игре бывает несколько, они понадобятся при замене.
    $dlssWorker = {
        param($root, $state)
        try {
            $names = @('nvngx_dlss.dll', 'nvngx_dlssd.dll', 'nvngx_dlssg.dll',
                       'amd_fidelityfx_dx12.dll', 'amd_fidelityfx_vk.dll',
                       'libxess.dll', 'libxess_fg.dll', 'libxess_dx11.dll', 'libxell.dll')
            $res = @{}
            foreach ($nm in $names) { $res[$nm] = New-Object System.Collections.ArrayList }
            $queue = New-Object System.Collections.Generic.Queue[object]
            $queue.Enqueue(@($root, 0))
            $visited = 0
            while ($queue.Count -gt 0 -and $visited -lt 30000) {
                if ($state['Cancel']) { break }
                $it = $queue.Dequeue()
                $dir = [string]$it[0]
                $depth = [int]$it[1]
                $visited++
                foreach ($nm in $names) {
                    try {
                        $cand = [System.IO.Path]::Combine($dir, $nm)
                        if ([System.IO.File]::Exists($cand)) { [void]$res[$nm].Add($cand) }
                    } catch {}
                }
                if ($depth -lt 12) {
                    try {
                        foreach ($sd in [System.IO.Directory]::EnumerateDirectories($dir)) {
                            $skip = $false
                            try { if (([System.IO.File]::GetAttributes($sd) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $skip = $true } } catch { $skip = $true }
                            if (-not $skip) { $queue.Enqueue(@([string]$sd, ($depth + 1))) }
                        }
                    } catch {}
                }
            }
            $out = @{}
            foreach ($nm in $names) {
                $list = New-Object System.Collections.ArrayList
                foreach ($fp in $res[$nm]) {
                    $ver = ''
                    try {
                        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo([string]$fp)
                        $parts = @([int]$vi.FileMajorPart, [int]$vi.FileMinorPart, [int]$vi.FileBuildPart, [int]$vi.FilePrivatePart)
                        if ($parts[0] -gt 0) {
                            $n = 4
                            while ($n -gt 2 -and $parts[$n - 1] -eq 0) { $n-- }
                            $ver = 'v' + ((@($parts[0..($n - 1)])) -join '.')
                        }
                    } catch {}
                    [void]$list.Add([PSCustomObject]@{ Path = [string]$fp; Ver = [string]$ver })
                }
                $out[$nm] = $list
            }
            $state['Result'] = $out
        } catch {}
        $state['Done'] = $true
    }

    # Приводит версию к виду 'a.b.c.d' (без 'v', добивая нулями до 4 частей), чтобы 'v310.7.129' из DLL
    # совпадало с '310.7.129.0' из манифеста.
    $normDlssVer = {
        param([string]$v)
        $t = ([string]$v).Trim().TrimStart('v', 'V')
        if ($t -notmatch '^\d+(\.\d+)*$') { return '' }
        $parts = @($t.Split('.'))
        while ($parts.Count -lt 4) { $parts += '0' }
        return ((@($parts[0..3])) -join '.')
    }

    # Список версий для поля: все версии из кэша манифеста + скачанные, которых в манифесте нет —
    # ровно тот набор, что в настройках («Библиотеки апскейлеров»). Версия из папки игры выбирается в
    # списке; если её там нет — добавляется отдельной белой строкой («cur»). То же с исходной версией
    # из бэкапа (<dll>.sc_orig), если игру уже меняли. Srcs[i] — файл, из которого версию можно поставить
    # в игру: скачанная версия из библиотеки или бэкап оригинала; '' — взять неоткуда (не скачана).
    $buildDlssItems = {
        param([string]$key, [string]$gameVer, $remote, [string]$origVer = '', [string]$origPath = '')
        $list = New-Object System.Collections.ArrayList
        $raw = New-Object System.Collections.ArrayList
        $udef = $null
        foreach ($ud in @(Get-UpscalerDefs)) { if ([string]$ud.Key -eq $key) { $udef = $ud; break } }
        if ($null -ne $udef) {
            $local = @(Get-UpscalerLocalVersions $key ([string]$udef.File))
            $localById = @{}
            foreach ($lv in $local) { $localById[[string]$lv.Id] = $lv }
            $seen = @{}
            $ord = 0
            foreach ($en in @(Get-UpscalerRemoteEntries $remote $udef)) {
                $eid = New-UpscalerEntryId $en
                if ($seen.ContainsKey($eid)) { continue }
                $seen[$eid] = $true
                $txt = Format-UpscalerVersion ([string]$en.ver)
                if (-not [string]::IsNullOrWhiteSpace([string]$en.label)) { $txt += ' ' + [string]$en.label }
                $kind = 'nodl'; $src = ''
                if ($localById.ContainsKey($eid)) { $kind = 'dl'; $src = [string]$localById[$eid].Path }
                [void]$raw.Add([PSCustomObject]@{ Text = $txt; Kind = $kind; Src = $src; Norm = (& $normDlssVer ([string]$en.ver)); Num = (ConvertTo-UpscalerVersionObj ([string]$en.ver)); Ord = $ord })
                $ord++
            }
            foreach ($lv in $local) {
                if ($seen.ContainsKey([string]$lv.Id)) { continue }
                [void]$raw.Add([PSCustomObject]@{ Text = [string]$lv.Display; Kind = 'dl'; Src = [string]$lv.Path; Norm = (& $normDlssVer ([string]$lv.Ver)); Num = $lv.Num; Ord = $ord })
                $ord++
            }
        }
        foreach ($r in @($raw | Sort-Object -Property @{ Expression = { $_.Num }; Descending = $true }, @{ Expression = { $_.Ord }; Descending = $false })) { [void]$list.Add($r) }

        # Строка списка по версии (из нескольких одинаковых предпочитаем скачанную).
        $findIdx = {
            param([string]$norm)
            $res = -1
            if ($norm -eq '') { return -1 }
            for ($i = 0; $i -lt $list.Count; $i++) {
                if ([string]$list[$i].Norm -ne $norm) { continue }
                if ($res -lt 0) { $res = $i }
                if ([string]$list[$i].Kind -eq 'dl') { $res = $i; break }
            }
            return $res
        }
        # Добавляет белую строку на место по номеру версии, возвращает её индекс.
        $insertItem = {
            param([string]$text, [string]$norm, [string]$src)
            $num = [version]'0.0'
            if ($norm -ne '') { $num = ConvertTo-UpscalerVersionObj $norm }
            $obj = [PSCustomObject]@{ Text = $text; Kind = 'cur'; Src = $src; Norm = $norm; Num = $num; Ord = 0 }
            $pos = 0
            if ($norm -ne '') { while ($pos -lt $list.Count -and $list[$pos].Num -ge $num) { $pos++ } }
            $list.Insert($pos, $obj)
            return [int]$pos
        }

        $gameNorm = & $normDlssVer $gameVer
        $selIdx = [int](& $findIdx $gameNorm)
        $origNorm = & $normDlssVer $origVer
        $origIdx = -2   # -2: исходная версия совпадает с текущей
        if ($origNorm -ne '' -and $origNorm -ne $gameNorm) { $origIdx = [int](& $findIdx $origNorm) }

        if ($selIdx -lt 0) {
            $curText = [string]$gameVer
            if ([string]::IsNullOrWhiteSpace($curText)) { $curText = '?' }
            $pos = [int](& $insertItem $curText $gameNorm '')
            if ($origIdx -ge 0 -and $origIdx -ge $pos) { $origIdx++ }
            $selIdx = $pos
        }
        if ($origIdx -eq -2) {
            $origIdx = $selIdx
        } elseif ($origIdx -lt 0) {
            $pos = [int](& $insertItem $origVer $origNorm $origPath)
            if ($selIdx -ge $pos) { $selIdx++ }
            $origIdx = $pos
        } elseif ([string]::IsNullOrEmpty([string]$list[$origIdx].Src)) {
            $list[$origIdx].Src = $origPath
        }
        return [PSCustomObject]@{
            Texts = @($list | ForEach-Object { [string]$_.Text })
            Kinds = @($list | ForEach-Object { [string]$_.Kind })
            Srcs = @($list | ForEach-Object { [string]$_.Src })
            SelIdx = [int]$selIdx; OrigIdx = [int]$origIdx
        }
    }

    # Все девять полей видны всегда, на своих местах в сетке 3×3: у найденной DLL — выпадающий список
    # версий (версия из папки игры выбрана), у остальных — «Не найдено».
    $applyDlssResult = {
        try {
            $st = $dlssScan.State
            if ($null -eq $st) { return }
            $res = $st['Result']
            if ($null -eq $res) { return }
            $fileOf = [ordered]@{}
            foreach ($d in $dlssFieldDefs) { $fileOf[[string]$d.Key] = [string]$d.File }
            # Кэш манифеста читаем один раз на все девять полей (без сети; нет кэша — только скачанные версии).
            $dlssRemote = $null
            try { $dlssRemote = Get-UpscalerRemote } catch {}
            $anyDllFound = $false
            foreach ($k in @($fileOf.Keys)) {
                $c = $dlssControls[$k]
                $found = @($res[$fileOf[$k]])
                if ($found.Count -eq 0) {
                    & $setDlssMissing $c
                    continue
                }
                $txt = [string]$found[0].Ver
                if ([string]::IsNullOrWhiteSpace($txt)) { $txt = '?' }
                # Бэкап оригинала (<dll>.sc_orig) появляется после первой замены библиотеки программой.
                $origPath = [string]$found[0].Path + '.sc_orig'
                $origVer = ''
                if ([System.IO.File]::Exists($origPath)) { $origVer = [string](Get-DllVersionLabel $origPath) } else { $origPath = '' }
                $built = $null
                try { $built = & $buildDlssItems $k $txt $dlssRemote $origVer $origPath } catch { $built = $null }
                if ($null -eq $built -or @($built.Texts).Count -eq 0) {
                    $built = [PSCustomObject]@{ Texts = @($txt); Kinds = @('cur'); Srcs = @(''); SelIdx = 0; OrigIdx = 0 }
                }
                $dlssMarks[[string]$c.Combo.Name] = @($built.Kinds)
                $dlssSrcs[[string]$c.Combo.Name] = @($built.Srcs)
                $dlssOrig[[string]$k] = [int]$built.OrigIdx
                $dlssCurIdx[[string]$k] = [int]$built.SelIdx
                $dlssTargets[[string]$k] = @($found | ForEach-Object { [string]$_.Path })
                $anyDllFound = $true
                $c.Combo.Items.Clear()
                foreach ($bt in @($built.Texts)) { [void]$c.Combo.Items.Add([string]$bt) }
                $c.Combo.SelectedIndex = [int]$built.SelIdx
                $dlssCommitted[[string]$c.Combo.Name] = [int]$built.SelIdx
                $c.Combo.Tag = $null
                $c.Combo.Locked = $false
                try { $dlssTip.SetToolTip($c.Panel, ([string]$dlssBaseTip[$k] + "`n" + (T 'card_dll_ver_tip'))) } catch {}
                try { $c.Combo.Invalidate() } catch {}
            }
            if ($anyDllFound) { $btnDllLatest.Enabled = $true; $btnDllRestore.Enabled = $true }
            # Найденные копии пригодятся при замене версий (следующий шаг).
            try { $editorState | Add-Member -NotePropertyName DlssFound -NotePropertyValue $res -Force } catch {}
        } catch {}
    }

    $startDlssScan = {
        try {
            if ([string]::IsNullOrWhiteSpace($dlssRoot)) {
                # Папка игры неизвестна — искать негде, все поля «Не найдено» (кроме ROM, где блок скрыт).
                if (-not $IsRomEntry) { foreach ($k in @($dlssControls.Keys)) { & $setDlssMissing $dlssControls[$k] } }
                return
            }
            $state = [hashtable]::Synchronized(@{ Result = $null; Done = $false; Cancel = $false })
            $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
            $rs.Open()
            $ps = [System.Management.Automation.PowerShell]::Create()
            $ps.Runspace = $rs
            [void]$ps.AddScript($dlssWorker.ToString())
            [void]$ps.AddArgument($dlssRoot)
            [void]$ps.AddArgument($state)
            [void]$ps.BeginInvoke()
            $dlssScan.State = $state
            $dlssScan.Ps = $ps
            $dlssScan.Rs = $rs
            $dlssScan.Timer.Start()
        } catch {}
    }

    $dlssScan.Timer = New-Object System.Windows.Forms.Timer
    $dlssScan.Timer.Interval = 250
    $dlssScan.Timer.Add_Tick({
        try {
            $st = $dlssScan.State
            if ($null -eq $st) { $dlssScan.Timer.Stop(); return }
            if (-not [bool]$st['Done']) { return }
            $dlssScan.Timer.Stop()
            & $applyDlssResult
        } catch {}
    })
    # Поиск стартует после показа карточки, а не при её сборке — открытие окна не замедляется.
    $dlg.Add_Shown({ try { & $startDlssScan } catch {} })
    $dlg.Add_FormClosed({
        try { if ($null -ne $dlssScan.State) { $dlssScan.State['Cancel'] = $true } } catch {}
        try { if ($null -ne $dlssScan.Timer) { $dlssScan.Timer.Stop(); $dlssScan.Timer.Dispose() } } catch {}
        try { if ($null -ne $dlssScan.Ps) { $dlssScan.Ps.Dispose() } } catch {}
        try { if ($null -ne $dlssScan.Rs) { $dlssScan.Rs.Dispose() } } catch {}
    })

    $selectCoverLanguage = {
        param([string]$newLang)
        if([string]::IsNullOrWhiteSpace($newLang)){ return }
        if($editorState.SearchSource -ne 'Steam'){ return }
        $appId = $txtId.Text.Trim()
        if($appId -notmatch '^\d+$'){ $status.Text = (T 'covlang_no_appid'); return }
        if([string]$btnCoverLang.Tag.Lang -eq $newLang){ return }

        # 1) Сразу подсвечиваем кнопку региона — до любой сети.
        Set-EditorCoverLangButton $btnCoverLang $newLang
        try { [System.Windows.Forms.Application]::DoEvents() } catch {}

        # 2) Сразу обновляем название под выбранный регион (кэш или быстрый API).
        try {
            $localizedName = Get-SteamLocalizedAppName $appId $newLang
            if (-not [string]::IsNullOrWhiteSpace([string]$localizedName)) {
                $tag = $txtTitle.Tag
                if ($null -ne $tag) { $tag.SuppressAutoSearch = $true }
                try {
                    $txtTitle.Text = [string]$localizedName
                    $txtTitle.SelectionStart = $txtTitle.Text.Length
                    $txtTitle.SelectionLength = 0
                    $dlg.Text = (T 'card_title' @($originalCardName))
                } finally {
                    if ($null -ne $tag) { $tag.SuppressAutoSearch = $false }
                }
                Set-ConfidenceBadge $titleConfidenceBadge $true (T 'badge_title_ok') (T 'badge_title_fail_auto')
            }
        } catch {}
        try { [System.Windows.Forms.Application]::DoEvents() } catch {}

        # 3) Затем грузим обложки выбранного региона (дольше).
        $addWas = $btnAdd.Enabled
        $btnCoverLang.Enabled = $false
        $btnAdd.Enabled = $false
        try {
            $n = [int]@(Reload-EditorSteamCoversForLanguage $appId $slots $status $newLang)[-1]
            # На случай если ControlAdded/перерисовка сбросили стиль — закрепляем выбор.
            Set-EditorCoverLangButton $btnCoverLang $newLang
        } catch {
            $status.Text = (T 'covlang_fail' @([string](Get-SteamLanguageInfo $newLang).Name))
        } finally {
            $btnAdd.Enabled = $addWas
            $btnCoverLang.Enabled = ($editorState.SearchSource -eq 'Steam')
        }
    }

    $btnCoverLang.Add_ControlAdded({
        # После добавления/обновления значков сохраняем тот же стиль активного
        # языка. Сам обработчик не меняет выбранный язык.
        try { Set-EditorCoverLangButton $btnCoverLang ([string]$btnCoverLang.Tag.Lang) } catch {}
    })

    $btnCoverLang.Add_MouseClick({
        try {
            $pt = $btnCoverLang.PointToClient([System.Windows.Forms.Cursor]::Position)
            $child = $btnCoverLang.GetChildAtPoint($pt)
            if($null -ne $child -and $child.Tag -ne $null -and $child.Tag.Lang){
                & $selectCoverLanguage ([string]$child.Tag.Lang)
            }
        } catch {}
    })

    # FlowLayoutPanel передаёт клик дочерней кнопке, поэтому каждому значку
    # добавляем тот же обработчик напрямую.
    $wireCoverLanguageButton = {
        param($b)
        try {
            $b.Add_Click({
                try { & $selectCoverLanguage ([string]$this.Tag.Lang) } catch {}
            })
        } catch {}
    }

    $updateSearchSourceUi = {
        # Регион обложек относится только к Steam-обложкам.
        try { $btnCoverLang.Enabled = ($editorState.SearchSource -eq 'Steam') } catch {}
        $idLbl.Text = $(if($editorState.SearchSource -eq 'Steam'){ 'App ID' } else { 'SGDB ID' })
        # Подпись, значок и подсветка единственной кнопки источника обновляются здесь.
        & $updateSgdbButtonState
    }
    & $updateSearchSourceUi

    # Переключение источника поиска.
    # Важно: сетевой поиск НЕ запускается прямо из Click-обработчика.
    # Он ставится в очередь UI через BeginInvoke. Это исключает повторный вход
    # в обработчик кнопки через Application.DoEvents() и устраняет ситуацию,
    # когда SGDB-поиск продолжает выполняться поверх нового Steam-поиска.
    # Пока текущий поиск выполняется, обе кнопки источника заблокированы.
    # После завершения их можно снова переключать.
    # Переключение источника поиска.
    # ВАЖНО: поиск выполняется непосредственно после смены источника в том же
    # UI-обработчике. Здесь намеренно НЕТ BeginInvoke/DoEvents вокруг самого
    # поиска: предыдущая схема могла оставить карточку в промежуточном
    # состоянии «ищу…», а следующий источник уже не получал результат.
    # Каждый клик запускает полностью самостоятельный поиск и загрузку.
    $switchSearchSource = {
        param([string]$newSource, [bool]$fromPending = $false)

        if ($IsRomEntry) {
            $newSource = 'SteamGridDB'
        }
        try { if ($dlg.IsDisposed -or $dlg.Disposing) { return } } catch {}
        # Клик по уже активному источнику ничего не меняет. Отложенное
        # переключение ($fromPending) выполняется всегда: источник в
        # $editorState к этому моменту уже выставлен самим кликом.
        if(-not $fromPending -and $editorState.SearchSource -eq $newSource){ return }

        # Переключатели источника НЕ блокируются на время поиска/загрузки.
        # Если сейчас идёт загрузка обложек (Steam или SGDB) или поиск названия,
        # клик сразу меняет активный источник и подсветку кнопок, прерывает
        # текущую операцию (флаг прерывания убивает curl.exe и фоновые запросы)
        # и ставит новую загрузку в очередь: она запустится, как только
        # прерванная операция освободит UI (см. Invoke-EditorPendingSwitch в её
        # finally). Запускать её прямо здесь нельзя: старый curl ещё пишет в те
        # же temp-файлы, а старый загрузчик после возврата перезаписал бы слоты.
        # Повторный клик до освобождения просто заменяет отложенное действие —
        # побеждает последний выбранный источник.
        $opBusy = ($global:editorSteamLoadBusy -or $global:editorSgdbLoadBusy -or ([int]$editorState.OpDepth -gt 0))
        if(-not $fromPending -and $opBusy){
            $editorState.SwitchSerial = [int]$editorState.SwitchSerial + 1
            $editorState.SearchSource = $newSource
            try { $titleResults.Visible=$false } catch {}
            & $updateSearchSourceUi
            try { $status.Text = if($newSource -eq 'Steam'){(T 'st_searching_steam')}else{(T 'st_searching_sgdb')} } catch {}
            $pendSwitch = $switchSearchSource; $pendSource = $newSource
            $global:editorPendingSwitchAction = { & $pendSwitch $pendSource $true }.GetNewClosure()
            $global:editorLoadAbortRequested = $true
            return
        }

        $editorState.SwitchSerial = [int]$editorState.SwitchSerial + 1
        $serial = [int]$editorState.SwitchSerial
        $editorState.SearchSource = $newSource
        $editorState.OpDepth = [int]$editorState.OpDepth + 1

        try {
        try { $titleResults.Visible=$false } catch {}
        try { $dlg.ActiveControl=$null } catch {}
        & $updateSearchSourceUi

        $query = ([string]$txtTitle.Text).Trim()
        # Если текущее название подставила сама программа (результат поиска
        # другого источника), ищем по исходному названию, а не по чужому результату.
        try {
            $autoT = ([string]$editorState.AutoTitle).Trim()
            $origT = ([string]$editorState.OriginalTitle).Trim()
            if (-not [string]::IsNullOrWhiteSpace($autoT) -and -not [string]::IsNullOrWhiteSpace($origT) -and $query -eq $autoT) { $query = $origT }
        } catch {}
        $txtId.Text = ''

        # Сбрасываем старые варианты названия и старые миниатюры.
        $tag=$txtTitle.Tag
        if($tag -ne $null){
            $tag.RefreshNeeded=$true
            $tag.Busy=$false
            $tag.Map=@{}
        }
        try { $titleResults.Items.Clear() } catch {}
        foreach($sl in $slots.Values){
            try { Set-EditorPreviewFile $sl $null | Out-Null } catch {}
            try { $sl.ExpectedSource=$newSource } catch {}
            try { $sl.SgdbItems=@() } catch {}
        }

        if([string]::IsNullOrWhiteSpace($query) -or $query.Length -lt 2){
            $status.Text=if($newSource -eq 'Steam'){(T 'st_name_needed_steam')}else{(T 'st_name_needed_sgdb')}
            # Прерванная загрузка могла оставить «Добавить» выключенной.
            if($fromPending){ $btnAdd.Enabled=$true }
            return
        }

        # Кнопки источников остаются активными: «Добавить» блокируем только
        # пока карточка не получила обложки нового источника.
        $btnAdd.Enabled=$false
        $status.Text=if($newSource -eq 'Steam'){(T 'st_searching_steam')}else{(T 'st_searching_sgdb')}
        [System.Windows.Forms.Application]::DoEvents()

        try {
            # Если между началом и концом поиска был создан новый запрос
            # (пользователь переключил источник ещё раз), результат старого
            # запроса не имеет права менять карточку.
            if([int]$editorState.SwitchSerial -ne $serial){ return }

            $candidates=@()
            $chosen=$null

            if($newSource -eq 'Steam'){
                # Собственный поиск вариантов Steam — без SGDB и без ключа.
                # Каждый вариант уже несёт настоящий Steam App ID.
                try { $candidates=@(Get-SteamStoreNameCandidates $query) } catch { $candidates=@() }
                if([int]$editorState.SwitchSerial -ne $serial){ return }
                # Раньше слепо бралась первая подсказка — для игры, которой нет в Steam
                # (например StarCraft), это был случайный «почти-тёзка» (Star Crafter).
                # Теперь берём только точное совпадение (скор >= 1.5) либо результат
                # Find-SteamAppInfo, который проверяет похожесть названия.
                if(@($candidates).Count -gt 0 -and [double]$candidates[0].MatchScore -ge 1.5){
                    $chosen=$candidates[0]
                } else {
                    try { $chosen=Find-SteamAppInfo $query } catch { $chosen=$null }
                }
            } else {
                try { $candidates=@(Get-EditorSgdbCandidates $query '') } catch { $candidates=@() }
                if(@($candidates).Count -gt 0){ $chosen=$candidates[0] }
            }

            if([int]$editorState.SwitchSerial -ne $serial){ return }

            if($null -eq $chosen){
                $status.Text=if($newSource -eq 'Steam'){(T 'st_notfound_steam')}else{(T 'st_notfound_sgdb')}
                # Название не меняем, но варианты оставляем в списке — можно выбрать вручную.
                if($tag -ne $null -and @($candidates).Count -gt 0){
                    try {
                        $mapInfo=New-EditorTitleCandidateMap $candidates
                        $tag.Map=$mapInfo.Map
                        $tag.RefreshNeeded=$false
                        $titleResults.BeginUpdate()
                        $titleResults.Items.Clear()
                        foreach($key in $mapInfo.Names){ [void]$titleResults.Items.Add([string]$key) }
                        & $resizeEditorTitleResults
                    } catch {} finally { try { $titleResults.EndUpdate() } catch {} }
                    try { $titleResults.SelectedIndex=-1 } catch {}
                }
                return
            }

            $chosenId=0
            try { $chosenId=[int]$chosen.Id } catch { $chosenId=0 }
            if($chosenId -le 0){
                $status.Text=if($newSource -eq 'Steam'){(T 'st_noid_steam')}else{(T 'st_noid_sgdb')}
                return
            }

            # Заполняем выпадающий список теми же кандидатами, которые реально
            # использованы для текущего источника.
            if($tag -ne $null){
                $mapInfo=New-EditorTitleCandidateMap $candidates
                $newMap=$mapInfo.Map
                $mapNames=$mapInfo.Names
                if($newMap.Count -eq 0){ $newMap[[string]$chosen.Name]=$chosen; [void]$mapNames.Add([string]$chosen.Name) }
                $tag.Map=$newMap
                $tag.RefreshNeeded=$false

                # Переключение источника должно сразу подготовить тот же список,
                # который используется после ручного Enter/автопоиска.
                try {
                    $titleResults.BeginUpdate()
                    $titleResults.Items.Clear()
                    foreach($key in $mapNames){ [void]$titleResults.Items.Add([string]$key) }
                    & $resizeEditorTitleResults
                } finally {
                    try { $titleResults.EndUpdate() } catch {}
                }
                $titleResults.SelectedIndex=-1
            }

            $txtTitle.Text=[string]$chosen.Name
            $editorState.AutoTitle=[string]$chosen.Name
            $txtTitle.SelectionStart=$txtTitle.Text.Length
            $txtId.Text=[string]$chosenId

            if([int]$editorState.SwitchSerial -ne $serial){ return }

            # Ключевой момент: оба источника запускают свои собственные
            # загрузчики. После возврата с SGDB Steam снова проходит именно
            # Load-EditorSteamPreviews, а SGDB — только Load-EditorSgdbPreviews.
            # Оба загрузчика прерываются кликом по другому источнику.
            if($newSource -eq 'Steam'){
                Load-EditorSteamPreviews ([string]$chosenId) $slots $status
            } else {
                [void](Load-EditorSgdbPreviews -gameName $txtTitle.Text.Trim() -steamAppId '' -slots $slots -statusLabel $status -sgdbGameId $chosenId)
            }
        }
        catch {
            if([int]$editorState.SwitchSerial -eq $serial){
                foreach($sl in $slots.Values){ try { Set-EditorPreviewFile $sl $null | Out-Null } catch {} }
                $status.Text=(T 'st_src_error' @($newSource, [string]$_.Exception.Message))
            }
        }
        finally {
            if([int]$editorState.SwitchSerial -eq $serial){
                & $updateSearchSourceUi
                $btnAdd.Enabled=$true
                Set-ConfidenceBadge $titleConfidenceBadge ($txtId.Text.Trim() -match '^\d+$') (T 'badge_title_ok') (T 'badge_title_fail_src')
            }
        }
        } finally {
            $editorState.OpDepth = [Math]::Max(0, [int]$editorState.OpDepth - 1)
            # Если во время этого переключения пользователь уже выбрал другой
            # источник, а загрузчик не успел выполнить отложенное действие —
            # выполняем его здесь.
            Invoke-EditorPendingSwitch
        }
    }

    # Клик по кнопке источника переключает его на противоположный.
    $searchSourceBtn.Add_Click({
        $nextSource = $(if($editorState.SearchSource -eq 'Steam'){ 'SteamGridDB' } else { 'Steam' })
        & $switchSearchSource $nextSource
    })

    # ВАЖНО: $exeCandidates раньше был обычным PS-массивом, и добавление через
    # "$exeCandidates += $x" создавало НОВЫЙ объект массива и переприсваивало
    # переменную. Разные обработчики событий (Add_Click, SelectedIndexChanged,
    # кнопка "Сохранить" и т.д.) замыкают СВОИ копии этой переменной на момент
    # создания диалога, поэтому переприсваивание в одном обработчике не было
    # видно остальным — новый EXE попадал в cmbExe.Items (это общий .NET-объект),
    # но не попадал в "чужие" копии $exeCandidates, из-за чего индекс/выбор/сохранение
    # расходились с реальным списком. List[object] мутируется на месте через
    # .Add(), а не переприсваивается, поэтому все обработчики видят один и тот
    # же объект и одни и те же добавленные элементы.
    [System.Collections.Generic.List[object]]$exeCandidates = New-Object System.Collections.Generic.List[object]
    $exeDisplay = New-Object System.Collections.Generic.List[object]
    $selectEditorExe = { param($index) }

    if (-not $IsRomEntry) {
    $exeCandidates = @(Get-EditorExecutableCandidates $gamePath)
    # Путь выбранного сейчас EXE — для автоматического варианта в окне выбора иконок.
    # Замыкание создаётся после переприсваивания списка; дальше он только дополняется через .Add().
    try {
        $exeResolverBlock = {
            $res = New-Object System.Collections.Generic.List[string]
            try {
                $ix = [int]$cmbExe.SelectedIndex
                if ($ix -ge 0 -and $ix -lt $exeCandidates.Count) {
                    $res.Add([string]$exeCandidates[$ix].FullName)
                } else {
                    # EXE ещё не выбран (несколько кандидатов) — предлагаем иконки всех найденных.
                    for ($ci = 0; $ci -lt [Math]::Min(6, $exeCandidates.Count); $ci++) { $res.Add([string]$exeCandidates[$ci].FullName) }
                }
            } catch {}
            return ,$res.ToArray()
        }.GetNewClosure()
        $editorState | Add-Member -NotePropertyName ExePathResolver -NotePropertyValue $exeResolverBlock -Force
    } catch {}
    $cmbExe.Items.Clear()
    for($i=0; $i -lt $exeCandidates.Count; $i++) {
        $exe = $exeCandidates[$i]
        if($null -eq $exe){ continue }
        $rel = [string]$exe.FullName
        try {
            if($exe.FullName.StartsWith($gamePath, [System.StringComparison]::OrdinalIgnoreCase)) {
                $rel = $exe.FullName.Substring($gamePath.Length).TrimStart('\')
            } else { $rel = [System.IO.Path]::GetFileName($exe.FullName) }
        } catch {}
        $ico = $null
        try { $ico=[System.Drawing.Icon]::ExtractAssociatedIcon($exe.FullName) } catch {}
        $entry=[PSCustomObject]@{ Text=$rel; Image=$ico }
        [void]$exeDisplay.Add($entry)
        [void]$cmbExe.Items.Add($rel)
    }
    if($editMode -and $existingShortcut -ne $null){
        $existingExePath=[string]$existingShortcut.Exe
        $existingLaunchOptions=[string]$existingShortcut.LaunchOptions
        if($existingLaunchOptions){$txtLaunchOptions.Text=$existingLaunchOptions}
        if($existingExePath -and (Test-Path $existingExePath)){
            $existingExeItem=Get-Item -LiteralPath $existingExePath -ErrorAction SilentlyContinue
            if($existingExeItem -ne $null){
                $foundExistingIndex=-1
                for($i=0;$i -lt $exeCandidates.Count;$i++){
                    try{if([string]::Equals([string]$exeCandidates[$i].FullName,[string]$existingExeItem.FullName,[System.StringComparison]::OrdinalIgnoreCase)){$foundExistingIndex=$i;break}}catch{}
                }
                if($foundExistingIndex -lt 0){
                    $exeCandidates.Add($existingExeItem)
                    $relExisting=[string]$existingExeItem.FullName
                    try{if($existingExeItem.FullName.StartsWith($gamePath,[System.StringComparison]::OrdinalIgnoreCase)){$relExisting=$existingExeItem.FullName.Substring($gamePath.Length).TrimStart('\')}}catch{}
                    $icoExisting=$null; try{$icoExisting=[System.Drawing.Icon]::ExtractAssociatedIcon($existingExeItem.FullName)}catch{}
                    [void]$exeDisplay.Add([PSCustomObject]@{Text=$relExisting;Image=$icoExisting})
                    [void]$cmbExe.Items.Add($relExisting)
                    $foundExistingIndex=$exeCandidates.Count-1
                }
                try{$global:exeSelectionCache[$gamePath.ToUpper()]=[string]$existingExeItem.FullName}catch{}
            }
        }
    }

    # Игра из лаунчера: exe, указанный самим лаунчером, всегда есть в списке (даже если он
    # отфильтрован как служебный файл или лаунчер-заглушка), чтобы его можно было предвыбрать.
    if (Test-IsLauncherEntry $LauncherEntry) {
        $mfExe = Get-LauncherManifestExe $LauncherEntry
        if ($null -ne $mfExe) {
            $mfFound = $false
            for($i=0;$i -lt $exeCandidates.Count;$i++){
                try{if([string]::Equals([string]$exeCandidates[$i].FullName,[string]$mfExe.FullName,[System.StringComparison]::OrdinalIgnoreCase)){$mfFound=$true;break}}catch{}
            }
            if(-not $mfFound){
                $exeCandidates.Add($mfExe)
                $relMf=[string]$mfExe.FullName
                try{if($mfExe.FullName.StartsWith($gamePath,[System.StringComparison]::OrdinalIgnoreCase)){$relMf=$mfExe.FullName.Substring($gamePath.Length).TrimStart('\')}}catch{}
                $icoMf=$null; try{$icoMf=[System.Drawing.Icon]::ExtractAssociatedIcon($mfExe.FullName)}catch{}
                [void]$exeDisplay.Add([PSCustomObject]@{Text=$relMf;Image=$icoMf})
                [void]$cmbExe.Items.Add($relMf)
            }
        }
    }

    $cmbExe.Tag = $exeDisplay.ToArray()
    $cmbExe.DropDownHeight = 128
    $cmbExe.IntegralHeight = $false

    $selectEditorExe = {
        param($index)
        if($index -lt 0 -or $index -ge $exeCandidates.Count -or $cmbExe.Items.Count -eq 0){ return }
        $cmbExe.SelectedIndex = $index
        try { $status.Text = (T 'st_exe_selected' @([string]$cmbExe.Items[$index])) } catch {}
    }

    if($cmbExe.Items.Count -gt 0){
        $cacheKey = $gamePath.ToUpper()
        $cached = $null
        try { if($global:exeSelectionCache.ContainsKey($cacheKey)){ $cached=[string]$global:exeSelectionCache[$cacheKey] } } catch {}
        $idx = -1
        # Кэш выбора живёт до перезапуска программы и не знает, что ярлык уже
        # удалили из Steam. Для одиночной карточки он засчитывается, только если
        # игра сейчас есть в Steam (тогда выбор всё равно берётся из ярлыка ниже).
        if($cached -and -not $batchMode -and $existingShortcut -eq $null){ $cached = $null }
        if($cached){
            for($i=0; $i -lt $exeCandidates.Count; $i++){
                try {
                    if([string]::Equals([string]$exeCandidates[$i].FullName,$cached,[System.StringComparison]::OrdinalIgnoreCase)){ $idx=$i; break }
                } catch {}
            }
        }
        if($editMode -and $existingShortcut -ne $null -and $existingShortcut.Exe){
            for($i=0;$i -lt $exeCandidates.Count;$i++){
                try{if([string]::Equals([string]$exeCandidates[$i].FullName,[string]$existingShortcut.Exe,[System.StringComparison]::OrdinalIgnoreCase)){$idx=$i;break}}catch{}
            }
        }
        # Уверенность фиксируем ДО подстановки запасного индекса 0: если ни кэш,
        # ни уже сохранённый ярлык не дали совпадения среди нескольких
        # кандидатов, это угадывание, а не определённый выбор.
        # Игра из лаунчера без явного выбора пользователя: берём exe из манифеста лаунчера.
        $launcherChoice = $null
        if($idx -lt 0 -and (Test-IsLauncherEntry $LauncherEntry)){
            $launcherChoice = Resolve-LauncherExeChoice $LauncherEntry $exeCandidates
            if($launcherChoice.Index -ge 0){ $idx = $launcherChoice.Index }
        }
        $exeConfidentInitial = ($idx -ge 0) -or ($exeCandidates.Count -le 1)
        # Запуск через SCLauncher.exe: выбор файла на запуск не влияет — поле всегда определено.
        $exeViaWrapper = (-not $IsRomEntry) -and (-not $editMode) -and (Test-LauncherEntryWrapped $LauncherEntry)
        if($exeViaWrapper){ $exeConfidentInitial = $true }
        $editorState.ExeConfirmed = $exeConfidentInitial
        if($idx -lt 0){ $idx=0 }
        $exeProgrammaticSelect = $true
        try { & $selectEditorExe $idx } finally { $exeProgrammaticSelect = $false }
        if($exeViaWrapper){
            Set-ConfidenceBadge $exeConfidenceBadge $true (T 'badge_exe_wrapped') ''
        } elseif($null -ne $launcherChoice -and $launcherChoice.Source -eq 'manifest'){
            Set-ConfidenceBadge $exeConfidenceBadge $true (T 'badge_exe_launcher') ''
        } else {
            Set-ConfidenceBadge $exeConfidenceBadge $exeConfidentInitial (T 'badge_exe_ok') (T 'badge_exe_multi')
        }
    } elseif((-not $IsRomEntry) -and (-not $editMode) -and (Test-LauncherEntryWrapped $LauncherEntry)){
        # Через SCLauncher.exe файл не нужен: рабочей папкой станет папка игры.
        $editorState.ExeConfirmed = $true
        Set-ConfidenceBadge $exeConfidenceBadge $true (T 'badge_exe_wrapped') ''
    } else {
        $status.Text=(T 'st_no_exe')
        Set-ConfidenceBadge $exeConfidenceBadge $false (T 'badge_exe_ok') (T 'badge_exe_none')
    }
    # Лицензионная игра: EXE только для просмотра, поэтому зелёная отметка
    # сразу при открытии карточки. ExeConfirmed не трогаем — подсказка Steam
    # по-прежнему сможет выбрать нужный файл в списке.
    if ($licensedMode) {
        Set-ConfidenceBadge $exeConfidenceBadge $true (T 'lib_licensed_hint') ''
    }

    } else {
        # Режим ROMs: вместо сканирования EXE-файлов в папке — выбор эмулятора
        # из уже настроенного списка и подстановка шаблона его аргументов.
        if ($emuProfiles.Count -eq 0) {
            $status.Text = (T 'st_no_exe')
            & $populateRomCandidates ''
        } else {
            $defaultIdx = -1
            # Ярлык ROM из архива через SCLauncher.exe: настоящие эмулятор/ядро/архив/файл лежат в его параметрах.
            $savedRomWrap = $null
            $existingEmuExe = ''
            if ($editMode -and $existingShortcut -ne $null) {
                $existingEmuExe = [string]$existingShortcut.Exe
                $swo = [string]$existingShortcut.LaunchOptions
                $swm = [regex]::Match($swo, '^\s*--rom-archive\s+"(?<a>[^"]+)"\s+--emu\s+"(?<e>[^"]+)"\s+(?:--core\s+"(?<c>[^"]*)"|--args\s+"(?<t>(?:[^"\\]|\\.)*)")')
                if ($swm.Success) {
                    $swEntry = ''
                    $swen = [regex]::Match($swo, '--entry\s+"(?<n>[^"]+)"')
                    if ($swen.Success) { $swEntry = [string]$swen.Groups['n'].Value }
                    # Args заполнен только у ярлыков обычного эмулятора (--args); у RetroArch - $null.
                    $swArgs = $null
                    if ($swm.Groups['t'].Success) { $swArgs = ([string]$swm.Groups['t'].Value).Replace('\"', '"') }
                    $savedRomWrap = [PSCustomObject]@{ Archive = [string]$swm.Groups['a'].Value; Emu = [string]$swm.Groups['e'].Value; Core = [string]$swm.Groups['c'].Value; Entry = $swEntry; Args = $swArgs }
                    $existingEmuExe = [string]$savedRomWrap.Emu
                }
            }
            if ($editMode -and $existingShortcut -ne $null -and $existingEmuExe) {
                for ($i=0; $i -lt $emuProfiles.Count; $i++) {
                    try { if ([string]::Equals([string]$emuProfiles[$i].ExePath, $existingEmuExe, [System.StringComparison]::OrdinalIgnoreCase)) { $defaultIdx = $i; break } } catch {}
                }
            }
            if ($defaultIdx -lt 0) {
                $active = Get-ActiveEmulatorProfile
                if ($active -ne $null) {
                    for ($i=0; $i -lt $emuProfiles.Count; $i++) {
                        if ([string]$emuProfiles[$i].Id -eq [string]$active.Id) { $defaultIdx = $i; break }
                    }
                }
            }
            if ($defaultIdx -lt 0) { $defaultIdx = 0 }

            $emuProgrammaticSelect = $true
            try { $cmbEmulator.SelectedIndex = $defaultIdx } finally { $emuProgrammaticSelect = $false }

            # Поле "Ядро" (если это RetroArch) — сразу видимо/заполнено, по
            # умолчанию ядром, сохранённым в самом профиле эмулятора; ниже,
            # если у ярлыка уже есть сохранённые параметры запуска, выбор
            # переопределяется тем ядром, которое реально в них упомянуто.
            & $updateGameCoreVisibility $true

            # Список кандидатов в ROM строится расширениями эмулятора по
            # умолчанию — до подстановки шаблона аргументов, чтобы в нём уже
            # был выбран правильный файл.
            & $populateRomCandidates ([string]$emuProfiles[$defaultIdx].Extensions) (Test-EmulatorExtractArchives $emuProfiles[$defaultIdx])

            # Существующий сохранённый ярлык уже содержит свои LaunchOptions —
            # их подставляют чуть выше по коду вместе с полем "Параметры" для
            # обычного режима; для ROMs делаем то же самое явно здесь и не
            # перетираем их шаблоном, если они уже есть. Поле "ROM" при этом
            # пытаемся выставить на файл, реально упомянутый в уже сохранённых
            # параметрах запуска.
            if ($null -ne $savedRomWrap) {
                if (-not [string]::IsNullOrEmpty([string]$savedRomWrap.Core)) { try { & $setCoreGameFile ([string]$savedRomWrap.Core) } catch {} }
                for ($i = 0; $i -lt $romCandidates.Count; $i++) {
                    if ([string]::Equals([string]$romCandidates[$i].FullName, [string]$savedRomWrap.Archive, [System.StringComparison]::OrdinalIgnoreCase)) {
                        # Сохранённый файл внутри архива возвращаем в поле "Файл" (если он ещё есть в архиве).
                        $pes = $romCandidates[$i].PSObject.Properties['ArchiveEntries']
                        if ($null -ne $pes -and $null -ne $pes.Value -and -not [string]::IsNullOrEmpty([string]$savedRomWrap.Entry)) {
                            foreach ($ei in @($pes.Value)) {
                                if ([string]::Equals([string]$ei.Path, [string]$savedRomWrap.Entry, [System.StringComparison]::OrdinalIgnoreCase)) { $romCandidates[$i].ArchiveEntry = [string]$ei.Path; break }
                            }
                        }
                        $editorState.RomProgrammaticSelect = $true
                        try { $cmbRom.SelectedIndex = $i } finally { $editorState.RomProgrammaticSelect = $false }
                        & $updateRomEntryList
                        Set-ConfidenceBadge $romConfidenceBadge $true (T 'rom_badge_saved') ''
                        break
                    }
                }
                & $applyEmulatorArgsTemplate $emuProfiles[$defaultIdx] (& $getSelectedRomPath)
                # Обычный эмулятор: возвращаем сохранённые в ярлыке параметры (шаблон --args), а не шаблон профиля.
                if ($null -ne $savedRomWrap.Args) { try { $txtLaunchOptions.Text = Format-EmulatorLaunchArgs ([string]$savedRomWrap.Args) ([string](& $getSelectedRomPath)) } catch {} }
            } elseif ($editMode -and $existingShortcut -ne $null -and $existingShortcut.LaunchOptions) {
                $txtLaunchOptions.Text = [string]$existingShortcut.LaunchOptions
                if ($lblCoreGame.Visible -and [string]$existingShortcut.LaunchOptions -match '(?i)-L\s+"?(?:[^"\\/]*[\\/])*(?<core>[^"\\/]+?)_libretro\.dll') {
                    & $setCoreGameFile ([string]$Matches['core'])
                }
                for ($i = 0; $i -lt $romCandidates.Count; $i++) {
                    if ([string]$existingShortcut.LaunchOptions -match [System.Text.RegularExpressions.Regex]::Escape([string]$romCandidates[$i].FullName)) {
                        $editorState.RomProgrammaticSelect = $true
                        try { $cmbRom.SelectedIndex = $i } finally { $editorState.RomProgrammaticSelect = $false }
                        Set-ConfidenceBadge $romConfidenceBadge $true (T 'rom_badge_saved') ''
                        break
                    }
                }
            } else {
                & $applyEmulatorArgsTemplate $emuProfiles[$defaultIdx] (& $getSelectedRomPath)
            }
            Set-ConfidenceBadge $exeConfidenceBadge $true (T 'badge_exe_ok') ''
        }
    }

    $btnBrowseExe.Add_Click({
        try {
            # Ручной выбор допускает EXE и BAT, но принимать можно только файл
            # из папки самой игры или одной из её подпапок.
            while($true){
                $ofd = New-Object System.Windows.Forms.OpenFileDialog
                $ofd.Title = (T 'ofd_title')
                $ofd.Filter = (T 'ofd_filter')
                $ofd.CheckFileExists = $true
                $ofd.Multiselect = $false
                try {
                    if($cmbExe.SelectedIndex -ge 0){
                        $selectedExe=$exeCandidates[$cmbExe.SelectedIndex]
                        if($selectedExe -and (Test-Path $selectedExe.FullName)){ $ofd.InitialDirectory=$selectedExe.DirectoryName }
                    } elseif(Test-Path $gamePath) { $ofd.InitialDirectory=$gamePath }
                } catch {}

                if($ofd.ShowDialog($dlg) -ne [System.Windows.Forms.DialogResult]::OK){ break }
                $chosenExe=Get-Item -LiteralPath $ofd.FileName -ErrorAction SilentlyContinue
                if($chosenExe -eq $null){ break }

                if(-not (Test-FileInsideRoot $chosenExe.FullName $gamePath)){
                    Show-AppMessageBox($dlg,
                        ((T 'exe_outside') + "`r`n`r`n" + [string]$gamePath),
                        (T 'exe_outside_title'),
                        [System.Windows.Forms.MessageBoxButtons]::OK,
                        [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                    continue
                }

                $existingIndex=-1
                for($i=0;$i -lt $exeCandidates.Count;$i++){
                    try { if([string]::Equals([string]$exeCandidates[$i].FullName,[string]$chosenExe.FullName,[System.StringComparison]::OrdinalIgnoreCase)){ $existingIndex=$i; break } } catch {}
                }
                if($existingIndex -lt 0){
                    $exeCandidates.Add($chosenExe)
                    $existingIndex=$exeCandidates.Count-1
                    $rel=[string]$chosenExe.FullName
                    try { $rel=$chosenExe.FullName.Substring(([System.IO.Path]::GetFullPath($gamePath)).TrimEnd('\').Length).TrimStart('\') } catch {}
                    $ico = $null
                    try { $ico=[System.Drawing.Icon]::ExtractAssociatedIcon($chosenExe.FullName) } catch {}
                    $entry=[PSCustomObject]@{ Text=$rel; Image=$ico }
                    $exeDisplay.Add($entry)
                    $cmbExe.Tag = $exeDisplay.ToArray()
                    [void]$cmbExe.Items.Add($rel)
                }
                # ВАЖНО: после ручного добавления элемент должен стать выбранным
                # сразу, а не просто появиться в выпадающем списке. В некоторых
                # случаях OwnerDraw ComboBox после Items.Add сохраняет старый
                # SelectedIndex, поэтому задаём выбор повторно и через SelectedItem.
                try {
                    $cmbExe.SelectedIndex = -1
                    $cmbExe.SelectedIndex = $existingIndex
                    if ($existingIndex -ge 0 -and $existingIndex -lt $cmbExe.Items.Count) {
                        $cmbExe.SelectedItem = $cmbExe.Items[$existingIndex]
                    }
                    $cmbExe.Refresh()
                } catch {}
                & $selectEditorExe $existingIndex
                try {
                    $global:exeSelectionCache[$gamePath.ToUpper()]=[string]$chosenExe.FullName
                } catch {}
                break
            }
        } catch {}
    })

    # Название — отдельный TextBox. Варианты получаем в отдельном ComboBox-popup.
    # Нативный WinForms AutoComplete здесь намеренно отключён:
    # при динамической замене Items он может одновременно держать свой
    # внутренний список и вызывать DropDown/WM_NOTIFY. Это и было причиной
    # вылета при ручной правке названия.
    $txtTitle.Tag=[PSCustomObject]@{Busy=$false;Map=@{};RefreshNeeded=$true;SuppressAutoSearch=$false;SearchTimer=$null}

    function Update-EditorTitleCandidates {
        try {
            $tag=$txtTitle.Tag
            if($null -eq $tag -or $tag.Busy){return $false}

            $query=([string]$txtTitle.Text).Trim()
            if($query.Length -lt 2){
                try { $titleResults.Items.Clear() } catch {}
                return $false
            }

            if(-not $tag.RefreshNeeded -and $titleResults.Items.Count -gt 0){return $true}

            $tag.Busy=$true
            try {
                if($editorState.SearchSource -eq 'Steam') {
                    # Собственный поиск вариантов Steam — без SGDB и без ключа.
                    # Каждый вариант уже несёт настоящий Steam App ID, который
                    # используется напрямую при выборе варианта из списка.
                    $candidates=@(Get-SteamStoreNameCandidates $query)
                } else {
                    $candidates=@(Get-EditorSgdbCandidates $query $txtId.Text.Trim())
                }

                # Пока шёл поиск (он прокачивает сообщения окна), пользователь мог
                # продолжить набор — тогда этот результат уже устарел: не
                # показываем его, а сразу перезапускаем поиск по актуальному тексту.
                if((([string]$txtTitle.Text).Trim()) -ne $query){
                    $tag.RefreshNeeded=$true
                    try { $tag.SearchTimer.Stop(); $tag.SearchTimer.Start() } catch {}
                    return $false
                }

                # Одноимённые варианты (разные App ID) больше не схлопываются в
                # один пункт списка — см. New-EditorTitleCandidateMap.
                $mapInfo=New-EditorTitleCandidateMap $candidates
                $newMap=$mapInfo.Map
                $names=$mapInfo.Names

                # Это отдельный TextBox, поэтому обновление Items списка
                # НИКОГДА не должно переписывать Text. Раньше здесь использовался
                # .Trim() -> возврат строки в Text, из-за чего введённый пробел
                # в конце названия сразу исчезал.
                $tag.SuppressAutoSearch=$true
                try {
                    try { $titleResults.Visible=$false } catch {}

                    $titleResults.BeginUpdate()
                    try {
                        $titleResults.Items.Clear()
                        foreach($nm in $names){ [void]$titleResults.Items.Add($nm) }
                        & $resizeEditorTitleResults
                    } finally {
                        $titleResults.EndUpdate()
                    }
                    $titleResults.SelectedIndex=-1
                    $titleResults.Visible=$false
                } finally {
                    $tag.SuppressAutoSearch=$false
                }

                $tag.Map=$newMap
                $tag.RefreshNeeded=$false
                return ($names.Count -gt 0)
            } finally {
                $tag.Busy=$false
            }
        } catch {
            try { $titleResults.EndUpdate() } catch {}
            try { $txtTitle.Tag.Busy=$false } catch {}
            return $false
        }
    }

    # Поиск запускается с небольшой задержкой после окончания ввода.
    # Это даёт Steam Store-поиску работать как автоподсказки, но без сетевого
    # запроса на каждый символ и без реэнтерантного DropDown-события.
    $titleSearchTimer=New-Object System.Windows.Forms.Timer
    $titleSearchTimer.Interval=350
    $titleSearchTimer.Add_Tick({
        try {
            try { $txtTitle.Tag.SearchTimer.Stop() } catch {}
            $tag=$txtTitle.Tag
            if($null -eq $tag -or $tag.Busy -or $tag.SuppressAutoSearch){return}
            $query=([string]$txtTitle.Text).Trim()
            if($query.Length -lt 2){return}

            $hasItems=Update-EditorTitleCandidates
            if($hasItems -and $txtTitle.Focused -and $titleResults.Items.Count -gt 0){
                try { & $openEditorTitleDropDown } catch {}
            }
        } catch {
            try { $txtTitle.Tag.SearchTimer.Stop() } catch {}
        }
    })
    $txtTitle.Tag.SearchTimer=$titleSearchTimer

    $queueEditorTitleSearch={
        try {
            $tag=$txtTitle.Tag
            if($null -eq $tag -or $tag.Busy -or $tag.SuppressAutoSearch){return}
            $tag.RefreshNeeded=$true
            $timer=$tag.SearchTimer
            if($null -eq $timer){ return }
            $timer.Stop()
            $timer.Start()
        } catch {}
    }

    # Открываем список НЕ внутри KeyDown/Timer-события, а через очередь UI.
    # WinForms ComboBox иногда игнорирует DroppedDown=$true, пока ещё
    # обрабатывает Enter/WM_KEYDOWN. BeginInvoke гарантирует, что список
    # раскроется уже после завершения текущего события.
    $openEditorTitleDropDown = {
        try {
            $tag=$txtTitle.Tag
            if($null -eq $tag -or $tag.Busy -or $tag.SuppressAutoSearch){ return }
            if($titleResults.Items.Count -le 0 -or -not $txtTitle.Focused){ return }
            $titleResults.SelectedIndex=-1
            $titleResults.Visible=$true
            $titleResults.BringToFront()
            # Открываем список результатов поверх остальных контролов формы. TextBox остаётся
            # отдельным полем ввода и поэтому его Text никогда не меняется от
            # обновления Items.
        } catch {}
    }

    # Закрытие списка возвращает фокус в поле названия (Focus()). Это вызывает
    # GotFocus, который теперь сам открывает подсказки, — на время возврата фокуса
    # обработчик отключаем, иначе после выбора варианта/Esc список открывался бы снова.
    $titleFocusState=@{Skip=$false}

    $closeEditorTitleDropDown = {
        try {
            $titleFocusState.Skip=$true
            $titleResults.Visible=$false; $titleResults.SelectedIndex=-1; $txtTitle.Focus()
        } catch {
        } finally { $titleFocusState.Skip=$false }
    }


    # Выбор результата — единственная операция, которая имеет право менять
    # название и ID. Сам поиск, обновление списка и набор текста этого не делают.
    $commitEditorTitleResult = {
        try {
            $tag=$txtTitle.Tag
            if($null -eq $tag -or $tag.Busy){return}
            $nm=[string]$titleResults.SelectedItem
            if([string]::IsNullOrWhiteSpace($nm)){return}
            if($null -eq $tag.Map -or -not $tag.Map.ContainsKey($nm)){return}

            $choice=$tag.Map[$nm]

            try { $tag.SearchTimer.Stop() } catch {}
            $tag.Busy=$true
            $tag.SuppressAutoSearch=$true
            try {
                & $closeEditorTitleDropDown
                # Текст выбранного SGDB-варианта становится новым точным названием.
                # При источнике Steam SGDB-ID НЕ записываем в поле App ID: вместо
                # этого по полному названию ищем соответствующую игру в Steam.
                $txtTitle.Text=[string]$choice.Name
                $editorState.OriginalTitle=[string]$choice.Name
                $editorState.AutoTitle=''
                $txtTitle.SelectionStart=$txtTitle.Text.Length
                $txtTitle.SelectionLength=0
                $tag.RefreshNeeded=$false
            } finally {
                $tag.SuppressAutoSearch=$false
                $tag.Busy=$false
            }

            # Переключатели источника не блокируем: клик по ним прервёт эту загрузку.
            $btnAdd.Enabled=$false
            $editorState.OpDepth = [int]$editorState.OpDepth + 1
            try {
                if($editorState.SearchSource -eq 'Steam') {
                    # Выбранный вариант уже несёт настоящий Steam App ID (из
                    # собственного поиска Steam) — повторный поиск не нужен.
                    $steamChosenId=0
                    try { $steamChosenId=[int]$choice.Id } catch { $steamChosenId=0 }
                    if($steamChosenId -gt 0){
                        $txtId.Text=[string]$steamChosenId
                        # После выбора варианта название — по региону из «Настроек».
                        $localizedChoiceName = Get-SteamLocalizedAppName ([string]$steamChosenId) ([string](Get-SteamAssetLanguage))
                        if(-not [string]::IsNullOrWhiteSpace([string]$localizedChoiceName)){
                            $tag.SuppressAutoSearch=$true
                            try {
                                $txtTitle.Text=[string]$localizedChoiceName
                                $editorState.AutoTitle=[string]$localizedChoiceName
                                $txtTitle.SelectionStart=$txtTitle.Text.Length
                                $txtTitle.SelectionLength=0
                            } finally {
                                $tag.SuppressAutoSearch=$false
                            }
                        }
                        if (Test-EditorLoadCancelled) { return }
                        Load-EditorSteamPreviews ([string]$steamChosenId) $slots $status
                        & $tryApplySteamExeHint ([string]$steamChosenId)
                    } else {
                        $txtId.Text=''
                        foreach($sl in $slots.Values){ try { Set-EditorPreviewFile $sl $null | Out-Null } catch {} }
                        $status.Text=(T 'st_pick_noid_steam')
                    }
                } else {
                    $chosenId=0
                    try { $chosenId=[int]$choice.Id } catch {}
                    if($chosenId -le 0){ throw (T 'err_pick_noid_sgdb') }
                    $txtId.Text=[string]$chosenId
                    [void](Load-EditorSgdbPreviews -gameName $txtTitle.Text.Trim() -steamAppId '' -slots $slots -statusLabel $status -sgdbGameId $chosenId)
                }
            } catch {
                $status.Text=$editorState.SearchSource+': '+[string]$_.Exception.Message
            } finally {
                & $updateSearchSourceUi
                $btnAdd.Enabled=$true
                Set-ConfidenceBadge $titleConfidenceBadge ($txtId.Text.Trim() -match '^\d+$') (T 'badge_title_ok') (T 'badge_title_fail_pick')
                $editorState.OpDepth = [Math]::Max(0, [int]$editorState.OpDepth - 1)
                Invoke-EditorPendingSwitch
            }
        } catch {}
    }

    $txtTitle.Add_TextChanged({
        try {
            $tag=$txtTitle.Tag
            if($tag -ne $null -and -not $tag.Busy -and -not $tag.SuppressAutoSearch){
                & $queueEditorTitleSearch
                # Ручная правка текста делает прежнее подтверждение неактуальным,
                # пока новый поиск/выбор его не подтвердит заново.
                Set-ConfidenceBadge $titleConfidenceBadge $false (T 'badge_title_ok') (T 'badge_title_manual')
            }
        } catch {}
    })


    # Подсказки появляются сразу, как только курсор встал в поле названия (по
    # фокусу или по клику в уже сфокусированное поле) — ещё до начала набора.
    # Поиск идёт через тот же отложенный таймер, что и при наборе: на фокусе
    # сетевой запрос не блокирует UI. Если список для текущего текста уже
    # загружен, таймер просто раскроет его без повторного запроса.
    $showEditorTitleSuggestionsOnEnter = {
        try {
            if($titleFocusState.Skip){ return }
            $tag=$txtTitle.Tag
            if($null -eq $tag -or $tag.Busy -or $tag.SuppressAutoSearch){ return }
            if($titleResults.Visible){ return }
            if(([string]$txtTitle.Text).Trim().Length -lt 2){ return }
            $timer=$tag.SearchTimer
            if($null -eq $timer){ return }
            $timer.Stop()
            $timer.Start()
        } catch {}
    }
    # GotFocus не раскрывает список: после возврата фокуса из окна выбора
    # обложки поле получает фокус автоматически, но это не является кликом
    # пользователя по полю. Открытие выполняется только через Click.
    $txtTitle.Add_Click({
        if($licensedMode){ return }
        if($editorState.SuppressTitleSuggestionOnce){ $editorState.SuppressTitleSuggestionOnce=$false; return }
        $editorState.LastSuggestionField='title'
        & $showEditorTitleSuggestionsOnEnter
    })

    $titleResults.Add_MouseClick({ & $commitEditorTitleResult })
    $titleResults.Add_KeyDown({
        if($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter){ $_.SuppressKeyPress=$true; & $commitEditorTitleResult }
        elseif($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape){ $_.SuppressKeyPress=$true; & $closeEditorTitleDropDown; $txtTitle.Focus() }
    })

    $txtTitle.Add_KeyDown({
        if($_.KeyCode -eq [System.Windows.Forms.Keys]::Down -and $titleResults.Visible -and $titleResults.Items.Count -gt 0){
            $_.SuppressKeyPress=$true
            $titleResults.SelectedIndex=0
            $titleResults.Focus()
            return
        }
        if($_.KeyCode -ne [System.Windows.Forms.Keys]::Enter){
            try { & $queueEditorTitleSearch } catch {}
            return
        }
        $_.SuppressKeyPress=$true
        $name=$txtTitle.Text.Trim()
        if([string]::IsNullOrWhiteSpace($name)){return}
        try { $txtTitle.Tag.SearchTimer.Stop() } catch {}
        try { & $closeEditorTitleDropDown } catch {}
        $txtTitle.Focus()

        if($editorState.SearchSource -eq 'Steam') {
            # Enter в поле «Название» должен повторно искать игру в Steam по
            # введённому тексту — точно так же, как при открытии карточки —
            # а не просто обновлять список подсказок SGDB. Раньше Enter вызывал
            # только Update-EditorTitleCandidates: если список подсказок уже
            # был открыт с теми же вариантами (например, при том же названии),
            # видимых изменений не происходило и казалось, что Enter не работает.
            # Переключатели источника не блокируем: клик по ним прервёт этот поиск.
            $btnAdd.Enabled=$false
            $editorState.OpDepth = [int]$editorState.OpDepth + 1
            $status.Text=(T 'st_searching_name_steam' @($name))
            [System.Windows.Forms.Application]::DoEvents()
            try {
                $steamFound=$null
                try { $steamFound=Find-SteamAppInfo $name } catch { $steamFound=$null }
                if (Test-EditorLoadCancelled) { return }
                if($steamFound -ne $null){
                    $txtId.Text=[string]$steamFound.Id
                    if(-not [string]::IsNullOrWhiteSpace([string]$steamFound.Name)){
                        $tag=$txtTitle.Tag
                        if($tag -ne $null){ $tag.SuppressAutoSearch=$true }
                        try {
                            $editorState.OriginalTitle=[string]$name
                            $editorState.AutoTitle=[string]$steamFound.Name
                            $txtTitle.Text=[string]$steamFound.Name
                            $txtTitle.SelectionStart=$txtTitle.Text.Length
                            $txtTitle.SelectionLength=0
                        } finally {
                            if($tag -ne $null){ $tag.SuppressAutoSearch=$false }
                        }
                    }
                    try { $txtTitle.Tag.RefreshNeeded=$true } catch {}
                    Load-EditorSteamPreviews ([string]$steamFound.Id) $slots $status
                    & $tryApplySteamExeHint ([string]$steamFound.Id)
                } else {
                    $txtId.Text=''
                    foreach($sl in $slots.Values){ try { Set-EditorPreviewFile $sl $null | Out-Null } catch {} }
                    $status.Text=(T 'st_game_notfound_steam' @($name))
                }
            } catch {
                $status.Text='Steam: '+[string]$_.Exception.Message
            } finally {
                if ($IsRomEntry) { $searchSourceBtn.Visible=$false }
                $btnAdd.Enabled=$true
                Set-ConfidenceBadge $titleConfidenceBadge ($txtId.Text.Trim() -match '^\d+$') (T 'badge_title_ok') (T 'badge_title_fail_pick')
                $editorState.OpDepth = [Math]::Max(0, [int]$editorState.OpDepth - 1)
                Invoke-EditorPendingSwitch
            }
            return
        }

        # SteamGridDB: Enter по-прежнему открывает список вариантов названия
        # для ручного выбора конкретного варианта.
        try {
            $txtTitle.Tag.RefreshNeeded=$true
            $hasItems=Update-EditorTitleCandidates
            if($hasItems -and $titleResults.Items.Count -gt 0){
                & $openEditorTitleDropDown
            } else {
                $status.Text = (T 'st_no_variants' @($editorState.SearchSource, $name))
            }
        } catch {}
    })

    # Enter в ID обновляет выбранный источник.
    $txtId.Add_KeyDown({
        if($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter){
            $_.SuppressKeyPress=$true
            if($txtId.Text.Trim() -match '^\d+$'){
                if($editorState.SearchSource -eq 'Steam') {
                    Load-EditorSteamPreviews $txtId.Text.Trim() $slots $status $licensedMode
                } else {
                    [void](Load-EditorSgdbPreviews -gameName $txtTitle.Text.Trim() -steamAppId '' -slots $slots -statusLabel $status -sgdbGameId ([int]$txtId.Text.Trim()))
                }
                # ID введён пользователем вручную и явно указывает на конкретную
                # игру — это осознанное подтверждение, а не догадка программы.
                Set-ConfidenceBadge $titleConfidenceBadge $true (T 'badge_title_ok') (T 'badge_title_fail_auto')
                if($editorState.SearchSource -eq 'Steam') { & $tryApplySteamExeHint $txtId.Text.Trim() }
            } else {
                $status.Text=if($editorState.SearchSource -eq 'Steam'){(T 'st_id_digits_steam')}else{(T 'st_id_digits_sgdb')}
            }
        }
    })

    # Подсказка exe из Steam: вынесена в переиспользуемый блок, чтобы её можно
    # было применять не только сразу при открытии карточки (когда App ID уже
    # мог быть определён автоматикой), но и после ЛЮБОГО последующего
    # подтверждения App ID — например, когда автопоиск названия не сработал
    # (см. исправление Find-SteamAppInfo для случаев вроде "Crash Bandicoot 4"
    # / официального "Crash Bandicoot™ 4: It's About Time"), а пользователь
    # нашёл и подтвердил игру вручную (из списка вариантов, повторным Enter
    # по названию, или вводом App ID напрямую). Раньше в этих случаях exe так
    # и оставался неопределённым (красный "!") до конца работы с карточкой,
    # хотя после подтверждения App ID подсказка от Steam уже могла сработать.
    #
    # Применяется только если выбор exe ещё НЕ подтверждён ($editorState.ExeConfirmed
    # -eq $false) — то есть не перетирает ни кэш/сохранённый ярлык, ни уже
    # сделанный пользователем осознанный выбор.
    $tryApplySteamExeHint = {
        param($appIdForHint)
        try {
            if ($editorState.SearchSource -ne 'Steam') { return }
            if ($editorState.ExeConfirmed) { return }
            if ([string]::IsNullOrWhiteSpace([string]$appIdForHint) -or ([string]$appIdForHint) -notmatch '^\d+$') { return }
            $hintedExe = Get-SteamHintedExecutable $gamePath ([string]$appIdForHint)
            if ($hintedExe -eq $null -and $licensedMode) { $hintedExe = Get-SteamPrimaryExecutable $gamePath ([string]$appIdForHint) }
            if ($hintedExe -eq $null) { return }
            $hintIndex = -1
            for ($hi=0; $hi -lt $exeCandidates.Count; $hi++) {
                try { if ([string]::Equals([string]$exeCandidates[$hi].FullName,[string]$hintedExe.FullName,[System.StringComparison]::OrdinalIgnoreCase)) { $hintIndex=$hi; break } } catch {}
            }
            if ($hintIndex -lt 0) {
                $exeCandidates.Add($hintedExe)
                $hintIndex = $exeCandidates.Count-1
                $relHint = [string]$hintedExe.FullName
                try { if ($hintedExe.FullName.StartsWith($gamePath,[System.StringComparison]::OrdinalIgnoreCase)) { $relHint = $hintedExe.FullName.Substring($gamePath.Length).TrimStart('\') } } catch {}
                $icoHint = $null
                try { $icoHint=[System.Drawing.Icon]::ExtractAssociatedIcon($hintedExe.FullName) } catch {}
                $exeDisplay.Add([PSCustomObject]@{ Text=$relHint; Image=$icoHint })
                $cmbExe.Tag = $exeDisplay.ToArray()
                [void]$cmbExe.Items.Add($relHint)
            }
            $exeProgrammaticSelect = $true
            try {
                $cmbExe.SelectedIndex = -1
                $cmbExe.SelectedIndex = $hintIndex
                $cmbExe.Refresh()
            } finally { $exeProgrammaticSelect = $false }
            $editorState.ExeConfirmed = $true
            Set-ConfidenceBadge $exeConfidenceBadge $true (T 'badge_exe_steam') ''
        } catch {}
    }

    $dlg.Add_Shown({
        # Пока идёт начальное определение App ID и загрузка обложек, клик по
        # переключателю источника не блокируется: он прерывает эту загрузку, а
        # новая запускается в finally ниже (см. $switchSearchSource).
        $editorState.OpDepth = [int]$editorState.OpDepth + 1
        try {
        # Каждая карточка начинает с чистых временных обложек (см. Clear-TempCoverFiles).
        # В режиме редактирования Copy-ExistingShortcutCoversToTemp ниже всё равно
        # перезапишет их обложками существующего ярлыка.
        Clear-TempCoverFiles
        $status.Text=if($editorState.SearchSource -eq 'Steam'){(T 'st_resolving_steam')}else{(T 'st_resolving_sgdb')}
        # Анимацию включаем сразу при открытии карточки: определение App ID —
        # тоже часть пути к миниатюрам, и до конца этого пути слот показывает
        # спиннер, а не крест. Крест появится только в ветке "App ID не
        # определён" — то есть когда источника обложек реально нет.
        #
        # До первого DoEvents принудительно отдаём фокус безопасному невидимому
        # sink-контролу. Иначе WinForms успевает сфокусировать txtTitle и показать
        # выделение текста прямо во время начальной загрузки.
        try {
            $dlg.ActiveControl = $editorFocusSink
            $editorFocusSink.Focus() | Out-Null
            $txtTitle.SelectionLength=0
            $txtId.SelectionLength=0
            $txtLaunchOptions.SelectionLength=0
        } catch {}
        Start-EditorLoading $slots $dlg
        [System.Windows.Forms.Application]::DoEvents()
        # Начальное автозаполнение карточки не должно считаться ручным
        # редактированием. Иначе TextChanged после установки найденного имени
        # ставит таймер поиска, а тот через 350 мс раскрывает список сам по себе.
        # Особенно заметно это на играх, для которых SGDB возвращает варианты.
        $initialTag=$txtTitle.Tag
        if($null -ne $initialTag){ $initialTag.SuppressAutoSearch=$true }
        $found = $null
        $candidates = @()
        try {
            # ROM-карточка никогда не переключается на Steam: при открытии
            # название и обложки определяются только через SteamGridDB.
            if ($IsRomEntry) { $editorState.SearchSource = 'SteamGridDB' }
            if($editorState.SearchSource -eq 'Steam') {
                if ($licensedMode -and ($licensedAppId -match '^\d+$')) {
                    $found = [PSCustomObject]@{ Id = $licensedAppId; Name = $gameName }
                } elseif($editMode -and $existingShortcut -ne $null) {
                    # Для уже добавленной игры сначала пробуем имя папки, затем
                    # AppName shortcut'а и только потом отображаемое имя карточки.
                    # Это позволяет автоматически получить App ID даже если
                    # пользователь ранее сохранил локализованное название.
                    $found = Find-ExistingGameSteamAppInfo $txtTitle.Text.Trim() $gamePath $existingShortcut
                } else {
                    $found = Find-SteamAppInfo $txtTitle.Text.Trim()
                }
                if($found -ne $null){
                    $txtId.Text=[string]$found.Id
                    # Официальное название: сначала store API по региону из «Настроек»,
                    # иначе english, иначе имя из поиска/локальной базы (часто полнее папки).
                    $localizedName = Get-SteamLocalizedAppName ([string]$found.Id) ([string](Get-SteamAssetLanguage))
                    if ([string]::IsNullOrWhiteSpace([string]$localizedName) -and -not [string]::IsNullOrWhiteSpace([string]$found.Name)) {
                        $localizedName = [string]$found.Name
                    }
                    if(-not [string]::IsNullOrWhiteSpace([string]$localizedName)) {
                        $txtTitle.Text=[string]$localizedName
                        $editorState.AutoTitle=[string]$localizedName
                        $txtTitle.SelectionStart=$txtTitle.Text.Length
                    }
                }
            } else {
                $candidates=@(Get-EditorSgdbCandidates $txtTitle.Text.Trim() '')
                if(@($candidates).Count -gt 0){
                    $txtId.Text=[string]$candidates[0].Id
                    $txtTitle.Text=[string]$candidates[0].Name
                    $editorState.AutoTitle=[string]$candidates[0].Name
                }
            }
        } catch {} finally {
            if($null -ne $initialTag){
                $initialTag.RefreshNeeded=$true
                $initialTag.SuppressAutoSearch=$false
                try { $initialTag.SearchTimer.Stop() } catch {}
            }
        }
        if($global:editorLoadAbortRequested -or $dlg.IsDisposed -or $dlg.Disposing){ return }
        $titleConfidentInitial = if($editorState.SearchSource -eq 'Steam'){ $found -ne $null } else { (@($candidates).Count -gt 0) }
        Set-ConfidenceBadge $titleConfidenceBadge $titleConfidentInitial (T 'badge_title_ok') (T 'badge_title_fail_auto')
        # Название уже подставлено выше — сразу отдаём кадр UI, не дожидаясь обложек.
        try {
            if (-not [string]::IsNullOrWhiteSpace([string]$txtTitle.Text)) {
                $dlg.Text = (T 'card_title' @($originalCardName))
            }
        } catch {}
        try { [System.Windows.Forms.Application]::DoEvents() } catch {}

        # Кнопки регионов — ДО загрузки обложек (PICS лёгкий и кэшируется).
        # Активна кнопка региона из «Настроек», если он есть у игры; иначе english.
        try {
            if($editorState.SearchSource -eq 'Steam' -and $txtId.Text -match '^\d+$'){
                $availEarly = @(Get-SteamPicsAvailableLanguages $txtId.Text.Trim())
                if ($availEarly.Count -eq 0) { $availEarly = @('english') }
                $preferEarly = [string](Get-SteamAssetLanguage)
                if ($availEarly -contains $preferEarly) { $activeEarly = $preferEarly }
                elseif ($availEarly -contains 'english') { $activeEarly = 'english' }
                else { $activeEarly = [string]$availEarly[0] }
                & $renderCoverLanguages $availEarly $activeEarly
                try { [System.Windows.Forms.Application]::DoEvents() } catch {}
            }
        } catch {}

        # Значок exe определяем ДО загрузки обложек: подсказка Steam нужна
        # только App ID, который уже известен, и не должна ждать миниатюры.
        try { & $tryApplySteamExeHint $txtId.Text.Trim() } catch {}
        try { [System.Windows.Forms.Application]::DoEvents() } catch {}
        if($global:editorLoadAbortRequested -or $dlg.IsDisposed -or $dlg.Disposing){ return }

        $loadedExistingCovers=$false
        if($editMode -and $existingShortcut -ne $null){
            try {
                $loadedExistingCovers=Copy-ExistingShortcutCoversToTemp $existingShortcut
                if($loadedExistingCovers){
                    # Значок источника у уже сохранённых обложек: читаем из
                    # cover_sources\<shortcutId>.json, куда он был записан при
                    # последнем сохранении карточки. Для игр, добавленных ещё
                    # до появления этого файла, метаданных не будет — тогда,
                    # как и раньше, считаем источником Steam (это подавляющее
                    # большинство обложек).
                    $savedSources = Get-CoverSourcesMetadata ([string]$existingShortcut.ShortcutId)
                    $sourceFor = {
                        param($key)
                        if ($null -ne $savedSources -and -not [string]::IsNullOrWhiteSpace([string]$savedSources.$key)) { return [string]$savedSources.$key }
                        return 'Steam'
                    }
                    $vSource = & $sourceFor 'p'
                    $hSource = & $sourceFor 'header'
                    $heroSource = & $sourceFor 'hero'
                    $lSource = & $sourceFor 'logo'

                    if(Set-EditorPreviewFile $slots.Vertical (Join-Path $global:tempCovers 'temp_p.jpg')){ Set-EditorSourceBadge $slots.Vertical $vSource }
                    if(Set-EditorPreviewFile $slots.Horizontal (Join-Path $global:tempCovers 'temp_header.jpg')){ Set-EditorSourceBadge $slots.Horizontal $hSource }
                    if(Set-EditorPreviewFile $slots.Hero (Join-Path $global:tempCovers 'temp_hero.jpg')){ Set-EditorSourceBadge $slots.Hero $heroSource }
                    if(Set-EditorPreviewFile $slots.Logo (Join-Path $global:tempCovers 'temp_logo.png')){ Set-EditorSourceBadge $slots.Logo $lSource }
                    if($null -ne $slots.Icon){
                        # Старый _icon.png из grid часто чёрный (битый ico→png).
                        # Всегда тянем свежую иконку из Steam по App ID.
                        # ROM (и любая карточка с источником SteamGridDB): в поле ID стоит SGDB ID, а не Steam App ID,
                        # поэтому иконку из Steam не качаем — показываем ту, что уже сохранена в grid (она уже в temp),
                        # а значок источника берём из метаданных (по умолчанию SteamGridDB).
                        $iconFromSaved = ($IsRomEntry -or ([string]$editorState.SearchSource -ne 'Steam'))
                        $appForIcon = $txtId.Text.Trim()
                        if ((-not $iconFromSaved) -and $appForIcon -match '^\d+$') {
                            try { Download-SteamIconToTemp $appForIcon $true | Out-Null } catch {}
                        }
                        $iconSource = 'Steam'
                        if ($iconFromSaved) {
                            $iconSource = 'SteamGridDB'
                            try { if ($null -ne $savedSources -and -not [string]::IsNullOrWhiteSpace([string]$savedSources.icon)) { $iconSource = [string]$savedSources.icon } } catch {}
                        }
                        $iconPrev = Get-TempIconPath
                        if($null -ne $iconPrev -and (Set-EditorPreviewFile $slots.Icon $iconPrev)){ Set-EditorSourceBadge $slots.Icon $iconSource }
                        else { Set-EditorPreviewFile $slots.Icon $null | Out-Null }
                        try { $slots.Icon.ExpectedSource = $iconSource } catch {}
                        # «Использовать иконки из EXE»: и при открытии уже добавленной игры
                        # иконка по умолчанию — из её EXE (прежняя остаётся для кнопки EXE).
                        try { Invoke-EditorAutoExeIcon $slots } catch {}
                    }
                    $slots.Vertical.ExpectedSource=$vSource
                    $slots.Horizontal.ExpectedSource=$hSource
                    $slots.Hero.ExpectedSource=$heroSource
                    $slots.Logo.ExpectedSource=$lSource
                    # Регион сохранённых обложек — из метаданных; для игр, добавленных
                    # раньше, обложки всегда были стандартными (английскими).
                    $savedCoverLang = 'english'
                    try { if ($null -ne $savedSources -and -not [string]::IsNullOrWhiteSpace([string]$savedSources.lang)) { $savedCoverLang = [string]$savedSources.lang } } catch {}
                    # Сохраняем старый выбранный язык для обратной совместимости,
                    # но список доступных локализаций будет заполнен ниже по App ID.
                    $btnCoverLang.Tag.Lang = [string]$savedCoverLang
                    $status.Text=(T 'st_covers_loaded')
                }
            } catch {}
        }

        if($loadedExistingCovers){
            # В режиме редактирования уже установленные в Steam обложки были
            # загружены выше из userdata\<account>\config\grid. НИЧЕГО не
            # очищаем и не заменяем их повторной загрузкой по App ID.
            Stop-EditorLoading $slots $dlg
        } elseif($txtId.Text -match '^\d+$'){
            if($editorState.SearchSource -eq 'Steam') {
                Load-EditorSteamPreviews $txtId.Text.Trim() $slots $status $licensedMode
            } else {
                [void](Load-EditorSgdbPreviews -gameName $txtTitle.Text.Trim() -steamAppId '' -slots $slots -statusLabel $status -sgdbGameId ([int]$txtId.Text.Trim()))
            }
            if($global:editorLoadAbortRequested -or $dlg.IsDisposed -or $dlg.Disposing){ return }
        } else {
            Stop-EditorLoading $slots $dlg
            foreach($sl in $slots.Values){ Set-EditorPreviewFile $sl $null | Out-Null }
            $status.Text=if($editorState.SearchSource -eq 'Steam'){(T 'st_noid_hint_steam')}else{(T 'st_noid_hint_sgdb')}
        }

        # Лицензионная игра: поверх официальных Steam-обложек подставляем те, что уже сохранены
        # в config\grid (выбранные ранее, в т.ч. из SteamGridDB) — карточка должна показывать то,
        # что установлено сейчас. Источник для значка берём из cover_sources\<appid>.json.
        if($licensedMode -and $editorState.SearchSource -eq 'Steam' -and $licensedAppId -match '^\d+$' -and -not (Test-EditorLoadCancelled) -and -not $dlg.IsDisposed){
            try {
                $licSources = Get-CoverSourcesMetadata $licensedAppId
                $licSrc = {
                    param($key)
                    if ($null -ne $licSources -and -not [string]::IsNullOrWhiteSpace([string]$licSources.$key)) { return [string]$licSources.$key }
                    return 'Steam'
                }
                # Иконку подменяем только если её выбирали вручную в SGDB: старые _icon.png из grid
                # у официальных иконок часто чёрные (см. комментарий выше про ico→png).
                $iconFromSgdb = ($null -ne $licSources -and [string]$licSources.icon -eq 'SteamGridDB')
                $licLoaded = Copy-LicensedGridCoversToTemp $licensedAppId $iconFromSgdb
                $licCount = 0
                $licMap = @(
                    @{ Key = 'p';      Slot = $slots.Vertical;   File = 'temp_p.jpg' },
                    @{ Key = 'header'; Slot = $slots.Horizontal; File = 'temp_header.jpg' },
                    @{ Key = 'hero';   Slot = $slots.Hero;       File = 'temp_hero.jpg' },
                    @{ Key = 'logo';   Slot = $slots.Logo;       File = 'temp_logo.png' }
                )
                foreach ($lm in $licMap) {
                    if (-not $licLoaded.ContainsKey($lm.Key)) { continue }
                    if (Set-EditorPreviewFile $lm.Slot (Join-Path $global:tempCovers $lm.File)) {
                        $lsrc = & $licSrc $lm.Key
                        Set-EditorSourceBadge $lm.Slot $lsrc
                        try { $lm.Slot.ExpectedSource = $lsrc } catch {}
                        $licCount++
                    }
                }
                if ($licLoaded.ContainsKey('icon') -and $null -ne $slots.Icon) {
                    $licIcon = Get-TempIconPath
                    if ($null -ne $licIcon -and (Set-EditorPreviewFile $slots.Icon $licIcon)) {
                        Set-EditorSourceBadge $slots.Icon 'SteamGridDB'
                        try { $slots.Icon.ExpectedSource = 'SteamGridDB' } catch {}
                        $licCount++
                    }
                }
                if ($licCount -gt 0) { $status.Text = (T 'st_covers_loaded') }
            } catch {}
        }

        # Кнопки регионов уже показаны до загрузки обложек. Здесь — только
        # запасной проход, если ранний не сработал (нет App ID на тот момент).
        try {
            $coverLangPanel = Get-EditorCoverLanguagePanel $dlg
            if($editorState.SearchSource -eq 'Steam' -and $txtId.Text -match '^\d+$' -and $null -ne $coverLangPanel){
                $avail = @($coverLangPanel.Tag.Codes)
                if(@($avail).Count -eq 0){
                    $avail = @(Get-SteamPicsAvailableLanguages $txtId.Text.Trim())
                    if ($avail.Count -eq 0) { $avail = @('english') }
                    $prefer = [string](Get-SteamAssetLanguage)
                    if ($avail -contains $prefer) { $activeLang = $prefer }
                    elseif ($avail -contains 'english') { $activeLang = 'english' }
                    else { $activeLang = [string]$avail[0] }
                    & $renderCoverLanguages $avail $activeLang
                }
            } elseif ($null -ne $coverLangPanel) {
                $coverLangPanel.Visible = $false
            }
        } catch {}

        # Подсказка exe из Steam — теперь через переиспользуемый блок
        # $tryApplySteamExeHint (см. его определение выше), чтобы её можно было
        # так же вызвать позже, при последующих подтверждениях App ID.
        & $tryApplySteamExeHint $txtId.Text.Trim()
        # Лицензионная игра: EXE только для просмотра и нигде не сохраняется,
        # поэтому красный "!" не имеет смысла — считаем поле подтверждённым.
        if ($licensedMode -and -not $editorState.ExeConfirmed) {
            $editorState.ExeConfirmed = $true
            Set-ConfidenceBadge $exeConfidenceBadge $true (T 'lib_licensed_hint') ''
        }

        # При открытии карточки ничего не выделяем автоматически и не оставляем
        # фокус на одном из полей ввода. Важно не просто сбросить SelectionLength,
        # а реально убрать фокус с TextBox: при следующем DoEvents WinForms иначе
        # может снова показать выделение.
        try {
            $txtTitle.SelectionLength=0; $txtTitle.SelectionStart=0
            $txtId.SelectionLength=0; $txtId.SelectionStart=0
            $txtLaunchOptions.SelectionLength=0; $txtLaunchOptions.SelectionStart=0
            $dlg.ActiveControl=$editorFocusSink
            $editorFocusSink.Focus() | Out-Null
        } catch {}
        try {
            $dlg.BeginInvoke([Action]{
                try {
                    $txtTitle.SelectionLength=0; $txtTitle.SelectionStart=0
                    $txtId.SelectionLength=0; $txtId.SelectionStart=0
                    $txtLaunchOptions.SelectionLength=0; $txtLaunchOptions.SelectionStart=0
                    $dlg.ActiveControl=$editorFocusSink
                    $editorFocusSink.Focus() | Out-Null
                } catch {}
            }) | Out-Null
        } catch {}
        # Положение логотипа: у готового ярлыка и лицензионной игры берём сохранённое в
        # config\librarycache\<id>.json, чтобы карточка открывалась с прежними значениями.
        # Снимок отпечатка берём после этого - «не трогали» значит «равно тому, что открылось».
        try {
            $logoCacheId = ''
            if ($licensedMode) { $logoCacheId = [string]$licensedAppId }
            elseif ($editMode -and $null -ne $existingShortcut) { $logoCacheId = [string]$existingShortcut.ShortcutId }
            if ($logoCacheId -match '^\d+$' -and $script:LogoComposeEnabled -and $null -ne $slots.Hero.PSObject.Properties['ComposeLogo']) {
                $savedLogoPos = Get-SteamLogoPositionFromCache $logoCacheId
                if ($null -ne $savedLogoPos) { Set-EditorLogoStateFromCache $slots.Hero $savedLogoPos }
            }
        } catch {}
        # Галочка «по умолчанию» включена - карточка (в том числе новая и для рома) открывается с общими
        # положением и размером логотипа вместо сохранённых у конкретной игры.
        try {
            if ($script:LogoComposeEnabled -and $null -ne $slots.Hero.PSObject.Properties['ComposeLogo']) {
                $logoDefOpen = Get-LogoDefaultPosition
                if ($null -ne $logoDefOpen) {
                    Set-EditorLogoStateFromCache $slots.Hero $logoDefOpen
                    $editorState.LogoUseDefault = $true
                    $slots.Hero.ChkDefault.Checked = $true
                }
            }
        } catch {}
        try { $editorState.LogoSig0 = [string](Get-EditorLogoSignature $editorState) } catch {}
        # Снимок состояния карточки сразу после загрузки: по нему при сохранении понимаем, менялось ли
        # что-то кроме библиотек (см. $hasOtherEditorChanges).
        try {
            $editorState.Baseline = [PSCustomObject]@{
                Name = $txtTitle.Text.Trim(); Id = $txtId.Text.Trim(); Launch = $txtLaunchOptions.Text.Trim()
                Exe = [string](& $getEditorExePathNow); Covers = [string](Get-EditorCoverFingerprint); Logo = [string](Get-EditorLogoSignature $editorState)
            }
        } catch {}
        } finally {
            $editorState.OpDepth = [Math]::Max(0, [int]$editorState.OpDepth - 1)
            Invoke-EditorPendingSwitch
        }
    })

    # После создания всех остальных контролов ещё раз поднимаем поле ввода.
    # Закрытый results-combo полностью скрыт под ним, но его нативный popup
    # при DroppedDown=$true остаётся видимым поверх формы.
    $pnlTitle.BringToFront()

    # Какие библиотеки нужно заменить: поле, где выбрана не та версия, что лежит в игре. Источник —
    # скачанная версия или бэкап оригинала. Если выбрана нескачанная версия — сохранение блокируется
    # с понятным сообщением, пока ничего не тронуто.
    $getDllPlan = {
        $targets = New-Object System.Collections.ArrayList
        foreach ($k in @($dlssControls.Keys)) {
            $c = $dlssControls[$k].Combo
            if ([bool]$c.Locked) { continue }
            if (-not $dlssCurIdx.ContainsKey([string]$k)) { continue }
            $i = [int]$c.SelectedIndex
            if ($i -lt 0 -or $i -eq [int]$dlssCurIdx[[string]$k]) { continue }
            $srcs = @($dlssSrcs[[string]$c.Name])
            $src = ''
            if ($i -lt $srcs.Count) { $src = [string]$srcs[$i] }
            if ([string]::IsNullOrWhiteSpace($src) -or -not [System.IO.File]::Exists($src)) {
                return [PSCustomObject]@{ Ok = $false; Error = (T 'card_dll_not_downloaded' @([string]$dlssTitles[[string]$k], [string]$c.Items[$i])); Targets = @() }
            }
            foreach ($dst in @($dlssTargets[[string]$k])) { [void]$targets.Add(@{ Dst = [string]$dst; Src = $src }) }
        }
        return [PSCustomObject]@{ Ok = $true; Error = ''; Targets = @($targets) }
    }

    # Менялось ли в карточке что-то кроме библиотек (название, App ID, exe, параметры, обложки/иконка).
    # Сравнение — с состоянием, снятым сразу после загрузки карточки ($editorState.Baseline).
    # Нет снимка или любая ошибка — считаем, что менялось (тогда всё работает как раньше, со Steam).
    $getEditorExePathNow = {
        $pth = ''
        try {
            $ix = [int]$cmbExe.SelectedIndex
            if ($ix -ge 0 -and $ix -lt @($exeCandidates).Count) { $pth = [string]$exeCandidates[$ix].FullName }
        } catch {}
        return $pth
    }
    $hasOtherEditorChanges = {
        try {
            $b = $editorState.Baseline
            if ($null -eq $b) { return $true }
            if ((Get-EditorCoverFingerprint) -ne [string]$b.Covers) { return $true }
            # Изменение одного только положения/размера логотипа тоже считается изменением карточки.
            if ((Get-EditorLogoSignature $editorState) -ne [string]$b.Logo) { return $true }
            if ($licensedMode) { return $false }
            if ($txtTitle.Text.Trim() -ne [string]$b.Name) { return $true }
            if ($txtId.Text.Trim() -ne [string]$b.Id) { return $true }
            if ($txtLaunchOptions.Text.Trim() -ne [string]$b.Launch) { return $true }
            if ((& $getEditorExePathNow) -ne [string]$b.Exe) { return $true }
            return $false
        } catch { return $true }
    }

    $btnAdd.Add_Click({
        $name=$txtTitle.Text.Trim()
        if([string]::IsNullOrWhiteSpace($name)){ $status.Text=(T 'st_enter_title'); return }
        $launchOptions=$txtLaunchOptions.Text.Trim()
        $exePath = ''
        $startDir = ''
        $isWrappedEntry = (-not $licensedMode) -and (-not $IsRomEntry) -and (-not $editMode) -and (Test-LauncherEntryWrapped $LauncherEntry)
        if (-not $licensedMode -and $IsRomEntry) {
            if($romCandidates.Count -gt 0 -and $cmbRom.SelectedIndex -lt 0){ $status.Text=(T 'rom_pick_file'); return }
            if($cmbRom.SelectedIndex -ge 0 -and -not (Test-Path -LiteralPath ([string](& $getSelectedRomPath)))){
                # Файл мог быть переименован/заменён (например, после докачки
                # обновления или конвертации) уже после того, как список
                # кандидатов был построен при открытии карточки. Прежде чем
                # блокировать добавление, пересканируем папку заново.
                # ВАЖНО: проверка обязательно через -LiteralPath — иначе Test-Path
                # трактует квадратные скобки в имени рома (Title ID, [v0] и т.п.)
                # как маску подстановки, а не как буквальные символы, и файл,
                # который физически существует, ошибочно считается отсутствующим.
                $rescanExt = if ($cmbEmulator.SelectedIndex -ge 0 -and $cmbEmulator.SelectedIndex -lt $emuProfiles.Count) { [string]$emuProfiles[$cmbEmulator.SelectedIndex].Extensions } else { '' }
                $rescanExtract = if ($cmbEmulator.SelectedIndex -ge 0 -and $cmbEmulator.SelectedIndex -lt $emuProfiles.Count) { Test-EmulatorExtractArchives $emuProfiles[$cmbEmulator.SelectedIndex] } else { $false }
                & $populateRomCandidates $rescanExt $rescanExtract
                if($cmbRom.SelectedIndex -lt 0 -or -not (Test-Path -LiteralPath ([string](& $getSelectedRomPath)))){
                    $status.Text=(T 'rom_file_gone')
                    return
                }
            }
            if($cmbEmulator.SelectedIndex -lt 0){ $status.Text=(T 'st_pick_emulator'); return }
            $emuIndex=$cmbEmulator.SelectedIndex
            if($emuIndex -lt 0 -or $emuIndex -ge $emuProfiles.Count){ $status.Text=(T 'st_pick_emulator'); return }
            $exePath=[string]$emuProfiles[$emuIndex].ExePath
            if([string]::IsNullOrWhiteSpace($exePath) -or -not (Test-Path $exePath)){ $status.Text=(T 'st_emulator_gone'); return }
            $startDir=[System.IO.Path]::GetDirectoryName($exePath)
            if([string]::IsNullOrWhiteSpace($startDir) -or -not (Test-Path $startDir -PathType Container)){
                $status.Text=(T 'st_no_workdir')
                return
            }
            $global:folderDisplayNameCache[$gamePath.ToUpper()]=$name
        } elseif ($isWrappedEntry -and $cmbExe.SelectedIndex -lt 0) {
            # Запуск через SCLauncher.exe: exe не выбран (в папке не найден) — рабочая папка = папка игры.
            if([string]::IsNullOrWhiteSpace([string]$gamePath) -or -not (Test-Path -LiteralPath $gamePath -PathType Container)){
                $status.Text=(T 'st_no_workdir')
                return
            }
            $startDir=[string]$gamePath
            $global:folderDisplayNameCache[$gamePath.ToUpper()]=$name
        } elseif (-not $licensedMode) {
            if($cmbExe.SelectedIndex -lt 0){ $status.Text=(T 'st_pick_exe'); return }
            $exeIndex=$cmbExe.SelectedIndex
            if($exeIndex -lt 0 -or $exeIndex -ge $exeCandidates.Count){ $status.Text=(T 'st_exe_gone'); return }
            $exePath=[string]$exeCandidates[$exeIndex].FullName
            if(-not (Test-Path $exePath)){ $status.Text=(T 'st_exe_bat_gone'); return }
            $startDir=[System.IO.Path]::GetDirectoryName($exePath)
            if([string]::IsNullOrWhiteSpace($startDir) -or -not (Test-Path $startDir -PathType Container)){
                $status.Text=(T 'st_no_workdir')
                return
            }
            $cacheKey=$gamePath.ToUpper()
            $global:exeSelectionCache[$cacheKey]=$exePath
            $global:folderDisplayNameCache[$gamePath.ToUpper()]=$name
        }
        # Игра лаунчера (Epic Games, GOG, Ubisoft): в карточке пользователь видит и выбирает
        # настоящий exe, а в ярлык при добавлении пишется SCLauncher.exe с параметрами
        # (ссылка запуска + папка игры). StartDir остаётся папкой настоящего exe.
        $wrapExe = ''
        $wrapArgs = ''
        if ($isWrappedEntry) {
            $wrapPlan = Get-LauncherWrapPlan $LauncherEntry
            if (-not $wrapPlan.Ok) { $status.Text=[string]$wrapPlan.Reason; return }
            $wrapExe = [string]$wrapPlan.Exe
            $wrapArgs = [string]$wrapPlan.Args
        }
        # ROM RetroArch в архиве, который RetroArch сам не откроет (мультифайловый образ, .rar и т.п.):
        # ярлык = SCLauncher.exe, он распакует архив и запустит ядро. Остальные ROM — прямо на эмулятор.
        if (-not $licensedMode -and $IsRomEntry) {
            $romWrap = $null
            $extractOn = $false
            try {
                $selEmuProfile = $emuProfiles[$cmbEmulator.SelectedIndex]
                $extractOn = Test-EmulatorExtractArchives $selEmuProfile
                if (-not $extractOn) {
                    # Галочка выключена: ничего не распаковываем, ярлык прямо на эмулятор (как с обычным файлом).
                } elseif (Test-IsRetroArchProfile ([string]$selEmuProfile.Name) $exePath) {
                    # RetroArch с галочкой: «умный» выбор по .info ядра (needs_fullpath, supported_extensions) -
                    # архив распаковывается, только если ядро не умеет читать его само.
                    $status.Text = (T 'rom_arc_checking')
                    [System.Windows.Forms.Application]::DoEvents()
                    $romWrap = Get-RomArchiveWrapPlan ([string](& $getSelectedRomPath)) $exePath $launchOptions ([string](& $getSelectedRomEntry))
                } else {
                    # Остальные эмуляторы: общий механизм (шаблон параметров профиля, {rom}).
                    $status.Text = (T 'rom_arc_checking')
                    [System.Windows.Forms.Application]::DoEvents()
                    $romWrap = Get-EmulatorArchiveWrapPlan ([string](& $getSelectedRomPath)) $exePath $launchOptions ([string]$selEmuProfile.Extensions) ([string](& $getSelectedRomEntry))
                }
            } catch {
                # При включённой галочке «Распаковывать архивы» молча добавлять ярлык на сам архив нельзя:
                # эмулятор получил бы .zip/.7z как есть. Пишем причину в лог и показываем ошибку.
                try { Write-LauncherLog ('rom wrap plan failed: ' + [string]$_.Exception.Message) } catch {}
                $romWrap = $null
                if ($extractOn) { $romWrap = [PSCustomObject]@{ Wrapped = $false; Ok = $false; Exe = ''; Args = ''; Reason = (T 'st_launcher_wrap_fail') } }
            }
            if ($null -ne $romWrap) {
                if (-not $romWrap.Ok) { $status.Text = [string]$romWrap.Reason; return }
                if ($romWrap.Wrapped) { $wrapExe = [string]$romWrap.Exe; $wrapArgs = [string]$romWrap.Args }
            }
        }
        # --- Библиотеки апскейлеров: бэкап и замена DLL в папке игры ---
        # Выполняется до любых действий со Steam: при ошибке (например, игра запущена и держит DLL)
        # карточка остаётся открытой, ничего не сохранено и Steam не закрыт.
        $libPlan = $null
        if (-not $IsRomEntry) { try { $libPlan = & $getDllPlan } catch { $libPlan = $null } }
        if ($null -ne $libPlan -and -not $libPlan.Ok) { $status.Text = [string]$libPlan.Error; return }
        if ($null -ne $libPlan -and @($libPlan.Targets).Count -gt 0) {
            $libRes = Set-GameUpscalerFiles @($libPlan.Targets)
            if (-not $libRes.Ok) { $status.Text = (T 'card_dll_apply_fail' @([string]$libRes.Error)); return }
            # Менялись только библиотеки — shortcuts.vdf и обложки не трогаем, Steam не закрываем
            # и после закрытия карточки не перезапускаем ($steamWasKilledThisSession остаётся $false).
            if ($editMode -and -not $batchMode -and -not (& $hasOtherEditorChanges)) {
                $status.Text = (T 'st_done_saved')
                [System.Media.SystemSounds]::Asterisk.Play()
                $script:editorSavedChanges = $true
                $dlg.DialogResult=[System.Windows.Forms.DialogResult]::OK
                $dlg.Close()
                return
            }
        }
        $btnAdd.Enabled=$false; $searchSourceBtn.Enabled=$false; $btnCoverLang.Enabled=$false; if($btnCancel -ne $null){$btnCancel.Enabled=$false}

        try {
            if ($licensedMode) {
                # Лицензионная игра: сохраняем только обложки в config\grid по App ID.
                $steamPathProperty=(Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
                if([string]::IsNullOrEmpty($steamPathProperty)){$steamPathProperty='C:\Program Files (x86)\Steam\steam.exe'}
                $labelHeader.Text=(T 'hd_saving' @($name))
                [System.Windows.Forms.Application]::DoEvents()
                taskkill.exe /F /T /IM steam.exe 2>$null | Out-Null
                Start-Sleep -Seconds 2
                $script:steamWasKilledThisSession = $true
                $appIdSave = $licensedAppId
                if ($appIdSave -notmatch '^\d+$') { $appIdSave = $txtId.Text.Trim() }
                if ($appIdSave -notmatch '^\d+$') { throw 'App ID' }
                # Положение логотипа - во все профили Steam, независимо от того, менялись ли картинки.
                try {
                    $logoPosLic = Get-EditorLogoPositionToSave $editorState $false
                    if ($null -ne $logoPosLic) { [void](Set-SteamLogoPositionForAllProfiles ([string]$appIdSave) $logoPosLic) }
                } catch {}
                $hasCovers=$false
                try { $hasCovers=Test-CoversValid } catch { $hasCovers=$false }
                $coversSaved=$false
                if ($hasCovers) {
                    try { $coversSaved = [bool](Copy-TempCoversDirectlyToGrid $appIdSave) } catch { $coversSaved=$false }
                    if ($coversSaved) {
                        try { Save-CoverSourcesMetadata ([string]$appIdSave) $slots ([string]$btnCoverLang.Tag.Lang) | Out-Null } catch {}
                    }
                }
                $status.Text=if($coversSaved){(T 'st_done_saved_covers')}elseif($hasCovers){(T 'st_saved_no_covers')}else{(T 'st_done_saved')}
                [System.Media.SystemSounds]::Asterisk.Play()
                $script:editorSavedChanges = $true
                $dlg.DialogResult=[System.Windows.Forms.DialogResult]::OK
                $dlg.Close()
                return
            }
            if($editMode){
                $steamPathProperty=(Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
                if([string]::IsNullOrEmpty($steamPathProperty)){$steamPathProperty='C:\Program Files (x86)\Steam\steam.exe'}
                $labelHeader.Text=(T 'hd_saving' @($name))
                [System.Windows.Forms.Application]::DoEvents()
                taskkill.exe /F /T /IM steam.exe 2>$null | Out-Null
                Start-Sleep -Seconds 2
                $script:steamWasKilledThisSession = $true
                # Ярлык уже известен - перечитываем его строго по ID, а не по имени/папке (см. Find-SteamShortcutRecordById).
                $freshShortcut=Find-SteamShortcutRecordById $existingShortcut
                if($freshShortcut -eq $null){$freshShortcut=$existingShortcut}
                # Ром из архива через SCLauncher.exe: в ярлык пишется обёртка, а не сам эмулятор.
                $editExe = $exePath; $editLaunch = $launchOptions
                if ($wrapExe) { $editExe = $wrapExe; $editLaunch = $wrapArgs }
                $shortcutId=Update-ExistingSteamShortcut $freshShortcut $name $editExe $startDir $editLaunch
                if(-not $shortcutId){
                    $reason=if($global:lastShortcutError){[string]$global:lastShortcutError}else{(T 'reason_save_shortcut')}
                    throw $reason
                }
                # Exe/параметры могли измениться — переносим запомненную папку игры на новый ключ.
                try { Move-GameFolderMapEntry ([string]$freshShortcut.Exe) ([string]$freshShortcut.LaunchOptions) ([string]$editExe) ([string]$editLaunch) '' } catch {}
                # Обложки сохраняем именно в userdata\<account>\config\grid
                # того же Steam-профиля, в котором лежит изменяемый shortcuts.vdf.
                $freshShortcutAfterSave=$null
                try {
                    $freshShortcutAfterSave=Find-SteamShortcutRecordById ([PSCustomObject]@{
                        ShortcutId=[string]$shortcutId; FilePath=[string]$freshShortcut.FilePath
                        Exe=[string]$editExe; LaunchOptions=[string]$editLaunch; AppName=[string]$name })
                } catch {}
                if($freshShortcutAfterSave -eq $null){$freshShortcutAfterSave=$freshShortcut}
                $hasCovers=$false
                try { $hasCovers=Test-CoversValid } catch { $hasCovers=$false }
                $coversSaved=$false
                if($hasCovers){
                    try { $coversSaved=Save-ExistingShortcutCoversToGrid $freshShortcutAfterSave } catch { $coversSaved=$false }
                    if($coversSaved){
                        try {
                            $newShortcutId=[string]$freshShortcutAfterSave.ShortcutId
                            Save-CoverSourcesMetadata $newShortcutId $slots ([string]$btnCoverLang.Tag.Lang) | Out-Null
                            $oldShortcutId=[string]$existingShortcut.ShortcutId
                            if(-not [string]::IsNullOrWhiteSpace($oldShortcutId) -and $oldShortcutId -ne $newShortcutId){ Remove-CoverSourcesMetadata $oldShortcutId }
                        } catch {}
                    }
                }

                # Положение логотипа - во все профили Steam (config\librarycache\<id>.json), независимо от того,
                # менялись ли картинки. Если id ярлыка изменился (переименование), сохранённое положение переносится.
                try {
                    $logoIdChanged = ([string]$freshShortcutAfterSave.ShortcutId -ne [string]$existingShortcut.ShortcutId)
                    $logoPosEdit = Get-EditorLogoPositionToSave $editorState $logoIdChanged
                    if ($null -ne $logoPosEdit) { [void](Set-SteamLogoPositionForAllProfiles ([string]$freshShortcutAfterSave.ShortcutId) $logoPosEdit) }
                } catch {}

                # Сначала гарантированно закрываем карточку. Steam запускается
                # внешним finally главного обработчика после возврата из ShowDialog.
                $status.Text=if($coversSaved){(T 'st_done_saved_covers')}elseif($hasCovers){(T 'st_saved_no_covers')}else{(T 'st_done_saved')}
                [System.Media.SystemSounds]::Asterisk.Play()
                $script:editorSavedChanges = $true
                $dlg.DialogResult=[System.Windows.Forms.DialogResult]::OK
                $dlg.Close()
                return
            }

            if([string]::IsNullOrWhiteSpace($txtId.Text) -or $txtId.Text -notmatch '^\d+$'){
                if($editorState.SearchSource -eq 'Steam'){
                    $found=Find-SteamAppInfo $name
                    if($found -ne $null){$txtId.Text=[string]$found.Id}
                } else {
                    $candidates=@(Get-EditorSgdbCandidates $name '')
                    if(@($candidates).Count -gt 0){$txtId.Text=[string]$candidates[0].Id}
                }
            }
            if($txtId.Text -match '^\d+$' -and -not (Test-Path (Join-Path $global:tempCovers 'temp_p.jpg'))){
                if($editorState.SearchSource -eq 'Steam'){
                    Load-EditorSteamPreviews $txtId.Text.Trim() $slots $status
                } else {
                    [void](Load-EditorSgdbPreviews -gameName $name -steamAppId '' -slots $slots -statusLabel $status -sgdbGameId ([int]$txtId.Text.Trim()))
                }
            }

            $steamPathProperty=(Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
            if([string]::IsNullOrEmpty($steamPathProperty)){$steamPathProperty='C:\Program Files (x86)\Steam\steam.exe'}
            $labelHeader.Text=(T 'hd_adding' @($name))
            [System.Windows.Forms.Application]::DoEvents()
            if(-not $batchMode){taskkill.exe /F /T /IM steam.exe 2>$null | Out-Null;Start-Sleep -Seconds 2}

            # Обе панели равноправны. При добавлении игры в Steam НЕ переносим
            # её в другую панель и НЕ создаём Junction. Steam получает реальный
            # путь к выбранному EXE/BAT там, где папка игры находится сейчас.
            $finalExe=$exePath
            $finalStart=$startDir
            $finalLaunch=$launchOptions
            if($wrapExe){ $finalExe=$wrapExe; $finalLaunch=$wrapArgs }

            $newId=Add-ShortcutToSteam $name $finalExe $finalStart $finalLaunch
            if(-not $newId){$reason=if($global:lastShortcutError){[string]$global:lastShortcutError}else{(T 'reason_shortcut_fail')};throw $reason}
            # Запоминаем полную папку игры из панели (корень для поиска DLSS в библиотеке).
            try { if(-not $IsRomEntry -and -not [string]::IsNullOrWhiteSpace([string]$gamePath)){ Set-GameFolderForShortcut $finalExe $finalLaunch ([string]$gamePath) } } catch {}
            $hasCovers=$false
            try { $hasCovers=Test-CoversValid } catch { $hasCovers=$false }
            $logoPosNew = $null
            try { $logoPosNew = Get-EditorLogoPositionToSave $editorState $false } catch {}
            if($hasCovers){
                try { Copy-TempCoversDirectlyToGrid $newId $logoPosNew | Out-Null } catch {}
                try { Save-CoverSourcesMetadata ([string]$newId) $slots ([string]$btnCoverLang.Tag.Lang) | Out-Null } catch {}
            } elseif ($null -ne $logoPosNew) {
                try { [void](Set-SteamLogoPositionForAllProfiles ([string]$newId) $logoPosNew) } catch {}
            }
            $script:editorSavedChanges = $true
            if(-not $batchMode -and (Test-Path $steamPathProperty)){Start-Process -FilePath $steamPathProperty}
            $status.Text=if($hasCovers){(T 'st_done_added_covers')}else{(T 'st_done_added_nocovers')}
            [System.Media.SystemSounds]::Asterisk.Play()
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 500
            $dlg.Close()
        } catch {
            if(-not $batchMode){try{if(Test-Path $steamPathProperty){Start-Process -FilePath $steamPathProperty}}catch{}}
            $status.Text=(T 'st_error' @([string]$_.Exception.Message))
            $btnAdd.Enabled=$true; try { & $updateSgdbButtonState } catch {}; if ($IsRomEntry) { $searchSourceBtn.Visible=$false }; $btnCoverLang.Enabled=($editorState.SearchSource -eq 'Steam'); if($btnCancel -ne $null){$btnCancel.Enabled=$true}
        }
    })

    # Закрытие карточки во время сетевой загрузки не должно ждать ответа сервера.
    # FormClosing срабатывает и для крестика, и для кнопок «Отмена»/«Пропустить».
    $dlg.Add_FormClosing({
        $global:editorLoadAbortRequested = $true
        # Отложенное переключение источника при закрытии карточки не нужно.
        $global:editorPendingSwitchAction = $null
    })

    if($btnCancel -ne $null){
        $btnCancel.Add_Click({
            $script:batchCardCancelRequested = $true
            $global:editorLoadAbortRequested = $true
            $dlg.Close()
        })
    }
    if($batchMode -and $btnSkip -ne $null){
        $btnSkip.Add_Click({
            $script:batchCardSkipRequested = $true
            $global:editorLoadAbortRequested = $true
            $dlg.Close()
        })
    }
    # Если открыт список подсказок названия или параметров, любой клик
    # в другом месте карточки должен закрывать его. Важно: клик по самому
    # полю и по его списку не закрывает список. Обработчик навешивается
    # рекурсивно на все существующие контролы карточки, поэтому это работает
    # не только по фону формы, но и по кнопкам, подписям, панелям и обложкам.
    $hideEditorDropDownsOnOutsideClick = {
        param($sender, $e)
        try {
            $ctrl = $sender
            $isInsideExcluded = $false
            $excluded = @($txtTitle, $pnlTitle, $titleResults, $txtLaunchOptions, $launchOptResults)
            foreach($root in $excluded){
                if($null -eq $root){ continue }
                $node = $ctrl
                while($null -ne $node){
                    if([object]::ReferenceEquals($node, $root)){
                        $isInsideExcluded = $true
                        break
                    }
                    $node = $node.Parent
                }
                if($isInsideExcluded){ break }
            }
            if($isInsideExcluded){ return }
            if($titleResults.Visible){
                $titleResults.Visible = $false
                $titleResults.SelectedIndex = -1
            }
            if($launchOptResults.Visible){
                $launchOptResults.Visible = $false
                $launchOptResults.SelectedIndex = -1
            }
            # Реально снимаем фокус именно с текстового поля. Form.Focus()
            # здесь недостаточно: WinForms может оставить ActiveControl
            # прежним, поэтому курсор в TextBox продолжает мигать.
            # Используем отдельный невидимый focus-sink. Если клик был по
            # кнопке/другому фокусируемому контролу, этот контрол после
            # MouseDown получит фокус обычным порядком WinForms.
            try {
                if([object]::ReferenceEquals($dlg.ActiveControl,$txtTitle) -or [object]::ReferenceEquals($dlg.ActiveControl,$txtLaunchOptions)){
                    $dlg.ActiveControl=$editorFocusSink
                    $editorFocusSink.Focus() | Out-Null
                } else {
                    if($txtTitle.Focused -or $txtLaunchOptions.Focused){
                        $editorFocusSink.Focus() | Out-Null
                    }
                }
            } catch {}
        } catch {}
    }

    $wireOutsideDropDownDismiss = $null
    $wireOutsideDropDownDismiss = {
        param($control)
        try {
            if($null -eq $control){ return }
            $control.Add_MouseDown($hideEditorDropDownsOnOutsideClick)
            foreach($child in @($control.Controls)){
                & $wireOutsideDropDownDismiss $child
            }
        } catch {}
    }
    & $wireOutsideDropDownDismiss $dlg

    # Esc закрывает карточку так же, как кнопка отмены. Порядок такой:
    #  1) открытый выпадающий список (варианты названия, список EXE) — Esc закрывает только его;
    #  2) идёт сохранение/поиск (кнопка добавления отключена) — Esc игнорируется;
    #  3) пакетный режим — нажимается «Отменить»; обычный режим — карточка просто закрывается
    #     (отдельной кнопки отмены в ней нет, результат тот же, что у крестика окна).
    $dlg.KeyPreview = $true
    $dlg.Add_KeyDown({
        if($_.KeyCode -ne [System.Windows.Forms.Keys]::Escape){ return }
        $ac = $dlg.ActiveControl
        if($ac -is [System.Windows.Forms.ComboBox] -and $ac.DroppedDown){ return }
        $_.SuppressKeyPress = $true; $_.Handled = $true
        if($titleResults.Visible){ & $closeEditorTitleDropDown; $txtTitle.Focus(); return }
        # Языки обложек теперь представлены постоянными значками; отдельного списка нет.
        if(-not $btnAdd.Enabled){ return }
        if($btnCancel -ne $null){ $btnCancel.PerformClick() } else { $dlg.Close() }
    })
    if($batchHost -ne $null){
        # Показываем карточку не отдельным диалогом, а встроенной в панель
        # уже открытого окна пакетного добавления, и ждём её закрытия тем же
        # способом прокачки очереди сообщений, что и остальные неблокирующие
        # ожидания в этом файле — вместо вложенного ShowDialog() у отдельного
        # окна (тут это и не сработало бы: TopLevel=false).
        try { $batchHost.Panel.Controls.Clear() } catch {}
        $batchHost.Panel.Controls.Add($dlg)
        $script:__embeddedCardClosed = $false
        $dlg.Add_FormClosed({ $script:__embeddedCardClosed = $true })
        $dlg.Show()
        $dlg.BringToFront()
        [System.Windows.Forms.Application]::DoEvents()
        while(-not $script:__embeddedCardClosed){
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 15
        }
    } else {
        try { Initialize-FormForSmallScreen -Form $dlg -Owner $ownerWin } catch {}
        $dlg.ShowDialog($ownerWin) | Out-Null
    }
    # Карточка уже закрыта — дальнейшая работа программы не должна наследовать
    # её флаг отмены. Флаги пакетного режима остаются отдельно и обрабатываются
    # вызывающим циклом.
    $global:editorLoadAbortRequested = $false
    $global:editorPendingSwitchAction = $null
    # В режиме редактирования Steam закрывался перед записью shortcuts.vdf
    # только если пользователь реально сохранил изменения (см.
    # $steamWasKilledThisSession выше). Запускаем его здесь после полного
    # закрытия карточки — это также работает при открытии карточки двойным
    # кликом/Enter, а не только через главную кнопку — но НЕ делаем этого,
    # если Steam в этой сессии карточки не убивали: иначе он просто
    # поднимался поверх всех окон без всякой причины при обычном закрытии
    # или отмене карточки.
    if($editMode -and -not $batchMode -and $script:steamWasKilledThisSession){
        try {
            $steamPathProperty=(Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
            if([string]::IsNullOrEmpty($steamPathProperty)){$steamPathProperty='C:\Program Files (x86)\Steam\steam.exe'}
            if(Test-Path $steamPathProperty){Start-Process -FilePath $steamPathProperty}
        } catch {}
    }
    # Возвращаем фокус и передний план окну-владельцу карточки — оно было
    # отключено (disabled) на время модального показа карточки, но после
    # Start-Process (запуск/перезапуск Steam) Windows отдаёт передний план
    # именно новому процессу, а не владельцу закрывшегося диалога. Раньше
    # здесь всегда поднималось главное окно программы — из-за этого, если
    # карточку открывали из библиотеки, главное окно (всё это время скрытое
    # $form.Hide()) вдруг появлялось поверх/позади библиотеки без причины.
    # Теперь поднимаем именно того владельца, с которым карточка была
    # открыта — библиотеку или главное окно.
    if($batchHost -eq $null){
        # Это возвращение фокуса нужно только когда карточка была отдельным
        # окном поверх своего владельца. Когда карточка встроена в окно
        # пакетного добавления (batchHost), поднимать владельца нельзя —
        # он закроет собой ещё работающее окно пакета.
        try {
            if($ownerWin -ne $null){
                if($ownerWin -eq $form -and $form.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized){ $form.WindowState=[System.Windows.Forms.FormWindowState]::Normal }
                $ownerWin.Show()
                $ownerWin.Activate()
                $ownerWin.BringToFront()
            }
        } catch {}
    }
    try { foreach($sl in $slots.Values){ if($sl.Stream){$sl.Stream.Dispose()} } } catch {}
    try { Get-ChildItem -Path $global:tempCovers -Filter 'editor_*' -Directory -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue } catch {}
    # Перечитываем панели только если что-то сохранено (или это пакетный режим, где так было всегда).
    # Refresh-Panels тяжёлый: Get-CimInstance ×2, рекурсивный поиск shortcuts.vdf, скан обеих папок.
    if ($batchMode -and $null -eq $ownerWin) {
        # Пакет из главного окна: панели один раз перечитает вызывающий обработчик кнопки в конце
        # (раньше перечитывание шло после каждой карточки, ~1 с на игру).
    } elseif ($batchMode -or $script:editorSavedChanges) { Refresh-Panels }
}

$btnSettings.Add_Click({
    try {
        Show-ProgramSettingsDialog | Out-Null
        if([string]::IsNullOrWhiteSpace([string]$global:steamGridDbApiKey)){
            $labelHeader.Text=(T 'sl_sg_nokey')
        } else {
            $labelHeader.Text=(T 'sl_sg_keysaved')
        }
    } catch {
        Show-AppMessageBox(
            $form,
            (T 'settings_open_fail' @([string]$_.Exception.Message)),
            $global:appTitle,
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
    }
})

function Set-PanelPathFromText($panelId, $pathText) {
    $path = [string]$pathText
    if ($null -eq $path) { $path = '' }
    $path = $path.Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($path)) { return $false }

    try {
        $full = [System.IO.Path]::GetFullPath($path)
    } catch {
        [System.Media.SystemSounds]::Beep.Play()
        return $false
    }

    if (-not (Test-Path -LiteralPath $full -PathType Container)) {
        [System.Media.SystemSounds]::Beep.Play()
        return $false
    }

    if ($panelId -eq 'C') { $global:dirC = $full; $lblPathC.Text = $full }
    else { $global:dirD = $full; $lblPathD.Text = $full }
    Refresh-Panels
    Save-Configuration
    return $true
}

$lblPathC.Add_KeyDown({
    if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) {
        $_.SuppressKeyPress = $true
        $_.Handled = $true
        [void](Set-PanelPathFromText 'C' $lblPathC.Text)
    }
})
$lblPathD.Add_KeyDown({
    if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) {
        $_.SuppressKeyPress = $true
        $_.Handled = $true
        [void](Set-PanelPathFromText 'D' $lblPathD.Text)
    }
})


# Поля пути не должны получать фокус автоматически.
# Пользователь получает фокус только обычным кликом по самому TextBox.
$lblPathC.TabStop = $false
$lblPathD.TabStop = $false

function Remove-PathFocus {
    try {
        if ($lblPathC.Focused -or $lblPathD.Focused) {
            # Только снимаем текущий ActiveControl. Никаких Focus()/Select() здесь нет.
            $form.ActiveControl = $null
        }
    } catch {}
}

function Install-PathFocusDismissHandlers {
    function Add-DismissHandler([System.Windows.Forms.Control]$control) {
        if ($null -eq $control) { return }
        if ($control -ne $lblPathC -and $control -ne $lblPathD) {
            $control.Add_MouseDown({ Remove-PathFocus })
        }
        foreach ($child in @($control.Controls)) {
            Add-DismissHandler $child
        }
    }

    foreach ($control in @($form.Controls)) {
        Add-DismissHandler $control
    }
    $form.Add_MouseDown({ Remove-PathFocus })
}

$btnSelectC.Add_Click({
    $res = Show-CenteredFolderDialog (T 'pick_extra_folder') $global:dirC
    if ($res -ne $null) { $global:dirC = $res; Refresh-Panels; Save-Configuration }
})
$btnSelectD.Add_Click({
    $res = Show-CenteredFolderDialog (T 'pick_main_folder') $global:dirD
    if ($res -ne $null) { $global:dirD = $res; Refresh-Panels; Save-Configuration }
})

function Get-MovedSteamPath ($oldGameRoot, $newGameRoot, $oldPath) {
    if ([string]::IsNullOrWhiteSpace([string]$oldPath)) { return $null }
    $oldRoot = ([string]$oldGameRoot).TrimEnd('\')
    $candidate = [string]$oldPath
    if ($candidate.StartsWith($oldRoot + '\',[System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $candidate.Substring($oldRoot.Length).TrimStart('\')
        if ([string]::IsNullOrWhiteSpace($relative)) { return $newGameRoot }
        return Join-Path $newGameRoot $relative
    }
    if ($candidate.Equals($oldRoot,[System.StringComparison]::OrdinalIgnoreCase)) { return $newGameRoot }
    return $null
}

function Update-SteamShortcutAfterGameMove ($gameName, $oldGamePath, $newGamePath, [switch]$IsFile) {
    # Ищем ярлык ПО СТАРОМУ пути до перемещения и после переноса записываем
    # новые Exe/StartDir в shortcuts.vdf. Никаких Junction/симлинков здесь нет.
    $record = Find-SteamShortcutRecord $gameName $oldGamePath
    if ($record -eq $null) { return $false }

    if ($IsFile) {
        # ROM-ярлык: Exe — это эмулятор и не меняется, а путь к ROM-файлу лежит
        # в кавычках в LaunchOptions — подменяем его на новый. StartDir меняем
        # только если он указывал на старую папку с ROM.
        $newLaunch = [regex]::Replace([string]$record.LaunchOptions, [regex]::Escape([string]$oldGamePath), [System.Text.RegularExpressions.MatchEvaluator]{ param($m) [string]$newGamePath }, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        $oldDir = [System.IO.Path]::GetDirectoryName([string]$oldGamePath).TrimEnd('\')
        $newDir = [System.IO.Path]::GetDirectoryName([string]$newGamePath)
        $newStartRom = [string]$record.StartDir
        if ($newStartRom.Trim('"').TrimEnd('\').Equals($oldDir, [System.StringComparison]::OrdinalIgnoreCase)) { $newStartRom = $newDir }
        $resultRom = Update-ExistingSteamShortcut $record $record.AppName $record.Exe $newStartRom $newLaunch
        return (-not [string]::IsNullOrWhiteSpace([string]$resultRom))
    }

    $newExe = Get-MovedSteamPath $oldGamePath $newGamePath $record.Exe
    $newStart = Get-MovedSteamPath $oldGamePath $newGamePath $record.StartDir

    # ROM внутри папки игры (Wii U/Cemu и т.п.): Exe — эмулятор, а путь к ROM
    # в LaunchOptions начинается со старой папки игры — заменяем этот префикс.
    $launchForUpdate = [string]$record.LaunchOptions
    $romInsideFolder = $false
    if (-not [string]::IsNullOrEmpty($launchForUpdate)) {
        $oldPrefixRx = [regex]::Escape(([string]$oldGamePath).TrimEnd('\'))
        if ([regex]::IsMatch($launchForUpdate, $oldPrefixRx, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)) {
            $romInsideFolder = $true
            $newGameTrim = ([string]$newGamePath).TrimEnd('\')
            $launchForUpdate = [regex]::Replace($launchForUpdate, $oldPrefixRx, [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $newGameTrim }, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        }
    }
    if ([string]::IsNullOrWhiteSpace([string]$newExe)) {
        # На всякий случай: если EXE оказался записан в другом виде, но StartDir
        # однозначно указывает на игру, сохраняем новый каталог запуска.
        $newExe = $record.Exe
    }
    if ([string]::IsNullOrWhiteSpace([string]$newStart)) {
        # У ROM-ярлыка StartDir обычно относится к эмулятору — его не трогаем.
        $newStart = if ($romInsideFolder -and -not [string]::IsNullOrWhiteSpace([string]$record.StartDir)) { $record.StartDir } else { $newGamePath }
    }

    $result = Update-ExistingSteamShortcut $record $record.AppName $newExe $newStart $launchForUpdate
    $moveOk = (-not [string]::IsNullOrWhiteSpace([string]$result))
    if ($moveOk) {
        # Запомненная папка игры (корень поиска DLSS в библиотеке) переезжает вместе с игрой.
        try { Move-GameFolderMapEntry ([string]$record.Exe) ([string]$record.LaunchOptions) ([string]$newExe) ([string]$launchForUpdate) ([string]$newGamePath) } catch {}
    }
    return $moveOk
}

# ============================================================================
# БЕЗОПАСНЫЙ ПЕРЕНОС ИГР МЕЖДУ ПАНЕЛЯМИ (в обе стороны, с учётом свободного места)
#
# Принципы:
#  1. Игры из ОБЕИХ панелей переносятся одной операцией. Порядок строится
#     планировщиком так, чтобы сначала уходили игры с диска, на котором не
#     хватает места под игры из соседней панели, и только потом — остальные.
#  2. Данные никогда не удаляются, пока их полная копия не создана и не
#     проверена: копия -> проверка -> переименование -> удаление источника.
#  3. Копирование идёт во временную папку «<имя>.__sc_moving__». Настоящее имя
#     она получает только после успешной проверки. Если программу убили или
#     отключили свет, исходная игра цела, а недокопированный хвост легко узнать.
#  4. На целевом диске всегда остаётся запас ($script:MoveReserveBytes).
#  5. Перед КАЖДОЙ игрой свободное место измеряется заново, а оставшаяся часть
#     плана пересчитывается по реальным цифрам.
# ============================================================================
$script:MoveReserveBytes = [int64](1GB)
$script:MoveStageSuffix  = '.__sc_moving__'
$script:moveInProgress   = $false
$script:MoveCtx          = @{}

function Get-VolumeKey ([string]$path) {
    try { return ([System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($path))).ToUpperInvariant() } catch { return $null }
}

function Get-PathFreeSpace ([string]$path) {
    try {
        $root = [System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($path))
        if ($root -match '^[A-Za-z]:\\') {
            $letter = $root.Substring(0, 1)
            $di = New-Object System.IO.DriveInfo $letter
            if ($di.IsReady) { return [int64]$di.AvailableFreeSpace }
        }
    } catch {}
    return $null
}

function Format-MoveGb ([int64]$bytes) {
    return ('{0} {1}' -f [string][Math]::Round($bytes / 1GB, 2), (T 'unit_gb'))
}

# ---------------------------------------------------------------- планировщик
# Задача: Name, From ('C'|'D'), To ('C'|'D'), Size. Задача выполнима, если на
# целевом диске есть Size + запас. После выполнения место на целевом диске
# уменьшается, а на исходном — увеличивается.
function Invoke-MovePlanSimulation ([object[]]$tasks, [int64]$freeC, [int64]$freeD, [int64]$reserve, [string]$strategy) {
    $free = @{ C = [int64]$freeC; D = [int64]$freeD }
    $pending = New-Object System.Collections.ArrayList
    foreach ($t in $tasks) { [void]$pending.Add($t) }
    $order = New-Object System.Collections.ArrayList

    while ($pending.Count -gt 0) {
        $pick = $null; $pk1 = 0.0; $pk2 = 0.0
        foreach ($t in $pending) {
            if ([int64]$free[$t.To] -lt ([int64]$t.Size + $reserve)) { continue }
            # Меньший ключ = выше приоритет.
            if ($strategy -eq 'large') { $k1 = 0.0; $k2 = -[double]$t.Size }
            elseif ($strategy -eq 'small') { $k1 = 0.0; $k2 = [double]$t.Size }
            else { $k1 = [double]$free[$t.From]; $k2 = -[double]$t.Size }   # 'starved'
            if ($null -eq $pick -or $k1 -lt $pk1 -or ($k1 -eq $pk1 -and $k2 -lt $pk2)) { $pick = $t; $pk1 = $k1; $pk2 = $k2 }
        }
        if ($null -eq $pick) { break }
        $free[$pick.To]   = [int64]$free[$pick.To]   - [int64]$pick.Size
        $free[$pick.From] = [int64]$free[$pick.From] + [int64]$pick.Size
        [void]$order.Add($pick)
        [void]$pending.Remove($pick)
    }

    $bytes = [int64]0
    foreach ($t in $order) { $bytes += [int64]$t.Size }
    return [PSCustomObject]@{ Order = @($order); Left = @($pending); Free = $free; Bytes = $bytes }
}

# Стратегии:
#  starved — сначала игры с диска, где меньше всего места (освобождаем «голодный» диск),
#  large / small — запасные варианты. Берём первый полный план либо тот, что переносит больше.
function Get-MovePlan ([object[]]$tasks, [int64]$freeC, [int64]$freeD, [int64]$reserve) {
    $best = $null
    foreach ($s in @('starved', 'large', 'small')) {
        $r = Invoke-MovePlanSimulation $tasks $freeC $freeD $reserve $s
        if ($null -eq $best -or $r.Bytes -gt $best.Bytes) { $best = $r }
        if ($r.Left.Count -eq 0) { $best = $r; break }
    }
    return $best
}

# ------------------------------------------------------- вспомогательные штуки
function Set-MoveProgress ([string]$name, [int64]$bytesNow, [int64]$bytesTotal, [int]$speedMB) {
    $pct = 0
    if ($bytesTotal -gt 0) { $pct = [int][Math]::Round(($bytesNow / [double]$bytesTotal) * 100) }
    $pct = [Math]::Min(100, [Math]::Max(0, $pct))
    $progressBarFolder.Value = $pct
    $labelHeader.Text = (T 'st_copy_progress' @((T 'move_title'), $name, ([string]$speedMB), $pct))
}

# Запускает внешний процесс и не даёт окну «зависнуть» (DoEvents), возвращает код выхода.
function Invoke-ExternalPumped ([string]$file, [string]$arguments, $onTick) {
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $file; $psi.Arguments = $arguments
    $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    $proc = New-Object System.Diagnostics.Process
    $proc.StartInfo = $psi
    [void]$proc.Start()
    $lastTick = [DateTime]::MinValue
    while (-not $proc.HasExited) {
        Start-Sleep -Milliseconds 100
        [System.Windows.Forms.Application]::DoEvents()
        if ($null -ne $onTick -and ([DateTime]::Now - $lastTick).TotalMilliseconds -ge 1500) {
            $lastTick = [DateTime]::Now
            & $onTick
        }
    }
    $proc.WaitForExit()
    $code = [int]$proc.ExitCode
    $proc.Dispose()
    return $code
}

function Get-DirBytesFast ([string]$path) {
    $sum = [int64]0
    try {
        $di = New-Object System.IO.DirectoryInfo $path
        foreach ($fi in $di.EnumerateFiles('*', [System.IO.SearchOption]::AllDirectories)) { $sum += [int64]$fi.Length }
    } catch {}
    return $sum
}

# Символические ссылки/junction внутри игры: robocopy/удаление могут «пойти по ссылке»
# и затронуть чужие данные, поэтому такие папки автоматически не переносим.
function Test-FolderHasReparsePoints ([string]$path) {
    try {
        $rootDi = New-Object System.IO.DirectoryInfo $path
        if ((([int]$rootDi.Attributes) -band 0x400) -ne 0) { return $true }
        $stack = New-Object System.Collections.Stack
        $stack.Push($rootDi)
        $n = 0
        while ($stack.Count -gt 0) {
            $d = $stack.Pop()
            foreach ($e in $d.EnumerateFileSystemInfos()) {
                if ((([int]$e.Attributes) -band 0x400) -ne 0) { return $true }
                if ($e -is [System.IO.DirectoryInfo]) { $stack.Push($e) }
                $n++
                if (($n % 3000) -eq 0) { [System.Windows.Forms.Application]::DoEvents() }
            }
        }
    } catch { return $true }   # не смогли прочитать — считаем небезопасным
    return $false
}

# Сверка копии с оригиналом: тот же набор относительных путей файлов, те же размеры,
# то же число папок. Любая ошибка чтения = «не совпало» (источник при этом не удаляется).
function Test-FolderCopyMatches ([string]$src, [string]$dst) {
    try {
        $sd = New-Object System.IO.DirectoryInfo $src
        $dd = New-Object System.IO.DirectoryInfo $dst
        $sp = $sd.FullName.TrimEnd('\') + '\'
        $dp = $dd.FullName.TrimEnd('\') + '\'
        $map = @{}
        $n = 0
        foreach ($fi in $sd.EnumerateFiles('*', [System.IO.SearchOption]::AllDirectories)) {
            $map[$fi.FullName.Substring($sp.Length)] = [int64]$fi.Length
            $n++
            if (($n % 2000) -eq 0) { [System.Windows.Forms.Application]::DoEvents() }
        }
        $cnt = 0
        foreach ($fi in $dd.EnumerateFiles('*', [System.IO.SearchOption]::AllDirectories)) {
            $rel = $fi.FullName.Substring($dp.Length)
            if (-not $map.ContainsKey($rel)) { return $false }
            if ([int64]$map[$rel] -ne [int64]$fi.Length) { return $false }
            $cnt++
            if (($cnt % 2000) -eq 0) { [System.Windows.Forms.Application]::DoEvents() }
        }
        if ($cnt -ne $map.Count) { return $false }
        $sdirs = 0; foreach ($x in $sd.EnumerateDirectories('*', [System.IO.SearchOption]::AllDirectories)) { $sdirs++ }
        $ddirs = 0; foreach ($x in $dd.EnumerateDirectories('*', [System.IO.SearchOption]::AllDirectories)) { $ddirs++ }
        return ($sdirs -eq $ddirs)
    } catch { return $false }
}

# Быстрое удаление папки (cmd rd — на порядок быстрее Remove-Item на десятках тысяч файлов),
# окно при этом не зависает. Бросает исключение, если что-то осталось.
function Remove-GamePathPumped ([string]$path) {
    if (-not (Test-Path -LiteralPath $path)) { return }
    if (Test-Path -LiteralPath $path -PathType Leaf) {
        try { [System.IO.File]::SetAttributes($path, [System.IO.FileAttributes]::Normal) } catch {}
        [System.IO.File]::Delete($path)
        return
    }
    if ($path.Contains('%')) {
        # '%' в пути cmd мог бы раскрыть как переменную окружения — используем PowerShell.
        Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop
    } else {
        [void](Invoke-ExternalPumped 'cmd.exe' ('/c rd /s /q "{0}"' -f $path) $null)
    }
    if (Test-Path -LiteralPath $path) { throw (New-Object System.IO.IOException(('Not fully removed: ' + $path))) }
}

# Переименование с повторами: сразу после копирования десятков тысяч файлов антивирус или
# индексатор могут на секунду-другую удерживать дескрипторы, и Directory.Move кратко падает.
function Move-PathWithRetry ([string]$from, [string]$to, [bool]$isFile) {
    $lastErr = $null
    for ($i = 1; $i -le 8; $i++) {
        try {
            if ($isFile) { [System.IO.File]::Move($from, $to) } else { [System.IO.Directory]::Move($from, $to) }
            return
        } catch {
            $lastErr = $_
            for ($w = 0; $w -lt 10; $w++) { Start-Sleep -Milliseconds 100; [System.Windows.Forms.Application]::DoEvents() }
        }
    }
    throw $lastErr
}

function Copy-GameFolderStaged ($item, [string]$stage, [int64]$base, [int64]$total) {
    $stageParent = [System.IO.Path]::GetDirectoryName($stage.TrimEnd('\'))
    $targetParent = [System.IO.Path]::GetDirectoryName($item.TargetPath.TrimEnd('\'))
    # /MIR применяется ТОЛЬКО к нашей временной папке (она же даёт возобновление после обрыва).
    if (-not $stage.EndsWith($script:MoveStageSuffix) -or -not $stageParent.Equals($targetParent, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw (T 'mv_move_fail' @([string]$item.Name))
    }
    $script:MoveCtx = @{ Name = $item.Name; Stage = $stage; Base = $base; Total = $total; LastBytes = [int64]0; LastTime = [DateTime]::Now }
    $rcArgs = '"{0}" "{1}" /MIR /COPY:DAT /DCOPY:DAT /XJ /R:2 /W:2 /MT:6 /BYTES /NJH /NJS /NC /NFL /NDL /NP' -f $item.SourcePath, $stage
    $tick = {
        $c = $script:MoveCtx
        $cur = Get-DirBytesFast $c.Stage
        $now = [DateTime]::Now
        $dt = ($now - $c.LastTime).TotalSeconds
        $speed = 0
        if ($dt -gt 0 -and $cur -ge $c.LastBytes) { $speed = [int][Math]::Round((($cur - $c.LastBytes) / 1MB) / $dt) }
        $c.LastBytes = $cur; $c.LastTime = $now
        Set-MoveProgress $c.Name ([int64]$c.Base + $cur) $c.Total $speed
    }
    $code = Invoke-ExternalPumped 'robocopy.exe' $rcArgs $tick
    # Коды robocopy 0..7 — успех (в т.ч. «ничего не копировалось»), 8 и выше — ошибки.
    if ($code -ge 8) { throw (T 'mv2_copy_fail' @([string]$item.Name, [string]$code)) }

    $labelHeader.Text = (T 'mv2_phase_verify' @((T 'move_title'), $item.Name))
    [System.Windows.Forms.Application]::DoEvents()
    if (-not (Test-FolderCopyMatches $item.SourcePath $stage)) { throw (T 'mv2_verify_fail' @([string]$item.Name)) }
}

function Copy-GameFileStaged ($item, [string]$stage, [int64]$base, [int64]$total) {
    $srcInfo = New-Object System.IO.FileInfo $item.SourcePath
    $fileLen = [int64]$srcInfo.Length
    $inS = $null; $outS = $null
    try {
        $inS = New-Object System.IO.FileStream($item.SourcePath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read, 1048576)
        $outS = New-Object System.IO.FileStream($stage, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 1048576)
        $buf = New-Object byte[] 1048576
        $copied = [int64]0; $lastTick = [DateTime]::Now; $lastBytes = [int64]0
        while (($n = $inS.Read($buf, 0, $buf.Length)) -gt 0) {
            $outS.Write($buf, 0, $n)
            $copied += $n
            $now = [DateTime]::Now
            $dt = ($now - $lastTick).TotalSeconds
            if ($dt -ge 0.25) {
                $speed = [int][Math]::Round((($copied - $lastBytes) / 1MB) / $dt)
                $lastTick = $now; $lastBytes = $copied
                Set-MoveProgress $item.Name ($base + $copied) $total $speed
                [System.Windows.Forms.Application]::DoEvents()
            }
        }
        $outS.Flush()
    } finally {
        if ($null -ne $outS) { $outS.Dispose() }
        if ($null -ne $inS) { $inS.Dispose() }
    }
    try {
        [System.IO.File]::SetCreationTime($stage, $srcInfo.CreationTime)
        [System.IO.File]::SetLastWriteTime($stage, $srcInfo.LastWriteTime)
    } catch {}
    if ([int64](New-Object System.IO.FileInfo $stage).Length -ne $fileLen) { throw (T 'mv2_verify_fail' @([string]$item.Name)) }
}

# Перенос одной игры/ROM. Любая ошибка ДО этапа удаления оставляет исходные данные нетронутыми.
# Нефатальные проблемы (путь в Steam, остаток исходной папки) попадают в $warnings.
function Invoke-SafeGameMove ($item, [bool]$sameVolume, [int64]$base, [int64]$total, $warnings) {
    $src = [string]$item.SourcePath
    $dst = [string]$item.TargetPath
    $stage = $dst + $script:MoveStageSuffix
    if (Test-Path -LiteralPath $dst) { throw (T 'mv_target_exists' @([string]$item.Name)) }

    if ($sameVolume) {
        # Тот же том: «перенос» — мгновенное атомарное переименование, данные не копируются.
        Move-PathWithRetry $src $dst ([bool]$item.IsFile)
    } else {
        try {
            if ($item.IsFile) { Copy-GameFileStaged $item $stage $base $total }
            else { Copy-GameFolderStaged $item $stage $base $total }
            # Фиксация: временное имя -> настоящее (переименование в пределах одного тома).
            Move-PathWithRetry $stage $dst ([bool]$item.IsFile)
        } catch {
            # Неудачную копию убираем (она занимает место на и так тесном диске); источник не трогали.
            try { Remove-GamePathPumped $stage } catch {}
            throw
        }
    }
    $targetType = if ($item.IsFile) { 'Leaf' } else { 'Container' }
    if (-not (Test-Path -LiteralPath $dst -PathType $targetType)) { throw (T 'mv_move_fail' @([string]$item.Name)) }

    # Путь в Steam обновляем, пока исходные данные ещё лежат на месте.
    try {
        [void](Update-SteamShortcutAfterGameMove $item.Name $src $dst -IsFile:$item.IsFile)
    } catch {
        [void]$warnings.Add((T 'mv_steam_path_fail' @([string]$item.Name, [string]$_.Exception.Message)))
    }

    # Только теперь, когда копия проверена и закреплена под настоящим именем, удаляем источник.
    if (-not $sameVolume) {
        $labelHeader.Text = (T 'mv2_phase_cleanup' @((T 'move_title'), $item.Name))
        [System.Windows.Forms.Application]::DoEvents()
        try { Remove-GamePathPumped $src }
        catch { [void]$warnings.Add((T 'mv_src_not_removed' @($src))) }
    }
    Set-MoveProgress $item.Name ($base + [int64]$item.Size) $total 0
}

function Move-SelectedGames($source) {
    # Обе панели равноправны. Переносятся ВСЕ отмеченные игры: отмеченные слева уходят вправо,
    # отмеченные справа — влево. $source (панель в фокусе) оставлен для совместимости вызова.
    $namesC = @($global:checkedC.Keys)
    $namesD = @($global:checkedD.Keys)
    if ($namesC.Count -eq 0 -and $namesD.Count -eq 0) {
        $labelHeader.Text = (T 'st_move_first')
        return
    }
    $reserve = [int64]$script:MoveReserveBytes

    $btnMoveGame.Enabled = $false
    $btnRefreshLibrary.Enabled = $false
    $btnAddToSteam.Enabled = $false

    $steamWasRunning = $false; $steamClosed = $false
    try { $steamWasRunning = @(Get-Process -Name steam -ErrorAction SilentlyContinue).Count -gt 0 } catch {}
    $steamPathProperty = Get-ConfiguredSteamExePath
    $executed = $false
    $script:moveInProgress = $true

    try {
        foreach ($r in @($global:dirC, $global:dirD)) {
            if ([string]::IsNullOrWhiteSpace($r) -or -not (Test-Path -LiteralPath $r -PathType Container)) {
                throw (T $(if ($r -eq $global:dirC) { 'mv_no_source' } else { 'mv_no_target' }))
            }
        }
        if ([System.IO.Path]::GetFullPath($global:dirC).TrimEnd('\').Equals([System.IO.Path]::GetFullPath($global:dirD).TrimEnd('\'), [System.StringComparison]::OrdinalIgnoreCase)) {
            throw (T 'mv_same')
        }
        $sameVolume = ((Get-VolumeKey $global:dirC) -eq (Get-VolumeKey $global:dirD))

        # ---- 1. Задачи из обеих панелей + проверки до начала любых действий -------------
        $labelHeader.Text = (T 'mv2_scanning')
        [System.Windows.Forms.Application]::DoEvents()
        $tasks = New-Object System.Collections.ArrayList
        $skipped = New-Object System.Collections.ArrayList
        foreach ($side in @('C', 'D')) {
            $names = if ($side -eq 'C') { $namesC } else { $namesD }
            $toSide = if ($side -eq 'C') { 'D' } else { 'C' }
            $fromRoot = if ($side -eq 'C') { $global:dirC } else { $global:dirD }
            $toRoot = if ($side -eq 'C') { $global:dirD } else { $global:dirC }
            foreach ($text in @($names | Sort-Object)) {
                $name = Clean-GameName $text
                $sp = Join-Path $fromRoot $name
                $tp = Join-Path $toRoot $name
                $isFile = Test-Path -LiteralPath $sp -PathType Leaf
                if (-not $isFile -and -not (Test-Path -LiteralPath $sp -PathType Container)) {
                    [void]$skipped.Add([PSCustomObject]@{ Name = $name; Reason = (T 'mv_src_missing' @([string]$sp)) }); continue
                }
                if (Test-Path -LiteralPath $tp) {
                    [void]$skipped.Add([PSCustomObject]@{ Name = $name; Reason = (T 'mv_target_exists' @([string]$name)) }); continue
                }
                if (-not $isFile -and (Test-FolderHasReparsePoints $sp)) {
                    [void]$skipped.Add([PSCustomObject]@{ Name = $name; Reason = (T 'mv2_reparse') }); continue
                }
                $size = if ($isFile) { [int64](Get-Item -LiteralPath $sp).Length } else { [int64](Get-FolderSize $sp) }
                [void]$tasks.Add([PSCustomObject]@{ Name = $name; From = $side; To = $toSide; SourcePath = $sp; TargetPath = $tp; Size = [int64]$size; IsFile = $isFile })
            }
        }

        # ---- 2. План: кто первым освобождает место --------------------------------------
        if ($sameVolume) {
            # Один том: перенос = переименование, место не нужно, порядок не важен.
            $plan = [PSCustomObject]@{ Order = @($tasks); Left = @(); Free = @{ C = 0; D = 0 }; Bytes = 0 }
        } else {
            $freeC = Get-PathFreeSpace $global:dirC
            $freeD = Get-PathFreeSpace $global:dirD
            if ($null -eq $freeC) { throw (T 'mv2_free_unknown' @([string]$global:dirC)) }
            if ($null -eq $freeD) { throw (T 'mv2_free_unknown' @([string]$global:dirD)) }
            $plan = Get-MovePlan @($tasks) $freeC $freeD $reserve
            foreach ($t in $plan.Left) {
                $need = [int64]($t.Size + $reserve - [int64]$plan.Free[$t.To])
                $toRootText = if ($t.To -eq 'C') { $global:dirC } else { $global:dirD }
                [void]$skipped.Add([PSCustomObject]@{ Name = $t.Name; Reason = (T 'mv2_need_space' @((Format-MoveGb $need), [System.IO.Path]::GetPathRoot($toRootText))) })
            }
        }
        $totalSelected = $plan.Order.Count + $skipped.Count

        if ($skipped.Count -gt 0) {
            $lines = (@($skipped | Select-Object -First 8 | ForEach-Object { '• {0} — {1}' -f $_.Name, $_.Reason }) -join "`n")
            if ($skipped.Count -gt 8) { $lines += "`n…" }
            if ($plan.Order.Count -eq 0) {
                Show-AppMessageBox(((T 'mv2_none') + "`n`n" + $lines), $global:appTitle,
                    [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
                $labelHeader.Text = $global:mainHintText
                return
            }
            $answer = Show-AppMessageBox(((T 'mv2_partial' @($plan.Order.Count, $totalSelected)) + "`n`n" + $lines + "`n`n" + (T 'mv2_continue')),
                $global:appTitle, [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
            if ($answer -ne [System.Windows.Forms.DialogResult]::Yes) { $labelHeader.Text = $global:mainHintText; return }
        }

        # ---- 3. Выполнение ---------------------------------------------------------------
        $executed = $true
        # Steam закрываем на время правки shortcuts.vdf, чтобы клиент не перезаписал файл.
        if ($steamWasRunning) {
            taskkill.exe /F /T /IM steam.exe 2>$null | Out-Null
            $steamClosed = $true
            Start-Sleep -Seconds 2
        }
        $aggregateTotal = [int64]0
        foreach ($t in $plan.Order) { $aggregateTotal += [int64]$t.Size }
        if ($aggregateTotal -lt 1) { $aggregateTotal = 1 }
        $doneBytes = [int64]0
        $progressBarFolder.Value = 0

        $pending = New-Object System.Collections.ArrayList
        foreach ($t in $plan.Order) { [void]$pending.Add($t) }
        $done = New-Object System.Collections.ArrayList
        $stalled = New-Object System.Collections.ArrayList
        $warnings = New-Object System.Collections.ArrayList
        $failure = $null

        while ($pending.Count -gt 0) {
            $next = $null
            if ($sameVolume) {
                $next = $pending[0]
            } else {
                # Реальное свободное место на момент КАЖДОГО шага + пересчёт оставшегося плана.
                $p = Get-MovePlan @($pending) (Get-PathFreeSpace $global:dirC) (Get-PathFreeSpace $global:dirD) $reserve
                if ($p.Order.Count -gt 0) { $next = $p.Order[0] }
            }
            if ($null -eq $next) {
                foreach ($t in $pending) { [void]$stalled.Add($t) }
                break
            }
            [void]$pending.Remove($next)
            try {
                Invoke-SafeGameMove $next $sameVolume $doneBytes $aggregateTotal $warnings
                [void]$done.Add($next)
                $doneBytes += [int64]$next.Size
            } catch {
                # При любой ошибке останавливаем пакет: не продолжаем писать на возможно неисправный диск.
                $failure = [PSCustomObject]@{ Name = $next.Name; Message = [string]$_.Exception.Message }
                foreach ($t in $pending) { [void]$stalled.Add($t) }
                break
            }
        }

        # ---- 4. Итог ---------------------------------------------------------------------
        foreach ($t in $done) {
            $set = if ($t.From -eq 'C') { $global:checkedC } else { $global:checkedD }
            foreach ($k in @($set.Keys)) { if ((Clean-GameName ([string]$k)) -eq $t.Name) { [void]$set.Remove($k) } }
        }
        $problems = New-Object System.Collections.ArrayList
        if ($null -ne $failure) { [void]$problems.Add(('• {0} — {1}' -f $failure.Name, $failure.Message)) }
        $stalledKey = if ($null -ne $failure) { 'mv2_stopped' } else { 'mv2_stalled' }
        foreach ($t in $stalled) { [void]$problems.Add(('• {0} — {1}' -f $t.Name, (T $stalledKey))) }
        foreach ($s in $skipped) { [void]$problems.Add(('• {0} — {1}' -f $s.Name, $s.Reason)) }
        foreach ($w in $warnings) { [void]$problems.Add(('• ' + $w)) }

        $progressBarFolder.Value = 100
        $labelHeader.Text = (T 'mv_done' @($done.Count, $totalSelected))
        [System.Windows.Forms.Application]::DoEvents()
        if ($problems.Count -eq 0) {
            Start-Sleep -Milliseconds 400
            $progressBarFolder.Value = 0
            $labelHeader.Text = $global:mainHintText
            [System.Media.SystemSounds]::Asterisk.Play()
        } else {
            $progressBarFolder.Value = 0
            Show-AppMessageBox(((T 'mv2_summary') + "`n`n" + ($problems -join "`n")), $global:appTitle,
                [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
        }
    } catch {
        $labelHeader.Text = (T 'mv_error' @([string]$_.Exception.Message))
    } finally {
        $script:moveInProgress = $false
        if ($steamClosed -and -not [string]::IsNullOrWhiteSpace($steamPathProperty) -and (Test-Path $steamPathProperty)) {
            try { Start-Process -FilePath $steamPathProperty } catch {}
        }
        $btnMoveGame.Enabled = $true
        $btnRefreshLibrary.Enabled = $true
        $btnAddToSteam.Enabled = $true
        if ($executed) { Refresh-Panels } else { try { Update-MainLibraryButtonState } catch {} }
    }
}

$listBoxC.Add_Enter({ $global:lastFocusedPanel = 'C' })
$listBoxD.Add_Enter({ $global:lastFocusedPanel = 'D' })
$listBoxC.Add_MouseDown({ $global:lastFocusedPanel = 'C' })
$listBoxD.Add_MouseDown({ $global:lastFocusedPanel = 'D' })

$btnMoveGame.Add_Click({
    Move-SelectedGames $global:lastFocusedPanel
})

$btnRefreshLibrary.Add_Click({
    if (-not $btnRefreshLibrary.Enabled) { return }
    $btnRefreshLibrary.Enabled = $false
    $btnMoveGame.Enabled = $false
    $btnAddToSteam.Enabled = $false
    try {
        $labelHeader.Text = (T 'st_refresh_start')
        [System.Windows.Forms.Application]::DoEvents()
        $global:hiddenGames.Clear()
        # Размеры могли устареть (папку могли перенести/удалить/докачать) —
        # на явном "Обновить" пересчитываем их заново при следующей сортировке.
        $global:folderSizeCache.Clear()
        # Прогретые данные библиотеки (записи Steam и лаунчеры) тоже сбрасываем — Refresh-Panels ниже запустит новый прогрев.
        try { Reset-LibPreheat } catch {}
        # Явное "Обновить" — это полный пересчёт библиотеки с нуля, поэтому,
        # в отличие от закрытия карточки игры, тут отмеченные галочки тоже
        # сбрасываются намеренно.
        $global:checkedC.Clear(); $global:checkedD.Clear()
        Refresh-Panels
        $labelHeader.Text = (T 'st_refresh_done')
    } catch {
        $labelHeader.Text = (T 'st_refresh_err' @($_.Exception.Message))
    } finally {
        $btnRefreshLibrary.Enabled = $true
        # РАНЬШЕ здесь было безусловное $btnMoveGame.Enabled = $true /
        # $btnAddToSteam.Enabled = $true — из-за этого кнопка "Перенести игру"
        # включалась даже сразу после обновления, когда выше по коду все
        # галочки были явно сброшены ($global:checkedC.Clear() и т.д.) и
        # Refresh-Panels/Update-MainLibraryButtonState уже корректно её
        # выключили. Пересчитываем состояние заново по реальному количеству
        # отмеченных игр, вместо того чтобы включать кнопки вслепую.
        try { Update-MainLibraryButtonState } catch { $btnMoveGame.Enabled = $true; $btnAddToSteam.Enabled = $true }
    }
})


# Кнопка "Перенести игру" активна, как только отмечена хотя бы одна галочка
# в текущей панели. Кнопка "Добавить" на главном экране теперь скрыта по
# умолчанию — карточка одной игры открывается прямым кликом по ней, а эта
# кнопка появляется только для ПАКЕТНОГО добавления, когда отмечено 2+ игры.
# Пока идёт пакетное добавление (batchInProgress), кнопка занята под "Отменить" —
# её текст/видимость в этот момент не трогаем.
# Перерисовывает подписи главного окна после смены языка в «Настройках».
# Заголовки панелей и статусы с подстановками пересобирает Refresh-Panels,
# который вызывается сразу после сохранения настроек.
function Apply-Localization {
    $prevHint = [string]$global:mainHintText
    $global:mainHintText = (T 'hint_main')
    try { if ([string]$labelHeader.Text -eq $prevHint) { $labelHeader.Text = $global:mainHintText } } catch {}
    try {
        Set-BrowseIconTip $btnSelectC
        Set-BrowseIconTip $btnSelectD
        Set-TextBoxCue $txtSearchC (T 'search_cue')
        Set-TextBoxCue $txtSearchD (T 'search_cue')
        $lblEmptyD.Text = (T 'empty_main')
        $btnMoveGame.Text = (T 'btn_move')
        $btnRefreshLibrary.Text = (T 'btn_refresh')
        $lblBatchAuto.Text = (T 'batch_auto')
        $batchAutoTooltipText = (T 'batch_auto_tip')
        $mainToolTip.SetToolTip($pnlBatchToggle, $batchAutoTooltipText)
        $mainToolTip.SetToolTip($lblBatchAuto, $batchAutoTooltipText)
        foreach ($hs in @('C','D')) {
            $mainToolTip.SetToolTip($script:headerParts[$hs].Cb, (T 'tip_select_all'))
            $mainToolTip.SetToolTip($script:headerParts[$hs].Labels['Library'], (T 'tip_lib_header'))
        }
        $btnSettings.AccessibleName = (T 'settings_title')
        $btnSettings.AccessibleDescription = (T 'settings_desc')
        $btnAddToSteam.Tag = (T 'btn_add_batch')
$btnAddToSteam.Text = ''
        $btnSteamLibrary.Tag = (T 'btn_steam_library')
    } catch {}
    try {
        $lblRomsMode.Text = (T 'rom_mode')
        $romsModeTooltipText = (T 'rom_mode_tip')
        $mainToolTip.SetToolTip($pnlRomsToggle, $romsModeTooltipText)
        $mainToolTip.SetToolTip($lblRomsMode, $romsModeTooltipText)
        $mainToolTip.SetToolTip($cmbMainCore, (T 'rom_core_tip'))
        foreach ($romCtl in @($pnlRomIndicator, $picRomEmulatorIcon, $lblRomEmulatorName)) { $mainToolTip.SetToolTip($romCtl, (T 'rom_emu_pick_tip')) }
        $script:mainCorePlaceholderText = (T 'core_choose')
        Update-RomEmulatorIndicator
    } catch {}
    try { Update-SortHeaderUI 'C'; Update-SortHeaderUI 'D' } catch {}
    try { Update-MainLibraryButtonState } catch {}
    try { $listBoxC.Invalidate(); $listBoxD.Invalidate() } catch {}
}

function Update-MainLibraryButtonState {
    # Галочка "выбрать всё" над списками обновляется при любом изменении отметок.
    try { Update-SelectAllCheckbox 'C'; Update-SelectAllCheckbox 'D' } catch {}
    try {
        if ($script:batchInProgress) { return }

        # Общее количество отмеченных используется для кнопки "Перенести игру".
        # Для "Добавить в библиотеку" считаем только те игры, которых ещё нет
        # в Steam. Именно это поведение было в рабочей версии до правок кнопки.
        $totalChecked = [int]$global:checkedC.Count + [int]$global:checkedD.Count
        $ready = [bool]$global:foldersReady
        $btnMoveGame.Enabled = ($ready -and $totalChecked -ge 1)

        $addableCount = 0
        if ($ready -and $totalChecked -ge 1) {
            foreach ($game in @(Get-CheckedGames)) {
                $key = Get-NormalizedGamePathKey $game.Path
                if (-not ($key -and $global:installedSteamGames.ContainsKey($key))) {
                    $addableCount++
                }
            }
        }

        if ($ready -and $totalChecked -ge 1 -and $addableCount -ge 1) {
            $btnAddToSteam.Tag = (T 'btn_add_batch_n' @($addableCount))
            $btnAddToSteam.Visible = $true
            $btnAddToSteam.Enabled = $true
            $btnSteamLibrary.Visible = $false
        } else {
            # Если отмечены только игры, которые уже есть в Steam, кнопки
            # добавления вообще быть не должно — показываем библиотеку.
            $btnAddToSteam.Visible = $false
            $btnSteamLibrary.Visible = $true
            $btnSteamLibrary.Enabled = $true
            $btnSteamLibrary.Tag = (T 'btn_steam_library')
        }

        try { $btnAddToSteam.Invalidate(); $btnSteamLibrary.Invalidate() } catch {}
    } catch {
        try { $btnAddToSteam.Visible = $false; $btnSteamLibrary.Visible = $true } catch {}
    }
}

function Get-ListGameContext($listBox, $source) {
    if($listBox.SelectedItem -eq $null){return $null}
    $displayName=[string]$listBox.SelectedItem.ToString()
    $root=if($source -eq 'C'){$global:dirC}else{$global:dirD}
    $path=Join-Path $root $displayName
    $isLeaf = $false
    try { $isLeaf = Test-Path -LiteralPath $path -PathType Leaf } catch {}
    if ($isLeaf -or $script:romsModeEnabled) {
        $name = Get-RomFileTitle $displayName
        if ([string]::IsNullOrWhiteSpace($name)) { $name = Clean-GameName $displayName }
    } else {
        $name = Clean-GameName $displayName
    }
    return [PSCustomObject]@{Name=$name;Source=$source;Path=$path}
}

function Show-SelectedGameCard($listBox, $source) {
    $ctx=Get-ListGameContext $listBox $source
    if($ctx -eq $null){return}
    Show-GameEditorDialog $ctx.Name $ctx.Source $ctx.Path -IsRomEntry:$script:romsModeEnabled
}

function Show-SelectedGameSize($listBox, $source) {
    # Space при отмеченных играх считает размеры В ОБЕИХ панелях и сразу
    # сверяет с свободным местом: тот же планировщик, что у «Перенести игру».
    # Отметки только слева → размер vs место справа; только справа → vs место
    # слева; в обеих → общий план (взаимное освобождение места учитывается).
    $namesC = @($global:checkedC.Keys)
    $namesD = @($global:checkedD.Keys)
    $hasChecked = ($namesC.Count -gt 0 -or $namesD.Count -gt 0)

    if (-not $hasChecked) {
        $ctx = Get-ListGameContext $listBox $source
        if ($ctx -eq $null) { return }
        $size = Get-FolderSize $ctx.Path
        $global:folderSizeCache[$ctx.Path.ToLowerInvariant()] = $size
        $listBox.Invalidate()
        Set-MainStatusWithBadge (T 'st_size_one' @($ctx.Name, ([string][Math]::Round($size / 1GB, 2)), (T 'unit_gb'))) $null
        return
    }

    $tasks = New-Object System.Collections.ArrayList
    $totalBytes = [int64]0
    $allNames = New-Object System.Collections.ArrayList
    foreach ($n in $namesC) { [void]$allNames.Add([PSCustomObject]@{ Name = $n; Side = 'C' }) }
    foreach ($n in $namesD) { [void]$allNames.Add([PSCustomObject]@{ Name = $n; Side = 'D' }) }
    $totalCount = $allNames.Count
    $i = 0
    foreach ($entry in $allNames) {
        $i++
        $name = [string]$entry.Name
        $side = [string]$entry.Side
        $root = if ($side -eq 'C') { $global:dirC } else { $global:dirD }
        $path = Join-Path $root $name
        $labelHeader.Text = (T 'st_sizes_checked' @($name, $i, $totalCount))
        [System.Windows.Forms.Application]::DoEvents()
        $isFile = $false
        try { $isFile = Test-Path -LiteralPath $path -PathType Leaf } catch {}
        $size = [int64]0
        if ($isFile) {
            try { $size = [int64](Get-Item -LiteralPath $path).Length } catch { $size = 0 }
        } else {
            $size = [int64](Get-FolderSize $path)
            $global:folderSizeCache[$path.ToLowerInvariant()] = $size
        }
        $totalBytes += $size
        $toSide = if ($side -eq 'C') { 'D' } else { 'C' }
        [void]$tasks.Add([PSCustomObject]@{
            Name = $name; From = $side; To = $toSide; Size = $size
        })
    }
    try { $listBoxC.Invalidate(); $listBoxD.Invalidate() } catch { $listBox.Invalidate() }

    $sizeText = Format-MoveGb $totalBytes
    $countText = [string]$totalCount

    # Папки не заданы / один и тот же том — место не нужно.
    $sameVolume = $false
    try {
        if (-not [string]::IsNullOrWhiteSpace($global:dirC) -and -not [string]::IsNullOrWhiteSpace($global:dirD)) {
            $sameVolume = ((Get-VolumeKey $global:dirC) -eq (Get-VolumeKey $global:dirD))
        }
    } catch {}

    if ($sameVolume) {
        Set-MainStatusWithBadge (T 'st_move_same' @($countText, $sizeText)) $true
        return
    }

    $freeC = Get-PathFreeSpace $global:dirC
    $freeD = Get-PathFreeSpace $global:dirD
    if ($null -eq $freeC -or $null -eq $freeD) {
        Set-MainStatusWithBadge (T 'st_move_free_unknown') $false
        return
    }

    $reserve = [int64]$script:MoveReserveBytes
    $plan = Get-MovePlan @($tasks) $freeC $freeD $reserve
    $canCount = @($plan.Order).Count
    $leftCount = @($plan.Left).Count

    if ($leftCount -eq 0) {
        Set-MainStatusWithBadge (T 'st_move_ok' @($countText, $sizeText)) $true
        return
    }

    if ($canCount -eq 0) {
        # Ни одну не влезает — сколько ещё нужно для самой «тяжёлой» из оставшихся.
        $needExtra = [int64]0
        foreach ($t in @($plan.Left)) {
            $avail = [int64]$plan.Free[$t.To]
            $need = [int64]($t.Size + $reserve - $avail)
            if ($need -gt $needExtra) { $needExtra = $need }
        }
        if ($needExtra -lt 0) { $needExtra = 0 }
        Set-MainStatusWithBadge (T 'st_move_none' @((Format-MoveGb $needExtra))) $false
        return
    }

    $canBytes = [int64]$plan.Bytes
    Set-MainStatusWithBadge (T 'st_move_partial' @($canCount, $totalCount, (Format-MoveGb $canBytes))) $false
}

# Alt+Shift+Enter — считает размер ВСЕХ папок активной панели (не только
# отфильтрованных текущим поиском — весь набор данных панели) и показывает
# итог. Переиспользует тот же кэш и ту же функцию с прогресс-баром, которой
# уже пользуется сортировка "по размеру".
function Show-PanelFolderSizes ([string]$source) {
    $data = if ($source -eq 'C') { $script:panelDataC } else { $script:panelDataD }
    $listBox = if ($source -eq 'C') { $listBoxC } else { $listBoxD }
    if (@($data).Count -eq 0) { return }
    Ensure-FolderSizesCached $data
    $total = [int64]0
    foreach ($it in $data) {
        $s = Get-FolderSizeCached $it.Path
        if ($s -ge 0) { $total += $s }
    }
    $listBox.Invalidate()
    $labelHeader.Text = (T 'st_panel_sizes' @($data.Count, ([string][Math]::Round($total / 1GB, 2)), (T 'unit_gb')))
}

# Единый обработчик клика по строке для ОБЕИХ панелей: попадание в квадратик
# галочки — переключает отметку (для «Перенести»/«Добавить несколько»),
# любое другое место строки — только выделяет её. Карточка игры по одиночному
# клику больше НЕ открывается — см. Invoke-GamePanelDoubleClick (двойной клик)
# и Invoke-GamePanelKey (Enter).
# Shift + щелчок — диапазонное выделение, как в проводнике: от "якоря" (строки,
# по которой щёлкнули последний раз) до строки под курсором включительно все
# строки получают одну и ту же отметку. Якорь запоминается отдельно для каждой
# панели: щелчок по галочке ставит якорь с новым состоянием этой галочки
# (поставили — диапазон отметится, сняли — диапазон очистится), обычный щелчок
# по строке ставит якорь с состоянием "отметить". Shift+щелчок работает и по
# галочке, и по любому другому месту строки; сам якорь при этом не сдвигается,
# чтобы можно было менять границу диапазона повторными Shift+щелчками.
if (-not $script:panelClickAnchor) {
    $script:panelClickAnchor = @{
        C = [PSCustomObject]@{ Index = -1; State = $true }
        D = [PSCustomObject]@{ Index = -1; State = $true }
    }
}

function Invoke-GamePanelClick($listBox, $source, $e) {
    $idx = $listBox.IndexFromPoint($e.Location)
    if ($idx -lt 0 -or $idx -ge $listBox.Items.Count) { return }
    $itemBounds = $listBox.GetItemRectangle($idx)
    $cbRect = Get-RowCheckboxHitRect $itemBounds
    $checkedSet = Get-CheckedSet $source
    $anchor = $script:panelClickAnchor[$source]
    $shiftDown = (([System.Windows.Forms.Control]::ModifierKeys -band [System.Windows.Forms.Keys]::Shift) -eq [System.Windows.Forms.Keys]::Shift)

    if ($shiftDown) {
        $from = [int]$anchor.Index
        if ($from -lt 0 -or $from -ge $listBox.Items.Count) {
            # Якоря ещё нет (или список изменился) — берём текущую выделенную строку.
            $from = if ($listBox.SelectedIndex -ge 0) { [int]$listBox.SelectedIndex } else { $idx }
            $anchor.State = $true
        }
        $lo = [Math]::Min($from, $idx)
        $hi = [Math]::Max($from, $idx)
        $state = [bool]$anchor.State
        for ($i = $lo; $i -le $hi; $i++) {
            $n = Clean-GameName $listBox.Items[$i].ToString()
            if ($state) { $checkedSet[$n] = $true } else { $checkedSet.Remove($n) | Out-Null }
        }
        $anchor.Index = $from
        $listBox.SelectedIndex = $idx
        $listBox.Invalidate()
        Update-MainLibraryButtonState
        return
    }

    if ($cbRect.Contains($e.Location)) {
        $name = Clean-GameName $listBox.Items[$idx].ToString()
        if ($checkedSet.ContainsKey($name)) { $checkedSet.Remove($name) | Out-Null; $anchor.State = $false } else { $checkedSet[$name] = $true; $anchor.State = $true }
        $anchor.Index = $idx
        $listBox.Invalidate($itemBounds)
        Update-MainLibraryButtonState
        return
    }
    $anchor.Index = $idx
    $anchor.State = $true
    $listBox.SelectedIndex = $idx
}
$listBoxC.Add_MouseClick({ Invoke-GamePanelClick $listBoxC 'C' $_ })
$listBoxD.Add_MouseClick({ Invoke-GamePanelClick $listBoxD 'D' $_ })

# Двойной клик по строке (вне квадратика галочки) — открывает карточку игры.
# Двойной клик по самому квадратику галочки карточку не открывает: два
# щелчка по нему — это просто снять-поставить отметку дважды подряд.
function Invoke-GamePanelDoubleClick($listBox, $source, $e) {
    $idx = $listBox.IndexFromPoint($e.Location)
    if ($idx -lt 0 -or $idx -ge $listBox.Items.Count) { return }
    $itemBounds = $listBox.GetItemRectangle($idx)
    $cbRect = Get-RowCheckboxHitRect $itemBounds
    if ($cbRect.Contains($e.Location)) { return }
    $listBox.SelectedIndex = $idx
    Show-SelectedGameCard $listBox $source
}
$listBoxC.Add_MouseDoubleClick({ Invoke-GamePanelDoubleClick $listBoxC 'C' $_ })
$listBoxD.Add_MouseDoubleClick({ Invoke-GamePanelDoubleClick $listBoxD 'D' $_ })
# Delete: убрать выбранные игры ТОЛЬКО из списка. Ни одна папка на диске не
# удаляется и не изменяется (в функции нет операций с файловой системой).
function Remove-SelectedGamesFromList($listBox, $source) {
    $names = @($listBox.SelectedItems | ForEach-Object { [string]$_ })
    if ($names.Count -eq 0) { return }
    $listBox.BeginUpdate()
    try {
        foreach ($n in $names) {
            $global:hiddenGames[(Get-HiddenGameKey $source $n)] = $true
            $listBox.Items.Remove($n)
        }
    } finally { $listBox.EndUpdate() }
    try { Update-MainLibraryButtonState } catch {}
    $labelHeader.Text = (T 'st_removed' @($names.Count))
}

# Единая клавиатурная логика для ОБЕИХ панелей (C и D).
#   Enter  — карточка игры        Space  — размер папки
#   Delete — убрать из списка     Ctrl+A — выбрать всё
# Ctrl+A в ListBox сам по себе не выделяет все элементы — делаем это вручную.
#
# БАГ-ФИКС: раньше после SetSelected() по всем элементам список сам прокручивался
# в самый низ (последним выделялся последний элемент, и ListBox "тянул" вид к нему).
# Теперь запоминаем позицию прокрутки (TopIndex) и позицию "рамки фокуса" (caret)
# до выделения и возвращаем их обратно — список остаётся на месте.
try {
    if (-not ('ListBoxCaretNative' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class ListBoxCaretNative {
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);
    private const int LB_SETCARETINDEX = 0x019E;
    private const int LB_GETCARETINDEX = 0x019F;
    public static int GetCaret(IntPtr hWnd) {
        return (int)SendMessage(hWnd, LB_GETCARETINDEX, IntPtr.Zero, IntPtr.Zero);
    }
    public static void SetCaret(IntPtr hWnd, int index) {
        SendMessage(hWnd, LB_SETCARETINDEX, new IntPtr(index), new IntPtr(1));
    }
}
'@
    }
} catch {}

function Invoke-GamePanelKey($listBox, $source, $e) {
    $key = $e.KeyCode
    if ($e.Control -and -not $e.Alt -and -not $e.Shift -and $key -eq [System.Windows.Forms.Keys]::A) {
        # Раньше Ctrl+A подсвечивал (выделял) все строки для мышиного мультивыбора.
        # Теперь пакетный выбор — это галочки, поэтому Ctrl+A отмечает их все.
        $checkedSet = Get-CheckedSet $source
        for ($i = 0; $i -lt $listBox.Items.Count; $i++) {
            $name = Clean-GameName $listBox.Items[$i].ToString()
            $checkedSet[$name] = $true
        }
        $listBox.Invalidate()
        Update-MainLibraryButtonState
        $e.SuppressKeyPress = $true; $e.Handled = $true
        return
    }
    if ($e.Alt -and $e.Shift -and -not $e.Control -and $key -eq [System.Windows.Forms.Keys]::Enter) {
        # Alt+Shift+Enter — посчитать размер ВСЕХ папок активной панели разом
        # (не только отмеченных или выделенной), с тем же прогресс-баром, что
        # и у сортировки "по размеру".
        $e.SuppressKeyPress = $true; $e.Handled = $true
        Show-PanelFolderSizes $source
        return
    }
    # Остальные клавиши — только без Ctrl/Alt/Shift, чтобы не ломать стандартное
    # выделение (Shift+Space, Ctrl+Space) и не превращать Shift+Delete во что-то иное.
    if ($e.Control -or $e.Alt -or $e.Shift) { return }
    switch ($key) {
        ([System.Windows.Forms.Keys]::Enter)  { $e.SuppressKeyPress = $true; Show-SelectedGameCard $listBox $source }
        ([System.Windows.Forms.Keys]::Space)  { $e.SuppressKeyPress = $true; Show-SelectedGameSize $listBox $source }
        ([System.Windows.Forms.Keys]::Delete) { $e.SuppressKeyPress = $true; Remove-SelectedGamesFromList $listBox $source }
    }
}

$listBoxC.Add_KeyDown({ Invoke-GamePanelKey $listBoxC 'C' $_ })
$listBoxD.Add_KeyDown({ Invoke-GamePanelKey $listBoxD 'D' $_ })

$listBoxC.Add_SelectedIndexChanged({ Update-MainLibraryButtonState })
$listBoxD.Add_SelectedIndexChanged({ Update-MainLibraryButtonState })

# Вывод статуса/прогресса пакетного добавления. По умолчанию — заголовок и прогресс-бар
# главного окна; окно библиотеки (импорт из лаунчеров) передаёт свой хук, потому что
# главное окно на время библиотеки скрыто. Хук получает только текст статуса.
$script:batchStatusHook = $null
$script:batchProgressHook = $null
function Set-BatchStatusText ([string]$Text) {
    if ($null -ne $script:batchStatusHook) { try { & $script:batchStatusHook $Text } catch {} }
    else { $labelHeader.Text = $Text }
}
function Set-BatchProgressValue ([int]$Value) {
    if ($null -ne $script:batchProgressHook) { try { & $script:batchProgressHook $Value } catch {}; return }
    if ($null -ne $script:batchStatusHook) { return }
    $progressBarFolder.Value = $Value
}

# ===================== ПАКЕТНОЕ ДОБАВЛЕНИЕ С АВТОЗАПОЛНЕНИЕМ =====================
# Игры, для которых программа уверенно определила И название (Steam нашёл точное
# совпадение по имени папки), И исполняемый файл (единственный кандидат или уже
# закэшированный выбор — см. Add-GameToSteamQuietly), добавляются полностью
# автоматически, без показа карточки вообще. Все остальные игры показываются той
# же самой карточкой, что и в обычном пакетном режиме (три кнопки внизу:
# отменить/пропустить/добавить) — отдельным диалогом, одна за другой, точно так
# же, как в обычном пакетном добавлении (см. конец файла).
#
# Отдельного окна с собственным прогресс-баром больше нет: общий прогресс — это
# тот же $progressBarFolder главного окна, что показывает перенос папок между
# панелями (теперь это единый прогресс-бар на всю программу), а текущий статус
# выводится в $labelHeader. На время выполнения кнопка «Добавить игры»
# превращается в кнопку отмены (см. $btnAddToSteam.Add_Click) — отмена
# безопасна: она не прерывает уже начатую обработку текущей игры (тихое
# добавление или открытую карточку), а останавливает пакет перед следующей.
# Отмена кнопкой на самой карточке (см. $btnCancel в Show-GameEditorDialog)
# работает так же, как и в обычном пакетном добавлении — через тот же
# $script:batchCardCancelRequested.
# Закрыть Steam, не замораживая окно: taskkill ждём с прокачкой сообщений, затем те же 2 секунды паузы.
function Stop-SteamProcessResponsive {
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo('taskkill.exe', '/F /T /IM steam.exe')
        $psi.CreateNoWindow = $true
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $p = [System.Diagnostics.Process]::Start($psi)
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        while ($null -ne $p -and -not $p.HasExited -and $sw.ElapsedMilliseconds -lt 20000) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 30
        }
    } catch {
        try { taskkill.exe /F /T /IM steam.exe 2>$null | Out-Null } catch {}
    }
    $sw2 = [System.Diagnostics.Stopwatch]::StartNew()
    while ($sw2.ElapsedMilliseconds -lt 2000) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 30
    }
}

function Invoke-SmartBatchAdd ($selectedGames, [bool]$AutoFill = $true, $OwnerWin = $null, [scriptblock]$StatusHook = $null, [scriptblock]$ProgressHook = $null) {
    $script:batchStatusHook = $StatusHook
    $script:batchProgressHook = $ProgressHook
    $script:batchCardCancelRequested = $false
    $script:batchCardSkipRequested = $false
    $script:smartBatchActive = $true
    $script:quietRomActive = $false
    $global:editorLoadAbortRequested = $false
    $script:batchResults = [PSCustomObject]@{ Ok=0; AutoAdded=0; Skipped=0; Failed=0 }

    $steamPathProperty = $null
    try {
        $steamPathProperty = (Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
        if ([string]::IsNullOrEmpty($steamPathProperty)) { $steamPathProperty = 'C:\Program Files (x86)\Steam\steam.exe' }
        Stop-SteamProcessResponsive

        # Трёхфазный пакет (без лагов на карточке):
        #  1) Быстрая классификация: авто vs нужна карточка.
        #  2) Все авто-добавления подряд (карточка ещё не открыта).
        #  3) Очередь карточек — каждая отдельным диалогом, как в обычном пакете.
        $totalGames = [Math]::Max(1, @($selectedGames).Count)
        $autoList = New-Object System.Collections.Generic.List[object]
        $cardList = New-Object System.Collections.Generic.List[object]
        $done = 0

        Set-BatchProgressValue ([int](0))
        Set-BatchStatusText ([string]((T 'hd_classify')))
        [System.Windows.Forms.Application]::DoEvents()

        for ($i = 0; $i -lt $selectedGames.Count; $i++) {
            if ($script:batchCardCancelRequested) { break }
            $game = $selectedGames[$i]
            # Автоимпорт выключен: без классификации, все игры идут в очередь карточек.
            if (-not $AutoFill) { $cardList.Add($game); continue }
            # Режим ROMs: проверка по Steam/exe к образам не применима. Ром сразу идёт в
            # тихое добавление (Add-RomToSteamQuietly), а если там что-то определено
            # неуверенно, возвращается Handled = $false и ром уходит в очередь карточек.
            if ($script:romsModeEnabled -and -not (Test-IsLauncherEntry $game)) { $autoList.Add($game); continue }
            Set-BatchStatusText ([string]((T 'hd_classify_n' @($game.Name, ($i+1), $totalGames))))
            [System.Windows.Forms.Application]::DoEvents()

            # Та же проверка уверенности, что в Add-GameToSteamQuietly, но без
            # скачивания обложек и записи ярлыка — быстро и без блокировок UI надолго.
            $canAuto = $false
            try {
                $steamInfo = $null
                try { $steamInfo = Find-SteamAppInfo $game.Name } catch { $steamInfo = $null }
                if ($steamInfo -ne $null -and -not [string]::IsNullOrWhiteSpace([string]$steamInfo.Id)) {
                    $exeCandidates = @(Get-EditorExecutableCandidates $game.Path $game.Name)
                    # Игра из лаунчера: за SCLauncher.exe или с exe из манифеста лаунчера
                    # выбор определён без карточки (те же правила, что в Add-GameToSteamQuietly).
                    if (Test-IsLauncherEntry $game) {
                        if ((Test-LauncherEntryWrapped $game) -or ($null -ne (Get-LauncherManifestExe $game))) { $canAuto = $true }
                    }
                    if ($canAuto) {
                        # уже определено выше
                    } elseif ($exeCandidates.Count -eq 1) {
                        $canAuto = $true
                    } elseif ($exeCandidates.Count -gt 1) {
                        $cacheKey = $game.Path.ToUpper()
                        $cached = $null
                        try { if ($global:exeSelectionCache.ContainsKey($cacheKey)) { $cached = [string]$global:exeSelectionCache[$cacheKey] } } catch {}
                        if ($cached) {
                            foreach ($ex in $exeCandidates) {
                                if ([string]::Equals([string]$ex.FullName, $cached, [System.StringComparison]::OrdinalIgnoreCase)) { $canAuto = $true; break }
                            }
                        }
                        # Нет сохранённого выбора — пробуем подсказку Steam (см.
                        # Get-SteamHintedExecutable): если основной exe для этого
                        # App ID найден в папке, карточка не нужна.
                        if (-not $canAuto) {
                            $hintedExe = $null
                            try { $hintedExe = Get-SteamHintedExecutable $game.Path ([string]$steamInfo.Id) } catch { $hintedExe = $null }
                            if ($hintedExe -ne $null) { $canAuto = $true }
                        }
                    }
                }
            } catch { $canAuto = $false }

            if ($canAuto) { $autoList.Add($game) } else { $cardList.Add($game) }
        }

        # Фаза 2: авто-добавление (карточка ещё не открыта, UI свободен).
        # Скачивание обложек внутри Add-GameToSteamQuietly по умолчанию блокирующее
        # (Invoke-WebRequest без прокачки очереди сообщений) — этого достаточно,
        # чтобы Windows пометила окно «Не отвечает» на время каждой картинки.
        # В карточке для этого включают $global:uiPumpDuringDownload — делаем то
        # же самое здесь на время всей фазы, чтобы скачивание шло через
        # Invoke-UiPumpingDownload (curl.exe-процесс + прокачка DoEvents) и окно
        # оставалось отзывчивым, включая кнопку «Отменить».
        $global:uiPumpDuringDownload = $true
        try {
            for ($i = 0; $i -lt $autoList.Count; $i++) {
                if ($script:batchCardCancelRequested) { break }
                $game = $autoList[$i]
                Set-BatchStatusText ([string]((T 'hd_auto_n' @($game.Name, ($i+1), $autoList.Count, $cardList.Count))))
                Set-BatchProgressValue ([int]([Math]::Min(100, [int](($done / $totalGames) * 100))))
                [System.Windows.Forms.Application]::DoEvents()

                if ($script:romsModeEnabled -and -not (Test-IsLauncherEntry $game)) {
                    $script:quietRomActive = $true
                    try { $quiet = Add-RomToSteamQuietly $game } finally { $script:quietRomActive = $false }
                } else {
                    $quiet = Add-GameToSteamQuietly $game
                }
                # Отмена посреди добавления: до записи в Steam ничего не сделано, в карточки не отправляем.
                if ($script:batchCardCancelRequested -and -not $quiet.Handled) { break }
                if ($quiet.Handled -and $quiet.Success) {
                    $script:batchResults.Ok++
                    $script:batchResults.AutoAdded++
                } elseif ($quiet.Handled) {
                    $script:batchResults.Failed++
                    Set-BatchStatusText ([string]((T 'hd_game_error' @($game.Name, $quiet.Reason))))
                } else {
                    # На классификации казалось уверенным, на деле нет — в карточки.
                    $cardList.Add($game)
                }
                $done++
                Set-BatchProgressValue ([int]([Math]::Min(100, [int](($done / $totalGames) * 100))))
                [System.Windows.Forms.Application]::DoEvents()
            }
        } finally {
            $global:uiPumpDuringDownload = $false
        }

        # Фаза 3: очередь карточек. Каждая карточка — отдельный диалог, ровно как
        # в обычном (не авто) пакетном добавлении, а не встроенная панель.
        $cardTotal = $cardList.Count
        for ($i = 0; $i -lt $cardList.Count; $i++) {
            if ($script:batchCardCancelRequested) { break }
            $game = $cardList[$i]
            $left = $cardTotal - $i - 1
            Set-BatchStatusText ([string]((T 'hd_refine_n' @($game.Name, ($i+1), $cardTotal)) + $(if ($left -gt 0) { (T 'hd_queue_left' @($left)) } else { "" })))
            Set-BatchProgressValue ([int]([Math]::Min(100, [int](($done / $totalGames) * 100))))
            [System.Windows.Forms.Application]::DoEvents()

            if (Test-IsLauncherEntry $game) {
                Show-GameEditorDialog $game.Name 'Steam' $game.Path $true $null $null $OwnerWin -IsRomEntry:$false -LauncherEntry $game
            } else {
                Show-GameEditorDialog $game.Name $game.Source $game.Path $true $null $null $OwnerWin -IsRomEntry:$script:romsModeEnabled
            }

            if ($script:batchCardCancelRequested) { break }
            elseif ($script:batchCardSkipRequested) { $script:batchResults.Skipped++ }
            else {
                $script:batchResults.Ok++
            }
            $done++
            Set-BatchProgressValue ([int]([Math]::Min(100, [int](($done / $totalGames) * 100))))
            [System.Windows.Forms.Application]::DoEvents()
        }

        if ($script:batchCardCancelRequested) {
            Set-BatchStatusText ([string]((T 'hd_stopped' @($script:batchResults.Ok, $script:batchResults.AutoAdded, $script:batchResults.Skipped))))
        } else {
            Set-BatchProgressValue ([int](100))
            Set-BatchStatusText ([string]((T 'hd_finished' @($script:batchResults.Ok, $totalGames, $script:batchResults.AutoAdded, $script:batchResults.Skipped))))
        }
        [System.Windows.Forms.Application]::DoEvents()
        [System.Media.SystemSounds]::Asterisk.Play()
    } catch {
        Set-BatchStatusText ([string]((T 'hd_auto_batch_err' @([string]$_.Exception.Message))))
    } finally {
        try { if ($steamPathProperty -and (Test-Path $steamPathProperty)) { Start-Process -FilePath $steamPathProperty } } catch {}
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 400
        Set-BatchProgressValue ([int](0))
        $script:batchStatusHook = $null
        $script:batchProgressHook = $null
        $script:smartBatchActive = $false
        $script:quietRomActive = $false
        $global:editorLoadAbortRequested = $false
    }
    return $script:batchResults
}


# В пакетном режиме карточки открываются по одной, а Steam закрывается только
# один раз перед началом операции и запускается один раз после её завершения.
$script:batchCardMode = $false

# Пока идёт автоматическое пакетное добавление (Invoke-SmartBatchAdd), кнопка
# «Добавить игры» превращается в кнопку отмены — сама кнопка остаётся
# активной (в отличие от остальных элементов управления библиотекой), чтобы
# по ней можно было кликнуть в любой момент. Отмена безопасна: она лишь
# взводит тот же $script:batchCardCancelRequested, что проверяется между
# играми внутри Invoke-SmartBatchAdd, поэтому уже начатая обработка текущей
# (последней перед остановкой) игры спокойно доходит до конца.
$script:batchInProgress = $false
$script:btnAddToSteamDefaultText = [string]$btnAddToSteam.Tag
$btnAddToSteam.Add_Click({
    if($script:batchInProgress){
        $script:batchCardCancelRequested = $true
        # Идёт тихое добавление рома: прерываем его долгие операции (чтение архива, запросы к
        # SteamGridDB, скачивание обложек). Ром при этом не добавляется вовсе — Add-RomToSteamQuietly
        # возвращает Handled = $false до записи в Steam. У обычных игр флаг не трогаем: начатая
        # игра, как и раньше, спокойно доходит до конца.
        if ($script:quietRomActive) { $global:editorLoadAbortRequested = $true }
        $labelHeader.Text = (T 'hd_cancelling')
        return
    }
    # Кнопка видна при 1+ отмеченной игре (см. Update-MainLibraryButtonState).
    # Для одной игры путь тот же, что для батча: Smart Batch Add сам решает,
    # можно ли добавить автоматически, или показывает карточку для подтверждения.
    $selectedGames=@(Get-CheckedGames)
    if($selectedGames.Count -eq 0){$labelHeader.Text=(T 'hd_tick_one');return}

    $gamesToProcess=@()
    $skippedCount=0
    foreach($game in $selectedGames){
        if(Test-GameAlreadyInSteamLibrary $game.Name $game.Path){$skippedCount++}else{$gamesToProcess+=$game}
    }
    if($skippedCount -gt 0){
        $labelHeader.Text=(T 'hd_skip_existing' @($skippedCount))
        [System.Windows.Forms.Application]::DoEvents()
    }
    $selectedGames=@($gamesToProcess)
    if($selectedGames.Count -eq 0){
        $labelHeader.Text=(T 'hd_all_exist')
        return
    }

    if($script:batchAutoFillEnabled){
        # $btnAddToSteam намеренно остаётся Enabled=$true — он на время выполнения
        # исполняет роль кнопки отмены, см. перехват $script:batchInProgress в
        # начале этого обработчика. Списки тоже блокируются: пока карточка ещё не
        # открыта модально (фазы классификации и авто-добавления), главное окно
        # остаётся отзывчивым, и смена выделения в списке иначе сбросила бы текст
        # кнопки обратно через Update-MainLibraryButtonState.
        $btnMoveGame.Enabled=$false;$btnRefreshLibrary.Enabled=$false
        $listBoxC.Enabled=$false;$listBoxD.Enabled=$false
        $script:batchInProgress=$true
        $btnAddToSteam.Tag=(T 'btn_cancel_batch')
        try{
            $labelHeader.Text=(T 'hd_autofill' @($selectedGames.Count))
            [System.Windows.Forms.Application]::DoEvents()
            $batchResult=Invoke-SmartBatchAdd $selectedGames
            if($batchResult -ne $null){
                if($script:batchCardCancelRequested){
                    $labelHeader.Text=(T 'hd_cancelled' @($batchResult.Ok, $selectedGames.Count, $batchResult.AutoAdded, $batchResult.Skipped))
                }else{
                    $labelHeader.Text=(T 'hd_autofill_done' @($batchResult.Ok, $selectedGames.Count, $batchResult.AutoAdded))
                }
            }
        }catch{$labelHeader.Text=(T 'hd_autofill_err' @([string]$_.Exception.Message))}
        finally{
            $script:batchInProgress=$false
            $btnAddToSteam.Tag=$script:btnAddToSteamDefaultText
            $btnMoveGame.Enabled=$true;$btnRefreshLibrary.Enabled=$true;$btnAddToSteam.Enabled=$true
            $listBoxC.Enabled=$true;$listBoxD.Enabled=$true
            # Пакетное автозаполнение по отмеченным играм завершено (или
            # отменено) — отметки своё дело сделали, явно снимаем.
            $global:checkedC.Clear(); $global:checkedD.Clear()
            Refresh-Panels
        }
        return
    }

    $btnMoveGame.Enabled=$false;$btnRefreshLibrary.Enabled=$false;$btnAddToSteam.Enabled=$false
    $steamPathProperty=$null
    try{
        $steamPathProperty=(Get-ItemProperty -Path 'HKCU:\Software\Valve\Steam' -Name 'SteamExe' -ErrorAction SilentlyContinue).SteamExe
        if([string]::IsNullOrEmpty($steamPathProperty)){$steamPathProperty='C:\Program Files (x86)\Steam\steam.exe'}
        Stop-SteamProcessResponsive
        [System.Windows.Forms.Application]::DoEvents()

        $manualTotal=[Math]::Max(1,@($selectedGames).Count)
        for($i=0;$i -lt $selectedGames.Count;$i++){
            $game=$selectedGames[$i]
            $labelHeader.Text=(T 'hd_card_n' @(($i+1), $selectedGames.Count, $game.Name))
            # Общий прогресс пакета: доля уже обработанных карточек. Минимум 1%,
            # иначе таймер прогресс-бара (значение 0 = «не используется») скроет
            # бар на первой игре.
            $progressBarFolder.Value=[int][Math]::Max(1,[Math]::Min(100,[Math]::Floor(($i/$manualTotal)*100)))
            [System.Windows.Forms.Application]::DoEvents()
            if (Test-IsLauncherEntry $game) {
                Show-GameEditorDialog $game.Name 'Steam' $game.Path $true -IsRomEntry:$false -LauncherEntry $game
            } else {
                Show-GameEditorDialog $game.Name $game.Source $game.Path $true -IsRomEntry:$script:romsModeEnabled
            }
            if($script:batchCardCancelRequested){$labelHeader.Text=(T 'hd_batch_cancelled');break}
            $progressBarFolder.Value=[int][Math]::Max(1,[Math]::Min(100,[Math]::Floor((($i+1)/$manualTotal)*100)))
            if($script:batchCardSkipRequested){$labelHeader.Text=(T 'hd_skipped' @($game.Name));[System.Windows.Forms.Application]::DoEvents();continue}
        }
        if(-not $script:batchCardCancelRequested){$labelHeader.Text=(T 'hd_processing' @($selectedGames.Count))}
    }catch{$labelHeader.Text=(T 'hd_card_err' @([string]$_.Exception.Message))}
    finally{
        # Если пакет отменён/упал — сразу убираем бар; при успешном завершении (100%)
        # его скроет таймер через ~1.2 с.
        try{if($script:batchCardCancelRequested -or $progressBarFolder.Value -lt 100){$progressBarFolder.Value=0}}catch{}
        try{if($steamPathProperty -and (Test-Path $steamPathProperty)){Start-Process -FilePath $steamPathProperty}}catch{}
        $btnMoveGame.Enabled=$true;$btnRefreshLibrary.Enabled=$true;$btnAddToSteam.Enabled=$true
        # Карточки по всем отмеченным играм прошли (или добавление отменено) —
        # отметки своё дело сделали, явно снимаем.
        $global:checkedC.Clear(); $global:checkedD.Clear()
        Refresh-Panels
    }
})



$btnSteamLibrary.Add_Click({
    # Библиотека открывается как экран той же программы: модальное окно ровно поверх главного, которое
    # на время показа становится невидимым (Opacity = 0), но остаётся «живым» владельцем и единственной
    # кнопкой на панели задач. Кнопка "Назад" в самой библиотеке лишь закрывает её ($dlg.Close());
    # главное окно возвращается в $dlg.Add_FormClosing и дублируется здесь после закрытия диалога
    # (кнопкой "Назад" или крестиком).
    # Пока открыта библиотека, прогрев не работает (иначе он делал бы ту же работу параллельно).
    $script:libPreheatBlocked = $true
    try { Stop-LibPreheatJob } catch {}
    Write-Tm '=== CLICK: открытие библиотеки ===' -Reset
    # Бесшовный переход: главное окно не прячем и сплэш не показываем — библиотека открывается ровно поверх него
    # (см. Show-SteamLibraryBrowser). Пока она строится, у окна курсор ожидания; потом главное окно становится
    # невидимым (Opacity = 0), а при закрытии библиотеки возвращается (см. $dlg.Add_FormClosing).
    try { $form.UseWaitCursor = $true; [System.Windows.Forms.Cursor]::Current = [System.Windows.Forms.Cursors]::WaitCursor } catch {}
    try {
        Show-SteamLibraryBrowser
    } catch {
        $script:libPreheatBlocked = $false
        try { $form.UseWaitCursor = $false; $form.Opacity = 1 } catch {}
        try { $form.Show() } catch {}
        Show-AppMessageBox(
            $form,
            (T 'lib_open_fail' @([string]$_.Exception.Message)),
            $global:appTitle,
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
        return
    }
    try { $form.UseWaitCursor = $false; $form.Opacity = 1 } catch {}
    try { $form.Show(); $form.Activate() } catch {}
    # Библиотека закрыта: если снимок устарел (например, после импорта игр), готовим новый в фоне.
    $script:libPreheatBlocked = $false
    try { Request-LibPreheat 2500 } catch {}
})

$form.Add_FormClosing({ Save-Configuration })

# Если папка Steam не найдена или не выбран (либо не найден) userdata-профиль —
# сразу открываем окно настроек, чтобы пользователь их указал. Нужные поля там
# уже подсвечены красным значком (см. Show-ProgramSettingsDialog).
if (-not (Test-ConfiguredSteamPathValid) -or -not (Test-ConfiguredSteamProfileValid)) {
    try { Close-Splash } catch {}
    try { Show-ProgramSettingsDialog | Out-Null } catch {}
}

Set-SplashProgress 0.82
try { Set-SplashText (T 'splash_reading') } catch {}
Refresh-Panels
Set-SplashProgress 0.94
Set-SteamButtonIcons
Install-PathFocusDismissHandlers
try { Update-RomEmulatorIndicator } catch {}
# F5 — то же, что кнопка "Обновить". KeyPreview нужен, чтобы форма получала клавишу
# раньше активного контрола (список, поле поиска и т.д.). Сама кнопка сама
# игнорирует нажатие, пока идёт обновление (Enabled = $false).
$form.KeyPreview = $true
$form.Add_KeyDown({
    if ($_.KeyCode -eq [System.Windows.Forms.Keys]::F5) {
        $_.Handled = $true
        $_.SuppressKeyPress = $true
        if ($btnRefreshLibrary.Enabled) { $btnRefreshLibrary.PerformClick() }
    }
})

$form.Add_Shown({
    # Окно должно остаться развёрнутым и на переднем плане: сначала восстанавливаем и активируем его (пока
    # передний план ещё у процесса — у загрузочного экрана), и только потом закрываем загрузочный экран.
    try { if ($form.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal } } catch {}
    try { $form.Activate(); $form.BringToFront() } catch {}
    try { Set-SplashProgress 1.0 } catch {}
    try { Close-Splash } catch {}
    try { if ($form.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal } } catch {}
    try { $form.Activate() } catch {}
    try { $form.ActiveControl = $null } catch {}
    # Прогрев попапа выбора эмулятора: компиляция C#-типов и загрузка иконок в
    # память — когда окно уже на экране, а не на первом клике по значку эмулятора.
    try {
        $script:romWarmupTimer = New-Object System.Windows.Forms.Timer
        $script:romWarmupTimer.Interval = 500
        $script:romWarmupTimer.Add_Tick({
            try { $script:romWarmupTimer.Stop(); $script:romWarmupTimer.Dispose() } catch {}
            try { Initialize-RomPickerTypes } catch {}
            try { foreach ($wp in @($global:emulatorProfiles)) { [void](Get-EmulatorIconBitmap $wp) } } catch {}
        })
        $script:romWarmupTimer.Start()
    } catch {}
    # Прогрев данных библиотеки: записи Steam и лаунчеры читаются кусками по таймеру, пока человек смотрит на главное окно.
    try { $script:libPreheatEnabled = $true; Request-LibPreheat 1800 } catch {}
})
[System.Windows.Forms.Application]::DoEvents()
try { Initialize-FormForSmallScreen -Form $form } catch {}
$form.ShowDialog() | Out-Null
